internal class ModbusDataDict : IDisposable
{
	private Dictionary<int, ModbusDataPool> dictModbusDataPool;

	private bool stationDataIsolation;

	public ModbusDataDict()
	{
		dictModbusDataPool = new Dictionary<int, ModbusDataPool>();
		dictModbusDataPool.Add(0, new ModbusDataPool(0));
	}

	public void Set(bool stationDataIsolation)
	{
		if (this.stationDataIsolation == stationDataIsolation)
		{
			return;
		}
		this.stationDataIsolation = stationDataIsolation;
		if (this.stationDataIsolation)
		{
			dictModbusDataPool = new Dictionary<int, ModbusDataPool>();
			for (int i = 0; i < 255; i++)
			{
				dictModbusDataPool.Add(i, new ModbusDataPool((byte)i));
			}
		}
		else
		{
			dictModbusDataPool = new Dictionary<int, ModbusDataPool>();
			dictModbusDataPool.Add(0, new ModbusDataPool(0));
		}
	}

	public ModbusDataPool GetModbusPool(byte station)
	{
		if (stationDataIsolation)
		{
			return dictModbusDataPool[station];
		}
		return dictModbusDataPool.FirstOrDefault().Value;
	}

	/// <inheritdoc />
	public void Dispose()
	{
		foreach (ModbusDataPool value in dictModbusDataPool.Values)
		{
			value.Dispose();
		}
		dictModbusDataPool.Clear();
	}
}
internal class ModbusDataPool : IDisposable
{
	private byte station = 1;

	private SoftBuffer coilBuffer;

	private SoftBuffer inputBuffer;

	private SoftBuffer registerBuffer;

	private SoftBuffer inputRegisterBuffer;

	private const int DataPoolLength = 65536;

	public ModbusDataPool(byte station)
	{
		coilBuffer = new SoftBuffer(65536);
		inputBuffer = new SoftBuffer(65536);
		registerBuffer = new SoftBuffer(131072);
		inputRegisterBuffer = new SoftBuffer(131072);
		registerBuffer.IsBoolReverseByWord = true;
		inputRegisterBuffer.IsBoolReverseByWord = true;
		this.station = station;
	}

	public OResult<byte[]> Read(string address, ushort length)
	{
		OResult<ModbusAddress> oResult = ModbusInfo.AnalysisAddress(address, station, isStartWithZero: true, 3);
		if (!oResult.IsSuccess)
		{
			return OResult.CreateFailedResult<byte[]>(oResult);
		}
		if (oResult.Content.Function == 3)
		{
			return OResult.CreateSuccessResult(registerBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
		}
		if (oResult.Content.Function == 4)
		{
			return OResult.CreateSuccessResult(inputRegisterBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
		}
		return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
	}

	public OResult Write(string address, byte[] value)
	{
		OResult<ModbusAddress> oResult = ModbusInfo.AnalysisAddress(address, station, isStartWithZero: true, 3);
		if (!oResult.IsSuccess)
		{
			return OResult.CreateFailedResult<byte[]>(oResult);
		}
		if (oResult.Content.Function == 3 || oResult.Content.Function == 6 || oResult.Content.Function == 16)
		{
			registerBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
			return OResult.CreateSuccessResult();
		}
		if (oResult.Content.Function == 4)
		{
			inputRegisterBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
			return OResult.CreateSuccessResult();
		}
		return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
	}

	public OResult<bool[]> ReadBool(string address, ushort length, DataFormat dataFormat)
	{
		if (address.IndexOf('.') < 0)
		{
			OResult<ModbusAddress> oResult = ModbusInfo.AnalysisAddress(address, station, isStartWithZero: true, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content.Function == 1 || oResult.Content.Function == 5 || oResult.Content.Function == 15)
			{
				return OResult.CreateSuccessResult((from m in coilBuffer.GetBytes(oResult.Content.AddressStart, length)
					select m != 0).ToArray());
			}
			if (oResult.Content.Function == 2)
			{
				return OResult.CreateSuccessResult((from m in inputBuffer.GetBytes(oResult.Content.AddressStart, length)
					select m != 0).ToArray());
			}
			return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
		}
		try
		{
			int num = Convert.ToInt32(address.Substring(address.IndexOf('.') + 1));
			address = address.Substring(0, address.IndexOf('.'));
			OResult<ModbusAddress> oResult2 = ModbusInfo.AnalysisAddress(address, station, isStartWithZero: true, 3);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			num = oResult2.Content.AddressStart * 16 + num;
			if (oResult2.Content.Function == 3)
			{
				return OResult.CreateSuccessResult(registerBuffer.GetBool(num, length, dataFormat));
			}
			if (oResult2.Content.Function == 4)
			{
				return OResult.CreateSuccessResult(inputRegisterBuffer.GetBool(num, length, dataFormat));
			}
			return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
		}
		catch (Exception ex)
		{
			return new OResult<bool[]>(ex.Message);
		}
	}

	public OResult Write(string address, bool[] value)
	{
		if (address.IndexOf('.') < 0)
		{
			OResult<ModbusAddress> oResult = ModbusInfo.AnalysisAddress(address, station, isStartWithZero: true, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content.Function == 1 || oResult.Content.Function == 15 || oResult.Content.Function == 5)
			{
				coilBuffer.SetBytes(value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			}
			if (oResult.Content.Function == 2)
			{
				inputBuffer.SetBytes(value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			}
			return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
		}
		try
		{
			int num = Convert.ToInt32(address.Substring(address.IndexOf('.') + 1));
			address = address.Substring(0, address.IndexOf('.'));
			OResult<ModbusAddress> oResult2 = ModbusInfo.AnalysisAddress(address, station, isStartWithZero: true, 3);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			num = oResult2.Content.AddressStart * 16 + num;
			if (oResult2.Content.Function == 3)
			{
				registerBuffer.SetBool(value, num);
				return OResult.CreateSuccessResult();
			}
			if (oResult2.Content.Function == 4)
			{
				inputRegisterBuffer.SetBool(value, num);
				return OResult.CreateSuccessResult();
			}
			return new OResult(StringResources.Language.NotSupportedDataType);
		}
		catch (Exception ex)
		{
			return new OResult(ex.Message);
		}
	}

	/// <summary>
	/// 读取地址的线圈的通断情况
	/// </summary>
	/// <param name="address">起始地址，示例："100"</param>
	/// <returns><c>True</c>或是<c>False</c></returns>
	/// <exception cref="T:System.IndexOutOfRangeException"></exception>
	public bool ReadCoil(string address)
	{
		ushort index = ushort.Parse(address);
		return coilBuffer.GetByte(index) != 0;
	}

	/// <summary>
	/// 批量读取地址的线圈的通断情况
	/// </summary>
	/// <param name="address">起始地址，示例："100"</param>
	/// <param name="length">读取长度</param>
	/// <returns><c>True</c>或是<c>False</c></returns>
	/// <exception cref="T:System.IndexOutOfRangeException"></exception>
	public bool[] ReadCoil(string address, ushort length)
	{
		ushort index = ushort.Parse(address);
		return (from m in coilBuffer.GetBytes(index, length)
			select m != 0).ToArray();
	}

	/// <summary>
	/// 写入线圈的通断值
	/// </summary>
	/// <param name="address">起始地址，示例："100"</param>
	/// <param name="data">是否通断</param>
	/// <returns><c>True</c>或是<c>False</c></returns>
	/// <exception cref="T:System.IndexOutOfRangeException"></exception>
	public void WriteCoil(string address, bool data)
	{
		ushort index = ushort.Parse(address);
		coilBuffer.SetValue(data ? ((byte)1) : ((byte)0), index);
	}

	/// <summary>
	/// 写入线圈数组的通断值
	/// </summary>
	/// <param name="address">起始地址，示例："100"</param>
	/// <param name="data">是否通断</param>
	/// <returns><c>True</c>或是<c>False</c></returns>
	/// <exception cref="T:System.IndexOutOfRangeException"></exception>
	public void WriteCoil(string address, bool[] data)
	{
		if (data != null)
		{
			ushort destIndex = ushort.Parse(address);
			coilBuffer.SetBytes(data.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), destIndex);
		}
	}

	/// <summary>
	/// 读取地址的离散线圈的通断情况
	/// </summary>
	/// <param name="address">起始地址，示例："100"</param>
	/// <returns><c>True</c>或是<c>False</c></returns>
	/// <exception cref="T:System.IndexOutOfRangeException"></exception>
	public bool ReadDiscrete(string address)
	{
		ushort index = ushort.Parse(address);
		return inputBuffer.GetByte(index) != 0;
	}

	/// <summary>
	/// 批量读取地址的离散线圈的通断情况
	/// </summary>
	/// <param name="address">起始地址，示例："100"</param>
	/// <param name="length">读取长度</param>
	/// <returns><c>True</c>或是<c>False</c></returns>
	/// <exception cref="T:System.IndexOutOfRangeException"></exception>
	public bool[] ReadDiscrete(string address, ushort length)
	{
		ushort index = ushort.Parse(address);
		return (from m in inputBuffer.GetBytes(index, length)
			select m != 0).ToArray();
	}

	/// <summary>
	/// 写入离散线圈的通断值
	/// </summary>
	/// <param name="address">起始地址，示例："100"</param>
	/// <param name="data">是否通断</param>
	/// <exception cref="T:System.IndexOutOfRangeException"></exception>
	public void WriteDiscrete(string address, bool data)
	{
		ushort index = ushort.Parse(address);
		inputBuffer.SetValue(data ? ((byte)1) : ((byte)0), index);
	}

	/// <summary>
	/// 写入离散线圈数组的通断值
	/// </summary>
	/// <param name="address">起始地址，示例："100"</param>
	/// <param name="data">是否通断</param>
	/// <exception cref="T:System.IndexOutOfRangeException"></exception>
	public void WriteDiscrete(string address, bool[] data)
	{
		if (data != null)
		{
			ushort destIndex = ushort.Parse(address);
			inputBuffer.SetBytes(data.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), destIndex);
		}
	}

	/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusTcpServer.SaveToBytes" />
	public byte[] SaveToBytes()
	{
		return ByteTransformHelper.GetByteFromSoftBuffer(coilBuffer, inputBuffer, registerBuffer, inputRegisterBuffer).ToArray();
	}

	/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusTcpServer.LoadFromBytes(System.Byte[])" />
	public void LoadFromBytes(byte[] content, int index)
	{
		ByteTransformHelper.SetByteToSoftBuffer(content, index, coilBuffer, inputBuffer, registerBuffer, inputRegisterBuffer);
	}

	/// <inheritdoc />
	public void Dispose()
	{
		coilBuffer?.Dispose();
		inputBuffer?.Dispose();
		registerBuffer?.Dispose();
		inputRegisterBuffer?.Dispose();
	}
}
namespace Snet.Driver
{
	/// <summary>
	/// 用于PLC通讯及ModBus自定义数据类型的读写操作
	/// </summary>
	/// <remarks>
	/// 主要应用于设备实现设备类的自定义的数据类型读写，以此达到简化代码的操作，但是有一个前提，该数据处于连续的数据区块
	/// </remarks>
	/// <example>
	/// 此处举例读取三菱的自定义的数据，先实现接口，然后再读写操作
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDeviceBase.cs" region="IDataTransfer Example" title="DataMy示例" />
	/// 接下来就可以实现数据的读取了
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDeviceBase.cs" region="ReadCustomerExample" title="ReadCustomer示例" />
	/// </example>
	public interface IDataTransfer
	{
		/// <summary>
		/// 读取的数据长度，对于西门子，等同于字节数，对于三菱和Modbus为字节数的一半
		/// </summary>
		ushort ReadCount { get; }

		/// <summary>
		/// 从字节数组进行解析实际的对象
		/// </summary>
		/// <param name="Content">从远程读取的数据源</param>
		void ParseSource(byte[] Content);

		/// <summary>
		/// 将对象生成字符源，写入PLC中
		/// </summary>
		/// <returns>准备写入到远程的数据</returns>
		byte[] ToSource();
	}
	/// <summary>
	/// 用于网络传递的信息头，使用上等同于int
	/// </summary>
	/// <remarks>
	/// 通常用于<see cref="T:Snet.Driver.Enthernet.NetComplexServer" />和<see cref="T:Snet.Driver.Enthernet.NetComplexClient" />之间的通信，以及<see cref="T:Snet.Driver.Enthernet.NetSimplifyServer" />和<see cref="T:Snet.Driver.Enthernet.NetSimplifyClient" />通讯
	/// </remarks>
	/// <example>
	/// 使用上等同于int，只是本结构体允许将4字节的int拆分成3部分单独访问
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetHandle.cs" region="NetHandleExample" title="NetHandle示例" />
	/// </example>
	[StructLayout(LayoutKind.Explicit)]
	public struct NetHandle
	{
		/// <summary>
		/// 完整的暗号值
		/// </summary>
		[FieldOffset(0)]
		private int m_CodeValue;

		/// <summary>
		/// 主暗号分类0-255
		/// </summary>
		[FieldOffset(3)]
		private byte m_CodeMajor;

		/// <summary>
		/// 次要的暗号分类0-255
		/// </summary>
		[FieldOffset(2)]
		private byte m_CodeMinor;

		/// <summary>
		/// 暗号的编号分类0-65535
		/// </summary>
		[FieldOffset(0)]
		private ushort m_CodeIdentifier;

		/// <summary>
		/// 完整的暗号值
		/// </summary>
		public int CodeValue
		{
			get
			{
				return m_CodeValue;
			}
			set
			{
				m_CodeValue = value;
			}
		}

		/// <summary>
		/// 主暗号分类0-255
		/// </summary>
		public byte CodeMajor
		{
			get
			{
				return m_CodeMajor;
			}
			private set
			{
				m_CodeMajor = value;
			}
		}

		/// <summary>
		/// 次要的暗号分类0-255
		/// </summary>
		public byte CodeMinor
		{
			get
			{
				return m_CodeMinor;
			}
			private set
			{
				m_CodeMinor = value;
			}
		}

		/// <summary>
		/// 暗号的编号分类0-65535
		/// </summary>
		public ushort CodeIdentifier
		{
			get
			{
				return m_CodeIdentifier;
			}
			private set
			{
				m_CodeIdentifier = value;
			}
		}

		/// <summary>
		/// 赋值操作，可以直接赋值int数据
		/// </summary>
		/// <param name="value">int数值</param>
		/// <returns>等值的消息对象</returns>
		public static implicit operator NetHandle(int value)
		{
			return new NetHandle(value);
		}

		/// <summary>
		/// 也可以赋值给int数据
		/// </summary>
		/// <param name="netHandle">netHandle对象</param>
		/// <returns>等值的消息对象</returns>
		public static implicit operator int(NetHandle netHandle)
		{
			return netHandle.m_CodeValue;
		}

		/// <summary>
		/// 判断是否相等
		/// </summary>
		/// <param name="netHandle1">第一个数</param>
		/// <param name="netHandle2">第二个数</param>
		/// <returns>等于返回<c>True</c>，否则<c>False</c></returns>
		public static bool operator ==(NetHandle netHandle1, NetHandle netHandle2)
		{
			return netHandle1.CodeValue == netHandle2.CodeValue;
		}

		/// <summary>
		/// 判断是否不相等
		/// </summary>
		/// <param name="netHandle1">第一个对象</param>
		/// <param name="netHandle2">第二个对象</param>
		/// <returns>等于返回<c>False</c>，否则<c>True</c></returns>
		public static bool operator !=(NetHandle netHandle1, NetHandle netHandle2)
		{
			return netHandle1.CodeValue != netHandle2.CodeValue;
		}

		/// <summary>
		/// 两个数值相加
		/// </summary>
		/// <param name="netHandle1">第一个对象</param>
		/// <param name="netHandle2">第二个对象</param>
		/// <returns>返回两个指令的和</returns>
		public static NetHandle operator +(NetHandle netHandle1, NetHandle netHandle2)
		{
			return new NetHandle(netHandle1.CodeValue + netHandle2.CodeValue);
		}

		/// <summary>
		/// 两个数值相减
		/// </summary>
		/// <param name="netHandle1">第一个对象</param>
		/// <param name="netHandle2">第二个对象</param>
		/// <returns>返回两个指令的差</returns>
		public static NetHandle operator -(NetHandle netHandle1, NetHandle netHandle2)
		{
			return new NetHandle(netHandle1.CodeValue - netHandle2.CodeValue);
		}

		/// <summary>
		/// 判断是否小于另一个数值
		/// </summary>
		/// <param name="netHandle1">第一个对象</param>
		/// <param name="netHandle2">第二个对象</param>
		/// <returns>小于则返回<c>True</c>，否则返回<c>False</c></returns>
		public static bool operator <(NetHandle netHandle1, NetHandle netHandle2)
		{
			return netHandle1.CodeValue < netHandle2.CodeValue;
		}

		/// <summary>
		/// 判断是否大于另一个数值
		/// </summary>
		/// <param name="netHandle1">第一个对象</param>
		/// <param name="netHandle2">第二个对象</param>
		/// <returns>大于则返回<c>True</c>，否则返回<c>False</c></returns>
		public static bool operator >(NetHandle netHandle1, NetHandle netHandle2)
		{
			return netHandle1.CodeValue > netHandle2.CodeValue;
		}

		/// <summary>
		/// 初始化一个暗号对象
		/// </summary>
		/// <param name="value">使用一个默认的数值进行初始化</param>
		public NetHandle(int value)
		{
			m_CodeMajor = 0;
			m_CodeMinor = 0;
			m_CodeIdentifier = 0;
			m_CodeValue = value;
		}

		/// <summary>
		/// 根据三个值来初始化暗号对象
		/// </summary>
		/// <param name="major">主暗号</param>
		/// <param name="minor">次暗号</param>
		/// <param name="identifier">暗号编号</param>
		public NetHandle(byte major, byte minor, ushort identifier)
		{
			m_CodeValue = 0;
			m_CodeMajor = major;
			m_CodeMinor = minor;
			m_CodeIdentifier = identifier;
		}

		/// <summary>
		/// 获取完整的暗号数据
		/// </summary>
		/// <returns>返回暗号的字符串表示形式</returns>
		public override string ToString()
		{
			return m_CodeValue.ToString();
		}

		/// <summary>
		/// 判断两个实例是否相同
		/// </summary>
		/// <param name="obj">对比的对象</param>
		/// <returns>相同返回<c>True</c>，否则返回<c>False</c></returns>
		public override bool Equals(object obj)
		{
			if (obj is NetHandle netHandle)
			{
				return CodeValue.Equals(netHandle.CodeValue);
			}
			return false;
		}

