		/// 获取哈希值
		/// </summary>
		/// <returns>返回当前对象的哈希值</returns>
		public override int GetHashCode()
		{
			return base.GetHashCode();
		}
	}
	/// <summary>
	/// 操作结果的类，只带有成功标志和错误信息<br />
	/// The class that operates the result, with only success flags and error messages
	/// </summary>
	/// <remarks>
	/// 当 <see cref="P:Snet.Driver.OResult.IsSuccess" /> 为 True 时，忽略 <see cref="P:Snet.Driver.OResult.Message" /> 及 <see cref="P:Snet.Driver.OResult.ErrorCode" /> 的值
	/// </remarks>
	public class OResult
	{
		/// <summary>
		/// 指示本次操作是否成功。<br />
		/// Indicates whether this operation was successful.
		/// </summary>
		public bool IsSuccess { get; set; }

		/// <summary>
		/// 具体的错误描述。<br />
		/// Specific error description.
		/// </summary>
		public string Message { get; set; } = StringResources.Language.UnknownError;

		/// <summary>
		/// 具体的错误代码。<br />
		/// The specific error code.
		/// </summary>
		/// <remarks>
		/// 默认的错误码值为 10000，此时需要看 <see cref="P:Snet.Driver.OResult.Message" /> 的消息来查看错误信息，如果由于网络问题导致的错误，错误码小于 0，
		/// 其他情况的错误都是对应协议的错误码，有些错误码的描述信息可以看 <see cref="P:Snet.Driver.OResult.Message" />，如果消息也是未知的话，此时需要根据错误码找对应协议的手册来确认错误消息。<br />
		/// The default error code value is 10000. In this case, you need to view the <see cref="P:Snet.Driver.OResult.Message" /> message to view the error information. 
		/// If the error code is less than 0 due to network problems, the error code in other cases is the error code of the corresponding protocol. 
		/// You can see <see cref="P:Snet.Driver.OResult.Message" /> for the description of some error codes. If the message is also unknown, you need to refer to the manual of the corresponding protocol to confirm the error message.
		/// </remarks>
		public int ErrorCode { get; set; } = 10000;

		/// <summary>
		/// 实例化一个默认的结果对象
		/// </summary>
		public OResult()
		{
		}

		/// <summary>
		/// 使用指定的消息实例化一个默认的结果对象
		/// </summary>
		/// <param name="msg">错误消息</param>
		public OResult(string msg)
		{
			Message = msg;
		}

		/// <summary>
		/// 使用错误代码，消息文本来实例化对象
		/// </summary>
		/// <param name="err">错误代码</param>
		/// <param name="msg">错误消息</param>
		public OResult(int err, string msg)
		{
			ErrorCode = err;
			Message = msg;
		}

		/// <summary>
		/// 获取错误代号及文本描述。<br />
		/// Get the error code and text description.
		/// </summary>
		/// <returns>包含错误码及错误消息</returns>
		public string ToMessageShowString()
		{
			return $"{StringResources.Language.ErrorCode}:{ErrorCode}{Environment.NewLine}{StringResources.Language.TextDescription}:{Message}";
		}

		/// <summary>
		/// 从另一个结果类中拷贝错误信息，主要是针对错误码和错误消息。<br />
		/// Copy error information from another result class, mainly for error codes and error messages.
		/// </summary>
		/// <typeparam name="TResult">支持结果类及派生类</typeparam>
		/// <param name="result">结果类及派生类的对象</param>
		public void CopyErrorFromOther<TResult>(TResult result) where TResult : OResult
		{
			if (result != null)
			{
				ErrorCode = result.ErrorCode;
				Message = result.Message;
			}
		}

