	/// <summary>
	/// 操作结果的泛型类，允许带一个用户自定义的泛型对象，推荐使用这个类
	/// </summary>
	/// <typeparam name="T">泛型类</typeparam>
	public class OResult<T> : OResult
	{
		/// <summary>
		/// 用户自定义的泛型数据
		/// </summary>
		public T Content { get; set; }

		/// <summary>
		/// 实例化一个默认的结果对象
		/// </summary>
		public OResult()
		{
		}

		/// <summary>
		/// 使用指定的消息实例化一个默认的结果对象
		/// </summary>
		/// <param name="msg">错误消息</param>
		public OResult(string msg)
			: base(msg)
		{
		}

		/// <summary>
		/// 使用错误代码，消息文本来实例化对象
		/// </summary>
		/// <param name="err">错误代码</param>
		/// <param name="msg">错误消息</param>
		public OResult(int err, string msg)
			: base(err, msg)
		{
		}

		/// <summary>
		/// 返回一个检查结果对象，可以进行自定义的数据检查。<br />
		/// Returns a check result object that allows you to perform custom data checks.
		/// </summary>
		/// <param name="check">检查的委托方法</param>
		/// <param name="message">检查失败的错误消息</param>
		/// <returns>如果检查成功，则返回对象本身，如果失败，返回错误信息。</returns>
		public OResult<T> Check(Func<T, bool> check, string message = "All content data check failed")
		{
			if (!base.IsSuccess)
			{
				return this;
			}
			if (check(Content))
			{
				return this;
			}
			return new OResult<T>(message);
		}

		/// <summary>
		/// 返回一个检查结果对象，可以进行自定义的数据检查。<br />
		/// Returns a check result object that allows you to perform custom data checks.
		/// </summary>
		/// <param name="check">检查的委托方法</param>
		/// <returns>如果检查成功，则返回对象本身，如果失败，返回错误信息。</returns>
		public OResult<T> Check(Func<T, OResult> check)
		{
			if (!base.IsSuccess)
			{
				return this;
			}
			OResult oResult = check(Content);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<T>(oResult);
			}
			return this;
		}

