		public OResult<T1, T2, T3> Check(Func<T1, T2, T3, OResult> check)
		{
			if (!base.IsSuccess)
			{
				return this;
			}
			OResult oResult = check(Content1, Content2, Content3);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<T1, T2, T3>(oResult);
			}
			return this;
		}

