		public OResult<T1, T2, T3, T4, T5> Check(Func<T1, T2, T3, T4, T5, OResult> check)
		{
			if (!base.IsSuccess)
			{
				return this;
			}
			OResult oResult = check(Content1, Content2, Content3, Content4, Content5);
			if (!oResult.IsSuccess)
			{
