		/// </summary>
		public OResult()
		{
		}

		/// <summary>
		/// 使用指定的消息实例化一个默认的结果对象
		/// </summary>
		/// <param name="msg">错误消息</param>
		public OResult(string msg)
			: base(msg)
		{
		}

		/// <summary>
		/// 使用错误代码，消息文本来实例化对象
		/// </summary>
		/// <param name="err">错误代码</param>
		/// <param name="msg">错误消息</param>
		public OResult(int err, string msg)
			: base(err, msg)
		{
		}

		/// <summary>
		/// 返回一个检查结果对象，可以进行自定义的数据检查。<br />
		/// Returns a check result object that allows you to perform custom data checks.
		/// </summary>
		/// <param name="check">检查的委托方法</param>
		/// <param name="message">检查失败的错误消息</param>
		/// <returns>如果检查成功，则返回对象本身，如果失败，返回错误信息。</returns>
		public OResult<T1, T2, T3, T4, T5, T6, T7, T8, T9> Check(Func<T1, T2, T3, T4, T5, T6, T7, T8, T9, bool> check, string message = "All content data check failed")
		{
			if (!base.IsSuccess)
			{
				return this;
			}
			if (check(Content1, Content2, Content3, Content4, Content5, Content6, Content7, Content8, Content9))
			{
				return this;
			}
			return new OResult<T1, T2, T3, T4, T5, T6, T7, T8, T9>(message);
		}

		/// <summary>
		/// 返回一个检查结果对象，可以进行自定义的数据检查。<br />
		/// Returns a check result object that allows you to perform custom data checks.
		/// </summary>
		/// <param name="check">检查的委托方法</param>
		/// <returns>如果检查成功，则返回对象本身，如果失败，返回错误信息。</returns>
		public OResult<T1, T2, T3, T4, T5, T6, T7, T8, T9> Check(Func<T1, T2, T3, T4, T5, T6, T7, T8, T9, OResult> check)
		{
			if (!base.IsSuccess)
			{
				return this;
			}
			OResult oResult = check(Content1, Content2, Content3, Content4, Content5, Content6, Content7, Content8, Content9);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<T1, T2, T3, T4, T5, T6, T7, T8, T9>(oResult);
			}
			return this;
		}

