		/// <returns>如果检查成功，则返回对象本身，如果失败，返回错误信息。</returns>
		public OResult<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10> Check(Func<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, bool> check, string message = "All content data check failed")
		{
			if (!base.IsSuccess)
			{
				return this;
			}
			if (check(Content1, Content2, Content3, Content4, Content5, Content6, Content7, Content8, Content9, Content10))
			{
				return this;
			}
			return new OResult<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10>(message);
		}

