			}
			if (value.Length < length)
			{
				return string.Empty;
			}
			return value.Remove(value.Length - length);
		}

		/// <summary>
		/// 将指定的数据添加到数组的每个元素上去，会改变每个元素的值
		/// </summary>
		/// <param name="array">原始数组</param>
		/// <param name="value">值</param>
		/// <returns>修改后的数组信息</returns>
		public static byte[] EveryByteAdd(this byte[] array, int value)
		{
			if (array == null)
			{
				return null;
			}
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = (byte)(array[i] + value);
			}
			return array;
		}

		/// <summary>
		/// 将指定的数据添加到数组的每个元素上去，使用表达式树的形式实现，将会修改原数组。不适用byte类型
		/// </summary>
		/// <typeparam name="T">数组的类型</typeparam>
		/// <param name="array">原始数据</param>
		/// <param name="value">数据值</param>
		/// <returns>返回的结果信息</returns>
		public static T[] IncreaseBy<T>(this T[] array, T value)
		{
			if (typeof(T) == typeof(byte))
			{
				Func<int, int, int> func = ((Expression<Func<int, int, int>>)((int first, int second) => first + second)).Compile();
				for (int num = 0; num < array.Length; num++)
				{
					array[num] = (T)(object)(byte)func(Convert.ToInt32(array[num]), Convert.ToInt32(value));
				}
			}
			else
			{
				Func<T, T, T> func2 = ((Expression<Func<T, T, T>>)((T first, T second) => (T)((object)first + (object)second))).Compile();
				for (int num2 = 0; num2 < array.Length; num2++)
				{
					array[num2] = func2(array[num2], value);
				}
			}
			return array;
		}

