		/// <summary>
		/// 启动接收数据，需要传入回调方法，传递对象<br />
		/// To start receiving data, you need to pass in a callback method and pass an object
		/// </summary>
		/// <param name="socket">socket对象</param>
		/// <param name="callback">回调方法</param>
		/// <param name="obj">数据对象</param>
		/// <returns>是否启动成功</returns>
		public static OResult BeginReceiveResult(this Socket socket, AsyncCallback callback, object obj)
		{
			try
			{
				socket.BeginReceive(new byte[0], 0, 0, SocketFlags.None, callback, obj);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult(ex.Message);
			}
		}

