		/// </summary>
		internal const int ProtocolEmptyFolderDelete = 2014;

		/// <summary>
		/// 请求指定文件夹的文件大小
		/// </summary>
		internal const int ProtocolFolderInfo = 2015;

		/// <summary>
		/// 指定目录的所有子目录的文件统计信息，每个文件夹的文件数量，所有文件大小，最后更新时间
		/// </summary>
		internal const int ProtocolFolderInfos = 2016;

		/// <summary>
		/// 不压缩数据字节
		/// </summary>
		internal const int ProtocolNoZipped = 3001;

		/// <summary>
		/// 压缩数据字节
		/// </summary>
		internal const int ProtocolZipped = 3002;

		/// <summary>
		/// 生成终极传送指令的方法，所有的数据均通过该方法出来
		/// </summary>
		/// <param name="command">命令头</param>
		/// <param name="customer">自用自定义</param>
		/// <param name="token">令牌</param>
		/// <param name="data">字节数据</param>
		/// <returns>包装后的数据信息</returns>
		internal static byte[] CommandBytes(int command, int customer, Guid token, byte[] data)
		{
			int num = ((data != null) ? data.Length : 0);
			byte[] array = new byte[32 + num];
			BitConverter.GetBytes(command).CopyTo(array, 0);
			BitConverter.GetBytes(customer).CopyTo(array, 4);
			BitConverter.GetBytes(3001).CopyTo(array, 8);
			token.ToByteArray().CopyTo(array, 12);
			if (num > 0)
			{
				BitConverter.GetBytes(num).CopyTo(array, 28);
				Array.Copy(data, 0, array, 32, num);
				SnetSecurity.ByteEncrypt(array, 32, num);
			}
			return array;
		}

		/// <summary>
		/// 解析接收到数据，先解压缩后进行解密
		/// </summary>
		/// <param name="head">指令头</param>
		/// <param name="content">指令的内容</param>
		/// <return>真实的数据内容</return>
		internal static byte[] CommandAnalysis(byte[] head, byte[] content)
		{
			if (content != null)
			{
				if (BitConverter.ToInt32(head, 8) == 3002)
				{
					content = SoftZipped.Decompress(content);
				}
				return SnetSecurity.ByteDecrypt(content);
			}
			return null;
		}

		/// <summary>
		/// 获取发送字节数据的实际数据，带指令头
		/// </summary>
		/// <param name="customer">用户数据</param>
		/// <param name="token">令牌</param>
		/// <param name="data">字节信息</param>
		/// <returns>包装后的指令信息</returns>
		internal static byte[] CommandBytes(int customer, Guid token, byte[] data)
		{
			return CommandBytes(1002, customer, token, data);
		}

		/// <summary>
		/// 获取发送字节数据的实际数据，带指令头
		/// </summary>
		/// <param name="customer">用户数据</param>
		/// <param name="token">令牌</param>
		/// <param name="data">字符串数据信息</param>
		/// <returns>包装后的指令信息</returns>
		internal static byte[] CommandBytes(int customer, Guid token, string data)
		{
			if (data == null)
			{
				return CommandBytes(1001, customer, token, null);
			}
			return CommandBytes(1001, customer, token, Encoding.Unicode.GetBytes(data));
		}

		/// <summary>
		/// 获取发送字节数据的实际数据，带指令头
		/// </summary>
		/// <param name="customer">用户数据</param>
		/// <param name="token">令牌</param>
		/// <param name="data">字符串数据信息</param>
		/// <returns>包装后的指令信息</returns>
		internal static byte[] CommandBytes(int customer, Guid token, string[] data)
		{
			return CommandBytes(1005, customer, token, PackStringArrayToByte(data));
		}

		/// <inheritdoc cref="M:Snet.Driver.SnetProtocol.PackStringArrayToByte(System.String[])" />
		internal static byte[] PackStringArrayToByte(string data)
		{
			return PackStringArrayToByte(new string[1] { data });
		}

		/// <summary>
		/// 将字符串打包成字节数组内容
		/// </summary>
		/// <param name="data">字符串数组</param>
		/// <returns>打包后的原始数据内容</returns>
		internal static byte[] PackStringArrayToByte(string[] data)
		{
			if (data == null)
			{
				data = new string[0];
			}
			List<byte> list = new List<byte>();
			list.AddRange(BitConverter.GetBytes(data.Length));
			for (int i = 0; i < data.Length; i++)
			{
				if (!string.IsNullOrEmpty(data[i]))
				{
					byte[] bytes = Encoding.Unicode.GetBytes(data[i]);
					list.AddRange(BitConverter.GetBytes(bytes.Length));
					list.AddRange(bytes);
				}
				else
				{
					list.AddRange(BitConverter.GetBytes(0));
				}
			}
			return list.ToArray();
		}

		/// <summary>
		/// 将字节数组还原成真实的字符串数组
		/// </summary>
		/// <param name="content">原始字节数组</param>
		/// <returns>解析后的字符串内容</returns>
		internal static string[] UnPackStringArrayFromByte(byte[] content)
		{
			if (content != null && content.Length < 4)
			{
				return null;
			}
			int num = 0;
			int num2 = BitConverter.ToInt32(content, num);
			string[] array = new string[num2];
			num += 4;
			for (int i = 0; i < num2; i++)
			{
				int num3 = BitConverter.ToInt32(content, num);
				num += 4;
				if (num3 > 0)
				{
					array[i] = Encoding.Unicode.GetString(content, num, num3);
				}
				else
				{
					array[i] = string.Empty;
				}
				num += num3;
			}
			return array;
		}

		/// <summary>
		/// 从接收的数据内容提取出用户的暗号和数据内容
		/// </summary>
		/// <param name="content">数据内容</param>
		/// <returns>包含结果对象的信息</returns>
		public static OResult<NetHandle, byte[]> ExtractSnetData(byte[] content)
		{
			if (content.Length == 0)
			{
				return OResult.CreateSuccessResult((NetHandle)0, new byte[0]);
			}
			byte[] array = new byte[32];
			byte[] array2 = new byte[content.Length - 32];
			Array.Copy(content, 0, array, 0, 32);
			if (array2.Length != 0)
			{
				Array.Copy(content, 32, array2, 0, content.Length - 32);
			}
			if (BitConverter.ToInt32(array, 0) == 2010)
			{
				return new OResult<NetHandle, byte[]>(Encoding.Unicode.GetString(array2));
			}
			int num = BitConverter.ToInt32(array, 0);
			int num2 = BitConverter.ToInt32(array, 4);
			array2 = CommandAnalysis(array, array2);
			if (num == 6)
			{
				return new OResult<NetHandle, byte[]>(Encoding.Unicode.GetString(array2));
			}
			return OResult.CreateSuccessResult((NetHandle)num2, array2);
		}
	}
	internal class SnetSecurity
	{
		/// <summary>
		/// 加密方法，只对当前的程序集开放
		/// </summary>
		/// <param name="enBytes">等待加密的数据</param>
		/// <returns>加密后的字节数据</returns>
		internal static byte[] ByteEncrypt(byte[] enBytes)
		{
			if (enBytes == null)
			{
				return null;
			}
			byte[] array = new byte[enBytes.Length];
			for (int i = 0; i < enBytes.Length; i++)
			{
				array[i] = (byte)(enBytes[i] ^ 0xB5);
			}
			return array;
		}

		internal static void ByteEncrypt(byte[] enBytes, int offset, int count)
		{
			for (int i = offset; i < offset + count && i < enBytes.Length; i++)
			{
				enBytes[i] ^= 181;
			}
		}

		/// <summary>
		/// 解密方法，只对当前的程序集开放
		/// </summary>
		/// <param name="deBytes">等待解密的数据</param>
		/// <returns>解密后的字节数据</returns>
		internal static byte[] ByteDecrypt(byte[] deBytes)
		{
			return ByteEncrypt(deBytes);
		}
	}
	/// <summary>
	/// 超时操作的类<br />
	/// a class use to indicate the time-out of the connection
	/// </summary>
	/// <remarks>
	/// 本类自动启动一个静态线程来处理
	/// </remarks>
	public class SnetTimeOut
	{
		private static long SnetTimeoutId;

		private static List<SnetTimeOut> WaitHandleTimeOut;

		private static object listLock;

		private static Thread threadCheckTimeOut;

		private static long threadUniqueId;

		private static DateTime threadActiveTime;

		private static int activeDisableCount;

		/// <summary>
		/// 当前的超时对象处理的总个数，如果需要重置该值，方便重新计数，请调用如下代码：<c>long current = Interlocked.Exchange( ref Snet.Driver.SnetTimeOut.TimeoutDealCount, 0 );</c><br />
		/// The total number of timeout objects processed at present, if you need to reset the value to facilitate recounting, call the following code: <c>long current = Interlocked.Exchange( ref Snet.Driver.SnetTimeOut.TimeoutDealCount, 0 );</c>
		/// </summary>
		public static long TimeoutDealCount;

		private static bool isLinuxPlatform;

		/// <summary>
		/// 当前超时对象的唯一ID信息，没实例化一个对象，id信息就会自增1<br />
		/// The unique ID information of the current timeout object. If an object is not instantiated, the id information will increase by 1
		/// </summary>
		public long UniqueId { get; private set; }

		/// <summary>
		/// 操作的开始时间<br />
		/// Start time of operation
		/// </summary>
		public DateTime StartTime { get; set; }

		/// <summary>
		/// 操作是否成功，当操作完成的时候，需要设置为<c>True</c>，超时检测自动结束。如果一直为<c>False</c>，超时检测到超时，设置<see cref="P:Snet.Driver.SnetTimeOut.IsTimeout" />为<c>True</c><br />
		/// Whether the operation is successful, when the operation is completed, it needs to be set to <c>True</c>, 
		/// and the timeout detection will automatically end. If it is always <c>False</c>, 
		/// the timeout is detected by the timeout, set <see cref="P:Snet.Driver.SnetTimeOut.IsTimeout" /> to <c>True</c>
		/// </summary>
		public bool IsSuccessful { get; set; }

		/// <summary>
		/// 延时的时间，单位毫秒<br />
		/// Delay time, in milliseconds
		/// </summary>
		public int DelayTime { get; set; }

		/// <summary>
		/// 连接超时用的Socket，本超时对象主要针对套接字的连接，接收数据的超时检测，也可以设置为空，用作其他用途的超时检测。<br />
		/// Socket used for connection timeout. This timeout object is mainly for socket connection and timeout detection of received data. 
		/// It can also be set to empty for other purposes.
		/// </summary>
		[JsonIgnore]
		public Socket WorkSocket { get; set; }

		/// <summary>
		/// 是否发生了超时的操作，当调用方因为异常结束的时候，需要对<see cref="P:Snet.Driver.SnetTimeOut.IsTimeout" />进行判断，是否因为发送了超时导致的异常<br />
		/// Whether a timeout operation has occurred, when the caller ends abnormally, 
		/// it needs to judge <see cref="P:Snet.Driver.SnetTimeOut.IsTimeout" />, whether it is an exception caused by a timeout sent
		/// </summary>
		public bool IsTimeout { get; set; }

		/// <summary>
		/// 获取或设置当前的超时线程的状态日志信息，只要实例化，即可记录当前的超时日志运行信息<br />
		/// Obtain or set the status log information of the current timeout thread, and record the current timeout log operation information as long as it is instantiated
		/// </summary>
		public static ILogNet TimeoutLogNet { get; set; }

		/// <summary>
		/// 获取当前检查超时对象的个数<br />
		/// Get the number of current check timeout objects
		/// </summary>
		public static int TimeOutCheckCount => WaitHandleTimeOut.Count;

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public SnetTimeOut()
		{
			UniqueId = Interlocked.Increment(ref SnetTimeoutId);
			StartTime = DateTime.Now;
			IsSuccessful = false;
			IsTimeout = false;
		}

		/// <summary>
		/// 获取到目前为止所花费的时间<br />
		/// Get the time spent so far
		/// </summary>
		/// <returns>时间信息</returns>
		public TimeSpan GetConsumeTime()
		{
			return DateTime.Now - StartTime;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SnetTimeOut[{DelayTime}]";
		}

		/// <summary>
		/// 新增一个超时检测的对象，当操作完成的时候，需要自行标记<see cref="T:Snet.Driver.SnetTimeOut" />对象的<see cref="P:Snet.Driver.SnetTimeOut.IsSuccessful" />为<c>True</c><br />
		/// Add a new object for timeout detection. When the operation is completed, 
		/// you need to mark the <see cref="P:Snet.Driver.SnetTimeOut.IsSuccessful" /> of the <see cref="T:Snet.Driver.SnetTimeOut" /> object as <c>True</c>
		/// </summary>
		/// <param name="timeOut">超时对象</param>
		public static void HandleTimeOutCheck(SnetTimeOut timeOut)
		{
			lock (listLock)
			{
				if ((DateTime.Now - threadActiveTime).TotalSeconds > 60.0)
				{
					threadActiveTime = DateTime.Now;
					if (Interlocked.Increment(ref activeDisableCount) >= 2)
					{
						CreateTimeoutCheckThread();
					}
				}
				WaitHandleTimeOut.Add(timeOut);
			}
		}

		/// <summary>
		/// 获取当前的所有的等待超时检查对象列表，请勿手动更改对象的属性值<br />
		/// Get the current list of all waiting timeout check objects, do not manually change the property value of the object
		/// </summary>
		/// <returns>SnetTimeOut数组，请勿手动更改对象的属性值</returns>
		public static SnetTimeOut[] GetSnetTimeOutsSnapShoot()
		{
			lock (listLock)
			{
				return WaitHandleTimeOut.ToArray();
			}
		}

		/// <summary>
		/// 新增一个超时检测的对象，需要指定socket，超时时间，返回<see cref="T:Snet.Driver.SnetTimeOut" />对象，用作标记完成信息<br />
		/// Add a new object for timeout detection, you need to specify the socket, the timeout period, 
		/// and return the <see cref="T:Snet.Driver.SnetTimeOut" /> object for marking completion information
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="timeout">超时时间，单位为毫秒<br />Timeout period, in milliseconds</param>
		public static SnetTimeOut HandleTimeOutCheck(Socket socket, int timeout)
		{
			SnetTimeOut snetTimeOut = new SnetTimeOut
			{
				DelayTime = timeout,
				IsSuccessful = false,
				StartTime = DateTime.Now,
				WorkSocket = socket
			};
			if (timeout > 0)
			{
				HandleTimeOutCheck(snetTimeOut);
			}
			return snetTimeOut;
		}

		static SnetTimeOut()
		{
			SnetTimeoutId = 0L;
			WaitHandleTimeOut = new List<SnetTimeOut>(128);
			listLock = new object();
			threadUniqueId = 0L;
			activeDisableCount = 0;
			TimeoutDealCount = 0L;
			isLinuxPlatform = false;
			CreateTimeoutCheckThread();
		}

		private static void CreateTimeoutCheckThread()
		{
			threadActiveTime = DateTime.Now;
			try
			{
				threadCheckTimeOut?.Abort();
			}
			catch
			{
			}
			threadCheckTimeOut = new Thread(CheckTimeOut);
			threadCheckTimeOut.IsBackground = true;
			threadCheckTimeOut.Priority = ThreadPriority.AboveNormal;
			threadCheckTimeOut.Start(Interlocked.Increment(ref threadUniqueId));
		}

		/// <summary>
		/// 整个Snet.Driver的检测超时的核心方法，由一个单独的线程运行，线程的优先级很高，当前其他所有的超时信息都可以放到这里处理<br />
		/// The core method of detecting the timeout of th e entire Snet.Driver is run by a separate thread. 
		/// The priority of the thread is very high. All other timeout information can be processed here.
		/// </summary>
		/// <param name="obj">需要传入线程的id信息</param>
		private static void CheckTimeOut(object obj)
		{
			long num = (long)obj;
			TimeoutLogNet?.WriteInfo("Snet.Driver.TimeoutThread", $"ID[{num}] CheckTimeOut start.");
			ManualResetEvent manualResetEvent = new ManualResetEvent(initialState: false);
			int num2 = 0;
			while (true)
			{
				try
				{
					manualResetEvent.WaitOne(100);
					num2 = 0;
				}
				catch (Exception ex)
				{
					num2++;
					TimeoutLogNet?.WriteWarn("Snet.Driver.TimeoutThread", $"ID[{num}] Exception {SoftBasic.GetExceptionMessage(ex)}");
					SnetHelper.ThreadSleep(100);
					if (num2 == 5 || num2 % 1000 == 0)
					{
						manualResetEvent.Close();
						manualResetEvent = new ManualResetEvent(initialState: false);
					}
				}
				if (num != threadUniqueId)
				{
					break;
				}
				threadActiveTime = DateTime.Now;
				activeDisableCount = 0;
				lock (listLock)
				{
					for (int num3 = WaitHandleTimeOut.Count - 1; num3 >= 0; num3--)
					{
						SnetTimeOut snetTimeOut = WaitHandleTimeOut[num3];
						if (snetTimeOut.IsSuccessful)
						{
							WaitHandleTimeOut[num3].WorkSocket = null;
							WaitHandleTimeOut.RemoveAt(num3);
							Interlocked.Increment(ref TimeoutDealCount);
						}
						else
						{
							double num4 = (DateTime.Now - snetTimeOut.StartTime).TotalMilliseconds;
							if (num4 < 0.0)
							{
								snetTimeOut.StartTime = DateTime.Now;
								num4 = 0.0;
							}
							if (num4 > (double)snetTimeOut.DelayTime)
							{
								if (!snetTimeOut.IsSuccessful)
								{
									if (isLinuxPlatform)
									{
										try
										{
											snetTimeOut.WorkSocket?.Disconnect(reuseSocket: false);
										}
										catch
										{
										}
									}
									NetSupport.CloseSocket(snetTimeOut.WorkSocket);
									snetTimeOut.IsTimeout = true;
								}
								WaitHandleTimeOut[num3].WorkSocket = null;
								WaitHandleTimeOut.RemoveAt(num3);
								Interlocked.Increment(ref TimeoutDealCount);
							}
						}
					}
				}
			}
			TimeoutLogNet?.WriteWarn("Snet.Driver.TimeoutThread", $"ID[{num}] break not same as {threadUniqueId}");
			manualResetEvent?.Close();
		}
	}
