	/// <summary>
	/// 所有串行通信类的基类，提供了一些基础的服务，核心的通信实现<br />
	/// The base class of all serial communication classes provides some basic services for the core communication implementation
	/// </summary>
	public class SerialBase : BinaryCommunication, IDisposable
	{
		private bool disposedValue;

		private PipeSerialPort pipe;

		/// <inheritdoc />
		public override CommunicationPipe CommunicationPipe
		{
			get
			{
				return base.CommunicationPipe;
			}
			set
			{
				base.CommunicationPipe = value;
				if (value is PipeSerialPort pipeSerialPort)
				{
					pipe = pipeSerialPort;
				}
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeSerialPort.RtsEnable" />
		public bool RtsEnable
		{
			get
			{
				return pipe.RtsEnable;
			}
			set
			{
				pipe.RtsEnable = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeSerialPort.ReceiveEmptyDataCount" />
		public int ReceiveEmptyDataCount
		{
			get
			{
				return pipe.ReceiveEmptyDataCount;
			}
			set
			{
				pipe.ReceiveEmptyDataCount = value;
			}
		}

		/// <summary>
		/// 是否在发送数据前清空缓冲数据，默认是false<br />
		/// Whether to empty the buffer before sending data, the default is false
		/// </summary>
		public bool IsClearCacheBeforeRead
		{
			get
			{
				return pipe.IsClearCacheBeforeRead;
			}
			set
			{
				pipe.IsClearCacheBeforeRead = value;
			}
		}

		/// <summary>
		/// 当前连接串口信息的端口号名称<br />
		/// The port name of the current connection serial port information
		/// </summary>
		public string PortName { get; private set; }

		/// <summary>
		/// 当前连接串口信息的波特率<br />
		/// Baud rate of current connection serial port information
		/// </summary>
		public int BaudRate { get; private set; }

		/// <summary>
		/// 实例化一个无参的构造方法<br />
		/// Instantiate a parameterless constructor
		/// </summary>
		public SerialBase()
		{
			CommunicationPipe = new PipeSerialPort();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSerialPort.SerialPortInni(System.String)" />
		public virtual void SerialPortInni(string portName)
		{
			pipe.SerialPortInni(portName);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceSerialPort.SerialPortInni(System.String,System.Int32)" />
		public virtual void SerialPortInni(string portName, int baudRate)
		{
			SerialPortInni(portName, baudRate, 8, (StopBits)1, (Parity)0);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSerialPort.SerialPortInni(System.String,System.Int32,System.Int32,System.IO.Ports.StopBits,System.IO.Ports.Parity)" />
		public virtual void SerialPortInni(string portName, int baudRate, int dataBits, StopBits stopBits, Parity parity)
		{
			//IL_0009: Unknown result type (might be due to invalid IL or missing references)
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			pipe.SerialPortInni(portName, baudRate, dataBits, stopBits, parity);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSerialPort.SerialPortInni(System.Action{System.IO.Ports.SerialPort})" />
		public void SerialPortInni(Action<SerialPort> initi)
		{
			pipe.SerialPortInni(initi);
			PortName = pipe.GetPipe().PortName;
			BaudRate = pipe.GetPipe().BaudRate;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSerialPort.OpenCommunication" />
		public virtual OResult Open()
		{
			OResult<bool> oResult = pipe.OpenCommunication();
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content)
			{
				return InitializationOnConnect();
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceSerialPort.IsOpen" />
		public bool IsOpen()
		{
			return pipe.GetPipe().IsOpen;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceSerialPort.Close" />
		public void Close()
		{
			if (pipe.GetPipe().IsOpen)
			{
				ExtraOnDisconnect();
				pipe.CloseCommunication();
			}
		}

		/// <summary>
		/// 释放当前的对象
		/// </summary>
		/// <param name="disposing">是否在</param>
		protected virtual void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				if (disposing)
				{
					pipe?.CloseCommunication();
				}
				disposedValue = true;
			}
		}

		/// <summary>
		/// 释放当前的对象
		/// </summary>
		public void Dispose()
		{
			Dispose(disposing: true);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SerialBase{CommunicationPipe}";
		}
	}
	/// <summary>
	/// 用于CRC16验证的类，提供了标准的验证方法，可以方便快速的对数据进行CRC校验<br />
	/// The class for CRC16 validation provides a standard validation method that makes it easy to CRC data quickly
	/// </summary>
	/// <remarks>
	/// 本类提供了几个静态的方法，用来进行CRC16码的计算和验证的，多项式码可以自己指定配置，但是预置的寄存器为0xFF 0xFF
	/// </remarks>
	/// <example>
	/// 先演示如何校验一串数据的CRC码
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Serial\SoftCRC16.cs" region="Example1" title="SoftCRC16示例" />
	/// 然后下面是如何生成你自己的CRC校验码
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Serial\SoftCRC16.cs" region="Example2" title="SoftCRC16示例" />
	/// </example>
	public class SoftCRC16
	{
		/// <summary>
		/// 来校验对应的接收数据的CRC校验码，默认多项式码为0xA001<br />
		/// To verify the CRC check code corresponding to the received data, the default polynomial code is 0xA001
		/// </summary>
		/// <param name="value">需要校验的数据，带CRC校验码</param>
		/// <returns>返回校验成功与否</returns>
		public static bool CheckCRC16(byte[] value)
		{
			return CheckCRC16(value, 160, 1);
		}

		/// <summary>
		/// 指定多项式码来校验对应的接收数据的CRC校验码<br />
		/// Specifies a polynomial code to validate the corresponding CRC check code for the received data
		/// </summary>
		/// <param name="value">需要校验的数据，带CRC校验码</param>
		/// <param name="CH">多项式码高位</param>
		/// <param name="CL">多项式码低位</param>
		/// <returns>返回校验成功与否</returns>
		public static bool CheckCRC16(byte[] value, byte CH, byte CL)
		{
			if (value == null)
			{
				return false;
			}
			if (value.Length < 2)
			{
				return false;
			}
			int num = value.Length;
			byte[] array = new byte[num - 2];
			Array.Copy(value, 0, array, 0, array.Length);
			byte[] array2 = CRC16(array, CH, CL);
			if (array2[num - 2] == value[num - 2] && array2[num - 1] == value[num - 1])
			{
				return true;
			}
			return false;
		}

		/// <summary>
		/// 获取对应的数据的CRC校验码，默认多项式码为0xA001<br />
		/// Get the CRC check code of the corresponding data, the default polynomial code is 0xA001
		/// </summary>
		/// <param name="value">需要校验的数据，不包含CRC字节</param>
		/// <returns>返回带CRC校验码的字节数组，可用于串口发送</returns>
		public static byte[] CRC16(byte[] value)
		{
			return CRC16(value, 160, 1);
		}

		/// <summary>
		/// 通过指定多项式码来获取对应的数据的CRC校验码<br />
		/// The CRC check code of the corresponding data is obtained by specifying the polynomial code
		/// </summary>
		/// <param name="value">需要校验的数据，不包含CRC字节</param>
		/// <param name="CL">多项式码地位</param>
		/// <param name="CH">多项式码高位</param>
		/// <param name="preH">预置的高位值</param>
		/// <param name="preL">预置的低位值</param>
		/// <returns>返回带CRC校验码的字节数组，可用于串口发送</returns>
		public static byte[] CRC16(byte[] value, byte CH, byte CL, byte preH = byte.MaxValue, byte preL = byte.MaxValue)
		{
			byte[] array = new byte[value.Length + 2];
			value.CopyTo(array, 0);
			byte b = preL;
			byte b2 = preH;
			for (int i = 0; i < value.Length; i++)
			{
				b ^= value[i];
				for (int j = 0; j <= 7; j++)
				{
					byte num = b2;
					byte b3 = b;
					b2 >>= 1;
					b >>= 1;
					if ((num & 1) == 1)
					{
						b |= 0x80;
					}
					if ((b3 & 1) == 1)
					{
						b2 ^= CH;
						b ^= CL;
					}
				}
			}
			array[^2] = b;
			array[^1] = b2;
			return array;
		}

		/// <summary>
		/// 通过指定多项式码来获取对应的数据的CRC校验码<br />
		/// The CRC check code of the corresponding data is obtained by specifying the polynomial code
		/// </summary>
		/// <param name="value">需要校验的数据，不包含CRC字节</param>
		/// <param name="index">计算的起始字节索引</param>
		/// <param name="length">计算的字节长度</param>
		/// <param name="CL">多项式码地位</param>
		/// <param name="CH">多项式码高位</param>
		/// <param name="preH">预置的高位值</param>
		/// <param name="preL">预置的低位值</param>
		/// <returns>返回带CRC校验码的字节数组，可用于串口发送</returns>
		public static byte[] CRC16Only(byte[] value, int index, int length, byte CH, byte CL, byte preH = byte.MaxValue, byte preL = byte.MaxValue)
		{
			byte b = preL;
			byte b2 = preH;
			for (int i = index; i < index + length; i++)
			{
				b ^= value[i];
				for (int j = 0; j <= 7; j++)
				{
					byte num = b2;
					byte b3 = b;
					b2 >>= 1;
					b >>= 1;
					if ((num & 1) == 1)
					{
						b |= 0x80;
					}
					if ((b3 & 1) == 1)
					{
						b2 ^= CH;
						b ^= CL;
					}
				}
			}
			return new byte[2] { b, b2 };
		}
	}
	/// <summary>
	/// 用于LRC验证的类，提供了标准的验证方法<br />
	/// The class used for LRC verification provides a standard verification method
	/// </summary>
	public class SoftLRC
	{
		/// <summary>
		/// 获取对应的数据的LRC校验码<br />
		/// Class for LRC validation that provides a standard validation method
		/// </summary>
		/// <param name="value">需要校验的数据，不包含LRC字节</param>
		/// <returns>返回带LRC校验码的字节数组，可用于串口发送</returns>
		public static byte[] LRC(byte[] value)
		{
			if (value == null)
			{
				return null;
			}
			int num = 0;
			for (int i = 0; i < value.Length; i++)
			{
				num += value[i];
			}
			num %= 256;
			num = 256 - num;
			byte[] array = new byte[1] { (byte)num };
			return SoftBasic.SpliceArray<byte>(value, array);
		}

		/// <summary>
		/// 获取对应的数据的LRC校验码<br />
		/// Class for LRC validation that provides a standard validation method
		/// </summary>
		/// <param name="value">需要校验的数据，不包含LRC字节</param>
		/// <param name="left">忽略的左边的字节数量</param>
		/// <param name="right">忽略的右边的字节数量</param>
		/// <returns>返回LRC校验码</returns>
		public static byte LRC(byte[] value, int left, int right)
		{
			int num = 0;
			for (int i = left; i < value.Length - right; i++)
			{
				num += value[i];
			}
			num %= 256;
			num = 256 - num;
			return (byte)num;
		}

		/// <summary>
		/// 检查数据是否符合LRC的验证<br />
		/// Check data for compliance with LRC validation
		/// </summary>
		/// <param name="value">等待校验的数据，是否正确</param>
		/// <returns>是否校验成功</returns>
		public static bool CheckLRC(byte[] value)
		{
			if (value == null)
			{
				return false;
			}
			int num = value.Length;
			byte[] array = new byte[num - 1];
			Array.Copy(value, 0, array, 0, array.Length);
			if (LRC(array)[num - 1] == value[num - 1])
			{
				return true;
			}
			return false;
		}

		/// <inheritdoc cref="M:Snet.Driver.Serial.SoftLRC.CalculateAcc(System.Byte[],System.Int32,System.Int32)" />
		public static int CalculateAcc(byte[] buffer)
		{
			return CalculateAcc(buffer, 0, 0);
		}

		/// <summary>
		/// 根据传入的原始字节数组，计算和校验信息，可以指定起始的偏移地址和尾部的字节数量信息<br />
		/// Calculate and check the information according to the incoming original byte array, you can specify the starting offset address and the number of bytes at the end
		/// </summary>
		/// <param name="buffer">原始字节数组信息</param>
		/// <param name="headCount">起始的偏移地址信息</param>
		/// <param name="lastCount">尾部的字节数量信息</param>
		/// <returns>和校验的结果</returns>
		public static int CalculateAcc(byte[] buffer, int headCount, int lastCount)
		{
			int num = 0;
			for (int i = headCount; i < buffer.Length - lastCount; i++)
			{
				num += buffer[i];
			}
			return num;
		}

		/// <summary>
		/// 计算数据的和校验，并且输入和校验的值信息<br />
		/// Calculate the sum check of the data, and enter the value information of the sum check
		/// </summary>
		/// <param name="buffer">原始字节数组信息</param>
		/// <param name="headCount">起始的偏移地址信息</param>
		/// <param name="lastCount">尾部的字节数量信息</param>
		public static void CalculateAccAndFill(byte[] buffer, int headCount, int lastCount)
		{
			byte b = (byte)CalculateAcc(buffer, headCount, lastCount);
			Encoding.ASCII.GetBytes(b.ToString("X2")).CopyTo(buffer, buffer.Length - lastCount);
		}

		/// <summary>
		/// 计算数据的和校验，并且和当前已经存在的和校验信息进行匹配，返回是否匹配成功<br />
		/// Calculate the sum check of the data, and match it with the existing sum check information, and return whether the match is successful
		/// </summary>
		/// <param name="buffer">原始字节数组信息</param>
		/// <param name="headCount">起始的偏移地址信息</param>
		/// <param name="lastCount">尾部的字节数量信息</param>
		/// <returns>和校验是否检查通过</returns>
		public static bool CalculateAccAndCheck(byte[] buffer, int headCount, int lastCount)
		{
			return ((byte)CalculateAcc(buffer, headCount, lastCount)).ToString("X2") == Encoding.ASCII.GetString(buffer, buffer.Length - lastCount, 2);
		}

		/// <summary>
		/// 计算数据的异或信息，也称为 FCS，可以指定前面无用的字节数量，以及尾部无用的字节数量
		/// </summary>
		/// <param name="source">数据源信息</param>
		/// <param name="left">前面无用的字节数量</param>
		/// <param name="right">后面无用的字节数量</param>
		/// <returns>返回异或校验后的值</returns>
		public static byte[] CalculateFcs(byte[] source, int left, int right)
		{
			int num = source[left];
			for (int i = left + 1; i < source.Length - right; i++)
			{
				num ^= source[i];
			}
			return new byte[2]
			{
				SoftBasic.BuildAsciiBytesFrom((byte)num)[0],
				SoftBasic.BuildAsciiBytesFrom((byte)num)[1]
			};
		}
	}
}
namespace Snet.Driver.Robot.FANUC
{
	/// <summary>
	/// Fanuc机器人的报警对象
	/// </summary>
	public class FanucAlarm
	{
		/// <summary>
		/// AlarmID
		/// </summary>
		public short AlarmID { get; set; }

		/// <summary>
		/// AlarmNumber
		/// </summary>
		public short AlarmNumber { get; set; }

		/// <summary>
		/// CauseAlarmID
		/// </summary>
		public short CauseAlarmID { get; set; }

		/// <summary>
		/// CauseAlarmNumber
		/// </summary>
		public short CauseAlarmNumber { get; set; }

		/// <summary>
		/// Severity
		/// </summary>
		public short Severity { get; set; }

		/// <summary>
		/// Time
		/// </summary>
		public DateTime Time { get; set; }

		/// <summary>
		/// AlarmMessage
		/// </summary>
		public string AlarmMessage { get; set; }

		/// <summary>
		/// CauseAlarmMessage
		/// </summary>
		public string CauseAlarmMessage { get; set; }

		/// <summary>
		/// SeverityMessage
		/// </summary>
		public string SeverityMessage { get; set; }

		/// <summary>
		/// 从字节数据加载真实的信息
		/// </summary>
		/// <param name="byteTransform">字节变换</param>
		/// <param name="content">原始的字节内容</param>
		/// <param name="index">索引</param>
		/// <param name="encoding">编码</param>
		public void LoadByContent(IByteTransform byteTransform, byte[] content, int index, Encoding encoding)
		{
			AlarmID = BitConverter.ToInt16(content, index);
			AlarmNumber = BitConverter.ToInt16(content, index + 2);
			CauseAlarmID = BitConverter.ToInt16(content, index + 4);
			CauseAlarmNumber = BitConverter.ToInt16(content, index + 6);
			Severity = BitConverter.ToInt16(content, index + 8);
			if (BitConverter.ToInt16(content, index + 10) > 0)
			{
				Time = new DateTime(BitConverter.ToInt16(content, index + 10), BitConverter.ToInt16(content, index + 12), BitConverter.ToInt16(content, index + 14), BitConverter.ToInt16(content, index + 16), BitConverter.ToInt16(content, index + 18), BitConverter.ToInt16(content, index + 20));
			}
			AlarmMessage = encoding.GetString(content, index + 22, 80).Trim('\0');
			CauseAlarmMessage = encoding.GetString(content, index + 102, 80).Trim('\0');
			SeverityMessage = encoding.GetString(content, index + 182, 18).Trim('\0');
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"FanucAlarm ID[{AlarmID},{AlarmNumber},{CauseAlarmID},{CauseAlarmNumber},{Severity}]{Environment.NewLine}{AlarmMessage}{Environment.NewLine}{CauseAlarmMessage}{Environment.NewLine}{SeverityMessage}";
		}

		/// <summary>
		/// 从数据内容创建报警信息
		/// </summary>
		/// <param name="byteTransform">字节变换</param>
		/// <param name="content">原始的字节内容</param>
		/// <param name="index">索引</param>
		/// <param name="encoding">编码</param>
		/// <returns>报警信息</returns>
		public static FanucAlarm PraseFrom(IByteTransform byteTransform, byte[] content, int index, Encoding encoding)
		{
			FanucAlarm fanucAlarm = new FanucAlarm();
			fanucAlarm.LoadByContent(byteTransform, content, index, encoding);
			return fanucAlarm;
		}
	}
	/// <summary>
	/// Fanuc机器人的所有的数据信息
	/// </summary>
	public class FanucData
	{
		private bool isIni;

		public FanucAlarm[] AlarmList { get; set; }

		public FanucAlarm AlarmCurrent { get; set; }

		public FanucAlarm AlarmPassword { get; set; }

		public FanucPose CurrentPose { get; set; }

