		/// <summary>
		/// 按照字为单位批量读取设备的原始数据，需要指定数据块地址，偏移地址及长度，主要针对08, 10, 12的数据块，注意地址的起始为1<br />
		/// Read the raw data of the device in batches in units of words. You need to specify the data block address, offset address, and length. It is mainly for data blocks of 08, 10, and 12. Note that the start of the address is 1.
		/// </summary>
		/// <param name="select">数据块信息</param>
		/// <param name="address">偏移地址</param>
		/// <param name="length">读取的长度，字为单位</param>
		public OResult<byte[]> Read(byte select, ushort address, ushort length)
		{
			byte[] send = FanucHelper.BulidReadData(select, address, length);
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content[31] == 148)
			{
				return OResult.CreateSuccessResult(SoftBasic.ArrayRemoveBegin(oResult.Content, 56));
			}
			if (oResult.Content[31] == 212)
			{
				return OResult.CreateSuccessResult(SoftBasic.ArraySelectMiddle(oResult.Content, 44, length * 2));
			}
			return new OResult<byte[]>(oResult.Content[31], "Error");
		}

		/// <summary>
		/// 写入原始的byte数组数据到指定的地址，返回是否写入成功，，需要指定数据块地址，偏移地址，主要针对08, 10, 12的数据块，注意起始的起始为1<br />
		/// Write the original byte array data to the specified address, and return whether the writing is successful. You need to specify the data block address and offset address, 
		/// which are mainly for the data blocks of 08, 10, and 12. Note that the start of the start is 1.
		/// </summary>
		/// <param name="select">数据块信息</param>
		/// <param name="address">偏移地址</param>
		/// <param name="value">原始数据内容</param>
		public OResult Write(byte select, ushort address, byte[] value)
		{
			byte[] send = FanucHelper.BuildWriteData(select, address, value, value.Length / 2);
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content[31] == 212)
			{
				return OResult.CreateSuccessResult();
			}
			return new OResult<byte[]>(oResult.Content[31], "Error");
		}

		/// <summary>
		/// 按照位为单位批量读取设备的原始数据，需要指定数据块地址，偏移地址及长度，主要针对70, 72, 76的数据块，注意地址的起始为1<br />
		/// </summary>
		/// <param name="select">数据块信息</param>
		/// <param name="address">偏移地址</param>
		/// <param name="length">读取的长度，字为单位</param>
		public OResult<bool[]> ReadBool(byte select, ushort address, ushort length)
		{
			int num = address - 1 - (address - 1) % 8 + 1;
			int num2 = ((((address + length - 1) % 8 == 0) ? (address + length - 1) : ((address + length - 1) / 8 * 8 + 8)) - num + 1) / 8;
			byte[] send = FanucHelper.BulidReadData(select, address, (ushort)(num2 * 8));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content[31] == 148)
			{
				bool[] sourceArray = SoftBasic.ByteToBoolArray(SoftBasic.ArrayRemoveBegin(oResult.Content, 56));
				bool[] array = new bool[length];
				Array.Copy(sourceArray, address - num, array, 0, length);
				return OResult.CreateSuccessResult(array);
			}
			if (oResult.Content[31] == 212)
			{
				bool[] sourceArray2 = SoftBasic.ByteToBoolArray(SoftBasic.ArraySelectMiddle(oResult.Content, 44, num2));
				bool[] array2 = new bool[length];
				Array.Copy(sourceArray2, address - num, array2, 0, length);
				return OResult.CreateSuccessResult(array2);
			}
			return new OResult<bool[]>(oResult.Content[31], "Error");
		}

		/// <summary>
		/// 批量写入<see cref="T:System.Boolean" />数组数据，返回是否写入成功，需要指定数据块地址，偏移地址，主要针对70, 72, 76的数据块，注意起始的起始为1
		/// </summary>
		/// <param name="select">数据块信息</param>
		/// <param name="address">偏移地址</param>
		/// <param name="value">原始的数据内容</param>
		/// <returns>是否写入成功</returns>
		public OResult WriteBool(byte select, ushort address, bool[] value)
		{
			int num = address - 1 - (address - 1) % 8 + 1;
			bool[] array = new bool[((((address + value.Length - 1) % 8 == 0) ? (address + value.Length - 1) : ((address + value.Length - 1) / 8 * 8 + 8)) - num + 1) / 8 * 8];
			Array.Copy(value, 0, array, address - num, value.Length);
			byte[] send = FanucHelper.BuildWriteData(select, address, base.ByteTransform.TransByte(array), value.Length);
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<short[]>(oResult);
			}
			if (oResult.Content[31] == 212)
			{
				return OResult.CreateSuccessResult();
			}
			return new OResult();
		}

