		/// <inheritdoc cref="M:Snet.Driver.Robot.FANUC.FanucInterfaceNet.ReadBool(System.Byte,System.UInt16,System.UInt16)" />
		public async Task<OResult<bool[]>> ReadBoolAsync(byte select, ushort address, ushort length)
		{
			int byteStartIndex = address - 1 - (address - 1) % 8 + 1;
			int num = (((address + length - 1) % 8 == 0) ? (address + length - 1) : ((address + length - 1) / 8 * 8 + 8));
			int byteLength = (num - byteStartIndex + 1) / 8;
			byte[] send = FanucHelper.BulidReadData(select, address, (ushort)(byteLength * 8));
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content[31] == 148)
			{
				bool[] sourceArray = SoftBasic.ByteToBoolArray(SoftBasic.ArrayRemoveBegin(oResult.Content, 56));
				bool[] array = new bool[length];
				Array.Copy(sourceArray, address - byteStartIndex, array, 0, length);
				return OResult.CreateSuccessResult(array);
			}
			if (oResult.Content[31] == 212)
			{
				bool[] sourceArray2 = SoftBasic.ByteToBoolArray(SoftBasic.ArraySelectMiddle(oResult.Content, 44, byteLength));
				bool[] array2 = new bool[length];
				Array.Copy(sourceArray2, address - byteStartIndex, array2, 0, length);
				return OResult.CreateSuccessResult(array2);
			}
			return new OResult<bool[]>(oResult.Content[31], "Error");
		}

		/// <inheritdoc cref="M:Snet.Driver.Robot.FANUC.FanucInterfaceNet.WriteBool(System.Byte,System.UInt16,System.Boolean[])" />
		public async Task<OResult> WriteBoolAsync(byte select, ushort address, bool[] value)
		{
			int num = address - 1 - (address - 1) % 8 + 1;
			bool[] array = new bool[((((address + value.Length - 1) % 8 == 0) ? (address + value.Length - 1) : ((address + value.Length - 1) / 8 * 8 + 8)) - num + 1) / 8 * 8];
			Array.Copy(value, 0, array, address - num, value.Length);
			byte[] send = FanucHelper.BuildWriteData(select, address, base.ByteTransform.TransByte(array), value.Length);
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<short[]>(oResult);
			}
			if (oResult.Content[31] == 212)
			{
				return OResult.CreateSuccessResult();
			}
			return new OResult();
		}

