		/// <summary>
		/// 写入机器人的Rxyzwpr信息，谨慎调用，
		/// </summary>
		/// <param name="Address">偏移地址</param>
		/// <param name="Xyzwpr">姿态信息</param>
		/// <param name="Config">设置信息</param>
		/// <param name="UserFrame">参考系</param>
		/// <param name="UserTool">工具</param>
		/// <returns>是否写入成功</returns>
		public OResult WriteRXyzwpr(ushort Address, float[] Xyzwpr, short[] Config, short UserFrame, short UserTool)
		{
			byte[] array = new byte[Xyzwpr.Length * 4 + Config.Length * 2 + 2];
			base.ByteTransform.TransByte(Xyzwpr).CopyTo(array, 0);
			base.ByteTransform.TransByte(Config).CopyTo(array, 36);
			OResult oResult = Write(8, Address, array);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (0 <= UserFrame && UserFrame <= 15)
			{
				if (0 <= UserTool && UserTool <= 15)
				{
					oResult = Write(8, (ushort)(Address + 45), base.ByteTransform.TransByte(new short[2] { UserFrame, UserTool }));
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
				else
				{
					oResult = Write(8, (ushort)(Address + 45), base.ByteTransform.TransByte(new short[1] { UserFrame }));
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
			}
			else if (0 <= UserTool && UserTool <= 15)
			{
				oResult = Write(8, (ushort)(Address + 46), base.ByteTransform.TransByte(new short[1] { UserTool }));
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Robot.FANUC.FanucInterfaceNet.WriteRXyzwpr(System.UInt16,System.Single[],System.Int16[],System.Int16,System.Int16)" />
		public OResult WriteRXyzwpr(ushort Address, float[] Xyzwpr, string[] Config, short UserFrame, short UserTool)
		{
			short[] array = new short[7];
			if (Config != null)
			{
				if (Config.Length != 0)
				{
					array[0] = (Config[0].Equals("F", StringComparison.OrdinalIgnoreCase) ? ((short)1) : ((short)0));
				}
				if (Config.Length > 1)
				{
					array[1] = (Config[1].Equals("L", StringComparison.OrdinalIgnoreCase) ? ((short)1) : ((short)0));
				}
				if (Config.Length > 2)
				{
					array[2] = (Config[2].Equals("U", StringComparison.OrdinalIgnoreCase) ? ((short)1) : ((short)0));
				}
				if (Config.Length > 3)
				{
					array[3] = (Config[3].Equals("T", StringComparison.OrdinalIgnoreCase) ? ((short)1) : ((short)0));
				}
				if (Config.Length > 4)
				{
					array[4] = short.Parse(Config[4]);
				}
				if (Config.Length > 5)
				{
					array[5] = short.Parse(Config[5]);
				}
				if (Config.Length > 6)
				{
					array[6] = short.Parse(Config[6]);
				}
			}
			return WriteRXyzwpr(Address, Xyzwpr, array, UserFrame, UserTool);
		}

		/// <summary>
		/// 写入机器人的Joint信息
		/// </summary>
		/// <param name="address">偏移地址</param>
		/// <param name="joint">关节坐标</param>
		/// <param name="UserFrame">参考系</param>
		/// <param name="UserTool">工具</param>
		/// <returns>是否写入成功</returns>
		public OResult WriteRJoint(ushort address, float[] joint, short UserFrame, short UserTool)
		{
			OResult oResult = Write(8, (ushort)(address + 26), base.ByteTransform.TransByte(joint));
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (0 <= UserFrame && UserFrame <= 15)
			{
				if (0 <= UserTool && UserTool <= 15)
				{
					oResult = Write(8, (ushort)(address + 44), base.ByteTransform.TransByte(new short[3] { 0, UserFrame, UserTool }));
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
				else
				{
					oResult = Write(8, (ushort)(address + 44), base.ByteTransform.TransByte(new short[2] { 0, UserFrame }));
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
			}
			else
			{
				oResult = Write(8, (ushort)(address + 44), base.ByteTransform.TransByte(new short[1]));
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				if (0 <= UserTool && UserTool <= 15)
				{
					oResult = Write(8, (ushort)(address + 44), base.ByteTransform.TransByte(new short[2] { 0, UserTool }));
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Robot.FANUC.FanucInterfaceNet.ReadFanucData" />
		public async Task<OResult<FanucData>> ReadFanucDataAsync()
		{
			OResult<byte[]> oResult = await ReadAsync("");
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<FanucData>(oResult);
			}
			return FanucData.PraseFrom(oResult.Content, StringEncoding);
		}

