		/// <inheritdoc cref="M:Snet.Driver.Robot.FANUC.FanucInterfaceNet.WriteRXyzwpr(System.UInt16,System.Single[],System.Int16[],System.Int16,System.Int16)" />
		public async Task<OResult> WriteRXyzwprAsync(ushort Address, float[] Xyzwpr, short[] Config, short UserFrame, short UserTool)
		{
			byte[] array = new byte[Xyzwpr.Length * 4 + Config.Length * 2 + 2];
			base.ByteTransform.TransByte(Xyzwpr).CopyTo(array, 0);
			base.ByteTransform.TransByte(Config).CopyTo(array, 36);
			OResult oResult = await WriteAsync(8, Address, array);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (0 <= UserFrame && UserFrame <= 15)
			{
				if (0 <= UserTool && UserTool <= 15)
				{
					oResult = await WriteAsync(8, (ushort)(Address + 45), base.ByteTransform.TransByte(new short[2] { UserFrame, UserTool }));
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
				else
				{
					oResult = await WriteAsync(8, (ushort)(Address + 45), base.ByteTransform.TransByte(new short[1] { UserFrame }));
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
			}
			else if (0 <= UserTool && UserTool <= 15)
			{
				oResult = await WriteAsync(8, (ushort)(Address + 46), base.ByteTransform.TransByte(new short[1] { UserTool }));
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Robot.FANUC.FanucInterfaceNet.WriteRJoint(System.UInt16,System.Single[],System.Int16,System.Int16)" />
		public async Task<OResult> WriteRJointAsync(ushort address, float[] joint, short UserFrame, short UserTool)
		{
			OResult oResult = await WriteAsync(8, (ushort)(address + 26), base.ByteTransform.TransByte(joint));
			if (!oResult.IsSuccess)
			{
				return oResult;
