		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte, ushort> oResult = FanucHelper.AnalysisFanucAddress(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content2 == 0)
			{
				return new OResult<byte[]>("Address start can't be zero");
			}
			oResult.Content2--;
			if (oResult.Content1 == 8)
			{
				return OResult.CreateSuccessResult(dBuffer.GetBytes(oResult.Content2 * 2, length * 2));
			}
			if (oResult.Content1 == 10)
			{
				return OResult.CreateSuccessResult(aiBuffer.GetBytes(oResult.Content2 * 2, length * 2));
			}
			if (oResult.Content1 == 12)
			{
				return OResult.CreateSuccessResult(aqBuffer.GetBytes(oResult.Content2 * 2, length * 2));
			}
			return new OResult<byte[]>(StringResources.Language.NotSupportedDataType + ", Current address not support word read/write");
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte, ushort> oResult = FanucHelper.AnalysisFanucAddress(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content2 == 0)
			{
				return new OResult("Address start can't be zero");
			}
			oResult.Content2--;
			if (oResult.Content1 == 8)
			{
				dBuffer.SetBytes(value, oResult.Content2 * 2);
			}
			else if (oResult.Content1 == 10)
			{
				aiBuffer.SetBytes(value, oResult.Content2 * 2);
			}
			else
			{
				if (oResult.Content1 != 12)
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedDataType + ", Current address not support word read/write");
				}
				aqBuffer.SetBytes(value, oResult.Content2 * 2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<byte, ushort> oResult = FanucHelper.AnalysisFanucAddress(address, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content2 == 0)
			{
				return new OResult<bool[]>("Address start can't be zero");
			}
			oResult.Content2--;
			if (oResult.Content1 == 70)
			{
				return OResult.CreateSuccessResult((from m in iBuffer.GetBytes(oResult.Content2, length)
					select m != 0).ToArray());
			}
			if (oResult.Content1 == 72)
			{
				return OResult.CreateSuccessResult((from m in qBuffer.GetBytes(oResult.Content2, length)
					select m != 0).ToArray());
			}
			if (oResult.Content1 == 76)
			{
				return OResult.CreateSuccessResult((from m in mBuffer.GetBytes(oResult.Content2, length)
					select m != 0).ToArray());
			}
			return new OResult<bool[]>(StringResources.Language.NotSupportedDataType + ", Current address not support bool read/write");
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] value)
		{
			OResult<byte, ushort> oResult = FanucHelper.AnalysisFanucAddress(address, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content2 == 0)
			{
				return new OResult("Address start can't be zero");
			}
			oResult.Content2--;
			if (oResult.Content1 == 70)
			{
				iBuffer.SetBytes(value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), oResult.Content2);
			}
			else if (oResult.Content1 == 72)
			{
				qBuffer.SetBytes(value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), oResult.Content2);
			}
			else
			{
				if (oResult.Content1 != 76)
				{
					return new OResult(StringResources.Language.NotSupportedDataType + ", Current address not support bool read/write");
				}
				mBuffer.SetBytes(value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), oResult.Content2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FanucRobotMessage();
		}

		/// <inheritdoc />
		protected override OResult ThreadPoolLoginAfterClientCheck(PipeSession session, IPEndPoint endPoint)
		{
			CommunicationPipe communication = session.Communication;
			FanucRobotMessage netMessage = new FanucRobotMessage();
			OResult<byte[]> oResult = communication.ReceiveMessage(netMessage, null, useActivePush: false, null, delegate(byte[] m)
			{
				LogRevcMessage(m, session);
			});
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			byte[] array = SoftBasic.HexStringToBytes("01 00 00 00 00 00 00 00 01 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00");
			LogSendMessage(array, session);
			OResult oResult2 = communication.Send(array);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = communication.ReceiveMessage(netMessage, null, useActivePush: false, null, delegate(byte[] m)
			{
				LogRevcMessage(m, session);
			});
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			byte[] array2 = SoftBasic.HexStringToBytes("03 00 01 00 00 00 00 00 00 01 00 00 00 00 00 00 00 01 00 00 00 00 00 00 00 00 00 00 00 00 01 d4 10 0e 00 00 30 3a 00 00 01 01 00 00 00 00 00 00 01 01 ff 02 00 00 7c 21");
			LogSendMessage(array2, session);
			OResult result = communication.Send(array2);
			if (!oResult3.IsSuccess)
			{
				return result;
			}
			return base.ThreadPoolLoginAfterClientCheck(session, endPoint);
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			int num = ((receive[2] == 6) ? receive[43] : ((receive[2] == 8) ? receive[43] : ((receive[2] == 9) ? receive[51] : 0)));
			byte[] array = null;
			if (num == 56)
			{
				array = GetCommandBackMessage(receive[2]);
			}
			else if (receive[2] == 6)
			{
				array = GetReadBackMessage(receive, num);
			}
			else
			{
				if (receive[2] != 8 && receive[2] != 9)
				{
					return new OResult<byte[]>($"Not supported function: {receive[2]}");
				}
				array = GetWriteBackMessage(receive, num);
			}
			return OResult.CreateSuccessResult(array);
		}

		private byte[] GetCommandBackMessage(byte command)
		{
			byte[] array = SoftBasic.HexStringToBytes("\r\n03 00 08 00 00 00 00 00 00 01 00 00 00 00 00 00\r\n00 01 00 00 00 00 00 00 00 00 00 00 00 00 08 d4\r\n10 0e 00 00 30 3a 00 00 01 01 00 00 00 00 00 00\r\n01 01 ff 04 00 00 7c 21");
			array[2] = command;
			return array;
		}

		private byte[] GetReadBackMessage(byte[] command, int select)
		{
			ushort num = BitConverter.ToUInt16(command, 44);
			ushort num2 = BitConverter.ToUInt16(command, 46);
			switch (select)
			{
			case 8:
				return FanucHelper.BuildReadResponseData(dBuffer.GetBytes(num * 2, num2 * 2));
			case 10:
				return FanucHelper.BuildReadResponseData(aiBuffer.GetBytes(num * 2, num2 * 2));
			case 12:
				return FanucHelper.BuildReadResponseData(aqBuffer.GetBytes(num * 2, num2 * 2));
			default:
				if (select != 72)
				{
					return FanucHelper.BuildReadResponseData(new byte[0]);
				}
				break;
			case 70:
			case 76:
				break;
			}
			int num3 = num / 8 * 8;
			int length = num + num2 - num3;
			return FanucHelper.BuildReadResponseData(SoftBasic.BoolArrayToByte((from m in (@select switch
				{
					70 => iBuffer, 
					76 => mBuffer, 
					_ => qBuffer, 
				}).GetBytes(num3, length)
				select m != 0).ToArray()));
		}

		private byte[] GetWriteBackMessage(byte[] command, int select)
		{
			if (!base.EnableWrite)
			{
				return null;
			}
			ushort num = BitConverter.ToUInt16(command, (command[2] == 8) ? 44 : 52);
			ushort num2 = BitConverter.ToUInt16(command, (command[2] == 8) ? 46 : 54);
			int num3 = ((command[2] == 8) ? 48 : 56);
			if (select == 8 || select == 10 || select == 12)
			{
				switch (select)
				{
				case 8:
					dBuffer.SetBytes(SoftBasic.ArraySelectMiddle(command, num3, num2 * 2), num * 2, num2 * 2);
					break;
				case 10:
					aiBuffer.SetBytes(SoftBasic.ArraySelectMiddle(command, num3, num2 * 2), num * 2, num2 * 2);
					break;
				case 12:
					aqBuffer.SetBytes(SoftBasic.ArraySelectMiddle(command, num3, num2 * 2), num * 2, num2 * 2);
					break;
				}
			}
			else
			{
				int index = num % 8;
				byte[] data = (from m in SoftBasic.ArraySelectMiddle(SoftBasic.ByteToBoolArray(SoftBasic.ArrayRemoveBegin(command, num3)), index, num2)
					select m ? ((byte)1) : ((byte)0)).ToArray();
				switch (select)
				{
				case 76:
					mBuffer.SetBytes(data, num);
					break;
				case 70:
					iBuffer.SetBytes(data, num);
					break;
				case 72:
					qBuffer.SetBytes(data, num);
					break;
				}
			}
			byte[] array = SoftBasic.HexStringToBytes("03 00 09 00 00 00 00 00 00 01 00 00 00 00 00 00 00 01 00 00 00 00 00 00 \r\n00 00 00 00 00 00 09 d4 10 0e 00 00 30 3a 00 00 01 01 00 00 00 00 00 00 01 01 ff 04 00 00 7c 21");
			array[2] = command[2];
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 393216)
			{
				throw new Exception("File is not correct");
			}
			iBuffer.SetBytes(content, 0, 0, 65536);
			qBuffer.SetBytes(content, 65536, 0, 65536);
			mBuffer.SetBytes(content, 131072, 0, 65536);
			aiBuffer.SetBytes(content, 196608, 0, 65536);
			aqBuffer.SetBytes(content, 262144, 0, 65536);
			dBuffer.SetBytes(content, 327680, 0, 65536);
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[393216];
			Array.Copy(iBuffer.GetBytes(), 0, array, 0, 65536);
			Array.Copy(qBuffer.GetBytes(), 0, array, 65536, 65536);
			Array.Copy(mBuffer.GetBytes(), 0, array, 131072, 65536);
			Array.Copy(aiBuffer.GetBytes(), 0, array, 196608, 65536);
			Array.Copy(aqBuffer.GetBytes(), 0, array, 262144, 65536);
			Array.Copy(dBuffer.GetBytes(), 0, array, 327680, 65536);
			return array;
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				iBuffer?.Dispose();
				qBuffer?.Dispose();
				mBuffer?.Dispose();
				dBuffer?.Dispose();
				aiBuffer?.Dispose();
				aqBuffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"FanucRobotServer[{base.Port}]";
		}
	}
	/// <summary>
	/// Fanuc机器人的任务类
	/// </summary>
	public class FanucTask
	{
		/// <summary>
		/// ProgramName
		/// </summary>
		public string ProgramName { get; set; }

		/// <summary>
		/// LineNumber
		/// </summary>
		public short LineNumber { get; set; }

		/// <summary>
		/// State
		/// </summary>
		public short State { get; set; }

		/// <summary>
		/// ParentProgramName
		/// </summary>
		public string ParentProgramName { get; set; }

		/// <summary>
		/// 从原始的数据对象加载数据信息
		/// </summary>
		/// <param name="byteTransform">字节变换</param>
		/// <param name="content">原始的字节数据</param>
		/// <param name="index">索引信息</param>
		/// <param name="encoding">编码</param>
		public void LoadByContent(IByteTransform byteTransform, byte[] content, int index, Encoding encoding)
		{
			ProgramName = encoding.GetString(content, index, 16).Trim('\0');
			LineNumber = BitConverter.ToInt16(content, index + 16);
			State = BitConverter.ToInt16(content, index + 18);
			ParentProgramName = encoding.GetString(content, index + 20, 16).Trim('\0');
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"ProgramName[{ProgramName}] LineNumber[{LineNumber}] State[{State}] ParentProgramName[{ParentProgramName}]";
		}

		/// <summary>
		/// 从原始的数据信息初始化一个任务对象
		/// </summary>
		/// <param name="byteTransform">字节变换</param>
		/// <param name="content">原始的字节数据</param>
		/// <param name="index">索引信息</param>
		/// <param name="encoding">编码</param>
		/// <returns>任务对象</returns>
		public static FanucTask ParseFrom(IByteTransform byteTransform, byte[] content, int index, Encoding encoding)
		{
			FanucTask fanucTask = new FanucTask();
			fanucTask.LoadByContent(byteTransform, content, index, encoding);
			return fanucTask;
		}
	}
