		public static SnetDeviceAddressAttribute GetSnetDeviceAddressAttribute(Type deviceType, PropertyInfo property)
		{
			object[] customAttributes = property.GetCustomAttributes(typeof(SnetDeviceAddressAttribute), inherit: false);
			if (customAttributes == null)
			{
				return null;
			}
			SnetDeviceAddressAttribute snetDeviceAddressAttribute = null;
			for (int i = 0; i < customAttributes.Length; i++)
			{
				SnetDeviceAddressAttribute snetDeviceAddressAttribute2 = (SnetDeviceAddressAttribute)customAttributes[i];
				if (snetDeviceAddressAttribute2.DeviceType != null && snetDeviceAddressAttribute2.DeviceType == deviceType)
				{
					snetDeviceAddressAttribute = snetDeviceAddressAttribute2;
					break;
				}
			}
			if (snetDeviceAddressAttribute == null)
			{
				for (int j = 0; j < customAttributes.Length; j++)
				{
					SnetDeviceAddressAttribute snetDeviceAddressAttribute3 = (SnetDeviceAddressAttribute)customAttributes[j];
					if (snetDeviceAddressAttribute3.DeviceType == null)
					{
						snetDeviceAddressAttribute = snetDeviceAddressAttribute3;
						break;
					}
				}
			}
			return snetDeviceAddressAttribute;
		}

