		public static SnetDeviceAddressAttribute[] GetSnetDeviceAddressAttributeArray(Type deviceType, PropertyInfo property)
		{
			object[] customAttributes = property.GetCustomAttributes(typeof(SnetDeviceAddressAttribute), inherit: false);
			if (customAttributes == null)
			{
				return null;
			}
			List<SnetDeviceAddressAttribute> list = new List<SnetDeviceAddressAttribute>();
			for (int i = 0; i < customAttributes.Length; i++)
			{
				SnetDeviceAddressAttribute snetDeviceAddressAttribute = (SnetDeviceAddressAttribute)customAttributes[i];
				if (snetDeviceAddressAttribute.DeviceType != null && snetDeviceAddressAttribute.DeviceType == deviceType)
				{
					list.Add(snetDeviceAddressAttribute);
				}
			}
			if (list.Count == 0)
			{
				for (int j = 0; j < customAttributes.Length; j++)
				{
					SnetDeviceAddressAttribute snetDeviceAddressAttribute2 = (SnetDeviceAddressAttribute)customAttributes[j];
					if (snetDeviceAddressAttribute2.DeviceType == null)
					{
						list.Add(snetDeviceAddressAttribute2);
					}
				}
			}
			return list.ToArray();
		}

		private static void SetReadAttributeString(PropertyInfo property, object obj, IReadWriteNet readWrite, byte[] content, SnetDeviceAddressAttribute SnetDeviceAddressAttribute)
		{
			string[] array = new string[SnetDeviceAddressAttribute.StringArrayLength];
			int num = content.Length / SnetDeviceAddressAttribute.StringArrayLength;
			for (int i = 0; i < SnetDeviceAddressAttribute.StringArrayLength; i++)
			{
				if (readWrite.GetType() == typeof(SiemensS7Net))
				{
					array[i] = SnetDeviceAddressAttribute.GetEncoding().GetString(content, i * num + 2, content[i * num + 1]).TrimEnd();
				}
				else
				{
					array[i] = readWrite.ByteTransform.TransString(content, i * num, num, SnetDeviceAddressAttribute.GetEncoding()).TrimEnd('\0');
				}
			}
			property.SetValue(obj, array, null);
		}

