		private static byte[] WriteAttributeStringArray(PropertyInfo property, object obj, byte[] content, IReadWriteNet readWrite, SnetDeviceAddressAttribute SnetDeviceAddressAttribute)
		{
			int num = content.Length / SnetDeviceAddressAttribute.StringArrayLength;
			string[] array = (string[])property.GetValue(obj, null);
			if (readWrite.GetType() == typeof(SiemensS7Net))
			{
				for (int i = 0; i < array.Length; i++)
				{
					byte[] array2 = SnetDeviceAddressAttribute.GetEncoding().GetBytes(array[i] ?? "");
					if (array2.Length > num - 2)
					{
						array2 = array2.SelectBegin(num - 2);
					}
					Array.Copy(array2, 0, content, i * num + 2, Math.Min(array2.Length, num - 2));
					content[i * num + 1] = (byte)Math.Min(array2.Length, num - 2);
				}
			}
			else
			{
				Array.Clear(content, 0, content.Length);
				for (int j = 0; j < array.Length; j++)
				{
					byte[] array3 = SnetDeviceAddressAttribute.GetEncoding().GetBytes(array[j] ?? "");
					if (readWrite.ByteTransform.IsStringReverseByteWord)
					{
						array3 = SoftBasic.BytesReverseByWord(array3);
					}
					Array.Copy(array3, 0, content, j * num, Math.Min(array3.Length, num));
				}
			}
			return content;
		}

