		/// <param name="byteTransform">数据变换规则对象</param>
		/// <returns>新的实例化的类型对象</returns>
		public static T PraseStructContent<T>(byte[] buffer, int startIndex, IByteTransform byteTransform) where T : class, new()
		{
			Type typeFromHandle = typeof(T);
			object? obj = typeFromHandle.Assembly.CreateInstance(typeFromHandle.FullName);
			PraseStructContent(obj, buffer, startIndex, byteTransform);
			return (T)obj;
		}

		/// <summary>
		/// 根据结构体的定义，将原始字节的数据解析出来，然后赋值给对应的对象，该对象的属性需要支持特性 <see cref="T:Snet.Driver.Reflection.SnetStructAttribute" /> 才支持设置
		/// </summary>
		/// <param name="obj">类型对象信息</param>
		/// <param name="buffer">读取的缓存数据信息</param>
		/// <param name="startIndex">起始的偏移地址</param>
		/// <param name="byteTransform">数据变换规则对象</param>
		public static void PraseStructContent(object obj, byte[] buffer, int startIndex, IByteTransform byteTransform)
		{
			PropertyInfo[] properties = obj.GetType().GetProperties(BindingFlags.Instance | BindingFlags.Public);
			foreach (PropertyInfo propertyInfo in properties)
			{
				object[] customAttributes = propertyInfo.GetCustomAttributes(typeof(SnetStructAttribute), inherit: false);
				if (customAttributes == null)
				{
					continue;
				}
				SnetStructAttribute snetStructAttribute = ((customAttributes.Length != 0) ? ((SnetStructAttribute)customAttributes[0]) : null);
				if (snetStructAttribute == null)
				{
					continue;
				}
				Type propertyType = propertyInfo.PropertyType;
				if (propertyType == typeof(byte))
				{
					propertyInfo.SetValue(obj, buffer[startIndex + snetStructAttribute.Index], null);
				}
				else if (propertyType == typeof(byte[]))
				{
					propertyInfo.SetValue(obj, buffer.SelectMiddle(startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(short))
				{
					propertyInfo.SetValue(obj, byteTransform.TransInt16(buffer, startIndex + snetStructAttribute.Index), null);
				}
				else if (propertyType == typeof(short[]))
				{
					propertyInfo.SetValue(obj, byteTransform.TransInt16(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(ushort))
				{
					propertyInfo.SetValue(obj, byteTransform.TransUInt16(buffer, startIndex + snetStructAttribute.Index), null);
				}
				else if (propertyType == typeof(ushort[]))
				{
					propertyInfo.SetValue(obj, byteTransform.TransUInt16(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(int))
				{
					propertyInfo.SetValue(obj, byteTransform.TransInt32(buffer, startIndex + snetStructAttribute.Index), null);
				}
				else if (propertyType == typeof(int[]))
				{
					propertyInfo.SetValue(obj, byteTransform.TransInt32(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(uint))
				{
					propertyInfo.SetValue(obj, byteTransform.TransUInt32(buffer, startIndex + snetStructAttribute.Index), null);
				}
				else if (propertyType == typeof(uint[]))
				{
					propertyInfo.SetValue(obj, byteTransform.TransUInt32(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(long))
				{
					propertyInfo.SetValue(obj, byteTransform.TransInt64(buffer, startIndex + snetStructAttribute.Index), null);
				}
				else if (propertyType == typeof(long[]))
				{
					propertyInfo.SetValue(obj, byteTransform.TransInt64(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(ulong))
				{
					propertyInfo.SetValue(obj, byteTransform.TransUInt64(buffer, startIndex + snetStructAttribute.Index), null);
				}
				else if (propertyType == typeof(ulong[]))
				{
					propertyInfo.SetValue(obj, byteTransform.TransUInt64(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(float))
				{
					propertyInfo.SetValue(obj, byteTransform.TransSingle(buffer, startIndex + snetStructAttribute.Index), null);
				}
				else if (propertyType == typeof(float[]))
				{
					propertyInfo.SetValue(obj, byteTransform.TransSingle(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(double))
				{
					propertyInfo.SetValue(obj, byteTransform.TransDouble(buffer, startIndex + snetStructAttribute.Index), null);
				}
				else if (propertyType == typeof(double[]))
				{
					propertyInfo.SetValue(obj, byteTransform.TransDouble(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length), null);
				}
				else if (propertyType == typeof(string))
				{
					Encoding uTF = Encoding.UTF8;
					uTF = (string.IsNullOrEmpty(snetStructAttribute.Encoding) ? Encoding.ASCII : (snetStructAttribute.Encoding.Equals("ASCII", StringComparison.OrdinalIgnoreCase) ? Encoding.ASCII : (snetStructAttribute.Encoding.Equals("UNICODE", StringComparison.OrdinalIgnoreCase) ? Encoding.Unicode : (snetStructAttribute.Encoding.Equals("ANSI", StringComparison.OrdinalIgnoreCase) ? Encoding.Default : (snetStructAttribute.Encoding.Equals("UTF8", StringComparison.OrdinalIgnoreCase) ? Encoding.UTF8 : (snetStructAttribute.Encoding.Equals("BIG-UNICODE", StringComparison.OrdinalIgnoreCase) ? Encoding.BigEndianUnicode : ((!snetStructAttribute.Encoding.Equals("GB2312", StringComparison.OrdinalIgnoreCase)) ? Encoding.GetEncoding(snetStructAttribute.Encoding) : Encoding.GetEncoding("GB2312"))))))));
					if (snetStructAttribute.StringMode == 0)
					{
						propertyInfo.SetValue(obj, byteTransform.TransString(buffer, startIndex + snetStructAttribute.Index, snetStructAttribute.Length, uTF), null);
					}
					else if (snetStructAttribute.StringMode == 1)
					{
						propertyInfo.SetValue(obj, byteTransform.TransString(buffer, startIndex + snetStructAttribute.Index + 1, buffer[startIndex + snetStructAttribute.Index], uTF), null);
					}
					else if (snetStructAttribute.StringMode == 2)
					{
						propertyInfo.SetValue(obj, byteTransform.TransString(buffer, startIndex + snetStructAttribute.Index + 2, buffer[startIndex + snetStructAttribute.Index + 1], uTF), null);
					}
					else if (snetStructAttribute.StringMode == 3)
					{
						propertyInfo.SetValue(obj, byteTransform.TransString(buffer, startIndex + snetStructAttribute.Index + 2, byteTransform.TransUInt16(buffer, startIndex + snetStructAttribute.Index), uTF), null);
					}
					else if (snetStructAttribute.StringMode == 4)
					{
						propertyInfo.SetValue(obj, byteTransform.TransString(buffer, startIndex + snetStructAttribute.Index + 4, byteTransform.TransUInt16(buffer, startIndex + snetStructAttribute.Index + 2), uTF), null);
					}
					else if (snetStructAttribute.StringMode == 5)
					{
						propertyInfo.SetValue(obj, byteTransform.TransString(buffer, startIndex + snetStructAttribute.Index + 4, byteTransform.TransInt32(buffer, startIndex + snetStructAttribute.Index), uTF), null);
					}
				}
				else if (propertyType == typeof(bool))
				{
					int num = startIndex * 8 + snetStructAttribute.Index;
					if (snetStructAttribute.BoolMode == 1)
					{
						if (num % 16 >= 8)
						{
							propertyInfo.SetValue(obj, buffer.GetBoolByIndex(num - 8), null);
						}
						else
						{
							propertyInfo.SetValue(obj, buffer.GetBoolByIndex(num + 8), null);
						}
					}
					else
					{
						propertyInfo.SetValue(obj, buffer.GetBoolByIndex(num), null);
					}
				}
				else if (propertyType == typeof(bool[]))
				{
					bool[] array = new bool[snetStructAttribute.Length];
					for (int j = 0; j < array.Length; j++)
					{
						int num2 = startIndex * 8 + snetStructAttribute.Index + j;
						if (snetStructAttribute.BoolMode == 1)
						{
							if (num2 % 16 >= 8)
							{
								array[j] = buffer.GetBoolByIndex(num2 - 8);
							}
							else
							{
								array[j] = buffer.GetBoolByIndex(num2 + 8);
							}
						}
						else
						{
							array[j] = buffer.GetBoolByIndex(num2);
						}
					}
					propertyInfo.SetValue(obj, array, null);
				}
				else
				{
					object obj2 = propertyType.Assembly.CreateInstance(propertyType.FullName);
					PraseStructContent(obj2, buffer, startIndex + snetStructAttribute.Index, byteTransform);
					propertyInfo.SetValue(obj, obj2, null);
				}
			}
		}

		/// <summary>
		/// 使用表达式树的方式来给一个属性赋值
		/// </summary>
		/// <param name="propertyInfo">属性信息</param>
		/// <param name="obj">对象信息</param>
		/// <param name="objValue">实际的值</param>
		public static void SetPropertyExp<T, K>(PropertyInfo propertyInfo, T obj, K objValue)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(T), "obj");
			ParameterExpression parameterExpression2 = Expression.Parameter(propertyInfo.PropertyType, "objValue");
			Expression.Lambda<Action<T, K>>(Expression.Call(parameterExpression, propertyInfo.GetSetMethod(), parameterExpression2), new ParameterExpression[2] { parameterExpression, parameterExpression2 }).Compile()(obj, objValue);
		}

		/// <summary>
		/// 从设备里读取支持Snet特性的数据内容，该特性为<see cref="T:Snet.Driver.Reflection.SnetDeviceAddressAttribute" />，详细参考论坛的操作说明。
