		/// <summary>
		/// 从设备里读取支持Snet特性的数据内容，该特性为<see cref="T:Snet.Driver.Reflection.SnetDeviceAddressAttribute" />，详细参考论坛的操作说明。
		/// </summary>
		/// <typeparam name="T">自定义的数据类型对象</typeparam>
		/// <param name="data">自定义的数据对象</param>
		/// <param name="readWrite">数据读写对象</param>
		/// <returns>包含是否成功的结果对象</returns>
		/// <exception cref="T:System.ArgumentNullException"></exception>
		public static async Task<OResult> WriteAsync<T>(T data, IReadWriteNet readWrite) where T : class, new()
		{
			if (data == null)
			{
				throw new ArgumentNullException("data");
			}
			PropertyInfo[] properties = typeof(T).GetProperties(BindingFlags.Instance | BindingFlags.Public);
			PropertyInfo[] array = properties;
			foreach (PropertyInfo property in array)
			{
				Type propertyType = property.PropertyType;
				if (propertyType == typeof(string[]))
				{
					SnetDeviceAddressAttribute[] SnetAttributes = GetSnetDeviceAddressAttributeArray(readWrite.GetType(), property);
					if (SnetAttributes == null || SnetAttributes.Length == 0)
					{
						continue;
					}
					if (SnetAttributes.Length == 1 && SnetAttributes[0].StringArrayLength > 0)
					{
						OResult<byte[]> oResult = await readWrite.ReadAsync(SnetAttributes[0].Address, (ushort)(SnetAttributes[0].Length * SnetAttributes[0].StringArrayLength));
						if (!oResult.IsSuccess)
						{
							return OResult.CreateFailedResult<T>(oResult);
						}
						OResult oResult2 = await readWrite.WriteAsync(SnetAttributes[0].Address, WriteAttributeStringArray(property, data, oResult.Content, readWrite, SnetAttributes[0]));
						if (!oResult2.IsSuccess)
						{
							return oResult2;
						}
						continue;
					}
					string[] strings = (string[])property.GetValue(data, null);
					for (int j = 0; j < SnetAttributes.Length; j++)
					{
						OResult oResult3 = await readWrite.WriteAsync(SnetAttributes[j].Address, strings[j], SnetAttributes[j].GetEncoding());
						if (!oResult3.IsSuccess)
						{
							return oResult3;
						}
					}
				}
				else
				{
					if (property.GetCustomAttributes(typeof(SnetDeviceAddressAttribute), inherit: false) == null)
					{
						continue;
					}
					SnetDeviceAddressAttribute snetDeviceAddressAttribute = GetSnetDeviceAddressAttribute(readWrite.GetType(), property);
					if (snetDeviceAddressAttribute == null)
					{
						continue;
					}
					if (propertyType == typeof(byte))
					{
						MethodInfo method = readWrite.GetType().GetMethod("WriteAsync", new Type[2]
						{
							typeof(string),
							typeof(byte)
						});
						if (method == null)
						{
							return new OResult<T>(readWrite.GetType().Name + " not support write byte value. ");
						}
						byte b = (byte)property.GetValue(data, null);
						object obj = method.Invoke(readWrite, new object[2] { snetDeviceAddressAttribute.Address, b });
						if (!(obj is Task writeTask))
						{
							return new OResult(readWrite.GetType().Name + " not task type result. ");
						}
						await writeTask;
						OResult oResult4 = writeTask.GetType().GetProperty("Result").GetValue(writeTask, null) as OResult;
						if (!oResult4.IsSuccess)
						{
							return OResult.CreateFailedResult<T>(oResult4);
						}
					}
					else if (propertyType == typeof(short))
					{
						OResult oResult5 = await readWrite.WriteAsync(value: (short)property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult5.IsSuccess)
						{
							return oResult5;
						}
					}
					else if (propertyType == typeof(short[]))
					{
						OResult oResult6 = await readWrite.WriteAsync(values: (short[])property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult6.IsSuccess)
						{
							return oResult6;
						}
					}
					else if (propertyType == typeof(ushort))
					{
						OResult oResult7 = await readWrite.WriteAsync(value: (ushort)property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult7.IsSuccess)
						{
							return oResult7;
						}
					}
					else if (propertyType == typeof(ushort[]))
					{
						OResult oResult8 = await readWrite.WriteAsync(values: (ushort[])property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult8.IsSuccess)
						{
							return oResult8;
						}
					}
					else if (propertyType == typeof(int))
					{
						OResult oResult9 = await readWrite.WriteAsync(value: (int)property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult9.IsSuccess)
						{
							return oResult9;
						}
					}
					else if (propertyType == typeof(int[]))
					{
						OResult oResult10 = await readWrite.WriteAsync(values: (int[])property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult10.IsSuccess)
						{
							return oResult10;
						}
					}
					else if (propertyType == typeof(uint))
					{
						OResult oResult11 = await readWrite.WriteAsync(value: (uint)property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult11.IsSuccess)
						{
							return oResult11;
						}
					}
					else if (propertyType == typeof(uint[]))
					{
						OResult oResult12 = await readWrite.WriteAsync(values: (uint[])property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
