						}
					}
					else if (propertyType == typeof(ulong))
					{
						OResult oResult15 = await readWrite.WriteAsync(value: (ulong)property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult15.IsSuccess)
						{
							return oResult15;
						}
					}
					else if (propertyType == typeof(ulong[]))
					{
						OResult oResult16 = await readWrite.WriteAsync(values: (ulong[])property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult16.IsSuccess)
						{
							return oResult16;
						}
					}
					else if (propertyType == typeof(float))
					{
						OResult oResult17 = await readWrite.WriteAsync(value: (float)property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult17.IsSuccess)
						{
							return oResult17;
						}
					}
					else if (propertyType == typeof(float[]))
					{
						OResult oResult18 = await readWrite.WriteAsync(values: (float[])property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult18.IsSuccess)
						{
							return oResult18;
						}
					}
					else if (propertyType == typeof(double))
					{
						OResult oResult19 = await readWrite.WriteAsync(value: (double)property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult19.IsSuccess)
						{
							return oResult19;
						}
					}
					else if (propertyType == typeof(double[]))
					{
						OResult oResult20 = await readWrite.WriteAsync(values: (double[])property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult20.IsSuccess)
						{
							return oResult20;
						}
					}
					else if (propertyType == typeof(string))
					{
						OResult oResult21 = await readWrite.WriteAsync(value: (string)property.GetValue(data, null), address: snetDeviceAddressAttribute.Address, encoding: snetDeviceAddressAttribute.GetEncoding());
						if (!oResult21.IsSuccess)
						{
							return oResult21;
