					}
					else if (propertyType == typeof(byte[]))
					{
						OResult oResult22 = await readWrite.WriteAsync(value: (byte[])property.GetValue(data, null), address: snetDeviceAddressAttribute.Address);
						if (!oResult22.IsSuccess)
