		/// <summary>
		/// 根据提供的类型对象，解析出符合 <see cref="T:Snet.Driver.Reflection.SnetDeviceAddressAttribute" /> 特性的地址列表
		/// </summary>
		/// <param name="valueType">数据类型</param>
		/// <param name="deviceType">设备类型</param>
		/// <param name="obj">类型的对象信息</param>
		/// <param name="byteTransform">数据变换对象</param>
		/// <returns>地址列表信息</returns>
		public static List<SnetAddressProperty> GetSnetPropertyInfos(Type valueType, Type deviceType, object obj, IByteTransform byteTransform)
		{
			List<SnetAddressProperty> list = new List<SnetAddressProperty>();
			PropertyInfo[] properties = valueType.GetProperties(BindingFlags.Instance | BindingFlags.Public);
			int num = 0;
			PropertyInfo[] array = properties;
			foreach (PropertyInfo propertyInfo in array)
			{
				SnetDeviceAddressAttribute snetDeviceAddressAttribute = GetSnetDeviceAddressAttribute(deviceType, propertyInfo);
				if (snetDeviceAddressAttribute == null)
				{
					continue;
				}
				SnetAddressProperty snetAddressProperty = new SnetAddressProperty();
				snetAddressProperty.PropertyInfo = propertyInfo;
				snetAddressProperty.DeviceAddressAttribute = snetDeviceAddressAttribute;
				snetAddressProperty.ByteOffset = num;
				Type propertyType = propertyInfo.PropertyType;
				if (propertyType == typeof(byte))
				{
					num++;
					if (obj != null)
					{
						snetAddressProperty.Buffer = new byte[1] { (byte)propertyInfo.GetValue(obj, null) };
					}
				}
				else if (propertyType == typeof(short))
				{
					num += 2;
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((short)propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(short[]))
				{
					num += 2 * ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((short[])propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(ushort))
				{
					num += 2;
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((ushort)propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(ushort[]))
				{
					num += 2 * ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((ushort[])propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(int))
				{
					num += 4;
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((int)propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(int[]))
				{
					num += 4 * ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((int[])propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(uint))
				{
					num += 4;
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((uint)propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(uint[]))
				{
					num += 4 * ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((uint[])propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(long))
				{
					num += 8;
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((long)propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(long[]))
				{
					num += 8 * ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((long[])propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(ulong))
				{
					num += 8;
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((ulong)propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(ulong[]))
				{
					num += 8 * ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((ulong[])propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(float))
				{
					num += 4;
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((float)propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(float[]))
				{
					num += 4 * ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((float[])propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(double))
				{
					num += 8;
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((double)propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(double[]))
				{
					num += 8 * ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((double[])propertyInfo.GetValue(obj, null));
					}
				}
				else if (propertyType == typeof(string))
				{
					num += ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = byteTransform.TransByte((string)propertyInfo.GetValue(obj, null), Encoding.ASCII);
					}
				}
				else if (propertyType == typeof(byte[]))
				{
					num += ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = (byte[])propertyInfo.GetValue(obj, null);
					}
				}
				else if (propertyType == typeof(bool))
				{
					num++;
					if (obj != null)
					{
						snetAddressProperty.Buffer = ((!(bool)propertyInfo.GetValue(obj, null)) ? new byte[1] : new byte[1] { 1 });
					}
				}
				else if (propertyType == typeof(bool[]))
				{
					num += ((snetDeviceAddressAttribute.Length <= 0) ? 1 : snetDeviceAddressAttribute.Length);
					if (obj != null)
					{
						snetAddressProperty.Buffer = ((bool[])propertyInfo.GetValue(obj, null)).Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray();
					}
				}
				snetAddressProperty.ByteLength = num - snetAddressProperty.ByteOffset;
				list.Add(snetAddressProperty);
			}
			return list;
		}

		/// <summary>
		/// 根据地址列表信息，数据缓存，自动解析基础类型的数据，赋值到自定义的对象上去
		/// </summary>
		/// <param name="byteTransform">数据解析对象</param>
		/// <param name="obj">数据对象信息</param>
		/// <param name="properties">地址属性列表</param>
		/// <param name="buffer">缓存数据信息</param>
		public static void SetPropertyValueFrom(IByteTransform byteTransform, object obj, List<SnetAddressProperty> properties, byte[] buffer)
		{
			foreach (SnetAddressProperty property in properties)
			{
				Type propertyType = property.PropertyInfo.PropertyType;
				object obj2 = null;
				if (propertyType == typeof(byte))
				{
					obj2 = buffer[property.ByteOffset];
				}
				else if (propertyType == typeof(short))
				{
					obj2 = byteTransform.TransInt16(buffer, property.ByteOffset);
				}
				else if (propertyType == typeof(short[]))
				{
					obj2 = byteTransform.TransInt16(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(ushort))
				{
					obj2 = byteTransform.TransUInt16(buffer, property.ByteOffset);
				}
				else if (propertyType == typeof(ushort[]))
				{
					obj2 = byteTransform.TransUInt16(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(int))
				{
					obj2 = byteTransform.TransInt32(buffer, property.ByteOffset);
				}
				else if (propertyType == typeof(int[]))
				{
					obj2 = byteTransform.TransInt32(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(uint))
				{
					obj2 = byteTransform.TransUInt32(buffer, property.ByteOffset);
				}
				else if (propertyType == typeof(uint[]))
				{
					obj2 = byteTransform.TransUInt32(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(long))
				{
					obj2 = byteTransform.TransInt64(buffer, property.ByteOffset);
				}
				else if (propertyType == typeof(long[]))
				{
					obj2 = byteTransform.TransInt64(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(ulong))
				{
					obj2 = byteTransform.TransUInt64(buffer, property.ByteOffset);
				}
				else if (propertyType == typeof(ulong[]))
				{
					obj2 = byteTransform.TransUInt64(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(float))
				{
					obj2 = byteTransform.TransSingle(buffer, property.ByteOffset);
				}
				else if (propertyType == typeof(float[]))
				{
					obj2 = byteTransform.TransSingle(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(double))
				{
					obj2 = byteTransform.TransDouble(buffer, property.ByteOffset);
				}
				else if (propertyType == typeof(double[]))
				{
					obj2 = byteTransform.TransDouble(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(string))
				{
					obj2 = Encoding.ASCII.GetString(buffer, property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(byte[]))
				{
					obj2 = buffer.SelectMiddle(property.ByteOffset, property.DeviceAddressAttribute.GetDataLength());
				}
				else if (propertyType == typeof(bool))
				{
					obj2 = buffer[property.ByteOffset] != 0;
				}
				else if (propertyType == typeof(bool[]))
				{
					obj2 = (from m in buffer.SelectMiddle(property.ByteOffset, property.DeviceAddressAttribute.GetDataLength())
						select m != 0).ToArray();
				}
				if (obj2 != null)
				{
					property.PropertyInfo.SetValue(obj, obj2, null);
				}
			}
		}
	}
	/// <summary>
	/// 结构体的字节偏移信息定义，用于方法 <see cref="M:Snet.Driver.Core.Device.DeviceCommunication.ReadStruct``1(System.String,System.UInt16)" />读取字节数据并实现解析操作的<br />
	/// The byte offset information of the structure is defined, Method used for <see cref="M:Snet.Driver.Core.Device.DeviceCommunication.ReadStruct``1(System.String,System.UInt16)" /> read byte data and implement the parsing operation
	/// </summary>
	public class SnetStructAttribute : Attribute
	{
		/// <summary>
		/// 字节偏移字节信息，如果是bool，就是位偏移地址，按照位为单位<br />
		/// Byte offset Indicates the byte information. If the value is bool, it is the address of the bit offset. The unit is bits
		/// </summary>
		public int Index { get; set; }

		/// <summary>
		/// 长度信息，如果是普通类型，则表示数组，如果是字符串，则表示字符串占用的最大字节长度<br />
		/// Length information, if a common type, represents an array, if a string, represents the maximum length of bytes taken by the string
		/// </summary>
		public int Length { get; set; }

		/// <summary>
		/// 编码信息，如果是字符串类型，则表示字符串的编码信息，可选 ASCII UNICODE UTF8 GB2312 ANSI BIG-UNICODE<br />
		/// Encoding information. If it is a string, it indicates the encoding information of a string. The option is ASCII UNICODE UTF8 GB2312 ANSI BIG-UNICODE
		/// </summary>
		public string Encoding { get; set; }

		/// <summary>
		/// 字符串的解析模式，0：默认没有字节头 1: 一个头子节，表示长度，2: 两个头子节，最大字符数和实际字符数，3: 两个字节头，实际字符数，4: 四个头字节，最大字符数和实际字符数，5: 四个头字节，字符串实际长度<br />
		/// Parsing mode of the string, 0: default byte header 1: one head section, indicating the length, 2: two head sections, maximum number of characters and actual number of characters, 
		/// 3: two head bytes, actual number of characters, 4: four head bytes, maximum number of characters and actual number of characters, 5: four head bytes, actual length of the string
		/// </summary>
		public int StringMode { get; set; }

		/// <summary>
		/// bool类型的解析模式，0: 默认字节顺序 1: 按字反转之后再解析bool值
		/// </summary>
		public int BoolMode { get; set; }

		/// <summary>
		/// 指定偏移地址来实例化一个对象<br />
		/// Specify an offset address to instantiate an object
		/// </summary>
		/// <param name="index">字节偏移字节信息，如果是bool，就是位偏移地址，按照位为单位</param>
		public SnetStructAttribute(int index)
		{
			Index = index;
		}

		/// <summary>
		/// 指定偏移地址和长度信息来实例化一个对象<br />
		/// Specify offset address and length information to instantiate an object
		/// </summary>
		/// <param name="index">字节偏移字节信息，如果是bool，就是位偏移地址，按照位为单位</param>
		/// <param name="length">长度信息，如果是普通类型，则表示数组，如果是字符串，则表示字符串占用的最大字节长度</param>
		public SnetStructAttribute(int index, int length)
			: this(index)
		{
			Length = length;
		}

		/// <summary>
		/// 指定偏移地址和长度信息，bool解析模式来实例化一个对象<br />
		/// Specify offset address and length information to instantiate an object
		/// </summary>
		/// <param name="index">字节偏移字节信息，如果是bool，就是位偏移地址，按照位为单位</param>
		/// <param name="length">长度信息，如果是普通类型，则表示数组</param>
		/// <param name="boolMode">bool类型解析模式, 0: 默认字节顺序 1: 按字反转之后再解析bool值</param>
		public SnetStructAttribute(int index, int length, int boolMode)
			: this(index, length)
		{
			BoolMode = boolMode;
		}

		/// <summary>
		/// 指定偏移地址，长度信息，编码信息来实例化一个对象，通常应用于字符串数据<br />
		/// Specify offset address, length information, and encoding information to instantiate an object, usually applied to string data
		/// </summary>
		/// <param name="index">字节偏移字节信息，如果是bool，就是位偏移地址，按照位为单位</param>
		/// <param name="length">长度信息，如果是普通类型，则表示数组，如果是字符串，则表示字符串占用的最大字节长度</param>
		/// <param name="encoding">编码信息，如果是字符串类型，则表示字符串的编码信息，可选 ASCII UNICODE UTF8 GB2312 ANSI BIG-UNICODE</param>
		public SnetStructAttribute(int index, int length, string encoding)
			: this(index, length)
		{
			Encoding = encoding;
		}

		/// <summary>
		/// 指定偏移地址，长度信息，编码信息，字符串解析模式来实例化一个对象，通常应用于字符串数据<br />
		/// Specify offset address, length information, encoding information, string parsing mode to instantiate an object, usually applied to string data
		/// </summary>
		/// <param name="index">字节偏移字节信息，如果是bool，就是位偏移地址，按照位为单位</param>
		/// <param name="length">长度信息，如果是普通类型，则表示数组，如果是字符串，则表示字符串占用的最大字节长度</param>
		/// <param name="encoding">编码信息，如果是字符串类型，则表示字符串的编码信息，可选 ASCII UNICODE UTF8 GB2312 ANSI BIG-UNICODE</param>
		/// <param name="mode">字符串的解析模式，0：默认没有字节头 1: 一个头子节，表示长度，2: 两个头子节，最大字符数和实际字符数，3: 两个字节头，实际字符数，4: 四个头字节，字符串实际长度</param>
		public SnetStructAttribute(int index, int length, string encoding, int mode)
			: this(index, length, encoding)
		{
			StringMode = mode;
		}
	}
}
namespace Snet.Driver.Profinet.Yokogawa
{
	/// <summary>
	/// 横河PLC的通信辅助类。
	/// </summary>
	public class YokogawaLinkHelper
	{
		/// <summary>
		/// 获取横河PLC的错误的具体描述信息
		/// </summary>
		/// <param name="code">错误码</param>
		/// <returns>错误的描述信息</returns>
		public static string GetErrorMsg(byte code)
		{
			return code switch
			{
				1 => StringResources.Language.YokogawaLinkError01, 
				2 => StringResources.Language.YokogawaLinkError02, 
				3 => StringResources.Language.YokogawaLinkError03, 
				4 => StringResources.Language.YokogawaLinkError04, 
				5 => StringResources.Language.YokogawaLinkError05, 
				6 => StringResources.Language.YokogawaLinkError06, 
				7 => StringResources.Language.YokogawaLinkError07, 
				8 => StringResources.Language.YokogawaLinkError08, 
				65 => StringResources.Language.YokogawaLinkError41, 
				66 => StringResources.Language.YokogawaLinkError42, 
				67 => StringResources.Language.YokogawaLinkError43, 
				68 => StringResources.Language.YokogawaLinkError44, 
				81 => StringResources.Language.YokogawaLinkError51, 
				82 => StringResources.Language.YokogawaLinkError52, 
				241 => StringResources.Language.YokogawaLinkErrorF1, 
				_ => StringResources.Language.UnknownError, 
			};
		}
	}
	/// <summary>
	/// 横河PLC的虚拟服务器，支持X,Y,I,E,M,T,C,L继电器类型的数据读写，支持D,B,F,R,V,Z,W,TN,CN寄存器类型的数据读写，可以用来测试横河PLC的二进制通信类型<br />
	/// Yokogawa PLC's virtual server, supports X, Y, I, E, M, T, C, L relay type data read and write, 
	/// supports D, B, F, R, V, Z, W, TN, CN register types The data read and write can be used to test the binary communication type of Yokogawa PLC
	/// </summary>
	/// <remarks>
	/// 其中的X继电器可以在服务器进行读写操作，但是远程的PLC只能进行读取，所有的数据读写的最大的范围按照协议进行了限制。
	/// </remarks>
	/// <example>
	/// 你可以很快速并且简单的创建一个虚拟的横河服务器
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\YokogawaLinkServerSample.cs" region="UseExample1" title="简单的创建服务器" />
	/// 当然如果需要高级的服务器，指定日志，限制客户端的IP地址，获取客户端发送的信息，在服务器初始化的时候就要参照下面的代码：
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\YokogawaLinkServerSample.cs" region="UseExample4" title="定制服务器" />
	/// 服务器创建好之后，我们就可以对服务器进行一些读写的操作了，下面的代码是基础的BCL类型的读写操作。
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\YokogawaLinkServerSample.cs" region="ReadWriteExample" title="基础的读写示例" />
	/// 高级的对于byte数组类型的数据进行批量化的读写操作如下：   
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\YokogawaLinkServerSample.cs" region="BytesReadWrite" title="字节的读写示例" />
	/// 更高级操作请参见源代码。
	/// </example>
	public class YokogawaLinkServer : DeviceServer
	{
		private SoftBuffer xBuffer;

		private SoftBuffer yBuffer;

		private SoftBuffer iBuffer;

		private SoftBuffer eBuffer;

		private SoftBuffer mBuffer;

		private SoftBuffer lBuffer;

		private SoftBuffer dBuffer;

		private SoftBuffer bBuffer;

		private SoftBuffer fBuffer;

		private SoftBuffer rBuffer;

		private SoftBuffer vBuffer;

		private SoftBuffer zBuffer;

		private SoftBuffer wBuffer;

		private SoftBuffer specialBuffer;

		private const int DataPoolLength = 65536;

		private IByteTransform transform;

		private bool isProgramStarted;

		/// <summary>
		/// 实例化一个横河PLC的服务器，支持X,Y,I,E,M,T,C,L继电器类型的数据读写，支持D,B,F,R,V,Z,W,TN,CN寄存器类型的数据读写<br />
		/// Instantiate a Yokogawa PLC server, support X, Y, I, E, M, T, C, L relay type data read and write, 
		/// support D, B, F, R, V, Z, W, TN, CN Register type data reading and writing
		/// </summary>
		public YokogawaLinkServer()
		{
			xBuffer = new SoftBuffer(65536);
			yBuffer = new SoftBuffer(65536);
			iBuffer = new SoftBuffer(65536);
			eBuffer = new SoftBuffer(65536);
			mBuffer = new SoftBuffer(65536);
			lBuffer = new SoftBuffer(65536);
			dBuffer = new SoftBuffer(131072);
			bBuffer = new SoftBuffer(131072);
			fBuffer = new SoftBuffer(131072);
			rBuffer = new SoftBuffer(131072);
			vBuffer = new SoftBuffer(131072);
			zBuffer = new SoftBuffer(131072);
			wBuffer = new SoftBuffer(131072);
			specialBuffer = new SoftBuffer(131072);
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
			base.ByteTransform.DataFormat = DataFormat.CDAB;
			transform = new ReverseBytesTransform();
		}

		private OResult<SoftBuffer> GetDataAreaFromYokogawaAddress(YokogawaLinkAddress yokogawaAddress, bool isBit)
		{
			if (isBit)
			{
				return yokogawaAddress.DataCode switch
				{
					24 => OResult.CreateSuccessResult(xBuffer), 
					25 => OResult.CreateSuccessResult(yBuffer), 
					9 => OResult.CreateSuccessResult(iBuffer), 
					5 => OResult.CreateSuccessResult(eBuffer), 
					13 => OResult.CreateSuccessResult(mBuffer), 
					12 => OResult.CreateSuccessResult(lBuffer), 
					_ => new OResult<SoftBuffer>(StringResources.Language.NotSupportedDataType), 
				};
			}
			return yokogawaAddress.DataCode switch
			{
				24 => OResult.CreateSuccessResult(xBuffer), 
				25 => OResult.CreateSuccessResult(yBuffer), 
				9 => OResult.CreateSuccessResult(iBuffer), 
				5 => OResult.CreateSuccessResult(eBuffer), 
				13 => OResult.CreateSuccessResult(mBuffer), 
				12 => OResult.CreateSuccessResult(lBuffer), 
				4 => OResult.CreateSuccessResult(dBuffer), 
				2 => OResult.CreateSuccessResult(bBuffer), 
				6 => OResult.CreateSuccessResult(fBuffer), 
				18 => OResult.CreateSuccessResult(rBuffer), 
				22 => OResult.CreateSuccessResult(vBuffer), 
				26 => OResult.CreateSuccessResult(zBuffer), 
				23 => OResult.CreateSuccessResult(wBuffer), 
				_ => new OResult<SoftBuffer>(StringResources.Language.NotSupportedDataType), 
			};
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Yokogawa.YokogawaLinkTcp.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			if (address.StartsWith("Special:") || address.StartsWith("special:"))
			{
				address = address.Substring(8);
				SnetHelper.ExtractParameter(ref address, "unit");
				SnetHelper.ExtractParameter(ref address, "slot");
				try
				{
					return OResult.CreateSuccessResult(specialBuffer.GetBytes(ushort.Parse(address) * 2, length * 2));
				}
				catch (Exception ex)
				{
					return new OResult<byte[]>("Address format wrong: " + ex.Message);
				}
			}
			OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromYokogawaAddress = GetDataAreaFromYokogawaAddress(oResult.Content, isBit: false);
			if (!dataAreaFromYokogawaAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataAreaFromYokogawaAddress);
			}
			if (oResult.Content.DataCode == 24 || oResult.Content.DataCode == 25 || oResult.Content.DataCode == 9 || oResult.Content.DataCode == 5 || oResult.Content.DataCode == 13 || oResult.Content.DataCode == 12)
			{
				return OResult.CreateSuccessResult((from m in dataAreaFromYokogawaAddress.Content.GetBytes(oResult.Content.AddressStart, length * 16)
					select m != 0).ToArray().ToByteArray());
			}
			return OResult.CreateSuccessResult(dataAreaFromYokogawaAddress.Content.GetBytes(oResult.Content.AddressStart * 2, length * 2));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Yokogawa.YokogawaLinkTcp.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			if (address.StartsWith("Special:") || address.StartsWith("special:"))
			{
				address = address.Substring(8);
				SnetHelper.ExtractParameter(ref address, "unit");
				SnetHelper.ExtractParameter(ref address, "slot");
				try
				{
					specialBuffer.SetBytes(value, ushort.Parse(address) * 2);
					return OResult.CreateSuccessResult();
				}
				catch (Exception ex)
				{
					return new OResult("Address format wrong: " + ex.Message);
				}
			}
			OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromYokogawaAddress = GetDataAreaFromYokogawaAddress(oResult.Content, isBit: false);
			if (!dataAreaFromYokogawaAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataAreaFromYokogawaAddress);
			}
			if (oResult.Content.DataCode == 24 || oResult.Content.DataCode == 25 || oResult.Content.DataCode == 9 || oResult.Content.DataCode == 5 || oResult.Content.DataCode == 13 || oResult.Content.DataCode == 12)
			{
				dataAreaFromYokogawaAddress.Content.SetBytes((from m in value.ToBoolArray()
					select m ? ((byte)1) : ((byte)0)).ToArray(), oResult.Content.AddressStart);
			}
			else
			{
				dataAreaFromYokogawaAddress.Content.SetBytes(value, oResult.Content.AddressStart * 2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Yokogawa.YokogawaLinkTcp.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromYokogawaAddress = GetDataAreaFromYokogawaAddress(oResult.Content, isBit: true);
			if (!dataAreaFromYokogawaAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(dataAreaFromYokogawaAddress);
			}
			return OResult.CreateSuccessResult((from m in dataAreaFromYokogawaAddress.Content.GetBytes(oResult.Content.AddressStart, length)
				select m != 0).ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Yokogawa.YokogawaLinkTcp.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<SoftBuffer> dataAreaFromYokogawaAddress = GetDataAreaFromYokogawaAddress(oResult.Content, isBit: true);
			if (!dataAreaFromYokogawaAddress.IsSuccess)
			{
				return dataAreaFromYokogawaAddress;
			}
			dataAreaFromYokogawaAddress.Content.SetBytes(value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), oResult.Content.AddressStart);
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 如果未执行程序，则开始执行程序<br />
		/// Starts executing a program if it is not being executed
		/// </summary>
		public void StartProgram()
		{
			isProgramStarted = true;
		}

		/// <summary>
		/// 停止当前正在执行程序<br />
		/// Stops the executing program.
		/// </summary>
		public void StopProgram()
		{
			isProgramStarted = false;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new YokogawaLinkBinaryMessage();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			byte[] array = null;
			if (receive[0] == 1)
			{
				array = ReadBoolByCommand(receive);
			}
			else if (receive[0] == 2)
			{
				array = WriteBoolByCommand(receive);
			}
			else if (receive[0] == 4)
			{
				array = ReadRandomBoolByCommand(receive);
			}
			else if (receive[0] == 5)
			{
				array = WriteRandomBoolByCommand(receive);
			}
			else if (receive[0] == 17)
			{
				array = ReadWordByCommand(receive);
			}
			else if (receive[0] == 18)
			{
				array = WriteWordByCommand(receive);
			}
			else if (receive[0] == 20)
			{
				array = ReadRandomWordByCommand(receive);
			}
			else if (receive[0] == 21)
			{
				array = WriteRandomWordByCommand(receive);
			}
			else if (receive[0] == 49)
			{
				array = ReadSpecialModule(receive);
			}
			else if (receive[0] == 50)
			{
				array = WriteSpecialModule(receive);
			}
			else if (receive[0] == 69)
			{
				array = StartByCommand(receive);
			}
			else if (receive[0] == 70)
			{
				array = StopByCommand(receive);
			}
			else
			{
				if (receive[0] == 97)
				{
					throw new RemoteCloseException();
				}
				array = ((receive[0] == 98) ? ReadSystemByCommand(receive) : ((receive[0] != 99) ? PackCommandBack(receive[0], 3, null) : ReadSystemDateTime(receive)));
			}
			return OResult.CreateSuccessResult(array);
		}

		private byte[] ReadBoolByCommand(byte[] command)
		{
			int num = transform.TransInt32(command, 6);
			int num2 = transform.TransUInt16(command, 10);
			if (num > 65535 || num < 0)
			{
				return PackCommandBack(command[0], 4, null);
			}
			if (num2 > 256)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num + num2 > 65535)
			{
				return PackCommandBack(command[0], 5, null);
			}
			return command[5] switch
			{
				24 => PackCommandBack(command[0], 0, xBuffer.GetBytes(num, num2)), 
				25 => PackCommandBack(command[0], 0, yBuffer.GetBytes(num, num2)), 
				9 => PackCommandBack(command[0], 0, iBuffer.GetBytes(num, num2)), 
				5 => PackCommandBack(command[0], 0, eBuffer.GetBytes(num, num2)), 
				13 => PackCommandBack(command[0], 0, mBuffer.GetBytes(num, num2)), 
				12 => PackCommandBack(command[0], 0, lBuffer.GetBytes(num, num2)), 
				_ => PackCommandBack(command[0], 3, null), 
			};
		}

		private byte[] WriteBoolByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandBack(command[0], 3, null);
			}
			int num = transform.TransInt32(command, 6);
			int num2 = transform.TransUInt16(command, 10);
			if (num > 65535 || num < 0)
			{
				return PackCommandBack(command[0], 4, null);
			}
			if (num2 > 256)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num + num2 > 65535)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num2 != command.Length - 12)
			{
				return PackCommandBack(command[0], 5, null);
			}
			switch (command[5])
			{
			case 24:
				return PackCommandBack(command[0], 3, null);
			case 25:
				yBuffer.SetBytes(command.RemoveBegin(12), num);
				return PackCommandBack(command[0], 0, null);
			case 9:
				iBuffer.SetBytes(command.RemoveBegin(12), num);
				return PackCommandBack(command[0], 0, null);
			case 5:
				eBuffer.SetBytes(command.RemoveBegin(12), num);
				return PackCommandBack(command[0], 0, null);
			case 13:
				mBuffer.SetBytes(command.RemoveBegin(12), num);
				return PackCommandBack(command[0], 0, null);
			case 12:
				lBuffer.SetBytes(command.RemoveBegin(12), num);
				return PackCommandBack(command[0], 0, null);
			default:
				return PackCommandBack(command[0], 3, null);
			}
		}

		private byte[] ReadRandomBoolByCommand(byte[] command)
		{
			int num = transform.TransUInt16(command, 4);
			if (num > 32)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num * 6 != command.Length - 6)
			{
				return PackCommandBack(command[0], 5, null);
			}
			byte[] array = new byte[num];
			for (int i = 0; i < num; i++)
			{
				int num2 = transform.TransInt32(command, 8 + 6 * i);
				if (num2 > 65535 || num2 < 0)
				{
					return PackCommandBack(command[0], 4, null);
				}
				switch (command[7 + i * 6])
				{
				case 24:
					array[i] = xBuffer.GetBytes(num2, 1)[0];
					break;
				case 25:
					array[i] = yBuffer.GetBytes(num2, 1)[0];
					break;
				case 9:
					array[i] = iBuffer.GetBytes(num2, 1)[0];
					break;
				case 5:
					array[i] = eBuffer.GetBytes(num2, 1)[0];
					break;
				case 13:
					array[i] = mBuffer.GetBytes(num2, 1)[0];
					break;
				case 12:
					array[i] = lBuffer.GetBytes(num2, 1)[0];
					break;
				default:
					return PackCommandBack(command[0], 3, null);
				}
			}
			return PackCommandBack(command[0], 0, array);
		}

		private byte[] WriteRandomBoolByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandBack(command[0], 3, null);
			}
			int num = transform.TransUInt16(command, 4);
			if (num > 32)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num * 8 - 1 != command.Length - 6)
			{
				return PackCommandBack(command[0], 5, null);
			}
			for (int i = 0; i < num; i++)
			{
				int num2 = transform.TransInt32(command, 8 + 8 * i);
				if (num2 > 65535 || num2 < 0)
				{
					return PackCommandBack(command[0], 4, null);
				}
				switch (command[7 + i * 8])
				{
				case 24:
					return PackCommandBack(command[0], 3, null);
				case 25:
					yBuffer.SetValue(command[12 + 8 * i], num2);
					break;
				case 9:
					iBuffer.SetValue(command[12 + 8 * i], num2);
					break;
				case 5:
					eBuffer.SetValue(command[12 + 8 * i], num2);
					break;
				case 13:
					mBuffer.SetValue(command[12 + 8 * i], num2);
					break;
				case 12:
					lBuffer.SetValue(command[12 + 8 * i], num2);
					break;
				default:
					return PackCommandBack(command[0], 3, null);
				}
			}
			return PackCommandBack(command[0], 0, null);
		}

		private byte[] ReadWordByCommand(byte[] command)
		{
			int num = transform.TransInt32(command, 6);
			int num2 = transform.TransUInt16(command, 10);
			if (num > 65535 || num < 0)
			{
				return PackCommandBack(command[0], 4, null);
			}
			if (num2 > 64)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num + num2 > 65535)
			{
				return PackCommandBack(command[0], 5, null);
			}
			return command[5] switch
			{
				24 => PackCommandBack(command[0], 0, (from m in xBuffer.GetBytes(num, num2 * 16)
					select m != 0).ToArray().ToByteArray()), 
				25 => PackCommandBack(command[0], 0, (from m in yBuffer.GetBytes(num, num2 * 16)
					select m != 0).ToArray().ToByteArray()), 
				9 => PackCommandBack(command[0], 0, (from m in iBuffer.GetBytes(num, num2 * 16)
					select m != 0).ToArray().ToByteArray()), 
				5 => PackCommandBack(command[0], 0, (from m in eBuffer.GetBytes(num, num2 * 16)
					select m != 0).ToArray().ToByteArray()), 
				13 => PackCommandBack(command[0], 0, (from m in mBuffer.GetBytes(num, num2 * 16)
					select m != 0).ToArray().ToByteArray()), 
				12 => PackCommandBack(command[0], 0, (from m in lBuffer.GetBytes(num, num2 * 16)
					select m != 0).ToArray().ToByteArray()), 
				4 => PackCommandBack(command[0], 0, dBuffer.GetBytes(num * 2, num2 * 2)), 
				2 => PackCommandBack(command[0], 0, bBuffer.GetBytes(num * 2, num2 * 2)), 
				6 => PackCommandBack(command[0], 0, fBuffer.GetBytes(num * 2, num2 * 2)), 
				18 => PackCommandBack(command[0], 0, rBuffer.GetBytes(num * 2, num2 * 2)), 
				22 => PackCommandBack(command[0], 0, vBuffer.GetBytes(num * 2, num2 * 2)), 
				26 => PackCommandBack(command[0], 0, zBuffer.GetBytes(num * 2, num2 * 2)), 
				23 => PackCommandBack(command[0], 0, wBuffer.GetBytes(num * 2, num2 * 2)), 
				_ => PackCommandBack(command[0], 3, null), 
			};
		}

		private byte[] WriteWordByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandBack(command[0], 3, null);
			}
			int num = transform.TransInt32(command, 6);
			int num2 = transform.TransUInt16(command, 10);
			if (num > 65535 || num < 0)
			{
				return PackCommandBack(command[0], 4, null);
			}
			if (num2 > 64)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num + num2 > 65535)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num2 * 2 != command.Length - 12)
			{
				return PackCommandBack(command[0], 5, null);
			}
			switch (command[5])
			{
			case 24:
				return PackCommandBack(command[0], 3, null);
			case 25:
				yBuffer.SetBytes((from m in command.RemoveBegin(12).ToBoolArray()
					select m ? ((byte)1) : ((byte)0)).ToArray(), num);
				return PackCommandBack(command[0], 0, null);
			case 9:
				iBuffer.SetBytes((from m in command.RemoveBegin(12).ToBoolArray()
					select m ? ((byte)1) : ((byte)0)).ToArray(), num);
				return PackCommandBack(command[0], 0, null);
			case 5:
				eBuffer.SetBytes((from m in command.RemoveBegin(12).ToBoolArray()
					select m ? ((byte)1) : ((byte)0)).ToArray(), num);
				return PackCommandBack(command[0], 0, null);
			case 13:
				mBuffer.SetBytes((from m in command.RemoveBegin(12).ToBoolArray()
					select m ? ((byte)1) : ((byte)0)).ToArray(), num);
				return PackCommandBack(command[0], 0, null);
			case 12:
				lBuffer.SetBytes((from m in command.RemoveBegin(12).ToBoolArray()
					select m ? ((byte)1) : ((byte)0)).ToArray(), num);
				return PackCommandBack(command[0], 0, null);
			case 4:
				dBuffer.SetBytes(command.RemoveBegin(12), num * 2);
				return PackCommandBack(command[0], 0, null);
			case 2:
				bBuffer.SetBytes(command.RemoveBegin(12), num * 2);
				return PackCommandBack(command[0], 0, null);
			case 6:
				fBuffer.SetBytes(command.RemoveBegin(12), num * 2);
				return PackCommandBack(command[0], 0, null);
			case 18:
				rBuffer.SetBytes(command.RemoveBegin(12), num * 2);
				return PackCommandBack(command[0], 0, null);
			case 22:
				vBuffer.SetBytes(command.RemoveBegin(12), num * 2);
				return PackCommandBack(command[0], 0, null);
			case 26:
				zBuffer.SetBytes(command.RemoveBegin(12), num * 2);
				return PackCommandBack(command[0], 0, null);
			case 23:
				wBuffer.SetBytes(command.RemoveBegin(12), num * 2);
				return PackCommandBack(command[0], 0, null);
			default:
				return PackCommandBack(command[0], 3, null);
			}
		}

		private byte[] ReadRandomWordByCommand(byte[] command)
		{
			int num = transform.TransUInt16(command, 4);
			if (num > 32)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num * 6 != command.Length - 6)
			{
				return PackCommandBack(command[0], 5, null);
			}
			byte[] array = new byte[num * 2];
			for (int i = 0; i < num; i++)
			{
				int num2 = transform.TransInt32(command, 8 + 6 * i);
				if (num2 > 65535 || num2 < 0)
				{
					return PackCommandBack(command[0], 4, null);
				}
				switch (command[7 + i * 6])
				{
				case 24:
					(from m in xBuffer.GetBytes(num2, 16)
						select m != 0).ToArray().ToByteArray().CopyTo(array, i * 2);
					break;
				case 25:
					(from m in yBuffer.GetBytes(num2, 16)
						select m != 0).ToArray().ToByteArray().CopyTo(array, i * 2);
					break;
				case 9:
					(from m in iBuffer.GetBytes(num2, 16)
						select m != 0).ToArray().ToByteArray().CopyTo(array, i * 2);
					break;
				case 5:
					(from m in eBuffer.GetBytes(num2, 16)
						select m != 0).ToArray().ToByteArray().CopyTo(array, i * 2);
					break;
				case 13:
					(from m in mBuffer.GetBytes(num2, 16)
						select m != 0).ToArray().ToByteArray().CopyTo(array, i * 2);
					break;
				case 12:
					(from m in lBuffer.GetBytes(num2, 16)
						select m != 0).ToArray().ToByteArray().CopyTo(array, i * 2);
					break;
				case 4:
					dBuffer.GetBytes(num2 * 2, 2).CopyTo(array, i * 2);
					break;
				case 2:
					bBuffer.GetBytes(num2 * 2, 2).CopyTo(array, i * 2);
					break;
				case 6:
					fBuffer.GetBytes(num2 * 2, 2).CopyTo(array, i * 2);
					break;
				case 18:
					rBuffer.GetBytes(num2 * 2, 2).CopyTo(array, i * 2);
					break;
				case 22:
					vBuffer.GetBytes(num2 * 2, 2).CopyTo(array, i * 2);
					break;
				case 26:
					zBuffer.GetBytes(num2 * 2, 2).CopyTo(array, i * 2);
					break;
				case 23:
					wBuffer.GetBytes(num2 * 2, 2).CopyTo(array, i * 2);
					break;
				default:
					return PackCommandBack(command[0], 3, null);
				}
			}
			return PackCommandBack(command[0], 0, array);
		}

		private byte[] WriteRandomWordByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandBack(command[0], 3, null);
			}
			int num = transform.TransUInt16(command, 4);
			if (num > 32)
			{
				return PackCommandBack(command[0], 5, null);
			}
			if (num * 8 != command.Length - 6)
			{
				return PackCommandBack(command[0], 5, null);
			}
			for (int i = 0; i < num; i++)
			{
				int num2 = transform.TransInt32(command, 8 + 8 * i);
				if (num2 > 65535 || num2 < 0)
				{
					return PackCommandBack(command[0], 4, null);
				}
				switch (command[7 + i * 8])
				{
				case 24:
					return PackCommandBack(command[0], 3, null);
				case 25:
					yBuffer.SetBytes((from m in command.SelectMiddle(12 + 8 * i, 2).ToBoolArray()
						select m ? ((byte)1) : ((byte)0)).ToArray(), num2);
					break;
				case 9:
					iBuffer.SetBytes((from m in command.SelectMiddle(12 + 8 * i, 2).ToBoolArray()
						select m ? ((byte)1) : ((byte)0)).ToArray(), num2);
					break;
				case 5:
					eBuffer.SetBytes((from m in command.SelectMiddle(12 + 8 * i, 2).ToBoolArray()
						select m ? ((byte)1) : ((byte)0)).ToArray(), num2);
					break;
				case 13:
					mBuffer.SetBytes((from m in command.SelectMiddle(12 + 8 * i, 2).ToBoolArray()
						select m ? ((byte)1) : ((byte)0)).ToArray(), num2);
					break;
				case 12:
					lBuffer.SetBytes((from m in command.SelectMiddle(12 + 8 * i, 2).ToBoolArray()
						select m ? ((byte)1) : ((byte)0)).ToArray(), num2);
					break;
				case 4:
					dBuffer.SetBytes(command.SelectMiddle(12 + 8 * i, 2), num2 * 2);
					break;
				case 2:
					bBuffer.SetBytes(command.SelectMiddle(12 + 8 * i, 2), num2 * 2);
					break;
				case 6:
					fBuffer.SetBytes(command.SelectMiddle(12 + 8 * i, 2), num2 * 2);
					break;
				case 18:
					rBuffer.SetBytes(command.SelectMiddle(12 + 8 * i, 2), num2 * 2);
					break;
				case 22:
					vBuffer.SetBytes(command.SelectMiddle(12 + 8 * i, 2), num2 * 2);
					break;
				case 26:
					zBuffer.SetBytes(command.SelectMiddle(12 + 8 * i, 2), num2 * 2);
					break;
				case 23:
					wBuffer.SetBytes(command.SelectMiddle(12 + 8 * i, 2), num2 * 2);
					break;
				default:
					return PackCommandBack(command[0], 3, null);
				}
			}
			return PackCommandBack(command[0], 0, null);
		}

		private byte[] StartByCommand(byte[] command)
		{
			isProgramStarted = true;
			return PackCommandBack(command[0], 0, null);
		}

		private byte[] StopByCommand(byte[] command)
		{
			isProgramStarted = false;
			return PackCommandBack(command[0], 0, null);
		}

		private byte[] ReadSystemByCommand(byte[] command)
		{
			if (command[5] == 1)
			{
				return PackCommandBack(result: new byte[2]
				{
					0,
					(byte)(isProgramStarted ? 1u : 2u)
				}, cmd: command[0], err: 0);
			}
			if (command[5] == 2)
			{
				byte[] array = new byte[28];
				Encoding.ASCII.GetBytes("F3SP38-6N").CopyTo(array, 0);
				Encoding.ASCII.GetBytes("12345").CopyTo(array, 16);
				array[25] = 17;
				array[26] = 2;
				array[27] = 3;
				return PackCommandBack(command[0], 0, array);
			}
			return PackCommandBack(command[0], 3, null);
		}

		private byte[] ReadSystemDateTime(byte[] command)
		{
			byte[] array = new byte[16];
			DateTime now = DateTime.Now;
			array[0] = BitConverter.GetBytes(now.Year - 2000)[1];
			array[1] = BitConverter.GetBytes(now.Year - 2000)[0];
			array[2] = BitConverter.GetBytes(now.Month)[1];
			array[3] = BitConverter.GetBytes(now.Month)[0];
			array[4] = BitConverter.GetBytes(now.Day)[1];
			array[5] = BitConverter.GetBytes(now.Day)[0];
			array[6] = BitConverter.GetBytes(now.Hour)[1];
			array[7] = BitConverter.GetBytes(now.Hour)[0];
			array[8] = BitConverter.GetBytes(now.Minute)[1];
			array[9] = BitConverter.GetBytes(now.Minute)[0];
			array[10] = BitConverter.GetBytes(now.Second)[1];
			array[11] = BitConverter.GetBytes(now.Second)[0];
			uint value = (uint)(now - new DateTime(now.Year, 1, 1)).TotalSeconds;
			array[12] = BitConverter.GetBytes(value)[3];
			array[13] = BitConverter.GetBytes(value)[2];
			array[14] = BitConverter.GetBytes(value)[1];
			array[15] = BitConverter.GetBytes(value)[0];
			return PackCommandBack(command[0], 0, array);
		}

		private byte[] ReadSpecialModule(byte[] command)
		{
			if (command[4] != 0 || command[5] != 1)
			{
				return PackCommandBack(command[0], 3, null);
			}
			ushort num = transform.TransUInt16(command, 6);
			ushort num2 = transform.TransUInt16(command, 8);
			return PackCommandBack(command[0], 0, specialBuffer.GetBytes(num * 2, num2 * 2));
		}

		private byte[] WriteSpecialModule(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandBack(command[0], 3, null);
			}
			if (command[4] != 0 || command[5] != 1)
			{
				return PackCommandBack(command[0], 3, null);
			}
			ushort num = transform.TransUInt16(command, 6);
			if (transform.TransUInt16(command, 8) * 2 != command.Length - 10)
			{
				return PackCommandBack(command[0], 5, null);
			}
			specialBuffer.SetBytes(command.RemoveBegin(10), num * 2);
			return PackCommandBack(command[0], 0, null);
		}

		private byte[] PackCommandBack(byte cmd, byte err, byte[] result)
		{
			if (result == null)
			{
				result = new byte[0];
			}
			byte[] array = new byte[4 + result.Length];
			array[0] = (byte)(cmd + 128);
			array[1] = err;
			array[2] = BitConverter.GetBytes(result.Length)[1];
			array[3] = BitConverter.GetBytes(result.Length)[0];
			result.CopyTo(array, 4);
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 1310720)
			{
				throw new Exception("File is not correct");
			}
			xBuffer.SetBytes(content, 0, 0, 65536);
			yBuffer.SetBytes(content, 65536, 0, 65536);
			iBuffer.SetBytes(content, 131072, 0, 65536);
			eBuffer.SetBytes(content, 196608, 0, 65536);
			mBuffer.SetBytes(content, 262144, 0, 65536);
			lBuffer.SetBytes(content, 327680, 0, 65536);
			dBuffer.SetBytes(content, 393216, 0, 65536);
			bBuffer.SetBytes(content, 524288, 0, 65536);
			fBuffer.SetBytes(content, 655360, 0, 65536);
			rBuffer.SetBytes(content, 786432, 0, 65536);
			vBuffer.SetBytes(content, 917504, 0, 65536);
			zBuffer.SetBytes(content, 1048576, 0, 65536);
			wBuffer.SetBytes(content, 1179648, 0, 65536);
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[1310720];
			Array.Copy(xBuffer.GetBytes(), 0, array, 0, 65536);
			Array.Copy(yBuffer.GetBytes(), 0, array, 65536, 65536);
			Array.Copy(iBuffer.GetBytes(), 0, array, 131072, 65536);
			Array.Copy(eBuffer.GetBytes(), 0, array, 196608, 65536);
			Array.Copy(mBuffer.GetBytes(), 0, array, 262144, 65536);
			Array.Copy(lBuffer.GetBytes(), 0, array, 327680, 65536);
			Array.Copy(dBuffer.GetBytes(), 0, array, 393216, 65536);
			Array.Copy(bBuffer.GetBytes(), 0, array, 524288, 65536);
			Array.Copy(fBuffer.GetBytes(), 0, array, 655360, 65536);
			Array.Copy(rBuffer.GetBytes(), 0, array, 786432, 65536);
			Array.Copy(vBuffer.GetBytes(), 0, array, 917504, 65536);
			Array.Copy(zBuffer.GetBytes(), 0, array, 1048576, 65536);
			Array.Copy(wBuffer.GetBytes(), 0, array, 1179648, 65536);
			return array;
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				xBuffer?.Dispose();
				yBuffer?.Dispose();
				iBuffer?.Dispose();
				eBuffer?.Dispose();
				mBuffer?.Dispose();
				lBuffer?.Dispose();
				dBuffer?.Dispose();
				bBuffer?.Dispose();
				fBuffer?.Dispose();
				rBuffer?.Dispose();
				vBuffer?.Dispose();
				zBuffer?.Dispose();
				wBuffer?.Dispose();
				specialBuffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"YokogawaLinkServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 横河PLC的二进制通信类，支持X,Y,I,E,M,T,C,L继电器类型的数据读写，支持D,B,F,R,V,Z,W,TN,CN寄存器类型的数据读写，还支持一些高级的信息读写接口，详细参考Demo界面。<br />
	/// Yokogawa PLC's binary communication type, supports X, Y, I, E, M, T, C, L relay type data read and write, 
	/// supports D, B, F, R, V, Z, W, TN, CN registers Types of data reading and writing, and some advanced information reading and writing interfaces are also supported. 
	/// Please refer to the Demo UI.
	/// </summary>
	/// <remarks>
	/// 基础的数据读写面向VIP用户开放，高级的读写随机数据，启动停止命令，读取程序状态，
	/// 系统信息，PLC时间，读写特殊的模块数据需要商业用户授权，读取的数据长度，读取的随机地址长度，在商业授权下，长度不受限制，可以无限大。
	/// </remarks>
	/// <example>
	/// 例如我们正常读取一个D100的数据如下：
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\YokogawaLinkTcpSample.cs" region="Sample1" title="Read示例" />
	/// 我们在读取的时候可以动态的变更cpu信息，参考下面的代码
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\YokogawaLinkTcpSample.cs" region="Sample2" title="Read示例" />
	/// 关于随机读写的代码示例，可以读写地址分布很散的地址，参考下面的代码
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\YokogawaLinkTcpSample.cs" region="Sample3" title="Read示例" />
	/// 最后看一下读取特殊模块的数据，可以读取基本的字节数据，也可以使用富文本的地址读取
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\YokogawaLinkTcpSample.cs" region="Sample4" title="Read示例" />
	/// </example>
	public class YokogawaLinkTcp : DeviceTcpNet
	{
		/// <summary>
		/// 获取或设置当前的CPU Number，默认值为1<br />
		/// Get or set the current CPU Number, the default value is 1
		/// </summary>
		public byte CpuNumber { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public YokogawaLinkTcp()
		{
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
			CpuNumber = 1;
		}

		/// <summary>
		/// 指定IP地址和端口号来实例化一个对象<br />
		/// Specify the IP address and port number to instantiate an object
		/// </summary>
		/// <param name="ipAddress">Ip地址</param>
		/// <param name="port">端口号</param>
		public YokogawaLinkTcp(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new YokogawaLinkBinaryMessage();
		}

		/// <inheritdoc />
		/// <remarks>
		/// 读取的线圈地址支持X,Y,I,E,M,T,C,L，寄存器地址支持D,B,F,R,V,Z,W,TN,CN，举例：D100；也可以携带CPU进行访问，举例：cpu=2;D100<br />
		/// 如果想要读取特殊模块的数据，需要使用 <b>Special:</b> 开头标记，举例：Special:unit=0;slot=1;100<br />
		/// The read coil address supports X, Y, I, E, M, T, C, L, and the register address supports D, B, F, R, V, Z, W, TN, CN, for example: D100; 
		/// it can also be carried CPU access, for example: cpu=2;D100. <br />
		/// If you want to read the data of a special module, you need to use the <b>Special:</b> beginning tag, for example: Special:unit=0;slot=1;100
		/// </remarks>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = ((!address.StartsWith("Special:") && !address.StartsWith("special:")) ? BuildReadCommand(CpuNumber, address, length, isBit: false) : BuildReadSpecialModule(CpuNumber, address, length));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult<byte[]> oResult3 = CheckContent(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				list.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc />
		/// <remarks>
		/// 写入的线圈地址支持Y,I,E,M,T,C,L，寄存器地址支持D,B,F,R,V,Z,W,TN,CN，举例：D100；也可以携带CPU进行访问，举例：cpu=2;D100<br />
		/// 如果想要写入特殊模块的数据，需要使用 <b>Special:</b> 开头标记，举例：Special:unit=0;slot=1;100<br />
		/// The read coil address supports Y, I, E, M, T, C, L, and the register address supports D, B, F, R, V, Z, W, TN, CN, for example: D100; 
		/// it can also be carried CPU access, for example: cpu=2;D100.
		/// If you want to read the data of a special module, you need to use the <b>Special:</b> beginning tag, for example: Special:unit=0;slot=1;100
		/// </remarks>
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = ((!address.StartsWith("Special:") && !address.StartsWith("special:")) ? BuildWriteWordCommand(CpuNumber, address, value) : BuildWriteSpecialModule(CpuNumber, address, value));
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return CheckContent(oResult2.Content);
		}

		/// <inheritdoc />
		/// <remarks>
		/// 读取的线圈地址支持X,Y,I,E,M,T,C,L，举例：Y100；也可以携带CPU进行访问，举例：cpu=2;Y100<br />
		/// The read coil address supports X, Y, I, E, M, T, C, L, for example: Y100; you can also carry the CPU for access, for example: cpu=2;Y100
		/// </remarks>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadCommand(CpuNumber, address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult<byte[]> oResult3 = CheckContent(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				list.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult((from m in list.ToArray()
				select m != 0).ToArray());
		}

		/// <inheritdoc />
		/// <remarks>
		/// 写入的线圈地址支持Y,I,E,M,T,C,L，举例：Y100；也可以携带CPU进行访问，举例：cpu=2;Y100<br />
		/// The write coil address supports Y, I, E, M, T, C, L, for example: Y100; you can also carry the CPU for access, for example: cpu=2;Y100
		/// </remarks>
		public override OResult Write(string address, bool[] value)
		{
			OResult<byte[]> oResult = BuildWriteBoolCommand(CpuNumber, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return CheckContent(oResult2.Content);
		}

		/// <summary>
		/// 随机读取<see cref="T:System.Boolean" />数组信息，主需要出传入<see cref="T:System.String" />数组地址信息，就可以返回批量<see cref="T:System.Boolean" />值<br />
		/// Random read <see cref="T:System.Boolean" /> array information, the master needs to pass in the <see cref="T:System.String" /> array address information, and then the batch can be returned to <see cref="T:System.Boolean" /> value
		/// </summary> 
		/// <param name="address">批量地址信息</param>
		/// <remarks>
		/// 读取的线圈地址支持X,Y,I,E,M,T,C,L，举例：Y100；也可以携带CPU进行访问，举例：cpu=2;Y100<br />
		/// The read coil address supports X, Y, I, E, M, T, C, L, for example: Y100; you can also carry the CPU for access, for example: cpu=2;Y100
		/// </remarks>
		/// <returns>带有成功标志的Bool数组信息</returns>
		public OResult<bool[]> ReadRandomBool(string[] address)
		{
			OResult<List<byte[]>> oResult = BuildReadRandomCommand(CpuNumber, address, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<bool> list = new List<bool>();
			foreach (byte[] item in oResult.Content)
			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(item);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult<byte[]> oResult3 = CheckContent(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				list.AddRange(oResult3.Content.Select((byte m) => m != 0));
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <summary>
		/// 随机写入<see cref="T:System.Boolean" />数组信息，主需要出传入<see cref="T:System.String" />数组地址信息，以及对应的<see cref="T:System.Boolean" />数组值<br />
		/// Randomly write the <see cref="T:System.Boolean" /> array information, the main need to pass in the <see cref="T:System.String" /> array address information, 
		/// and the corresponding <see cref="T:System.Boolean" /> array value
		/// </summary>
		/// <param name="address">批量地址信息</param>
		/// <param name="value">批量的数据值信息</param>
		/// <remarks>
		/// 写入的线圈地址支持Y,I,E,M,T,C,L，举例：Y100；也可以携带CPU进行访问，举例：cpu=2;Y100<br />
		/// The write coil address supports Y, I, E, M, T, C, L, for example: Y100; you can also carry the CPU for access, for example: cpu=2;Y100
		/// </remarks>
		/// <returns>是否写入成功</returns>
