		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<List<byte[]>> command = ((!address.StartsWith("Special:") && !address.StartsWith("special:")) ? BuildReadCommand(CpuNumber, address, length, isBit: false) : BuildReadSpecialModule(CpuNumber, address, length));
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(command);
			}
			List<byte> content = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = CheckContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				content.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(content.ToArray());
		}

