		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			OResult<List<byte[]>> command = BuildReadCommand(CpuNumber, address, length, isBit: true);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(command);
			}
			List<byte> content = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				OResult<byte[]> oResult2 = CheckContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				content.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult((from m in content.ToArray()
				select m != 0).ToArray());
		}

