		/// <summary>
		/// 重置当前的模块，当前打开的连接被强制关闭。 模块中所做的设置也将被清除。然后当前对象需要重连PLC。<br />
		/// When this command is executed via an Ethernet interface module or an Ethernet connection of an F3SP66, F3SP67, 
		/// F3SP71 or F3SP76 sequence CPU module, the connection which is currently open is forced to close. 
		/// The settings made in the modules are also cleared. Then the current object needs to reconnect to the PLC.
		/// </summary>
		/// <returns>是否重置成功</returns>
		public OResult ModuleReset()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(new byte[4] { 97, CpuNumber, 0, 0 }, hasResponseData: false, usePackAndUnpack: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 读取当前PLC的程序状态，返回1：RUN；2：Stop；3：Debug；255：ROM writer<br />
		/// Read the program status. return code 1:RUN; 2:Stop; 3:Debug; 255:ROM writer
		/// </summary>
		/// <returns>当前PLC的程序状态，返回1：RUN；2：Stop；3：Debug；255：ROM writer</returns>
		public OResult<int> ReadProgramStatus()
		{
			byte[] array = new byte[6] { 98, 0, 0, 2, 0, 1 };
			array[1] = CpuNumber;
			OResult<byte[]> oResult = ReadFromCoreServer(array);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int>(oResult);
			}
			OResult<byte[]> oResult2 = CheckContent(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<int>(oResult2);
			}
			return OResult.CreateSuccessResult((int)oResult2.Content[1]);
		}

