		/// <summary>
		/// 读取当前PLC的时间信息，包含年月日时分秒<br />
		/// Read current PLC time information, including year, month, day, hour, minute, and second
		/// </summary>
		/// <returns>PLC的当前的时间信息</returns>
		public OResult<DateTime> ReadDateTime()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(new byte[4] { 99, CpuNumber, 0, 0 });
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<DateTime>(oResult);
			}
			OResult<byte[]> oResult2 = CheckContent(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<DateTime>(oResult2);
