			return OResult.CreateSuccessResult(new DateTime(2000 + base.ByteTransform.TransUInt16(oResult2.Content, 0), base.ByteTransform.TransUInt16(oResult2.Content, 2), base.ByteTransform.TransUInt16(oResult2.Content, 4), base.ByteTransform.TransUInt16(oResult2.Content, 6), base.ByteTransform.TransUInt16(oResult2.Content, 8), base.ByteTransform.TransUInt16(oResult2.Content, 10)));
		}

		/// <summary>
		/// 读取特殊模块的数据信息，需要指定模块单元号，模块站号，数据地址，长度信息。<br />
		/// To read the data information of a special module, you need to specify the module unit number, module slot number, data address, and length information.
		/// </summary>
		/// <param name="moduleUnit">模块的单元号</param>
		/// <param name="moduleSlot">模块的站号</param>
		/// <param name="dataPosition">模块的数据地址</param>
		/// <param name="length">长度信息</param>
		/// <returns>带有成功标识的byte[]，可以自行解析出所需要的各种类型的数据</returns>
		public OResult<byte[]> ReadSpecialModule(byte moduleUnit, byte moduleSlot, ushort dataPosition, ushort length)
		{
			List<byte> list = new List<byte>();
			List<byte[]> list2 = BuildReadSpecialModule(CpuNumber, moduleUnit, moduleSlot, dataPosition, length);
			for (int i = 0; i < list2.Count; i++)
			{
				OResult<byte[]> oResult = ReadFromCoreServer(list2[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				OResult<byte[]> oResult2 = CheckContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				list.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

