			}
			OResult<byte[]> oResult3 = CheckContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Yokogawa.YokogawaLinkTcp.Stop" />
		public async Task<OResult> StopAsync()
		{
			OResult<byte[]> oResult = BuildStopCommand(CpuNumber);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = CheckContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult();
		}

