		/// <inheritdoc cref="M:Snet.Driver.Profinet.Yokogawa.YokogawaLinkTcp.ReadDateTime" />
		public async Task<OResult<DateTime>> ReadDateTimeAsync()
		{
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(new byte[4] { 99, CpuNumber, 0, 0 });
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<DateTime>(oResult);
			}
			OResult<byte[]> oResult2 = CheckContent(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<DateTime>(oResult2);
			}
			return OResult.CreateSuccessResult(new DateTime(2000 + base.ByteTransform.TransUInt16(oResult2.Content, 0), base.ByteTransform.TransUInt16(oResult2.Content, 2), base.ByteTransform.TransUInt16(oResult2.Content, 4), base.ByteTransform.TransUInt16(oResult2.Content, 6), base.ByteTransform.TransUInt16(oResult2.Content, 8), base.ByteTransform.TransUInt16(oResult2.Content, 10)));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Yokogawa.YokogawaLinkTcp.ReadSpecialModule(System.Byte,System.Byte,System.UInt16,System.UInt16)" />
		public async Task<OResult<byte[]>> ReadSpecialModuleAsync(byte moduleUnit, byte moduleSlot, ushort dataPosition, ushort length)
		{
			List<byte> content = new List<byte>();
			List<byte[]> commands = BuildReadSpecialModule(CpuNumber, moduleUnit, moduleSlot, dataPosition, length);
			for (int i = 0; i < commands.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(commands[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				OResult<byte[]> oResult2 = CheckContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				content.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(content.ToArray());
		}

		/// <summary>
		/// 检查当前的反馈内容，如果没有发生错误，就解析出实际的数据内容。<br />
		/// Check the current feedback content, if there is no error, parse out the actual data content.
		/// </summary>
		/// <param name="content">原始的数据内容</param>
		/// <returns>解析之后的数据内容</returns>
		public static OResult<byte[]> CheckContent(byte[] content)
		{
			if (content == null || content.Length < 2)
			{
				return new OResult<byte[]>(StringResources.Language.ReceiveDataLengthTooShort + " 2 content: " + content.ToHexString(' '));
			}
			if (content[1] != 0)
			{
				return new OResult<byte[]>(YokogawaLinkHelper.GetErrorMsg(content[1]));
			}
			if (content.Length > 4)
			{
				return OResult.CreateSuccessResult(content.RemoveBegin(4));
			}
			return OResult.CreateSuccessResult(new byte[0]);
		}

		/// <summary>
		/// 构建读取命令的原始报文信息
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="address">地址数据信息</param>
		/// <param name="length">数据长度信息</param>
		/// <param name="isBit">是否位访问</param>
		/// <returns>实际的读取的报文信息</returns>
		public static OResult<List<byte[]>> BuildReadCommand(byte cpu, string address, ushort length, bool isBit)
		{
			cpu = (byte)SnetHelper.ExtractParameter(ref address, "cpu", cpu);
			OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			OResult<int[], int[]> oResult2 = ((!isBit) ? SnetHelper.SplitReadLength(oResult.Content.AddressStart, length, 64) : SnetHelper.SplitReadLength(oResult.Content.AddressStart, length, 256));
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < oResult2.Content1.Length; i++)
			{
				oResult.Content.AddressStart = oResult2.Content1[i];
				byte[] array = new byte[12]
				{
					(byte)(isBit ? 1u : 17u),
					cpu,
					0,
					8,
					0,
					0,
					0,
					0,
					0,
					0,
					0,
					0
				};
				oResult.Content.GetAddressBinaryContent().CopyTo(array, 4);
				array[10] = BitConverter.GetBytes(oResult2.Content2[i])[1];
				array[11] = BitConverter.GetBytes(oResult2.Content2[i])[0];
				list.Add(array);
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 构建随机读取的原始报文的初始命令
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="address">实际的数据地址信息</param>
		/// <param name="isBit">是否是位读取</param>
		/// <returns>实际的读取的报文信息</returns>
		public static OResult<List<byte[]>> BuildReadRandomCommand(byte cpu, string[] address, bool isBit)
		{
			List<string[]> list = SoftBasic.ArraySplitByLength(address, 32);
			List<byte[]> list2 = new List<byte[]>();
			foreach (string[] item in list)
			{
				byte[] array = new byte[6 + 6 * item.Length];
				array[0] = (byte)(isBit ? 4u : 20u);
				array[1] = cpu;
				array[2] = BitConverter.GetBytes(array.Length - 4)[1];
				array[3] = BitConverter.GetBytes(array.Length - 4)[0];
				array[4] = BitConverter.GetBytes(item.Length)[1];
				array[5] = BitConverter.GetBytes(item.Length)[0];
				for (int i = 0; i < item.Length; i++)
				{
					array[1] = (byte)SnetHelper.ExtractParameter(ref item[i], "cpu", cpu);
					OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(item[i], 1);
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<List<byte[]>>(oResult);
					}
					oResult.Content.GetAddressBinaryContent().CopyTo(array, 6 * i + 6);
				}
				list2.Add(array);
			}
			return OResult.CreateSuccessResult(list2);
		}

		/// <summary>
		/// 构建批量写入Bool数组的命令，需要指定CPU Number信息和设备地址信息
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="address">设备地址数据</param>
		/// <param name="value">实际的bool数组</param>
		/// <returns>构建的写入指令</returns>
		public static OResult<byte[]> BuildWriteBoolCommand(byte cpu, string address, bool[] value)
		{
			cpu = (byte)SnetHelper.ExtractParameter(ref address, "cpu", cpu);
			OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[12 + value.Length];
			array[0] = 2;
			array[1] = cpu;
			array[2] = 0;
			array[3] = (byte)(8 + value.Length);
			oResult.Content.GetAddressBinaryContent().CopyTo(array, 4);
			array[10] = BitConverter.GetBytes(value.Length)[1];
			array[11] = BitConverter.GetBytes(value.Length)[0];
			for (int i = 0; i < value.Length; i++)
			{
				array[12 + i] = (value[i] ? ((byte)1) : ((byte)0));
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建批量随机写入Bool数组的命令，需要指定CPU Number信息和设备地址信息
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="address">设备地址数据</param>
		/// <param name="value">实际的bool数组</param>
		/// <returns>构建的写入指令</returns>
		public static OResult<byte[]> BuildWriteRandomBoolCommand(byte cpu, string[] address, bool[] value)
		{
			if (address.Length != value.Length)
			{
				return new OResult<byte[]>(StringResources.Language.TwoParametersLengthIsNotSame);
			}
			byte[] array = new byte[6 + address.Length * 8 - 1];
			array[0] = 5;
			array[1] = cpu;
			array[2] = BitConverter.GetBytes(array.Length - 4)[1];
			array[3] = BitConverter.GetBytes(array.Length - 4)[0];
			array[4] = BitConverter.GetBytes(address.Length)[1];
			array[5] = BitConverter.GetBytes(address.Length)[0];
			for (int i = 0; i < address.Length; i++)
			{
				array[1] = (byte)SnetHelper.ExtractParameter(ref address[i], "cpu", cpu);
				OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address[i], 0);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				oResult.Content.GetAddressBinaryContent().CopyTo(array, 6 + 8 * i);
				array[12 + 8 * i] = (value[i] ? ((byte)1) : ((byte)0));
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建字写入的命令报文信息，需要指定设备地址
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="address">地址</param>
		/// <param name="value">原始的数据值</param>
		/// <returns>原始的报文命令</returns>
		public static OResult<byte[]> BuildWriteWordCommand(byte cpu, string address, byte[] value)
		{
			cpu = (byte)SnetHelper.ExtractParameter(ref address, "cpu", cpu);
			OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[12 + value.Length];
			array[0] = 18;
			array[1] = cpu;
			array[2] = 0;
			array[3] = (byte)(8 + value.Length);
			oResult.Content.GetAddressBinaryContent().CopyTo(array, 4);
			array[10] = BitConverter.GetBytes(value.Length / 2)[1];
			array[11] = BitConverter.GetBytes(value.Length / 2)[0];
			value.CopyTo(array, 12);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建随机写入字的命令的报文
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="address">地址</param>
		/// <param name="value">原始的数据值</param>
		/// <returns>原始的报文命令</returns>
		public static OResult<byte[]> BuildWriteRandomWordCommand(byte cpu, string[] address, byte[] value)
		{
			if (address.Length * 2 != value.Length)
			{
				return new OResult<byte[]>(StringResources.Language.TwoParametersLengthIsNotSame);
			}
			byte[] array = new byte[6 + address.Length * 8];
			array[0] = 21;
			array[1] = cpu;
			array[2] = BitConverter.GetBytes(array.Length - 4)[1];
			array[3] = BitConverter.GetBytes(array.Length - 4)[0];
			array[4] = BitConverter.GetBytes(address.Length)[1];
			array[5] = BitConverter.GetBytes(address.Length)[0];
			for (int i = 0; i < address.Length; i++)
			{
				array[1] = (byte)SnetHelper.ExtractParameter(ref address[i], "cpu", cpu);
				OResult<YokogawaLinkAddress> oResult = YokogawaLinkAddress.ParseFrom(address[i], 0);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				oResult.Content.GetAddressBinaryContent().CopyTo(array, 6 + 8 * i);
				array[12 + 8 * i] = value[i * 2];
				array[13 + 8 * i] = value[i * 2 + 1];
			}
			return OResult.CreateSuccessResult(array);
		}

