		/// <summary>
		/// 构建读取特殊模块的命令报文
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="moduleUnit">模块单元号</param>
		/// <param name="moduleSlot">模块站号</param>
		/// <param name="dataPosition">数据位置</param>
		/// <param name="length">长度信息</param>
		/// <returns>原始的报文命令</returns>
		public static List<byte[]> BuildReadSpecialModule(byte cpu, byte moduleUnit, byte moduleSlot, ushort dataPosition, ushort length)
		{
			List<byte[]> list = new List<byte[]>();
			OResult<int[], int[]> oResult = SnetHelper.SplitReadLength(dataPosition, length, 64);
			for (int i = 0; i < oResult.Content1.Length; i++)
			{
				byte[] array = new byte[10];
				array[0] = 49;
				array[1] = cpu;
				array[2] = BitConverter.GetBytes(array.Length - 4)[1];
				array[3] = BitConverter.GetBytes(array.Length - 4)[0];
				array[4] = moduleUnit;
				array[5] = moduleSlot;
				array[6] = BitConverter.GetBytes(oResult.Content1[i])[1];
				array[7] = BitConverter.GetBytes(oResult.Content1[i])[0];
				array[8] = BitConverter.GetBytes(oResult.Content2[i])[1];
				array[9] = BitConverter.GetBytes(oResult.Content2[i])[0];
				list.Add(array);
			}
			return list;
		}

		/// <summary>
		/// 构建读取特殊模块的命令报文，需要传入高级地址，必须以 <b>Special:</b> 开头表示特殊模块地址，示例：Special:cpu=1;unit=0;slot=1;100<br />
		/// To construct a command message to read a special module, the advanced address needs to be passed in. 
		/// It must start with <b>Special:</b> to indicate the address of the special module, for example: Special:cpu=1;unit=0;slot=1;100
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="address">高级的混合地址，除了Cpu可以不携带，例如：Special:unit=0;slot=1;100</param>
		/// <param name="length">长度信息</param>
		/// <returns>原始的报文命令</returns>
		public static OResult<List<byte[]>> BuildReadSpecialModule(byte cpu, string address, ushort length)
		{
			if (address.StartsWith("Special:") || address.StartsWith("special:"))
			{
				address = address.Substring(8);
				cpu = (byte)SnetHelper.ExtractParameter(ref address, "cpu", cpu);
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "unit");
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<List<byte[]>>(oResult);
				}
				OResult<int> oResult2 = SnetHelper.ExtractParameter(ref address, "slot");
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<List<byte[]>>(oResult2);
				}
				try
				{
					return OResult.CreateSuccessResult(BuildReadSpecialModule(cpu, (byte)oResult.Content, (byte)oResult2.Content, ushort.Parse(address), length));
				}
				catch (Exception ex)
				{
					return new OResult<List<byte[]>>("Address format wrong: " + ex.Message);
				}
			}
			return new OResult<List<byte[]>>("Special module address must start with Special:");
		}

		/// <summary>
		/// 构建读取特殊模块的命令报文
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="moduleUnit">模块单元号</param>
		/// <param name="moduleSlot">模块站号</param>
		/// <param name="dataPosition">数据位置</param>
		/// <param name="data">数据内容</param>
		/// <returns>原始的报文命令</returns>
		public static byte[] BuildWriteSpecialModule(byte cpu, byte moduleUnit, byte moduleSlot, ushort dataPosition, byte[] data)
		{
			byte[] array = new byte[10 + data.Length];
			array[0] = 50;
			array[1] = cpu;
			array[2] = BitConverter.GetBytes(array.Length - 4)[1];
			array[3] = BitConverter.GetBytes(array.Length - 4)[0];
			array[4] = moduleUnit;
			array[5] = moduleSlot;
			array[6] = BitConverter.GetBytes(dataPosition)[1];
			array[7] = BitConverter.GetBytes(dataPosition)[0];
			array[8] = BitConverter.GetBytes(data.Length / 2)[1];
			array[9] = BitConverter.GetBytes(data.Length / 2)[0];
			data.CopyTo(array, 10);
			return array;
		}

		/// <summary>
		/// 构建写入特殊模块的命令报文，需要传入高级地址，必须以 <b>Special:</b> 开头表示特殊模块地址，示例：Special:cpu=1;unit=0;slot=1;100<br />
		/// To construct a command message to write a special module, the advanced address needs to be passed in. 
		/// It must start with <b>Special:</b> to indicate the address of the special module, for example: Special:cpu=1;unit=0;slot=1;100
		/// </summary>
		/// <param name="cpu">Cpu Number</param>
		/// <param name="address">高级的混合地址，除了Cpu可以不携带，例如：Special:unit=0;slot=1;100</param>
		/// <param name="data">写入的原始数据内容</param>
		/// <returns>原始的报文命令</returns>
		public static OResult<byte[]> BuildWriteSpecialModule(byte cpu, string address, byte[] data)
		{
			OResult<List<byte[]>> oResult = BuildReadSpecialModule(cpu, address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[10 + data.Length];
			array[0] = 50;
			array[1] = oResult.Content[0][1];
			array[2] = BitConverter.GetBytes(array.Length - 4)[1];
			array[3] = BitConverter.GetBytes(array.Length - 4)[0];
			array[4] = oResult.Content[0][4];
			array[5] = oResult.Content[0][5];
			array[6] = oResult.Content[0][6];
			array[7] = oResult.Content[0][7];
			array[8] = BitConverter.GetBytes(data.Length / 2)[1];
			array[9] = BitConverter.GetBytes(data.Length / 2)[0];
			data.CopyTo(array, 10);
			return OResult.CreateSuccessResult(array);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"YokogawaLinkTcp[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 横河PLC的系统基本信息<br />
	/// Basic system information of Yokogawa PLC
	/// </summary>
	public class YokogawaSystemInfo
	{
		/// <summary>
		/// 当前系统的ID名称，例如F3SP21-ON<br />
		/// The ID name of the current system, such as F3SP21-ON
		/// </summary>
		public string SystemID { get; set; }

		/// <summary>
		/// 当前系统的修订版本号<br />
		/// The revision number of the current system
		/// </summary>
		public string Revision { get; set; }

		/// <summary>
		/// 当前系统的类型，分为 <b>Sequence</b> 和 <b>BASIC</b> <br />
		/// The type of the current system, divided into <b>Sequence</b> and <b>BASIC</b>
		/// </summary>
		public string CpuType { get; set; }

		/// <summary>
		/// 当前系统的程序大小，如果是Sequence系统，就是步序总量，如果是BASIC系统，就是字节数量<br />
		/// The program size of the current system, if it is a Sequence system, it is the total number of steps, if it is a BASIC system, it is the number of bytes
		/// </summary>
		public int ProgramAreaSize { get; set; }

		/// <inheritdoc />
		public override string ToString()
		{
			return "YokogawaSystemInfo[" + SystemID + "]";
		}

		/// <summary>
		/// 根据原始的数据信息解析出<see cref="T:Snet.Driver.Profinet.Yokogawa.YokogawaSystemInfo" />对象<br />
		/// Analyze the <see cref="T:Snet.Driver.Profinet.Yokogawa.YokogawaSystemInfo" /> object according to the original data information
		/// </summary>
		/// <param name="content">原始的数据信息</param>
		/// <returns>是否解析成功的结果对象</returns>
		public static OResult<YokogawaSystemInfo> Parse(byte[] content)
		{
			try
			{
				YokogawaSystemInfo yokogawaSystemInfo = new YokogawaSystemInfo();
				yokogawaSystemInfo.SystemID = Encoding.ASCII.GetString(content, 0, 16).Trim('\0', ' ');
				yokogawaSystemInfo.Revision = Encoding.ASCII.GetString(content, 16, 8).Trim('\0', ' ');
				if (content[25] == 1 || content[25] == 17)
				{
					yokogawaSystemInfo.CpuType = "Sequence";
				}
				else if (content[25] == 2 || content[25] == 18)
				{
					yokogawaSystemInfo.CpuType = "BASIC";
				}
				else
				{
					yokogawaSystemInfo.CpuType = StringResources.Language.UnknownError;
				}
				yokogawaSystemInfo.ProgramAreaSize = content[26] * 256 + content[27];
				return OResult.CreateSuccessResult(yokogawaSystemInfo);
			}
			catch (Exception ex)
			{
				return new OResult<YokogawaSystemInfo>("Parse YokogawaSystemInfo failed: " + ex.Message + Environment.NewLine + "Source: " + content.ToHexString(' '));
			}
		}
	}
}
