	/// <summary>
	/// 基于扩展memobus协议的虚拟服务器，支持线圈，输入线圈，保持型寄存器，输入寄存器，保持型寄存器（扩展），输入寄存器（扩展）的读写。对于远程客户端来说，还支持对扩展保持寄存器的随机字读取和写入操作。<br />
	/// A virtual server based on the extended memobus protocol, which supports the reading and writing of coils, input coils, holding registers, input registers, 
	/// holding registers (expansion), input registers (expansion). For remote clients, random word reads and writes to extended hold registers are also supported.
	/// </summary>
	/// <remarks>
	/// 支持的功能码为 01 02 03 04 05 06 08 09 0A 0B 0D 0E 0F 10, 访问方式分为位读写和字读写，位读写：线圈：100; 输入线圈：x=2;100<br />
	/// 字读写时，保持型寄存器：100; 输入寄存器：x=4;100  保持型寄存器（扩展）: x=9;100   输入寄存器（扩展）: x=10;100
	/// </remarks>
	public class MemobusTcpServer : DeviceServer
	{
		private SoftBuffer xBuffer;

		private SoftBuffer yBuffer;

		private SoftBuffer inputBuffer;

		private SoftBuffer rBuffer;

		private SoftBuffer rExtBuffer;

		private SoftBuffer inputExtBuffer;

		private SoftBuffer gBuffer;

		private const int DataPoolLength = 65536;

		/// <summary>
		/// 实例化一个memobus协议的PLC的服务器，支持线圈，输入线圈，保持型寄存器，输入寄存器，保持型寄存器（扩展），输入寄存器（扩展）的读写。
		/// </summary>
		public MemobusTcpServer()
		{
			xBuffer = new SoftBuffer(65536);
			yBuffer = new SoftBuffer(65536);
			inputBuffer = new SoftBuffer(131072)
			{
				IsBoolReverseByWord = true
			};
			rBuffer = new SoftBuffer(131072)
			{
				IsBoolReverseByWord = true
			};
			inputExtBuffer = new SoftBuffer(131072)
			{
				IsBoolReverseByWord = true
			};
			rExtBuffer = new SoftBuffer(131072)
			{
				IsBoolReverseByWord = true
			};
			gBuffer = new SoftBuffer(131072)
			{
				IsBoolReverseByWord = true
			};
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
		}

		private OResult<SoftBuffer> GetDataAreaFromYokogawaAddress(MemobusAddress address, bool isBit)
		{
			switch (address.SFC)
			{
			case 1:
			case 5:
			case 15:
				return OResult.CreateSuccessResult(yBuffer);
			case 2:
				return OResult.CreateSuccessResult(xBuffer);
			case 3:
			case 6:
			case 16:
				return OResult.CreateSuccessResult(rBuffer);
			case 4:
				return OResult.CreateSuccessResult(inputBuffer);
			case 9:
			case 11:
			case 13:
			case 14:
				return OResult.CreateSuccessResult(rExtBuffer);
			case 10:
				return OResult.CreateSuccessResult(inputExtBuffer);
			default:
				return new OResult<SoftBuffer>(StringResources.Language.NotSupportedDataType);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.YASKAWA.MemobusTcpNet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			if (address.StartsWith(new string[1] { "G" }))
			{
				int num = Convert.ToInt32(address.Substring(1));
				return OResult.CreateSuccessResult(gBuffer.GetBytes(num * 2, length * 2));
			}
			OResult<MemobusAddress> oResult = MemobusAddress.ParseFrom(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromYokogawaAddress = GetDataAreaFromYokogawaAddress(oResult.Content, isBit: false);
			if (!dataAreaFromYokogawaAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataAreaFromYokogawaAddress);
			}
			return OResult.CreateSuccessResult(dataAreaFromYokogawaAddress.Content.GetBytes(oResult.Content.AddressStart * 2, length * 2));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.YASKAWA.MemobusTcpNet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			if (address.StartsWith(new string[1] { "G" }))
			{
				int num = Convert.ToInt32(address.Substring(1));
				gBuffer.SetBytes(value, num * 2);
				return OResult.CreateSuccessResult();
			}
			OResult<MemobusAddress> oResult = MemobusAddress.ParseFrom(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromYokogawaAddress = GetDataAreaFromYokogawaAddress(oResult.Content, isBit: false);
			if (!dataAreaFromYokogawaAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataAreaFromYokogawaAddress);
			}
			dataAreaFromYokogawaAddress.Content.SetBytes(value, oResult.Content.AddressStart * 2);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.YASKAWA.MemobusTcpNet.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (address.StartsWith(new string[1] { "G" }))
			{
				int destIndex = MemobusHelper.CalculateBoolIndex(address);
				return OResult.CreateSuccessResult(gBuffer.GetBool(destIndex, length));
			}
			OResult<MemobusAddress> oResult = MemobusAddress.ParseFrom(address, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromYokogawaAddress = GetDataAreaFromYokogawaAddress(oResult.Content, isBit: true);
			if (!dataAreaFromYokogawaAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(dataAreaFromYokogawaAddress);
			}
			if (oResult.Content.SFC == 3 || oResult.Content.SFC == 4)
			{
				return OResult.CreateSuccessResult(dataAreaFromYokogawaAddress.Content.GetBool(oResult.Content.AddressStart, length));
			}
			return OResult.CreateSuccessResult((from m in dataAreaFromYokogawaAddress.Content.GetBytes(oResult.Content.AddressStart, length)
				select m != 0).ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.YASKAWA.MemobusTcpNet.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			if (address.StartsWith(new string[1] { "G" }))
			{
				int destIndex = MemobusHelper.CalculateBoolIndex(address);
				gBuffer.SetBool(value, destIndex);
				return OResult.CreateSuccessResult();
			}
			OResult<MemobusAddress> oResult = MemobusAddress.ParseFrom(address, isBit: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<SoftBuffer> dataAreaFromYokogawaAddress = GetDataAreaFromYokogawaAddress(oResult.Content, isBit: true);
			if (!dataAreaFromYokogawaAddress.IsSuccess)
			{
				return dataAreaFromYokogawaAddress;
			}
			if (oResult.Content.SFC == 3 || oResult.Content.SFC == 4)
			{
				dataAreaFromYokogawaAddress.Content.SetBool(value, oResult.Content.AddressStart);
			}
			else
			{
				dataAreaFromYokogawaAddress.Content.SetBytes(value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), oResult.Content.AddressStart);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new MemobusMessage();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			return OResult.CreateSuccessResult((receive[15] != 1 && receive[15] != 2 && receive[15] != 65) ? ((receive[15] != 5 && receive[15] != 15 && receive[15] != 79) ? ((receive[15] != 3 && receive[15] != 4 && receive[15] != 9 && receive[15] != 10 && receive[15] != 73) ? ((receive[15] == 6 || receive[15] == 16 || receive[15] == 11 || receive[15] == 75) ? WriteWordByCommand(receive) : ((receive[15] == 13 || receive[15] == 77) ? ReadRandomWordByCommand(receive) : ((receive[15] == 14) ? WriteRandomWordByCommand(receive) : ((receive[15] != 8) ? PackCommandBack(receive, 1, null) : PackCommandBack(receive, 0, null))))) : ReadWordByCommand(receive)) : WriteBoolByCommand(receive)) : ReadBoolByCommand(receive));
		}

		private byte[] ReadBoolByCommand(byte[] command)
		{
			if (command[15] == 1 || command[15] == 2)
			{
				int num = base.ByteTransform.TransUInt16(command, 17);
				int num2 = base.ByteTransform.TransUInt16(command, 19);
				if (num + num2 > 65535)
				{
					return PackCommandBack(command, 3, null);
				}
				return command[15] switch
				{
					1 => PackCommandBack(command, 0, (from m in yBuffer.GetBytes(num, num2)
						select m != 0).ToArray().ToByteArray()), 
					2 => PackCommandBack(command, 0, (from m in xBuffer.GetBytes(num, num2)
						select m != 0).ToArray().ToByteArray()), 
					_ => PackCommandBack(command, 1, null), 
				};
			}
			if (command[15] == 65)
			{
				byte b = command[18];
				int destIndex = BitConverter.ToInt32(command, 20);
				int length = BitConverter.ToInt32(command, 24);
				return b switch
				{
					77 => PackCommandBack(command, 0, rBuffer.GetBool(destIndex, length).ToByteArray()), 
					73 => PackCommandBack(command, 0, inputBuffer.GetBool(destIndex, length).ToByteArray()), 
					71 => PackCommandBack(command, 0, gBuffer.GetBool(destIndex, length).ToByteArray()), 
					_ => PackCommandBack(command, 1, null), 
				};
			}
			return PackCommandBack(command, 1, null);
		}

		private byte[] WriteBoolByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandBack(command, 3, null);
			}
			if (command[15] == 5 || command[15] == 15)
			{
				int num = base.ByteTransform.TransUInt16(command, 17);
				int num2 = base.ByteTransform.TransUInt16(command, 19);
				switch (command[15])
				{
				case 5:
					if (command.Length != 21)
					{
						return PackCommandBack(command, 5, null);
					}
					yBuffer.SetBytes(new byte[1] { command[19] }, num);
					return PackCommandBack(command, 0, null);
				case 15:
				{
					if (num + num2 > 65535)
					{
						return PackCommandBack(command, 3, null);
					}
					if (command.Length != 21 + (num2 + 7) / 8)
					{
						return PackCommandBack(command, 5, null);
					}
					bool[] source = command.RemoveBegin(21).ToBoolArray().SelectBegin(num2);
					yBuffer.SetBytes(source.Select((bool m) => (byte)(m ? 255u : 0u)).ToArray(), num);
					return PackCommandBack(command, 0, null);
				}
				default:
					return PackCommandBack(command, 1, null);
				}
			}
			if (command[15] == 79)
			{
				byte b = command[18];
				int destIndex = BitConverter.ToInt32(command, 20);
				int length = BitConverter.ToUInt16(command, 24);
				bool[] value = command.RemoveBegin(28).ToBoolArray().SelectBegin(length);
				switch (b)
				{
				case 77:
					rBuffer.SetBool(value, destIndex);
					return PackCommandBack(command, 0, null);
				case 71:
					gBuffer.SetBool(value, destIndex);
					return PackCommandBack(command, 0, null);
				default:
					return PackCommandBack(command, 1, null);
				}
			}
			return PackCommandBack(command, 1, null);
		}

		private byte[] ReadWordByCommand(byte[] command)
		{
			if (command[15] == 3 || command[15] == 4)
			{
				int num = base.ByteTransform.TransUInt16(command, 17);
				int num2 = base.ByteTransform.TransUInt16(command, 19);
				if (num + num2 > 65535)
				{
					return PackCommandBack(command, 3, null);
				}
				if (command[15] == 3)
				{
					return PackCommandBack(command, 0, rBuffer.GetBytes(num * 2, num2 * 2));
				}
				if (command[15] == 4)
				{
					return PackCommandBack(command, 0, inputBuffer.GetBytes(num * 2, num2 * 2));
				}
			}
			else if (command[15] == 9 || command[15] == 10)
			{
				int num3 = BitConverter.ToUInt16(command, 18);
				int num4 = BitConverter.ToUInt16(command, 20);
				if (num3 + num4 > 65535)
				{
					return PackCommandBack(command, 3, null);
				}
				if (command[15] == 9)
				{
					return PackCommandBack(command, 0, SoftBasic.BytesReverseByWord(rExtBuffer.GetBytes(num3 * 2, num4 * 2)));
				}
				if (command[15] == 10)
				{
					return PackCommandBack(command, 0, SoftBasic.BytesReverseByWord(inputExtBuffer.GetBytes(num3 * 2, num4 * 2)));
				}
			}
			else if (command[15] == 73)
			{
				byte b = command[18];
				int num5 = BitConverter.ToInt32(command, 20);
				int num6 = BitConverter.ToUInt16(command, 24);
				switch (b)
				{
				case 77:
					return PackCommandBack(command, 0, SoftBasic.BytesReverseByWord(rBuffer.GetBytes(num5 * 2, num6 * 2)));
				case 73:
					return PackCommandBack(command, 0, SoftBasic.BytesReverseByWord(inputBuffer.GetBytes(num5 * 2, num6 * 2)));
				case 71:
					return PackCommandBack(command, 0, SoftBasic.BytesReverseByWord(gBuffer.GetBytes(num5 * 2, num6 * 2)));
				}
			}
			return PackCommandBack(command, 1, null);
		}

		private byte[] WriteWordByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandBack(command, 3, null);
			}
			if (command[15] == 6 || command[15] == 16)
			{
				int num = base.ByteTransform.TransUInt16(command, 17);
				int num2 = base.ByteTransform.TransUInt16(command, 19);
				if (command[15] == 6)
				{
					if (command.Length != 21)
					{
						return PackCommandBack(command, 3, null);
					}
					rBuffer.SetBytes(command.SelectLast(2), num * 2);
					return PackCommandBack(command, 0, null);
				}
				if (num + num2 > 65535)
				{
					return PackCommandBack(command, 3, null);
				}
				if (command.Length != 21 + num2 * 2)
				{
					return PackCommandBack(command, 3, null);
				}
				rBuffer.SetBytes(command.RemoveBegin(21), num * 2);
				return PackCommandBack(command, 0, null);
			}
			if (command[15] == 11)
			{
				int num3 = BitConverter.ToUInt16(command, 18);
				int num4 = BitConverter.ToUInt16(command, 20);
				if (num3 + num4 > 65535)
				{
					return PackCommandBack(command, 3, null);
				}
				if (command.Length != 22 + num4 * 2)
				{
					return PackCommandBack(command, 3, null);
				}
				rExtBuffer.SetBytes(SoftBasic.BytesReverseByWord(command.RemoveBegin(22)), num3 * 2);
				return PackCommandBack(command, 0, null);
			}
			if (command[15] == 75)
			{
				byte b = command[18];
				int num5 = BitConverter.ToInt32(command, 20);
				int num6 = BitConverter.ToUInt16(command, 24);
				if (command.Length != 26 + num6 * 2)
				{
					return PackCommandBack(command, 3, null);
				}
				switch (b)
				{
				case 77:
					rBuffer.SetBytes(SoftBasic.BytesReverseByWord(command.RemoveBegin(26)), num5 * 2);
					return PackCommandBack(command, 0, null);
				case 71:
					gBuffer.SetBytes(SoftBasic.BytesReverseByWord(command.RemoveBegin(26)), num5 * 2);
					return PackCommandBack(command, 0, null);
				}
			}
			return PackCommandBack(command, 1, null);
		}

		private byte[] ReadRandomWordByCommand(byte[] command)
		{
			int num = BitConverter.ToUInt16(command, 18);
			if (command[15] == 13)
			{
				if (command.Length != 20 + num * 2)
				{
					return PackCommandBack(command, 3, null);
				}
				byte[] array = new byte[num * 2];
				for (int i = 0; i < num; i++)
				{
					int num2 = BitConverter.ToUInt16(command, 20 + i * 2);
					byte[] bytes = rExtBuffer.GetBytes(num2 * 2, 2);
					array[i * 2] = bytes[1];
					array[i * 2 + 1] = bytes[0];
				}
				return PackCommandBack(command, 0, array);
			}
			if (command.Length != 20 + num * 6)
			{
				return PackCommandBack(command, 3, null);
			}
			byte[] array2 = new byte[num * 2];
			for (int j = 0; j < num; j++)
			{
				byte b = command[20 + j * 6];
				int num3 = BitConverter.ToInt32(command, 22 + j * 6);
				switch (b)
				{
				case 77:
				{
					byte[] bytes4 = rBuffer.GetBytes(num3 * 2, 2);
					array2[j * 2] = bytes4[1];
					array2[j * 2 + 1] = bytes4[0];
					break;
				}
				case 73:
				{
					byte[] bytes3 = inputBuffer.GetBytes(num3 * 2, 2);
					array2[j * 2] = bytes3[1];
					array2[j * 2 + 1] = bytes3[0];
					break;
				}
				case 71:
				{
					byte[] bytes2 = gBuffer.GetBytes(num3 * 2, 2);
					array2[j * 2] = bytes2[1];
					array2[j * 2 + 1] = bytes2[0];
					break;
				}
				}
			}
			return PackCommandBack(command, 0, array2);
		}

		private byte[] WriteRandomWordByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandBack(command, 3, null);
			}
			int num = BitConverter.ToUInt16(command, 18);
			if (command.Length != 20 + num * 4)
			{
				return PackCommandBack(command, 3, null);
			}
			for (int i = 0; i < num; i++)
			{
				int num2 = BitConverter.ToUInt16(command, 20 + i * 4);
				rExtBuffer.SetValue(command[20 + i * 4 + 2], num2 * 2 + 1);
				rExtBuffer.SetValue(command[20 + i * 4 + 3], num2 * 2);
			}
			return PackCommandBack(command, 0, null);
		}

		private byte TransByteHighLow(byte value)
		{
			int num = value & 0xF0;
			num >>= 4;
			return (byte)(((value & 0xF) << 4) | num);
		}

		private byte[] PackCommandBack(byte[] cmds, byte err, byte[] result)
		{
			if (result == null)
			{
				result = new byte[0];
			}
			if (err > 0)
			{
				byte[] array = new byte[6 + result.Length];
				array[0] = 4;
				array[1] = 0;
				array[2] = cmds[14];
				array[3] = (byte)(cmds[15] + 128);
				array[4] = TransByteHighLow(cmds[16]);
				array[5] = err;
				return MemobusHelper.PackCommandWithHeader(array, cmds[1]);
			}
			if (cmds[15] == 1 || cmds[15] == 2 || cmds[15] == 3 || cmds[15] == 4)
			{
				byte[] array2 = new byte[5 + result.Length];
				array2[0] = BitConverter.GetBytes(3 + result.Length)[0];
				array2[1] = BitConverter.GetBytes(3 + result.Length)[1];
				array2[2] = cmds[14];
				array2[3] = cmds[15];
				array2[4] = TransByteHighLow(cmds[16]);
				result.CopyTo(array2, 5);
				return MemobusHelper.PackCommandWithHeader(array2, cmds[1]);
			}
			if (cmds[15] == 5 || cmds[15] == 6 || cmds[15] == 8)
			{
				byte[] array3 = cmds.RemoveBegin(12);
				array3[0] = BitConverter.GetBytes(array3.Length - 2)[0];
				array3[1] = BitConverter.GetBytes(array3.Length - 2)[1];
				array3[4] = TransByteHighLow(cmds[16]);
				return MemobusHelper.PackCommandWithHeader(array3, cmds[1]);
			}
			if (cmds[15] == 9 || cmds[15] == 10 || cmds[15] == 13)
			{
				byte[] array4 = new byte[8 + result.Length];
				array4[0] = BitConverter.GetBytes(array4.Length - 2)[0];
				array4[1] = BitConverter.GetBytes(array4.Length - 2)[1];
				array4[2] = cmds[14];
				array4[3] = cmds[15];
				array4[4] = TransByteHighLow(cmds[16]);
				array4[6] = BitConverter.GetBytes(result.Length / 2)[0];
				array4[7] = BitConverter.GetBytes(result.Length / 2)[1];
				result.CopyTo(array4, 8);
				return MemobusHelper.PackCommandWithHeader(array4, cmds[1]);
			}
			if (cmds[15] == 11)
			{
				byte[] array5 = cmds.SelectMiddle(12, 10);
				array5[0] = BitConverter.GetBytes(array5.Length - 2)[0];
				array5[1] = BitConverter.GetBytes(array5.Length - 2)[1];
				array5[4] = TransByteHighLow(cmds[16]);
				return MemobusHelper.PackCommandWithHeader(array5, cmds[1]);
			}
			if (cmds[15] == 14)
			{
				byte[] array6 = cmds.SelectMiddle(12, 8);
				array6[0] = BitConverter.GetBytes(array6.Length - 2)[0];
				array6[1] = BitConverter.GetBytes(array6.Length - 2)[1];
				array6[4] = TransByteHighLow(cmds[16]);
				return MemobusHelper.PackCommandWithHeader(array6, cmds[1]);
			}
			if (cmds[15] == 15 || cmds[15] == 16)
			{
				byte[] array7 = cmds.SelectMiddle(12, 9);
				array7[0] = BitConverter.GetBytes(array7.Length - 2)[0];
				array7[1] = BitConverter.GetBytes(array7.Length - 2)[1];
				array7[4] = TransByteHighLow(cmds[16]);
				return MemobusHelper.PackCommandWithHeader(array7, cmds[1]);
			}
			if (cmds[15] == 65)
			{
				byte[] array8 = new byte[8 + result.Length];
				array8[0] = BitConverter.GetBytes(array8.Length - 2)[0];
				array8[1] = BitConverter.GetBytes(array8.Length - 2)[1];
				array8[2] = cmds[14];
				array8[3] = cmds[15];
				array8[4] = TransByteHighLow(cmds[16]);
				array8[6] = cmds[18];
				result.CopyTo(array8, 8);
				return MemobusHelper.PackCommandWithHeader(array8, cmds[1]);
			}
			if (cmds[15] == 73)
			{
				byte[] array9 = new byte[10 + result.Length];
				array9[0] = BitConverter.GetBytes(8 + result.Length)[0];
				array9[1] = BitConverter.GetBytes(8 + result.Length)[1];
				array9[2] = cmds[14];
				array9[3] = cmds[15];
				array9[4] = TransByteHighLow(cmds[16]);
				array9[6] = cmds[18];
				array9[8] = BitConverter.GetBytes(result.Length / 2)[0];
				array9[9] = BitConverter.GetBytes(result.Length / 2)[1];
				result.CopyTo(array9, 10);
				return MemobusHelper.PackCommandWithHeader(array9, cmds[1]);
			}
			if (cmds[15] == 75)
			{
				byte[] array10 = cmds.SelectMiddle(12, 14);
				array10[0] = BitConverter.GetBytes(array10.Length - 2)[0];
				array10[1] = BitConverter.GetBytes(array10.Length - 2)[1];
				array10[4] = TransByteHighLow(cmds[16]);
				return MemobusHelper.PackCommandWithHeader(array10, cmds[1]);
			}
			if (cmds[15] == 77)
			{
				byte[] array11 = new byte[8 + result.Length];
				array11[0] = BitConverter.GetBytes(6 + result.Length)[0];
				array11[1] = BitConverter.GetBytes(6 + result.Length)[1];
				array11[2] = cmds[14];
				array11[3] = cmds[15];
				array11[4] = TransByteHighLow(cmds[16]);
				array11[6] = BitConverter.GetBytes(result.Length / 2)[0];
				array11[7] = BitConverter.GetBytes(result.Length / 2)[1];
				result.CopyTo(array11, 8);
				return MemobusHelper.PackCommandWithHeader(array11, cmds[1]);
			}
			if (cmds[15] == 79)
			{
				byte[] array12 = cmds.SelectMiddle(12, 16);
				array12[0] = BitConverter.GetBytes(array12.Length - 2)[0];
				array12[1] = BitConverter.GetBytes(array12.Length - 2)[1];
				array12[4] = TransByteHighLow(cmds[16]);
				return MemobusHelper.PackCommandWithHeader(array12, cmds[1]);
			}
			return PackCommandBack(cmds, 3, null);
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 655360)
			{
				throw new Exception("File is not correct");
			}
			xBuffer.SetBytes(content, 0, 0, 65536);
			yBuffer.SetBytes(content, 65536, 0, 65536);
			inputBuffer.SetBytes(content, 131072, 0, 65536);
			rBuffer.SetBytes(content, 262144, 0, 65536);
			rExtBuffer.SetBytes(content, 393216, 0, 65536);
			inputExtBuffer.SetBytes(content, 524288, 0, 65536);
			if (content.Length >= 786432)
			{
				gBuffer.SetBytes(content, 655360, 0, 65536);
			}
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[786432];
			Array.Copy(xBuffer.GetBytes(), 0, array, 0, 65536);
			Array.Copy(yBuffer.GetBytes(), 0, array, 65536, 65536);
			Array.Copy(inputBuffer.GetBytes(), 0, array, 131072, 131072);
			Array.Copy(rBuffer.GetBytes(), 0, array, 262144, 131072);
			Array.Copy(rExtBuffer.GetBytes(), 0, array, 393216, 131072);
			Array.Copy(inputExtBuffer.GetBytes(), 0, array, 524288, 131072);
			Array.Copy(gBuffer.GetBytes(), 0, array, 655360, 131072);
			return array;
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				xBuffer?.Dispose();
				yBuffer?.Dispose();
				inputBuffer?.Dispose();
				rBuffer?.Dispose();
				rExtBuffer?.Dispose();
				inputExtBuffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MemobusTcpServer[{base.Port}]";
		}
	}
	/// <inheritdoc cref="T:Snet.Driver.Profinet.YASKAWA.MemobusTcpNet" />
	public class MemobusUdpNet : MemobusTcpNet, IMemobus, IReadWriteDevice, IReadWriteNet
	{
		/// <summary>
		/// 实例化一个Memobus-Tcp协议的客户端对象<br />
		/// Instantiate a client object of the Memobus-Tcp protocol
		/// </summary>
		public MemobusUdpNet()
		{
			CommunicationPipe = new PipeUdpNet();
		}

		/// <summary>
		/// 指定服务器地址，端口号，客户端自己的站号来初始化<br />
		/// Specify the server address, port number, and client's own station number to initialize
		/// </summary>
		/// <param name="ipAddress">服务器的Ip地址</param>
		/// <param name="port">服务器的端口号</param>
		public MemobusUdpNet(string ipAddress, int port = 502)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MemobusUdpNet[{IpAddress}:{Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.YASKAWA.Helper
{
	/// <summary>
	/// Memobus协议的接口信息
	/// </summary>
	public interface IMemobus : IReadWriteDevice, IReadWriteNet
	{
		/// <summary>
		/// 获取或设置发送目标的CPU的编号信息，默认为 2<br />
		/// Get or set the CPU number information of the sending destination, the default is 2
		/// </summary>
		byte CpuTo { get; set; }

		/// <summary>
		/// 获取或设置发送源的CPU的编号信息，默认为 1<br />
		/// Get or set the number information of the sending source CPU, the default is 1
		/// </summary>
		byte CpuFrom { get; set; }
	}
	/// <summary>
	/// Memobus的辅助类对象
	/// </summary>
	public class MemobusHelper
	{
		internal static byte[] PackCommandWithHeader(byte[] command, long id)
		{
			byte[] array = new byte[12 + command.Length];
			array[0] = 17;
			array[1] = (byte)id;
			array[2] = 0;
			array[3] = 0;
			array[6] = BitConverter.GetBytes(array.Length)[0];
			array[7] = BitConverter.GetBytes(array.Length)[1];
			command.CopyTo(array, 12);
			return array;
		}

		internal static string GetErrorText(byte err)
		{
			return err switch
			{
				1 => StringResources.Language.Memobus01, 
				2 => StringResources.Language.Memobus02, 
				3 => StringResources.Language.Memobus03, 
				64 => StringResources.Language.Memobus40, 
				65 => StringResources.Language.Memobus41, 
				66 => StringResources.Language.Memobus42, 
				_ => StringResources.Language.UnknownError, 
			};
		}

		internal static OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			try
			{
				if (send.Length > 15 && response.Length > 15)
				{
					if (send[15] + 128 == response[15] && response.Length >= 18)
					{
						return new OResult<byte[]>(response[17], GetErrorText(response[17]) + " Source: " + response.ToHexString(' '));
					}
					if (send[15] != response[15])
					{
						return new OResult<byte[]>(response[15], "Send SFC not same as back SFC:" + response.ToHexString());
					}
				}
				return OResult.CreateSuccessResult(response.RemoveBegin(12));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("UnpackResponseContent failed: " + ex.Message + "  Source: " + response.ToHexString(' '));
			}
		}

		private static void SetByteHead(byte[] buffer, byte mfc, byte sfc, byte cpuTo, byte cpuFrom)
		{
			buffer[0] = BitConverter.GetBytes(buffer.Length - 2)[0];
			buffer[1] = BitConverter.GetBytes(buffer.Length - 2)[1];
			buffer[2] = mfc;
			buffer[3] = sfc;
			buffer[4] = (byte)((cpuTo << 4) + cpuFrom);
		}

		internal static byte GetAddressDataType(string address)
		{
			byte result = 77;
			if (address[0] == 'M' || address[0] == 'm')
			{
				result = 77;
			}
			else if (address[0] == 'G' || address[0] == 'g')
			{
				result = 71;
			}
			else if (address[0] == 'I' || address[0] == 'i')
			{
				result = 73;
			}
			else if (address[0] == 'O' || address[0] == 'o')
			{
				result = 79;
			}
			else if (address[0] == 'S' || address[0] == 's')
			{
				result = 83;
			}
			return result;
		}

		internal static int CalculateBoolIndex(string address)
		{
			address = ((address[1] != 'B' && address[1] != 'b') ? address.Substring(1) : address.Substring(2));
			int num = address.IndexOf('.');
			if (num > 0)
			{
				return Convert.ToInt32(address.Substring(0, num)) * 16 + SnetHelper.CalculateBitStartIndex(address.Substring(num + 1));
			}
			return Convert.ToInt32(address.Substring(0, address.Length - 1)) * 16 + SnetHelper.CalculateBitStartIndex(address.Substring(address.Length - 1));
		}

		/// <summary>
		/// 构建读取的命令报文，支持功能码 01,02,03,04,09,0A
		/// </summary>
		/// <param name="mfc">主功能码</param>
		/// <param name="sfc">子功能码</param>
		/// <param name="cpuTo">目标的CPU编号</param>
		/// <param name="cpuFrom">发送源CPU编号</param>
		/// <param name="address">起始地址</param>
		/// <param name="length">读取地址长度</param>
		/// <returns>结果报文信息</returns>
		internal static OResult<byte[]> BuildReadCommand(byte mfc, byte sfc, byte cpuTo, byte cpuFrom, string address, ushort length)
		{
			if (address.StartsWith(new string[5] { "M", "G", "I", "O", "S" }))
			{
				byte addressDataType = GetAddressDataType(address);
				if (address[1] == 'B' || address[1] == 'b' || address.IndexOf('.') > 0)
				{
					int value = CalculateBoolIndex(address);
					byte[] array = new byte[16];
					SetByteHead(array, 67, 65, cpuTo, cpuFrom);
					array[6] = addressDataType;
					BitConverter.GetBytes(value).CopyTo(array, 8);
					BitConverter.GetBytes(length).CopyTo(array, 12);
					return OResult.CreateSuccessResult(array);
				}
				byte[] array2 = new byte[14];
				SetByteHead(array2, 67, 73, cpuTo, cpuFrom);
				array2[6] = addressDataType;
				BitConverter.GetBytes(Convert.ToUInt32(address.Substring(1))).CopyTo(array2, 8);
				BitConverter.GetBytes(length).CopyTo(array2, 12);
				return OResult.CreateSuccessResult(array2);
			}
			if (!ushort.TryParse(address, out var result))
			{
				return new OResult<byte[]>("Address[" + address + "] wrong, not supported");
			}
			switch (sfc)
			{
			case 1:
			case 2:
			case 3:
			case 4:
			{
				byte[] array4 = new byte[9];
				SetByteHead(array4, mfc, sfc, cpuTo, cpuFrom);
				array4[5] = BitConverter.GetBytes(result)[1];
				array4[6] = BitConverter.GetBytes(result)[0];
				array4[7] = BitConverter.GetBytes(length)[1];
				array4[8] = BitConverter.GetBytes(length)[0];
				return OResult.CreateSuccessResult(array4);
			}
			case 9:
			case 10:
			{
				byte[] array3 = new byte[10];
				SetByteHead(array3, mfc, sfc, cpuTo, cpuFrom);
				array3[6] = BitConverter.GetBytes(result)[0];
				array3[7] = BitConverter.GetBytes(result)[1];
				array3[8] = BitConverter.GetBytes(length)[0];
				array3[9] = BitConverter.GetBytes(length)[1];
				return OResult.CreateSuccessResult(array3);
			}
			default:
				return new OResult<byte[]>($"SFC:{sfc} {StringResources.Language.NotSupportedFunction}");
			}
		}

		internal static OResult<byte[]> BuildReadRandomCommand(byte mfc, byte sfc, byte cpuTo, byte cpuFrom, ushort[] address)
		{
			byte[] array = new byte[8 + address.Length * 2];
			SetByteHead(array, mfc, sfc, cpuTo, cpuFrom);
			array[6] = BitConverter.GetBytes(address.Length)[0];
			array[7] = BitConverter.GetBytes(address.Length)[1];
			for (int i = 0; i < address.Length; i++)
			{
				array[8 + i * 2] = BitConverter.GetBytes(address[i])[0];
				array[8 + i * 2 + 1] = BitConverter.GetBytes(address[i])[1];
			}
			return OResult.CreateSuccessResult(array);
		}

		internal static OResult<byte[]> BuildReadRandomCommand(byte cpuTo, byte cpuFrom, string[] address)
		{
			byte[] array = new byte[8 + address.Length * 6];
			SetByteHead(array, 67, 77, cpuTo, cpuFrom);
			array[6] = BitConverter.GetBytes(address.Length)[0];
			array[7] = BitConverter.GetBytes(address.Length)[1];
			for (int i = 0; i < address.Length; i++)
			{
				byte addressDataType = GetAddressDataType(address[i]);
				array[8 + i * 6] = addressDataType;
				array[8 + i * 6 + 1] = 2;
				BitConverter.GetBytes(Convert.ToUInt32(address[i].Substring(1))).CopyTo(array, 8 + i * 6 + 2);
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建写入单一的线圈的状态变更的报文
		/// </summary>
		/// <param name="mfc">主功能码</param>
		/// <param name="sfc">子功能码</param>
		/// <param name="cpuTo">目标的CPU编号</param>
		/// <param name="cpuFrom">发送源CPU编号</param>
		/// <param name="address">起始地址</param>
		/// <param name="value">写入的通断值信息</param>
		/// <returns>写入的报文</returns>
		internal static OResult<byte[]> BuildWriteCommand(byte mfc, byte sfc, byte cpuTo, byte cpuFrom, ushort address, bool value)
		{
			byte[] array = new byte[9];
			SetByteHead(array, mfc, sfc, cpuTo, cpuFrom);
			array[5] = BitConverter.GetBytes(address)[1];
			array[6] = BitConverter.GetBytes(address)[0];
			array[7] = (byte)(value ? 255u : 0u);
			array[8] = 0;
			return OResult.CreateSuccessResult(array);
		}

		internal static OResult<byte[]> BuildWriteCommand(byte mfc, byte sfc, byte cpuTo, byte cpuFrom, string address, bool[] value)
		{
			if (address.StartsWith(new string[5] { "M", "G", "I", "O", "S" }))
			{
				byte addressDataType = GetAddressDataType(address);
				if (address[1] == 'B' || address[1] == 'b' || address.IndexOf('.') > 0)
				{
					int value2 = CalculateBoolIndex(address);
					byte[] array = new byte[16 + (value.Length + 7) / 8];
					SetByteHead(array, 67, 79, cpuTo, cpuFrom);
					array[6] = addressDataType;
					BitConverter.GetBytes(value2).CopyTo(array, 8);
					BitConverter.GetBytes(value.Length).CopyTo(array, 12);
					value.ToByteArray().CopyTo(array, 16);
					return OResult.CreateSuccessResult(array);
				}
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
			}
			if (!ushort.TryParse(address, out var result))
			{
				return new OResult<byte[]>("Address[" + address + "] wrong, not supported");
			}
			byte[] array2 = SoftBasic.BoolArrayToByte(value);
			byte[] array3 = new byte[9 + array2.Length];
			SetByteHead(array3, mfc, sfc, cpuTo, cpuFrom);
			array3[5] = BitConverter.GetBytes(result)[1];
			array3[6] = BitConverter.GetBytes(result)[0];
			array3[7] = BitConverter.GetBytes(value.Length)[1];
			array3[8] = BitConverter.GetBytes(value.Length)[0];
			array2.CopyTo(array3, 9);
			return OResult.CreateSuccessResult(array3);
		}

		internal static OResult<byte[]> BuildWriteCommand(byte mfc, byte sfc, byte cpuTo, byte cpuFrom, ushort address, short value)
		{
			byte[] array = new byte[9];
			SetByteHead(array, mfc, sfc, cpuTo, cpuFrom);
			array[5] = BitConverter.GetBytes(address)[1];
			array[6] = BitConverter.GetBytes(address)[0];
			array[7] = BitConverter.GetBytes(value)[1];
			array[8] = BitConverter.GetBytes(value)[0];
			return OResult.CreateSuccessResult(array);
		}

		internal static OResult<byte[]> BuildWriteCommand(byte mfc, byte sfc, byte cpuTo, byte cpuFrom, ushort address, ushort value)
		{
			byte[] array = new byte[9];
			SetByteHead(array, mfc, sfc, cpuTo, cpuFrom);
			array[5] = BitConverter.GetBytes(address)[1];
			array[6] = BitConverter.GetBytes(address)[0];
			array[7] = BitConverter.GetBytes(value)[1];
			array[8] = BitConverter.GetBytes(value)[0];
			return OResult.CreateSuccessResult(array);
		}

		internal static OResult<byte[]> BuildWriteCommand(byte mfc, byte sfc, byte cpuTo, byte cpuFrom, string address, byte[] value)
		{
			if (address.StartsWithAndNumber(new string[5] { "M", "G", "I", "O", "S" }))
			{
				byte addressDataType = GetAddressDataType(address);
				byte[] array = new byte[14 + value.Length];
				SetByteHead(array, 67, 75, cpuTo, cpuFrom);
				array[6] = addressDataType;
				BitConverter.GetBytes(Convert.ToUInt32(address.Substring(1))).CopyTo(array, 8);
				BitConverter.GetBytes(value.Length / 2).CopyTo(array, 12);
				SoftBasic.BytesReverseByWord(value).CopyTo(array, 14);
				return OResult.CreateSuccessResult(array);
			}
			if (!ushort.TryParse(address, out var result))
			{
				return new OResult<byte[]>("Address[" + address + "] wrong, not supported");
			}
			switch (sfc)
			{
			case 11:
			{
				byte[] array3 = new byte[10 + value.Length];
				SetByteHead(array3, mfc, sfc, cpuTo, cpuFrom);
				array3[6] = BitConverter.GetBytes(result)[0];
				array3[7] = BitConverter.GetBytes(result)[1];
				array3[8] = BitConverter.GetBytes(value.Length / 2)[0];
				array3[9] = BitConverter.GetBytes(value.Length / 2)[1];
				SoftBasic.BytesReverseByWord(value).CopyTo(array3, 10);
				return OResult.CreateSuccessResult(array3);
			}
			case 16:
			{
				byte[] array2 = new byte[9 + value.Length];
				SetByteHead(array2, mfc, sfc, cpuTo, cpuFrom);
				array2[5] = BitConverter.GetBytes(result)[1];
				array2[6] = BitConverter.GetBytes(result)[0];
				array2[7] = BitConverter.GetBytes(value.Length / 2)[1];
				array2[8] = BitConverter.GetBytes(value.Length / 2)[0];
				value.CopyTo(array2, 9);
				return OResult.CreateSuccessResult(array2);
			}
			default:
				return new OResult<byte[]>($"SFC:{sfc} {StringResources.Language.NotSupportedFunction}");
			}
		}

		internal static OResult<byte[]> BuildWriteRandomCommand(byte mfc, byte sfc, byte cpuTo, byte cpuFrom, ushort[] address, byte[] value)
		{
			if (value.Length != address.Length * 2)
			{
				return new OResult<byte[]>("value.Length must be twice as much as address.Length");
			}
			byte[] array = new byte[8 + address.Length * 4];
			SetByteHead(array, mfc, sfc, cpuTo, cpuFrom);
			array[6] = BitConverter.GetBytes(address.Length)[0];
			array[7] = BitConverter.GetBytes(address.Length)[1];
			for (int i = 0; i < address.Length; i++)
			{
				array[8 + i * 4] = BitConverter.GetBytes(address[i])[0];
				array[8 + i * 4 + 1] = BitConverter.GetBytes(address[i])[1];
				array[8 + i * 4 + 2] = value[i * 2 + 1];
				array[8 + i * 4 + 3] = value[i * 2];
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadBool(System.String,System.UInt16)" />
		/// <remarks>
		/// 默认使用功能码01，读取线圈操作，如果需要指定读取输入线圈，地址需要携带额外的参数，例如 x=2;100<br />
		/// The function code 01 is used by default to read the coil operation. If you need to specify the read input coil, the address needs to carry additional parameters, such as x=2;100
		/// </remarks>
		public static OResult<bool[]> ReadBool(IMemobus memobus, string address, ushort length)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte sfc = (byte)SnetHelper.ExtractParameter(ref address, "x", 1);
			OResult<byte[]> oResult = BuildReadCommand(mfc, sfc, memobus.CpuTo, memobus.CpuFrom, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			if (oResult2.Content[3] == 65)
			{
				return OResult.CreateSuccessResult(oResult2.Content.RemoveBegin(8).ToBoolArray().SelectBegin(length));
			}
			return OResult.CreateSuccessResult(oResult2.Content.RemoveBegin(5).ToBoolArray().SelectBegin(length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean)" />
		/// <remarks>
		/// 单一线圈的状态变更，使用的主功能码为0x20, 子功能码为0x05<br />
		/// The status of a single coil is changed, the main function code used is 0x20, and the sub function code is 0x05
		/// </remarks>
		public static OResult Write(IMemobus memobus, string address, bool value)
		{
			if (address.StartsWith(new string[5] { "M", "G", "I", "O", "S" }))
			{
				return Write(memobus, address, new bool[1] { value });
			}
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte sfc = (byte)SnetHelper.ExtractParameter(ref address, "x", 5);
			OResult<byte[]> oResult = BuildWriteCommand(mfc, sfc, memobus.CpuTo, memobus.CpuFrom, ushort.Parse(address), value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean[])" />
		/// <remarks>
		/// 多个线圈的状态更改，默认使用的是 0x0f 子功能码。<br />
		/// The status of multiple coils is changed, and the sub-function code 0x0f is used by default.
		/// </remarks>
		public static OResult Write(IMemobus memobus, string address, bool[] value)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte sfc = (byte)SnetHelper.ExtractParameter(ref address, "x", 15);
			OResult<byte[]> oResult = BuildWriteCommand(mfc, sfc, memobus.CpuTo, memobus.CpuFrom, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult();
		}

		private static OResult<byte[]> ExtraContent(string address, byte[] content)
		{
			if (content[2] == 32)
			{
				if (content[3] == 3 || content[3] == 4)
				{
					return OResult.CreateSuccessResult(content.RemoveBegin(5));
				}
				if (content[3] == 9 || content[3] == 10)
				{
					return OResult.CreateSuccessResult(SoftBasic.BytesReverseByWord(content.RemoveBegin(8)));
				}
				return OResult.CreateSuccessResult(content.RemoveBegin(5));
			}
			if (content[2] == 67)
			{
				if (content[3] == 73 || content[3] == 77)
				{
					return OResult.CreateSuccessResult(SoftBasic.BytesReverseByWord(content.RemoveBegin(10)));
				}
				return OResult.CreateSuccessResult(content.RemoveBegin(8));
			}
			return new OResult<byte[]>($"[{address}], mfc[{content[2]}] is not supported");
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Read(System.String,System.UInt16)" />
		/// <remarks>
		/// 地址默认使用功能码03，如果需要指定其他的功能码地址，需要手动指定功能码，例如：x=4;100, x=9;100, x=10;100, 当然也可以写成 x=0x0A;100<br />
		/// The address uses function code 03 by default. If you need to specify other function code addresses, 
		/// you need to manually specify the function code, for example: x=4;100, x=9;100, x=10;100, of course, it can also be written as x=0x0A; 100
		/// </remarks>
		public static OResult<byte[]> Read(IMemobus memobus, string address, ushort length)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte sfc = (byte)SnetHelper.ExtractParameter(ref address, "x", 3);
			OResult<byte[]> oResult = BuildReadCommand(mfc, sfc, memobus.CpuTo, memobus.CpuFrom, address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return ExtraContent(address, oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Byte[])" />
		/// <remarks>
		/// 连续的寄存器写入操作，默认功能码是0x10，如果需要写入扩展的寄存器，使用 x=0xA;100 或是 x=10;100 即可。<br />
		/// For continuous register write operation, the default function code is 0x10. If you need to write an extended register, use x=0xA;100 or x=10;100.
		/// </remarks>
		public static OResult Write(IMemobus memobus, string address, byte[] value)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte b = (byte)SnetHelper.ExtractParameter(ref address, "x", 16);
			if (b == 3)
			{
				b = 16;
			}
			if (b == 9)
			{
				b = 11;
			}
			OResult<byte[]> oResult = BuildWriteCommand(mfc, b, memobus.CpuTo, memobus.CpuFrom, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Int16)" />
		/// <remarks>
		/// 单一保持寄存器的值变更，使用的主功能码为0x20, 默认子功能码为0x06，也可以写入扩展的保持型寄存器，子功能码为0x0B<br />
		/// The value of a single hold register is changed, using a primary function code of 0x20 and a default subfunction code of 0x06, or an extended holding register with a subfunction code of 0x0B
		/// </remarks>
		public static OResult Write(IMemobus memobus, string address, short value, Func<string, short, OResult> writeShort)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte b = (byte)SnetHelper.ExtractParameter(ref address, "x", 6);
			switch (b)
			{
			case 9:
			case 11:
				return writeShort($"x={b};{address}", value);
			case 3:
				b = 6;
				break;
			}
			OResult<byte[]> oResult = BuildWriteCommand(mfc, b, memobus.CpuTo, memobus.CpuFrom, ushort.Parse(address), value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.UInt16)" />
		/// <remarks>
		/// 单一保持寄存器的值变更，使用的主功能码为0x20, 默认子功能码为0x06<br />
		/// The value of a single hold register changes, using a primary function code of 0x20 and a default subfunction code of 0x06
		/// </remarks>
		public static OResult Write(IMemobus memobus, string address, ushort value, Func<string, ushort, OResult> writeUShort)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte b = (byte)SnetHelper.ExtractParameter(ref address, "x", 6);
			switch (b)
			{
			case 9:
			case 11:
				return writeUShort($"x={b};{address}", value);
			case 3:
				b = 6;
				break;
			}
			OResult<byte[]> oResult = BuildWriteCommand(mfc, b, memobus.CpuTo, memobus.CpuFrom, ushort.Parse(address), value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 随机读取扩展的保持寄存器的内容，也即读取不连续地址的字数据，可以指定多个地址，然后一次性读取所有的数据，然后解析出实际的数据<br />
		/// Randomly read the contents of the extended hold register, that is, read word data of discontinuous addresses, 
		/// you can specify multiple addresses, then read all the data at once, and then parse out the actual data
		/// </summary>
		/// <remarks>
		/// 注意，本方法只能针对扩展的保持寄存器进行读取
		/// </remarks>
		/// <param name="memobus">PLC通信对象</param>
		/// <param name="address">地址信息</param>
		/// <returns>读取的原始字节结果信息</returns>
		public static OResult<byte[]> ReadRandom(IMemobus memobus, ushort[] address)
		{
			OResult<byte[]> oResult = BuildReadRandomCommand(32, 13, memobus.CpuTo, memobus.CpuFrom, address);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult(SoftBasic.BytesReverseByWord(oResult2.Content.RemoveBegin(8)));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.YASKAWA.Helper.MemobusHelper.ReadRandom(Snet.Driver.Profinet.YASKAWA.Helper.IMemobus,System.UInt16[])" />
		/// <remarks>
		/// 本方法的地址支持 保持寄存器 M100, 数据寄存器 G100, 输入寄存器 I100, 输出寄存器 O100, 系统寄存器 S100,
		/// </remarks>
		public static OResult<byte[]> ReadRandom(IMemobus memobus, string[] address)
		{
			OResult<byte[]> oResult = BuildReadRandomCommand(memobus.CpuTo, memobus.CpuFrom, address);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult(SoftBasic.BytesReverseByWord(oResult2.Content.RemoveBegin(8)));
		}

		/// <summary>
		/// 随机写入扩展的保持寄存器的内容，也即写入不连续的地址的字数据，字节数组的长度必须为地址数组长度的两倍，才能正确写入。<br />
		/// Write the contents of the extended hold registers randomly, that is, write word data for discontinuous addresses,
		/// and the byte array must be twice the length of the address array to be written correctly.
		/// </summary>
		/// <remarks>
		/// 注意，本方法只能针对扩展的保持寄存器进行读取
		/// </remarks>
		/// <param name="memobus">PLC通信对象</param>
		/// <param name="address">地址信息</param>
		/// <param name="value">数据信息</param>
		/// <returns>是否写入成功的结果对象</returns>
		public static OResult WriteRandom(IMemobus memobus, ushort[] address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteRandomCommand(32, 14, memobus.CpuTo, memobus.CpuFrom, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = memobus.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.YASKAWA.Helper.MemobusHelper.ReadBool(Snet.Driver.Profinet.YASKAWA.Helper.IMemobus,System.String,System.UInt16)" />
		public static async Task<OResult<bool[]>> ReadBoolAsync(IMemobus memobus, string address, ushort length)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte sfc = (byte)SnetHelper.ExtractParameter(ref address, "x", 1);
			OResult<byte[]> oResult = BuildReadCommand(mfc, sfc, memobus.CpuTo, memobus.CpuFrom, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = await memobus.ReadFromCoreServerAsync(oResult.Content).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			if (oResult2.Content[3] == 65)
			{
				return OResult.CreateSuccessResult(oResult2.Content.RemoveBegin(8).ToBoolArray().SelectBegin(length));
			}
			return OResult.CreateSuccessResult(oResult2.Content.RemoveBegin(5).ToBoolArray().SelectBegin(length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.YASKAWA.Helper.MemobusHelper.Write(Snet.Driver.Profinet.YASKAWA.Helper.IMemobus,System.String,System.Boolean)" />
		public static async Task<OResult> WriteAsync(IMemobus memobus, string address, bool value)
		{
			if (address.StartsWith(new string[5] { "M", "G", "I", "O", "S" }))
			{
				return await WriteAsync(memobus, address, new bool[1] { value }).ConfigureAwait(continueOnCapturedContext: false);
			}
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte sfc = (byte)SnetHelper.ExtractParameter(ref address, "x", 5);
			OResult<byte[]> oResult = BuildWriteCommand(mfc, sfc, memobus.CpuTo, memobus.CpuFrom, ushort.Parse(address), value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await memobus.ReadFromCoreServerAsync(oResult.Content).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult();
		}

