		public static async Task<OResult> WriteAsync(IMemobus memobus, string address, byte[] value)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte b = (byte)SnetHelper.ExtractParameter(ref address, "x", 16);
			if (b == 3)
			{
				b = 16;
			}
			if (b == 9)
			{
				b = 11;
			}
			OResult<byte[]> oResult = BuildWriteCommand(mfc, b, memobus.CpuTo, memobus.CpuFrom, address, value);
			if (!oResult.IsSuccess)
			{
