		public static async Task<OResult> WriteAsync(IMemobus memobus, string address, short value, Func<string, short, Task<OResult>> writeShort)
		{
			byte mfc = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
			byte b = (byte)SnetHelper.ExtractParameter(ref address, "x", 6);
			switch (b)
			{
			case 9:
			case 11:
				return await writeShort($"x={b};{address}", value);
			case 3:
				b = 6;
