	/// <summary>
	/// 山武的数字指示调节器的虚拟设备，支持和Snet本身进行数据通信测试<br />
	/// Yamatake’s digital indicating regulator is a virtual device that supports data communication testing with Snet itself
	/// </summary>
	public class DigitronCPLServer : DeviceServer
	{
		private SoftBuffer softBuffer;

		private const int DataPoolLength = 65536;

		/// <summary>
		/// 获取或设置当前虚拟仪表的站号信息，如果站号不一致，将不予访问<br />
		/// Get or set the station number information of the current virtual instrument. If the station number is inconsistent, it will not be accessed
		/// </summary>
		public byte Station { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public DigitronCPLServer()
		{
			softBuffer = new SoftBuffer(131072);
			base.ByteTransform = new RegularByteTransform();
			Station = 1;
			LogMsgFormatBinary = false;
			base.SerialReceiveAtleastTime = 1000;
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			try
			{
				ushort num = ushort.Parse(address);
				return OResult.CreateSuccessResult(softBuffer.GetBytes(num * 2, length * 2));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Read Failed: " + ex.Message);
			}
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			try
			{
				ushort num = ushort.Parse(address);
				softBuffer.SetBytes(value, num * 2);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				return new OResult("Write Failed: " + ex.Message);
			}
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SpecifiedCharacterMessage(10);
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			return OResult.CreateSuccessResult(ReadFromCore(session, receive));
		}

		private byte[] ReadFromCore(PipeSession session, byte[] command)
		{
			try
			{
				int num = 9;
				for (int i = 9; i < command.Length; i++)
				{
					if (command[i] == 3)
					{
						num = i;
						break;
					}
				}
				byte b = Convert.ToByte(Encoding.ASCII.GetString(command, 1, 2), 16);
				if (b != Station)
				{
					base.LogNet?.WriteDebug(ToString(), $"<{session.Communication}> Station not same, need: {Station} but {b}");
					return DigitronCPLHelper.PackResponseContent(Station, 40, null, 87);
				}
				string[] array = Encoding.ASCII.GetString(command, 9, num - 9).Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries);
				string text = Encoding.ASCII.GetString(command, 6, 2);
				int num2 = int.Parse(array[0].Substring(0, array[0].Length - 1));
				byte b2 = (byte)(array[0].EndsWith("W") ? 87u : 83u);
				if (num2 >= 65536 || num2 < 0)
				{
					return DigitronCPLHelper.PackResponseContent(Station, 42, null, b2);
				}
				if (text == "RS")
				{
					int num3 = int.Parse(array[1]);
					if (num2 + num3 > 65535)
					{
						return DigitronCPLHelper.PackResponseContent(Station, 42, null, b2);
					}
					if (num3 > 16)
					{
						return DigitronCPLHelper.PackResponseContent(Station, 41, null, b2);
					}
					return DigitronCPLHelper.PackResponseContent(Station, 0, softBuffer.GetBytes(num2 * 2, num3 * 2), b2);
				}
				if (text == "WS")
				{
					if (!base.EnableWrite)
					{
						return DigitronCPLHelper.PackResponseContent(Station, 46, null, b2);
					}
					if (array.Length > 17)
					{
						return DigitronCPLHelper.PackResponseContent(Station, 41, null, b2);
					}
					byte[] array2 = new byte[(array.Length - 1) * 2];
					for (int j = 1; j < array.Length; j++)
					{
						if (b2 == 87)
						{
							BitConverter.GetBytes(short.Parse(array[j])).CopyTo(array2, j * 2 - 2);
						}
						else
						{
							BitConverter.GetBytes(ushort.Parse(array[j])).CopyTo(array2, j * 2 - 2);
						}
					}
					softBuffer.SetBytes(array2, num2 * 2);
					return DigitronCPLHelper.PackResponseContent(Station, 0, null, b2);
				}
				return DigitronCPLHelper.PackResponseContent(Station, 40, null, b2);
			}
			catch
			{
				return null;
			}
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			if (receivedLength > 5)
			{
				if (buffer[receivedLength - 2] == 13)
				{
					return buffer[receivedLength - 1] == 10;
				}
				return false;
			}
			return base.CheckSerialReceiveDataComplete(buffer, receivedLength);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"DigitronCPLServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Yamatake.Helper
{
	/// <summary>
	/// 辅助类方法
	/// </summary>
	public class DigitronCPLHelper
	{
		/// <summary>
		/// 构建写入操作的报文信息
		/// </summary>
		/// <param name="station">站号</param>
		/// <param name="address">地址</param>
		/// <param name="length">长度的长度</param>
		/// <returns>报文内容</returns>
		public static OResult<byte[]> BuildReadCommand(byte station, string address, ushort length)
		{
			try
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append('\u0002');
				stringBuilder.Append(station.ToString("X2"));
				stringBuilder.Append("00XRS,");
				stringBuilder.Append(ushort.Parse(address).ToString());
				stringBuilder.Append("W,");
				stringBuilder.Append(length.ToString());
				stringBuilder.Append('\u0003');
				int num = 0;
				for (int i = 0; i < stringBuilder.Length; i++)
				{
					num += stringBuilder[i];
				}
				stringBuilder.Append(((byte)(256 - num % 256)).ToString("X2"));
				stringBuilder.Append("\r\n");
				return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address wrong: " + ex.Message);
			}
		}

		/// <summary>
		/// 构建写入操作的命令报文
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">数据的地址</param>
		/// <param name="value">等待写入的值</param>
		/// <returns>写入的报文命令</returns>
		public static OResult<byte[]> BuildWriteCommand(byte station, string address, byte[] value)
		{
			try
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append('\u0002');
				stringBuilder.Append(station.ToString("X2"));
				stringBuilder.Append("00XWS,");
				stringBuilder.Append(ushort.Parse(address).ToString());
				stringBuilder.Append("W");
				for (int i = 0; i < value.Length / 2; i++)
				{
					short num = BitConverter.ToInt16(value, i * 2);
					stringBuilder.Append(",");
					stringBuilder.Append(num.ToString());
				}
				stringBuilder.Append('\u0003');
				int num2 = 0;
				for (int j = 0; j < stringBuilder.Length; j++)
				{
					num2 += stringBuilder[j];
				}
				stringBuilder.Append(((byte)(256 - num2 % 256)).ToString("X2"));
				stringBuilder.Append("\r\n");
				return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address wrong: " + ex.Message);
			}
		}

		/// <summary>
		/// 用于服务器反馈的数据的报文打包操作
		/// </summary>
		/// <param name="station">站号</param>
		/// <param name="err">错误码，如果为0则表示正常</param>
		/// <param name="value">原始数据值信息</param>
		/// <param name="dataType">数据类型</param>
		/// <returns>打包的报文数据信息</returns>
		public static byte[] PackResponseContent(byte station, int err, byte[] value, byte dataType)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append('\u0002');
			stringBuilder.Append(station.ToString("X2"));
			stringBuilder.Append("00X");
			stringBuilder.Append(err.ToString("D2"));
			if (err == 0 && value != null)
			{
				for (int i = 0; i < value.Length / 2; i++)
				{
					if (dataType == 87)
					{
						short num = BitConverter.ToInt16(value, i * 2);
						stringBuilder.Append(",");
						stringBuilder.Append(num.ToString());
					}
					else
					{
						ushort num2 = BitConverter.ToUInt16(value, i * 2);
						stringBuilder.Append(",");
						stringBuilder.Append(num2.ToString());
					}
				}
			}
			stringBuilder.Append('\u0003');
			int num3 = 0;
			for (int j = 0; j < stringBuilder.Length; j++)
			{
				num3 += stringBuilder[j];
			}
			stringBuilder.Append(((byte)(256 - num3 % 256)).ToString("X2"));
			stringBuilder.Append("\r\n");
			return Encoding.ASCII.GetBytes(stringBuilder.ToString());
		}

		/// <summary>
		/// 根据错误码获取到相关的错误代号信息
		/// </summary>
		/// <param name="err">错误码</param>
		/// <returns>错误码对应的文本描述信息</returns>
		public static string GetErrorText(int err)
		{
			return err switch
			{
				40 => StringResources.Language.YamatakeDigitronCPL40, 
				41 => StringResources.Language.YamatakeDigitronCPL41, 
				42 => StringResources.Language.YamatakeDigitronCPL42, 
				43 => StringResources.Language.YamatakeDigitronCPL43, 
				44 => StringResources.Language.YamatakeDigitronCPL44, 
				45 => StringResources.Language.YamatakeDigitronCPL45, 
				46 => StringResources.Language.YamatakeDigitronCPL46, 
				47 => StringResources.Language.YamatakeDigitronCPL47, 
				48 => StringResources.Language.YamatakeDigitronCPL48, 
				99 => StringResources.Language.YamatakeDigitronCPL99, 
				_ => StringResources.Language.UnknownError, 
			};
		}

		/// <summary>
		/// 从反馈的数据内容中解析出真实的数据信息
		/// </summary>
		/// <param name="response">仪表反馈的真实的数据信息</param>
		/// <returns>解析之后的实际数据信息</returns>
		public static OResult<byte[]> ExtraActualResponse(byte[] response)
		{
			try
			{
				int num = Convert.ToInt32(Encoding.ASCII.GetString(response, 6, 2));
				if (num > 0)
				{
					return new OResult<byte[]>(num, GetErrorText(num));
				}
				int num2 = 8;
				for (int i = 8; i < response.Length; i++)
				{
					if (response[i] == 3)
					{
						num2 = i;
						break;
					}
				}
				int num3 = ((response[8] == 44) ? 9 : 8);
				if (num2 - num3 > 0)
				{
					short[] array = (from m in Encoding.ASCII.GetString(response, num3, num2 - num3).Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries)
						select short.Parse(m)).ToArray();
					byte[] array2 = new byte[array.Length * 2];
					for (int num4 = 0; num4 < array.Length; num4++)
					{
						BitConverter.GetBytes(array[num4]).CopyTo(array2, num4 * 2);
					}
					return OResult.CreateSuccessResult(array2);
				}
				return OResult.CreateSuccessResult(new byte[0]);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Data wrong: " + ex.Message + Environment.NewLine + "Source: " + response.ToHexString(' '));
			}
		}
	}
}
namespace Snet.Driver.Profinet.XINJE
{
	/// <summary>
	/// 信捷PLC的相关辅助类
	/// </summary>
	public class XinJEHelper
	{
		private static int CalculateXinJEStartAddress(string address)
		{
			if (address.IndexOf('.') < 0)
			{
				return Convert.ToInt32(address, 8);
			}
			string[] array = address.SplitDot();
			return Convert.ToInt32(array[0], 8) * 8 + int.Parse(array[1]);
		}

		/// <summary>
		/// 根据信捷PLC的地址，解析出转换后的modbus协议信息
		/// </summary>
		/// <param name="series">PLC的系列信息</param>
		/// <param name="address">汇川plc的地址信息</param>
		/// <param name="modbusCode">原始的对应的modbus信息</param>
		/// <returns>还原后的modbus地址</returns>
		public static OResult<string> PraseXinJEAddress(XinJESeries series, string address, byte modbusCode)
		{
			string text = string.Empty;
			OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
			if (oResult.IsSuccess)
			{
				text = $"s={oResult.Content};";
			}
			string text2 = string.Empty;
			OResult<int> oResult2 = SnetHelper.ExtractParameter(ref address, "x");
			if (oResult2.IsSuccess)
			{
				text2 = $"x={oResult2.Content};";
			}
			if (series == XinJESeries.XC)
			{
				try
				{
					if ((Regex.IsMatch(address, "^X[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^Y[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^M[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^S[0-9]+", RegexOptions.IgnoreCase)) && modbusCode == 3)
					{
						modbusCode = 1;
						text2 = "x=1;";
					}
				}
				catch
				{
				}
				return PraseXinJEXCAddress(text + text2, address, modbusCode);
			}
			try
			{
				if ((Regex.IsMatch(address, "^X[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^Y[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^M[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^S[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^SEM[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^HSC[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^SM[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^ET[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^HM[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^HS[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^HT[0-9]+", RegexOptions.IgnoreCase) || Regex.IsMatch(address, "^HC[0-9]+", RegexOptions.IgnoreCase)) && modbusCode == 3)
				{
					modbusCode = 1;
					text2 = "x=1;";
				}
			}
			catch
			{
			}
			return PraseXinJEXD1XD2XD3XL1XL3Address(text + text2, address, modbusCode);
		}

		private static int CalculateXC_D(string address)
		{
			int num = Convert.ToInt32(address);
			if (num >= 8000)
			{
				return num - 8000 + 16384;
			}
			return num;
		}

		/// <summary>
		/// 根据信捷PLC的地址，解析出转换后的modbus协议信息，适用XC系列
		/// </summary>
		/// <param name="station">站号的特殊指定信息，可以为空</param>
		/// <param name="address">信捷plc的地址信息</param>
		/// <param name="modbusCode">原始的对应的modbus信息</param>
		/// <returns>还原后的modbus地址</returns>
		public static OResult<string> PraseXinJEXCAddress(string station, string address, byte modbusCode)
		{
			try
			{
				if (modbusCode == 1 || modbusCode == 2 || modbusCode == 15 || modbusCode == 5)
				{
					if (ModbusHelper.TransAddressToModbus(station, address, new string[2] { "X", "Y" }, new int[2] { 16384, 18432 }, CalculateXinJEStartAddress, out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
					if (ModbusHelper.TransAddressToModbus(station, address, new string[3] { "S", "T", "C" }, new int[3] { 20480, 25600, 27648 }, out string newAddress2))
					{
						return OResult.CreateSuccessResult(newAddress2);
					}
					if (address.StartsWithAndNumber("M"))
					{
						int num = Convert.ToInt32(address.Substring(1));
						if (num >= 8000)
						{
							return OResult.CreateSuccessResult(station + (num - 8000 + 24576));
						}
						return OResult.CreateSuccessResult(station + num);
					}
					if (ModbusHelper.TransPointAddressToModbus(station, address, new string[1] { "D" }, new int[1], CalculateXC_D, out string newAddress3))
					{
						return OResult.CreateSuccessResult(newAddress3);
					}
				}
				else
				{
					if (address.StartsWithAndNumber("D"))
					{
						return OResult.CreateSuccessResult(station + CalculateXC_D(address.Substring(1)));
					}
					if (address.StartsWithAndNumber("F"))
					{
						int num2 = Convert.ToInt32(address.Substring(1));
						if (num2 >= 8000)
						{
							return OResult.CreateSuccessResult(station + (num2 - 8000 + 26624));
						}
						return OResult.CreateSuccessResult(station + (num2 + 18432));
					}
					if (ModbusHelper.TransAddressToModbus(station, address, new string[3] { "E", "T", "C" }, new int[3] { 28672, 12288, 14336 }, out string newAddress4))
					{
						return OResult.CreateSuccessResult(newAddress4);
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}

		/// <summary>
		/// 解析信捷的XD1,XD2,XD3,XL1,XL3系列的PLC的Modbus地址和内部软元件的对照
		/// </summary>
		/// <remarks>适用 XD1、XD2、XD3、XL1、XL3、XD5、XDM、XDC、XD5E、XDME、XL5、XL5E、XLME, XDH 只是支持的地址范围不一样而已</remarks>
		/// <param name="station">站号的特殊指定信息，可以为空</param>
		/// <param name="address">PLC内部的软元件的地址</param>
		/// <param name="modbusCode">默认的Modbus功能码</param>
		/// <returns>解析后的Modbus地址</returns>
		public static OResult<string> PraseXinJEXD1XD2XD3XL1XL3Address(string station, string address, byte modbusCode)
		{
			try
			{
				if (modbusCode == 1 || modbusCode == 2 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWith("X") || address.StartsWith("x"))
					{
						int num = CalculateXinJEStartAddress(address.Substring(1));
						if (num < 4096)
						{
							return OResult.CreateSuccessResult(station + (num + 20480));
						}
						if (num < 8192)
						{
							return OResult.CreateSuccessResult(station + (num - 4096 + 20736));
						}
						if (num < 12288)
						{
							return OResult.CreateSuccessResult(station + (num - 8192 + 22736));
						}
						return OResult.CreateSuccessResult(station + (num - 12288 + 23536));
					}
					if (address.StartsWith("Y") || address.StartsWith("y"))
					{
						int num2 = CalculateXinJEStartAddress(address.Substring(1));
						if (num2 < 4096)
						{
							return OResult.CreateSuccessResult(station + (num2 + 24576));
						}
						if (num2 < 8192)
						{
							return OResult.CreateSuccessResult(station + (num2 - 4096 + 24832));
						}
						if (num2 < 12288)
						{
							return OResult.CreateSuccessResult(station + (num2 - 8192 + 26832));
						}
						return OResult.CreateSuccessResult(station + (num2 - 12288 + 27632));
					}
					if (ModbusHelper.TransAddressToModbus(station, address, new string[12]
					{
						"SEM", "HSC", "SM", "ET", "HM", "HS", "HT", "HC", "S", "T",
						"C", "M"
					}, new int[12]
					{
						49280, 59648, 36864, 49152, 49408, 55552, 57600, 58624, 28672, 40960,
						45056, 0
					}, out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
					if (ModbusHelper.TransPointAddressToModbus(station, address, new string[3] { "D", "SD", "HD" }, new int[3] { 0, 28672, 41088 }, out string newAddress2))
					{
						return OResult.CreateSuccessResult(newAddress2);
					}
				}
				else
				{
					if (address.StartsWith("ID") || address.StartsWith("id"))
					{
						int num3 = Convert.ToInt32(address.Substring(2));
						if (num3 < 10000)
						{
							return OResult.CreateSuccessResult(station + (num3 + 20480));
						}
						if (num3 < 20000)
						{
							return OResult.CreateSuccessResult(station + (num3 - 10000 + 20736));
						}
						if (num3 < 30000)
						{
							return OResult.CreateSuccessResult(station + (num3 - 20000 + 22736));
						}
						return OResult.CreateSuccessResult(station + (num3 - 30000 + 23536));
					}
					if (address.StartsWith("QD") || address.StartsWith("qd"))
					{
						int num4 = Convert.ToInt32(address.Substring(2));
						if (num4 < 10000)
						{
							return OResult.CreateSuccessResult(station + (num4 + 24576));
						}
						if (num4 < 20000)
						{
							return OResult.CreateSuccessResult(station + (num4 - 10000 + 24832));
						}
						if (num4 < 30000)
						{
							return OResult.CreateSuccessResult(station + (num4 - 20000 + 26832));
						}
						return OResult.CreateSuccessResult(station + (num4 - 30000 + 27632));
					}
					if (ModbusHelper.TransAddressToModbus(station, address, new string[13]
					{
						"HSCD", "ETD", "HSD", "HTD", "HCD", "SFD", "SD", "TD", "CD", "HD",
						"FD", "FS", "D"
					}, new int[13]
					{
						50304, 40960, 47232, 48256, 49280, 58560, 28672, 32768, 36864, 41088,
						50368, 62656, 0
					}, out string newAddress3))
					{
						return OResult.CreateSuccessResult(newAddress3);
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}

		internal static OResult<List<byte[]>> BuildReadCommand(byte station, string address, ushort length, bool isBit)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, station);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			return BuildReadCommand(oResult.Content, length, isBit);
		}

		internal static OResult<List<byte[]>> BuildReadCommand(XinJEAddress address, ushort length, bool isBit)
		{
			List<byte[]> list = new List<byte[]>();
			int[] array = SoftBasic.SplitIntegerToArray(length, isBit ? 1920 : 120);
			for (int i = 0; i < array.Length; i++)
			{
				byte[] item = new byte[8]
				{
					address.Station,
					(byte)(isBit ? 30u : 32u),
					address.DataCode,
					BitConverter.GetBytes(address.AddressStart)[2],
					BitConverter.GetBytes(address.AddressStart)[1],
					BitConverter.GetBytes(address.AddressStart)[0],
					BitConverter.GetBytes(array[i])[1],
					BitConverter.GetBytes(array[i])[0]
				};
				address.AddressStart += array[i];
				list.Add(item);
			}
			return OResult.CreateSuccessResult(list);
		}

		internal static OResult<byte[]> BuildWriteWordCommand(byte station, string address, byte[] value)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, station);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return BuildWriteWordCommand(oResult.Content, value);
		}

		internal static OResult<byte[]> BuildWriteWordCommand(XinJEAddress address, byte[] value)
		{
			byte[] array = new byte[9 + value.Length];
			array[0] = address.Station;
			array[1] = 33;
			array[2] = address.DataCode;
			array[3] = BitConverter.GetBytes(address.AddressStart)[2];
			array[4] = BitConverter.GetBytes(address.AddressStart)[1];
			array[5] = BitConverter.GetBytes(address.AddressStart)[0];
			array[6] = BitConverter.GetBytes(value.Length / 2)[1];
			array[7] = BitConverter.GetBytes(value.Length / 2)[0];
			array[8] = (byte)value.Length;
			value.CopyTo(array, 9);
			return OResult.CreateSuccessResult(array);
		}

		internal static OResult<byte[]> BuildWriteBoolCommand(byte station, string address, bool[] value)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, station);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return BuildWriteBoolCommand(oResult.Content, value);
		}

		internal static OResult<byte[]> BuildWriteBoolCommand(XinJEAddress address, bool[] value)
		{
			byte[] array = value.ToByteArray();
			byte[] array2 = new byte[9 + array.Length];
			array2[0] = address.Station;
			array2[1] = 31;
			array2[2] = address.DataCode;
			array2[3] = BitConverter.GetBytes(address.AddressStart)[2];
			array2[4] = BitConverter.GetBytes(address.AddressStart)[1];
			array2[5] = BitConverter.GetBytes(address.AddressStart)[0];
			array2[6] = BitConverter.GetBytes(value.Length)[1];
			array2[7] = BitConverter.GetBytes(value.Length)[0];
			array2[8] = (byte)array.Length;
			array.CopyTo(array2, 9);
			return OResult.CreateSuccessResult(array2);
		}

		internal static OResult<byte[]> Read(IModbus modbus, string address, ushort length, Func<string, ushort, OResult<byte[]>> funcRead)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, length, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return funcRead(address, length);
			}
			XinJEAddress content = oResult.Content;
			if (content.AddressStart + length <= content.CriticalAddress)
			{
				return funcRead(address, length);
			}
			List<byte> list = new List<byte>();
			if (content.AddressStart < content.CriticalAddress)
			{
				OResult<byte[]> oResult2 = funcRead(address, (ushort)(content.CriticalAddress - content.AddressStart));
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				list.AddRange(oResult2.Content);
				length = (ushort)(length - (content.CriticalAddress - content.AddressStart));
				content.AddressStart = content.CriticalAddress;
			}
			OResult<List<byte[]>> oResult3 = BuildReadCommand(content, length, isBit: false);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			OResult<byte[]> oResult4 = modbus.ReadFromCoreServer(oResult3.Content);
			if (!oResult4.IsSuccess)
			{
				return oResult4;
			}
			list.AddRange(oResult4.Content);
			return OResult.CreateSuccessResult(list.ToArray());
		}

		internal static OResult Write(IModbus modbus, string address, byte[] value, Func<string, byte[], OResult> funcWrite)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return funcWrite(address, value);
			}
			XinJEAddress content = oResult.Content;
			if (content.AddressStart + value.Length / 2 <= content.CriticalAddress)
			{
				return funcWrite(address, value);
			}
			if (content.AddressStart < content.CriticalAddress)
			{
				OResult oResult2 = funcWrite(address, value.SelectBegin((content.CriticalAddress - content.AddressStart) * 2));
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				value = value.RemoveBegin((content.CriticalAddress - content.AddressStart) * 2);
				content.AddressStart = content.CriticalAddress;
			}
			OResult<byte[]> oResult3 = BuildWriteWordCommand(content, value);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return modbus.ReadFromCoreServer(oResult3.Content);
		}

		internal static OResult Write(IModbus modbus, string address, short value, Func<string, short, OResult> funcWrite)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return funcWrite(address, value);
			}
			XinJEAddress content = oResult.Content;
			if (content.AddressStart < content.CriticalAddress)
			{
				return funcWrite(address, value);
			}
			return modbus.Write(address, modbus.ByteTransform.TransByte(value));
		}

		internal static OResult Write(IModbus modbus, string address, ushort value, Func<string, ushort, OResult> funcWrite)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return funcWrite(address, value);
			}
			XinJEAddress content = oResult.Content;
			if (content.AddressStart < content.CriticalAddress)
			{
				return funcWrite(address, value);
			}
			return modbus.Write(address, modbus.ByteTransform.TransByte(value));
		}

		internal static OResult<bool[]> ReadBool(IModbus modbus, string address, ushort length, Func<string, ushort, OResult<bool[]>> funcRead)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, length, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return funcRead(address, length);
			}
			XinJEAddress content = oResult.Content;
			if (content.AddressStart + length <= content.CriticalAddress)
			{
				return funcRead(address, length);
			}
			List<bool> list = new List<bool>();
			if (content.AddressStart < content.CriticalAddress)
			{
				OResult<bool[]> oResult2 = funcRead(address, (ushort)(content.CriticalAddress - content.AddressStart));
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				list.AddRange(oResult2.Content);
				length = (ushort)(length - (content.CriticalAddress - content.AddressStart));
				content.AddressStart = content.CriticalAddress;
			}
			OResult<List<byte[]>> oResult3 = BuildReadCommand(content, length, isBit: true);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult3);
			}
			OResult<byte[]> oResult4 = modbus.ReadFromCoreServer(oResult3.Content);
			if (!oResult4.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult4);
			}
			list.AddRange(oResult4.Content.ToBoolArray().SelectBegin(length));
			return OResult.CreateSuccessResult(list.ToArray());
		}

		internal static OResult Write(IModbus modbus, string address, bool[] values, Func<string, bool[], OResult> funcWrite)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return funcWrite(address, values);
			}
			XinJEAddress content = oResult.Content;
			if (content.AddressStart + values.Length <= content.CriticalAddress)
			{
				return funcWrite(address, values);
			}
			if (content.AddressStart < content.CriticalAddress)
			{
				OResult oResult2 = funcWrite(address, values.SelectBegin(content.CriticalAddress - content.AddressStart));
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				values = values.RemoveBegin(content.CriticalAddress - content.AddressStart);
				content.AddressStart = content.CriticalAddress;
			}
			OResult<byte[]> oResult3 = BuildWriteBoolCommand(content, values);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return modbus.ReadFromCoreServer(oResult3.Content);
		}

		internal static OResult Write(IModbus modbus, string address, bool value, Func<string, bool, OResult> funcWrite)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return funcWrite(address, value);
			}
			XinJEAddress content = oResult.Content;
			if (content.AddressStart < content.CriticalAddress)
			{
				return funcWrite(address, value);
			}
			return modbus.Write(address, new bool[1] { value });
		}

		internal static async Task<OResult<byte[]>> ReadAsync(IModbus modbus, string address, ushort length, Func<string, ushort, Task<OResult<byte[]>>> funcRead)
		{
			OResult<XinJEAddress> analysis = XinJEAddress.ParseFrom(address, modbus.Station);
			if (!analysis.IsSuccess)
			{
				return await funcRead(address, length);
			}
			XinJEAddress xinJE = analysis.Content;
			if (xinJE.AddressStart + length <= xinJE.CriticalAddress)
			{
				return await funcRead(address, length);
			}
			List<byte> result = new List<byte>();
			if (xinJE.AddressStart < xinJE.CriticalAddress)
			{
				OResult<byte[]> oResult = await funcRead(address, (ushort)(xinJE.CriticalAddress - xinJE.AddressStart));
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				result.AddRange(oResult.Content);
				length = (ushort)(length - (xinJE.CriticalAddress - xinJE.AddressStart));
				xinJE.AddressStart = xinJE.CriticalAddress;
			}
			OResult<List<byte[]>> oResult2 = BuildReadCommand(analysis.Content, length, isBit: false);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			OResult<byte[]> oResult3 = await modbus.ReadFromCoreServerAsync(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			result.AddRange(oResult3.Content);
			return OResult.CreateSuccessResult(result.ToArray());
		}

		internal static async Task<OResult> WriteAsync(IModbus modbus, string address, byte[] value, Func<string, byte[], Task<OResult>> funcWrite)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return await funcWrite(address, value);
			}
			XinJEAddress xinJE = oResult.Content;
			if (xinJE.AddressStart + value.Length / 2 <= xinJE.CriticalAddress)
			{
				return await funcWrite(address, value);
			}
			if (xinJE.AddressStart < xinJE.CriticalAddress)
			{
				OResult oResult2 = await funcWrite(address, value.SelectBegin((xinJE.CriticalAddress - xinJE.AddressStart) * 2));
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				value = value.RemoveBegin((xinJE.CriticalAddress - xinJE.AddressStart) * 2);
				xinJE.AddressStart = xinJE.CriticalAddress;
			}
			OResult<byte[]> oResult3 = BuildWriteWordCommand(xinJE, value);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return await modbus.ReadFromCoreServerAsync(oResult3.Content);
		}

		internal static async Task<OResult> WriteAsync(IModbus modbus, string address, short value, Func<string, short, Task<OResult>> funcWrite)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, modbus.Station);
			if (!oResult.IsSuccess)
			{
				return await funcWrite(address, value);
			}
			XinJEAddress content = oResult.Content;
			if (content.AddressStart < content.CriticalAddress)
			{
				return await funcWrite(address, value);
			}
			return await modbus.WriteAsync(address, modbus.ByteTransform.TransByte(value));
		}

		internal static async Task<OResult> WriteAsync(IModbus modbus, string address, ushort value, Func<string, ushort, Task<OResult>> funcWrite)
		{
			OResult<XinJEAddress> oResult = XinJEAddress.ParseFrom(address, modbus.Station);
