			}
			return await modbus.WriteAsync(address, modbus.ByteTransform.TransByte(value));
		}

		internal static async Task<OResult<bool[]>> ReadBoolAsync(IModbus modbus, string address, ushort length, Func<string, ushort, Task<OResult<bool[]>>> funcRead)
		{
