	/// <summary>
	/// 信捷内部的TCP信息，该协议是信捷基于modbus协议扩展而来，支持更多的地址类型，以及更广泛的地址范围。具体参考Demo界面信息。<br />
	/// The TCP information inside Xinjie, which is extended by Xinjie based on the modbus protocol, 
	/// supports more address types and a wider range of addresses. For details, refer to the Demo UI.
	/// </summary>
	public class XinJEInternalNet : DeviceTcpNet
	{
		private byte station = 1;

		private readonly SoftIncrementCount softIncrementCount;

		/// <summary>
		/// 获取或者重新修改服务器的默认站号信息，当然，你可以再读写的时候动态指定，参见备注<br />
		/// Get or modify the default station number information of the server. Of course, you can specify it dynamically when reading and writing, see note
		/// </summary>
		/// <remarks>
		/// 当你调用 ReadCoil("100") 时，对应的站号就是本属性的值，当你调用 ReadCoil("s=2;100") 时，就忽略本属性的值，读写寄存器的时候同理
		/// </remarks>
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.IByteTransform.DataFormat" />
		public DataFormat DataFormat
		{
			get
			{
				return base.ByteTransform.DataFormat;
			}
			set
			{
				base.ByteTransform.DataFormat = value;
			}
		}

		/// <summary>
		/// 字符串数据是否按照字来反转，默认为False<br />
		/// Whether the string data is reversed according to words. The default is False.
		/// </summary>
		/// <remarks>
		/// 字符串按照2个字节的排列进行颠倒，根据实际情况进行设置
		/// </remarks>
		public bool IsStringReverse
		{
			get
			{
				return base.ByteTransform.IsStringReverseByteWord;
			}
			set
			{
				base.ByteTransform.IsStringReverseByteWord = value;
			}
		}

		/// <summary>
		/// 获取协议自增的消息号，你可以自定义modbus的消息号的规则，详细参见<see cref="T:Snet.Driver.Profinet.XINJE.XinJEInternalNet" />说明，也可以查找<see cref="T:Snet.Driver.BasicFramework.SoftIncrementCount" />说明。<br />
		/// Get the message number incremented by the modbus protocol. You can customize the rules of the message number of the modbus. For details, please refer to the description of <see cref="T:Snet.Driver.ModBus.ModbusTcpNet" />, or you can find the description of <see cref="T:Snet.Driver.BasicFramework.SoftIncrementCount" />
		/// </summary>
		public SoftIncrementCount MessageId => softIncrementCount;

		/// <summary>
		/// 实例化一个XINJE-Tcp协议的客户端对象<br />
		/// Instantiate a client object of the Modbus-Tcp protocol
		/// </summary>
		public XinJEInternalNet()
		{
			softIncrementCount = new SoftIncrementCount(65535L, 0L);
			base.WordLength = 1;
			station = 1;
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
		}

		/// <summary>
		/// 指定服务器地址，端口号，客户端自己的站号来初始化<br />
		/// Specify the server address, port number, and client's own station number to initialize
		/// </summary>
		/// <param name="ipAddress">服务器的Ip地址</param>
		/// <param name="port">服务器的端口号</param>
		/// <param name="station">客户端自身的站号</param>
		public XinJEInternalNet(string ipAddress, int port = 502, byte station = 1)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
			this.station = station;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new ModbusTcpMessage();
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			return ModbusInfo.PackCommandToTcp(command, (ushort)softIncrementCount.GetCurrentValue());
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			return ModbusInfo.ExtractActualData(ModbusInfo.ExplodeTcpCommandToCore(response));
		}

		/// <inheritdoc />
		/// <remarks>
		/// 地址支持 D100, SD100, TD100, CD100, HD100, FD100, ETD100, HTD100, HCD100, HSD100, 各自的地址范围取决于实际PLC的范围，比如D的地址在XLH型号上可达 0~499999<br />
		/// Address support D100, SD100, TD100, CD100, HD100, FD100, ETD100, HTD100, HCD100, HSD100, the respective address range depends on the actual PLC range, for example, the address of D can reach 0~499999 on the XLH model
		/// </remarks>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = XinJEHelper.BuildReadCommand(Station, address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc />
		/// <remarks>
		/// 地址支持 M100, X100, Y100, SM100, T100, C100, HM100, HS100, HT100, HSC100 各自的地址范围取决于实际PLC的范围，比如M的地址在XLH型号上可达 0~199999<br />
		/// The address supports M100, X100, Y100, SM100, T100, C100, HM100, HS100, HT100, HSC100, the respective address range depends on the actual PLC range, for example, the address of M can reach 0~199999 on the XLH model
		/// </remarks>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = XinJEHelper.BuildReadCommand(Station, address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectBegin(length));
		}

		/// <inheritdoc />
		/// <remarks>
		/// 地址支持 D100, SD100, TD100, CD100, HD100, FD100, ETD100, HTD100, HCD100, HSD100,  各自的地址范围取决于实际PLC的范围，比如D的地址在XLH型号上可达 0~499999<br />
		/// Address support D100, SD100, TD100, CD100, HD100, FD100, ETD100, HTD100, HCD100, HSD100,  the respective address range depends on the actual PLC range, for example, the address of D can reach 0~499999 on the XLH model
		/// </remarks>
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = XinJEHelper.BuildWriteWordCommand(Station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc />
		/// <remarks>
		/// 地址支持 M100, Y100, SM100, T100, C100, 各自的地址范围取决于实际PLC的范围，比如M的地址在XLH型号上可达 0~199999<br />
		/// The address supports M100, Y100, SM100, T100, C100, the respective address range depends on the actual PLC range, for example, the address of M can reach 0~199999 on the XLH model
		/// </remarks>
		public override OResult Write(string address, bool[] value)
		{
			OResult<byte[]> oResult = XinJEHelper.BuildWriteBoolCommand(Station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.XINJE.XinJEInternalNet.Read(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = XinJEHelper.BuildReadCommand(Station, address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return await ReadFromCoreServerAsync(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.XINJE.XinJEInternalNet.ReadBool(System.String,System.UInt16)" />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = XinJEHelper.BuildReadCommand(Station, address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectBegin(length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.XINJE.XinJEInternalNet.Write(System.String,System.Byte[])" />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<byte[]> oResult = XinJEHelper.BuildWriteWordCommand(Station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return await ReadFromCoreServerAsync(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.XINJE.XinJEInternalNet.Write(System.String,System.Boolean[])" />
		public override async Task<OResult> WriteAsync(string address, bool[] value)
		{
			OResult<byte[]> oResult = XinJEHelper.BuildWriteBoolCommand(Station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return await ReadFromCoreServerAsync(oResult.Content);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"XinJEInternalNet[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 信捷PLC的XC,XD,XL系列的串口通讯类，底层使用ModbusRtu协议实现，每个系列支持的地址类型及范围不一样，详细参考DEMO程序说明<br />
	/// XC, XD, XL series serial communication of Xinje PLC, the bottom layer is implemented by ModbusRtu protocol, 
	/// the address type and range supported by each series are different, please refer to the Demo for details
	/// </summary>
	/// <remarks>
	/// 地址可以携带站号访问，例如 s=2;M100 <br />
	/// 对于XC系列适用于XC1/XC2/XC3/XC5/XCM/XCC系列，线圈支持X,Y,S,M,T,C，寄存器支持D,F,E,T,C<br />
	/// 对于XD,XL系列适用于XD1/XD2/XD3/XD5/XDM/XDC/XD5E/XDME/XDH/XL1/XL3/XL5/XL5E/XLME，
	/// 线圈支持X,Y,S,M,SM,T,C,ET,SEM,HM,HS,HT,HC,HSC 寄存器支持D,ID,QD,SD,TD,CD,ETD,HD,HSD,HTD,HCD,HSCD,FD,SFD,FS<br />
	/// </remarks>
	public class XinJESerial : ModbusRtu
	{
		/// <summary>
		/// 获取或设置当前的信捷PLC的系列，默认XC系列
		/// </summary>
		public XinJESeries Series { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public XinJESerial()
		{
			Series = XinJESeries.XC;
		}

		/// <summary>
		/// 指定客户端自己的站号来初始化<br />
		/// Specify the client's own station number to initialize
		/// </summary>
		/// <param name="station">客户端自身的站号</param>
		public XinJESerial(byte station = 1)
			: base(station)
		{
			Series = XinJESeries.XC;
		}

		/// <summary>
		/// 通过指定站号以及PLC的系列来实例化一个新的对象<br />
		/// Instantiate a new object by specifying the station number and PLC series
		/// </summary>
		/// <param name="series">PLC的系列</param>
		/// <param name="station">站号信息</param>
		public XinJESerial(XinJESeries series, byte station = 1)
			: base(station)
		{
			Series = series;
		}

		/// <inheritdoc />
