	/// <summary>
	/// 丰炜的虚拟PLC，模拟了VS系列的通信，可以和对应的客户端进行数据读写测试，位地址支持 X,Y,M,S，字地址支持 D,R,SD
	/// </summary>
	public class VigorServer : DeviceServer
	{
		private SoftBuffer xBuffer;

		private SoftBuffer yBuffer;

		private SoftBuffer mBuffer;

		private SoftBuffer sBuffer;

		private SoftBuffer dBuffer;

		private SoftBuffer rBuffer;

		private SoftBuffer sdBuffer;

		private const int DataPoolLength = 65536;

		private int station;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Vigor.VigorSerial.Station" />
		public int Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 实例化一个丰炜PLC的网口和串口服务器，支持数据读写操作
		/// </summary>
		public VigorServer()
		{
			xBuffer = new SoftBuffer(65536);
			yBuffer = new SoftBuffer(65536);
			mBuffer = new SoftBuffer(65536);
			sBuffer = new SoftBuffer(65536);
			dBuffer = new SoftBuffer(131072);
			rBuffer = new SoftBuffer(131072);
			sdBuffer = new SoftBuffer(131072);
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new VigorSerialMessage();
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[655360];
			xBuffer.GetBytes().CopyTo(array, 0);
			yBuffer.GetBytes().CopyTo(array, 65536);
			mBuffer.GetBytes().CopyTo(array, 131072);
			sBuffer.GetBytes().CopyTo(array, 196608);
			dBuffer.GetBytes().CopyTo(array, 262144);
			rBuffer.GetBytes().CopyTo(array, 393216);
			sdBuffer.GetBytes().CopyTo(array, 524288);
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 655360)
			{
				throw new Exception("File is not correct");
			}
			xBuffer.SetBytes(content, 0, 65536);
			yBuffer.SetBytes(content, 65536, 65536);
			mBuffer.SetBytes(content, 131072, 65536);
			sBuffer.SetBytes(content, 196608, 65536);
			dBuffer.SetBytes(content, 262144, 131072);
			rBuffer.SetBytes(content, 393216, 131072);
			sdBuffer.SetBytes(content, 524288, 131072);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Vigor.VigorSerial.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = new OResult<byte[]>();
			try
			{
				if (address.StartsWith("SD") || address.StartsWith("sd"))
				{
					return OResult.CreateSuccessResult(sdBuffer.GetBytes(Convert.ToInt32(address.Substring(2)) * 2, length * 2));
				}
				if (address.StartsWith("D") || address.StartsWith("d"))
				{
					return OResult.CreateSuccessResult(dBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				}
				if (address.StartsWith("R") || address.StartsWith("r"))
				{
					return OResult.CreateSuccessResult(rBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				}
				throw new Exception(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Vigor.VigorSerial.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = new OResult<byte[]>();
			try
			{
				if (address.StartsWith("SD") || address.StartsWith("sd"))
				{
					sdBuffer.SetBytes(value, Convert.ToInt32(address.Substring(2)) * 2);
					return OResult.CreateSuccessResult();
				}
				if (address.StartsWith("D") || address.StartsWith("d"))
				{
					dBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
					return OResult.CreateSuccessResult();
				}
				if (address.StartsWith("R") || address.StartsWith("r"))
				{
					rBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
					return OResult.CreateSuccessResult();
				}
				throw new Exception(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Vigor.VigorSerial.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			try
			{
				int destIndex = Convert.ToInt32(address.Substring(1));
				switch (address[0])
				{
				case 'X':
				case 'x':
					return OResult.CreateSuccessResult(xBuffer.GetBool(destIndex, length));
				case 'Y':
				case 'y':
					return OResult.CreateSuccessResult(yBuffer.GetBool(destIndex, length));
				case 'M':
				case 'm':
					return OResult.CreateSuccessResult(mBuffer.GetBool(destIndex, length));
				case 'S':
				case 's':
					return OResult.CreateSuccessResult(sBuffer.GetBool(destIndex, length));
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<bool[]>(ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceCommunication.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			try
			{
				int destIndex = Convert.ToInt32(address.Substring(1));
				switch (address[0])
				{
				case 'X':
				case 'x':
					xBuffer.SetBool(value, destIndex);
					return OResult.CreateSuccessResult();
				case 'Y':
				case 'y':
					yBuffer.SetBool(value, destIndex);
					return OResult.CreateSuccessResult();
				case 'M':
				case 'm':
					mBuffer.SetBool(value, destIndex);
					return OResult.CreateSuccessResult();
				case 'S':
				case 's':
					sBuffer.SetBool(value, destIndex);
					return OResult.CreateSuccessResult();
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<bool[]>(ex.Message);
			}
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive[0] != 16 || receive[1] != 2)
			{
				return new OResult<byte[]>("start message must be 0x10, 0x02");
			}
			if (receive[2] != station)
			{
				return new OResult<byte[]>($"Station not match , Except: {station:X2} , Actual: {receive[2]}");
			}
			return OResult.CreateSuccessResult(ReadFromVigorCore(VigorVsHelper.UnPackCommand(receive)));
		}

		private byte[] CreateResponseBack(byte[] request, byte err, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[4 + data.Length];
			array[0] = request[2];
			array[1] = BitConverter.GetBytes(1 + data.Length)[0];
			array[2] = BitConverter.GetBytes(1 + data.Length)[1];
			array[3] = err;
			if (data.Length != 0)
			{
				data.CopyTo(array, 4);
			}
			return VigorVsHelper.PackCommand(array, 6);
		}

		private byte[] ReadFromVigorCore(byte[] receive)
		{
			if (receive.Length < 16)
			{
				return null;
			}
			if (receive[5] == 32)
			{
				return ReadWordByCommand(receive);
			}
			if (receive[5] == 33)
			{
				return ReadBoolByCommand(receive);
			}
			if (receive[5] == 40)
			{
				return WriteWordByCommand(receive);
			}
			if (receive[5] == 41)
			{
				return WriteBoolByCommand(receive);
			}
			return CreateResponseBack(receive, 49, null);
		}

		private byte[] ReadWordByCommand(byte[] command)
		{
			int num = Convert.ToInt32(Enumerable.Reverse(command.SelectMiddle(7, 3)).ToArray().ToHexString());
			int num2 = base.ByteTransform.TransUInt16(command, 10);
			return command[6] switch
			{
				160 => CreateResponseBack(command, 0, dBuffer.GetBytes(num * 2, num2 * 2)), 
				161 => CreateResponseBack(command, 0, sdBuffer.GetBytes(num * 2, num2 * 2)), 
				162 => CreateResponseBack(command, 0, rBuffer.GetBytes(num * 2, num2 * 2)), 
				_ => CreateResponseBack(command, 49, null), 
			};
		}

		private byte[] ReadBoolByCommand(byte[] command)
		{
			string value = Enumerable.Reverse(command.SelectMiddle(7, 3)).ToArray().ToHexString();
			int length = base.ByteTransform.TransUInt16(command, 10);
			return command[6] switch
			{
				144 => CreateResponseBack(command, 0, xBuffer.GetBool(Convert.ToInt32(value, 8), length).ToByteArray()), 
				145 => CreateResponseBack(command, 0, yBuffer.GetBool(Convert.ToInt32(value, 8), length).ToByteArray()), 
				146 => CreateResponseBack(command, 0, mBuffer.GetBool(Convert.ToInt32(value), length).ToByteArray()), 
				147 => CreateResponseBack(command, 0, sBuffer.GetBool(Convert.ToInt32(value), length).ToByteArray()), 
				_ => CreateResponseBack(command, 49, null), 
			};
		}

		private byte[] WriteWordByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return CreateResponseBack(command, 49, null);
			}
			int num = Convert.ToInt32(Enumerable.Reverse(command.SelectMiddle(7, 3)).ToArray().ToHexString());
			int length = base.ByteTransform.TransUInt16(command, 3) - 7;
			byte[] data = command.SelectMiddle(12, length);
			switch (command[6])
			{
			case 160:
				dBuffer.SetBytes(data, num * 2);
				return CreateResponseBack(command, 0, null);
			case 161:
				sdBuffer.SetBytes(data, num * 2);
				return CreateResponseBack(command, 0, null);
			case 162:
				rBuffer.SetBytes(data, num * 2);
				return CreateResponseBack(command, 0, null);
			default:
				return CreateResponseBack(command, 49, null);
			}
		}

		private byte[] WriteBoolByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return CreateResponseBack(command, 49, null);
			}
			string value = Enumerable.Reverse(command.SelectMiddle(7, 3)).ToArray().ToHexString();
			int length = base.ByteTransform.TransUInt16(command, 3) - 7;
			int length2 = base.ByteTransform.TransUInt16(command, 10);
			bool[] value2 = command.SelectMiddle(12, length).ToBoolArray().SelectBegin(length2);
			switch (command[6])
			{
			case 144:
				xBuffer.SetBool(value2, Convert.ToInt32(value, 8));
				return CreateResponseBack(command, 0, null);
			case 145:
				yBuffer.SetBool(value2, Convert.ToInt32(value, 8));
				return CreateResponseBack(command, 0, null);
			case 146:
				mBuffer.SetBool(value2, Convert.ToInt32(value));
				return CreateResponseBack(command, 0, null);
			case 147:
				sBuffer.SetBool(value2, Convert.ToInt32(value));
				return CreateResponseBack(command, 0, null);
			default:
				return CreateResponseBack(command, 49, null);
			}
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			return VigorVsHelper.CheckReceiveDataComplete(buffer, receivedLength);
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				xBuffer.Dispose();
				yBuffer.Dispose();
				mBuffer.Dispose();
				sBuffer.Dispose();
				dBuffer.Dispose();
				rBuffer.Dispose();
				sdBuffer.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"VigorServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Vigor.Helper
{
	/// <summary>
	/// 丰炜PLC的辅助方法
	/// </summary>
	public class VigorHelper
	{
		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Read(System.String,System.UInt16)" />
		/// <remarks>
		/// 支持字地址，单次最多读取64字节，支持D,SD,R,T,C的数据读取，同时地址支持携带站号信息，s=2;D100
		/// </remarks>
		public static OResult<byte[]> Read(IReadWriteDevice plc, byte station, string address, ushort length)
		{
			OResult<List<byte[]>> oResult = VigorVsHelper.BuildReadCommand((byte)SnetHelper.ExtractParameter(ref address, "s", station), address, length, isBool: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult<byte[]> oResult3 = VigorVsHelper.CheckResponseContent(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				list.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadBool(System.String,System.UInt16)" />
		/// <remarks>
		/// 需要输入位地址，最多读取1024位，支持X,Y,M,SM,S,TS(定时器触点),TC（定时器线圈）,CS(计数器触点),CC（计数器线圈）
		/// </remarks>
		public static OResult<bool[]> ReadBool(IReadWriteDevice plc, byte station, string address, ushort length)
		{
			OResult<List<byte[]>> oResult = VigorVsHelper.BuildReadCommand((byte)SnetHelper.ExtractParameter(ref address, "s", station), address, length, isBool: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<bool> list = new List<bool>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult<byte[]> oResult3 = VigorVsHelper.CheckResponseContent(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				list.AddRange(oResult3.Content.ToBoolArray().SelectBegin(length));
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Byte[])" />
		/// <remarks>
		/// 支持字地址，单次最多读取64字节，支持D,SD,R,T,C的数据写入，其中C199~C200不能连续写入，前者是16位计数器，后者是32位计数器
		/// </remarks>
		public static OResult Write(IReadWriteDevice plc, byte station, string address, byte[] value)
		{
			OResult<byte[]> oResult = VigorVsHelper.BuildWriteWordCommand((byte)SnetHelper.ExtractParameter(ref address, "s", station), address, value);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return VigorVsHelper.CheckResponseContent(oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean[])" />
		/// <remarks>
		/// 支持位地址的写入，支持X,Y,M,SM,S,TS(定时器触点),TC（定时器线圈）,CS(计数器触点),CC（计数器线圈）
		/// </remarks>
		public static OResult Write(IReadWriteDevice plc, byte station, string address, bool[] value)
		{
			OResult<byte[]> oResult = VigorVsHelper.BuildWriteBoolCommand((byte)SnetHelper.ExtractParameter(ref address, "s", station), address, value);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return VigorVsHelper.CheckResponseContent(oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Vigor.Helper.VigorHelper.Read(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.UInt16)" />
		public static async Task<OResult<byte[]>> ReadAsync(IReadWriteDevice plc, byte station, string address, ushort length)
		{
			byte station2 = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<List<byte[]>> command = VigorVsHelper.BuildReadCommand(station2, address, length, isBool: false);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(command);
			}
			List<byte> result = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await plc.ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				OResult<byte[]> oResult2 = VigorVsHelper.CheckResponseContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				result.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(result.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Vigor.Helper.VigorHelper.ReadBool(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.UInt16)" />
		public static async Task<OResult<bool[]>> ReadBoolAsync(IReadWriteDevice plc, byte station, string address, ushort length)
		{
			byte station2 = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<List<byte[]>> command = VigorVsHelper.BuildReadCommand(station2, address, length, isBool: true);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(command);
			}
			List<bool> result = new List<bool>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await plc.ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				OResult<byte[]> oResult2 = VigorVsHelper.CheckResponseContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				result.AddRange(oResult2.Content.ToBoolArray().SelectBegin(length));
			}
			return OResult.CreateSuccessResult(result.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Vigor.Helper.VigorHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Byte[])" />
		public static async Task<OResult> WriteAsync(IReadWriteDevice plc, byte station, string address, byte[] value)
		{
			OResult<byte[]> oResult = VigorVsHelper.BuildWriteWordCommand((byte)SnetHelper.ExtractParameter(ref address, "s", station), address, value);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<byte[]> oResult2 = await plc.ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return VigorVsHelper.CheckResponseContent(oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Vigor.Helper.VigorHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Boolean[])" />
		public static async Task<OResult> WriteAsync(IReadWriteDevice plc, byte station, string address, bool[] value)
		{
			OResult<byte[]> oResult = VigorVsHelper.BuildWriteBoolCommand((byte)SnetHelper.ExtractParameter(ref address, "s", station), address, value);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<byte[]> oResult2 = await plc.ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return VigorVsHelper.CheckResponseContent(oResult2.Content);
		}
	}
	/// <summary>
	/// 丰炜PLC的辅助类对象
	/// </summary>
	public class VigorVsHelper
	{
		internal static byte[] PackCommand(byte[] command, byte code = 2)
		{
			if (command == null)
			{
				command = new byte[0];
			}
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(16);
			memoryStream.WriteByte(code);
			int num = 0;
			for (int i = 0; i < command.Length; i++)
			{
				num += command[i];
				memoryStream.WriteByte(command[i]);
				if (command[i] == 16)
				{
					memoryStream.WriteByte(command[i]);
				}
			}
			memoryStream.WriteByte(16);
			memoryStream.WriteByte(3);
			byte[] bytes = Encoding.ASCII.GetBytes((num % 256).ToString("X2"));
			memoryStream.WriteByte(bytes[0]);
			memoryStream.WriteByte(bytes[1]);
			return memoryStream.ToArray();
		}

		internal static byte[] UnPackCommand(byte[] command)
		{
			if (command == null)
			{
				command = new byte[0];
			}
			MemoryStream memoryStream = new MemoryStream();
			for (int i = 0; i < command.Length; i++)
			{
				memoryStream.WriteByte(command[i]);
				if (command[i] == 16 && i + 1 < command.Length && command[i + 1] == 16)
				{
					i++;
				}
			}
			return memoryStream.ToArray();
		}

		internal static bool CheckReceiveDataComplete(byte[] buffer, int length)
		{
			int num = 0;
			if (length < 10)
			{
				return false;
			}
			for (int i = 0; i < length; i++)
			{
				if (buffer[i] == 16 && i + 1 < length)
				{
					if (buffer[i + 1] == 16)
					{
						i++;
					}
					else if (buffer[i + 1] == 3)
					{
						num = i;
						break;
					}
				}
			}
			if (num == length - 4)
			{
				return true;
			}
			return false;
		}

		private static byte[] GetBytesAddress(int address)
		{
			string text = address.ToString("D6");
			if (text.Length > 6)
			{
				text = text.Substring(6);
			}
			return text.ToHexBytes();
		}

		/// <summary>
		/// 构建读取的报文命令，对于字地址，单次最多读取64字节，支持D,SD,R,T,C的数据读取，对于位地址，最多读取1024位，支持X,Y,M,SM,S,TS(定时器触点),TC（定时器线圈）,CS(计数器触点),CC（计数器线圈）<br />
		/// Construct a read message command. For word addresses, up to 64 bytes can be read at a time, and data reading of D, SD, R, T, and C is supported. For bit addresses, 
		/// up to 1024 bits are read, and X, Y are supported. , M, SM, S, TS (timer contact), TC (timer coil), CS (counter contact), CC (counter coil)
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">PLC的数据地址</param>
		/// <param name="length">读取的长度</param>
		/// <param name="isBool">是否进行位读取</param>
		/// <returns>完整的读取的报文信息</returns>
		public static OResult<List<byte[]>> BuildReadCommand(byte station, string address, ushort length, bool isBool)
		{
			OResult<VigorAddress> oResult = VigorAddress.ParseFrom(address, length, isBool);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			int[] array = SoftBasic.SplitIntegerToArray(length, isBool ? 1024 : ((oResult.Content.DataCode == 173) ? 32 : 64));
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				byte[] bytesAddress = GetBytesAddress(oResult.Content.AddressStart);
				list.Add(PackCommand(new byte[10]
				{
					station,
					7,
					0,
					(byte)(isBool ? 33u : 32u),
					oResult.Content.DataCode,
					bytesAddress[2],
					bytesAddress[1],
					bytesAddress[0],
					BitConverter.GetBytes(array[i])[0],
					BitConverter.GetBytes(array[i])[1]
				}, 2));
				oResult.Content.AddressStart += array[i];
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 构建以字单位写入的报文，单次最多写入64个word，地址支持 D,SD,R,T,C，对于C200~C255,是属于32位的计数器<br />
		/// Construct a message written in word units, and write up to 64 words in a single time. The address supports D, SD, R, T, C. For C200~C255, it is a 32-bit counter
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">PLC的地址</param>
		/// <param name="value">写入的原始数据</param>
		/// <returns>写入命令的完整报文</returns>
		public static OResult<byte[]> BuildWriteWordCommand(byte station, string address, byte[] value)
		{
			OResult<VigorAddress> oResult = VigorAddress.ParseFrom(address, 1, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] bytesAddress = GetBytesAddress(oResult.Content.AddressStart);
			byte[] array = new byte[10 + value.Length];
			array[0] = station;
			array[1] = BitConverter.GetBytes(7 + value.Length)[0];
			array[2] = BitConverter.GetBytes(7 + value.Length)[1];
			array[3] = 40;
			array[4] = oResult.Content.DataCode;
			array[5] = bytesAddress[2];
			array[6] = bytesAddress[1];
			array[7] = bytesAddress[0];
			if (oResult.Content.DataCode == 173)
			{
				array[8] = BitConverter.GetBytes(value.Length / 4)[0];
				array[9] = BitConverter.GetBytes(value.Length / 4)[1];
			}
			else
			{
				array[8] = BitConverter.GetBytes(value.Length / 2)[0];
				array[9] = BitConverter.GetBytes(value.Length / 2)[1];
			}
			value.CopyTo(array, 10);
			return OResult.CreateSuccessResult(PackCommand(array, 2));
		}

		/// <summary>
		/// 构建以位单位写入的报文，单次最多写入1024bit，支持X,Y,M,SM,S,TS(定时器触点),TC（定时器线圈）,CS(计数器触点),CC（计数器线圈）
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">PLC的地址</param>
		/// <param name="value">等待写入的bool数组</param>
		/// <returns>写入位数据的完整报文信息</returns>
		public static OResult<byte[]> BuildWriteBoolCommand(byte station, string address, bool[] value)
		{
			OResult<VigorAddress> oResult = VigorAddress.ParseFrom(address, 1, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] bytesAddress = GetBytesAddress(oResult.Content.AddressStart);
			byte[] array = value.ToByteArray();
			byte[] array2 = new byte[10 + array.Length];
			array2[0] = station;
			array2[1] = BitConverter.GetBytes(7 + array.Length)[0];
			array2[2] = BitConverter.GetBytes(7 + array.Length)[1];
			array2[3] = 41;
			array2[4] = oResult.Content.DataCode;
			array2[5] = bytesAddress[2];
			array2[6] = bytesAddress[1];
			array2[7] = bytesAddress[0];
			array2[8] = BitConverter.GetBytes(value.Length)[0];
			array2[9] = BitConverter.GetBytes(value.Length)[1];
			array.CopyTo(array2, 10);
			return OResult.CreateSuccessResult(PackCommand(array2, 2));
		}

		/// <summary>
		/// 检查从PLC返回的报文是否正确，以及提取出正确的结果数据
		/// </summary>
		/// <param name="response">PLC返回的报文</param>
		/// <returns>提取的结果数据内容</returns>
		public static OResult<byte[]> CheckResponseContent(byte[] response)
		{
			response = UnPackCommand(response);
			if (response.Length < 6)
			{
				return new OResult<byte[]>(StringResources.Language.ReceiveDataLengthTooShort + " Source: " + response.ToHexString(' '));
			}
			if (response[5] != 0)
			{
				return new OResult<byte[]>(response[5], GetErrorText(response[5]) + " Source: " + response.ToHexString(' '));
			}
			try
			{
				int num = BitConverter.ToUInt16(response, 3);
				if (num + 9 == response.Length)
				{
					if (num == 1)
					{
						return OResult.CreateSuccessResult(new byte[0]);
					}
					return OResult.CreateSuccessResult(response.SelectMiddle(6, num - 1));
				}
				return new OResult<byte[]>(response[5], "Length check failed, Source: " + response.ToHexString(' '));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("CheckResponseContent failed: " + ex.Message + Environment.NewLine + "Source: " + response.ToHexString(' '));
			}
		}

		internal static string GetErrorText(byte status)
		{
			return status switch
			{
				2 => StringResources.Language.Vigor02, 
				4 => StringResources.Language.Vigor04, 
				6 => StringResources.Language.Vigor06, 
				8 => StringResources.Language.Vigor08, 
				49 => StringResources.Language.Vigor31, 
				_ => StringResources.Language.UnknownError, 
			};
		}
	}
}
namespace Snet.Driver.Profinet.Turck
{
	/// <summary>
	/// Reader协议的实现
	/// </summary>
	public class ReaderNet : DeviceTcpNet
	{
		private bool successfullyInitialized;

		/// <summary>
		/// 获取设备的唯一的UID信息，本值会在连接上PLC之后自动赋值
		/// </summary>
		public string UID { get; private set; }

		/// <summary>
		/// 获取当前设备的数据块总数量，本值会在连接上PLC之后自动赋值
		/// </summary>
		public byte NumberOfBlock { get; private set; }

		/// <summary>
		/// 获取当前设备的每个数据块拥有的字节数，本值会在连接上PLC之后自动赋值
		/// </summary>
		public byte BytesOfBlock { get; private set; }

		/// <summary>
		/// 实例化默认的构造方法<br />
		/// Instantiate the default constructor
		/// </summary>
		public ReaderNet()
		{
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 使用指定的ip地址和端口来实例化一个对象<br />
		/// Instantiate an object with the specified IP address and port
		/// </summary>
		/// <param name="ipAddress">设备的Ip地址</param>
		/// <param name="port">设备的端口号</param>
		public ReaderNet(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new TurckReaderMessage();
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			successfullyInitialized = false;
			return base.InitializationOnConnect();
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			successfullyInitialized = false;
			return await base.InitializationOnConnectAsync();
		}

		/// <summary>
		/// 读取指定地址的byte数据
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <returns>是否读取成功的结果对象 -&gt; Whether to read the successful result object</returns>
		/// <example>参考<see cref="M:Snet.Driver.Profinet.Turck.ReaderNet.Read(System.String,System.UInt16)" />的注释</example>
		public OResult<byte> ReadByte(string address)
		{
			return ByteTransformHelper.GetResultFromArray(Read(address, 1));
		}

		/// <summary>
		/// 向设备中写入byte数据，返回值说明<br />
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="value">byte数据 -&gt; Byte data</param>
		/// <returns>是否写入成功的结果对象 -&gt; Whether to write a successful result object</returns>
		public OResult Write(string address, byte value)
		{
			return Write(address, new byte[1] { value });
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Turck.ReaderNet.ReadByte(System.String)" />
		public async Task<OResult<byte>> ReadByteAsync(string address)
		{
			return ByteTransformHelper.GetResultFromArray(await ReadAsync(address, 1));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Turck.ReaderNet.Write(System.String,System.Byte)" />
		public async Task<OResult> WriteAsync(string address, byte value)
		{
			return await WriteAsync(address, new byte[1] { value });
		}

		private OResult<byte[]> CheckResponseContent(byte[] content)
		{
			if (content[1] == 10 && content[2] == 10)
			{
				if (content[5] == 0 && content[6] == 2 && content[7] == 0)
				{
					successfullyInitialized = false;
				}
				return new OResult<byte[]>(GetErrorText(content[5], content[6], content[7]) + " Source: " + content.ToHexString(' '));
			}
			if (content[1] == 7 && content[2] == 7)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (content.Length > 7)
			{
				return OResult.CreateSuccessResult(content.SelectMiddle(5, content.Length - 7));
			}
			return new OResult<byte[]>("Error message: " + content.ToHexString(' '));
		}

		private OResult<byte[]> ReadRaw(byte startBlock, byte lengthOfBlock)
		{
			List<byte[]> list = BuildReadCommand(startBlock, lengthOfBlock, BytesOfBlock);
			List<byte> list2 = new List<byte>();
			for (int i = 0; i < list.Count; i++)
			{
				OResult<byte[]> oResult = ReadFromCoreServer(list[i]);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = CheckResponseContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				list2.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(list2.ToArray());
		}

		private OResult WriteRaw(byte startBlock, byte lengthOfBlock, byte[] value)
		{
			List<byte[]> list = BuildWriteCommand(startBlock, lengthOfBlock, BytesOfBlock, value);
			for (int i = 0; i < list.Count; i++)
			{
				OResult<byte[]> oResult = ReadFromCoreServer(list[i]);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = CheckResponseContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			if (!successfullyInitialized)
			{
				OResult<string> oResult = ReadRFIDInfo();
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
			}
			OResult<ushort> oResult2 = ParseAddress(address, isBit: false);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			CalculateBlockAddress(oResult2.Content, length, BytesOfBlock, out var startBlock, out var lengthOfBlock);
			OResult<byte[]> oResult3 = ReadRaw(startBlock, lengthOfBlock);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult(oResult3.Content.SelectMiddle(oResult2.Content % BytesOfBlock, length));
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			if (!successfullyInitialized)
			{
				OResult<string> oResult = ReadRFIDInfo();
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
			}
			OResult<ushort> oResult2 = ParseAddress(address, isBit: false);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			CalculateBlockAddress(oResult2.Content, (ushort)value.Length, BytesOfBlock, out var startBlock, out var lengthOfBlock);
			OResult<byte[]> oResult3 = ReadRaw(startBlock, lengthOfBlock);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			value.CopyTo(oResult3.Content, oResult2.Content % BytesOfBlock);
			return WriteRaw(startBlock, lengthOfBlock, oResult3.Content);
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (!successfullyInitialized)
			{
				OResult<string> oResult = ReadRFIDInfo();
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
			}
			OResult<ushort> oResult2 = ParseAddress(address, isBit: true);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			ushort num = (ushort)(oResult2.Content / 8);
			ushort length2 = (ushort)((oResult2.Content + length - 1) / 8 - num + 1);
			CalculateBlockAddress(num, length2, BytesOfBlock, out var startBlock, out var lengthOfBlock);
			OResult<byte[]> oResult3 = ReadRaw(startBlock, lengthOfBlock);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult3);
			}
			return OResult.CreateSuccessResult(oResult3.Content.SelectMiddle(num % BytesOfBlock, length2).ToBoolArray().SelectMiddle(oResult2.Content % 8, length));
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] value)
		{
			if (!successfullyInitialized)
			{
				OResult<string> oResult = ReadRFIDInfo();
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
			}
			OResult<ushort> oResult2 = ParseAddress(address, isBit: true);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			ushort num = (ushort)(oResult2.Content / 8);
			ushort length = (ushort)((oResult2.Content + value.Length - 1) / 8 - num + 1);
			CalculateBlockAddress(num, length, BytesOfBlock, out var startBlock, out var lengthOfBlock);
			OResult<byte[]> oResult3 = ReadRaw(startBlock, lengthOfBlock);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult3);
			}
			bool[] array = oResult3.Content.ToBoolArray();
			value.CopyTo(array, num % BytesOfBlock * 8 + oResult2.Content % 8);
			return WriteRaw(startBlock, lengthOfBlock, array.ToByteArray());
		}

		private async Task<OResult<byte[]>> ReadRawAsync(byte startBlock, byte lengthOfBlock)
		{
			List<byte[]> list = BuildReadCommand(startBlock, lengthOfBlock, BytesOfBlock);
			List<byte> result = new List<byte>();
			for (int i = 0; i < list.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(list[i]);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = CheckResponseContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				result.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(result.ToArray());
		}

		private async Task<OResult> WriteRawAsync(byte startBlock, byte lengthOfBlock, byte[] value)
		{
			List<byte[]> list = BuildWriteCommand(startBlock, lengthOfBlock, BytesOfBlock, value);
			for (int i = 0; i < list.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(list[i]);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = CheckResponseContent(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			if (!successfullyInitialized)
			{
				OResult<string> oResult = await ReadRFIDInfoAsync();
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
			}
			OResult<ushort> addAnalysis = ParseAddress(address, isBit: false);
			if (!addAnalysis.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(addAnalysis);
			}
			CalculateBlockAddress(addAnalysis.Content, length, BytesOfBlock, out var startBlock, out var lengthOfBlock);
			OResult<byte[]> oResult2 = await ReadRawAsync(startBlock, lengthOfBlock);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult(oResult2.Content.SelectMiddle(addAnalysis.Content % BytesOfBlock, length));
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			if (!successfullyInitialized)
			{
				OResult<string> oResult = await ReadRFIDInfoAsync();
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
			}
			OResult<ushort> addAnalysis = ParseAddress(address, isBit: false);
			if (!addAnalysis.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(addAnalysis);
			}
			CalculateBlockAddress(addAnalysis.Content, (ushort)value.Length, BytesOfBlock, out var startBlock, out var lengthOfBlock);
			OResult<byte[]> oResult2 = await ReadRawAsync(startBlock, lengthOfBlock);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			value.CopyTo(oResult2.Content, addAnalysis.Content % BytesOfBlock);
			return await WriteRawAsync(startBlock, lengthOfBlock, oResult2.Content);
		}

		/// <inheritdoc />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			if (!successfullyInitialized)
			{
				OResult<string> oResult = await ReadRFIDInfoAsync();
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
			}
			OResult<ushort> addAnalysis = ParseAddress(address, isBit: true);
			if (!addAnalysis.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(addAnalysis);
			}
			ushort byteStart = (ushort)(addAnalysis.Content / 8);
			ushort byteLength = (ushort)((addAnalysis.Content + length - 1) / 8 - byteStart + 1);
			CalculateBlockAddress(byteStart, byteLength, BytesOfBlock, out var startBlock, out var lengthOfBlock);
			OResult<byte[]> oResult2 = await ReadRawAsync(startBlock, lengthOfBlock);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.SelectMiddle(byteStart % BytesOfBlock, byteLength).ToBoolArray().SelectMiddle(addAnalysis.Content % 8, length));
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, bool[] value)
		{
			if (!successfullyInitialized)
			{
				OResult<string> oResult = await ReadRFIDInfoAsync();
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
			}
			OResult<ushort> addAnalysis = ParseAddress(address, isBit: true);
			if (!addAnalysis.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(addAnalysis);
			}
			ushort byteStart = (ushort)(addAnalysis.Content / 8);
			ushort length = (ushort)((addAnalysis.Content + value.Length - 1) / 8 - byteStart + 1);
			CalculateBlockAddress(byteStart, length, BytesOfBlock, out var startBlock, out var lengthOfBlock);
			OResult<byte[]> oResult2 = await ReadRawAsync(startBlock, lengthOfBlock);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			bool[] array = oResult2.Content.ToBoolArray();
			value.CopyTo(array, byteStart % BytesOfBlock * 8 + addAnalysis.Content % 8);
			return await WriteRawAsync(startBlock, lengthOfBlock, array.ToByteArray());
		}

		private OResult<string> ExtraUID(byte[] content)
		{
			OResult<byte[]> oResult = CheckResponseContent(content);
			if (oResult.IsSuccess)
			{
				UID = content.SelectMiddle(5, 8).ToHexString();
				NumberOfBlock = content[15];
				BytesOfBlock = (byte)(content[16] + 1);
				successfullyInitialized = true;
				return OResult.CreateSuccessResult(UID);
			}
			successfullyInitialized = false;
			return OResult.CreateFailedResult<string>(oResult);
		}

		/// <summary>
		/// 读取载码体信息，并将读取的信息进行初始化
		/// </summary>
		/// <returns>返回UID信息</returns>
		public OResult<string> ReadRFIDInfo()
		{
			return ReadFromCoreServer(PackReaderCommand(new byte[2] { 112, 0 })).Then<string>(ExtraUID);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Turck.ReaderNet.ReadRFIDInfo" />
		public async Task<OResult<string>> ReadRFIDInfoAsync()
		{
			return (await ReadFromCoreServerAsync(PackReaderCommand(new byte[2] { 112, 0 }))).Then<string>(ExtraUID);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"ReaderNet[{IpAddress}:{Port}]";
		}

		private static string GetErrorText(byte err1, byte err2, byte err3)
		{
			return err1 switch
			{
				1 => "Command not supported", 
				2 => "Command not correctly detected, e.g. wrong format", 
				3 => "Command option not supportde", 
				15 => "Undefined/General error", 
				16 => "Requested memory block not available", 
				17 => "Requested memory block is already locked", 
				18 => "Requested memory block is locked and cannot be written", 
				19 => "Writing of requested memory block not successful", 
				20 => "Requested memory block could not be locked", 
				0 => err2 switch
				{
					1 => "CRC_ERR, telegram fault in the tag-response", 
					2 => "TimeOut_ERR, no tag-response in the given time", 
					4 => "Tag_ERR, tag defect, e.g. multiple crc-faults on the air interface", 
					8 => "CHAIN_ERR, Tag has left the air interface before executing all commands", 
					16 => "UID_ERR, other UID as expected was detected during addressed mode", 
					0 => err3 switch
					{
						1 => "TRANS_ERR, transceiver defect, e.g. Flash-checksum", 
						2 => "CMD_ERR, fault during execution of a command", 
						4 => "syntax_ERR, telegram content not valid, e.g. requested tag-memory address not available", 
						8 => "PS_ERR, power supply too low", 
						16 => "CMD_UNKNOWN, unknown command code", 
						_ => StringResources.Language.UnknownError, 
					}, 
					_ => StringResources.Language.UnknownError, 
				}, 
				_ => "Customer specific error codes", 
			};
		}

		/// <summary>
		/// 将字符串的地址解析出实际的整数地址，如果是位地址，支持使用小数点的形式 例如100.1
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="isBit">是否位地址</param>
		/// <returns>整数地址信息</returns>
		public static OResult<ushort> ParseAddress(string address, bool isBit)
		{
			try
			{
				if (!isBit)
				{
					return OResult.CreateSuccessResult(ushort.Parse(address));
				}
				if (address.IndexOf('.') < 0)
				{
					return OResult.CreateSuccessResult(ushort.Parse(address));
				}
				string[] array = address.SplitDot();
				return OResult.CreateSuccessResult((ushort)(int.Parse(array[0]) * 8 + int.Parse(array[1])));
			}
			catch (Exception ex)
			{
				return new OResult<ushort>("Address input wrong, reason: " + ex.Message);
			}
		}

		/// <summary>
		/// 计算缓存数据里的CRC校验信息，并返回CRC计算的结果
		/// </summary>
		/// <param name="data">数据信息</param>
		/// <param name="len">计算的长度信息</param>
		/// <returns>CRC计算结果</returns>
		public static byte[] CalculateCRC(byte[] data, int len)
		{
			int num = 65535;
			int num2 = 33800;
			byte[] array = new byte[2];
			for (int i = 0; i < len; i++)
			{
				num ^= data[i];
				for (int j = 0; j < 8; j++)
				{
					num = (((num & 1) != 1) ? (num >> 1) : ((num >> 1) ^ num2));
				}
			}
			num = ~num;
			array[0] = Convert.ToByte(num & 0xFF);
			array[1] = Convert.ToByte((num >> 8) & 0xFF);
			return array;
		}

		/// <summary>
		/// 计算并填充CRC校验到原始数据中去
		/// </summary>
		/// <param name="data">原始的数据信息</param>
		/// <param name="len">计算的长度信息</param>
		public static void CalculateAndFillCRC(byte[] data, int len)
		{
			byte[] array = CalculateCRC(data, len);
			data[len] = array[0];
			data[len + 1] = array[1];
		}

		/// <summary>
		/// 校验当前数据的CRC校验是否正确
		/// </summary>
		/// <param name="data">原始数据信息</param>
		/// <param name="len">长度数据信息</param>
		/// <returns>校验结果</returns>
		public static bool CheckCRC(byte[] data, int len)
		{
			byte[] array = CalculateCRC(data, len);
			if (data[len] == array[0])
			{
				return data[len + 1] == array[1];
			}
			return false;
		}

		/// <summary>
		/// 将普通的命令打造成图尔克的reader协议完整命令
		/// </summary>
		/// <param name="command">命令信息</param>
		/// <returns>完整的命令包</returns>
		public static byte[] PackReaderCommand(byte[] command)
		{
			byte[] array = new byte[5 + command.Length];
			array[0] = 170;
			array[1] = (byte)array.Length;
			array[2] = (byte)array.Length;
			command.CopyTo(array, 3);
			CalculateAndFillCRC(array, 3 + command.Length);
			return array;
		}

		/// <summary>
		/// 构建读取的数据块的命令信息，一次最多读取64个字节
		/// </summary>
		/// <param name="startBlock">需要读取的起始 Block。从 0 开始。</param>
		/// <param name="numberBlock">需要读取的 Block 数量。 从 0 开始。</param>
		/// <param name="bytesOfBlock">每个数据块占用的字节数</param>
		/// <returns>完整的命令报文信息</returns>
		private static List<byte[]> BuildReadCommand(byte startBlock, byte numberBlock, byte bytesOfBlock)
		{
			int everyLength = 64 / bytesOfBlock;
			int[] array = SoftBasic.SplitIntegerToArray(numberBlock, everyLength);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				list.Add(PackReaderCommand(new byte[4]
				{
					104,
					0,
					startBlock,
					(byte)(array[i] - 1)
				}));
				startBlock += (byte)array[i];
			}
			return list;
		}

		/// <summary>
		/// 构建写入数据块的命令信息，一次最多写入64个字节
		/// </summary>
		/// <param name="startBlock">需要读取的起始 Block。从 0 开始。</param>
		/// <param name="numberBlock">需要读取的 Block 数量。 从 0 开始。</param>
		/// <param name="bytesOfBlock">每个数据块占用的字节数</param>
		/// <param name="value">写入的数据</param>
		/// <returns>完整的写入的命令报文信息</returns>
		private static List<byte[]> BuildWriteCommand(byte startBlock, byte numberBlock, byte bytesOfBlock, byte[] value)
		{
			if (value == null)
			{
				value = new byte[0];
			}
			int everyLength = 64 / bytesOfBlock;
			int[] array = SoftBasic.SplitIntegerToArray(numberBlock, everyLength);
			List<byte[]> list = new List<byte[]>();
			int num = 0;
			for (int i = 0; i < array.Length; i++)
			{
				byte[] array2 = new byte[4 + array[i] * bytesOfBlock];
				array2[0] = 105;
				array2[1] = 0;
				array2[2] = startBlock;
				array2[3] = (byte)(array[i] - 1);
				value.SelectMiddle(num, array[i] * bytesOfBlock).CopyTo(array2, 4);
				startBlock += (byte)array[i];
				num += array[i] * bytesOfBlock;
				list.Add(PackReaderCommand(array2));
			}
			return list;
		}

		private static void CalculateBlockAddress(ushort address, ushort length, byte bytesOfBlock, out byte startBlock, out byte lengthOfBlock)
		{
			startBlock = (byte)(address / bytesOfBlock);
			int num = (byte)((address + length - 1) / bytesOfBlock);
			lengthOfBlock = (byte)(num - startBlock + 1);
		}
	}
	/// <summary>
	/// 图尔克reader协议的虚拟服务器
	/// </summary>
	public class ReaderServer : DeviceServer
	{
		private int bytesOfBlock = 8;

		private SoftBuffer buffer;

		private const int DataPoolLength = 65536;

		/// <summary>
		/// 获取或设置每个block占用的字节数信息
		/// </summary>
		public int BytesOfBlock
		{
			get
			{
				return bytesOfBlock;
			}
			set
			{
				bytesOfBlock = value;
			}
		}

		/// <summary>
		/// 实例化一个默认的图尔克虚拟服务器
		/// </summary>
		public ReaderServer()
		{
			base.WordLength = 2;
			base.ByteTransform = new ReverseBytesTransform();
			buffer = new SoftBuffer(65536);
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new TurckReaderMessage();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (!ReaderNet.CheckCRC(receive, receive.Length - 2))
			{
				return OResult.CreateSuccessResult(ReaderNet.PackReaderCommand(new byte[5]
				{
					receive[3],
					131,
					0,
					1,
					0
				}));
			}
			CommunicationPipe communication = session.Communication;
			byte[] array = null;
			if (receive[3] == 104)
			{
				byte[] array2 = ReaderNet.PackReaderCommand(new byte[2] { 104, 137 });
				LogSendMessage(array2, session);
				communication.Send(array2);
				array = ReadByMessage(receive);
			}
			else if (receive[3] == 105)
			{
				byte[] array3 = ReaderNet.PackReaderCommand(new byte[2] { 105, 137 });
				LogSendMessage(array3, session);
				communication.Send(array3);
				array = WriteByMessage(receive);
			}
			else
			{
				if (receive[3] != 112)
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedFunction);
				}
				byte[] array4 = ReaderNet.PackReaderCommand(new byte[2] { 112, 137 });
				LogSendMessage(array4, session);
				communication.Send(array4);
				byte[] obj = new byte[15]
				{
					112, 138, 113, 38, 208, 229, 215, 1, 8, 224,
					0, 0, 249, 0, 116
				};
				obj[13] = (byte)(bytesOfBlock - 1);
				array = ReaderNet.PackReaderCommand(obj);
			}
			return OResult.CreateSuccessResult(array);
		}

		private byte[] ReadByMessage(byte[] receive)
		{
			byte[] bytes = buffer.GetBytes(receive[5] * bytesOfBlock, (receive[6] + 1) * bytesOfBlock);
			return ReaderNet.PackReaderCommand(SoftBasic.SpliceArray<byte>(new byte[2]
			{
				receive[3],
				154
			}, bytes));
		}

		private byte[] WriteByMessage(byte[] receive)
		{
			if (!base.EnableWrite)
			{
				return ReaderNet.PackReaderCommand(new byte[5]
				{
					receive[3],
					131,
					18,
					0,
					0
				});
			}
			if ((receive[6] + 1) * bytesOfBlock != receive.Length - 9)
			{
				return ReaderNet.PackReaderCommand(new byte[5]
				{
					receive[3],
					131,
					1,
					0,
					0
				});
			}
			buffer.SetBytes(receive.SelectMiddle(7, receive.Length - 9), receive[5] * bytesOfBlock);
			return ReaderNet.PackReaderCommand(new byte[2]
			{
				receive[3],
				138
			});
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"ReaderServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Toyota
{
	/// <summary>
	/// 丰田工机的计算机链接协议实现，通过2PORT-EFR模块实现对PLC的读写数据操作，需要在PLC配置相关的以太网端口信息，才能进行通信。具体的地址参考DEMO程序信息。<br />
	/// Toyota Gongki's computer link protocol realizes the reading and writing data operation of the PLC through the 2PORT-EFR module, 
	/// and the relevant Ethernet port information needs to be configured in the PLC in order to communicate. For specific addresses, refer to Demo UI.
	/// </summary>
	/// <remarks>
	/// 感谢QQ：435416143 对本类的测试，时间：2023年5月2日<br />
	/// 位地址支持  K,V,T,C,L,X,Y,M,EK,EV,EC,ET,EL,EX,EY,EM,GX,GY,GM 地址，也可以指定prg参数，例如 prg=1;K000<br />
	/// 当然也可以使用字地址访问上述的位地址的，例如 M100~M10F 的位地址，就等于 M10 读字，也就是short。字地址额外支持：S,N,R,D,B,ES,EN,H,U,EB
	/// </remarks>
	public class ToyoPuc : DeviceTcpNet
	{
		private class WordAddress
		{
			public string Address { get; set; }

			public int BitIndex { get; set; }

			public ushort WordLength { get; set; }
		}

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public ToyoPuc()
		{
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
		}

		/// <summary>
		/// 指定IP地址，端口号信息来实例化一个对象
		/// </summary>
		/// <param name="ipAddress">IP地址</param>
		/// <param name="port">端口号</param>
		public ToyoPuc(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new ToyoPucMessage();
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			byte[] array = new byte[command.Length + 4];
			array[2] = BitConverter.GetBytes(command.Length)[0];
			array[3] = BitConverter.GetBytes(command.Length)[1];
			command.CopyTo(array, 4);
			return array;
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			if (response == null || response.Length < 4)
			{
				return new OResult<byte[]>("Receive data too short: " + response.ToHexString(' '));
			}
			if (response[0] != 128)
			{
				return new OResult<byte[]>("FT check failed: " + response.ToHexString(' '));
			}
			if (response[1] != 0)
			{
				return new OResult<byte[]>((response.Length == 4) ? GetErrorText(response[1]) : GetErrorText(response[4]));
			}
			if (response.Length > 5)
			{
				return OResult.CreateSuccessResult(response.RemoveBegin(5));
			}
			return OResult.CreateSuccessResult(new byte[0]);
		}

		private static string GetErrorText(byte code)
		{
			return code switch
			{
				17 => StringResources.Language.ToyoPuc11, 
				32 => StringResources.Language.ToyoPuc20, 
				33 => StringResources.Language.ToyoPuc21, 
				35 => StringResources.Language.ToyoPuc23, 
				36 => StringResources.Language.ToyoPuc24, 
				37 => StringResources.Language.ToyoPuc25, 
				52 => StringResources.Language.ToyoPuc34, 
				62 => StringResources.Language.ToyoPuc3E, 
				63 => StringResources.Language.ToyoPuc3F, 
				64 => StringResources.Language.ToyoPuc40, 
				65 => StringResources.Language.ToyoPuc41, 
				_ => StringResources.Language.UnknownError, 
			};
		}

		private OResult<WordAddress> ExtraWordAddress(string address, ushort length)
		{
			try
			{
				int num = 0;
				int num2 = address.IndexOf('.');
				if (num2 > 0)
				{
					num = Convert.ToInt32(address.Substring(num2 + 1), 16);
					address = address.Substring(0, num2);
				}
				else
				{
					num = Convert.ToInt32(address.Substring(address.Length - 1), 16);
					address = address.Substring(0, address.Length - 1);
					if (address.StartsWith("EK", StringComparison.OrdinalIgnoreCase) || address.StartsWith("EV", StringComparison.OrdinalIgnoreCase) || address.StartsWith("ET", StringComparison.OrdinalIgnoreCase) || address.StartsWith("EC", StringComparison.OrdinalIgnoreCase) || address.StartsWith("EL", StringComparison.OrdinalIgnoreCase) || address.StartsWith("EX", StringComparison.OrdinalIgnoreCase) || address.StartsWith("EY", StringComparison.OrdinalIgnoreCase) || address.StartsWith("EM", StringComparison.OrdinalIgnoreCase))
					{
						if (address.Length == 2)
						{
							address += "0";
						}
					}
					else if (address.Length == 1)
					{
						address += "0";
					}
				}
				int num3 = (num + length + 15) / 16;
				return OResult.CreateSuccessResult(new WordAddress
				{
					Address = address,
					BitIndex = num,
					WordLength = (ushort)num3
				});
			}
			catch (Exception ex)
			{
				return new OResult<WordAddress>("ExtraWordAddress failed: " + ex.Message);
			}
		}

		/// <inheritdoc />
		/// <remarks>
		/// 地址类型地址 K,V,T,C,L,X,Y,M,EK,EV,EC,ET,EL,EX,EY,EM 地址，也可以指定程序号(prg)参数，例如 prg=1;K000
		/// </remarks>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (address.IndexOf(".") > 0)
			{
				return SnetHelper.ReadBool(this, address, length);
			}
			OResult<WordAddress> oResult = ExtraWordAddress(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = Read(oResult.Content.Address, oResult.Content.WordLength);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectMiddle(oResult.Content.BitIndex, length));
		}

