		private static OResult<byte[]> BuildReadBoolCommand(string address)
		{
			OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(address, 1, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			ToyoPucAddress content = oResult.Content;
			if (content.PRG >= 0)
			{
				return new OResult<byte[]>();
			}
			return OResult.CreateSuccessResult(new byte[3]
			{
				32,
				BitConverter.GetBytes(content.AddressStart)[0],
				BitConverter.GetBytes(content.AddressStart)[1]
			});
		}

		private static OResult<byte[]> BuildReadWordCommand(string address, ushort length)
		{
			OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			ToyoPucAddress content = oResult.Content;
			if (content.PRG >= 0)
			{
				return OResult.CreateSuccessResult(new byte[6]
				{
					148,
					(byte)content.PRG,
					BitConverter.GetBytes(content.AddressStart)[0],
					BitConverter.GetBytes(content.AddressStart)[1],
					BitConverter.GetBytes(length)[0],
					BitConverter.GetBytes(length)[1]
				});
			}
			return OResult.CreateSuccessResult(new byte[5]
			{
				28,
				BitConverter.GetBytes(content.AddressStart)[0],
				BitConverter.GetBytes(content.AddressStart)[1],
				BitConverter.GetBytes(length)[0],
				BitConverter.GetBytes(length)[1]
			});
		}

		private static OResult<byte[]> BuildWriteWordCommand(string address, byte[] value)
		{
			OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(address, 1, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			ToyoPucAddress content = oResult.Content;
			if (content.PRG >= 0)
			{
				byte[] array = new byte[4 + value.Length];
				array[0] = 149;
				array[1] = (byte)content.PRG;
				array[2] = BitConverter.GetBytes(content.AddressStart)[0];
				array[3] = BitConverter.GetBytes(content.AddressStart)[1];
				value.CopyTo(array, 4);
				return OResult.CreateSuccessResult(array);
			}
			byte[] array2 = new byte[3 + value.Length];
			array2[0] = 29;
			array2[1] = BitConverter.GetBytes(content.AddressStart)[0];
			array2[2] = BitConverter.GetBytes(content.AddressStart)[1];
			value.CopyTo(array2, 3);
			return OResult.CreateSuccessResult(array2);
		}

		private static OResult<byte[]> BuildWriteBoolCommand(string address, bool value)
		{
			OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(address, 1, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (!oResult.Content.WriteBitEnabled)
			{
				return new OResult<byte[]>("Address: " + address + "  is not support write bit, because it is word address");
			}
			ToyoPucAddress content = oResult.Content;
			if (content.PRG >= 0)
			{
				return new OResult<byte[]>("Not supported prg write bool");
			}
			byte[] array = new byte[4]
			{
				33,
				BitConverter.GetBytes(content.AddressStart)[0],
				BitConverter.GetBytes(content.AddressStart)[1],
				0
			};
			if (value)
			{
				array[3] = 1;
			}
			return OResult.CreateSuccessResult(array);
		}

		private static OResult<List<byte[]>> BuildReadRandomCommand(string[] address)
		{
			List<string[]> list = SoftBasic.ArraySplitByLength(address, 80);
			List<byte[]> list2 = new List<byte[]>();
			for (int i = 0; i < list.Count; i++)
			{
				string[] array = list[i];
				byte[] array2 = new byte[1 + array.Length * 2];
				array2[0] = 34;
				for (int j = 0; j < array.Length; j++)
				{
					OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(array[j], 1, isBit: false);
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<List<byte[]>>(oResult);
					}
					ToyoPucAddress content = oResult.Content;
					array2[j * 2 + 1] = BitConverter.GetBytes(content.AddressStart)[0];
					array2[j * 2 + 2] = BitConverter.GetBytes(content.AddressStart)[1];
				}
				list2.Add(array2);
			}
			return OResult.CreateSuccessResult(list2);
		}
	}
	/// <summary>
	/// 丰田工机的PLC对象信息
	/// </summary>
	public class ToyoPucServer : DeviceServer
	{
		private SoftBuffer buffer1;

		private SoftBuffer buffer00;

		private SoftBuffer buffer01;

		private SoftBuffer buffer02;

		private SoftBuffer buffer03;

		private SoftBuffer buffer08;

		private const int DataPoolLength = 65536;

		private int station;

		/// <summary>
		/// 实例化一个丰田工机PLC的网口和串口服务器，支持数据读写操作
		/// </summary>
		public ToyoPucServer()
		{
			buffer1 = new SoftBuffer(65536);
			buffer00 = new SoftBuffer(65536);
			buffer01 = new SoftBuffer(65536);
			buffer02 = new SoftBuffer(65536);
			buffer03 = new SoftBuffer(65536);
			buffer08 = new SoftBuffer(65536);
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new ToyoPucMessage();
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[393216];
			buffer1.GetBytes().CopyTo(array, 0);
			buffer00.GetBytes().CopyTo(array, 65536);
			buffer01.GetBytes().CopyTo(array, 131072);
			buffer02.GetBytes().CopyTo(array, 196608);
			buffer03.GetBytes().CopyTo(array, 262144);
			buffer08.GetBytes().CopyTo(array, 327680);
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 393216)
			{
				throw new Exception("File is not correct");
			}
			buffer1.SetBytes(content, 0, 65536);
			buffer00.SetBytes(content, 65536, 65536);
			buffer01.SetBytes(content, 131072, 65536);
			buffer02.SetBytes(content, 196608, 65536);
			buffer03.SetBytes(content, 262144, 65536);
			buffer08.SetBytes(content, 327680, 65536);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Toyota.ToyoPuc.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			ToyoPucAddress content = oResult.Content;
			if (content.PRG >= 0)
			{
				if (content.PRG == 0)
				{
					return OResult.CreateSuccessResult(buffer00.GetBytes(content.AddressStart * 2, length * 2));
				}
				if (content.PRG == 1)
				{
					return OResult.CreateSuccessResult(buffer01.GetBytes(content.AddressStart * 2, length * 2));
				}
				if (content.PRG == 2)
				{
					return OResult.CreateSuccessResult(buffer02.GetBytes(content.AddressStart * 2, length * 2));
				}
				if (content.PRG == 3)
				{
					return OResult.CreateSuccessResult(buffer03.GetBytes(content.AddressStart * 2, length * 2));
				}
				if (content.PRG == 8)
				{
					return OResult.CreateSuccessResult(buffer08.GetBytes(content.AddressStart * 2, length * 2));
				}
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
			}
			return OResult.CreateSuccessResult(buffer1.GetBytes(content.AddressStart * 2, length * 2));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Toyota.ToyoPuc.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(address, 1, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			ToyoPucAddress content = oResult.Content;
			if (content.PRG >= 0)
			{
				if (content.PRG == 0)
				{
					buffer00.SetBytes(value, content.AddressStart * 2);
				}
				else if (content.PRG == 1)
				{
					buffer01.SetBytes(value, content.AddressStart * 2);
				}
				else if (content.PRG == 2)
				{
					buffer02.SetBytes(value, content.AddressStart * 2);
				}
				else if (content.PRG == 3)
				{
					buffer03.SetBytes(value, content.AddressStart * 2);
				}
				else
				{
					if (content.PRG != 8)
					{
						return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
					}
					buffer08.SetBytes(value, content.AddressStart * 2);
				}
				return OResult.CreateSuccessResult();
			}
			buffer1.SetBytes(value, content.AddressStart * 2);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Toyota.ToyoPuc.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (address.IndexOf(".") > 0)
			{
				return SnetHelper.ReadBool(this, address, length);
			}
			OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			ToyoPucAddress content = oResult.Content;
			if (content.PRG >= 0)
			{
				if (content.PRG == 0)
				{
					return OResult.CreateSuccessResult(buffer00.GetBool(content.AddressStart, length));
				}
				if (content.PRG == 1)
				{
					return OResult.CreateSuccessResult(buffer01.GetBool(content.AddressStart, length));
				}
				if (content.PRG == 2)
				{
					return OResult.CreateSuccessResult(buffer02.GetBool(content.AddressStart, length));
				}
				if (content.PRG == 3)
				{
					return OResult.CreateSuccessResult(buffer03.GetBool(content.AddressStart, length));
				}
				if (content.PRG == 8)
				{
					return OResult.CreateSuccessResult(buffer08.GetBool(content.AddressStart, length));
				}
				return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
			}
			return OResult.CreateSuccessResult(buffer1.GetBool(content.AddressStart, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceCommunication.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			if (address.IndexOf(".") > 0)
			{
				return SnetHelper.WriteBool(this, address, value);
			}
			OResult<ToyoPucAddress> oResult = ToyoPucAddress.ParseFrom(address, 1, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			ToyoPucAddress content = oResult.Content;
			if (content.PRG >= 0)
			{
				if (content.PRG == 0)
				{
					buffer00.SetBool(value, content.AddressStart);
				}
				else if (content.PRG == 1)
				{
					buffer01.SetBool(value, content.AddressStart);
				}
				else if (content.PRG == 2)
				{
					buffer02.SetBool(value, content.AddressStart);
				}
				else if (content.PRG == 3)
				{
					buffer03.SetBool(value, content.AddressStart);
				}
				else
				{
					if (content.PRG != 8)
					{
						return new OResult<byte[]>("Not supported prg write bool");
					}
					buffer08.SetBool(value, content.AddressStart);
				}
				return OResult.CreateSuccessResult();
			}
			buffer1.SetBool(value, content.AddressStart);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive.Length < 5)
			{
				return null;
			}
			try
			{
				byte[] array = null;
				if (receive[4] == 28)
				{
					array = ReadWordByCommand(receive);
				}
				else if (receive[4] == 32)
				{
					array = ReadBoolByCommand(receive);
				}
				else if (receive[4] == 29)
				{
					array = WriteWordByCommand(receive);
				}
				else if (receive[4] == 33)
				{
					array = WriteBoolByCommand(receive);
				}
				else if (receive[4] == 34)
				{
					array = ReadRandomWord(receive);
				}
				else if (receive[4] == 35)
				{
					array = WriteRandomWord(receive);
				}
				else if (receive[4] == 148)
				{
					array = ReadExWordByCommand(receive);
				}
				else if (receive[4] == 149)
				{
					array = WriteExWordByCommand(receive);
				}
				if (array != null)
				{
					return OResult.CreateSuccessResult(array);
				}
				return OResult.CreateSuccessResult(CreateResponseBack(receive, 35, null));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		private byte[] CreateResponseBack(byte[] request, byte err, byte[] data)
		{
			if (err != 0)
			{
				byte[] obj = new byte[5] { 128, 16, 1, 0, 0 };
				obj[4] = err;
				return obj;
			}
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[5 + data.Length];
			array[0] = 128;
			array[1] = 0;
			array[2] = BitConverter.GetBytes(data.Length + 1)[0];
			array[3] = BitConverter.GetBytes(data.Length + 1)[1];
			array[4] = request[4];
			if (data.Length != 0)
			{
				data.CopyTo(array, 5);
			}
			return array;
		}

		private byte[] ReadWordByCommand(byte[] command)
		{
			ushort num = BitConverter.ToUInt16(command, 5);
			ushort num2 = BitConverter.ToUInt16(command, 7);
			return CreateResponseBack(command, 0, buffer1.GetBytes(num * 2, num2 * 2));
		}

		private byte[] ReadExWordByCommand(byte[] command)
		{
			ushort num = BitConverter.ToUInt16(command, 6);
			ushort num2 = BitConverter.ToUInt16(command, 8);
			if (command[5] == 0)
			{
				return CreateResponseBack(command, 0, buffer00.GetBytes(num * 2, num2 * 2));
			}
			if (command[5] == 1)
			{
				return CreateResponseBack(command, 0, buffer01.GetBytes(num * 2, num2 * 2));
			}
			if (command[5] == 2)
			{
				return CreateResponseBack(command, 0, buffer02.GetBytes(num * 2, num2 * 2));
			}
			if (command[5] == 3)
			{
				return CreateResponseBack(command, 0, buffer03.GetBytes(num * 2, num2 * 2));
			}
			if (command[5] == 8)
			{
				if (num * 2 > 65535 || num * 2 + num2 * 2 > 65536)
				{
					return CreateResponseBack(command, 64, null);
				}
				return CreateResponseBack(command, 0, buffer08.GetBytes(num * 2, num2 * 2));
			}
			return CreateResponseBack(command, 52, null);
		}

		private byte[] ReadRandomWord(byte[] command)
		{
			int num = (command.Length - 5) / 2;
			if (num > 80)
			{
				return CreateResponseBack(command, 64, null);
			}
			byte[] array = new byte[num * 2];
			for (int i = 5; i < command.Length - 1; i += 2)
			{
				ushort num2 = BitConverter.ToUInt16(command, i);
				buffer1.GetBytes(num2 * 2, 2).CopyTo(array, i - 5);
			}
			return CreateResponseBack(command, 0, array);
		}

		private byte[] WriteRandomWord(byte[] command)
		{
			int num = (command.Length - 5) / 4;
			if (num > 80)
			{
				return CreateResponseBack(command, 64, null);
			}
			for (int i = 0; i < num; i++)
			{
				ushort destIndex = BitConverter.ToUInt16(command, i * 4 + 5);
				buffer1.SetBytes(command.SelectMiddle(i * 4 + 7, 2), destIndex);
			}
			return CreateResponseBack(command, 0, null);
		}

		private byte[] ReadBoolByCommand(byte[] command)
		{
			ushort destIndex = BitConverter.ToUInt16(command, 5);
			bool flag = buffer1.GetBool(destIndex);
			return CreateResponseBack(command, 0, new byte[1] { flag ? ((byte)1) : ((byte)0) });
		}

		private byte[] WriteWordByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return CreateResponseBack(command, 52, null);
			}
			ushort num = BitConverter.ToUInt16(command, 5);
			buffer1.SetBytes(command.RemoveBegin(7), num * 2);
			return CreateResponseBack(command, 0, null);
		}

		private byte[] WriteExWordByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return CreateResponseBack(command, 52, null);
			}
			ushort num = BitConverter.ToUInt16(command, 6);
			if (command[5] == 0)
			{
				buffer00.SetBytes(command.RemoveBegin(8), num * 2);
			}
			else if (command[5] == 1)
			{
				buffer01.SetBytes(command.RemoveBegin(8), num * 2);
			}
			else if (command[5] == 2)
			{
				buffer02.SetBytes(command.RemoveBegin(8), num * 2);
			}
			else if (command[5] == 3)
			{
				buffer03.SetBytes(command.RemoveBegin(8), num * 2);
			}
			else
			{
				if (command[5] != 8)
				{
					return CreateResponseBack(command, 52, null);
				}
				if (num * 2 > 65535)
				{
					return CreateResponseBack(command, 64, null);
				}
				buffer08.SetBytes(command.RemoveBegin(8), num * 2);
			}
			return CreateResponseBack(command, 0, null);
		}

		private byte[] WriteBoolByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return CreateResponseBack(command, 52, null);
			}
			ushort destIndex = BitConverter.ToUInt16(command, 5);
			buffer1.SetBool(command[7] != 0, destIndex);
			return CreateResponseBack(command, 0, null);
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				buffer1.Dispose();
				buffer00.Dispose();
				buffer01.Dispose();
				buffer02.Dispose();
				buffer03.Dispose();
				buffer08.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"ToyoPucServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Toledo
{
	/// <summary>
	/// 托利多电子秤的串口服务器对象
	/// </summary>
	public class ToledoSerial
	{
		/// <summary>
		/// 托利多数据接收时的委托
		/// </summary>
		/// <param name="sender">数据发送对象</param>
		/// <param name="toledoStandardData">数据对象</param>
		public delegate void ToledoStandardDataReceivedDelegate(object sender, ToledoStandardData toledoStandardData);

		private SerialPort serialPort;

		private ILogNet logNet;

		private int receiveTimeout;

		/// <inheritdoc cref="P:Snet.Driver.Core.Net.NetworkBase.LogNet" />
		public ILogNet LogNet
		{
			get
			{
				return logNet;
			}
			set
			{
				logNet = value;
			}
		}

		/// <summary>
		/// 获取或设置一个值，该值指示在串行通信中是否启用请求发送 (RTS) 信号。<br />
		/// Gets or sets a value indicating whether the request sending (RTS) signal is enabled in serial communication.
		/// </summary>
		public bool RtsEnable
		{
			get
			{
				return serialPort.RtsEnable;
			}
			set
			{
				serialPort.RtsEnable = value;
			}
		}

		/// <summary>
		/// 当前连接串口信息的端口号名称<br />
		/// The port name of the current connection serial port information
		/// </summary>
		public string PortName { get; private set; }

		/// <summary>
		/// 当前连接串口信息的波特率<br />
		/// Baud rate of current connection serial port information
		/// </summary>
		public int BaudRate { get; private set; }

		/// <summary>
		/// 接收数据的超时时间，默认5000ms<br />
		/// Timeout for receiving data, default is 5000ms
		/// </summary>
		public int ReceiveTimeout
		{
			get
			{
				return receiveTimeout;
			}
			set
			{
				receiveTimeout = value;
			}
		}

		/// <summary>
		/// 获取或设置当前的报文否是含有校验的，默认为含有校验
		/// </summary>
		public bool HasChk { get; set; }

		/// <summary>
		/// 当接收到一条新的托利多的数据的时候触发
		/// </summary>
		public event ToledoStandardDataReceivedDelegate OnToledoStandardDataReceived;

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public ToledoSerial()
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_001c: Expected O, but got Unknown
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_003f: Expected O, but got Unknown
			receiveTimeout = 5000;
			base..ctor();
			serialPort = new SerialPort();
			serialPort.RtsEnable = true;
			serialPort.DataReceived += new SerialDataReceivedEventHandler(SerialPort_DataReceived);
		}

		private void SerialPort_DataReceived(object sender, SerialDataReceivedEventArgs e)
		{
			List<byte> list = new List<byte>();
			byte[] array = new byte[1024];
			int num = 0;
			do
			{
				IL_0013:
				SnetHelper.ThreadSleep(20);
				if (serialPort.BytesToRead < 1)
				{
					num++;
					continue;
				}
				num = 0;
				try
				{
					int num2 = serialPort.Read(array, 0, Math.Min(serialPort.BytesToRead, array.Length));
					byte[] array2 = new byte[num2];
					Array.Copy(array, 0, array2, 0, num2);
					list.AddRange(array2);
					if (HasChk)
					{
						if (list.Count <= 15 || list[list.Count - 2] != 13)
						{
							goto IL_0013;
						}
					}
					else if ((list.Count <= 15 || list[list.Count - 1] != 13) && (list.Count <= 15 || list[list.Count - 2] != 13))
					{
						goto IL_0013;
					}
				}
				catch (Exception ex)
				{
					logNet?.WriteException(ToString(), "SerialPort_DataReceived", ex);
					return;
				}
				break;
			}
			while (num < 3);
			if (list.Count != 0)
			{
				byte[] array3 = list.ToArray();
				LogNet?.WriteDebug(ToString(), StringResources.Language.Receive + " : " + array3.ToHexString(' '));
				ToledoStandardData toledoStandardData = null;
				try
				{
					toledoStandardData = new ToledoStandardData(array3);
				}
				catch (Exception ex2)
				{
					logNet?.WriteException(ToString(), "ToledoStandardData new failed: " + array3.ToHexString(' '), ex2);
				}
				if (toledoStandardData != null)
				{
					OnToledoStandardDataReceived?.Invoke(this, toledoStandardData);
				}
			}
		}

		/// <summary>
		/// 初始化串口信息，9600波特率，8位数据位，1位停止位，无奇偶校验<br />
		/// Initial serial port information, 9600 baud rate, 8 data bits, 1 stop bit, no parity
		/// </summary>
		/// <param name="portName">端口号信息，例如"COM3"</param>
		public void SerialPortInni(string portName)
		{
			SerialPortInni(portName, 9600);
		}

		/// <summary>
		/// 初始化串口信息，波特率，8位数据位，1位停止位，无奇偶校验<br />
		/// Initializes serial port information, baud rate, 8-bit data bit, 1-bit stop bit, no parity
		/// </summary>
		/// <param name="portName">端口号信息，例如"COM3"</param>
		/// <param name="baudRate">波特率</param>
		public void SerialPortInni(string portName, int baudRate)
		{
			SerialPortInni(portName, baudRate, 8, (StopBits)1, (Parity)0);
		}

		/// <summary>
		/// 初始化串口信息，波特率，数据位，停止位，奇偶校验需要全部自己来指定<br />
		/// Start serial port information, baud rate, data bit, stop bit, parity all need to be specified
		/// </summary>
		/// <param name="portName">端口号信息，例如"COM3"</param>
		/// <param name="baudRate">波特率</param>
		/// <param name="dataBits">数据位</param>
		/// <param name="stopBits">停止位</param>
		/// <param name="parity">奇偶校验</param>
		public void SerialPortInni(string portName, int baudRate, int dataBits, StopBits stopBits, Parity parity)
		{
			//IL_0037: Unknown result type (might be due to invalid IL or missing references)
			//IL_0044: Unknown result type (might be due to invalid IL or missing references)
			if (!serialPort.IsOpen)
			{
				serialPort.PortName = portName;
				serialPort.BaudRate = baudRate;
				serialPort.DataBits = dataBits;
				serialPort.StopBits = stopBits;
				serialPort.Parity = parity;
				PortName = serialPort.PortName;
				BaudRate = serialPort.BaudRate;
			}
		}

		/// <summary>
		/// 根据自定义初始化方法进行初始化串口信息<br />
		/// Initialize the serial port information according to the custom initialization method
		/// </summary>
		/// <param name="initi">初始化的委托方法</param>
		public void SerialPortInni(Action<SerialPort> initi)
		{
			if (!serialPort.IsOpen)
			{
				serialPort.PortName = "COM5";
				serialPort.BaudRate = 9600;
				serialPort.DataBits = 8;
				serialPort.StopBits = (StopBits)1;
				serialPort.Parity = (Parity)0;
				initi(serialPort);
				PortName = serialPort.PortName;
				BaudRate = serialPort.BaudRate;
			}
		}

		/// <summary>
		/// 打开一个新的串行端口连接<br />
		/// Open a new serial port connection
		/// </summary>
		public void Open()
		{
			if (!serialPort.IsOpen)
			{
				serialPort.Open();
			}
		}

		/// <summary>
		/// 获取一个值，指示串口是否处于打开状态<br />
		/// Gets a value indicating whether the serial port is open
		/// </summary>
		/// <returns>是或否</returns>
		public bool IsOpen()
		{
			return serialPort.IsOpen;
		}

		/// <summary>
		/// 关闭当前的串口连接<br />
		/// Close the current serial connection
		/// </summary>
		public void Close()
		{
			if (serialPort.IsOpen)
			{
				serialPort.Close();
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return base.ToString();
		}
	}
	/// <summary>
	/// 托利多标准格式的数据类对象
	/// </summary>
	public class ToledoStandardData
	{
		/// <summary>
		/// 为 True 则是净重，为 False 则为毛重
		/// </summary>
		public bool Suttle { get; set; }

		/// <summary>
		/// 为 True 则是正，为 False 则为负
		/// </summary>
		public bool Symbol { get; set; }

		/// <summary>
		/// 是否在范围之外
		/// </summary>
		public bool BeyondScope { get; set; }

		/// <summary>
		/// 是否为动态，为 True 则是动态，为 False 则为稳态
		/// </summary>
		public bool DynamicState { get; set; }

		/// <summary>
		/// 单位
		/// </summary>
		public string Unit { get; set; }

		/// <summary>
		/// 是否打印
		/// </summary>
		public bool IsPrint { get; set; }

		/// <summary>
		/// 是否10被扩展
		/// </summary>
		public bool IsTenExtend { get; set; }

		/// <summary>
		/// 重量
		/// </summary>
		public float Weight { get; set; }

		/// <summary>
		/// 皮重
		/// </summary>
		public float Tare { get; set; }

		/// <summary>
		/// 皮重类型，0: 无皮重; 1: 按键去皮; 2: 预置去皮; 3: 皮重内存，仅在扩展输出下有效
		/// </summary>
		public int TareType { get; set; }

		/// <summary>
		/// 数据是否有效
		/// </summary>
		public bool DataValid { get; set; } = true;

		/// <summary>
		/// 是否属于扩展输出模式
		/// </summary>
		public bool IsExpandOutput { get; set; }

		/// <summary>
		/// 解析数据的原始字节
		/// </summary>
		[JsonIgnore]
		public byte[] SourceData { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public ToledoStandardData()
		{
		}

		/// <summary>
		/// 从缓存里加载一个标准格式的对象
		/// </summary>
		/// <param name="buffer">缓存</param>
		public ToledoStandardData(byte[] buffer)
		{
			if (buffer[0] == 2)
			{
				ParseFromStandardOutput(buffer);
			}
			else if (buffer[0] == 1)
			{
				ParseFromExpandOutput(buffer);
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"ToledoStandardData[{Weight}]";
		}

		/// <summary>
		/// 从连续标准的模式里解析出真实的数据信息
		/// </summary>
		/// <param name="buffer">接收到的数据缓存</param>
		/// <returns>托利多的数据对象</returns>
		private void ParseFromStandardOutput(byte[] buffer)
		{
			Weight = float.Parse(Encoding.ASCII.GetString(buffer, 4, 6));
			Tare = float.Parse(Encoding.ASCII.GetString(buffer, 10, 6));
			switch (buffer[1] & 7)
			{
			case 0:
				Weight *= 100f;
				Tare *= 100f;
				break;
			case 1:
				Weight *= 10f;
				Tare *= 10f;
				break;
			case 3:
				Weight /= 10f;
				Tare /= 10f;
				break;
			case 4:
				Weight /= 100f;
				Tare /= 100f;
				break;
			case 5:
				Weight /= 1000f;
				Tare /= 1000f;
				break;
			case 6:
				Weight /= 10000f;
				Tare /= 10000f;
				break;
			case 7:
				Weight /= 100000f;
				Tare /= 100000f;
				break;
			}
			Suttle = SoftBasic.BoolOnByteIndex(buffer[2], 0);
			Symbol = SoftBasic.BoolOnByteIndex(buffer[2], 1);
			BeyondScope = SoftBasic.BoolOnByteIndex(buffer[2], 2);
			DynamicState = SoftBasic.BoolOnByteIndex(buffer[2], 3);
			switch (buffer[3] & 7)
			{
			case 0:
				Unit = (SoftBasic.BoolOnByteIndex(buffer[2], 4) ? "kg" : "lb");
				break;
			case 1:
				Unit = "g";
				break;
			case 2:
				Unit = "t";
				break;
			case 3:
				Unit = "oz";
				break;
			case 4:
				Unit = "ozt";
				break;
			case 5:
				Unit = "dwt";
				break;
			case 6:
				Unit = "ton";
				break;
			case 7:
				Unit = "newton";
				break;
			}
			IsPrint = SoftBasic.BoolOnByteIndex(buffer[3], 3);
			IsTenExtend = SoftBasic.BoolOnByteIndex(buffer[3], 4);
			SourceData = buffer;
		}

		private void ParseFromExpandOutput(byte[] buffer)
		{
			IsExpandOutput = true;
			string text = Encoding.ASCII.GetString(buffer, 6, 9).Replace(" ", "");
			if (!string.IsNullOrEmpty(text))
			{
				Weight = float.Parse(text);
			}
			string text2 = Encoding.ASCII.GetString(buffer, 15, 8).Replace(" ", "");
			if (!string.IsNullOrEmpty(text2))
			{
				Tare = float.Parse(text2);
			}
			switch (buffer[2] & 0xF)
			{
			case 0:
				Unit = "None";
				break;
			case 1:
				Unit = "lb";
				break;
			case 2:
				Unit = "kg";
				break;
			case 3:
				Unit = "g";
				break;
			case 4:
				Unit = "t";
				break;
			case 5:
				Unit = "ton";
				break;
			case 8:
				Unit = "oz";
				break;
			case 9:
				Unit = "newton";
				break;
			}
			DynamicState = SoftBasic.BoolOnByteIndex(buffer[2], 6);
			Suttle = SoftBasic.BoolOnByteIndex(buffer[3], 0);
			TareType = (buffer[3] & 6) >> 1;
			BeyondScope = SoftBasic.BoolOnByteIndex(buffer[4], 1) || SoftBasic.BoolOnByteIndex(buffer[4], 2);
			IsPrint = SoftBasic.BoolOnByteIndex(buffer[4], 4);
			DataValid = SoftBasic.BoolOnByteIndex(buffer[4], 0);
			SourceData = buffer;
		}
	}
	/// <summary>
	/// 托利多电子秤的TCP服务器，启动服务器后，等待电子秤的数据连接。
	/// </summary>
	public class ToledoTcpServer : CommunicationServer
	{
		/// <summary>
		/// 托利多数据接收时的委托
		/// </summary>
		/// <param name="sender">数据发送对象</param>
		/// <param name="toledoStandardData">数据对象</param>
		public delegate void ToledoStandardDataReceivedDelegate(object sender, ToledoStandardData toledoStandardData);

		/// <summary>
		/// 获取或设置当前的报文否是含有校验的，默认为含有校验
		/// </summary>
		public bool HasChk { get; set; } = true;

		/// <summary>
		/// 当接收到一条新的托利多的数据的时候触发
		/// </summary>
		public event ToledoStandardDataReceivedDelegate OnToledoStandardDataReceived;

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public ToledoTcpServer()
		{
			base.OnPipeMessageReceived += ToledoTcpServer_OnPipeMessageReceived;
		}

		private void ToledoTcpServer_OnPipeMessageReceived(PipeSession session, byte[] buffer)
		{
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Receive + " : " + buffer.ToHexString(' '));
			ToledoStandardData toledoStandardData = null;
			try
			{
				toledoStandardData = new ToledoStandardData(buffer);
			}
			catch (Exception ex)
			{
				base.LogNet?.WriteException(ToString(), "ToledoStandardData new failed: " + buffer.ToHexString(' '), ex);
			}
			if (toledoStandardData != null)
			{
				OnToledoStandardDataReceived?.Invoke(session, toledoStandardData);
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"ToledoTcpServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Siemens
{
	/// <summary>
	/// S7-Plus协议专用的数据流
	/// </summary>
	internal class S7PlusStream : NetworkStream
	{
		private SiemensS7Plus siemens;

		private MemoryStream ms = new MemoryStream();

		private Socket socket;

		/// <summary>
		/// 使用指定的<see cref="T:System.Net.Sockets.Socket" />对象，是否所属权来实例化一个对象
		/// </summary>
		/// <param name="socket">套接字对象</param>
		/// <param name="ownsSocket">是否所属权</param>
		/// <param name="siemens">当前的PLC对象</param>
		public S7PlusStream(Socket socket, bool ownsSocket, SiemensS7Plus siemens)
			: base(socket, ownsSocket)
		{
			this.socket = socket;
			this.siemens = siemens;
		}

		/// <inheritdoc />
		public override void Write(byte[] buffer, int offset, int size)
		{
			byte[] array = null;
			if (buffer[0] == 22 && buffer[5] == 1)
			{
				buffer[2] = 1;
			}
			array = ((offset != 0 || buffer.Length != size) ? SiemensS7Plus.BuildWithTPKTAndISO(buffer.SelectMiddle(offset, size)) : SiemensS7Plus.BuildWithTPKTAndISO(buffer));
			if (array != null)
			{
				base.Write(array, 0, array.Length);
			}
		}

		/// <inheritdoc />
		public override int Read(byte[] buffer, int offset, int size)
		{
			if (ms.Position >= ms.Length)
			{
				byte[] array = NetSupport.ReadBytesFromSocket(socket, 7);
				int num = array[2] * 256 + array[3];
				ms = new MemoryStream(num);
				if (num > 0)
				{
					ms.Write(NetSupport.ReadBytesFromSocket(socket, num), 0, num);
				}
			}
			return ms.Read(buffer, offset, size);
		}
	}
	/// <summary>
	/// Contains the methods to convert between <see cref="T:System.DateTime" /> and S7 representation of datetime values.
	/// </summary>
	/// <remarks>
	/// 这部分的代码参考了另一个s7的库，感谢原作者，此处贴出出处，遵循 MIT 协议
	///
	/// https://github.com/S7NetPlus/s7netplus
	/// </remarks>
	public class SiemensDateTime
	{
		/// <summary>
		/// The minimum <see cref="T:System.DateTime" /> value supported by the specification.
		/// </summary>
		public static readonly DateTime SpecMinimumDateTime = new DateTime(1990, 1, 1);

		/// <summary>
		/// The maximum <see cref="T:System.DateTime" /> value supported by the specification.
		/// </summary>
		public static readonly DateTime SpecMaximumDateTime = new DateTime(2089, 12, 31, 23, 59, 59, 999);

		/// <summary>
		/// Parses a <see cref="T:System.DateTime" /> value from bytes.
		/// </summary>
		/// <param name="bytes">Input bytes read from PLC.</param>
		/// <returns>A <see cref="T:System.DateTime" /> object representing the value read from PLC.</returns>
		/// <exception cref="T:System.ArgumentOutOfRangeException">Thrown when the length of
		///   <paramref name="bytes" /> is not 8 or any value in <paramref name="bytes" />
		///   is outside the valid range of values.</exception>
		public static OResult<DateTime> FromByteArray(byte[] bytes)
		{
			try
			{
				return OResult.CreateSuccessResult(FromByteArrayImpl(bytes));
			}
			catch (Exception ex)
			{
				return new OResult<DateTime>("Prase DateTime failed: " + ex.Message);
			}
		}

		/// <summary>
		/// 从西门子的原始字节数据中，提取出DTL格式的时间信息
		/// </summary>
		/// <param name="byteTransform">西门子的字节变换对象</param>
		/// <param name="buffer">原始字节数据</param>
		/// <param name="index">字节偏移索引</param>
		/// <returns>时间信息</returns>
		public static OResult<DateTime> GetDTLTime(IByteTransform byteTransform, byte[] buffer, int index)
		{
			try
			{
				short year = byteTransform.TransInt16(buffer, index);
				int month = buffer[index + 2];
				int day = buffer[index + 3];
				int hour = buffer[index + 5];
				int minute = buffer[index + 6];
				int second = buffer[index + 7];
				int millisecond = byteTransform.TransInt32(buffer, index + 8) / 1000 / 1000;
				return OResult.CreateSuccessResult(new DateTime(year, month, day, hour, minute, second, millisecond));
			}
			catch (Exception ex)
			{
				return new OResult<DateTime>("GetDTLTime failed: " + ex.Message);
			}
		}

		/// <summary>
		/// 将时间数据转换为西门子的DTL格式的时间数据
		/// </summary>
		/// <param name="byteTransform">西门子的字节变换对象</param>
		/// <param name="dateTime">指定的时间信息</param>
		/// <returns>原始字节数据信息</returns>
		public static byte[] GetBytesFromDTLTime(IByteTransform byteTransform, DateTime dateTime)
		{
			byte[] array = new byte[12];
			byteTransform.TransByte((short)dateTime.Year).CopyTo(array, 0);
			array[2] = (byte)dateTime.Month;
			array[3] = (byte)dateTime.Day;
			array[4] = 5;
			array[5] = (byte)dateTime.Hour;
			array[6] = (byte)dateTime.Minute;
			array[7] = (byte)dateTime.Second;
			byteTransform.TransByte(dateTime.Millisecond * 1000 * 1000).CopyTo(array, 8);
			return array;
		}

		/// <summary>
		/// Parses an array of <see cref="T:System.DateTime" /> values from bytes.
		/// </summary>
		/// <param name="bytes">Input bytes read from PLC.</param>
		/// <returns>An array of <see cref="T:System.DateTime" /> objects representing the values read from PLC.</returns>
		/// <exception cref="T:System.ArgumentOutOfRangeException">Thrown when the length of
		///   <paramref name="bytes" /> is not a multiple of 8 or any value in
		///   <paramref name="bytes" /> is outside the valid range of values.</exception>
		public static DateTime[] ToArray(byte[] bytes)
		{
			if (bytes.Length % 8 != 0)
			{
				throw new ArgumentOutOfRangeException("bytes", bytes.Length, $"Parsing an array of DateTime requires a multiple of 8 bytes of input data, input data is '{bytes.Length}' long.");
			}
			int num = bytes.Length / 8;
			DateTime[] array = new DateTime[bytes.Length / 8];
			for (int i = 0; i < num; i++)
			{
				array[i] = FromByteArrayImpl(new ArraySegment<byte>(bytes, i * 8, 8).Array);
			}
			return array;
		}

		private static DateTime FromByteArrayImpl(IList<byte> bytes)
		{
			if (bytes.Count != 8)
			{
				throw new ArgumentOutOfRangeException("bytes", bytes.Count, $"Parsing a DateTime requires exactly 8 bytes of input data, input data is {bytes.Count} bytes long.");
			}
			int year = ByteToYear(bytes[0]);
			int month = AssertRangeInclusive(DecodeBcd(bytes[1]), 1, 12, "month");
			int day = AssertRangeInclusive(DecodeBcd(bytes[2]), 1, 31, "day of month");
			int hour = AssertRangeInclusive(DecodeBcd(bytes[3]), 0, 23, "hour");
			int minute = AssertRangeInclusive(DecodeBcd(bytes[4]), 0, 59, "minute");
			int second = AssertRangeInclusive(DecodeBcd(bytes[5]), 0, 59, "second");
			int num = AssertRangeInclusive(DecodeBcd(bytes[6]), 0, 99, "first two millisecond digits");
			int num2 = AssertRangeInclusive(bytes[7] >> 4, 0, 9, "third millisecond digit");
			AssertRangeInclusive(bytes[7] & 0xF, 1, 7, "day of week");
			return new DateTime(year, month, day, hour, minute, second, num * 10 + num2);
			static int AssertRangeInclusive(int input, byte min, byte max, string field)
			{
				if (input < min)
				{
					throw new ArgumentOutOfRangeException("input", input, $"Value '{input}' is lower than the minimum '{min}' allowed for {field}.");
				}
				if (input > max)
				{
					throw new ArgumentOutOfRangeException("input", input, $"Value '{input}' is higher than the maximum '{max}' allowed for {field}.");
				}
				return input;
			}
			static int ByteToYear(byte bcdYear)
			{
				int num3 = DecodeBcd(bcdYear);
				if (num3 < 90)
				{
					return num3 + 2000;
				}
				if (num3 >= 100)
				{
					throw new ArgumentOutOfRangeException("bcdYear", bcdYear, $"Value '{num3}' is higher than the maximum '99' of S7 date and time representation.");
				}
				return num3 + 1900;
			}
			static int DecodeBcd(byte input)
			{
				return 10 * (input >> 4) + (input & 0xF);
			}
		}

		/// <summary>
		/// Converts a <see cref="T:System.DateTime" /> value to a byte array.
		/// </summary>
		/// <param name="dateTime">The DateTime value to convert.</param>
		/// <returns>A byte array containing the S7 date time representation of <paramref name="dateTime" />.</returns>
		/// <exception cref="T:System.ArgumentOutOfRangeException">Thrown when the value of
		///   <paramref name="dateTime" /> is before <see cref="P:SpecMinimumDateTime" />
		///   or after <see cref="P:SpecMaximumDateTime" />.</exception>
		public static byte[] ToByteArray(DateTime dateTime)
		{
			if (dateTime < SpecMinimumDateTime)
			{
				throw new ArgumentOutOfRangeException("dateTime", dateTime, $"Date time '{dateTime}' is before the minimum '{SpecMinimumDateTime}' supported in S7 date time representation.");
			}
			if (dateTime > SpecMaximumDateTime)
			{
				throw new ArgumentOutOfRangeException("dateTime", dateTime, $"Date time '{dateTime}' is after the maximum '{SpecMaximumDateTime}' supported in S7 date time representation.");
			}
			return new byte[8]
			{
				EncodeBcd(MapYear(dateTime.Year)),
				EncodeBcd(dateTime.Month),
				EncodeBcd(dateTime.Day),
				EncodeBcd(dateTime.Hour),
				EncodeBcd(dateTime.Minute),
				EncodeBcd(dateTime.Second),
				EncodeBcd(dateTime.Millisecond / 10),
				(byte)((dateTime.Millisecond % 10 << 4) | DayOfWeekToInt(dateTime.DayOfWeek))
			};
			static int DayOfWeekToInt(DayOfWeek dayOfWeek)
			{
				return (int)(dayOfWeek + 1);
			}
			static byte EncodeBcd(int value)
			{
				return (byte)((value / 10 << 4) | (value % 10));
			}
			static byte MapYear(int year)
			{
				return (byte)((year < 2000) ? (year - 1900) : (year - 2000));
			}
		}

		/// <summary>
		/// Converts an array of <see cref="T:System.DateTime" /> values to a byte array.
		/// </summary>
		/// <param name="dateTimes">The DateTime values to convert.</param>
		/// <returns>A byte array containing the S7 date time representations of <paramref name="dateTimes" />.</returns>
		/// <exception cref="T:System.ArgumentOutOfRangeException">Thrown when any value of
		///   <paramref name="dateTimes" /> is before <see cref="P:SpecMinimumDateTime" />
		///   or after <see cref="P:SpecMaximumDateTime" />.</exception>
		public static byte[] ToByteArray(DateTime[] dateTimes)
		{
			List<byte> list = new List<byte>(dateTimes.Length * 8);
			foreach (DateTime dateTime in dateTimes)
			{
				list.AddRange(ToByteArray(dateTime));
			}
			return list.ToArray();
		}
	}
	/// <summary>
	/// 使用了Fetch/Write协议来和西门子进行通讯，该种方法需要在PLC侧进行一些配置<br />
	/// Using the Fetch/write protocol to communicate with Siemens, this method requires some configuration on the PLC side
	/// </summary>
	/// <remarks>
	/// 配置的参考文章地址：https://www.cnblogs.com/dathlin/p/8685855.html
	/// <br />
	/// 与S7协议相比较而言，本协议不支持对单个的点位的读写操作。如果读取M100.0，需要读取M100的值，然后进行提取位数据。
	///
	/// 如果需要写入位地址的数据，可以读取plc的byte值，然后进行与或非，然后写入到plc之中。
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensFetchWriteNet.cs" region="Usage" title="简单的短连接使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensFetchWriteNet.cs" region="Usage2" title="简单的长连接使用" />
	/// </example>
	public class SiemensFetchWriteNet : DeviceTcpNet
	{
		/// <summary>
		/// 实例化一个西门子的Fetch/Write协议的通讯对象<br />
		/// Instantiate a communication object for a Siemens Fetch/write protocol
		/// </summary>
		public SiemensFetchWriteNet()
		{
			base.WordLength = 2;
			base.ByteTransform = new ReverseBytesTransform();
		}

		/// <summary>
		/// 实例化一个西门子的Fetch/Write协议的通讯对象<br />
		/// Instantiate a communication object for a Siemens Fetch/write protocol
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址 -&gt; Specify IP Address</param>
		/// <param name="port">PLC的端口 -&gt; Specify IP Port</param>
		public SiemensFetchWriteNet(string ipAddress, int port)
		{
			base.WordLength = 2;
			IpAddress = ipAddress;
			Port = port;
			base.ByteTransform = new ReverseBytesTransform();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FetchWriteMessage();
		}

		/// <summary>
		/// 从PLC读取数据，地址格式为I100，Q100，DB20.100，M100，T100，C100，以字节为单位<br />
		/// Read data from PLC, address format I100,Q100,DB20.100,M100,T100,C100, in bytes
		/// </summary>
		/// <param name="address">起始地址，格式为I100，M100，Q100，DB20.100，T100，C100 -&gt;
		/// Starting address, formatted as I100,M100,Q100,DB20.100,T100,C100
		/// </param>
		/// <param name="length">读取的数量，以字节为单位 -&gt; The number of reads, in bytes</param>
		/// <returns>带有成功标志的字节信息 -&gt; Byte information with a success flag</returns>
		/// <example>
		/// 假设起始地址为M100，M100存储了温度，100.6℃值为1006，M102存储了压力，1.23Mpa值为123，M104，M105，M106，M107存储了产量计数，读取如下：
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensFetchWriteNet.cs" region="ReadExample2" title="Read示例" />
		/// 以下是读取不同类型数据的示例
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensFetchWriteNet.cs" region="ReadExample1" title="Read示例" />
		/// </example>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponseContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult(SoftBasic.ArrayRemoveBegin(oResult2.Content, 16));
		}

		/// <summary>
		/// 将数据写入到PLC数据，地址格式为I100，Q100，DB20.100，M100，以字节为单位<br />
		/// Writes data to the PLC data, in the address format i100,q100,db20.100,m100, in bytes
		/// </summary>
		/// <param name="address">起始地址，格式为M100,I100,Q100,DB1.100 -&gt; Starting address, formatted as M100,I100,Q100,DB1.100</param>
		/// <param name="value">要写入的实际数据 -&gt; The actual data to write</param>
		/// <returns>是否写入成功的结果对象 -&gt; Whether to write a successful result object</returns>
		/// <example>
		/// 假设起始地址为M100，M100,M101存储了温度，100.6℃值为1006，M102,M103存储了压力，1.23Mpa值为123，M104-M107存储了产量计数，写入如下：
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensFetchWriteNet.cs" region="WriteExample2" title="Write示例" />
		/// 以下是写入不同类型数据的示例
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensFetchWriteNet.cs" region="WriteExample1" title="Write示例" />
		/// </example>
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponseContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensFetchWriteNet.Read(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponseContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult(SoftBasic.ArrayRemoveBegin(oResult2.Content, 16));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensFetchWriteNet.Write(System.String,System.Byte[])" />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponseContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 读取指定地址的byte数据<br />
		/// Reads the byte data for the specified address
