		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SiemensFetchWriteNet[{IpAddress}:{Port}]";
		}

		/// <summary>
		/// 计算特殊的地址信息<br />
		/// Calculate special address information
		/// </summary>
		/// <param name="address">字符串信息</param>
		/// <returns>实际值</returns>
		private static int CalculateAddressStarted(string address)
		{
			if (address.IndexOf('.') < 0)
			{
				return Convert.ToInt32(address);
			}
			return Convert.ToInt32(address.Split('.')[0]);
		}

		private static OResult CheckResponseContent(byte[] content)
		{
			if (content == null || content.Length < 9)
			{
				return new OResult(StringResources.Language.ReceiveDataLengthTooShort + "9, Content: " + content.ToHexString(' '));
			}
			if (content[8] != 0)
			{
				return new OResult(content[8], StringResources.Language.SiemensWriteError + content[8]);
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 解析数据地址，解析出地址类型，起始地址，DB块的地址<br />
		/// Parse data address, parse out address type, start address, db block address
		/// </summary>
		/// <param name="address">起始地址，格式为M100,I100,Q100,DB1.100 -&gt; Starting address, formatted as M100,I100,Q100,DB1.100</param>
		/// <returns>解析出地址类型，起始地址，DB块的地址 -&gt; Resolves address type, start address, db block address</returns>
		private static OResult<byte, int, ushort> AnalysisAddress(string address)
		{
			OResult<byte, int, ushort> oResult = new OResult<byte, int, ushort>();
			try
			{
				oResult.Content3 = 0;
				if (address[0] == 'I')
				{
					oResult.Content1 = 3;
					oResult.Content2 = CalculateAddressStarted(address.Substring(1));
				}
				else if (address[0] == 'Q')
				{
					oResult.Content1 = 4;
					oResult.Content2 = CalculateAddressStarted(address.Substring(1));
				}
				else if (address[0] == 'M')
				{
					oResult.Content1 = 2;
					oResult.Content2 = CalculateAddressStarted(address.Substring(1));
				}
				else if (address[0] == 'D' || address.Substring(0, 2) == "DB")
				{
					oResult.Content1 = 1;
					string[] array = address.Split('.');
					if (address[1] == 'B')
					{
						oResult.Content3 = Convert.ToUInt16(array[0].Substring(2));
					}
					else
					{
						oResult.Content3 = Convert.ToUInt16(array[0].Substring(1));
					}
					if (oResult.Content3 > 255)
					{
						oResult.Message = StringResources.Language.SiemensDBAddressNotAllowedLargerThan255;
						return oResult;
					}
					oResult.Content2 = CalculateAddressStarted(address.Substring(address.IndexOf('.') + 1));
				}
				else if (address[0] == 'T')
				{
					oResult.Content1 = 7;
					oResult.Content2 = CalculateAddressStarted(address.Substring(1));
				}
				else
				{
					if (address[0] != 'C')
					{
						oResult.Message = StringResources.Language.NotSupportedDataType;
						oResult.Content1 = 0;
						oResult.Content2 = 0;
						oResult.Content3 = 0;
						return oResult;
					}
					oResult.Content1 = 6;
					oResult.Content2 = CalculateAddressStarted(address.Substring(1));
				}
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
			oResult.IsSuccess = true;
			return oResult;
		}

		/// <summary>
		/// 生成一个读取字数据指令头的通用方法<br />
		/// A general method for generating a command header to read a Word data
		/// </summary>
		/// <param name="address">起始地址，格式为M100,I100,Q100,DB1.100 -&gt; Starting address, formatted as M100,I100,Q100,DB1.100</param>
		/// <param name="count">读取数据个数 -&gt; Number of Read data</param>
		/// <returns>带结果对象的报文数据 -&gt; Message data with a result object</returns>
		public static OResult<byte[]> BuildReadCommand(string address, ushort count)
		{
			OResult<byte, int, ushort> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] obj = new byte[16]
			{
				83, 53, 16, 1, 3, 5, 3, 8, 0, 0,
				0, 0, 0, 0, 0, 0
			};
			obj[8] = oResult.Content1;
			obj[9] = (byte)oResult.Content3;
			obj[10] = (byte)(oResult.Content2 / 256);
			obj[11] = (byte)(oResult.Content2 % 256);
			byte[] array = obj;
			if (oResult.Content1 == 1 || oResult.Content1 == 6 || oResult.Content1 == 7)
			{
				if (count % 2 != 0)
				{
					return new OResult<byte[]>(StringResources.Language.SiemensReadLengthMustBeEvenNumber);
				}
				array[12] = BitConverter.GetBytes(count / 2)[1];
				array[13] = BitConverter.GetBytes(count / 2)[0];
			}
			else
			{
				array[12] = BitConverter.GetBytes(count)[1];
				array[13] = BitConverter.GetBytes(count)[0];
			}
			array[14] = byte.MaxValue;
			array[15] = 2;
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 生成一个写入字节数据的指令<br />
		/// Generate an instruction to write byte data
		/// </summary>
		/// <param name="address">起始地址，格式为M100,I100,Q100,DB1.100 -&gt; Starting address, formatted as M100,I100,Q100,DB1.100</param>
		/// <param name="data">实际的写入的内容 -&gt; The actual content of the write</param>
		/// <returns>带结果对象的报文数据 -&gt; Message data with a result object</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			OResult<byte, int, ushort> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[16 + data.Length];
			array[0] = 83;
			array[1] = 53;
			array[2] = 16;
			array[3] = 1;
			array[4] = 3;
			array[5] = 3;
			array[6] = 3;
			array[7] = 8;
			array[8] = oResult.Content1;
			array[9] = (byte)oResult.Content3;
			array[10] = (byte)(oResult.Content2 / 256);
			array[11] = (byte)(oResult.Content2 % 256);
			if (oResult.Content1 == 1 || oResult.Content1 == 6 || oResult.Content1 == 7)
			{
				if (data.Length % 2 != 0)
				{
					return new OResult<byte[]>(StringResources.Language.SiemensReadLengthMustBeEvenNumber);
				}
				array[12] = BitConverter.GetBytes(data.Length / 2)[1];
				array[13] = BitConverter.GetBytes(data.Length / 2)[0];
			}
			else
			{
				array[12] = BitConverter.GetBytes(data.Length)[1];
				array[13] = BitConverter.GetBytes(data.Length)[0];
			}
			array[14] = byte.MaxValue;
			array[15] = 2;
			Array.Copy(data, 0, array, 16, data.Length);
			return OResult.CreateSuccessResult(array);
		}
	}
	/// <summary>
	/// 西门子的Fetch/Write协议的虚拟PLC，可以用来调试通讯，也可以实现一个虚拟的PLC功能，从而开发一套带虚拟环境的上位机系统，可以用来演示，测试。<br />
	/// The virtual PLC of Siemens Fetch/Write protocol can be used for debugging communication, and can also realize a virtual PLC function, so as to develop a set of upper computer system with virtual environment, which can be used for demonstration and testing.
	/// </summary>
	/// <remarks>
	/// 本虚拟服务器的使用需要企业商业授权，否则只能运行24小时。本协议实现的虚拟PLC服务器，主要支持I,Q,M,DB块的数据读写操作，例如 M100, DB1.100，服务器端也可以对位进行读写操作，例如M100.1，DB1.100.2；
	/// 但是不支持连接的远程客户端对位进行操作。
	/// </remarks>
	/// <example>
	/// 地址支持的列表如下：
	/// <list type="table">
	///   <listheader>
	///     <term>地址名称</term>
	///     <term>地址代号</term>
	///     <term>示例</term>
	///     <term>地址进制</term>
	///     <term>字操作</term>
	///     <term>位操作</term>
	///     <term>备注</term>
	///   </listheader>
	///   <item>
	///     <term>中间寄存器</term>
	///     <term>M</term>
	///     <term>M100,M200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>输入寄存器</term>
	///     <term>I</term>
	///     <term>I100,I200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>输出寄存器</term>
	///     <term>Q</term>
	///     <term>Q100,Q200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>DB块寄存器</term>
	///     <term>DB</term>
	///     <term>DB1.100,DB1.200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>V寄存器</term>
	///     <term>V</term>
	///     <term>V100,V200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term>V寄存器本质就是DB块1</term>
	///   </item>
	/// </list>
	/// 本虚拟的PLC共有4个DB块，DB1.X, DB2.X, DB3.X, 和其他DB块。对于远程客户端的读写长度，暂时没有限制。
	/// </example>
	public class SiemensFetchWriteServer : DeviceServer
	{
		private SoftBuffer inputBuffer;

		private SoftBuffer outputBuffer;

		private SoftBuffer memeryBuffer;

		private SoftBuffer counterBuffer;

		private SoftBuffer timerBuffer;

		private SoftBuffer db1BlockBuffer;

		private SoftBuffer db2BlockBuffer;

		private SoftBuffer db3BlockBuffer;

		private SoftBuffer dbOtherBlockBuffer;

		private const int DataPoolLength = 65536;

		/// <summary>
		/// 实例化一个S7协议的服务器，支持I，Q，M，DB1.X, DB2.X, DB3.X 数据区块的读写操作<br />
		/// Instantiate a server with S7 protocol, support I, Q, M, DB1.X data block read and write operations
		/// </summary>
		public SiemensFetchWriteServer()
		{
			inputBuffer = new SoftBuffer(65536);
			outputBuffer = new SoftBuffer(65536);
			memeryBuffer = new SoftBuffer(65536);
			db1BlockBuffer = new SoftBuffer(65536);
			db2BlockBuffer = new SoftBuffer(65536);
			db3BlockBuffer = new SoftBuffer(65536);
			dbOtherBlockBuffer = new SoftBuffer(65536);
			counterBuffer = new SoftBuffer(65536);
			timerBuffer = new SoftBuffer(65536);
			base.WordLength = 2;
			base.ByteTransform = new ReverseBytesTransform();
		}

		private OResult<SoftBuffer> GetDataAreaFromS7Address(S7AddressData s7Address)
		{
			switch (s7Address.DataCode)
			{
			case 129:
				return OResult.CreateSuccessResult(inputBuffer);
			case 130:
				return OResult.CreateSuccessResult(outputBuffer);
			case 131:
				return OResult.CreateSuccessResult(memeryBuffer);
			case 132:
				if (s7Address.DbBlock == 1)
				{
					return OResult.CreateSuccessResult(db1BlockBuffer);
				}
				if (s7Address.DbBlock == 2)
				{
					return OResult.CreateSuccessResult(db2BlockBuffer);
				}
				if (s7Address.DbBlock == 3)
				{
					return OResult.CreateSuccessResult(db3BlockBuffer);
				}
				return OResult.CreateSuccessResult(dbOtherBlockBuffer);
			default:
				return new OResult<SoftBuffer>(StringResources.Language.NotSupportedDataType);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(oResult.Content);
			if (!dataAreaFromS7Address.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataAreaFromS7Address);
			}
			return OResult.CreateSuccessResult(dataAreaFromS7Address.Content.GetBytes(oResult.Content.AddressStart / 8, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(oResult.Content);
			if (!dataAreaFromS7Address.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataAreaFromS7Address);
			}
			dataAreaFromS7Address.Content.SetBytes(value, oResult.Content.AddressStart / 8);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.ReadByte(System.String)" />
		public OResult<byte> ReadByte(string address)
		{
			return ByteTransformHelper.GetResultFromArray(Read(address, 1));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Byte)" />
		public OResult Write(string address, byte value)
		{
			return Write(address, new byte[1] { value });
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.ReadBool(System.String)" />
		public override OResult<bool> ReadBool(string address)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(oResult.Content);
			if (!dataAreaFromS7Address.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(dataAreaFromS7Address);
			}
			return OResult.CreateSuccessResult(dataAreaFromS7Address.Content.GetBool(oResult.Content.AddressStart));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Boolean)" />
		public override OResult Write(string address, bool value)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(oResult.Content);
			if (!dataAreaFromS7Address.IsSuccess)
			{
				return dataAreaFromS7Address;
			}
			dataAreaFromS7Address.Content.SetBool(value, oResult.Content.AddressStart);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FetchWriteMessage();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			byte[] value = null;
			if (receive[5] == 3)
			{
				value = WriteByMessage(receive);
			}
			else if (receive[5] == 5)
			{
				value = ReadByMessage(receive);
			}
			return OResult.CreateSuccessResult(value);
		}

		private SoftBuffer GetBufferFromCommand(byte[] command)
		{
			if (command[8] == 2)
			{
				return memeryBuffer;
			}
			if (command[8] == 3)
			{
				return inputBuffer;
			}
			if (command[8] == 4)
			{
				return outputBuffer;
			}
			if (command[8] == 1)
			{
				if (command[9] == 1)
				{
					return db1BlockBuffer;
				}
				if (command[9] == 2)
				{
					return db2BlockBuffer;
				}
				if (command[9] == 3)
				{
					return db3BlockBuffer;
				}
				return dbOtherBlockBuffer;
			}
			if (command[8] == 6)
			{
				return counterBuffer;
			}
			if (command[8] == 7)
			{
				return timerBuffer;
			}
			return null;
		}

		private byte[] ReadByMessage(byte[] command)
		{
			SoftBuffer bufferFromCommand = GetBufferFromCommand(command);
			int index = command[10] * 256 + command[11];
			int num = command[12] * 256 + command[13];
			if (bufferFromCommand == null)
			{
				return PackCommandResponse(6, 1, null);
			}
			if (command[8] == 1 || command[8] == 6 || command[8] == 7)
			{
				return PackCommandResponse(6, 0, bufferFromCommand.GetBytes(index, num * 2));
			}
			return PackCommandResponse(6, 0, bufferFromCommand.GetBytes(index, num));
		}

		private byte[] WriteByMessage(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackCommandResponse(4, 1, null);
			}
			SoftBuffer bufferFromCommand = GetBufferFromCommand(command);
			int destIndex = command[10] * 256 + command[11];
			int num = command[12] * 256 + command[13];
			if (bufferFromCommand == null)
			{
				return PackCommandResponse(4, 1, null);
			}
			if (command[8] == 1 || command[8] == 6 || command[8] == 7)
			{
				if (num != (command.Length - 16) / 2)
				{
					return PackCommandResponse(4, 1, null);
				}
				bufferFromCommand.SetBytes(command.RemoveBegin(16), destIndex);
				return PackCommandResponse(4, 0, null);
			}
			if (num != command.Length - 16)
			{
				return PackCommandResponse(4, 1, null);
			}
			bufferFromCommand.SetBytes(command.RemoveBegin(16), destIndex);
			return PackCommandResponse(4, 0, null);
		}

		private byte[] PackCommandResponse(byte opCode, byte err, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[16 + data.Length];
			array[0] = 83;
			array[1] = 53;
			array[2] = 16;
			array[3] = 1;
			array[4] = 3;
			array[5] = opCode;
			array[6] = 15;
			array[7] = 3;
			array[8] = err;
			array[9] = byte.MaxValue;
			array[10] = 7;
			if (data.Length != 0)
			{
				data.CopyTo(array, 16);
			}
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 589824)
			{
				throw new Exception("File is not correct");
			}
			inputBuffer.SetBytes(content, 0, 0, 65536);
			outputBuffer.SetBytes(content, 65536, 0, 65536);
			memeryBuffer.SetBytes(content, 131072, 0, 65536);
			db1BlockBuffer.SetBytes(content, 196608, 0, 65536);
			db2BlockBuffer.SetBytes(content, 262144, 0, 65536);
			db3BlockBuffer.SetBytes(content, 327680, 0, 65536);
			dbOtherBlockBuffer.SetBytes(content, 393216, 0, 65536);
			counterBuffer.SetBytes(content, 458752, 0, 65536);
			timerBuffer.SetBytes(content, 524288, 0, 65536);
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[589824];
			Array.Copy(inputBuffer.GetBytes(), 0, array, 0, 65536);
			Array.Copy(outputBuffer.GetBytes(), 0, array, 65536, 65536);
			Array.Copy(memeryBuffer.GetBytes(), 0, array, 131072, 65536);
			Array.Copy(db1BlockBuffer.GetBytes(), 0, array, 196608, 65536);
			Array.Copy(db2BlockBuffer.GetBytes(), 0, array, 262144, 65536);
			Array.Copy(db3BlockBuffer.GetBytes(), 0, array, 327680, 65536);
			Array.Copy(dbOtherBlockBuffer.GetBytes(), 0, array, 393216, 65536);
			Array.Copy(counterBuffer.GetBytes(), 0, array, 458752, 65536);
			Array.Copy(timerBuffer.GetBytes(), 0, array, 524288, 65536);
			return array;
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				inputBuffer?.Dispose();
				outputBuffer?.Dispose();
				memeryBuffer?.Dispose();
				db1BlockBuffer?.Dispose();
				db2BlockBuffer?.Dispose();
				db3BlockBuffer?.Dispose();
				dbOtherBlockBuffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SiemensFetchWriteServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 西门子的MPI协议信息，注意：未测试通过，无法使用<br />
	/// Siemens MPI protocol information, note: it has not passed the test and cannot be used
	/// </summary>
	public class SiemensMPI : DeviceSerialPort
	{
		private byte station = 2;

		private byte[] readConfirm = new byte[15]
		{
			104, 8, 8, 104, 130, 128, 92, 22, 2, 176,
			7, 0, 45, 22, 229
		};

		private byte[] writeConfirm = new byte[15]
		{
			104, 8, 8, 104, 130, 128, 124, 22, 2, 176,
			7, 0, 77, 22, 229
		};

		/// <summary>
		/// 西门子PLC的站号信息<br />
		/// Siemens PLC station number information
		/// </summary>
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
				readConfirm[4] = (byte)(value + 128);
				writeConfirm[4] = (byte)(value + 128);
				int num = 0;
				int num2 = 0;
				for (int i = 4; i < 12; i++)
				{
					num += readConfirm[i];
					num2 += writeConfirm[i];
				}
				readConfirm[12] = (byte)num;
				writeConfirm[12] = (byte)num2;
			}
		}

		/// <summary>
		/// 实例化一个西门子的MPI协议对象<br />
		/// Instantiate a Siemens MPI protocol object
		/// </summary>
		public SiemensMPI()
		{
			base.ByteTransform = new ReverseBytesTransform();
			base.WordLength = 2;
		}

		/// <summary>
		/// 与PLC进行握手<br />
		/// Handshake with PLC
		/// </summary>
		/// <returns>是否握手成功</returns>
		public OResult Handle()
		{
			while (true)
			{
				OResult<byte[]> oResult = CommunicationPipe.ReceiveMessage(null, null);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				if (oResult.Content[0] == 220 && oResult.Content[1] == 2 && oResult.Content[2] == 2)
				{
					OResult oResult2 = CommunicationPipe.Send(new byte[3] { 220, 0, 0 });
					if (!oResult2.IsSuccess)
					{
						return OResult.CreateFailedResult<byte[]>(oResult2);
					}
				}
				else if (oResult.Content[0] == 220 && oResult.Content[1] == 0 && oResult.Content[2] == 2)
				{
					break;
				}
			}
			OResult oResult3 = CommunicationPipe.Send(new byte[3] { 220, 2, 0 });
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 从西门子的PLC中读取数据信息，地址为"M100","AI100","I0","Q0","V100","S100"等，详细请参照API文档<br />
		/// Read data information from Siemens PLC, the address is "M100", "AI100", "I0", "Q0", "V100", "S100", etc., please refer to the API documentation
		/// </summary>
		/// <param name="address">西门子的地址数据信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>带返回结果的结果对象</returns>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(station, address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (base.IsClearCacheBeforeRead)
			{
				((PipeSerialPort)CommunicationPipe).ClearSerialCache();
			}
			OResult oResult2 = CommunicationPipe.Send(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			OResult<byte[]> oResult3 = CommunicationPipe.ReceiveMessage(null, null);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			if (oResult3.Content[14] != 229)
			{
				return new OResult<byte[]>("PLC Receive Check Failed:" + SoftBasic.ByteToHexString(oResult3.Content));
			}
			oResult3 = CommunicationPipe.ReceiveMessage(null, null);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			if (oResult3.Content[19] != 0)
			{
				return new OResult<byte[]>("PLC Receive Check Failed:" + oResult3.Content[19]);
			}
			oResult2 = CommunicationPipe.Send(readConfirm);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			byte[] array = new byte[length];
			if (oResult3.Content[25] == byte.MaxValue && oResult3.Content[26] == 4)
			{
				Array.Copy(oResult3.Content, 29, array, 0, length);
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 从西门子的PLC中读取bool数据信息，地址为"M100.0","AI100.1","I0.3","Q0.6","V100.4","S100"等，详细请参照API文档<br />
		/// Read the bool data information from Siemens PLC. The addresses are "M100.0", "AI100.1", "I0.3", "Q0.6", "V100.4", "S100", etc. For details, please Refer to API documentation
		/// </summary>
		/// <param name="address">西门子的地址数据信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>带返回结果的结果对象</returns>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(station, address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult oResult2 = CommunicationPipe.Send(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			OResult<byte[]> oResult3 = CommunicationPipe.ReceiveMessage(null, null);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult3);
			}
			if (oResult3.Content[14] != 229)
			{
				return new OResult<bool[]>("PLC Receive Check Failed:" + SoftBasic.ByteToHexString(oResult3.Content));
			}
			oResult3 = CommunicationPipe.ReceiveMessage(null, null);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult3);
			}
			if (oResult3.Content[19] != 0)
			{
				return new OResult<bool[]>("PLC Receive Check Failed:" + oResult3.Content[19]);
			}
			oResult2 = CommunicationPipe.Send(readConfirm);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			byte[] array = new byte[oResult3.Content.Length - 31];
			if (oResult3.Content[21] == byte.MaxValue && oResult3.Content[22] == 3)
			{
				Array.Copy(oResult3.Content, 28, array, 0, array.Length);
			}
			return OResult.CreateSuccessResult(SoftBasic.ByteToBoolArray(array, length));
		}

		/// <summary>
		/// 将字节数据写入到西门子PLC中，地址为"M100.0","AI100.1","I0.3","Q0.6","V100.4","S100"等，详细请参照API文档<br />
		/// Write byte data to Siemens PLC, the address is "M100.0", "AI100.1", "I0.3", "Q0.6", "V100.4", "S100", etc. Refer to API documentation
		/// </summary>
		/// <param name="address">西门子的地址数据信息</param>
		/// <param name="value">数据长度</param>
		/// <returns>带返回结果的结果对象</returns>
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (base.IsClearCacheBeforeRead)
			{
				((PipeSerialPort)CommunicationPipe).ClearSerialCache();
			}
			OResult oResult2 = CommunicationPipe.Send(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			OResult<byte[]> oResult3 = CommunicationPipe.ReceiveMessage(null, null);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			if (oResult3.Content[14] != 229)
			{
				return new OResult<byte[]>("PLC Receive Check Failed:" + SoftBasic.ByteToHexString(oResult3.Content));
			}
			oResult3 = CommunicationPipe.ReceiveMessage(null, null);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			if (oResult3.Content[25] != byte.MaxValue)
			{
				return new OResult<byte[]>("PLC Receive Check Failed:" + oResult3.Content[25]);
			}
			oResult2 = CommunicationPipe.Send(writeConfirm);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult();
		}

