	/// <summary>
	/// 西门子的PPI协议，适用于s7-200plc，注意，由于本类库的每次通讯分成2次操作，内部增加了一个同步锁，所以单次通信时间比较久，另外，地址支持携带站号，例如：s=2;M100<br />
	/// Siemens' PPI protocol is suitable for s7-200plc. Note that since each communication of this class library is divided into two operations, 
	/// and a synchronization lock is added inside, the single communication time is relatively long. In addition, 
	/// the address supports carrying the station number, for example : S=2;M100
	/// </summary>
	/// <remarks>
	/// 适用于西门子200的通信，非常感谢 合肥-加劲 的测试，让本类库圆满完成。注意：M地址范围有限 0-31地址<br />
	/// 在本类的<see cref="T:Snet.Driver.Profinet.Siemens.SiemensPPIOverTcp" />实现类里，如果使用了Async的异步方法，没有增加同步锁，多线程调用可能会引发数据错乱的情况。<br />
	/// In the <see cref="T:Snet.Driver.Profinet.Siemens.SiemensPPIOverTcp" /> implementation class of this class, if the asynchronous method of Async is used, 
	/// the synchronization lock is not added, and multi-threaded calls may cause data disorder.
	/// </remarks>
	public class SiemensPPI : DeviceSerialPort, ISiemensPPI, IReadWriteNet
	{
		private byte station = 2;

		private object communicationLock;

		/// <summary>
		/// 西门子PLC的站号信息<br />
		/// Siemens PLC station number information
		/// </summary>
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 实例化一个西门子的PPI协议对象<br />
		/// Instantiate a Siemens PPI protocol object
		/// </summary>
		public SiemensPPI()
		{
			base.ByteTransform = new ReverseBytesTransform();
			base.WordLength = 2;
			communicationLock = new object();
			base.ReceiveEmptyDataCount = 5;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SiemensPPIMessage();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.Read(Snet.Driver.Core.IReadWriteDevice,System.String,System.UInt16,System.Byte,System.Object)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			return SiemensPPIHelper.Read(this, address, length, Station, communicationLock);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.ReadBool(Snet.Driver.Core.IReadWriteDevice,System.String,System.Byte,System.Object)" />
		public override OResult<bool> ReadBool(string address)
		{
			return SiemensPPIHelper.ReadBool(this, address, Station, communicationLock);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.ReadBool(Snet.Driver.Core.IReadWriteDevice,System.String,System.Byte,System.Object)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			return SiemensPPIHelper.ReadBool(this, address, length, Station, communicationLock);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.String,System.Byte[],System.Byte,System.Object)" />
		public override OResult Write(string address, byte[] value)
		{
			return SiemensPPIHelper.Write(this, address, value, Station, communicationLock);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.String,System.Boolean[],System.Byte,System.Object)" />
		public override OResult Write(string address, bool[] value)
		{
			return SiemensPPIHelper.Write(this, address, value, Station, communicationLock);
		}

		/// <summary>
		/// 从西门子的PLC中读取byte数据信息，地址为"M100","AI100","I0","Q0","V100","S100"等，详细请参照API文档<br />
		/// Read byte data information from Siemens PLC. The addresses are "M100", "AI100", "I0", "Q0", "V100", "S100", etc. Please refer to the API documentation for details.
		/// </summary>
		/// <param name="address">西门子的地址数据信息</param>
		/// <returns>带返回结果的结果对象</returns>
		public OResult<byte> ReadByte(string address)
		{
			return ByteTransformHelper.GetResultFromArray(Read(address, 1));
		}

		/// <summary>
		/// 向西门子的PLC中写入byte数据，地址为"M100","AI100","I0","Q0","V100","S100"等，详细请参照API文档<br />
		/// Write byte data from Siemens PLC with addresses "M100", "AI100", "I0", "Q0", "V100", "S100", etc. For details, please refer to the API documentation
		/// </summary>
		/// <param name="address">西门子的地址数据信息</param>
		/// <param name="value">数据长度</param>
		/// <returns>带返回结果的结果对象</returns>
		public OResult Write(string address, byte value)
		{
			return Write(address, new byte[1] { value });
		}

		/// <inheritdoc />
		public override async Task<OResult<bool>> ReadBoolAsync(string address)
		{
			return await Task.Run(() => ReadBool(address));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.Start(Snet.Driver.Core.IReadWriteDevice,System.String,System.Byte,System.Object)" />
		public OResult Start(string parameter = "")
		{
			return SiemensPPIHelper.Start(this, parameter, Station, communicationLock);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.Stop(Snet.Driver.Core.IReadWriteDevice,System.String,System.Byte,System.Object)" />
		public OResult Stop(string parameter = "")
		{
			return SiemensPPIHelper.Stop(this, parameter, Station, communicationLock);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.ReadPlcType(Snet.Driver.Core.IReadWriteDevice,System.String,System.Byte,System.Object)" />
		public OResult<string> ReadPlcType(string parameter = "")
		{
			return SiemensPPIHelper.ReadPlcType(this, parameter, Station, communicationLock);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SiemensPPI[{base.PortName}:{base.BaudRate}]";
		}
	}
