		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensPPI.Stop(System.String)" />
		public async Task<OResult> StopAsync(string parameter = "")
		{
			return await Task.Run(() => Stop(parameter));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.ReadPlcType(Snet.Driver.Core.IReadWriteDevice,System.String,System.Byte,System.Object)" />
		public async Task<OResult<string>> ReadPlcTypeAsync(string parameter = "")
		{
			return await Task.Run(() => SiemensPPIHelper.ReadPlcType(this, parameter, Station, communicationLock));
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SiemensPPIOverTcp[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// PPIServer的虚拟服务器对象，支持的地址类型和S7虚拟服务器一致
	/// </summary>
	public class SiemensPPIServer : SiemensS7Server
	{
		/// <inheritdoc cref="P:Snet.Driver.Profinet.Siemens.SiemensPPIOverTcp.Station" />
		public byte Station { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public SiemensPPIServer()
		{
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SiemensPPIServerMessage();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			CommunicationPipe communication = session.Communication;
			if (receive[4] != Station)
			{
				return new OResult<byte[]>($"Station not match, expect: {Station}, but actual: {receive[4]}");
			}
			byte[] array = new byte[1] { 229 };
			LogSendMessage(array, session);
			communication.Send(array);
			OResult<byte[]> oResult = communication.ReceiveMessage(new SpecifiedCharacterMessage(22), null, useActivePush: false, null, delegate(byte[] m)
			{
				LogRevcMessage(m, session);
			});
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return base.ReadFromCoreServer(session, receive);
		}

		/// <inheritdoc />
		protected override bool IsNeedShakeHands()
		{
			return false;
		}

		/// <inheritdoc />
		protected override byte[] PackReadBack(byte[] command, List<byte> content)
		{
			byte[] array = new byte[21 + content.Count + 2];
			SoftBasic.HexStringToBytes("68 1D 1D 68 00 02 08 32 03 00 00 00 00 00 02 00 0C 00 00 04 01").CopyTo(array, 0);
			array[1] = (byte)(array.Length - 6);
			array[2] = (byte)(array.Length - 6);
			array[15] = (byte)(content.Count / 256);
			array[16] = (byte)(content.Count % 256);
			array[20] = command[18];
			content.CopyTo(array, 21);
			array[^2] = (byte)SoftLRC.CalculateAcc(array, 4, 2);
			array[^1] = 22;
			return array;
		}

		/// <inheritdoc />
		protected override byte[] PackWriteBack(byte[] packCommand, byte[] status)
		{
			byte[] array = new byte[23 + status.Length];
			SoftBasic.HexStringToBytes("68 12 12 68 00 02 08 32 03 00 00 00 01 00 02 00 01 00 00 05 01 04 00 16").CopyTo(array, 0);
			array[20] = (byte)status.Length;
			status.CopyTo(array, 21);
			array[^2] = (byte)SoftLRC.CalculateAcc(array, 4, 2);
			array[^1] = 22;
			return array;
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			if (receivedLength == 6 && buffer[0] == 16 && buffer[1] == 2 && buffer[5] == 22)
			{
				return true;
			}
			if (receivedLength > 6 && buffer[0] == 104 && buffer[1] + 6 == receivedLength && buffer[receivedLength - 1] == 22)
			{
				return true;
			}
			return base.CheckSerialReceiveDataComplete(buffer, receivedLength);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SiemensPPIServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 一个西门子的客户端类，使用S7协议来进行数据交互，对于s300,s400需要关注<see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.Slot" />和<see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.Rack" />的设置值，
	/// 对于s200，需要关注<see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.LocalTSAP" />和<see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.DestTSAP" />的设置值，详细参考demo的设置。 <br />
	/// A Siemens client class uses the S7 protocol for data exchange. For s300 and s400, 
	/// you need to pay attention to the setting values of <see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.Slot" /> and <see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.Rack" />. For s200, 
	/// you need to pay attention to <see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.Slot" /> and <see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.Rack" />. See cref="LocalTSAP"/&gt; and <see cref="P:Snet.Driver.Profinet.Siemens.SiemensS7Net.DestTSAP" /> settings, 
	/// please refer to the demo settings for details.
	/// </summary>
	/// <remarks>
	/// 暂时不支持bool[]的批量写入操作，请使用 Write(string, byte[]) 替换。<br />
	/// <note type="important">对于200smartPLC的V区，就是DB1.X，例如，V100=DB1.100，当然了你也可以输入V100</note><br />
	/// 如果读取PLC的字符串string数据，可以使用 <see cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.ReadString(System.String)" />
