	/// <note type="important">对于200smartPLC的V区，就是DB1.X，例如，V100=DB1.100</note>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="Usage" title="简单的短连接使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="Usage2" title="简单的长连接使用" />
	///
	/// 假设起始地址为M100，M100存储了温度，100.6℃值为1006，M102存储了压力，1.23Mpa值为123，M104，M105，M106，M107存储了产量计数，读取如下：
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="ReadExample2" title="Read示例" />
	/// 以下是读取不同类型数据的示例
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="ReadExample1" title="Read示例" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="WriteExample1" title="Write示例" />
	/// 以下是一个复杂的读取示例
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="ReadExample3" title="Read示例" />
	/// 在西门子PLC，字符串分为普通的string，和WString类型，前者为单字节的类型，后者为双字节的字符串类型<br />
	/// 一个字符串除了本身的数据信息，还有字符串的长度信息，比如字符串 "12345"，比如在PLC的地址 DB1.0 存储的字节是 FE 05 31 32 33 34 35, 第一个字节是最大长度，第二个字节是当前长度，后面的才是字符串的数据信息。<br />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="ReadWriteString" title="字符串读写示例" />
	/// </example>
	public class SiemensS7Net : DeviceTcpNet
	{
		private byte[] plcHead1 = new byte[22]
		{
			3, 0, 0, 22, 17, 224, 0, 0, 0, 1,
			0, 192, 1, 10, 193, 2, 1, 2, 194, 2,
			1, 0
		};

		private byte[] plcHead2 = new byte[25]
		{
			3, 0, 0, 25, 2, 240, 128, 50, 1, 0,
			0, 4, 0, 0, 8, 0, 0, 240, 0, 0,
			1, 0, 1, 1, 224
		};

		private byte[] plcOrderNumber = new byte[33]
		{
			3, 0, 0, 33, 2, 240, 128, 50, 7, 0,
			0, 0, 1, 0, 8, 0, 8, 0, 1, 18,
			4, 17, 68, 1, 0, 255, 9, 0, 4, 0,
			17, 0, 0
		};

		private SiemensPLCS CurrentPlc = SiemensPLCS.S1200;

		private byte[] plcHead1_200smart = new byte[22]
		{
			3, 0, 0, 22, 17, 224, 0, 0, 0, 1,
			0, 193, 2, 16, 0, 194, 2, 3, 0, 192,
			1, 10
		};

		private byte[] plcHead2_200smart = new byte[25]
		{
			3, 0, 0, 25, 2, 240, 128, 50, 1, 0,
			0, 204, 193, 0, 8, 0, 0, 240, 0, 0,
			1, 0, 1, 3, 192
		};

		private byte[] plcHead1_200 = new byte[22]
		{
			3, 0, 0, 22, 17, 224, 0, 0, 0, 1,
			0, 193, 2, 77, 87, 194, 2, 77, 87, 192,
			1, 9
		};

		private byte[] plcHead2_200 = new byte[25]
		{
			3, 0, 0, 25, 2, 240, 128, 50, 1, 0,
			0, 0, 0, 0, 8, 0, 0, 240, 0, 0,
			1, 0, 1, 3, 192
		};

		private byte[] S7_STOP = new byte[33]
		{
			3, 0, 0, 33, 2, 240, 128, 50, 1, 0,
			0, 14, 0, 0, 16, 0, 0, 41, 0, 0,
			0, 0, 0, 9, 80, 95, 80, 82, 79, 71,
			82, 65, 77
		};

		private byte[] S7_HOT_START = new byte[37]
		{
			3, 0, 0, 37, 2, 240, 128, 50, 1, 0,
			0, 12, 0, 0, 20, 0, 0, 40, 0, 0,
			0, 0, 0, 0, 253, 0, 0, 9, 80, 95,
			80, 82, 79, 71, 82, 65, 77
		};

		private byte[] S7_COLD_START = new byte[39]
		{
			3, 0, 0, 39, 2, 240, 128, 50, 1, 0,
			0, 15, 0, 0, 22, 0, 0, 40, 0, 0,
			0, 0, 0, 0, 253, 0, 2, 67, 32, 9,
			80, 95, 80, 82, 79, 71, 82, 65, 77
		};

		private byte plc_rack;

		private byte plc_slot;

		private int pdu_length = 200;

		private int pdu_length_set = -1;

		private int pdu_length_default = 200;

		private const byte pduStart = 40;

		private const byte pduStop = 41;

		private const byte pduAlreadyStarted = 2;

		private const byte pduAlreadyStopped = 7;

		private SoftIncrementCount incrementCount = new SoftIncrementCount(65535L, 1L);

		/// <summary>
		/// PLC的槽号，针对S7-400的PLC设置的<br />
		/// The slot number of PLC is set for PLC of s7-400
		/// </summary>
		public byte Slot
		{
			get
			{
				return plc_slot;
			}
			set
			{
				plc_slot = value;
				if (CurrentPlc != SiemensPLCS.S200 && CurrentPlc != SiemensPLCS.S200Smart)
				{
					plcHead1[21] = (byte)(plc_rack * 32 + plc_slot);
				}
			}
		}

		/// <summary>
		/// PLC的机架号，针对S7-400的PLC设置的<br />
		/// The frame number of the PLC is set for the PLC of s7-400
		/// </summary>
		public byte Rack
		{
			get
			{
				return plc_rack;
			}
			set
			{
				plc_rack = value;
				if (CurrentPlc != SiemensPLCS.S200 && CurrentPlc != SiemensPLCS.S200Smart)
				{
					plcHead1[21] = (byte)(plc_rack * 32 + plc_slot);
				}
			}
		}

		/// <summary>
		/// 获取或设置当前PLC的连接方式，PG: 0x01，OP: 0x02，S7Basic: 0x03...0x10<br />
		/// Get or set the current PLC connection mode, PG: 0x01, OP: 0x02, S7Basic: 0x03...0x10
		/// </summary>
		public byte ConnectionType
		{
			get
			{
				return plcHead1[20];
			}
			set
			{
				if (CurrentPlc != SiemensPLCS.S200 && CurrentPlc != SiemensPLCS.S200Smart)
				{
					plcHead1[20] = value;
				}
			}
		}

		/// <summary>
		/// 西门子相关的本地TSAP参数信息<br />
		/// A parameter information related to Siemens
		/// </summary>
		public int LocalTSAP
		{
			get
			{
				if (CurrentPlc == SiemensPLCS.S200 || CurrentPlc == SiemensPLCS.S200Smart)
				{
					return plcHead1[13] * 256 + plcHead1[14];
				}
				return plcHead1[16] * 256 + plcHead1[17];
			}
			set
			{
				if (CurrentPlc == SiemensPLCS.S200 || CurrentPlc == SiemensPLCS.S200Smart)
				{
					plcHead1[13] = BitConverter.GetBytes(value)[1];
					plcHead1[14] = BitConverter.GetBytes(value)[0];
				}
				else
				{
					plcHead1[16] = BitConverter.GetBytes(value)[1];
					plcHead1[17] = BitConverter.GetBytes(value)[0];
				}
			}
		}

		/// <summary>
		/// 西门子相关的远程TSAP参数信息<br />
		/// A parameter information related to Siemens
		/// </summary>
		public int DestTSAP
		{
			get
			{
				if (CurrentPlc == SiemensPLCS.S200 || CurrentPlc == SiemensPLCS.S200Smart)
				{
					return plcHead1[17] * 256 + plcHead1[18];
				}
				return plcHead1[20] * 256 + plcHead1[21];
			}
			set
			{
				if (CurrentPlc == SiemensPLCS.S200 || CurrentPlc == SiemensPLCS.S200Smart)
				{
					plcHead1[17] = BitConverter.GetBytes(value)[1];
					plcHead1[18] = BitConverter.GetBytes(value)[0];
				}
				else
				{
					plcHead1[20] = BitConverter.GetBytes(value)[1];
					plcHead1[21] = BitConverter.GetBytes(value)[0];
				}
			}
		}

		/// <summary>
		/// 获取当前西门子的PDU的长度信息，不同型号PLC的值会不一样。例如设置值为300，如果想要恢复默认值的话，设置为-1<br />
		/// Get the length information of the current Siemens PDU, the value of different types of PLC will be different.
		/// </summary>
		/// <remarks>V12.6.0版本开放修改值，方便用户手动强制设置pdu长度信息</remarks>
		public int PDULength
		{
			get
			{
				return pdu_length;
			}
			set
			{
				if (value > 100)
				{
					pdu_length = value;
				}
				else
				{
					pdu_length = pdu_length_default;
				}
				pdu_length_set = value;
			}
		}

		/// <summary>
		/// 实例化一个西门子的S7协议的通讯对象 <br />
		/// Instantiate a communication object for a Siemens S7 protocol
		/// </summary>
		/// <param name="siemens">指定西门子的型号</param>
		public SiemensS7Net(SiemensPLCS siemens)
		{
			Initialization(siemens, string.Empty);
		}

		/// <summary>
		/// 实例化一个西门子的S7协议的通讯对象并指定Ip地址 <br />
		/// Instantiate a communication object for a Siemens S7 protocol and specify an IP address
		/// </summary>
		/// <param name="siemens">指定西门子的型号</param>
		/// <param name="ipAddress">Ip地址</param>
		public SiemensS7Net(SiemensPLCS siemens, string ipAddress)
		{
			Initialization(siemens, ipAddress);
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new S7Message();
		}

		/// <summary>
		/// 初始化方法<br />
		/// Initialize method
		/// </summary>
		/// <param name="siemens">指定西门子的型号 -&gt; Designation of Siemens</param>
		/// <param name="ipAddress">Ip地址 -&gt; IpAddress</param>
		private void Initialization(SiemensPLCS siemens, string ipAddress)
		{
			base.WordLength = 2;
			IpAddress = ipAddress;
			Port = 102;
			CurrentPlc = siemens;
			base.ByteTransform = new ReverseBytesTransform();
			switch (siemens)
			{
			case SiemensPLCS.S1200:
				plcHead1[21] = 0;
				break;
			case SiemensPLCS.S300:
				plcHead1[21] = 2;
				break;
			case SiemensPLCS.S400:
				plcHead1[21] = 3;
				plcHead1[17] = 0;
				break;
			case SiemensPLCS.S1500:
				plcHead1[21] = 0;
				break;
			case SiemensPLCS.S200Smart:
				plcHead1 = plcHead1_200smart;
				plcHead2 = plcHead2_200smart;
				break;
			case SiemensPLCS.S200:
				plcHead1 = plcHead1_200;
				plcHead2 = plcHead2_200;
				break;
			default:
				plcHead1[18] = 0;
				break;
			}
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReadFromCoreServer(CommunicationPipe pipe, byte[] send, bool hasResponseData, bool usePackAndUnpack)
		{
			OResult<byte[]> oResult;
			byte[] content;
			do
			{
				oResult = base.ReadFromCoreServer(pipe, send, hasResponseData, usePackAndUnpack);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				content = oResult.Content;
			}
			while (content == null || content.Length < 4 || oResult.Content[2] * 256 + oResult.Content[3] == 7);
			return oResult;
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, plcHead1, hasResponseData: true, usePackAndUnpack: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(CommunicationPipe, plcHead2, hasResponseData: true, usePackAndUnpack: true);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			pdu_length_default = base.ByteTransform.TransUInt16(oResult2.Content.SelectLast(2), 0) - 28;
			if (pdu_length_default < 200)
			{
				pdu_length_default = 200;
			}
			pdu_length = pdu_length_default;
			if (pdu_length_set > 100)
			{
				pdu_length = pdu_length_set;
			}
			incrementCount = new SoftIncrementCount(65535L, 1L);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadFromCoreServerAsync(CommunicationPipe pipe, byte[] send, bool hasResponseData, bool usePackAndUnpack)
		{
			OResult<byte[]> oResult;
			byte[] content;
			do
			{
				oResult = await base.ReadFromCoreServerAsync(pipe, send, hasResponseData, usePackAndUnpack);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				content = oResult.Content;
			}
			while (content == null || content.Length < 4 || oResult.Content[2] * 256 + oResult.Content[3] == 7);
			return oResult;
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(CommunicationPipe, plcHead1, hasResponseData: true, usePackAndUnpack: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(CommunicationPipe, plcHead2, hasResponseData: true, usePackAndUnpack: true);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			pdu_length_default = base.ByteTransform.TransUInt16(oResult2.Content.SelectLast(2), 0) - 28;
			if (pdu_length_default < 200)
			{
				pdu_length_default = 200;
			}
			pdu_length = pdu_length_default;
			if (pdu_length_set > 100)
			{
				pdu_length = pdu_length_set;
			}
			incrementCount = new SoftIncrementCount(65535L, 1L);
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 从PLC读取订货号信息<br />
		/// Reading order number information from PLC
		/// </summary>
		/// <returns>CPU的订货号信息 -&gt; Order number information for the CPU</returns>
		public OResult<string> ReadOrderNumber()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(plcOrderNumber);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			if (oResult.Content == null || oResult.Content.Length < 91)
			{
				return new OResult<string>(StringResources.Language.ReceiveDataLengthTooShort + "91, Source: " + oResult.Content.ToHexString(' '));
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult.Content, 71, 20));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.ReadOrderNumber" />
		public async Task<OResult<string>> ReadOrderNumberAsync()
		{
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(plcOrderNumber);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			if (oResult.Content == null || oResult.Content.Length < 91)
			{
				return new OResult<string>(StringResources.Language.ReceiveDataLengthTooShort + "91, Source: " + oResult.Content.ToHexString(' '));
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult.Content, 71, 20));
		}

		private OResult CheckStartResult(byte[] content)
		{
			if (content == null || content.Length < 21)
			{
				return new OResult("Receive error length < 21, Content: " + ((content == null) ? "" : content.ToHexString(' ')));
			}
			if (content[19] != 40)
			{
				return new OResult("Can not start PLC");
			}
			if (content[20] != 2)
			{
				return new OResult("Can not start PLC");
			}
			return OResult.CreateSuccessResult();
		}

		private OResult CheckStopResult(byte[] content)
		{
			if (content == null || content.Length < 21)
			{
				return new OResult("Receive error length < 21, Content: " + ((content == null) ? "" : content.ToHexString(' ')));
			}
			if (content[19] != 41)
			{
				return new OResult("Can not stop PLC");
			}
			if (content[20] != 7)
			{
				return new OResult("Can not stop PLC");
			}
			return OResult.CreateSuccessResult();
		}

