		/// <summary>
		/// 将数据写入到PLC数据，地址格式为I100，Q100，DB20.100，M100，以字节为单位<br />
		/// Writes data to the PLC data, in the address format I100,Q100,DB20.100,M100, in bytes
		/// </summary>
		/// <param name="address">起始地址，格式为I100，M100，Q100，DB20.100 -&gt;
		/// Starting address, formatted as I100,M100,Q100,DB20.100</param>
		/// <param name="value">写入的原始数据 -&gt; Raw data written to</param>
		/// <returns>是否写入成功的结果对象 -&gt; Whether to write a successful result object</returns>
		/// <example>
		/// 假设起始地址为M100，M100,M101存储了温度，100.6℃值为1006，M102,M103存储了压力，1.23Mpa值为123，M104-M107存储了产量计数，写入如下：
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="WriteExample2" title="Write示例" />
		/// 以下是写入不同类型数据的示例
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="WriteExample1" title="Write示例" />
		/// </example>
		public override OResult Write(string address, byte[] value)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return Write(oResult.Content, value);
		}

		private OResult Write(S7AddressData address, byte[] value)
		{
			int num = value.Length;
			ushort num2 = 0;
			while (num2 < num)
			{
				ushort num3 = (ushort)Math.Min(num - num2, pdu_length);
				byte[] data = base.ByteTransform.TransByte(value, num2, num3);
				OResult<byte[]> oResult = BuildWriteByteCommand(address, data, GetMessageId());
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult oResult2 = WriteBase(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				num2 += num3;
				address.AddressStart += num3 * 8;
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 使用离散的方式，同时写入多个数据块到不同的地址中去，但是支持的地址数量及写入数据的最大长度是有限制的，不能超过pdu长度限制。<br />
		/// Using the discrete method, multiple blocks of data are written to different addresses at the same time, but the number of supported addresses and the maximum length of the data written are limited, and cannot exceed the PDU length limit.
		/// </summary>
		/// <param name="address">地址数组信息</param>
		/// <param name="data">原始数据列表</param>
		/// <returns>是否写入成功</returns>
		public OResult Write(string[] address, List<byte[]> data)
		{
			S7AddressData[] array = new S7AddressData[address.Length];
			for (int i = 0; i < address.Length; i++)
			{
				OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address[i], 1);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				array[i] = oResult.Content;
			}
			OResult<byte[]> oResult2 = BuildWriteByteCommand(array, data, GetMessageId());
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ReadFromCoreServer(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return AnalysisWrite(oResult3.Content);
		}

