		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Read(Snet.Driver.Core.Address.S7AddressData[])" />
		public async Task<OResult<byte[]>> ReadAsync(S7AddressData[] s7Addresses)
		{
			List<byte> bytes = new List<byte>();
			List<S7AddressData[]> groups = SiemensS7Helper.ArraySplitByLength(s7Addresses, pdu_length);
			for (int i = 0; i < groups.Count; i++)
			{
				S7AddressData[] array = groups[i];
				if (array.Length == 1 && array[0].Length > pdu_length)
				{
					S7AddressData[] array2 = SiemensS7Helper.SplitS7Address(array[0], pdu_length);
					for (int j = 0; j < array2.Length; j++)
					{
						OResult<byte[]> oResult = await ReadS7AddressDataAsync(new S7AddressData[1] { array2[j] });
						if (!oResult.IsSuccess)
						{
							return oResult;
						}
						bytes.AddRange(oResult.Content);
					}
				}
				else
				{
					OResult<byte[]> oResult2 = await ReadS7AddressDataAsync(array);
					if (!oResult2.IsSuccess)
					{
						return oResult2;
					}
					bytes.AddRange(oResult2.Content);
				}
			}
			return OResult.CreateSuccessResult(bytes.ToArray());
		}

