		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Byte[])" />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return await WriteAsync(oResult.Content, value);
		}

		private async Task<OResult> WriteAsync(S7AddressData address, byte[] value)
		{
			int length = value.Length;
			ushort alreadyFinished = 0;
			while (alreadyFinished < length)
			{
				ushort writeLength = (ushort)Math.Min(length - alreadyFinished, pdu_length);
				byte[] data = base.ByteTransform.TransByte(value, alreadyFinished, writeLength);
				OResult<byte[]> oResult = BuildWriteByteCommand(address, data, GetMessageId());
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult oResult2 = await WriteBaseAsync(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				alreadyFinished += writeLength;
				address.AddressStart += writeLength * 8;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String[],System.Collections.Generic.List{System.Byte[]})" />
