			for (int i = 0; i < address.Length; i++)
			{
				OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address[i], 1);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				array[i] = oResult.Content;
			}
			OResult<byte[]> oResult2 = BuildWriteByteCommand(array, data, GetMessageId());
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = await ReadFromCoreServerAsync(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return AnalysisWrite(oResult3.Content);
		}

		/// <summary>
		/// 读取指定地址的bool数据，地址格式为I100，M100，Q100，DB20.100<br />
		/// reads bool data for the specified address in the format I100，M100，Q100，DB20.100
		/// </summary>
		/// <param name="address">起始地址，格式为I100，M100，Q100，DB20.100 -&gt;
		/// Starting address, formatted as I100,M100,Q100,DB20.100</param>
		/// <returns>是否读取成功的结果对象 -&gt; Whether to read the successful result object</returns>
		/// <remarks>
		/// <note type="important">
		/// 对于200smartPLC的V区，就是DB1.X，例如，V100=DB1.100
		/// </note>
		/// </remarks>
		/// <example>
		/// 假设读取M100.0的位是否通断
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="ReadBool" title="ReadBool示例" />
		/// </example>
		public override OResult<bool> ReadBool(string address)
		{
			return ByteTransformHelper.GetResultFromBytes(ReadBitFromPLC(address), (byte[] m) => m[0] != 0);
		}

		/// <summary>
		/// 读取指定地址的bool数组，地址格式为I100，M100，Q100，DB20.100<br />
		/// reads bool array data for the specified address in the format I100，M100，Q100，DB20.100
		/// </summary>
		/// <param name="address">起始地址，格式为I100，M100，Q100，DB20.100 -&gt;
		/// Starting address, formatted as I100,M100,Q100,DB20.100</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>是否读取成功的结果对象 -&gt; Whether to read the successful result object</returns>
		/// <remarks>
		/// <note type="important">
		/// 对于200smartPLC的V区，就是DB1.X，例如，V100=DB1.100
		/// </note>
		/// </remarks>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			SnetHelper.CalculateStartBitIndexAndLength(oResult.Content.AddressStart, length, out var newStart, out var byteLength, out var offset);
			oResult.Content.AddressStart = newStart;
			oResult.Content.Length = byteLength;
			OResult<byte[]> oResult2 = Read(new S7AddressData[1] { oResult.Content });
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectMiddle(offset, length));
		}

		/// <summary>
		/// 写入PLC的一个位，例如"M100.6"，"I100.7"，"Q100.0"，"DB20.100.0"，如果只写了"M100"默认为"M100.0"<br />
		/// Write a bit of PLC, for example  "M100.6",  "I100.7",  "Q100.0",  "DB20.100.0", if only write  "M100" defaults to  "M100.0"
		/// </summary>
		/// <param name="address">起始地址，格式为"M100.6",  "I100.7",  "Q100.0",  "DB20.100.0" -&gt;
		/// Start address, format  "M100.6",  "I100.7",  "Q100.0",  "DB20.100.0"</param>
		/// <param name="value">写入的数据，True或是False -&gt; Writes the data, either True or False</param>
		/// <returns>是否写入成功的结果对象 -&gt; Whether to write a successful result object</returns>
		/// <example>
		/// 假设写入M100.0的位是否通断
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7Net.cs" region="WriteBool" title="WriteBool示例" />
		/// </example>
		public override OResult Write(string address, bool value)
		{
			OResult<byte[]> oResult = BuildWriteBitCommand(address, value, GetMessageId());
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return WriteBase(oResult.Content);
		}

		/// <summary>
		/// [警告] 向PLC中写入bool数组，比如你写入M100,那么data[0]对应M100.0，写入的长度应该小于1600位<br />
		/// [Warn] Write the bool array to the PLC, for example, if you write M100, then data[0] corresponds to M100.0, 
		/// The length of the write should be less than 1600 bits
		/// </summary>
		/// <param name="address">起始地址，格式为I100，M100，Q100，DB20.100 -&gt; Starting address, formatted as I100,mM100,Q100,DB20.100</param>
		/// <param name="values">要写入的bool数组，长度为8的倍数 -&gt; The bool array to write, a multiple of 8 in length</param>
		/// <returns>是否写入成功的结果对象 -&gt; Whether to write a successful result object</returns>
		/// <remarks>
		/// <note type="warning">
		/// 批量写入bool数组存在一定的风险，举例写入M100.5的值 [true,false,true,true,false,true]，会读取M100-M101的byte[]，然后修改中间的位，再写入回去，
		/// 如果读取之后写入之前，PLC修改了其他位，则会影响其他的位的数据，请谨慎使用。<br />
		/// There is a certain risk in batch writing bool arrays. For example, writing the value of M100.5 [true,false,true,true,false,true], 
		/// will read the byte[] of M100-M101, then modify the middle bit, and then Write back. 
		/// If the PLC modifies other bits after reading and before writing, it will affect the data of other bits. Please use it with caution.
		/// </note>
		/// </remarks>
		public override OResult Write(string address, bool[] values)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			SnetHelper.CalculateStartBitIndexAndLength(oResult.Content.AddressStart, (ushort)values.Length, out var newStart, out var byteLength, out var offset);
			oResult.Content.AddressStart = newStart;
			oResult.Content.Length = byteLength;
			OResult<byte[]> oResult2 = Read(new S7AddressData[1] { oResult.Content });
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			bool[] array = oResult2.Content.ToBoolArray();
			Array.Copy(values, 0, array, offset, values.Length);
			return Write(oResult.Content, SoftBasic.BoolArrayToByte(array));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.ReadBool(System.String)" />
		public override async Task<OResult<bool>> ReadBoolAsync(string address)
		{
			return ByteTransformHelper.GetResultFromBytes(await ReadBitFromPLCAsync(address), (byte[] m) => m[0] != 0);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.ReadBool(System.String,System.UInt16)" />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			SnetHelper.CalculateStartBitIndexAndLength(oResult.Content.AddressStart, length, out var newStart, out var byteLength, out var offset);
			oResult.Content.AddressStart = newStart;
			oResult.Content.Length = byteLength;
			OResult<byte[]> oResult2 = await ReadAsync(new S7AddressData[1] { oResult.Content });
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectMiddle(offset, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Boolean)" />
		public override async Task<OResult> WriteAsync(string address, bool value)
		{
			OResult<byte[]> oResult = BuildWriteBitCommand(address, value, GetMessageId());
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return await WriteBaseAsync(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Boolean[])" />
		public override async Task<OResult> WriteAsync(string address, bool[] values)
		{
			OResult<S7AddressData> analysis = S7AddressData.ParseFrom(address);
			if (!analysis.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(analysis);
			}
			SnetHelper.CalculateStartBitIndexAndLength(analysis.Content.AddressStart, (ushort)values.Length, out var newStart, out var byteLength, out var offset);
			analysis.Content.AddressStart = newStart;
			analysis.Content.Length = byteLength;
			OResult<byte[]> oResult = await ReadAsync(new S7AddressData[1] { analysis.Content });
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			bool[] array = oResult.Content.ToBoolArray();
			Array.Copy(values, 0, array, offset, values.Length);
			return await WriteAsync(analysis.Content, SoftBasic.BoolArrayToByte(array));
		}

