		/// <summary>
		/// 强制输出一个位到指定的地址，针对PLC类型为 200smart 时有效<br />
		/// Force output one bit to the specified address, valid for PLC type 200smart
		/// </summary>
		/// <remarks>测试型号: S7-200 smart CPU SR30</remarks>
		/// <param name="address">西门子的地址信息，例如 I0.0, Q1.0, M2.0</param>
		/// <param name="value">输出值 false=断开, true=闭合</param>
		/// <returns>是否强制输出成功</returns>
		public OResult ForceBool(string address, bool value)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			byte[] array = new byte[47]
			{
				3, 0, 0, 47, 2, 240, 128, 50, 7, 0,
				0, 121, 249, 0, 12, 0, 18, 0, 1, 18,
				8, 18, 72, 11, 0, 0, 0, 0, 0, 255,
				9, 0, 14, 0, 1, 16, 1, 0, 1, 0,
				0, 130, 0, 0, 0, 1, 0
			};
			array[39] = (byte)(oResult.Content.DbBlock / 256);
			array[40] = (byte)(oResult.Content.DbBlock % 256);
			array[41] = oResult.Content.DataCode;
			array[42] = (byte)(oResult.Content.AddressStart / 256 / 256 % 256);
			array[43] = (byte)(oResult.Content.AddressStart / 256 % 256);
			array[44] = (byte)(oResult.Content.AddressStart % 256);
			array[45] = (value ? ((byte)1) : ((byte)0));
			OResult<byte[]> oResult2 = ReadFromCoreServer(array);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 取消所有强制输出，针对PLC类型为 200smart 时有效<br />
		/// Cancel all forced outputs, effective for PLC type 200smart
		/// </summary>
		/// <returns>是否取消成功</returns>
		public OResult CancelAllForce()
		{
			byte[] send = new byte[35]
			{
				3, 0, 0, 35, 2, 240, 128, 50, 7, 0,
				0, 166, 209, 0, 12, 0, 6, 0, 1, 18,
				8, 18, 72, 11, 0, 0, 0, 0, 0, 255,
				9, 0, 2, 2, 0
			};
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content.Length < 33)
			{
				return new OResult("Receive error");
			}
			if (oResult.Content[11] != 166 || oResult.Content[12] != 209)
			{
				return new OResult("CancelAllForceOut Fail!");
			}
			return OResult.CreateSuccessResult();
		}

