		/// <summary>
		/// A general method for generating a command header to read a Word data
		/// </summary>
		/// <param name="s7Addresses">siemens address</param>
		/// <param name="msgId">message id informaion</param>
		/// <returns>Message containing the result object</returns>
		public static OResult<byte[]> BuildReadCommand(S7AddressData[] s7Addresses, int msgId)
		{
			if (s7Addresses == null)
			{
				throw new NullReferenceException("s7Addresses");
			}
			if (s7Addresses.Length > 19)
			{
				throw new Exception(StringResources.Language.SiemensReadLengthCannotLargerThan19);
			}
			int num = s7Addresses.Length;
			byte[] array = new byte[19 + num * 12];
			array[0] = 3;
			array[1] = 0;
			array[2] = (byte)(array.Length / 256);
			array[3] = (byte)(array.Length % 256);
			array[4] = 2;
			array[5] = 240;
			array[6] = 128;
			array[7] = 50;
			array[8] = 1;
			array[9] = 0;
			array[10] = 0;
			array[11] = BitConverter.GetBytes(msgId)[1];
			array[12] = BitConverter.GetBytes(msgId)[0];
			array[13] = (byte)((array.Length - 17) / 256);
			array[14] = (byte)((array.Length - 17) % 256);
			array[15] = 0;
			array[16] = 0;
			array[17] = 4;
			array[18] = (byte)num;
			for (int i = 0; i < num; i++)
			{
				array[19 + i * 12] = 18;
				array[20 + i * 12] = 10;
				array[21 + i * 12] = 16;
				if (s7Addresses[i].DataCode == 30 || s7Addresses[i].DataCode == 31)
				{
					array[22 + i * 12] = s7Addresses[i].DataCode;
					array[23 + i * 12] = (byte)(s7Addresses[i].Length / 2 / 256);
					array[24 + i * 12] = (byte)(s7Addresses[i].Length / 2 % 256);
				}
				else if ((s7Addresses[i].DataCode == 6) | (s7Addresses[i].DataCode == 7))
				{
					array[22 + i * 12] = 4;
					array[23 + i * 12] = (byte)(s7Addresses[i].Length / 2 / 256);
					array[24 + i * 12] = (byte)(s7Addresses[i].Length / 2 % 256);
				}
				else
				{
					array[22 + i * 12] = 2;
					array[23 + i * 12] = (byte)(s7Addresses[i].Length / 256);
					array[24 + i * 12] = (byte)(s7Addresses[i].Length % 256);
				}
				array[25 + i * 12] = (byte)(s7Addresses[i].DbBlock / 256);
				array[26 + i * 12] = (byte)(s7Addresses[i].DbBlock % 256);
				array[27 + i * 12] = s7Addresses[i].DataCode;
				array[28 + i * 12] = (byte)(s7Addresses[i].AddressStart / 256 / 256 % 256);
				array[29 + i * 12] = (byte)(s7Addresses[i].AddressStart / 256 % 256);
				array[30 + i * 12] = (byte)(s7Addresses[i].AddressStart % 256);
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 生成一个位读取数据指令头的通用方法 -&gt;
		/// A general method for generating a bit-read-Data instruction header
		/// </summary>
		/// <param name="address">起始地址，例如M100.0，I0.1，Q0.1，DB2.100.2 -&gt;
		/// Start address, such as M100.0,I0.1,Q0.1,DB2.100.2
		/// </param>
		/// <param name="msgId">message id informaion</param>
		/// <returns>包含结果对象的报文 -&gt; Message containing the result object</returns>
		public static OResult<byte[]> BuildBitReadCommand(string address, int msgId)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[31];
			array[0] = 3;
			array[1] = 0;
			array[2] = (byte)(array.Length / 256);
			array[3] = (byte)(array.Length % 256);
			array[4] = 2;
			array[5] = 240;
			array[6] = 128;
			array[7] = 50;
			array[8] = 1;
			array[9] = 0;
			array[10] = 0;
			array[11] = BitConverter.GetBytes(msgId)[1];
			array[12] = BitConverter.GetBytes(msgId)[0];
			array[13] = (byte)((array.Length - 17) / 256);
			array[14] = (byte)((array.Length - 17) % 256);
			array[15] = 0;
			array[16] = 0;
			array[17] = 4;
			array[18] = 1;
			array[19] = 18;
			array[20] = 10;
			array[21] = 16;
			array[22] = 1;
			array[23] = 0;
			array[24] = 1;
			array[25] = (byte)(oResult.Content.DbBlock / 256);
			array[26] = (byte)(oResult.Content.DbBlock % 256);
			array[27] = oResult.Content.DataCode;
			array[28] = (byte)(oResult.Content.AddressStart / 256 / 256 % 256);
			array[29] = (byte)(oResult.Content.AddressStart / 256 % 256);
			array[30] = (byte)(oResult.Content.AddressStart % 256);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 生成一个写入字节数据的指令 -&gt; Generate an instruction to write byte data
		/// </summary>
		/// <param name="s7Address">起始地址，示例M100,I100,Q100,DB1.100 -&gt; Start Address, example M100,I100,Q100,DB1.100</param>
		/// <param name="data">原始的字节数据 -&gt; Raw byte data</param>
		/// <param name="msgId">message id informaion</param>
		/// <returns>包含结果对象的报文 -&gt; Message containing the result object</returns>
		public static OResult<byte[]> BuildWriteByteCommand(S7AddressData s7Address, byte[] data, int msgId)
		{
			return BuildWriteByteCommand(new S7AddressData[1] { s7Address }, new List<byte[]> { data }, msgId);
		}

		private static void WriteS7AddressToStream(MemoryStream ms, S7AddressData add, byte writeType, int dataLen)
		{
			ms.WriteByte(18);
			ms.WriteByte(10);
			ms.WriteByte(16);
			if (add.DataCode == 6 || add.DataCode == 7)
			{
				ms.WriteByte(4);
				ms.WriteByte(BitConverter.GetBytes(dataLen / 2)[1]);
				ms.WriteByte(BitConverter.GetBytes(dataLen / 2)[0]);
			}
			else
			{
				ms.WriteByte(writeType);
				ms.WriteByte(BitConverter.GetBytes(dataLen)[1]);
				ms.WriteByte(BitConverter.GetBytes(dataLen)[0]);
			}
			ms.WriteByte(BitConverter.GetBytes(add.DbBlock)[1]);
			ms.WriteByte(BitConverter.GetBytes(add.DbBlock)[0]);
			ms.WriteByte(add.DataCode);
			ms.WriteByte(BitConverter.GetBytes(add.AddressStart)[2]);
			ms.WriteByte(BitConverter.GetBytes(add.AddressStart)[1]);
			ms.WriteByte(BitConverter.GetBytes(add.AddressStart)[0]);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.BuildWriteByteCommand(Snet.Driver.Core.Address.S7AddressData,System.Byte[],System.Int32)" />
		public static OResult<byte[]> BuildWriteByteCommand(S7AddressData[] s7Address, List<byte[]> data, int msgId)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.Write(new byte[7] { 3, 0, 0, 0, 2, 240, 128 });
			memoryStream.WriteByte(50);
			memoryStream.WriteByte(1);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(BitConverter.GetBytes(msgId)[1]);
			memoryStream.WriteByte(BitConverter.GetBytes(msgId)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(s7Address.Length * 12 + 2)[1]);
			memoryStream.WriteByte(BitConverter.GetBytes(s7Address.Length * 12 + 2)[0]);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(5);
			memoryStream.WriteByte((byte)s7Address.Length);
			for (int i = 0; i < s7Address.Length; i++)
			{
				WriteS7AddressToStream(memoryStream, s7Address[i], 2, (data[i] != null) ? data[i].Length : 0);
			}
			int num = (int)memoryStream.Length;
			for (int j = 0; j < data.Count; j++)
			{
				memoryStream.WriteByte(0);
				memoryStream.WriteByte(4);
				if (data[j] != null)
				{
					memoryStream.WriteByte(BitConverter.GetBytes(data[j].Length * 8)[1]);
					memoryStream.WriteByte(BitConverter.GetBytes(data[j].Length * 8)[0]);
					memoryStream.Write(data[j]);
					if (j < data.Count - 1 && data[j].Length % 2 == 1)
					{
						memoryStream.WriteByte(0);
					}
				}
				else
				{
					memoryStream.WriteByte(0);
					memoryStream.WriteByte(0);
				}
			}
			byte[] array = memoryStream.ToArray();
			array[2] = (byte)(array.Length / 256);
			array[3] = (byte)(array.Length % 256);
			array[15] = BitConverter.GetBytes(array.Length - num)[1];
			array[16] = BitConverter.GetBytes(array.Length - num)[0];
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 生成一个写入位数据的指令 -&gt; Generate an instruction to write bit data
		/// </summary>
		/// <param name="address">起始地址，示例M100,I100,Q100,DB1.100 -&gt; Start Address, example M100,I100,Q100,DB1.100</param>
		/// <param name="data">是否通断 -&gt; Power on or off</param>
		/// <param name="msgId">message id informaion</param>
		/// <returns>包含结果对象的报文 -&gt; Message containing the result object</returns>
		public static OResult<byte[]> BuildWriteBitCommand(string address, bool data, int msgId)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[1] { data ? ((byte)1) : ((byte)0) };
			byte[] array2 = new byte[35 + array.Length];
			array2[0] = 3;
			array2[1] = 0;
			array2[2] = (byte)((35 + array.Length) / 256);
			array2[3] = (byte)((35 + array.Length) % 256);
			array2[4] = 2;
			array2[5] = 240;
			array2[6] = 128;
			array2[7] = 50;
			array2[8] = 1;
			array2[9] = 0;
			array2[10] = 0;
			array2[11] = BitConverter.GetBytes(msgId)[1];
			array2[12] = BitConverter.GetBytes(msgId)[0];
			array2[13] = 0;
			array2[14] = 14;
			array2[15] = (byte)((4 + array.Length) / 256);
			array2[16] = (byte)((4 + array.Length) % 256);
			array2[17] = 5;
			array2[18] = 1;
			array2[19] = 18;
			array2[20] = 10;
			array2[21] = 16;
			array2[22] = 1;
			array2[23] = (byte)(array.Length / 256);
			array2[24] = (byte)(array.Length % 256);
			array2[25] = (byte)(oResult.Content.DbBlock / 256);
			array2[26] = (byte)(oResult.Content.DbBlock % 256);
			array2[27] = oResult.Content.DataCode;
			array2[28] = (byte)(oResult.Content.AddressStart / 256 / 256);
			array2[29] = (byte)(oResult.Content.AddressStart / 256);
			array2[30] = (byte)(oResult.Content.AddressStart % 256);
			if (oResult.Content.DataCode == 28)
			{
				array2[31] = 0;
				array2[32] = 9;
			}
			else
			{
				array2[31] = 0;
				array2[32] = 3;
			}
			array2[33] = (byte)(array.Length / 256);
			array2[34] = (byte)(array.Length % 256);
			array.CopyTo(array2, 35);
			return OResult.CreateSuccessResult(array2);
		}

		private static OResult<byte[]> AnalysisReadByte(S7AddressData[] s7Addresses, byte[] content)
		{
			try
			{
				int num = 0;
				for (int i = 0; i < s7Addresses.Length; i++)
				{
					num = ((s7Addresses[i].DataCode != 31 && s7Addresses[i].DataCode != 30) ? (num + s7Addresses[i].Length) : (num + s7Addresses[i].Length * 2));
				}
				if (content.Length >= 21 && content[20] == s7Addresses.Length)
				{
					byte[] array = new byte[num];
					int num2 = 0;
					int num3 = 0;
					for (int j = 21; j < content.Length; j++)
					{
						if (j + 1 >= content.Length)
						{
							continue;
						}
						if (content[j] == byte.MaxValue && content[j + 1] == 4)
						{
							Array.Copy(content, j + 4, array, num3, s7Addresses[num2].Length);
							j += s7Addresses[num2].Length + 3;
							num3 += s7Addresses[num2].Length;
							num2++;
						}
						else if (content[j] == byte.MaxValue && content[j + 1] == 9)
						{
							int num4 = content[j + 2] * 256 + content[j + 3];
							if (num4 % 3 == 0)
							{
								for (int k = 0; k < num4 / 3; k++)
								{
									Array.Copy(content, j + 5 + 3 * k, array, num3, 2);
									num3 += 2;
								}
							}
							else
							{
								for (int l = 0; l < num4 / 5; l++)
								{
									Array.Copy(content, j + 7 + 5 * l, array, num3, 2);
									num3 += 2;
								}
							}
							j += num4 + 4;
							num2++;
						}
						else
						{
							if (content[j] == 5 && content[j + 1] == 0)
							{
								return new OResult<byte[]>(content[j], StringResources.Language.SiemensReadLengthOverPlcAssign);
							}
							if (content[j] == 6 && content[j + 1] == 0)
							{
								return new OResult<byte[]>(content[j], StringResources.Language.SiemensError0006);
							}
							if (content[j] == 10 && content[j + 1] == 0)
							{
								return new OResult<byte[]>(content[j], StringResources.Language.SiemensError000A);
							}
						}
					}
					return OResult.CreateSuccessResult(array);
				}
				return new OResult<byte[]>(StringResources.Language.SiemensDataLengthCheckFailed + " Msg:" + SoftBasic.ByteToHexString(content, ' '));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("AnalysisReadByte failed: " + ex.Message + Environment.NewLine + " Msg:" + SoftBasic.ByteToHexString(content, ' '));
			}
		}

		private static OResult AnalysisWrite(byte[] content)
		{
			try
			{
				if (content != null && content.Length >= 22)
				{
					int num = content[20];
					for (int i = 0; i < num; i++)
					{
						byte b = content[21 + i];
						switch (b)
						{
						case 5:
							return new OResult(b, StringResources.Language.SiemensReadLengthOverPlcAssign);
						case 6:
							return new OResult(b, StringResources.Language.SiemensError0006);
						case 10:
							return new OResult(b, StringResources.Language.SiemensError000A);
						default:
							return new OResult(b, StringResources.Language.SiemensWriteError + b + " Msg:" + SoftBasic.ByteToHexString(content, ' '));
						case byte.MaxValue:
							break;
						}
					}
					return OResult.CreateSuccessResult();
				}
				return new OResult(StringResources.Language.UnknownError + " Msg:" + SoftBasic.ByteToHexString(content, ' '));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("AnalysisWrite failed: " + ex.Message + Environment.NewLine + " Msg:" + SoftBasic.ByteToHexString(content, ' '));
			}
		}
	}
	/// <summary>
	/// 测试的基于S7 PLUS的协议，功能还未完成，无法调用
	/// </summary>
	public class SiemensS7Plus : DeviceTcpNet
	{
		private List<S7Object> dbObjects;

		private Dictionary<uint, S7Object> structIdCache = new Dictionary<uint, S7Object>();

		private object structIdLock = new object();

		private byte[] iso_head = new byte[20]
		{
			3, 0, 0, 36, 31, 224, 0, 0, 0, 1,
			0, 192, 1, 10, 193, 2, 1, 0, 194, 16
		};

		private byte[] destTSAP = Encoding.ASCII.GetBytes("SIMATIC-ROOT-HMI");

		private int pdu_length = 240;

		private SoftIncrementCount incrementCount;

		private SoftIncrementCount integrityIdCount;

		private SoftIncrementCount integrityIdSet;

		private byte protocolVersion;

		private bool useSSL;

		private OpenSslConnect sslConnect;

		private MemoryStream memoryStream = new MemoryStream();

		private AutoResetEvent autoResetEventPdu;

		private byte protoVersionBuffer = 2;

		private byte[] recieveBuffer;

		/// <summary>
		/// 西门子相关的本地TSAP参数信息<br />
		/// A parameter information related to Siemens
		/// </summary>
		public ushort LocalTSAP { get; set; } = 1536;

		/// <summary>
		/// 西门子相关的远程TSAP参数信息<br />
		/// A parameter information related to Siemens
		/// </summary>
		public byte[] DestTSAP
		{
			get
			{
				return destTSAP;
			}
			set
			{
				destTSAP = value;
			}
		}

		/// <summary>
		/// 最近一次的PDU类型
		/// </summary>
		public byte LastPDUType { get; set; }

		/// <summary>
		/// 获取当前西门子的PDU的长度信息，不同型号PLC的值会不一样。<br />
		/// Get the length information of the current Siemens PDU, the value of different types of PLC will be different.
		/// </summary>
		public int PDULength => pdu_length;

		/// <summary>
		/// 获取当前的通信会话ID信息
		/// </summary>
		public uint SessionID { get; private set; }

		/// <summary>
		/// 获取当前的PLC的订货号
		/// </summary>
		public string OrderNumber { get; private set; }

		/// <summary>
		/// 实例化一个西门子的S7协议的通讯对象 <br />
		/// Instantiate a communication object for a Siemens S7 protocol
		/// </summary>
		public SiemensS7Plus()
		{
			incrementCount = new SoftIncrementCount(65535L, 1L);
			integrityIdCount = new SoftIncrementCount(4294967295L, 0L);
			integrityIdSet = new SoftIncrementCount(4294967295L, 0L);
			base.WordLength = 2;
			base.ByteTransform = new ReverseBytesTransform();
			autoResetEventPdu = new AutoResetEvent(initialState: false);
			base.ReceiveTimeOut = 30000;
		}

		/// <summary>
		/// 实例化一个西门子的S7协议的通讯对象并指定Ip地址 <br />
		/// Instantiate a communication object for a Siemens S7 protocol and specify an IP address
		/// </summary>
		/// <param name="ipAddress">Ip地址</param>
		/// <param name="port">端口号信息</param>
		public SiemensS7Plus(string ipAddress, int port = 102)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new S7Message
			{
				CheckMessage = false
			};
		}

		private OResult<byte[]> ReadFromCoreServer(CommunicationPipe pipe, List<byte[]> sends, bool hasResponseData = true, bool usePackHeader = true)
		{
			INetMessage newNetMessage = GetNewNetMessage();
			if (newNetMessage != null)
			{
				newNetMessage.SendBytes = ((sends.Count > 0) ? sends[0] : null);
			}
			for (int i = 0; i < sends.Count; i++)
			{
				LogSendMessage(sends[i]);
			}
			OResult oResult = sslConnect.Write(sends);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (base.ReceiveTimeOut < 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (!hasResponseData)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (base.SleepTime > 0)
			{
				SnetHelper.ThreadSleep(base.SleepTime);
			}
			OResult<byte[]> oResult2 = null;
			if (autoResetEventPdu.WaitOne(base.ReceiveTimeOut))
			{
				newNetMessage.HeadBytes = recieveBuffer;
				oResult2 = OResult.CreateSuccessResult(recieveBuffer);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				return OResult.CreateSuccessResult(oResult2.Content);
			}
			pipe.RaisePipeError();
			pipe.CloseCommunication();
			sslConnect?.Dispose();
			return new OResult<byte[]>(-10000, StringResources.Language.ReceiveDataTimeout + base.ReceiveTimeOut);
		}

		private byte[] PackSendBuffer(byte[] buffer)
		{
			base.ByteTransform.TransByte(SessionID).CopyTo(buffer, 9);
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.Write(buffer);
			memoryStream.Write("00 00 04 E8 89 69 00 12 00 00 00 00 89 6A 00 13 00 89 6B 00 04 00 00".ToHexBytes());
			int num = buffer[3] * 256 + buffer[4];
			if (num == 1346 || num == 1266 || num == 1404 || num == 1236 || num == 1226)
			{
				uint value = (uint)integrityIdSet.GetCurrentValue();
				S7Object.WriteUint32(memoryStream, value);
			}
			else
			{
				uint value2 = (uint)integrityIdCount.GetCurrentValue();
				S7Object.WriteUint32(memoryStream, value2);
			}
			memoryStream.Write("00 00 00 00".ToHexBytes());
			buffer = memoryStream.ToArray();
			int value3 = (int)incrementCount.GetCurrentValue();
			buffer[7] = BitConverter.GetBytes(value3)[1];
			buffer[8] = BitConverter.GetBytes(value3)[0];
			return buffer;
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReadFromCoreServer(CommunicationPipe pipe, byte[] send, bool hasResponseData = true, bool usePackAndUnpack = true)
		{
			if (!useSSL)
			{
				OResult<byte[]> oResult;
				byte[] content;
				do
				{
					oResult = base.ReadFromCoreServer(pipe, send, hasResponseData, usePackAndUnpack);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					content = oResult.Content;
				}
				while (content == null || content.Length < 4 || oResult.Content[2] * 256 + oResult.Content[3] == 7);
				LastPDUType = oResult.Content[5];
				return oResult;
			}
			if (send[0] != 114)
			{
				if (usePackAndUnpack)
				{
					send = PackSendBuffer(send);
				}
				return ReadFromCoreServer(pipe, BuildS7PlusPdu(send, send.Length, 2), hasResponseData, usePackAndUnpack);
			}
			return ReadFromCoreServer(pipe, new List<byte[]> { send }, hasResponseData, usePackAndUnpack);
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			useSSL = false;
			CommunicationPipe.UseServerActivePush = false;
			incrementCount = new SoftIncrementCount(65535L, 1L);
			integrityIdCount = new SoftIncrementCount(4294967295L, 0L);
			SessionID = 0u;
			CommunicationPipe.ResetConnectErrorCount();
			OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, GetISOTelegrams(), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content.Length == 36 && LastPDUType != 208)
			{
				return new OResult(65536, "errIsoConnect");
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(CommunicationPipe, BuildInitSslCommand(), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (base.ByteTransform.TransUInt16(oResult2.Content, 14) != 1459)
			{
				CommunicationPipe.CloseCommunication();
				return new OResult("InitSsl failed: need 0x05b3 but actual 0x" + base.ByteTransform.TransUInt16(oResult2.Content, 14).ToString("X"));
			}
			protocolVersion = oResult2.Content[8];
			try
			{
				sslConnect?.Dispose();
				useSSL = true;
				sslConnect = new OpenSslConnect(SendS7Pdu, ReceiveS7Pdu);
				sslConnect.LogNet = base.LogNet;
				sslConnect.ObjectString = ToString();
			}
			catch (Exception ex)
			{
				return new OResult("Create OpenSslConnect failed: " + ex.Message);
			}
			CommunicationPipe.UseServerActivePush = true;
			base.InitializationOnConnect();
			try
			{
				sslConnect.SSLConnect();
				sslConnect.SSLInit();
			}
			catch (Exception ex2)
			{
				return new OResult(ex2.Message);
			}
			SnetHelper.ThreadSleep(100);
			OResult<byte[]> oResult3 = ReadFromCoreServer(CommunicationPipe, BuildCreateObjectRequest(), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			int index = 10;
			S7Object.GetValueUint64(oResult3.Content, ref index);
			index++;
			SessionID = S7Object.GetValueUint32(oResult3.Content, ref index);
			S7Object.GetValueUint32(oResult3.Content, ref index);
			int num = index;
			OrderNumber = Encoding.ASCII.GetString(ExtraResponseData(oResult3.Content, 319u, ref index, stuctType: true).Content);
			index = num;
			byte[] content = ExtraResponseData(oResult3.Content, 306u, ref index, stuctType: true).Content;
			OResult<byte[]> oResult4 = ReadFromCoreServer(CommunicationPipe, BuildMultiSetRequest(content), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult4.IsSuccess)
			{
				return oResult4;
			}
			dbObjects = null;
			lock (structIdLock)
			{
				structIdCache.Clear();
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override bool DecideWhetherQAMessage(CommunicationPipe pipe, OResult<byte[]> receive)
		{
			byte[] content = receive.Content;
			if (content != null && content.Length >= 4)
			{
				if (receive.Content[2] * 256 + receive.Content[3] == 7)
				{
					return false;
				}
				if (receive.Content.Length > 7)
				{
					sslConnect.ReadCompleted(receive.Content.RemoveBegin(7));
					if (receive.Content[7] == 22)
					{
						sslConnect.SSLInit();
					}
				}
			}
			return false;
		}

		/// <inheritdoc />
		protected override OResult ExtraOnDisconnect()
		{
			sslConnect?.Dispose();
			return base.ExtraOnDisconnect();
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			useSSL = false;
			CommunicationPipe.UseServerActivePush = false;
			incrementCount = new SoftIncrementCount(65535L, 1L);
			integrityIdCount = new SoftIncrementCount(4294967295L, 0L);
			SessionID = 0u;
			CommunicationPipe.ResetConnectErrorCount();
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(CommunicationPipe, GetISOTelegrams(), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content.Length == 36 && LastPDUType != 208)
			{
				return new OResult(65536, "errIsoConnect");
			}
			OResult<byte[]> read2 = await ReadFromCoreServerAsync(CommunicationPipe, BuildInitSslCommand(), hasResponseData: true, usePackAndUnpack: false);
			if (!read2.IsSuccess)
			{
				return read2;
			}
			if (base.ByteTransform.TransUInt16(read2.Content, 14) != 1459)
			{
				await CommunicationPipe.CloseCommunicationAsync();
				return new OResult("InitSsl failed: need 0x05b3 but actual 0x" + base.ByteTransform.TransUInt16(read2.Content, 14).ToString("X"));
			}
			protocolVersion = read2.Content[8];
			try
			{
				sslConnect?.Dispose();
				useSSL = true;
				sslConnect = new OpenSslConnect(SendS7Pdu, ReceiveS7Pdu);
				sslConnect.LogNet = base.LogNet;
				sslConnect.ObjectString = ToString();
			}
			catch (Exception ex)
			{
				return new OResult("Create OpenSslConnect failed: " + ex.Message);
			}
			CommunicationPipe.UseServerActivePush = true;
			base.InitializationOnConnect();
			try
			{
				sslConnect.SSLConnect();
				sslConnect.SSLInit();
			}
			catch (Exception ex2)
			{
				return new OResult(ex2.Message);
			}
			SnetHelper.ThreadSleep(100);
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(CommunicationPipe, BuildCreateObjectRequest(), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			int index = 10;
			S7Object.GetValueUint64(oResult2.Content, ref index);
			index++;
			SessionID = S7Object.GetValueUint32(oResult2.Content, ref index);
			S7Object.GetValueUint32(oResult2.Content, ref index);
			int num = index;
			OrderNumber = Encoding.ASCII.GetString(ExtraResponseData(oResult2.Content, 319u, ref index, stuctType: true).Content);
			index = num;
			OResult<byte[]> oResult3 = await ReadFromCoreServerAsync(send: BuildMultiSetRequest(ExtraResponseData(oResult2.Content, 306u, ref index, stuctType: true).Content), pipe: CommunicationPipe, hasResponseData: true, usePackAndUnpack: false);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			dbObjects = null;
			lock (structIdLock)
			{
				structIdCache.Clear();
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadFromCoreServerAsync(CommunicationPipe pipe, byte[] send, bool hasResponseData = true, bool usePackAndUnpack = true)
		{
			if (!useSSL)
			{
				OResult<byte[]> oResult;
				byte[] content;
				do
				{
					oResult = await base.ReadFromCoreServerAsync(pipe, send, hasResponseData, usePackAndUnpack);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					content = oResult.Content;
				}
				while (content == null || content.Length < 4 || oResult.Content[2] * 256 + oResult.Content[3] == 7);
				LastPDUType = oResult.Content[5];
				return oResult;
			}
			if (send[0] != 114)
			{
				if (usePackAndUnpack)
				{
					send = PackSendBuffer(send);
				}
				return await Task.Run(() => ReadFromCoreServer(pipe, BuildS7PlusPdu(send, send.Length, 2), hasResponseData, usePackAndUnpack));
			}
			return await Task.Run(() => ReadFromCoreServer(pipe, new List<byte[]> { send }, hasResponseData, usePackAndUnpack));
		}

		private OResult<S7Tag[]> CreateTagsFromAddress(string address, ushort length)
		{
			string[] address2 = address.Split(new char[1] { ';' }, StringSplitOptions.RemoveEmptyEntries);
			return CreateTagsFromAddress(address2);
		}

		private OResult<S7Tag[]> CreateTagsFromAddress(string[] address)
		{
			List<S7Tag> list = new List<S7Tag>();
			for (int i = 0; i < address.Length; i++)
			{
				string str = address[i];
				if (address[i].StartsWith("\"") || address[i].StartsWith("'"))
				{
					OResult<string> lIDFromTagName = GetLIDFromTagName(address[i]);
					if (!lIDFromTagName.IsSuccess)
					{
						return OResult.CreateFailedResult<S7Tag[]>(lIDFromTagName);
					}
					str = lIDFromTagName.Content;
				}
				string[] source = str.SplitDot();
				S7Tag s7Tag = new S7Tag();
				s7Tag.LID = source.Select((string m) => Convert.ToUInt32(m, 16)).ToList();
				list.Add(s7Tag);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<S7Tag[]> oResult = CreateTagsFromAddress(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<List<S7Value>> oResult2 = ReadTags(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			List<S7Value> content = oResult2.Content;
			if (content != null && content.Count > 0)
			{
				if (oResult2.Content.Count == 1)
				{
					return OResult.CreateSuccessResult(oResult2.Content[0].Buffer);
				}
				return OResult.CreateSuccessResult(SoftBasic.SpliceArray(oResult2.Content.Select((S7Value m) => m.Buffer).ToArray()));
			}
			return new OResult<byte[]>("S7 Value null, address not exist!");
		}

