		/// <inheritdoc />
		public override OResult Write(string address, string value, Encoding encoding)
		{
			OResult<byte[]> oResult = Read(address, 1);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			byte[] bytes = encoding.GetBytes(value);
			if (bytes.Length > oResult.Content[0])
			{
				return new OResult("string length is too big, must less than :" + oResult.Content[0]);
			}
			bytes.CopyTo(oResult.Content, 2);
			oResult.Content[1] = (byte)bytes.Length;
			return OResult.CreateSuccessResult(encoding.GetString(oResult.Content, 2, oResult.Content[1]));
		}

