		private OResult<string> GetLISFromS7TagName(string tagName, List<S7Tag> tags, StringBuilder ids, string[] names, int nameIndex)
		{
			if (nameIndex >= names.Length)
			{
				return OResult.CreateSuccessResult(ids.ToString());
			}
			if (tags == null)
			{
				return new OResult<string>("S7 tags is null, can not get tag");
			}
			string name = names[nameIndex];
			int num = -1;
			if (Regex.IsMatch(name, "\\[\\d+\\]$"))
			{
				int num2 = name.LastIndexOf("[");
				num = Convert.ToInt32(name.Substring(num2 + 1, name.Length - num2 - 2));
				name = name.Substring(0, num2);
			}
			name = name.Trim('"', '\'');
			S7Tag s7Tag = tags.FirstOrDefault((S7Tag m) => m.Name == name);
			if (s7Tag == null)
			{
				return new OResult<string>("Tag name " + name + " is not exist in current tags");
			}
			ids.AppendFormat(".{0:X}", s7Tag.LID[0]);
			if (num >= 0)
			{
				ids.AppendFormat(".{0:X}", num);
				if (s7Tag.TypeCode == 17)
				{
					ids.Append(".1");
				}
			}
			List<S7Tag> tags2 = null;
			if (s7Tag.TypeCode == 17)
			{
				bool flag = false;
				lock (structIdLock)
				{
					flag = structIdCache.ContainsKey(s7Tag.StructID);
				}
				if (!flag)
				{
					OResult<List<S7Object>> oResult = BrowseTags(s7Tag.StructID);
					if (oResult.IsSuccess && oResult.Content.Count == 1)
					{
						lock (structIdLock)
						{
							if (!structIdCache.ContainsKey(s7Tag.StructID))
							{
								structIdCache.Add(s7Tag.StructID, oResult.Content[0]);
							}
						}
					}
				}
				lock (structIdLock)
				{
					if (structIdCache.ContainsKey(s7Tag.StructID))
					{
						tags2 = structIdCache[s7Tag.StructID].S7Tags;
					}
				}
			}
			return GetLISFromS7TagName(tagName, tags2, ids, names, nameIndex + 1);
		}

		/// <summary>
		/// 根据输入的标签名称获取对应的LID，例子："A"."B[0]"."Tag1" 例子
		/// </summary>
		/// <param name="tagName">标签名称</param>
		/// <returns>操作结果，包含LID字符串</returns>
		public OResult<string> GetLIDFromTagName(string tagName)
		{
			string[] array = tagName.SplitDot();
			if (array.Length == 0)
			{
				return new OResult<string>("Tag name " + tagName + " is invalid, because the tag name is empty");
			}
			StringBuilder stringBuilder = new StringBuilder();
			string dbName = array[0].Trim('"', '\'');
			List<S7Object> list = dbObjects;
			if (list == null)
			{
				OResult<List<S7Object>> oResult = BrowseDB();
				if (!oResult.IsSuccess)
				{
					return new OResult<string>("Tag name " + tagName + " is invalid, because the DB blocks are not exist in cache, and browse db failed: " + oResult.Message);
				}
				if (oResult.Content.Count == 1)
				{
					dbObjects = oResult.Content[0].SubObjects;
				}
				else
				{
					dbObjects = oResult.Content;
				}
				list = dbObjects;
			}
			S7Object s7Object = list.FirstOrDefault((S7Object m) => m.Name == dbName);
			if (s7Object == null)
			{
				return new OResult<string>("Tag name " + tagName + " is invalid, because the DB block " + dbName + " is not exist in cache");
			}
			stringBuilder.AppendFormat("{0:X}", s7Object.RelationId);
			if (s7Object.S7Tags == null)
			{
				OResult<List<S7Object>> oResult2 = BrowseTags(s7Object);
				if (oResult2.IsSuccess && oResult2.Content.Count == 1)
				{
					if (oResult2.Content[0].S7Tags != null)
					{
						s7Object.S7Tags = oResult2.Content[0].S7Tags;
					}
					else
					{
						s7Object.S7Tags = new List<S7Tag>();
					}
				}
			}
			return GetLISFromS7TagName(tagName, s7Object.S7Tags, stringBuilder, array, 1);
		}

		/// <summary>
		/// 浏览当前PLC的DB块列表，并且拿到用户自定义的DB块的关联ID信息<br />
		/// Browse the DB block list of the current PLC and get the associated ID information of the user-defined DB block
		/// </summary>
		/// <returns>DB块列表信息</returns>
		public OResult<List<S7Object>> BrowseDB()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(BuildBrowseRequest(3u, new uint[3] { 233u, 2521u, 4288u })[0]);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<S7Object>>(oResult);
			}
			List<S7Object> list = ExploreResponse(oResult.Content);
			for (int i = 0; i < list.Count; i++)
			{
