				array[0] = 114;
				array[1] = protoVersion;
				array[2] = BitConverter.GetBytes(num3)[1];
				array[3] = BitConverter.GetBytes(num3)[0];
				Array.Copy(pduData, num, array, 4, num3);
				num += num3;
