			return $"SiemensS7Plus[{IpAddress}:{Port}]";
		}

		/// <summary>
		/// 构建S7完整的通信报文
		/// </summary>
		/// <param name="pdu">报文信息</param>
		/// <returns>报文</returns>
		public static byte[] BuildWithTPKTAndISO(byte[] pdu)
		{
			byte[] array = SoftBasic.SpliceArray<byte>(new byte[7] { 3, 0, 0, 31, 2, 240, 128 }, pdu);
			array[2] = BitConverter.GetBytes(array.Length)[1];
			array[3] = BitConverter.GetBytes(array.Length)[0];
			return array;
		}
	}
	/// <summary>
	/// 西门子S7协议的虚拟服务器，支持TCP协议，模拟的是1200的PLC进行通信，在客户端进行操作操作的时候，最好是选择1200的客户端对象进行通信。<br />
	/// The virtual server of Siemens S7 protocol supports TCP protocol. It simulates 1200 PLC for communication. When the client is operating, it is best to select the 1200 client object for communication.
	/// </summary>
	/// <remarks>
	/// 本西门子的虚拟PLC仅限商业授权用户使用，感谢支持。
	/// <note type="important">对于200smartPLC的V区，就是DB1.X，例如，V100=DB1.100</note>
	/// </remarks>
	/// <example>
	/// 地址支持的列表如下：
	/// <list type="table">
	///   <listheader>
	///     <term>地址名称</term>
	///     <term>地址代号</term>
	///     <term>示例</term>
	///     <term>地址进制</term>
	///     <term>字操作</term>
	///     <term>位操作</term>
	///     <term>备注</term>
	///   </listheader>
	///   <item>
	///     <term>中间寄存器</term>
	///     <term>M</term>
	///     <term>M100,M200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>输入寄存器</term>
	///     <term>I</term>
	///     <term>I100,I200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>输出寄存器</term>
	///     <term>Q</term>
	///     <term>Q100,Q200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>DB块寄存器</term>
	///     <term>DB</term>
	///     <term>DB1.100,DB1.200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>V寄存器</term>
	///     <term>V</term>
	///     <term>V100,V200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term>V寄存器本质就是DB块1</term>
	///   </item>
	///   <item>
	///     <term>定时器的值</term>
	///     <term>T</term>
	///     <term>T100,T200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term>未测试通过</term>
	///   </item>
	///   <item>
	///     <term>计数器的值</term>
	///     <term>C</term>
	///     <term>C100,C200</term>
	///     <term>10</term>
	///     <term>√</term>
	///     <term>√</term>
	///     <term>未测试通过</term>
	///   </item>
	/// </list>
	/// 你可以很快速并且简单的创建一个虚拟的s7服务器
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7ServerExample.cs" region="UseExample1" title="简单的创建服务器" />
	/// 当然如果需要高级的服务器，指定日志，限制客户端的IP地址，获取客户端发送的信息，在服务器初始化的时候就要参照下面的代码：
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7ServerExample.cs" region="UseExample4" title="定制服务器" />
	/// 服务器创建好之后，我们就可以对服务器进行一些读写的操作了，下面的代码是基础的BCL类型的读写操作。
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7ServerExample.cs" region="ReadWriteExample" title="基础的读写示例" />
	/// 高级的对于byte数组类型的数据进行批量化的读写操作如下：   
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SiemensS7ServerExample.cs" region="BytesReadWrite" title="字节的读写示例" />
	/// 更高级操作请参见源代码。
	/// </example>
	public class SiemensS7Server : DeviceServer
	{
		private SoftBuffer systemBuffer;

		private SoftBuffer inputBuffer;

		private SoftBuffer outputBuffer;

		private SoftBuffer memeryBuffer;

		private SoftBuffer countBuffer;

		private SoftBuffer timerBuffer;

		private SoftBuffer aiBuffer;

		private SoftBuffer aqBuffer;

		private Dictionary<int, SoftBuffer> dbBlockBuffer;

		private const int DataPoolLength = 65536;

		/// <summary>
		/// 是否分析通信报文信息，并将分析结果追加到报文日志里去<br />
		/// Should we analyze the communication message information and add the analysis results to the message log?
		/// </summary>
		public bool AnalysisLogMessage { get; set; }

		/// <summary>
		/// 实例化一个S7协议的服务器，支持I，Q，M，DB1.X, DB2.X, DB3.X 数据区块的读写操作<br />
		/// Instantiate a server with S7 protocol, support I, Q, M, DB1.X data block read and write operations
		/// </summary>
		public SiemensS7Server()
		{
			inputBuffer = new SoftBuffer(65536);
			outputBuffer = new SoftBuffer(65536);
			memeryBuffer = new SoftBuffer(65536);
			countBuffer = new SoftBuffer(131072);
			timerBuffer = new SoftBuffer(131072);
			aiBuffer = new SoftBuffer(65536);
			aqBuffer = new SoftBuffer(65536);
			systemBuffer = new SoftBuffer(65536);
			systemBuffer.SetBytes("43 50 55 20 32 32 36 20 43 4E 20 20 20 20 20 20 30 32 30 31".ToHexBytes(), 0);
			base.WordLength = 2;
			base.ByteTransform = new ReverseBytesTransform();
			dbBlockBuffer = new Dictionary<int, SoftBuffer>();
			dbBlockBuffer.Add(1, new SoftBuffer(65536));
			dbBlockBuffer.Add(2, new SoftBuffer(65536));
			dbBlockBuffer.Add(3, new SoftBuffer(65536));
		}

		/// <summary>
		/// 根据S7格式的地址，获取当前的数据缓存类对象
		/// </summary>
		/// <param name="s7Address">S7格式的数据地址信息</param>
		/// <returns>内存缓存对象</returns>
		private OResult<SoftBuffer> GetDataAreaFromS7Address(S7AddressData s7Address)
		{
			switch (s7Address.DataCode)
			{
			case 3:
				return OResult.CreateSuccessResult(systemBuffer);
			case 129:
				return OResult.CreateSuccessResult(inputBuffer);
			case 130:
				return OResult.CreateSuccessResult(outputBuffer);
			case 131:
				return OResult.CreateSuccessResult(memeryBuffer);
			case 132:
				if (dbBlockBuffer.ContainsKey(s7Address.DbBlock))
				{
					return OResult.CreateSuccessResult(dbBlockBuffer[s7Address.DbBlock]);
				}
				return new OResult<SoftBuffer>(10, StringResources.Language.SiemensError000A);
			case 30:
				return OResult.CreateSuccessResult(countBuffer);
			case 31:
				return OResult.CreateSuccessResult(timerBuffer);
			case 6:
				return OResult.CreateSuccessResult(aiBuffer);
			case 7:
				return OResult.CreateSuccessResult(aqBuffer);
			default:
				return new OResult<SoftBuffer>(6, StringResources.Language.SiemensError0006);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(oResult.Content);
			if (!dataAreaFromS7Address.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataAreaFromS7Address);
			}
			if (oResult.Content.DataCode == 30 || oResult.Content.DataCode == 31)
			{
				return OResult.CreateSuccessResult(dataAreaFromS7Address.Content.GetBytes(oResult.Content.AddressStart * 2, length * 2));
			}
			int num = oResult.Content.AddressStart / 8;
			if (num + length > dataAreaFromS7Address.Content.Capacity)
			{
				return new OResult<byte[]>(5, StringResources.Language.SiemensReadLengthOverPlcAssign);
			}
			return OResult.CreateSuccessResult(dataAreaFromS7Address.Content.GetBytes(num, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(oResult.Content);
			if (!dataAreaFromS7Address.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataAreaFromS7Address);
			}
			if (oResult.Content.DataCode == 30 || oResult.Content.DataCode == 31)
			{
				dataAreaFromS7Address.Content.SetBytes(value, oResult.Content.AddressStart * 2);
			}
			else
			{
				int num = oResult.Content.AddressStart / 8;
				if (num + value.Length > dataAreaFromS7Address.Content.Capacity)
				{
					return new OResult<byte[]>(5, StringResources.Language.SiemensReadLengthOverPlcAssign);
				}
				dataAreaFromS7Address.Content.SetBytes(value, num);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.ReadByte(System.String)" />
		public OResult<byte> ReadByte(string address)
		{
			return ByteTransformHelper.GetResultFromArray(Read(address, 1));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Byte)" />
		public OResult Write(string address, byte value)
		{
			return Write(address, new byte[1] { value });
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(oResult.Content);
			if (!dataAreaFromS7Address.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(dataAreaFromS7Address);
			}
			if (oResult.Content.AddressStart + length > dataAreaFromS7Address.Content.Capacity * 8)
			{
				return new OResult<bool[]>(5, StringResources.Language.SiemensReadLengthOverPlcAssign);
			}
			return OResult.CreateSuccessResult(dataAreaFromS7Address.Content.GetBool(oResult.Content.AddressStart, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Net.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			OResult<S7AddressData> oResult = S7AddressData.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(oResult.Content);
			if (!dataAreaFromS7Address.IsSuccess)
			{
				return dataAreaFromS7Address;
			}
			if (oResult.Content.AddressStart + value.Length > dataAreaFromS7Address.Content.Capacity * 8)
			{
				return new OResult(5, StringResources.Language.SiemensReadLengthOverPlcAssign);
			}
			dataAreaFromS7Address.Content.SetBool(value, oResult.Content.AddressStart);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult Write(string address, string value, Encoding encoding)
		{
			return SiemensS7Helper.Write(this, SiemensPLCS.S1200, address, value, encoding);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensS7Helper.WriteWString(Snet.Driver.Core.IReadWriteNet,Snet.Driver.Profinet.Siemens.SiemensPLCS,System.String,System.String)" />
