		/// <inheritdoc />
		protected override string GetLogTextFromBinary(PipeSession session, byte[] content)
		{
			string text = base.GetLogTextFromBinary(session, content);
			if (AnalysisLogMessage)
			{
				text += SiemensS7Helper.AnalysisAddressLogMessage(session, base.ByteTransform, content);
			}
			return text;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new S7Message();
		}

		private byte[] CreateHandleOneBack(byte[] handle)
		{
			byte[] array = new byte[handle.Length];
			handle.CopyTo(array, 0);
			array[5] = 208;
			array[6] = handle[8];
			array[7] = handle[9];
			array[8] = 0;
			array[9] = 12;
			return array;
		}

		private byte[] CreateHandleTwoBack(byte[] handle)
		{
			byte[] array = SoftBasic.HexStringToBytes("03 00 00 1B 02 f0 80 32 03 00 00 00 00 00 08 00 00 00 00 f0 01 00 01 00 f0 00 f0");
			if (handle.Length > 14)
			{
				array[11] = handle[11];
				array[12] = handle[12];
			}
			return array;
		}

		/// <inheritdoc />
		protected override OResult ThreadPoolLoginAfterClientCheck(PipeSession session, IPEndPoint endPoint)
		{
			if (IsNeedShakeHands())
			{
				CommunicationPipe communication = session.Communication;
				OResult<byte[]> oResult = communication.ReceiveMessage(new S7Message(), null, useActivePush: false, null, delegate(byte[] m)
				{
					LogRevcMessage(m, session);
				});
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				if (oResult.Content == null || oResult.Content.Length < 10)
				{
					return new OResult("Data is too short: " + oResult.Content.ToHexString(' '));
				}
				byte[] array = CreateHandleOneBack(oResult.Content);
				LogSendMessage(array, session);
				OResult oResult2 = communication.Send(array);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult<byte[]> oResult3 = communication.ReceiveMessage(new S7Message(), null, useActivePush: false, null, delegate(byte[] m)
				{
					LogRevcMessage(m, session);
				});
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				byte[] array2 = CreateHandleTwoBack(oResult3.Content);
				LogSendMessage(array2, session);
				OResult oResult4 = communication.Send(array2);
				if (!oResult4.IsSuccess)
				{
					return oResult4;
				}
			}
			return base.ThreadPoolLoginAfterClientCheck(session, endPoint);
		}

		/// <summary>
		/// 获取是否需要进行握手报文信息
		/// </summary>
		/// <returns>是否需要进行握手操作</returns>
		protected virtual bool IsNeedShakeHands()
		{
			return true;
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			byte[] array = null;
			try
			{
				if (receive[5] == 224)
				{
					return OResult.CreateSuccessResult(CreateHandleOneBack(receive));
				}
				if (receive[3] == 25 && receive[14] == 8)
				{
					return OResult.CreateSuccessResult(CreateHandleTwoBack(receive));
				}
				if (receive[17] == 4)
				{
					array = ReadByMessage(receive);
				}
				else if (receive[17] == 5)
				{
					array = WriteByMessage(receive);
				}
				else
				{
					if (receive[17] != 0)
					{
						return new OResult<byte[]>(StringResources.Language.NotSupportedFunction);
					}
					array = ReadPlcType();
				}
				receive.SelectMiddle(11, 2).CopyTo(array, 11);
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		private byte[] ReadPlcType()
		{
			return SoftBasic.HexStringToBytes("03 00 00 7D 02 F0 80 32 07 00 00 00 01 00 0C 00 60 00 01 12 08 12 84 01 01 00 00 00 00 FF 09 00 5C 00 11 00 00 00 1C 00 03 00 01 36 45 53 37 20 32 31 35 2D 31 41 47 34 30 2D 30 58 42 30 20 00 00 00 06 20 20 00 06 36 45 53 37 20 32 31 35 2D 31 41 47 34 30 2D 30 58 42 30 20 00 00 00 06 20 20 00 07 36 45 53 37 20 32 31 35 2D 31 41 47 34 30 2D 30 58 42 30 20 00 00 56 04 02 01");
		}

		/// <summary>
		/// 将读取的结果数据内容进行打包，返回客户端读取
		/// </summary>
		/// <param name="command">接收的命令信息</param>
		/// <param name="content">读取的原始字节信息</param>
		/// <returns>返回客户端的原始报文信息</returns>
		protected virtual byte[] PackReadBack(byte[] command, List<byte> content)
		{
			if (content.Count > 226)
			{
				content = new List<byte>(PackReadWordCommandBack(5, null));
			}
			byte[] array = new byte[21 + content.Count];
			SoftBasic.HexStringToBytes("03 00 00 1A 02 F0 80 32 03 00 00 00 01 00 02 00 05 00 00 04 01").CopyTo(array, 0);
			array[2] = (byte)(array.Length / 256);
			array[3] = (byte)(array.Length % 256);
			array[15] = (byte)(content.Count / 256);
			array[16] = (byte)(content.Count % 256);
			array[20] = command[18];
			content.CopyTo(array, 21);
			return array;
		}

		private byte[] ReadByMessage(byte[] packCommand)
		{
			List<byte> list = new List<byte>();
			int num = packCommand[18];
			int num2 = 19;
			for (int i = 0; i < num; i++)
			{
				byte b = packCommand[num2 + 1];
				byte[] command = packCommand.SelectMiddle(num2, b + 2);
				num2 += b + 2;
				list.AddRange(ReadByCommand(command));
			}
			return PackReadBack(packCommand, list);
		}

		private byte[] ReadByCommand(byte[] command)
		{
			if (command[3] == 1)
			{
				int num = command[9] * 65536 + command[10] * 256 + command[11];
				ushort dbBlock = base.ByteTransform.TransUInt16(command, 6);
				ushort num2 = base.ByteTransform.TransUInt16(command, 4);
				OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(new S7AddressData
				{
					AddressStart = num,
					DataCode = command[8],
					DbBlock = dbBlock,
					Length = 1
				});
				if (!dataAreaFromS7Address.IsSuccess)
				{
					return PackReadWordCommandBack((short)dataAreaFromS7Address.ErrorCode, null);
				}
				if (num + num2 > dataAreaFromS7Address.Content.Capacity * 8)
				{
					return PackReadWordCommandBack(5, null);
				}
				return PackReadBitCommandBack(dataAreaFromS7Address.Content.GetBool(num));
			}
			if (command[3] == 30 || command[3] == 31)
			{
				ushort num3 = base.ByteTransform.TransUInt16(command, 4);
				int num4 = command[9] * 65536 + command[10] * 256 + command[11];
				OResult<SoftBuffer> dataAreaFromS7Address2 = GetDataAreaFromS7Address(new S7AddressData
				{
					AddressStart = num4,
					DataCode = command[8],
					DbBlock = 0,
					Length = num3
				});
				if (!dataAreaFromS7Address2.IsSuccess)
				{
					throw new Exception(dataAreaFromS7Address2.Message);
				}
				return PackReadCTCommandBack(dataAreaFromS7Address2.Content.GetBytes(num4 * 2, num3 * 2), (command[3] == 30) ? 3 : 5);
			}
			ushort num5 = base.ByteTransform.TransUInt16(command, 4);
			if (command[3] == 4)
			{
				num5 *= 2;
			}
			ushort dbBlock2 = base.ByteTransform.TransUInt16(command, 6);
			int num6 = (command[9] * 65536 + command[10] * 256 + command[11]) / 8;
			OResult<SoftBuffer> dataAreaFromS7Address3 = GetDataAreaFromS7Address(new S7AddressData
			{
				AddressStart = num6,
				DataCode = command[8],
				DbBlock = dbBlock2,
				Length = num5
			});
			if (!dataAreaFromS7Address3.IsSuccess)
			{
				return PackReadWordCommandBack((short)dataAreaFromS7Address3.ErrorCode, null);
			}
			if (num6 + num5 > dataAreaFromS7Address3.Content.Capacity)
			{
				return PackReadWordCommandBack(5, null);
			}
			return PackReadWordCommandBack(0, dataAreaFromS7Address3.Content.GetBytes(num6, num5));
		}

		private byte[] PackReadWordCommandBack(short err, byte[] result)
		{
			if (err > 0)
			{
				byte[] array = new byte[4];
				BitConverter.GetBytes(err).CopyTo(array, 0);
				return array;
			}
			byte[] array2 = new byte[4 + result.Length];
			array2[0] = byte.MaxValue;
			array2[1] = 4;
			base.ByteTransform.TransByte((ushort)(result.Length * 8)).CopyTo(array2, 2);
			result.CopyTo(array2, 4);
			return array2;
		}

		private byte[] PackReadCTCommandBack(byte[] result, int dataLength)
		{
			byte[] array = new byte[4 + result.Length * dataLength / 2];
			array[0] = byte.MaxValue;
			array[1] = 9;
			base.ByteTransform.TransByte((ushort)(array.Length - 4)).CopyTo(array, 2);
			for (int i = 0; i < result.Length / 2; i++)
			{
				result.SelectMiddle(i * 2, 2).CopyTo(array, 4 + dataLength - 2 + i * dataLength);
			}
			return array;
		}

		private byte[] PackReadBitCommandBack(bool value)
		{
			byte[] obj = new byte[5] { 255, 3, 0, 1, 0 };
			obj[4] = (value ? ((byte)1) : ((byte)0));
			return obj;
		}

		private byte[] PackWriteBack(byte[] packCommand, byte status)
		{
			return PackWriteBack(packCommand, new byte[1] { status });
		}

		/// <summary>
		/// 创建返回的报文信息
		/// </summary>
		/// <param name="packCommand">接收到的报文命令</param>
		/// <param name="status">返回的状态信息</param>
		/// <returns>返回的原始字节数组</returns>
		protected virtual byte[] PackWriteBack(byte[] packCommand, byte[] status)
		{
			byte[] array = new byte[21 + status.Length];
			SoftBasic.HexStringToBytes("03 00 00 16 02 F0 80 32 03 00 00 00 01 00 02 00 01 00 00 05 01").CopyTo(array, 0);
			array[20] = (byte)status.Length;
			status.CopyTo(array, 21);
			array[2] = BitConverter.GetBytes(array.Length)[1];
			array[3] = BitConverter.GetBytes(array.Length)[0];
			return array;
		}

		private byte[] WriteByMessage(byte[] packCommand)
		{
			if (!base.EnableWrite)
			{
				return PackWriteBack(packCommand, 4);
			}
			int num = packCommand[18];
			byte[] array = new byte[num];
			int num2 = 19 + num * 12;
			for (int i = 0; i < num; i++)
			{
				if (packCommand[22 + 12 * i] == 2 || packCommand[22 + 12 * i] == 4)
				{
					ushort dbBlock = base.ByteTransform.TransUInt16(packCommand, 25 + 12 * i);
					int num3 = base.ByteTransform.TransInt16(packCommand, 23 + 12 * i);
					if (packCommand[22 + 12 * i] == 4)
					{
						num3 *= 2;
					}
					int num4 = 0;
					num4 = ((packCommand[27 + 12 * i] < 28 || packCommand[27 + 12 * i] > 31) ? ((packCommand[28 + 12 * i] * 65536 + packCommand[29 + 12 * i] * 256 + packCommand[30 + 12 * i]) / 8) : ((packCommand[28 + 12 * i] * 65536 + packCommand[29 + 12 * i] * 256 + packCommand[30 + 12 * i]) * 2));
					byte[] array2 = base.ByteTransform.TransByte(packCommand, num2 + 4, num3);
					num2 += 4 + num3;
					if (i < num - 1 && num3 % 2 == 1)
					{
						num2++;
					}
					OResult<SoftBuffer> dataAreaFromS7Address = GetDataAreaFromS7Address(new S7AddressData
					{
						DataCode = packCommand[27 + 12 * i],
						DbBlock = dbBlock,
						Length = 1
					});
					if (!dataAreaFromS7Address.IsSuccess)
					{
						array[i] = (byte)dataAreaFromS7Address.ErrorCode;
						continue;
					}
					if (num4 + array2.Length > dataAreaFromS7Address.Content.Capacity)
					{
						return PackWriteBack(packCommand, 5);
					}
					dataAreaFromS7Address.Content.SetBytes(array2, num4);
					array[i] = byte.MaxValue;
					continue;
				}
				ushort dbBlock2 = base.ByteTransform.TransUInt16(packCommand, 25 + 12 * i);
				int num5 = packCommand[28 + 12 * i] * 65536 + packCommand[29 + 12 * i] * 256 + packCommand[30 + 12 * i];
				int num6 = packCommand[num2 + 2] * 256 + packCommand[num2 + 3];
				int num7 = (num6 + 7) / 8;
				bool[] value = SoftBasic.ByteToBoolArray(packCommand.SelectMiddle(num2 + 4, num7), num6);
				num2 += 4 + num7;
				if (i < num - 1)
				{
					num2++;
				}
				OResult<SoftBuffer> dataAreaFromS7Address2 = GetDataAreaFromS7Address(new S7AddressData
				{
					DataCode = packCommand[27 + 12 * i],
					DbBlock = dbBlock2,
					Length = 1
				});
				if (!dataAreaFromS7Address2.IsSuccess)
				{
					array[i] = (byte)dataAreaFromS7Address2.ErrorCode;
					continue;
				}
				if (num5 >= dataAreaFromS7Address2.Content.Capacity * 8)
				{
					return PackWriteBack(packCommand, 5);
				}
				dataAreaFromS7Address2.Content.SetBool(value, num5);
				array[i] = byte.MaxValue;
			}
			return PackWriteBack(packCommand, array);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensS7Server.AddDbBlock(System.Int32,System.Int32)" />
		public void AddDbBlock(int db)
		{
			if (!dbBlockBuffer.ContainsKey(db))
			{
				dbBlockBuffer.Add(db, new SoftBuffer(65536));
			}
		}

		/// <summary>
		/// 新增一个独立的DB块数据区，如果这个DB块已经存在，则新增无效。<br />
		/// Add a separate DB block data area, if the DB block already exists, the new one is invalid.
		/// </summary>
		/// <param name="db">DB块ID信息</param>
		/// <param name="length">指定新增的DB块长度信息</param>
		public void AddDbBlock(int db, int length)
		{
			if (!dbBlockBuffer.ContainsKey(db))
			{
				dbBlockBuffer.Add(db, new SoftBuffer(length));
			}
		}

		/// <summary>
		/// 移除指定的DB块数据区，如果这个DB块不存在的话，操作无效，本方法无法移除1，2，3的DB块<br />
		/// Remove the specified DB block data area, if the DB block does not exist, the operation is invalid, and this method cannot remove the DB block of 1, 2, 3
		/// </summary>
		/// <param name="db">指定的ID信息</param>
		public void RemoveDbBlock(int db)
		{
			if (db != 1 && db != 2 && db != 3 && dbBlockBuffer.ContainsKey(db))
			{
				dbBlockBuffer.Remove(db);
			}
		}

		/// <summary>
		/// 获取当前的DB块数据区信息，返回一个字典对象，Key为DB块的ID，Value为对应的SoftBuffer对象<br />
		/// Get the current DB block data area information, returning a dictionary object, where the key is the ID of the DB block and the value is the corresponding SoftBuffer object.
		/// </summary>
		/// <returns>词典对象</returns>
		public Dictionary<int, SoftBuffer> GetDbBlockBuffer()
		{
			return dbBlockBuffer;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 393216)
			{
				throw new Exception("File is not correct");
			}
			inputBuffer.SetBytes(content, 0, 0, 65536);
			outputBuffer.SetBytes(content, 65536, 0, 65536);
			memeryBuffer.SetBytes(content, 131072, 0, 65536);
			dbBlockBuffer[1].SetBytes(content, 196608, 0, 65536);
			dbBlockBuffer[2].SetBytes(content, 262144, 0, 65536);
			dbBlockBuffer[3].SetBytes(content, 327680, 0, 65536);
			if (content.Length <= 458752)
			{
				return;
			}
			countBuffer.SetBytes(content, 458752, 0, 131072);
			timerBuffer.SetBytes(content, 589824, 0, 131072);
			if (content.Length <= 720896)
			{
				return;
			}
			int num = 720896;
			while (num < content.Length)
			{
				int key = BitConverter.ToInt32(content, num);
				int num2 = BitConverter.ToInt32(content, num + 4);
				num += 8;
				if (num + num2 <= content.Length)
				{
					if (!dbBlockBuffer.ContainsKey(key))
					{
						dbBlockBuffer.Add(key, new SoftBuffer(num2));
					}
					dbBlockBuffer[key].SetBytes(content, num, 0, num2);
					num += num2;
					continue;
				}
				break;
			}
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.Write(inputBuffer.GetBytes());
			memoryStream.Write(outputBuffer.GetBytes());
			memoryStream.Write(memeryBuffer.GetBytes());
			memoryStream.Write(dbBlockBuffer[1].GetBytes());
			memoryStream.Write(dbBlockBuffer[2].GetBytes());
			memoryStream.Write(dbBlockBuffer[3].GetBytes());
			memoryStream.Write(inputBuffer.GetBytes());
			memoryStream.Write(countBuffer.GetBytes());
			memoryStream.Write(timerBuffer.GetBytes());
			foreach (KeyValuePair<int, SoftBuffer> item in dbBlockBuffer)
			{
				if (item.Key != 1 && item.Key != 2 && item.Key != 3)
				{
					memoryStream.Write(BitConverter.GetBytes(item.Key));
					memoryStream.Write(BitConverter.GetBytes(item.Value.Capacity));
					memoryStream.Write(item.Value.GetBytes());
				}
			}
			return memoryStream.ToArray();
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				systemBuffer?.Dispose();
				inputBuffer?.Dispose();
				outputBuffer?.Dispose();
				memeryBuffer?.Dispose();
				countBuffer?.Dispose();
				timerBuffer?.Dispose();
				foreach (SoftBuffer value in dbBlockBuffer.Values)
				{
					value?.Dispose();
				}
				aiBuffer?.Dispose();
				aqBuffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SiemensS7Server[{base.Port}]";
		}
	}
	/// <summary>
	/// 西门子的基于WebApi协议读写数据对象，支持对PLC的标签进行读取，适用于1500系列，该数据标签需要共享开放出来。<br />
	/// Siemens reads and writes data objects based on the WebApi protocol, supports reading PLC tags, 
	/// and is suitable for the 1500 series. The data tags need to be shared and opened.
	/// </summary>
	public class SiemensWebApi : DeviceWebApi
	{
		private string rawUrl = "api/jsonrpc";

		private string token = string.Empty;

		private SoftIncrementCount incrementCount = new SoftIncrementCount(65535L, 1L);

		/// <summary>
		/// 当前PLC的通信令牌，当调用<see cref="M:Snet.Driver.Profinet.Siemens.SiemensWebApi.ConnectServer" />时，会自动获取，当然你也可以手动赋值一个合法的令牌，跳过<see cref="M:Snet.Driver.Profinet.Siemens.SiemensWebApi.ConnectServer" />直接进行读写操作。<br />
		/// The communication token of the current PLC will be automatically obtained when <see cref="M:Snet.Driver.Profinet.Siemens.SiemensWebApi.ConnectServer" /> is called. Of course, 
		/// you can also manually assign a valid token, skip <see cref="M:Snet.Driver.Profinet.Siemens.SiemensWebApi.ConnectServer" /> and read it directly Write operation.
		/// </summary>
		public string Token
		{
			get
			{
				return token;
			}
			set
			{
				token = value;
			}
		}

		/// <summary>
		/// 实例化一个默认的西门子WebApi通信对象<br />
		/// Instantiate a default Siemens WebApi communication object
		/// </summary>
		public SiemensWebApi()
			: this("127.0.0.1")
		{
		}

		/// <summary>
		/// 使用指定的ip地址及端口号来实例化一个对象，端口号默认使用443，如果是http访问，使用80端口号<br />
		/// Use the specified ip address and port number to instantiate an object, the port number is 443 by default, if it is http access, port 80 is used
		/// </summary>
		/// <param name="ipAddress">ip地址信息</param>
		/// <param name="port">端口号信息</param>
		public SiemensWebApi(string ipAddress, int port = 443)
			: base(ipAddress, port)
		{
			base.WordLength = 2;
			base.UseHttps = true;
			base.DefaultContentType = "application/json";
			base.ByteTransform = new ReverseBytesTransform();
		}

		/// <inheritdoc />
		protected override void AddRequestHeaders(HttpContentHeaders headers)
		{
			if (!string.IsNullOrEmpty(token))
			{
				headers.Add("X-Auth-Token", token);
			}
		}

		/// <summary>
		/// 根据设置好的用户名和密码信息，登录远程的PLC，返回是否登录成功！在读写之前，必须成功调用当前的方法，获取到token，否则无法进行通信。<br />
		/// According to the set user name and password information, log in to the remote PLC, and return whether the login is successful! 
		/// Before reading and writing, the current method must be successfully called to obtain the token, 
		/// otherwise communication cannot be carried out.
		/// </summary>
		/// <returns>是否连接成功</returns>
		public OResult ConnectServer()
		{
			JArray val = BuildConnectBody(incrementCount.GetCurrentValue(), base.UserName, base.Password);
			OResult<string> oResult = Post(rawUrl, ((object)val).ToString());
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return CheckLoginResult(oResult.Content);
		}

		/// <summary>
		/// 和PLC断开当前的连接信息，主要是使得Token信息失效。<br />
		/// Disconnecting the current connection information from the PLC mainly makes the token information invalid.
		/// </summary>
		/// <returns>是否断开成功</returns>
		public OResult ConnectClose()
		{
			return Logout();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensWebApi.ConnectServer" />
		public async Task<OResult> ConnectServerAsync()
		{
			OResult<string> oResult = await PostAsync(body: ((object)BuildConnectBody(incrementCount.GetCurrentValue(), base.UserName, base.Password)).ToString(), rawUrl: rawUrl);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return CheckLoginResult(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.SiemensWebApi.ConnectClose" />
		public async Task<OResult> ConnectCloseAsync()
		{
			return await LogoutAsync();
		}

		private OResult CheckLoginResult(string response)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Expected O, but got Unknown
			try
			{
				JObject val = (JObject)JArray.Parse(response)[0];
				OResult oResult = CheckErrorResult(val);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<JToken>(oResult);
				}
				if (val.ContainsKey("result"))
				{
					JToken obj = val["result"];
					JObject val2 = (JObject)(object)((obj is JObject) ? obj : null);
					token = ((JToken)val2).Value<string>((object)"token");
					return OResult.CreateSuccessResult();
				}
				return new OResult("Can't find result key and none token, login failed:" + Environment.NewLine + response);
			}
			catch (Exception ex)
			{
				return new OResult("CheckLoginResult failed:" + ex.Message + Environment.NewLine + response);
			}
		}

		/// <summary>
		/// 从PLC中根据输入的数据标签名称，读取出原始的字节数组信息，长度参数无效，需要二次解析<br />
		/// According to the input data tag name, read the original byte array information from the PLC, 
		/// the length parameter is invalid, and a second analysis is required
		/// </summary>
		/// <param name="address">标签的地址信息，例如 "全局DB".Static_21</param>
		/// <param name="length">无效的参数</param>
		/// <returns>原始的字节数组信息</returns>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			JArray val = BuildReadRawBody(incrementCount.GetCurrentValue(), address);
			OResult<string> oResult = Post(rawUrl, ((object)val).ToString());
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return CheckReadRawResult(oResult.Content);
		}

		/// <summary>
		/// 从PLC中根据输入的数据标签名称，按照类型byte进行读取出数据信息<br />
		/// According to the input data tag name from the PLC, read the data information according to the type byte
		/// </summary>
		/// <param name="address">标签的地址信息，例如 "全局DB".Static_21</param>
		/// <returns>包含是否成功的结果对象</returns>
		public OResult<byte> ReadByte(string address)
		{
			return ByteTransformHelper.GetResultFromArray(Read(address, 1));
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<byte[]> oResult = Read(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			return OResult.CreateSuccessResult(oResult.Content.ToBoolArray().SelectBegin(length));
		}

		/// <summary>
		/// 将原始的字节数组信息写入到PLC的指定的数据标签里，写入方式为raw写入，是否写入成功取决于PLC的返回信息<br />
		/// Write the original byte array information to the designated data tag of the PLC. 
		/// The writing method is raw writing. Whether the writing is successful depends on the return information of the PLC.
		/// </summary>
		/// <param name="address">标签的地址信息，例如 "全局DB".Static_21</param>
		/// <param name="value">原始的字节数据信息</param>
		/// <returns>是否成功写入PLC的结果对象</returns>
		public override OResult Write(string address, byte[] value)
		{
			JArray val = BuildWriteRawBody(incrementCount.GetCurrentValue(), address, value);
			OResult<string> oResult = Post(rawUrl, ((object)val).ToString());
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return CheckWriteResult(oResult.Content);
		}

		/// <summary>
		/// 写入<see cref="T:System.Byte" />数组数据，返回是否成功<br />
		/// Write <see cref="T:System.Byte" /> array data, return whether the write was successful
		/// </summary>
		/// <param name="address">标签的地址信息，例如 "全局DB".Static_21</param>
		/// <param name="value">写入值</param>
		/// <returns>是否写入成功</returns>
		public OResult Write(string address, byte value)
		{
			return Write(address, new byte[1] { value });
		}

		/// <summary>
		/// 批量写入<see cref="T:System.Boolean" />数组数据，返回是否成功<br />
		/// Batch write <see cref="T:System.Boolean" /> array data, return whether the write was successful
		/// </summary>
		/// <param name="address">标签的地址信息，例如 "全局DB".Static_21</param>
		/// <param name="value">写入值</param>
		/// <returns>是否写入成功</returns>
		public override OResult Write(string address, bool[] value)
		{
			byte[] value2 = value.ToByteArray();
			return Write(address, value2);
		}

		/// <summary>
		/// 从PLC中读取字符串内容，需要指定数据标签名称，使用JSON方式读取，所以无论字符串是中英文都是支持读取的。<br />
		/// To read the string content from the PLC, you need to specify the data tag name and use JSON to read it, 
		/// so no matter whether the string is in Chinese or English, it supports reading.
		/// </summary>
		/// <param name="address">标签的地址信息，例如 "全局DB".Static_21</param>
		/// <param name="length">无效参数</param>
		/// <returns>包含是否成功的结果对象</returns>
		public override OResult<string> ReadString(string address, ushort length)
		{
			JArray val = BuildReadJTokenBody(incrementCount.GetCurrentValue(), address);
			OResult<string> oResult = Post(rawUrl, ((object)val).ToString());
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<JToken> oResult2 = CheckAndExtraOneJsonResult(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			return OResult.CreateSuccessResult(Extensions.Value<string>((IEnumerable<JToken>)oResult2.Content));
		}

		/// <summary>
		/// 将字符串信息写入到PLC中，需要指定数据标签名称，如果PLC指定了类型为WString，才支持写入中文，否则会出现乱码。<br />
		/// To write string information into the PLC, you need to specify the data tag name. 
