			//IL_0012: Expected O, but got Unknown
			JObject val = (JObject)JArray.Parse(response)[0];
			OResult oResult = CheckErrorResult(val);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<JToken>(oResult);
			}
			if (val.ContainsKey("result"))
			{
				if (!Extensions.Value<bool>((IEnumerable<JToken>)val["result"]))
				{
					return new OResult(((object)val).ToString());
				}
				return OResult.CreateSuccessResult();
			}
			return new OResult<JToken>("Can't find result key and none token, login failed:" + Environment.NewLine + response);
		}

		private static OResult<JToken> CheckAndExtraOneJsonResult(string response)
		{
