		private static OResult<JToken[]> CheckAndExtraJsonResult(string response)
		{
			try
			{
				JArray val = JArray.Parse(response);
				List<JToken> list = new List<JToken>();
				for (int i = 0; i < ((JContainer)val).Count; i++)
				{
					JToken obj = val[i];
					JObject val2 = (JObject)(object)((obj is JObject) ? obj : null);
					if (val2 != null)
					{
						OResult oResult = CheckErrorResult(val2);
						if (!oResult.IsSuccess)
						{
							return OResult.CreateFailedResult<JToken[]>(oResult);
						}
						if (!val2.ContainsKey("result"))
						{
							return new OResult<JToken[]>("Can't find result key and none token, login failed:" + Environment.NewLine + response);
						}
						list.Add(val2["result"]);
					}
				}
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<JToken[]>("CheckAndExtraJsonResult failed: " + ex.Message + Environment.NewLine + "Content: " + response);
			}
		}
