			if (OpenSslNative.OPENSSL_init_ssl(0uL, IntPtr.Zero) != 1)
			{
				throw new Exception("errOpenSSL");
			}
			m_ptr_ssl_method = OpenSslNative.ExpectNonNull(OpenSslNative.TLS_client_method());
			m_ptr_ctx = OpenSslNative.ExpectNonNull(OpenSslNative.SSL_CTX_new(m_ptr_ssl_method));
			OpenSslNative.SSL_CTX_ctrl(m_ptr_ctx, 123, 772L, IntPtr.Zero);
			if (OpenSslNative.SSL_CTX_set_ciphersuites(m_ptr_ctx, "TLS_AES_256_GCM_SHA384:TLS_AES_128_GCM_SHA256") != 1)
			{
				throw new Exception("errOpenSSL");
			}
			m_readRequired = false;
			m_ssl = OpenSslNative.SSL_new(m_ptr_ctx);
			m_pBioIn = OpenSslNative.BIO_new(OpenSslNative.BIO_s_mem());
			m_pBioOut = OpenSslNative.BIO_new(OpenSslNative.BIO_s_mem());
			OpenSslNative.SSL_set_bio(m_ssl, m_pBioIn, m_pBioOut);
			this.sendDataFunc = sendDataFunc;
			this.receiveByte = receiveByte;
		}

		/// <summary>
		/// 连接
		/// </summary>
		public void SSLConnect()
		{
			OpenSslNative.SSL_set_connect_state(m_ssl);
		}

		/// <summary>
		/// 将PDU数据写入到当前的信息中
		/// </summary>
		/// <param name="value">原始数据信息</param>
		public OResult Write(byte[] value)
		{
			return Write(new List<byte[]> { value });
		}

		/// <summary>
		/// 将PDU数据写入到当前的信息中
		/// </summary>
		/// <param name="values">等待发送的字节列表</param>
		public OResult Write(List<byte[]> values)
		{
			try
			{
				for (int i = 0; i < values.Count; i++)
				{
					m_pendingWriteList.AddLast(values[i]);
				}
				RunSSL();
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				return new OResult(ex.Message);
			}
		}

		/// <summary>
		/// 收到了加密数据，写入到ssl里进行解密
		/// </summary>
		/// <param name="pData"></param>
		public void ReadCompleted(byte[] pData)
		{
			m_pendingReadList.AddLast(pData);
			RunSSL();
		}

		/// <summary>
		/// 初始化方法
		/// </summary>
		public void SSLInit()
		{
			OpenSslNative.SSL_in_init(m_ssl);
			if (OpenSslNative.BIO_ctrl_pending(m_pBioOut) != 0L)
			{
				SendPendingData();
			}
		}

		/// <summary>
		/// 运行当前的SSL方法
		/// </summary>
		private void RunSSL()
		{
			bool dataToWrite = false;
			bool dataToRead = false;
			GetPendingOperations(ref dataToRead, ref dataToWrite);
			while ((!m_readRequired & dataToWrite) | dataToRead)
			{
				OpenSslNative.SSL_in_init(m_ssl);
				if (dataToRead)
				{
					PerformRead();
				}
				if (!m_readRequired & dataToWrite)
				{
					PerformWrite();
				}
				if (OpenSslNative.BIO_ctrl_pending(m_pBioOut) != 0L)
				{
					SendPendingData();
				}
				GetPendingOperations(ref dataToRead, ref dataToWrite);
			}
		}

		private void GetPendingOperations(ref bool dataToRead, ref bool dataToWrite)
		{
			dataToRead = m_pendingReadList.Count > 0;
			dataToWrite = m_pendingWriteList.Count > 0;
		}

		private void PerformRead()
		{
			byte[] nextBuffer = GetNextBuffer(m_pendingReadList);
			if (nextBuffer != null)
			{
				DataToRead(nextBuffer, nextBuffer.Length);
			}
		}

		private void PerformWrite()
		{
			byte[] nextBuffer = GetNextBuffer(m_pendingWriteList);
			if (nextBuffer != null)
			{
				int num = DataToWrite(nextBuffer, nextBuffer.Length);
				if (num == 0)
				{
					m_pendingWriteList.AddLast(nextBuffer);
				}
				else if (num < nextBuffer.Length)
				{
					nextBuffer.RemoveBegin(num);
					m_pendingWriteList.AddLast(nextBuffer);
				}
			}
		}

		private void DataToRead(byte[] pData, int dataLength)
		{
			m_readRequired = false;
			int num = 0;
			while (num < dataLength)
			{
				byte[] array = new byte[dataLength - num];
				Array.Copy(pData, num, array, 0, array.Length);
				num += OpenSslNative.BIO_write(m_pBioIn, array, array.Length);
				int num2 = 0;
				do
				{
					byte[] array2 = new byte[4096];
					num2 = OpenSslNative.SSL_read(m_ssl, array2, array2.Length);
					if (num2 > 0)
					{
						receiveByte(array2.SelectBegin(num2));
					}
					_ = 0;
				}
				while (num2 > 0);
			}
		}

		private void SendPendingData()
		{
			while (OpenSslNative.BIO_ctrl_pending(m_pBioOut) != 0L)
			{
				byte[] array = new byte[4096];
				int num = OpenSslNative.BIO_read(m_pBioOut, array, array.Length);
				if (num > 0)
				{
					Array.Resize(ref array, num);
					OResult oResult = sendDataFunc(array);
					if (!oResult.IsSuccess)
					{
						LogNet?.WriteDebug(ObjectString, "SendPendingData failed: " + oResult.Message);
					}
				}
				if (num <= 0 && !skip_bio_should_retry)
				{
					try
					{
						OpenSslNative.BIO_should_retry(m_pBioOut);
					}
					catch (EntryPointNotFoundException)
					{
						skip_bio_should_retry = true;
					}
				}
			}
		}

		private int DataToWrite(byte[] pData, int dataLength)
		{
			int result = 0;
			int num = OpenSslNative.SSL_write(m_ssl, pData, dataLength);
			if (num < 0)
			{
				LogNet?.WriteDebug(ObjectString, "OpenSSL DataToWrite: Error = " + OpenSslNative.SSL_get_error(m_ssl, num));
			}
			else
			{
				result = num;
			}
			if (OpenSslNative.SSL_want(m_ssl) == 3)
			{
				m_readRequired = true;
			}
			return result;
		}

		private void HandleError(int result)
		{
			if (result <= 0)
			{
				int num = OpenSslNative.SSL_get_error(m_ssl, result);
				if (num != 0)
				{
					LogNet?.WriteDebug(ObjectString, "OpenSSL HandleError: Error = " + num);
				}
			}
		}

		private byte[] GetNextBuffer(LinkedList<byte[]> list)
		{
			byte[] result = null;
			if (list.Count > 0)
			{
				result = list.First.Value;
				list.RemoveFirst();
			}
			return result;
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		protected virtual void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				OpenSslNative.SSL_free(m_ssl);
				disposedValue = true;
			}
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}
	}
	/// <summary>
	/// 西门子的数据对象信息
	/// </summary>
	public class S7Object : IS7Object
	{
		private uint relationId;

		/// <summary>
		/// RelationId
		/// </summary>
		public uint RelationId
		{
			get
			{
				return relationId;
			}
			set
			{
				relationId = value;
				if (value == 80)
				{
					RelationId2 = 2415984640u;
				}
				if (value == 81)
				{
					RelationId2 = 2416050176u;
				}
				if (value == 82)
				{
					RelationId2 = 2416115712u;
				}
				if (value == 83)
				{
					RelationId2 = 2416312320u;
				}
				if (value == 84)
				{
					RelationId2 = 2416246784u;
				}
			}
		}

		/// <summary>
		/// 第二个关联的信息
		/// </summary>
		public uint RelationId2 { get; set; }

		/// <summary>
		/// ClassId
		/// </summary>
		public uint ClassId { get; set; }

		/// <summary>
		/// ClassFlags
		/// </summary>
		public uint ClassFlags { get; set; }

		/// <summary>
		/// AttributeId
		/// </summary>
		public uint AttributeId { get; set; }

		/// <summary>
		/// 名称信息
		/// </summary>
		public string Name { get; set; }

		/// <summary>
		/// 数据对象关联的子对象信息
		/// </summary>
		public List<S7Object> SubObjects { get; set; }

		/// <summary>
		/// 关联的节点信息
		/// </summary>
		public List<S7Tag> S7Tags { get; set; }

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.S7PlusHelper.IS7Object.WriteMessgae(System.IO.MemoryStream)" />
		public void WriteMessgae(MemoryStream ms)
		{
			WriteUint32(ms, 0u);
			WriteUint32(ms, RelationId);
			WriteUint32(ms, 2u);
			WriteUint32(ms, 2550u);
			WriteUint32(ms, 1u);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.S7PlusHelper.IS7Object.GetNumberOfFields" />
		public int GetNumberOfFields()
		{
			return 5;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return "S7Object[" + Name + "]";
		}

		private static int GetLongLength(ulong value)
		{
			ulong num = 128uL;
			int num2 = 0;
			while (true)
			{
				num2++;
				if (num2 >= 9)
				{
					return num2;
				}
				if (value < num)
				{
					break;
				}
				num <<= 7;
			}
			return num2;
		}

		private static void WriteAutoLength(MemoryStream ms, int len, ulong value)
		{
			byte[] array = new byte[len];
			for (int num = len - 1; num >= 0; num--)
			{
				if (num == len - 1)
				{
					if (num == 8)
					{
						array[num] = (byte)value;
						value >>= 8;
					}
					else
					{
						array[num] = (byte)(value & 0x7F);
						value >>= 7;
					}
				}
				else
				{
					array[num] = (byte)(value | 0x80);
					value >>= 7;
				}
			}
			ms.Write(array, 0, array.Length);
		}

		/// <summary>
		/// 写入一个uint类型的数据，使用动态长度表示方式，写入到字节流里去
		/// </summary>
		/// <param name="ms">字节流</param>
		/// <param name="value">值信息</param>
		public static void WriteUint32(MemoryStream ms, uint value)
		{
			WriteAutoLength(ms, GetLongLength(value), value);
		}

		/// <summary>
		/// 写入一个ulong类型的数据，使用动态长度表示方式，写入到字节流里去
		/// </summary>
		/// <param name="ms">字节流</param>
		/// <param name="value">值信息</param>
		public static void WriteUint64(MemoryStream ms, ulong value)
		{
			WriteAutoLength(ms, GetLongLength(value), value);
		}

		/// <summary>
		/// 从缓存中获取动态长度的uint类型数据
		/// </summary>
		/// <param name="buffer">缓存值</param>
		/// <param name="index">索引信息</param>
		/// <param name="disableVlq">是否禁用可变长度编码</param>
		/// <returns>结果值</returns>
		public static uint GetValueUint32(byte[] buffer, ref int index, bool disableVlq = false)
		{
			if (disableVlq)
			{
				uint num = 0u;
				for (int i = 0; i < 4; i++)
				{
					num <<= 8;
					num += buffer[index + i];
				}
				index += 4;
				return num;
			}
			int num2 = 0;
			int num3 = 0;
			for (int j = 0; j < 5; j++)
			{
				num3++;
				num2 <<= 7;
				num2 += (byte)(buffer[index + j] & 0x7F);
				if (!buffer[index + j].GetBoolByIndex(7))
				{
					break;
				}
			}
			index += num3;
			return (uint)num2;
		}

		/// <summary>
		/// 从缓存中获取动态长度的ulong类型数据
		/// </summary>
		/// <param name="buffer">缓存值</param>
		/// <param name="index">索引信息</param>
		/// <param name="disableVlq">是否禁用可变长度编码</param>
		/// <returns>结果值</returns>
		public static ulong GetValueUint64(byte[] buffer, ref int index, bool disableVlq = false)
		{
			if (disableVlq)
			{
				ulong num = 0uL;
				for (int i = 0; i < 8; i++)
				{
					num <<= 8;
					num += buffer[index + i];
				}
				index += 8;
				return num;
			}
			ulong num2 = 0uL;
			int num3 = 0;
			for (int j = 0; j < 9; j++)
			{
				num3++;
				if (j == 8)
				{
					num2 <<= 8;
					num2 += buffer[index + j];
					continue;
				}
				num2 <<= 7;
				num2 += (byte)(buffer[index + j] & 0x7F);
				if (!buffer[index + j].GetBoolByIndex(7))
				{
					break;
				}
			}
			index += num3;
			return num2;
		}
	}
	/// <summary>
	/// 节点类对象
	/// </summary>
	public class S7Tag : IS7Object
	{
		/// <summary>
		/// 数据名称
		/// </summary>
		public string Name { get; set; }

		/// <summary>
		/// 数据ID信息，第一个为DB块的信息，第二个是数据信息，如果是结构体，则继续往后面拓展
		/// </summary>
		public List<uint> LID { get; set; }

		/// <summary>
		/// 类型代号
		/// </summary>
		public byte TypeCode { get; set; }

		/// <summary>
		/// 数组长度，如果小于0则表示标量的数据
		/// </summary>
		public int ArrayLength { get; set; } = -1;

		/// <summary>
		/// 当类型为结构体的时候，关联的其他结构体的ID信息
		/// </summary>
		public uint StructID { get; set; }

		/// <summary>
		/// 当类型为结构体的时候，标签的偏移信息
		/// </summary>
		public int StructOffset { get; set; }

		/// <summary>
		/// 用户自定义的标签信息，可以用来存储一些额外的信息，方便用户使用
		/// </summary>
		public string Tag { get; set; }

		/// <summary>
		/// 获取类型的文本描述
		/// </summary>
		/// <returns>string info</returns>
		public string GetTypeText()
		{
			string text = null;
			text = TypeCode switch
			{
				0 => "Void", 
				1 => "Bool", 
				2 => "Byte", 
				3 => "Char", 
				4 => "Word(ushort)", 
				5 => "Int(short)", 
				6 => "DWord(uint)", 
				7 => "DInt(int)", 
				8 => "Real(float)", 
				9 => "Date", 
				10 => "TimeOfDay", 
				11 => "Time", 
				12 => "S5Time", 
				13 => "S5Count", 
				14 => "DateAndTime", 
				15 => "InteretTime", 
				16 => "Array", 
				17 => "Struct", 
				18 => "EndStruct", 
				19 => "String", 
				20 => "Pointer", 
				21 => "Multi_FB", 
				22 => "Any", 
				23 => "Block_FB", 
				24 => "Block_FC", 
				25 => "Block_DB", 
				26 => "Block_SDB", 
				27 => "Multi_SFB", 
				28 => "Counter", 
				29 => "Timer", 
				30 => "IEC_COUNTER", 
				31 => "IEC_TIMER", 
				32 => "Block_SFB", 
				33 => "Block_SFC", 
				34 => "Block_CB", 
				35 => "Block_SCB", 
				36 => "Block_OB", 
				37 => "Block_UDT", 
				38 => "Offset", 
				39 => "Block_SDT", 
				40 => "BBOOL", 
				41 => "BLOCK_EXT", 
				48 => "LReal(double)", 
				49 => "ULInt(ulong)", 
				50 => "LInt(long)", 
				51 => "LWord(ulong)", 
				52 => "USInt", 
				53 => "UInt(ushort)", 
				54 => "UDInt(uint)", 
				55 => "SInt(sbyte)", 
				56 => "Bcd8", 
				57 => "Bcd16", 
				58 => "Bcd32", 
				59 => "Bcd64", 
				60 => "ARef", 
				61 => "WChar", 
				62 => "WString", 
				63 => "Variant", 
				64 => "LTime", 
				65 => "LTOD", 
				66 => "LDT", 
				67 => "DTL", 
				68 => "IEC_LTIMER", 
				97 => "Error_Struct", 
				144 => "HW_ANY", 
				145 => "HW_IOSYSTEM", 
				149 => "HW_IO", 
				170 => "CONN_OUC", 
				254 => "Label", 
				byte.MaxValue => "Undefined", 
				_ => $"Unknown({TypeCode})", 
			};
			if (ArrayLength < 0)
			{
				return text;
			}
			return $"{text}[{ArrayLength}]";
		}

		/// <summary>
		/// 获取LID的文本信息
		/// </summary>
		/// <returns></returns>
		public string GetLIDText()
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (LID != null)
			{
				for (int i = 0; i < LID.Count; i++)
				{
					stringBuilder.Append(LID[i].ToString("X"));
					if (i != LID.Count - 1)
					{
						stringBuilder.Append(".");
					}
				}
			}
			return stringBuilder.ToString();
		}

		/// <summary>
		/// 获取LID的文本信息
		/// </summary>
		/// <param name="relationId">关联的ID信息</param>
		/// <returns>地址文本</returns>
		public string GetLIDText(uint relationId)
		{
			StringBuilder stringBuilder = new StringBuilder(relationId.ToString("X"));
			stringBuilder.Append(".");
			if (LID != null)
			{
				for (int i = 0; i < LID.Count; i++)
				{
					stringBuilder.Append(LID[i].ToString("X"));
					if (i != LID.Count - 1)
					{
						stringBuilder.Append(".");
					}
				}
			}
			return stringBuilder.ToString();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.S7PlusHelper.IS7Object.WriteMessgae(System.IO.MemoryStream)" />
		public void WriteMessgae(MemoryStream ms)
		{
			S7Object.WriteUint32(ms, 0u);
			S7Object.WriteUint32(ms, LID[0]);
			S7Object.WriteUint32(ms, (uint)LID.Count);
			if (LID[0] >= 2316173312u)
			{
				S7Object.WriteUint32(ms, 2550u);
			}
			else
			{
				S7Object.WriteUint32(ms, 3736u);
			}
			for (int i = 1; i < LID.Count; i++)
			{
				S7Object.WriteUint32(ms, LID[i]);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.S7PlusHelper.IS7Object.GetNumberOfFields" />
		public int GetNumberOfFields()
		{
			return 3 + LID.Count;
		}

		/// <summary>
		/// 深度克隆一个对象
		/// </summary>
		/// <returns></returns>
		public S7Tag Clone()
		{
			S7Tag s7Tag = new S7Tag();
			s7Tag.Name = Name;
			if (LID != null)
			{
				s7Tag.LID = new List<uint>(LID.ToArray());
			}
			s7Tag.TypeCode = TypeCode;
			s7Tag.ArrayLength = ArrayLength;
			s7Tag.StructID = StructID;
			s7Tag.StructOffset = StructOffset;
			s7Tag.Tag = Tag;
			return s7Tag;
		}
	}
	/// <summary>
	/// S7对象的类，表示一个对象信息
	/// </summary>
	public class S7Value
	{
		/// <summary>
		/// 类型代号
		/// </summary>
		public byte TypeCode { get; set; }

		/// <summary>
		/// 内存数据
		/// </summary>
		public byte[] Buffer { get; set; }

		/// <summary>
		/// 值对象
		/// </summary>
		public object Value { get; set; }

		/// <summary>
		/// 标记信息
		/// </summary>
		public byte Flag { get; set; }

		/// <summary>
		/// 关联的结构体的标识信息
		/// </summary>
		public uint StructID { get; set; }

		internal static byte[] GetBufferBool(IByteTransform byteTransform, bool value)
		{
			byte[] array = new byte[3] { 0, 1, 0 };
			if (value)
			{
				array[2] = 1;
			}
			else
			{
				array[2] = 0;
			}
			return array;
		}

		internal static byte[] GetBufferInt8(IByteTransform byteTransform, sbyte value)
		{
			return new byte[3]
			{
				0,
				6,
				(byte)value
			};
		}

		internal static byte[] GetBufferUInt8(IByteTransform byteTransform, byte value)
		{
			return new byte[3] { 0, 10, value };
		}

		internal static byte[] GetBufferUInt8(IByteTransform byteTransform, byte[] value)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(16);
			memoryStream.WriteByte(10);
			S7Object.WriteUint32(memoryStream, (uint)value.Length);
			memoryStream.Write(value);
			return memoryStream.ToArray();
		}

		internal static byte[] GetBufferInt16(IByteTransform byteTransform, short value)
		{
			byte[] array = new byte[4] { 0, 7, 0, 0 };
			byteTransform.TransByte(value).CopyTo(array, 2);
			return array;
		}

		internal static byte[] GetBufferInt16(IByteTransform byteTransform, short[] value)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(16);
			memoryStream.WriteByte(7);
			S7Object.WriteUint32(memoryStream, (uint)value.Length);
			memoryStream.Write(byteTransform.TransByte(value));
			return memoryStream.ToArray();
		}

