		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.NetMessageBase.CheckReceiveDataComplete(System.Byte[],System.IO.MemoryStream)" />
		public static bool CheckReceiveDataComplete(MemoryStream ms)
		{
			byte[] array = ms.ToArray();
			if (array.Length == 0)
			{
				return false;
			}
			if (array.Length == 1 && array[0] == 229)
			{
				return true;
			}
			if (array.Length > 6 && array[0] == 104 && array[1] + 6 == array.Length && array[^1] == 22)
			{
				return true;
			}
			if (array.Length > 6 && array[0] == 3 && array[3] == array.Length)
			{
				return true;
			}
			return false;
		}

		/// <summary>
		/// 检查西门子PLC的返回的数据和合法性，对反馈的数据进行初步的校验
		/// </summary>
		/// <param name="content">服务器返回的原始的数据内容</param>
		/// <returns>是否校验成功</returns>
		public static OResult CheckResponse(byte[] content)
		{
			if (content.Length < 21)
			{
				return new OResult(10000, "Failed, data too short:" + SoftBasic.ByteToHexString(content, ' '));
			}
			if (content[17] != 0 || content[18] != 0)
			{
				return new OResult(content[19], GetMsgFromStatus(content[18], content[19]));
			}
			if (content.Length < 22)
			{
				return new OResult(10000, "Failed, data too short:" + SoftBasic.ByteToHexString(content, ' '));
			}
			if (content[21] != byte.MaxValue)
			{
				return new OResult(content[21], GetMsgFromStatus(content[21]));
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 根据站号信息获取命令二次确认的报文信息
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <returns>二次命令确认的报文</returns>
		public static byte[] GetExecuteConfirm(byte station)
		{
			byte[] array = new byte[6] { 16, 2, 0, 92, 94, 22 };
			array[1] = station;
			int num = 0;
			for (int i = 1; i < 4; i++)
			{
				num += array[i];
			}
			array[4] = (byte)num;
			return array;
		}

		private static OResult<byte[]> Read(IReadWriteDevice plc, S7AddressData address, ushort length, byte station, object communicationLock)
		{
			OResult<byte[]> oResult = BuildReadCommand(station, address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			lock (communicationLock)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				if (oResult2.Content == null || oResult2.Content.Length == 0 || oResult2.Content[0] != 229)
				{
					return new OResult<byte[]>("PLC Receive Check Failed:" + SoftBasic.ByteToHexString(oResult2.Content, ' '));
				}
				OResult<byte[]> oResult3 = plc.ReadFromCoreServer(GetExecuteConfirm(station));
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				OResult oResult4 = CheckResponse(oResult3.Content);
				if (!oResult4.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult4);
				}
				return SiemensS7Helper.AnalysisReadByte(oResult3.Content);
			}
		}

		/// <summary>
		/// 从西门子的PLC中读取数据信息，地址为"M100","AI100","I0","Q0","V100","S100"等<br />
		/// Read data information from Siemens PLC with addresses "M100", "AI100", "I0", "Q0", "V100", "S100", etc.
		/// </summary>
		/// <param name="plc">PLC的通信对象</param>
		/// <param name="address">西门子的地址数据信息</param>
		/// <param name="length">数据长度</param>
		/// <param name="station">当前的站号信息</param>
		/// <param name="communicationLock">当前的同通信锁</param>
		/// <returns>带返回结果的结果对象</returns>
		public static OResult<byte[]> Read(IReadWriteDevice plc, string address, ushort length, byte station, object communicationLock)
		{
			byte station2 = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<S7AddressData> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return Read(plc, oResult.Content, length, station2, communicationLock);
		}

		/// <summary>
		/// 从西门子的PLC中读取bool数据信息，地址为"M100.0","AI100.1","I0.3","Q0.6","V100.4","S100"等<br />
		/// Read bool data information from Siemens PLC, the addresses are "M100.0", "AI100.1", "I0.3", "Q0.6", "V100.4", "S100", etc.
		/// </summary>
		/// <param name="plc">PLC的通信对象</param>
		/// <param name="address">西门子的地址数据信息</param>
		/// <param name="station">当前的站号信息</param>
		/// <param name="communicationLock">当前的同通信锁</param>
		/// <returns>带返回结果的结果对象</returns>
		public static OResult<bool> ReadBool(IReadWriteDevice plc, string address, byte station, object communicationLock)
		{
			byte station2 = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<byte[]> oResult = BuildReadCommand(station2, address, 1, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			lock (communicationLock)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool>(oResult2);
				}
				if (oResult2.Content == null || oResult2.Content.Length == 0 || oResult2.Content[0] != 229)
				{
					return new OResult<bool>("PLC Receive Check Failed:" + SoftBasic.ByteToHexString(oResult2.Content, ' '));
				}
				OResult<byte[]> oResult3 = plc.ReadFromCoreServer(GetExecuteConfirm(station2));
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool>(oResult3);
				}
				OResult oResult4 = CheckResponse(oResult3.Content);
				if (!oResult4.IsSuccess)
				{
					return OResult.CreateFailedResult<bool>(oResult4);
				}
				OResult<byte[]> oResult5 = SiemensS7Helper.AnalysisReadBit(oResult3.Content);
				if (!oResult5.IsSuccess)
				{
					return OResult.CreateFailedResult<bool>(oResult5);
				}
				return OResult.CreateSuccessResult(oResult5.Content.ToBoolArray()[0]);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensPPIHelper.ReadBool(Snet.Driver.Core.IReadWriteDevice,System.String,System.Byte,System.Object)" />
		public static OResult<bool[]> ReadBool(IReadWriteDevice plc, string address, ushort length, byte station, object communicationLock)
		{
			byte station2 = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<S7AddressData> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			SnetHelper.CalculateStartBitIndexAndLength(oResult.Content.AddressStart, length, out var newStart, out var byteLength, out var offset);
			oResult.Content.AddressStart = newStart;
			oResult.Content.Length = byteLength;
			OResult<byte[]> oResult2 = Read(plc, oResult.Content, oResult.Content.Length, station2, communicationLock);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectMiddle(offset, length));
		}

