		/// <summary>
		/// 读取西门子PLC的型号信息，参数信息可以携带站号信息 "s=2;", 注意，分号是必须的。<br />
		/// Read the model information of Siemens PLC, the parameter information can carry the station number information "s=2;", note that the semicolon is required.
		/// </summary>
		/// <param name="plc">PLC的通信对象</param>
		/// <param name="parameter">额外的参数信息，例如可以携带站号信息 "s=2;", 注意，分号是必须的。</param>
		/// <param name="station">当前的站号信息</param>
		/// <param name="communicationLock">当前的同通信锁</param>
		/// <returns>包含是否成功的结果对象</returns>
		public static OResult<string> ReadPlcType(IReadWriteDevice plc, string parameter, byte station, object communicationLock)
		{
			byte station2 = (byte)SnetHelper.ExtractParameter(ref parameter, "s", station);
			OResult<byte[]> oResult = BuildReadCommand(station2, "SYS0", 20, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			lock (communicationLock)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult2);
				}
				if (oResult2.Content == null || oResult2.Content.Length == 0 || oResult2.Content[0] != 229)
				{
					return new OResult<string>("PLC Receive Check Failed:" + SoftBasic.ByteToHexString(oResult2.Content, ' '));
				}
				OResult<byte[]> oResult3 = plc.ReadFromCoreServer(GetExecuteConfirm(station2));
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult3);
				}
				try
				{
					byte[] array = new byte[20];
					if (oResult3.Content[21] == byte.MaxValue && oResult3.Content[22] == 4)
					{
						Array.Copy(oResult3.Content, 25, array, 0, 20);
					}
					return OResult.CreateSuccessResult(Encoding.ASCII.GetString(array));
				}
				catch (Exception ex)
				{
					return new OResult<string>("Get plc type failed: " + ex.Message + Environment.NewLine + "Content: " + oResult3.Content.ToHexString(' '));
				}
			}
		}
	}
	internal class SiemensS7Helper
	{
		/// <summary>
		/// 读取BOOL时，根据S7协议的返回报文，正确提取出实际的数据内容
		/// </summary>
		/// <param name="content">PLC返回的原始字节信息</param>
		/// <returns>解析之后的结果对象</returns>
		internal static OResult<byte[]> AnalysisReadBit(byte[] content)
		{
			try
			{
				int num = 1;
				if (content.Length >= 21 && content[20] == 1)
				{
					byte[] array = new byte[num];
					if (22 < content.Length)
					{
						if (content[21] != byte.MaxValue || content[22] != 3)
						{
							if (content[21] == 5 && content[22] == 0)
							{
								return new OResult<byte[]>(content[21], StringResources.Language.SiemensReadLengthOverPlcAssign);
							}
							if (content[21] == 6 && content[22] == 0)
							{
								return new OResult<byte[]>(content[21], StringResources.Language.SiemensError0006);
							}
							if (content[21] == 10 && content[22] == 0)
							{
								return new OResult<byte[]>(content[21], StringResources.Language.SiemensError000A);
							}
							return new OResult<byte[]>(content[21], StringResources.Language.UnknownError + " Source: " + content.ToHexString(' '));
						}
						array[0] = content[25];
					}
					return OResult.CreateSuccessResult(array);
				}
				return new OResult<byte[]>(StringResources.Language.SiemensDataLengthCheckFailed);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("AnalysisReadBit failed: " + ex.Message + Environment.NewLine + " Msg:" + SoftBasic.ByteToHexString(content, ' '));
			}
		}

		internal static List<S7AddressData[]> ArraySplitByLength(S7AddressData[] s7Addresses, int pduLength)
		{
			List<S7AddressData[]> list = new List<S7AddressData[]>();
			List<S7AddressData> list2 = new List<S7AddressData>();
			int num = 0;
			for (int i = 0; i < s7Addresses.Length; i++)
			{
				if (list2.Count >= 19 || num + s7Addresses[i].Length + list2.Count * 4 >= pduLength)
				{
					if (list2.Count > 0)
					{
						list.Add(list2.ToArray());
						list2.Clear();
					}
					num = 0;
				}
				list2.Add(s7Addresses[i]);
				num += s7Addresses[i].Length;
			}
			if (list2.Count > 0)
			{
				list.Add(list2.ToArray());
			}
			return list;
		}

		internal static S7AddressData[] SplitS7Address(S7AddressData s7Address, int pduLength)
		{
			List<S7AddressData> list = new List<S7AddressData>();
			int i = 0;
			ushort num;
			for (int length = s7Address.Length; i < length; i += num)
			{
				num = (ushort)Math.Min(length - i, pduLength);
				S7AddressData s7AddressData = new S7AddressData(s7Address);
				if (s7Address.DataCode == 31 || s7Address.DataCode == 30)
				{
					s7AddressData.AddressStart = s7Address.AddressStart + i / 2;
				}
				else
				{
					s7AddressData.AddressStart = s7Address.AddressStart + i * 8;
				}
				s7AddressData.Length = num;
				list.Add(s7AddressData);
			}
			return list.ToArray();
		}

		/// <summary>
		/// 读取字数据时，根据S7协议返回的报文，解析出实际的原始字节数组信息
		/// </summary>
		/// <param name="content">PLC返回的原始字节数组</param>
		/// <returns>实际的结果数据对象</returns>
		internal static OResult<byte[]> AnalysisReadByte(byte[] content)
		{
			try
			{
				List<byte> list = new List<byte>();
				if (content.Length >= 21)
				{
					for (int i = 21; i < content.Length - 1; i++)
					{
						if (content[i] == byte.MaxValue && content[i + 1] == 4)
						{
							int num = (content[i + 2] * 256 + content[i + 3]) / 8;
							list.AddRange(content.SelectMiddle(i + 4, num));
							i += num + 3;
						}
						else if (content[i] == byte.MaxValue && content[i + 1] == 9)
						{
							int num2 = content[i + 2] * 256 + content[i + 3];
							if (num2 % 3 == 0)
							{
								for (int j = 0; j < num2 / 3; j++)
								{
									list.AddRange(content.SelectMiddle(i + 5 + 3 * j, 2));
								}
							}
							else
							{
								for (int k = 0; k < num2 / 5; k++)
								{
									list.AddRange(content.SelectMiddle(i + 7 + 5 * k, 2));
								}
							}
							i += num2 + 4;
						}
						else
						{
							if (content[i] == 5 && content[i + 1] == 0)
							{
								return new OResult<byte[]>(content[i], StringResources.Language.SiemensReadLengthOverPlcAssign);
							}
							if (content[i] == 6 && content[i + 1] == 0)
							{
								return new OResult<byte[]>(content[i], StringResources.Language.SiemensError0006);
							}
							if (content[i] == 10 && content[i + 1] == 0)
							{
								return new OResult<byte[]>(content[i], StringResources.Language.SiemensError000A);
							}
						}
					}
					return OResult.CreateSuccessResult(list.ToArray());
				}
				return new OResult<byte[]>(StringResources.Language.SiemensDataLengthCheckFailed + " Msg: " + SoftBasic.ByteToHexString(content, ' '));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("AnalysisReadByte failed: " + ex.Message + Environment.NewLine + " Msg:" + SoftBasic.ByteToHexString(content, ' '));
			}
		}

		internal static string AnalysisAddressLogMessage(PipeSession pipeSession, IByteTransform byteTransform, byte[] content)
		{
			if (content.Length >= 31 && (content[17] == 4 || content[17] == 5))
			{
				ushort value = byteTransform.TransUInt16(content, 25);
				byte b = content[27];
				int num = content[28] * 65536 + content[29] * 256 + content[30];
				StringBuilder stringBuilder = new StringBuilder();
				if (content[22] == 1)
				{
					stringBuilder.Append((content[17] == 4) ? " --- ReadBool( \"" : " --- Write( \"");
				}
				else
				{
					stringBuilder.Append((content[17] == 4) ? " --- Read( \"" : " --- Write( \"");
				}
				switch (b)
				{
				case 5:
					stringBuilder.Append("SM");
					break;
				case 6:
					stringBuilder.Append("AI");
					break;
				case 7:
					stringBuilder.Append("AQ");
					break;
				case 128:
					stringBuilder.Append("P");
					break;
				case 129:
					stringBuilder.Append("I");
					break;
				case 130:
					stringBuilder.Append("Q");
					break;
				case 131:
					stringBuilder.Append("M");
					break;
				case 132:
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder3 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(3, 1, stringBuilder2);
					handler.AppendLiteral("DB");
					handler.AppendFormatted(value);
					handler.AppendLiteral(".");
					stringBuilder3.Append(ref handler);
					break;
				}
				case 31:
					stringBuilder.Append("T");
					break;
				case 30:
					stringBuilder.Append("C");
					break;
				default:
					stringBuilder.Append("");
					break;
				}
				stringBuilder.Append((num / 8).ToString());
				if (num % 8 != 0)
				{
					stringBuilder.Append(".");
					stringBuilder.Append((num % 8).ToString());
				}
				stringBuilder.Append("\", ");
				ushort value2 = byteTransform.TransUInt16(content, 23);
				if (content[17] == 4)
				{
					stringBuilder.Append(value2);
				}
				else if (content[22] == 1)
				{
					if (content.Length >= 36)
					{
						stringBuilder.Append((content[35] != 0) ? "true" : "false");
					}
				}
				else
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder4 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(10, 1, stringBuilder2);
					handler.AppendLiteral("new byte[");
					handler.AppendFormatted(value2);
					handler.AppendLiteral("]");
					stringBuilder4.Append(ref handler);
				}
				stringBuilder.Append(" )");
				return stringBuilder.ToString();
			}
			return string.Empty;
		}

		/// <summary>
		/// 读取西门子的地址的字符串信息，这个信息是和西门子绑定在一起，长度随西门子的信息动态变化的<br />
		/// Read the Siemens address string information. This information is bound to Siemens and its length changes dynamically with the Siemens information
		/// </summary>
		/// <remarks>
		/// 如果指定编码，一般<see cref="P:System.Text.Encoding.ASCII" />即可，中文需要 Encoding.GetEncoding("gb2312")
		/// </remarks>
		/// <param name="plc">PLC的通信对象</param>
		/// <param name="currentPlc">PLC的系列信息</param>
		/// <param name="address">数据地址，具体的格式需要参照类的说明文档</param>
		/// <param name="encoding">自定的编码信息，一般<see cref="P:System.Text.Encoding.ASCII" />即可，中文需要 Encoding.GetEncoding("gb2312")</param>
		/// <returns>带有是否成功的字符串结果类对象</returns>
		public static OResult<string> ReadString(IReadWriteNet plc, SiemensPLCS currentPlc, string address, Encoding encoding)
		{
			if (currentPlc != SiemensPLCS.S200Smart)
			{
				OResult<byte[]> oResult = plc.Read(address, 2);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult);
				}
				if (oResult.Content[0] == 0 || oResult.Content[0] == byte.MaxValue)
				{
					return new OResult<string>("Value in plc is not string type");
				}
				OResult<byte[]> oResult2 = plc.Read(address, (ushort)(2 + oResult.Content[1]));
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult2);
				}
				return OResult.CreateSuccessResult(encoding.GetString(oResult2.Content, 2, oResult2.Content.Length - 2));
			}
			OResult<byte[]> oResult3 = plc.Read(address, 1);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			OResult<byte[]> oResult4 = plc.Read(address, (ushort)(1 + oResult3.Content[0]));
			if (!oResult4.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult4);
			}
			return OResult.CreateSuccessResult(encoding.GetString(oResult4.Content, 1, oResult4.Content.Length - 1));
		}

		/// <summary>
		/// 将指定的字符串写入到西门子PLC里面去，将自动添加字符串长度信息，方便PLC识别字符串的内容。<br />
		/// Write the specified string into Siemens PLC, and the string length information will be automatically added, which is convenient for PLC to identify the content of the string.
		/// </summary>
		/// <param name="plc">PLC的通信对象</param>
		/// <param name="currentPlc">PLC的系列信息</param>
		/// <param name="address">数据地址，具体的格式需要参照类的说明文档</param>
		/// <param name="value">写入的字符串值</param>
		/// <param name="encoding">编码信息</param>
		/// <returns>是否写入成功</returns>
		public static OResult Write(IReadWriteNet plc, SiemensPLCS currentPlc, string address, string value, Encoding encoding)
		{
			if (value == null)
			{
				value = string.Empty;
			}
			byte[] array = encoding.GetBytes(value);
			if (encoding == Encoding.Unicode)
			{
				array = SoftBasic.BytesReverseByWord(array);
			}
			if (currentPlc != SiemensPLCS.S200Smart)
			{
				OResult<byte[]> oResult = plc.Read(address, 2);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				if (oResult.Content[0] == byte.MaxValue)
				{
					return new OResult<string>("Value in plc is not string type");
				}
				if (oResult.Content[0] == 0)
				{
					oResult.Content[0] = 254;
				}
				if (array.Length > oResult.Content[0])
				{
					return new OResult<string>("String length is too long than plc defined");
				}
				return plc.Write(address, SoftBasic.SpliceArray<byte>(new byte[2]
				{
					oResult.Content[0],
					(byte)array.Length
				}, array));
			}
			return plc.Write(address, SoftBasic.SpliceArray<byte>(new byte[1] { (byte)array.Length }, array));
		}

		/// <summary>
		/// 读取西门子的地址的字符串信息，这个信息是和西门子绑定在一起，长度随西门子的信息动态变化的<br />
		/// Read the Siemens address string information. This information is bound to Siemens and its length changes dynamically with the Siemens information
		/// </summary>
		/// <param name="plc">PLC的通信对象</param>
		/// <param name="currentPlc">PLC的系列信息</param>
		/// <param name="address">数据地址，具体的格式需要参照类的说明文档</param>
		/// <returns>带有是否成功的字符串结果类对象</returns>
		public static OResult<string> ReadWString(IReadWriteNet plc, SiemensPLCS currentPlc, string address)
		{
			if (currentPlc != SiemensPLCS.S200Smart)
			{
				OResult<byte[]> oResult = plc.Read(address, 4);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult);
				}
				OResult<byte[]> oResult2 = plc.Read(address, (ushort)(4 + (oResult.Content[2] * 256 + oResult.Content[3]) * 2));
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult2);
				}
				return OResult.CreateSuccessResult(Encoding.Unicode.GetString(SoftBasic.BytesReverseByWord(oResult2.Content.RemoveBegin(4))));
			}
			OResult<byte[]> oResult3 = plc.Read(address, 1);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			OResult<byte[]> oResult4 = plc.Read(address, (ushort)(1 + oResult3.Content[0] * 2));
			if (!oResult4.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult4);
			}
			return OResult.CreateSuccessResult(Encoding.Unicode.GetString(oResult4.Content, 1, oResult4.Content.Length - 1));
		}

		/// <summary>
		/// 使用双字节编码的方式，将字符串以 Unicode 编码写入到PLC的地址里，可以使用中文。<br />
		/// Use the double-byte encoding method to write the character string to the address of the PLC in Unicode encoding. Chinese can be used.
		/// </summary>
		/// <param name="plc">PLC的通信对象</param>
		/// <param name="currentPlc">PLC的系列信息</param>
		/// <param name="address">起始地址，格式为I100，M100，Q100，DB20.100 -&gt; Starting address, formatted as I100,mM100,Q100,DB20.100</param>
		/// <param name="value">字符串的值</param>
		/// <returns>是否写入成功的结果对象</returns>
		public static OResult WriteWString(IReadWriteNet plc, SiemensPLCS currentPlc, string address, string value)
		{
			if (currentPlc != SiemensPLCS.S200Smart)
			{
				if (value == null)
				{
					value = string.Empty;
				}
				byte[] array = Encoding.Unicode.GetBytes(value).ReverseByWord();
				OResult<byte[]> oResult = plc.Read(address, 4);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				int num = oResult.Content[0] * 256 + oResult.Content[1];
				if (num == 0)
				{
					num = 254;
					oResult.Content[1] = 254;
				}
				if (value.Length > num)
				{
					return new OResult<string>("String length is too long than plc defined");
				}
				byte[] array2 = new byte[array.Length + 4];
				array2[0] = oResult.Content[0];
				array2[1] = oResult.Content[1];
				array2[2] = BitConverter.GetBytes(value.Length)[1];
				array2[3] = BitConverter.GetBytes(value.Length)[0];
				array.CopyTo(array2, 4);
				return plc.Write(address, array2);
			}
			return plc.Write(address, value, Encoding.Unicode);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensS7Helper.ReadString(Snet.Driver.Core.IReadWriteNet,Snet.Driver.Profinet.Siemens.SiemensPLCS,System.String,System.Text.Encoding)" />
		public static async Task<OResult<string>> ReadStringAsync(IReadWriteNet plc, SiemensPLCS currentPlc, string address, Encoding encoding)
