					return OResult.CreateFailedResult<string>(oResult2);
				}
				return OResult.CreateSuccessResult(encoding.GetString(oResult2.Content, 2, oResult2.Content.Length - 2));
			}
			OResult<byte[]> oResult3 = await plc.ReadAsync(address, 1);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			OResult<byte[]> oResult4 = await plc.ReadAsync(address, (ushort)(1 + oResult3.Content[0]));
			if (!oResult4.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult4);
			}
			return OResult.CreateSuccessResult(encoding.GetString(oResult4.Content, 1, oResult4.Content.Length - 1));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensS7Helper.Write(Snet.Driver.Core.IReadWriteNet,Snet.Driver.Profinet.Siemens.SiemensPLCS,System.String,System.String,System.Text.Encoding)" />
		public static async Task<OResult> WriteAsync(IReadWriteNet plc, SiemensPLCS currentPlc, string address, string value, Encoding encoding)
		{
