		/// <inheritdoc cref="M:Snet.Driver.Profinet.Siemens.Helper.SiemensS7Helper.ReadWString(Snet.Driver.Core.IReadWriteNet,Snet.Driver.Profinet.Siemens.SiemensPLCS,System.String)" />
		public static async Task<OResult<string>> ReadWStringAsync(IReadWriteNet plc, SiemensPLCS currentPlc, string address)
		{
			if (currentPlc != SiemensPLCS.S200Smart)
