				}
				byte[] buffer = Encoding.Unicode.GetBytes(value);
				buffer = SoftBasic.BytesReverseByWord(buffer);
				OResult<byte[]> oResult = await plc.ReadAsync(address, 4);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				int num = oResult.Content[0] * 256 + oResult.Content[1];
				if (num == 0)
