namespace Snet.Driver.Profinet.Sick
{
	/// <summary>
	/// Sick的扫码器的服务器信息，只要启动服务器之后，扫码器配置将条码发送到PC的指定端口上来即可，就可以持续的接收条码信息，同样也适用于海康，基恩士，DATELOGIC 。<br />
	/// The server information of Sick's code scanner, as long as the server is started, the code scanner is configured to send the barcode to the designated port of the PC, and it can continuously receive the barcode information.
	/// </summary>
	public class SickIcrTcpServer : CommunicationServer
	{
		/// <summary>
		/// 接收条码数据的委托信息<br />
		/// Entrusted information to receive barcode data
		/// </summary>
		/// <param name="ipAddress">Ip地址信息</param>
		/// <param name="barCode">条码信息</param>
		public delegate void ReceivedBarCodeDelegate(string ipAddress, string barCode);

		/// <summary>
		/// 当接收到条码数据的时候触发<br />
		/// Triggered when barcode data is received
		/// </summary>
		public event ReceivedBarCodeDelegate OnReceivedBarCode;

		/// <summary>
		/// 实例化一个默认的服务器对象<br />
		/// Instantiate a default server object
		/// </summary>
		public SickIcrTcpServer()
		{
			base.OnPipeMessageReceived += SickIcrTcpServer_OnPipeMessageReceived;
		}

		private void SickIcrTcpServer_OnPipeMessageReceived(PipeSession session, byte[] buffer)
		{
			string ipAddress = string.Empty;
			if (session.Communication is PipeTcpNet pipeTcpNet)
			{
				ipAddress = pipeTcpNet.IpAddress;
			}
			if (session != null)
			{
				base.LogNet?.WriteDebug(ToString(), $"<{session.Communication}> Recv: " + buffer.ToHexString(' '));
			}
			OnReceivedBarCode?.Invoke(ipAddress, TranslateCode(Encoding.ASCII.GetString(buffer)));
		}

		private string TranslateCode(string code)
		{
			StringBuilder stringBuilder = new StringBuilder("");
			for (int i = 0; i < code.Length; i++)
			{
				if (char.IsLetterOrDigit(code, i))
				{
					stringBuilder.Append(code[i]);
				}
			}
			return stringBuilder.ToString();
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SickIcrTcpServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Panasonic
{
	/// <summary>
	/// 松下PLC的辅助类，提供了基本的辅助方法，用于解析地址，计算校验和，创建报文<br />
	/// The auxiliary class of Panasonic PLC provides basic auxiliary methods for parsing addresses, calculating checksums, and creating messages
	/// </summary>
	public class PanasonicHelper
	{
		private static string CalculateCrc(StringBuilder sb)
		{
			byte b = 0;
			b = (byte)sb[0];
			for (int i = 1; i < sb.Length; i++)
			{
				b ^= (byte)sb[i];
			}
			return SoftBasic.ByteToHexString(new byte[1] { b });
		}

		/// <summary>
		/// 位地址转换方法，101等同于10.1等同于10*16+1=161<br />
		/// Bit address conversion method, 101 is equivalent to 10.1 is equivalent to 10 * 16 + 1 = 161
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="fromBase">倍率信息</param>
		/// <returns>实际的位地址信息</returns>
		public static int CalculateComplexAddress(string address, int fromBase = 16)
		{
			if (address.IndexOf(".") < 0)
			{
				if (address.Length == 1)
				{
					return Convert.ToInt32(address, fromBase);
				}
				return Convert.ToInt32(address.Substring(0, address.Length - 1)) * fromBase + Convert.ToInt32(address.Substring(address.Length - 1), fromBase);
			}
			int num = Convert.ToInt32(address.Substring(0, address.IndexOf("."))) * fromBase;
			string bit = address.Substring(address.IndexOf(".") + 1);
			return num + SnetHelper.CalculateBitStartIndex(bit);
		}

		/// <summary>
		/// 解析数据地址，解析出地址类型，起始地址<br />
		/// Parse the data address, resolve the address type, start address
		/// </summary>
		/// <param name="address">数据地址</param>
		/// <returns>解析出地址类型，起始地址</returns>
		public static OResult<string, int> AnalysisAddress(string address)
		{
			OResult<string, int> oResult = new OResult<string, int>();
			try
			{
				oResult.Content2 = 0;
				if (address.StartsWith("IX", StringComparison.OrdinalIgnoreCase))
				{
					oResult.Content1 = "IX";
					oResult.Content2 = int.Parse(address.Substring(2));
				}
				else if (address.StartsWith("IY") || address.StartsWith("iy"))
				{
					oResult.Content1 = "IY";
					oResult.Content2 = int.Parse(address.Substring(2));
				}
				else if (address.StartsWith("ID") || address.StartsWith("id"))
				{
					oResult.Content1 = "ID";
					oResult.Content2 = int.Parse(address.Substring(2));
				}
				else if (address.StartsWith("SR") || address.StartsWith("sr"))
				{
					oResult.Content1 = "SR";
					oResult.Content2 = CalculateComplexAddress(address.Substring(2));
				}
				else if (address.StartsWith("LD") || address.StartsWith("ld"))
				{
					oResult.Content1 = "LD";
					oResult.Content2 = int.Parse(address.Substring(2));
				}
				else if (address.StartsWithAndNumber("DT"))
				{
					oResult.Content1 = "D";
					oResult.Content2 = int.Parse(address.Substring(2));
				}
				else if (address[0] == 'X' || address[0] == 'x')
				{
					oResult.Content1 = "X";
					oResult.Content2 = CalculateComplexAddress(address.Substring(1));
				}
				else if (address[0] == 'Y' || address[0] == 'y')
				{
					oResult.Content1 = "Y";
					oResult.Content2 = CalculateComplexAddress(address.Substring(1));
				}
				else if (address[0] == 'R' || address[0] == 'r')
				{
					oResult.Content1 = "R";
					oResult.Content2 = CalculateComplexAddress(address.Substring(1));
				}
				else if (address[0] == 'T' || address[0] == 't')
				{
					oResult.Content1 = "T";
					oResult.Content2 = int.Parse(address.Substring(1));
				}
				else if (address[0] == 'C' || address[0] == 'c')
				{
					oResult.Content1 = "C";
					oResult.Content2 = int.Parse(address.Substring(1));
				}
				else if (address[0] == 'L' || address[0] == 'l')
				{
					oResult.Content1 = "L";
					oResult.Content2 = CalculateComplexAddress(address.Substring(1));
				}
				else if (address[0] == 'D' || address[0] == 'd')
				{
					oResult.Content1 = "D";
					oResult.Content2 = int.Parse(address.Substring(1));
				}
				else if (address[0] == 'F' || address[0] == 'f')
				{
					oResult.Content1 = "F";
					oResult.Content2 = int.Parse(address.Substring(1));
				}
				else if (address[0] == 'S' || address[0] == 's')
				{
					oResult.Content1 = "S";
					oResult.Content2 = int.Parse(address.Substring(1));
				}
				else
				{
					if (address[0] != 'K' && address[0] != 'k')
					{
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
					oResult.Content1 = "K";
					oResult.Content2 = int.Parse(address.Substring(1));
				}
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
			oResult.IsSuccess = true;
			return oResult;
		}

		/// <summary>
		/// 将松下的命令打包成带有%开头，CRC校验，CR结尾的完整的命令报文。如果参数 <c>useExpandedHeader</c> 设置为 <c>Ture</c>，则命令头使用 &lt; 开头
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="cmd">松下的命令。例如 RCSR100F</param>
		/// <param name="useExpandedHeader">设置是否使用扩展的命令头消息</param>
		/// <returns>原始的字节数组的命令</returns>
		public static OResult<byte[]> PackPanasonicCommand(byte station, string cmd, bool useExpandedHeader)
		{
			StringBuilder stringBuilder = new StringBuilder(useExpandedHeader ? "<" : "%");
			stringBuilder.Append(station.ToString("X2"));
			stringBuilder.Append(cmd);
			stringBuilder.Append(CalculateCrc(stringBuilder));
			stringBuilder.Append('\r');
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		private static OResult AppendCoil(StringBuilder sb, string address)
		{
			OResult<string, int> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			sb.Append(oResult.Content1);
			if (oResult.Content1 == "X" || oResult.Content1 == "Y" || oResult.Content1 == "R" || oResult.Content1 == "L")
			{
				sb.Append((oResult.Content2 / 16).ToString("D3"));
				sb.Append((oResult.Content2 % 16).ToString("X1"));
			}
			else
			{
				if (!(oResult.Content1 == "T") && !(oResult.Content1 == "C"))
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
				}
				sb.Append("0");
				sb.Append(oResult.Content2.ToString("D3"));
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 创建读取离散触点的报文指令<br />
		/// Create message instructions for reading discrete contacts
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">地址信息</param>
		/// <returns>包含是否成功的结果对象</returns>
		public static OResult<byte[]> BuildReadOneCoil(byte station, string address)
		{
			if (address == null)
			{
				return new OResult<byte[]>("address is not allowed null");
			}
			if (address.Length < 1 || address.Length > 8)
			{
				return new OResult<byte[]>("length must be 1-8");
			}
			StringBuilder stringBuilder = new StringBuilder("#RCS");
			OResult oResult = AppendCoil(stringBuilder, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return PackPanasonicCommand(station, stringBuilder.ToString(), useExpandedHeader: false);
		}

		/// <summary>
		/// 创建读取多个bool值得报文命令
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">等待读取的地址数组</param>
		/// <returns>包含是否成功的结果对象</returns>
		public static OResult<List<byte[]>> BuildReadCoils(byte station, string[] address)
		{
			List<byte[]> list = new List<byte[]>();
			List<string[]> list2 = SoftBasic.ArraySplitByLength(address, 8);
			for (int i = 0; i < list2.Count; i++)
			{
				StringBuilder stringBuilder = new StringBuilder("#RCP");
				stringBuilder.Append(list2[i].Length.ToString());
				for (int j = 0; j < list2[i].Length; j++)
				{
					OResult oResult = AppendCoil(stringBuilder, list2[i][j]);
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<List<byte[]>>(oResult);
					}
				}
				list.Add(PackPanasonicCommand(station, stringBuilder.ToString(), useExpandedHeader: false).Content);
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 创建写入离散触点的报文指令<br />
		/// Create message instructions to write discrete contacts
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">地址信息</param>
		/// <param name="value">bool值数组</param>
		/// <returns>包含是否成功的结果对象</returns>
		public static OResult<byte[]> BuildWriteOneCoil(byte station, string address, bool value)
		{
			StringBuilder stringBuilder = new StringBuilder("#WCS");
			OResult oResult = AppendCoil(stringBuilder, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			stringBuilder.Append(value ? '1' : '0');
			return PackPanasonicCommand(station, stringBuilder.ToString(), useExpandedHeader: false);
		}

		/// <summary>
		/// 创建写入多个离散触点的报文指令
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">等待写入的地址列表</param>
		/// <param name="value">等待写入的值列表，长度应和地址长度一致</param>
		/// <returns>所有写入命令的报文列表</returns>
		public static OResult<List<byte[]>> BuildWriteCoils(byte station, string[] address, bool[] value)
		{
			if (address == null)
			{
				return new OResult<List<byte[]>>("Parameter address can't be null");
			}
			if (value == null)
			{
				return new OResult<List<byte[]>>("Parameter value can't be null");
			}
			if (address.Length != value.Length)
			{
				return new OResult<List<byte[]>>("Parameter address and parameter value, length is not same!");
			}
			List<byte[]> list = new List<byte[]>();
			List<string[]> list2 = SoftBasic.ArraySplitByLength(address, 8);
			List<bool[]> list3 = SoftBasic.ArraySplitByLength(value, 8);
			for (int i = 0; i < list2.Count; i++)
			{
				StringBuilder stringBuilder = new StringBuilder("#WCP");
				stringBuilder.Append(list2[i].Length.ToString());
				for (int j = 0; j < list2[i].Length; j++)
				{
					OResult oResult = AppendCoil(stringBuilder, list2[i][j]);
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<List<byte[]>>(oResult);
					}
					stringBuilder.Append(list3[i][j] ? '1' : '0');
				}
				list.Add(PackPanasonicCommand(station, stringBuilder.ToString(), useExpandedHeader: false).Content);
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 创建批量读取触点的报文指令<br />
		/// Create message instructions for batch reading contacts
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <param name="isBit">是否进行位为单位</param>
		/// <returns>包含是否成功的结果对象</returns>
		public static OResult<List<byte[]>> BuildReadCommand(byte station, string address, ushort length, bool isBit)
		{
			if (address == null)
			{
				return new OResult<List<byte[]>>(StringResources.Language.PanasonicAddressParameterCannotBeNull);
			}
			OResult<string, int> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			List<byte[]> list = new List<byte[]>();
			int[] array;
			if (isBit)
			{
				length += (ushort)(oResult.Content2 % 16);
				oResult.Content2 -= oResult.Content2 % 16;
				array = SoftBasic.SplitIntegerToArray(length, 400);
				foreach (int num in array)
				{
					StringBuilder stringBuilder = new StringBuilder("#");
					if (oResult.Content1 == "X" || oResult.Content1 == "Y" || oResult.Content1 == "R" || oResult.Content1 == "L")
					{
						stringBuilder.Append("RCC");
						stringBuilder.Append(oResult.Content1);
						int num2 = oResult.Content2 / 16;
						int num3 = (oResult.Content2 + num - 1) / 16;
						stringBuilder.Append(num2.ToString("D4"));
						stringBuilder.Append(num3.ToString("D4"));
						oResult.Content2 += num;
						list.Add(PackPanasonicCommand(station, stringBuilder.ToString(), useExpandedHeader: false).Content);
						continue;
					}
					return new OResult<List<byte[]>>("Bit read only support X,Y,R,L");
				}
				return OResult.CreateSuccessResult(list);
			}
			array = SoftBasic.SplitIntegerToArray(length, 500);
			foreach (int num4 in array)
			{
				StringBuilder stringBuilder2 = new StringBuilder("#");
				if (oResult.Content1 == "X" || oResult.Content1 == "Y" || oResult.Content1 == "R" || oResult.Content1 == "L")
				{
					stringBuilder2.Append("RCC");
					stringBuilder2.Append(oResult.Content1);
					if (oResult.Content2 % 16 != 0)
					{
						return new OResult<List<byte[]>>(StringResources.Language.PanasonicAddressBitStartMulti16);
					}
					int num5 = oResult.Content2 / 16;
					int num6 = (oResult.Content2 + (num4 - 1) * 16) / 16;
					stringBuilder2.Append(num5.ToString("D4"));
					stringBuilder2.Append(num6.ToString("D4"));
					oResult.Content2 += num4 * 16;
				}
				else if (oResult.Content1 == "D" || oResult.Content1 == "LD" || oResult.Content1 == "F")
				{
					stringBuilder2.Append("RD");
					stringBuilder2.Append(oResult.Content1.Substring(0, 1));
					stringBuilder2.Append(oResult.Content2.ToString("D5"));
					stringBuilder2.Append((oResult.Content2 + num4 - 1).ToString("D5"));
					oResult.Content2 += num4;
				}
				else if (oResult.Content1 == "IX" || oResult.Content1 == "IY" || oResult.Content1 == "ID")
				{
					stringBuilder2.Append("RD");
					stringBuilder2.Append(oResult.Content1);
					stringBuilder2.Append("000000000");
					oResult.Content2 += num4;
				}
				else if (oResult.Content1 == "C" || oResult.Content1 == "T")
				{
					stringBuilder2.Append("RS");
					stringBuilder2.Append(oResult.Content2.ToString("D4"));
					stringBuilder2.Append((oResult.Content2 + num4 - 1).ToString("D4"));
					oResult.Content2 += num4;
				}
				else
				{
					if (!(oResult.Content1 == "K") && !(oResult.Content1 == "S"))
					{
						return new OResult<List<byte[]>>(StringResources.Language.NotSupportedDataType);
					}
					stringBuilder2.Append("R");
					stringBuilder2.Append(oResult.Content1);
					stringBuilder2.Append(oResult.Content2.ToString("D4"));
					stringBuilder2.Append((oResult.Content2 + num4 - 1).ToString("D4"));
					oResult.Content2 += num4;
				}
				list.Add(PackPanasonicCommand(station, stringBuilder2.ToString(), num4 > 27).Content);
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 创建批量读取触点的报文指令<br />
		/// Create message instructions for batch reading contacts
		/// </summary>
		/// <param name="station">设备站号</param>
		/// <param name="address">地址信息</param>
		/// <param name="values">数据值</param>
		/// <returns>包含是否成功的结果对象</returns>
		public static OResult<byte[]> BuildWriteCommand(byte station, string address, byte[] values)
		{
			if (address == null)
			{
				return new OResult<byte[]>(StringResources.Language.PanasonicAddressParameterCannotBeNull);
			}
			OResult<string, int> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			values = SoftBasic.ArrayExpandToLengthEven(values);
			short num = (short)(values.Length / 2);
			StringBuilder stringBuilder = new StringBuilder("#");
			if (oResult.Content1 == "X" || oResult.Content1 == "Y" || oResult.Content1 == "R" || oResult.Content1 == "L")
			{
				stringBuilder.Append("WCC");
				stringBuilder.Append(oResult.Content1);
				int num2 = oResult.Content2 / 16;
				int num3 = num2 + num - 1;
				stringBuilder.Append(num2.ToString("D4"));
				stringBuilder.Append(num3.ToString("D4"));
			}
			else if (oResult.Content1 == "D" || oResult.Content1 == "LD" || oResult.Content1 == "F")
			{
				stringBuilder.Append("WD");
				stringBuilder.Append(oResult.Content1.Substring(0, 1));
				stringBuilder.Append(oResult.Content2.ToString("D5"));
				stringBuilder.Append((oResult.Content2 + num - 1).ToString("D5"));
			}
			else if (oResult.Content1 == "IX" || oResult.Content1 == "IY" || oResult.Content1 == "ID")
			{
				stringBuilder.Append("WD");
				stringBuilder.Append(oResult.Content1);
				stringBuilder.Append(oResult.Content2.ToString("D9"));
				stringBuilder.Append((oResult.Content2 + num - 1).ToString("D9"));
			}
			else if (oResult.Content1 == "C" || oResult.Content1 == "T")
			{
				stringBuilder.Append("WS");
				stringBuilder.Append(oResult.Content2.ToString("D4"));
				stringBuilder.Append((oResult.Content2 + num - 1).ToString("D4"));
			}
			else if (oResult.Content1 == "K" || oResult.Content1 == "S")
			{
				stringBuilder.Append("W");
				stringBuilder.Append(oResult.Content1);
				stringBuilder.Append(oResult.Content2.ToString("D4"));
				stringBuilder.Append((oResult.Content2 + num - 1).ToString("D4"));
			}
			stringBuilder.Append(SoftBasic.ByteToHexString(values));
			return PackPanasonicCommand(station, stringBuilder.ToString(), stringBuilder.Length > 112);
		}

		/// <summary>
		/// 构建获取PLC型号的报文命令
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <returns>读取PLC型号的命令报文信息</returns>
		public static OResult<byte[]> BuildReadPlcModel(byte station)
		{
			StringBuilder stringBuilder = new StringBuilder("#");
			stringBuilder.Append("RT");
			return PackPanasonicCommand(station, stringBuilder.ToString(), stringBuilder.Length > 112);
		}

		/// <summary>
		/// 检查从PLC反馈的数据，并返回正确的数据内容<br />
		/// Check the data feedback from the PLC and return the correct data content
		/// </summary>
		/// <param name="response">反馈信号</param>
		/// <param name="parseData">是否解析数据内容部分</param>
		/// <returns>是否成功的结果信息</returns>
		public static OResult<byte[]> ExtraActualData(byte[] response, bool parseData = true)
		{
			if (response.Length < 9)
			{
				return new OResult<byte[]>(StringResources.Language.PanasonicReceiveLengthMustLargerThan9);
			}
			try
			{
				if (response[3] == 36)
				{
					byte[] array = new byte[response.Length - 9];
					if (array.Length != 0)
					{
						Array.Copy(response, 6, array, 0, array.Length);
						if (parseData)
						{
							array = SoftBasic.HexStringToBytes(Encoding.ASCII.GetString(array));
						}
					}
					return OResult.CreateSuccessResult(array);
				}
				if (response[3] == 33)
				{
					int err = int.Parse(Encoding.ASCII.GetString(response, 4, 2));
					return new OResult<byte[]>(err, GetErrorDescription(err));
				}
				return new OResult<byte[]>(StringResources.Language.UnknownError + " Source Data: " + SoftBasic.GetAsciiStringRender(response));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("ExtraActualData failed: " + ex.Message + Environment.NewLine + "Source: " + SoftBasic.GetAsciiStringRender(response));
			}
		}

		/// <summary>
		/// 检查从PLC反馈的数据，并返回正确的数据内容<br />
		/// Check the data feedback from the PLC and return the correct data content
		/// </summary>
		/// <param name="response">反馈信号</param>
		/// <returns>是否成功的结果信息</returns>
		public static OResult<bool[]> ExtraActualBool(byte[] response)
		{
			if (response.Length < 9)
			{
				return new OResult<bool[]>(StringResources.Language.PanasonicReceiveLengthMustLargerThan9 + " Source: " + SoftBasic.GetAsciiStringRender(response));
			}
			if (response[3] == 36)
			{
				return OResult.CreateSuccessResult((from m in response.SelectMiddle(6, response.Length - 9)
					select m == 49).ToArray());
			}
			if (response[3] == 33)
			{
				int err = int.Parse(Encoding.ASCII.GetString(response, 4, 2));
				return new OResult<bool[]>(err, GetErrorDescription(err));
			}
			return new OResult<bool[]>(StringResources.Language.UnknownError + " Source: " + SoftBasic.GetAsciiStringRender(response));
		}

