	/// <summary>
	/// 松下PLC的数据读写类，基于MC协议的实现，具体的地址格式请参考备注说明<br />
	/// Data reading and writing of Panasonic PLC, based on the implementation of the MC protocol, please refer to the note for specific address format
	/// </summary>
	public class PanasonicMcNet : MelsecMcNet
	{
		/// <summary>
		/// 实例化松下的的Qna兼容3E帧协议的通讯对象<br />
		/// Instantiate Panasonic's Qna compatible 3E frame protocol communication object
		/// </summary>
		public PanasonicMcNet()
		{
		}

		/// <summary>
		/// 指定ip地址及端口号来实例化一个松下的Qna兼容3E帧协议的通讯对象<br />
		/// Specify an IP address and port number to instantiate a Panasonic Qna compatible 3E frame protocol communication object
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
		/// <param name="port">PLC的端口</param>
		public PanasonicMcNet(string ipAddress, int port)
			: base(ipAddress, port)
		{
		}

		/// <inheritdoc />
		public override OResult<McAddressData> McAnalysisAddress(string address, ushort length, bool isBit)
		{
			return McAddressData.ParsePanasonicFrom(address, length, isBit);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			ushort num = BitConverter.ToUInt16(response, 9);
			if (num != 0)
			{
				return new OResult<byte[]>(num, PanasonicHelper.GetMcErrorDescription(num));
			}
			return OResult.CreateSuccessResult(response.RemoveBegin(11));
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"PanasonicMcNet[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 松下PLC的数据交互协议，采用Mewtocol协议通讯，支持的地址列表参考api文档<br />
	/// The data exchange protocol of Panasonic PLC adopts Mewtocol protocol for communication. For the list of supported addresses, refer to the api document.
	/// </summary>
	/// <remarks>
	/// 地址支持携带站号的访问方式，例如：s=2;D100
	/// </remarks>
	public class PanasonicMewtocol : DeviceSerialPort
	{
		/// <inheritdoc cref="P:Snet.Driver.Profinet.Panasonic.PanasonicMewtocolOverTcp.Station" />
		public byte Station { get; set; }

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocolOverTcp.#ctor(System.Byte)" />
		public PanasonicMewtocol(byte station = 238)
		{
			base.ByteTransform = new RegularByteTransform();
			Station = station;
			base.ByteTransform.DataFormat = DataFormat.DCBA;
			base.WordLength = 1;
			base.ReceiveEmptyDataCount = 5;
			LogMsgFormatBinary = false;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SpecifiedCharacterMessage(13);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocolOverTcp.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			return MewtocolHelper.Read(this, Station, address, length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocolOverTcp.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			return MewtocolHelper.Write(this, Station, address, value);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocolOverTcp.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			return MewtocolHelper.ReadBool(this, Station, address, length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.Helper.MewtocolHelper.ReadBool(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String[])" />
		public OResult<bool[]> ReadBool(string[] address)
		{
			return MewtocolHelper.ReadBool(this, Station, address);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocolOverTcp.ReadBool(System.String)" />
		public override OResult<bool> ReadBool(string address)
		{
			return MewtocolHelper.ReadBool(this, Station, address);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocolOverTcp.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] values)
		{
