	/// <summary>
	/// 松下Mewtocol协议的虚拟服务器，支持串口和网口的操作<br />
	/// Panasonic Mewtocol protocol virtual server, supports serial and network port operations
	/// </summary>
	/// <remarks>
	/// 地址的地址分为线圈型和整型，线圈支持X,Y,R,L, 字单位的整型支持 X,Y,R,L,D,LD,F<br />
	/// The address of the address is divided into coil type and integer type, the coil supports X, Y, R, L, and the integer type of word unit supports X, Y, R, L, D, LD, F
	/// </remarks>
	public class PanasonicMewtocolServer : DeviceServer
	{
		private SoftBuffer xBuffer;

		private SoftBuffer rBuffer;

		private SoftBuffer dtBuffer;

		private SoftBuffer ldBuffer;

		private SoftBuffer flBuffer;

		private SoftBuffer yBuffer;

		private SoftBuffer lBuffer;

		private const int DataPoolLength = 65536;

		private byte station = 1;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Panasonic.PanasonicMewtocol.Station" />
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public PanasonicMewtocolServer()
		{
			rBuffer = new SoftBuffer(131072);
			dtBuffer = new SoftBuffer(131072);
			ldBuffer = new SoftBuffer(131072);
			flBuffer = new SoftBuffer(131072);
			xBuffer = new SoftBuffer(131072);
			lBuffer = new SoftBuffer(131072);
			yBuffer = new SoftBuffer(131072);
			base.ByteTransform = new RegularByteTransform();
			base.ByteTransform.DataFormat = DataFormat.DCBA;
			LogMsgFormatBinary = false;
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[917504];
			Array.Copy(rBuffer.GetBytes(), 0, array, 0, 131072);
			Array.Copy(dtBuffer.GetBytes(), 0, array, 131072, 131072);
			Array.Copy(ldBuffer.GetBytes(), 0, array, 262144, 131072);
			Array.Copy(flBuffer.GetBytes(), 0, array, 393216, 131072);
			Array.Copy(xBuffer.GetBytes(), 0, array, 524288, 131072);
			Array.Copy(lBuffer.GetBytes(), 0, array, 655360, 131072);
			Array.Copy(yBuffer.GetBytes(), 0, array, 786432, 131072);
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 917504)
			{
				throw new Exception("File is not correct");
			}
			rBuffer.SetBytes(content, 0, 0, 131072);
			dtBuffer.SetBytes(content, 131072, 0, 131072);
			ldBuffer.SetBytes(content, 262144, 0, 131072);
			flBuffer.SetBytes(content, 393216, 0, 131072);
			xBuffer.SetBytes(content, 524288, 0, 131072);
			lBuffer.SetBytes(content, 655360, 0, 131072);
			yBuffer.SetBytes(content, 786432, 0, 131072);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocol.Read(System.String,System.UInt16)" />
		/// <remarks>
		/// 在服务器端的功能实现里，暂时不支持C,T数据的访问。<br />
		/// In the server-side function implementation, access to C and T data is temporarily not supported.
		/// </remarks>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<string, int> oResult = PanasonicHelper.AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content1 == "D")
			{
				return OResult.CreateSuccessResult(dtBuffer.GetBytes(oResult.Content2 * 2, length * 2));
			}
			if (oResult.Content1 == "LD")
			{
				return OResult.CreateSuccessResult(ldBuffer.GetBytes(oResult.Content2 * 2, length * 2));
			}
			if (oResult.Content1 == "F")
			{
				return OResult.CreateSuccessResult(flBuffer.GetBytes(oResult.Content2 * 2, length * 2));
			}
			if (oResult.Content1 == "X")
			{
				return OResult.CreateSuccessResult(xBuffer.GetBool(oResult.Content2, length * 16).ToByteArray());
			}
			if (oResult.Content1 == "Y")
			{
				return OResult.CreateSuccessResult(yBuffer.GetBool(oResult.Content2, length * 16).ToByteArray());
			}
			if (oResult.Content1 == "R")
			{
				return OResult.CreateSuccessResult(rBuffer.GetBool(oResult.Content2, length * 16).ToByteArray());
			}
			if (oResult.Content1 == "L")
			{
				return OResult.CreateSuccessResult(lBuffer.GetBool(oResult.Content2, length * 16).ToByteArray());
			}
			return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocol.Write(System.String,System.Byte[])" />
		/// <remarks>
		/// 在服务器端的功能实现里，暂时不支持C,T数据的访问。<br />
		/// In the server-side function implementation, access to C and T data is temporarily not supported.
		/// </remarks>
		public override OResult Write(string address, byte[] value)
		{
			OResult<string, int> oResult = PanasonicHelper.AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content1 == "D")
			{
				dtBuffer.SetBytes(value, oResult.Content2 * 2);
			}
			else if (oResult.Content1 == "LD")
			{
				ldBuffer.SetBytes(value, oResult.Content2 * 2);
			}
			else if (oResult.Content1 == "F")
			{
				flBuffer.SetBytes(value, oResult.Content2 * 2);
			}
			else if (oResult.Content1 == "X")
			{
				xBuffer.SetBool(value.ToBoolArray(), oResult.Content2);
			}
			else if (oResult.Content1 == "Y")
			{
				yBuffer.SetBool(value.ToBoolArray(), oResult.Content2);
			}
			else if (oResult.Content1 == "R")
			{
				rBuffer.SetBool(value.ToBoolArray(), oResult.Content2);
			}
			else
			{
				if (!(oResult.Content1 == "L"))
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
				}
				lBuffer.SetBool(value.ToBoolArray(), oResult.Content2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocol.ReadBool(System.String,System.UInt16)" />
		/// <remarks>
		/// 在服务器端的功能实现里，长度支持任意的长度信息。<br />
		/// In the server-side function implementation, the length supports arbitrary length information.
		/// </remarks>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<string, int> oResult = PanasonicHelper.AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content1 == "X")
			{
				return OResult.CreateSuccessResult(xBuffer.GetBool(oResult.Content2, length));
			}
			if (oResult.Content1 == "Y")
			{
				return OResult.CreateSuccessResult(yBuffer.GetBool(oResult.Content2, length));
			}
			if (oResult.Content1 == "R")
			{
				return OResult.CreateSuccessResult(rBuffer.GetBool(oResult.Content2, length));
			}
			if (oResult.Content1 == "L")
			{
				return OResult.CreateSuccessResult(lBuffer.GetBool(oResult.Content2, length));
			}
			return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.PanasonicMewtocol.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			OResult<string, int> oResult = PanasonicHelper.AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content1 == "X")
			{
				xBuffer.SetBool(value, oResult.Content2);
			}
			else if (oResult.Content1 == "Y")
			{
				yBuffer.SetBool(value, oResult.Content2);
			}
			else if (oResult.Content1 == "R")
			{
				rBuffer.SetBool(value, oResult.Content2);
			}
			else
			{
				if (!(oResult.Content1 == "L"))
				{
					return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
				}
				lBuffer.SetBool(value, oResult.Content2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SpecifiedCharacterMessage(13);
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive.Length < 5)
			{
				return new OResult<byte[]>("Uknown Data：" + receive.ToHexString(' '));
			}
			return PanasonicHelper.PackPanasonicCommand(station, ReadFromCommand(receive), receive[0] == 60);
		}

		/// <summary>
		/// 创建一个失败的返回消息，指定错误码即可，会自动计算出来BCC校验和
		/// </summary>
		/// <param name="code">错误码</param>
		/// <returns>原始字节报文，用于反馈消息</returns>
		protected string CreateFailedResponse(byte code)
		{
			return "!" + code.ToString("D2");
		}

		/// <summary>
		/// 根据命令来获取相关的数据内容
		/// </summary>
		/// <param name="cmd">原始的命令码</param>
		/// <returns>返回的数据信息</returns>
		public virtual string ReadFromCommand(byte[] cmd)
		{
			try
			{
				string text = Encoding.ASCII.GetString(cmd);
				if (text[0] != '%' && text[0] != '<')
				{
					return CreateFailedResponse(41);
				}
				byte b = Convert.ToByte(text.Substring(1, 2), 16);
				bool flag = text[0] == '<';
				if (b != station)
				{
					base.LogNet?.WriteError(ToString(), $"Station not match, need:{station}, but now: {b}");
					return CreateFailedResponse(50);
				}
				if (text[3] != '#')
				{
					return CreateFailedResponse(41);
				}
				if (text.Substring(4, 3) == "RCS")
				{
					int destIndex = Convert.ToInt32(text.Substring(8, 3)) * 16 + Convert.ToInt32(text.Substring(11, 1), 16);
					if (text[7] == 'R')
					{
						return "$RC" + (rBuffer.GetBool(destIndex) ? "1" : "0");
					}
					if (text[7] == 'X')
					{
						return "$RC" + (xBuffer.GetBool(destIndex) ? "1" : "0");
					}
					if (text[7] == 'Y')
					{
						return "$RC" + (yBuffer.GetBool(destIndex) ? "1" : "0");
					}
					if (text[7] == 'L')
					{
						return "$RC" + (lBuffer.GetBool(destIndex) ? "1" : "0");
					}
					return CreateFailedResponse(42);
				}
				if (text.Substring(4, 3) == "WCS")
				{
					int destIndex2 = Convert.ToInt32(text.Substring(8, 3)) * 16 + Convert.ToInt32(text.Substring(11, 1), 16);
					if (text[7] == 'R')
					{
						rBuffer.SetBool(text[12] == '1', destIndex2);
						return "$WC";
					}
					if (text[7] == 'X')
					{
						xBuffer.SetBool(text[12] == '1', destIndex2);
						return "$WC";
					}
					if (text[7] == 'Y')
					{
						yBuffer.SetBool(text[12] == '1', destIndex2);
						return "$WC";
					}
					if (text[7] == 'L')
					{
						lBuffer.SetBool(text[12] == '1', destIndex2);
						return "$WC";
					}
					return CreateFailedResponse(42);
				}
				if (text.Substring(4, 3) == "RCP")
				{
					int num = text[7] - 48;
					if (num > 8)
					{
						return CreateFailedResponse(42);
					}
					StringBuilder stringBuilder = new StringBuilder();
					for (int i = 0; i < num; i++)
					{
						int destIndex3 = Convert.ToInt32(text.Substring(9 + 5 * i, 3)) * 16 + Convert.ToInt32(text.Substring(12 + 5 * i, 1), 16);
						if (text[8 + 5 * i] == 'R')
						{
							stringBuilder.Append(rBuffer.GetBool(destIndex3) ? "1" : "0");
						}
						else if (text[8 + 5 * i] == 'X')
						{
							stringBuilder.Append(xBuffer.GetBool(destIndex3) ? "1" : "0");
						}
						else if (text[8 + 5 * i] == 'Y')
						{
							stringBuilder.Append(yBuffer.GetBool(destIndex3) ? "1" : "0");
						}
						else if (text[8 + 5 * i] == 'L')
						{
							stringBuilder.Append(lBuffer.GetBool(destIndex3) ? "1" : "0");
						}
					}
					return "$RC" + stringBuilder.ToString();
				}
				if (text.Substring(4, 3) == "WCP")
				{
					int num2 = text[7] - 48;
					if (num2 > 8)
					{
						return CreateFailedResponse(42);
					}
					for (int j = 0; j < num2; j++)
					{
						int destIndex4 = Convert.ToInt32(text.Substring(9 + 6 * j, 3)) * 16 + Convert.ToInt32(text.Substring(12 + 6 * j, 1), 16);
						if (text[8 + 6 * j] == 'R')
						{
							rBuffer.SetBool(text[13 + 6 * j] == '1', destIndex4);
						}
						else if (text[8 + 6 * j] == 'X')
						{
							xBuffer.SetBool(text[13 + 6 * j] == '1', destIndex4);
						}
						else if (text[8 + 6 * j] == 'Y')
						{
							yBuffer.SetBool(text[13 + 6 * j] == '1', destIndex4);
						}
						else if (text[8 + 6 * j] == 'L')
						{
							lBuffer.SetBool(text[13 + 6 * j] == '1', destIndex4);
						}
					}
					return "$WC";
				}
				if (text.Substring(4, 3) == "RCC")
				{
					int num3 = Convert.ToInt32(text.Substring(8, 4));
					int num4 = Convert.ToInt32(text.Substring(12, 4)) - num3 + 1;
					if (num4 > (flag ? 509 : 27))
					{
						return CreateFailedResponse(42);
					}
					if (text[7] == 'R')
					{
						return "$RC" + rBuffer.GetBytes(num3 * 2, num4 * 2).ToHexString();
					}
					if (text[7] == 'X')
					{
						return "$RC" + xBuffer.GetBytes(num3 * 2, num4 * 2).ToHexString();
					}
					if (text[7] == 'Y')
					{
						return "$RC" + yBuffer.GetBytes(num3 * 2, num4 * 2).ToHexString();
					}
					if (text[7] == 'L')
					{
						return "$RC" + lBuffer.GetBytes(num3 * 2, num4 * 2).ToHexString();
					}
					return CreateFailedResponse(42);
				}
				if (text.Substring(4, 3) == "WCC")
				{
					int num5 = Convert.ToInt32(text.Substring(8, 4));
					int num6 = Convert.ToInt32(text.Substring(12, 4)) - num5 + 1;
					byte[] array = text.Substring(16, num6 * 4).ToHexBytes();
					if (array.Length > (flag ? 2028 : 98))
					{
						return CreateFailedResponse(42);
					}
					if (text[7] == 'R')
					{
						rBuffer.SetBytes(array, num5 * 2);
						return "$WC";
					}
					if (text[7] == 'X')
					{
						xBuffer.SetBytes(array, num5 * 2);
						return "$WC";
					}
					if (text[7] == 'Y')
					{
						yBuffer.SetBytes(array, num5 * 2);
						return "$WC";
					}
					if (text[7] == 'L')
					{
						lBuffer.SetBytes(array, num5 * 2);
						return "$WC";
					}
					return CreateFailedResponse(42);
				}
				if (text.Substring(4, 2) == "RD")
				{
					int num7 = Convert.ToInt32(text.Substring(7, 5));
					int num8 = Convert.ToInt32(text.Substring(12, 5)) - num7 + 1;
					if (num8 > (flag ? 509 : 27))
					{
						return CreateFailedResponse(42);
					}
					if (text[6] == 'D')
					{
						return "$RD" + dtBuffer.GetBytes(num7 * 2, num8 * 2).ToHexString();
					}
					if (text[6] == 'L')
					{
						return "$RD" + ldBuffer.GetBytes(num7 * 2, num8 * 2).ToHexString();
					}
					if (text[6] == 'F')
					{
						return "$RD" + flBuffer.GetBytes(num7 * 2, num8 * 2).ToHexString();
					}
					return CreateFailedResponse(42);
				}
				if (text.Substring(4, 2) == "WD")
				{
					int num9 = Convert.ToInt32(text.Substring(7, 5));
					int num10 = Convert.ToInt32(text.Substring(12, 5)) - num9 + 1;
					byte[] array2 = text.Substring(17, num10 * 4).ToHexBytes();
					if (array2.Length > (flag ? 2028 : 98))
					{
						return CreateFailedResponse(42);
					}
					if (text[6] == 'D')
					{
						dtBuffer.SetBytes(array2, num9 * 2);
						return "$WD";
					}
					if (text[6] == 'L')
					{
						ldBuffer.SetBytes(array2, num9 * 2);
						return "$WD";
					}
					if (text[6] == 'F')
					{
						flBuffer.SetBytes(array2, num9 * 2);
						return "$WD";
					}
					return CreateFailedResponse(42);
				}
				if (text.Substring(4, 2) == "RT")
				{
					return "$RT0300160000000000";
				}
				return CreateFailedResponse(41);
			}
			catch (Exception ex)
			{
				base.LogNet?.WriteException(ToString(), ex);
				return CreateFailedResponse(41);
			}
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			if (receivedLength > 5)
			{
				return buffer[receivedLength - 1] == 13;
			}
			return base.CheckSerialReceiveDataComplete(buffer, receivedLength);
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				xBuffer?.Dispose();
				rBuffer?.Dispose();
				dtBuffer?.Dispose();
				ldBuffer?.Dispose();
				flBuffer?.Dispose();
				yBuffer?.Dispose();
				lBuffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"PanasonicMewtocolServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Panasonic.Helper
{
	/// <summary>
	/// Mewtocol协议的辅助类信息
	/// </summary>
	public class MewtocolHelper
	{
		private static bool CheckBoolOnWordAddress(string address)
		{
			return Regex.IsMatch(address, "^(s=[0-9]+;)?(D|LD|DT|F)[0-9]+\\.[0-9]+$", RegexOptions.IgnoreCase);
		}

		/// <summary>
		/// 读取单个的地址信息的bool值，地址举例：SR0.0  X0.0  Y0.0  R0.0  L0.0<br />
		/// Read the bool value of a single address, for example: SR0.0 X0.0 Y0.0 R0.0 L0.0
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="address">起始地址</param>
		/// <returns>读取结果对象</returns>
		public static OResult<bool> ReadBool(IReadWriteDevice plc, byte station, string address)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return ByteTransformHelper.GetResultFromArray(SnetHelper.ReadBool(plc, address, 1));
			}
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<byte[]> oResult = PanasonicHelper.BuildReadOneCoil(station, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult2);
			}
			return ByteTransformHelper.GetResultFromArray(PanasonicHelper.ExtraActualBool(oResult2.Content));
		}

		/// <summary>
		/// 批量读取松下PLC的位数据，按照字为单位，地址为 X0,X10,Y10，读取的长度为16的倍数<br />
		/// Read the bit data of Panasonic PLC in batches, the unit is word, the address is X0, X10, Y10, and the read length is a multiple of 16
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="address">起始地址</param>
		/// <param name="length">数据长度</param>
		/// <returns>读取结果对象</returns>
		public static OResult<bool[]> ReadBool(IReadWriteDevice plc, byte station, string address, ushort length)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return SnetHelper.ReadBool(plc, address, length);
			}
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<string, int> oResult = PanasonicHelper.AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<List<byte[]>> oResult2 = PanasonicHelper.BuildReadCommand(station, address, length, isBit: true);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult2.Content.Count; i++)
			{
				OResult<byte[]> oResult3 = plc.ReadFromCoreServer(oResult2.Content[i]);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				OResult<byte[]> oResult4 = PanasonicHelper.ExtraActualData(oResult3.Content);
				if (!oResult4.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult4);
				}
				list.AddRange(oResult4.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray().ToBoolArray().SelectMiddle(oResult.Content2 % 16, length));
		}

		/// <summary>
		/// 批量读取松下PLC的位数据，传入一个读取的地址列表，地址支持X,Y,R,T,C,L, 举例：R1.0, X2.0, R3.A<br />
		/// Batch read the bit data of Panasonic PLC, pass in a read address list, the address supports X, Y, R, T, C, L, for example: R1.0, X2.0, R3.A
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="address">等待读取的地址列表，数组长度不限制</param>
		/// <returns>读取结果对象</returns>
		public static OResult<bool[]> ReadBool(IReadWriteDevice plc, byte station, string[] address)
		{
			OResult<List<byte[]>> oResult = PanasonicHelper.BuildReadCoils(station, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<bool> list = new List<bool>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult<bool[]> oResult3 = PanasonicHelper.ExtraActualBool(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				list.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <summary>
		/// 往指定的地址写入bool数据，地址举例：SR0.0  X0.0  Y0.0  R0.0  L0.0<br />
		/// Write bool data to the specified address. Example address: SR0.0 X0.0 Y0.0 R0.0 L0.0
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="address">起始地址</param>
		/// <param name="value">数据值信息</param>
		/// <returns>返回是否成功的结果对象</returns>
		public static OResult Write(IReadWriteDevice plc, byte station, string address, bool value)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return SnetHelper.WriteBool(plc, address, new bool[1] { value });
			}
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<byte[]> oResult = PanasonicHelper.BuildWriteOneCoil(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return PanasonicHelper.ExtraActualData(oResult2.Content);
		}

		/// <summary>
		/// 往指定的地址写入 <see cref="T:System.Boolean" /> 数组，地址举例 X0.0  Y0.0  R0.0  L0.0，
		/// 起始的位地址必须为16的倍数，写入的 <see cref="T:System.Boolean" /> 数组长度也为16的倍数。<br />
		/// Write the <see cref="T:System.Boolean" /> array to the specified address, address example: SR0.0 X0.0 Y0.0 R0.0 L0.0, 
		/// the starting bit address must be a multiple of 16. <see cref="T:System.Boolean" /> The length of the array is also a multiple of 16. <br />
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="address">起始地址</param>
		/// <param name="values">数据值信息</param>
		/// <returns>返回是否成功的结果对象</returns>
		public static OResult Write(IReadWriteDevice plc, byte station, string address, bool[] values)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return SnetHelper.WriteBool(plc, address, values);
			}
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<string, int> oResult = PanasonicHelper.AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content2 % 16 != 0)
			{
				return new OResult(StringResources.Language.PanasonicAddressBitStartMulti16);
			}
			if (values.Length % 16 != 0)
			{
				return new OResult(StringResources.Language.PanasonicBoolLengthMulti16);
			}
			byte[] values2 = SoftBasic.BoolArrayToByte(values);
			OResult<byte[]> oResult2 = PanasonicHelper.BuildWriteCommand(station, address, values2);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = plc.ReadFromCoreServer(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return PanasonicHelper.ExtraActualData(oResult3.Content);
		}

		/// <summary>
		/// 将Bool数组值写入到指定的离散地址里，一个地址对应一个bool值，地址数组长度和值数组长度必须相等，地址支持X,Y,R,T,C,L, 举例：R1.0, X2.0, R3.A<br />
		/// Write the Bool array value to the specified discrete address, one address corresponds to one bool value, 
		/// the length of the address array and the length of the value array must be equal, the address supports X, Y, R, T, C, L, for example: R1.0, X2.0, R3.A
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="address">离散的地址列表</param>
		/// <param name="value">bool数组值</param>
		/// <returns>是否写入成功的结果对象</returns>
		public static OResult Write(IReadWriteDevice plc, byte station, string[] address, bool[] value)
		{
			OResult<List<byte[]>> oResult = PanasonicHelper.BuildWriteCoils(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult oResult3 = PanasonicHelper.ExtraActualData(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 读取指定地址的原始数据，地址示例：D0  F0  K0  T0  C0, 地址支持携带站号的访问方式，例如：s=2;D100<br />
		/// Read the original data of the specified address, address example: D0 F0 K0 T0 C0, the address supports carrying station number information, for example: s=2;D100
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="address">起始地址</param>
		/// <param name="length">长度</param>
		/// <returns>原始的字节数据的信息</returns>
		public static OResult<byte[]> Read(IReadWriteDevice plc, byte station, string address, ushort length)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<List<byte[]>> oResult = PanasonicHelper.BuildReadCommand(station, address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult<byte[]> oResult3 = PanasonicHelper.ExtraActualData(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				list.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

