			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<byte[]> oResult = PanasonicHelper.BuildWriteOneCoil(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await plc.ReadFromCoreServerAsync(oResult.Content).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return PanasonicHelper.ExtraActualData(oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.Helper.MewtocolHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Boolean[])" />
		public static async Task<OResult> WriteAsync(IReadWriteDevice plc, byte station, string address, bool[] values)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return SnetHelper.WriteBool(plc, address, values);
			}
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<string, int> oResult = PanasonicHelper.AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content2 % 16 != 0)
			{
				return new OResult(StringResources.Language.PanasonicAddressBitStartMulti16);
			}
			if (values.Length % 16 != 0)
			{
				return new OResult(StringResources.Language.PanasonicBoolLengthMulti16);
			}
			byte[] values2 = SoftBasic.BoolArrayToByte(values);
			OResult<byte[]> oResult2 = PanasonicHelper.BuildWriteCommand(station, address, values2);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = await plc.ReadFromCoreServerAsync(oResult2.Content).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return PanasonicHelper.ExtraActualData(oResult3.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.Helper.MewtocolHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String[],System.Boolean[])" />
		public static async Task<OResult> WriteAsync(IReadWriteDevice plc, byte station, string[] address, bool[] value)
		{
			OResult<List<byte[]>> command = PanasonicHelper.BuildWriteCoils(station, address, value);
			if (!command.IsSuccess)
			{
				return command;
			}
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await plc.ReadFromCoreServerAsync(command.Content[i]).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult oResult2 = PanasonicHelper.ExtraActualData(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.Helper.MewtocolHelper.Read(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.UInt16)" />
		public static async Task<OResult<byte[]>> ReadAsync(IReadWriteDevice plc, byte station, string address, ushort length)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<List<byte[]>> command = PanasonicHelper.BuildReadCommand(station, address, length, isBit: false);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(command);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await plc.ReadFromCoreServerAsync(command.Content[i]).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = PanasonicHelper.ExtraActualData(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				list.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Panasonic.Helper.MewtocolHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Byte[])" />
		public static async Task<OResult> WriteAsync(IReadWriteDevice plc, byte station, string address, byte[] value)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<byte[]> oResult = PanasonicHelper.BuildWriteCommand(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await plc.ReadFromCoreServerAsync(oResult.Content).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return PanasonicHelper.ExtraActualData(oResult2.Content);
		}

		private static OResult<string> GetPlcType(byte[] data)
		{
			try
			{
				string text = Encoding.ASCII.GetString(data, 0, 2);
				return text switch
				{
					"03" => OResult.CreateSuccessResult("FP3"), 
					"02" => OResult.CreateSuccessResult("FP5"), 
					"05" => OResult.CreateSuccessResult("FP-E"), 
					_ => OResult.CreateSuccessResult(text), 
				};
			}
			catch (Exception ex)
			{
				return new OResult<string>("Get plctype failed : " + ex.Message + Environment.NewLine + "Source: " + data.ToHexString());
			}
		}

		/// <summary>
		/// 读取PLC的型号信息<br />
		/// Read the model information of the PLC
		/// </summary>
		/// <param name="plc">通信对象</param>
		/// <param name="station">站号信息</param>
		/// <returns>PLC型号</returns>
		public static OResult<string> ReadPlcType(IReadWriteDevice plc, byte station)
		{
			OResult<byte[]> oResult = PanasonicHelper.BuildReadPlcModel(station);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			OResult<byte[]> oResult3 = PanasonicHelper.ExtraActualData(oResult2.Content, parseData: false);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			return GetPlcType(oResult3.Content);
		}
	}
}
namespace Snet.Driver.Profinet.OrientalMotor
{
	/// <summary>
	/// 东方马达的EIP通信协议，适用控制器
	/// </summary>
	public class OrientalMotorEipNet : NetworkConnectedCip
	{
		private byte[] inputBuffer;

		private byte[] outputBuffer = new byte[172];

		private Socket socketCore;

		private Thread threadReceive;

		private int bufferLength = 2048;

		private bool IsStarted;

		private EndPoint udpEndPoint;

		private int returnId;

		private DateTime bufferReceiveTime = DateTime.Now;

		/// <summary>
		/// 获取或设置CIP I/O 模式下的端口信息
		/// </summary>
		public int CipIoPort { get; private set; }

		/// <summary>
		/// 回发消息的时候RunIdle
		/// </summary>
		public uint RunIdleHeader { get; set; } = 1u;

		/// <summary>
		/// RPI的时间，单位是毫秒，默认100ms
		/// </summary>
		public uint RPITime { get; set; } = 100u;

		/// <summary>
		/// EIP协议超时时间，单位是秒，只能设置2得指数倍，例如1,2,4,8,16,32,64,128,256等，默认2秒
		/// </summary>
		public int ActualTimeout { get; set; } = 2;

		/// <summary>
		/// 收到数据的事件，如果是172字节长度，则是Input数据，其他长度的数据则不处理
		/// </summary>
		public event EventHandler<OrientalMotorEventArgs> OnReceiveData;

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceTcpNet.#ctor" />
		public OrientalMotorEipNet()
		{
			base.WordLength = 2;
			bufferReceiveTime = DateTime.Now;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceTcpNet.#ctor(System.String,System.Int32)" />
		public OrientalMotorEipNet(string ip, int port)
			: this()
		{
			IpAddress = ip;
			Port = port;
		}

		private int GetTickTimes(int actualTimeout)
		{
			int num = 0;
			for (int num2 = 1; num2 < actualTimeout; num2 *= 2)
			{
				num++;
			}
			return num;
		}

		private byte[] GetHandleData()
		{
			byte[] array = "000000000000020000000000b2003a0054022006240103fa0000000001004757010000000000000000000000a0860100b248a0860100ae4801083404bb002b00fb13010020042c652c64".ToHexBytes();
			base.TOConnectionId = (uint)SnetHelper.SnetRandom.Next();
			BitConverter.GetBytes(base.TOConnectionId).CopyTo(array, 28);
			BitConverter.GetBytes(RPITime * 1000).CopyTo(array, 44);
			BitConverter.GetBytes(RPITime * 1000).CopyTo(array, 50);
			array[22] = (byte)GetTickTimes(ActualTimeout * 4);
			return array;
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.RegisterSessionHandle(), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult oResult2 = AllenBradleyHelper.CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			base.SessionHandle = base.ByteTransform.TransUInt32(oResult.Content, 4);
			OResult<byte[]> oResult3 = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, base.SessionHandle, GetHandleData()), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			base.OTConnectionId = BitConverter.ToUInt32(oResult3.Content, 44);
			CipIoPort = oResult3.Content[96] * 256 + oResult3.Content[97];
			returnId = 0;
			OResult oResult4 = StartUdpServer();
			if (!oResult4.IsSuccess)
			{
				return oResult4;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(CommunicationPipe, AllenBradleyHelper.RegisterSessionHandle(), hasResponseData: true, usePackAndUnpack: false).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult oResult2 = AllenBradleyHelper.CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			base.SessionHandle = base.ByteTransform.TransUInt32(oResult.Content, 4);
			OResult<byte[]> oResult3 = await ReadFromCoreServerAsync(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, base.SessionHandle, GetHandleData()), hasResponseData: true, usePackAndUnpack: false).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			base.OTConnectionId = BitConverter.ToUInt32(oResult3.Content, 44);
			CipIoPort = oResult3.Content[96] * 256 + oResult3.Content[97];
			returnId = 0;
			OResult oResult4 = StartUdpServer();
			if (!oResult4.IsSuccess)
			{
				return oResult4;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override OResult ExtraOnDisconnect()
		{
			IsStarted = false;
			if (socketCore != null)
			{
				NetSupport.CloseSocket(socketCore);
			}
			return base.ExtraOnDisconnect();
		}

		/// <inheritdoc />
		protected override async Task<OResult> ExtraOnDisconnectAsync()
		{
			IsStarted = false;
			if (socketCore != null)
			{
				NetSupport.CloseSocket(socketCore);
			}
			return await base.ExtraOnDisconnectAsync();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			if (base.ReceiveTimeOut > 0 && (DateTime.Now - bufferReceiveTime).TotalMilliseconds > (double)base.ReceiveTimeOut)
			{
				return new OResult<byte[]>("No input data received within the timeout period");
			}
			if (address.StartsWith("input", StringComparison.OrdinalIgnoreCase))
			{
				if (inputBuffer != null)
				{
					int num = SnetHelper.ExtractStartIndex(ref address);
					if (num < 0)
					{
						num = 0;
					}
					if (num + length > inputBuffer.Length)
					{
						return new OResult<byte[]>("Read length exceeds the buffer size");
					}
					return OResult.CreateSuccessResult(inputBuffer.SelectMiddle(num, length));
				}
				return new OResult<byte[]>("No input data received yet");
			}
			if (address.StartsWith("output", StringComparison.OrdinalIgnoreCase))
			{
				int num2 = SnetHelper.ExtractStartIndex(ref address);
				if (num2 < 0)
				{
					num2 = 0;
				}
				if (num2 + length > outputBuffer.Length)
				{
					return new OResult<byte[]>("Read length exceeds the buffer size");
				}
				return OResult.CreateSuccessResult(outputBuffer.SelectMiddle(num2, length));
			}
			return new OResult<byte[]>("Only support read input data, address should start with 'input'");
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadAsync(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			return await Task.FromResult(Read(address, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			if (base.ReceiveTimeOut > 0 && (DateTime.Now - bufferReceiveTime).TotalMilliseconds > (double)base.ReceiveTimeOut)
			{
				return new OResult("No input data received within the timeout period");
			}
			if (address.StartsWith("output", StringComparison.OrdinalIgnoreCase))
			{
				int num = SnetHelper.ExtractStartIndex(ref address);
				if (num < 0)
				{
					num = 0;
				}
				if (num + value.Length > outputBuffer.Length)
				{
					return new OResult<byte[]>("Write length exceeds the buffer size");
				}
				Array.Copy(value, 0, outputBuffer, num, value.Length);
				return OResult.CreateSuccessResult();
			}
			return new OResult<byte[]>("Only support write output data, address should start with 'output'");
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.WriteAsync(System.String,System.Byte[])" />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			return await Task.FromResult(Write(address, value));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.OrientalMotor.OrientalMotorEipNet.Read(System.String,System.UInt16)" />
		public OResult<byte> ReadByte(string address)
		{
			return ByteTransformHelper.GetResultFromArray(Read(address, 1));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.OrientalMotor.OrientalMotorEipNet.Write(System.String,System.Byte[])" />
		public OResult Write(string address, byte value)
		{
			return Write(address, new byte[1] { value });
		}

		private OResult StartUdpServer()
		{
			if (socketCore != null)
			{
				NetSupport.CloseSocket(socketCore);
			}
			try
			{
				socketCore = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp);
				socketCore.Bind(new IPEndPoint(IPAddress.Any, CipIoPort));
				IsStarted = true;
				threadReceive = new Thread(ThreadReceiveUdpCycle)
				{
					IsBackground = true
				};
				threadReceive.Start();
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				return new OResult("Start Udp failed: " + ex.Message);
			}
		}

		private void ThreadReceiveUdpCycle()
		{
			byte[] array = new byte[bufferLength];
			while (IsStarted)
			{
				int num = 0;
				try
				{
					EndPoint remoteEP = new IPEndPoint(IPAddress.Any, 0);
					num = socketCore.ReceiveFrom(array, 0, array.Length, SocketFlags.None, ref remoteEP);
					udpEndPoint = remoteEP;
					if (num < 18)
					{
						continue;
					}
					LogRevcMessage(array.SelectBegin(num));
					int num2 = BitConverter.ToUInt16(array, 0);
					int num3 = 2;
					for (int i = 0; i < num2; i++)
					{
						ushort num4 = BitConverter.ToUInt16(array, num3);
						num3 += 2;
						ushort num5 = BitConverter.ToUInt16(array, num3);
						num3 += 2;
						if (num4 == 177 && num5 == 174)
						{
							bufferReceiveTime = DateTime.Now;
							if (inputBuffer == null)
							{
								inputBuffer = new byte[172];
							}
							Array.Copy(array, num3 + 2, inputBuffer, 0, inputBuffer.Length);
							if (OnReceiveData != null)
							{
								OrientalMotorEventArgs e = new OrientalMotorEventArgs();
								e.Content = array.SelectMiddle(num3 + 2, inputBuffer.Length);
								OnReceiveData?.Invoke(this, e);
							}
							byte[] array2 = "".ToHexBytes();
							BitConverter.GetBytes(base.OTConnectionId).CopyTo(array2, 6);
							Array.Copy(array, 10, array2, 10, 4);
							BitConverter.GetBytes((short)returnId).CopyTo(array2, 18);
							BitConverter.GetBytes(RunIdleHeader).CopyTo(array2, 20);
							Array.Copy(outputBuffer, 0, array2, 24, outputBuffer.Length);
							returnId++;
							if (returnId > 65535)
							{
								returnId = 1;
							}
							LogSendMessage(array2);
							try
							{
								socketCore.SendTo(array2, 0, array2.Length, SocketFlags.None, udpEndPoint);
							}
							catch (Exception ex)
							{
								base.LogNet?.WriteException("UDP send back failed: ", ex);
							}
						}
						num3 += num5;
					}
				}
				catch (Exception)
				{
					break;
				}
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"OrientalMotorEipNet[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 东方马达的消息类信息
