		public int BatchSize { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public JobItem()
		{
		}

		/// <summary>
		/// 指定原始数据实例化一个对象信息
		/// </summary>
		/// <param name="data">等待分析的原始数据，例如：15:011:0:22</param>
		public JobItem(string data)
		{
			if (data.Length == 12)
			{
				data = data.Substring(0, 11);
			}
			string[] array = data.Split(new char[1] { ':' }, StringSplitOptions.RemoveEmptyEntries);
			ChannelID = Convert.ToInt32(array[0]);
			TypeID = Convert.ToInt32(array[1]);
			AutoValue = Convert.ToInt32(array[2]);
			BatchSize = Convert.ToInt32(array[3]);
		}
	}
	/// <summary>
	/// Job message
	/// </summary>
	public class JobMessage
	{
		private OpenProtocolNet openProtocol;

		/// <summary>
		/// 指定Open协议实例化一个任务消息对象
		/// </summary>
		/// <param name="openProtocol">连接通道</param>
		public JobMessage(OpenProtocolNet openProtocol)
		{
			this.openProtocol = openProtocol;
		}

		/// <summary>
		/// This is a request for a transmission of all the valid Job IDs of the controller. The result of this command is a transmission of all the valid Job IDs.
		/// </summary>
		/// <param name="revision">Revision</param>
		/// <returns>任务ID的列表信息</returns>
		public OResult<int[]> JobIDUpload(int revision = 1)
		{
			OResult<string> oResult = openProtocol.ReadCustomer(30, revision, -1, -1, null);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int[]>(oResult);
			}
			return PraseMID0031(oResult.Content);
		}

		/// <summary>
		/// Request to upload the data for a specific Job from the controller.
		/// </summary>
		/// <param name="id">job id</param>
		/// <returns>任务数据的结果对象</returns>
		public OResult<JobData> JobDataUpload(int id)
		{
			OResult<string> oResult = openProtocol.ReadCustomer(32, 1, -1, -1, new List<string> { id.ToString("D2") });
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<JobData>(oResult);
			}
			return PraseMID0033(oResult.Content);
		}

		/// <summary>
		/// A subscription for the Job info. MID 0035 Job info is sent to the integrator when a new Job is selected and after each tightening performed during the Job.
		/// </summary>
		/// <returns>是否成功的结果对象</returns>
		public OResult JobInfoSubscribe()
		{
			return openProtocol.ReadCustomer(34, 1, -1, -1, null);
		}

		/// <summary>
		/// Reset the subscription for a Job info message.
		/// </summary>
		/// <returns>是否成功的结果对象</returns>
		public OResult JobInfoUnsubscribe()
		{
			return openProtocol.ReadCustomer(37, 1, -1, -1, null);
		}

		/// <summary>
		/// Message to select Job. If the requested ID is not present in the controller, then the command will not be performed.
		/// </summary>
		/// <param name="id">Job ID</param>
		/// <param name="revision">Revision</param>
		/// <returns>是否成功的结果对象</returns>
		public OResult SelectJob(int id, int revision = 1)
		{
			return openProtocol.ReadCustomer(38, revision, -1, -1, new List<string> { (revision == 1) ? id.ToString("D2") : id.ToString("D4") });
		}

		/// <summary>
		/// Job restart message.
		/// </summary>
		/// <param name="id">Job ID</param>
		/// <returns>是否成功的结果对象</returns>
		public OResult JobRestart(int id)
		{
			return openProtocol.ReadCustomer(39, 1, -1, -1, new List<string> { id.ToString("D2") });
		}

		private OResult<int[]> PraseMID0031(string reply)
		{
			try
			{
				int num = ((Convert.ToInt32(reply.Substring(8, 3)) == 1) ? 2 : 4);
				int num2 = Convert.ToInt32(reply.Substring(20, num));
				int[] array = new int[num2];
				for (int i = 0; i < num2; i++)
				{
					array[i] = Convert.ToInt32(reply.Substring(20 + num + i * num, num));
				}
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				return new OResult<int[]>("MID0031 prase failed: " + ex.Message + Environment.NewLine + "Source: " + reply);
			}
		}

		private OResult<JobData> PraseMID0033(string reply)
		{
			try
			{
				JobData jobData = new JobData();
				jobData.JobID = Convert.ToInt32(reply.Substring(22, 2));
				jobData.JobName = reply.Substring(26, 25).Trim();
				jobData.ForcedOrder = Convert.ToInt32(reply.Substring(53, 1));
				jobData.MaxTimeForFirstTightening = Convert.ToInt32(reply.Substring(56, 4));
				jobData.MaxTimeToCompleteJob = Convert.ToInt32(reply.Substring(62, 5));
				jobData.JobBatchMode = Convert.ToInt32(reply.Substring(69, 1));
				jobData.LockAtJobDone = reply[72] == '1';
				jobData.UseLineControl = reply[75] == '1';
				jobData.RepeatJob = reply[78] == '1';
				jobData.ToolLoosening = Convert.ToInt32(reply.Substring(81, 1));
				jobData.Reserved = Convert.ToInt32(reply.Substring(86, 1));
				jobData.JobList = new List<JobItem>();
				int num = Convert.ToInt32(reply.Substring(89, 2));
				for (int i = 0; i < num; i++)
				{
					jobData.JobList.Add(new JobItem(reply.Substring(92 + i * 12, 11)));
				}
				return OResult.CreateSuccessResult(jobData);
			}
			catch (Exception ex)
			{
				return new OResult<JobData>("MID0033 prase failed: " + ex.Message + Environment.NewLine + "Source: " + reply);
			}
		}
	}
	/// <summary>
	/// Open协议的消息对象信息
	/// </summary>
	public class OpenEventArgs : EventArgs
	{
		/// <summary>
		/// Open协议的消息内容
		/// </summary>
		public string Content { get; set; }

		/// <summary>
		/// 接收到的原数据信息
		/// </summary>
		public byte[] RawData { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public OpenEventArgs()
		{
		}

		/// <summary>
		/// 指定Open的消息来实例化对象
		/// </summary>
		/// <param name="content">Open内容</param>
		public OpenEventArgs(byte[] content)
		{
			RawData = content;
			Content = Encoding.ASCII.GetString(content).TrimEnd('\0');
		}

		/// <summary>
		/// 指定Open的消息来实例化对象
		/// </summary>
		/// <param name="content">Open内容</param>
		public OpenEventArgs(string content)
		{
			Content = content;
		}
	}
	/// <summary>
	/// 开放以太网协议，在拧紧枪中应用广泛，本通信支持基本的问答机制以及订阅机制，支持完全自定义的参数指定及数据读取。<br />
	/// Open Ethernet protocol, widely used in tightening guns, this communication supports basic question answering mechanism and subscription mechanism, supports fully customized parameter specification and data reading.
	/// </summary>
	/// <remarks>
	/// 自定义的读取使用<see cref="M:Snet.Driver.Profinet.OpenProtocol.OpenProtocolNet.ReadCustomer(System.Int32,System.Int32,System.Int32,System.Int32,System.Collections.Generic.List{System.String})" />来实现，如果是订阅的数据，使用<see cref="E:Snet.Driver.Profinet.OpenProtocol.OpenProtocolNet.OnReceivedOpenMessage" />绑定自己的方法触发。更详细的示例参考：http://api.Snetcommunication.cn<br />
	/// Custom reads are implemented using <see cref="M:Snet.Driver.Profinet.OpenProtocol.OpenProtocolNet.ReadCustomer(System.Int32,System.Int32,System.Int32,System.Int32,System.Collections.Generic.List{System.String})" />, and if it is subscribed data, use <see cref="E:Snet.Driver.Profinet.OpenProtocol.OpenProtocolNet.OnReceivedOpenMessage" /> 
	/// bind your own method to trigger it. For a more detailed example, refer to: http://api.Snetcommunication.cn
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OpenProtocolNetSample.cs" region="Usage" title="连接及自定义读取使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OpenProtocolNetSample.cs" region="Usage2" title="便捷的读取示例" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OpenProtocolNetSample.cs" region="Usage3" title="订阅事件处理操作" />
	/// </example>
	public class OpenProtocolNet : TcpNetCommunication
	{
		private Timer timer;

		private ParameterSetMessages parameterSetMessages;

		private JobMessage jobMessage;

		private TighteningResultMessages tighteningResultMessages;

		private ToolMessages toolMessages;

		private TimeMessages timeMessages;

		private int revisonOnConnected;

		/// <summary>
		/// 获取或设置当前 MID 9999 的心跳命令是否生效，默认为 <c>True</c><br />
		/// Get or set the current MID 9999's heartbeat command that is in effect, defaulting to <c>True</c>
		/// </summary>
		public bool KeepAliveMessageEnable { get; set; } = true;

		/// <summary>
		/// 额外的用于订阅的MID信息，并且指定返回的MID信息<br />
		/// Additional MID information for subscription, and specifying the returned MID information
		/// </summary>
		public ExtraSubscribeMid[] ExtraSubscribeMID { get; set; }

		/// <summary>
		/// 获取或设置初始化连接时 MID0001 命令的版本号，默认为 1，如果设置小于 0，则表示不发送 MID0001 命令。<br />
		/// Get or set the version of the MID0001 command when initializing the connection, the default is 1, if the setting is less than 0, it means that the MID0001 command is not sent.
		/// </summary>
		/// <remarks>
		/// 当连接的设备是 MT Focus 6000的控制器时，本值需要设置为 6
		/// </remarks>
		public int RevisonOnConnected
		{
			get
			{
				return revisonOnConnected;
			}
			set
			{
				revisonOnConnected = value;
			}
		}

		/// <summary>
		/// 针对控制器的主动发送的消息，是否无视<c>Ack</c>标记，全部进行返回信号操作，默认为 <c>False</c>，将根据报文里的<c>Ack</c>信号来决定是否返回数据<br />
		/// If the default value is <c>False</c>, the controller will<c></c> decide whether to return data based on the <c>Ack</c> signal in the packet
		/// </summary>
		public bool AutoAckControllerMessage { get; set; }

		/// <summary>
		/// 参数集合操作的相关属性，可以用来获取参数ID列表，设置数据等操作。<br />
		/// The properties related to parameter collection operations can be used to obtain parameter ID lists, set data, and other operations.
		/// </summary>
		public ParameterSetMessages ParameterSetMessages => parameterSetMessages;

		/// <summary>
		/// 任务消息的相关属性，可以用来获取任务的数据，订阅任务，取消订阅任务，选择任务，启动任务。<br />
		/// The relevant properties of task messages can be used to obtain task data, subscribe to tasks, unsubscribe tasks, select tasks, and start tasks.
		/// </summary>
		public JobMessage JobMessage => jobMessage;

		/// <summary>
		/// 拧紧结果消息的操作属性
		/// </summary>
		public TighteningResultMessages TighteningResultMessages => tighteningResultMessages;

		/// <summary>
		/// 工具消息的操作属性
		/// </summary>
		public ToolMessages ToolMessages => toolMessages;

		/// <summary>
		/// 时间消息的属性
		/// </summary>
		public TimeMessages TimeMessages => timeMessages;

		/// <summary>
		/// 当接收到OpenProtocol协议消息触发的事件
		/// </summary>
		public event EventHandler<OpenEventArgs> OnReceivedOpenMessage;

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public OpenProtocolNet()
		{
			revisonOnConnected = 1;
			CommunicationPipe.UseServerActivePush = true;
			timer = new Timer(ThreadKeepAlive, null, 10000, 10000);
			parameterSetMessages = new ParameterSetMessages(this);
			jobMessage = new JobMessage(this);
			tighteningResultMessages = new TighteningResultMessages(this);
			toolMessages = new ToolMessages(this);
			timeMessages = new TimeMessages(this);
			LogMsgFormatBinary = false;
		}

		/// <summary>
		/// 使用指定的IP地址及端口来初始化对象<br />
		/// Use the specified IP address and port to initialize the object
		/// </summary>
		/// <param name="ipAddress">Ip地址</param>
		/// <param name="port">端口号</param>
		public OpenProtocolNet(string ipAddress, int port = 4545)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new OpenProtocolMessage();
		}

		private void ThreadKeepAlive(object state)
		{
			if (!CommunicationPipe.IsConnectError() && KeepAliveMessageEnable)
			{
				OResult<byte[]> oResult = BuildReadCommand(9999, 1, -1, -1, null);
				if (oResult.IsSuccess)
				{
					CommunicationPipe.Send(oResult.Content);
				}
			}
		}

		/// <summary>
		/// 设置额外的用于订阅的MID信息，并且指定返回的MID信息，格式为 "mid1-replyMid1;mid2-replyMid2;mid3;mid4"，如果不指定返回的MID，则回复的MID通常是当前MID+1<br />
		/// </summary>
		/// <param name="mids">订阅的消息</param>
		public void SetExtraSubscribeMID(string mids)
		{
			if (string.IsNullOrEmpty(mids))
			{
				ExtraSubscribeMID = null;
				return;
			}
			string[] source = mids.Split(new char[2] { ';', ',' }, StringSplitOptions.RemoveEmptyEntries);
			ExtraSubscribeMID = source.Select(delegate(string m)
			{
				if (m.Contains('-'))
				{
					string[] array = m.Split(new char[1] { '-' }, StringSplitOptions.RemoveEmptyEntries);
					if (array.Length == 2)
					{
						int mid = Convert.ToInt32(array[0]);
						int replyMid = Convert.ToInt32(array[1]);
						return new ExtraSubscribeMid
						{
							Mid = mid,
							ReplyMid = replyMid
						};
					}
					return (ExtraSubscribeMid)null;
				}
				int num = Convert.ToInt32(m);
				return new ExtraSubscribeMid
				{
					Mid = num,
					ReplyMid = num + 1
				};
			}).ToArray();
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			CommunicationPipe.UseServerActivePush = true;
			if (revisonOnConnected >= 0)
			{
				OResult<byte[]> oResult = BuildReadCommand(1, revisonOnConnected, -1, -1, null);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult);
				}
				OResult oResult2 = CommunicationPipe.Send(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult2);
				}
				OResult<byte[]> oResult3 = CommunicationPipe.ReceiveMessage(GetNewNetMessage(), null, useActivePush: false);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<string>("InitializationOnConnect failed", oResult3);
				}
				string text = Encoding.ASCII.GetString(oResult3.Content);
				if (text.Substring(4, 4) == "0002")
				{
					return base.InitializationOnConnect();
				}
				return new OResult("Failed:" + text.Substring(4, 4));
			}
			return base.InitializationOnConnect();
		}

		/// <inheritdoc />
		protected override OResult ExtraOnDisconnect()
		{
			OResult<byte[]> oResult = BuildReadCommand(3, 1, -1, -1, null);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			return ReadFromCoreServer(CommunicationPipe, oResult.Content, hasResponseData: true, usePackAndUnpack: true);
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			CommunicationPipe.UseServerActivePush = true;
			if (revisonOnConnected >= 0)
			{
				OResult<byte[]> oResult = BuildReadCommand(1, revisonOnConnected, -1, -1, null);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult);
				}
				OResult oResult2 = await CommunicationPipe.SendAsync(oResult.Content).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult2);
				}
				OResult<byte[]> oResult3 = await CommunicationPipe.ReceiveMessageAsync(GetNewNetMessage(), null, useActivePush: false).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<string>("InitializationOnConnect failed", oResult3);
				}
				string text = Encoding.ASCII.GetString(oResult3.Content);
				if (text.Substring(4, 4) == "0002")
				{
					return await base.InitializationOnConnectAsync();
				}
				return new OResult("Failed:" + text.Substring(4, 4));
			}
			return await base.InitializationOnConnectAsync();
		}

		/// <summary>
		/// 根据传入的MID来决定是用于订阅的消息ID，如果是订阅的ID，通常返回id+1
		/// </summary>
		/// <param name="mid">当前的mid号</param>
		/// <returns>如果是订阅的，请返回实际需要返回的id</returns>
		protected virtual int DecideSubscribeData(int mid)
		{
			if (ExtraSubscribeMID != null)
			{
				for (int i = 0; i < ExtraSubscribeMID.Length; i++)
				{
					if (ExtraSubscribeMID[i].Mid == mid)
					{
						if (ExtraSubscribeMID[i].ReplyMid <= 0)
						{
							return mid + 1;
						}
						return ExtraSubscribeMID[i].ReplyMid;
					}
				}
			}
			switch (mid)
			{
			case 15:
			case 35:
			case 52:
			case 61:
			case 71:
			case 74:
			case 76:
			case 91:
			case 101:
				return mid + 1;
			case 106:
			case 107:
				return 108;
			case 121:
			case 122:
			case 123:
			case 124:
				return 125;
			case 152:
				return 153;
			case 211:
				return 212;
			case 217:
				return 218;
			case 221:
				return 222;
			case 242:
				return 243;
			case 251:
				return 252;
			case 401:
				return 402;
			case 421:
				return 422;
			default:
				return -1;
			}
		}

		/// <inheritdoc />
		protected override bool DecideWhetherQAMessage(CommunicationPipe pipe, OResult<byte[]> receive)
		{
			if (receive.Content.Length >= 20)
			{
				int num = Convert.ToInt32(Encoding.ASCII.GetString(receive.Content, 4, 4));
				bool flag = receive.Content[11] == 48;
				if (num == 9999)
				{
					return false;
				}
				int num2 = DecideSubscribeData(num);
				if (num2 > 0)
				{
					if (flag || AutoAckControllerMessage)
					{
						pipe.Send(BuildReadCommand(num2, 1, -1, -1, null).Content);
					}
					OnReceivedOpenMessage?.Invoke(this, new OpenEventArgs(receive.Content));
					return false;
				}
			}
			return base.DecideWhetherQAMessage(pipe, receive);
		}

		/// <summary>
		/// 使用自定义的命令读取数据，需要指定每个参数信息，然后返回字符串数据内容，根据实际的功能码，解析出实际的数据信息<br />
		/// To use a custom command to read data, you need to specify each parameter information, then return the string data content, and parse the actual data information according to the actual function code
		/// </summary>
		/// <param name="mid">The MID is four bytes long and is specified by four ASCII digits(‘0’…’9’). The MID describes how to interpret the message.</param>
		/// <param name="revison">The revision of the MID is specified by three ASCII digits(‘0’…’9’).The MID revision is unique per MID and is used in case several versions are available for the same MID. </param>
		/// <param name="stationId">The station the message is addressed to in the case of controller with multi-station configuration.The station ID is 1 byte long and is specified by one ASCII digit(‘0’…’9’). </param>
		/// <param name="spindleId">The spindle the message is addressed to in the case several spindles are connected to the same controller. The spindle ID is 2 bytes long and is specified by two ASCII digits (‘0’…’9’). </param>
		/// <param name="parameters">The Data Field is ASCII data representing the data. The data contains a list of parameters depending on the MID.Each parameter is represented with an ID and the parameter value. </param>
		/// <returns>结果数据信息</returns>
		public OResult<string> ReadCustomer(int mid, int revison, int stationId, int spindleId, List<string> parameters)
		{
			if (parameters == null)
			{
				parameters = new List<string>();
			}
			OResult<byte[]> oResult = BuildReadCommand(mid, revison, stationId, spindleId, parameters);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			OResult oResult3 = CheckRequestReplyMessages(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult2.Content));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.OpenProtocol.OpenProtocolNet.ReadCustomer(System.Int32,System.Int32,System.Int32,System.Int32,System.Collections.Generic.List{System.String})" />
		public async Task<OResult<string>> ReadCustomerAsync(int mid, int revison, int stationId, int spindleId, List<string> parameters)
		{
			if (parameters == null)
			{
				parameters = new List<string>();
			}
			OResult<byte[]> oResult = BuildReadCommand(mid, revison, stationId, spindleId, parameters);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			OResult oResult3 = CheckRequestReplyMessages(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult2.Content));
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"OpenProtocolNet[{IpAddress}:{Port}]";
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.OpenProtocol.OpenProtocolNet.BuildOpenProtocolMessage(System.Int32,System.Int32,System.Int32,System.Int32,System.Int32,System.Boolean,System.String[])" />
		public static OResult<byte[]> BuildReadCommand(int mid, int revison, int stationId, int spindleId, List<string> parameters)
		{
			if (mid < 0 || mid > 9999)
			{
				return new OResult<byte[]>("Mid must be between 0 - 9999");
			}
			if (revison < 0 || revison > 999)
			{
				return new OResult<byte[]>("revison must be between 0 - 999");
			}
			if (stationId > 9)
			{
				return new OResult<byte[]>("stationId must be between 0 - 9");
			}
			if (spindleId > 99)
			{
				return new OResult<byte[]>("spindleId must be between 0 - 99");
			}
			int count = 0;
			parameters?.ForEach(delegate(string m)
			{
				count += m.Length;
			});
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append((20 + count).ToString("D4"));
			stringBuilder.Append(mid.ToString("D4"));
			stringBuilder.Append(revison.ToString("D3"));
			stringBuilder.Append('0');
			stringBuilder.Append((stationId < 0) ? "  " : stationId.ToString("D2"));
			stringBuilder.Append((spindleId < 0) ? "  " : spindleId.ToString("D2"));
			stringBuilder.Append(' ');
			stringBuilder.Append(' ');
			stringBuilder.Append(' ');
			stringBuilder.Append(' ');
			if (parameters != null)
			{
				for (int num = 0; num < parameters.Count; num++)
				{
					stringBuilder.Append(parameters[num]);
				}
			}
			stringBuilder.Append('\0');
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 构建一个读取的初始报文
		/// </summary>
		/// <param name="mid">The MID is four bytes long and is specified by four ASCII digits(‘0’…’9’). The MID describes how to interpret the message.</param>
		/// <param name="revison">The revision of the MID is specified by three ASCII digits(‘0’…’9’).The MID revision is unique per MID and is used in case several versions are available for the same MID. </param>
		/// <param name="ack">The No Ack Flag is used when setting a subscription. If the No Ack flag is not set in a subscription it means that the subscriber will acknowledge each “push” message sent by the controller (reliable mode).</param>
		/// <param name="stationId">The station the message is addressed to in the case of controller with multi-station configuration.The station ID is 1 byte long and is specified by one ASCII digit(‘0’…’9’). </param>
		/// <param name="spindleId">The spindle the message is addressed to in the case several spindles are connected to the same controller. The spindle ID is 2 bytes long and is specified by two ASCII digits (‘0’…’9’). </param>
		/// <param name="withIndex">每个参数的前面，是否携带索引信息</param>
		/// <param name="parameters">The Data Field is ASCII data representing the data. The data contains a list of parameters depending on the MID.Each parameter is represented with an ID and the parameter value. </param>
		/// <returns>原始字节的报文信息</returns>
		public static OResult<byte[]> BuildOpenProtocolMessage(int mid, int revison, int ack, int stationId, int spindleId, bool withIndex, params string[] parameters)
		{
			if (mid < 0 || mid > 9999)
			{
				return new OResult<byte[]>("Mid must be between 0 - 9999");
			}
			if (revison < 0 || revison > 999)
			{
				return new OResult<byte[]>("revison must be between 0 - 999");
			}
			if (stationId > 9)
			{
				return new OResult<byte[]>("stationId must be between 0 - 9");
			}
			if (spindleId > 99)
			{
				return new OResult<byte[]>("spindleId must be between 0 - 99");
			}
			int num = 0;
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(mid.ToString("D4"));
			stringBuilder.Append(revison.ToString("D3"));
			stringBuilder.Append((ack < 0) ? " " : ack.ToString("D1"));
			stringBuilder.Append((stationId < 0) ? "  " : stationId.ToString("D2"));
			stringBuilder.Append((spindleId < 0) ? "  " : spindleId.ToString("D2"));
			stringBuilder.Append(' ');
			stringBuilder.Append(' ');
			stringBuilder.Append(' ');
			stringBuilder.Append(' ');
			if (parameters != null)
			{
				for (int i = 0; i < parameters.Length; i++)
				{
					if (withIndex)
					{
						stringBuilder.Append((i + 1).ToString("D2"));
						stringBuilder.Append(parameters[i]);
						num += 2 + parameters[i].Length;
					}
					else
					{
						stringBuilder.Append(parameters[i]);
						num += parameters[i].Length;
					}
				}
			}
			stringBuilder.Append('\0');
			stringBuilder.Insert(0, (20 + num).ToString("D4"));
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

