		/// <summary>
		/// Read time request.
		/// </summary>
		/// <returns>包含时间的结果对象</returns>
		public OResult<DateTime> ReadTimeUpload()
		{
			OResult<string> oResult = openProtocol.ReadCustomer(80, 1, -1, -1, null);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<DateTime>(oResult);
			}
			return OResult.CreateSuccessResult(DateTime.ParseExact(oResult.Content.Substring(20, 19), "yyyy-MM-dd:HH:mm:ss", null));
		}

