	/// <summary>
	/// 工具类消息
	/// </summary>
	public class ToolMessages
	{
		private OpenProtocolNet openProtocol;

		/// <summary>
		/// 指定Open通信来实例化一个工具类消息的对象
		/// </summary>
		/// <param name="openProtocol">工具类消息</param>
		public ToolMessages(OpenProtocolNet openProtocol)
		{
			this.openProtocol = openProtocol;
		}

		/// <summary>
		/// A request for some of the data stored in the tool. The result of this command is the transmission of the tool data.
		/// </summary>
		/// <param name="revision">Revision</param>
		/// <returns>工具数据的结果对象</returns>
		public OResult<ToolData> ToolDataUpload(int revision = 1)
		{
			OResult<string> oResult = openProtocol.ReadCustomer(40, revision, -1, -1, null);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<ToolData>(oResult);
			}
			return PraseMID0041(oResult.Content);
		}

		/// <summary>
		/// Disable tool.
		/// </summary>
		/// <returns>是否成功的结果对象</returns>
		public OResult DisableTool()
		{
			return openProtocol.ReadCustomer(42, 1, -1, -1, null);
		}

		/// <summary>
		/// Enable tool
		/// </summary>
		/// <returns>是否成功的结果对象</returns>
		public OResult EnableTool()
		{
			return openProtocol.ReadCustomer(43, 1, -1, -1, null);
		}

		/// <summary>
		/// This command is sent by the integrator in order to request the possibility to disconnect the tool from the controller.The command is rejected if the tool is currently used.
		/// </summary>
		/// <returns>是否成功的结果对象</returns>
		public OResult DisconnectToolRequest()
		{
			return openProtocol.ReadCustomer(44, 1, -1, -1, null);
		}

		/// <summary>
		/// This message is sent by the integrator in order to set the calibration value of the tool.
		/// </summary>
		/// <param name="calibrationValueUnit">The unit in which the calibration value is sent. 1=Nm, 2=Lbf.ft, 3=Lbf.In, 4=Kpm</param>
		/// <param name="calibrationValue">The calibration value</param>
		/// <returns>是否成功的结果对象</returns>
		public OResult SetCalibrationValueRequest(int calibrationValueUnit, double calibrationValue)
		{
			string item = "01" + calibrationValueUnit;
			string item2 = "02" + Convert.ToInt32(calibrationValue * 100.0).ToString("D6");
			return openProtocol.ReadCustomer(45, 1, -1, -1, new List<string> { item, item2 });
		}

		private OResult<ToolData> PraseMID0041(string reply)
		{
			try
			{
				int num = Convert.ToInt32(reply.Substring(8, 3));
				ToolData toolData = new ToolData
				{
					ToolSerialNumber = reply.Substring(22, 14),
					ToolNumberOfTightening = Convert.ToUInt32(reply.Substring(38, 10)),
					LastCalibrationDate = DateTime.ParseExact(reply.Substring(50, 19), "yyyy-MM-dd:HH:mm:ss", null),
					ControllerSerialNumber = reply.Substring(71, 10)
				};
				if (num > 1)
				{
					toolData.CalibrationValue = Convert.ToDouble(reply.Substring(83, 6)) / 100.0;
					toolData.LastServiceDate = DateTime.ParseExact(reply.Substring(91, 19), "yyyy-MM-dd:HH:mm:ss", null);
					toolData.TighteningsSinceService = Convert.ToUInt32(reply.Substring(112, 10));
					toolData.ToolType = Convert.ToInt32(reply.Substring(124, 2));
					toolData.MotorSize = Convert.ToInt32(reply.Substring(128, 2));
					toolData.UseOpenEnd = reply[132] == '1';
					toolData.TighteningDirection = ((reply[133] == '1') ? "CCW" : "CW");
					toolData.MotorRotation = Convert.ToInt32(reply.Substring(134, 1));
					toolData.ControllerSoftwareVersion = reply.Substring(137, 19);
				}
				return OResult.CreateSuccessResult(toolData);
			}
			catch (Exception ex)
			{
				return new OResult<ToolData>("MID0031 prase failed: " + ex.Message + Environment.NewLine + "Source: " + reply);
			}
		}
	}
}
namespace Snet.Driver.Profinet.Omron
{
	/// <summary>
	/// 欧姆龙PLC的CIP协议的类，支持NJ,NX,NY系列PLC，支持tag名的方式读写数据，假设你读取的是局部变量，那么使用 Program:MainProgram.变量名<br />
	/// Omron PLC's CIP protocol class, support NJ, NX, NY series PLC, support tag name read and write data, assuming you read local variables, then use Program: MainProgram. Variable name
	/// </summary>
	public class OmronCipNet : AllenBradleyNet
	{
		/// <summary>
		/// Instantiate a communication object for a OmronCipNet PLC protocol
		/// </summary>
		public OmronCipNet()
		{
		}

		/// <summary>
		/// Specify the IP address and port to instantiate a communication object for a OmronCipNet PLC protocol
		/// </summary>
		/// <param name="ipAddress">PLC IpAddress</param>
		/// <param name="port">PLC Port</param>
		public OmronCipNet(string ipAddress, int port = 44818)
			: base(ipAddress, port)
		{
		}

		private bool CheckAddressArrayTag(string address)
		{
			return Regex.IsMatch(address, "\\[[0-9]+\\]$");
		}

		/// <inheritdoc />
		protected override bool GetBoolWritePadding()
		{
			return true;
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			if (length > 1)
			{
				if (CheckAddressArrayTag(address))
				{
					return Read(new string[1] { address }, new ushort[1] { length });
				}
				return Read(new string[1] { address }, new ushort[1] { 1 });
			}
			return Read(new string[1] { address }, new ushort[1] { length });
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (address.StartsWith("i="))
			{
				return base.ReadBool(address, length);
			}
			OResult<byte[]> oResult = Read(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (CheckAddressArrayTag(address))
			{
				return OResult.CreateSuccessResult(oResult.Content.Select((byte m) => m != 0).Take(length).ToArray());
			}
			return OResult.CreateSuccessResult(SoftBasic.ByteToBoolArray(oResult.Content, length));
		}

		/// <inheritdoc />
		public override OResult<string> ReadString(string address, ushort length, Encoding encoding)
		{
			OResult<byte[]> oResult = Read(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			try
			{
				int count = base.ByteTransform.TransUInt16(oResult.Content, 0);
				return OResult.CreateSuccessResult(encoding.GetString(oResult.Content, 2, count));
			}
			catch (Exception ex)
			{
				return new OResult<string>("Parse failed: " + ex.Message + Environment.NewLine + "Source: " + oResult.Content.ToHexString(' '));
			}
		}

		/// <inheritdoc />
		protected override int GetWriteValueLength(string address, int length)
		{
			if (CheckAddressArrayTag(address))
			{
				return length;
			}
			return 1;
		}

		/// <inheritdoc />
		public override OResult<T> ReadStruct<T>(string address, ushort length)
		{
			return ReadWriteNetHelper.ReadStruct<T>(this, address, length, base.ByteTransform, 2);
		}

		/// <inheritdoc />
		public override OResult Write(string address, string value, Encoding encoding)
		{
			if (string.IsNullOrEmpty(value))
			{
				value = string.Empty;
			}
			byte[] array = SoftBasic.SpliceArray<byte>(new byte[2], SoftBasic.ArrayExpandToLengthEven(encoding.GetBytes(value)));
			array[0] = BitConverter.GetBytes(array.Length - 2)[0];
			array[1] = BitConverter.GetBytes(array.Length - 2)[1];
			return WriteTag(address, 208, array);
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte value)
		{
			return WriteTag(address, 209, new byte[1] { value });
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronCipNet.Read(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			if (length > 1)
			{
				if (CheckAddressArrayTag(address))
				{
					return await ReadAsync(new string[1] { address }, new ushort[1] { length });
				}
				return await ReadAsync(new string[1] { address }, new ushort[1] { 1 });
			}
			return await ReadAsync(new string[1] { address }, new ushort[1] { length });
		}

		/// <inheritdoc />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			if (address.StartsWith("i="))
			{
				return await base.ReadBoolAsync(address, length);
			}
			OResult<byte[]> oResult = await ReadAsync(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (CheckAddressArrayTag(address))
			{
				return OResult.CreateSuccessResult(oResult.Content.Select((byte m) => m != 0).Take(length).ToArray());
			}
			return OResult.CreateSuccessResult(SoftBasic.ByteToBoolArray(oResult.Content, length));
		}

		/// <inheritdoc />
		public override async Task<OResult<string>> ReadStringAsync(string address, ushort length, Encoding encoding)
		{
			OResult<byte[]> oResult = await ReadAsync(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			try
			{
				return OResult.CreateSuccessResult(encoding.GetString(count: base.ByteTransform.TransUInt16(oResult.Content, 0), bytes: oResult.Content, index: 2));
			}
			catch (Exception ex)
			{
				return new OResult<string>("Parse failed: " + ex.Message + Environment.NewLine + "Source: " + oResult.Content.ToHexString(' '));
			}
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, string value, Encoding encoding)
		{
			if (string.IsNullOrEmpty(value))
			{
				value = string.Empty;
			}
			byte[] array = SoftBasic.SpliceArray<byte>(new byte[2], SoftBasic.ArrayExpandToLengthEven(encoding.GetBytes(value)));
			array[0] = BitConverter.GetBytes(array.Length - 2)[0];
			array[1] = BitConverter.GetBytes(array.Length - 2)[1];
			return await WriteTagAsync(address, 208, array);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronCipNet.Write(System.String,System.Byte)" />
		public override async Task<OResult> WriteAsync(string address, byte value)
		{
			return await WriteTagAsync(address, 209, new byte[1] { value });
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"OmronCipNet[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 欧姆龙的CIP虚拟服务器
	/// </summary>
	public class OmronCipServer : AllenBradleyServer
	{
		/// <inheritdoc />
		public override void AddTagValue(string key, string value, int maxLength)
		{
			byte[] bytes = Encoding.UTF8.GetBytes(value);
			AddTagValue(key, new AllenBradleyItemValue
			{
				IsArray = false,
				Buffer = SoftBasic.ArrayExpandToLength(SoftBasic.SpliceArray<byte>(BitConverter.GetBytes((ushort)bytes.Length), Encoding.UTF8.GetBytes(value)), maxLength),
				TypeLength = maxLength,
				TypeCode = 208
			});
		}

		/// <inheritdoc />
		public override void AddTagValue(string key, string[] value, int maxLength)
		{
			byte[] array = new byte[maxLength * value.Length];
			for (int i = 0; i < value.Length; i++)
			{
				byte[] bytes = Encoding.UTF8.GetBytes(value[i]);
				BitConverter.GetBytes((ushort)bytes.Length).CopyTo(array, maxLength * i);
				bytes.CopyTo(array, maxLength * i + 2);
			}
			AddTagValue(key, new AllenBradleyItemValue
			{
				IsArray = true,
				Buffer = array,
				TypeLength = maxLength,
				TypeCode = 208
			});
		}

		/// <inheritdoc />
		public override OResult<string> ReadString(string address, ushort length, Encoding encoding)
		{
			OResult<byte[]> oResult = Read(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			if (oResult.Content.Length >= 2)
			{
				int count = BitConverter.ToUInt16(oResult.Content, 0);
				return OResult.CreateSuccessResult(encoding.GetString(oResult.Content, 2, count));
			}
			return OResult.CreateSuccessResult(encoding.GetString(oResult.Content));
		}

		/// <inheritdoc />
		public override OResult Write(string address, string value, Encoding encoding)
		{
			if (IsNeedCreateTag(address))
			{
				AddTagValue(address, value, 1024);
				return OResult.CreateSuccessResult();
			}
			bool flag = false;
			int addressIndex = GetAddressIndex(ref address);
			simpleHybird.Enter();
			if (abValues.ContainsKey(address))
			{
				flag = true;
				AllenBradleyItemValue allenBradleyItemValue = abValues[address];
				byte[] buffer = allenBradleyItemValue.Buffer;
				if (buffer != null && buffer.Length >= 2)
				{
					byte[] bytes = encoding.GetBytes(value);
					BitConverter.GetBytes((ushort)bytes.Length).CopyTo(allenBradleyItemValue.Buffer, addressIndex * allenBradleyItemValue.TypeLength);
					if (bytes.Length != 0)
					{
						Array.Copy(bytes, 0, allenBradleyItemValue.Buffer, 2 + addressIndex * allenBradleyItemValue.TypeLength, Math.Min(bytes.Length, allenBradleyItemValue.Buffer.Length - 2));
					}
				}
			}
			simpleHybird.Leave();
			if (!flag)
			{
				return new OResult<bool>(StringResources.Language.AllenBradley04);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override byte[] ReadByCommand(PipeSession session, byte[] cipCore)
		{
			if (session.Tag is string)
			{
				return base.ReadByCommand(session, cipCore);
			}
			byte[] array = base.ByteTransform.TransByte(cipCore, 2, cipCore[1] * 2);
			string text = AllenBradleyHelper.ParseRequestPathCommand(array);
			OResult<byte[], ushort> oResult = null;
			if (session.Tag is CipSessionTag { IsConnectedCIP: not false })
			{
				ushort length = BitConverter.ToUInt16(cipCore, 2 + array.Length);
				oResult = ReadWithType(text, length);
			}
			else if (Regex.IsMatch(text, "\\[[0-9]+\\]$"))
			{
				ushort length2 = BitConverter.ToUInt16(cipCore, 2 + array.Length);
				oResult = ReadWithType(text, length2);
			}
			else
			{
				oResult = ReadWithType(text, -1);
			}
			AllenBradleyItemValue addressItemValue = GetAddressItemValue(text);
			byte[] array2;
			if (addressItemValue != null && addressItemValue.TypeCode == 193 && addressItemValue.IsArray)
			{
				array2 = AllenBradleyHelper.PackCommandResponse(oResult.Content1, isRead: true);
			}
			else if (addressItemValue == null)
			{
				array2 = new byte[4] { 204, 0, 5, 0 };
			}
			else if (addressItemValue.TypeCode == 208)
			{
				if (oResult.Content1.Length >= 2)
				{
					int num = BitConverter.ToUInt16(oResult.Content1, 0);
					if (num + 2 > oResult.Content1.Length)
					{
						num = oResult.Content1.Length - 2;
					}
					array2 = AllenBradleyHelper.PackCommandResponse(oResult.Content1.SelectBegin(num + 2), isRead: true);
				}
				else
				{
					array2 = AllenBradleyHelper.PackCommandResponse(oResult.Content1, isRead: true);
				}
			}
			else
			{
				array2 = AllenBradleyHelper.PackCommandResponse(oResult.Content1, isRead: true);
			}
			if (array2.Length > 6)
			{
				BitConverter.GetBytes(oResult.Content2).CopyTo(array2, 4);
			}
			return array2;
		}

		/// <inheritdoc />
		protected override byte[] WriteByMessage(byte[] cipCore)
		{
			if (!base.EnableWrite)
			{
				return AllenBradleyHelper.PackCommandResponse(null, isRead: false);
			}
			byte[] array = base.ByteTransform.TransByte(cipCore, 2, cipCore[1] * 2);
			string address = AllenBradleyHelper.ParseRequestPathCommand(array);
			ushort num = BitConverter.ToUInt16(cipCore, 2 + array.Length);
			ushort num2 = BitConverter.ToUInt16(cipCore, 4 + array.Length);
			byte[] array2 = base.ByteTransform.TransByte(cipCore, 6 + array.Length, cipCore.Length - 6 - array.Length);
			AllenBradleyItemValue addressItemValue = GetAddressItemValue(address);
			if (addressItemValue != null && addressItemValue.TypeCode == 193 && addressItemValue.IsArray)
			{
				if (num2 == 1)
				{
					bool value = false;
					if (array2.Length == 2 && array2[0] == byte.MaxValue && array2[1] == byte.MaxValue)
					{
						value = true;
					}
					if (Write(address, value).IsSuccess)
					{
						return AllenBradleyHelper.PackCommandResponse(new byte[0], isRead: false);
					}
					return AllenBradleyHelper.PackCommandResponse(null, isRead: false);
				}
				if (Write(address, array2.SelectBegin(addressItemValue.Buffer.Length)).IsSuccess)
				{
					return AllenBradleyHelper.PackCommandResponse(new byte[0], isRead: false);
				}
				return AllenBradleyHelper.PackCommandResponse(null, isRead: false);
			}
			if (addressItemValue == null)
			{
				return new byte[4] { 205, 0, 5, 0 };
			}
			if (addressItemValue.TypeCode == 208 && num == 208)
			{
				if (array2.Length < 2)
				{
					return AllenBradleyHelper.PackCommandResponse(null, isRead: false);
				}
				int num3 = BitConverter.ToUInt16(array2, 0);
				int num4 = 2 + num3 - 1;
				while (num4 >= 2 && array2[num4] == 0)
				{
					num3--;
					num4--;
				}
				if (Write(address, Encoding.UTF8.GetString(array2, 2, num3), Encoding.UTF8).IsSuccess)
				{
					return AllenBradleyHelper.PackCommandResponse(new byte[0], isRead: false);
				}
				return AllenBradleyHelper.PackCommandResponse(null, isRead: false);
			}
			if (num == 193 && num2 == 1)
			{
				bool value2 = false;
				if (array2.Length == 2 && array2[0] == byte.MaxValue && array2[1] == byte.MaxValue)
				{
					value2 = true;
				}
				if (Write(address, value2).IsSuccess)
				{
					return AllenBradleyHelper.PackCommandResponse(new byte[0], isRead: false);
				}
				return AllenBradleyHelper.PackCommandResponse(null, isRead: false);
			}
			OResult oResult = Write(address, array2);
			if (!oResult.IsSuccess)
			{
				return new byte[4]
				{
					205,
					0,
					BitConverter.GetBytes(oResult.ErrorCode)[0],
					BitConverter.GetBytes(oResult.ErrorCode)[1]
				};
			}
			return new byte[4] { 205, 0, 0, 0 };
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"OmronCipServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 基于连接的对象访问的CIP协议的实现，用于对Omron PLC进行标签的数据读写，对数组，多维数组进行读写操作，支持的数据类型请参照API文档手册。<br />
	/// The implementation of the CIP protocol based on connected object access is used to read and write tag data to Omron PLC, 
	/// and read and write arrays and multidimensional arrays. For the supported data types, please refer to the API documentation manual.
	/// </summary>
	/// <remarks>
	/// 支持普通标签的读写，类型要和标签对应上。如果标签是数组，例如 A 是 INT[0...9] 那么Read("A", 1)，返回的是10个short所有字节数组。
	/// 如果需要返回10个长度的short数组，请调用 ReadInt16("A[0], 10"); 地址必须写 "A[0]"，不能写 "A" , 如需要读取结构体，参考 <see cref="M:Snet.Driver.Profinet.Omron.OmronConnectedCipNet.ReadStruct``1(System.String)" />
	/// </remarks>
	/// <example>
	/// 首先说明支持的类型地址，在PLC里支持了大量的类型，有些甚至在C#里是不存在的。现在做个统一的声明
	/// <list type="table">
	///   <listheader>
	///     <term>PLC类型</term>
	///     <term>含义</term>
	///     <term>代号</term>
	///     <term>C# 类型</term>
	///     <term>备注</term>
	///   </listheader>
	///   <item>
	///     <term>bool</term>
	///     <term>位类型数据</term>
	///     <term>0xC1</term>
	///     <term>bool</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>SINT</term>
	///     <term>8位的整型</term>
	///     <term>0xC2</term>
	///     <term>sbyte</term>
	///     <term>有符号8位很少用，Snet直接用byte</term>
	///   </item>
	///   <item>
	///     <term>USINT</term>
	///     <term>无符号8位的整型</term>
	///     <term>0xC6</term>
	///     <term>byte</term>
	///     <term>如需要，使用<see cref="M:Snet.Driver.Profinet.Omron.OmronConnectedCipNet.WriteTag(System.String,System.UInt16,System.Byte[],System.Int32)" />实现</term>
	///   </item>
	///   <item>
	///     <term>BYTE</term>
	///     <term>8位字符数据</term>
	///     <term>0xD1</term>
	///     <term>byte</term>
	///     <term>如需要，使用<see cref="M:Snet.Driver.Profinet.Omron.OmronConnectedCipNet.WriteTag(System.String,System.UInt16,System.Byte[],System.Int32)" />实现</term>
	///   </item>
	///   <item>
	///     <term>INT</term>
	///     <term>16位的整型</term>
	///     <term>0xC3</term>
	///     <term>short</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>UINT</term>
	///     <term>无符号的16位整型</term>
	///     <term>0xC7</term>
	///     <term>ushort</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>DINT</term>
	///     <term>32位的整型</term>
	///     <term>0xC4</term>
	///     <term>int</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>UDINT</term>
	///     <term>无符号的32位整型</term>
	///     <term>0xC8</term>
	///     <term>uint</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>LINT</term>
	///     <term>64位的整型</term>
	///     <term>0xC5</term>
	///     <term>long</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>ULINT</term>
	///     <term>无符号的64位的整型</term>
	///     <term>0xC9</term>
	///     <term>ulong</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>REAL</term>
	///     <term>单精度浮点数</term>
	///     <term>0xCA</term>
	///     <term>float</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>DOUBLE</term>
	///     <term>双精度浮点数</term>
	///     <term>0xCB</term>
	///     <term>double</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>STRING</term>
	///     <term>字符串数据</term>
	///     <term>0xD0</term>
	///     <term>string</term>
	///     <term>前两个字节为字符长度</term>
	///   </item>
	///   <item>
	///     <term>8bit string BYTE</term>
	///     <term>8位的字符串</term>
	///     <term>0xD1</term>
	///     <term></term>
	///     <term>本质是BYTE数组</term>
	///   </item>
	///   <item>
	///     <term>16bit string WORD</term>
	///     <term>16位的字符串</term>
	///     <term>0xD2</term>
	///     <term></term>
	///     <term>本质是WORD数组，可存放中文</term>
	///   </item>
	///   <item>
	///     <term>32bit string DWORD</term>
	///     <term>32位的字符串</term>
	///     <term>0xD2</term>
	///     <term></term>
	///     <term>本质是DWORD数组，可存放中文</term>
	///   </item>
	/// </list>
	/// 在读写操作之前，先看看怎么实例化和连接PLC<br />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage" title="实例化及连接示例" />
	/// 现在来说明以下具体的操作细节。我们假设有如下的变量：<br />
	/// CESHI_A       SINT<br />
	/// CESHI_B       BYTE<br />
	/// CESHI_C       INT<br />
	/// CESHI_D       UINT<br />
	/// CESHI_E       SINT[0..9]<br />
	/// CESHI_F       BYTE[0..9]<br />
	/// CESHI_G       INT[0..9]<br />
	/// CESHI_H       UINT[0..9]<br />
	/// CESHI_I       INT[0..511]<br />
	/// CESHI_J       STRING[12]<br />
	/// ToPc_ID1      ARRAY[0..99] OF STRING[20]<br />
	/// CESHI_O       BOOL<br />
	/// CESHI_P       BOOL[0..31]<br />
	/// 对 CESHI_A 来说，读写这么操作
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage2" title="读写示例" />
	/// 对于 CESHI_B 来说，写入的操作有点特殊
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage3" title="读写示例" />
	/// 对于 CESHI_C, CESHI_D 来说，就是 ReadInt16(string address) , Write( string address, short value ) 和 ReadUInt16(string address) 和 Write( string address, ushort value ) 差别不大。
	/// 所以我们着重来看看数组的情况，以 CESHI_G 标签为例子:<br />
	/// 情况一，我想一次读取这个标签所有的字节数组（当长度满足的情况下，会一次性返回数据）
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage4" title="读写示例" />
	/// 情况二，我想读取第3个数，或是第6个数开始，一共5个数
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage5" title="读写示例" />
	/// 其他的数组情况都是类似的，我们来看看字符串 CESHI_J 变量
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage6" title="读写示例" />
	/// 对于 bool 变量来说，就是 ReadBool("CESHI_O") 和 Write("CESHI_O", true) 操作，如果是bool数组，就不一样了
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage7" title="读写示例" />
	/// 最后我们来看看结构体的操作，假设我们有个结构体<br />
	/// MyData.Code     STRING(12)<br />
	/// MyData.Value1   INT<br />
	/// MyData.Value2   INT<br />
	/// MyData.Value3   REAL<br />
	/// MyData.Value4   INT<br />
	/// MyData.Value5   INT<br />
	/// MyData.Value6   INT[0..3]<br />
	/// 因为bool比较复杂，暂时不考虑。要读取上述的结构体，我们需要定义结构一样的数据
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage8" title="结构体" />
	/// 定义好后，我们再来读取就很简单了。
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\OmronConnectedCipNetSample.cs" region="Usage9" title="读写示例" />
	/// </example>
	public class OmronConnectedCipNet : NetworkConnectedCip, IReadWriteCip, IReadWriteNet
	{
		/// <summary>
		/// 当前产品的型号信息<br />
		/// Model information of the current product
		/// </summary>
		public string ProductName { get; private set; }

		/// <summary>
		/// 获取或设置不通信时超时的时间，默认02，为 32 秒，设置06 时为8分多，计算方法为 (2的x次方乘以8) 的秒数<br />
		/// Get or set the timeout time when there is no communication. The default is 02, which is 32 seconds, and when 06 is set, it is more than 8 minutes. The calculation method is (2 times the power of x times 8) seconds.
		/// </summary>
		public byte ConnectionTimeoutMultiplier { get; set; } = 2;

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public OmronConnectedCipNet()
		{
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 根据指定的IP及端口来实例化这个连接对象
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
		/// <param name="port">PLC的端口号信息</param>
		public OmronConnectedCipNet(string ipAddress, int port = 44818)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override byte[] GetLargeForwardOpen(ushort connectionID)
		{
			uint value = (base.TOConnectionId = (uint)(-2130837503 + connectionID));
			byte[] array = "\r\n00 00 00 00 00 00 02 00 00 00 00 00 b2 00 34 00\r\n5b 02 20 06 24 01 0e 9c 02 00 00 80 01 00 fe 80\r\n02 00 1b 05 30 a7 2b 03 02 00 00 00 80 84 1e 00\r\ncc 07 00 42 80 84 1e 00 cc 07 00 42 a3 03 20 02\r\n24 01 2c 01".ToHexBytes();
			BitConverter.GetBytes((uint)(-2147483646 + connectionID)).CopyTo(array, 24);
			BitConverter.GetBytes(value).CopyTo(array, 28);
			BitConverter.GetBytes((ushort)(2 + connectionID)).CopyTo(array, 32);
			BitConverter.GetBytes((ushort)4105).CopyTo(array, 34);
			SnetHelper.SnetRandom.GetBytes(4).CopyTo(array, 36);
			array[40] = ConnectionTimeoutMultiplier;
			return array;
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			OResult oResult = base.InitializationOnConnect();
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, base.SessionHandle, GetAttributeAll()), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (oResult2.Content.Length > 59 && oResult2.Content.Length >= 59 + oResult2.Content[58])
			{
				ProductName = Encoding.UTF8.GetString(oResult2.Content, 59, oResult2.Content[58]);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			OResult oResult = await base.InitializationOnConnectAsync().ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, base.SessionHandle, GetAttributeAll()), hasResponseData: true, usePackAndUnpack: false).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (oResult2.Content.Length > 59 && oResult2.Content.Length >= 59 + oResult2.Content[58])
			{
				ProductName = Encoding.UTF8.GetString(oResult2.Content, 59, oResult2.Content[58]);
			}
			return OResult.CreateSuccessResult();
		}

		private byte[] GetAttributeAll()
		{
			return "00 00 00 00 00 00 02 00 00 00 00 00 b2 00 06 00 01 02 20 01 24 01".ToHexBytes();
		}

		private OResult<byte[]> BuildReadCommand(string[] address, ushort[] length)
		{
			try
			{
				List<byte[]> list = new List<byte[]>();
				for (int i = 0; i < address.Length; i++)
				{
					list.Add(AllenBradleyHelper.PackRequsetRead(address[i], length[i], isConnectedAddress: true));
				}
				return OResult.CreateSuccessResult(PackCommandService(list.ToArray()));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address Wrong:" + ex.Message);
			}
		}

		private OResult<byte[]> BuildWriteCommand(string address, ushort typeCode, byte[] data, int length = 1)
		{
			try
			{
				return OResult.CreateSuccessResult(PackCommandService(AllenBradleyHelper.PackRequestWrite(address, typeCode, data, length, isConnectedAddress: true)));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address Wrong:" + ex.Message);
			}
		}

		private OResult<byte[], ushort, bool> ReadWithType(string[] address, ushort[] length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], ushort, bool>(oResult);
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], ushort, bool>(oResult2);
			}
			OResult oResult3 = AllenBradleyHelper.CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], ushort, bool>(oResult3);
			}
			return NetworkConnectedCip.ExtractActualData(oResult2.Content, isRead: true);
		}

