		/// <summary>
		/// 获取传递的最大长度的字节信息
		/// </summary>
		/// <returns>字节长度</returns>
		protected virtual int GetMaxTransferBytes()
		{
			return 1988;
		}

		private int GetLengthFromRemain(ushort dataType, int length)
		{
			switch (dataType)
			{
			case 193:
			case 194:
			case 198:
			case 211:
				return Math.Min(length, GetMaxTransferBytes());
			case 195:
			case 199:
				return Math.Min(length, GetMaxTransferBytes() / 2);
			case 196:
			case 200:
			case 202:
				return Math.Min(length, GetMaxTransferBytes() / 4);
			default:
				return Math.Min(length, GetMaxTransferBytes() / 8);
			}
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			SnetHelper.ExtractParameter(ref address, "type", 0);
			if (length == 1)
			{
				OResult<byte[], ushort, bool> oResult = ReadWithType(new string[1] { address }, new ushort[1] { length });
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				return OResult.CreateSuccessResult(oResult.Content1);
			}
			int num = 0;
			int num2 = 0;
			string format = "[{0}]";
			List<byte> list = new List<byte>();
			Match match = Regex.Match(address, "\\[[0-9]+\\]$");
			if (match.Success)
			{
				address = address.Remove(match.Index, match.Length);
				num2 = int.Parse(match.Value.Substring(1, match.Value.Length - 2));
			}
			else
			{
				Match match2 = Regex.Match(address, "\\[[0-9]+,[0-9]+\\]$");
				if (match2.Success)
				{
					address = address.Remove(match2.Index, match2.Length);
					string value = Regex.Matches(match2.Value, "[0-9]+")[1].Value;
					format = match2.Value.Replace(value + "]", "{0}]");
					num2 = int.Parse(value);
				}
			}
			ushort dataType = 0;
			while (num < length)
			{
				if (num == 0)
				{
					ushort num3 = Math.Min(length, (ushort)248);
					OResult<byte[], ushort, bool> oResult2 = ReadWithType(new string[1] { address + string.Format(format, num2) }, new ushort[1] { num3 });
					if (!oResult2.IsSuccess)
					{
						return OResult.CreateFailedResult<byte[]>(oResult2);
					}
					dataType = oResult2.Content2;
					num += num3;
					num2 += num3;
					list.AddRange(oResult2.Content1);
				}
				else
				{
					ushort num4 = (ushort)GetLengthFromRemain(dataType, length - num);
					OResult<byte[], ushort, bool> oResult3 = ReadWithType(new string[1] { address + string.Format(format, num2) }, new ushort[1] { num4 });
					if (!oResult3.IsSuccess)
					{
						return OResult.CreateFailedResult<byte[]>(oResult3);
					}
					num += num4;
					num2 += num4;
					list.AddRange(oResult3.Content1);
				}
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.Read(System.String[],System.UInt16[])" />
		public OResult<byte[]> Read(string[] address, ushort[] length)
		{
			OResult<byte[], ushort, bool> oResult = ReadWithType(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(oResult.Content1);
		}

		/// <summary>
		/// 读取bool数据信息，如果读取的是单bool变量，就直接写变量名，如果是 bool 数组，就 <br />
		/// Read a single bool data information, if it is a single bool variable, write the variable name directly, 
		/// if it is a value of a bool array composed of int, it is always accessed with "i=" at the beginning, for example, "i=A[0]"
		/// </summary>
		/// <param name="address">节点的名称 -&gt; Name of the node </param>
		/// <param name="length">读取的数组长度信息</param>
		/// <returns>带有结果对象的结果数据 -&gt; Result data with result info </returns>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (length == 1 && !Regex.IsMatch(address, "\\[[0-9]+\\]$"))
			{
				OResult<byte[]> oResult = Read(address, length);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				return OResult.CreateSuccessResult(SoftBasic.ByteToBoolArray(oResult.Content));
			}
			OResult<byte[]> oResult2 = Read(address, length);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.Select((byte m) => m != 0).Take(length).ToArray());
		}

