		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			SnetHelper.ExtractParameter(ref address, "type", 0);
			if (length == 1)
			{
				OResult<byte[], ushort, bool> oResult = await ReadWithTypeAsync(new string[1] { address }, new ushort[1] { length });
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				return OResult.CreateSuccessResult(oResult.Content1);
			}
			int count = 0;
			int index = 0;
			string format = "[{0}]";
			List<byte> array = new List<byte>();
			Match match = Regex.Match(address, "\\[[0-9]+\\]$");
			if (match.Success)
			{
				address = address.Remove(match.Index, match.Length);
				index = int.Parse(match.Value.Substring(1, match.Value.Length - 2));
			}
			else
			{
				Match match2 = Regex.Match(address, "\\[[0-9]+,[0-9]+\\]$");
				if (match2.Success)
				{
					address = address.Remove(match2.Index, match2.Length);
					string value = Regex.Matches(match2.Value, "[0-9]+")[1].Value;
					format = match2.Value.Replace(value + "]", "{0}]");
					index = int.Parse(value);
				}
			}
			ushort dataType = 0;
			while (count < length)
			{
				if (count == 0)
				{
					ushort first = Math.Min(length, (ushort)248);
					OResult<byte[], ushort, bool> oResult2 = await ReadWithTypeAsync(new string[1] { address + string.Format(format, index) }, new ushort[1] { first });
					if (!oResult2.IsSuccess)
					{
						return OResult.CreateFailedResult<byte[]>(oResult2);
					}
					dataType = oResult2.Content2;
					count += first;
					index += first;
					array.AddRange(oResult2.Content1);
				}
				else
				{
					ushort first = (ushort)GetLengthFromRemain(dataType, length - count);
					OResult<byte[], ushort, bool> oResult3 = await ReadWithTypeAsync(new string[1] { address + string.Format(format, index) }, new ushort[1] { first });
					if (!oResult3.IsSuccess)
					{
						return OResult.CreateFailedResult<byte[]>(oResult3);
					}
					count += first;
					index += first;
					array.AddRange(oResult3.Content1);
				}
			}
			return OResult.CreateSuccessResult(array.ToArray());
		}

