		/// <summary>
		/// 读取字符串数据，默认为UTF-8编码<br />
		/// Read string data, default is UTF-8 encoding
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="length">数据长度</param>
		/// <returns>带有成功标识的string数据</returns>
		/// <example>
		/// 以下为三菱的连接对象示例，其他的设备读写情况参照下面的代码：
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDeviceBase.cs" region="ReadString" title="String类型示例" />
		/// </example>
		public override OResult<string> ReadString(string address, ushort length)
		{
			return ReadString(address, length, Encoding.UTF8);
		}

		/// <inheritdoc />
		public override OResult<string> ReadString(string address, ushort length, Encoding encoding)
		{
			OResult<byte[]> oResult = Read(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			return ExtraStringContent(oResult.Content, encoding);
		}

		private OResult<string> ExtraStringContent(byte[] content, Encoding encoding)
		{
			try
			{
				if (content.Length >= 2)
				{
					int count = base.ByteTransform.TransUInt16(content, 0);
					return OResult.CreateSuccessResult(encoding.GetString(content, 2, count));
				}
				return OResult.CreateSuccessResult(encoding.GetString(content));
			}
			catch (Exception ex)
			{
				return new OResult<string>("Parse string failed: " + ex.Message + " Source: " + content.ToHexString(' '));
			}
		}

