	/// <summary>
	/// Omron PLC的FINS协议相关的辅助类，主要是一些地址解析，读写的指令生成。<br />
	/// The auxiliary classes related to the FINS protocol of Omron PLC are mainly some address resolution and the generation of read and write instructions.
	/// </summary>
	public class OmronFinsNetHelper
	{
		private static bool IsBitOperateCode(byte dataType)
		{
			if (dataType != OmronFinsDataType.DM.BitCode && dataType != OmronFinsDataType.CIO.BitCode && dataType != OmronFinsDataType.WR.BitCode && dataType != OmronFinsDataType.HR.BitCode && dataType != OmronFinsDataType.AR.BitCode && dataType != OmronFinsDataType.TIM.BitCode)
			{
				return dataType == 7;
			}
			return true;
		}

		private static bool IsWordOperateCode(byte dataType)
		{
			if (dataType != OmronFinsDataType.DM.WordCode && dataType != OmronFinsDataType.CIO.WordCode && dataType != OmronFinsDataType.WR.WordCode && dataType != OmronFinsDataType.HR.WordCode && dataType != OmronFinsDataType.AR.WordCode && dataType != OmronFinsDataType.TIM.WordCode && dataType != 220 && dataType != 188)
			{
				return dataType == 156;
			}
			return true;
		}

		internal static string AnalysisAddressLogMessage(PipeSession pipeSession, IByteTransform byteTransform, byte[] content, int offset)
		{
			if (content.Length >= offset + 8 && content[offset] == 1 && (content[offset + 1] == 1 || content[offset + 1] == 2))
			{
				StringBuilder stringBuilder = new StringBuilder();
				byte b = content[offset + 2];
				if (IsBitOperateCode(b))
				{
					if (content[offset + 1] == 1)
					{
						stringBuilder.Append(" --- ReadBool(\"");
					}
					else
					{
						stringBuilder.Append(" --- Write(\"");
					}
				}
				else
				{
					if (!IsWordOperateCode(b))
					{
						return string.Empty;
					}
					if (content[offset + 1] == 1)
					{
						stringBuilder.Append(" --- Read(\"");
					}
					else
					{
						stringBuilder.Append(" --- Write(\"");
					}
				}
				int num = content[offset + 3] * 256 + content[offset + 4];
				int value = content[offset + 5];
				int num2 = content[offset + 6] * 256 + content[offset + 7];
				if (b == OmronFinsDataType.DM.BitCode)
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder3 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(3, 2, stringBuilder2);
					handler.AppendLiteral("DM");
