		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.Read(Snet.Driver.Profinet.Omron.Helper.IOmronFins,System.String,System.UInt16,System.Int32)" />
		public static async Task<OResult<byte[]>> ReadAsync(IOmronFins omron, string address, ushort length, int splits)
		{
			OResult<List<byte[]>> command = BuildReadCommand(omron.PlcType, address, length, isBit: false, splits);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(command);
			}
			List<byte> contentArray = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await omron.ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				contentArray.AddRange(oResult.Content);
			}
			return OResult.CreateSuccessResult(contentArray.ToArray());
		}

