		/// <summary>
		/// 从欧姆龙PLC中批量读取位软元件，地址格式为"D100.0","C100.0","W100.0","H100.0","A100.0"<br />
		/// Read bit devices in batches from Omron PLC with address format "D100.0", "C100.0", "W100.0", "H100.0", "A100.0"
		/// </summary>
		/// <param name="omron">PLC设备的连接对象</param>
		/// <param name="address">读取地址，格式为"D100","C100","W100","H100","A100"</param>
		/// <param name="length">读取的长度</param>
		/// <param name="splits">分割信息</param>
		/// <returns>带成功标志的结果数据对象</returns>
		public static OResult<bool[]> ReadBool(IOmronFins omron, string address, ushort length, int splits)
		{
			if (address.StartsWith("DR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("IR", StringComparison.OrdinalIgnoreCase))
			{
				if (!address.Contains("."))
				{
					address += ".0";
				}
				return SnetHelper.ReadBool(omron, address, length, 16, reverseByWord: true);
			}
			OResult<OmronFinsAddress> oResult = OmronFinsAddress.ParseFrom(address, length, omron.PlcType);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			int num = 0;
			List<bool> list = new List<bool>();
			while (num < length)
			{
				byte[] send = BuildReadCommand(oResult.Content, (ushort)(length - num), isBit: true);
				OResult<byte[]> oResult2 = omron.ReadFromCoreServer(send);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				if (oResult2.Content.Length == 0)
				{
					return new OResult<bool[]>(oResult2.ErrorCode, oResult2.Message);
				}
				IEnumerable<bool> enumerable = oResult2.Content.Select((byte m) => m != 0);
				list.AddRange(enumerable);
				num += enumerable.Count();
				oResult.Content.AddressStart += enumerable.Count();
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <summary>
		/// 向PLC中位软元件写入bool数组，返回是否写入成功，比如你写入D100,values[0]对应D100.0，地址格式为"D100.0","C100.0","W100.0","H100.0","A100.0"<br />
		/// Write the bool array to the PLC's median device and return whether the write was successful. For example, if you write D100, values [0] corresponds to D100.0 
		/// and the address format is "D100.0", "C100.0", "W100. 0 "," H100.0 "," A100.0 "
		/// </summary>
		/// <param name="omron">PLC设备的连接对象</param>
		/// <param name="address">要写入的数据地址</param>
		/// <param name="values">要写入的实际数据，可以指定任意的长度</param>
		/// <returns>返回写入结果</returns>
		public static OResult Write(IOmronFins omron, string address, bool[] values)
		{
			if (address.StartsWith("DR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("IR", StringComparison.OrdinalIgnoreCase))
			{
				return new OResult("DR and IR address not support bit write");
			}
			if (omron.PlcType == OmronPlcType.CV && (address.StartsWithAndNumber("CIO") || address.StartsWithAndNumber("C")))
			{
				return ReadWriteNetHelper.WriteBoolWithWord(omron, address, values, 16, reverseWord: true);
			}
			OResult<byte[]> oResult = BuildWriteWordCommand(omron.PlcType, address, values.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), isBit: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = omron.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.ReadBool(Snet.Driver.Profinet.Omron.Helper.IOmronFins,System.String,System.UInt16,System.Int32)" />
		public static async Task<OResult<bool[]>> ReadBoolAsync(IOmronFins omron, string address, ushort length, int splits)
		{
			if (address.StartsWith("DR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("IR", StringComparison.OrdinalIgnoreCase))
			{
				if (!address.Contains("."))
				{
					address += ".0";
				}
				return await SnetHelper.ReadBoolAsync(omron, address, length, 16, reverseByWord: true);
			}
			OResult<OmronFinsAddress> analysis = OmronFinsAddress.ParseFrom(address, length, omron.PlcType);
			if (!analysis.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(analysis);
			}
			int len = 0;
			List<bool> contentArray = new List<bool>();
			while (len < length)
			{
				byte[] send = BuildReadCommand(analysis.Content, (ushort)(length - len), isBit: true);
				OResult<byte[]> oResult = await omron.ReadFromCoreServerAsync(send);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				if (oResult.Content.Length == 0)
				{
					return new OResult<bool[]>(oResult.ErrorCode, oResult.Message);
				}
				IEnumerable<bool> enumerable = oResult.Content.Select((byte m) => m != 0);
				contentArray.AddRange(enumerable);
				len += enumerable.Count();
				analysis.Content.AddressStart += enumerable.Count();
			}
			return OResult.CreateSuccessResult(contentArray.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.Write(Snet.Driver.Profinet.Omron.Helper.IOmronFins,System.String,System.Boolean[])" />
		public static async Task<OResult> WriteAsync(IOmronFins omron, string address, bool[] values)
		{
			if (address.StartsWith("DR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("IR", StringComparison.OrdinalIgnoreCase))
			{
				return new OResult("DR and IR address not support bit write");
			}
			if (omron.PlcType == OmronPlcType.CV && (address.StartsWithAndNumber("CIO") || address.StartsWithAndNumber("C")))
			{
				return await ReadWriteNetHelper.WriteBoolWithWordAsync(omron, address, values, 16, reverseWord: true).ConfigureAwait(continueOnCapturedContext: false);
			}
			OResult<byte[]> oResult = BuildWriteWordCommand(omron.PlcType, address, values.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), isBit: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await omron.ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

