		private static OResult<DateTime> CreatePlcTime(byte[] buffer)
		{
			try
			{
				string text = buffer.ToHexString();
				return OResult.CreateSuccessResult(new DateTime(Convert.ToInt32(DateTime.Now.Year.ToString().Substring(0, 2) + text.Substring(0, 2)), Convert.ToInt32(text.Substring(2, 2)), Convert.ToInt32(text.Substring(4, 2)), Convert.ToInt32(text.Substring(6, 2)), Convert.ToInt32(text.Substring(8, 2)), Convert.ToInt32(text.Substring(10, 2))));
			}
			catch (Exception ex)
			{
				return new OResult<DateTime>("Prase Time failed: " + ex.Message + Environment.NewLine + "Source: " + buffer.ToHexString(' '));
			}
		}

		/// <summary>
		/// 读取CPU的时间信息<br />
		/// Read the time information of the CPU
		/// </summary>
		/// <param name="omron">PLC设备的连接对象</param>
		/// <returns>是否读取成功</returns>
		public static OResult<DateTime> ReadCpuTime(IReadWriteDevice omron)
		{
			return omron.ReadFromCoreServer(new byte[2] { 7, 1 }).Then((byte[] m) => CreatePlcTime(m));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.ReadCpuUnitStatus(Snet.Driver.Core.IReadWriteDevice)" />
		public static async Task<OResult<DateTime>> ReadCpuTimeAsync(IReadWriteDevice omron)
		{
			return (await omron.ReadFromCoreServerAsync(new byte[2] { 7, 1 }).ConfigureAwait(continueOnCapturedContext: false)).Then((byte[] m) => CreatePlcTime(m));
		}
	}
	/// <summary>
	/// 欧姆龙的虚拟服务器，支持DM区，CIO区，Work区，Hold区，Auxiliary区，可以方便的进行测试<br />
	/// Omron's virtual server supports DM area, CIO area, Work area, Hold area, and Auxiliary area, which can be easily tested
	/// </summary>
	public class OmronFinsServer : DeviceServer
	{
		protected SoftBuffer dBuffer;

		protected SoftBuffer cioBuffer;

		protected SoftBuffer wBuffer;

		protected SoftBuffer hBuffer;

		protected SoftBuffer arBuffer;

		protected SoftBuffer emBuffer;

		protected SoftBuffer cfBuffer;

		protected SoftBuffer irBuffer;

		protected SoftBuffer drBuffer;

		protected bool connectionInitialization = true;

		protected const int DataPoolLength = 65536;

		/// <inheritdoc cref="P:Snet.Driver.Core.IByteTransform.DataFormat" />
		public DataFormat DataFormat
		{
			get
			{
				return base.ByteTransform.DataFormat;
			}
			set
			{
				base.ByteTransform.DataFormat = value;
			}
		}

		/// <summary>
		/// 是否在返回的报文中复制SID信息，默认是True<br />
		/// Indicates whether to copy SID information in the returned message, default is True
		/// </summary>
		public bool CopySID { get; set; } = true;

		/// <summary>
		/// 是否分析通信报文信息，并将分析结果追加到报文日志里去<br />
		/// Should we analyze the communication message information and add the analysis results to the message log?
		/// </summary>
		public bool AnalysisLogMessage { get; set; }

		/// <summary>
		/// 实例化一个Fins协议的服务器<br />
		/// Instantiate a Fins protocol server
		/// </summary>
		public OmronFinsServer()
		{
			dBuffer = new SoftBuffer(131072);
			cioBuffer = new SoftBuffer(131072);
			wBuffer = new SoftBuffer(131072);
			hBuffer = new SoftBuffer(131072);
			arBuffer = new SoftBuffer(131072);
			emBuffer = new SoftBuffer(131072);
			cfBuffer = new SoftBuffer(131072);
			irBuffer = new SoftBuffer(131072);
			drBuffer = new SoftBuffer(131072);
			dBuffer.IsBoolReverseByWord = true;
			cioBuffer.IsBoolReverseByWord = true;
			wBuffer.IsBoolReverseByWord = true;
			hBuffer.IsBoolReverseByWord = true;
			arBuffer.IsBoolReverseByWord = true;
			emBuffer.IsBoolReverseByWord = true;
			cfBuffer.IsBoolReverseByWord = true;
			irBuffer.IsBoolReverseByWord = true;
			drBuffer.IsBoolReverseByWord = true;
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
		}

		private OResult<SoftBuffer, OmronFinsAddress> GetWordAddressBuffer(string address)
		{
			OResult<OmronFinsAddress> oResult = OmronFinsAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<SoftBuffer, OmronFinsAddress>(oResult);
			}
			if (oResult.Content.WordCode == OmronFinsDataType.DM.WordCode)
			{
				return OResult.CreateSuccessResult(dBuffer, oResult.Content);
			}
			if (oResult.Content.WordCode == OmronFinsDataType.CIO.WordCode)
			{
				return OResult.CreateSuccessResult(cioBuffer, oResult.Content);
			}
			if (oResult.Content.WordCode == OmronFinsDataType.WR.WordCode)
			{
				return OResult.CreateSuccessResult(wBuffer, oResult.Content);
			}
			if (oResult.Content.WordCode == OmronFinsDataType.HR.WordCode)
			{
				return OResult.CreateSuccessResult(hBuffer, oResult.Content);
			}
			if (oResult.Content.WordCode == OmronFinsDataType.AR.WordCode)
			{
				return OResult.CreateSuccessResult(arBuffer, oResult.Content);
			}
			if (oResult.Content.WordCode == 188)
			{
				return OResult.CreateSuccessResult(drBuffer, oResult.Content);
			}
			if (oResult.Content.WordCode == 220)
			{
				return OResult.CreateSuccessResult(irBuffer, oResult.Content);
			}
			if (address.StartsWith("E", StringComparison.OrdinalIgnoreCase))
			{
				return OResult.CreateSuccessResult(emBuffer, oResult.Content);
			}
			return new OResult<SoftBuffer, OmronFinsAddress>(StringResources.Language.NotSupportedDataType);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<SoftBuffer, OmronFinsAddress> wordAddressBuffer = GetWordAddressBuffer(address);
			if (!wordAddressBuffer.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(wordAddressBuffer);
			}
			return OResult.CreateSuccessResult(wordAddressBuffer.Content1.GetBytes(wordAddressBuffer.Content2.AddressStart / 16 * 2, length * 2));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<SoftBuffer, OmronFinsAddress> wordAddressBuffer = GetWordAddressBuffer(address);
			if (!wordAddressBuffer.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(wordAddressBuffer);
			}
			wordAddressBuffer.Content1.SetBytes(value, wordAddressBuffer.Content2.AddressStart / 16 * 2);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<OmronFinsAddress> oResult = OmronFinsAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content.BitCode == OmronFinsDataType.DM.BitCode)
			{
				return OResult.CreateSuccessResult(dBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.BitCode == OmronFinsDataType.CIO.BitCode)
			{
				return OResult.CreateSuccessResult(cioBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.BitCode == OmronFinsDataType.WR.BitCode)
			{
				return OResult.CreateSuccessResult(wBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.BitCode == OmronFinsDataType.HR.BitCode)
			{
				return OResult.CreateSuccessResult(hBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.BitCode == OmronFinsDataType.AR.BitCode)
			{
				return OResult.CreateSuccessResult(arBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.BitCode == 7)
			{
				return OResult.CreateSuccessResult(cfBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.WordCode == 188)
			{
				return OResult.CreateSuccessResult(drBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.WordCode == 220)
			{
				return OResult.CreateSuccessResult(irBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			return OResult.CreateSuccessResult(emBuffer.GetBool(oResult.Content.AddressStart, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			OResult<OmronFinsAddress> oResult = OmronFinsAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content.BitCode == OmronFinsDataType.DM.BitCode)
			{
				dBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.BitCode == OmronFinsDataType.CIO.BitCode)
			{
				cioBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.BitCode == OmronFinsDataType.WR.BitCode)
			{
				wBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.BitCode == OmronFinsDataType.HR.BitCode)
			{
				hBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.BitCode == OmronFinsDataType.AR.BitCode)
			{
				arBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.BitCode == 7)
			{
				cfBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.WordCode == 188)
			{
				drBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.WordCode == 220)
			{
				irBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else
			{
				emBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override string GetLogTextFromBinary(PipeSession session, byte[] content)
		{
			string text = base.GetLogTextFromBinary(session, content);
			if (AnalysisLogMessage)
			{
				string text2 = OmronFinsNetHelper.AnalysisAddressLogMessage(session, base.ByteTransform, content, 26);
				text += text2;
			}
			return text;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FinsMessage();
		}

		/// <inheritdoc />
		protected override OResult ThreadPoolLoginAfterClientCheck(PipeSession session, IPEndPoint endPoint)
		{
			if (connectionInitialization)
			{
				CommunicationPipe communication = session.Communication;
				OResult<byte[]> oResult = communication.ReceiveMessage(GetNewNetMessage(), null, useActivePush: false, null, delegate(byte[] m)
				{
					LogRevcMessage(m, session);
				});
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				byte[] array = SoftBasic.HexStringToBytes("46 49 4E 53 00 00 00 10 00 00 00 01 00 00 00 00 00 00 00 01 00 00 00 02");
				LogSendMessage(array, session);
				OResult oResult2 = communication.Send(array);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
			}
			return base.ThreadPoolLoginAfterClientCheck(session, endPoint);
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive[0] == 70 && receive[7] == 12 && receive.Length == 20)
			{
				return OResult.CreateSuccessResult(SoftBasic.HexStringToBytes("46 49 4E 53 00 00 00 10 00 00 00 01 00 00 00 00 00 00 00 01 00 00 00 02"));
			}
			byte[] array = ReadFromFinsCore(receive.RemoveBegin(26));
			if (receive != null && receive.Length > 25)
			{
				array[20] = receive[23];
				array[23] = receive[20];
				if (CopySID)
				{
					array[25] = receive[25];
				}
				else
				{
					array[25] = 0;
				}
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 当收到mc协议的报文的时候应该触发的方法，允许继承重写，来实现自定义的返回，或是数据监听。<br />
		/// The method that should be triggered when a message of the mc protocol is received is allowed to be inherited and rewritten to achieve a custom return or data monitoring.
		/// </summary>
		/// <param name="finsCore">mc报文</param>
		/// <returns>返回的报文信息</returns>
		protected virtual byte[] ReadFromFinsCore(byte[] finsCore)
		{
			if (finsCore.Length == 0)
			{
				return null;
			}
			if (finsCore[0] == 1 && finsCore[1] == 1)
			{
				byte[] array = ReadByCommand(finsCore);
				return PackCommand((array == null) ? 2 : 0, finsCore, array);
			}
			if (finsCore[0] == 1 && finsCore[1] == 2)
			{
				if (!base.EnableWrite)
				{
					return PackCommand(3, finsCore, null);
				}
				return PackCommand(0, finsCore, WriteByMessage(finsCore));
			}
			if (finsCore[0] == 1 && finsCore[1] == 4)
			{
				byte[] array2 = ReadByMultiCommand(finsCore);
				return PackCommand((array2 == null) ? 2 : 0, finsCore, array2);
			}
			if (finsCore[0] == 4 && finsCore[1] == 1)
			{
				return PackCommand(0, finsCore, null);
			}
			if (finsCore[0] == 4 && finsCore[1] == 2)
			{
				return PackCommand(0, finsCore, null);
			}
			if (finsCore[0] == 5 && finsCore[1] == 1)
			{
				return PackCommand(0, finsCore, "43 4A 32 4D 2D 43 50 55 33 31 20 20 20 20 20 20 20 20 20 20 30 32 2E 30 31 00 00 00 00 00 30 32 2E 31 30 00 00 00 00 00 00 01 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 01 00 00 80 01 80 01 80 01 80 00 00 00 00 00 00 00 00 02 01 00 00 0A 17 80 00 08 01 00 00 00 00 00".ToHexBytes());
			}
			if (finsCore[0] == 6 && finsCore[1] == 1)
			{
				return PackCommand(0, finsCore, "05 02 00 00 00 00 00 00 00 00 20 20 20 20 20 20 20 20 20 20 20 20 20 20 20 20".ToHexBytes());
			}
			if (finsCore[0] == 7 && finsCore[1] == 1)
			{
				return PackCommand(0, finsCore, (DateTime.Now.ToString("yy-MM-dd-HH-mm-ss").Replace("-", "") + ((int)DateTime.Now.DayOfWeek).ToString("D2")).ToHexBytes());
			}
			return PackCommand(3, finsCore, null);
		}

		/// <summary>
		/// 将核心报文打包的方法，追加报文头<br />
		/// The method of packing the core message, adding the message header
		/// </summary>
		/// <param name="status">错误码</param>
		/// <param name="finsCore">Fins的核心报文</param>
		/// <param name="data">核心的内容</param>
		/// <returns>完整的报文信息</returns>
		protected virtual byte[] PackCommand(int status, byte[] finsCore, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[30 + data.Length];
			SoftBasic.HexStringToBytes("46 49 4E 53 00 00 00 0000 00 00 02 00 00 00 00C0 00 02 00 EF 00 00 33 00 00 00 00 00 00").CopyTo(array, 0);
			if (data.Length != 0)
			{
				data.CopyTo(array, 30);
			}
			array[26] = finsCore[0];
			array[27] = finsCore[1];
			BitConverter.GetBytes(array.Length - 8).ReverseNew().CopyTo(array, 4);
			BitConverter.GetBytes(status).ReverseNew().CopyTo(array, 12);
			return array;
		}

		private SoftBuffer GetSoftBuffer(byte code, int startIndex)
		{
			if (code == OmronFinsDataType.DM.BitCode)
			{
				return dBuffer;
			}
			if (code == OmronFinsDataType.DM.WordCode)
			{
				return dBuffer;
			}
			if (code == OmronFinsDataType.CIO.BitCode)
			{
				return cioBuffer;
			}
			if (code == OmronFinsDataType.CIO.WordCode)
			{
				return cioBuffer;
			}
			if (code == OmronFinsDataType.WR.BitCode)
			{
				return wBuffer;
			}
			if (code == OmronFinsDataType.WR.WordCode)
			{
				return wBuffer;
			}
			if (code == OmronFinsDataType.HR.BitCode)
			{
				return hBuffer;
			}
			if (code == OmronFinsDataType.HR.WordCode)
			{
				return hBuffer;
			}
			if (code == OmronFinsDataType.AR.BitCode)
			{
				return arBuffer;
			}
			if (code == OmronFinsDataType.AR.WordCode)
			{
				return arBuffer;
			}
			switch (code)
			{
			case 7:
				return cfBuffer;
			case 188:
				return drBuffer;
			case 220:
				return irBuffer;
			case 0:
				if (startIndex < 45056)
				{
					return cioBuffer;
				}
				return arBuffer;
			case 128:
				if (startIndex < 45056)
				{
					return cioBuffer;
				}
				return arBuffer;
			default:
				if ((32 <= code && code < 48) || (208 <= code && code < 224))
				{
					return emBuffer;
				}
				if ((160 <= code && code < 176) || (80 <= code && code < 96))
				{
					return emBuffer;
				}
				if (144 <= code && code < 153)
				{
					return emBuffer;
				}
				if (code == 10)
				{
					return emBuffer;
				}
				throw new Exception(StringResources.Language.NotSupportedDataType);
			}
		}

		private byte[] ReadByCommand(byte[] command)
		{
			if (command[2] == OmronFinsDataType.DM.BitCode || command[2] == OmronFinsDataType.CIO.BitCode || command[2] == OmronFinsDataType.WR.BitCode || command[2] == OmronFinsDataType.HR.BitCode || command[2] == OmronFinsDataType.AR.BitCode || command[2] == 0 || command[2] == 7 || command[2] == 10 || (32 <= command[2] && command[2] < 48) || (208 <= command[2] && command[2] < 224))
			{
				ushort length = (ushort)(command[6] * 256 + command[7]);
				int num = (command[3] * 256 + command[4]) * 16 + command[5];
				SoftBuffer softBuffer = GetSoftBuffer(command[2], num);
				if ((command[2] == 0 || command[2] == 128) && num >= 45056)
				{
					num -= 45056;
				}
				return (from m in softBuffer.GetBool(num, length)
					select m ? ((byte)1) : ((byte)0)).ToArray();
			}
			if (command[2] == OmronFinsDataType.DM.WordCode || command[2] == OmronFinsDataType.CIO.WordCode || command[2] == OmronFinsDataType.WR.WordCode || command[2] == OmronFinsDataType.HR.WordCode || command[2] == OmronFinsDataType.AR.WordCode || command[2] == 128 || command[2] == 188 || command[2] == 220 || command[2] == 152 || (160 <= command[2] && command[2] < 176) || (80 <= command[2] && command[2] < 96))
			{
				ushort num2 = (ushort)(command[6] * 256 + command[7]);
				int num3 = command[3] * 256 + command[4];
				if (num2 > 999)
				{
					return null;
				}
				SoftBuffer softBuffer2 = GetSoftBuffer(command[2], num3);
				if ((command[2] == 0 || command[2] == 128) && num3 >= 45056)
				{
					num3 -= 45056;
				}
				return softBuffer2.GetBytes(num3 * 2, num2 * 2);
			}
			return new byte[0];
		}

		private byte[] ReadByMultiCommand(byte[] command)
		{
			MemoryStream memoryStream = new MemoryStream();
			for (int i = 2; i < command.Length; i += 4)
			{
				int num = command[i + 1] * 256 + command[i + 2];
				if (command[i] == OmronFinsDataType.DM.WordCode || command[i] == OmronFinsDataType.CIO.WordCode || command[i] == OmronFinsDataType.WR.WordCode || command[i] == OmronFinsDataType.HR.WordCode || command[i] == OmronFinsDataType.AR.WordCode || command[i] == 128 || command[i] == 188 || command[i] == 220 || command[i] == 152 || (160 <= command[i] && command[i] < 176) || (80 <= command[i] && command[i] < 96))
				{
					memoryStream.WriteByte(command[i]);
					SoftBuffer softBuffer = GetSoftBuffer(command[i], num);
					if ((command[2] == 0 || command[2] == 128) && num >= 45056)
					{
						num -= 45056;
					}
					memoryStream.Write(softBuffer.GetBytes(num * 2, 2));
				}
			}
			return memoryStream.ToArray();
		}

		private byte[] WriteByMessage(byte[] command)
		{
			if (command[2] == OmronFinsDataType.DM.BitCode || command[2] == OmronFinsDataType.CIO.BitCode || command[2] == OmronFinsDataType.WR.BitCode || command[2] == OmronFinsDataType.HR.BitCode || command[2] == OmronFinsDataType.AR.BitCode || command[2] == 0 || command[2] == 7 || (32 <= command[2] && command[2] < 48) || (208 <= command[2] && command[2] < 224))
			{
				_ = command[6];
				_ = command[7];
				int num = (command[3] * 256 + command[4]) * 16 + command[5];
				bool[] value = (from m in SoftBasic.ArrayRemoveBegin(command, 8)
					select m == 1).ToArray();
				SoftBuffer softBuffer = GetSoftBuffer(command[2], num);
				if ((command[2] == 0 || command[2] == 128) && num >= 45056)
				{
					num -= 45056;
				}
				softBuffer.SetBool(value, num);
				return new byte[0];
			}
			_ = command[6];
			_ = command[7];
			int num2 = command[3] * 256 + command[4];
			byte[] data = SoftBasic.ArrayRemoveBegin(command, 8);
			SoftBuffer softBuffer2 = GetSoftBuffer(command[2], num2);
			if ((command[2] == 0 || command[2] == 128) && num2 >= 45056)
			{
				num2 -= 45056;
			}
			softBuffer2.SetBytes(data, num2 * 2);
			return new byte[0];
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			SoftBuffer.LoadFromBuffer(content, dBuffer, cioBuffer, wBuffer, hBuffer, arBuffer, emBuffer, cfBuffer, irBuffer, drBuffer);
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			return SoftBuffer.ToMemoryStream(dBuffer, cioBuffer, wBuffer, hBuffer, arBuffer, emBuffer, cfBuffer, irBuffer, drBuffer).ToArray();
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				dBuffer?.Dispose();
				cioBuffer?.Dispose();
				wBuffer?.Dispose();
				hBuffer?.Dispose();
				arBuffer?.Dispose();
				emBuffer?.Dispose();
				cfBuffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"OmronFinsServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 欧姆龙的Udp协议的实现类，地址类型和Fins-TCP一致，无连接的实现，可靠性不如<see cref="T:Snet.Driver.Profinet.Omron.OmronFinsNet" /><br />
	/// Omron's Udp protocol implementation class, the address type is the same as Fins-TCP, 
	/// and the connectionless implementation is not as reliable as <see cref="T:Snet.Driver.Profinet.Omron.OmronFinsNet" />
	/// </summary>
	/// <remarks>
	/// <inheritdoc cref="T:Snet.Driver.Profinet.Omron.OmronFinsNet" path="remarks" />
	/// </remarks>
	public class OmronFinsUdp : DeviceUdpNet, IOmronFins, IReadWriteDevice, IReadWriteNet
	{
		private readonly SoftIncrementCount incrementSID = new SoftIncrementCount(255L, 0L);

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.ICF" />
		public byte ICF { get; set; } = 128;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.RSV" />
		public byte RSV { get; private set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.GCT" />
		public byte GCT { get; set; } = 2;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.DNA" />
		public byte DNA { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.DA1" />
		public byte DA1 { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.DA2" />
		public byte DA2 { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.SNA" />
		public byte SNA { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.SA1" />
		public byte SA1 { get; set; } = 13;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.SA2" />
		public byte SA2 { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.SID" />
		public byte SID { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.OmronFinsNet.ReadSplits" />
		public int ReadSplits { get; set; } = 500;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Omron.Helper.IOmronFins.PlcType" />
		public OmronPlcType PlcType { get; set; } = OmronPlcType.CSCJ;

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.#ctor(System.String,System.Int32)" />
		public OmronFinsUdp(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.#ctor" />
		public OmronFinsUdp()
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
			base.ByteTransform.IsStringReverseByteWord = true;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FinsUdpMessage();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.PackCommand(System.Byte[])" />
		private byte[] PackCommand(byte[] cmd)
		{
			byte[] array = new byte[10 + cmd.Length];
			array[0] = ICF;
			array[1] = RSV;
			array[2] = GCT;
			array[3] = DNA;
			array[4] = DA1;
			array[5] = DA2;
			array[6] = SNA;
			array[7] = SA1;
			array[8] = SA2;
			array[9] = (byte)incrementSID.GetCurrentValue();
			SID = array[9];
			cmd.CopyTo(array, 10);
			return array;
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			return PackCommand(command);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			return OmronFinsNetHelper.UdpResponseValidAnalysis(response);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			return OmronFinsNetHelper.Read(this, address, length, ReadSplits);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			return OmronFinsNetHelper.Write(this, address, value);
		}

		/// <inheritdoc />
		public override OResult<string> ReadString(string address, ushort length)
		{
			return base.ReadString(address, length, Encoding.UTF8);
		}

		/// <inheritdoc />
		public override OResult Write(string address, string value)
		{
			return base.Write(address, value, Encoding.UTF8);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.Read(Snet.Driver.Profinet.Omron.Helper.IOmronFins,System.String[])" />
		public OResult<byte[]> Read(string[] address)
		{
			return OmronFinsNetHelper.Read(this, address);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			return OmronFinsNetHelper.ReadBool(this, address, length, ReadSplits);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] values)
		{
			return OmronFinsNetHelper.Write(this, address, values);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.Run(Snet.Driver.Core.IReadWriteDevice)" />
		public OResult Run()
		{
			return OmronFinsNetHelper.Run(this);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.Stop(Snet.Driver.Core.IReadWriteDevice)" />
		public OResult Stop()
		{
			return OmronFinsNetHelper.Stop(this);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.ReadCpuUnitData(Snet.Driver.Core.IReadWriteDevice)" />
		public OResult<OmronCpuUnitData> ReadCpuUnitData()
		{
			return OmronFinsNetHelper.ReadCpuUnitData(this);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.ReadCpuUnitStatus(Snet.Driver.Core.IReadWriteDevice)" />
		public OResult<OmronCpuUnitStatus> ReadCpuUnitStatus()
		{
			return OmronFinsNetHelper.ReadCpuUnitStatus(this);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNetHelper.ReadCpuTime(Snet.Driver.Core.IReadWriteDevice)" />
		public OResult<DateTime> ReadCpuTime()
		{
			return OmronFinsNetHelper.ReadCpuTime(this);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"OmronFinsUdp[{IpAddress}:{Port}]";
		}
	}
	/// <inheritdoc cref="T:Snet.Driver.Profinet.Omron.OmronFinsServer" />
	public class OmronFinsUdpServer : OmronFinsServer
	{
		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public OmronFinsUdpServer()
		{
			connectionInitialization = false;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return null;
		}

		/// <inheritdoc />
		protected override string GetLogTextFromBinary(PipeSession session, byte[] content)
		{
			string text = base.GetLogTextFromBinary(session, content);
			if (base.AnalysisLogMessage)
			{
				string text2 = OmronFinsNetHelper.AnalysisAddressLogMessage(session, base.ByteTransform, content, 10);
				text += text2;
			}
			return text;
		}

		/// <inheritdoc />
		protected override byte[] PackCommand(int status, byte[] finsCore, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[14 + data.Length];
			SoftBasic.HexStringToBytes("C0 00 02 00 00 00 00 00 00 00 00 00 00 00").CopyTo(array, 0);
			if (data.Length != 0)
			{
				data.CopyTo(array, 14);
			}
			array[10] = finsCore[0];
			array[11] = finsCore[1];
			array[12] = BitConverter.GetBytes(status)[1];
			array[13] = BitConverter.GetBytes(status)[0];
			return array;
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			byte[] array = ReadFromFinsCore(receive.RemoveBegin(10));
			if (array != null)
			{
				array[4] = receive[7];
				array[7] = receive[4];
				if (base.CopySID)
				{
					array[9] = receive[9];
				}
				else
				{
					array[9] = 0;
				}
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"OmronFinsUdpServer[{base.Port}]";
		}
	}
