	/// <summary>
	/// 欧姆龙的OmronHostLinkCMode的辅助类方法
	/// </summary>
	public class OmronHostLinkCModeHelper
	{
		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Read(System.String,System.UInt16)" />
		/// <remarks>
		/// 地址里可以额外指定单元号信息，例如 s=2;D100
		/// </remarks>
		public static OResult<byte[]> Read(IReadWriteDevice omron, byte unitNumber, string address, ushort length)
		{
			byte unitNumber2 = (byte)SnetHelper.ExtractParameter(ref address, "s", unitNumber);
			OResult<List<byte[]>> oResult = BuildReadCommand(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = omron.ReadFromCoreServer(PackCommand(oResult.Content[i], unitNumber2));
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult<byte[]> oResult3 = ResponseValidAnalysis(oResult2.Content, isRead: true);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult3);
				}
				list.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.Helper.OmronHostLinkCModeHelper.Read(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.UInt16)" />
		public static async Task<OResult<byte[]>> ReadAsync(IReadWriteDevice omron, byte unitNumber, string address, ushort length)
		{
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", unitNumber);
