			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(command);
			}
			List<byte> array = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await omron.ReadFromCoreServerAsync(PackCommand(command.Content[i], station));
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				OResult<byte[]> oResult2 = ResponseValidAnalysis(oResult.Content, isRead: true);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				array.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(array.ToArray());
		}

