		/// <summary>
		/// 读取PLC的当前的型号信息<br />
		/// Read the current model information of the PLC
		/// </summary>
		/// <param name="omron">PLC连接对象</param>
		/// <param name="unitNumber">站号信息</param>
		/// <returns>型号</returns>
		public static OResult<string> ReadPlcType(IReadWriteDevice omron, byte unitNumber)
		{
			OResult<byte[]> oResult = omron.ReadFromCoreServer(PackCommand(Encoding.ASCII.GetBytes("MM"), unitNumber));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			int num = Convert.ToInt32(Encoding.ASCII.GetString(oResult.Content, 5, 2), 16);
			if (num > 0)
			{
				return new OResult<string>(num, "Unknown Error");
			}
			return GetModelText(Encoding.ASCII.GetString(oResult.Content, 7, 2));
		}

		/// <summary>
		/// 读取PLC当前的操作模式，0: 编程模式  1: 运行模式  2: 监视模式<br />
		/// Reads the Operation mode of the CPU Unit. 0: PROGRAM mode  1: RUN mode  2: MONITOR mode
		/// </summary>
		/// <param name="omron">PLC连接对象</param>
		/// <param name="unitNumber">站号信息</param>
		/// <returns>0: 编程模式  1: 运行模式  2: 监视模式</returns>
		public static OResult<int> ReadPlcMode(IReadWriteDevice omron, byte unitNumber)
		{
			OResult<byte[]> oResult = omron.ReadFromCoreServer(PackCommand(Encoding.ASCII.GetBytes("MS"), unitNumber));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int>(oResult);
			}
			int num = Convert.ToInt32(Encoding.ASCII.GetString(oResult.Content, 5, 2), 16);
			if (num > 0)
			{
				return new OResult<int>(num, "Unknown Error");
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult.Content, 7, 4).ToHexBytes()[0] & 3);
