		private static OResult<string, int> GetEMAddress(string address, int start, bool isRead)
		{
			string[] array = address.SplitDot();
			int num = Convert.ToInt32(array[0].Substring(start), 16);
			return OResult.CreateSuccessResult((isRead ? "RE" : "WE") + Encoding.ASCII.GetString(SoftBasic.BuildAsciiBytesFrom((byte)num)), (int)ushort.Parse(array[1]));
		}

		/// <summary>
		/// 解析欧姆龙的数据地址，参考来源是Omron手册第188页，比如D100， E1.100<br />
		/// Analyze Omron's data address, the reference source is page 188 of the Omron manual, such as D100, E1.100
		/// </summary>
		/// <param name="address">数据地址</param>
		/// <param name="isBit">是否是位地址</param>
		/// <param name="isRead">是否读取</param>
		/// <returns>解析后的结果地址对象</returns>
		public static OResult<string, int> AnalysisAddress(string address, bool isBit, bool isRead)
		{
			try
			{
				if (isBit)
				{
					if (isRead)
					{
						if (address.StartsWith("TIM", StringComparison.OrdinalIgnoreCase))
						{
							return OResult.CreateSuccessResult("RG", (int)ushort.Parse(address.Substring(3)));
						}
						if (address.StartsWith("CNT", StringComparison.OrdinalIgnoreCase))
						{
							return OResult.CreateSuccessResult("RG", ushort.Parse(address.Substring(3)) + 2048);
						}
					}
					return new OResult<string, int>(StringResources.Language.NotSupportedDataType);
				}
				if (address.StartsWith("DM", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(isRead ? "RD" : "WD", (int)ushort.Parse(address.Substring(2)));
				}
				if (address.StartsWith("LR", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(isRead ? "RL" : "WL", (int)ushort.Parse(address.Substring(2)));
				}
				if (address.StartsWith("HR", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(isRead ? "RH" : "WH", (int)ushort.Parse(address.Substring(2)));
				}
				if (address.StartsWith("AR", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(isRead ? "RJ" : "WJ", (int)ushort.Parse(address.Substring(2)));
				}
				if (address.StartsWith("CIO", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(isRead ? "RR" : "WR", (int)ushort.Parse(address.Substring(3)));
				}
				if (address.StartsWith("TIM", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(isRead ? "RC" : "WC", (int)ushort.Parse(address.Substring(3)));
				}
				if (address.StartsWith("CNT", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(isRead ? "RC" : "WC", ushort.Parse(address.Substring(3)) + 2048);
				}
				if (address.StartsWith("EM", StringComparison.OrdinalIgnoreCase))
				{
					return GetEMAddress(address, 2, isRead);
				}
				switch (address[0])
				{
				case 'D':
				case 'd':
					return OResult.CreateSuccessResult(isRead ? "RD" : "WD", (int)ushort.Parse(address.Substring(1)));
				case 'C':
				case 'c':
					return OResult.CreateSuccessResult(isRead ? "RR" : "WR", (int)ushort.Parse(address.Substring(1)));
				case 'H':
				case 'h':
					return OResult.CreateSuccessResult(isRead ? "RH" : "WH", (int)ushort.Parse(address.Substring(1)));
				case 'A':
				case 'a':
					return OResult.CreateSuccessResult(isRead ? "RJ" : "WJ", (int)ushort.Parse(address.Substring(1)));
				case 'E':
				case 'e':
					return GetEMAddress(address, 1, isRead);
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<string, int>(ex.Message);
			}
		}

		/// <summary>
		/// 根据读取的地址，长度，是否位读取创建Fins协议的核心报文<br />
		/// According to the read address, length, whether to read the core message that creates the Fins protocol
		/// </summary>
		/// <param name="address">地址，具体格式请参照示例说明</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="isBit">是否使用位读取</param>
		/// <returns>带有成功标识的Fins核心报文</returns>
		public static OResult<List<byte[]>> BuildReadCommand(string address, ushort length, bool isBit)
		{
			OResult<string, int> oResult = AnalysisAddress(address, isBit, isRead: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			int[] array = SoftBasic.SplitIntegerToArray(length, 30);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append(oResult.Content1);
				stringBuilder.Append(oResult.Content2.ToString("D4"));
				stringBuilder.Append(array[i].ToString("D4"));
				list.Add(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
				oResult.Content2 += array[i];
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 根据读取的地址，长度，是否位读取创建Fins协议的核心报文<br />
		/// According to the read address, length, whether to read the core message that creates the Fins protocol
		/// </summary>
		/// <param name="address">地址，具体格式请参照示例说明</param>
		/// <param name="value">等待写入的数据</param>
		/// <returns>带有成功标识的Fins核心报文</returns>
		public static OResult<List<byte[]>> BuildWriteWordCommand(string address, byte[] value)
		{
			OResult<string, int> oResult = AnalysisAddress(address, isBit: false, isRead: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			List<byte[]> list = SoftBasic.ArraySplitByLength(value, 60);
			List<byte[]> list2 = new List<byte[]>();
			for (int i = 0; i < list.Count; i++)
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append(oResult.Content1);
				stringBuilder.Append(oResult.Content2.ToString("D4"));
				if (list[i].Length != 0)
				{
					stringBuilder.Append(list[i].ToHexString());
				}
				list2.Add(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
				oResult.Content2 += list[i].Length / 2;
			}
			return OResult.CreateSuccessResult(list2);
		}

		/// <summary>
		/// 验证欧姆龙的Fins-TCP返回的数据是否正确的数据，如果正确的话，并返回所有的数据内容
		/// </summary>
		/// <param name="response">来自欧姆龙返回的数据内容</param>
		/// <param name="isRead">是否读取</param>
		/// <returns>带有是否成功的结果对象</returns>
		public static OResult<byte[]> ResponseValidAnalysis(byte[] response, bool isRead)
		{
			if (response.Length >= 11)
			{
				try
				{
					int num = Convert.ToInt32(Encoding.ASCII.GetString(response, 5, 2), 16);
					byte[] array = null;
					string input = Encoding.ASCII.GetString(response, 3, 2);
					if (response.Length > 11)
					{
						array = ((!input.EqualsNoCase("RG")) ? Encoding.ASCII.GetString(response, 7, response.Length - 11).ToHexBytes() : response.SelectMiddle(7, response.Length - 11));
					}
					if (num > 0)
					{
						return new OResult<byte[]>
						{
							ErrorCode = num,
							Message = GetErrorMessage(num),
							Content = array
						};
					}
					return OResult.CreateSuccessResult(array);
				}
				catch (Exception ex)
				{
					return new OResult<byte[]>("ResponseValidAnalysis failed: " + ex.Message + " Source: " + response.ToHexString(' '));
				}
			}
			return new OResult<byte[]>(StringResources.Language.OmronReceiveDataError);
		}

		/// <summary>
		/// 将普通的指令打包成完整的指令
		/// </summary>
		/// <param name="cmd">fins指令</param>
		/// <param name="unitNumber">站号信息</param>
		/// <returns>完整的质量</returns>
		public static byte[] PackCommand(byte[] cmd, byte unitNumber)
		{
			byte[] array = new byte[7 + cmd.Length];
			array[0] = 64;
			array[1] = SoftBasic.BuildAsciiBytesFrom(unitNumber)[0];
			array[2] = SoftBasic.BuildAsciiBytesFrom(unitNumber)[1];
			array[^2] = 42;
			array[^1] = 13;
			cmd.CopyTo(array, 3);
			int num = array[0];
			for (int i = 1; i < array.Length - 4; i++)
			{
				num ^= array[i];
			}
			array[^4] = SoftBasic.BuildAsciiBytesFrom((byte)num)[0];
			array[^3] = SoftBasic.BuildAsciiBytesFrom((byte)num)[1];
			return array;
		}

		/// <summary>
		/// 获取model的字符串描述信息
		/// </summary>
		/// <param name="model">型号代码</param>
		/// <returns>是否解析成功</returns>
		public static OResult<string> GetModelText(string model)
		{
			return model switch
			{
				"30" => OResult.CreateSuccessResult("CS/CJ"), 
				"01" => OResult.CreateSuccessResult("C250"), 
				"02" => OResult.CreateSuccessResult("C500"), 
				"03" => OResult.CreateSuccessResult("C120/C50"), 
				"09" => OResult.CreateSuccessResult("C250F"), 
				"0A" => OResult.CreateSuccessResult("C500F"), 
				"0B" => OResult.CreateSuccessResult("C120F"), 
				"0E" => OResult.CreateSuccessResult("C2000"), 
				"10" => OResult.CreateSuccessResult("C1000H"), 
				"11" => OResult.CreateSuccessResult("C2000H/CQM1/CPM1"), 
				"12" => OResult.CreateSuccessResult("C20H/C28H/C40H, C200H, C200HS, C200HX/HG/HE (-ZE)"), 
				"20" => OResult.CreateSuccessResult("CV500"), 
				"21" => OResult.CreateSuccessResult("CV1000"), 
				"22" => OResult.CreateSuccessResult("CV2000"), 
				"40" => OResult.CreateSuccessResult("CVM1-CPU01-E"), 
				"41" => OResult.CreateSuccessResult("CVM1-CPU11-E"), 
				"42" => OResult.CreateSuccessResult("CVM1-CPU21-E"), 
				_ => new OResult<string>("Unknown model, model code:" + model), 
			};
		}

		/// <summary>
		/// 根据错误码的信息，返回错误的具体描述的文本<br />
		/// According to the information of the error code, return the text of the specific description of the error
		/// </summary>
		/// <param name="err">错误码</param>
		/// <returns>错误的描述文本</returns>
		public static string GetErrorMessage(int err)
		{
			return err switch
			{
				1 => "Not executable in RUN mode", 
				2 => "Not executable in MONITOR mode", 
				3 => "UM write-protected", 
				4 => "Address over: The program address setting in an read or write command is above the highest program address.", 
				11 => "Not executable in PROGRAM mode", 
				19 => "The FCS is wrong.", 
				20 => "The command format is wrong, or a command that cannot be divided has been divided, or the frame length is smaller than the minimum length for the applicable command.", 
				21 => "1. The data is outside of the specified range or too long. 2.Hexadecimal data has not been specified.", 
				22 => "Command not supported: The operand specified in an SV Read or SV Change command does not exist in the program.", 
				24 => "Frame length error: The maximum frame length of 131 bytes was exceeded.", 
				25 => "Not executable: The read SV exceeded 9,999, or an I/O memory batch read was executed when items to read were not registered for composite command, or access right was not obtained.", 
				32 => "Could not create I/O table", 
				33 => "Not executable due to CPU Unit CPU error( See note.)", 
				35 => "User memory protected, The UM is read-protected or writeprotected.", 
				163 => "Aborted due to FCS error in transmission data", 
				164 => "Aborted due to format error in transmission data", 
				165 => "Aborted due to entry number data error in transmission data", 
				168 => "Aborted due to frame length error in transmission data", 
				_ => StringResources.Language.UnknownError, 
			};
		}
	}
	/// <summary>
	/// 欧姆龙的OmronHostLink相关辅助方法
	/// </summary>
	public class OmronHostLinkHelper
	{
		/// <summary>
		/// 验证欧姆龙的Fins-TCP返回的数据是否正确的数据，如果正确的话，并返回所有的数据内容
		/// </summary>
		/// <param name="send">发送的报文信息</param>
		/// <param name="response">来自欧姆龙返回的数据内容</param>
		/// <returns>带有是否成功的结果对象</returns>
		public static OResult<byte[]> ResponseValidAnalysis(byte[] send, byte[] response)
		{
			if (response.Length >= 27)
			{
				try
				{
					string text = Encoding.ASCII.GetString(send, 14, 4);
					string text2 = Encoding.ASCII.GetString(response, 15, 4);
					if (text2 != text)
					{
						return new OResult<byte[]>("Send Command [" + text + "] not the same as receive command [" + text2 + "] source:[" + SoftBasic.GetAsciiStringRender(response) + "]");
					}
					int num;
					try
					{
						num = Convert.ToInt32(Encoding.ASCII.GetString(response, 19, 4), 16);
					}
					catch (Exception ex)
					{
						return new OResult<byte[]>("Get error code failed: " + ex.Message + Environment.NewLine + "Source Data: " + SoftBasic.GetAsciiStringRender(response));
					}
					byte[] array = new byte[0];
					if (response.Length > 27)
					{
						array = SoftBasic.HexStringToBytes(Encoding.ASCII.GetString(response, 23, response.Length - 27));
					}
					if (num > 0)
					{
						return new OResult<byte[]>
						{
							ErrorCode = num,
							Content = array,
							Message = GetErrorText(num)
						};
					}
					if (Encoding.ASCII.GetString(response, 15, 4) == "0104")
					{
						byte[] array2 = ((array.Length != 0) ? new byte[array.Length * 2 / 3] : new byte[0]);
						for (int i = 0; i < array.Length / 3; i++)
						{
							array2[i * 2] = array[i * 3 + 1];
							array2[i * 2 + 1] = array[i * 3 + 2];
						}
						array = array2;
					}
					return OResult.CreateSuccessResult(array);
				}
				catch (Exception ex2)
				{
					return new OResult<byte[]>("ResponseValidAnalysis failed: " + ex2.Message + " Source: " + response.ToHexString(' '));
				}
			}
			return new OResult<byte[]>(StringResources.Language.OmronReceiveDataError + " Source Data: " + response.ToHexString(' '));
		}

		/// <summary>
		/// 根据错误信息获取当前的文本描述信息
		/// </summary>
		/// <param name="error">错误代号</param>
		/// <returns>文本消息</returns>
		public static string GetErrorText(int error)
