		/// <summary>
		/// 将 fins 命令的报文打包成 HostLink 格式的报文信息，打包之后的结果可以直接发送给PLC<br />
		/// Pack the message of the fins command into the message information in the HostLink format, and the packaged result can be sent directly to the PLC
		/// </summary>
		/// <param name="hostLink">HostLink协议的plc通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="cmd">fins命令</param>
		/// <returns>可发送PLC的完整的报文信息</returns>
		public static byte[] PackCommand(IHostLink hostLink, byte station, byte[] cmd)
		{
			cmd = SoftBasic.BytesToAsciiBytes(cmd);
			byte[] array = new byte[18 + cmd.Length];
			array[0] = 64;
			array[1] = SoftBasic.BuildAsciiBytesFrom(station)[0];
			array[2] = SoftBasic.BuildAsciiBytesFrom(station)[1];
			array[3] = 70;
			array[4] = 65;
			array[5] = hostLink.ResponseWaitTime;
			array[6] = SoftBasic.BuildAsciiBytesFrom(hostLink.ICF)[0];
			array[7] = SoftBasic.BuildAsciiBytesFrom(hostLink.ICF)[1];
			array[8] = SoftBasic.BuildAsciiBytesFrom(hostLink.DA2)[0];
			array[9] = SoftBasic.BuildAsciiBytesFrom(hostLink.DA2)[1];
			array[10] = SoftBasic.BuildAsciiBytesFrom(hostLink.SA2)[0];
			array[11] = SoftBasic.BuildAsciiBytesFrom(hostLink.SA2)[1];
			array[12] = SoftBasic.BuildAsciiBytesFrom(hostLink.SID)[0];
			array[13] = SoftBasic.BuildAsciiBytesFrom(hostLink.SID)[1];
			array[^2] = 42;
			array[^1] = 13;
			cmd.CopyTo(array, 14);
			int num = array[0];
			for (int i = 1; i < array.Length - 4; i++)
			{
				num ^= array[i];
			}
			array[^4] = SoftBasic.BuildAsciiBytesFrom((byte)num)[0];
			array[^3] = SoftBasic.BuildAsciiBytesFrom((byte)num)[1];
			return array;
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Read(System.String,System.UInt16)" />
		public static OResult<byte[]> Read(IHostLink hostLink, string address, ushort length)
		{
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", hostLink.UnitNumber);
			OResult<List<byte[]>> oResult = OmronFinsNetHelper.BuildReadCommand(hostLink.PlcType, address, length, isBit: false, hostLink.ReadSplits);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = hostLink.ReadFromCoreServer(PackCommand(hostLink, station, oResult.Content[i]));
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				list.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

