		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.ReadBool(System.String,System.UInt16)" />
		public static OResult<bool[]> ReadBool(IHostLink hostLink, string address, ushort length)
		{
			byte b = (byte)SnetHelper.ExtractParameter(ref address, "s", hostLink.UnitNumber);
			if (address.StartsWith("DR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("IR", StringComparison.OrdinalIgnoreCase))
			{
				if (!address.Contains("."))
				{
					address += ".0";
				}
				string text = ((b != hostLink.UnitNumber) ? $"s={b};" : string.Empty);
				return SnetHelper.ReadBool(hostLink, text + address, length, 16, reverseByWord: true);
			}
			OResult<List<byte[]>> oResult = OmronFinsNetHelper.BuildReadCommand(hostLink.PlcType, address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<bool> list = new List<bool>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = hostLink.ReadFromCoreServer(PackCommand(hostLink, b, oResult.Content[i]));
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				if (oResult2.Content.Length == 0)
				{
					return new OResult<bool[]>("Data is empty.");
				}
				list.AddRange(oResult2.Content.Select((byte m) => m != 0));
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Omron.OmronFinsNet.Write(System.String,System.Boolean[])" />
		public static OResult Write(IHostLink hostLink, string address, bool[] values)
		{
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", hostLink.UnitNumber);
			if (address.StartsWith("DR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("IR", StringComparison.OrdinalIgnoreCase))
			{
				return new OResult("DR and IR address not support bit write");
			}
			OResult<byte[]> oResult = OmronFinsNetHelper.BuildWriteWordCommand(hostLink.PlcType, address, values.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray(), isBit: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = hostLink.ReadFromCoreServer(PackCommand(hostLink, station, oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

