		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecA1ENet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadCommand(address, length, isBit: false, PLCNumber);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult oResult3 = CheckResponseLegal(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult3);
				}
				OResult<byte[]> oResult4 = ExtractActualData(oResult2.Content, isBit: false);
				if (!oResult4.IsSuccess)
				{
					return oResult4;
				}
				list.AddRange(oResult4.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

