		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecA1EAsciiNet.ReadBool(System.String,System.UInt16)" />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			if (address.IndexOf('.') > 0)
			{
				return await SnetHelper.ReadBoolAsync(this, address, length);
			}
			OResult<List<byte[]>> command = BuildReadCommand(address, length, isBit: true, PLCNumber);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(command);
			}
			List<byte> array = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				OResult oResult2 = CheckResponseLegal(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult<byte[]> oResult3 = ExtractActualData(oResult.Content, isBit: true);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				array.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(array.Select((byte m) => m == 1).Take(length).ToArray());
		}

