		/// <summary>
		/// 根据类型地址长度确认需要读取的指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="length">长度</param>
		/// <param name="isBit">指示是否按照位成批的读出</param>
		/// <param name="plcNumber">PLC编号</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<List<byte[]>> BuildReadCommand(string address, ushort length, bool isBit, byte plcNumber)
		{
			OResult<MelsecA1EDataType, int> oResult = MelsecHelper.McA1EAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			byte value = ((!isBit) ? ((byte)1) : ((byte)0));
			int[] array = SoftBasic.SplitIntegerToArray(length, isBit ? 256 : 64);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				byte[] array2 = new byte[24]
				{
					SoftBasic.BuildAsciiBytesFrom(value)[0],
					SoftBasic.BuildAsciiBytesFrom(value)[1],
					SoftBasic.BuildAsciiBytesFrom(plcNumber)[0],
					SoftBasic.BuildAsciiBytesFrom(plcNumber)[1],
					48,
					48,
					48,
					65,
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[1])[0],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[1])[1],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[0])[0],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[0])[1],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[3])[0],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[3])[1],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[2])[0],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[2])[1],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[1])[0],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[1])[1],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[0])[0],
					SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[0])[1],
					0,
					0,
					0,
					0
				};
				int num = array[i];
				if (num == 256)
				{
					num = 0;
				}
				array2[20] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(num % 256)[0])[0];
				array2[21] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(num % 256)[0])[1];
				array2[22] = 48;
				array2[23] = 48;
				list.Add(array2);
				if (isBit)
				{
					oResult.Content2 += array[i];
				}
				else if (oResult.Content1.DataType == 1)
				{
					oResult.Content2 += array[i] * 16;
				}
				else
				{
					oResult.Content2 += array[i];
				}
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 根据类型地址以及需要写入的数据来生成指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="value">数据值</param>
		/// <param name="plcNumber">PLC编号</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<byte[]> BuildWriteWordCommand(string address, byte[] value, byte plcNumber)
		{
			OResult<MelsecA1EDataType, int> oResult = MelsecHelper.McA1EAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			value = MelsecHelper.TransByteArrayToAsciiByteArray(value);
			byte[] array = new byte[24 + value.Length];
			array[0] = 48;
			array[1] = 51;
			array[2] = SoftBasic.BuildAsciiBytesFrom(plcNumber)[0];
			array[3] = SoftBasic.BuildAsciiBytesFrom(plcNumber)[1];
			array[4] = 48;
			array[5] = 48;
			array[6] = 48;
			array[7] = 65;
			array[8] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[1])[0];
			array[9] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[1])[1];
			array[10] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[0])[0];
			array[11] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[0])[1];
			array[12] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[3])[0];
			array[13] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[3])[1];
			array[14] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[2])[0];
			array[15] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[2])[1];
			array[16] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[1])[0];
			array[17] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[1])[1];
			array[18] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[0])[0];
			array[19] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[0])[1];
			array[20] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(value.Length / 4)[0])[0];
			array[21] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(value.Length / 4)[0])[1];
			array[22] = 48;
			array[23] = 48;
			value.CopyTo(array, 24);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 根据类型地址以及需要写入的数据来生成指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="value">数据值</param>
		/// <param name="plcNumber">PLC编号</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<byte[]> BuildWriteBoolCommand(string address, bool[] value, byte plcNumber)
		{
			OResult<MelsecA1EDataType, int> oResult = MelsecHelper.McA1EAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = value.Select((bool m) => (byte)(m ? 49u : 48u)).ToArray();
			if (array.Length % 2 == 1)
			{
				array = SoftBasic.SpliceArray<byte>(array, new byte[1] { 48 });
			}
			byte[] array2 = new byte[24 + array.Length];
			array2[0] = 48;
			array2[1] = 50;
			array2[2] = SoftBasic.BuildAsciiBytesFrom(plcNumber)[0];
			array2[3] = SoftBasic.BuildAsciiBytesFrom(plcNumber)[1];
			array2[4] = 48;
			array2[5] = 48;
			array2[6] = 48;
			array2[7] = 65;
			array2[8] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[1])[0];
			array2[9] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[1])[1];
			array2[10] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[0])[0];
			array2[11] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content1.DataCode)[0])[1];
			array2[12] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[3])[0];
			array2[13] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[3])[1];
			array2[14] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[2])[0];
			array2[15] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[2])[1];
			array2[16] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[1])[0];
			array2[17] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[1])[1];
			array2[18] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[0])[0];
			array2[19] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(oResult.Content2)[0])[1];
			array2[20] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(value.Length)[0])[0];
			array2[21] = SoftBasic.BuildAsciiBytesFrom(BitConverter.GetBytes(value.Length)[0])[1];
			array2[22] = 48;
			array2[23] = 48;
			array.CopyTo(array2, 24);
			return OResult.CreateSuccessResult(array2);
		}

		/// <summary>
		/// 检测反馈的消息是否合法
		/// </summary>
		/// <param name="response">接收的报文</param>
		/// <returns>是否成功</returns>
		public static OResult CheckResponseLegal(byte[] response)
		{
			if (response.Length < 4)
			{
				return new OResult(StringResources.Language.ReceiveDataLengthTooShort);
			}
			if (response[2] == 48 && response[3] == 48)
			{
				return OResult.CreateSuccessResult();
			}
			if (response[2] == 53 && response[3] == 66)
			{
				return new OResult(Convert.ToInt32(Encoding.ASCII.GetString(response, 4, 2), 16), StringResources.Language.MelsecPleaseReferToManualDocument);
			}
			return new OResult(Convert.ToInt32(Encoding.ASCII.GetString(response, 2, 2), 16), StringResources.Language.MelsecPleaseReferToManualDocument);
		}

		/// <summary>
		/// 从PLC反馈的数据中提取出实际的数据内容，需要传入反馈数据，是否位读取
		/// </summary>
		/// <param name="response">反馈的数据内容</param>
		/// <param name="isBit">是否位读取</param>
		/// <returns>解析后的结果对象</returns>
		public static OResult<byte[]> ExtractActualData(byte[] response, bool isBit)
		{
			if (isBit)
			{
				return OResult.CreateSuccessResult((from m in response.RemoveBegin(4)
					select (m != 48) ? ((byte)1) : ((byte)0)).ToArray());
			}
			return OResult.CreateSuccessResult(MelsecHelper.TransAsciiByteArrayToByteArray(response.RemoveBegin(4)));
		}
	}
