	/// <summary>
	/// 三菱PLC通讯协议，采用A兼容1E帧协议实现，使用二进制码通讯，请根据实际型号来进行选取<br />
	/// Mitsubishi PLC communication protocol, implemented using A compatible 1E frame protocol, using binary code communication, please choose according to the actual model
	/// </summary>
	/// <remarks>
	/// 本类适用于的PLC列表
	/// <list type="number">
	/// <item>FX3U(C) PLC   测试人sandy_liao</item>
	/// </list>
	/// <note type="important">本通讯类由CKernal推送，感谢</note>
	/// </remarks>
	public class MelsecA1ENet : DeviceTcpNet
	{
		/// <summary>
		/// PLC编号，默认为0xFF<br />
		/// PLC number, default is 0xFF
		/// </summary>
		public byte PLCNumber { get; set; } = byte.MaxValue;

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public MelsecA1ENet()
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 指定ip地址和端口来来实例化一个默认的对象<br />
		/// Specify the IP address and port to instantiate a default object
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
		/// <param name="port">PLC的端口</param>
		public MelsecA1ENet(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new MelsecA1EBinaryMessage();
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadCommand(address, length, isBit: false, PLCNumber);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult oResult3 = CheckResponseLegal(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult3);
				}
				OResult<byte[]> oResult4 = ExtractActualData(oResult2.Content, isBit: false);
				if (!oResult4.IsSuccess)
				{
					return oResult4;
				}
				list.AddRange(oResult4.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteWordCommand(address, value, PLCNumber);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponseLegal(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<List<byte[]>> command = BuildReadCommand(address, length, isBit: false, PLCNumber);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(command);
			}
			List<byte> array = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				OResult oResult2 = CheckResponseLegal(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult<byte[]> oResult3 = ExtractActualData(oResult.Content, isBit: false);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				array.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(array.ToArray());
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteWordCommand(address, value, PLCNumber);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponseLegal(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 批量读取<see cref="T:System.Boolean" />数组信息，需要指定地址和长度，地址示例M100，S100，B1A，如果是X,Y, X017就是8进制地址，Y10就是16进制地址。<br />
		/// Batch read <see cref="T:System.Boolean" /> array information, need to specify the address and length, return <see cref="T:System.Boolean" /> array. 
		/// Examples of addresses M100, S100, B1A, if it is X, Y, X017 is an octal address, Y10 is a hexadecimal address.
		/// </summary>
		/// <remarks>
		/// 根据协议的规范，最多读取256长度的bool数组信息，如果需要读取更长的bool信息，需要按字为单位进行读取的操作。
		/// </remarks>
		/// <param name="address">数据地址</param>
		/// <param name="length">数据长度</param>
		/// <returns>带有成功标识的byte[]数组</returns>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (address.IndexOf('.') > 0)
			{
				return SnetHelper.ReadBool(this, address, length);
			}
			OResult<List<byte[]>> oResult = BuildReadCommand(address, length, isBit: true, PLCNumber);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult oResult3 = CheckResponseLegal(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				OResult<byte[]> oResult4 = ExtractActualData(oResult2.Content, isBit: true);
				if (!oResult4.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult4);
				}
				list.AddRange(oResult4.Content);
			}
			return OResult.CreateSuccessResult(list.Select((byte m) => m == 1).Take(length).ToArray());
		}

		/// <summary>
		/// 批量写入<see cref="T:System.Boolean" />数组数据，返回是否成功，地址示例M100，S100，B1A，如果是X,Y, X017就是8进制地址，Y10就是16进制地址。<br />
		/// Batch write <see cref="T:System.Boolean" /> array data, return whether the write was successful. 
		/// Examples of addresses M100, S100, B1A, if it is X, Y, X017 is an octal address, Y10 is a hexadecimal address.
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="value">写入值</param>
		/// <returns>带有成功标识的结果类对象</returns>
		public override OResult Write(string address, bool[] value)
		{
			OResult<byte[]> oResult = BuildWriteBoolCommand(address, value, PLCNumber);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return CheckResponseLegal(oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecA1ENet.ReadBool(System.String,System.UInt16)" />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			if (address.IndexOf('.') > 0)
			{
				return await SnetHelper.ReadBoolAsync(this, address, length);
			}
			OResult<List<byte[]>> command = BuildReadCommand(address, length, isBit: true, PLCNumber);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(command);
			}
			List<byte> array = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				OResult oResult2 = CheckResponseLegal(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult<byte[]> oResult3 = ExtractActualData(oResult.Content, isBit: true);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				array.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(array.Select((byte m) => m == 1).Take(length).ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecA1ENet.Write(System.String,System.Boolean[])" />
		public override async Task<OResult> WriteAsync(string address, bool[] values)
		{
			OResult<byte[]> oResult = BuildWriteBoolCommand(address, values, PLCNumber);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return CheckResponseLegal(oResult2.Content);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecA1ENet[{IpAddress}:{Port}]";
		}

		/// <summary>
		/// 根据类型地址长度确认需要读取的指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="length">长度</param>
		/// <param name="isBit">指示是否按照位成批的读出</param>
		/// <param name="plcNumber">PLC编号</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<List<byte[]>> BuildReadCommand(string address, ushort length, bool isBit, byte plcNumber)
		{
			OResult<MelsecA1EDataType, int> oResult = MelsecHelper.McA1EAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			byte b = ((!isBit) ? ((byte)1) : ((byte)0));
			int[] array = SoftBasic.SplitIntegerToArray(length, isBit ? 256 : 64);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				byte[] array2 = new byte[12]
				{
					b,
					plcNumber,
					10,
					0,
					BitConverter.GetBytes(oResult.Content2)[0],
					BitConverter.GetBytes(oResult.Content2)[1],
					BitConverter.GetBytes(oResult.Content2)[2],
					BitConverter.GetBytes(oResult.Content2)[3],
					BitConverter.GetBytes(oResult.Content1.DataCode)[0],
					BitConverter.GetBytes(oResult.Content1.DataCode)[1],
					0,
					0
				};
				int num = array[i];
				if (num == 256)
				{
					num = 0;
				}
				array2[10] = BitConverter.GetBytes(num)[0];
				array2[11] = BitConverter.GetBytes(num)[1];
				list.Add(array2);
				if (isBit)
				{
					oResult.Content2 += array[i];
				}
				else if (oResult.Content1.DataType == 1)
				{
					oResult.Content2 += array[i] * 16;
				}
				else
				{
					oResult.Content2 += array[i];
				}
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 根据类型地址以及需要写入的数据来生成指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="value">数据值</param>
		/// <param name="plcNumber">PLC编号</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<byte[]> BuildWriteWordCommand(string address, byte[] value, byte plcNumber)
		{
			OResult<MelsecA1EDataType, int> oResult = MelsecHelper.McA1EAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[12 + value.Length];
			array[0] = 3;
			array[1] = plcNumber;
			array[2] = 10;
			array[3] = 0;
			array[4] = BitConverter.GetBytes(oResult.Content2)[0];
			array[5] = BitConverter.GetBytes(oResult.Content2)[1];
			array[6] = BitConverter.GetBytes(oResult.Content2)[2];
			array[7] = BitConverter.GetBytes(oResult.Content2)[3];
			array[8] = BitConverter.GetBytes(oResult.Content1.DataCode)[0];
			array[9] = BitConverter.GetBytes(oResult.Content1.DataCode)[1];
			array[10] = BitConverter.GetBytes(value.Length / 2)[0];
			array[11] = BitConverter.GetBytes(value.Length / 2)[1];
			Array.Copy(value, 0, array, 12, value.Length);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 根据类型地址以及需要写入的数据来生成指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="value">数据值</param>
		/// <param name="plcNumber">PLC编号</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<byte[]> BuildWriteBoolCommand(string address, bool[] value, byte plcNumber)
		{
			OResult<MelsecA1EDataType, int> oResult = MelsecHelper.McA1EAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = MelsecHelper.TransBoolArrayToByteData(value);
			byte[] array2 = new byte[12 + array.Length];
			array2[0] = 2;
			array2[1] = plcNumber;
			array2[2] = 10;
			array2[3] = 0;
			array2[4] = BitConverter.GetBytes(oResult.Content2)[0];
			array2[5] = BitConverter.GetBytes(oResult.Content2)[1];
			array2[6] = BitConverter.GetBytes(oResult.Content2)[2];
			array2[7] = BitConverter.GetBytes(oResult.Content2)[3];
			array2[8] = BitConverter.GetBytes(oResult.Content1.DataCode)[0];
			array2[9] = BitConverter.GetBytes(oResult.Content1.DataCode)[1];
			array2[10] = BitConverter.GetBytes(value.Length)[0];
			array2[11] = BitConverter.GetBytes(value.Length)[1];
			Array.Copy(array, 0, array2, 12, array.Length);
			return OResult.CreateSuccessResult(array2);
		}

		/// <summary>
		/// 检测反馈的消息是否合法
		/// </summary>
		/// <param name="response">接收的报文</param>
		/// <returns>是否成功</returns>
		public static OResult CheckResponseLegal(byte[] response)
		{
			if (response.Length < 2)
			{
				return new OResult(StringResources.Language.ReceiveDataLengthTooShort);
			}
			if (response[1] == 0)
			{
				return OResult.CreateSuccessResult();
			}
			if (response[1] == 91 && response.Length > 2)
			{
				return new OResult(response[2], StringResources.Language.MelsecPleaseReferToManualDocument);
			}
			return new OResult(response[1], StringResources.Language.MelsecPleaseReferToManualDocument);
		}

		/// <summary>
		/// 从PLC反馈的数据中提取出实际的数据内容，需要传入反馈数据，是否位读取
		/// </summary>
		/// <param name="response">反馈的数据内容</param>
		/// <param name="isBit">是否位读取</param>
		/// <returns>解析后的结果对象</returns>
		public static OResult<byte[]> ExtractActualData(byte[] response, bool isBit)
		{
			if (isBit)
			{
				byte[] array = new byte[(response.Length - 2) * 2];
				for (int i = 2; i < response.Length; i++)
				{
					if ((response[i] & 0x10) == 16)
					{
						array[(i - 2) * 2] = 1;
					}
					if ((response[i] & 1) == 1)
					{
						array[(i - 2) * 2 + 1] = 1;
					}
				}
				return OResult.CreateSuccessResult(array);
			}
			return OResult.CreateSuccessResult(response.RemoveBegin(2));
		}
	}
	/// <summary>
	/// 三菱MC-A1E协议的虚拟服务器，支持M,X,Y,D,W的数据池读写操作，支持二进制及ASCII格式进行读写操作，需要在实例化的时候指定。<br />
	/// The Mitsubishi MC-A1E protocol virtual server supports M, X, Y, D, W data pool read and write operations, 
	/// and supports binary and ASCII format read and write operations, which need to be specified during instantiation.
	/// </summary>
	/// <remarks>
	/// 本三菱的虚拟PLC仅限商业授权用户使用，感谢支持。
	/// 如果你没有可以测试的三菱PLC，想要测试自己开发的上位机软件，或是想要在本机实现虚拟PLC，然后进行IO的输入输出练习，都可以使用本类来实现，地址参考DEMO程序
	/// </remarks>
	public class MelsecA1EServer : MelsecMcServer
	{
		/// <summary>
		/// 实例化一个默认参数的mc协议的服务器<br />
		/// Instantiate a mc protocol server with default parameters
		/// </summary>
		/// <param name="isBinary">是否是二进制，默认是二进制，否则是ASCII格式</param>
		public MelsecA1EServer(bool isBinary = true)
			: base(isBinary)
		{
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return null;
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (base.IsBinary)
			{
				return OResult.CreateSuccessResult(ReadFromMcCore(receive));
			}
			return OResult.CreateSuccessResult(ReadFromMcAsciiCore(receive));
		}

		private byte[] PackResponseCommand(byte[] mcCore, byte err, byte code, byte[] data)
		{
			byte[] array = new byte[2]
			{
				(byte)(mcCore[0] + 128),
				err
			};
			switch (err)
			{
			case 91:
				return SoftBasic.SpliceArray<byte>(array, new byte[1] { code });
			default:
				return array;
			case 0:
				if (data == null)
				{
					return array;
				}
				return SoftBasic.SpliceArray<byte>(array, data);
			}
		}

		private byte[] PackResponseCommand(byte[] mcCore, byte err, byte code, bool[] data)
		{
			byte[] array = new byte[2]
			{
				(byte)(mcCore[0] + 128),
				err
			};
			switch (err)
			{
			case 91:
				return SoftBasic.SpliceArray<byte>(array, new byte[1] { code });
			default:
				return array;
			case 0:
				if (data == null)
				{
					return array;
				}
				return SoftBasic.SpliceArray<byte>(array, MelsecHelper.TransBoolArrayToByteData(data));
			}
		}

		private string GetAddressFromDataCode(ushort dataCode, int address)
		{
			if (dataCode == MelsecA1EDataType.M.DataCode)
			{
				return "M" + address;
			}
			if (dataCode == MelsecA1EDataType.X.DataCode)
			{
				return "X" + address.ToString("X");
			}
			if (dataCode == MelsecA1EDataType.Y.DataCode)
			{
				return "Y" + address.ToString("X");
			}
			if (dataCode == MelsecA1EDataType.S.DataCode)
			{
				return "S" + address;
			}
			if (dataCode == MelsecA1EDataType.F.DataCode)
			{
				return "F" + address;
			}
			if (dataCode == MelsecA1EDataType.B.DataCode)
			{
				return "B" + address.ToString("X");
			}
			if (dataCode == MelsecA1EDataType.D.DataCode)
			{
				return "D" + address;
			}
			if (dataCode == MelsecA1EDataType.R.DataCode)
			{
				return "R" + address;
			}
			if (dataCode == MelsecA1EDataType.W.DataCode)
			{
				return "W" + address.ToString("X");
			}
			return string.Empty;
		}

		/// <inheritdoc />
		protected override byte[] ReadFromMcCore(byte[] mcCore)
		{
			try
			{
				int address = BitConverter.ToInt32(mcCore, 4);
				ushort num = BitConverter.ToUInt16(mcCore, 8);
				ushort num2 = BitConverter.ToUInt16(mcCore, 10);
				string addressFromDataCode = GetAddressFromDataCode(num, address);
				if (mcCore[0] == 0)
				{
					if (num == MelsecA1EDataType.M.DataCode || num == MelsecA1EDataType.X.DataCode || num == MelsecA1EDataType.Y.DataCode || num == MelsecA1EDataType.S.DataCode || num == MelsecA1EDataType.F.DataCode || num == MelsecA1EDataType.B.DataCode)
					{
						if (num2 == 0)
						{
							num2 = 256;
						}
						if (num2 > 256)
						{
							return PackResponseCommand(mcCore, 16, 0, new bool[0]);
						}
						OResult<bool[]> oResult = ReadBool(addressFromDataCode, num2);
						if (!oResult.IsSuccess)
						{
							return PackResponseCommand(mcCore, 16, 0, new bool[0]);
						}
						return PackResponseCommand(mcCore, 0, 0, oResult.Content);
					}
				}
				else if (mcCore[0] == 1)
				{
					if (num == MelsecA1EDataType.M.DataCode || num == MelsecA1EDataType.X.DataCode || num == MelsecA1EDataType.Y.DataCode || num == MelsecA1EDataType.S.DataCode || num == MelsecA1EDataType.F.DataCode || num == MelsecA1EDataType.B.DataCode || num == MelsecA1EDataType.D.DataCode || num == MelsecA1EDataType.R.DataCode || num == MelsecA1EDataType.W.DataCode)
					{
						if (num2 > 64)
						{
							return PackResponseCommand(mcCore, 16, 0, new byte[0]);
						}
						OResult<byte[]> oResult2 = Read(addressFromDataCode, num2);
						if (!oResult2.IsSuccess)
						{
							return PackResponseCommand(mcCore, 16, 0, new byte[0]);
						}
						return PackResponseCommand(mcCore, 0, 0, oResult2.Content);
					}
				}
				else if (mcCore[0] == 2)
				{
					bool[] value = MelsecHelper.TransByteArrayToBoolData(mcCore, 12, num2);
					if (num == MelsecA1EDataType.M.DataCode || num == MelsecA1EDataType.X.DataCode || num == MelsecA1EDataType.Y.DataCode || num == MelsecA1EDataType.S.DataCode || num == MelsecA1EDataType.F.DataCode || num == MelsecA1EDataType.B.DataCode)
					{
						if (!Write(addressFromDataCode, value).IsSuccess)
						{
							return PackResponseCommand(mcCore, 16, 0, new byte[0]);
						}
						return PackResponseCommand(mcCore, 0, 0, new byte[0]);
					}
				}
				else if (mcCore[0] == 3)
				{
					byte[] value2 = mcCore.RemoveBegin(12);
					if (num == MelsecA1EDataType.M.DataCode || num == MelsecA1EDataType.X.DataCode || num == MelsecA1EDataType.Y.DataCode || num == MelsecA1EDataType.S.DataCode || num == MelsecA1EDataType.F.DataCode || num == MelsecA1EDataType.B.DataCode || num == MelsecA1EDataType.D.DataCode || num == MelsecA1EDataType.R.DataCode || num == MelsecA1EDataType.W.DataCode)
					{
						if (!Write(addressFromDataCode, value2).IsSuccess)
						{
							return PackResponseCommand(mcCore, 16, 0, new byte[0]);
						}
						return PackResponseCommand(mcCore, 0, 0, new byte[0]);
					}
				}
				return null;
			}
			catch (Exception ex)
			{
				base.LogNet?.WriteException(ToString(), ex);
				return null;
			}
		}

		private byte[] PackAsciiResponseCommand(byte[] mcCore, byte[] data)
		{
			byte[] array = new byte[4]
			{
				(byte)(mcCore[0] + 8),
				mcCore[1],
				48,
				48
			};
			if (data == null)
			{
				return array;
			}
			return SoftBasic.SpliceArray<byte>(array, MelsecHelper.TransByteArrayToAsciiByteArray(data));
		}

		private byte[] PackAsciiResponseCommand(byte[] mcCore, bool[] data)
		{
			byte[] array = new byte[4]
			{
				(byte)(mcCore[0] + 8),
				mcCore[1],
				48,
				48
			};
			if (data == null)
			{
				return array;
			}
			if (data.Length % 2 == 1)
			{
				data = SoftBasic.ArrayExpandToLength(data, data.Length + 1);
			}
			return SoftBasic.SpliceArray<byte>(array, data.Select((bool m) => (byte)(m ? 49u : 48u)).ToArray());
		}

		/// <inheritdoc />
		protected override byte[] ReadFromMcAsciiCore(byte[] mcCore)
		{
			try
			{
				byte b = Convert.ToByte(Encoding.ASCII.GetString(mcCore, 0, 2), 16);
				int address = Convert.ToInt32(Encoding.ASCII.GetString(mcCore, 12, 8), 16);
				ushort num = Convert.ToUInt16(Encoding.ASCII.GetString(mcCore, 8, 4), 16);
				ushort num2 = Convert.ToUInt16(Encoding.ASCII.GetString(mcCore, 20, 2), 16);
				string addressFromDataCode = GetAddressFromDataCode(num, address);
				switch (b)
				{
				case 0:
					if (num == MelsecA1EDataType.M.DataCode || num == MelsecA1EDataType.X.DataCode || num == MelsecA1EDataType.Y.DataCode || num == MelsecA1EDataType.S.DataCode || num == MelsecA1EDataType.F.DataCode || num == MelsecA1EDataType.B.DataCode)
					{
						if (num2 == 0)
						{
							num2 = 256;
						}
						return PackAsciiResponseCommand(mcCore, ReadBool(addressFromDataCode, num2).Content);
					}
					break;
				case 1:
					if (num == MelsecA1EDataType.M.DataCode || num == MelsecA1EDataType.X.DataCode || num == MelsecA1EDataType.Y.DataCode || num == MelsecA1EDataType.S.DataCode || num == MelsecA1EDataType.F.DataCode || num == MelsecA1EDataType.B.DataCode || num == MelsecA1EDataType.D.DataCode || num == MelsecA1EDataType.R.DataCode || num == MelsecA1EDataType.W.DataCode)
					{
						return PackAsciiResponseCommand(mcCore, Read(addressFromDataCode, num2).Content);
					}
					break;
				case 2:
				{
					bool[] value2 = (from m in mcCore.SelectMiddle(24, num2)
						select m == 49).ToArray();
					if (num == MelsecA1EDataType.M.DataCode || num == MelsecA1EDataType.X.DataCode || num == MelsecA1EDataType.Y.DataCode || num == MelsecA1EDataType.S.DataCode || num == MelsecA1EDataType.F.DataCode || num == MelsecA1EDataType.B.DataCode)
					{
						Write(addressFromDataCode, value2);
						return PackAsciiResponseCommand(mcCore, new byte[0]);
					}
					break;
				}
				case 3:
				{
					byte[] value = MelsecHelper.TransAsciiByteArrayToByteArray(mcCore.RemoveBegin(24));
					if (num == MelsecA1EDataType.M.DataCode || num == MelsecA1EDataType.X.DataCode || num == MelsecA1EDataType.Y.DataCode || num == MelsecA1EDataType.S.DataCode || num == MelsecA1EDataType.F.DataCode || num == MelsecA1EDataType.B.DataCode || num == MelsecA1EDataType.D.DataCode || num == MelsecA1EDataType.R.DataCode || num == MelsecA1EDataType.W.DataCode)
					{
						Write(addressFromDataCode, value);
						return PackAsciiResponseCommand(mcCore, new byte[0]);
					}
					break;
				}
				}
				return null;
			}
			catch (Exception ex)
			{
				base.LogNet?.WriteException(ToString(), ex);
				return null;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecA1EServer[{base.Port}]";
		}
	}
