	/// <summary>
	/// 三菱的虚拟的FxLinks服务器
	/// </summary>
	public class MelsecFxLinksServer : DeviceServer
	{
		private SoftBuffer xBuffer;

		private SoftBuffer yBuffer;

		private SoftBuffer mBuffer;

		private SoftBuffer sBuffer;

		private SoftBuffer dBuffer;

		private SoftBuffer rBuffer;

		private const int DataPoolLength = 65536;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteA3C.Station" />
		public byte Station { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteA3C.SumCheck" />
		public bool SumCheck { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteA3C.Format" />
		public int Format { get; set; } = 1;

		/// <summary>
		/// 实例化一个虚拟的FxLinks服务器
		/// </summary>
		public MelsecFxLinksServer()
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
			LogMsgFormatBinary = false;
			xBuffer = new SoftBuffer(131072);
			yBuffer = new SoftBuffer(131072);
			mBuffer = new SoftBuffer(131072);
			sBuffer = new SoftBuffer(131072);
			dBuffer = new SoftBuffer(131072);
			rBuffer = new SoftBuffer(131072);
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<MelsecFxLinksAddress> oResult = MelsecFxLinksAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content.TypeCode == "X")
			{
				return OResult.CreateSuccessResult(xBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.TypeCode == "Y")
			{
				return OResult.CreateSuccessResult(yBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.TypeCode == "M")
			{
				return OResult.CreateSuccessResult(mBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.TypeCode == "S")
			{
				return OResult.CreateSuccessResult(sBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.TypeCode == "D")
			{
				return OResult.CreateSuccessResult(dBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
			}
			if (oResult.Content.TypeCode == "R")
			{
				return OResult.CreateSuccessResult(rBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
			}
			return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<MelsecFxLinksAddress> oResult = MelsecFxLinksAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content.TypeCode == "X")
			{
				xBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else if (oResult.Content.TypeCode == "Y")
			{
				yBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else if (oResult.Content.TypeCode == "M")
			{
				mBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else if (oResult.Content.TypeCode == "S")
			{
				sBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else if (oResult.Content.TypeCode == "D")
			{
				dBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
			}
			else
			{
				if (!(oResult.Content.TypeCode == "R"))
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
				}
				rBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<MelsecFxLinksAddress> oResult = MelsecFxLinksAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if (oResult.Content.TypeCode == "X")
			{
				return OResult.CreateSuccessResult(xBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.TypeCode == "Y")
			{
				return OResult.CreateSuccessResult(yBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.TypeCode == "M")
			{
				return OResult.CreateSuccessResult(mBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.TypeCode == "S")
			{
				return OResult.CreateSuccessResult(sBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] value)
		{
			OResult<MelsecFxLinksAddress> oResult = MelsecFxLinksAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content.TypeCode == "X")
			{
				xBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.TypeCode == "Y")
			{
				yBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.TypeCode == "M")
			{
				mBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else
			{
				if (!(oResult.Content.TypeCode == "S"))
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
				}
				sBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return null;
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			OResult<byte[]> oResult = ExtraMcCore(receive, Format);
			if (!oResult.IsSuccess)
			{
				if (oResult.ErrorCode < 256 && oResult.ErrorCode > 0)
				{
					return OResult.CreateSuccessResult(PackCommand((byte)oResult.ErrorCode, null, Format));
				}
				return oResult;
			}
			switch (Encoding.ASCII.GetString(oResult.Content, 0, 2))
			{
			case "BR":
				return ReadBoolByCommand(oResult.Content);
			case "WR":
			case "QR":
				return ReadWordByCommand(oResult.Content);
			case "BW":
				return WriteBoolByCommand(oResult.Content);
			case "WW":
			case "QW":
				return WriteWordByCommand(oResult.Content);
			case "RR":
				return OResult.CreateSuccessResult(PackCommand(0, null, Format));
			case "RS":
				return OResult.CreateSuccessResult(PackCommand(0, null, Format));
			case "PC":
				return OResult.CreateSuccessResult(PackCommand(0, Encoding.ASCII.GetBytes("F3"), Format));
			default:
				return OResult.CreateSuccessResult(PackCommand(6, null, Format));
			}
		}

		private OResult<byte[]> ExtraMcCore(byte[] command, int format)
		{
			byte b = Convert.ToByte(Encoding.ASCII.GetString(command, 1, 2), 16);
			if (Station != b)
			{
				return new OResult<byte[]>($"Station Not Match, need: {Station}  but: {b}");
			}
			switch (format)
			{
			case 1:
				if (command[0] != 5)
				{
					return new OResult<byte[]>("First Byte Must Start with ENQ(0x05)");
				}
				if (SumCheck)
				{
					if (!SoftLRC.CalculateAccAndCheck(command, 1, 2))
					{
						return new OResult<byte[]>(2, "Sum Check Failed!");
					}
					return OResult.CreateSuccessResult(command.SelectMiddle(5, command.Length - 7));
				}
				return OResult.CreateSuccessResult(command.SelectMiddle(5, command.Length - 5));
			case 4:
				if (command[^1] == 10 && command[^2] == 13)
				{
					return ExtraMcCore(command.RemoveLast(2), 1);
				}
				return new OResult<byte[]>("In format 4 case, last two char must be CR(0x0d) and LF(0x0a)");
			default:
				return OResult.CreateSuccessResult(command);
			}
		}

		private int GetAddressOctOrTen(byte address)
		{
			if (address != 88 && address != 89)
			{
				return 10;
			}
			return 8;
		}

		private SoftBuffer GetAddressBuffer(byte address)
		{
			return address switch
			{
				88 => xBuffer, 
				89 => yBuffer, 
				77 => mBuffer, 
				83 => sBuffer, 
				68 => dBuffer, 
				82 => rBuffer, 
				_ => null, 
			};
		}

		private OResult<byte[]> ReadBoolByCommand(byte[] command)
		{
			if (command[3] == 68 || command[3] == 82)
			{
				return OResult.CreateSuccessResult(PackCommand(6, null, Format));
			}
			int destIndex = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 4), GetAddressOctOrTen(command[3]));
			int num = Convert.ToInt32(Encoding.ASCII.GetString(command, 8, 2), 16);
			if (num == 0)
			{
				num = 256;
			}
			SoftBuffer addressBuffer = GetAddressBuffer(command[3]);
			if (addressBuffer == null)
			{
				return OResult.CreateSuccessResult(PackCommand(6, null, Format));
			}
			return OResult.CreateSuccessResult(PackCommand(0, (from m in addressBuffer.GetBool(destIndex, num)
				select (byte)(m ? 49u : 48u)).ToArray(), Format));
		}

		private OResult<byte[]> WriteBoolByCommand(byte[] command)
		{
			if (command[3] == 68 || command[3] == 82)
			{
				return OResult.CreateSuccessResult(PackCommand(6, null, Format));
			}
			int destIndex = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 4), GetAddressOctOrTen(command[3]));
			int length = Convert.ToInt32(Encoding.ASCII.GetString(command, 8, 2), 16);
			bool[] value = (from m in command.SelectMiddle(10, length)
				select m == 49).ToArray();
			SoftBuffer addressBuffer = GetAddressBuffer(command[3]);
			if (addressBuffer == null)
			{
				return OResult.CreateSuccessResult(PackCommand(6, null, Format));
			}
			addressBuffer.SetBool(value, destIndex);
			return OResult.CreateSuccessResult(PackCommand(0, null, Format));
		}

		private OResult<byte[]> ReadWordByCommand(byte[] command)
		{
			if (command[3] == 88 || command[3] == 89 || command[3] == 77 || command[3] == 83)
			{
				int num = 0;
				int num2 = 0;
				if (command[0] == 81)
				{
					num = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 6), GetAddressOctOrTen(command[3]));
					num2 = Convert.ToInt32(Encoding.ASCII.GetString(command, 10, 2), 16);
				}
				else
				{
					num = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 4), GetAddressOctOrTen(command[3]));
					num2 = Convert.ToInt32(Encoding.ASCII.GetString(command, 8, 2), 16);
				}
				SoftBuffer addressBuffer = GetAddressBuffer(command[3]);
				return OResult.CreateSuccessResult(PackCommand(0, Encoding.ASCII.GetBytes(addressBuffer.GetBool(num, num2 * 16).ToByteArray().ToHexString()), Format));
			}
			if (command[3] == 68 || command[3] == 82)
			{
				int num3 = 0;
				int num4 = 0;
				if (command[0] == 81)
				{
					num3 = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 6));
					num4 = Convert.ToInt32(Encoding.ASCII.GetString(command, 10, 2), 16);
				}
				else
				{
					num3 = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 4));
					num4 = Convert.ToInt32(Encoding.ASCII.GetString(command, 8, 2), 16);
				}
				SoftBuffer addressBuffer2 = GetAddressBuffer(command[3]);
				return OResult.CreateSuccessResult(PackCommand(0, Encoding.ASCII.GetBytes(addressBuffer2.GetBytes(num3 * 2, num4 * 2).ToHexString()), Format));
			}
			return OResult.CreateSuccessResult(PackCommand(6, null, Format));
		}

		private OResult<byte[]> WriteWordByCommand(byte[] command)
		{
			if (command[3] == 88 || command[3] == 89 || command[3] == 77 || command[3] == 83)
			{
				int num = 0;
				int num2 = 0;
				bool[] value;
				if (command[0] == 81)
				{
					num = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 6), GetAddressOctOrTen(command[3]));
					num2 = Convert.ToInt32(Encoding.ASCII.GetString(command, 10, 2), 16);
					value = Encoding.ASCII.GetString(command, 12, num2 * 4).ToHexBytes().ToBoolArray();
				}
				else
				{
					num = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 4), GetAddressOctOrTen(command[3]));
					num2 = Convert.ToInt32(Encoding.ASCII.GetString(command, 8, 2), 16);
					value = Encoding.ASCII.GetString(command, 10, num2 * 4).ToHexBytes().ToBoolArray();
				}
				GetAddressBuffer(command[3]).SetBool(value, num);
				return OResult.CreateSuccessResult(PackCommand(0, null, Format));
			}
			if (command[3] == 68 || command[3] == 82)
			{
				int num3 = 0;
				int num4 = 0;
				byte[] data;
				if (command[0] == 81)
				{
					num3 = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 6));
					num4 = Convert.ToInt32(Encoding.ASCII.GetString(command, 10, 2), 16);
					data = Encoding.ASCII.GetString(command, 12, num4 * 4).ToHexBytes();
				}
				else
				{
					num3 = Convert.ToInt32(Encoding.ASCII.GetString(command, 4, 4));
					num4 = Convert.ToInt32(Encoding.ASCII.GetString(command, 8, 2), 16);
					data = Encoding.ASCII.GetString(command, 10, num4 * 4).ToHexBytes();
				}
				GetAddressBuffer(command[3]).SetBytes(data, num3 * 2);
				return OResult.CreateSuccessResult(PackCommand(0, null, Format));
			}
			return OResult.CreateSuccessResult(PackCommand(6, null, Format));
		}

		/// <inheritdoc />
		protected byte[] PackCommand(byte status, byte[] data, int format)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			if (data.Length == 0)
			{
				switch (format)
				{
				case 1:
				{
					if (status == 0)
					{
						byte[] bytes = Encoding.ASCII.GetBytes("\u0006F9FF");
						SoftBasic.BuildAsciiBytesFrom(Station).CopyTo(bytes, 1);
						return bytes;
					}
					byte[] bytes2 = Encoding.ASCII.GetBytes("\u001500FF00");
					SoftBasic.BuildAsciiBytesFrom(Station).CopyTo(bytes2, 1);
					SoftBasic.BuildAsciiBytesFrom(status).CopyTo(bytes2, 5);
					return bytes2;
				}
				case 4:
				{
					byte[] array = PackCommand(status, data, 1);
					return SoftBasic.SpliceArray<byte>(array, new byte[2] { 13, 10 });
				}
				default:
					return null;
				}
			}
			switch (format)
			{
			case 1:
			{
				if (status != 0)
				{
					byte[] bytes3 = Encoding.ASCII.GetBytes("\u001500FF00");
					SoftBasic.BuildAsciiBytesFrom(Station).CopyTo(bytes3, 1);
					SoftBasic.BuildAsciiBytesFrom(status).CopyTo(bytes3, 5);
					return bytes3;
				}
				byte[] array3 = new byte[(SumCheck ? 8 : 6) + data.Length];
				array3[0] = 2;
				SoftBasic.BuildAsciiBytesFrom(Station).CopyTo(array3, 1);
				Encoding.ASCII.GetBytes("FF").CopyTo(array3, 3);
				data.CopyTo(array3, 5);
				array3[^((!SumCheck) ? 1 : 3)] = 3;
				if (SumCheck)
				{
					SoftLRC.CalculateAccAndFill(array3, 1, 2);
				}
				return array3;
			}
			case 4:
			{
				byte[] array2 = PackCommand(status, data, 1);
				return SoftBasic.SpliceArray<byte>(array2, new byte[2] { 13, 10 });
			}
			default:
				return null;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecFxLinksServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 三菱的串口通信的对象，适用于读取FX系列的串口数据，支持的类型参考文档说明<br />
	/// Mitsubishi's serial communication object is suitable for reading serial data of the FX series. Refer to the documentation for the supported types.
	/// </summary>
	/// <remarks>
	/// 一般老旧的型号，例如FX2N之类的，需要将<see cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerial.IsNewVersion" />设置为<c>False</c>，如果是FX3U新的型号，则需要将<see cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerial.IsNewVersion" />设置为<c>True</c>
	/// </remarks>
	/// <example>
	/// <inheritdoc cref="T:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp" path="remarks" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecFxSerial.cs" region="Usage" title="简单的使用" />
	/// </example>
	public class MelsecFxSerial : DeviceSerialPort, IMelsecFxSerial, IReadWriteNet
	{
		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.IsNewVersion" />
		public bool IsNewVersion { get; set; }

		/// <summary>
		/// 获取或设置是否动态修改PLC的波特率，如果为 <c>True</c>，那么如果本对象设置了波特率 115200，就会自动修改PLC的波特率到 115200，因为三菱PLC再重启后都会使用默认的波特率9600 <br />
		/// Get or set whether to dynamically modify the baud rate of the PLC. If it is <c>True</c>, then if the baud rate of this object is set to 115200, 
		/// the baud rate of the PLC will be automatically modified to 115200, because the Mitsubishi PLC is not After restart, the default baud rate of 9600 will be used
		/// </summary>
		public bool AutoChangeBaudRate { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public MelsecFxSerial()
		{
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
			IsNewVersion = true;
			base.ByteTransform.IsStringReverseByteWord = true;
			LogMsgFormatBinary = false;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new MelsecFxSerialMessage();
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			int num = MelsecFxSerialHelper.FindSTXIndex(response);
			if (num > 0)
			{
				return OResult.CreateSuccessResult(response.RemoveBegin(num));
			}
			return OResult.CreateSuccessResult(response);
		}

		/// <inheritdoc />
		public override OResult Open()
		{
			if (!(CommunicationPipe is PipeSerialPort pipeSerialPort))
			{
				return new OResult("PipeSerialPort get failed");
			}
			int baudRate = pipeSerialPort.GetPipe().BaudRate;
			if (AutoChangeBaudRate && baudRate != 9600)
			{
				pipeSerialPort.GetPipe().BaudRate = 9600;
				OResult oResult = pipeSerialPort.OpenCommunication();
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				for (int i = 0; i < 3; i++)
				{
					OResult<byte[]> oResult2 = pipeSerialPort.ReadFromCoreServer(GetNewNetMessage(), new byte[1] { 5 }, hasResponseData: true);
					if (!oResult2.IsSuccess)
					{
						return oResult2;
					}
					if (oResult2.Content.Length >= 1 && oResult2.Content[0] == 6)
					{
						break;
					}
					if (i == 2)
					{
						return new OResult("check 0x06 back before send data failed!");
					}
				}
				byte[] sendValue = baudRate switch
				{
					115200 => new byte[6] { 2, 65, 53, 3, 55, 57 }, 
					57600 => new byte[6] { 2, 65, 51, 3, 55, 55 }, 
					38400 => new byte[6] { 2, 65, 50, 3, 55, 54 }, 
					19200 => new byte[6] { 2, 65, 49, 3, 55, 53 }, 
					_ => new byte[6] { 2, 65, 53, 3, 55, 57 }, 
				};
				OResult<byte[]> oResult3 = pipeSerialPort.ReadFromCoreServer(GetNewNetMessage(), sendValue, hasResponseData: true);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				if (oResult3.Content.Length < 1 || oResult3.Content[0] != 6)
				{
					return new OResult("check 0x06 back after send data failed!");
				}
				pipeSerialPort.CloseCommunication();
				pipeSerialPort.GetPipe().BaudRate = baudRate;
			}
			return base.Open();
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			if (AutoChangeBaudRate)
			{
				return CommunicationPipe.ReadFromCoreServer(GetNewNetMessage(), new byte[1] { 5 }, hasResponseData: true);
			}
			return base.InitializationOnConnect();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			return MelsecFxSerialHelper.Read(this, address, length, IsNewVersion);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			return MelsecFxSerialHelper.Write(this, address, value, IsNewVersion);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			return MelsecFxSerialHelper.ReadBool(this, address, length, IsNewVersion);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.Write(System.String,System.Boolean)" />
		public override OResult Write(string address, bool value)
		{
			return MelsecFxSerialHelper.Write(this, address, value);
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] value)
		{
			return MelsecFxSerialHelper.Write(this, address, value, IsNewVersion);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.MelsecFxSerialHelper.ActivePlc(Snet.Driver.Core.IReadWriteDevice)" />
		public OResult ActivePlc()
		{
			return MelsecFxSerialHelper.ActivePlc(this);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.MelsecFxSerialHelper.ActivePlc(Snet.Driver.Core.IReadWriteDevice)" />
		public async Task<OResult> ActivePlcAsync()
		{
			return await MelsecFxSerialHelper.ActivePlcAsync(this);
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, bool value)
		{
			return await Task.Run(() => Write(address, value));
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecFxSerial[{CommunicationPipe}]";
		}
	}
	/// <summary>
	/// 三菱串口协议的网络版，如果使用的是 FX3U编程口(fx2n) -&gt; GOT1000(RS232)(或是GOT2000)  -&gt; 上位机(以太网) 的方式，那么就需要把<see cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.UseGOT" />设置为 <c>True</c><br />
	/// The network version of the Mitsubishi serial port protocol, if you use the FX3U programming port (fx2n) -&gt; GOT1000 (RS232) (or GOT2000) -&gt; host computer (Ethernet) method, 
	/// then you need to put <see cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.UseGOT" /> is set to <c>True</c>
	/// </summary>
	/// <remarks>
	/// 一般老旧的型号，例如FX2N之类的，需要将<see cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.IsNewVersion" />设置为<c>False</c>，如果是FX3U新的型号，则需要将<see cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.IsNewVersion" />设置为<c>True</c>
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecFxSerial.cs" region="Usage" title="简单的使用" />
	/// </example>
	public class MelsecFxSerialOverTcp : DeviceTcpNet, IMelsecFxSerial, IReadWriteNet
	{
		private List<string> inis = new List<string>
		{
			"00 10 02 FF FF FC 01 10 03", "10025E000000FC00000000001212000000FFFF030000FF0300002D001C091A18000000000000000000FC000012120414000113960AC4E5D7010201000000023030453032303203364310033543", "10025E000000FC00000000001212000000FFFF030000FF0300002D001C091A18000000000000000000FC000012120414000113960AC4E5D7010202000000023030454341303203384510033833", "10025E000000FC00000000001212000000FFFF030000FF0300002D001C091A18000000000000000000FC000012120414000113960AC4E5D7010203000000023030453032303203364310033545", "10025E000000FC00000000001212000000FFFF030000FF0300002D001C091A18000000000000000000FC000012120414000113960AC4E5D7010204000000023030454341303203384510033835", "10025E000000FC00000000001212000000FFFF030000FF0300002F001C091A18000000000000000000FC000012120414000113960AC4E5D70102050000000245303138303030343003443510034342", "10025E000000FC00000000001212000000FFFF030000FF0300002F001C091A18000000000000000000FC000012120414000113960AC4E5D70102060000000245303138303430314303453910034535", "10025E000000FC00000000001212000000FFFF030000FF0300002F001C091A18000000000000000000FC000012120414000113960AC4E5D70102070000000245303030453030343003453110034436", "10025E000000FC00000000001212000000FFFF030000FF0300002F001C091A18000000000000000000FC000012120414000113960AC4E5D70102080000000245303030453430343003453510034446", "10025E000000FC00000000001212000000FFFF030000FF0300002F001C091A18000000000000000000FC000012120414000113960AC4E5D70102090000000245303030453830343003453910034538",
			"10025E000000FC00000000001212000000FFFF030000FF0300002F001C091A18000000000000000000FC000012120414000113960AC4E5D701020A0000000245303030454330343003463410034630"
		};

		private bool useGot;

		private SoftIncrementCount incrementCount;

		/// <summary>
		/// 获取或设置是否使用GOT连接三菱的PLC，当使用了GOT连接到
		/// </summary>
		public bool UseGOT
		{
			get
			{
				return useGot;
			}
			set
			{
				useGot = value;
			}
		}

		/// <summary>
		/// 当前的编程口协议是否为新版，默认为新版，如果无法读取，切换旧版再次尝试<br />
		/// Whether the current programming port protocol is the new version, the default is the new version, 
		/// if it cannot be read, switch to the old version and try again
		/// </summary>
		public bool IsNewVersion { get; set; }

		/// <summary>
		/// 实例化网络版的三菱的串口协议的通讯对象<br />
		/// Instantiate the communication object of Mitsubishi's serial protocol on the network
		/// </summary>
		public MelsecFxSerialOverTcp()
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform();
			IsNewVersion = true;
			base.ByteTransform.IsStringReverseByteWord = true;
			base.SleepTime = 20;
			incrementCount = new SoftIncrementCount(2147483647L, 1L);
			LogMsgFormatBinary = false;
		}

		/// <summary>
		/// 指定ip地址及端口号来实例化三菱的串口协议的通讯对象<br />
		/// Specify the IP address and port number to instantiate the communication object of Mitsubishi's serial protocol
		/// </summary>
		/// <param name="ipAddress">Ip地址</param>
		/// <param name="port">端口号</param>
		public MelsecFxSerialOverTcp(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		private byte[] GetBytesSend(byte[] command)
		{
			List<byte> list = new List<byte>();
			for (int i = 0; i < command.Length; i++)
			{
				if (i < 2)
				{
					list.Add(command[i]);
				}
				else if (i < command.Length - 4)
				{
					if (command[i] == 16)
					{
						list.Add(command[i]);
					}
					list.Add(command[i]);
				}
				else
				{
					list.Add(command[i]);
				}
			}
			return list.ToArray();
		}

		private byte[] GetBytesReceive(byte[] response)
		{
			List<byte> list = new List<byte>();
			for (int i = 0; i < response.Length; i++)
			{
				if (i < 2)
				{
					list.Add(response[i]);
				}
				else if (i < response.Length - 4)
				{
					if (response[i] == 16 && response[i + 1] == 16)
					{
						list.Add(response[i]);
						i++;
					}
					else
					{
						list.Add(response[i]);
					}
				}
				else
				{
					list.Add(response[i]);
				}
			}
			return list.ToArray();
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			if (useGot)
			{
				byte[] array = new byte[66 + command.Length];
				array[0] = 16;
				array[1] = 2;
				array[2] = 94;
				array[6] = 252;
				array[12] = 18;
				array[13] = 18;
				array[17] = byte.MaxValue;
				array[18] = byte.MaxValue;
				array[19] = 3;
				array[22] = byte.MaxValue;
				array[23] = 3;
				array[26] = BitConverter.GetBytes(34 + command.Length)[0];
				array[27] = BitConverter.GetBytes(34 + command.Length)[1];
				array[28] = 28;
				array[29] = 9;
				array[30] = 26;
				array[31] = 24;
				array[41] = 252;
				array[44] = 18;
				array[45] = 18;
				array[46] = 4;
				array[47] = 20;
				array[49] = 1;
				array[50] = BitConverter.GetBytes(Port)[1];
				array[51] = BitConverter.GetBytes(Port)[0];
				array[52] = IPAddress.Parse(IpAddress).GetAddressBytes()[0];
				array[53] = IPAddress.Parse(IpAddress).GetAddressBytes()[1];
				array[54] = IPAddress.Parse(IpAddress).GetAddressBytes()[2];
				array[55] = IPAddress.Parse(IpAddress).GetAddressBytes()[3];
				array[56] = 1;
				array[57] = 2;
				BitConverter.GetBytes((int)incrementCount.GetCurrentValue()).CopyTo(array, 58);
				command.CopyTo(array, 62);
				array[^4] = 16;
				array[^3] = 3;
				MelsecHelper.FxCalculateCRC(array, 2, 4).CopyTo(array, array.Length - 2);
				return GetBytesSend(array);
			}
			return base.PackCommandWithHeader(command);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			if (useGot)
			{
				if (response.Length > 68)
				{
					response = GetBytesReceive(response);
					int num = -1;
					for (int i = 0; i < response.Length - 4; i++)
					{
						if (response[i] == 16 && response[i + 1] == 2)
						{
							num = i;
							break;
						}
					}
					if (num >= 0)
					{
						return OResult.CreateSuccessResult(response.RemoveDouble(64 + num, 4));
					}
				}
				return new OResult<byte[]>("Got failed: " + response.ToHexString(' ', 16));
			}
			return base.UnpackResponseContent(send, response);
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			if (useGot)
			{
				for (int i = 0; i < inis.Count; i++)
				{
					OResult oResult = ReadFromCoreServer(CommunicationPipe, inis[i].ToHexBytes(), hasResponseData: true, usePackAndUnpack: false);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
			}
			return base.InitializationOnConnect();
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReadFromCoreServer(CommunicationPipe pipe, byte[] send, bool hasResponseData = true, bool usePackAndUnpack = true)
		{
			OResult<byte[]> oResult = base.ReadFromCoreServer(pipe, send, hasResponseData, usePackAndUnpack);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content == null)
			{
				return oResult;
			}
			if (oResult.Content.Length > 2)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = base.ReadFromCoreServer(pipe, send, hasResponseData, usePackAndUnpack);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(oResult.Content, oResult2.Content));
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadFromCoreServerAsync(CommunicationPipe pipe, byte[] send, bool hasResponseData = true, bool usePackAndUnpack = true)
		{
			OResult<byte[]> read = await base.ReadFromCoreServerAsync(pipe, send, hasResponseData, usePackAndUnpack).ConfigureAwait(continueOnCapturedContext: false);
			if (!read.IsSuccess)
			{
				return read;
			}
			if (read.Content == null)
			{
				return read;
			}
			if (read.Content.Length > 2)
			{
				return read;
			}
			OResult<byte[]> oResult = await base.ReadFromCoreServerAsync(pipe, send, hasResponseData, usePackAndUnpack).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(read.Content, oResult.Content));
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			if (useGot)
			{
				for (int i = 0; i < inis.Count; i++)
				{
					OResult oResult = await ReadFromCoreServerAsync(CommunicationPipe, inis[i].ToHexBytes(), hasResponseData: true, usePackAndUnpack: false).ConfigureAwait(continueOnCapturedContext: false);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
				}
			}
			return await base.InitializationOnConnectAsync();
		}

