	/// <summary>
	/// 三菱编程口协议的虚拟服务器，属性<see cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerialServer.IsNewVersion" />的配置和客户端保持一致才能数据一致<br />
	/// Mitsubishi Programming interface protocol virtual server, attribute <see cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerialServer.IsNewVersion" /> and the client configuration must be consistent data consistency
	/// </summary>
	public class MelsecFxSerialServer : DeviceServer
	{
		private SoftBuffer softBuffer;

		private const int DataPoolLength = 65536;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.MelsecFxSerialOverTcp.IsNewVersion" />
		public bool IsNewVersion { get; set; }

		/// <summary>
		/// 实例化一个虚拟的FxLinks服务器<br />
		/// Instantiate a virtual FxLinks server
		/// </summary>
		public MelsecFxSerialServer()
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform();
			LogMsgFormatBinary = false;
			softBuffer = new SoftBuffer(131072);
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<ushort> oResult = MelsecFxSerialHelper.FxCalculateWordStartAddress(address, IsNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(softBuffer.GetBytes(oResult.Content, length * 2));
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<ushort> oResult = MelsecFxSerialHelper.FxCalculateWordStartAddress(address, IsNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			softBuffer.SetBytes(value, oResult.Content);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<ushort, ushort, ushort> oResult = MelsecFxSerialHelper.FxCalculateBoolStartAddress(address, IsNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			return OResult.CreateSuccessResult(softBuffer.GetBool(oResult.Content1 * 8 + oResult.Content3, length));
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] value)
		{
			OResult<ushort, ushort, ushort> oResult = MelsecFxSerialHelper.FxCalculateBoolStartAddress(address, IsNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			softBuffer.SetBool(value, oResult.Content1 * 8 + oResult.Content3);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return null;
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive.Length == 1 && receive[0] == 5)
			{
				return OResult.CreateSuccessResult(new byte[1] { 6 });
			}
			if (receive[1] == 48)
			{
				return ReadByCommand(receive, 2);
			}
			if (receive[1] == 49)
			{
				return WriteByCommand(receive, 2);
			}
			if (receive[1] == 55)
			{
				return WriteBitByCommand(receive, 2, value: true);
			}
			if (receive[1] == 56)
			{
				return WriteBitByCommand(receive, 2, value: false);
			}
			if (receive[1] == 69)
			{
				if (receive[2] == 48)
				{
					return ReadByCommand(receive, 4);
				}
				if (receive[2] == 49)
				{
					return WriteByCommand(receive, 4);
				}
			}
			else if (receive[1] == 65)
			{
				session.Communication.Send(new byte[1] { 6 });
				if (session.Communication is PipeSerialPort pipeSerialPort)
				{
					Thread.Sleep(20);
					if (receive[2] == 49)
					{
						pipeSerialPort.GetPipe().BaudRate = 19200;
					}
					else if (receive[2] == 50)
					{
						pipeSerialPort.GetPipe().BaudRate = 38400;
					}
					else if (receive[2] == 51)
					{
						pipeSerialPort.GetPipe().BaudRate = 57600;
					}
					else if (receive[2] == 52)
					{
						pipeSerialPort.GetPipe().BaudRate = 115200;
					}
				}
			}
			return OResult.CreateSuccessResult(new byte[0]);
		}

		private OResult<byte[]> ReadByCommand(byte[] cmd, int offset)
		{
			int index = Convert.ToInt32(Encoding.ASCII.GetString(cmd, offset, 4), 16);
			int length = Convert.ToInt32(Encoding.ASCII.GetString(cmd, offset + 4, 2), 16);
			return OResult.CreateSuccessResult(BuildReadResponse(softBuffer.GetBytes(index, length)));
		}

		private OResult<byte[]> WriteByCommand(byte[] cmd, int offset)
		{
			int destIndex = Convert.ToInt32(Encoding.ASCII.GetString(cmd, offset, 4), 16);
			int num = Convert.ToInt32(Encoding.ASCII.GetString(cmd, offset + 4, 2), 16);
			if (num * 2 == cmd.Length - offset - 9)
			{
				byte[] array = new byte[num];
				for (int i = 0; i < array.Length; i++)
				{
					int num2 = Convert.ToInt32(Encoding.ASCII.GetString(cmd, 6 + offset + i * 2, 2), 16);
					array[i] = (byte)num2;
				}
				softBuffer.SetBytes(array, destIndex);
				return OResult.CreateSuccessResult(new byte[2] { 6, 3 });
			}
			return OResult.CreateSuccessResult(new byte[0]);
		}

		private OResult<byte[]> WriteBitByCommand(byte[] cmd, int offset, bool value)
		{
			byte[] bytes = new byte[4]
			{
				cmd[offset + 2],
				cmd[offset + 3],
				cmd[offset],
				cmd[offset + 1]
			};
			int num = Convert.ToInt32(Encoding.ASCII.GetString(bytes), 16);
			if (IsNewVersion)
			{
				if (num >= 2048 && num < 10048)
				{
					num = 278528 + (num - 2048);
				}
				else if (num >= 1024 && num < 1280)
				{
					num = 288000 + (num - 1024);
				}
				else if (num >= 1280 && num < 1536)
				{
					num = 286208 + (num - 1280);
				}
				else if (num >= 0 && num < 1024)
				{
					num = 288512 + num;
				}
			}
			softBuffer.SetBool(value, num);
			return OResult.CreateSuccessResult(new byte[2] { 6, 3 });
		}

		private byte[] BuildReadResponse(byte[] data)
		{
			byte[] array = new byte[4 + data.Length * 2];
			array[0] = 2;
			for (int i = 0; i < data.Length; i++)
			{
				array[1 + 2 * i] = SoftBasic.BuildAsciiBytesFrom(data[i])[0];
				array[2 + 2 * i] = SoftBasic.BuildAsciiBytesFrom(data[i])[1];
			}
			array[^3] = 3;
			MelsecHelper.FxCalculateCRC(array).CopyTo(array, array.Length - 2);
			return array;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecFxSerialServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 所有三菱通讯类的通用辅助工具类，包含了一些通用的静态方法，可以使用本类来获取一些原始的报文信息。详细的操作参见例子<br />
	/// All general auxiliary tool classes of Mitsubishi communication class include some general static methods. 
	/// You can use this class to get some primitive message information. See the example for detailed operation
	/// </summary>
	public class MelsecHelper
	{
		/// <summary>
		/// 解析A1E协议数据地址<br />
		/// Parse A1E protocol data address
		/// </summary>
		/// <param name="address">数据地址</param>
		/// <returns>结果对象</returns>
		public static OResult<MelsecA1EDataType, int> McA1EAnalysisAddress(string address)
		{
			OResult<MelsecA1EDataType, int> oResult = new OResult<MelsecA1EDataType, int>();
			try
			{
				switch (address[0])
				{
				case 'T':
				case 't':
					if (address[1] == 'S' || address[1] == 's')
					{
						oResult.Content1 = MelsecA1EDataType.TS;
						oResult.Content2 = Convert.ToInt32(address.Substring(2), MelsecA1EDataType.TS.FromBase);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						oResult.Content1 = MelsecA1EDataType.TC;
						oResult.Content2 = Convert.ToInt32(address.Substring(2), MelsecA1EDataType.TC.FromBase);
						break;
					}
					if (address[1] == 'N' || address[1] == 'n')
					{
						oResult.Content1 = MelsecA1EDataType.TN;
						oResult.Content2 = Convert.ToInt32(address.Substring(2), MelsecA1EDataType.TN.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'C':
				case 'c':
					if (address[1] == 'S' || address[1] == 's')
					{
						oResult.Content1 = MelsecA1EDataType.CS;
						oResult.Content2 = Convert.ToInt32(address.Substring(2), MelsecA1EDataType.CS.FromBase);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						oResult.Content1 = MelsecA1EDataType.CC;
						oResult.Content2 = Convert.ToInt32(address.Substring(2), MelsecA1EDataType.CC.FromBase);
						break;
					}
					if (address[1] == 'N' || address[1] == 'n')
					{
						oResult.Content1 = MelsecA1EDataType.CN;
						oResult.Content2 = Convert.ToInt32(address.Substring(2), MelsecA1EDataType.CN.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'X':
				case 'x':
					oResult.Content1 = MelsecA1EDataType.X;
					address = address.Substring(1);
					if (address.StartsWith("0"))
					{
						oResult.Content2 = Convert.ToInt32(address, 8);
					}
					else
					{
						oResult.Content2 = Convert.ToInt32(address, MelsecA1EDataType.X.FromBase);
					}
					break;
				case 'Y':
				case 'y':
					oResult.Content1 = MelsecA1EDataType.Y;
					address = address.Substring(1);
					if (address.StartsWith("0"))
					{
						oResult.Content2 = Convert.ToInt32(address, 8);
					}
					else
					{
						oResult.Content2 = Convert.ToInt32(address, MelsecA1EDataType.Y.FromBase);
					}
					break;
				case 'M':
				case 'm':
					oResult.Content1 = MelsecA1EDataType.M;
					oResult.Content2 = Convert.ToInt32(address.Substring(1), MelsecA1EDataType.M.FromBase);
					break;
				case 'S':
				case 's':
					oResult.Content1 = MelsecA1EDataType.S;
					oResult.Content2 = Convert.ToInt32(address.Substring(1), MelsecA1EDataType.S.FromBase);
					break;
				case 'F':
				case 'f':
					oResult.Content1 = MelsecA1EDataType.F;
					oResult.Content2 = Convert.ToInt32(address.Substring(1), MelsecA1EDataType.F.FromBase);
					break;
				case 'B':
				case 'b':
					oResult.Content1 = MelsecA1EDataType.B;
					oResult.Content2 = Convert.ToInt32(address.Substring(1), MelsecA1EDataType.B.FromBase);
					break;
				case 'D':
				case 'd':
					oResult.Content1 = MelsecA1EDataType.D;
					oResult.Content2 = Convert.ToInt32(address.Substring(1), MelsecA1EDataType.D.FromBase);
					break;
				case 'R':
				case 'r':
					oResult.Content1 = MelsecA1EDataType.R;
					oResult.Content2 = Convert.ToInt32(address.Substring(1), MelsecA1EDataType.R.FromBase);
					break;
				case 'W':
				case 'w':
					oResult.Content1 = MelsecA1EDataType.W;
					oResult.Content2 = Convert.ToInt32(address.Substring(1), MelsecA1EDataType.W.FromBase);
					break;
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
			oResult.IsSuccess = true;
			return oResult;
		}

		/// <summary>
		/// 根据三菱的错误码去查找对象描述信息
		/// </summary>
