		/// <summary>
		/// 从三菱的地址中构建MC协议的6字节的ASCII格式的地址
		/// </summary>
		/// <param name="address">三菱地址</param>
		/// <param name="type">三菱的数据类型</param>
		/// <returns>6字节的ASCII格式的地址</returns>
		internal static byte[] BuildBytesFromAddress(int address, MelsecMcDataType type)
		{
			if (type.AsciiCode == "ZR")
			{
				return Encoding.ASCII.GetBytes(address.ToString("X6"));
			}
			return Encoding.ASCII.GetBytes(address.ToString((type.FromBase == 10) ? "D6" : "X6"));
		}

		/// <summary>
		/// 将0，1，0，1的字节数组压缩成三菱格式的字节数组来表示开关量的
		/// </summary>
		/// <param name="value">原始的数据字节</param>
		/// <returns>压缩过后的数据字节</returns>
		internal static byte[] TransBoolArrayToByteData(byte[] value)
		{
			return TransBoolArrayToByteData(value.Select((byte m) => m != 0).ToArray());
		}

		internal static bool[] TransByteArrayToBoolData(byte[] value, int offset, int length)
		{
			bool[] array = new bool[(length > (value.Length - offset) * 2) ? ((value.Length - offset) * 2) : length];
			for (int i = 0; i < array.Length; i++)
			{
				if (i % 2 == 0)
				{
					array[i] = (value[offset + i / 2] & 0x10) == 16;
				}
				else
				{
					array[i] = (value[offset + i / 2] & 1) == 1;
				}
			}
			return array;
		}

		/// <summary>
		/// 将bool的组压缩成三菱格式的字节数组来表示开关量的
		/// </summary>
		/// <param name="value">原始的数据字节</param>
		/// <returns>压缩过后的数据字节</returns>
		internal static byte[] TransBoolArrayToByteData(bool[] value)
		{
			int num = (value.Length + 1) / 2;
			byte[] array = new byte[num];
			for (int i = 0; i < num; i++)
			{
				if (value[i * 2])
				{
					array[i] += 16;
				}
				if (i * 2 + 1 < value.Length && value[i * 2 + 1])
				{
					array[i]++;
				}
			}
			return array;
		}

		internal static byte[] TransByteArrayToAsciiByteArray(byte[] value)
		{
			if (value == null)
			{
				return new byte[0];
			}
			byte[] array = new byte[value.Length * 2];
			for (int i = 0; i < value.Length / 2; i++)
			{
				SoftBasic.BuildAsciiBytesFrom(BitConverter.ToUInt16(value, i * 2)).CopyTo(array, 4 * i);
			}
			return array;
		}

		internal static byte[] TransAsciiByteArrayToByteArray(byte[] value)
		{
			byte[] array = new byte[value.Length / 2];
			for (int i = 0; i < array.Length / 2; i++)
			{
				BitConverter.GetBytes(Convert.ToUInt16(Encoding.ASCII.GetString(value, i * 4, 4), 16)).CopyTo(array, i * 2);
			}
			return array;
		}

		/// <summary>
		/// 计算Fx协议指令的和校验信息
		/// </summary>
		/// <param name="data">字节数据</param>
		/// <param name="start">起始的索引信息</param>
		/// <param name="tail">结束的长度信息</param>
		/// <returns>校验之后的数据</returns>
		internal static byte[] FxCalculateCRC(byte[] data, int start = 1, int tail = 2)
		{
			int num = 0;
			for (int i = start; i < data.Length - tail; i++)
			{
				num += data[i];
			}
			return SoftBasic.BuildAsciiBytesFrom((byte)num);
		}

		/// <summary>
		/// 检查指定的和校验是否是正确的
		/// </summary>
		/// <param name="data">字节数据</param>
		/// <returns>是否成功</returns>
		internal static bool CheckCRC(byte[] data)
		{
			byte[] array = FxCalculateCRC(data);
			if (array[0] != data[^2])
			{
				return false;
			}
			if (array[1] != data[^1])
			{
				return false;
			}
			return true;
		}
	}
	/// <summary>
	/// 三菱PLC通讯类，采用Qna兼容3E帧协议实现，需要在PLC侧先的以太网模块先进行配置，必须为ASCII通讯格式<br />
	/// Mitsubishi PLC communication class is implemented using Qna compatible 3E frame protocol. 
	/// The Ethernet module on the PLC side needs to be configured first. It must be ascii communication.
	/// </summary>
	/// <remarks>
	/// <inheritdoc cref="T:Snet.Driver.Profinet.Melsec.MelsecMcNet" path="remarks" />
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecAscii.cs" region="Usage" title="简单的短连接使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecAscii.cs" region="Usage2" title="简单的长连接使用" />
	/// </example>
	public class MelsecMcAsciiNet : MelsecMcNet
	{
		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.McType" />
		public override McType McType => McType.MCAscii;

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecMcNet.#ctor" />
		public MelsecMcAsciiNet()
		{
			base.WordLength = 1;
			LogMsgFormatBinary = false;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecMcNet.#ctor(System.String,System.Int32)" />
		public MelsecMcAsciiNet(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new MelsecQnA3EAsciiMessage();
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			return McAsciiHelper.PackMcCommand(this, command);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			OResult oResult = McAsciiHelper.CheckResponseContent(response);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(response.RemoveBegin(22));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.ExtractActualData(System.Byte[],System.Boolean)" />
		public override byte[] ExtractActualData(byte[] response, bool isBit)
		{
			return McAsciiHelper.ExtractActualDataHelper(response, isBit);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecMcAsciiNet[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 三菱PLC通讯类，采用UDP的协议实现，采用Qna兼容3E帧协议实现，需要在PLC侧先的以太网模块先进行配置，必须为ascii通讯<br />
	/// Mitsubishi PLC communication class is implemented using UDP protocol and Qna compatible 3E frame protocol. 
	/// The Ethernet module needs to be configured first on the PLC side, and it must be ascii communication.
	/// </summary>
	/// <remarks>
	/// <inheritdoc cref="T:Snet.Driver.Profinet.Melsec.MelsecMcNet" path="remarks" />
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecAscii.cs" region="Usage" title="简单的短连接使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecAscii.cs" region="Usage2" title="简单的长连接使用" />
	/// </example>
	public class MelsecMcAsciiUdp : MelsecMcAsciiNet, IReadWriteMc, IReadWriteDevice, IReadWriteNet
	{
		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecMcNet.#ctor" />
		public MelsecMcAsciiUdp()
			: this("127.0.0.1", 6000)
		{
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecMcNet.#ctor(System.String,System.Int32)" />
		public MelsecMcAsciiUdp(string ipAddress, int port)
		{
			base.WordLength = 1;
			LogMsgFormatBinary = false;
			base.ByteTransform = new RegularByteTransform();
			CommunicationPipe = new PipeUdpNet();
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecMcAsciiUdp[{IpAddress}:{Port}]";
		}
	}
