		/// 数据的类型，0代表按字，1代表按位
		/// </summary>
		public byte DataType { get; private set; }

		/// <summary>
		/// 当以ASCII格式通讯时的类型描述
		/// </summary>
		public string AsciiCode { get; private set; }

		/// <summary>
		/// 指示地址是10进制，还是16进制的
		/// </summary>
		public int FromBase { get; private set; }

		/// <summary>
		/// 实例化一个三菱数据类型对象，如果您清楚类型代号，可以根据值进行扩展<br />
		/// Instantiate a Mitsubishi data type object, if you know the type code, you can expand according to the value
		/// </summary>
		/// <param name="code">数据类型的代号</param>
		/// <param name="type">0或1，默认为0，0代表按字，1代表按位</param>
		/// <param name="asciiCode">ASCII格式的类型信息</param>
		/// <param name="fromBase">指示地址的多少进制的，10或是16</param>
		public MelsecMcDataType(ushort code, byte type, string asciiCode, int fromBase)
		{
			DataCode = code;
			AsciiCode = asciiCode;
			FromBase = fromBase;
			if (type < 2)
			{
				DataType = type;
			}
		}

		/// <summary>
		/// 根据类型代码获取真实的地址对象
		/// </summary>
		/// <param name="code"></param>
		/// <returns></returns>
		public static MelsecMcDataType GetMelsecAddress(byte code)
		{
			if (code == X.DataCode)
			{
				return X;
			}
			if (code == Y.DataCode)
			{
				return Y;
			}
			if (code == M.DataCode)
			{
				return M;
			}
			if (code == SM.DataCode)
			{
				return SM;
			}
			if (code == S.DataCode)
			{
				return S;
			}
			if (code == L.DataCode)
			{
				return L;
			}
			if (code == F.DataCode)
			{
				return F;
			}
			if (code == V.DataCode)
			{
				return V;
			}
			if (code == B.DataCode)
			{
				return B;
			}
			if (code == SB.DataCode)
			{
				return SB;
			}
			if (code == DX.DataCode)
			{
				return DX;
			}
			if (code == DY.DataCode)
			{
				return DY;
			}
			if (code == D.DataCode)
			{
				return D;
			}
			if (code == SD.DataCode)
			{
				return SD;
			}
			if (code == W.DataCode)
			{
				return W;
			}
			if (code == SW.DataCode)
			{
				return SW;
			}
			if (code == R.DataCode)
			{
				return R;
			}
			if (code == Z.DataCode)
			{
				return Z;
			}
			if (code == ZR.DataCode)
			{
				return ZR;
			}
			if (code == TN.DataCode)
			{
				return TN;
			}
			if (code == TS.DataCode)
			{
				return TS;
			}
			if (code == TC.DataCode)
			{
				return TC;
			}
			if (code == SS.DataCode)
			{
				return SS;
			}
			if (code == SC.DataCode)
			{
				return SC;
			}
			if (code == SN.DataCode)
			{
				return SN;
			}
			if (code == CN.DataCode)
			{
				return CN;
			}
			return null;
		}
	}
	/// <summary>
	/// 三菱PLC通讯类，采用Qna兼容3E帧协议实现，需要在PLC侧先的以太网模块先进行配置，必须为二进制通讯<br />
	/// Mitsubishi PLC communication class is implemented using Qna compatible 3E frame protocol. 
	/// The Ethernet module on the PLC side needs to be configured first. It must be binary communication.
	/// </summary>
	/// <remarks>
	/// 支持读写的数据类型详细参考API文档，支持高级的数据读取，例如读取智能模块，缓冲存储器等等。如果使用的Fx5u的PLC，如果之前有写过用户认证，需要对设备信息全部初始化
	/// </remarks>
	/// <list type="number">
	/// 目前组件测试通过的PLC型号列表，有些来自于网友的测试
	/// <item>Q06UDV PLC  感谢hwdq0012</item>
	/// <item>fx5u PLC  感谢山楂</item>
	/// <item>Q02CPU PLC </item>
	/// <item>L02CPU PLC </item>
	/// </list>
	/// 地址的输入的格式支持多种复杂的地址表示方式：
	/// <list type="number">
	/// <item>[商业授权] 扩展的数据地址: 表示为 ext=1;W100  访问扩展区域为1的W100的地址信息</item>
	/// <item>[商业授权] 缓冲存储器地址: 表示为 mem=32  访问地址为32的本站缓冲存储器地址</item>
	/// <item>[商业授权] 智能模块地址：表示为 module=3;4106  访问模块号3，偏移地址是4106的数据，偏移地址需要根据模块的详细信息来确认。</item>
	/// <item>[商业授权] 基于标签的地址: 表示位 s=AAA  假如标签的名称为AAA，但是标签的读取是有条件的，详细参照<see cref="M:Snet.Driver.Profinet.Melsec.MelsecMcNet.ReadTags(System.String,System.UInt16)" /></item>
	/// <item>普通的数据地址，参照下面的信息</item>
	/// </list>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="Usage" title="简单的短连接使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="Usage2" title="简单的长连接使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample1" title="基本的读取示例" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample2" title="批量读取示例" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample3" title="随机字读取示例" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample4" title="随机批量字读取示例" />
	/// </example>
	public class MelsecMcNet : DeviceTcpNet, IReadWriteMc, IReadWriteDevice, IReadWriteNet
	{
		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.McType" />
		public virtual McType McType => McType.McBinary;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.NetworkNumber" />
		public byte NetworkNumber { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.PLCNumber" />
		public byte PLCNumber { get; set; } = byte.MaxValue;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.NetworkStationNumber" />
		public byte NetworkStationNumber { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.EnableWriteBitToWordRegister" />
		public bool EnableWriteBitToWordRegister { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.TargetIOStation" />
		public ushort TargetIOStation { get; set; } = 1023;

		/// <summary>
		/// 实例化三菱的Qna兼容3E帧协议的通讯对象<br />
		/// Instantiate the communication object of Mitsubishi's Qna compatible 3E frame protocol
		/// </summary>
		public MelsecMcNet()
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 指定ip地址和端口号来实例化一个默认的对象<br />
		/// Specify the IP address and port number to instantiate a default object
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
		/// <param name="port">PLC的端口</param>
		public MelsecMcNet(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new MelsecQnA3EBinaryMessage();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.McAnalysisAddress(System.String,System.UInt16,System.Boolean)" />
		public virtual OResult<McAddressData> McAnalysisAddress(string address, ushort length, bool isBit)
		{
			return McAddressData.ParseMelsecFrom(address, length, isBit);
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			return McBinaryHelper.PackMcCommand(this, command);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			OResult oResult = McBinaryHelper.CheckResponseContentHelper(response);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(response.RemoveBegin(11));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc.ExtractActualData(System.Byte[],System.Boolean)" />
		public virtual byte[] ExtractActualData(byte[] response, bool isBit)
