		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 458752)
			{
				throw new Exception("File is not correct");
			}
			mBuffer.SetBytes(content, 0, 0, 65536);
			xBuffer.SetBytes(content, 65536, 0, 65536);
			yBuffer.SetBytes(content, 131072, 0, 65536);
			dBuffer.SetBytes(content, 196608, 0, 131072);
			wBuffer.SetBytes(content, 327680, 0, 131072);
			if (content.Length >= 12)
			{
				bBuffer.SetBytes(content, 458752, 0, 65536);
				rBuffer.SetBytes(content, 524288, 0, 131072);
				zrBuffer.SetBytes(content, 655360, 0, 131072);
			}
			if (content.Length >= 15)
			{
				dBuffer.SetBytes(content, 786432, 131072, 131072);
				lBuffer.SetBytes(content, 917504, 0, 65536);
			}
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[983040];
			Array.Copy(mBuffer.GetBytes(), 0, array, 0, 65536);
			Array.Copy(xBuffer.GetBytes(), 0, array, 65536, 65536);
			Array.Copy(yBuffer.GetBytes(), 0, array, 131072, 65536);
			Array.Copy(dBuffer.GetBytes(), 0, array, 196608, 131072);
			Array.Copy(wBuffer.GetBytes(), 0, array, 327680, 131072);
			Array.Copy(bBuffer.GetBytes(), 0, array, 458752, 65536);
			Array.Copy(rBuffer.GetBytes(), 0, array, 524288, 131072);
			Array.Copy(zrBuffer.GetBytes(), 0, array, 655360, 131072);
			Array.Copy(dBuffer.GetBytes(), 131072, array, 786432, 131072);
			Array.Copy(lBuffer.GetBytes(), 0, array, 917504, 65536);
			return array;
		}

		/// <summary>
		/// 释放当前的对象
		/// </summary>
		/// <param name="disposing">是否托管对象</param>
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				xBuffer?.Dispose();
				yBuffer?.Dispose();
				mBuffer?.Dispose();
				dBuffer?.Dispose();
				wBuffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecMcServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 三菱PLC通讯类，采用UDP的协议实现，采用Qna兼容3E帧协议实现，需要在PLC侧先的以太网模块先进行配置，必须为二进制通讯<br />
	/// Mitsubishi PLC communication class is implemented using UDP protocol and Qna compatible 3E frame protocol. 
	/// The Ethernet module needs to be configured first on the PLC side, and it must be binary communication.
	/// </summary>
	/// <remarks>
	/// <inheritdoc cref="T:Snet.Driver.Profinet.Melsec.MelsecMcNet" path="remarks" />
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="Usage" title="简单的短连接使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="Usage2" title="简单的长连接使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample1" title="基本的读取示例" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample2" title="批量读取示例" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample3" title="随机字读取示例" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample4" title="随机批量字读取示例" />
	/// </example>
	public class MelsecMcUdp : MelsecMcNet, IReadWriteMc, IReadWriteDevice, IReadWriteNet
	{
		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecMcNet.#ctor" />
		public MelsecMcUdp()
			: this("127.0.0.1", 6000)
		{
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.MelsecMcNet.#ctor(System.String,System.Int32)" />
		public MelsecMcUdp(string ipAddress, int port)
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform();
			CommunicationPipe = new PipeUdpNet();
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"MelsecMcUdp[{IpAddress}:{Port}]";
		}
	}
