		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.McBinaryHelper.ReadTags(Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc,System.String[],System.UInt16[])" />
		public static OResult<bool[]> ReadBoolTag(IReadWriteMc mc, string tag, ushort length)
		{
			byte[] send = BuildReadTag(new string[1] { tag }, new ushort[1] { length }, isBit: true);
			OResult<byte[]> oResult = mc.ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = ExtraTagData(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectBegin(length));
		}

