	/// <summary>
	/// MC协议的辅助类对象，提供了MC协议的读写操作的基本支持
	/// </summary>
	public class McHelper
	{
		/// <summary>
		/// 返回按照字单位读取的最低的长度信息
		/// </summary>
		/// <param name="type">MC协议的类型</param>
		/// <returns>长度信息</returns>
		public static int GetReadWordLength(McType type)
		{
			if (type == McType.McBinary || type == McType.McRBinary)
			{
				return 950;
			}
			return 460;
		}

		/// <summary>
		/// 返回按照位单位读取的最低的长度信息
		/// </summary>
		/// <param name="type">MC协议的类型</param>
		/// <returns>长度信息</returns>
		public static int GetReadBoolLength(McType type)
		{
			if (type == McType.McBinary || type == McType.McRBinary)
			{
				return 7168;
			}
			return 3584;
		}

		internal static string AnalysisAddressLogMessage(PipeSession pipeSession, IByteTransform byteTransform, byte[] content)
		{
			if (content[0] == 80 && content.Length >= 21)
			{
				StringBuilder stringBuilder = new StringBuilder();
				if (content[11] == 1 && content[12] == 4)
				{
					if (content[13] == 0)
					{
						stringBuilder.Append(" --- Read(\"");
					}
					else
					{
						stringBuilder.Append(" --- ReadBool(\"");
					}
				}
				else
				{
					if (content[11] != 1 || content[12] != 20)
					{
						return string.Empty;
					}
					stringBuilder.Append(" --- Write(\"");
				}
				int num = content[15] + content[16] * 256 + content[17] * 256 * 256;
				MelsecMcDataType melsecAddress = MelsecMcDataType.GetMelsecAddress(content[18]);
				if (melsecAddress != null)
				{
					stringBuilder.Append(melsecAddress.AsciiCode.Trim('*'));
					stringBuilder.Append(Convert.ToString(num, melsecAddress.FromBase).ToUpper());
				}
				stringBuilder.Append("\", ");
				int num2 = BitConverter.ToUInt16(content, 19);
				if (content[12] == 4)
				{
					stringBuilder.Append(num2);
				}
				else if (content[13] == 0)
				{
					if (num2 == 1 && content.Length >= 23)
					{
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder3 = stringBuilder2;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(0, 1, stringBuilder2);
						handler.AppendFormatted(BitConverter.ToUInt16(content, 21));
						stringBuilder3.Append(ref handler);
					}
					else
					{
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder4 = stringBuilder2;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(10, 1, stringBuilder2);
						handler.AppendLiteral("new byte[");
						handler.AppendFormatted(num2 * 2);
						handler.AppendLiteral("]");
						stringBuilder4.Append(ref handler);
					}
				}
				else if (num2 == 1 && content.Length >= 22)
				{
					stringBuilder.Append((content[21] == 0) ? "false" : "true");
				}
				else
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder5 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(10, 1, stringBuilder2);
					handler.AppendLiteral("new bool[");
					handler.AppendFormatted(num2);
					handler.AppendLiteral("]");
					stringBuilder5.Append(ref handler);
				}
				stringBuilder.Append(")");
				return stringBuilder.ToString();
			}
			return string.Empty;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Read(System.String,System.UInt16)" />
		/// <remarks>
		/// 初步支持普通的数据地址之外，还额外支持高级的地址写法，以下是示例（适用于MC协议为二进制和ASCII格式）：<br />
		/// [商业授权] 扩展的数据地址: 表示为 ext=1;W100  访问扩展区域为1的W100的地址信息<br />
		/// [商业授权] 缓冲存储器地址: 表示为 mem=32  访问地址为32的本站缓冲存储器地址<br />
		/// [商业授权] 智能模块地址：表示为 module=3;4106  访问模块号3，偏移地址是4106的数据，偏移地址需要根据模块的详细信息来确认。<br />
		/// [商业授权] 基于标签的地址: 表示位 s=AAA  假如标签的名称为AAA，但是标签的读取是有条件的，详细参照<see cref="M:Snet.Driver.Profinet.Melsec.Helper.McBinaryHelper.ReadTags(Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc,System.String[],System.UInt16[])" /><br />
		/// </remarks>
		public static OResult<byte[]> Read(IReadWriteMc mc, string address, ushort length)
		{
			if (address.StartsWith("s=") || address.StartsWith("S="))
			{
				if (mc.McType == McType.McBinary)
				{
					return McBinaryHelper.ReadTags(mc, new string[1] { address.Substring(2) }, new ushort[1] { length });
				}
				if (mc.McType == McType.MCAscii)
				{
					return McAsciiHelper.ReadTags(mc, new string[1] { address.Substring(2) }, new ushort[1] { length });
				}
				return new OResult<byte[]>(StringResources.Language.NotSupportedFunction);
			}
			if ((mc.McType == McType.McBinary || mc.McType == McType.MCAscii) && Regex.IsMatch(address, "ext=[0-9]+;", RegexOptions.IgnoreCase))
			{
				string value = Regex.Match(address, "ext=[0-9]+;").Value;
				ushort extend = ushort.Parse(Regex.Match(value, "[0-9]+").Value);
				return ReadExtend(mc, extend, address.Substring(value.Length), length);
			}
			if ((mc.McType == McType.McBinary || mc.McType == McType.MCAscii) && Regex.IsMatch(address, "mem=", RegexOptions.IgnoreCase))
			{
				return ReadMemory(mc, address.Substring(4), length);
			}
			if ((mc.McType == McType.McBinary || mc.McType == McType.MCAscii) && Regex.IsMatch(address, "module=[0-9]+;", RegexOptions.IgnoreCase))
			{
				string value2 = Regex.Match(address, "module=[0-9]+;").Value;
				ushort module = ushort.Parse(Regex.Match(value2, "[0-9]+").Value);
				return ReadSmartModule(mc, module, address.Substring(value2.Length), (ushort)(length * 2));
			}
			OResult<McAddressData> oResult = mc.McAnalysisAddress(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			ushort num = 0;
			while (num < length)
			{
				ushort num2 = (ushort)Math.Min(length - num, GetReadWordLength(mc.McType));
				oResult.Content.Length = num2;
				byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildReadMcCoreCommand(oResult.Content, isBit: false) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiReadMcCoreCommand(oResult.Content, isBit: false) : ((mc.McType == McType.McRBinary) ? MelsecMcRNet.BuildReadMcCoreCommand(oResult.Content, isBit: false) : null)));
				OResult<byte[]> oResult2 = mc.ReadFromCoreServer(send);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				list.AddRange(mc.ExtractActualData(oResult2.Content, isBit: false));
				num += num2;
				if (oResult.Content.McDataType.DataType == 0)
				{
					oResult.Content.AddressStart += num2;
				}
				else
				{
					oResult.Content.AddressStart += num2 * 16;
				}
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Byte[])" />
		public static OResult Write(IReadWriteMc mc, string address, byte[] value)
		{
			if (address.StartsWith("s=") || address.StartsWith("S="))
			{
				if (mc.McType == McType.McBinary)
				{
					return McBinaryHelper.WriteTag(mc, address.Substring(2), value);
				}
				if (mc.McType == McType.MCAscii)
				{
					return McAsciiHelper.WriteTag(mc, address.Substring(2), value);
				}
			}
			OResult<McAddressData> oResult = mc.McAnalysisAddress(address, 0, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildWriteWordCoreCommand(oResult.Content, value) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiWriteWordCoreCommand(oResult.Content, value) : ((mc.McType == McType.McRBinary) ? MelsecMcRNet.BuildWriteWordCoreCommand(oResult.Content, value) : null)));
			OResult<byte[]> oResult2 = mc.ReadFromCoreServer(send);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadBool(System.String)" />
		/// <remarks>
		/// 对于X,Y类型的地址，有两种表示方式，十六进制和八进制，默认16进制，比如输入 X10 是16进制的，如果想要输入8进制的地址，地址补0操作，例如 X010
		/// </remarks>
		public static OResult<bool> ReadBool(IReadWriteMc mc, string address)
		{
			return ByteTransformHelper.GetResultFromArray(ReadBool(mc, address, 1));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadBool(System.String,System.UInt16)" />
		/// <remarks>
		/// 当读取的长度过大时，会自动进行切割，对于二进制格式，切割长度为7168，对于ASCII格式协议来说，切割长度则是3584<br />
		/// 对于X,Y类型的地址，有两种表示方式，十六进制和八进制，默认16进制，比如输入 X10 是16进制的，如果想要输入8进制的地址，地址补0操作，例如 X010
		/// </remarks>
		public static OResult<bool[]> ReadBool(IReadWriteMc mc, string address, ushort length, bool supportWordAdd = true)
		{
			if ((mc.McType == McType.McBinary && address.StartsWith("s=")) || address.StartsWith("S="))
			{
				return McBinaryHelper.ReadBoolTag(mc, address.Substring(2), length);
			}
			if (supportWordAdd && address.IndexOf('.') > 0)
			{
				return SnetHelper.ReadBool(mc, address, length);
			}
			OResult<McAddressData> oResult = mc.McAnalysisAddress(address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<bool> list = new List<bool>();
			ushort num = 0;
			while (num < length)
			{
				ushort num2 = (ushort)Math.Min(length - num, GetReadBoolLength(mc.McType));
				oResult.Content.Length = num2;
				byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildReadMcCoreCommand(oResult.Content, isBit: true) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiReadMcCoreCommand(oResult.Content, isBit: true) : ((mc.McType == McType.McRBinary) ? MelsecMcRNet.BuildReadMcCoreCommand(oResult.Content, isBit: true) : null)));
				OResult<byte[]> oResult2 = mc.ReadFromCoreServer(send);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				list.AddRange((from m in mc.ExtractActualData(oResult2.Content, isBit: true)
					select m == 1).Take(num2).ToArray());
				num += num2;
				oResult.Content.AddressStart += num2;
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean[])" />
		/// <remarks>
		/// 当读取的长度过大时，会自动进行切割，对于二进制格式，切割长度为7168，对于ASCII格式协议来说，切割长度则是3584<br />
		/// 对于X,Y类型的地址，有两种表示方式，十六进制和八进制，默认16进制，比如输入 X10 是16进制的，如果想要输入8进制的地址，地址补0操作，例如 X010
		/// </remarks>
		public static OResult Write(IReadWriteMc mc, string address, bool[] values, bool supportWordAdd = true)
		{
			if ((mc.McType == McType.McBinary && address.StartsWith("s=")) || address.StartsWith("S="))
			{
				return McBinaryHelper.WriteTag(mc, address.Substring(2), values);
			}
			if (supportWordAdd && mc.EnableWriteBitToWordRegister && address.Contains("."))
			{
				return ReadWriteNetHelper.WriteBoolWithWord(mc, address, values);
			}
			OResult<McAddressData> oResult = mc.McAnalysisAddress(address, 0, isBit: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildWriteBitCoreCommand(oResult.Content, values) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiWriteBitCoreCommand(oResult.Content, values) : ((mc.McType == McType.McRBinary) ? MelsecMcRNet.BuildWriteBitCoreCommand(oResult.Content, values) : null)));
			OResult<byte[]> oResult2 = mc.ReadFromCoreServer(send);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.McHelper.Read(Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc,System.String,System.UInt16)" />
		public static async Task<OResult<byte[]>> ReadAsync(IReadWriteMc mc, string address, ushort length)
		{
			if ((mc.McType == McType.McBinary && address.StartsWith("s=")) || address.StartsWith("S="))
			{
				return await McBinaryHelper.ReadTagsAsync(mc, new string[1] { address.Substring(2) }, new ushort[1] { length });
			}
			if ((mc.McType == McType.McBinary || mc.McType == McType.MCAscii) && Regex.IsMatch(address, "ext=[0-9]+;", RegexOptions.IgnoreCase))
			{
				string value = Regex.Match(address, "ext=[0-9]+;").Value;
				ushort extend = ushort.Parse(Regex.Match(value, "[0-9]+").Value);
				return await ReadExtendAsync(mc, extend, address.Substring(value.Length), length);
			}
			if ((mc.McType == McType.McBinary || mc.McType == McType.MCAscii) && Regex.IsMatch(address, "mem=", RegexOptions.IgnoreCase))
			{
				return await ReadMemoryAsync(mc, address.Substring(4), length);
			}
			if ((mc.McType == McType.McBinary || mc.McType == McType.MCAscii) && Regex.IsMatch(address, "module=[0-9]+;", RegexOptions.IgnoreCase))
			{
				string value2 = Regex.Match(address, "module=[0-9]+;").Value;
				ushort module = ushort.Parse(Regex.Match(value2, "[0-9]+").Value);
				return await ReadSmartModuleAsync(mc, module, address.Substring(value2.Length), (ushort)(length * 2));
			}
			OResult<McAddressData> addressResult = mc.McAnalysisAddress(address, length, isBit: false);
			if (!addressResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(addressResult);
			}
			List<byte> bytesContent = new List<byte>();
			ushort alreadyFinished = 0;
			while (alreadyFinished < length)
			{
				ushort readLength = (ushort)Math.Min(length - alreadyFinished, GetReadWordLength(mc.McType));
				addressResult.Content.Length = readLength;
				byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildReadMcCoreCommand(addressResult.Content, isBit: false) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiReadMcCoreCommand(addressResult.Content, isBit: false) : ((mc.McType == McType.McRBinary) ? MelsecMcRNet.BuildReadMcCoreCommand(addressResult.Content, isBit: false) : null)));
				OResult<byte[]> oResult = await mc.ReadFromCoreServerAsync(send);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				bytesContent.AddRange(mc.ExtractActualData(oResult.Content, isBit: false));
				alreadyFinished += readLength;
				if (addressResult.Content.McDataType.DataType == 0)
				{
					addressResult.Content.AddressStart += readLength;
				}
				else
				{
					addressResult.Content.AddressStart += readLength * 16;
				}
			}
			return OResult.CreateSuccessResult(bytesContent.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Byte[])" />
		public static async Task<OResult> WriteAsync(IReadWriteMc mc, string address, byte[] value)
		{
			if ((mc.McType == McType.McBinary && address.StartsWith("s=")) || address.StartsWith("S="))
			{
				return await McBinaryHelper.WriteTagAsync(mc, address.Substring(2), value);
			}
			OResult<McAddressData> oResult = mc.McAnalysisAddress(address, 0, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildWriteWordCoreCommand(oResult.Content, value) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiWriteWordCoreCommand(oResult.Content, value) : ((mc.McType == McType.McRBinary) ? MelsecMcRNet.BuildWriteWordCoreCommand(oResult.Content, value) : null)));
			OResult<byte[]> oResult2 = await mc.ReadFromCoreServerAsync(send);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.McHelper.ReadBool(Snet.Driver.Profinet.Melsec.Helper.IReadWriteMc,System.String,System.UInt16,System.Boolean)" />
		public static async Task<OResult<bool[]>> ReadBoolAsync(IReadWriteMc mc, string address, ushort length, bool supportWordAdd = true)
		{
			if ((mc.McType == McType.McBinary && address.StartsWith("s=")) || address.StartsWith("S="))
			{
				return await McBinaryHelper.ReadBoolTagAsync(mc, address.Substring(2), length);
			}
			if (supportWordAdd && address.IndexOf('.') > 0)
			{
				return await SnetHelper.ReadBoolAsync(mc, address, length);
			}
			OResult<McAddressData> addressResult = mc.McAnalysisAddress(address, length, isBit: true);
			if (!addressResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(addressResult);
			}
			List<bool> boolContent = new List<bool>();
			ushort alreadyFinished = 0;
			while (alreadyFinished < length)
			{
				ushort readLength = (ushort)Math.Min(length - alreadyFinished, GetReadBoolLength(mc.McType));
				addressResult.Content.Length = readLength;
				byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildReadMcCoreCommand(addressResult.Content, isBit: true) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiReadMcCoreCommand(addressResult.Content, isBit: true) : ((mc.McType == McType.McRBinary) ? MelsecMcRNet.BuildReadMcCoreCommand(addressResult.Content, isBit: true) : null)));
				OResult<byte[]> oResult = await mc.ReadFromCoreServerAsync(send);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				boolContent.AddRange((from m in mc.ExtractActualData(oResult.Content, isBit: true)
					select m == 1).Take(readLength).ToArray());
				alreadyFinished += readLength;
				addressResult.Content.AddressStart += readLength;
			}
			return OResult.CreateSuccessResult(boolContent.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean[])" />
		public static async Task<OResult> WriteAsync(IReadWriteMc mc, string address, bool[] values, bool supportWordAdd = true)
		{
			if ((mc.McType == McType.McBinary && address.StartsWith("s=")) || address.StartsWith("S="))
			{
				return await McBinaryHelper.WriteTagAsync(mc, address.Substring(2), values);
			}
			if (supportWordAdd && mc.EnableWriteBitToWordRegister && address.Contains("."))
			{
				return await ReadWriteNetHelper.WriteBoolWithWordAsync(mc, address, values).ConfigureAwait(continueOnCapturedContext: false);
			}
			OResult<McAddressData> oResult = mc.McAnalysisAddress(address, 0, isBit: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildWriteBitCoreCommand(oResult.Content, values) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiWriteBitCoreCommand(oResult.Content, values) : ((mc.McType == McType.McRBinary) ? MelsecMcRNet.BuildWriteBitCoreCommand(oResult.Content, values) : null)));
			OResult<byte[]> oResult2 = await mc.ReadFromCoreServerAsync(send);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 随机读取PLC的数据信息，可以跨地址，跨类型组合，但是每个地址只能读取一个word，也就是2个字节的内容。收到结果后，需要自行解析数据<br />
		/// Randomly read PLC data information, which can be combined across addresses and types, but each address can only read one word, 
		/// which is the content of 2 bytes. After receiving the results, you need to parse the data yourself
		/// </summary>
		/// <param name="mc">MC协议通信对象</param>
		/// <param name="address">所有的地址的集合</param>
		/// <remarks>
		/// 访问安装有 Q 系列 C24/E71 的站 QCPU 上位站 经由 Q 系列兼容网络系统 MELSECNET/H MELSECNET/10 Ethernet 的 QCPU 其他站 时
		/// 访问点数········1≦ 字访问点数 双字访问点数 ≦192
		/// <br />
		/// 访问 QnACPU 其他站 经由 QnA 系列兼容网络系统 MELSECNET/10 Ethernet 的 Q/QnACPU 其他站 时访问点数········1≦ 字访问点数 双字访问点数 ≦96
		/// <br />
		/// 访问上述以外的 PLC CPU 其他站 时访问点数········1≦字访问点数≦10
		/// </remarks>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample3" title="随机字读取示例" /></example>
		/// <returns>结果</returns>
		public static OResult<byte[]> ReadRandom(IReadWriteMc mc, string[] address)
		{
			McAddressData[] array = new McAddressData[address.Length];
			for (int i = 0; i < address.Length; i++)
			{
				OResult<McAddressData> oResult = McAddressData.ParseMelsecFrom(address[i], 1, isBit: false);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				array[i] = oResult.Content;
			}
			List<byte[]> list = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildReadRandomWordCommand(array) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiReadRandomWordCommand(array) : null));
			List<byte> list2 = new List<byte>();
			for (int j = 0; j < list.Count; j++)
			{
				OResult<byte[]> oResult2 = mc.ReadFromCoreServer(list[j]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				list2.AddRange(mc.ExtractActualData(oResult2.Content, isBit: false));
			}
			return OResult.CreateSuccessResult(list2.ToArray());
		}

		/// <summary>
		/// 使用块读取PLC的数据信息，可以跨地址，跨类型组合，每个地址是任意的长度。收到结果后，需要自行解析数据，目前只支持字地址，比如D区，W区，R区，不支持X，Y，M，B，L等等<br />
		/// Read the data information of the PLC randomly. It can be combined across addresses and types. Each address is of any length. After receiving the results, 
		/// you need to parse the data yourself. Currently, only word addresses are supported, such as D area, W area, R area. X, Y, M, B, L, etc
		/// </summary>
		/// <param name="mc">MC协议通信对象</param>
		/// <param name="address">所有的地址的集合</param>
		/// <param name="length">每个地址的长度信息</param>
		/// <remarks>
		/// 实际测试不一定所有的plc都可以读取成功，具体情况需要具体分析
		/// <br />
		/// 1 块数按照下列要求指定 120 ≧ 字软元件块数 + 位软元件块数
		/// <br />
		/// 2 各软元件点数按照下列要求指定 960 ≧ 字软元件各块的合计点数 + 位软元件各块的合计点数
		/// </remarks>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\melsecTest.cs" region="ReadExample4" title="随机批量字读取示例" />
		/// </example>
		/// <returns>结果</returns>
		public static OResult<byte[]> ReadRandom(IReadWriteMc mc, string[] address, ushort[] length)
		{
			if (length.Length != address.Length)
			{
				return new OResult<byte[]>(StringResources.Language.TwoParametersLengthIsNotSame);
			}
			McAddressData[] array = new McAddressData[address.Length];
			for (int i = 0; i < address.Length; i++)
			{
				OResult<McAddressData> oResult = McAddressData.ParseMelsecFrom(address[i], length[i], isBit: false);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				array[i] = oResult.Content;
			}
			byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildReadRandomCommand(array) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildAsciiReadRandomCommand(array) : null));
			OResult<byte[]> oResult2 = mc.ReadFromCoreServer(send);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult(mc.ExtractActualData(oResult2.Content, isBit: false));
		}

		/// <summary>
		/// 随机字写入数据到PLC里，可以跨地址写入，指定一个字符串数组，一个地址需要对应2个字节，所以写入的字节长度为地址两倍。<br />
		/// Randomly write data into the PLC. It can be written across addresses. Specify a string array. One address needs to correspond to 2 bytes, so the length of the written bytes is twice the address.
		/// </summary>
		/// <param name="mc">MC协议通信对象</param>
		/// <param name="address">所有的地址集合</param>
		/// <param name="data">写入数据</param>
		/// <returns>是否写入成功</returns>
		public static OResult WriteRandom(IReadWriteMc mc, string[] address, byte[] data)
		{
			if (data.Length != address.Length * 2)
			{
				return new OResult<byte[]>(StringResources.Language.TwoParametersLengthIsNotSame);
			}
			McAddressData[] array = new McAddressData[address.Length];
			for (int i = 0; i < address.Length; i++)
			{
				OResult<McAddressData> oResult = McAddressData.ParseMelsecFrom(address[i], 0, isBit: false);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				array[i] = oResult.Content;
			}
			byte[] send = ((mc.McType == McType.McBinary) ? McBinaryHelper.BuildWriteRandomWordCommand(array, data) : ((mc.McType == McType.MCAscii) ? McAsciiHelper.BuildWriteRandomWordCommand(array, data) : null));
			OResult<byte[]> oResult2 = mc.ReadFromCoreServer(send);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult(mc.ExtractActualData(oResult2.Content, isBit: false));
		}

