		/// <param name="mc">MC协议通信对象</param>
		/// <returns>是否成功</returns>
		public static OResult RemoteRun(IReadWriteMc mc)
		{
			if (mc.McType != McType.McBinary)
			{
				if (mc.McType != McType.MCAscii)
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedFunction);
				}
				return mc.ReadFromCoreServer(Encoding.ASCII.GetBytes("1001000000010000"));
			}
			return mc.ReadFromCoreServer(new byte[8] { 1, 16, 0, 0, 1, 0, 0, 0 });
		}

