	/// <summary>
	/// MC协议的类型
	/// </summary>
	public enum McType
	{
		/// <summary>
		/// 基于二进制的MC协议
		/// </summary>
		McBinary,
		/// <summary>
		/// 基于ASCII格式的MC协议
		/// </summary>
		MCAscii,
		/// <summary>
		/// 基于R系列的二进制的MC协议
		/// </summary>
		McRBinary,
		/// <summary>
		/// 基于R系列的ASCII格式的MC协议
		/// </summary>
		McRAscii
	}
	/// <summary>
	/// MelsecA3CNet1协议通信的辅助类
	/// </summary>
	public class MelsecA3CNetHelper
	{
		/// <summary>
		/// 将命令进行打包传送，可选站号及是否和校验机制
		/// </summary>
		/// <param name="plc">PLC设备通信对象</param>
		/// <param name="mcCommand">mc协议的命令</param>
		/// <param name="station">PLC的站号</param>
		/// <returns>最终的原始报文信息</returns>
		public static byte[] PackCommand(IReadWriteA3C plc, byte[] mcCommand, byte station = 0)
		{
			MemoryStream memoryStream = new MemoryStream();
			if (plc.Format != 3)
			{
				memoryStream.WriteByte(5);
			}
			else
			{
				memoryStream.WriteByte(2);
			}
			if (plc.Format == 2)
			{
				memoryStream.WriteByte(48);
				memoryStream.WriteByte(48);
			}
			memoryStream.WriteByte(70);
			memoryStream.WriteByte(57);
			memoryStream.WriteByte(SoftBasic.BuildAsciiBytesFrom(station)[0]);
			memoryStream.WriteByte(SoftBasic.BuildAsciiBytesFrom(station)[1]);
			memoryStream.WriteByte(48);
			memoryStream.WriteByte(48);
			memoryStream.WriteByte(70);
			memoryStream.WriteByte(70);
			memoryStream.WriteByte(48);
			memoryStream.WriteByte(48);
			memoryStream.Write(mcCommand, 0, mcCommand.Length);
			if (plc.Format == 3)
			{
				memoryStream.WriteByte(3);
			}
			if (plc.SumCheck)
			{
				byte[] array = memoryStream.ToArray();
				int num = 0;
				for (int i = 1; i < array.Length; i++)
				{
					num += array[i];
				}
				memoryStream.WriteByte(SoftBasic.BuildAsciiBytesFrom((byte)num)[0]);
				memoryStream.WriteByte(SoftBasic.BuildAsciiBytesFrom((byte)num)[1]);
			}
			if (plc.Format == 4)
			{
				memoryStream.WriteByte(13);
				memoryStream.WriteByte(10);
			}
			byte[] result = memoryStream.ToArray();
			memoryStream.Dispose();
			return result;
		}

		private static int GetErrorCodeOrDataStartIndex(IReadWriteA3C plc)
		{
			int result = 11;
			switch (plc.Format)
			{
			case 1:
				result = 11;
				break;
			case 2:
				result = 13;
				break;
			case 3:
				result = 15;
				break;
			case 4:
				result = 11;
				break;
			}
			return result;
		}

		/// <summary>
		/// 根据PLC返回的数据信息，获取到实际的数据内容
		/// </summary>
		/// <param name="plc">PLC设备通信对象</param>
		/// <param name="response">PLC返回的数据信息</param>
		/// <returns>带有是否成功的读取结果对象内容</returns>
		public static OResult<byte[]> ExtraReadActualResponse(IReadWriteA3C plc, byte[] response)
		{
			try
			{
				int errorCodeOrDataStartIndex = GetErrorCodeOrDataStartIndex(plc);
				if (plc.Format == 1 || plc.Format == 2 || plc.Format == 4)
				{
					if (response[0] == 21)
					{
						int num = Convert.ToInt32(Encoding.ASCII.GetString(response, errorCodeOrDataStartIndex, 4), 16);
						return new OResult<byte[]>(num, MelsecHelper.GetErrorDescription(num));
					}
					if (response[0] != 2)
					{
						return new OResult<byte[]>(response[0], "Read Faild:" + SoftBasic.GetAsciiStringRender(response));
					}
				}
				else if (plc.Format == 3)
				{
					string text = Encoding.ASCII.GetString(response, 11, 4);
					if (text == "QNAK")
					{
						int num2 = Convert.ToInt32(Encoding.ASCII.GetString(response, errorCodeOrDataStartIndex, 4), 16);
						return new OResult<byte[]>(num2, MelsecHelper.GetErrorDescription(num2));
					}
					if (text != "QACK")
					{
						return new OResult<byte[]>(response[0], "Read Faild:" + SoftBasic.GetAsciiStringRender(response));
					}
				}
				int num3 = -1;
				for (int i = errorCodeOrDataStartIndex; i < response.Length; i++)
				{
					if (response[i] == 3)
					{
						num3 = i;
						break;
					}
				}
				if (num3 == -1)
				{
					num3 = response.Length;
				}
				return OResult.CreateSuccessResult(response.SelectMiddle(errorCodeOrDataStartIndex, num3 - errorCodeOrDataStartIndex));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("ExtraReadActualResponse Wrong:" + ex.Message + Environment.NewLine + "Source: " + response.ToHexString(' '));
			}
		}

		private static OResult CheckWriteResponse(IReadWriteA3C plc, byte[] response)
		{
			int errorCodeOrDataStartIndex = GetErrorCodeOrDataStartIndex(plc);
			try
			{
				if (plc.Format == 1 || plc.Format == 2)
				{
					if (response[0] == 21)
					{
						int num = Convert.ToInt32(Encoding.ASCII.GetString(response, errorCodeOrDataStartIndex, 4), 16);
						return new OResult<byte[]>(num, MelsecHelper.GetErrorDescription(num));
					}
					if (response[0] != 6)
					{
						return new OResult<byte[]>(response[0], "Write Faild:" + SoftBasic.GetAsciiStringRender(response));
					}
				}
				else if (plc.Format == 3)
				{
					if (response[0] != 2)
					{
						return new OResult<byte[]>(response[0], "Write Faild:" + SoftBasic.GetAsciiStringRender(response));
					}
					string text = Encoding.ASCII.GetString(response, 11, 4);
					if (text == "QNAK")
					{
						int num2 = Convert.ToInt32(Encoding.ASCII.GetString(response, errorCodeOrDataStartIndex, 4), 16);
						return new OResult<byte[]>(num2, MelsecHelper.GetErrorDescription(num2));
					}
					if (text != "QACK")
					{
						return new OResult<byte[]>(response[0], "Write Faild:" + SoftBasic.GetAsciiStringRender(response));
					}
				}
				else if (plc.Format == 4)
				{
					if (response[0] == 21)
					{
						int num3 = Convert.ToInt32(Encoding.ASCII.GetString(response, errorCodeOrDataStartIndex, 4), 16);
						return new OResult<byte[]>(num3, MelsecHelper.GetErrorDescription(num3));
					}
					if (response[0] != 6)
					{
						return new OResult<byte[]>(response[0], "Write Faild:" + SoftBasic.GetAsciiStringRender(response));
					}
				}
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("CheckWriteResponse failed: " + ex.Message + Environment.NewLine + "Content: " + SoftBasic.GetAsciiStringRender(response));
			}
		}

		/// <summary>
		/// 批量读取PLC的数据，以字为单位，支持读取X,Y,M,S,D,T,C，具体的地址范围需要根据PLC型号来确认
		/// </summary>
		/// <param name="plc">PLC设备通信对象</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>读取结果信息</returns>
		public static OResult<byte[]> Read(IReadWriteA3C plc, string address, ushort length)
		{
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", plc.Station);
			OResult<McAddressData> oResult = McAddressData.ParseMelsecFrom(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			ushort num = 0;
			while (num < length)
			{
				ushort num2 = (ushort)Math.Min(length - num, McHelper.GetReadWordLength(McType.MCAscii));
				oResult.Content.Length = num2;
				byte[] mcCommand = McAsciiHelper.BuildAsciiReadMcCoreCommand(oResult.Content, isBit: false);
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(PackCommand(plc, mcCommand, station));
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult<byte[]> oResult3 = ExtraReadActualResponse(plc, oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				list.AddRange(MelsecHelper.TransAsciiByteArrayToByteArray(oResult3.Content));
				num += num2;
				if (oResult.Content.McDataType.DataType == 0)
				{
					oResult.Content.AddressStart += num2;
				}
				else
				{
					oResult.Content.AddressStart += num2 * 16;
				}
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.MelsecA3CNetHelper.Read(Snet.Driver.Profinet.Melsec.Helper.IReadWriteA3C,System.String,System.UInt16)" />
		public static async Task<OResult<byte[]>> ReadAsync(IReadWriteA3C plc, string address, ushort length)
		{
			byte stat = (byte)SnetHelper.ExtractParameter(ref address, "s", plc.Station);
			OResult<McAddressData> addressResult = McAddressData.ParseMelsecFrom(address, length, isBit: false);
			if (!addressResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(addressResult);
			}
			List<byte> bytesContent = new List<byte>();
			ushort alreadyFinished = 0;
			while (alreadyFinished < length)
			{
				ushort readLength = (ushort)Math.Min(length - alreadyFinished, McHelper.GetReadWordLength(McType.MCAscii));
				addressResult.Content.Length = readLength;
				byte[] mcCommand = McAsciiHelper.BuildAsciiReadMcCoreCommand(addressResult.Content, isBit: false);
				OResult<byte[]> oResult = await plc.ReadFromCoreServerAsync(PackCommand(plc, mcCommand, stat));
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = ExtraReadActualResponse(plc, oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				bytesContent.AddRange(MelsecHelper.TransAsciiByteArrayToByteArray(oResult2.Content));
				alreadyFinished += readLength;
				if (addressResult.Content.McDataType.DataType == 0)
				{
					addressResult.Content.AddressStart += readLength;
				}
				else
				{
					addressResult.Content.AddressStart += readLength * 16;
				}
			}
			return OResult.CreateSuccessResult(bytesContent.ToArray());
		}

