		/// <summary>
		/// 批量读取bool类型数据，支持的类型为X,Y,S,T,C，具体的地址范围取决于PLC的类型
		/// </summary>
		/// <param name="plc">PLC设备通信对象</param>
		/// <param name="address">地址信息，比如X10,Y17，注意X，Y的地址是8进制的</param>
		/// <param name="length">读取的长度</param>
		/// <returns>读取结果信息</returns>
		public static OResult<bool[]> ReadBool(IReadWriteA3C plc, string address, ushort length)
		{
			if (address.IndexOf('.') > 0)
			{
				return SnetHelper.ReadBool(plc, address, length);
			}
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", plc.Station);
			OResult<McAddressData> oResult = McAddressData.ParseMelsecFrom(address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<bool> list = new List<bool>();
			ushort num = 0;
			while (num < length)
			{
				ushort num2 = (ushort)Math.Min(length - num, McHelper.GetReadBoolLength(McType.MCAscii));
				oResult.Content.Length = num2;
				byte[] mcCommand = McAsciiHelper.BuildAsciiReadMcCoreCommand(oResult.Content, isBit: true);
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(PackCommand(plc, mcCommand, station));
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult<byte[]> oResult3 = ExtraReadActualResponse(plc, oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				list.AddRange(oResult3.Content.Select((byte m) => m == 49).ToArray());
				num += num2;
				oResult.Content.AddressStart += num2;
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Melsec.Helper.MelsecA3CNetHelper.ReadBool(Snet.Driver.Profinet.Melsec.Helper.IReadWriteA3C,System.String,System.UInt16)" />
		public static async Task<OResult<bool[]>> ReadBoolAsync(IReadWriteA3C plc, string address, ushort length)
		{
			if (address.IndexOf('.') > 0)
			{
				return await SnetHelper.ReadBoolAsync(plc, address, length);
			}
			byte stat = (byte)SnetHelper.ExtractParameter(ref address, "s", plc.Station);
			OResult<McAddressData> addressResult = McAddressData.ParseMelsecFrom(address, length, isBit: true);
			if (!addressResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(addressResult);
			}
			List<bool> boolContent = new List<bool>();
			ushort alreadyFinished = 0;
			while (alreadyFinished < length)
			{
				ushort readLength = (ushort)Math.Min(length - alreadyFinished, McHelper.GetReadBoolLength(McType.MCAscii));
				addressResult.Content.Length = readLength;
				byte[] mcCommand = McAsciiHelper.BuildAsciiReadMcCoreCommand(addressResult.Content, isBit: true);
				OResult<byte[]> oResult = await plc.ReadFromCoreServerAsync(PackCommand(plc, mcCommand, stat));
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				OResult<byte[]> oResult2 = ExtraReadActualResponse(plc, oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				boolContent.AddRange(oResult2.Content.Select((byte m) => m == 49).ToArray());
				alreadyFinished += readLength;
				addressResult.Content.AddressStart += readLength;
			}
			return OResult.CreateSuccessResult(boolContent.ToArray());
		}

