	/// <summary>
	/// 三菱的FxLinks的辅助方法信息
	/// </summary>
	public class MelsecFxLinksHelper
	{
		/// <summary>
		/// 将当前的报文进行打包，根据和校验的方式以及格式信息来实现打包操作
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="command">原始的命令数据</param>
		/// <returns>打包后的命令</returns>
		public static byte[] PackCommandWithHeader(IReadWriteFxLinks plc, byte[] command)
		{
			if (command.Length > 3 && command[0] == 5)
			{
				return command;
			}
			byte[] array = command;
			if (plc.SumCheck)
			{
				array = new byte[command.Length + 2];
				command.CopyTo(array, 0);
				SoftLRC.CalculateAccAndFill(array, 0, 2);
			}
			if (plc.Format == 1)
			{
				return SoftBasic.SpliceArray<byte>(new byte[1] { 5 }, array);
			}
			if (plc.Format == 4)
			{
				return SoftBasic.SpliceArray<byte>(new byte[1] { 5 }, array, new byte[2] { 13, 10 });
			}
			return SoftBasic.SpliceArray<byte>(new byte[1] { 5 }, array);
		}

		/// <summary>
		/// 创建一条读取的指令信息，需要指定一些参数
		/// </summary>
		/// <param name="plc">PLC通信的对象</param>
		/// <param name="station">PLC的站号</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <param name="isBool">是否位读取</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<List<byte[]>> BuildReadCommand(IReadWriteFxLinks plc, byte station, string address, ushort length, bool isBool)
		{
			OResult<MelsecFxLinksAddress> oResult = plc.AnalyzeAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			int[] array = SoftBasic.SplitIntegerToArray(length, isBool ? 256 : 64);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append(station.ToString("X2"));
				stringBuilder.Append("FF");
				if (isBool)
				{
					stringBuilder.Append("BR");
				}
				else if (oResult.Content.AddressStart >= 10000)
				{
					stringBuilder.Append("QR");
				}
				else
				{
					stringBuilder.Append("WR");
				}
				stringBuilder.Append(plc.WaittingTime.ToString("X"));
				stringBuilder.Append(oResult.Content.ToString());
				if (array[i] == 256)
				{
					stringBuilder.Append("00");
				}
				else
				{
					stringBuilder.Append(array[i].ToString("X2"));
				}
				list.Add(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
				oResult.Content.AddressStart += array[i];
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 创建一条别入bool数据的指令信息，需要指定一些参数
		/// </summary>
		/// <param name="plc">PLC通信的对象</param>
		/// <param name="station">站号</param>
		/// <param name="address">地址</param>
		/// <param name="value">数组值</param>
		/// <returns>是否创建成功</returns>
		public static OResult<byte[]> BuildWriteBoolCommand(IReadWriteFxLinks plc, byte station, string address, bool[] value)
		{
			OResult<MelsecFxLinksAddress> oResult = plc.AnalyzeAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(station.ToString("X2"));
			stringBuilder.Append("FF");
			stringBuilder.Append("BW");
			stringBuilder.Append(plc.WaittingTime.ToString("X"));
			stringBuilder.Append(oResult.Content.ToString());
			stringBuilder.Append(value.Length.ToString("X2"));
			for (int i = 0; i < value.Length; i++)
			{
				stringBuilder.Append(value[i] ? "1" : "0");
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 创建一条别入byte数据的指令信息，需要指定一些参数，按照字单位
		/// </summary>
		/// <param name="plc">PLC通信的对象</param>
		/// <param name="station">站号</param>
		/// <param name="address">地址</param>
		/// <param name="value">数组值</param>
		/// <returns>命令报文的结果内容对象</returns>
		public static OResult<byte[]> BuildWriteByteCommand(IReadWriteFxLinks plc, byte station, string address, byte[] value)
		{
			OResult<MelsecFxLinksAddress> oResult = plc.AnalyzeAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(station.ToString("X2"));
			stringBuilder.Append("FF");
			if (oResult.Content.AddressStart >= 10000)
			{
				stringBuilder.Append("QW");
			}
			else
			{
				stringBuilder.Append("WW");
			}
			stringBuilder.Append(plc.WaittingTime.ToString("X"));
			stringBuilder.Append(oResult.Content.ToString());
			stringBuilder.Append((value.Length / 2).ToString("X2"));
			byte[] array = new byte[value.Length * 2];
			for (int i = 0; i < value.Length / 2; i++)
			{
				SoftBasic.BuildAsciiBytesFrom(BitConverter.ToUInt16(value, i * 2)).CopyTo(array, 4 * i);
			}
			stringBuilder.Append(Encoding.ASCII.GetString(array));
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

