		/// <summary>
		/// 从编码中提取PLC的型号信息
		/// </summary>
		/// <param name="code">编码</param>
		/// <returns>PLC的型号信息</returns>
		public static OResult<string> GetPlcTypeFromCode(string code)
		{
			return code switch
			{
				"F2" => OResult.CreateSuccessResult("FX1S"), 
				"8E" => OResult.CreateSuccessResult("FX0N"), 
				"8D" => OResult.CreateSuccessResult("FX2/FX2C"), 
				"9E" => OResult.CreateSuccessResult("FX1N/FX1NC"), 
				"9D" => OResult.CreateSuccessResult("FX2N/FX2NC"), 
				"F4" => OResult.CreateSuccessResult("FX3G"), 
				"F3" => OResult.CreateSuccessResult("FX3U/FX3UC"), 
				"98" => OResult.CreateSuccessResult("A0J2HCPU"), 
				"A1" => OResult.CreateSuccessResult("A1CPU /A1NCPU"), 
				"A2" => OResult.CreateSuccessResult("A2CPU/A2NCPU/A2SCPU"), 
				"92" => OResult.CreateSuccessResult("A2ACPU"), 
				"93" => OResult.CreateSuccessResult("A2ACPU-S1"), 
				"9A" => OResult.CreateSuccessResult("A2CCPU"), 
				"82" => OResult.CreateSuccessResult("A2USCPU"), 
				"83" => OResult.CreateSuccessResult("A2CPU-S1/A2USCPU-S1"), 
				"A3" => OResult.CreateSuccessResult("A3CPU/A3NCPU"), 
				"94" => OResult.CreateSuccessResult("A3ACPU"), 
				"A4" => OResult.CreateSuccessResult("A3HCPU/A3MCPU"), 
				"84" => OResult.CreateSuccessResult("A3UCPU"), 
				"85" => OResult.CreateSuccessResult("A4UCPU"), 
				"AB" => OResult.CreateSuccessResult("AJ72P25/R25"), 
				"8B" => OResult.CreateSuccessResult("AJ72LP25/BR15"), 
				_ => new OResult<string>(StringResources.Language.NotSupportedDataType + " Code:" + code), 
			};
		}

		private static string GetErrorText(int error)
		{
			return error switch
			{
				2 => StringResources.Language.MelsecFxLinksError02, 
				3 => StringResources.Language.MelsecFxLinksError03, 
				6 => StringResources.Language.MelsecFxLinksError06, 
				7 => StringResources.Language.MelsecFxLinksError07, 
				10 => StringResources.Language.MelsecFxLinksError0A, 
				16 => StringResources.Language.MelsecFxLinksError10, 
				24 => StringResources.Language.MelsecFxLinksError18, 
				_ => StringResources.Language.UnknownError, 
			};
		}

		/// <summary>
		/// 检查PLC的消息反馈是否合法，合法则提取当前的数据信息，当时写入的命令消息时，无任何的数据返回<br />
		/// Check whether the PLC's message feedback is legal. If it is legal, extract the current data information. When the command message is written at that time, no data is returned.
		/// </summary>
		/// <param name="response">从PLC反馈的数据消息</param>
		/// <returns>检查的结果消息</returns>
		public static OResult<byte[]> CheckPlcResponse(byte[] response)
		{
			try
			{
				if (response[0] == 21)
				{
					int num = Convert.ToInt32(Encoding.ASCII.GetString(response, 5, 2), 16);
					return new OResult<byte[]>(num, GetErrorText(num));
				}
				if (response[0] != 2 && response[0] != 6)
				{
					return new OResult<byte[]>(response[0], "Check command failed: " + SoftBasic.GetAsciiStringRender(response));
				}
				if (response[0] == 6)
				{
					return OResult.CreateSuccessResult(new byte[0]);
				}
				int num2 = -1;
				for (int i = 5; i < response.Length; i++)
				{
					if (response[i] == 3)
					{
						num2 = i;
						break;
					}
				}
				if (num2 == -1)
				{
					num2 = response.Length;
				}
				return OResult.CreateSuccessResult(response.SelectMiddle(5, num2 - 5));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Check Plc Response failed Error: " + ex.Message + " Source: " + SoftBasic.GetAsciiStringRender(response));
			}
		}

		private static OResult<byte[]> ExtraResponse(byte[] response)
		{
			try
			{
				byte[] array = new byte[response.Length / 2];
				for (int i = 0; i < array.Length / 2; i++)
				{
					BitConverter.GetBytes(Convert.ToUInt16(Encoding.ASCII.GetString(response, i * 4, 4), 16)).CopyTo(array, i * 2);
				}
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Extra source data failed: " + ex.Message + Environment.NewLine + "Source: " + response.ToHexString(' '));
			}
		}

		/// <summary>
		/// 批量读取PLC的数据，以字为单位，支持读取X,Y,M,S,D,T,C，具体的地址范围需要根据PLC型号来确认，地址支持动态指定站号，例如：s=2;D100<br />
		/// Read PLC data in batches, in units of words, supports reading X, Y, M, S, D, T, C. 
		/// The specific address range needs to be confirmed according to the PLC model, 
		/// The address supports dynamically specifying the station number, for example: s=2;D100
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>读取结果信息</returns>
		public static OResult<byte[]> Read(IReadWriteFxLinks plc, string address, ushort length)
		{
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", plc.Station);
			OResult<List<byte[]>> oResult = BuildReadCommand(plc, station, address, length, isBool: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult<byte[]> oResult3 = CheckPlcResponse(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				OResult<byte[]> oResult4 = ExtraResponse(oResult3.Content);
				if (!oResult4.IsSuccess)
				{
					return oResult4;
				}
				list.AddRange(oResult4.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

