		/// <returns>读取结果信息</returns>
		public static OResult<bool[]> ReadBool(IReadWriteFxLinks plc, string address, ushort length)
		{
			if (address.IndexOf('.') > 0)
			{
				return SnetHelper.ReadBool(plc, address, length);
			}
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", plc.Station);
			OResult<List<byte[]>> oResult = BuildReadCommand(plc, station, address, length, isBool: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<bool> list = new List<bool>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult<byte[]> oResult3 = CheckPlcResponse(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
