	/// <summary>
	/// 三菱编程口协议的辅助方法，定义了如何读写bool数据，以及读写原始字节的数据。<br />
	/// The auxiliary method of Mitsubishi programming port protocol defines how to read and write bool data and read and write raw byte data.
	/// </summary>
	public class MelsecFxSerialHelper
	{
		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.NetMessageBase.CheckReceiveDataComplete(System.Byte[],System.IO.MemoryStream)" />
		public static bool CheckReceiveDataComplete(byte[] buffer)
		{
			if (buffer.Length == 0)
			{
				return false;
			}
			if (buffer.Length == 1)
			{
				if (buffer[0] == 21)
				{
					return true;
				}
				if (buffer[0] == 6)
				{
					return true;
				}
			}
			if (buffer.Length == 2 && buffer[0] == 6 && buffer[1] == 3)
			{
				return true;
			}
			int num = FindSTXIndex(buffer);
			if (num > 0)
			{
				return CheckReceiveDataCompleteHelper(buffer.RemoveBegin(num));
			}
			return CheckReceiveDataCompleteHelper(buffer);
		}

		private static bool CheckReceiveDataCompleteHelper(byte[] buffer)
		{
			if (buffer[0] == 2 && buffer.Length >= 5 && buffer[^3] == 3 && MelsecHelper.CheckCRC(buffer))
			{
				return true;
			}
			return false;
		}

		internal static int FindSTXIndex(byte[] buffer)
		{
			int result = 0;
			for (int i = 0; i < buffer.Length; i++)
			{
				if (buffer[i] != 63)
				{
					result = ((buffer[i] == 2) ? i : 0);
					break;
				}
			}
			return result;
		}

		/// <summary>
		/// 根据指定的地址及长度信息从三菱PLC中读取原始的字节数据，根据PLC中实际定义的规则，可以解析出任何类的数据信息<br />
		/// Read the original byte data from the Mitsubishi PLC according to the specified address and length information. 
		/// According to the rules actually defined in the PLC, any type of data information can be parsed
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="address">读取地址，，支持的类型参考文档说明</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="isNewVersion">是否是新版的串口访问类</param>
		/// <returns>带成功标志的结果数据对象</returns>
		/// <example>
		/// 假设起始地址为D100，D100存储了温度，100.6℃值为1006，D101存储了压力，1.23Mpa值为123，D102，D103存储了产量计数，读取如下：
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecFxSerial.cs" region="ReadExample2" title="Read示例" />
		/// 以下是读取不同类型数据的示例
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecFxSerial.cs" region="ReadExample1" title="Read示例" />
		/// </example>
		public static OResult<byte[]> Read(IReadWriteDevice plc, string address, ushort length, bool isNewVersion)
		{
			OResult<List<byte[]>> oResult = BuildReadWordCommand(address, length, isNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult oResult3 = CheckPlcReadResponse(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult3);
				}
				OResult<byte[]> oResult4 = ExtractActualData(oResult2.Content);
				if (!oResult4.IsSuccess)
				{
					return oResult4;
				}
				list.AddRange(oResult4.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <summary>
		/// 从三菱PLC中批量读取位软元件，返回读取结果，该读取地址最好从0，16，32...等开始读取，这样可以读取比较长的数据数组<br />
		/// Read bit devices in batches from Mitsubishi PLC and return the read results. 
		/// The read address should preferably be read from 0, 16, 32... etc., so that a relatively long data array can be read
		/// </summary>
		/// <param name="plc">PLC的通信对象</param>
		/// <param name="address">起始地址</param>
		/// <param name="length">读取的长度</param>
		/// <param name="isNewVersion">是否是新版的串口访问类</param>
		/// <returns>带成功标志的结果数据对象</returns>
		/// <example>
		///  <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\MelsecFxSerial.cs" region="ReadBool" title="Bool类型示例" />
		/// </example>
		public static OResult<bool[]> ReadBool(IReadWriteDevice plc, string address, ushort length, bool isNewVersion)
		{
			OResult<List<byte[]>, int> oResult = BuildReadBoolCommand(address, length, isNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content1.Count; i++)
			{
				OResult<byte[]> oResult2 = plc.ReadFromCoreServer(oResult.Content1[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult oResult3 = CheckPlcReadResponse(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				OResult<byte[]> oResult4 = ExtractActualData(oResult2.Content);
				if (!oResult4.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult4);
				}
				list.AddRange(oResult4.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray().ToBoolArray().SelectMiddle(oResult.Content2, length));
		}

