		/// <summary>
		/// 根据指定的地址向PLC写入bool数组，数组的长度需要为16的倍数，以及地址的偏移地址也需要是16的倍数
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="address">初始地址，支持的类型参考文档说明</param>
		/// <param name="value">bool数组值</param>
		/// <param name="isNewVersion">是否是新版的串口访问类</param>
		/// <returns>是否写入成功</returns>
		public static OResult Write(IReadWriteDevice plc, string address, bool[] value, bool isNewVersion)
		{
			if (value == null)
			{
				value = new bool[0];
			}
			if (value.Length % 16 != 0)
			{
				return new OResult(StringResources.Language.MelsecFxBoolLength16);
			}
			return Write(plc, address, value.ToByteArray(), isNewVersion);
		}

