		/// <summary>
		/// 激活PLC的接收状态，需要再和PLC交互之前进行调用，之后就需要再调用了。<br />
		/// </summary>
		/// <param name="plc">PLC通信对象</param>
		/// <returns>是否激活成功</returns>
		public static OResult ActivePlc(IReadWriteDevice plc)
		{
			OResult<byte[]> oResult = plc.ReadFromCoreServer(new byte[1] { 5 });
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content[0] != 6)
			{
				return new OResult("Send ENQ(0x05), Check Receive ACK(0x06) failed");
			}
			OResult<byte[]> oResult2 = plc.ReadFromCoreServer(new byte[11]
			{
				2, 48, 48, 69, 48, 50, 48, 50, 3, 54,
				67
			});
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return plc.ReadFromCoreServer(new byte[11]
			{
				2, 48, 48, 69, 48, 50, 48, 50, 3, 54,
				67
			});
		}

