		/// <summary>
		/// 检查PLC返回的读取数据是否是正常的
		/// </summary>
		/// <param name="ack">Plc反馈的数据信息</param>
		/// <returns>检查结果</returns>
		public static OResult CheckPlcReadResponse(byte[] ack)
		{
			if (ack.Length == 0)
			{
				return new OResult(StringResources.Language.MelsecFxReceiveZero);
			}
			if (ack[0] == 21)
			{
				return new OResult(StringResources.Language.MelsecFxAckNagative + " Actual: " + SoftBasic.ByteToHexString(ack, ' '));
			}
			if (ack[0] != 2)
			{
				return new OResult(StringResources.Language.MelsecFxAckWrong + ack[0] + " Actual: " + SoftBasic.ByteToHexString(ack, ' '));
			}
			try
			{
				if (!MelsecHelper.CheckCRC(ack))
				{
					return new OResult(StringResources.Language.MelsecFxCrcCheckFailed + " Actual: " + SoftBasic.ByteToHexString(ack, ' '));
				}
			}
			catch (Exception ex)
			{
				return new OResult(StringResources.Language.MelsecFxCrcCheckFailed + ex.Message + Environment.NewLine + "Actual: " + SoftBasic.ByteToHexString(ack, ' '));
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 检查PLC返回的写入的数据是否是正常的
		/// </summary>
		/// <param name="ack">Plc反馈的数据信息</param>
		/// <returns>检查结果</returns>
		public static OResult CheckPlcWriteResponse(byte[] ack)
		{
			if (ack.Length == 0)
			{
				return new OResult(StringResources.Language.MelsecFxReceiveZero);
			}
			if (ack[0] == 21)
			{
				return new OResult(StringResources.Language.MelsecFxAckNagative + " Actual: " + SoftBasic.ByteToHexString(ack, ' '));
			}
			if (ack[0] != 6)
			{
				return new OResult(StringResources.Language.MelsecFxAckWrong + ack[0] + " Actual: " + SoftBasic.ByteToHexString(ack, ' '));
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 生成位写入的数据报文信息，该报文可直接用于发送串口给PLC
		/// </summary>
		/// <param name="address">地址信息，每个地址存在一定的范围，需要谨慎传入数据。举例：M10,S10,X5,Y10,C10,T10</param>
		/// <param name="value"><c>True</c>或是<c>False</c></param>
		/// <returns>带报文信息的结果对象</returns>
		public static OResult<byte[]> BuildWriteBoolPacket(string address, bool value)
		{
			OResult<MelsecMcDataType, ushort> oResult = FxAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			ushort content = oResult.Content2;
			if (oResult.Content1 == MelsecMcDataType.M)
			{
				content = ((content < 8000) ? ((ushort)(content + 2048)) : ((ushort)(content - 8000 + 3840)));
			}
			else if (oResult.Content1 == MelsecMcDataType.S)
			{
				content = content;
			}
			else if (oResult.Content1 == MelsecMcDataType.X)
			{
				content += 1024;
			}
			else if (oResult.Content1 == MelsecMcDataType.Y)
			{
				content += 1280;
			}
			else if (oResult.Content1 == MelsecMcDataType.CS)
			{
				content += 448;
			}
			else if (oResult.Content1 == MelsecMcDataType.CC)
			{
				content += 960;
			}
			else if (oResult.Content1 == MelsecMcDataType.CN)
			{
				content += 3584;
			}
			else if (oResult.Content1 == MelsecMcDataType.TS)
			{
				content += 192;
			}
			else if (oResult.Content1 == MelsecMcDataType.TC)
			{
				content += 704;
			}
			else
			{
				if (oResult.Content1 != MelsecMcDataType.TN)
				{
					return new OResult<byte[]>(StringResources.Language.MelsecCurrentTypeNotSupportedBitOperate);
				}
				content += 1536;
			}
			byte[] array = new byte[9]
			{
				2,
				(byte)(value ? 55u : 56u),
				SoftBasic.BuildAsciiBytesFrom(content)[2],
				SoftBasic.BuildAsciiBytesFrom(content)[3],
				SoftBasic.BuildAsciiBytesFrom(content)[0],
				SoftBasic.BuildAsciiBytesFrom(content)[1],
				3,
				0,
				0
			};
			MelsecHelper.FxCalculateCRC(array).CopyTo(array, 7);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 根据类型地址长度确认需要读取的指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="length">长度</param>
		/// <param name="isNewVersion">是否是新版的串口访问类</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<List<byte[]>> BuildReadWordCommand(string address, ushort length, bool isNewVersion)
		{
			OResult<ushort> oResult = FxCalculateWordStartAddress(address, isNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			length *= 2;
			ushort num = oResult.Content;
			int[] array = SoftBasic.SplitIntegerToArray(length, 254);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				if (isNewVersion)
				{
					byte[] obj = new byte[13]
					{
						2, 69, 48, 48, 0, 0, 0, 0, 0, 0,
						3, 0, 0
					};
					obj[4] = SoftBasic.BuildAsciiBytesFrom(num)[0];
					obj[5] = SoftBasic.BuildAsciiBytesFrom(num)[1];
					obj[6] = SoftBasic.BuildAsciiBytesFrom(num)[2];
					obj[7] = SoftBasic.BuildAsciiBytesFrom(num)[3];
					obj[8] = SoftBasic.BuildAsciiBytesFrom((byte)array[i])[0];
					obj[9] = SoftBasic.BuildAsciiBytesFrom((byte)array[i])[1];
					byte[] array2 = obj;
					MelsecHelper.FxCalculateCRC(array2).CopyTo(array2, 11);
					list.Add(array2);
					num = (ushort)(num + array[i]);
				}
				else
				{
					byte[] obj2 = new byte[11]
					{
						2, 48, 0, 0, 0, 0, 0, 0, 3, 0,
						0
					};
					obj2[2] = SoftBasic.BuildAsciiBytesFrom(num)[0];
					obj2[3] = SoftBasic.BuildAsciiBytesFrom(num)[1];
					obj2[4] = SoftBasic.BuildAsciiBytesFrom(num)[2];
					obj2[5] = SoftBasic.BuildAsciiBytesFrom(num)[3];
					obj2[6] = SoftBasic.BuildAsciiBytesFrom((byte)array[i])[0];
					obj2[7] = SoftBasic.BuildAsciiBytesFrom((byte)array[i])[1];
					byte[] array3 = obj2;
					MelsecHelper.FxCalculateCRC(array3).CopyTo(array3, 9);
					list.Add(array3);
					num = (ushort)(num + array[i]);
				}
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 根据类型地址长度确认需要读取的指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="length">bool数组长度</param>
		/// <param name="isNewVersion">是否是新版的串口访问类</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<List<byte[]>, int> BuildReadBoolCommand(string address, ushort length, bool isNewVersion)
		{
			OResult<ushort, ushort, ushort> oResult = FxCalculateBoolStartAddress(address, isNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>, int>(oResult);
			}
			ushort integer = (ushort)SnetHelper.CalculateOccupyLength(oResult.Content2, length);
			ushort num = oResult.Content1;
			int[] array = SoftBasic.SplitIntegerToArray(integer, 254);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				if (isNewVersion)
				{
					byte[] obj = new byte[13]
					{
						2, 69, 48, 48, 0, 0, 0, 0, 0, 0,
						3, 0, 0
					};
					obj[4] = SoftBasic.BuildAsciiBytesFrom(num)[0];
					obj[5] = SoftBasic.BuildAsciiBytesFrom(num)[1];
					obj[6] = SoftBasic.BuildAsciiBytesFrom(num)[2];
					obj[7] = SoftBasic.BuildAsciiBytesFrom(num)[3];
					obj[8] = SoftBasic.BuildAsciiBytesFrom((byte)array[i])[0];
					obj[9] = SoftBasic.BuildAsciiBytesFrom((byte)array[i])[1];
					byte[] array2 = obj;
					MelsecHelper.FxCalculateCRC(array2).CopyTo(array2, 11);
					list.Add(array2);
				}
				else
				{
					byte[] obj2 = new byte[11]
					{
						2, 48, 0, 0, 0, 0, 0, 0, 3, 0,
						0
					};
					obj2[2] = SoftBasic.BuildAsciiBytesFrom(num)[0];
					obj2[3] = SoftBasic.BuildAsciiBytesFrom(num)[1];
					obj2[4] = SoftBasic.BuildAsciiBytesFrom(num)[2];
					obj2[5] = SoftBasic.BuildAsciiBytesFrom(num)[3];
					obj2[6] = SoftBasic.BuildAsciiBytesFrom((byte)array[i])[0];
					obj2[7] = SoftBasic.BuildAsciiBytesFrom((byte)array[i])[1];
					byte[] array3 = obj2;
					MelsecHelper.FxCalculateCRC(array3).CopyTo(array3, 9);
					list.Add(array3);
				}
				num = (ushort)(num + array[i]);
			}
			return OResult.CreateSuccessResult(list, (int)oResult.Content3);
		}

		/// <summary>
		/// 根据类型地址以及需要写入的数据来生成指令头
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="value">实际的数据信息</param>
		/// <param name="isNewVersion">是否是新版的串口访问类</param>
		/// <returns>带有成功标志的指令数据</returns>
		public static OResult<byte[]> BuildWriteWordCommand(string address, byte[] value, bool isNewVersion)
		{
			OResult<ushort> oResult = FxCalculateWordStartAddress(address, isNewVersion);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (value != null)
			{
				value = SoftBasic.BuildAsciiBytesFrom(value);
			}
			ushort content = oResult.Content;
			if (isNewVersion)
			{
				byte[] array = new byte[13 + value.Length];
				array[0] = 2;
				array[1] = 69;
				array[2] = 49;
				array[3] = 48;
				array[4] = SoftBasic.BuildAsciiBytesFrom(content)[0];
				array[5] = SoftBasic.BuildAsciiBytesFrom(content)[1];
				array[6] = SoftBasic.BuildAsciiBytesFrom(content)[2];
				array[7] = SoftBasic.BuildAsciiBytesFrom(content)[3];
				array[8] = SoftBasic.BuildAsciiBytesFrom((byte)(value.Length / 2))[0];
				array[9] = SoftBasic.BuildAsciiBytesFrom((byte)(value.Length / 2))[1];
				Array.Copy(value, 0, array, 10, value.Length);
				array[^3] = 3;
				MelsecHelper.FxCalculateCRC(array).CopyTo(array, array.Length - 2);
				return OResult.CreateSuccessResult(array);
			}
			byte[] array2 = new byte[11 + value.Length];
			array2[0] = 2;
			array2[1] = 49;
			array2[2] = SoftBasic.BuildAsciiBytesFrom(content)[0];
			array2[3] = SoftBasic.BuildAsciiBytesFrom(content)[1];
			array2[4] = SoftBasic.BuildAsciiBytesFrom(content)[2];
			array2[5] = SoftBasic.BuildAsciiBytesFrom(content)[3];
			array2[6] = SoftBasic.BuildAsciiBytesFrom((byte)(value.Length / 2))[0];
			array2[7] = SoftBasic.BuildAsciiBytesFrom((byte)(value.Length / 2))[1];
			Array.Copy(value, 0, array2, 8, value.Length);
			array2[^3] = 3;
			MelsecHelper.FxCalculateCRC(array2).CopyTo(array2, array2.Length - 2);
			return OResult.CreateSuccessResult(array2);
		}

		/// <summary>
		/// 从PLC反馈的数据进行提炼操作
		/// </summary>
		/// <param name="response">PLC反馈的真实数据</param>
		/// <returns>数据提炼后的真实数据</returns>
		public static OResult<byte[]> ExtractActualData(byte[] response)
		{
			try
			{
				byte[] array = new byte[(response.Length - 4) / 2];
				for (int i = 0; i < array.Length; i++)
				{
					byte[] bytes = new byte[2]
					{
						response[i * 2 + 1],
						response[i * 2 + 2]
					};
					array[i] = Convert.ToByte(Encoding.ASCII.GetString(bytes), 16);
				}
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				OResult<byte[]> oResult = new OResult<byte[]>();
				oResult.Message = "Extract Msg：" + ex.Message + Environment.NewLine + "Data: " + SoftBasic.ByteToHexString(response);
				return oResult;
			}
		}

		/// <summary>
		/// 从PLC反馈的数据进行提炼bool数组操作
		/// </summary>
		/// <param name="response">PLC反馈的真实数据</param>
		/// <param name="start">起始提取的点信息</param>
		/// <param name="length">bool数组的长度</param>
		/// <returns>数据提炼后的真实数据</returns>
		public static OResult<bool[]> ExtractActualBoolData(byte[] response, int start, int length)
		{
			OResult<byte[]> oResult = ExtractActualData(response);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			try
			{
				bool[] array = new bool[length];
				bool[] array2 = SoftBasic.ByteToBoolArray(oResult.Content, oResult.Content.Length * 8);
				for (int i = 0; i < length; i++)
				{
					array[i] = array2[i + start];
				}
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				OResult<bool[]> oResult2 = new OResult<bool[]>();
				oResult2.Message = "Extract Msg：" + ex.Message + Environment.NewLine + "Data: " + SoftBasic.ByteToHexString(response);
				return oResult2;
			}
		}

		/// <summary>
		/// 解析数据地址成不同的三菱地址类型
		/// </summary>
		/// <param name="address">数据地址</param>
		/// <returns>地址结果对象</returns>
		public static OResult<MelsecMcDataType, ushort> FxAnalysisAddress(string address)
		{
			OResult<MelsecMcDataType, ushort> oResult = new OResult<MelsecMcDataType, ushort>();
			try
			{
				switch (address[0])
				{
				case 'M':
				case 'm':
					oResult.Content1 = MelsecMcDataType.M;
					oResult.Content2 = Convert.ToUInt16(address.Substring(1), MelsecMcDataType.M.FromBase);
					break;
				case 'X':
				case 'x':
					oResult.Content1 = MelsecMcDataType.X;
					oResult.Content2 = Convert.ToUInt16(address.Substring(1), 8);
					break;
				case 'Y':
				case 'y':
					oResult.Content1 = MelsecMcDataType.Y;
					oResult.Content2 = Convert.ToUInt16(address.Substring(1), 8);
					break;
				case 'D':
				case 'd':
					oResult.Content1 = MelsecMcDataType.D;
					oResult.Content2 = Convert.ToUInt16(address.Substring(1), MelsecMcDataType.D.FromBase);
					break;
				case 'S':
				case 's':
					oResult.Content1 = MelsecMcDataType.S;
					oResult.Content2 = Convert.ToUInt16(address.Substring(1), MelsecMcDataType.S.FromBase);
					break;
				case 'T':
				case 't':
					if (address[1] == 'N' || address[1] == 'n')
					{
						oResult.Content1 = MelsecMcDataType.TN;
						oResult.Content2 = Convert.ToUInt16(address.Substring(2), MelsecMcDataType.TN.FromBase);
						break;
					}
					if (address[1] == 'S' || address[1] == 's')
					{
						oResult.Content1 = MelsecMcDataType.TS;
						oResult.Content2 = Convert.ToUInt16(address.Substring(2), MelsecMcDataType.TS.FromBase);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						oResult.Content1 = MelsecMcDataType.TC;
						oResult.Content2 = Convert.ToUInt16(address.Substring(2), MelsecMcDataType.TC.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'C':
				case 'c':
					if (address[1] == 'N' || address[1] == 'n')
					{
						oResult.Content1 = MelsecMcDataType.CN;
						oResult.Content2 = Convert.ToUInt16(address.Substring(2), MelsecMcDataType.CN.FromBase);
						break;
					}
					if (address[1] == 'S' || address[1] == 's')
					{
						oResult.Content1 = MelsecMcDataType.CS;
						oResult.Content2 = Convert.ToUInt16(address.Substring(2), MelsecMcDataType.CS.FromBase);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						oResult.Content1 = MelsecMcDataType.CC;
						oResult.Content2 = Convert.ToUInt16(address.Substring(2), MelsecMcDataType.CC.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
			oResult.IsSuccess = true;
			return oResult;
		}

		/// <summary>
		/// 判断是否是位地址信息
		/// </summary>
		/// <param name="dataType"></param>
		/// <returns></returns>
		private static bool CheckAddressBool(MelsecMcDataType dataType)
		{
			if (dataType != MelsecMcDataType.X && dataType != MelsecMcDataType.Y && dataType != MelsecMcDataType.M && dataType != MelsecMcDataType.S && dataType != MelsecMcDataType.CS && dataType != MelsecMcDataType.CC && dataType != MelsecMcDataType.TS)
			{
				return dataType == MelsecMcDataType.TC;
			}
			return true;
		}

		private static ushort CalculateBoolStartAddress(MelsecMcDataType dataType, ushort startAddress, bool isNewVersion)
		{
			if (dataType == MelsecMcDataType.M)
			{
				startAddress = ((!isNewVersion) ? ((startAddress < 8000) ? ((ushort)(startAddress / 8 + 256)) : ((ushort)((startAddress - 8000) / 8 + 480))) : ((startAddress < 8000) ? ((ushort)(startAddress / 8 + 34816)) : ((ushort)((startAddress - 8000) / 8 + 35840))));
			}
			else if (dataType == MelsecMcDataType.X)
			{
				startAddress = (ushort)(startAddress / 8 + (isNewVersion ? 36000 : 128));
			}
			else if (dataType == MelsecMcDataType.Y)
			{
				startAddress = (ushort)(startAddress / 8 + (isNewVersion ? 35776 : 160));
			}
			else if (dataType == MelsecMcDataType.S)
			{
				startAddress = (ushort)(startAddress / 8 + (isNewVersion ? 36064 : 0));
			}
			else if (dataType == MelsecMcDataType.CS)
			{
				startAddress = (ushort)(startAddress / 8 + (isNewVersion ? 37696 : 448));
			}
			else if (dataType == MelsecMcDataType.CC)
			{
				startAddress = (ushort)(startAddress / 8 + (isNewVersion ? 37600 : 960));
			}
			else if (dataType == MelsecMcDataType.TS)
			{
				startAddress = (ushort)(startAddress / 8 + (isNewVersion ? 37728 : 192));
			}
			else if (dataType == MelsecMcDataType.TC)
			{
				startAddress = (ushort)(startAddress / 8 + (isNewVersion ? 37632 : 704));
			}
			return startAddress;
		}

		/// <summary>
		/// 返回读取的地址及长度信息
		/// </summary>
		/// <param name="address">读取的地址信息</param>
		/// <param name="isNewVersion">是否是新版的串口访问类</param>
		/// <returns>带起始地址的结果对象</returns>
		internal static OResult<ushort> FxCalculateWordStartAddress(string address, bool isNewVersion)
		{
			OResult<MelsecMcDataType, ushort> oResult = FxAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<ushort>(oResult);
			}
			ushort content = oResult.Content2;
			if (oResult.Content1 == MelsecMcDataType.D)
			{
				content = ((content >= 8000) ? ((ushort)((content - 8000) * 2 + (isNewVersion ? 32768 : 3584))) : (isNewVersion ? ((ushort)(content * 2 + 16384)) : ((ushort)(content * 2 + 4096))));
			}
			else if (oResult.Content1 == MelsecMcDataType.CN)
			{
				content = ((content < 200) ? ((ushort)(content * 2 + 2560)) : ((ushort)((content - 200) * 4 + 3072)));
			}
			else
			{
				if (oResult.Content1 != MelsecMcDataType.TN)
				{
					if (CheckAddressBool(oResult.Content1))
					{
						if (oResult.Content2 % 16 != 0)
						{
							return new OResult<ushort>(StringResources.Language.MelsecFxAddressStartWith16);
						}
						return OResult.CreateSuccessResult(CalculateBoolStartAddress(oResult.Content1, content, isNewVersion));
					}
					return new OResult<ushort>(StringResources.Language.MelsecCurrentTypeNotSupportedWordOperate);
				}
				content = ((!isNewVersion) ? ((ushort)(content * 2 + 2048)) : ((ushort)(content * 2 + 4096)));
			}
			return OResult.CreateSuccessResult(content);
		}

		/// <summary>
		/// 返回读取的实际的字节地址，相对位置，以及当前的位偏置信息
		/// </summary><param name="address">读取的地址信息</param>
		/// <param name="isNewVersion">是否是新版的串口访问类</param>
		/// <returns>带起始地址的结果对象</returns>
		public static OResult<ushort, ushort, ushort> FxCalculateBoolStartAddress(string address, bool isNewVersion)
		{
			OResult<MelsecMcDataType, ushort> oResult = FxAnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<ushort, ushort, ushort>(oResult);
			}
			ushort content = oResult.Content2;
			if (CheckAddressBool(oResult.Content1))
			{
				content = CalculateBoolStartAddress(oResult.Content1, content, isNewVersion);
				return OResult.CreateSuccessResult(content, oResult.Content2, (ushort)(oResult.Content2 % 8));
			}
			return new OResult<ushort, ushort, ushort>(StringResources.Language.MelsecCurrentTypeNotSupportedBitOperate);
		}
	}
}
namespace Snet.Driver.Profinet.MegMeet
{
	/// <summary>
	/// 麦格米特PLC的辅助方法
	/// </summary>
	public class MegMeetHelper
	{
		/// <summary>
		///
		/// </summary>
		/// <param name="address"></param>
		/// <param name="modbusCode"></param>
		/// <returns></returns>
		public static OResult<string> PraseMegMeetAddress(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWithAndNumber("X"))
					{
						return OResult.CreateSuccessResult(text + "x=2;" + Convert.ToInt32(address.Substring(1), 8));
					}
					if (address.StartsWithAndNumber("Y"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1), 8));
					}
					if (address.StartsWithAndNumber("M"))
					{
						int num = Convert.ToInt32(address.Substring(1));
						if (num < 2048)
						{
							return OResult.CreateSuccessResult(text + (num + 2000));
						}
						return OResult.CreateSuccessResult(text + (num - 2048 + 12000));
					}
					if (address.StartsWithAndNumber("SM"))
					{
						int num2 = Convert.ToInt32(address.Substring(2));
						if (num2 < 256)
						{
							return OResult.CreateSuccessResult(text + (num2 + 4400));
						}
						return OResult.CreateSuccessResult(text + (num2 - 256 + 30000));
					}
					if (address.StartsWithAndNumber("S"))
					{
						int num3 = Convert.ToInt32(address.Substring(1));
						if (num3 < 1024)
						{
							return OResult.CreateSuccessResult(text + (num3 + 6000));
						}
						return OResult.CreateSuccessResult(text + (num3 - 1024 + 31000));
					}
					if (address.StartsWithAndNumber("T"))
					{
						int num4 = Convert.ToInt32(address.Substring(1));
						if (num4 < 256)
						{
							return OResult.CreateSuccessResult(text + (num4 + 8000));
						}
						return OResult.CreateSuccessResult(text + (num4 - 256 + 11000));
					}
					if (address.StartsWithAndNumber("C"))
					{
						int num5 = Convert.ToInt32(address.Substring(1));
						if (num5 < 256)
						{
							return OResult.CreateSuccessResult(text + (num5 + 9200));
						}
						return OResult.CreateSuccessResult(text + (num5 - 256 + 10000));
					}
					if (ModbusHelper.TransPointAddressToModbus(text, address, new string[2] { "D", "R" }, new int[2] { 0, 13000 }, out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
				}
				else
				{
					if (address.StartsWithAndNumber("T"))
					{
						int num6 = Convert.ToInt32(address.Substring(1));
						if (num6 < 256)
						{
							return OResult.CreateSuccessResult(text + (num6 + 9000));
						}
						return OResult.CreateSuccessResult(text + (num6 - 256 + 11000));
					}
					if (address.StartsWithAndNumber("C"))
					{
						int num7 = Convert.ToInt32(address.Substring(1));
						if (num7 < 200)
						{
							return OResult.CreateSuccessResult(text + (num7 + 9500));
						}
						if (num7 < 256)
						{
							return OResult.CreateSuccessResult(text + (num7 * 2 - 200 + 9700));
						}
						return OResult.CreateSuccessResult(text + (num7 * 2 - 256 + 10000));
					}
					if (address.StartsWithAndNumber("D"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWithAndNumber("SD"))
					{
						int num8 = Convert.ToInt32(address.Substring(2));
						if (num8 < 256)
						{
							return OResult.CreateSuccessResult(text + (num8 + 8000));
						}
						return OResult.CreateSuccessResult(text + (num8 - 256 + 12000));
					}
					if (address.StartsWithAndNumber("Z"))
					{
						int num9 = Convert.ToInt32(address.Substring(1));
						return OResult.CreateSuccessResult(text + (num9 + 8500));
					}
					if (address.StartsWithAndNumber("R"))
					{
						int num10 = Convert.ToInt32(address.Substring(1));
						return OResult.CreateSuccessResult(text + (num10 + 13000));
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}

		private static List<CuttingAddress> GetBoolCuttingAddress()
		{
			return new List<CuttingAddress>
			{
				new CuttingAddress("M", 2048),
				new CuttingAddress("SM", 256),
				new CuttingAddress("S", 1024),
				new CuttingAddress("T", 256),
				new CuttingAddress("C", 256)
			};
		}

		private static List<CuttingAddress> GetWordCuttingAddress()
		{
			return new List<CuttingAddress>
			{
				new CuttingAddress("SD", 256),
				new CuttingAddress("T", 256),
				new CuttingAddress("C", 256)
			};
		}

		internal static OResult<bool[]> ReadBool(Func<string, ushort, OResult<bool[]>> readBoolFunc, string address, ushort length)
		{
			return SnetHelper.ReadCuttingHelper(readBoolFunc, GetBoolCuttingAddress(), address, length);
		}

		internal static async Task<OResult<bool[]>> ReadBoolAsync(Func<string, ushort, Task<OResult<bool[]>>> readBoolFunc, string address, ushort length)
		{
			return await SnetHelper.ReadCuttingAsyncHelper(readBoolFunc, GetBoolCuttingAddress(), address, length);
		}

		internal static OResult<byte[]> Read(Func<string, ushort, OResult<byte[]>> readFunc, string address, ushort length)
		{
			return SnetHelper.ReadCuttingHelper(readFunc, GetWordCuttingAddress(), address, length);
		}

		internal static async Task<OResult<byte[]>> ReadAsync(Func<string, ushort, Task<OResult<byte[]>>> readFunc, string address, ushort length)
		{
			return await SnetHelper.ReadCuttingAsyncHelper(readFunc, GetWordCuttingAddress(), address, length);
		}
	}
	/// <summary>
	/// 深圳麦格米特PLC的通信对象，基于ModbusRtu协议实现，适用机型为 MC80/MC100/MC200/MC280/MC200E，具体支持的地址及范围参见API文档：http://api.Snetcommunication.cn<br />
	/// The communication object of Shenzhen MegMeet PLC is based on the ModbusRtu, and the applicable model is MC80/MC100/MC200/MC280/MC200E, 
	/// and the specific supported address and range are described in API document: http://api.Snetcommunication.cn
	/// </summary>
	/// <remarks>
	/// 位读写地址支持：X,Y,M,SM,S,T,C，字读写地址为：D,SD,Z,R,T,C，期中 C200以上使用int/uint类型进行读写操作
	/// </remarks>
	public class MegMeetSerial : ModbusRtu
	{
		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public MegMeetSerial()
		{
			base.DataFormat = DataFormat.CDAB;
		}

		/// <summary>
		/// 指定客户端自己的站号来初始化<br />
		/// Specify the server address, port number, and client's own station number to initialize
		/// </summary>
		/// <param name="station">客户端自身的站号</param>
		public MegMeetSerial(byte station = 1)
			: base(station)
		{
			base.DataFormat = DataFormat.CDAB;
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			return MegMeetHelper.ReadBool(base.ReadBool, address, length);
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			return MegMeetHelper.Read(base.Read, address, length);
