		/// <summary>
		/// GetAddressOfU IX0.0.0 QX0.0.0
		/// </summary>
		/// <param name="Address"></param>
		/// <param name="IsWrite"></param>
		/// <returns></returns>
		public static string GetAddressOfU_Q_I(string Address, bool IsWrite = false)
		{
			string[] array = Address.Split('.');
			object obj = 0;
			if (array.Length >= 3)
			{
				int num = Convert.ToInt32(array[2].Last().ToString(), 16);
				obj = ((!(IsHex(array[2]) & IsWrite)) ? ((object)((int.Parse(array[0]) * 32 + int.Parse(array[1])) * 10 + num)) : (int.Parse(array[0]) * 32 + int.Parse(array[1]) + array[2]));
			}
			else
			{
				obj = int.Parse(array[0]) * 32 + int.Parse(array[1]);
			}
			return $"{obj}";
		}

		/// <summary>
		/// GetAddressOfBitTo_XGK  MX1.0  DX1.0 to PLC LS XGK
		/// </summary>
		/// <param name="address"></param>
		/// <param name="startIndex"></param>
		/// <param name="IsWrite"></param>
		/// <returns></returns>
		public static string GetAddressOfBitTo_XGK(string address, int startIndex, bool IsWrite = false)
		{
			string text = address.Substring(startIndex);
			if (text.IndexOf('.') < 0)
			{
				if (IsWrite)
				{
					return text;
				}
				int num = 0;
				string value = text.Substring(0, text.Length - 1);
				string text2 = text.Substring(text.Length - 1);
				num = ((!text2.Contains(new string[6] { "A", "B", "C", "D", "E", "F" })) ? Convert.ToInt32(text2) : Convert.ToInt32(text2, 16));
				return $"{Convert.ToInt32(value) * 16 + num}";
			}
			string[] array = text.Split('.');
			int bitIndexInformation = SnetHelper.GetBitIndexInformation(ref address);
			if (IsHex(array[1]) & IsWrite)
			{
				return address.Substring(2) + bitIndexInformation.ToString("X1");
			}
			return $"{Convert.ToInt32(array[0]) * 16 + bitIndexInformation}";
		}

		/// <summary>
		/// NumberStyles HexNumber
		/// </summary>
		/// <param name="value"></param>
		/// <returns></returns>
		public static bool IsHex(string value)
		{
			if (string.IsNullOrEmpty(value))
			{
				return false;
			}
			bool result = false;
			for (int i = 0; i < value.Length; i++)
			{
				switch (value[i])
				{
				case 'A':
				case 'B':
				case 'C':
				case 'D':
				case 'E':
				case 'F':
				case 'a':
				case 'b':
				case 'c':
				case 'd':
				case 'e':
				case 'f':
					result = true;
					break;
				}
			}
			return result;
		}

		/// <summary>
		/// AnalysisAddress
		/// </summary>
		/// <param name="address">start address</param>
		/// <param name="IsWrite"></param>
		/// <returns>analysis result</returns>
		public static OResult<string> AnalysisAddress(string address, bool IsWrite = false)
		{
			bool flag = false;
			StringBuilder stringBuilder = new StringBuilder();
			try
			{
				stringBuilder.Append("%");
				if (address.IndexOf('.') > 0)
				{
					flag = true;
				}
				bool flag2 = false;
				for (int i = 0; i < "PMLKFTCDSQINUZR".Length; i++)
				{
					if ("PMLKFTCDSQINUZR"[i] != address[0])
					{
						continue;
					}
					stringBuilder.Append("PMLKFTCDSQINUZR"[i]);
					if (address[1] == 'X')
					{
						stringBuilder.Append("X");
						if (flag)
						{
							if (address[0] != 'U' || address[0] != 'I' || address[0] != 'Q')
							{
								int bitIndexInformation = SnetHelper.GetBitIndexInformation(ref address);
								stringBuilder.Append(address.Substring(2));
								stringBuilder.Append(bitIndexInformation.ToString("X1"));
							}
							else
							{
								stringBuilder.Append(GetAddressOfU_Q_I(address.Substring(2), IsWrite));
							}
						}
						else
						{
							stringBuilder.Append(address.Substring(2));
						}
					}
					else
					{
						string value = string.Empty;
						if (address[1] == 'B')
						{
							stringBuilder.Append(flag ? "X" : "B");
							if (!flag)
							{
								value = ((address[0] != 'I' && address[0] != 'Q') ? $"{Convert.ToInt32(address.Substring(2))}" : address.Substring(2));
							}
							else if (address[0] != 'U' || address[0] != 'I' || address[0] != 'Q')
							{
								int bitIndexInformation2 = SnetHelper.GetBitIndexInformation(ref address);
								stringBuilder.Append(address.Substring(2));
								stringBuilder.Append(bitIndexInformation2.ToString("X1"));
							}
							else
							{
								stringBuilder.Append(GetAddressOfU_Q_I(address.Substring(2)));
							}
							stringBuilder.Append(value);
						}
						else if (address[1] == 'W')
						{
							stringBuilder.Append(flag ? "X" : "W");
							if (!flag)
							{
								value = ((address[0] != 'I' && address[0] != 'Q') ? $"{Convert.ToInt32(address.Substring(2)) * 2}" : address.Substring(2));
							}
							else if (address[0] != 'U' || address[0] != 'I' || address[0] != 'Q')
							{
								int bitIndexInformation3 = SnetHelper.GetBitIndexInformation(ref address);
								stringBuilder.Append(address.Substring(2));
								stringBuilder.Append(bitIndexInformation3.ToString("X1"));
							}
							else
							{
								stringBuilder.Append(GetAddressOfU_Q_I(address.Substring(2)));
							}
							stringBuilder.Append(value);
						}
						else if (address[1] == 'D')
						{
							stringBuilder.Append(flag ? "X" : "D");
							if (flag)
							{
								if (address[0] != 'U' || address[0] != 'I' || address[0] != 'Q')
								{
									int bitIndexInformation4 = SnetHelper.GetBitIndexInformation(ref address);
									stringBuilder.Append(address.Substring(2));
									stringBuilder.Append(bitIndexInformation4.ToString("X1"));
								}
								else
								{
									stringBuilder.Append(GetAddressOfU_Q_I(address.Substring(2)));
								}
							}
							else if (address[0] == 'I' || address[0] == 'Q')
							{
								stringBuilder.Append(address.Substring(2));
							}
							else
							{
								value = $"{Convert.ToInt32(address.Substring(2)) * 4}";
								stringBuilder.Append(value);
							}
						}
						else if (address[1] == 'L')
						{
							stringBuilder.Append(flag ? "X" : "L");
							if (flag)
							{
								if (address[0] != 'U' || address[0] != 'I' || address[0] != 'Q')
								{
									int bitIndexInformation5 = SnetHelper.GetBitIndexInformation(ref address);
									stringBuilder.Append(address.Substring(2));
									stringBuilder.Append(bitIndexInformation5.ToString("X1"));
								}
								else
								{
									stringBuilder.Append(GetAddressOfU_Q_I(address.Substring(2)));
								}
							}
							else if (address[0] == 'I' || address[0] == 'Q')
							{
								stringBuilder.Append(address.Substring(2));
							}
							else
							{
								value = $"{Convert.ToInt32(address.Substring(2)) * 8}";
								stringBuilder.Append(value);
							}
						}
						else
						{
							stringBuilder.Append(flag ? "X" : "B");
							if (flag)
							{
								if (address[0] != 'U' || address[0] != 'I' || address[0] != 'Q')
								{
									int bitIndexInformation6 = SnetHelper.GetBitIndexInformation(ref address);
									stringBuilder.Append(address.Substring(1));
									stringBuilder.Append(bitIndexInformation6.ToString("X1"));
								}
								else
								{
									stringBuilder.Append(GetAddressOfU_Q_I(address.Substring(1)));
								}
							}
							else if (address[0] == 'I' || address[0] == 'Q')
							{
								stringBuilder.Append(address.Substring(1));
							}
							else if (IsHex(address.Substring(1)))
							{
								stringBuilder.Append(address.Substring(1));
							}
							else
							{
								StringBuilder stringBuilder2 = stringBuilder;
								StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(0, 1, stringBuilder2);
								handler.AppendFormatted(Convert.ToInt32(address.Substring(1)) * 2);
								stringBuilder2.Append(ref handler);
							}
						}
					}
					flag2 = true;
					break;
				}
				if (!flag2)
				{
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
			return OResult.CreateSuccessResult(stringBuilder.ToString());
		}

		/// <summary>
		/// Get DataType to Address
		/// </summary>
		/// <param name="address">address</param>
		/// <returns>dataType</returns>
		public static OResult<string> GetDataTypeToAddress(string address)
		{
			string value = string.Empty;
			try
			{
				bool flag = false;
				for (int i = 0; i < "PMLKFTCDSQINUZR".Length; i++)
				{
					if ("PMLKFTCDSQINUZR"[i] == address[0])
					{
						value = ((address[1] == 'X') ? "Bit" : ((address[1] == 'W') ? "Word" : ((address[1] == 'D') ? "DWord" : ((address[1] == 'L') ? "LWord" : ((address[1] == 'B') ? "Continuous" : ((address.IndexOf('.') <= 0) ? "Continuous" : "Bit"))))));
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
			return OResult.CreateSuccessResult(value);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.LSIS.LSFastEnet.BuildReadIndividualCommand(System.Byte,System.String[])" />
		public static OResult<byte[]> BuildReadIndividualCommand(byte dataType, string address)
		{
			return BuildReadIndividualCommand(dataType, new string[1] { address });
		}

		/// <summary>
		/// Multi reading address Type of Read Individual
		/// </summary>
		/// <param name="dataType">dataType bit:0x04, byte:0x01, word:0x02, dword:0x03, lword:0x04, continuous:0x14</param>
		/// <param name="addresses">address, for example: MX100, PX100</param>
		/// <returns>Read Individual Command</returns>
		public static OResult<byte[]> BuildReadIndividualCommand(byte dataType, string[] addresses)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(84);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(dataType);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte((byte)addresses.Length);
			memoryStream.WriteByte(0);
			for (int i = 0; i < addresses.Length; i++)
			{
				OResult<string> oResult = AnalysisAddress(addresses[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				memoryStream.WriteByte((byte)oResult.Content.Length);
				memoryStream.WriteByte(0);
				byte[] bytes = Encoding.ASCII.GetBytes(oResult.Content);
				memoryStream.Write(bytes, 0, bytes.Length);
			}
			return OResult.CreateSuccessResult(memoryStream.ToArray());
		}

		private static OResult<byte[]> BuildReadByteCommand(string address, ushort length)
		{
			OResult<string> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<string> dataTypeToAddress = GetDataTypeToAddress(address);
			if (!dataTypeToAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataTypeToAddress);
			}
			byte[] array = new byte[12 + oResult.Content.Length];
			array[0] = 84;
			array[1] = 0;
			switch (dataTypeToAddress.Content)
			{
			case "Bit":
				array[2] = 0;
				break;
			case "Byte":
				array[2] = 1;
				break;
			case "Word":
				array[2] = 2;
				break;
			case "DWord":
				array[2] = 3;
				break;
			case "LWord":
				array[2] = 4;
				break;
			case "Continuous":
				array[2] = 20;
				break;
			}
			array[3] = 0;
			array[4] = 0;
			array[5] = 0;
			array[6] = 1;
			array[7] = 0;
			array[8] = (byte)oResult.Content.Length;
			array[9] = 0;
			Encoding.ASCII.GetBytes(oResult.Content).CopyTo(array, 10);
			BitConverter.GetBytes(length).CopyTo(array, array.Length - 2);
			return OResult.CreateSuccessResult(array);
		}

		private OResult<byte[]> BuildWriteByteCommand(string address, byte[] data)
		{
			OResult<string> oResult = AnalysisAddress(address, IsWrite: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<string> dataTypeToAddress = GetDataTypeToAddress(address);
			if (!dataTypeToAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataTypeToAddress);
			}
			byte[] array = new byte[12 + oResult.Content.Length + data.Length];
			switch (dataTypeToAddress.Content)
			{
			case "Bit":
				array[2] = 0;
				break;
			case "Byte":
				array[2] = 1;
				break;
			case "Word":
				array[2] = 2;
				break;
			case "DWord":
				array[2] = 3;
				break;
			case "LWord":
				array[2] = 4;
				break;
			case "Continuous":
				array[2] = 20;
				break;
			}
			array[0] = 88;
			array[1] = 0;
			array[3] = 0;
			array[4] = 0;
			array[5] = 0;
			array[6] = 1;
			array[7] = 0;
			array[8] = (byte)oResult.Content.Length;
			array[9] = 0;
			Encoding.ASCII.GetBytes(oResult.Content).CopyTo(array, 10);
			BitConverter.GetBytes(data.Length).CopyTo(array, array.Length - 2 - data.Length);
			data.CopyTo(array, array.Length - data.Length);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// Returns true data content, supports read and write returns
		/// </summary>
		/// <param name="response">response data</param>
		/// <returns>real data</returns>
		public OResult<byte[]> ExtractActualData(byte[] response)
		{
			if (response.Length < 20)
			{
				return new OResult<byte[]>("Length is less than 20:" + SoftBasic.ByteToHexString(response));
			}
			try
			{
				ushort num = BitConverter.ToUInt16(response, 10);
				BitArray bitArray = new BitArray(BitConverter.GetBytes(num));
				_ = num % 32;
				switch (num % 32)
				{
				case 1:
					CpuType = "XGK/R-CPUH";
					break;
				case 2:
					CpuType = "XGB/XBCU";
					break;
				case 4:
					CpuType = "XGK-CPUE";
					break;
				case 5:
					CpuType = "XGK/R-CPUH";
					break;
				}
				CpuError = bitArray[7];
				if (bitArray[8])
				{
					LSCpuStatus = LSCpuStatus.RUN;
				}
				if (bitArray[9])
				{
					LSCpuStatus = LSCpuStatus.STOP;
				}
				if (bitArray[10])
				{
					LSCpuStatus = LSCpuStatus.ERROR;
				}
				if (bitArray[11])
				{
					LSCpuStatus = LSCpuStatus.DEBUG;
				}
				if (response.Length < 28)
				{
					return new OResult<byte[]>("Length is less than 28:" + SoftBasic.ByteToHexString(response));
				}
				if (BitConverter.ToUInt16(response, 26) > 0 && response.Length > 28)
				{
					return new OResult<byte[]>(response[28], "Error:" + GetErrorDesciption(response[28]));
				}
				if (response[20] == 89)
				{
					return OResult.CreateSuccessResult(new byte[0]);
				}
				if (response[20] == 85)
				{
					try
					{
						ushort num2 = BitConverter.ToUInt16(response, 30);
						byte[] array = new byte[num2];
						Array.Copy(response, 32, array, 0, num2);
						return OResult.CreateSuccessResult(array);
					}
					catch (Exception ex)
					{
						return new OResult<byte[]>(ex.Message);
					}
				}
				return new OResult<byte[]>(StringResources.Language.NotSupportedFunction);
			}
			catch (Exception ex2)
			{
				return new OResult<byte[]>("ExtractActualData failed: " + ex2.Message + " Souce: " + response.ToHexString(' '));
			}
		}

		/// <summary>
		/// get the description of the error code meanning
		/// </summary>
		/// <param name="code">code value</param>
		/// <returns>string information</returns>
		public static string GetErrorDesciption(byte code)
		{
			return code switch
			{
				0 => "Normal", 
				1 => "Physical layer error (TX, RX unavailable)", 
				3 => "There is no identifier of Function Block to receive in communication channel", 
				4 => "Mismatch of data type", 
				5 => "Reset is received from partner station", 
				6 => "Communication instruction of partner station is not ready status", 
				7 => "Device status of remote station is not desirable status", 
				8 => "Access to some target is not available", 
				9 => "Can’ t deal with communication instruction of partner station by too many reception", 
				10 => "Time Out error", 
				11 => "Structure error", 
				12 => "Abort", 
				13 => "Reject(local/remote)", 
				14 => "Communication channel establishment error (Connect/Disconnect)", 
				15 => "High speed communication and connection service error", 
				33 => "Can’t find variable identifier", 
				34 => "Address error", 
				50 => "Response error", 
				113 => "Object Access Unsupported", 
				187 => "Unknown error code (communication code of other company) is received", 
				_ => "Unknown error", 
			};
		}
	}
