		/// <inheritdoc cref="M:Snet.Driver.Profinet.LSIS.LSFastEnet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<string> oResult = AnalysisAddressToByteUnit(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			int index = int.Parse(oResult.Content.Substring(1));
			return oResult.Content[0] switch
			{
				'P' => OResult.CreateSuccessResult(pBuffer.GetBytes(index, length)), 
				'Q' => OResult.CreateSuccessResult(qBuffer.GetBytes(index, length)), 
				'M' => OResult.CreateSuccessResult(mBuffer.GetBytes(index, length)), 
				'I' => OResult.CreateSuccessResult(iBuffer.GetBytes(index, length)), 
				'U' => OResult.CreateSuccessResult(uBuffer.GetBytes(index, length)), 
				'D' => OResult.CreateSuccessResult(dBuffer.GetBytes(index, length)), 
				'T' => OResult.CreateSuccessResult(tBuffer.GetBytes(index, length)), 
				_ => new OResult<byte[]>(StringResources.Language.NotSupportedDataType), 
			};
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.LSIS.LSFastEnet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<string> oResult = AnalysisAddressToByteUnit(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			int destIndex = int.Parse(oResult.Content.Substring(1));
			switch (oResult.Content[0])
			{
			case 'P':
				pBuffer.SetBytes(value, destIndex);
				break;
			case 'Q':
				qBuffer.SetBytes(value, destIndex);
				break;
			case 'M':
				mBuffer.SetBytes(value, destIndex);
				break;
			case 'I':
				iBuffer.SetBytes(value, destIndex);
				break;
			case 'U':
				uBuffer.SetBytes(value, destIndex);
				break;
			case 'D':
				dBuffer.SetBytes(value, destIndex);
				break;
			case 'T':
				tBuffer.SetBytes(value, destIndex);
				break;
			default:
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
			}
			return OResult.CreateSuccessResult();
		}

