		public static OResult<byte[]> BuildWriteOneCommand(byte station, string address, byte[] value)
		{
			OResult<string> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			list.Add(5);
			list.AddRange(SoftBasic.BuildAsciiBytesFrom(station));
			list.Add(119);
			list.Add(83);
			list.Add(83);
			list.Add(48);
			list.Add(49);
			list.AddRange(SoftBasic.BuildAsciiBytesFrom((byte)oResult.Content.Length));
			list.AddRange(Encoding.ASCII.GetBytes(oResult.Content));
			list.AddRange(SoftBasic.BytesToAsciiBytes(value));
			list.Add(4);
