		/// build read command. 
		/// </summary>
		/// <param name="station">station</param>
		/// <param name="address">start address</param>
		/// <param name="length">address length</param>
		/// <returns> command</returns>
		public static OResult<byte[]> BuildReadCommand(byte station, string address, ushort length)
		{
			return BuildReadByteCommand(station, address, length);
		}

		/// <summary>
		/// write data to address  Type of ReadByte
		/// </summary>
		/// <param name="station">plc station</param>
		/// <param name="address">address, for example: M100, D100, DW100</param>
		/// <param name="value">source value</param>
		/// <returns>command bytes</returns>
		public static OResult<byte[]> BuildWriteByteCommand(byte station, string address, byte[] value)
		{
			OResult<string> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			string text = new string(new char[60]);
			ushort num = 0;
			float[] array = new float[3];
			char[] array2 = new char[4];
			short num2 = BitConverter.ToInt16(value, 0);
			int dataType = GetDataType(oResult.Content);
			int memoryType = GetMemoryType(oResult.Content);
			int num3 = int.Parse(oResult.Content.Substring(2, oResult.Content.Length - 2));
			if (memoryType == 128)
			{
				Console.WriteLine("Memory Type Input Error. Memory Type = P, M, K, T, C, U, Z, S, L, N, D, R, ZR", num3);
			}
			else
			{
				list.Clear();
				list.Add(2);
				list.AddRange(Encoding.ASCII.GetBytes(sprintf("w%C", select_data_code(memoryType))));
				if (text != null)
				{
					list.AddRange(Encoding.ASCII.GetBytes($"{GetDataSize((ushort)Convert.ToInt32(num3), 2):X2}{0:X2}"));
				}
				list.AddRange(Encoding.ASCII.GetBytes($"{0:X2}"));
				list.AddRange(Encoding.ASCII.GetBytes($"{(byte)GetDataSize2(num3, 1, dataType):X2}"));
				int num4;
				switch (dataType)
				{
				case 1:
					list.AddRange(Encoding.ASCII.GetBytes($"{(byte)num2:X2}"));
					num4 = 13;
					break;
				case 3:
				{
					short value2 = (short)((ulong)num2 >> 16);
					list.AddRange(Encoding.ASCII.GetBytes($"{(uint)num2:X2}{(byte)num2:X2}"));
					list.AddRange(Encoding.ASCII.GetBytes($"{(uint)value2:X2}{(ulong)num2 >> 24:X2}"));
					num4 = 18;
					break;
				}
				case 4:
					array[0] = num2;
					Array.Copy(array2, array, 2);
					list.AddRange(Encoding.ASCII.GetBytes($"{array2[0]:X2}{array2[1]:X2}"));
					list.AddRange(Encoding.ASCII.GetBytes($"{array2[2]:X2}{array2[3]:X2}"));
					num4 = 18;
					break;
				case 5:
					array[0] = num2;
					Array.Copy(array2, array, 2);
					list.AddRange(Encoding.ASCII.GetBytes($"{array2[3]:X2}{array2[2]:X2}"));
					list.AddRange(Encoding.ASCII.GetBytes($"{array2[1]:X2}{array2[0]:X2}"));
					num4 = 18;
					break;
				default:
					list.AddRange(Encoding.ASCII.GetBytes($"{(sbyte)num2:X2}{num2 >> 8:X2}"));
					num4 = 14;
					break;
				}
				for (int i = 1; i <= num4; i++)
				{
					num += list[i];
				}
				list.AddRange(Encoding.ASCII.GetBytes($"{(byte)num:X2}"));
				list.Add(3);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <summary>
		/// write data to address  Type of One
		/// </summary>
		/// <param name="station">plc station</param>
		/// <param name="address">address, for example: M100, D100, DW100</param>
		/// <param name="value">source value</param>
		/// <returns>command bytes</returns>
		public static OResult<byte[]> BuildWriteOneCommand(byte station, string address, byte[] value)
		{
			OResult<string> oResult = AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			string text = new string(new char[31]);
			ushort num = 0;
			int memoryType = GetMemoryType(oResult.Content);
			int num2 = HexToOct(oResult.Content.Substring(2, oResult.Content.Length - 2));
			string text2 = value[0].ToString("X2");
			if (memoryType == 128)
			{
				Console.WriteLine("Memory Type Input Error. Memory Type = P, M, K, T, C, U, Z, S, L, N, D, R, ZR", address);
			}
			else
			{
				list.Clear();
				list.Add(2);
				if (text2 == "01")
				{
					list.AddRange(Encoding.ASCII.GetBytes(sprintf("o%C", select_data_code(memoryType))));
				}
				else
				{
					list.AddRange(Encoding.ASCII.GetBytes(sprintf("n%C", select_data_code(memoryType))));
				}
				if (memoryType != 1)
				{
					text = $"{num2 >> 4:X4}";
					list.AddRange(Encoding.ASCII.GetBytes($"{GetDataSize((ushort)Convert.ToInt32(text), 2):X2}{0:X2}"));
				}
				else
				{
					list.AddRange(Encoding.ASCII.GetBytes($"{(uint)(sbyte)((ushort)num2 / 16):X2}{(ushort)((ushort)num2 / 16) >> 16:X2}"));
				}
				list.AddRange(Encoding.ASCII.GetBytes($"{0:X2}"));
				short num3 = ((!(text2 != "00")) ? ((short)(-1.0 - Math.Pow(2.0, num2 % 16))) : ((short)Math.Pow(2.0, num2 % 16)));
				list.AddRange(Encoding.ASCII.GetBytes($"{(sbyte)num3:X2}{HIBYTE(num3):X2}"));
				for (int i = 1; i <= 12; i++)
				{
					num += list[i];
				}
				list.AddRange(Encoding.ASCII.GetBytes($"{(byte)num:X2}"));
				list.Add(3);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <summary>
		/// write data to address  Type of ReadByte
		/// </summary>
		/// <param name="station">plc station</param>
		/// <param name="address">address, for example: M100, D100, DW100</param>
		/// <param name="value">source value</param>
		/// <returns>command bytes</returns>
		public static OResult<byte[]> BuildWriteCommand(byte station, string address, byte[] value)
		{
			OResult<string> dataTypeToAddress = LSFastEnet.GetDataTypeToAddress(address);
			if (!dataTypeToAddress.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(dataTypeToAddress);
			}
			switch (dataTypeToAddress.Content)
			{
			case "Bit":
				return BuildWriteOneCommand(station, address, value);
			case "Word":
			case "DWord":
			case "LWord":
			case "Continuous":
				return BuildWriteByteCommand(station, address, value);
			default:
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
			}
		}

		/// <summary>
		/// 从PLC的指定地址读取原始的字节数据信息，地址示例：MB100, MW100, MD100, 如果输入了M100等同于MB100<br />
