		/// </remarks>
		/// <param name="plc">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <param name="address">PLC的地址信息，例如 M100, MB100, MW100, MD100</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>返回是否读取成功的结果对象</returns>
		public static OResult<byte[]> Read(IReadWriteDevice plc, int station, string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand((byte)SnetHelper.ExtractParameter(ref address, "s", station), address, length);
