		public static OResult<bool[]> ReadBool(IReadWriteDevice plc, int station, string address, ushort length)
		{
			int bitIndexInformation = SnetHelper.GetBitIndexInformation(ref address);
			int num = SnetHelper.CalculateOccupyLength(bitIndexInformation, length);
