	/// <summary>
	/// 基恩士的数字传感器的以太网模块，可以同时连接并读取多个传感器模块的功能代码
	/// </summary>
	public class KeyenceDLEN1 : NetworkDoubleBase
	{
		/// <summary>
		/// 实例化基恩士的Qna兼容3E帧协议的通讯对象<br />
		/// Instantiate Keyence Qna compatible 3E frame protocol communication object
		/// </summary>
		public KeyenceDLEN1()
		{
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 指定ip地址及端口号来实例化一个基恩士的Qna兼容3E帧协议的通讯对象<br />
		/// Specify an IP address and port number to instantiate a Keynes Qna compatible 3E frame protocol communication object
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
		/// <param name="port">PLC的端口</param>
		public KeyenceDLEN1(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SpecifiedCharacterMessage(13, 10);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			OResult oResult = CheckResponse(response);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return base.UnpackResponseContent(send, response);
		}

		/// <summary>
		/// 使用M0命令读取所有的传感器的数据信息
		/// </summary>
		/// <param name="cmds">命令信息</param>
		/// <returns>是否成功的结果对象</returns>
		public OResult<string[]> ReadByCommand(string[] cmds)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < cmds.Length; i++)
			{
				stringBuilder.Append(cmds[i]);
				if (i < cmds.Length - 1)
				{
					stringBuilder.Append(",");
				}
			}
			stringBuilder.Append("\r\n");
			OResult<byte[]> oResult = ReadFromCoreServer(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult);
			}
			if (oResult.Content.Length <= 5)
			{
				return OResult.CreateSuccessResult(new string[1] { Encoding.ASCII.GetString(oResult.Content) });
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult.Content, 2, oResult.Content.Length - 5).Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries));
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"KeyenceDLEN1[{IpAddress}:{Port}]";
		}

		/// <summary>
		/// 坚持设备的返回的数据，并校验是否成功
		/// </summary>
		/// <param name="content">设备的返回数据信息</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult CheckResponse(byte[] content)
		{
			if (content.Length >= 9 && Encoding.ASCII.GetString(content, 0, 2) == "ER")
			{
				int num = Convert.ToInt32(Encoding.ASCII.GetString(content, 6, 3));
				return num switch
				{
					9 => new OResult(num, "写入的数据超出有效范围。传感器不支持写入指定的 ID、数据编号。"), 
					12 => new OResult(num, "无法执行动作指令的状态。传感器不支持写入指定的 ID、数据编号。"), 
					14 => new OResult(num, "该地址处于禁止写入或无法写入的状态。"), 
					16 => new OResult(num, "该数据编号处于禁止读取或无法读取的状态。"), 
					20 => new OResult(num, "数据编号超出有效范围。"), 
					22 => new OResult(num, "ID 超出有效范围。"), 
					31 => new OResult(num, "传感器不支持读取、写入指定的 ID、数据编号。当前模式下无法写入或本机正在进行通信初始化。"), 
					254 => new OResult(num, "系统错误状态。请等待启动时间。请确认 D-bus 连接器等无异常。"), 
					255 => new OResult(num, "命令格式错误。"), 
					_ => new OResult(num, StringResources.Language.UnknownError), 
				};
			}
			return OResult.CreateSuccessResult();
		}
	}
	/// <summary>
	/// 老型号的基恩士类，适用于 Kv-10xx, 16xx, 24xx, 40xx, kv-80, kv-300，其中 xx 表示 AR/AT/DR/DT<br />
	/// Old Keenes class, suitable for Kv-10xx, 16xx, 24xx, 40xx, kv-80, kv-300, xx means AR/AT/DR/DT<br />
	/// </summary>
	public class KeyenceKvOld : DeviceTcpNet
	{
		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public KeyenceKvOld()
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform();
			base.ByteTransform.IsStringReverseByteWord = true;
			LogMsgFormatBinary = false;
		}

		/// <summary>
		/// 使用指定的ip地址和端口号来初始化对象<br />
		/// Initialize the object with the specified IP address and port number
		/// </summary>
		/// <param name="ipAddress">Ip地址数据</param>
		/// <param name="port">端口号</param>
		public KeyenceKvOld(string ipAddress, int port = 8501)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SpecifiedCharacterMessage(13, 10);
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, KeyenceNanoHelper.GetConnectCmd(0, useStation: false), hasResponseData: true, usePackAndUnpack: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override OResult ExtraOnDisconnect()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, KeyenceNanoHelper.GetDisConnectCmd(0, useStation: false), hasResponseData: true, usePackAndUnpack: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(CommunicationPipe, KeyenceNanoHelper.GetConnectCmd(0, useStation: false), hasResponseData: true, usePackAndUnpack: true).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override async Task<OResult> ExtraOnDisconnectAsync()
		{
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(CommunicationPipe, KeyenceNanoHelper.GetDisConnectCmd(0, useStation: false), hasResponseData: true, usePackAndUnpack: true).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadWordCommand(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ExtraResponseContent(address, oResult2.Content, isRead: true);
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteWordCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ExtraResponseContent(address, oResult2.Content, isRead: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceKvOld.Read(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadWordCommand(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ExtraResponseContent(address, oResult2.Content, isRead: true);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceKvOld.Write(System.String,System.Byte[])" />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteWordCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ExtraResponseContent(address, oResult2.Content, isRead: false);
		}

		private static bool CheckBoolOnWordAddress(string address)
		{
			return Regex.IsMatch(address, "^(DM|TM)[0-9]+\\.[0-9]+$", RegexOptions.IgnoreCase);
		}

		/// <inheritdoc />
		public override OResult<bool> ReadBool(string address)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return ByteTransformHelper.GetResultFromArray(SnetHelper.ReadBool(this, address, 1));
			}
			OResult<byte[]> oResult = BuildReadWordCommand(address, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult2);
			}
			return ExtraBoolContent(address, oResult2.Content, isRead: true);
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool value)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return SnetHelper.WriteBool(this, address, new bool[1] { value });
			}
			OResult<byte[]> oResult = BuildWriteBoolCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ExtraBoolContent(address, oResult2.Content, isRead: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceKvOld.ReadBool(System.String)" />
		public override async Task<OResult<bool>> ReadBoolAsync(string address)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return ByteTransformHelper.GetResultFromArray(await SnetHelper.ReadBoolAsync(this, address, 1).ConfigureAwait(continueOnCapturedContext: false));
			}
			OResult<byte[]> oResult = BuildReadWordCommand(address, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult2);
			}
			return ExtraBoolContent(address, oResult2.Content, isRead: true);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceKvOld.Write(System.String,System.Boolean)" />
		public override async Task<OResult> WriteAsync(string address, bool value)
		{
			if (CheckBoolOnWordAddress(address))
			{
				return await SnetHelper.WriteBoolAsync(this, address, new bool[1] { value }).ConfigureAwait(continueOnCapturedContext: false);
			}
			OResult<byte[]> oResult = BuildWriteBoolCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ExtraBoolContent(address, oResult2.Content, isRead: false);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"KeyenceKvOld<{CommunicationPipe}>";
		}

		private static OResult<string> AnalysisAddress(string address, bool isBit)
		{
			if (isBit)
			{
				if (address.StartsWithAndNumber("CTH"))
				{
					return OResult.CreateSuccessResult(address);
				}
				if (address.StartsWithAndNumber("CTC"))
				{
					return OResult.CreateSuccessResult(address);
				}
				if (address.StartsWithAndNumber("C"))
				{
					return OResult.CreateSuccessResult(address);
				}
				if (address.StartsWithAndNumber("T"))
				{
					return OResult.CreateSuccessResult(address);
				}
				if (address.StartsWithAndNumber("R"))
				{
					address = address.Substring(1);
					int num = address.IndexOf(".");
					if (num > 0 && num < address.Length - 1)
					{
						return OResult.CreateSuccessResult(address.Substring(0, num) + address.Substring(num + 1).PadLeft(2, '0'));
					}
					return OResult.CreateSuccessResult(address);
				}
				if (Regex.IsMatch(address, "^[0-9]+$"))
				{
					return OResult.CreateSuccessResult(address);
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			if (address.StartsWithAndNumber("DM"))
			{
				return OResult.CreateSuccessResult(address);
			}
			if (address.StartsWithAndNumber("CC"))
			{
				return OResult.CreateSuccessResult("C" + address.Substring(2));
			}
			if (address.StartsWithAndNumber("CS"))
			{
				return OResult.CreateSuccessResult("C" + address.Substring(2));
			}
			if (address.StartsWithAndNumber("CTH"))
			{
				return OResult.CreateSuccessResult(address);
			}
			if (address.StartsWithAndNumber("TC"))
			{
				return OResult.CreateSuccessResult("T" + address.Substring(2));
			}
			if (address.StartsWithAndNumber("TS"))
			{
				return OResult.CreateSuccessResult("T" + address.Substring(2));
			}
			if (address.StartsWithAndNumber("AT"))
			{
				return OResult.CreateSuccessResult(address);
			}
			if (address.StartsWithAndNumber("TM"))
			{
				return OResult.CreateSuccessResult(address);
			}
			return new OResult<string>(StringResources.Language.NotSupportedDataType);
		}

		private static OResult<byte[]> BuildReadWordCommand(string address, bool isBit)
		{
			OResult<string> oResult = AnalysisAddress(address, isBit);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("RD");
			stringBuilder.Append(" ");
			stringBuilder.Append(oResult.Content);
			stringBuilder.Append("\r");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		private static OResult<byte[]> BuildWriteWordCommand(string address, byte[] value)
		{
			OResult<string> oResult = AnalysisAddress(address, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			if (address.StartsWithAndNumber("CC"))
			{
				stringBuilder.Append("WR");
			}
			else if (address.StartsWithAndNumber("CS"))
			{
				stringBuilder.Append("WS");
			}
			else if (address.StartsWithAndNumber("CTH"))
			{
				stringBuilder.Append("WR");
			}
			else if (address.StartsWithAndNumber("TC"))
			{
				stringBuilder.Append("WR");
			}
			else if (address.StartsWithAndNumber("TS"))
			{
				stringBuilder.Append("WS");
			}
			else
			{
				stringBuilder.Append("WR");
			}
			stringBuilder.Append(" ");
			stringBuilder.Append(oResult.Content);
			stringBuilder.Append(" ");
			stringBuilder.Append(BitConverter.ToUInt16(value, 0));
			stringBuilder.Append("\r");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		private static OResult<byte[]> BuildWriteBoolCommand(string address, bool value)
		{
			OResult<string> oResult = AnalysisAddress(address, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(value ? "ST" : "RS");
			stringBuilder.Append(" ");
			stringBuilder.Append(oResult.Content);
			stringBuilder.Append("\r");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		private static OResult<bool> ExtraBoolContent(string address, byte[] ack, bool isRead)
		{
			if (ack.Length == 0)
			{
				return new OResult<bool>(StringResources.Language.MelsecFxReceiveZero);
			}
			if (ack[0] == 69)
			{
				return new OResult<bool>(KeyenceNanoHelper.GetErrorText(Encoding.ASCII.GetString(ack)));
			}
			if (!isRead)
			{
				string text = Encoding.ASCII.GetString(ack);
				if (text.StartsWith("OK", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(value: true);
				}
				return new OResult<bool>(text);
			}
			try
			{
				return OResult.CreateSuccessResult(ushort.Parse(Encoding.ASCII.GetString(ack).TrimEnd('\r', '\n').Split(',')[0]) != 0);
			}
			catch (Exception ex)
			{
				return new OResult<bool>(ex.Message + " Ack: " + ack.ToHexString(' '));
			}
		}

		private static OResult<byte[]> ExtraResponseContent(string address, byte[] ack, bool isRead)
		{
			if (ack.Length == 0)
			{
				return new OResult<byte[]>(StringResources.Language.MelsecFxReceiveZero);
			}
			if (ack[0] == 69)
			{
				return new OResult<byte[]>(KeyenceNanoHelper.GetErrorText(Encoding.ASCII.GetString(ack)));
			}
			if (!isRead)
			{
				string text = Encoding.ASCII.GetString(ack);
				if (text.StartsWith("OK", StringComparison.OrdinalIgnoreCase))
				{
					return OResult.CreateSuccessResult(new byte[0]);
				}
				return new OResult<byte[]>(text);
			}
			try
			{
				string text2 = Encoding.ASCII.GetString(ack).TrimEnd('\r', '\n');
				if (address.StartsWithAndNumber("CC"))
				{
					return OResult.CreateSuccessResult(BitConverter.GetBytes(ushort.Parse(text2.Split(',')[1])));
				}
				if (address.StartsWithAndNumber("CS"))
				{
					return OResult.CreateSuccessResult(BitConverter.GetBytes(ushort.Parse(text2.Split(',')[2])));
				}
				if (address.StartsWithAndNumber("CTH"))
				{
					return OResult.CreateSuccessResult(BitConverter.GetBytes(ushort.Parse(text2.Split(',')[1])));
				}
				if (address.StartsWithAndNumber("TC"))
				{
					return OResult.CreateSuccessResult(BitConverter.GetBytes(ushort.Parse(text2.Split(',')[1])));
				}
				if (address.StartsWithAndNumber("TS"))
				{
					return OResult.CreateSuccessResult(BitConverter.GetBytes(ushort.Parse(text2.Split(',')[2])));
				}
				if (address.StartsWithAndNumber("AT"))
				{
					return OResult.CreateSuccessResult(BitConverter.GetBytes(ushort.Parse(text2.Split(',')[1])));
				}
				return OResult.CreateSuccessResult(BitConverter.GetBytes(ushort.Parse(text2)));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message + " Ack: " + ack.ToHexString(' '));
			}
		}
	}
	/// <summary>
	/// 基恩士PLC的数据通信类，使用QnA兼容3E帧的通信协议实现，使用ASCII的格式，地址格式需要进行转换成三菱的格式，详细参照备注说明<br />
	/// Keyence PLC's data communication class is implemented using QnA compatible 3E frame communication protocol. 
	/// It uses ascii format. The address format needs to be converted to Mitsubishi format.
	/// </summary>
	/// <remarks>
	/// <inheritdoc cref="T:Snet.Driver.Profinet.Keyence.KeyenceMcNet" path="remarks" />
	/// </remarks>
	public class KeyenceMcAsciiNet : MelsecMcAsciiNet
	{
		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceMcNet.#ctor" />
		public KeyenceMcAsciiNet()
		{
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceMcNet.#ctor(System.String,System.Int32)" />
		public KeyenceMcAsciiNet(string ipAddress, int port)
			: base(ipAddress, port)
		{
		}

		/// <inheritdoc />
		public override OResult<McAddressData> McAnalysisAddress(string address, ushort length, bool isBit)
		{
			return McAddressData.ParseKeyenceFrom(address, length, isBit);
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (KeyenceMcNet.CheckKeyenceBoolAddress(address))
			{
				return McHelper.ReadBool(this, address, length, supportWordAdd: false);
			}
			return base.ReadBool(address, length);
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] values)
		{
			if (KeyenceMcNet.CheckKeyenceBoolAddress(address))
			{
				return McHelper.Write(this, address, values, supportWordAdd: false);
			}
			return base.Write(address, values);
		}

		/// <inheritdoc />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			if (KeyenceMcNet.CheckKeyenceBoolAddress(address))
			{
				return await McHelper.ReadBoolAsync(this, address, length, supportWordAdd: false).ConfigureAwait(continueOnCapturedContext: false);
			}
			return await base.ReadBoolAsync(address, length).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, bool[] values)
		{
			if (KeyenceMcNet.CheckKeyenceBoolAddress(address))
			{
				return await McHelper.WriteAsync(this, address, values, supportWordAdd: false).ConfigureAwait(continueOnCapturedContext: false);
			}
			return await base.WriteAsync(address, values).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"KeyenceMcAsciiNet[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 基恩士PLC的数据通信类，使用QnA兼容3E帧的通信协议实现，使用二进制的格式，地址同时支持三菱的地址格式及基恩士自身的地址格式，详细参照备注说明<br />
	/// The data communication class of KEYENCE PLC is implemented using a QnA-compatible 3E frame communication protocol, using binary format, 
	/// and the address supports both Mitsubishi's address format and Keyence's own address format, please refer to the remarks for details
	/// </summary>
	/// <remarks>
	/// 地址支持 R015, MR015, LR015, CR015, CM0, DM100, EM100, FM100, ZF100, W1A0, TN0, TS0, CN0, CS0, 具体范围参考：http://api.Snetcommunication.cn/html/04bd2a21-7ab0-2fb9-f7f1-e0f0ecaf9227.htm
	/// </remarks>
	public class KeyenceMcNet : MelsecMcNet
	{
		/// <summary>
		/// 实例化基恩士的Qna兼容3E帧协议的通讯对象<br />
		/// Instantiate Keyence Qna compatible 3E frame protocol communication object
		/// </summary>
		public KeyenceMcNet()
		{
		}

		/// <summary>
		/// 指定ip地址及端口号来实例化一个基恩士的Qna兼容3E帧协议的通讯对象<br />
		/// Specify an IP address and port number to instantiate a Keynes Qna compatible 3E frame protocol communication object
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
		/// <param name="port">PLC的端口</param>
		public KeyenceMcNet(string ipAddress, int port)
			: base(ipAddress, port)
		{
		}

		/// <inheritdoc />
		public override OResult<McAddressData> McAnalysisAddress(string address, ushort length, bool isBit)
		{
			return McAddressData.ParseKeyenceFrom(address, length, isBit);
		}

		internal static bool CheckKeyenceBoolAddress(string address)
		{
			if (address.StartsWith("MR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("CR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("LR", StringComparison.OrdinalIgnoreCase) || address.StartsWith("R", StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
			return false;
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (CheckKeyenceBoolAddress(address))
			{
				return McHelper.ReadBool(this, address, length, supportWordAdd: false);
			}
			return base.ReadBool(address, length);
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] values)
		{
			if (CheckKeyenceBoolAddress(address))
			{
				return McHelper.Write(this, address, values, supportWordAdd: false);
			}
			return base.Write(address, values);
		}

		/// <inheritdoc />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			if (CheckKeyenceBoolAddress(address))
			{
				return await McHelper.ReadBoolAsync(this, address, length, supportWordAdd: false).ConfigureAwait(continueOnCapturedContext: false);
			}
			return await base.ReadBoolAsync(address, length).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, bool[] values)
		{
			if (CheckKeyenceBoolAddress(address))
			{
				return await McHelper.WriteAsync(this, address, values, supportWordAdd: false).ConfigureAwait(continueOnCapturedContext: false);
			}
			return await base.WriteAsync(address, values).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"KeyenceMcNet[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// KeyenceNano的基本辅助方法
	/// </summary>
	public class KeyenceNanoHelper
	{
		/// <summary>
		/// 连接PLC的命令报文<br />
		/// Command message to connect to PLC
		/// </summary>
		/// <param name="station">当前PLC的站号信息</param>
		/// <param name="useStation">是否启动站号命令</param>
		public static byte[] GetConnectCmd(byte station, bool useStation)
		{
			if (!useStation)
			{
				return Encoding.ASCII.GetBytes("CR\r");
			}
			return Encoding.ASCII.GetBytes($"CR {station:D2}\r");
		}

		/// <summary>
		/// 断开PLC连接的命令报文<br />
		/// Command message to disconnect PLC
		/// </summary>
		/// <param name="station">当前PLC的站号信息</param>
		/// <param name="useStation">是否启动站号命令</param>
		public static byte[] GetDisConnectCmd(byte station, bool useStation)
		{
			return Encoding.ASCII.GetBytes("CQ\r");
		}

		/// <summary>
		/// 获取当前的地址类型是字数据的倍数关系
		/// </summary>
		/// <param name="type">地址的类型</param>
		/// <returns>倍数关系</returns>
		public static int GetWordAddressMultiple(string type)
		{
			if (type == null)
			{
				goto IL_00d1;
			}
			switch (type.Length)
			{
			case 3:
				break;
			case 1:
				goto IL_003d;
			case 2:
				goto IL_0057;
			default:
				goto IL_00d1;
			}
			char c = type[2];
			if (c != 'C')
			{
				if (c != 'H' || !(type == "CTH"))
				{
					goto IL_00d1;
				}
			}
			else if (!(type == "CTC"))
			{
				goto IL_00d1;
			}
			goto IL_01a2;
			IL_00d1:
			if (!(type == "AT"))
			{
				if (type != null)
				{
					int length = type.Length;
					if (length != 1)
					{
						if (length == 2)
						{
							switch (type[0])
							{
							case 'D':
								break;
							case 'C':
								goto IL_0149;
							case 'T':
								goto IL_0158;
							case 'E':
								goto IL_0167;
							case 'F':
								goto IL_0176;
							case 'Z':
								goto IL_0185;
							default:
								goto IL_0192;
							}
							if (type == "DM")
							{
								goto IL_01a0;
							}
						}
					}
					else
					{
						c = type[0];
						if (c == 'W' || c == 'Z')
						{
							goto IL_01a0;
						}
					}
				}
				goto IL_0192;
			}
			goto IL_01a2;
			IL_003d:
			c = type[0];
			if (c != 'C' && c != 'T')
			{
				goto IL_00d1;
			}
			goto IL_01a2;
			IL_0149:
			if (!(type == "CM"))
			{
				goto IL_0192;
			}
			goto IL_01a0;
			IL_0057:
			c = type[0];
			if (c != 'C')
			{
				if (c != 'T' || (!(type == "TS") && !(type == "TC")))
				{
					goto IL_00d1;
				}
			}
			else if (!(type == "CS") && !(type == "CC"))
			{
				goto IL_00d1;
			}
			goto IL_01a2;
			IL_0158:
			if (!(type == "TM"))
			{
				goto IL_0192;
			}
			goto IL_01a0;
			IL_0185:
			if (!(type == "ZF"))
			{
				goto IL_0192;
			}
			goto IL_01a0;
			IL_0167:
			if (!(type == "EM"))
			{
				goto IL_0192;
			}
			goto IL_01a0;
			IL_0192:
			_ = type == "VM";
			return 1;
			IL_0176:
			if (!(type == "FM"))
			{
				goto IL_0192;
			}
			goto IL_01a0;
			IL_01a0:
			return 1;
			IL_01a2:
			return 2;
		}

		/// <summary>
		/// 建立读取PLC数据的指令，需要传入地址数据，以及读取的长度，地址示例参照类的说明文档<br />
		/// To create a command to read PLC data, you need to pass in the address data, and the length of the read. For an example of the address, refer to the class documentation
		/// </summary>
		/// <param name="address">软元件地址</param>
		/// <param name="length">读取长度</param>
		/// <returns>是否建立成功</returns>
		public static OResult<List<byte[]>> BuildReadCommand(string address, ushort length)
		{
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			return BuildReadCommand(oResult.Content, length, isBit: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceNanoHelper.BuildReadCommand(System.String,System.UInt16)" />
		public static OResult<List<byte[]>> BuildReadCommand(KeyenceNanoAddress address, ushort length, bool isBit)
		{
			if (length > 1)
			{
				length = (ushort)(length / GetWordAddressMultiple(address.DataCode));
			}
			int[] array = SoftBasic.SplitIntegerToArray(length, address.SplitLength);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < array.Length; i++)
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("RDS");
				stringBuilder.Append(" ");
				stringBuilder.Append(address.DataCode);
				stringBuilder.Append(address.GetAddressStartFormat());
				if (!isBit && address.IsBitAddressDefault())
				{
					stringBuilder.Append(".U");
				}
				stringBuilder.Append(" ");
				stringBuilder.Append(array[i].ToString());
				stringBuilder.Append("\r");
				list.Add(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
				address.AddressStart += array[i];
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 建立写入PLC数据的指令，需要传入地址数据，以及写入的数据信息，地址示例参照类的说明文档<br />
		/// To create a command to write PLC data, you need to pass in the address data and the written data information. For an example of the address, refer to the class documentation
		/// </summary>
		/// <param name="address">软元件地址</param>
		/// <param name="value">转换后的数据</param>
		/// <returns>是否成功的信息</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, byte[] value)
		{
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("WRS");
			stringBuilder.Append(" ");
			stringBuilder.Append(oResult.Content.DataCode);
			stringBuilder.Append(oResult.Content.GetAddressStartFormat());
			if (oResult.Content.IsBitAddressDefault())
			{
				stringBuilder.Append(".U");
			}
			stringBuilder.Append(" ");
			int num = value.Length / (GetWordAddressMultiple(oResult.Content.DataCode) * 2);
			stringBuilder.Append(num.ToString());
			for (int i = 0; i < num; i++)
			{
				stringBuilder.Append(" ");
				stringBuilder.Append(BitConverter.ToUInt16(value, i * GetWordAddressMultiple(oResult.Content.DataCode) * 2));
			}
			stringBuilder.Append("\r");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 构建写入扩展单元缓冲寄存器的报文命令，需要传入单元编号，地址，写入的数据，实际写入的数据格式才有无符号的方式<br />
		/// To construct a message command to write to the buffer register of the expansion unit, the unit number, address, 
		/// and data to be written need to be passed in, and the format of the actually written data is unsigned.
		/// </summary>
		/// <param name="unit">单元编号0~48</param>
		/// <param name="address">地址0~32767</param>
		/// <param name="value">写入的数据信息，单次交互最大256个字</param>
		/// <returns>包含是否成功的报文对象</returns>
		public static OResult<byte[]> BuildWriteExpansionMemoryCommand(byte unit, ushort address, byte[] value)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("UWR");
			stringBuilder.Append(" ");
			stringBuilder.Append(unit);
			stringBuilder.Append(" ");
			stringBuilder.Append(address);
			stringBuilder.Append(".U");
			stringBuilder.Append(" ");
			int num = value.Length / 2;
			stringBuilder.Append(num.ToString());
			for (int i = 0; i < num; i++)
			{
				stringBuilder.Append(" ");
				stringBuilder.Append(BitConverter.ToUInt16(value, i * 2));
			}
			stringBuilder.Append("\r");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 建立写入bool数据的指令，针对地址类型为 R,CR,MR,LR<br />
		/// Create instructions to write bool data, address type is R, CR, MR, LR
		/// </summary>
		/// <param name="address">软元件地址</param>
		/// <param name="value">转换后的数据</param>
		/// <returns>是否成功的信息</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, bool value)
		{
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			if (value)
			{
				stringBuilder.Append("ST");
			}
			else
			{
				stringBuilder.Append("RS");
			}
			stringBuilder.Append(" ");
			stringBuilder.Append(oResult.Content.DataCode);
			stringBuilder.Append(oResult.Content.GetAddressStartFormat());
			stringBuilder.Append("\r");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 批量写入数据位到plc地址，针对地址格式为 R,B,CR,MR,LR,VB<br />
		/// Write data bits in batches to the plc address, and the address format is R, B, CR, MR, LR, VB
		/// </summary>
		/// <param name="address">PLC的地址</param>
		/// <param name="value">等待写入的bool数组</param>
		/// <returns>写入bool数组的命令报文</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, bool[] value)
		{
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("WRS");
			stringBuilder.Append(" ");
			stringBuilder.Append(oResult.Content.DataCode);
			stringBuilder.Append(oResult.Content.GetAddressStartFormat());
			stringBuilder.Append(" ");
			stringBuilder.Append(value.Length.ToString());
			for (int i = 0; i < value.Length; i++)
			{
				stringBuilder.Append(" ");
				stringBuilder.Append(value[i] ? "1" : "0");
			}
			stringBuilder.Append("\r");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		internal static string GetErrorText(string err)
		{
			if (err.StartsWith("E0"))
			{
				return StringResources.Language.KeyenceNanoE0;
			}
			if (err.StartsWith("E1"))
			{
				return StringResources.Language.KeyenceNanoE1;
			}
			if (err.StartsWith("E2"))
			{
				return StringResources.Language.KeyenceNanoE2;
			}
			if (err.StartsWith("E4"))
			{
				return StringResources.Language.KeyenceNanoE4;
			}
			if (err.StartsWith("E5"))
			{
				return StringResources.Language.KeyenceNanoE5;
			}
			if (err.StartsWith("E6"))
			{
				return StringResources.Language.KeyenceNanoE6;
			}
			return StringResources.Language.UnknownError + " " + err;
		}

		/// <summary>
		/// 校验读取返回数据状态，主要返回的第一个字节是不是E<br />
		/// Check the status of the data returned from reading, whether the first byte returned is E
		/// </summary>
		/// <param name="ack">反馈信息</param>
		/// <returns>是否成功的信息</returns>
		public static OResult CheckPlcReadResponse(byte[] ack)
		{
			try
			{
				if (ack.Length == 0)
				{
					return new OResult(StringResources.Language.MelsecFxReceiveZero);
				}
				if (ack[0] == 69)
				{
					return new OResult(GetErrorText(Encoding.ASCII.GetString(ack)));
				}
				if (ack[^1] != 10 && ack[^2] != 13)
				{
					return new OResult(StringResources.Language.MelsecFxAckWrong + " Actual: " + SoftBasic.ByteToHexString(ack, ' '));
				}
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				return new OResult("CheckPlcReadResponse failed: " + ex.Message + Environment.NewLine + ack.ToHexString(' '));
			}
		}

		/// <summary>
		/// 校验写入返回数据状态，检测返回的数据是不是OK<br />
		/// Verify the status of the returned data written and check whether the returned data is OK
		/// </summary>
		/// <param name="ack">反馈信息</param>
		/// <returns>是否成功的信息</returns>
		public static OResult CheckPlcWriteResponse(byte[] ack)
		{
			try
			{
				if (ack.Length == 0)
				{
					return new OResult(StringResources.Language.MelsecFxReceiveZero);
				}
				if (ack[0] == 79 && ack[1] == 75)
				{
					return OResult.CreateSuccessResult();
				}
				return new OResult(GetErrorText(Encoding.ASCII.GetString(ack)));
			}
			catch (Exception ex)
			{
				return new OResult("CheckPlcWriteResponse failed: " + ex.Message + Environment.NewLine + ack.ToHexString(' '));
			}
		}

		/// <summary>
		/// 从PLC反馈的数据进行提炼Bool操作<br />
		/// Refine Bool operation from data fed back from PLC
		/// </summary>
		/// <param name="addressType">地址的数据类型</param>
		/// <param name="response">PLC反馈的真实数据</param>
		/// <returns>数据提炼后的真实数据</returns>
		public static OResult<bool[]> ExtractActualBoolData(string addressType, byte[] response)
		{
			try
			{
				if (string.IsNullOrEmpty(addressType))
				{
					addressType = "R";
				}
				string text = Encoding.Default.GetString(response.RemoveLast(2));
				switch (addressType)
				{
				default:
					return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
				case "T":
				case "C":
				case "CTH":
				case "CTC":
					return OResult.CreateSuccessResult((from m in text.Split(new char[1] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
						select m.StartsWith("1")).ToArray());
				case "R":
				case "CR":
				case "MR":
				case "LR":
				case "B":
				case "VB":
					return OResult.CreateSuccessResult((from m in text.Split(new char[1] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
						select m == "1").ToArray());
				}
			}
			catch (Exception ex)
			{
				OResult<bool[]> oResult = new OResult<bool[]>();
				oResult.Message = "Extract Msg：" + ex.Message + Environment.NewLine + "Data: " + SoftBasic.ByteToHexString(response);
				return oResult;
			}
		}

