		/// <param name="response">PLC反馈的真实数据</param>
		/// <returns>数据提炼后的真实数据</returns>
		public static OResult<byte[]> ExtractActualData(string addressType, byte[] response)
		{
			try
			{
				if (string.IsNullOrEmpty(addressType))
				{
					addressType = "R";
				}
