							case 'D':
								break;
							case 'E':
								goto IL_00a6;
							case 'F':
								goto IL_00b8;
							case 'Z':
								goto IL_00ca;
							case 'T':
								goto IL_00dc;
							case 'C':
								goto IL_00ee;
