				case "MR":
				case "LR":
				case "CR":
				case "VB":
				{
					byte[] array3 = new byte[array.Length * 2];
					for (int j = 0; j < array.Length; j++)
					{
						BitConverter.GetBytes(ushort.Parse(array[j])).CopyTo(array3, j * 2);
					}
					return OResult.CreateSuccessResult(array3);
