					}
					return OResult.CreateSuccessResult(array4);
				}
				case "AT":
				case "TC":
				case "CC":
				case "TS":
				case "CS":
				{
					byte[] array2 = new byte[array.Length * 4];
					for (int i = 0; i < array.Length; i++)
					{
						BitConverter.GetBytes(uint.Parse(array[i])).CopyTo(array2, i * 4);
