				if (!(addressType == "CM"))
				{
					goto IL_00fe;
				}
				goto IL_02e0;
			}
			catch (Exception ex)
			{
				OResult<byte[]> oResult = new OResult<byte[]>();
				oResult.Message = "Extract Msg：" + ex.Message + Environment.NewLine + "Data: " + SoftBasic.ByteToHexString(response);
				return oResult;
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Read(System.String,System.UInt16)" />
		/// <remarks>
		/// 地址支持读取扩展单元缓冲存储器的数据，例如读取扩展单元号1，地址100的数据，地址写为 unit=1;100<br />
		/// The address supports reading the data in the buffer memory of the expansion unit, such as reading the data of the expansion unit number 1, address 100, and the address is written as unit=1;100
		/// </remarks>
		public static OResult<byte[]> Read(IReadWriteDevice keyence, string address, ushort length)
		{
			if (address.StartsWith("unit="))
			{
				byte unit = (byte)SnetHelper.ExtractParameter(ref address, "unit", 0);
				if (!ushort.TryParse(address, out var _))
				{
					return new OResult<byte[]>("Address is not right, convert ushort wrong!");
				}
				return ReadExpansionMemory(keyence, unit, ushort.Parse(address), length);
			}
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<List<byte[]>> oResult2 = BuildReadCommand(oResult.Content, length, isBit: false);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult2.Content.Count; i++)
			{
				OResult<byte[]> oResult3 = keyence.ReadFromCoreServer(oResult2.Content[i]);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult3);
				}
				OResult oResult4 = CheckPlcReadResponse(oResult3.Content);
				if (!oResult4.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult4);
				}
				OResult<byte[]> oResult5 = ExtractActualData(oResult.Content.DataCode, oResult3.Content);
				if (!oResult5.IsSuccess)
				{
