		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceNanoHelper.Read(Snet.Driver.Core.IReadWriteDevice,System.String,System.UInt16)" />
		public static async Task<OResult<byte[]>> ReadAsync(IReadWriteDevice keyence, string address, ushort length)
		{
			if (address.StartsWith("unit="))
			{
				byte unit = (byte)SnetHelper.ExtractParameter(ref address, "unit", 0);
				if (!ushort.TryParse(address, out var _))
				{
					return new OResult<byte[]>("Address is not right, convert ushort wrong!");
				}
				return await ReadExpansionMemoryAsync(keyence, unit, ushort.Parse(address), length);
			}
			OResult<KeyenceNanoAddress> addressResult = KeyenceNanoAddress.ParseFrom(address, length);
			if (!addressResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(addressResult);
			}
			OResult<List<byte[]>> command = BuildReadCommand(addressResult.Content, length, isBit: false);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(command);
			}
			List<byte> array = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await keyence.ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				OResult oResult2 = CheckPlcReadResponse(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult<byte[]> oResult3 = ExtractActualData(addressResult.Content.DataCode, oResult.Content);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult3);
				}
				array.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(array.ToArray());
		}

