		private static OResult<KeyencePLCS> ExtraPlcType(OResult<byte[]> read)
		{
			if (!read.IsSuccess)
			{
				return read.ConvertFailed<KeyencePLCS>();
			}
			OResult oResult = CheckPlcReadResponse(read.Content);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<KeyencePLCS>();
			}
			string text = Encoding.ASCII.GetString(read.Content.RemoveLast(2));
			switch (text)
			{
			case "48":
			case "49":
				return OResult.CreateSuccessResult(KeyencePLCS.KV700);
			case "50":
				return OResult.CreateSuccessResult(KeyencePLCS.KV1000);
			case "51":
				return OResult.CreateSuccessResult(KeyencePLCS.KV3000);
			case "52":
				return OResult.CreateSuccessResult(KeyencePLCS.KV5000);
			case "53":
				return OResult.CreateSuccessResult(KeyencePLCS.KV5500);
			default:
				return new OResult<KeyencePLCS>("Unknow type:" + text);
			}
		}

