		private static OResult<int> ExtraPlcMode(OResult<byte[]> read)
		{
			if (!read.IsSuccess)
			{
				return read.ConvertFailed<int>();
			}
			OResult oResult = CheckPlcReadResponse(read.Content);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<int>();
			}
			if (Encoding.ASCII.GetString(read.Content.RemoveLast(2)) == "0")
			{
				return OResult.CreateSuccessResult(0);
			}
			return OResult.CreateSuccessResult(1);
		}

