		/// <returns>是否设置成功</returns>
		public static OResult SetPlcDateTime(IReadWriteDevice keyence, DateTime dateTime)
		{
			OResult<byte[]> oResult = keyence.ReadFromCoreServer(Encoding.ASCII.GetBytes($"WRT {dateTime.Year - 2000:D2} {dateTime.Month:D2} {dateTime.Day:D2} {dateTime.Hour:D2} {dateTime.Minute:D2} {dateTime.Second:D2} {(int)dateTime.DayOfWeek}\r"));
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<int>();
			}
			return CheckPlcWriteResponse(oResult.Content);
		}

