	/// <summary>
	/// 基恩士的上位链路协议的虚拟服务器
	/// </summary>
	public class KeyenceNanoServer : DeviceServer
	{
		private SoftBuffer rBuffer;

		private SoftBuffer bBuffer;

		private SoftBuffer mrBuffer;

		private SoftBuffer lrBuffer;

		private SoftBuffer crBuffer;

		private SoftBuffer vbBuffer;

		private SoftBuffer dmBuffer;

		private SoftBuffer emBuffer;

		private SoftBuffer wBuffer;

		private SoftBuffer atBuffer;

		private const int DataPoolLength = 65536;

		/// <summary>
		/// 实例化一个基于上位链路协议的虚拟的基恩士PLC对象，可以用来和<see cref="T:Snet.Driver.Profinet.Keyence.KeyenceNanoSerialOverTcp" />进行通信测试。
		/// </summary>
		public KeyenceNanoServer()
		{
			rBuffer = new SoftBuffer(65536);
			bBuffer = new SoftBuffer(65536);
			mrBuffer = new SoftBuffer(65536);
			lrBuffer = new SoftBuffer(65536);
			crBuffer = new SoftBuffer(65536);
			vbBuffer = new SoftBuffer(65536);
			dmBuffer = new SoftBuffer(131072);
			emBuffer = new SoftBuffer(131072);
			wBuffer = new SoftBuffer(131072);
			atBuffer = new SoftBuffer(65536);
			base.ByteTransform = new RegularByteTransform();
			base.ByteTransform.IsStringReverseByteWord = true;
			base.WordLength = 1;
			LogMsgFormatBinary = false;
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[851968];
			rBuffer.GetBytes().CopyTo(array, 0);
			bBuffer.GetBytes().CopyTo(array, 65536);
			mrBuffer.GetBytes().CopyTo(array, 131072);
			lrBuffer.GetBytes().CopyTo(array, 196608);
			crBuffer.GetBytes().CopyTo(array, 262144);
			vbBuffer.GetBytes().CopyTo(array, 327680);
			dmBuffer.GetBytes().CopyTo(array, 393216);
			emBuffer.GetBytes().CopyTo(array, 524288);
			wBuffer.GetBytes().CopyTo(array, 655360);
			atBuffer.GetBytes().CopyTo(array, 786432);
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 851968)
			{
				throw new Exception("File is not correct");
			}
			rBuffer.SetBytes(content, 0, 65536);
			bBuffer.SetBytes(content, 65536, 65536);
			mrBuffer.SetBytes(content, 131072, 65536);
			lrBuffer.SetBytes(content, 196608, 65536);
			crBuffer.SetBytes(content, 262144, 65536);
			vbBuffer.SetBytes(content, 327680, 65536);
			dmBuffer.SetBytes(content, 393216, 131072);
			emBuffer.SetBytes(content, 524288, 131072);
			wBuffer.SetBytes(content, 655360, 131072);
			atBuffer.SetBytes(content, 786432, 65536);
		}

		private byte[] TransBoolByteToBuffer(byte[] data)
		{
			bool[] array = new bool[data.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = data[i] != 0;
			}
			return array.ToByteArray();
		}

		private byte[] TransBufferToBoolByte(byte[] data)
		{
			bool[] array = data.ToBoolArray();
			byte[] array2 = new byte[array.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array2[i] = (array[i] ? ((byte)1) : ((byte)0));
			}
			return array2;
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceNanoSerialOverTcp.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			try
			{
				if (address.StartsWith("DM"))
				{
					return OResult.CreateSuccessResult(dmBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
				}
				if (address.StartsWith("EM"))
				{
					return OResult.CreateSuccessResult(emBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
				}
				if (address.StartsWith("W"))
				{
					return OResult.CreateSuccessResult(wBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
				}
				if (address.StartsWith("AT"))
				{
					return OResult.CreateSuccessResult(atBuffer.GetBytes(oResult.Content.AddressStart * 4, length * 4));
				}
				if (address.StartsWith("MR"))
				{
					return OResult.CreateSuccessResult(TransBoolByteToBuffer(mrBuffer.GetBytes(oResult.Content.AddressStart, length * 16)));
				}
				if (address.StartsWith("LR"))
				{
					return OResult.CreateSuccessResult(TransBoolByteToBuffer(lrBuffer.GetBytes(oResult.Content.AddressStart, length * 16)));
				}
				if (address.StartsWith("CR"))
				{
					return OResult.CreateSuccessResult(TransBoolByteToBuffer(crBuffer.GetBytes(oResult.Content.AddressStart, length * 16)));
				}
				if (address.StartsWith("VB"))
				{
					return OResult.CreateSuccessResult(TransBoolByteToBuffer(vbBuffer.GetBytes(oResult.Content.AddressStart, length * 16)));
				}
				if (address.StartsWith("B"))
				{
					return OResult.CreateSuccessResult(TransBoolByteToBuffer(bBuffer.GetBytes(oResult.Content.AddressStart, length * 16)));
				}
				if (address.StartsWith("R"))
				{
					return OResult.CreateSuccessResult(TransBoolByteToBuffer(rBuffer.GetBytes(oResult.Content.AddressStart, length * 16)));
				}
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType + " Reason:" + ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Keyence.KeyenceNanoSerialOverTcp.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			try
			{
				if (address.StartsWith("DM"))
				{
					dmBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
				}
				else if (address.StartsWith("EM"))
				{
					emBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
				}
				else if (address.StartsWith("W"))
				{
					wBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
				}
				else if (address.StartsWith("AT"))
				{
					atBuffer.SetBytes(value, oResult.Content.AddressStart * 4);
				}
				else if (address.StartsWith("MR"))
				{
					mrBuffer.SetBytes(TransBufferToBoolByte(value), oResult.Content.AddressStart);
				}
				else if (address.StartsWith("LR"))
				{
					lrBuffer.SetBytes(TransBufferToBoolByte(value), oResult.Content.AddressStart);
				}
				else if (address.StartsWith("CR"))
				{
					crBuffer.SetBytes(TransBufferToBoolByte(value), oResult.Content.AddressStart);
				}
				else if (address.StartsWith("VB"))
				{
					vbBuffer.SetBytes(TransBufferToBoolByte(value), oResult.Content.AddressStart);
				}
				else if (address.StartsWith("B"))
				{
					bBuffer.SetBytes(TransBufferToBoolByte(value), oResult.Content.AddressStart);
				}
				else
				{
					if (!address.StartsWith("R"))
					{
						return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
					}
					rBuffer.SetBytes(TransBufferToBoolByte(value), oResult.Content.AddressStart);
				}
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType + " Reason:" + ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			try
			{
				if (address.StartsWith("R"))
				{
					return OResult.CreateSuccessResult((from m in rBuffer.GetBytes(oResult.Content.AddressStart, length)
						select m != 0).ToArray());
				}
				if (address.StartsWith("B"))
				{
					return OResult.CreateSuccessResult((from m in bBuffer.GetBytes(oResult.Content.AddressStart, length)
						select m != 0).ToArray());
				}
				if (address.StartsWith("MR"))
				{
					return OResult.CreateSuccessResult((from m in mrBuffer.GetBytes(oResult.Content.AddressStart, length)
						select m != 0).ToArray());
				}
				if (address.StartsWith("LR"))
				{
					return OResult.CreateSuccessResult((from m in lrBuffer.GetBytes(oResult.Content.AddressStart, length)
						select m != 0).ToArray());
				}
				if (address.StartsWith("CR"))
				{
					return OResult.CreateSuccessResult((from m in crBuffer.GetBytes(oResult.Content.AddressStart, length)
						select m != 0).ToArray());
				}
				if (address.StartsWith("VB"))
				{
					return OResult.CreateSuccessResult((from m in vbBuffer.GetBytes(oResult.Content.AddressStart, length)
						select m != 0).ToArray());
				}
				return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<bool[]>(StringResources.Language.NotSupportedDataType + " Reason:" + ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			OResult<KeyenceNanoAddress> oResult = KeyenceNanoAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			try
			{
				byte[] data = value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray();
				if (address.StartsWith("R"))
				{
					rBuffer.SetBytes(data, oResult.Content.AddressStart);
				}
				else if (address.StartsWith("B"))
				{
					bBuffer.SetBytes(data, oResult.Content.AddressStart);
				}
				else if (address.StartsWith("MR"))
				{
					mrBuffer.SetBytes(data, oResult.Content.AddressStart);
				}
				else if (address.StartsWith("LR"))
				{
					lrBuffer.SetBytes(data, oResult.Content.AddressStart);
				}
				else if (address.StartsWith("CR"))
				{
					crBuffer.SetBytes(data, oResult.Content.AddressStart);
				}
				else
				{
					if (!address.StartsWith("VB"))
					{
						return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
					}
					vbBuffer.SetBytes(data, oResult.Content.AddressStart);
				}
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				return new OResult<bool[]>(StringResources.Language.NotSupportedDataType + " Reason:" + ex.Message);
			}
		}

