		/// <summary>
		/// 读取条码信息，返回最终读取的条码数据<br />
		/// Read the barcode information and return the finally read barcode data
		/// </summary>
		/// <param name="readCore">核心交互的方法</param>
		/// <returns>条码信息</returns>
		public static OResult<string> ReadBarcode(Func<byte[], OResult<byte[]>> readCore)
		{
			OResult<string> oResult = ReadCustomer("LON", readCore);
			if (!oResult.IsSuccess && oResult.ErrorCode < 0)
			{
				ReadCustomer("LOFF", readCore);
			}
			return oResult;
		}

