		/// <summary>
		/// 读取IN端子的状况，需要传入哪个IN端子，返回是否通断<br />
		/// Read the status of the IN terminal, which IN terminal needs to be passed in, and return whether it is on or off
		/// </summary>
		/// <param name="number">端子的信息</param>
		/// <param name="readCore">核心交互的方法</param>
		/// <returns>返回是否成功的结果对象</returns>
		public static OResult<bool> CheckInput(int number, Func<byte[], OResult<byte[]>> readCore)
		{
			OResult<string> oResult = ReadCustomer("INCHK," + number, readCore);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			if (oResult.Content == "ON")
			{
				return OResult.CreateSuccessResult(value: true);
			}
			if (oResult.Content == "OFF")
			{
				return OResult.CreateSuccessResult(value: false);
			}
			return new OResult<bool>(oResult.Content);
		}

