	/// <summary>
	/// 汇川的计算机链接协议，使用PLC得COM1口，设置 D8126=06h, D8120.14=1 才能正常通信。<br />
	/// Inovance's computer connection protocol, when using the COM1 port of the PLC, requires setting D8126=06h and D8120.14=1 for normal communication.
	/// </summary>
	public class InovanceComputerLink : MelsecFxLinks
	{
		/// <summary>
		/// 实例化一个欧姆龙计算机链接协议的对象<br />
		/// Instantiate an object of the Omron Computer Link Protocol
		/// </summary>
		public InovanceComputerLink()
		{
			base.Format = 4;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"InovanceComputerLink<{CommunicationPipe}>";
		}
	}
	/// <summary>
	/// 汇川的CIP协议，基于连接的协议
	/// </summary>
	public class InovanceConnectedCipNet : OmronConnectedCipNet
	{
		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public InovanceConnectedCipNet()
		{
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 根据指定的IP及端口来实例化这个连接对象
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
		/// <param name="port">PLC的端口号信息</param>
		public InovanceConnectedCipNet(string ipAddress, int port = 44818)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override byte[] GetLargeForwardOpen(ushort connectionID)
		{
			byte[] array = "\r\n00 00 00 00 00 00 02 00 00 00 00 00 b2 00 34 00\r\n5b 02 20 06 24 01 0e 9c 02 00 00 80 01 00 fe 80\r\n02 00 1b 05 30 a7 2b 03 02 00 00 00 80 84 1e 00\r\ncc 07 00 42 80 84 1e 00 cc 07 00 42 a3 03 20 02\r\n24 01 2c 01".ToHexBytes();
			BitConverter.GetBytes(base.OTConnectionId).CopyTo(array, 24);
			BitConverter.GetBytes(base.TOConnectionId).CopyTo(array, 28);
			BitConverter.GetBytes((ushort)(2 + connectionID)).CopyTo(array, 32);
			BitConverter.GetBytes((ushort)4105).CopyTo(array, 34);
			SnetHelper.SnetRandom.GetBytes(4).CopyTo(array, 36);
			array[40] = base.ConnectionTimeoutMultiplier;
			return array;
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool value)
		{
			return WriteTag(address, 193, (!value) ? new byte[1] : new byte[1] { 1 });
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, bool value)
		{
			return await WriteTagAsync(address, 193, (!value) ? new byte[1] : new byte[1] { 1 }).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"InovanceConnectedCipNet<{CommunicationPipe}>";
		}
	}
	/// <summary>
	/// Easy系列的通信协议，使用的是专用的报文，地址说明参考Demo界面
	/// </summary>
	public class InovanceEasyNet : DeviceTcpNet
	{
		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public InovanceEasyNet()
		{
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
		}

		/// <summary>
		/// 指定IP地址和端口号来实例化一个新的对象<br />
		/// Specify the IP address and port number to instantiate a new object
		/// </summary>
		/// <param name="ipAddress">Ip地址</param>
		/// <param name="port">端口号</param>
		public InovanceEasyNet(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new InovanceEasyNetMessage();
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			if (response.Length < 9)
			{
				return new OResult<byte[]>("Received data length is too short: " + response.Length + " Source: " + response.ToHexString(' '));
			}
			if (response.Length >= 9 && response[8] == 15)
			{
				int err = ((response.Length >= 14) ? BitConverter.ToUInt16(response, 10) : 10000);
				return new OResult<byte[]>(err, "PLC returned an error code: " + err + " Source: " + response.ToHexString(' '));
			}
			return base.UnpackResponseContent(send, response);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadCommand(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			using (List<byte[]>.Enumerator enumerator = oResult.Content.GetEnumerator())
			{
				if (enumerator.MoveNext())
				{
					byte[] current = enumerator.Current;
					OResult<byte[]> oResult2 = ReadFromCoreServer(current);
					if (!oResult2.IsSuccess)
					{
						return oResult2;
					}
					if (oResult2.Content.Length > 22)
					{
						return OResult.CreateSuccessResult(oResult2.Content.RemoveBegin(22));
					}
					return new OResult<byte[]>("Received data length is too short");
				}
			}
			return new OResult<byte[]>("No command was sent");
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadCommand(address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			using (List<byte[]>.Enumerator enumerator = oResult.Content.GetEnumerator())
			{
				if (enumerator.MoveNext())
				{
					byte[] current = enumerator.Current;
					OResult<byte[]> oResult2 = ReadFromCoreServer(current);
					if (!oResult2.IsSuccess)
					{
						return OResult.CreateFailedResult<bool[]>(oResult2);
					}
					if (oResult2.Content.Length > 22)
					{
						return OResult.CreateSuccessResult(oResult2.Content.RemoveBegin(22).ToBoolArray(length));
					}
					return new OResult<bool[]>("Received data length is too short");
				}
			}
			return new OResult<bool[]>("No command was sent");
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<List<byte[]>> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			foreach (byte[] item in oResult.Content)
			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(item);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			OResult<List<byte[]>> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
