			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(item);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadCommand(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte[]> content = oResult.Content;
