			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, bool[] value)
		{
			OResult<List<byte[]>> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte[]> content = oResult.Content;
			foreach (byte[] item in content)
			{
				OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(item);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 构建读取的报文，返回一个列表，包含了所有需要发送的报文内容<br />
		/// Build the message for reading, return a list that contains all the message content that needs to be sent
		/// </summary>
		/// <param name="address"></param>
		/// <param name="length"></param>
		/// <param name="isBit"></param>
		/// <returns></returns>
		public OResult<List<byte[]>> BuildReadCommand(string address, ushort length, bool isBit)
		{
			List<byte[]> list = new List<byte[]>();
			byte[] array = "16 00 01 03 01 00 00 00 01 00 01 00 00 00 40 00 60 00 10 00 00 00".ToHexBytes();
			OResult<byte[]> oResult = AnalysisAddressBytes(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			oResult.Content.CopyTo(array, 14);
			if (isBit)
			{
				array[18] = BitConverter.GetBytes(length)[0];
				array[19] = BitConverter.GetBytes(length)[1];
			}
			else
			{
				array[18] = BitConverter.GetBytes(length * 16)[0];
				array[19] = BitConverter.GetBytes(length * 16)[1];
				array[20] = BitConverter.GetBytes(length * 16)[2];
			}
			list.Add(array);
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 构建写入的报文，返回一个列表，包含了所有需要发送的报文内容<br />
		/// Build the message for writing, return a list that contains all the message content that needs to be sent
		/// </summary>
		/// <param name="address"></param>
		/// <param name="value"></param>
		/// <returns></returns>
		public OResult<List<byte[]>> BuildWriteCommand(string address, byte[] value)
		{
			List<byte[]> list = new List<byte[]>();
			byte[] array = new byte[22 + value.Length];
			"16 00 01 03 01 00 00 00 02 00 01 00 00 00 20 00 60 00 10 00 00 00".ToHexBytes().CopyTo(array, 0);
			OResult<byte[]> oResult = AnalysisAddressBytes(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			oResult.Content.CopyTo(array, 14);
			value.CopyTo(array, 22);
			array[0] = BitConverter.GetBytes(array.Length)[0];
			array[1] = BitConverter.GetBytes(array.Length)[1];
			array[18] = BitConverter.GetBytes(value.Length * 8)[0];
			array[19] = BitConverter.GetBytes(value.Length * 8)[1];
			array[20] = BitConverter.GetBytes(value.Length * 8)[2];
			list.Add(array);
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 构建写入的报文，返回一个列表，包含了所有需要发送的报文内容<br />
		/// </summary>
		/// <param name="address"></param>
		/// <param name="value"></param>
		/// <returns></returns>
		public OResult<List<byte[]>> BuildWriteCommand(string address, bool[] value)
		{
			byte[] array = value.ToByteArray();
			List<byte[]> list = new List<byte[]>();
			byte[] array2 = new byte[22 + array.Length];
			"16 00 01 03 01 00 00 00 02 00 01 00 00 00 20 00 60 00 10 00 00 00".ToHexBytes().CopyTo(array2, 0);
			OResult<byte[]> oResult = AnalysisAddressBytes(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<List<byte[]>>(oResult);
			}
			oResult.Content.CopyTo(array2, 14);
			array.CopyTo(array2, 22);
			array2[0] = BitConverter.GetBytes(array2.Length)[0];
			array2[1] = BitConverter.GetBytes(array2.Length)[1];
			array2[18] = BitConverter.GetBytes(value.Length)[0];
			array2[19] = BitConverter.GetBytes(value.Length)[1];
			array2[20] = BitConverter.GetBytes(value.Length)[2];
			list.Add(array2);
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 分析地址信息，返回一个3字节的数组，前两字节是地址信息，第三个字节包含了类型和位的信息<br />
		/// </summary>
		/// <param name="address">PLC的地址</param>
		/// <returns></returns>
		public static OResult<byte[]> AnalysisAddressBytes(string address)
		{
			try
			{
				byte[] array = new byte[4];
				byte b = 0;
				int value = 0;
				if (address.StartsWithAndNumber("W"))
				{
					b = 96;
				}
				else if (address.StartsWithAndNumber("D"))
				{
					b = 64;
				}
				else if (address.StartsWithAndNumber("R"))
				{
					b = 80;
				}
				else if (address.StartsWithAndNumber("X"))
				{
					b = 0;
					value = Convert.ToInt32(address.Substring(1), 8);
				}
				else if (address.StartsWithAndNumber("Y"))
				{
					b = 0;
					value = Convert.ToInt32(address.Substring(1), 8) + 524288;
				}
				else if (address.StartsWithAndNumber("M"))
				{
					b = 16;
					value = Convert.ToInt32(address.Substring(1));
				}
				else if (address.StartsWithAndNumber("S"))
				{
					b = 16;
					value = Convert.ToInt32(address.Substring(1)) + 524288;
				}
				else if (address.StartsWithAndNumber("B"))
				{
					b = 32;
					value = Convert.ToInt32(address.Substring(1));
				}
				else if (address.StartsWithNoCase("UB") || address.StartsWithNoCase("UW"))
				{
					b = 240;
					value = Convert.ToInt32(address.Substring(2), 16);
				}
				else
				{
					if (!address.StartsWithNoCase("U"))
					{
						return new OResult<byte[]>("Only support W type address");
					}
					b = 240;
					value = Convert.ToInt32(address.Substring(1), 16);
				}
				address = address.Substring(1);
				if (b == 240)
				{
					BitConverter.GetBytes(value).CopyTo(array, 0);
				}
				else if (b >= 64)
				{
					string[] array2 = address.SplitDot();
					value = ushort.Parse(array2[0]) * 16;
					if (array2.Length > 1)
					{
						value += SnetHelper.CalculateBitStartIndex(array2[1]);
					}
					array[0] = BitConverter.GetBytes(value)[0];
					array[1] = BitConverter.GetBytes(value)[1];
					array[2] = BitConverter.GetBytes(value)[2];
					array[2] = (byte)((array[2] & 0xF) | b);
				}
				else
				{
					array[0] = BitConverter.GetBytes(value)[0];
					array[1] = BitConverter.GetBytes(value)[1];
					array[2] = BitConverter.GetBytes(value)[2];
					array[2] = (byte)((array[2] & 0xF) | b);
				}
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address analysis failed: " + ex.Message);
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"InovanceEasyNet[{IpAddress}:{Port}]";
		}
	}
