		/// 实例化一个基于EasyNet协议虚拟汇川PLC对象，可以用来和<see cref="T:Snet.Driver.Profinet.Inovance.InovanceEasyNet" />进行通信测试。
		/// </summary>
		public InovanceEasyNetServer()
		{
			xBuffer = new SoftBuffer(65536);
			yBuffer = new SoftBuffer(65536);
			mBuffer = new SoftBuffer(65536);
			sBuffer = new SoftBuffer(65536);
			rBuffer = new SoftBuffer(131072);
			dBuffer = new SoftBuffer(131072);
			wBuffer = new SoftBuffer(131072);
			uBuffer = new SoftBuffer(131072);
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			return ByteTransformHelper.GetByteFromSoftBuffer(xBuffer, yBuffer, mBuffer, sBuffer, rBuffer, dBuffer, wBuffer, uBuffer).ToArray();
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			ByteTransformHelper.SetByteToSoftBuffer(content, 0, xBuffer, yBuffer, mBuffer, sBuffer, rBuffer, dBuffer, wBuffer, uBuffer);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Inovance.InovanceEasyNet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			try
			{
				if (address.StartsWithAndNumber("D"))
				{
					return OResult.CreateSuccessResult(dBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				}
				if (address.StartsWithAndNumber("R"))
				{
					return OResult.CreateSuccessResult(rBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				}
				if (address.StartsWithAndNumber("W"))
				{
					return OResult.CreateSuccessResult(wBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				}
				if (address.StartsWithAndNumber("UB") || address.StartsWithAndNumber("UW"))
				{
					return OResult.CreateSuccessResult(uBuffer.GetBytes(Convert.ToInt32(address.Substring(2), 16), length * 2));
				}
				if (address.StartsWithAndNumber("U"))
				{
					return OResult.CreateSuccessResult(uBuffer.GetBytes(Convert.ToInt32(address.Substring(1), 16), length * 2));
				}
				if (address.StartsWithAndNumber("X"))
				{
					return OResult.CreateSuccessResult(xBuffer.GetBool(Convert.ToInt32(address.Substring(1), 8), length * 16).ToByteArray());
				}
				if (address.StartsWithAndNumber("Y"))
				{
					return OResult.CreateSuccessResult(yBuffer.GetBool(Convert.ToInt32(address.Substring(1), 8), length * 16).ToByteArray());
				}
				if (address.StartsWithAndNumber("M"))
				{
					return OResult.CreateSuccessResult(mBuffer.GetBool(Convert.ToInt32(address.Substring(1)), length * 16).ToByteArray());
				}
				if (address.StartsWithAndNumber("S"))
				{
					return OResult.CreateSuccessResult(sBuffer.GetBool(Convert.ToInt32(address.Substring(1)), length * 16).ToByteArray());
				}
				if (address.StartsWithAndNumber("B"))
				{
					return OResult.CreateSuccessResult(bBuffer.GetBool(Convert.ToInt32(address.Substring(1)), length * 16).ToByteArray());
				}
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType + " Reason:" + ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			try
			{
				if (address.StartsWithAndNumber("D"))
				{
					dBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
				}
				if (address.StartsWithAndNumber("R"))
