		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new InovanceEasyNetMessage();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			return OResult.CreateSuccessResult(ReadFromNanoCore(receive));
		}

		private byte[] ReadFromNanoCore(byte[] receive)
		{
			if (receive[8] == 1)
			{
				return ReadByCommand(receive);
			}
			if (receive[8] == 2)
			{
				return WriteByCommand(receive);
			}
			return Encoding.ASCII.GetBytes("E0\r\n");
		}

		private byte[] GetReadBack(byte[] receive, SoftBuffer softBuffer, int address, int length)
		{
			byte[] array = softBuffer.GetBool(address, length).ToByteArray();
			byte[] array2 = new byte[receive.Length + array.Length];
			receive.CopyTo(array2, 0);
			array.CopyTo(array2, receive.Length);
			array2[0] = BitConverter.GetBytes(array2.Length)[0];
			array2[1] = BitConverter.GetBytes(array2.Length)[1];
			return array2;
		}

		private byte[] GetWriteBack(byte[] receive, int err)
		{
			if (err == 0)
			{
				return "09 00 01 03 01 00 00 00 06".ToHexBytes();
			}
			byte[] array = "0E 00 01 03 01 00 00 00 0F 00 81 00 00 00".ToHexBytes();
			BitConverter.GetBytes(err).CopyTo(array, 10);
			return array;
		}

		private byte[] ReadByCommand(byte[] receive)
		{
			try
			{
				int num = receive[16] & 0xF0;
				receive[16] = (byte)(receive[16] & 0xF);
				int num2 = BitConverter.ToInt32(new byte[4]
				{
					receive[14],
					receive[15],
					(byte)(receive[16] & 0xF),
					0
				}, 0);
				int length = BitConverter.ToInt32(receive, 18);
				switch (num)
				{
				case 0:
					if (num2 < 524288)
					{
						return GetReadBack(receive, xBuffer, num2, length);
					}
					return GetReadBack(receive, yBuffer, num2 - 524288, length);
				case 16:
					if (num2 < 524288)
					{
						return GetReadBack(receive, mBuffer, num2, length);
					}
					return GetReadBack(receive, sBuffer, num2 - 524288, length);
				case 32:
					return GetReadBack(receive, bBuffer, num2, length);
				case 64:
					return GetReadBack(receive, dBuffer, num2, length);
				case 80:
					return GetReadBack(receive, rBuffer, num2, length);
				case 96:
					return GetReadBack(receive, wBuffer, num2, length);
				case 240:
					return GetReadBack(receive, uBuffer, num2, length);
				default:
					return GetWriteBack(receive, 1);
				}
			}
			catch
			{
				return GetWriteBack(receive, 2);
			}
		}

		private byte[] WriteByCommand(byte[] receive)
		{
			if (!base.EnableWrite)
			{
				return GetWriteBack(receive, 3);
			}
			try
			{
				int num = receive[16] & 0xF0;
				receive[16] = (byte)(receive[16] & 0xF);
				int num2 = BitConverter.ToInt32(new byte[4]
				{
					receive[14],
					receive[15],
					(byte)(receive[16] & 0xF),
					0
				}, 0);
				int num3 = BitConverter.ToInt32(receive, 18);
				bool[] array = receive.RemoveBegin(22).ToBoolArray();
				if (array.Length > num3)
				{
					array = array.SelectBegin(num3);
				}
				switch (num)
				{
				case 0:
					if (num2 < 524288)
					{
						xBuffer.SetBool(array, num2);
					}
					else
					{
						yBuffer.SetBool(array, num2);
					}
					break;
				case 16:
					if (num2 < 524288)
					{
						mBuffer.SetBool(array, num2);
					}
					else
					{
						sBuffer.SetBool(array, num2);
					}
					break;
				case 32:
					bBuffer.SetBool(array, num2);
					break;
				case 64:
					dBuffer.SetBool(array, num2);
					break;
				case 80:
					rBuffer.SetBool(array, num2);
					break;
				case 96:
					wBuffer.SetBool(array, num2);
					break;
				case 240:
					uBuffer.SetBool(array, num2);
					break;
				}
				return GetWriteBack(receive, 0);
			}
			catch
			{
				return GetWriteBack(receive, 2);
			}
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			if (receivedLength < 1)
			{
				return false;
			}
			return buffer[receivedLength - 1] == 13;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"KeyenceNanoServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 汇川PLC的辅助类，提供一些地址解析的方法<br />
	/// Auxiliary class of Yaskawa robot, providing some methods of address resolution
	/// </summary>
	public class InovanceHelper
	{
		private static int CalculateStartAddress(string address)
		{
			if (address.IndexOf('.') < 0)
			{
				return int.Parse(address);
			}
			string[] array = address.SplitDot();
			return int.Parse(array[0]) * 8 + int.Parse(array[1]);
		}

		/// <summary>
		/// 按照字节读取汇川M地址的数据，地址示例： MB100，MB101，需要注意的是，MB100 及 MB101 的地址是 MW50 的数据。<br />
		/// Read the data of Inovance M address according to the byte, address example: MB100, MB101, it should be noted that the addresses of MB100 and MB101 are the data of MW50.
		/// </summary>
		/// <param name="modbus">汇川的PLC对象</param>
		/// <param name="address">地址信息</param>
		/// <returns>读取的结果数据</returns>
		public static OResult<byte> ReadByte(IModbus modbus, string address)
		{
			try
			{
				int num = 0;
				if (address.StartsWith("MB") || address.StartsWith("mb"))
				{
					num = Convert.ToInt32(address.Substring(2));
				}
				else if (address.StartsWith("M") || address.StartsWith("m"))
				{
					num = Convert.ToInt32(address.Substring(1));
				}
				else
				{
					new OResult<string>(StringResources.Language.NotSupportedDataType);
				}
				OResult<byte[]> oResult = modbus.Read("MW" + num / 2, 1);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte>(oResult);
				}
				return OResult.CreateSuccessResult((num % 2 == 0) ? oResult.Content[1] : oResult.Content[0]);
			}
			catch (Exception ex)
			{
				return new OResult<byte>("Address prase failed: " + ex.Message);
			}
		}

		internal static OResult<string> ReadAMString(IModbus modbus, string address, ushort length, Encoding encoding)
		{
			int num = Convert.ToInt32(address.Substring(address.Length - 1));
			address = address.Substring(0, address.Length - 1) + (num - 1);
			OResult<byte[]> oResult = modbus.Read(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			if (modbus.IsStringReverse)
			{
				oResult.Content = SoftBasic.BytesReverseByWord(oResult.Content);
			}
			oResult.Content = oResult.Content.RemoveBegin(1);
			return OResult.CreateSuccessResult(encoding.GetString(oResult.Content));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Inovance.InovanceHelper.ReadByte(Snet.Driver.ModBus.IModbus,System.String)" />
		public static async Task<OResult<byte>> ReadByteAsync(IModbus modbus, string address)
		{
			try
			{
				int offset = 0;
				if (address.StartsWith("MB", StringComparison.OrdinalIgnoreCase))
				{
					offset = Convert.ToInt32(address.Substring(2));
				}
				else if (address.StartsWith("M", StringComparison.OrdinalIgnoreCase))
				{
					offset = Convert.ToInt32(address.Substring(1));
				}
				else
				{
					new OResult<string>(StringResources.Language.NotSupportedDataType);
				}
				OResult<byte[]> oResult = await modbus.ReadAsync("MW" + offset / 2, 1);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte>(oResult);
				}
				return OResult.CreateSuccessResult((offset % 2 == 0) ? oResult.Content[1] : oResult.Content[0]);
			}
			catch (Exception ex)
			{
				return new OResult<byte>("Address prase failed: " + ex.Message);
			}
		}

		internal static async Task<OResult<string>> ReadAMStringAsync(IModbus modbus, string address, ushort length, Encoding encoding)
		{
			address = string.Concat(str1: (Convert.ToInt32(address.Substring(address.Length - 1)) - 1).ToString(), str0: address.Substring(0, address.Length - 1));
			OResult<byte[]> oResult = await modbus.ReadAsync(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			if (modbus.IsStringReverse)
			{
				oResult.Content = SoftBasic.BytesReverseByWord(oResult.Content);
			}
			oResult.Content = oResult.Content.RemoveBegin(1);
			return OResult.CreateSuccessResult(encoding.GetString(oResult.Content));
		}

		/// <summary>
		/// 根据汇川PLC的地址，解析出转换后的modbus协议信息，适用AM,H3U,H5U系列的PLC<br />
		/// According to the address of Inovance PLC, analyze the converted modbus protocol information, which is suitable for AM, H3U, H5U series PLC
		/// </summary>
		/// <param name="series">PLC的系列</param>
		/// <param name="address">汇川plc的地址信息</param>
		/// <param name="modbusCode">原始的对应的modbus信息</param>
		/// <returns>Modbus格式的地址</returns>
		public static OResult<string> PraseInovanceAddress(InovanceSeries series, string address, byte modbusCode)
		{
			return series switch
			{
				InovanceSeries.AM => PraseInovanceAMAddress(address, modbusCode), 
				InovanceSeries.H3U => PraseInovanceH3UAddress(address, modbusCode), 
				InovanceSeries.H5U => PraseInovanceH5UAddress(address, modbusCode), 
				InovanceSeries.Easy => PraseInovanceH5UAddress(address, modbusCode), 
				InovanceSeries.EVO => PraseInovanceEvoAddress(address, modbusCode), 
				_ => new OResult<string>($"[{series}] Not supported series of plc"), 
			};
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Inovance.InovanceHelper.PraseInovanceAddress(Snet.Driver.Profinet.Inovance.InovanceSeries,System.String,System.Byte)" />
		public static OResult<string> PraseInovanceAMAddress(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (address.StartsWithNoCase("QX"))
				{
					return OResult.CreateSuccessResult(text + CalculateStartAddress(address.Substring(2)));
				}
				if (address.StartsWithNoCase("Q"))
				{
					return OResult.CreateSuccessResult(text + CalculateStartAddress(address.Substring(1)));
				}
				if (address.StartsWithNoCase("IX"))
				{
					return OResult.CreateSuccessResult(text + "x=2;" + CalculateStartAddress(address.Substring(2)));
				}
				if (address.StartsWithNoCase("I"))
				{
					return OResult.CreateSuccessResult(text + "x=2;" + CalculateStartAddress(address.Substring(1)));
				}
				if (address.StartsWithNoCase("MW"))
				{
					return OResult.CreateSuccessResult(text + address.Substring(2));
				}
				if (address.StartsWithNoCase("MD"))
				{
					if ((modbusCode == 1 || modbusCode == 15 || modbusCode == 5) && address.IndexOf('.') > 0)
					{
						return OResult.CreateSuccessResult(text + address);
					}
					return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(2)) * 2);
				}
				if (address.StartsWithNoCase("MB"))
				{
					int num = Convert.ToInt32(address.Substring(2));
					if (num % 2 == 1)
					{
						return new OResult<string>("Address[" + address + "] " + StringResources.Language.AddressOffsetEven);
					}
					return OResult.CreateSuccessResult(text + num / 2);
				}
				if (address.StartsWithNoCase("MX"))
				{
					if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
					{
						if (address.IndexOf('.') > 0)
						{
							string[] array = address.Substring(2).SplitDot();
							int num2 = Convert.ToInt32(array[0]);
							int num3 = Convert.ToInt32(array[1]);
							return OResult.CreateSuccessResult(text + num2 / 2 + "." + (num2 % 2 * 8 + num3));
						}
						int num4 = Convert.ToInt32(address.Substring(2));
						return OResult.CreateSuccessResult(text + num4 / 2 + ".0");
					}
					int num5 = Convert.ToInt32(address.Substring(2));
					return OResult.CreateSuccessResult(text + num5 / 2);
				}
				if (address.StartsWithNoCase("M"))
				{
					return OResult.CreateSuccessResult(text + address.Substring(1));
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWithNoCase("SMX"))
					{
						return OResult.CreateSuccessResult(text + $"x={modbusCode + 48};" + CalculateStartAddress(address.Substring(3)));
					}
					if (address.StartsWithNoCase("SM"))
					{
						return OResult.CreateSuccessResult(text + $"x={modbusCode + 48};" + CalculateStartAddress(address.Substring(2)));
					}
				}
				else
				{
					if (address.StartsWithNoCase("SDW"))
					{
						return OResult.CreateSuccessResult(text + $"x={modbusCode + 48};" + address.Substring(3));
					}
					if (address.StartsWithNoCase("SD"))
					{
						return OResult.CreateSuccessResult(text + $"x={modbusCode + 48};" + address.Substring(2));
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}

		private static int CalculateH3UStartAddress(string address)
		{
			if (address.IndexOf('.') < 0)
			{
				return Convert.ToInt32(address, 8);
			}
			string[] array = address.SplitDot();
			return Convert.ToInt32(array[0], 8) * 8 + int.Parse(array[1]);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Inovance.InovanceHelper.PraseInovanceAddress(Snet.Driver.Profinet.Inovance.InovanceSeries,System.String,System.Byte)" />
		public static OResult<string> PraseInovanceH3UAddress(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (ModbusHelper.TransAddressToModbus(text, address, new string[2] { "X", "Y" }, new int[2] { 63488, 64512 }, CalculateH3UStartAddress, out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
					if (ModbusHelper.TransAddressToModbus(text, address, new string[4] { "SM", "S", "T", "C" }, new int[4] { 9216, 57344, 61440, 62464 }, out string newAddress2))
					{
						return OResult.CreateSuccessResult(newAddress2);
					}
					if (address.StartsWith("M") || address.StartsWith("m"))
					{
						int num = Convert.ToInt32(address.Substring(1));
						if (num >= 8000)
						{
							return OResult.CreateSuccessResult(text + (num - 8000 + 8000));
						}
						return OResult.CreateSuccessResult(text + num);
					}
					if (ModbusHelper.TransPointAddressToModbus(text, address, new string[3] { "D", "SD", "R" }, new int[3] { 0, 9216, 12288 }, out string newAddress3))
					{
						return OResult.CreateSuccessResult(newAddress3);
					}
				}
				else
				{
					if (ModbusHelper.TransAddressToModbus(text, address, new string[4] { "D", "SD", "R", "T" }, new int[4] { 0, 9216, 12288, 61440 }, out string newAddress4))
					{
						return OResult.CreateSuccessResult(newAddress4);
					}
					if (address.StartsWith("C", StringComparison.InvariantCultureIgnoreCase))
					{
						int num2 = Convert.ToInt32(address.Substring(1));
						if (num2 >= 200)
						{
							return OResult.CreateSuccessResult(text + ((num2 - 200) * 2 + 63232));
						}
						return OResult.CreateSuccessResult(text + (num2 + 62464));
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Inovance.InovanceHelper.PraseInovanceAddress(Snet.Driver.Profinet.Inovance.InovanceSeries,System.String,System.Byte)" />
		public static OResult<string> PraseInovanceH5UAddress(string address, byte modbusCode)
		{
			try
			{
				string station = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					station = $"s={oResult.Content};";
				}
				string newAddress4;
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (ModbusHelper.TransAddressToModbus(station, address, new string[2] { "X", "Y" }, new int[2] { 63488, 64512 }, CalculateH3UStartAddress, out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
					if (ModbusHelper.TransAddressToModbus(station, address, new string[3] { "S", "B", "M" }, new int[3] { 57344, 12288, 0 }, out string newAddress2))
					{
						return OResult.CreateSuccessResult(newAddress2);
					}
					if (ModbusHelper.TransPointAddressToModbus(station, address, new string[2] { "D", "R" }, new int[2] { 0, 12288 }, out string newAddress3))
					{
						return OResult.CreateSuccessResult(newAddress3);
					}
				}
				else if (ModbusHelper.TransAddressToModbus(station, address, new string[2] { "D", "R" }, new int[2] { 0, 12288 }, out newAddress4))
				{
					return OResult.CreateSuccessResult(newAddress4);
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Inovance.InovanceHelper.PraseInovanceAddress(Snet.Driver.Profinet.Inovance.InovanceSeries,System.String,System.Byte)" />
		public static OResult<string> PraseInovanceEvoAddress(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWithNoCase("QX"))
					{
						return OResult.CreateSuccessResult(text + CalculateStartAddress(address.Substring(2)));
					}
					if (address.StartsWithNoCase("Q"))
					{
						return OResult.CreateSuccessResult(text + CalculateStartAddress(address.Substring(1)));
					}
					if (address.StartsWithNoCase("IX"))
					{
						return OResult.CreateSuccessResult(text + "x=2;" + CalculateStartAddress(address.Substring(2)));
					}
					if (address.StartsWithNoCase("I"))
					{
						return OResult.CreateSuccessResult(text + "x=2;" + CalculateStartAddress(address.Substring(1)));
					}
					if (address.StartsWithNoCase("MX"))
					{
						if (address.IndexOf('.') > 0)
						{
							string[] array = address.Substring(2).SplitDot();
							int num = Convert.ToInt32(array[0]);
							int num2 = Convert.ToInt32(array[1]);
							return OResult.CreateSuccessResult(text + num / 2 + "." + (num % 2 * 8 + num2));
						}
						int num3 = Convert.ToInt32(address.Substring(2));
						return OResult.CreateSuccessResult(text + num3 / 2 + ".0");
					}
					if (ModbusHelper.TransPointAddressToModbus(text, address, new string[2] { "MW", "MD" }, new int[2], out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
				}
				else
				{
					if (address.StartsWithNoCase("MW"))
					{
						return OResult.CreateSuccessResult(text + address.Substring(2));
					}
					if (address.StartsWithNoCase("MD"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(2)) * 2);
					}
					if (address.StartsWithNoCase("MX"))
					{
						int num4 = Convert.ToInt32(address.Substring(2));
						return OResult.CreateSuccessResult(text + num4 / 2);
					}
					if (address.StartsWithNoCase("MB"))
					{
						int num5 = Convert.ToInt32(address.Substring(2));
						if (num5 % 2 == 1)
						{
							return new OResult<string>("Address[" + address + "] " + StringResources.Language.AddressOffsetEven);
						}
						return OResult.CreateSuccessResult(text + num5 / 2);
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}
	}
	/// <summary>
	/// 汇川的串口通信协议，A适用于AM400、 AM400_800、 AC800、H3U, XP, H5U 等系列底层走的是MODBUS-RTU协议，地址说明参见标记<br />
	/// Huichuan's serial communication protocol is applicable to AM400, AM400_800, AC800 and other series. The bottom layer is MODBUS-RTU protocol. For the address description, please refer to the mark
	/// </summary>
	/// <remarks>
	/// AM400_800 的元件有 Q 区，I 区，M 区这三种，分别都可以按位，按字节，按字和按双字进行访问，在本组件的条件下，仅支持按照位，字访问。<br />
	/// 位地址支持 Q, I, M 地址类型，字地址支持 SM, SD，支持对字地址的位访问，例如 ReadBool("SD0.5");
	/// H3U 系列控制器支持 M/SM/S/T/C/X/Y 等 bit 型变量（也称线圈） 的访问、 D/SD/R/T/C 等 word 型变量的访问；<br />
	/// H5U 系列控制器支持 M/B/S/X/Y 等 bit 型变量（也称线圈） 的访问、 D/R 等 word 型变量的访问；内部 W 元件，不支持通信访问。<br />
	/// </remarks>
	public class InovanceSerial : ModbusRtu
	{
		/// <summary>
		/// 获取或设置汇川的系列，默认为AM系列
		/// </summary>
		public InovanceSeries Series { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public InovanceSerial()
		{
			Series = InovanceSeries.AM;
			base.DataFormat = DataFormat.CDAB;
		}

		/// <summary>
		/// 指定服务器地址，端口号，客户端自己的站号来初始化<br />
		/// Specify the server address, port number, and client's own station number to initialize
		/// </summary>
		/// <param name="station">客户端自身的站号</param>
		public InovanceSerial(byte station = 1)
			: base(station)
		{
			Series = InovanceSeries.AM;
			base.DataFormat = DataFormat.CDAB;
		}

		/// <summary>
		/// 指定服务器地址，端口号，客户端自己的站号来初始化<br />
		/// Specify the server address, port number, and client's own station number to initialize
		/// </summary>
		/// <param name="series">PLC的系列选择</param>
		/// <param name="station">客户端自身的站号</param>
		public InovanceSerial(InovanceSeries series, byte station = 1)
			: base(station)
		{
			Series = series;
			Series = InovanceSeries.AM;
			base.DataFormat = DataFormat.CDAB;
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Inovance.InovanceHelper.ReadByte(Snet.Driver.ModBus.IModbus,System.String)" />
		public OResult<byte> ReadByte(string address)
		{
			return InovanceHelper.ReadByte(this, address);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Inovance.InovanceHelper.ReadByte(Snet.Driver.ModBus.IModbus,System.String)" />
		public async Task<OResult<byte>> ReadByteAsync(string address)
		{
			return await InovanceHelper.ReadByteAsync(this, address);
		}

		/// <inheritdoc />
		public override OResult<string> TranslateToModbusAddress(string address, byte modbusCode)
		{
			return InovanceHelper.PraseInovanceAddress(Series, address, modbusCode);
		}

		/// <inheritdoc />
		public override OResult<string> ReadString(string address, ushort length, Encoding encoding)
		{
			if (Series == InovanceSeries.AM && Regex.IsMatch(address, "MB[0-9]*[13579]$", RegexOptions.IgnoreCase))
			{
				return InovanceHelper.ReadAMString(this, address, length, encoding);
			}
			return base.ReadString(address, length, encoding);
		}

		/// <inheritdoc />
		public override async Task<OResult<string>> ReadStringAsync(string address, ushort length, Encoding encoding)
		{
			if (Series == InovanceSeries.AM && Regex.IsMatch(address, "MB[0-9]*[13579]$", RegexOptions.IgnoreCase))
			{
				return await InovanceHelper.ReadAMStringAsync(this, address, length, encoding);
			}
			return await base.ReadStringAsync(address, length, encoding);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"InovanceSerial<{Series}>[{base.PortName}:{base.BaudRate}]";
		}
	}
	/// <summary>
	/// 汇川的串口转网口通信协议，A适用于AM400、 AM400_800、 AC800、H3U, XP, H5U 等系列底层走的是MODBUS-RTU协议，地址说明参见标记<br />
	/// Huichuan's serial communication protocol is applicable to AM400, AM400_800, AC800 and other series. The bottom layer is MODBUS-RTU protocol. For the address description, please refer to the mark
	/// </summary>
	/// <remarks>
	/// AM400_800 的元件有 Q 区，I 区，M 区这三种，分别都可以按位，按字节，按字和按双字进行访问，在本组件的条件下，仅支持按照位，字访问。<br />
	/// 位地址支持 Q, I, M 地址类型，字地址支持 SM, SD，支持对字地址的位访问，例如 ReadBool("SD0.5");<br />
	/// H3U 系列控制器支持 M/SM/S/T/C/X/Y 等 bit 型变量（也称线圈） 的访问、 D/SD/R/T/C 等 word 型变量的访问；<br />
	/// H5U 系列控制器支持 M/B/S/X/Y 等 bit 型变量（也称线圈） 的访问、 D/R 等 word 型变量的访问；内部 W 元件，不支持通信访问。<br />
	/// </remarks>
	public class InovanceSerialOverTcp : ModbusRtuOverTcp
	{
		/// <summary>
		/// 获取或设置汇川的系列，默认为AM系列
		/// </summary>
		public InovanceSeries Series { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public InovanceSerialOverTcp()
		{
			Series = InovanceSeries.AM;
			base.DataFormat = DataFormat.CDAB;
		}

		/// <summary>
		/// 通过指定站号，ip地址，端口号来实例化一个新的对象
		/// </summary>
		/// <param name="ipAddress">Ip地址</param>
