namespace Snet.Driver.Profinet.IDCard
{
	/// <summary>
	/// 身份证的信息类
	/// </summary>
	public class IdentityCard
	{
		/// <summary>
		/// 名字
		/// </summary>
		public string Name { get; set; }

		/// <summary>
		/// 性别
		/// </summary>
		public string Sex { get; set; }

		/// <summary>
		/// 身份证号
		/// </summary>
		public string Id { get; set; }

		/// <summary>
		/// 民族
		/// </summary>
		public string Nation { get; set; }

		/// <summary>
		/// 生日
		/// </summary>
		public DateTime Birthday { get; set; }

		/// <summary>
		/// 地址
		/// </summary>
		public string Address { get; set; }

		/// <summary>
		/// 发证机关
		/// </summary>
		public string Organ { get; set; }

		/// <summary>
		/// 有效期日期的起始日期
		/// </summary>
		public DateTime ValidityStartDate { get; set; }

		/// <summary>
		/// 有效期日期的结束日期
		/// </summary>
		public DateTime ValidityEndDate { get; set; }

		/// <summary>
		/// 头像信息
		/// </summary>
		public byte[] Portrait { get; set; }

		/// <summary>
		/// 返回表示当前对象的字符串
		/// </summary>
		/// <returns>字符串</returns>
		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("姓名：" + Name);
			stringBuilder.Append(Environment.NewLine);
			stringBuilder.Append("性别：" + Sex);
			stringBuilder.Append(Environment.NewLine);
			stringBuilder.Append("民族：" + Nation);
			stringBuilder.Append(Environment.NewLine);
			stringBuilder.Append("身份证号：" + Id);
			stringBuilder.Append(Environment.NewLine);
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(8, 3, stringBuilder2);
			handler.AppendLiteral("出身日期：");
			handler.AppendFormatted(Birthday.Year);
			handler.AppendLiteral("年");
			handler.AppendFormatted(Birthday.Month);
			handler.AppendLiteral("月");
			handler.AppendFormatted(Birthday.Day);
			handler.AppendLiteral("日");
			stringBuilder3.Append(ref handler);
			stringBuilder.Append(Environment.NewLine);
			stringBuilder.Append("地址：" + Address);
			stringBuilder.Append(Environment.NewLine);
			stringBuilder.Append("发证机关：" + Organ);
			stringBuilder.Append(Environment.NewLine);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder4 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(14, 6, stringBuilder2);
			handler.AppendLiteral("有效日期：");
			handler.AppendFormatted(ValidityStartDate.Year);
			handler.AppendLiteral("年");
			handler.AppendFormatted(ValidityStartDate.Month);
			handler.AppendLiteral("月");
			handler.AppendFormatted(ValidityStartDate.Day);
			handler.AppendLiteral("日 - ");
			handler.AppendFormatted(ValidityEndDate.Year);
			handler.AppendLiteral("年");
			handler.AppendFormatted(ValidityEndDate.Month);
			handler.AppendLiteral("月");
			handler.AppendFormatted(ValidityEndDate.Day);
			handler.AppendLiteral("日");
			stringBuilder4.Append(ref handler);
			stringBuilder.Append(Environment.NewLine);
			return stringBuilder.ToString();
		}
	}
	/// <summary>
	/// 基于SAM协议的串口通信类，支持读取身份证的数据信息，详细参见API文档<br />
	/// Network class implemented by Tcp based on the SAM protocol, which supports reading ID card data information, 
	/// see API documentation for details
	/// </summary>
	/// <example>
	/// 在使用之前需要实例化当前的对象，然后根据实际的情况填写好串口的信息，否则连接不上去。
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SAMSerialSample.cs" region="Sample1" title="实例化操作" />
	/// 在实际的读取，我们一般放在后台进行循环扫描的操作，参见下面的代码
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SAMSerialSample.cs" region="Sample2" title="基本的读取操作" />
	/// </example>
	public class SAMSerial : SerialBase
	{
		/// <inheritdoc cref="M:Snet.Driver.Profinet.IDCard.SAMTcpNet.#ctor" />
		public SAMSerial()
		{
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SAMMessage();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.IDCard.SAMTcpNet.ReadSafeModuleNumber" />
		public OResult<string> ReadSafeModuleNumber()
		{
			byte[] send = PackToSAMCommand(BuildReadCommand(18, byte.MaxValue, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			return ExtractSafeModuleNumber(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.IDCard.SAMTcpNet.CheckSafeModuleStatus" />
		public OResult CheckSafeModuleStatus()
		{
			byte[] send = PackToSAMCommand(BuildReadCommand(18, byte.MaxValue, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			if (oResult.Content[9] != 144)
			{
				return new OResult(GetErrorDescription(oResult.Content[9]));
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.IDCard.SAMTcpNet.SearchCard" />
		public OResult SearchCard()
		{
			byte[] send = PackToSAMCommand(BuildReadCommand(32, 1, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			if (oResult.Content[9] != 159)
			{
				return new OResult(GetErrorDescription(oResult.Content[9]));
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.IDCard.SAMTcpNet.SelectCard" />
		public OResult SelectCard()
		{
			byte[] send = PackToSAMCommand(BuildReadCommand(32, 2, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			if (oResult.Content[9] != 144)
			{
				return new OResult(GetErrorDescription(oResult.Content[9]));
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.IDCard.SAMTcpNet.ReadCard" />
		public OResult<IdentityCard> ReadCard()
		{
			byte[] send = PackToSAMCommand(BuildReadCommand(48, 1, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<IdentityCard>(oResult);
			}
			OResult oResult2 = CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<IdentityCard>(oResult2);
			}
			return ExtractIdentityCard(oResult.Content);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SAMSerial[{base.PortName}:{base.BaudRate}]";
		}

		/// <summary>
		/// 将指令进行打包成可以发送的数据对象
		/// </summary>
		/// <param name="command">命令信息</param>
		/// <returns>字节数组</returns>
		public static byte[] PackToSAMCommand(byte[] command)
		{
			byte[] array = new byte[command.Length + 8];
			array[0] = 170;
			array[1] = 170;
			array[2] = 170;
			array[3] = 150;
			array[4] = 105;
			array[5] = BitConverter.GetBytes(array.Length - 7)[1];
			array[6] = BitConverter.GetBytes(array.Length - 7)[0];
			command.CopyTo(array, 7);
			int num = 0;
			for (int i = 5; i < array.Length - 1; i++)
			{
				num ^= array[i];
			}
			array[^1] = (byte)num;
			return array;
		}

		/// <summary>
		/// 根据SAM的实际的指令，来生成实际的指令信息
		/// </summary>
		/// <param name="cmd">命令码</param>
		/// <param name="para">参数信息</param>
		/// <param name="data">数据内容</param>
		/// <returns>字符串的结果信息</returns>
		public static byte[] BuildReadCommand(byte cmd, byte para, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[2 + data.Length];
			array[0] = cmd;
			array[1] = para;
			data.CopyTo(array, 2);
			return array;
		}

		/// <summary>
		/// 检查当前的接收数据信息是否一条完整的数据信息
		/// </summary>
		/// <param name="input">输入的信息</param>
		/// <returns>是否接收完成</returns>
		public static bool CheckADSCommandCompletion(List<byte> input)
		{
			if (input != null && input.Count < 8)
			{
				return false;
			}
			if (input[5] * 256 + input[6] > input.Count - 7)
			{
				return false;
			}
			return true;
		}

		/// <summary>
		/// 检查当前的指令是否是正确的
		/// </summary>
		/// <param name="input">输入的指令信息</param>
		/// <returns>是否校验成功</returns>
		public static OResult CheckADSCommandAndSum(byte[] input)
		{
			if (input != null && input.Length < 8)
			{
				return new OResult(StringResources.Language.SAMReceiveLengthMustLargerThan8);
			}
			if (input[0] != 170 || input[1] != 170 || input[2] != 170 || input[3] != 150 || input[4] != 105)
			{
				return new OResult(StringResources.Language.SAMHeadCheckFailed);
			}
			if (input[5] * 256 + input[6] != input.Length - 7)
			{
				return new OResult(StringResources.Language.SAMLengthCheckFailed);
			}
			int num = 0;
			for (int i = 5; i < input.Length - 1; i++)
			{
				num ^= input[i];
			}
			if (num != input[^1])
			{
				return new OResult(StringResources.Language.SAMSumCheckFailed);
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 提炼安全的模块数据信息
		/// </summary>
		/// <param name="data">数据</param>
		/// <returns>结果对象</returns>
		public static OResult<string> ExtractSafeModuleNumber(byte[] data)
		{
			try
			{
				if (data[9] != 144)
				{
					return new OResult<string>(GetErrorDescription(data[9]));
				}
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append(data[10].ToString("D2"));
				stringBuilder.Append(".");
				stringBuilder.Append(data[12].ToString("D2"));
				stringBuilder.Append("-");
				stringBuilder.Append(BitConverter.ToInt32(data, 14).ToString());
				stringBuilder.Append("-");
				stringBuilder.Append(BitConverter.ToInt32(data, 18).ToString("D9"));
				stringBuilder.Append("-");
				stringBuilder.Append(BitConverter.ToInt32(data, 22).ToString("D9"));
				return OResult.CreateSuccessResult(stringBuilder.ToString());
			}
			catch (Exception ex)
			{
				return new OResult<string>("Error:" + ex.Message + "  Source Data: " + SoftBasic.ByteToHexString(data));
			}
		}

		/// <summary>
		/// 从数据中提取出真实的身份证信息
		/// </summary>
		/// <param name="data">原始数据内容</param>
		/// <returns>包含结果对象的身份证数据</returns>
		public static OResult<IdentityCard> ExtractIdentityCard(byte[] data)
		{
			try
			{
				if (data[9] != 144)
				{
					return new OResult<IdentityCard>(GetErrorDescription(data[9]));
				}
				string text = Encoding.Unicode.GetString(data, 14, 256);
				byte[] portrait = SoftBasic.ArraySelectMiddle(data, 270, 1024);
				return OResult.CreateSuccessResult(new IdentityCard
				{
					Name = text.Substring(0, 15),
					Sex = ((text.Substring(15, 1) == "1") ? "男" : ((text.Substring(15, 1) == "2") ? "女" : "未知")),
					Nation = GetNationText(Convert.ToInt32(text.Substring(16, 2))),
					Birthday = new DateTime(int.Parse(text.Substring(18, 4)), int.Parse(text.Substring(22, 2)), int.Parse(text.Substring(24, 2))),
					Address = text.Substring(26, 35),
					Id = text.Substring(61, 18),
					Organ = text.Substring(79, 15),
					ValidityStartDate = new DateTime(int.Parse(text.Substring(94, 4)), int.Parse(text.Substring(98, 2)), int.Parse(text.Substring(100, 2))),
					ValidityEndDate = new DateTime(int.Parse(text.Substring(102, 4)), int.Parse(text.Substring(106, 2)), int.Parse(text.Substring(108, 2))),
					Portrait = portrait
				});
			}
			catch (Exception ex)
			{
				return new OResult<IdentityCard>(ex.Message);
			}
		}

		/// <summary>
		/// 根据民族的代号来获取到民族的文本描述信息
		/// </summary>
		/// <param name="nation">民族代码</param>
		/// <returns>民族的文本信息</returns>
		public static string GetNationText(int nation)
		{
			return nation switch
			{
				1 => "汉", 
				2 => "蒙古", 
				3 => "回", 
				4 => "藏", 
				5 => "维吾尔", 
				6 => "苗", 
				7 => "彝", 
				8 => "壮", 
				9 => "布依", 
				10 => "朝鲜", 
				11 => "满", 
				12 => "侗", 
				13 => "瑶", 
				14 => "白", 
				15 => "土家", 
				16 => "哈尼", 
				17 => "哈萨克", 
