	/// <summary>
	/// 基于SAM协议的Tcp实现的网络类，支持读取身份证的数据信息，通过透传的形式实现，除了初始化和串口类不一致，调用方法是几乎一模一样的，详细参见API文档<br />
	/// The network class implemented by Tcp based on the SAM protocol supports reading ID card data information and is implemented in the form of transparent transmission. 
	/// Except for the inconsistency between the initialization and the serial port class, the calling method is almost the same. 
	/// See the API documentation for details
	/// </summary>
	/// <example>
	/// 在使用之前需要实例化当前的对象，然后根据实际的情况填写好串口的信息，否则连接不上去。
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SAMSerialSample.cs" region="Sample3" title="实例化操作" />
	/// 在实际的读取，我们一般放在后台进行循环扫描的操作，参见下面的代码
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SAMSerialSample.cs" region="Sample4" title="基本的读取操作" />
	/// 当然也支持全异步的操作了，就是方法的名称改改
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SAMSerialSample.cs" region="Sample5" title="实例化操作" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\SAMSerialSample.cs" region="Sample6" title="基本的读取操作" />
	/// </example>
	public class SAMTcpNet : NetworkDoubleBase
	{
		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public SAMTcpNet()
		{
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 通过指定的ip地址以及端口来实例化对象<br />
		/// Instantiate the object with the specified IP address and port
		/// </summary>
		/// <param name="ipAddress">ip地址</param>
		/// <param name="port">端口号</param>
		public SAMTcpNet(string ipAddress, int port)
		{
			IpAddress = ipAddress;
			Port = port;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SAMMessage();
		}

		/// <summary>
		/// 读取身份证设备的安全模块号<br />
		/// Read the security module number of the ID device
		/// </summary>
		/// <returns>结果数据内容</returns>
		public OResult<string> ReadSafeModuleNumber()
		{
			byte[] send = SAMSerial.PackToSAMCommand(SAMSerial.BuildReadCommand(18, byte.MaxValue, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = SAMSerial.CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			return SAMSerial.ExtractSafeModuleNumber(oResult.Content);
		}

		/// <summary>
		/// 检测安全模块状态<br />
		/// Detecting Security Module Status
		/// </summary>
		/// <returns>返回是否检测成功</returns>
		public OResult CheckSafeModuleStatus()
		{
			byte[] send = SAMSerial.PackToSAMCommand(SAMSerial.BuildReadCommand(18, byte.MaxValue, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = SAMSerial.CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			if (oResult.Content[9] != 144)
			{
				return new OResult(SAMSerial.GetErrorDescription(oResult.Content[9]));
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 寻找卡片，并返回是否成功<br />
		/// Find cards and return success
		/// </summary>
		/// <returns>是否寻找成功</returns>
		public OResult SearchCard()
		{
			byte[] send = SAMSerial.PackToSAMCommand(SAMSerial.BuildReadCommand(32, 1, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = SAMSerial.CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			if (oResult.Content[9] != 159)
			{
				return new OResult(SAMSerial.GetErrorDescription(oResult.Content[9]));
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 选择卡片，并返回是否成功<br />
		/// Select card and return success
		/// </summary>
		/// <returns>是否寻找成功</returns>
		public OResult SelectCard()
		{
			byte[] send = SAMSerial.PackToSAMCommand(SAMSerial.BuildReadCommand(32, 2, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = SAMSerial.CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			if (oResult.Content[9] != 144)
			{
				return new OResult(SAMSerial.GetErrorDescription(oResult.Content[9]));
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 读取卡片，如果成功的话，就返回身份证的所有的信息<br />
		/// Read the card, if successful, return all the information of the ID cards
		/// </summary>
		/// <returns>是否寻找成功</returns>
		public OResult<IdentityCard> ReadCard()
		{
			byte[] send = SAMSerial.PackToSAMCommand(SAMSerial.BuildReadCommand(48, 1, null));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<IdentityCard>(oResult);
			}
			OResult oResult2 = SAMSerial.CheckADSCommandAndSum(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<IdentityCard>(oResult2);
			}
			return SAMSerial.ExtractIdentityCard(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.IDCard.SAMTcpNet.ReadSafeModuleNumber" />
		public async Task<OResult<string>> ReadSafeModuleNumberAsync()
		{
			byte[] send = SAMSerial.PackToSAMCommand(SAMSerial.BuildReadCommand(18, byte.MaxValue, null));
