		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.GE.GeSRTPNet.ReadByte(System.String)" />
		public async Task<OResult<byte>> ReadByteAsync(string address)
		{
			OResult<GeSRTPAddress> oResult = GeSRTPAddress.ParseFrom(address, 1, isBit: true);
			if (!oResult.IsSuccess)
			{
