		/// <inheritdoc cref="M:Snet.Driver.Profinet.GE.GeSRTPNet.Write(System.String,System.Byte)" />
		public async Task<OResult> WriteAsync(string address, byte value)
		{
			OResult<GeSRTPAddress> oResult = GeSRTPAddress.ParseFrom(address, 1, isBit: true);
