			}
			return await WriteAsync(address, new byte[1] { value });
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.GE.GeSRTPNet.ReadBool(System.String,System.UInt16)" />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			OResult<GeSRTPAddress> analysis = GeSRTPAddress.ParseFrom(address, length, isBit: true);
			if (!analysis.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(analysis);
			}
			OResult<byte[]> oResult = GeHelper.BuildReadCommand(incrementCount.GetCurrentValue(), analysis.Content);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			OResult<byte[]> oResult3 = GeHelper.ExtraResponseContent(oResult2.Content);
			if (!oResult3.IsSuccess)
