				return OResult.CreateFailedResult<bool[]>(oResult3);
			}
			return OResult.CreateSuccessResult(oResult3.Content.ToBoolArray().SelectMiddle(analysis.Content.AddressStart % 8, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.GE.GeSRTPNet.Write(System.String,System.Boolean[])" />
		public override async Task<OResult> WriteAsync(string address, bool[] value)
