	/// <summary>
	/// Ge的SRTP协议实现的虚拟PLC，支持I,Q,M,T,SA,SB,SC,S,G的位和字节读写，支持AI,AQ,R的字读写操作，支持读取当前时间及程序名称。<br />
	/// Virtual PLC implemented by Ge's SRTP protocol, supports bit and byte read and write of I, Q, M, T, SA, SB, SC, S, G, 
	/// supports word read and write operations of AI, AQ, R, and supports reading Current time and program name.
	/// </summary>
	/// <remarks>
	/// 实例化之后，直接调用 <see cref="M:Snet.Driver.Core.Net.NetworkServerBase.ServerStart(System.Int32)" /> 方法就可以通信及交互，所有的地址都是从1开始的，地址示例：M1,M100, R1，
	/// 具体的用法参考 Snet.DriverDemo 相关界面的源代码。
	/// </remarks>
	/// <example>
	/// 地址的示例，参考 <see cref="T:Snet.Driver.Profinet.GE.GeSRTPNet" /> 相关的示例说明
	/// </example>
	public class GeSRTPServer : DeviceServer
	{
		private SoftBuffer iBuffer;

		private SoftBuffer qBuffer;

		private SoftBuffer mBuffer;

		private SoftBuffer tBuffer;

		private SoftBuffer saBuffer;

		private SoftBuffer sbBuffer;

		private SoftBuffer scBuffer;

		private SoftBuffer sBuffer;

		private SoftBuffer gBuffer;

		private SoftBuffer aiBuffer;

		private SoftBuffer aqBuffer;

		private SoftBuffer rBuffer;

		private const int DataPoolLength = 65536;

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public GeSRTPServer()
		{
			iBuffer = new SoftBuffer(65536);
			qBuffer = new SoftBuffer(65536);
			mBuffer = new SoftBuffer(65536);
			tBuffer = new SoftBuffer(65536);
			saBuffer = new SoftBuffer(65536);
			sbBuffer = new SoftBuffer(65536);
			scBuffer = new SoftBuffer(65536);
			sBuffer = new SoftBuffer(65536);
			gBuffer = new SoftBuffer(65536);
			aiBuffer = new SoftBuffer(131072);
			aqBuffer = new SoftBuffer(131072);
			rBuffer = new SoftBuffer(131072);
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.GE.GeSRTPNet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<GeSRTPAddress> oResult = GeSRTPAddress.ParseFrom(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(ReadByCommand(oResult.Content.DataCode, (ushort)oResult.Content.AddressStart, oResult.Content.Length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.GE.GeSRTPNet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<GeSRTPAddress> oResult = GeSRTPAddress.ParseFrom(address, (ushort)value.Length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return WriteByCommand(oResult.Content.DataCode, (ushort)oResult.Content.AddressStart, oResult.Content.Length, value);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.GE.GeSRTPNet.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<GeSRTPAddress> oResult = GeSRTPAddress.ParseFrom(address, length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			bool isBit;
			return OResult.CreateSuccessResult(GetSoftBufferFromDataCode(oResult.Content.DataCode, out isBit).GetBool(oResult.Content.AddressStart, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.GE.GeSRTPNet.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			OResult<GeSRTPAddress> oResult = GeSRTPAddress.ParseFrom(address, (ushort)value.Length, isBit: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			GetSoftBufferFromDataCode(oResult.Content.DataCode, out var _).SetBool(value, oResult.Content.AddressStart);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new GeSRTPMessage();
		}

		/// <inheritdoc />
		protected override OResult ThreadPoolLoginAfterClientCheck(PipeSession session, IPEndPoint endPoint)
		{
			CommunicationPipe communication = session.Communication;
			OResult<byte[]> oResult = communication.ReceiveMessage(new GeSRTPMessage(), null, useActivePush: false, null, delegate(byte[] m)
			{
				LogRevcMessage(m, session);
			});
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			byte[] array = new byte[56];
			array[0] = 1;
			array[8] = 15;
			LogSendMessage(array, session);
			OResult oResult2 = communication.Send(array);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return base.ThreadPoolLoginAfterClientCheck(session, endPoint);
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive[0] == 0 && receive[9] == 0 && receive[42] == 0)
			{
				byte[] array = new byte[56];
				array[0] = 1;
				array[8] = 15;
				return OResult.CreateSuccessResult(array);
			}
			return OResult.CreateSuccessResult((receive[42] == 4) ? ReadByCommand(receive) : ((receive[42] == 1) ? ReadProgramNameByCommand(receive) : ((receive[42] == 37) ? ReadDateTimeByCommand(receive) : ((receive[50] != 7) ? null : WriteByCommand(receive)))));
		}

		private SoftBuffer GetSoftBufferFromDataCode(byte code, out bool isBit)
		{
			switch (code)
			{
			case 70:
				isBit = true;
				return iBuffer;
			case 16:
				isBit = false;
				return iBuffer;
			case 72:
				isBit = true;
				return qBuffer;
			case 66:
				isBit = false;
				return qBuffer;
			case 76:
				isBit = true;
				return mBuffer;
			case 22:
				isBit = false;
				return mBuffer;
			case 74:
				isBit = true;
				return tBuffer;
			case 20:
				isBit = false;
				return tBuffer;
			case 78:
				isBit = true;
				return saBuffer;
			case 24:
				isBit = false;
				return saBuffer;
			case 80:
				isBit = true;
				return sbBuffer;
			case 26:
				isBit = false;
				return sbBuffer;
			case 82:
				isBit = true;
				return scBuffer;
			case 28:
				isBit = false;
				return scBuffer;
			case 84:
				isBit = true;
				return tBuffer;
			case 30:
				isBit = false;
				return tBuffer;
			case 86:
				isBit = true;
				return gBuffer;
			case 56:
				isBit = false;
				return gBuffer;
			case 10:
				isBit = false;
				return aiBuffer;
			case 12:
				isBit = false;
				return aqBuffer;
			case 8:
				isBit = false;
				return rBuffer;
			default:
				isBit = false;
				return null;
			}
		}

		private byte[] ReadByCommand(byte dataCode, ushort address, ushort length)
		{
			SoftBuffer softBufferFromDataCode = GetSoftBufferFromDataCode(dataCode, out var isBit);
			if (softBufferFromDataCode == null)
			{
				return null;
			}
			if (isBit)
			{
				SnetHelper.CalculateStartBitIndexAndLength(address, length, out var newStart, out var byteLength, out var _);
				return softBufferFromDataCode.GetBytes(newStart / 8, byteLength);
			}
			if (dataCode == 10 || dataCode == 12 || dataCode == 8)
			{
				return softBufferFromDataCode.GetBytes(address * 2, length * 2);
			}
			return softBufferFromDataCode.GetBytes(address, length);
		}

		private byte[] ReadByCommand(byte[] command)
		{
			byte[] array = ReadByCommand(command[43], BitConverter.ToUInt16(command, 44), BitConverter.ToUInt16(command, 46));
			if (array == null)
			{
				return null;
			}
			if (array.Length < 7)
			{
				byte[] array2 = "\r\n03 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00\r\n00 01 00 00 00 00 00 00 00 00 00 00 00 00 06 d4\r\n00 0e 00 00 00 60 01 a0 01 01 00 00 00 00 00 00\r\n00 00 ff 02 03 00 5c 01".ToHexBytes();
				array.CopyTo(array2, 44);
				command.SelectMiddle(2, 2).CopyTo(array2, 2);
				return array2;
			}
			byte[] array3 = new byte[56 + array.Length];
			"03 00 03 00 00 00 00 00 00 00 00 00 00 00 00 00 00 01 00 00 00 00 00 00 00 00 00 00 00 00 06 94\r\n\t\t\t\t00 0e 00 00 00 60 01 a0 00 00 0c 00 00 18 00 00 01 01 ff 02 03 00 5c 01".ToHexBytes().CopyTo(array3, 0);
			command.SelectMiddle(2, 2).CopyTo(array3, 2);
			array.CopyTo(array3, 56);
			BitConverter.GetBytes((ushort)array.Length).CopyTo(array3, 4);
			return array3;
		}

		private OResult WriteByCommand(byte dataCode, ushort address, ushort length, byte[] value)
		{
			SoftBuffer softBufferFromDataCode = GetSoftBufferFromDataCode(dataCode, out var isBit);
			if (softBufferFromDataCode == null)
			{
				return new OResult(StringResources.Language.NotSupportedDataType);
			}
			if (isBit)
			{
				SnetHelper.CalculateStartBitIndexAndLength(address, length, out var _, out var _, out var _);
				softBufferFromDataCode.SetBool(value.ToBoolArray().SelectMiddle(address % 8, length), address);
			}
			else if (dataCode == 10 || dataCode == 12 || dataCode == 8)
			{
				if (value.Length % 2 == 1)
				{
					return new OResult(StringResources.Language.GeSRTPWriteLengthMustBeEven);
				}
				softBufferFromDataCode.SetBytes(value, address * 2);
			}
			else
			{
				softBufferFromDataCode.SetBytes(value, address);
			}
			return OResult.CreateSuccessResult();
		}

		private byte[] WriteByCommand(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return null;
			}
			if (!WriteByCommand(command[51], BitConverter.ToUInt16(command, 52), BitConverter.ToUInt16(command, 54), command.RemoveBegin(56)).IsSuccess)
			{
				return null;
			}
			byte[] array = "03 00 01 00 00 00 00 00 00 00 00 00 00 00 00 00\r\n00 02 00 00 00 00 00 00 00 00 00 00 00 00 09 d4\r\n00 0e 00 00 00 60 01 a0 01 01 00 00 00 00 00 00\r\n00 00 ff 02 03 00 5c 01".ToHexBytes();
			command.SelectMiddle(2, 2).CopyTo(array, 2);
			return array;
		}

		private byte[] ReadDateTimeByCommand(byte[] command)
		{
			byte[] array = "03 00 03 00 07 00 00 00 00 00 00 00 00 00 00 00 00 01 00 00 00 00 00 00 00 00 00 00 00 00 06 94\r\n\t\t\t\t00 0e 00 00 00 60 01 a0 00 00 0c 00 00 18 00 00 01 01 ff 02 03 00 5c 01 00 00 00 00 00 00 03".ToHexBytes();
			DateTime now = DateTime.Now;
			now.Second.ToString("D2").ToHexBytes().CopyTo(array, 56);
			now.Minute.ToString("D2").ToHexBytes().CopyTo(array, 57);
			now.Hour.ToString("D2").ToHexBytes().CopyTo(array, 58);
			now.Day.ToString("D2").ToHexBytes().CopyTo(array, 59);
			now.Month.ToString("D2").ToHexBytes().CopyTo(array, 60);
			(now.Year - 2000).ToString("D2").ToHexBytes().CopyTo(array, 61);
			command.SelectMiddle(2, 2).CopyTo(array, 2);
			return array;
		}

		private byte[] ReadProgramNameByCommand(byte[] command)
		{
			byte[] array = "\r\n03 00 07 00 2a 00 00 00 00 00 00 00 00 00 00 00 \r\n00 01 00 00 00 00 00 00 00 00 00 00 00 00 06 94 \r\n00 0e 00 00 00 62 01 a0 00 00 2a 00 00 18 00 00 \r\n01 01 ff 02 03 00 5c 01 00 00 00 00 00 00 00 00 \r\n01 00 00 00 00 00 00 00 00 00 50 41 43 34 30 30 \r\n00 00 00 00 00 00 00 00 00 00 03 00 01 50 05 18 \r\n01 21".ToHexBytes();
			command.SelectMiddle(2, 2).CopyTo(array, 2);
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 983040)
			{
				throw new Exception("File is not correct");
			}
			iBuffer.SetBytes(content, 0, 0, 65536);
			qBuffer.SetBytes(content, 65536, 0, 65536);
			mBuffer.SetBytes(content, 131072, 0, 65536);
			tBuffer.SetBytes(content, 196608, 0, 65536);
			saBuffer.SetBytes(content, 262144, 0, 65536);
			sbBuffer.SetBytes(content, 327680, 0, 65536);
			scBuffer.SetBytes(content, 393216, 0, 65536);
			sBuffer.SetBytes(content, 458752, 0, 65536);
			gBuffer.SetBytes(content, 524288, 0, 65536);
			aiBuffer.SetBytes(content, 589824, 0, 131072);
			aqBuffer.SetBytes(content, 720896, 0, 131072);
			rBuffer.SetBytes(content, 851968, 0, 131072);
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[983040];
			Array.Copy(iBuffer.GetBytes(), 0, array, 0, 65536);
			Array.Copy(qBuffer.GetBytes(), 0, array, 65536, 65536);
			Array.Copy(mBuffer.GetBytes(), 0, array, 131072, 65536);
			Array.Copy(tBuffer.GetBytes(), 0, array, 196608, 65536);
			Array.Copy(saBuffer.GetBytes(), 0, array, 262144, 65536);
			Array.Copy(sbBuffer.GetBytes(), 0, array, 327680, 65536);
			Array.Copy(scBuffer.GetBytes(), 0, array, 393216, 65536);
			Array.Copy(sBuffer.GetBytes(), 0, array, 458752, 65536);
			Array.Copy(gBuffer.GetBytes(), 0, array, 524288, 65536);
			Array.Copy(aiBuffer.GetBytes(), 0, array, 589824, 131072);
			Array.Copy(aqBuffer.GetBytes(), 0, array, 720896, 131072);
			Array.Copy(rBuffer.GetBytes(), 0, array, 851968, 131072);
			return array;
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				iBuffer.Dispose();
				qBuffer.Dispose();
				mBuffer.Dispose();
				tBuffer.Dispose();
				saBuffer.Dispose();
				sbBuffer.Dispose();
				scBuffer.Dispose();
				sBuffer.Dispose();
				gBuffer.Dispose();
				aiBuffer.Dispose();
				aqBuffer.Dispose();
				rBuffer.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"GeSRTPServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Geniitek
{
	/// <summary>
	/// 振动传感器的加速度值
	/// </summary>
	public struct VibrationSensorActualValue
	{
		/// <summary>
		/// X轴的实时加速度
		/// </summary>
		public float AcceleratedSpeedX { get; set; }

		/// <summary>
		/// Y轴的实时加速度
		/// </summary>
		public float AcceleratedSpeedY { get; set; }

		/// <summary>
		/// Z轴的实时加速度
		/// </summary>
		public float AcceleratedSpeedZ { get; set; }

		/// <inheritdoc />
		public override string ToString()
		{
			return $"ActualValue[{AcceleratedSpeedX},{AcceleratedSpeedY},{AcceleratedSpeedZ}]";
		}
	}
	/// <summary>
	/// Geniitek-VB31 型号的智能无线振动传感器，来自苏州捷杰传感器技术有限公司
	/// </summary>
	public class VibrationSensorClient : NetworkXBase
	{
		/// <summary>
		/// 震动传感器峰值数据事件委托<br />
		/// Shock sensor peak data event delegation
		/// </summary>
		/// <param name="peekValue">峰值信息</param>
		public delegate void OnPeekValueReceiveDelegate(VibrationSensorPeekValue peekValue);

		/// <summary>
		/// 震动传感器实时数据事件委托<br />
		/// Vibration sensor real-time data event delegation
		/// </summary>
		/// <param name="actualValue">实际信息</param>
		public delegate void OnActualValueReceiveDelegate(VibrationSensorActualValue actualValue);

		/// <summary>
		/// 连接服务器成功的委托<br />
		/// Connection server successfully delegated
		/// </summary>
		public delegate void OnClientConnectedDelegate();

		private int isReConnectServer;

		private bool closed;

		private string ipAddress = string.Empty;

		private int port = 1883;

		private int connectTimeOut = 10000;

		private Timer timerCheck;

		private DateTime activeTime = DateTime.Now;

		private int checkSeconds = 60;

		private int CheckTimeoutCount;

		private ushort address = 1;

		private IByteTransform byteTransform;

		/// <summary>
		/// 获取或设置当前客户端的连接超时时间，默认10,000毫秒，单位ms<br />
		/// Gets or sets the connection timeout of the current client. The default is 10,000 milliseconds. The unit is ms.
		/// </summary>
		public int ConnectTimeOut
		{
			get
			{
				return connectTimeOut;
			}
			set
			{
				connectTimeOut = value;
			}
		}

		/// <summary>
		/// 获取或设置当前的客户端假死超时检查时间，单位为秒，默认60秒，60秒内没有接收到传感器的数据，则强制重连。
		/// </summary>
		public int CheckSeconds
		{
			get
			{
				return checkSeconds;
			}
			set
			{
				checkSeconds = value;
			}
		}

		/// <summary>
		/// 当前设备的地址信息
		/// </summary>
		public ushort Address
		{
			get
			{
				return address;
			}
			set
			{
				address = value;
			}
		}

		/// <summary>
		/// 接收到震动传感器峰值数据时触发<br />
		/// Triggered when peak data of vibration sensor is received
		///             </summary>
		public event OnPeekValueReceiveDelegate OnPeekValueReceive;

		/// <summary>
		/// 接收到震动传感器实时数据时触发<br />
		/// Triggered when real-time data from shock sensor is received
		///             </summary>
		public event OnActualValueReceiveDelegate OnActualValueReceive;

		/// <summary>
		/// 当客户端连接成功触发事件，就算是重新连接服务器后，也是会触发的<br />
		/// The event is triggered when the client is connected successfully, even after reconnecting to the server.
		/// </summary>
		public event OnClientConnectedDelegate OnClientConnected;

		/// <summary>
		/// 当网络发生异常的时候触发的事件，用户应该在事件里进行重连服务器
		/// </summary>
		public event EventHandler OnNetworkError;

		/// <summary>
		/// 使用指定的ip，端口来实例化一个默认的对象
		/// </summary>
		/// <param name="ipAddress">Ip地址信息</param>
		/// <param name="port">端口号信息</param>
		public VibrationSensorClient(string ipAddress = "192.168.1.1", int port = 3001)
		{
			this.ipAddress = SnetHelper.GetIpAddressFromInput(ipAddress);
			this.port = port;
			byteTransform = new ReverseBytesTransform();
		}

		/// <summary>
		/// 连接服务器，实例化客户端之后，至少要调用成功一次，如果返回失败，那些请过一段时间后重新调用本方法连接。<br />
		/// After connecting to the server, the client must be called at least once after instantiating the client.
		/// If the return fails, please call this method to connect again after a period of time.
		/// </summary>
		/// <returns>连接是否成功</returns>
		public OResult ConnectServer()
		{
			CoreSocket?.Close();
			OResult<Socket> oResult = NetSupport.CreateSocketAndConnect(ipAddress, port, connectTimeOut);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			CoreSocket = oResult.Content;
			try
			{
				CoreSocket.BeginReceive(new byte[0], 0, 0, SocketFlags.None, ReceiveAsyncCallback, CoreSocket);
			}
			catch (Exception ex)
			{
				return new OResult(ex.Message);
			}
			closed = false;
			OnClientConnected?.Invoke();
			timerCheck?.Dispose();
			timerCheck = new Timer(TimerCheckServer, null, 2000, 5000);
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 关闭Mqtt服务器的连接。<br />
		/// Close the connection to the Mqtt server.
		/// </summary>
		public void ConnectClose()
		{
			if (!closed)
			{
				closed = true;
				SnetHelper.ThreadSleep(20);
				CoreSocket?.Close();
				timerCheck?.Dispose();
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Geniitek.VibrationSensorClient.ConnectServer" />
		public async Task<OResult> ConnectServerAsync()
		{
			CoreSocket?.Close();
			OResult<Socket> oResult = await CreateSocketAndConnectAsync(ipAddress, port, connectTimeOut);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			CoreSocket = oResult.Content;
			try
			{
				CoreSocket.BeginReceive(new byte[0], 0, 0, SocketFlags.None, ReceiveAsyncCallback, CoreSocket);
			}
			catch (Exception ex)
			{
				return new OResult(ex.Message);
			}
			closed = false;
			OnClientConnected?.Invoke();
			timerCheck?.Dispose();
			timerCheck = new Timer(TimerCheckServer, null, 2000, 5000);
			return OResult.CreateSuccessResult();
		}

		private void OnVibrationSensorClientNetworkError()
		{
			if (closed || Interlocked.CompareExchange(ref isReConnectServer, 1, 0) != 0)
			{
				return;
			}
			try
			{
				if (OnNetworkError == null)
				{
					base.LogNet?.WriteInfo("The network is abnormal, and the system is ready to automatically reconnect after 10 seconds.");
					while (true)
					{
						for (int i = 0; i < 10; i++)
						{
							SnetHelper.ThreadSleep(1000);
							base.LogNet?.WriteInfo($"Wait for {10 - i} second to connect to the server ...");
						}
						if (ConnectServer().IsSuccess)
						{
							break;
						}
						base.LogNet?.WriteInfo("The connection failed. Prepare to reconnect after 10 seconds.");
					}
					base.LogNet?.WriteInfo("Successfully connected to the server!");
				}
				else
				{
					OnNetworkError?.Invoke(this, new EventArgs());
				}
				activeTime = DateTime.Now;
				Interlocked.Exchange(ref isReConnectServer, 0);
			}
			catch
			{
				Interlocked.Exchange(ref isReConnectServer, 0);
				throw;
			}
		}

		private async void ReceiveAsyncCallback(IAsyncResult ar)
		{
			object asyncState = ar.AsyncState;
			if (!(asyncState is Socket socket))
			{
				return;
			}
			try
			{
				socket.EndReceive(ar);
			}
			catch (ObjectDisposedException)
			{
				socket?.Close();
				base.LogNet?.WriteDebug(ToString(), "Closed");
				return;
			}
			catch (Exception ex2)
			{
				socket?.Close();
				base.LogNet?.WriteDebug(ToString(), "ReceiveCallback Failed:" + ex2.Message);
				OnVibrationSensorClientNetworkError();
				return;
			}
			if (closed)
			{
				base.LogNet?.WriteDebug(ToString(), "Closed");
				return;
			}
			OResult<byte[]> read = await ReceiveAsync(socket, 9);
			if (!read.IsSuccess)
			{
				OnVibrationSensorClientNetworkError();
				return;
			}
			if (read.Content[0] == 170 && read.Content[1] == 85 && read.Content[2] == 127 && read.Content[7] == 0)
			{
				OResult<byte[]> read2 = await ReceiveAsync(socket, 3);
				if (!read2.IsSuccess)
				{
					OnVibrationSensorClientNetworkError();
					return;
				}
				int num = read2.Content[1] * 256 + read2.Content[2];
				OResult<byte[]> oResult = await ReceiveAsync(socket, num + 4);
				if (!oResult.IsSuccess)
				{
					OnVibrationSensorClientNetworkError();
					return;
				}
				if (read.Content[5] == 1)
				{
					Address = byteTransform.TransUInt16(read.Content, 3);
					base.LogNet?.WriteDebug("Receive: " + SoftBasic.SpliceArray<byte>(read.Content, read2.Content, oResult.Content).ToHexString(' '));
					VibrationSensorPeekValue peekValue = new VibrationSensorPeekValue
					{
						AcceleratedSpeedX = (float)BitConverter.ToInt16(oResult.Content, 0) / 100f,
						AcceleratedSpeedY = (float)BitConverter.ToInt16(oResult.Content, 2) / 100f,
						AcceleratedSpeedZ = (float)BitConverter.ToInt16(oResult.Content, 4) / 100f,
						SpeedX = (float)BitConverter.ToInt16(oResult.Content, 6) / 100f,
						SpeedY = (float)BitConverter.ToInt16(oResult.Content, 8) / 100f,
						SpeedZ = (float)BitConverter.ToInt16(oResult.Content, 10) / 100f,
						OffsetX = BitConverter.ToInt16(oResult.Content, 12),
						OffsetY = BitConverter.ToInt16(oResult.Content, 14),
						OffsetZ = BitConverter.ToInt16(oResult.Content, 16),
						Temperature = (float)BitConverter.ToInt16(oResult.Content, 18) * 0.02f - 273.15f,
						Voltage = (float)BitConverter.ToInt16(oResult.Content, 20) / 100f,
						SendingInterval = BitConverter.ToInt32(oResult.Content, 22)
					};
					OnPeekValueReceive?.Invoke(peekValue);
				}
			}
			else if (read.Content[0] == 170)
			{
				VibrationSensorActualValue actualValue = new VibrationSensorActualValue
				{
					AcceleratedSpeedX = (float)byteTransform.TransInt16(read.Content, 1) / 100f,
					AcceleratedSpeedY = (float)byteTransform.TransInt16(read.Content, 3) / 100f,
					AcceleratedSpeedZ = (float)byteTransform.TransInt16(read.Content, 5) / 100f
				};
				OnActualValueReceive?.Invoke(actualValue);
			}
			else
			{
				OResult<byte[]> oResult2 = await ReceiveAsync(socket, 9);
				if (!oResult2.IsSuccess)
				{
					OnVibrationSensorClientNetworkError();
					return;
				}
				byte[] array = SoftBasic.SpliceArray<byte>(read.Content, oResult2.Content);
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i] == 170)
					{
						if (i >= 9)
						{
							await ReceiveAsync(socket, i - 9);
							break;
						}
						if (array[i + 9] == 170)
						{
							await ReceiveAsync(socket, i);
							break;
						}
					}
				}
			}
			activeTime = DateTime.Now;
			try
			{
				socket.BeginReceive(new byte[0], 0, 0, SocketFlags.None, ReceiveAsyncCallback, socket);
			}
			catch (Exception ex3)
			{
				socket?.Close();
				base.LogNet?.WriteDebug(ToString(), "BeginReceive Failed:" + ex3.Message);
				OnVibrationSensorClientNetworkError();
			}
		}

		private void TimerCheckServer(object obj)
		{
			if (CoreSocket == null || closed)
			{
				return;
			}
			if ((DateTime.Now - activeTime).TotalSeconds > (double)checkSeconds)
			{
				if (CheckTimeoutCount == 0)
				{
					base.LogNet?.WriteDebug(StringResources.Language.NetHeartCheckTimeout);
				}
				CheckTimeoutCount = 1;
				OnVibrationSensorClientNetworkError();
			}
			else
			{
				CheckTimeoutCount = 0;
			}
		}

		private OResult SendPre(byte[] send)
		{
			base.LogNet?.WriteDebug("Send " + send.ToHexString(' '));
			return Send(CoreSocket, send);
		}

		/// <summary>
		/// 设置读取震动传感器的状态数据<br />
		/// Set to read the status data of the shock sensor
		/// </summary>
		/// <returns>是否发送成功</returns>
		public OResult SetReadStatus()
		{
			return SendPre(BulidLongMessage(address, 1, null));
		}

		/// <summary>
		/// 设置读取震动传感器的实时加速度<br />
		/// Set the real-time acceleration of the vibration sensor
		/// </summary>
		/// <returns>是否发送成功</returns>
		public OResult SetReadActual()
		{
			return SendPre(BulidLongMessage(address, 2, null));
		}

		/// <summary>
		/// 设置当前的震动传感器的数据发送间隔为指定的时间，单位为秒<br />
		/// Set the current vibration sensor data transmission interval to the specified time in seconds
		/// </summary>
		/// <param name="seconds">时间信息，单位为秒</param>
		/// <returns>是否发送成功</returns>
		public OResult SetReadStatusInterval(int seconds)
		{
			byte[] array = new byte[6]
			{
				BitConverter.GetBytes(address)[0],
				BitConverter.GetBytes(address)[1],
				0,
				0,
				0,
				0
			};
			BitConverter.GetBytes(seconds).CopyTo(array, 2);
			return SendPre(BulidLongMessage(address, 16, array));
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"VibrationSensorClient[{ipAddress}:{port}]";
		}

		/// <summary>
		/// 根据地址，命令，数据，创建向传感器发送的数据信息
		/// </summary>
		/// <param name="address">设备地址</param>
		/// <param name="cmd">命令</param>
		/// <param name="data">数据信息</param>
		/// <returns>原始的数据内容</returns>
		public static byte[] BulidLongMessage(ushort address, byte cmd, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[16 + data.Length];
			array[0] = 170;
			array[1] = 85;
			array[2] = 127;
			array[3] = BitConverter.GetBytes(address)[1];
			array[4] = BitConverter.GetBytes(address)[0];
			array[5] = cmd;
			array[6] = 1;
			array[7] = 0;
			array[8] = 1;
			array[9] = 1;
			array[10] = BitConverter.GetBytes(data.Length)[1];
			array[11] = BitConverter.GetBytes(data.Length)[0];
			data.CopyTo(array, 12);
			int num = array[3];
			for (int i = 4; i < array.Length - 4; i++)
			{
				num ^= array[i];
			}
			array[^4] = (byte)num;
			array[^3] = 127;
			array[^2] = 170;
			array[^1] = 237;
			return array;
		}

		/// <summary>
		/// 检查当前的数据是否XOR校验成功
		/// </summary>
		/// <param name="data">数据信息</param>
		/// <returns>校验结果</returns>
		public static bool CheckXor(byte[] data)
		{
			int num = data[3];
			for (int i = 4; i < data.Length - 4; i++)
			{
				num ^= data[i];
			}
			return BitConverter.GetBytes(num)[0] == data[^4];
		}
	}
	/// <summary>
	/// 完整的数据报文信息
	/// </summary>
	public class VibrationSensorLongMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 12;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.CheckHeadBytesLegal(System.Byte[])" />
		public override bool CheckHeadBytesLegal(byte[] token)
		{
			if (base.HeadBytes == null)
			{
				return false;
			}
			if (base.HeadBytes[0] == 170 && base.HeadBytes[1] == 85 && base.HeadBytes[2] == 127)
			{
				return true;
			}
			return false;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			return base.HeadBytes[10] * 256 + base.HeadBytes[11] + 4;
		}
	}
