namespace Snet.Driver.Profinet.Fuji
{
	/// <summary>
	/// 基于Command-Setting-Type通信模式的协议实现，地址格式参数DEMO界面<br />
	/// Protocol implementation based on Command-Setting-Type communication mode, address format parameter DEMO interface
	/// </summary>
	/// <remarks>
	/// 本类实例化对象之后，还需要设置<see cref="P:Snet.Driver.Profinet.Fuji.FujiCommandSettingType.DataSwap" />属性，根据实际情况来设置。
	/// </remarks>
	public class FujiCommandSettingType : DeviceTcpNet
	{
		private bool dataSwap;

		/// <summary>
		/// 获取或设置当前的对象是否进行数据交换操作，将根据PLC的实际值来设定。<br />
		/// Get or set whether the current object performs data exchange operation or not, it will be set according to the actual value of the PLC.
		/// </summary>
		public bool DataSwap
		{
			get
			{
				return dataSwap;
			}
			set
			{
				dataSwap = value;
				if (value)
				{
					base.ByteTransform = new RegularByteTransform();
				}
				else
				{
					base.ByteTransform = new ReverseBytesTransform();
				}
			}
		}

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public FujiCommandSettingType()
		{
			base.ByteTransform = new ReverseBytesTransform();
			base.WordLength = 2;
		}

		/// <summary>
		/// 使用指定的IP地址和端口号来实例化一个对象
		/// </summary>
		/// <param name="ipAddress">IP地址信息</param>
		/// <param name="port">端口号信息</param>
		public FujiCommandSettingType(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FujiCommandSettingTypeMessage();
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			return UnpackResponseContentHelper(send, response);
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiCommandSettingType.Read(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return await ReadFromCoreServerAsync(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiCommandSettingType.Write(System.String,System.Byte[])" />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return await ReadFromCoreServerAsync(oResult.Content);
		}

		/// <summary>
		/// 读取指定地址的byte数据，地址格式 S100 <br />
		/// Reads the byte data of the specified address, the address format S100
		/// </summary>
		/// <param name="address">起始地址，格式为S100 </param>
		/// <returns>是否读取成功的结果对象</returns>
		/// <example>参考<see cref="M:Snet.Driver.Profinet.Fuji.FujiCommandSettingType.Read(System.String,System.UInt16)" />的注释</example>
		public OResult<byte> ReadByte(string address)
		{
			return ByteTransformHelper.GetResultFromArray(Read(address, 1));
		}

		/// <summary>
		/// 向PLC中写入byte数据，返回值说明<br />
		/// Write byte data to the PLC, return value description
		/// </summary>
		/// <param name="address">起始地址，格式为 S100</param>
		/// <param name="value">byte数据</param>
		/// <returns>是否写入成功的结果对象 </returns>
		public OResult Write(string address, byte value)
		{
			return Write(address, new byte[1] { value });
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiCommandSettingType.Read(System.String,System.UInt16)" />
		public async Task<OResult<byte>> ReadByteAsync(string address)
		{
			return ByteTransformHelper.GetResultFromArray(await ReadAsync(address, 1));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiCommandSettingType.Write(System.String,System.Byte[])" />
		public async Task<OResult> WriteAsync(string address, byte value)
		{
			return await WriteAsync(address, new byte[1] { value });
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"FujiCommandSettingType[{IpAddress}:{Port}]";
		}

		/// <summary>
		/// 构建读取的报文指令
		/// </summary>
		/// <param name="address">PLC的地址信息</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>报文构建的结果对象</returns>
		public static OResult<byte[]> BuildReadCommand(string address, ushort length)
		{
			OResult<FujiCommandSettingTypeAddress> oResult = FujiCommandSettingTypeAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(new byte[9]
			{
				0,
				0,
				0,
				oResult.Content.DataCode,
				4,
				BitConverter.GetBytes(oResult.Content.AddressStart)[0],
				BitConverter.GetBytes(oResult.Content.AddressStart)[1],
				BitConverter.GetBytes(oResult.Content.Length)[0],
				BitConverter.GetBytes(oResult.Content.Length)[1]
			});
		}

		/// <summary>
		/// 构建写入原始报文数据的请求信息
		/// </summary>
		/// <param name="address">地址数据</param>
		/// <param name="value">原始报文的数据</param>
		/// <returns>原始的写入报文数据</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, byte[] value)
		{
			OResult<FujiCommandSettingTypeAddress> oResult = FujiCommandSettingTypeAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[9 + value.Length];
			array[0] = 1;
			array[1] = 0;
			array[2] = 0;
			array[3] = oResult.Content.DataCode;
			array[4] = (byte)(4 + value.Length);
			array[5] = BitConverter.GetBytes(oResult.Content.AddressStart)[0];
			array[6] = BitConverter.GetBytes(oResult.Content.AddressStart)[1];
			array[7] = BitConverter.GetBytes(oResult.Content.Length)[0];
			array[8] = BitConverter.GetBytes(oResult.Content.Length)[0];
			value.CopyTo(array, 9);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 根据错误信息获取相关数据信息
		/// </summary>
		/// <param name="error">错误代号</param>
		/// <returns>实际的错误描述信息</returns>
		public static string GetErrorText(int error)
		{
			return error switch
			{
				18 => "Write of data to the program area", 
				32 => "Non-existing CMND code", 
				33 => "Input data is not in the order of data corresponding to CMND", 
				34 => "Operation only from the loader is effective. Operation from any other node is disabled", 
				36 => "A non-existing module has been specified", 
				50 => "An address out of the memory size has been specified", 
				_ => StringResources.Language.UnknownError, 
			};
		}

		/// <summary>
		/// 根据PLC返回的数据，解析出实际的数据内容
		/// </summary>
		/// <param name="send">发送给PLC的数据</param>
		/// <param name="response">PLC返回的数据</param>
		/// <returns>结果数据信息</returns>
		public static OResult<byte[]> UnpackResponseContentHelper(byte[] send, byte[] response)
		{
			try
			{
				if (response[1] != 0)
				{
					return new OResult<byte[]>(GetErrorText(response[1]));
				}
				if (response[0] == 1)
				{
					return OResult.CreateSuccessResult(new byte[0]);
				}
				if (response.Length < 10)
				{
					return new OResult<byte[]>(StringResources.Language.ReceiveDataLengthTooShort + "10, Source: " + response.ToHexString(' '));
				}
				return OResult.CreateSuccessResult(response.RemoveBegin(10));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("UnpackResponseContentHelper failed: " + ex.Message + " Source: " + response.ToHexString(' '));
			}
		}
	}
	/// <summary>
	/// 富士Command-Setting-type协议实现的虚拟服务器，支持的地址为 B,M,K,D,W9,BD,F,A,WL,W21,W9。具体的支持列表参考api文档<br />
	/// The virtual server implemented by Fuji Command-Setting-type protocol supports addresses B, M, K, D, W9, BD, F, A, WL, W21, W9. 
	/// For the specific support list, please refer to the api documentation
	/// </summary>
	/// <remarks>
	/// 当前的虚拟服务器实例化之后，调用<see cref="M:Snet.Driver.Core.Net.NetworkServerBase.ServerStart" /> 方法即可，还有个参数<see cref="P:Snet.Driver.Profinet.Fuji.FujiCommandSettingTypeServer.DataSwap" />需要特别注意，约定了数据的大小端形式。
	/// </remarks>
	public class FujiCommandSettingTypeServer : DeviceServer
	{
		private bool dataSwap;

		private SoftBuffer bBuffer;

		private SoftBuffer mBuffer;

		private SoftBuffer kBuffer;

		private SoftBuffer fBuffer;

		private SoftBuffer aBuffer;

		private SoftBuffer dBuffer;

		private SoftBuffer sBuffer;

		private SoftBuffer w9Buffer;

		private SoftBuffer bdBuffer;

		private SoftBuffer wlBuffer;

		private SoftBuffer w21Buffer;

		private const int DataPoolLength = 65536;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Fuji.FujiCommandSettingType.DataSwap" />
		public bool DataSwap
		{
			get
			{
				return dataSwap;
			}
			set
			{
				dataSwap = value;
				if (value)
				{
					base.ByteTransform = new RegularByteTransform();
				}
				else
				{
					base.ByteTransform = new ReverseBytesTransform();
				}
			}
		}

		/// <summary>
		/// 实例化一个富士的服务器<br />
		/// </summary>
		public FujiCommandSettingTypeServer()
		{
			bBuffer = new SoftBuffer(65536);
			mBuffer = new SoftBuffer(65536);
			kBuffer = new SoftBuffer(65536);
			dBuffer = new SoftBuffer(65536);
			sBuffer = new SoftBuffer(65536);
			w9Buffer = new SoftBuffer(65536);
			bdBuffer = new SoftBuffer(65536);
			fBuffer = new SoftBuffer(65536);
			aBuffer = new SoftBuffer(65536);
			wlBuffer = new SoftBuffer(65536);
			w21Buffer = new SoftBuffer(65536);
			base.WordLength = 2;
			base.ByteTransform = new ReverseBytesTransform();
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			try
			{
				OResult<byte[]> oResult = FujiCommandSettingType.BuildReadCommand(address, length);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				byte[] response = ReadByMessage(oResult.Content);
				return FujiCommandSettingType.UnpackResponseContentHelper(oResult.Content, response);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			try
			{
				OResult<byte[]> oResult = FujiCommandSettingType.BuildWriteCommand(address, value);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				byte[] response = WriteByMessage(oResult.Content);
				return FujiCommandSettingType.UnpackResponseContentHelper(oResult.Content, response);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 从PLC读取byte类型的数据信息，通常针对步进寄存器，也就是 S100 的地址
		/// </summary>
		/// <param name="address">PLC地址数据，例如 S100</param>
		/// <returns>是否读取成功结果对象</returns>
		public OResult<byte> ReadByte(string address)
		{
			return ByteTransformHelper.GetResultFromArray(Read(address, 1));
		}

		/// <summary>
		/// 将Byte输入写入到PLC之中，通常针对步进寄存器，也就是 S100 的地址
		/// </summary>
		/// <param name="address">PLC地址数据，例如 S100</param>
		/// <param name="value">数据信息</param>
		/// <returns>是否写入成功</returns>
		public OResult Write(string address, byte value)
		{
			return Write(address, new byte[1] { value });
		}

		/// <inheritdoc />
		public override OResult<bool> ReadBool(string address)
		{
			return base.ReadBool(address);
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool value)
		{
			return base.Write(address, value);
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FujiCommandSettingTypeMessage();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			return OResult.CreateSuccessResult((receive[0] == 0 && receive[2] == 0) ? ReadByMessage(receive) : ((receive[0] != 1 || receive[2] != 0) ? PackResponseResult(receive, 32, null) : WriteByMessage(receive)));
		}

		private byte[] PackResponseResult(byte[] command, byte err, byte[] value)
		{
			if (err > 0 || command[0] == 1)
			{
				byte[] array = new byte[9];
				Array.Copy(command, 0, array, 0, 9);
				array[1] = err;
				array[4] = 4;
				return array;
			}
			if (value == null)
			{
				value = new byte[0];
			}
			byte[] array2 = new byte[10 + value.Length];
			Array.Copy(command, 0, array2, 0, 9);
			array2[4] = (byte)(5 + value.Length);
			value.CopyTo(array2, 10);
			return array2;
		}

		private byte[] ReadByMessage(byte[] command)
		{
			int num = command[5] + command[6] * 256;
			int length = command[7] + command[8] * 256;
			if (command[3] == 0)
			{
				return PackResponseResult(command, 0, bBuffer.GetBytes(num * 2, length));
			}
			if (command[3] == 1)
			{
				return PackResponseResult(command, 0, mBuffer.GetBytes(num * 2, length));
			}
			if (command[3] == 2)
			{
				return PackResponseResult(command, 0, kBuffer.GetBytes(num * 2, length));
			}
			if (command[3] == 3)
			{
				return PackResponseResult(command, 0, fBuffer.GetBytes(num * 2, length));
			}
			if (command[3] == 4)
			{
				return PackResponseResult(command, 0, aBuffer.GetBytes(num * 2, length));
			}
			if (command[3] == 5)
			{
				return PackResponseResult(command, 0, dBuffer.GetBytes(num * 2, length));
			}
			if (command[3] == 8)
			{
				return PackResponseResult(command, 0, sBuffer.GetBytes(num, length));
			}
			if (command[3] == 9)
			{
				return PackResponseResult(command, 0, w9Buffer.GetBytes(num * 4, length));
			}
			if (command[3] == 14)
			{
				return PackResponseResult(command, 0, bdBuffer.GetBytes(num * 4, length));
			}
			if (command[3] == 20)
			{
				return PackResponseResult(command, 0, wlBuffer.GetBytes(num * 2, length));
			}
			if (command[3] == 21)
			{
				return PackResponseResult(command, 0, w21Buffer.GetBytes(num * 2, length));
			}
			return PackResponseResult(command, 36, null);
		}

		private byte[] WriteByMessage(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return PackResponseResult(command, 34, null);
			}
			int num = command[5] + command[6] * 256;
			_ = command[7];
			_ = command[8];
			byte[] data = command.RemoveBegin(9);
			if (command[3] == 0)
			{
				bBuffer.SetBytes(data, num * 2);
			}
			else if (command[3] == 1)
			{
				mBuffer.SetBytes(data, num * 2);
			}
			else if (command[3] == 2)
			{
				kBuffer.SetBytes(data, num * 2);
			}
			else if (command[3] == 3)
			{
				fBuffer.SetBytes(data, num * 2);
			}
			else if (command[3] == 4)
			{
				aBuffer.SetBytes(data, num * 2);
			}
			else if (command[3] == 5)
			{
				dBuffer.SetBytes(data, num * 2);
			}
			else if (command[3] == 8)
			{
				sBuffer.SetBytes(data, num);
			}
			else if (command[3] == 9)
			{
				w9Buffer.SetBytes(data, num * 4);
			}
			else if (command[3] == 14)
			{
				bdBuffer.SetBytes(data, num * 4);
			}
			else if (command[3] == 20)
			{
				wlBuffer.SetBytes(data, num * 2);
			}
			else
			{
				if (command[3] != 21)
				{
					return PackResponseResult(command, 36, null);
				}
				w21Buffer.SetBytes(data, num * 2);
			}
			return PackResponseResult(command, 0, null);
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 720896)
			{
				throw new Exception("File is not correct");
			}
			bBuffer.SetBytes(content, 0, 0, 65536);
			mBuffer.SetBytes(content, 65536, 0, 65536);
			kBuffer.SetBytes(content, 131072, 0, 65536);
			fBuffer.SetBytes(content, 196608, 0, 65536);
			aBuffer.SetBytes(content, 262144, 0, 65536);
			dBuffer.SetBytes(content, 327680, 0, 65536);
			sBuffer.SetBytes(content, 393216, 0, 65536);
			w9Buffer.SetBytes(content, 458752, 0, 65536);
			bdBuffer.SetBytes(content, 524288, 0, 65536);
			wlBuffer.SetBytes(content, 589824, 0, 65536);
			w21Buffer.SetBytes(content, 655360, 0, 65536);
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[720896];
			Array.Copy(bBuffer.GetBytes(), 0, array, 0, 65536);
			Array.Copy(mBuffer.GetBytes(), 0, array, 65536, 65536);
			Array.Copy(kBuffer.GetBytes(), 0, array, 131072, 65536);
			Array.Copy(fBuffer.GetBytes(), 0, array, 196608, 65536);
			Array.Copy(aBuffer.GetBytes(), 0, array, 262144, 65536);
			Array.Copy(dBuffer.GetBytes(), 0, array, 327680, 65536);
			Array.Copy(sBuffer.GetBytes(), 0, array, 393216, 65536);
			Array.Copy(w9Buffer.GetBytes(), 0, array, 458752, 65536);
			Array.Copy(bdBuffer.GetBytes(), 0, array, 524288, 65536);
			Array.Copy(wlBuffer.GetBytes(), 0, array, 589824, 65536);
			Array.Copy(w21Buffer.GetBytes(), 0, array, 655360, 65536);
			return array;
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				bBuffer?.Dispose();
				mBuffer?.Dispose();
				kBuffer?.Dispose();
				fBuffer?.Dispose();
				aBuffer?.Dispose();
				dBuffer?.Dispose();
				sBuffer?.Dispose();
				w9Buffer?.Dispose();
				bdBuffer?.Dispose();
				wlBuffer?.Dispose();
				w21Buffer?.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"FujiCommandSettingTypeServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 富士PLC的SPB协议，详细的地址信息见api文档说明，地址可以携带站号信息，例如：s=2;D100，PLC侧需要配置无BCC计算，包含0D0A结束码<br />
	/// Fuji PLC's SPB protocol. For detailed address information, see the api documentation, 
	/// The address can carry station number information, for example: s=2;D100, PLC side needs to be configured with no BCC calculation, including 0D0A end code
	/// </summary>
	public class FujiSPB : DeviceSerialPort
	{
		private byte station = 1;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.Station" />
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.#ctor" />
		public FujiSPB()
		{
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
			LogMsgFormatBinary = false;
			base.ReceiveEmptyDataCount = 5;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FujiSPBMessage();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			return FujiSPBHelper.Read(this, station, address, length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			return FujiSPBHelper.Write(this, station, address, value);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			return FujiSPBHelper.ReadBool(this, station, address, length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.Write(System.String,System.Boolean)" />
		public override OResult Write(string address, bool value)
		{
			return FujiSPBHelper.Write(this, station, address, value);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPB.Write(System.String,System.Boolean)" />
		public override async Task<OResult> WriteAsync(string address, bool value)
		{
			return await FujiSPBHelper.WriteAsync(this, station, address, value);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"FujiSPB[{base.PortName}:{base.BaudRate}]";
		}
	}
	/// <summary>
	/// 富士SPB的辅助类
	/// </summary>
	public class FujiSPBHelper
	{
		/// <summary>
		/// 将int数据转换成SPB可识别的标准的数据内容，例如 2转换为0200 , 200转换为0002
		/// </summary>
		/// <param name="address">等待转换的数据内容</param>
		/// <returns>转换之后的数据内容</returns>
		public static string AnalysisIntegerAddress(int address)
		{
			string text = address.ToString("D4");
			return text.Substring(2) + text.Substring(0, 2);
		}

		/// <summary>
		/// 计算指令的和校验码
		/// </summary>
		/// <param name="data">指令</param>
		/// <returns>校验之后的信息</returns>
		public static string CalculateAcc(string data)
		{
			byte[] bytes = Encoding.ASCII.GetBytes(data);
			int num = 0;
			for (int i = 0; i < bytes.Length; i++)
			{
				num += bytes[i];
			}
			return num.ToString("X4").Substring(2);
		}

		/// <summary>
		/// 创建一条读取的指令信息，需要指定一些参数，单次读取最大105个字
		/// </summary>
		/// <param name="station">PLC的站号</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<byte[]> BuildReadCommand(byte station, string address, ushort length)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<FujiSPBAddress> oResult = FujiSPBAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return BuildReadCommand(station, oResult.Content, length);
		}

		/// <summary>
		/// 创建一条读取的指令信息，需要指定一些参数，单次读取最大105个字
		/// </summary>
		/// <param name="station">PLC的站号</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<byte[]> BuildReadCommand(byte station, FujiSPBAddress address, ushort length)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(':');
			stringBuilder.Append(station.ToString("X2"));
			stringBuilder.Append("09");
			stringBuilder.Append("FFFF");
			stringBuilder.Append("00");
			stringBuilder.Append("00");
			stringBuilder.Append(address.GetWordAddress());
			stringBuilder.Append(AnalysisIntegerAddress(length));
			stringBuilder.Append("\r\n");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 创建一条读取多个地址的指令信息，需要指定一些参数，单次读取最大105个字
		/// </summary>
		/// <param name="station">PLC的站号</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <param name="isBool">是否位读取</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<byte[]> BuildReadCommand(byte station, string[] address, ushort[] length, bool isBool)
		{
			if (address == null || length == null)
			{
				return new OResult<byte[]>("Parameter address or length can't be null");
			}
			if (address.Length != length.Length)
			{
				return new OResult<byte[]>(StringResources.Language.TwoParametersLengthIsNotSame);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(':');
			stringBuilder.Append(station.ToString("X2"));
			stringBuilder.Append((6 + address.Length * 4).ToString("X2"));
			stringBuilder.Append("FFFF");
			stringBuilder.Append("00");
			stringBuilder.Append("04");
			stringBuilder.Append("00");
			stringBuilder.Append(address.Length.ToString("X2"));
			for (int i = 0; i < address.Length; i++)
			{
				station = (byte)SnetHelper.ExtractParameter(ref address[i], "s", station);
				OResult<FujiSPBAddress> oResult = FujiSPBAddress.ParseFrom(address[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				stringBuilder.Append(oResult.Content.TypeCode);
				stringBuilder.Append(length[i].ToString("X2"));
				stringBuilder.Append(AnalysisIntegerAddress(oResult.Content.AddressStart));
			}
			stringBuilder[1] = station.ToString("X2")[0];
			stringBuilder[2] = station.ToString("X2")[1];
			stringBuilder.Append("\r\n");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 创建一条别入byte数据的指令信息，需要指定一些参数，按照字单位，单次写入最大103个字
		/// </summary>
		/// <param name="station">站号</param>
		/// <param name="address">地址</param>
		/// <param name="value">数组值</param>
		/// <returns>是否创建成功</returns>
		public static OResult<byte[]> BuildWriteByteCommand(byte station, string address, byte[] value)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<FujiSPBAddress> oResult = FujiSPBAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(':');
			stringBuilder.Append(station.ToString("X2"));
			stringBuilder.Append("00");
			stringBuilder.Append("FFFF");
			stringBuilder.Append("01");
			stringBuilder.Append("00");
			stringBuilder.Append(oResult.Content.GetWordAddress());
			stringBuilder.Append(AnalysisIntegerAddress(value.Length / 2));
			stringBuilder.Append(value.ToHexString());
			stringBuilder[3] = ((stringBuilder.Length - 5) / 2).ToString("X2")[0];
			stringBuilder[4] = ((stringBuilder.Length - 5) / 2).ToString("X2")[1];
			stringBuilder.Append("\r\n");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 创建一条别入byte数据的指令信息，需要指定一些参数，按照字单位，单次写入最大103个字
		/// </summary>
		/// <param name="station">站号</param>
		/// <param name="address">地址</param>
		/// <param name="value">数组值</param>
		/// <returns>是否创建成功</returns>
		public static OResult<byte[]> BuildWriteBoolCommand(byte station, string address, bool value)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<FujiSPBAddress> oResult = FujiSPBAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if ((address.StartsWith("X") || address.StartsWith("Y") || address.StartsWith("M") || address.StartsWith("L") || address.StartsWith("TC") || address.StartsWith("CC")) && address.IndexOf('.') < 0)
			{
				oResult.Content.BitIndex = oResult.Content.AddressStart % 16;
				oResult.Content.AddressStart = (ushort)(oResult.Content.AddressStart / 16);
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(':');
			stringBuilder.Append(station.ToString("X2"));
			stringBuilder.Append("00");
			stringBuilder.Append("FFFF");
			stringBuilder.Append("01");
			stringBuilder.Append("02");
			stringBuilder.Append(oResult.Content.GetWriteBoolAddress());
			stringBuilder.Append(value ? "01" : "00");
			stringBuilder[3] = ((stringBuilder.Length - 5) / 2).ToString("X2")[0];
			stringBuilder[4] = ((stringBuilder.Length - 5) / 2).ToString("X2")[1];
			stringBuilder.Append("\r\n");
			return OResult.CreateSuccessResult(Encoding.ASCII.GetBytes(stringBuilder.ToString()));
		}

		/// <summary>
		/// 检查反馈的数据信息，是否包含了错误码，如果没有包含，则返回成功
		/// </summary>
		/// <param name="content">原始的报文返回</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<byte[]> CheckResponseData(byte[] content)
		{
			try
			{
				if (content[0] != 58)
				{
					return new OResult<byte[]>(content[0], "Read Faild:" + SoftBasic.ByteToHexString(content, ' '));
				}
				string text = Encoding.ASCII.GetString(content, 9, 2);
				if (text != "00")
				{
					return new OResult<byte[]>(Convert.ToInt32(text, 16), GetErrorDescriptionFromCode(text));
				}
				if (content[^2] == 13 && content[^1] == 10)
				{
					content = content.RemoveLast(2);
				}
				return OResult.CreateSuccessResult(content.RemoveBegin(11));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("CheckResponseData failed: " + ex.Message + Environment.NewLine + "Source: " + content.ToHexString(' '));
			}
		}

		/// <summary>
		/// 根据错误码获取到真实的文本信息
		/// </summary>
		/// <param name="code">错误码</param>
		/// <returns>错误的文本描述</returns>
		public static string GetErrorDescriptionFromCode(string code)
		{
			return code switch
			{
				"01" => StringResources.Language.FujiSpbStatus01, 
				"02" => StringResources.Language.FujiSpbStatus02, 
				"03" => StringResources.Language.FujiSpbStatus03, 
				"04" => StringResources.Language.FujiSpbStatus04, 
				"05" => StringResources.Language.FujiSpbStatus05, 
				"06" => StringResources.Language.FujiSpbStatus06, 
				"07" => StringResources.Language.FujiSpbStatus07, 
				"09" => StringResources.Language.FujiSpbStatus09, 
				"0C" => StringResources.Language.FujiSpbStatus0C, 
				_ => StringResources.Language.UnknownError, 
			};
		}

		/// <summary>
		/// 批量读取PLC的数据，以字为单位，支持读取X,Y,L,M,D,TN,CN,TC,CC,R,W具体的地址范围需要根据PLC型号来确认，地址可以携带站号信息，例如：s=2;D100<br />
		/// Read PLC data in batches, in units of words. Supports reading X, Y, L, M, D, TN, CN, TC, CC, R, W. 
		/// The specific address range needs to be confirmed according to the PLC model, The address can carry station number information, for example: s=2;D100
		/// </summary>
		/// <param name="device">PLC设备通信对象</param>
		/// <param name="station">当前的站号信息</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>读取结果信息</returns>
		/// <remarks>
		/// 单次读取的最大的字数为105，如果读取的字数超过这个值，请分批次读取。
		/// </remarks>
		public static OResult<byte[]> Read(IReadWriteDevice device, byte station, string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(station, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult<byte[]> oResult2 = device.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			OResult<byte[]> oResult3 = CheckResponseData(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult3.Content.RemoveBegin(4)).ToHexBytes());
		}

		/// <summary>
		/// 批量写入PLC的数据，以字为单位，也就是说最少2个字节信息，支持读取X,Y,L,M,D,TN,CN,TC,CC,R具体的地址范围需要根据PLC型号来确认，地址可以携带站号信息，例如：s=2;D100<br />
		/// The data written to the PLC in batches, in units of words, that is, a minimum of 2 bytes of information. It supports reading X, Y, L, M, D, TN, CN, TC, CC, and R. 
		/// The specific address range needs to be based on PLC model to confirm, The address can carry station number information, for example: s=2;D100
		/// </summary>
		/// <param name="device">PLC设备通信对象</param>
		/// <param name="station">当前的站号信息</param>
		/// <param name="address">地址信息，举例，D100，R200，TN100，CN200</param>
		/// <param name="value">数据值</param>
		/// <returns>是否写入成功</returns>
		/// <remarks>
		/// 单次写入的最大的字数为103个字，如果写入的数据超过这个长度，请分批次写入
		/// </remarks>
		public static OResult Write(IReadWriteDevice device, byte station, string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteByteCommand(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = device.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return CheckResponseData(oResult2.Content);
		}

		/// <summary>
		/// 批量读取PLC的Bool数据，以位为单位，支持读取X,Y,L,M,D,TN,CN,TC,CC,R,W，例如 M100, 如果是寄存器地址，可以使用D10.12来访问第10个字的12位，地址可以携带站号信息，例如：s=2;M100<br />
		/// Read PLC's Bool data in batches, in units of bits, support reading X, Y, L, M, D, TN, CN, TC, CC, R, W, such as M100, if it is a register address, 
		/// you can use D10. 12 to access the 12 bits of the 10th word, the address can carry station number information, for example: s=2;M100
		/// </summary>
		/// <param name="device">PLC设备通信对象</param>
		/// <param name="station">当前的站号信息</param>
		/// <param name="address">地址信息，举例：M100, D10.12</param>
		/// <param name="length">读取的bool长度信息</param>
		/// <returns>Bool[]的结果对象</returns>
		public static OResult<bool[]> ReadBool(IReadWriteDevice device, byte station, string address, ushort length)
		{
			byte station2 = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<FujiSPBAddress> oResult = FujiSPBAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			if ((address.StartsWith("X") || address.StartsWith("Y") || address.StartsWith("M") || address.StartsWith("L") || address.StartsWith("TC") || address.StartsWith("CC")) && address.IndexOf('.') < 0)
			{
				oResult.Content.BitIndex = oResult.Content.AddressStart % 16;
				oResult.Content.AddressStart = (ushort)(oResult.Content.AddressStart / 16);
			}
			ushort length2 = (ushort)((oResult.Content.GetBitIndex() + length - 1) / 16 - oResult.Content.GetBitIndex() / 16 + 1);
			OResult<byte[]> oResult2 = BuildReadCommand(station2, oResult.Content, length2);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			OResult<byte[]> oResult3 = device.ReadFromCoreServer(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult3);
			}
			OResult<byte[]> oResult4 = CheckResponseData(oResult3.Content);
			if (!oResult4.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult4);
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult4.Content.RemoveBegin(4)).ToHexBytes().ToBoolArray()
				.SelectMiddle(oResult.Content.BitIndex, length));
		}

		/// <summary>
		/// 写入一个Bool值到一个地址里，地址可以是线圈地址，也可以是寄存器地址，例如：M100, D10.12，地址可以携带站号信息，例如：s=2;D10.12<br />
		/// Write a Bool value to an address. The address can be a coil address or a register address, for example: M100, D10.12. 
		/// The address can carry station number information, for example: s=2;D10.12
		/// </summary>
		/// <param name="device">PLC设备通信对象</param>
