	/// <summary>
	/// 富士的SPB虚拟的PLC，线圈支持X,Y,M的读写，其中X只能远程读，寄存器支持D,R,W的读写操作。<br />
	/// Fuji's SPB virtual PLC, the coil supports X, Y, M read and write, 
	/// X can only be read remotely, and the register supports D, R, W read and write operations.
	/// </summary>
	public class FujiSPBServer : DeviceServer
	{
		private SoftBuffer xBuffer;

		private SoftBuffer yBuffer;

		private SoftBuffer mBuffer;

		private SoftBuffer dBuffer;

		private SoftBuffer rBuffer;

		private SoftBuffer wBuffer;

		private const int DataPoolLength = 65536;

		private int station = 1;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.DataFormat" />
		public DataFormat DataFormat
		{
			get
			{
				return base.ByteTransform.DataFormat;
			}
			set
			{
				base.ByteTransform.DataFormat = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.IsStringReverse" />
		public bool IsStringReverse
		{
			get
			{
				return base.ByteTransform.IsStringReverseByteWord;
			}
			set
			{
				base.ByteTransform.IsStringReverseByteWord = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.Station" />
		public int Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 实例化一个富士SPB的网口和串口服务器，支持数据读写操作
		/// </summary>
		public FujiSPBServer()
		{
			xBuffer = new SoftBuffer(65536);
			yBuffer = new SoftBuffer(65536);
			mBuffer = new SoftBuffer(65536);
			dBuffer = new SoftBuffer(131072);
			rBuffer = new SoftBuffer(131072);
			wBuffer = new SoftBuffer(131072);
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
			LogMsgFormatBinary = false;
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[589824];
			xBuffer.GetBytes().CopyTo(array, 0);
			yBuffer.GetBytes().CopyTo(array, 65536);
			mBuffer.GetBytes().CopyTo(array, 131072);
			dBuffer.GetBytes().CopyTo(array, 196608);
			rBuffer.GetBytes().CopyTo(array, 327680);
			wBuffer.GetBytes().CopyTo(array, 458752);
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 589824)
			{
				throw new Exception("File is not correct");
			}
			xBuffer.SetBytes(content, 0, 65536);
			yBuffer.SetBytes(content, 65536, 65536);
			mBuffer.SetBytes(content, 131072, 65536);
			dBuffer.SetBytes(content, 196608, 131072);
			rBuffer.SetBytes(content, 327680, 131072);
			wBuffer.SetBytes(content, 458752, 131072);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = new OResult<byte[]>();
			try
			{
				switch (address[0])
				{
				case 'X':
				case 'x':
					return OResult.CreateSuccessResult(xBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				case 'Y':
				case 'y':
					return OResult.CreateSuccessResult(yBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				case 'M':
				case 'm':
					return OResult.CreateSuccessResult(mBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				case 'D':
				case 'd':
					return OResult.CreateSuccessResult(dBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				case 'R':
				case 'r':
					return OResult.CreateSuccessResult(rBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				case 'W':
				case 'w':
					return OResult.CreateSuccessResult(wBuffer.GetBytes(Convert.ToInt32(address.Substring(1)) * 2, length * 2));
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = new OResult<byte[]>();
			try
			{
				switch (address[0])
				{
				case 'X':
				case 'x':
					xBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
					return OResult.CreateSuccessResult();
				case 'Y':
				case 'y':
					yBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
					return OResult.CreateSuccessResult();
				case 'M':
				case 'm':
					mBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
					return OResult.CreateSuccessResult();
				case 'D':
				case 'd':
					dBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
					return OResult.CreateSuccessResult();
				case 'R':
				case 'r':
					rBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
					return OResult.CreateSuccessResult();
				case 'W':
				case 'w':
					wBuffer.SetBytes(value, Convert.ToInt32(address.Substring(1)) * 2);
					return OResult.CreateSuccessResult();
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
		}

		private int GetBitIndex(string address)
		{
			int num = 0;
			if (address.LastIndexOf('.') > 0)
			{
				num = SnetHelper.GetBitIndexInformation(ref address);
				return Convert.ToInt32(address.Substring(1)) * 16 + num;
			}
			if (address[0] == 'X' || address[0] == 'x' || address[0] == 'Y' || address[0] == 'y' || address[0] == 'M' || address[0] == 'm')
			{
				return Convert.ToInt32(address.Substring(1));
			}
			return Convert.ToInt32(address.Substring(1)) * 16;
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPBOverTcp.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			try
			{
				int bitIndex = GetBitIndex(address);
				switch (address[0])
				{
				case 'X':
				case 'x':
					return OResult.CreateSuccessResult(xBuffer.GetBool(bitIndex, length));
				case 'Y':
				case 'y':
					return OResult.CreateSuccessResult(yBuffer.GetBool(bitIndex, length));
				case 'M':
				case 'm':
					return OResult.CreateSuccessResult(mBuffer.GetBool(bitIndex, length));
				case 'D':
				case 'd':
					return OResult.CreateSuccessResult(dBuffer.GetBool(bitIndex, length));
				case 'R':
				case 'r':
					return OResult.CreateSuccessResult(rBuffer.GetBool(bitIndex, length));
				case 'W':
				case 'w':
					return OResult.CreateSuccessResult(wBuffer.GetBool(bitIndex, length));
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<bool[]>(ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceCommunication.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			try
			{
				int bitIndex = GetBitIndex(address);
				switch (address[0])
				{
				case 'X':
				case 'x':
					xBuffer.SetBool(value, bitIndex);
					return OResult.CreateSuccessResult();
				case 'Y':
				case 'y':
					yBuffer.SetBool(value, bitIndex);
					return OResult.CreateSuccessResult();
				case 'M':
				case 'm':
					mBuffer.SetBool(value, bitIndex);
					return OResult.CreateSuccessResult();
				case 'D':
				case 'd':
					dBuffer.SetBool(value, bitIndex);
					return OResult.CreateSuccessResult();
				case 'R':
				case 'r':
					rBuffer.SetBool(value, bitIndex);
					return OResult.CreateSuccessResult();
				case 'W':
				case 'w':
					wBuffer.SetBool(value, bitIndex);
					return OResult.CreateSuccessResult();
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<bool[]>(ex.Message);
			}
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FujiSPBMessage();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive.Length < 5)
			{
				return new OResult<byte[]>("Uknown message: " + receive.ToHexString(' '));
			}
			if (receive[0] != 58)
			{
				return new OResult<byte[]>("Message must start with 0x3A: " + receive.ToHexString(' '));
			}
			if (Encoding.ASCII.GetString(receive, 1, 2) != station.ToString("X2"))
			{
				return new OResult<byte[]>($"Station not match , Except: {station:X2} , Actual: {Encoding.ASCII.GetString(receive, 1, 2)}");
			}
			return OResult.CreateSuccessResult(ReadFromSPBCore(receive));
		}

		private byte[] CreateResponseBack(byte err, string command, byte[] data, bool addLength = true)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(':');
			stringBuilder.Append(Station.ToString("X2"));
			stringBuilder.Append("00");
			stringBuilder.Append(command.Substring(9, 4));
			stringBuilder.Append(err.ToString("X2"));
			if (err == 0 && data != null)
			{
				if (addLength)
				{
					stringBuilder.Append(FujiSPBHelper.AnalysisIntegerAddress(data.Length / 2));
				}
				stringBuilder.Append(data.ToHexString());
			}
			stringBuilder[3] = ((stringBuilder.Length - 5) / 2).ToString("X2")[0];
			stringBuilder[4] = ((stringBuilder.Length - 5) / 2).ToString("X2")[1];
			stringBuilder.Append("\r\n");
			return Encoding.ASCII.GetBytes(stringBuilder.ToString());
		}

		private int AnalysisAddress(string address)
		{
			return Convert.ToInt32(address.Substring(2) + address.Substring(0, 2));
		}

		private byte[] ReadFromSPBCore(byte[] receive)
		{
			if (receive.Length < 15)
			{
				return null;
			}
			if (receive[^2] == 13 && receive[^1] == 10)
			{
				receive = receive.RemoveLast(2);
			}
			string text = Encoding.ASCII.GetString(receive);
			if (Convert.ToInt32(text.Substring(3, 2), 16) != (text.Length - 5) / 2)
			{
				return CreateResponseBack(3, text, null);
			}
			if (text.Substring(9, 4) == "0000")
			{
				return ReadByCommand(text);
			}
			if (text.Substring(9, 4) == "0100")
			{
				return WriteByCommand(text);
			}
			if (text.Substring(9, 4) == "0102")
			{
				return WriteBitByCommand(text);
			}
			return null;
		}

		private byte[] ReadByCommand(string command)
		{
			string text = command.Substring(13, 2);
			int num = AnalysisAddress(command.Substring(15, 4));
			int num2 = AnalysisAddress(command.Substring(19, 4));
			if (num2 > 105)
			{
				CreateResponseBack(3, command, null);
			}
			return text switch
			{
				"0C" => CreateResponseBack(0, command, dBuffer.GetBytes(num * 2, num2 * 2)), 
				"0D" => CreateResponseBack(0, command, rBuffer.GetBytes(num * 2, num2 * 2)), 
				"0E" => CreateResponseBack(0, command, wBuffer.GetBytes(num * 2, num2 * 2)), 
				"01" => CreateResponseBack(0, command, xBuffer.GetBytes(num * 2, num2 * 2)), 
				"00" => CreateResponseBack(0, command, yBuffer.GetBytes(num * 2, num2 * 2)), 
				"02" => CreateResponseBack(0, command, mBuffer.GetBytes(num * 2, num2 * 2)), 
				_ => CreateResponseBack(2, command, null), 
			};
		}

		private byte[] WriteByCommand(string command)
		{
			if (!base.EnableWrite)
			{
				return CreateResponseBack(2, command, null);
			}
			string text = command.Substring(13, 2);
			int num = AnalysisAddress(command.Substring(15, 4));
			if (AnalysisAddress(command.Substring(19, 4)) * 4 != command.Length - 23)
			{
				return CreateResponseBack(3, command, null);
			}
			byte[] data = command.Substring(23).ToHexBytes();
			switch (text)
			{
			case "0C":
				dBuffer.SetBytes(data, num * 2);
				return CreateResponseBack(0, command, null);
			case "0D":
				rBuffer.SetBytes(data, num * 2);
				return CreateResponseBack(0, command, null);
			case "0E":
				wBuffer.SetBytes(data, num * 2);
				return CreateResponseBack(0, command, null);
			case "00":
				yBuffer.SetBytes(data, num * 2);
				return CreateResponseBack(0, command, null);
			case "02":
				mBuffer.SetBytes(data, num * 2);
				return CreateResponseBack(0, command, null);
			default:
				return CreateResponseBack(2, command, null);
			}
		}

		private byte[] WriteBitByCommand(string command)
		{
			if (!base.EnableWrite)
			{
				return CreateResponseBack(2, command, null);
			}
			string text = command.Substring(13, 2);
			int num = AnalysisAddress(command.Substring(15, 4));
			int num2 = Convert.ToInt32(command.Substring(19, 2));
			bool value = command.Substring(21, 2) != "00";
			switch (text)
			{
			case "0C":
				dBuffer.SetBool(value, num * 8 + num2);
				return CreateResponseBack(0, command, null);
			case "0D":
				rBuffer.SetBool(value, num * 8 + num2);
				return CreateResponseBack(0, command, null);
			case "0E":
				wBuffer.SetBool(value, num * 8 + num2);
				return CreateResponseBack(0, command, null);
			case "00":
				yBuffer.SetBool(value, num * 8 + num2);
				return CreateResponseBack(0, command, null);
			case "02":
				mBuffer.SetBool(value, num * 8 + num2);
				return CreateResponseBack(0, command, null);
			default:
				return CreateResponseBack(2, command, null);
			}
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			return ModbusInfo.CheckAsciiReceiveDataComplete(buffer, receivedLength);
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				xBuffer.Dispose();
				yBuffer.Dispose();
				mBuffer.Dispose();
				dBuffer.Dispose();
				rBuffer.Dispose();
				wBuffer.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"FujiSPBServer[{base.Port}]";
		}
	}
	/// <summary>
	/// 富士PLC的SPH通信协议，可以和富士PLC进行通信，<see cref="P:Snet.Driver.Profinet.Fuji.FujiSPHNet.ConnectionID" />默认CPU0，需要根据实际进行调整。<br />
	/// The SPH communication protocol of Fujifilm PLC can communicate with Fujifilm PLC, <see cref="P:Snet.Driver.Profinet.Fuji.FujiSPHNet.ConnectionID" /> default CPU0, which needs to be adjusted according to the actual situation.
	/// </summary>
	/// <remarks>
	/// 地址支持 M1.0, M3.0, M10.0 以及I0, Q0
	/// </remarks>
	public class FujiSPHNet : DeviceTcpNet
	{
		/// <summary>
		/// 对于 CPU0-CPU7来说是CPU的站号，分为对应 0xFE-0xF7，对于P/PE link, FL-net是模块站号，分别对应0xF6-0xEF<br />
		/// CPU0 to CPU7: SX bus station No. of destination CPU (FEh to F7h); P/PE link, FL-net: SX bus station No. of destination module (F6H to EFH)
		/// </summary>
		public byte ConnectionID { get; set; } = 254;

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public FujiSPHNet()
		{
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
		}

		/// <summary>
		/// 指定IP地址和端口号来实例化一个对象<br />
		/// Specify the IP address and port number to instantiate an object
		/// </summary>
		/// <param name="ipAddress">Ip地址</param>
		/// <param name="port">端口号</param>
		public FujiSPHNet(string ipAddress, int port = 18245)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new FujiSPHMessage();
		}

		private OResult<byte[]> ReadFujiSPHAddress(FujiSPHAddress address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadCommand(ConnectionID, address, length);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			List<byte> list = new List<byte>();
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult<byte[]> oResult3 = ExtractActualData(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				list.AddRange(oResult3.Content);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <summary>
		/// 批量读取PLC的地址数据，长度单位为字。地址支持M1.1000，M3.1000，M10.1000，返回读取的原始字节数组。<br />
		/// Read PLC address data in batches, the length unit is words. The address supports M1.1000, M3.1000, M10.1000, 
		/// and returns the original byte array read.
		/// </summary>
		/// <param name="address">PLC的地址，支持M1.1000，M3.1000，M10.1000</param>
		/// <param name="length">读取的长度信息，按照字为单位</param>
		/// <returns>包含byte[]的原始字节数据内容</returns>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<FujiSPHAddress> oResult = FujiSPHAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			return ReadFujiSPHAddress(oResult.Content, length);
		}

		/// <summary>
		/// 批量写入字节数组到PLC的地址里，地址支持M1.1000，M3.1000，M10.1000，返回是否写入成功。<br />
		/// Batch write byte array to PLC address, the address supports M1.1000, M3.1000, M10.1000, 
		/// and return whether the writing is successful.
		/// </summary>
		/// <param name="address">PLC的地址，支持M1.1000，M3.1000，M10.1000</param>
		/// <param name="value">写入的原始字节数据</param>
		/// <returns>是否写入成功</returns>
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(ConnectionID, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ExtractActualData(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 批量读取位数据的方法，需要传入位地址，读取的位长度，地址示例：M1.100.5，M3.1000.12，M10.1000.0<br />
		/// To read the bit data in batches, you need to pass in the bit address, the length of the read bit, address examples: M1.100.5, M3.1000.12, M10.1000.0
		/// </summary>
		/// <param name="address">PLC的地址，示例：M1.100.5，M3.1000.12，M10.1000.0</param>
		/// <param name="length">读取的bool长度信息</param>
		/// <returns>包含bool[]的结果对象</returns>
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<FujiSPHAddress> oResult = FujiSPHAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<bool[]>();
			}
			int num = oResult.Content.BitIndex + length;
			int num2 = ((num % 16 == 0) ? (num / 16) : (num / 16 + 1));
			OResult<byte[]> oResult2 = ReadFujiSPHAddress(oResult.Content, (ushort)num2);
			if (!oResult2.IsSuccess)
			{
				return oResult2.ConvertFailed<bool[]>();
			}
			return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectMiddle(oResult.Content.BitIndex, length));
		}

		/// <summary>
		/// 批量写入位数据的方法，需要传入位地址，等待写入的boo[]数据，地址示例：M1.100.5，M3.1000.12，M10.1000.0<br />
		/// To write bit data in batches, you need to pass in the bit address and wait for the boo[] data to be written. Examples of addresses: M1.100.5, M3.1000.12, M10.1000.0
		/// </summary>
		/// <remarks>
		/// [警告] 由于协议没有提供位写入的命令，所有通过字写入间接实现，先读取字数据，修改中间的位，然后写入字数据，所以本质上不是安全的，确保相关的地址只有上位机可以写入。<br />
		/// [Warning] Since the protocol does not provide commands for bit writing, all are implemented indirectly through word writing. First read the word data, 
		/// modify the bits in the middle, and then write the word data, so it is inherently not safe. Make sure that the relevant address is only The host computer can write.
		/// </remarks>
		/// <param name="address">PLC的地址，示例：M1.100.5，M3.1000.12，M10.1000.0</param>
		/// <param name="value">等待写入的bool数组</param>
		/// <returns>是否写入成功的结果对象</returns>
		public override OResult Write(string address, bool[] value)
		{
			OResult<FujiSPHAddress> oResult = FujiSPHAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<bool[]>();
			}
			int num = oResult.Content.BitIndex + value.Length;
			int num2 = ((num % 16 == 0) ? (num / 16) : (num / 16 + 1));
			OResult<byte[]> oResult2 = ReadFujiSPHAddress(oResult.Content, (ushort)num2);
			if (!oResult2.IsSuccess)
			{
				return oResult2.ConvertFailed<bool[]>();
			}
			bool[] array = oResult2.Content.ToBoolArray();
			value.CopyTo(array, oResult.Content.BitIndex);
			OResult<byte[]> oResult3 = BuildWriteCommand(ConnectionID, address, array.ToByteArray());
			if (!oResult3.IsSuccess)
			{
				return oResult3.ConvertFailed<byte[]>();
			}
			OResult<byte[]> oResult4 = ReadFromCoreServer(oResult3.Content);
			if (!oResult4.IsSuccess)
			{
				return oResult4;
			}
			OResult<byte[]> oResult5 = ExtractActualData(oResult4.Content);
			if (!oResult5.IsSuccess)
			{
				return oResult5;
			}
			return OResult.CreateSuccessResult();
		}

		private async Task<OResult<byte[]>> ReadFujiSPHAddressAsync(FujiSPHAddress address, ushort length)
		{
			OResult<List<byte[]>> command = BuildReadCommand(ConnectionID, address, length);
			if (!command.IsSuccess)
			{
				return command.ConvertFailed<byte[]>();
			}
			List<byte> array = new List<byte>();
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = ExtractActualData(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				array.AddRange(oResult2.Content);
			}
			return OResult.CreateSuccessResult(array.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPHNet.Read(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<FujiSPHAddress> oResult = FujiSPHAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			return await ReadFujiSPHAddressAsync(oResult.Content, length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPHNet.Write(System.String,System.Byte[])" />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(ConnectionID, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ExtractActualData(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPHNet.ReadBool(System.String,System.UInt16)" />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			OResult<FujiSPHAddress> analysis = FujiSPHAddress.ParseFrom(address);
			if (!analysis.IsSuccess)
			{
				return analysis.ConvertFailed<bool[]>();
			}
			int num = analysis.Content.BitIndex + length;
			OResult<byte[]> oResult = await ReadFujiSPHAddressAsync(length: (ushort)((num % 16 == 0) ? (num / 16) : (num / 16 + 1)), address: analysis.Content);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<bool[]>();
			}
			return OResult.CreateSuccessResult(oResult.Content.ToBoolArray().SelectMiddle(analysis.Content.BitIndex, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.Fuji.FujiSPHNet.Write(System.String,System.Boolean[])" />
		public override async Task<OResult> WriteAsync(string address, bool[] value)
		{
			OResult<FujiSPHAddress> analysis = FujiSPHAddress.ParseFrom(address);
			if (!analysis.IsSuccess)
			{
				return analysis.ConvertFailed<bool[]>();
			}
			int num = analysis.Content.BitIndex + value.Length;
			OResult<byte[]> oResult = await ReadFujiSPHAddressAsync(length: (ushort)((num % 16 == 0) ? (num / 16) : (num / 16 + 1)), address: analysis.Content);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<bool[]>();
			}
			bool[] array = oResult.Content.ToBoolArray();
			value.CopyTo(array, analysis.Content.BitIndex);
			OResult<byte[]> oResult2 = BuildWriteCommand(ConnectionID, address, array.ToByteArray());
			if (!oResult2.IsSuccess)
			{
				return oResult2.ConvertFailed<byte[]>();
			}
			OResult<byte[]> oResult3 = await ReadFromCoreServerAsync(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			OResult<byte[]> oResult4 = ExtractActualData(oResult3.Content);
			if (!oResult4.IsSuccess)
			{
				return oResult4;
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// This command is used to start all the CPUs that exist in a configuration in a batch. 
		/// Each CPU is cold-started or warm-started,depending on its condition. If a CPU is already started up, 
		/// or if the key switch is set at "RUN" position, the CPU does not perform processing for startup, 
		/// which, however, does not result in an error, and a response is returned normally
		/// </summary>
		/// <returns>是否启动成功</returns>
		public OResult CpuBatchStart()
		{
			return ReadFromCoreServer(PackCommand(ConnectionID, 4, 0, null)).Check((Func<byte[], OResult>)ExtractActualData);
		}

		/// <summary>
		/// This command is used to initialize and start all the CPUs that exist in a configuration in a batch. Each CPU is cold-started.
		/// If a CPU is already started up, or if the key switch is set at "RUN" position, the CPU does not perform processing for initialization 
		/// and startup, which, however, does not result in an error, and a response is returned normally.
		/// </summary>
		/// <returns>是否启动成功</returns>
		public OResult CpuBatchInitializeAndStart()
		{
			return ReadFromCoreServer(PackCommand(ConnectionID, 4, 1, null)).Check((Func<byte[], OResult>)ExtractActualData);
		}

