	/// <summary>
	/// 永宏编程口协议的虚拟PLC，可以用来和<see cref="T:Snet.Driver.Profinet.FATEK.FatekProgram" />及<see cref="T:Snet.Driver.Profinet.FATEK.FatekProgramOverTcp" />类做通信测试，支持简单数据的读写操作。<br />
	/// The virtual PLC of Yonghong programming port protocol can be used to communicate with <see cref="T:Snet.Driver.Profinet.FATEK.FatekProgram" /> and <see cref="T:Snet.Driver.Profinet.FATEK.FatekProgramOverTcp" /> class, 
	/// and support simple data read and write operations.
	/// </summary>
	public class FatekProgramServer : DeviceServer
	{
		private SoftBuffer xBuffer;

		private SoftBuffer yBuffer;

		private SoftBuffer mBuffer;

		private SoftBuffer sBuffer;

		private SoftBuffer tBuffer;

		private SoftBuffer cBuffer;

		private SoftBuffer tmrBuffer;

		private SoftBuffer ctrBuffer;

		private SoftBuffer hrBuffer;

		private SoftBuffer drBuffer;

		private byte station = 1;

		private const int DataPoolLength = 65536;

		private bool run;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.FATEK.FatekProgram.Station" />
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 实例化一个基于Programe协议的虚拟的永宏PLC对象，可以用来和<see cref="T:Snet.Driver.Profinet.FATEK.FatekProgram" />进行通信测试。
		/// </summary>
		public FatekProgramServer()
		{
			xBuffer = new SoftBuffer(65536);
			yBuffer = new SoftBuffer(65536);
			mBuffer = new SoftBuffer(65536);
			sBuffer = new SoftBuffer(65536);
			tBuffer = new SoftBuffer(65536);
			cBuffer = new SoftBuffer(65536);
			tmrBuffer = new SoftBuffer(131072);
			ctrBuffer = new SoftBuffer(131072);
			hrBuffer = new SoftBuffer(131072);
			drBuffer = new SoftBuffer(131072);
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
			LogMsgFormatBinary = false;
			base.WordLength = 1;
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			byte[] array = new byte[917504];
			xBuffer.GetBytes().CopyTo(array, 0);
			yBuffer.GetBytes().CopyTo(array, 65536);
			mBuffer.GetBytes().CopyTo(array, 131072);
			sBuffer.GetBytes().CopyTo(array, 196608);
			tBuffer.GetBytes().CopyTo(array, 262144);
			cBuffer.GetBytes().CopyTo(array, 327680);
			tmrBuffer.GetBytes().CopyTo(array, 393216);
			ctrBuffer.GetBytes().CopyTo(array, 524288);
			hrBuffer.GetBytes().CopyTo(array, 655360);
			drBuffer.GetBytes().CopyTo(array, 786432);
			return array;
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			if (content.Length < 917504)
			{
				throw new Exception("File is not correct");
			}
			xBuffer.SetBytes(content, 0, 65536);
			yBuffer.SetBytes(content, 65536, 65536);
			mBuffer.SetBytes(content, 131072, 65536);
			sBuffer.SetBytes(content, 196608, 65536);
			tBuffer.SetBytes(content, 262144, 65536);
			cBuffer.SetBytes(content, 327680, 65536);
			tmrBuffer.SetBytes(content, 393216, 131072);
			ctrBuffer.SetBytes(content, 524288, 131072);
			hrBuffer.SetBytes(content, 655360, 131072);
			drBuffer.SetBytes(content, 786432, 131072);
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<FatekProgramAddress> oResult = FatekProgramAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			if (oResult.Content.DataCode == "D")
			{
				return OResult.CreateSuccessResult(drBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
			}
			if (oResult.Content.DataCode == "R")
			{
				return OResult.CreateSuccessResult(hrBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
			}
			if (oResult.Content.DataCode == "RT")
			{
				return OResult.CreateSuccessResult(tmrBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
			}
			if (oResult.Content.DataCode == "CT")
			{
				return OResult.CreateSuccessResult(ctrBuffer.GetBytes(oResult.Content.AddressStart * 2, length * 2));
			}
			if (oResult.Content.DataCode == "X")
			{
				return OResult.CreateSuccessResult(xBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.DataCode == "Y")
			{
				return OResult.CreateSuccessResult(yBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.DataCode == "M")
			{
				return OResult.CreateSuccessResult(mBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.DataCode == "S")
			{
				return OResult.CreateSuccessResult(sBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.DataCode == "T")
			{
				return OResult.CreateSuccessResult(tBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			if (oResult.Content.DataCode == "C")
			{
				return OResult.CreateSuccessResult(cBuffer.GetBool(oResult.Content.AddressStart, length * 16).ToByteArray());
			}
			return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<FatekProgramAddress> oResult = FatekProgramAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			if (oResult.Content.DataCode == "D")
			{
				drBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
			}
			else if (oResult.Content.DataCode == "R")
			{
				hrBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
			}
			else if (oResult.Content.DataCode == "RT")
			{
				tmrBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
			}
			else if (oResult.Content.DataCode == "CT")
			{
				ctrBuffer.SetBytes(value, oResult.Content.AddressStart * 2);
			}
			else if (oResult.Content.DataCode == "X")
			{
				xBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else if (oResult.Content.DataCode == "Y")
			{
				yBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else if (oResult.Content.DataCode == "M")
			{
				mBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else if (oResult.Content.DataCode == "S")
			{
				sBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else if (oResult.Content.DataCode == "T")
			{
				tBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			else
			{
				if (!(oResult.Content.DataCode == "C"))
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
				}
				cBuffer.SetBool(value.ToBoolArray(), oResult.Content.AddressStart);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadBool(System.String,System.UInt16)" />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			OResult<FatekProgramAddress> oResult = FatekProgramAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<bool[]>();
			}
			if (oResult.Content.DataCode == "X")
			{
				return OResult.CreateSuccessResult(xBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.DataCode == "Y")
			{
				return OResult.CreateSuccessResult(yBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.DataCode == "M")
			{
				return OResult.CreateSuccessResult(mBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.DataCode == "S")
			{
				return OResult.CreateSuccessResult(sBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.DataCode == "T")
			{
				return OResult.CreateSuccessResult(tBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			if (oResult.Content.DataCode == "C")
			{
				return OResult.CreateSuccessResult(cBuffer.GetBool(oResult.Content.AddressStart, length));
			}
			return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean[])" />
		public override OResult Write(string address, bool[] value)
		{
			OResult<FatekProgramAddress> oResult = FatekProgramAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			if (oResult.Content.DataCode == "X")
			{
				xBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.DataCode == "Y")
			{
				yBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.DataCode == "M")
			{
				mBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.DataCode == "S")
			{
				sBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else if (oResult.Content.DataCode == "T")
			{
				tBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			else
			{
				if (!(oResult.Content.DataCode == "C"))
				{
					return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
				}
				cBuffer.SetBool(value, oResult.Content.AddressStart);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new SpecifiedCharacterMessage(3);
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			if (receivedLength < 5)
			{
				return false;
			}
			return buffer[receivedLength - 1] == 3;
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			byte b = Convert.ToByte(Encoding.ASCII.GetString(receive, 1, 2), 16);
			if (b != Station)
			{
				return new OResult<byte[]>($"Station is not match, need [{station}] but actual is [{b}]");
			}
			switch (Encoding.ASCII.GetString(receive, 3, 2))
			{
			case "44":
				return OResult.CreateSuccessResult(ReadBoolByMessage(receive));
			case "45":
				return OResult.CreateSuccessResult(WriteBoolByMessage(receive));
			case "46":
				return OResult.CreateSuccessResult(ReadWordByMessage(receive));
			case "47":
				return OResult.CreateSuccessResult(WriteWordByMessage(receive));
			case "41":
				run = receive[5] == 49;
				return OResult.CreateSuccessResult(PackResponseBack(receive, 48, null));
			case "40":
				return OResult.CreateSuccessResult(PackResponseBack(receive, 48, Encoding.ASCII.GetBytes(new byte[3]
				{
					run ? ((byte)1) : ((byte)0),
					0,
					0
				}.ToHexString())));
			default:
				return OResult.CreateSuccessResult(PackResponseBack(receive, 52, null));
			}
		}

		private byte[] PackResponseBack(byte[] receive, byte err, byte[] value)
		{
			if (value == null)
			{
				value = new byte[0];
			}
			byte[] array = new byte[9 + value.Length];
			array[0] = 2;
			array[1] = receive[1];
			array[2] = receive[2];
			array[3] = receive[3];
			array[4] = receive[4];
			array[5] = err;
			value.CopyTo(array, 6);
			SoftLRC.CalculateAccAndFill(array, 0, 3);
			array[^1] = 3;
			return array;
		}

		private SoftBuffer GetBoolBuffer(char code)
		{
			return code switch
			{
				'X' => xBuffer, 
				'Y' => yBuffer, 
				'M' => mBuffer, 
				'S' => sBuffer, 
				'T' => tBuffer, 
				'C' => cBuffer, 
				_ => null, 
			};
		}

		private SoftBuffer GetWordBuffer(byte[] receive, out int address)
		{
			if (Encoding.ASCII.GetString(receive, 7, 2) == "RT")
			{
				address = Convert.ToInt32(Encoding.ASCII.GetString(receive, 9, 4));
				return tmrBuffer;
			}
			if (Encoding.ASCII.GetString(receive, 7, 2) == "RC")
			{
				address = Convert.ToInt32(Encoding.ASCII.GetString(receive, 9, 4));
				return ctrBuffer;
			}
			if (Encoding.ASCII.GetString(receive, 7, 1) == "D")
			{
				address = Convert.ToInt32(Encoding.ASCII.GetString(receive, 8, 5));
				return drBuffer;
			}
			if (Encoding.ASCII.GetString(receive, 7, 1) == "R")
			{
				address = Convert.ToInt32(Encoding.ASCII.GetString(receive, 8, 5));
				return hrBuffer;
			}
			address = 0;
			return null;
		}

		private byte[] ReadBoolByMessage(byte[] receive)
		{
			int num = Convert.ToInt32(Encoding.ASCII.GetString(receive, 5, 2), 16);
			if (num == 0)
			{
				num = 256;
			}
			int destIndex = Convert.ToInt32(Encoding.ASCII.GetString(receive, 8, 4), 10);
			SoftBuffer boolBuffer = GetBoolBuffer((char)receive[7]);
			if (boolBuffer == null)
			{
				return PackResponseBack(receive, 52, null);
			}
			return PackResponseBack(receive, 48, (from m in boolBuffer.GetBool(destIndex, num)
				select (byte)(m ? 49u : 48u)).ToArray());
		}

		private byte[] WriteBoolByMessage(byte[] receive)
		{
			int num = Convert.ToInt32(Encoding.ASCII.GetString(receive, 5, 2), 16);
			if (num == 0)
			{
				num = 256;
			}
			int destIndex = Convert.ToInt32(Encoding.ASCII.GetString(receive, 8, 4), 10);
			SoftBuffer boolBuffer = GetBoolBuffer((char)receive[7]);
			if (boolBuffer == null)
			{
				return PackResponseBack(receive, 52, null);
			}
			bool[] value = (from m in receive.SelectMiddle(12, num)
				select m == 49).ToArray();
			boolBuffer.SetBool(value, destIndex);
			return PackResponseBack(receive, 48, null);
		}

		private byte[] ReadWordByMessage(byte[] receive)
		{
			int num = Convert.ToInt32(Encoding.ASCII.GetString(receive, 5, 2), 16);
			if (num > 64)
			{
				return PackResponseBack(receive, 50, null);
			}
			SoftBuffer wordBuffer = GetWordBuffer(receive, out var address);
			if (wordBuffer == null)
			{
				return PackResponseBack(receive, 52, null);
			}
			return PackResponseBack(receive, 48, Encoding.ASCII.GetBytes(wordBuffer.GetBytes(address * 2, num * 2).ToHexString()));
		}

		private byte[] WriteWordByMessage(byte[] receive)
		{
			int num = Convert.ToInt32(Encoding.ASCII.GetString(receive, 5, 2), 16);
			if (num > 64)
			{
				return PackResponseBack(receive, 50, null);
			}
			SoftBuffer wordBuffer = GetWordBuffer(receive, out var address);
			if (wordBuffer == null)
			{
				return PackResponseBack(receive, 52, null);
			}
			byte[] data = Encoding.ASCII.GetString(receive, 13, num * 4).ToHexBytes();
			wordBuffer.SetBytes(data, address * 2);
			return PackResponseBack(receive, 48, null);
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				xBuffer.Dispose();
				yBuffer.Dispose();
				mBuffer.Dispose();
				sBuffer.Dispose();
				tBuffer.Dispose();
				cBuffer.Dispose();
				tmrBuffer.Dispose();
				ctrBuffer.Dispose();
				hrBuffer.Dispose();
				drBuffer.Dispose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"FatekProgramServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.FATEK.Helper
{
	/// <summary>
	/// FatekProgram相关的辅助方法，例如报文构建，核心读写支持
	/// </summary>
	public class FatekProgramHelper
	{
		/// <summary>
		/// 计算指令的和校验码
		/// </summary>
		/// <param name="data">指令</param>
		/// <returns>校验之后的信息</returns>
		public static string CalculateAcc(string data)
		{
			byte[] bytes = Encoding.ASCII.GetBytes(data);
			int num = 0;
			for (int i = 0; i < bytes.Length; i++)
			{
				num += bytes[i];
			}
			return num.ToString("X4").Substring(2);
		}

		/// <summary>
		/// 检查当前的串口的数据接收是否完整
		/// </summary>
		/// <param name="ms">数据流</param>
		/// <returns>是否数据接收完成</returns>
		public static bool CheckReceiveDataComplete(MemoryStream ms)
		{
			byte[] array = ms.ToArray();
			if (array.Length < 5)
			{
				return false;
			}
			return array[^1] == 3;
		}

		/// <summary>
		/// 将Fatek的基本命令打包成可以发送PLC的电文消息
		/// </summary>
		/// <param name="station">PLC的站号信息</param>
		/// <param name="cmd">基本命令信息</param>
		/// <returns>发送PLC的电文消息</returns>
		public static byte[] PackFatekCommand(byte station, string cmd)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append('\u0002');
			stringBuilder.Append(station.ToString("X2"));
			byte[] array = new byte[6 + cmd.Length];
			array[0] = 2;
			array[1] = SoftBasic.BuildAsciiBytesFrom(station)[0];
			array[2] = SoftBasic.BuildAsciiBytesFrom(station)[1];
			Encoding.ASCII.GetBytes(cmd).CopyTo(array, 3);
			SoftLRC.CalculateAccAndFill(array, 0, 3);
			array[^1] = 3;
			return array;
		}

		/// <summary>
		/// 创建一条读取的指令信息，需要指定一些参数
		/// </summary>
		/// <param name="station">PLC的站号</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<List<byte[]>> BuildReadWordCommand(byte station, string address, ushort length)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<FatekProgramAddress> oResult = FatekProgramAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<List<byte[]>>();
			}
			List<byte[]> list = new List<byte[]>();
			int[] array = SoftBasic.SplitIntegerToArray(length, 64);
			for (int i = 0; i < array.Length; i++)
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("46");
				stringBuilder.Append(array[i].ToString("X2"));
				if (oResult.Content.DataCode.StartsWith("X") || oResult.Content.DataCode.StartsWith("Y") || oResult.Content.DataCode.StartsWith("M") || oResult.Content.DataCode.StartsWith("S") || oResult.Content.DataCode.StartsWith("T") || oResult.Content.DataCode.StartsWith("C"))
				{
					stringBuilder.Append("W");
				}
				stringBuilder.Append(oResult.Content.ToString());
				list.Add(PackFatekCommand(station, stringBuilder.ToString()));
				if (oResult.Content.DataCode.StartsWith("X") || oResult.Content.DataCode.StartsWith("Y") || oResult.Content.DataCode.StartsWith("M") || oResult.Content.DataCode.StartsWith("S") || oResult.Content.DataCode.StartsWith("T") || oResult.Content.DataCode.StartsWith("C"))
				{
					oResult.Content.AddressStart += array[i] * 16;
				}
				else
				{
					oResult.Content.AddressStart += array[i];
				}
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 创建一条读取的指令信息，需要指定一些参数
		/// </summary>
		/// <param name="station">PLC的站号</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<List<byte[]>> BuildReadBoolCommand(byte station, string address, ushort length)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<FatekProgramAddress> oResult = FatekProgramAddress.ParseFrom(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<List<byte[]>>();
			}
			List<byte[]> list = new List<byte[]>();
			int[] array = SoftBasic.SplitIntegerToArray(length, 255);
			for (int i = 0; i < array.Length; i++)
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("44");
				stringBuilder.Append(array[i].ToString("X2"));
				stringBuilder.Append(oResult.Content.ToString());
				list.Add(PackFatekCommand(station, stringBuilder.ToString()));
				oResult.Content.AddressStart += array[i];
			}
			return OResult.CreateSuccessResult(list);
		}

		/// <summary>
		/// 提取当前的结果数据信息，针对的是字单位的方式
		/// </summary>
		/// <param name="response">PLC返回的数据信息</param>
		/// <param name="length">读取的长度内容</param>
		/// <returns>结果数组</returns>
		public static byte[] ExtraResponse(byte[] response, ushort length)
		{
			byte[] array = new byte[length * 2];
			for (int i = 0; i < array.Length / 2; i++)
			{
				BitConverter.GetBytes(Convert.ToUInt16(Encoding.ASCII.GetString(response, i * 4 + 6, 4), 16)).CopyTo(array, i * 2);
			}
			return array;
		}

		/// <summary>
		/// 创建一条别入bool数据的指令信息，需要指定一些参数
		/// </summary>
		/// <param name="station">站号</param>
		/// <param name="address">地址</param>
		/// <param name="value">数组值</param>
		/// <returns>是否创建成功</returns>
		public static OResult<byte[]> BuildWriteBoolCommand(byte station, string address, bool[] value)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<FatekProgramAddress> oResult = FatekProgramAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("45");
			stringBuilder.Append(value.Length.ToString("X2"));
			stringBuilder.Append(oResult.Content.ToString());
			for (int i = 0; i < value.Length; i++)
			{
				stringBuilder.Append(value[i] ? "1" : "0");
			}
			return OResult.CreateSuccessResult(PackFatekCommand(station, stringBuilder.ToString()));
		}

		/// <summary>
		/// 创建一条别入byte数据的指令信息，需要指定一些参数，按照字单位
		/// </summary>
		/// <param name="station">站号</param>
		/// <param name="address">地址</param>
		/// <param name="value">数组值</param>
		/// <returns>是否创建成功</returns>
		public static OResult<byte[]> BuildWriteByteCommand(byte station, string address, byte[] value)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			OResult<FatekProgramAddress> oResult = FatekProgramAddress.ParseFrom(address, 0);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("47");
			stringBuilder.Append((value.Length / 2).ToString("X2"));
			if (oResult.Content.DataCode.StartsWith("X") || oResult.Content.DataCode.StartsWith("Y") || oResult.Content.DataCode.StartsWith("M") || oResult.Content.DataCode.StartsWith("S") || oResult.Content.DataCode.StartsWith("T") || oResult.Content.DataCode.StartsWith("C"))
			{
				stringBuilder.Append("W");
			}
			stringBuilder.Append(oResult.Content.ToString());
			byte[] array = new byte[value.Length * 2];
			for (int i = 0; i < value.Length / 2; i++)
			{
				SoftBasic.BuildAsciiBytesFrom(BitConverter.ToUInt16(value, i * 2)).CopyTo(array, 4 * i);
			}
			stringBuilder.Append(Encoding.ASCII.GetString(array));
			return OResult.CreateSuccessResult(PackFatekCommand(station, stringBuilder.ToString()));
		}

		/// <summary>
		/// 检查PLC反馈的报文是否正确，如果不正确，返回错误消息
		/// </summary>
		/// <param name="content">PLC反馈的报文信息</param>
		/// <returns>反馈的报文是否正确</returns>
		public static OResult CheckResponse(byte[] content)
		{
			try
			{
				if (content[0] != 2)
				{
					return new OResult(content[0], "Write Faild:" + SoftBasic.ByteToHexString(content, ' '));
				}
				if (content[5] != 48)
				{
					return new OResult(content[5], GetErrorDescriptionFromCode((char)content[5]));
				}
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				return new OResult("CheckResponse failed: " + ex.Message + Environment.NewLine + "Source: " + content.ToHexString(' '));
			}
		}

		/// <summary>
		/// 根据错误码获取到真实的文本信息
		/// </summary>
		/// <param name="code">错误码</param>
		/// <returns>错误的文本描述</returns>
		public static string GetErrorDescriptionFromCode(char code)
		{
			return code switch
			{
				'2' => StringResources.Language.FatekStatus02, 
				'3' => StringResources.Language.FatekStatus03, 
				'4' => StringResources.Language.FatekStatus04, 
				'5' => StringResources.Language.FatekStatus05, 
				'6' => StringResources.Language.FatekStatus06, 
				'7' => StringResources.Language.FatekStatus07, 
				'9' => StringResources.Language.FatekStatus09, 
				'A' => StringResources.Language.FatekStatus10, 
				_ => StringResources.Language.UnknownError, 
			};
		}

		/// <summary>
		/// 批量读取PLC的字节数据，以字为单位，支持读取X,Y,M,S,D,T,C,R,RT,RC具体的地址范围需要根据PLC型号来确认，地址可以携带站号信息，例如 s=2;D100<br />
		/// Read PLC byte data in batches, in word units. Supports reading X, Y, M, S, D, T, C, R, RT, RC. 
		/// The specific address range needs to be confirmed according to the PLC model, The address can carry station number information, such as s=2;D100
		/// </summary>
		/// <param name="device">PLC通信的对象</param>
		/// <param name="station">设备的站点信息</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>读取结果信息</returns>
		public static OResult<byte[]> Read(IReadWriteDevice device, byte station, string address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadWordCommand(station, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			List<byte> list = new List<byte>();
			int[] array = SoftBasic.SplitIntegerToArray(length, 64);
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = device.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				OResult oResult3 = CheckResponse(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3.ConvertFailed<byte[]>();
				}
				list.AddRange(ExtraResponse(oResult2.Content, (ushort)array[i]));
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.FATEK.Helper.FatekProgramHelper.Read(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.UInt16)" />
		public static async Task<OResult<byte[]>> ReadAsync(IReadWriteDevice device, byte station, string address, ushort length)
		{
			OResult<List<byte[]>> command = BuildReadWordCommand(station, address, length);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(command);
			}
			List<byte> content = new List<byte>();
			int[] splits = SoftBasic.SplitIntegerToArray(length, 64);
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await device.ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				OResult oResult2 = CheckResponse(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2.ConvertFailed<byte[]>();
				}
				content.AddRange(ExtraResponse(oResult.Content, (ushort)splits[i]));
			}
			return OResult.CreateSuccessResult(content.ToArray());
		}

		/// <summary>
		/// 批量写入PLC的数据，以字为单位，也就是说最少2个字节信息，支持X,Y,M,S,D,T,C,R,RT,RC具体的地址范围需要根据PLC型号来确认，地址可以携带站号信息，例如 s=2;D100<br />
		/// The data written to the PLC in batches, in units of words, that is, at least 2 bytes of information, 
		/// supporting X, Y, M, S, D, T, C, R, RT, and RC. The specific address range needs to be based on the PLC model To confirm, The address can carry station number information, such as s=2;D100
		/// </summary>
		/// <param name="device">PLC通信的对象</param>
		/// <param name="station">设备的站号信息</param>
		/// <param name="address">地址信息，举例，D100，R200，RC100，RT200</param>
		/// <param name="value">数据值</param>
		/// <returns>是否写入成功</returns>
		public static OResult Write(IReadWriteDevice device, byte station, string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteByteCommand(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = device.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult();
		}

