		public static async Task<OResult> WriteAsync(IReadWriteDevice device, byte station, string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteByteCommand(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await device.ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 批量读取bool类型数据，支持的类型为X,Y,M,S,T,C，具体的地址范围取决于PLC的类型，地址可以携带站号信息，例如 s=2;M100<br />
		/// Read bool data in batches. The supported types are X, Y, M, S, T, C. The specific address range depends on the type of PLC, 
		/// The address can carry station number information, such as s=2;M100
		/// </summary>
		/// <param name="device">PLC通信对象</param>
		/// <param name="station">设备的站号信息</param>
		/// <param name="address">地址信息，比如X10，Y17，M100</param>
		/// <param name="length">读取的长度</param>
		/// <returns>读取结果信息</returns>
		public static OResult<bool[]> ReadBool(IReadWriteDevice device, byte station, string address, ushort length)
		{
			OResult<List<byte[]>> oResult = BuildReadBoolCommand(station, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			List<bool> list = new List<bool>();
			int[] array = SoftBasic.SplitIntegerToArray(length, 255);
			for (int i = 0; i < oResult.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = device.ReadFromCoreServer(oResult.Content[i]);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				OResult oResult3 = CheckResponse(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					return oResult3.ConvertFailed<bool[]>();
				}
				if (oResult2.Content.Length < 6 + array[i])
				{
					return new OResult<bool[]>(StringResources.Language.ReceiveDataLengthTooShort + " Source: " + oResult2.Content.ToHexString(' '));
				}
				list.AddRange(from m in oResult2.Content.SelectMiddle(6, array[i])
					select m == 49);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.FATEK.Helper.FatekProgramHelper.ReadBool(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.UInt16)" />
		public static async Task<OResult<bool[]>> ReadBoolAsync(IReadWriteDevice device, byte station, string address, ushort length)
		{
			OResult<List<byte[]>> command = BuildReadBoolCommand(station, address, length);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(command);
			}
			List<bool> content = new List<bool>();
			int[] splits = SoftBasic.SplitIntegerToArray(length, 255);
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult = await device.ReadFromCoreServerAsync(command.Content[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				OResult oResult2 = CheckResponse(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2.ConvertFailed<bool[]>();
				}
				if (oResult.Content.Length < 6 + splits[i])
				{
					return new OResult<bool[]>(StringResources.Language.ReceiveDataLengthTooShort + " Source: " + oResult.Content.ToHexString(' '));
				}
				content.AddRange(from m in oResult.Content.SelectMiddle(6, splits[i])
					select m == 49);
			}
			return OResult.CreateSuccessResult(content.ToArray());
		}

