		/// <summary>
		/// 读取当前PLC的状态信息，返回一个bool数组，同时包含了几种电量信息，分别为 0: RUN/STOP, 1: BAT LOW/正常, 2: Ladder checksum error/正常, 3: 使用ROM PACK/未使用, 
		/// 4: WDT Timeout/正常, 5: 设定ID/未设ID， 6： 紧急停机/正常<br />
		/// Read the status information of the current PLC and return a bool array, which also contains several power information, 0: RUN/STOP, 1: BAT LOW/normal, 
		/// 2: Ladder checksum error/normal, 3: Use ROM PACK/ Not used, 4: WDT Timeout/Normal, 5: ID set/ID not set, 6: Emergency stop/Normal
		/// </summary>
		/// <param name="device">PLC通信对象</param>
		/// <param name="station">站号信息</param>
		/// <returns>状态结果信息</returns>
		public static OResult<bool[]> ReadStatus(IReadWriteDevice device, byte station)
		{
			OResult<byte[]> oResult = device.ReadFromCoreServer(PackFatekCommand(station, "40"));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult oResult2 = CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2.ConvertFailed<bool[]>();
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult.Content, 6, 2).ToHexBytes().ToBoolArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.FATEK.Helper.FatekProgramHelper.Stop(Snet.Driver.Core.IReadWriteDevice,System.Byte)" />
		public static async Task<OResult<bool[]>> ReadStatusAsync(IReadWriteDevice device, byte station)
		{
			OResult<byte[]> oResult = await device.ReadFromCoreServerAsync(PackFatekCommand(station, "40"));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult oResult2 = CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2.ConvertFailed<bool[]>();
			}
			return OResult.CreateSuccessResult(Encoding.ASCII.GetString(oResult.Content, 6, 2).ToHexBytes().ToBoolArray());
		}
	}
