namespace Snet.Driver.Profinet.Delta.Helper
{
	/// <summary>
	/// 台达AS300的辅助帮助类信息
	/// </summary>
	public class DeltaASHelper
	{
		private static int ParseDeltaBitAddress(string address)
		{
			int num = address.IndexOf('.');
			if (num > 0)
			{
				return Convert.ToInt32(address.Substring(0, num)) * 16 + SnetHelper.CalculateBitStartIndex(address.Substring(num + 1));
			}
			return Convert.ToInt32(address) * 16;
		}

		/// <summary>
		/// 根据台达AS300的PLC的地址，解析出转换后的modbus协议信息，适用AS300系列，当前的地址仍然支持站号指定，例如s=2;D100<br />
		/// According to the PLC address of Delta AS300, the converted modbus protocol information is parsed, 
		/// and it is applicable to AS300 series. The current address still supports station number designation, for example, s=2;D100
		/// </summary>
		/// <param name="address">台达plc的地址信息</param>
		/// <param name="modbusCode">原始的对应的modbus信息</param>
		/// <returns>还原后的modbus地址</returns>
		public static OResult<string> ParseDeltaASAddress(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWith("SM") || address.StartsWith("sm"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 16384));
					}
					if (address.StartsWith("HC") || address.StartsWith("hc"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 64512));
					}
					if (address.StartsWith("S") || address.StartsWith("s"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 20480));
					}
					if (address.StartsWith("X") || address.StartsWith("x"))
					{
						return OResult.CreateSuccessResult(text + "x=2;" + (ParseDeltaBitAddress(address.Substring(1)) + 24576));
					}
					if (address.StartsWith("Y") || address.StartsWith("y"))
					{
						return OResult.CreateSuccessResult(text + (ParseDeltaBitAddress(address.Substring(1)) + 40960));
					}
					if (address.StartsWith("T") || address.StartsWith("t"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 57344));
					}
					if (address.StartsWith("C") || address.StartsWith("c"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 61440));
					}
					if (address.StartsWith("M") || address.StartsWith("m"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWith("D") && address.Contains("."))
					{
						return OResult.CreateSuccessResult(text + address);
					}
				}
				else
				{
					if (address.StartsWith("SR") || address.StartsWith("sr"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 49152));
					}
					if (address.StartsWith("HC") || address.StartsWith("hc"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 64512));
					}
					if (address.StartsWith("D") || address.StartsWith("d"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWith("X") || address.StartsWith("x"))
					{
						return OResult.CreateSuccessResult(text + "x=4;" + (Convert.ToInt32(address.Substring(1)) + 32768));
					}
					if (address.StartsWith("Y") || address.StartsWith("y"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 40960));
					}
					if (address.StartsWith("C") || address.StartsWith("c"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 61440));
					}
					if (address.StartsWith("T") || address.StartsWith("t"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 57344));
					}
					if (address.StartsWith("E") || address.StartsWith("e"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 65024));
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}
	}
	/// <summary>
	/// 台达PLC的相关的帮助类，公共的地址解析的方法。<br />
	/// Delta PLC related help classes, public address resolution methods.
	/// </summary>
	public class DeltaDvpHelper
	{
		private static int TransDAdressToModbusAddress(string address)
		{
			int num = Convert.ToInt32(address);
			if (num >= 4096)
			{
				return num - 4096 + 36864;
			}
			return num + 4096;
		}

		/// <summary>
		/// 根据台达PLC的地址，解析出转换后的modbus协议信息，适用DVP系列，当前的地址仍然支持站号指定，例如s=2;D100<br />
		/// According to the address of Delta PLC, the converted modbus protocol information is parsed out, applicable to DVP series, 
		/// the current address still supports station number designation, such as s=2;D100
		/// </summary>
		/// <param name="address">台达plc的地址信息</param>
		/// <param name="modbusCode">原始的对应的modbus信息</param>
		/// <returns>还原后的modbus地址</returns>
		public static OResult<string> ParseDeltaDvpAddress(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWithAndNumber("S"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWithAndNumber("X"))
					{
						return OResult.CreateSuccessResult(text + "x=2;" + (Convert.ToInt32(address.Substring(1), 8) + 1024));
					}
					if (address.StartsWithAndNumber("Y"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1), 8) + 1280));
					}
					if (address.StartsWithAndNumber("T"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 1536));
					}
					if (address.StartsWithAndNumber("C"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 3584));
					}
					if (address.StartsWithAndNumber("M"))
					{
						int num = Convert.ToInt32(address.Substring(1));
						if (num >= 1536)
						{
							return OResult.CreateSuccessResult(text + (num - 1536 + 45056));
						}
						return OResult.CreateSuccessResult(text + (num + 2048));
					}
					if (ModbusHelper.TransPointAddressToModbus(text, address, new string[1] { "D" }, new int[1], TransDAdressToModbusAddress, out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
				}
				else
				{
					if (address.StartsWithAndNumber("D"))
					{
						return OResult.CreateSuccessResult(text + TransDAdressToModbusAddress(address.Substring(1)));
					}
					if (address.StartsWithAndNumber("C"))
					{
						int num2 = Convert.ToInt32(address.Substring(1));
						if (num2 >= 200)
						{
							return OResult.CreateSuccessResult(text + (num2 - 200 + 3784));
						}
						return OResult.CreateSuccessResult(text + (num2 + 3584));
					}
					if (address.StartsWithAndNumber("T"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 1536));
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}

		/// <summary>
		/// 读取台达PLC的bool变量，重写了读M地址时，跨区域读1536地址时，将会分割多次读取
		/// </summary>
		/// <param name="readBoolFunc">底层基础的读取方法</param>
		/// <param name="address">PLC的地址信息</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>读取的结果</returns>
		public static OResult<bool[]> ReadBool(Func<string, ushort, OResult<bool[]>> readBoolFunc, string address, ushort length)
		{
			string text = string.Empty;
			OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
			if (oResult.IsSuccess)
			{
				text = $"s={oResult.Content};";
			}
			if (address.StartsWith("M") && int.TryParse(address.Substring(1), out var result) && result < 1536 && result + length > 1536)
			{
				ushort num = (ushort)(1536 - result);
				ushort arg = (ushort)(length - num);
				OResult<bool[]> oResult2 = readBoolFunc(text + address, num);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult<bool[]> oResult3 = readBoolFunc(text + "M1536", arg);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				return OResult.CreateSuccessResult(SoftBasic.SpliceArray<bool>(oResult2.Content, oResult3.Content));
			}
			return readBoolFunc(address, length);
		}

		/// <summary>
		/// 写入台达PLC的bool数据，当发现是M类型的数据，并且地址出现跨1536时，进行切割写入操作
		/// </summary>
		/// <param name="writeBoolFunc">底层的写入操作方法</param>
		/// <param name="address">PLC的起始地址信息</param>
		/// <param name="value">等待写入的数据信息</param>
		/// <returns>是否写入成功</returns>
		public static OResult Write(Func<string, bool[], OResult> writeBoolFunc, string address, bool[] value)
		{
			string text = string.Empty;
			OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
			if (oResult.IsSuccess)
			{
				text = $"s={oResult.Content};";
			}
			if (address.StartsWith("M") && int.TryParse(address.Substring(1), out var result) && result < 1536 && result + value.Length > 1536)
			{
				ushort length = (ushort)(1536 - result);
				OResult oResult2 = writeBoolFunc(text + address, value.SelectBegin(length));
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult oResult3 = writeBoolFunc(text + "M1536", value.RemoveBegin(length));
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				return OResult.CreateSuccessResult();
			}
			return writeBoolFunc(address, value);
		}

		/// <summary>
		/// 读取台达PLC的原始字节变量，重写了读D地址时，跨区域读4096地址时，将会分割多次读取
		/// </summary>
		/// <param name="readFunc">底层基础的读取方法</param>
		/// <param name="address">PLC的地址信息</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>读取的结果</returns>
		public static OResult<byte[]> Read(Func<string, ushort, OResult<byte[]>> readFunc, string address, ushort length)
		{
			string text = string.Empty;
			OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
			if (oResult.IsSuccess)
			{
				text = $"s={oResult.Content};";
			}
			if (address.StartsWith("D") && int.TryParse(address.Substring(1), out var result) && result < 4096 && result + length > 4096)
			{
				ushort num = (ushort)(4096 - result);
				ushort arg = (ushort)(length - num);
				OResult<byte[]> oResult2 = readFunc(text + address, num);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult<byte[]> oResult3 = readFunc(text + "D4096", arg);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(oResult2.Content, oResult3.Content));
			}
			return readFunc(address, length);
		}

		/// <summary>
		/// 写入台达PLC的原始字节数据，当发现是D类型的数据，并且地址出现跨4096时，进行切割写入操作
		/// </summary>
		/// <param name="writeFunc">底层的写入操作方法</param>
		/// <param name="address">PLC的起始地址信息</param>
		/// <param name="value">等待写入的数据信息</param>
		/// <returns>是否写入成功</returns>
		public static OResult Write(Func<string, byte[], OResult> writeFunc, string address, byte[] value)
		{
			string text = string.Empty;
			OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
			if (oResult.IsSuccess)
			{
				text = $"s={oResult.Content};";
			}
			if (address.StartsWith("D") && int.TryParse(address.Substring(1), out var result) && result < 4096 && result + value.Length / 2 > 4096)
			{
				ushort num = (ushort)(4096 - result);
				OResult oResult2 = writeFunc(text + address, value.SelectBegin(num * 2));
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult oResult3 = writeFunc(text + "D4096", value.RemoveBegin(num * 2));
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				return OResult.CreateSuccessResult();
			}
			return writeFunc(address, value);
		}

