	{
		internal static OResult<string> TranslateToModbusAddress(IDelta delta, string address, byte modbusCode)
		{
			return delta.Series switch
			{
				DeltaSeries.Dvp => DeltaDvpHelper.ParseDeltaDvpAddress(address, modbusCode), 
				DeltaSeries.AS => DeltaASHelper.ParseDeltaASAddress(address, modbusCode), 
				_ => new OResult<string>(StringResources.Language.NotSupportedDataType), 
			};
		}

		internal static OResult<bool[]> ReadBool(IDelta delta, Func<string, ushort, OResult<bool[]>> readBoolFunc, string address, ushort length)
		{
			return delta.Series switch
			{
				DeltaSeries.Dvp => DeltaDvpHelper.ReadBool(readBoolFunc, address, length), 
				DeltaSeries.AS => readBoolFunc(address, length), 
				_ => new OResult<bool[]>(StringResources.Language.NotSupportedDataType), 
			};
		}

