namespace Snet.Driver.Profinet.Cimon
{
	/// <summary>
	/// 西蒙PLC的数据读取类，支持的地址请参考Demo测试工具上的示例<br />
	/// Simon PLC data reading class, the supported address please refer to the Demo test tool on the example
	/// </summary>
	public class CimonHmiProtocol : DeviceTcpNet
	{
		private byte frameNo = 1;

		/// <summary>
		/// 获取或设置当前的站号信息<br />
		/// Gets or sets the current station number information
		/// </summary>
		public byte FrameNo
		{
			get
			{
				return frameNo;
			}
			set
			{
				frameNo = value;
			}
		}

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public CimonHmiProtocol()
		{
			base.WordLength = 2;
			IpAddress = "127.0.0.1";
			Port = 10260;
			base.ByteTransform = new ReverseWordTransform();
		}

		/// <summary>
		/// 根据IP地址，端口号来实例化一个对象
		/// </summary>
		/// <param name="ip">IP地址</param>
		/// <param name="port">端口号</param>
		public CimonHmiProtocol(string ip, int port = 10260)
			: this()
		{
			IpAddress = ip;
			Port = port;
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			return CimonHelper.ExtractActualData(response);
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = CimonHelper.BuildReadByteCommand(frameNo, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = CimonHelper.BuildWriteByteCommand(frameNo, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (Regex.IsMatch(address, "D[0-9]+\\.[0-9a-fA-F]"))
			{
				return SnetHelper.ReadBool(this, address, length, 16, reverseByWord: true);
			}
			OResult<byte[]> oResult = CimonHelper.BuildReadBitCommand(frameNo, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.Select((byte m) => m != 0).ToArray());
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] value)
		{
			OResult<byte[]> oResult = CimonHelper.BuildWriteBitCommand(FrameNo, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<byte[]> oResult = CimonHelper.BuildReadByteCommand(frameNo, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return await ReadFromCoreServerAsync(oResult.Content);
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<byte[]> oResult = CimonHelper.BuildWriteByteCommand(frameNo, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return await ReadFromCoreServerAsync(oResult.Content);
		}

		/// <inheritdoc />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			if (Regex.IsMatch(address, "D[0-9]+\\.[0-9a-fA-F]"))
			{
				return await SnetHelper.ReadBoolAsync(this, address, length, 16, reverseByWord: true);
			}
			OResult<byte[]> oResult = CimonHelper.BuildReadBitCommand(frameNo, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content.Select((byte m) => m != 0).ToArray());
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, bool[] value)
		{
			OResult<byte[]> oResult = CimonHelper.BuildWriteBitCommand(FrameNo, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return await ReadFromCoreServerAsync(oResult.Content);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"CimonHmiProtocol<{CommunicationPipe}>";
		}
	}
	/// <summary>
	/// Cimon的服务器端实现
	/// </summary>
	public class CimonServer : DeviceServer
	{
		private const int OffsetX = 0;

		private const int OffsetY = 1000;

		private const int OffsetM = 2000;

		private const int OffsetK = 3000;

		private const int OffsetL = 4000;

		private const int OffsetC = 5000;

		private const int OffsetT = 6000;

		private const int OffsetFlag = 7000;

		private const int OffsetD = 0;

		private const int OffsetF = 40000;

		private const int OffsetZ = 41000;

		private const int OffsetS = 42000;

		private SoftBuffer bufferBit;

		private SoftBuffer bufferWord;

		private const int DataPoolLength = 65536;

		private byte frameNo = 1;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.Cimon.CimonHmiProtocol.FrameNo" />
		public byte FrameNo
		{
			get
			{
				return frameNo;
			}
			set
			{
				frameNo = value;
			}
		}

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public CimonServer()
		{
			bufferBit = new SoftBuffer(131072)
			{
				IsBoolReverseByWord = true
			};
			bufferWord = new SoftBuffer(131072);
			base.WordLength = 1;
			base.ByteTransform = new ReverseWordTransform();
		}

		private OResult<byte[]> CreateReadWordResult(SoftBuffer softBuffer, int offset, int address, int length)
		{
			return OResult.CreateSuccessResult(softBuffer.GetBytes(address * 2 + offset * 2, length * 2));
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			try
			{
				int address2 = int.Parse(address.Substring(1));
				if (address[0] == 'X')
				{
					return CreateReadWordResult(bufferBit, 0, address2, length);
				}
				if (address[0] == 'Y')
				{
					return CreateReadWordResult(bufferBit, 1000, address2, length);
				}
				if (address[0] == 'M')
				{
					return CreateReadWordResult(bufferBit, 2000, address2, length);
				}
				if (address[0] == 'K')
				{
					return CreateReadWordResult(bufferBit, 3000, address2, length);
				}
				if (address[0] == 'L')
				{
					return CreateReadWordResult(bufferBit, 4000, address2, length);
				}
				if (address[0] == 'C')
				{
					return CreateReadWordResult(bufferBit, 5000, address2, length);
				}
				if (address[0] == 'T')
				{
					return CreateReadWordResult(bufferBit, 6000, address2, length);
				}
				if (address[0] == 'D')
				{
					return CreateReadWordResult(bufferWord, 0, address2, length);
				}
				if (address[0] == 'F')
				{
					return CreateReadWordResult(bufferWord, 40000, address2, length);
				}
				if (address[0] == 'Z')
				{
					return CreateReadWordResult(bufferWord, 41000, address2, length);
				}
				if (address[0] == 'S')
				{
					return CreateReadWordResult(bufferWord, 42000, address2, length);
				}
				return new OResult<byte[]>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		private OResult CreateWriteWordResult(SoftBuffer softBuffer, int offset, int address, byte[] value)
		{
			softBuffer.SetBytes(value, address * 2 + offset * 2);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			try
			{
				int address2 = int.Parse(address.Substring(1));
				if (address[0] == 'X')
				{
					return CreateWriteWordResult(bufferBit, 0, address2, value);
				}
				if (address[0] == 'Y')
				{
					return CreateWriteWordResult(bufferBit, 1000, address2, value);
				}
				if (address[0] == 'M')
				{
					return CreateWriteWordResult(bufferBit, 2000, address2, value);
				}
				if (address[0] == 'K')
				{
					return CreateWriteWordResult(bufferBit, 3000, address2, value);
				}
				if (address[0] == 'L')
				{
					return CreateWriteWordResult(bufferBit, 4000, address2, value);
				}
				if (address[0] == 'C')
				{
					return CreateWriteWordResult(bufferBit, 5000, address2, value);
				}
				if (address[0] == 'T')
				{
					return CreateWriteWordResult(bufferBit, 2000, address2, value);
				}
				if (address[0] == 'D')
				{
					return CreateWriteWordResult(bufferWord, 0, address2, value);
				}
				if (address[0] == 'F')
				{
					return CreateWriteWordResult(bufferWord, 40000, address2, value);
				}
				if (address[0] == 'Z')
				{
					return CreateWriteWordResult(bufferWord, 41000, address2, value);
				}
				if (address[0] == 'S')
				{
					return CreateWriteWordResult(bufferWord, 42000, address2, value);
				}
				return new OResult(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		private int GetBitIndex(ref string address)
		{
			if (address.IndexOf('.') < 0)
			{
				int result = Convert.ToInt32(address.Substring(address.Length - 1), 16);
				address = address.Substring(0, address.Length - 1);
				return result;
			}
			int result2 = Convert.ToInt32(address.Substring(address.IndexOf('.') + 1), 16);
			address = address.Substring(0, address.IndexOf('.'));
			return result2;
		}

		private OResult<bool[]> CreateReadBitResult(SoftBuffer softBuffer, int offset, int bitIndex, int length)
		{
			return OResult.CreateSuccessResult(softBuffer.GetBool(bitIndex + offset * 16, length));
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			int bitIndex = GetBitIndex(ref address);
			try
			{
				int bitIndex2 = int.Parse(address.Substring(1)) * 16 + bitIndex;
				if (address[0] == 'X')
				{
					return CreateReadBitResult(bufferBit, 0, bitIndex2, length);
				}
				if (address[0] == 'Y')
				{
					return CreateReadBitResult(bufferBit, 1000, bitIndex2, length);
				}
				if (address[0] == 'M')
				{
					return CreateReadBitResult(bufferBit, 2000, bitIndex2, length);
				}
				if (address[0] == 'K')
				{
					return CreateReadBitResult(bufferBit, 3000, bitIndex2, length);
				}
				if (address[0] == 'L')
				{
					return CreateReadBitResult(bufferBit, 4000, bitIndex2, length);
				}
				if (address[0] == 'T')
				{
					return CreateReadBitResult(bufferBit, 6000, bitIndex2, length);
				}
				if (address[0] == 'C')
				{
					return CreateReadBitResult(bufferBit, 5000, bitIndex2, length);
				}
				if (address[0] == 'F')
				{
					return CreateReadBitResult(bufferBit, 7000, bitIndex2, length);
				}
				return new OResult<bool[]>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<bool[]>(ex.Message);
			}
		}

		private OResult CreateWriteBitResult(SoftBuffer softBuffer, int offset, int bitIndex, bool[] value)
		{
			softBuffer.SetBool(value, bitIndex + offset * 16);
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool[] value)
		{
			int bitIndex = GetBitIndex(ref address);
			try
			{
				int bitIndex2 = int.Parse(address.Substring(1)) * 16 + bitIndex;
				if (address[0] == 'X')
				{
					return CreateWriteBitResult(bufferBit, 0, bitIndex2, value);
				}
				if (address[0] == 'Y')
				{
					return CreateWriteBitResult(bufferBit, 1000, bitIndex2, value);
				}
				if (address[0] == 'M')
				{
					return CreateWriteBitResult(bufferBit, 2000, bitIndex2, value);
				}
				if (address[0] == 'K')
				{
					return CreateWriteBitResult(bufferBit, 3000, bitIndex2, value);
				}
				if (address[0] == 'L')
				{
					return CreateWriteBitResult(bufferBit, 4000, bitIndex2, value);
				}
				if (address[0] == 'T')
				{
					return CreateWriteBitResult(bufferBit, 6000, bitIndex2, value);
				}
				if (address[0] == 'C')
				{
					return CreateWriteBitResult(bufferBit, 5000, bitIndex2, value);
				}
				if (address[0] == 'F')
				{
					return CreateWriteBitResult(bufferBit, 7000, bitIndex2, value);
				}
				return new OResult(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult(ex.Message);
			}
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive[10] == 82 || receive[10] == 114)
			{
				return OResult.CreateSuccessResult(ReadByCommand(receive));
			}
			if (receive[10] == 87 || receive[10] == 119)
			{
				return OResult.CreateSuccessResult(WriteByMessage(receive));
			}
			return OResult.CreateSuccessResult(CimonHelper.PackErrorResponse(frameNo, 14));
		}

		private byte[] ReadByCommand(byte[] command)
		{
			int num = command[21] * 256 + command[22];
			string text = Encoding.ASCII.GetString(command, 13, 1);
			string text2 = Encoding.ASCII.GetString(command, 15, 6);
			if (command[10] == 82)
			{
				List<byte> list = new List<byte>();
				list.AddRange(new byte[9]);
				OResult<byte[]> oResult = Read(text + text2, (ushort)num);
				if (oResult.IsSuccess)
				{
					list.AddRange(oResult.Content);
					return CimonHelper.PackEntireCommand(response: true, frameNo, command[10], list.ToArray());
				}
				return CimonHelper.PackErrorResponse(frameNo, 3);
			}
			if (command[10] == 114)
			{
				List<byte> list2 = new List<byte>();
				list2.AddRange(new byte[9]);
				OResult<bool[]> oResult2 = ReadBool(text + text2, (ushort)num);
				if (oResult2.IsSuccess)
				{
					list2.AddRange(oResult2.Content.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray());
				}
				return CimonHelper.PackEntireCommand(response: true, frameNo, command[10], list2.ToArray());
			}
			return CimonHelper.PackErrorResponse(frameNo, 14);
		}

		private byte[] WriteByMessage(byte[] command)
		{
			if (!base.EnableWrite)
			{
				return null;
			}
			string text = Encoding.ASCII.GetString(command, 14, 1);
			string text2 = Encoding.ASCII.GetString(command, 16, 6);
			int length = command[22] * 256 + command[23];
			byte[] array = base.ByteTransform.TransByte(command, 24, length);
			if (command[10] == 87)
			{
				if (Write(text + text2, array).IsSuccess)
				{
					return CimonHelper.PackEntireCommand(response: true, frameNo, command[10], new byte[9]);
				}
				return CimonHelper.PackErrorResponse(frameNo, 3);
			}
			if (command[10] == 119)
			{
				bool[] array2 = new bool[array.Length];
				for (int i = 0; i < array.Length; i++)
				{
					array2[i] = array[i] != 0;
				}
				if (Write(text + text2, array2).IsSuccess)
				{
					return CimonHelper.PackEntireCommand(response: true, frameNo, command[10], new byte[9]);
				}
				return CimonHelper.PackErrorResponse(frameNo, 3);
			}
			return CimonHelper.PackErrorResponse(frameNo, 14);
		}

		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			return ByteTransformHelper.GetByteFromSoftBuffer(bufferBit, bufferWord).ToArray();
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			ByteTransformHelper.SetByteToSoftBuffer(content, 0, bufferBit, bufferWord);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"CimonServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Profinet.Cimon.Helper
{
	/// <summary>
	/// 辅助帮助类对象
	/// </summary>
	public class CimonHelper
	{
		/// <summary>
		/// 所有支持的地址信息
		/// </summary>
		public const string AddressTypes = "YMLKFTCDSX";

		/// <summary>
		/// 根据错误码获取错误文本信息
		/// </summary>
		/// <param name="error">错误信息</param>
		/// <returns>错误消息</returns>
		public static string GetErrorText(int error)
		{
			return error switch
			{
				0 => "No Error", 
				1 => "Error in system (No link with CPU)", 
				2 => "Invalid Device Prefix", 
				3 => "Invalid Device Address", 
				4 => "UDP_ERR_READ_DATASIZE (Error in requested data size)", 
				5 => "UDP_ERR_BLOCK_SIZE (Over 16 requested blocks)", 
				6 => "The case that buffer memory send an error in data and size", 
				7 => "Over receiving buffer capacity", 
				8 => "Over sending time", 
				9 => "UDP_ERR_INVALID_HEADER (Error in header)", 
				10 => "Error in Check-Sum (Check-Sum of received data)", 
				11 => "Error in the information on Frame Length (Total received frame size)", 
				12 => "UDP_ERR_WRITE_DATASIZE (Error in the size to write)", 
				13 => "Unknown Bit Value (Error in Bit Write Data)", 
				14 => "Unknown Command", 
				15 => "Disabling state from writing", 
				16 => "Error in CPU process", 
				_ => StringResources.Language.UnknownError, 
			};
		}

		/// <summary>
		/// 打包错误信息的报文
		/// </summary>
		/// <param name="frame"></param>
		/// <param name="err"></param>
		/// <returns></returns>
		public static byte[] PackErrorResponse(byte frame, int err)
		{
			return PackEntireCommand(response: true, frame, 65, new byte[4]
			{
				0,
				0,
				BitConverter.GetBytes(err)[1],
				BitConverter.GetBytes(err)[0]
			});
		}

		/// <summary>
		/// 打包完整的命令信息
		/// </summary>
		/// <param name="response">是否响应的报文</param>
		/// <param name="frame">站号信息</param>
		/// <param name="cmd">命令码</param>
		/// <param name="data">返回的数据信息</param>
		/// <returns>完成的报文</returns>
		public static byte[] PackEntireCommand(bool response, byte frame, byte cmd, byte[] data)
		{
			MemoryStream memoryStream = new MemoryStream();
			if (response)
			{
				memoryStream.Write(Encoding.ASCII.GetBytes("KDT_PLC_S"));
			}
			else
			{
				memoryStream.Write(Encoding.ASCII.GetBytes("KDT_PLC_M"));
			}
			if (response)
			{
				memoryStream.WriteByte((byte)(frame + 128));
			}
			else
			{
				memoryStream.WriteByte(frame);
			}
			memoryStream.WriteByte(cmd);
			memoryStream.WriteByte(0);
			if (cmd == 82 || cmd == 114)
			{
				if (response)
				{
					memoryStream.WriteByte(BitConverter.GetBytes(data.Length)[1]);
					memoryStream.WriteByte(BitConverter.GetBytes(data.Length)[0]);
				}
				else
				{
					memoryStream.WriteByte(BitConverter.GetBytes(data.Length)[0]);
				}
			}
			else
			{
				memoryStream.WriteByte(BitConverter.GetBytes(data.Length)[1]);
				memoryStream.WriteByte(BitConverter.GetBytes(data.Length)[0]);
			}
			if (data.Length != 0)
			{
				memoryStream.Write(data);
			}
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			byte[] array = memoryStream.ToArray();
			int num = 0;
			for (int i = 0; i < array.Length - 2; i++)
			{
				num += array[i];
			}
			array[^2] = BitConverter.GetBytes(num)[1];
			array[^1] = BitConverter.GetBytes(num)[0];
			return array;
		}

		private static OResult<byte[]> PackReadWriteCommand(byte frameNo, byte control, string address, int length, byte[] data)
		{
			if (string.IsNullOrEmpty(address))
			{
				return new OResult<byte[]>("Address is null");
			}
			string text = address.Substring(0, 1);
			if (!"YMLKFTCDSX".Contains(text))
			{
				return new OResult<byte[]>("Address type error: " + text);
			}
			List<byte> list = new List<byte>();
			list.AddRange(Encoding.ASCII.GetBytes(text.ToUpper()));
			list.Add(0);
			list.AddRange(Encoding.ASCII.GetBytes(address.Substring(1).PadLeft(6, '0')));
			list.Add(BitConverter.GetBytes(length)[1]);
			list.Add(BitConverter.GetBytes(length)[0]);
			if (data != null && data.Length != 0)
			{
				list.AddRange(data);
			}
			return OResult.CreateSuccessResult(PackEntireCommand(response: false, frameNo, control, list.ToArray()));
		}

		/// <summary>
		/// 构建读取的报文信息
		/// </summary>
		/// <param name="frameNo">站号信息</param>
		/// <param name="address">PLC的地址</param>
		/// <param name="length">读取的长度</param>
		/// <returns>读取指定地址的报文</returns>
		public static OResult<byte[]> BuildReadByteCommand(byte frameNo, string address, int length)
		{
			frameNo = (byte)SnetHelper.ExtractParameter(ref address, "f", frameNo);
			return PackReadWriteCommand(frameNo, 82, address, length, null);
		}

		/// <summary>
		/// 构建一个读取位的报文信息
		/// </summary>
		/// <param name="frameNo">站号信息</param>
		/// <param name="address"></param>
		/// <param name="length"></param>
		/// <returns></returns>
		public static OResult<byte[]> BuildReadBitCommand(byte frameNo, string address, int length)
		{
			frameNo = (byte)SnetHelper.ExtractParameter(ref address, "f", frameNo);
			return PackReadWriteCommand(frameNo, 114, address, length, null);
		}

		/// <summary>
		/// 构建写入的报文信息
		/// </summary>
		/// <param name="frameNo">站号信息</param>
		/// <param name="address">PLC的地址</param>
		/// <param name="data">写入的数据</param>
		/// <returns>写入数据到地址的报文</returns>
		public static OResult<byte[]> BuildWriteByteCommand(byte frameNo, string address, byte[] data)
		{
			frameNo = (byte)SnetHelper.ExtractParameter(ref address, "f", frameNo);
			if (data == null)
			{
				data = new byte[0];
			}
			return PackReadWriteCommand(frameNo, 87, address, data.Length, data);
		}

		/// <summary>
		/// 构建写入bool数组的报文信息
		/// </summary>
		/// <param name="frameNo">站号信息</param>
		/// <param name="address">写入的PLC地址</param>
		/// <param name="data">Bool数组值</param>
		/// <returns>写入数据的报文信息</returns>
		public static OResult<byte[]> BuildWriteBitCommand(byte frameNo, string address, bool[] data)
		{
			frameNo = (byte)SnetHelper.ExtractParameter(ref address, "f", frameNo);
			if (data == null)
			{
				data = new bool[0];
			}
			byte[] array = new byte[data.Length];
			for (int i = 0; i < array.Length; i++)
			{
				if (data[i])
				{
					array[i] = 1;
				}
			}
			return PackReadWriteCommand(frameNo, 119, address, data.Length, array);
		}

		/// <summary>
		/// 解析出实际的数据信息
		/// </summary>
		/// <param name="response">PLC返回的报文数据</param>
		/// <returns>提炼的真实的数据</returns>
		public static OResult<byte[]> ExtractActualData(byte[] response)
		{
			if (response.Length < 20)
			{
				return new OResult<byte[]>("Length is less than 20:" + SoftBasic.ByteToHexString(response));
			}
			try
			{
				if (response[10] == 65)
				{
					int num = response[14] * 256 + response[15];
					return new OResult<byte[]>(num, GetErrorText(num) ?? "");
				}
				if (response[10] == 87 || response[10] == 119)
				{
					return OResult.CreateSuccessResult(new byte[0]);
				}
				if (response[10] == 82)
				{
					return OResult.CreateSuccessResult(response.RemoveDouble(23, 2));
				}
				if (response[10] == 114)
				{
					int num2 = response[12] * 256 + response[13];
					return OResult.CreateSuccessResult(response.SelectMiddle(23, num2 - 9));
				}
				return new OResult<byte[]>(StringResources.Language.NotSupportedFunction);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("ExtractActualData failed: " + ex.Message + " Souce: " + response.ToHexString(' '));
			}
		}
	}
}
namespace Snet.Driver.Profinet.Beckhoff
{
	/// <summary>
	/// Ads设备的相关信息，主要是版本号，设备名称<br />
	/// Information about Ads devices, primarily version numbers, device names.
	/// </summary>
	public class AdsDeviceInfo
	{
		/// <summary>
		/// 主版本号<br />
		/// Main Version
		/// </summary>
		public byte Major { get; set; }

		/// <summary>
		/// 次版本号<br />
		/// Minor Version
		/// </summary>
		public byte Minor { get; set; }

		/// <summary>
		/// 构建版本号<br />
		/// Build version
		/// </summary>
		public ushort Build { get; set; }

		/// <summary>
		/// 设备的名字<br />
		/// Device Name
		/// </summary>
		public string DeviceName { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public AdsDeviceInfo()
		{
		}

		/// <summary>
		/// 根据原始的数据内容来实例化一个对象<br />
		/// Instantiate an object based on the original data content
		/// </summary>
		/// <param name="data">原始的数据内容</param>
		public AdsDeviceInfo(byte[] data)
		{
			Major = data[0];
			Minor = data[1];
			Build = BitConverter.ToUInt16(data, 2);
			DeviceName = Encoding.ASCII.GetString(data.RemoveBegin(4)).Trim('\0', ' ');
		}
	}
	/// <summary>
	/// AMS消息的命令号
	/// </summary>
	public enum AmsTcpHeaderFlags : ushort
	{
		/// <summary>
		/// AmsCommand (AMS_TCP_PORT_AMS_CMD, 0x0000)
		/// </summary>
		Command = 0,
		/// <summary>
		/// Port Close command (AMS_TCP_PORT_CLOSE, 0x0001)
		/// </summary>
		PortClose = 1,
		/// <summary>
		/// Port connect command (AMS_TCP_PORT_CONNECT, 0x1000)
		/// </summary>
		PortConnect = 4096,
		/// <summary>
		/// Router Notification (AMS_TCP_PORT_ROUTER_NOTE, 0x1001)
		/// </summary>
		RouterNotification = 4097,
		/// <summary>
		/// Get LocalNetId header
		/// </summary>
		GetLocalNetId = 4098
	}
	/// <summary>
	/// 倍福的ADS协议，支持读取倍福的地址数据，关于端口号的选择，TwinCAT2，端口号801；TwinCAT3，端口号为851，NETID可以选择手动输入，自动输入方式，具体参考API文档的示例代码<br />
	/// Beckhoff's ADS protocol supports reading Beckhoff address data. Regarding the choice of port number, TwinCAT2, port number is 801; TwinCAT3, port number is 851, NETID can be input manually or automatically. 
	/// For details, please refer to the example of API documentation code
	/// </summary>
	/// <remarks>
	/// 支持的地址格式分四种，第一种是绝对的地址表示，比如M100，I100，Q100；第二种是字符串地址，采用s=aaaa;的表示方式；第三种是绝对内存地址采用i=1000000;的表示方式，第四种是自定义的index group, IG=0xF020;0 的地址<br />
	/// There are four supported address formats, the first is absolute address representation, such as M100, I100, Q100; the second is string address, using s=aaaa; representation; 
	/// the third is absolute memory address using i =1000000; representation, the fourth is the custom index group, the address of IG=0xF020;0
	/// <br />
	/// <note type="important">
	/// 在实际的测试中，由于打开了VS软件对倍福PLC进行编程操作，会导致Snet.DriverDemo读取PLC发生间歇性读写失败的问题，此时需要关闭Visual Studio软件对倍福的连接，之后Snet.DriverDemo就会读写成功，感谢QQ：1813782515 提供的解决思路。
	/// </note>
	/// </remarks>
	/// <example>
	/// 地址既支持 M100, I100，Q100 ，读取bool时，支持输入 M100.0,  也支持符号的地址，s=MAIN.a  ,也支持绝对地址的形式， i=1235467;<br />
	/// 下面是实例化的例子，可选两种方式
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\BeckhoffAdsNetSample.cs" region="Sample1" title="实例化" />
	/// 实例化之后，就可以连接操作了
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\BeckhoffAdsNetSample.cs" region="Sample2" title="连接" />
	/// 连接成功之后，就可以进行读写操作了
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\BeckhoffAdsNetSample.cs" region="Sample3" title="读写示例" />
	/// 也可以高级的批量读取，需要自己手动解析下数据
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\BeckhoffAdsNetSample.cs" region="Sample4" title="批量读取" />
	/// 当然，还可以进一步，既实现了批量的高性能读取，又自动解析。
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\BeckhoffAdsNetSample.cs" region="Sample5" title="类型读取" />
	/// </example>
	public class BeckhoffAdsNet : DeviceTcpNet
	{
		private byte[] targetAMSNetId = new byte[8];

		private byte[] sourceAMSNetId = new byte[8];

		private string senderAMSNetId = string.Empty;

		private string _targetAmsNetID = string.Empty;

		private bool _targetAmsSetAlready;

		private bool useAutoAmsNetID;

		private bool useTagCache;

		private readonly Dictionary<string, uint> tagCaches = new Dictionary<string, uint>();

		private readonly object tagLock = new object();

		private readonly SoftIncrementCount incrementCount = new SoftIncrementCount(2147483647L, 1L);

		/// <inheritdoc />
		public override string IpAddress
		{
			get
			{
				return base.IpAddress;
			}
			set
			{
				base.IpAddress = value;
				if (!_targetAmsSetAlready)
				{
					string[] array = base.IpAddress.SplitDot();
					for (int i = 0; i < array.Length; i++)
					{
						targetAMSNetId[i] = byte.Parse(array[i]);
					}
				}
			}
		}

		/// <summary>
		/// 是否使用标签的名称缓存功能，默认为 <c>False</c><br />
		/// Whether to use tag name caching. The default is <c>False</c>
		/// </summary>
		public bool UseTagCache
		{
			get
			{
				return useTagCache;
			}
			set
			{
				useTagCache = value;
			}
		}

		/// <summary>
		/// 是否使用服务器自动的NETID信息，默认手动设置<br />
		/// Whether to use the server's automatic NETID information, manually set by default
		/// </summary>
		public bool UseAutoAmsNetID
		{
			get
			{
				return useAutoAmsNetID;
			}
			set
			{
				useAutoAmsNetID = value;
			}
		}

		/// <summary>
		/// 获取或设置Ams的端口号信息，TwinCAT2，端口号801,811,821,831；TwinCAT3，端口号为851,852,853<br />
		/// Get or set the port number information of Ams, TwinCAT2, the port number is 801, 811, 821, 831; TwinCAT3, the port number is 851, 852, 853
		/// </summary>
		public int AmsPort
		{
			get
			{
				return BitConverter.ToUInt16(targetAMSNetId, 6);
			}
			set
			{
				targetAMSNetId[6] = BitConverter.GetBytes(value)[0];
				targetAMSNetId[7] = BitConverter.GetBytes(value)[1];
			}
		}

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public BeckhoffAdsNet()
		{
			base.WordLength = 2;
			targetAMSNetId[4] = 1;
			targetAMSNetId[5] = 1;
			targetAMSNetId[6] = 83;
			targetAMSNetId[7] = 3;
			sourceAMSNetId[4] = 1;
			sourceAMSNetId[5] = 1;
			base.ByteTransform = new RegularByteTransform();
			CommunicationPipe.UseServerActivePush = true;
		}

		/// <summary>
		/// 通过指定的ip地址以及端口号实例化一个默认的对象<br />
		/// Instantiate a default object with the specified IP address and port number
		/// </summary>
		/// <param name="ipAddress">IP地址信息</param>
		/// <param name="port">端口号</param>
		public BeckhoffAdsNet(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new AdsNetMessage();
		}

		/// <summary>
		/// 目标的地址，举例 192.168.0.1.1.1；也可以是带端口号 192.168.0.1.1.1:801<br />
		/// The address of the destination, for example 192.168.0.1.1.1; it can also be the port number 192.168.0.1.1.1: 801
		/// </summary>
		/// <remarks>
		/// Port：1: AMS Router; 2: AMS Debugger; 800: Ring 0 TC2 PLC; 801: TC2 PLC Runtime System 1; 811: TC2 PLC Runtime System 2; <br />
		/// 821: TC2 PLC Runtime System 3; 831: TC2 PLC Runtime System 4; 850: Ring 0 TC3 PLC; 851: TC3 PLC Runtime System 1<br />
		/// 852: TC3 PLC Runtime System 2; 853: TC3 PLC Runtime System 3; 854: TC3 PLC Runtime System 4; ...
		/// </remarks>
		/// <param name="amsNetId">AMSNet Id地址</param>
		public void SetTargetAMSNetId(string amsNetId)
		{
			if (!string.IsNullOrEmpty(amsNetId))
			{
				AdsHelper.StrToAMSNetId(amsNetId).CopyTo(targetAMSNetId, 0);
				_targetAmsNetID = amsNetId;
				_targetAmsSetAlready = true;
			}
		}

