			{
				tagCaches.Clear();
			}
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			uint value = (uint)incrementCount.GetCurrentValue();
			targetAMSNetId.CopyTo(command, 6);
			sourceAMSNetId.CopyTo(command, 14);
			command[34] = BitConverter.GetBytes(value)[0];
			command[35] = BitConverter.GetBytes(value)[1];
			command[36] = BitConverter.GetBytes(value)[2];
			command[37] = BitConverter.GetBytes(value)[3];
			return base.PackCommandWithHeader(command);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			if (response.Length >= 38)
			{
				ushort num = base.ByteTransform.TransUInt16(response, 22);
				OResult oResult = AdsHelper.CheckResponse(response);
				if (!oResult.IsSuccess)
				{
					if (oResult.ErrorCode == 1809 && (num == 2 || num == 3))
					{
						lock (tagLock)
						{
							tagCaches.Clear();
						}
					}
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				try
				{
					switch (num)
					{
					case 1:
						return OResult.CreateSuccessResult(response.RemoveBegin(42));
					case 2:
						return OResult.CreateSuccessResult(response.RemoveBegin(46));
					case 3:
						return OResult.CreateSuccessResult(new byte[0]);
					case 4:
						return OResult.CreateSuccessResult(response.RemoveBegin(42));
					case 5:
						return OResult.CreateSuccessResult(response.RemoveBegin(42));
					case 6:
						return OResult.CreateSuccessResult(response.RemoveBegin(42));
					case 7:
						return OResult.CreateSuccessResult(new byte[0]);
					case 9:
						return OResult.CreateSuccessResult(response.RemoveBegin(46));
					case 8:
						break;
					}
				}
				catch (Exception ex)
				{
					return new OResult<byte[]>("UnpackResponseContent failed: " + ex.Message + Environment.NewLine + "Source: " + response.ToHexString(' '));
				}
			}
			return base.UnpackResponseContent(send, response);
		}

		/// <inheritdoc />
		protected override void ExtraAfterReadFromCoreServer(OResult read)
		{
			if (!read.IsSuccess && read.ErrorCode < 0 && useTagCache)
			{
				lock (tagLock)
				{
					tagCaches.Clear();
				}
			}
			base.ExtraAfterReadFromCoreServer(read);
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			if (string.IsNullOrEmpty(senderAMSNetId) && string.IsNullOrEmpty(_targetAmsNetID))
			{
				useAutoAmsNetID = true;
			}
			if (useAutoAmsNetID)
			{
				OResult<byte[]> localNetId = GetLocalNetId();
				if (!localNetId.IsSuccess)
				{
					return localNetId;
				}
				if (localNetId.Content.Length >= 12)
				{
					Array.Copy(localNetId.Content, 6, targetAMSNetId, 0, 6);
				}
				OResult oResult = CommunicationPipe.Send(AdsHelper.PackAmsTcpHelper(AmsTcpHeaderFlags.PortConnect, new byte[2]));
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = CommunicationPipe.ReceiveMessage(GetNewNetMessage(), null, useActivePush: false);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				if (oResult2.Content.Length >= 14)
				{
					Array.Copy(oResult2.Content, 6, sourceAMSNetId, 0, 8);
				}
			}
			else if (string.IsNullOrEmpty(senderAMSNetId) && CommunicationPipe is PipeTcpNet pipeTcpNet)
			{
				IPEndPoint iPEndPoint = (IPEndPoint)pipeTcpNet.Socket.LocalEndPoint;
				sourceAMSNetId[6] = BitConverter.GetBytes(iPEndPoint.Port)[0];
				sourceAMSNetId[7] = BitConverter.GetBytes(iPEndPoint.Port)[1];
				iPEndPoint.Address.GetAddressBytes().CopyTo(sourceAMSNetId, 0);
			}
			if (useTagCache)
			{
				lock (tagLock)
				{
					tagCaches.Clear();
				}
			}
			CommunicationPipe.UseServerActivePush = true;
			return base.InitializationOnConnect();
		}

		private OResult<byte[]> GetLocalNetId()
		{
			PipeTcpNet pipeTcpNet = null;
			pipeTcpNet = ((!(CommunicationPipe.GetType() == typeof(PipeSslNet))) ? new PipeTcpNet(IpAddress, Port)
			{
				ConnectTimeOut = ConnectTimeOut,
				ReceiveTimeOut = base.ReceiveTimeOut
			} : new PipeSslNet(IpAddress, Port, serverMode: false)
			{
				ConnectTimeOut = ConnectTimeOut,
				ReceiveTimeOut = base.ReceiveTimeOut
			});
			OResult<bool> oResult = pipeTcpNet.OpenCommunication();
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult oResult2 = pipeTcpNet.Send(AdsHelper.PackAmsTcpHelper(AmsTcpHeaderFlags.GetLocalNetId, new byte[4]));
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			OResult<byte[]> oResult3 = pipeTcpNet.ReceiveMessage(GetNewNetMessage(), null);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			pipeTcpNet.CloseCommunication();
			return oResult3;
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			if (string.IsNullOrEmpty(senderAMSNetId) && string.IsNullOrEmpty(_targetAmsNetID))
			{
				useAutoAmsNetID = true;
			}
			if (useAutoAmsNetID)
			{
				OResult<byte[]> oResult = await GetLocalNetIdAsync();
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				if (oResult.Content.Length >= 12)
				{
					Array.Copy(oResult.Content, 6, targetAMSNetId, 0, 6);
				}
				OResult oResult2 = await CommunicationPipe.SendAsync(AdsHelper.PackAmsTcpHelper(AmsTcpHeaderFlags.PortConnect, new byte[2])).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult<byte[]> oResult3 = await CommunicationPipe.ReceiveMessageAsync(GetNewNetMessage(), null, useActivePush: false).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				if (oResult3.Content.Length >= 14)
				{
					Array.Copy(oResult3.Content, 6, sourceAMSNetId, 0, 8);
				}
			}
			else if (string.IsNullOrEmpty(senderAMSNetId) && CommunicationPipe is PipeTcpNet pipeTcpNet)
			{
				IPEndPoint iPEndPoint = (IPEndPoint)pipeTcpNet.Socket.LocalEndPoint;
				sourceAMSNetId[6] = BitConverter.GetBytes(iPEndPoint.Port)[0];
				sourceAMSNetId[7] = BitConverter.GetBytes(iPEndPoint.Port)[1];
				iPEndPoint.Address.GetAddressBytes().CopyTo(sourceAMSNetId, 0);
			}
			if (useTagCache)
			{
				lock (tagLock)
				{
					tagCaches.Clear();
				}
			}
			CommunicationPipe.UseServerActivePush = true;
			return await base.InitializationOnConnectAsync();
		}

		private async Task<OResult<byte[]>> GetLocalNetIdAsync()
		{
			PipeTcpNet pipeTcpNet = ((!(CommunicationPipe.GetType() == typeof(PipeSslNet))) ? new PipeTcpNet(IpAddress, Port)
			{
				ConnectTimeOut = ConnectTimeOut,
				ReceiveTimeOut = base.ReceiveTimeOut
			} : new PipeSslNet(IpAddress, Port, serverMode: false)
			{
				ConnectTimeOut = ConnectTimeOut,
				ReceiveTimeOut = base.ReceiveTimeOut
			});
			OResult<bool> oResult = await pipeTcpNet.OpenCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			OResult oResult2 = await pipeTcpNet.SendAsync(AdsHelper.PackAmsTcpHelper(AmsTcpHeaderFlags.GetLocalNetId, new byte[4])).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			OResult<byte[]> read = await pipeTcpNet.ReceiveMessageAsync(GetNewNetMessage(), null).ConfigureAwait(continueOnCapturedContext: false);
			if (!read.IsSuccess)
			{
				return read;
			}
			await pipeTcpNet.CloseCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
			return read;
		}

		/// <inheritdoc />
		protected override bool DecideWhetherQAMessage(CommunicationPipe pipe, OResult<byte[]> receive)
		{
			if (!receive.IsSuccess)
			{
				if (useTagCache)
				{
					lock (tagLock)
					{
						tagCaches.Clear();
					}
				}
				return false;
			}
			byte[] content = receive.Content;
			if (content.Length >= 2 && BitConverter.ToUInt16(content, 0) == 0)
			{
				if (content.Length >= 24 && base.ByteTransform.TransUInt16(content, 22) == 8)
				{
					return false;
				}
				return true;
			}
			return false;
		}

		/// <summary>
		/// 根据当前标签的地址获取到内存偏移地址<br />
		/// Get the memory offset address based on the address of the current label
		/// </summary>
		/// <param name="address">带标签的地址信息，例如s=A,那么标签就是A</param>
		/// <returns>内存偏移地址</returns>
		public OResult<uint> ReadValueHandle(string address)
		{
			if (!address.StartsWith("s="))
			{
				return new OResult<uint>("When read valueHandle, address must startwith 's=', forexample: s=MAIN.A");
			}
			OResult<byte[]> oResult = AdsHelper.BuildReadWriteCommand(address, 4, isBit: false, AdsHelper.StrToAdsBytes(address.Substring(2)));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<uint>(oResult);
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<uint>(oResult2);
			}
			return OResult.CreateSuccessResult(BitConverter.ToUInt32(oResult2.Content, 0));
		}

		/// <summary>
		/// 将字符串的地址转换为内存的地址，其他地址则不操作<br />
		/// Converts the address of a string to the address of a memory, other addresses do not operate
		/// </summary>
		/// <param name="address">地址信息，s=A的地址转换为i=100000的形式</param>
		/// <returns>地址</returns>
		public OResult<string> TransValueHandle(string address)
		{
			if (address.StartsWith("s=") || address.StartsWith("S="))
			{
				if (useTagCache)
				{
					lock (tagLock)
					{
						if (tagCaches.ContainsKey(address))
						{
							return OResult.CreateSuccessResult($"i={tagCaches[address]}");
						}
					}
				}
				OResult<uint> oResult = ReadValueHandle(address);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult);
				}
				if (useTagCache)
				{
					lock (tagLock)
					{
						if (!tagCaches.ContainsKey(address))
						{
							tagCaches.Add(address, oResult.Content);
						}
					}
				}
				return OResult.CreateSuccessResult($"i={oResult.Content}");
			}
			return OResult.CreateSuccessResult(address);
		}

