		/// <summary>
		/// 读取PLC的数据，地址共有三种格式，一：I,Q,M数据信息，举例M0,M100；二：内存地址，i=100000；三：标签地址，s=A<br />
		/// Read PLC data, there are three formats of address, one: I, Q, M data information, such as M0, M100; two: memory address, i = 100000; three: tag address, s = A
		/// </summary>
		/// <param name="address">地址信息，地址共有三种格式，一：I,Q,M数据信息，举例M0,M100；二：内存地址，i=100000；三：标签地址，s=A</param>
		/// <param name="length">长度</param>
		/// <returns>包含是否成功的结果对象</returns>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<string> oResult = TransValueHandle(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			address = oResult.Content;
			OResult<byte[]> oResult2 = AdsHelper.BuildReadCommand(address, length, isBit: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ReadFromCoreServer(oResult2.Content);
		}

		private void AddLengthAndOffset(List<ushort> length, List<int> offset, ref int index, int len)
		{
			length.Add((ushort)len);
			offset.Add(index);
			index += len;
		}

		/// <inheritdoc />
		public override OResult<T> Read<T>()
		{
			Type typeFromHandle = typeof(T);
			object obj = typeFromHandle.Assembly.CreateInstance(typeFromHandle.FullName);
			List<SnetAddressProperty> snetPropertyInfos = SnetReflectionHelper.GetSnetPropertyInfos(typeFromHandle, GetType(), null, base.ByteTransform);
			string[] address = snetPropertyInfos.Select((SnetAddressProperty m) => m.DeviceAddressAttribute.Address).ToArray();
			ushort[] length = snetPropertyInfos.Select((SnetAddressProperty m) => (ushort)m.ByteLength).ToArray();
			OResult<byte[]> oResult = Read(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<T>(oResult);
			}
			SnetReflectionHelper.SetPropertyValueFrom(base.ByteTransform, obj, snetPropertyInfos, oResult.Content);
			return OResult.CreateSuccessResult((T)obj);
		}

		/// <summary>
		/// 读取结构体的信息，传入结构体的类型，以及结构体的起始地址<br />
		/// Read the information of the structure, the type of the incoming structure, and the start address of the structure
		/// </summary>
		/// <typeparam name="T">结构体类型</typeparam>
		/// <param name="address">结构体的地址信息</param>
		/// <returns>是否读取成功</returns>
		public OResult<T> ReadStruct<T>(string address) where T : struct
		{
			T structure = new T();
			OResult<byte[]> oResult = Read(address, (ushort)Marshal.SizeOf(structure));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<T>(oResult);
			}
			GCHandle gCHandle = GCHandle.Alloc(oResult.Content, GCHandleType.Pinned);
			structure = (T)Marshal.PtrToStructure(gCHandle.AddrOfPinnedObject(), typeof(T));
			gCHandle.Free();
			return OResult.CreateSuccessResult(structure);
		}

		/// <summary>
		/// 将一个结构体写入到指定的地址中去，需要指定写入的起始地址<br />
		/// To write a structure to a specified address, you need to specify the start address of the write
		/// </summary>
		/// <typeparam name="T">结构体类型</typeparam>
		/// <param name="address">起始地址</param>
		/// <param name="value">结构体的值</param>
		/// <returns>是否写入成功</returns>
		public OResult WriteStruct<T>(string address, T value) where T : struct
		{
			byte[] value2 = new byte[Marshal.SizeOf(value)];
			GCHandle gCHandle = GCHandle.Alloc(value2, GCHandleType.Pinned);
			Marshal.StructureToPtr(value, gCHandle.AddrOfPinnedObject(), fDeleteOld: false);
			gCHandle.Free();
			return Write(address, value2);
		}

		/// <summary>
		/// 批量读取PLC的数据，需要传入地址数组，以及读取的长度数组信息，长度单位为字节单位，如果是读取bool变量的，则以bool为单位，统一返回一串字节数据信息，需要进行二次解析的操作。<br />
		/// To read PLC data in batches, you need to pass in the address array and the read length array information. The unit of length is in bytes. If you read a bool variable, 
		/// it will return a string of byte data information in units of bool. , which requires a secondary parsing operation.
		/// </summary>
		/// <remarks>
		/// 关于二次解析的参考信息，可以参考API文档，地址：http://api.Snetcommunication.cn<br />
		/// For reference information about secondary parsing, you can refer to the API documentation, address: http://api.Snetcommunication.cn
		/// </remarks>
		/// <param name="address">地址数组信息</param>
		/// <param name="length">读取的长度数组信息</param>
		/// <returns>原始字节数组的结果对象</returns>
		public OResult<byte[]> Read(string[] address, ushort[] length)
		{
			if (address.Length != length.Length)
			{
				return new OResult<byte[]>(StringResources.Language.TwoParametersLengthIsNotSame);
			}
			for (int i = 0; i < address.Length; i++)
			{
				OResult<string> oResult = TransValueHandle(address[i]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				address[i] = oResult.Content;
			}
			OResult<byte[]> oResult2 = AdsHelper.BuildReadCommand(address, length);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ReadFromCoreServer(oResult2.Content);
		}

