	/// <summary>
	/// 倍福PLC的命令码<br />
	/// Command Id: https://infosys.beckhoff.com/english.php?content=../content/1033/tc3_ads_intro/index.html
	/// </summary>
	public class BeckhoffCommandId
	{
		/// <summary>
		/// 读取PLC的名字和版本号等信息<br />
		/// Reads the name and the version number of the ADS device.
		/// </summary>
		public const ushort ReadDeviceInfo = 1;

		/// <summary>
		/// 可以读ADS的设备读取数据<br />
		/// With ADS Read data can be read from an ADS device
		/// </summary>
		public const ushort Read = 2;

		/// <summary>
		/// 将ADS数据写入到ADS的设备里去<br />
		/// With ADS Write data can be written to an ADS device
		/// </summary>
		public const ushort Write = 3;

		/// <summary>
		/// 读取ADS设备里的设备状态信息和ADS状态<br />
		/// Reads the ADS status and the device status of an ADS device.
		/// </summary>
		public const ushort ReadState = 4;

		/// <summary>
		/// 更改ADS设备的设备状态信息和ADS状态<br />
		/// Changes the ADS status and the device status of an ADS device.
		/// </summary>
		public const ushort WriteControl = 5;

		/// <summary>
		/// 在ADS设备里面创建一个通知对象<br />
		/// A notification is created in an ADS device
		/// </summary>
		public const ushort AddDeviceNotification = 6;

		/// <summary>
		/// 删除ADS设备里的一个通知对象<br />
		/// One before defined notification is deleted in an ADS device.
		/// </summary>
		public const ushort DeleteDeviceNotification = 7;

		/// <summary>
		/// 从ADS设备订阅一个数据的通知，将会发送到客户端<br />
		/// Data will carry forward independently from an ADS device to a Client
		/// </summary>
		public const ushort DeviceNotification = 8;

		/// <summary>
		/// 在写入的时候进行同时的读取<br />
		/// With ADS ReadWrite data will be written to an ADS device. Additionally, data can be read from the ADS device.
		/// </summary>
		public const ushort ReadWrite = 9;
	}
}
namespace Snet.Driver.Profinet.Beckhoff.Helper
{
	internal class AdsHelper
	{
		/// <summary>
		/// 根据命令码ID，消息ID，数据信息组成AMS的命令码
		/// </summary>
		/// <param name="commandId">命令码ID</param>
		/// <param name="data">数据内容</param>
		/// <returns>打包之后的数据信息，没有填写AMSNetId的Target和Source内容</returns>
		public static byte[] BuildAmsHeaderCommand(ushort commandId, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[32 + data.Length];
			array[16] = BitConverter.GetBytes(commandId)[0];
			array[17] = BitConverter.GetBytes(commandId)[1];
			array[18] = 4;
			array[19] = 0;
			array[20] = BitConverter.GetBytes(data.Length)[0];
			array[21] = BitConverter.GetBytes(data.Length)[1];
			array[22] = BitConverter.GetBytes(data.Length)[2];
			array[23] = BitConverter.GetBytes(data.Length)[3];
			array[24] = 0;
			array[25] = 0;
			array[26] = 0;
			array[27] = 0;
			data.CopyTo(array, 32);
			return PackAmsTcpHelper(AmsTcpHeaderFlags.Command, array);
		}

		/// <summary>
		/// 构建读取设备信息的命令报文
		/// </summary>
		/// <returns>报文信息</returns>
		public static OResult<byte[]> BuildReadDeviceInfoCommand()
		{
			return OResult.CreateSuccessResult(BuildAmsHeaderCommand(1, null));
		}

		/// <summary>
		/// 构建读取状态的命令报文
		/// </summary>
		/// <returns>报文信息</returns>
		public static OResult<byte[]> BuildReadStateCommand()
		{
			return OResult.CreateSuccessResult(BuildAmsHeaderCommand(4, null));
		}

		/// <summary>
		/// 构建写入状态的命令报文
		/// </summary>
		/// <param name="state">Ads state</param>
		/// <param name="deviceState">Device state</param>
		/// <param name="data">Data</param>
		/// <returns>报文信息</returns>
		public static OResult<byte[]> BuildWriteControlCommand(short state, short deviceState, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			_ = new byte[8 + data.Length];
			return OResult.CreateSuccessResult(BuildAmsHeaderCommand(5, SoftBasic.SpliceArray<byte>(BitConverter.GetBytes(state), BitConverter.GetBytes(deviceState), BitConverter.GetBytes(data.Length), data)));
		}

		/// <summary>
		/// 构建写入的指令信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <param name="isBit">是否是位信息</param>
		/// <returns>结果内容</returns>
		public static OResult<byte[]> BuildReadCommand(string address, int length, bool isBit)
		{
			OResult<uint, uint> oResult = AnalysisAddress(address, isBit);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[12];
			BitConverter.GetBytes(oResult.Content1).CopyTo(array, 0);
			BitConverter.GetBytes(oResult.Content2).CopyTo(array, 4);
			BitConverter.GetBytes(length).CopyTo(array, 8);
			return OResult.CreateSuccessResult(BuildAmsHeaderCommand(2, array));
		}

		/// <summary>
		/// 构建批量读取的指令信息，不能传入读取符号数据，只能传入读取M,I,Q,i=0x0001信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>结果内容</returns>
		public static OResult<byte[]> BuildReadCommand(string[] address, ushort[] length)
		{
			byte[] array = new byte[12 * address.Length];
			int num = 0;
			for (int i = 0; i < address.Length; i++)
			{
				OResult<uint, uint> oResult = AnalysisAddress(address[i], isBit: false);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				BitConverter.GetBytes(oResult.Content1).CopyTo(array, 12 * i);
				BitConverter.GetBytes(oResult.Content2).CopyTo(array, 12 * i + 4);
				BitConverter.GetBytes((int)length[i]).CopyTo(array, 12 * i + 8);
				num += length[i];
			}
			return BuildReadWriteCommand("ig=0xF080;0", num, isBit: false, array);
		}

		/// <summary>
		/// 构建写入的指令信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <param name="isBit">是否是位信息</param>
		/// <param name="value">写入的数值</param>
		/// <returns>结果内容</returns>
		public static OResult<byte[]> BuildReadWriteCommand(string address, int length, bool isBit, byte[] value)
		{
			OResult<uint, uint> oResult = AnalysisAddress(address, isBit);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[16 + value.Length];
			BitConverter.GetBytes(oResult.Content1).CopyTo(array, 0);
			BitConverter.GetBytes(oResult.Content2).CopyTo(array, 4);
			BitConverter.GetBytes(length).CopyTo(array, 8);
			BitConverter.GetBytes(value.Length).CopyTo(array, 12);
			value.CopyTo(array, 16);
			return OResult.CreateSuccessResult(BuildAmsHeaderCommand(9, array));
		}

		/// <summary>
		/// 构建批量写入的指令代码，不能传入读取符号数据，只能传入读取M,I,Q,i=0x0001信息
		/// </summary>
		/// <remarks>
		/// 实际没有调试通
		/// </remarks>
		/// <param name="address">地址列表信息</param>
		/// <param name="value">写入的数据值信息</param>
		/// <returns>命令报文</returns>
		public static OResult<byte[]> BuildWriteCommand(string[] address, List<byte[]> value)
		{
			MemoryStream memoryStream = new MemoryStream();
			int num = 0;
			for (int i = 0; i < address.Length; i++)
			{
				OResult<uint, uint> oResult = AnalysisAddress(address[i], isBit: false);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				memoryStream.Write(BitConverter.GetBytes(oResult.Content1));
				memoryStream.Write(BitConverter.GetBytes(oResult.Content2));
				memoryStream.Write(BitConverter.GetBytes(value[i].Length));
				memoryStream.Write(value[i]);
				num += value[i].Length;
			}
			return BuildReadWriteCommand("ig=0xF081;0", num, isBit: false, memoryStream.ToArray());
		}

		/// <summary>
		/// 构建写入的指令信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="value">数据</param>
		/// <param name="isBit">是否是位信息</param>
		/// <returns>结果内容</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, byte[] value, bool isBit)
		{
			OResult<uint, uint> oResult = AnalysisAddress(address, isBit);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = new byte[12 + value.Length];
			BitConverter.GetBytes(oResult.Content1).CopyTo(array, 0);
			BitConverter.GetBytes(oResult.Content2).CopyTo(array, 4);
			BitConverter.GetBytes(value.Length).CopyTo(array, 8);
			value.CopyTo(array, 12);
			return OResult.CreateSuccessResult(BuildAmsHeaderCommand(3, array));
		}

		/// <summary>
		/// 构建写入的指令信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="value">数据</param>
		/// <param name="isBit">是否是位信息</param>
		/// <returns>结果内容</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, bool[] value, bool isBit)
		{
			OResult<uint, uint> oResult = AnalysisAddress(address, isBit);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] array = value.Select((bool m) => m ? ((byte)1) : ((byte)0)).ToArray();
			byte[] array2 = new byte[12 + array.Length];
			BitConverter.GetBytes(oResult.Content1).CopyTo(array2, 0);
			BitConverter.GetBytes(oResult.Content2).CopyTo(array2, 4);
			BitConverter.GetBytes(array.Length).CopyTo(array2, 8);
			array.CopyTo(array2, 12);
			return OResult.CreateSuccessResult(BuildAmsHeaderCommand(3, array2));
		}

		/// <summary>
		/// 构建释放句柄的报文信息，当获取了变量的句柄后，这个句柄就被释放
		/// </summary>
		/// <param name="handle">句柄信息</param>
		/// <returns>报文的结果内容</returns>
		public static OResult<byte[]> BuildReleaseSystemHandle(uint handle)
		{
			byte[] array = new byte[16];
			BitConverter.GetBytes(61446).CopyTo(array, 0);
			BitConverter.GetBytes(4).CopyTo(array, 8);
			BitConverter.GetBytes(handle).CopyTo(array, 12);
			return OResult.CreateSuccessResult(BuildAmsHeaderCommand(3, array));
		}

		/// <summary>
		/// 检查从PLC的反馈的数据报文是否正确
		/// </summary>
		/// <param name="response">反馈报文</param>
		/// <returns>检查结果</returns>
		public static OResult<int> CheckResponse(byte[] response)
		{
			try
			{
				int num = BitConverter.ToInt32(response, 30);
				if (num > 0)
				{
					return new OResult<int>(num, GetErrorCodeText(num) + Environment.NewLine + "Source:" + response.ToHexString(' '));
				}
				if (response.Length >= 42)
				{
					int num2 = BitConverter.ToInt32(response, 38);
					if (num2 != 0)
					{
						return new OResult<int>(num2, GetErrorCodeText(num2) + Environment.NewLine + "Source:" + response.ToHexString(' '));
					}
				}
			}
			catch (Exception ex)
			{
				return new OResult<int>(ex.Message + " Source:" + response.ToHexString(' '));
			}
			return OResult.CreateSuccessResult(0);
		}

		/// <summary>
		/// 将实际的包含AMS头报文和数据报文的命令，打包成实际可发送的命令
		/// </summary>
		/// <param name="headerFlags">命令头信息</param>
		/// <param name="command">命令信息</param>
		/// <returns>结果信息</returns>
		public static byte[] PackAmsTcpHelper(AmsTcpHeaderFlags headerFlags, byte[] command)
		{
			byte[] array = new byte[6 + command.Length];
			BitConverter.GetBytes((ushort)headerFlags).CopyTo(array, 0);
			BitConverter.GetBytes(command.Length).CopyTo(array, 2);
			command.CopyTo(array, 6);
			return array;
		}

		private static int CalculateAddressStarted(string address)
		{
			if (address.IndexOf('.') < 0)
			{
				return Convert.ToInt32(address);
			}
			string[] array = address.Split('.');
			return Convert.ToInt32(array[0]) * 8 + SnetHelper.CalculateBitStartIndex(array[1]);
		}

		/// <summary>
		/// 分析当前的地址信息，根据结果信息进行解析出真实的偏移地址
		/// </summary>
		/// <param name="address">地址</param>
		/// <param name="isBit">是否位访问</param>
		/// <returns>结果内容</returns>
		public static OResult<uint, uint> AnalysisAddress(string address, bool isBit)
		{
			OResult<uint, uint> oResult = new OResult<uint, uint>();
			try
			{
				if (address.StartsWith("i=") || address.StartsWith("I="))
				{
					oResult.Content1 = 61445u;
					oResult.Content2 = uint.Parse(address.Substring(2));
				}
				else if (address.StartsWith("s=") || address.StartsWith("S="))
				{
					oResult.Content1 = 61443u;
					oResult.Content2 = 0u;
				}
				else if (address.StartsWith("ig=") || address.StartsWith("IG="))
				{
					address = address.ToUpper();
					oResult.Content1 = (uint)SnetHelper.ExtractParameter(ref address, "IG", 0);
					oResult.Content2 = uint.Parse(address);
				}
				else
				{
					switch (address[0])
					{
					case 'M':
					case 'm':
						if (isBit)
						{
							oResult.Content1 = 16417u;
							oResult.Content2 = (uint)CalculateAddressStarted(address.Substring(1));
						}
						else
						{
							oResult.Content1 = 16416u;
							oResult.Content2 = uint.Parse(address.Substring(1));
						}
						break;
					case 'I':
					case 'i':
						if (isBit)
						{
							oResult.Content1 = 61473u;
							oResult.Content2 = (uint)(CalculateAddressStarted(address.Substring(1)) + 1024000);
						}
						else
						{
							oResult.Content1 = 61472u;
							oResult.Content2 = uint.Parse(address.Substring(1)) + 128000;
						}
						break;
					case 'Q':
					case 'q':
						if (isBit)
						{
							oResult.Content1 = 61489u;
							oResult.Content2 = (uint)(CalculateAddressStarted(address.Substring(1)) + 2048000);
						}
						else
						{
							oResult.Content1 = 61488u;
							oResult.Content2 = uint.Parse(address.Substring(1)) + 256000;
						}
						break;
					default:
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
				}
			}
			catch (Exception ex)
			{
				oResult.Message = ex.Message;
				return oResult;
			}
			oResult.IsSuccess = true;
			oResult.Message = StringResources.Language.SuccessText;
			return oResult;
		}

		/// <summary>
		/// 将字符串名称转变为ADS协议可识别的字节数组
		/// </summary>
		/// <param name="value">值</param>
		/// <returns>字节数组</returns>
		public static byte[] StrToAdsBytes(string value)
		{
			return SoftBasic.SpliceArray<byte>(Encoding.ASCII.GetBytes(value), new byte[1]);
		}

		/// <summary>
		/// 将字符串的信息转换为AMS目标的地址
		/// </summary>
		/// <param name="amsNetId">目标信息</param>
		/// <returns>字节数组</returns>
		public static byte[] StrToAMSNetId(string amsNetId)
		{
			string str = amsNetId;
			byte[] array;
			if (amsNetId.IndexOf(':') > 0)
			{
				array = new byte[8];
				string[] array2 = amsNetId.Split(new char[1] { ':' }, StringSplitOptions.RemoveEmptyEntries);
				str = array2[0];
				array[6] = BitConverter.GetBytes(int.Parse(array2[1]))[0];
				array[7] = BitConverter.GetBytes(int.Parse(array2[1]))[1];
			}
			else
			{
				array = new byte[6];
			}
			string[] array3 = str.SplitDot();
			for (int i = 0; i < array3.Length; i++)
			{
				array[i] = byte.Parse(array3[i]);
			}
			return array;
		}

		/// <summary>
		/// 根据byte数组信息提取出字符串格式的AMSNetId数据信息，方便日志查看
		/// </summary>
		/// <param name="data">原始的报文数据信息</param>
		/// <param name="index">起始的节点信息</param>
		/// <returns>Ams节点号信息</returns>
		public static string GetAmsNetIdString(byte[] data, int index)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(data[index]);
			stringBuilder.Append(".");
			stringBuilder.Append(data[index + 1]);
			stringBuilder.Append(".");
			stringBuilder.Append(data[index + 2]);
			stringBuilder.Append(".");
			stringBuilder.Append(data[index + 3]);
			stringBuilder.Append(".");
			stringBuilder.Append(data[index + 4]);
			stringBuilder.Append(".");
			stringBuilder.Append(data[index + 5]);
			stringBuilder.Append(":");
			stringBuilder.Append(BitConverter.ToUInt16(data, index + 6));
			return stringBuilder.ToString();
		}

