namespace Snet.Driver.Profinet.AllenBradley
{
	/// <summary>
	/// 结构体的句柄信息
	/// </summary>
	public class AbStructHandle
	{
		/// <summary>
		/// 返回项数
		/// </summary>
		/// <remarks>
		/// Count of Items returned
		/// </remarks>
		public ushort ReturnCount { get; set; }

		/// <summary>
		/// 结构体定义大小
		/// </summary>
		/// <remarks>
		/// This is the number of structure members
		/// </remarks>
		public uint TemplateObjectDefinitionSize { get; set; }

		/// <summary>
		/// 使用读取标记服务读取结构时在线路上传输的字节数
		/// </summary>
		/// <remarks>
		/// This is the number of bytes of the structure data
		/// </remarks>
		public uint TemplateStructureSize { get; set; }

		/// <summary>
		/// 成员数量
		/// </summary>
		/// <remarks>
		/// This is the number of structure members
		/// </remarks>
		public ushort MemberCount { get; set; }

		/// <summary>
		/// 结构体的handle
		/// </summary>
		/// <remarks>
		/// This is the Tag Type Parameter used in Read/Write Tag service
		/// </remarks>
		public ushort StructureHandle { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// instantiate a default object
		/// </summary>
		public AbStructHandle()
		{
		}

		/// <summary>
		/// 使用原始字节的数据，索引信息来实例化一个对象<br />
		/// Instantiate an object with raw bytes of data, index information
		/// </summary>
		/// <param name="source">原始字节数据</param>
		/// <param name="index">起始的偏移索引</param>
		public AbStructHandle(byte[] source, int index)
		{
			ReturnCount = BitConverter.ToUInt16(source, index);
			TemplateObjectDefinitionSize = BitConverter.ToUInt32(source, index + 6);
			TemplateStructureSize = BitConverter.ToUInt32(source, index + 14);
			MemberCount = BitConverter.ToUInt16(source, index + 22);
			StructureHandle = BitConverter.ToUInt16(source, index + 28);
		}
	}
	/// <summary>
	/// AB PLC的数据标签实体类<br />
	/// Data tag entity class of AB PLC
	/// </summary>
	public class AbTagItem
	{
		/// <summary>
		/// 实例ID<br />
		/// instance ID
		/// </summary>
		public uint InstanceID { get; set; }

		/// <summary>
		/// 当前标签的名字<br />
		/// the name of the current label
		/// </summary>
		public string Name { get; set; }

		/// <summary>
		/// 当前标签的类型代号，例如 0x0C1 表示bool类型，如果当前的标签的<see cref="P:Snet.Driver.Profinet.AllenBradley.AbTagItem.IsStruct" />为 <c>True</c>，那么本属性表示结构体的实例ID<br />
		/// The type code of the current tag, for example 0x0C1 means bool type, if the current tag's <see cref="P:Snet.Driver.Profinet.AllenBradley.AbTagItem.IsStruct" /> is <c>True</c>, 
		/// then this attribute indicates the instance ID of the structure
		/// </summary>
		public ushort SymbolType { get; set; }

		/// <summary>
		/// 数据的维度信息，默认是0，标量数据，1表示一维数组，2表示二维数组<br />
		/// The dimension information of the data, the default is 0, scalar data, 1 means a one-dimensional array, 2 means a two-dimensional array
		/// </summary>
		public int ArrayDimension { get; set; }

		/// <summary>
		/// 当前的标签是否结构体数据<br />
		/// Whether the current label is structured data
		/// </summary>
		public bool IsStruct { get; set; }

		/// <summary>
		/// 当前如果是数组，表示数组的长度，仅在读取结构体的变量信息时有效，为-1则是无效。
		/// </summary>
		public int[] ArrayLength { get; set; }

		/// <summary>
		/// 如果当前的标签是结构体的标签，则表示为结构体的成员信息
		/// </summary>
		[JsonIgnore]
		public AbTagItem[] Members { get; set; }

		/// <summary>
		/// 用户自定义的额外的对象
		/// </summary>
		[JsonIgnore]
		public object Tag { get; set; }

		/// <summary>
		/// 获取或设置本属性实际数据在结构体中的偏移位置信息<br />
		/// Get or set the offset position information of the actual data of this property in the structure
		/// </summary>
		public int ByteOffset { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// instantiate a default object
		/// </summary>
		public AbTagItem()
		{
			ArrayLength = new int[3] { -1, -1, -1 };
		}

		/// <summary>
		/// 获取类型的文本描述信息
		/// </summary>
		/// <returns>文本信息</returns>
		public string GetTypeText()
		{
			string text = string.Empty;
			if (ArrayDimension == 1)
			{
				text = ((ArrayLength[0] >= 0) ? $"[{ArrayLength[0]}]" : "[]");
			}
			else if (ArrayDimension == 2)
			{
				text = $"[{ArrayLength[0]},{ArrayLength[1]}]";
			}
			else if (ArrayDimension == 3)
			{
				text = $"[{ArrayLength[0]},{ArrayLength[1]},{ArrayLength[2]}]";
			}
			if (IsStruct)
			{
				return "struct" + text;
			}
			if (SymbolType == 8)
			{
				return "date" + text;
			}
			if (SymbolType == 9)
			{
				return "time" + text;
			}
			if (SymbolType == 10)
			{
				return "timeAndDate" + text;
			}
			if (SymbolType == 11)
			{
				return "timeOfDate" + text;
			}
			if (SymbolType == 193)
			{
				return "bool" + text;
			}
			if (SymbolType == 194)
			{
				return "sbyte" + text;
			}
			if (SymbolType == 195)
			{
				return "short" + text;
			}
			if (SymbolType == 196)
			{
				return "int" + text;
			}
			if (SymbolType == 197)
			{
				return "long" + text;
			}
			if (SymbolType == 198)
			{
				return "byte" + text;
			}
			if (SymbolType == 199)
			{
				return "ushort" + text;
			}
			if (SymbolType == 200)
			{
				return "uint" + text;
			}
			if (SymbolType == 201)
			{
				return "ulong" + text;
			}
			if (SymbolType == 202)
			{
				return "float" + text;
			}
			if (SymbolType == 203)
			{
				return "double" + text;
			}
			if (SymbolType == 204)
			{
				return "struct";
			}
			if (SymbolType == 208)
			{
				return "string";
			}
			if (SymbolType == 209)
			{
				return "byte-str";
			}
			if (SymbolType == 210)
			{
				return "word-str";
			}
			if (SymbolType == 211)
			{
				if (ArrayDimension == 0)
				{
					return "bool[32]";
				}
				if (ArrayDimension == 1)
				{
					return "bool" + $"[{ArrayLength[0] * 32}]";
				}
				return "bool-str" + text;
			}
			if ((SymbolType | 0xF00) == 4033)
			{
				return "bool";
			}
			return "";
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return Name;
		}

		private void SetSymbolType(ushort value)
		{
			ArrayDimension = (((value & 0x4000) == 16384) ? 2 : (((value & 0x2000) == 8192) ? 1 : 0));
			IsStruct = (value & 0x8000) == 32768;
			SymbolType = (ushort)(value & 0xFFF);
		}

		/// <summary>
		/// 克隆单个的标签数据信息
		/// </summary>
		/// <param name="abTagItem">标签信息</param>
		/// <returns>新的实例的标签</returns>
		public static AbTagItem CloneBy(AbTagItem abTagItem)
		{
			if (abTagItem == null)
			{
				return null;
			}
			AbTagItem obj = new AbTagItem
			{
				InstanceID = abTagItem.InstanceID,
				Name = abTagItem.Name,
				ByteOffset = abTagItem.ByteOffset,
				SymbolType = abTagItem.SymbolType,
				ArrayDimension = abTagItem.ArrayDimension
			};
			obj.ArrayLength[0] = abTagItem.ArrayLength[0];
			obj.ArrayLength[1] = abTagItem.ArrayLength[1];
			obj.ArrayLength[2] = abTagItem.ArrayLength[2];
			obj.IsStruct = abTagItem.IsStruct;
			return obj;
		}

		/// <summary>
		/// 克隆整个的标签数组信息
		/// </summary>
		/// <param name="abTagItems">标签数组信息</param>
		/// <returns>标签数组</returns>
		public static AbTagItem[] CloneBy(AbTagItem[] abTagItems)
		{
			AbTagItem[] array = new AbTagItem[abTagItems.Length];
			for (int i = 0; i < abTagItems.Length; i++)
			{
				array[i] = CloneBy(abTagItems[i]);
			}
			return array;
		}

		/// <summary>
		/// 从指定的原始字节的数据中，解析出实际的节点信息
		/// </summary>
		/// <param name="source">原始字节数据</param>
		/// <param name="index">起始的索引</param>
		/// <returns>标签信息</returns>
		public static AbTagItem PraseAbTagItem(byte[] source, ref int index)
		{
			AbTagItem obj = new AbTagItem
			{
				InstanceID = BitConverter.ToUInt32(source, index)
			};
			index += 4;
			ushort num = BitConverter.ToUInt16(source, index);
			index += 2;
			obj.Name = Encoding.ASCII.GetString(source, index, num);
			index += num;
			obj.SetSymbolType(BitConverter.ToUInt16(source, index));
			index += 2;
			obj.ArrayLength[0] = BitConverter.ToInt32(source, index);
			index += 4;
			obj.ArrayLength[1] = BitConverter.ToInt32(source, index);
			index += 4;
			obj.ArrayLength[2] = BitConverter.ToInt32(source, index);
			index += 4;
			return obj;
		}

		/// <summary>
		/// 从指定的原始字节的数据中，解析出实际的标签数组，如果是系统保留的数组，或是__开头的，则自动忽略。
		/// </summary>
		/// <param name="source">原始字节数据</param>
		/// <param name="index">起始的索引</param>
		/// <param name="isGlobalVariable">是否局部变量</param>
		/// <param name="instance">输出最后一个标签的实例ID</param>
		/// <returns>标签信息</returns>
		public static List<AbTagItem> PraseAbTagItems(byte[] source, int index, bool isGlobalVariable, out uint instance)
		{
			List<AbTagItem> list = new List<AbTagItem>();
			instance = 0u;
			while (index < source.Length)
			{
				AbTagItem abTagItem = PraseAbTagItem(source, ref index);
				instance = abTagItem.InstanceID;
				if ((abTagItem.SymbolType & 0x1000) != 4096 && !abTagItem.Name.StartsWith("__") && !abTagItem.Name.Contains(":"))
				{
					if (!isGlobalVariable)
					{
						abTagItem.Name = "Program:MainProgram." + abTagItem.Name;
					}
					list.Add(abTagItem);
				}
			}
			return list;
		}

		/// <summary>
		/// 计算到达指定的字节的长度信息，可以用来计算固定分割符得字节长度
		/// </summary>
		/// <param name="source">原始字节数据</param>
		/// <param name="index">索引位置</param>
		/// <param name="value">等待判断的字节</param>
		/// <returns>字符串长度，如果不存在，返回-1</returns>
		private static int CalculatesSpecifiedCharacterLength(byte[] source, int index, byte value)
		{
			for (int i = index; i < source.Length; i++)
			{
				if (source[i] == value)
				{
					return i - index;
				}
			}
			return -1;
		}

		private static string CalculatesString(byte[] source, ref int index, byte value)
		{
			if (index >= source.Length)
			{
				return string.Empty;
			}
			int num = CalculatesSpecifiedCharacterLength(source, index, value);
			if (num < 0)
			{
				index = source.Length;
				return string.Empty;
			}
			string result = Encoding.ASCII.GetString(source, index, num);
			index += num + 1;
			return result;
		}

		/// <summary>
		/// 从结构体的数据中解析出实际的子标签信息
		/// </summary>
		/// <param name="source">原始字节</param>
		/// <param name="index">偏移索引</param>
		/// <param name="structHandle">结构体句柄</param>
		/// <returns>结果内容</returns>
		public static List<AbTagItem> PraseAbTagItemsFromStruct(byte[] source, int index, AbStructHandle structHandle)
		{
			List<AbTagItem> list = new List<AbTagItem>();
			int index2 = structHandle.MemberCount * 8 + index;
			CalculatesString(source, ref index2, 0);
			for (int i = 0; i < structHandle.MemberCount; i++)
			{
				AbTagItem abTagItem = new AbTagItem();
				abTagItem.ArrayLength[0] = BitConverter.ToUInt16(source, 8 * i + index);
				abTagItem.SetSymbolType(BitConverter.ToUInt16(source, 8 * i + index + 2));
				abTagItem.ByteOffset = BitConverter.ToInt32(source, 8 * i + index + 4) + 2;
				abTagItem.Name = CalculatesString(source, ref index2, 0);
				list.Add(abTagItem);
			}
			return list;
		}
	}
	/// <summary>
	/// AB标签的数据信息<br />
	/// </summary>
	public class AbTagValue
	{
		/// <summary>
		/// 标签的数据类型
		/// </summary>
		public ushort Type { get; set; }

		/// <summary>
		/// 标签的数据内容
		/// </summary>
		public byte[] Value { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// </summary>
		public AbTagValue()
		{
		}

		/// <summary>
		/// 指定标签的名称，数据类型，数据内容来实例化一个对象<br />
		/// </summary>
		/// <param name="type"></param>
		/// <param name="value"></param>
		public AbTagValue(ushort type, byte[] value)
		{
			Type = type;
			Value = value;
		}
	}
	/// <summary>
	/// 基于连接的对象访问的CIP协议的实现，用于对罗克韦尔 PLC进行标签的数据读写，对数组，多维数组进行读写操作，支持的数据类型请参照API文档手册。<br />
	/// The implementation of the CIP protocol based on connected object access is used to read and write tag data to Rockwell PLC, 
	/// and read and write arrays and multidimensional arrays. For the supported data types, please refer to the API documentation manual.
	/// </summary>
	/// <remarks>
	/// 支持普通标签的读写，类型要和标签对应上。如果标签是数组，例如 A 是 INT[0...9] 那么Read("A", 1)，返回的是10个short所有字节数组。
	/// 如果需要返回10个长度的short数组，请调用 ReadInt16("A[0], 10"); 地址必须写 "A[0]"，不能写 "A" , 如需要读取结构体，参考 <see cref="M:Snet.Driver.Profinet.Omron.OmronConnectedCipNet.ReadStruct``1(System.String)" />
	/// </remarks>
	/// <example>
	/// 首先说明支持的类型地址，在PLC里支持了大量的类型，有些甚至在C#里是不存在的。现在做个统一的声明
	/// <list type="table">
	///   <listheader>
	///     <term>PLC类型</term>
	///     <term>含义</term>
	///     <term>代号</term>
	///     <term>C# 类型</term>
	///     <term>备注</term>
	///   </listheader>
	///   <item>
	///     <term>bool</term>
	///     <term>位类型数据</term>
	///     <term>0xC1</term>
	///     <term>bool</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>SINT</term>
	///     <term>8位的整型</term>
	///     <term>0xC2</term>
	///     <term>sbyte</term>
	///     <term>有符号8位很少用，Snet直接用byte</term>
	///   </item>
	///   <item>
	///     <term>USINT</term>
	///     <term>无符号8位的整型</term>
	///     <term>0xC6</term>
	///     <term>byte</term>
	///     <term>如需要，使用<see cref="M:Snet.Driver.Profinet.Omron.OmronConnectedCipNet.WriteTag(System.String,System.UInt16,System.Byte[],System.Int32)" />实现</term>
	///   </item>
	///   <item>
	///     <term>BYTE</term>
	///     <term>8位字符数据</term>
	///     <term>0xD1</term>
	///     <term>byte</term>
	///     <term>如需要，使用<see cref="M:Snet.Driver.Profinet.Omron.OmronConnectedCipNet.WriteTag(System.String,System.UInt16,System.Byte[],System.Int32)" />实现</term>
	///   </item>
	///   <item>
	///     <term>INT</term>
	///     <term>16位的整型</term>
	///     <term>0xC3</term>
	///     <term>short</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>UINT</term>
	///     <term>无符号的16位整型</term>
	///     <term>0xC7</term>
	///     <term>ushort</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>DINT</term>
	///     <term>32位的整型</term>
	///     <term>0xC4</term>
	///     <term>int</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>UDINT</term>
	///     <term>无符号的32位整型</term>
	///     <term>0xC8</term>
	///     <term>uint</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>LINT</term>
	///     <term>64位的整型</term>
	///     <term>0xC5</term>
	///     <term>long</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>ULINT</term>
	///     <term>无符号的64位的整型</term>
	///     <term>0xC9</term>
	///     <term>ulong</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>REAL</term>
	///     <term>单精度浮点数</term>
	///     <term>0xCA</term>
	///     <term>float</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>DOUBLE</term>
	///     <term>双精度浮点数</term>
	///     <term>0xCB</term>
	///     <term>double</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>STRING</term>
	///     <term>字符串数据</term>
	///     <term>0xD0</term>
	///     <term>string</term>
	///     <term>前两个字节为字符长度</term>
	///   </item>
	///   <item>
	///     <term>8bit string BYTE</term>
	///     <term>8位的字符串</term>
	///     <term>0xD1</term>
	///     <term></term>
	///     <term>本质是BYTE数组</term>
	///   </item>
	///   <item>
	///     <term>16bit string WORD</term>
	///     <term>16位的字符串</term>
	///     <term>0xD2</term>
	///     <term></term>
	///     <term>本质是WORD数组，可存放中文</term>
	///   </item>
	///   <item>
	///     <term>32bit string DWORD</term>
	///     <term>32位的字符串</term>
	///     <term>0xD2</term>
	///     <term></term>
	///     <term>本质是DWORD数组，可存放中文</term>
	///   </item>
	/// </list>
	/// 在读写操作之前，先看看怎么实例化和连接PLC<br />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage" title="实例化及连接示例" />
	/// 现在来说明以下具体的操作细节。我们假设有如下的变量：<br />
	/// CESHI_A       SINT<br />
	/// CESHI_B       BYTE<br />
	/// CESHI_C       INT<br />
	/// CESHI_D       UINT<br />
	/// CESHI_E       SINT[0..9]<br />
	/// CESHI_F       BYTE[0..9]<br />
	/// CESHI_G       INT[0..9]<br />
	/// CESHI_H       UINT[0..9]<br />
	/// CESHI_I       INT[0..511]<br />
	/// CESHI_J       STRING[12]<br />
	/// ToPc_ID1      ARRAY[0..99] OF STRING[20]<br />
	/// CESHI_O       BOOL<br />
	/// CESHI_P       BOOL[0..31]<br />
	/// 对 CESHI_A 来说，读写这么操作
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage2" title="读写示例" />
	/// 对于 CESHI_B 来说，写入的操作有点特殊
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage3" title="读写示例" />
	/// 对于 CESHI_C, CESHI_D 来说，就是 ReadInt16(string address) , Write( string address, short value ) 和 ReadUInt16(string address) 和 Write( string address, ushort value ) 差别不大。
	/// 所以我们着重来看看数组的情况，以 CESHI_G 标签为例子:<br />
	/// 情况一，我想一次读取这个标签所有的字节数组（当长度满足的情况下，会一次性返回数据）
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage4" title="读写示例" />
	/// 情况二，我想读取第3个数，或是第6个数开始，一共5个数
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage5" title="读写示例" />
	/// 其他的数组情况都是类似的，我们来看看字符串 CESHI_J 变量
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage6" title="读写示例" />
	/// 对于 bool 变量来说，就是 ReadBool("CESHI_O") 和 Write("CESHI_O", true) 操作，如果是bool数组，就不一样了
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage7" title="读写示例" />
	/// 最后我们来看看结构体的操作，假设我们有个结构体<br />
	/// MyData.Code     STRING(12)<br />
	/// MyData.Value1   INT<br />
	/// MyData.Value2   INT<br />
	/// MyData.Value3   REAL<br />
	/// MyData.Value4   INT<br />
	/// MyData.Value5   INT<br />
	/// MyData.Value6   INT[0..3]<br />
	/// 因为bool比较复杂，暂时不考虑。要读取上述的结构体，我们需要定义结构一样的数据
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage8" title="结构体" />
	/// 定义好后，我们再来读取就很简单了。
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Profinet\AllenBradleyConnectedCipNetSample.cs" region="Usage9" title="读写示例" />
	/// </example>
	public class AllenBradleyConnectedCipNet : OmronConnectedCipNet
	{
		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public AllenBradleyConnectedCipNet()
		{
		}

		/// <summary>
		/// 根据指定的IP及端口来实例化这个连接对象
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
		/// <param name="port">PLC的端口号信息</param>
		public AllenBradleyConnectedCipNet(string ipAddress, int port = 44818)
			: base(ipAddress, port)
		{
		}

		/// <inheritdoc />
		protected override int GetMaxTransferBytes()
		{
			return 1980;
		}

		/// <inheritdoc />
		public override OResult<string> ReadString(string address, ushort length, Encoding encoding)
		{
			OResult<byte[]> oResult = Read(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			try
			{
				if (oResult.Content.Length >= 6)
				{
					int count = base.ByteTransform.TransInt32(oResult.Content, 2);
					return OResult.CreateSuccessResult(encoding.GetString(oResult.Content, 6, count));
				}
				return OResult.CreateSuccessResult(encoding.GetString(oResult.Content));
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message + " Source: " + oResult.Content.ToHexString(' '));
			}
		}

		/// <inheritdoc />
		public override OResult Write(string address, string value, Encoding encoding)
		{
			if (string.IsNullOrEmpty(value))
			{
				value = string.Empty;
			}
			byte[] bytes = encoding.GetBytes(value);
			OResult oResult = Write(address + ".LEN", bytes.Length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			byte[] value2 = SoftBasic.ArrayExpandToLengthEven(bytes);
			return WriteTag(address + ".DATA[0]", 194, value2, bytes.Length);
		}

		/// <inheritdoc />
		public override async Task<OResult<string>> ReadStringAsync(string address, ushort length, Encoding encoding)
		{
			OResult<byte[]> oResult = await ReadAsync(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			if (oResult.Content.Length >= 6)
			{
				return OResult.CreateSuccessResult(encoding.GetString(count: base.ByteTransform.TransInt32(oResult.Content, 2), bytes: oResult.Content, index: 6));
			}
			return OResult.CreateSuccessResult(encoding.GetString(oResult.Content));
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, string value, Encoding encoding)
		{
			if (string.IsNullOrEmpty(value))
			{
				value = string.Empty;
			}
			byte[] data = encoding.GetBytes(value);
			OResult oResult = await WriteAsync(address + ".LEN", data.Length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return await WriteTagAsync(value: SoftBasic.ArrayExpandToLengthEven(data), address: address + ".DATA[0]", typeCode: 194, length: data.Length);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"AllenBradleyConnectedCipNet[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// AB-PLC的DF1通信协议，基于串口实现，通信机制为半双工，目前适用于 Micro-Logix1000,SLC500,SLC 5/03,SLC 5/04，地址示例：N7:1
	/// </summary>
	public class AllenBradleyDF1Serial : DeviceSerialPort
	{
		private SoftIncrementCount incrementCount;

		/// <summary>
		/// 站号信息
		/// </summary>
		public byte Station { get; set; }

		/// <summary>
		/// 目标节点号
		/// </summary>
		public byte DstNode { get; set; }

		/// <summary>
		/// 源节点号
		/// </summary>
		public byte SrcNode { get; set; }

		/// <summary>
		/// 校验方式
		/// </summary>
		public CheckType CheckType { get; set; }

		/// <summary>
		/// Instantiate a communication object for a Allenbradley PLC protocol
		/// </summary>
		public AllenBradleyDF1Serial()
		{
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
			incrementCount = new SoftIncrementCount(65535L, 0L);
			CheckType = CheckType.CRC16;
		}

		/// <summary>
		/// 读取PLC的原始数据信息，地址示例：N7:0  可以携带站号 s=2;N7:0, 携带 dst 和 src 信息，例如 dst=1;src=2;N7:0
		/// </summary>
		/// <param name="address">PLC的地址信息，支持的类型见类型注释说明</param>
		/// <param name="length">读取的长度，单位，字节</param>
		/// <returns>是否读取成功的结果对象</returns>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", Station);
			byte dstNode = (byte)SnetHelper.ExtractParameter(ref address, "dst", DstNode);
			byte srcNode = (byte)SnetHelper.ExtractParameter(ref address, "src", SrcNode);
			OResult<byte[]> oResult = BuildProtectedTypedLogicalReadWithThreeAddressFields(dstNode, srcNode, (int)incrementCount.GetCurrentValue(), address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(PackCommand(station, oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ExtractActualData(oResult2.Content);
		}

		/// <summary>
		/// 写入PLC的原始数据信息，地址示例：N7:0  可以携带站号 s=2;N7:0, 携带 dst 和 src 信息，例如 dst=1;src=2;N7:0
		/// </summary>
		/// <param name="address">PLC的地址信息，支持的类型见类型注释说明</param>
		/// <param name="value">原始的数据值</param>
		/// <returns>是否写入成功</returns>
		public override OResult Write(string address, byte[] value)
		{
			byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", Station);
			byte dstNode = (byte)SnetHelper.ExtractParameter(ref address, "dst", DstNode);
			byte srcNode = (byte)SnetHelper.ExtractParameter(ref address, "src", SrcNode);
			OResult<byte[]> oResult = BuildProtectedTypedLogicalWriteWithThreeAddressFields(dstNode, srcNode, (int)incrementCount.GetCurrentValue(), address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(PackCommand(station, oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return ExtractActualData(oResult2.Content);
		}

		private byte[] CalculateCheckResult(byte station, byte[] command)
		{
			if (CheckType == CheckType.BCC)
			{
				int num = station;
				for (int i = 0; i < command.Length; i++)
				{
					num += command[i];
				}
				num = (byte)(~num);
				num++;
				return new byte[1] { (byte)num };
			}
			return SoftCRC16.CRC16(SoftBasic.SpliceArray<byte>(new byte[1] { station }, new byte[1] { 2 }, command, new byte[1] { 3 }), 160, 1, 0, 0).SelectLast(2);
		}

		/// <summary>
		/// 打包命令的操作，加站号进行打包成完整的数据内容，命令内容为原始命令，打包后会自动补充0x10的值
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="command">等待发送的命令</param>
		/// <returns>打包之后的数据内容</returns>
		public byte[] PackCommand(byte station, byte[] command)
		{
			byte[] array = CalculateCheckResult(station, command);
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(16);
			memoryStream.WriteByte(1);
			memoryStream.WriteByte(station);
			if (station == 16)
			{
				memoryStream.WriteByte(station);
			}
			memoryStream.WriteByte(16);
			memoryStream.WriteByte(2);
			for (int i = 0; i < command.Length; i++)
			{
				memoryStream.WriteByte(command[i]);
				if (command[i] == 16)
				{
					memoryStream.WriteByte(command[i]);
				}
			}
			memoryStream.WriteByte(16);
			memoryStream.WriteByte(3);
			memoryStream.Write(array, 0, array.Length);
			return memoryStream.ToArray();
		}

		private static void AddLengthToMemoryStream(MemoryStream ms, ushort value)
		{
			if (value < 255)
			{
				ms.WriteByte((byte)value);
				return;
			}
			ms.WriteByte(byte.MaxValue);
			ms.WriteByte(BitConverter.GetBytes(value)[0]);
			ms.WriteByte(BitConverter.GetBytes(value)[1]);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyDF1Serial.BuildProtectedTypedLogicalReadWithThreeAddressFields(System.Byte,System.Byte,System.Int32,System.String,System.Int32)" />
		public static OResult<byte[]> BuildProtectedTypedLogicalReadWithThreeAddressFields(int tns, string address, int length)
		{
			OResult<AllenBradleySLCAddress> oResult = AllenBradleySLCAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(15);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(BitConverter.GetBytes(tns)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(tns)[1]);
			memoryStream.WriteByte(162);
			memoryStream.WriteByte(BitConverter.GetBytes(length)[0]);
			AddLengthToMemoryStream(memoryStream, oResult.Content.DbBlock);
			memoryStream.WriteByte(oResult.Content.DataCode);
			AddLengthToMemoryStream(memoryStream, (ushort)oResult.Content.AddressStart);
			AddLengthToMemoryStream(memoryStream, 0);
			return OResult.CreateSuccessResult(memoryStream.ToArray());
		}

		/// <summary>
		/// 构建0F-A2命令码的报文读取指令，用来读取文件数据。适用 Micro-Logix1000,SLC500,SLC 5/03,SLC 5/04, PLC-5，地址示例：N7:1<br />
		/// Construct a message read instruction of 0F-A2 command code to read file data. Applicable to Micro-Logix1000, SLC500, SLC 5/03, SLC 5/04, PLC-5, address example: N7:1
		/// </summary>
		/// <param name="dstNode">目标节点号</param>
		/// <param name="srcNode">原节点号</param>
		/// <param name="tns">消息号</param>
		/// <param name="address">PLC的地址信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <returns>初步的报文信息</returns>
		/// <remarks>
		/// 对于SLC 5/01或SLC 5/02而言，一次最多读取82个字节。对于 03 或是 04 为225，236字节取决于是否应用DF1驱动
		/// </remarks>
		public static OResult<byte[]> BuildProtectedTypedLogicalReadWithThreeAddressFields(byte dstNode, byte srcNode, int tns, string address, int length)
		{
			OResult<byte[]> oResult = BuildProtectedTypedLogicalReadWithThreeAddressFields(tns, address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(new byte[2] { dstNode, srcNode }, oResult.Content));
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyDF1Serial.BuildProtectedTypedLogicalWriteWithThreeAddressFields(System.Byte,System.Byte,System.Int32,System.String,System.Byte[])" />
		public static OResult<byte[]> BuildProtectedTypedLogicalWriteWithThreeAddressFields(int tns, string address, byte[] data)
		{
			OResult<AllenBradleySLCAddress> oResult = AllenBradleySLCAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(15);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(BitConverter.GetBytes(tns)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(tns)[1]);
			memoryStream.WriteByte(170);
			memoryStream.WriteByte(BitConverter.GetBytes(data.Length)[0]);
			AddLengthToMemoryStream(memoryStream, oResult.Content.DbBlock);
			memoryStream.WriteByte(oResult.Content.DataCode);
			AddLengthToMemoryStream(memoryStream, (ushort)oResult.Content.AddressStart);
			AddLengthToMemoryStream(memoryStream, 0);
			memoryStream.Write(data);
			return OResult.CreateSuccessResult(memoryStream.ToArray());
		}

		/// <summary>
		/// 构建0F-AA命令码的写入读取指令，用来写入文件数据。适用 Micro-Logix1000,SLC500,SLC 5/03,SLC 5/04, PLC-5，地址示例：N7:1<br />
		/// Construct a write and read command of 0F-AA command code to write file data. Applicable to Micro-Logix1000, SLC500, SLC 5/03, SLC 5/04, PLC-5, address example: N7:1
		/// </summary>
		/// <param name="dstNode">目标节点号</param>
		/// <param name="srcNode">原节点号</param>
		/// <param name="tns">消息号</param>
		/// <param name="address">PLC的地址信息</param>
		/// <param name="data">写入的数据内容</param>
		/// <returns>初步的报文信息</returns>
		/// <remarks>
		/// 对于SLC 5/01或SLC 5/02而言，一次最多读取82个字节。对于 03 或是 04 为225，236字节取决于是否应用DF1驱动
		/// </remarks>
		public static OResult<byte[]> BuildProtectedTypedLogicalWriteWithThreeAddressFields(byte dstNode, byte srcNode, int tns, string address, byte[] data)
		{
			OResult<byte[]> oResult = BuildProtectedTypedLogicalWriteWithThreeAddressFields(tns, address, data);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(new byte[2] { dstNode, srcNode }, oResult.Content));
		}

		/// <summary>
		/// 构建0F-AB的掩码写入的功能
		/// </summary>
		/// <param name="tns">消息号</param>
		/// <param name="address">PLC的地址信息</param>
		/// <param name="bitIndex">位索引信息</param>
		/// <param name="value">通断值</param>
		/// <returns>命令报文</returns>
		public static OResult<byte[]> BuildProtectedTypedLogicalMaskWithThreeAddressFields(int tns, string address, int bitIndex, bool value)
		{
			int value2 = 1 << bitIndex;
			OResult<AllenBradleySLCAddress> oResult = AllenBradleySLCAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(15);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(BitConverter.GetBytes(tns)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(tns)[1]);
			memoryStream.WriteByte(171);
			memoryStream.WriteByte(2);
			AddLengthToMemoryStream(memoryStream, oResult.Content.DbBlock);
			memoryStream.WriteByte(oResult.Content.DataCode);
			AddLengthToMemoryStream(memoryStream, (ushort)oResult.Content.AddressStart);
			AddLengthToMemoryStream(memoryStream, 0);
			memoryStream.WriteByte(BitConverter.GetBytes(value2)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(value2)[1]);
			if (value)
			{
				memoryStream.WriteByte(BitConverter.GetBytes(value2)[0]);
				memoryStream.WriteByte(BitConverter.GetBytes(value2)[1]);
			}
			else
			{
				memoryStream.WriteByte(0);
				memoryStream.WriteByte(0);
			}
			return OResult.CreateSuccessResult(memoryStream.ToArray());
		}

		/// <summary>
		/// 提取返回报文的数据内容，将其转换成实际的数据内容，如果PLC返回了错误信息，则结果对象为失败。<br />
		/// Extract the data content of the returned message and convert it into the actual data content. If the PLC returns an error message, the result object is a failure.
		/// </summary>
		/// <param name="content">PLC返回的报文信息</param>
		/// <returns>结果对象内容</returns>
		public static OResult<byte[]> ExtractActualData(byte[] content)
		{
			try
			{
				int num = -1;
				for (int i = 0; i < content.Length; i++)
				{
					if (content[i] == 16 && content[i + 1] == 2)
					{
						num = i + 2;
						break;
					}
				}
				if (num < 0 || num >= content.Length - 6)
				{
					return new OResult<byte[]>("Message must start with '10 02', source: " + content.ToHexString(' '));
				}
				MemoryStream memoryStream = new MemoryStream();
				for (int j = num; j < content.Length - 1; j++)
				{
					if (content[j] == 16 && content[j + 1] == 16)
					{
						memoryStream.WriteByte(content[j]);
						j++;
						continue;
					}
					if (content[j] == 16 && content[j + 1] == 3)
					{
						break;
					}
					memoryStream.WriteByte(content[j]);
				}
				content = memoryStream.ToArray();
				if (content[3] == 240)
				{
					return new OResult<byte[]>(GetExtStatusDescription(content[6]));
				}
				if (content[3] != 0)
				{
					return new OResult<byte[]>(GetStatusDescription(content[3]));
				}
				if (content.Length > 6)
				{
					return OResult.CreateSuccessResult(content.RemoveBegin(6));
				}
				return OResult.CreateSuccessResult(new byte[0]);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message + " Source:" + content.ToHexString(' '));
			}
		}

		/// <summary>
		/// 根据错误代码，来获取错误的具体描述文本
		/// </summary>
		/// <param name="code">错误的代码，非0</param>
		/// <returns>错误的描述文本信息</returns>
		public static string GetStatusDescription(byte code)
		{
			byte b = (byte)(code & 0xF);
			byte b2 = (byte)(code & 0xF0);
			return b switch
			{
				1 => "DST node is out of buffer space", 
				2 => "Cannot guarantee delivery: link layer(The remote node specified does not ACK command.)", 
				3 => "Duplicate token holder detected", 
				4 => "Local port is disconnected", 
				5 => "Application layer timed out waiting for a response", 
				6 => "Duplicate node detected", 
				7 => "Station is offline", 
				8 => "Hardware fault", 
				_ => b2 switch
				{
					16 => "Illegal command or format", 
					32 => "Host has a problem and will not communicate", 
					48 => "Remote node host is missing, disconnected, or shut down", 
					64 => "Host could not complete function due to hardware fault", 
					80 => "Addressing problem or memory protect rungs", 
					96 => "Function not allowed due to command protection selection", 
					112 => "Processor is in Program mode", 
					128 => "Compatibility mode file missing or communication zone problem", 
					144 => "Remote node cannot buffer command", 
					160 => "Wait ACK (1775\u0006KA buffer full)", 
					176 => "Remote node problem due to download", 
					192 => "Wait ACK (1775\u0006KA buffer full)", 
					240 => "Error code in the EXT STS byte", 
					_ => StringResources.Language.UnknownError, 
				}, 
			};
		}

		/// <summary>
		/// 根据错误代码，来获取错误的具体描述文本
		/// </summary>
		/// <param name="code">错误的代码，非0</param>
		/// <returns>错误的描述文本信息</returns>
		public static string GetExtStatusDescription(byte code)
		{
			return code switch
			{
				1 => "A field has an illegal value", 
				2 => "Less levels specified in address than minimum for any address", 
				3 => "More levels specified in address than system supports", 
				4 => "Symbol not found", 
				5 => "Symbol is of improper format", 
				6 => "Address doesn’t point to something usable", 
				7 => "File is wrong size", 
				8 => "Cannot complete request, situation has changed since the start of the command", 
				9 => "Data or file is too large", 
				10 => "Transaction size plus word address is too large", 
				11 => "Access denied, improper privilege", 
				12 => "Condition cannot be generated \u0006 resource is not available", 
				13 => "Condition already exists \u0006 resource is already available", 
				14 => "Command cannot be executed", 
				15 => "Histogram overflow", 
				16 => "No access", 
				17 => "Illegal data type", 
				18 => "Invalid parameter or invalid data", 
				19 => "Address reference exists to deleted area", 
				20 => "Command execution failure for unknown reason; possible PLC\u00063 histogram overflow", 
				21 => "Data conversion error", 
				22 => "Scanner not able to communicate with 1771 rack adapter", 
				23 => "Type mismatch", 
				24 => "1771 module response was not valid", 
				25 => "Duplicated label", 
				26 => "File is open; another node owns it", 
				27 => "Another node is the program owner", 
				28 => "Reserved", 
				29 => "Reserved", 
				30 => "Data table element protection violation", 
				31 => "Temporary internal problem", 
				34 => "Remote rack fault", 
				35 => "Timeout", 
				36 => "Unknown error", 
				_ => StringResources.Language.UnknownError, 
			};
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"AllenBradleyDF1Serial[{base.PortName}:{base.BaudRate}]";
		}
	}
