	/// <summary>
	/// AB PLC的标签节点数据信息
	/// </summary>
	public class AllenBradleyItemValue
	{
		/// <summary>
		/// 当前标签的名称信息
		/// </summary>
		public string Name { get; set; }

		/// <summary>
		/// 真实的数组缓存
		/// </summary>
		public byte[] Buffer { get; set; }

		/// <summary>
		/// 是否是数组的数据
		/// </summary>
		public bool IsArray { get; set; }

		/// <summary>
		/// 单个单位的数据长度信息
		/// </summary>
		public int TypeLength { get; set; } = 1;

		/// <summary>
		/// 数据类型信息
		/// </summary>
		public ushort TypeCode { get; set; } = 193;

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public AllenBradleyItemValue()
		{
		}

		/// <summary>
		/// 指定XML元素的资源来实例化对象信息
		/// </summary>
		/// <param name="element">XML元素信息</param>
		public AllenBradleyItemValue(XElement element)
		{
			LoadByXml(element);
		}

		private string getTypeHelper(string type)
		{
			if (IsArray)
			{
				if (TypeLength == 0)
				{
					return type;
				}
				return $"{type}[{Buffer.Length / TypeLength}]";
			}
			return type ?? "";
		}

		/// <summary>
		/// 获取当前的数据类型名称描述
		/// </summary>
		/// <returns>类型信息，如果不支持解析，则返回类型代号</returns>
		public string GetTypeName()
		{
			if (TypeCode == 194)
			{
				return getTypeHelper("sbyte");
			}
			if (TypeCode == 195)
			{
				return getTypeHelper("short");
			}
			if (TypeCode == 196)
			{
				return getTypeHelper("int");
			}
			if (TypeCode == 197)
			{
				return getTypeHelper("long");
			}
			if (TypeCode == 198)
			{
				return getTypeHelper("byte");
			}
			if (TypeCode == 199)
			{
				return getTypeHelper("ushort");
			}
			if (TypeCode == 200)
			{
				return getTypeHelper("uint");
			}
			if (TypeCode == 201)
			{
				return getTypeHelper("ulong");
			}
			if (TypeCode == 202)
			{
				return getTypeHelper("float");
			}
			if (TypeCode == 203)
			{
				return getTypeHelper("double");
			}
			if (TypeCode == 208)
			{
				return getTypeHelper("string");
			}
			if (TypeCode == 209)
			{
				return getTypeHelper("string");
			}
			if (TypeCode == 193)
			{
				return getTypeHelper("bool");
			}
			return $"0x{TypeCode:X}";
		}

		/// <summary>
		/// 将值转换为同等描述的序列化字符串信息
		/// </summary>
		/// <returns>Xml元素</returns>
		public XElement ToXml()
		{
			XElement xElement = new XElement("AllenBradleyItemValue");
			xElement.SetAttributeValue("Name", Name);
			xElement.SetAttributeValue("TypeCode", TypeCode);
			xElement.SetAttributeValue("IsArray", IsArray);
			xElement.SetAttributeValue("TypeLength", TypeLength);
			if (Buffer != null)
			{
				xElement.SetAttributeValue("Buffer", Buffer.ToHexString());
			}
			return xElement;
		}

		private T GetXmlValue<T>(XElement element, string name, T defaultValue, Func<string, T> trans)
		{
			XAttribute xAttribute = element.Attribute(name);
			if (xAttribute == null)
			{
				return defaultValue;
			}
			try
			{
				return trans(xAttribute.Value);
			}
			catch
			{
				return defaultValue;
			}
		}

		/// <summary>
		/// 从xml元素加载当前的节点数据信息
		/// </summary>
		/// <param name="element">元素信息</param>
		public void LoadByXml(XElement element)
		{
			if (element.Name == "AllenBradleyItemValue")
			{
				Name = GetXmlValue(element, "Name", Name, (string m) => m);
				TypeCode = GetXmlValue(element, "TypeCode", TypeCode, ushort.Parse);
				IsArray = GetXmlValue(element, "IsArray", IsArray, bool.Parse);
				TypeLength = GetXmlValue(element, "TypeLength", TypeLength, int.Parse);
				Buffer = GetXmlValue(element, "Buffer", "", (string m) => m).ToHexBytes();
			}
		}
	}
	/// <summary>
	/// AB PLC的cip通信实现类，适用Micro800系列控制系统<br />
	/// AB PLC's cip communication implementation class, suitable for Micro800 series control system
	/// </summary>
	public class AllenBradleyMicroCip : AllenBradleyNet
	{
		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.#ctor" />
		public AllenBradleyMicroCip()
		{
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.#ctor(System.String,System.Int32)" />
		public AllenBradleyMicroCip(string ipAddress, int port = 44818)
			: base(ipAddress, port)
		{
		}

		/// <inheritdoc />
		protected override byte[] PackCommandService(byte[] portSlot, params byte[][] cips)
		{
			return AllenBradleyHelper.PackCleanCommandService(portSlot, cips);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"AllenBradleyMicroCip[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// AB PLC的数据通信类，使用CIP协议实现，适用1756，1769等型号，支持使用标签的形式进行读写操作，支持标量数据，一维数组，二维数组，三维数组等等。如果是局部变量，那么使用 Program:MainProgram.[变量名]。<br />
	/// The data communication class of AB PLC is implemented using the CIP protocol. It is suitable for 1756, 1769 and other models. 
	/// It supports reading and writing in the form of tags, scalar data, one-dimensional array, two-dimensional array, 
	/// three-dimensional array, and so on. If it is a local variable, use the Program:MainProgram.[Variable name].
	/// </summary>
	/// <remarks>
	/// 默认的地址就是PLC里的TAG名字，比如A，B，C；如果你需要读取的数据是一个数组，那么A就是默认的A[0]，如果想要读取偏移量为10的数据，那么地址为A[10]，
	/// 多维数组同理，使用A[10,10,10]的操作。
	/// <br />
	/// <br />
	/// 假设你读取的是局部变量，那么使用 Program:MainProgram.变量名<br />
	/// 目前适用的系列为1756 ControlLogix, 1756 GuardLogix, 1769 CompactLogix, 1769 Compact GuardLogix, 1789SoftLogix, 5069 CompactLogix, 5069 Compact GuardLogix, Studio 5000 Logix Emulate
	/// <br />
	/// <br />
	/// 如果你有个Bool数组要读取，变量名为 A, 那么读第0个位，可以通过 ReadBool("A")，但是第二个位需要使用<br />
	/// ReadBoolArray("A[0]")   // 返回32个bool长度，0-31的索引，如果我想读取32-63的位索引，就需要 ReadBoolArray("A[1]") ，以此类推。
	/// <br />
	/// <br />
	/// 地址可以携带站号信息，只要在前面加上slot=2;即可，这就是访问站号2的数据了，例如 slot=2;AAA，如果使用了自定义的消息路由，例如：[IP or Hostname],1,[Optional Routing Path],CPU Slot 172.20.1.109,1,[15,2,18,1],12<br />
	/// 在实例化之后，连接PLC之前，需要调用如下代码 plc.MessageRouter = new MessageRouter( "1.15.2.18.1.12" )
	/// </remarks>
	public class AllenBradleyNet : DeviceTcpNet, IReadWriteCip, IReadWriteNet
	{
		private long contextId;

		private Dictionary<string, int> boolValueDataBits = new Dictionary<string, int>();

		private object boolLock = new object();

		/// <summary>
		/// Gets or sets a value indicating whether the context ID is automatically incremented. The default is true
		/// </summary>
		public bool ContextIdAutoIncrement { get; set; } = true;

		/// <summary>
		/// The current session handle, which is determined by the PLC when communicating with the PLC handshake
		/// </summary>
		public uint SessionHandle { get; protected set; }

		/// <summary>
		/// Gets or sets the slot number information for the current plc, which should be set before connections
		/// </summary>
		public byte Slot { get; set; }

		/// <summary>
		/// port and slot information
		/// </summary>
		public byte[] PortSlot { get; set; }

		/// <summary>
		/// 获取或设置整个交互指令的控制码，默认为0x6F，通常不需要修改<br />
		/// Gets or sets the control code of the entire interactive instruction. The default is 0x6F, and usually does not need to be modified.
		/// </summary>
		public ushort CipCommand { get; set; } = 111;

		/// <summary>
		/// 获取或设置当前的通信的消息路由信息，可以实现一些复杂情况的通信，数据包含背板号，路由参数，slot，例如：1.15.2.18.1.1<br />
		/// Get or set the message routing information of the current communication, which can realize some complicated communication. 
		/// The data includes the backplane number, routing parameters, and slot, for example: 1.15.2.18.1.1
		/// </summary>
		public MessageRouter MessageRouter { get; set; }

		/// <summary>
		/// Gets or sets a value indicating whether the current context meets the required conditions.
		/// </summary>
		public bool ContextCheck { get; set; }

		/// <summary>
		/// 获取或设置是否在读取数组的时候使用片段读取功能，默认是开启的。<br />
		/// Get or set whether to use the fragment reading function when reading the array. By default, it is enabled.
		/// </summary>
		public bool ReadArrayUseSegment { get; set; } = true;

		/// <summary>
		/// 获取当前缓存的Bool变量的类型信息，key为标签地址，value为数据位长度信息<br />
		/// </summary>
		public Dictionary<string, int> TagValueAndDataBits => boolValueDataBits;

		/// <summary>
		/// Instantiate a communication object for a Allenbradley PLC protocol
		/// </summary>
		public AllenBradleyNet()
		{
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// Instantiate a communication object for a Allenbradley PLC protocol
		/// </summary>
		/// <param name="ipAddress">PLC IpAddress</param>
		/// <param name="port">PLC Port</param>
		public AllenBradleyNet(string ipAddress, int port = 44818)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new AllenBradleyMessage(ContextCheck);
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			byte[] bytes = BitConverter.GetBytes(ContextIdAutoIncrement ? Interlocked.Increment(ref contextId) : contextId);
			return AllenBradleyHelper.PackRequestHeader(CipCommand, SessionHandle, command, bytes);
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			Interlocked.Exchange(ref contextId, 0L);
			ClearBoolTypeCache();
			OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.RegisterSessionHandle(), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult oResult2 = AllenBradleyHelper.CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess && oResult2.ErrorCode != 1)
			{
				return oResult2;
			}
			if (oResult.Content.Length >= 8)
			{
				SessionHandle = BitConverter.ToUInt32(oResult.Content, 4);
			}
			if (MessageRouter != null)
			{
				byte[] routerCIP = MessageRouter.GetRouterCIP();
				OResult<byte[]> oResult3 = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, SessionHandle, AllenBradleyHelper.PackCommandSpecificData(new byte[4], AllenBradleyHelper.PackCommandSingleService(routerCIP, 178, isConnected: false, 0))), hasResponseData: true, usePackAndUnpack: false);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override OResult ExtraOnDisconnect()
		{
			if (CommunicationPipe != null)
			{
				OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.UnRegisterSessionHandle(SessionHandle), hasResponseData: true, usePackAndUnpack: false);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			return OResult.CreateSuccessResult();
		}

