				byte[] routerCIP = MessageRouter.GetRouterCIP();
				OResult<byte[]> oResult3 = await ReadFromCoreServerAsync(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, SessionHandle, AllenBradleyHelper.PackCommandSpecificData(new byte[4], AllenBradleyHelper.PackCommandSingleService(routerCIP, 178, isConnected: false, 0))), hasResponseData: true, usePackAndUnpack: false).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
			}
			return OResult.CreateSuccessResult();
		}

