		/// <summary>
		/// 创建一个读取标签的报文指定，标签地址可以手动动态指定slot编号，例如 slot=2;AAA<br />
		/// Build a read command bytes, The label address can manually specify the slot number dynamically, for example slot=2;AAA
		/// </summary>
		/// <param name="address">the address of the tag name</param>
		/// <param name="length">Array information, if not arrays, is 1 </param>
		/// <returns>Message information that contains the result object </returns>
		public virtual OResult<byte[]> BuildReadCommand(string[] address, ushort[] length)
		{
			if (address == null || length == null)
			{
				return new OResult<byte[]>("address or length is null");
			}
			if (address.Length != length.Length)
			{
				return new OResult<byte[]>("address and length is not same array");
			}
			try
			{
				if (address.Length == 1 && AllenBradleyHelper.IsAddressClassAndAttribute(address[0]))
				{
					byte[] cip = AllenBradleyHelper.PackRequsetRead(address[0], length[0]);
					return OResult.CreateSuccessResult(AllenBradleyHelper.PackCommandSpecificData(new byte[4], AllenBradleyHelper.PackCommandService(cip)));
				}
				byte b = Slot;
				List<byte[]> list = new List<byte[]>();
				for (int i = 0; i < address.Length; i++)
				{
					b = (byte)SnetHelper.ExtractParameter(ref address[i], "slot", Slot);
					list.Add(AllenBradleyHelper.PackRequsetRead(address[i], length[i]));
				}
				return OResult.CreateSuccessResult(AllenBradleyHelper.PackCommandSpecificData(new byte[4], PackCommandService(PortSlot ?? new byte[2] { 1, b }, list.ToArray())));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address Wrong:" + ex.Message);
			}
		}

		/// <summary>
		/// 创建一个读取多标签的报文<br />
		/// Build a read command bytes
		/// </summary>
		/// <param name="address">The address of the tag name </param>
		/// <returns>Message information that contains the result object </returns>
		public OResult<byte[]> BuildReadCommand(string[] address)
		{
			if (address == null)
			{
				return new OResult<byte[]>("address or length is null");
			}
			ushort[] array = new ushort[address.Length];
			for (int i = 0; i < address.Length; i++)
			{
				array[i] = 1;
			}
			return BuildReadCommand(address, array);
		}

		/// <summary>
		/// Create a written message instruction
		/// </summary>
		/// <param name="address">The address of the tag name </param>
		/// <param name="typeCode">Data type</param>
		/// <param name="data">Source Data </param>
		/// <param name="length">In the case of arrays, the length of the array </param>
		/// <returns>Message information that contains the result object</returns>
		protected virtual OResult<List<byte[]>> BuildWriteCommand(string address, ushort typeCode, byte[] data, int length = 1)
		{
			try
			{
				if (AllenBradleyHelper.IsAddressClassAndAttribute(address))
				{
					byte[] cip = AllenBradleyHelper.PackRequestWrite(address, typeCode, data, length, isConnectedAddress: false, GetBoolWritePadding());
					byte[] item = AllenBradleyHelper.PackCommandSpecificData(new byte[4], AllenBradleyHelper.PackCommandService(cip));
					return OResult.CreateSuccessResult(new List<byte[]> { item });
				}
				byte b = (byte)SnetHelper.ExtractParameter(ref address, "slot", Slot);
				int num = SnetHelper.ExtractParameter(ref address, "x", -1);
				if (num == 83 || num == 82)
				{
					int num2 = 0;
					List<byte[]> list = SoftBasic.ArraySplitByLength(data, 474);
					for (int i = 0; i < list.Count; i++)
					{
						byte[] array = AllenBradleyHelper.PackRequestWriteSegment(address, typeCode, list[i], num2, length);
						num2 += list[i].Length;
						byte[] value = AllenBradleyHelper.PackCommandSpecificData(new byte[4], PackCommandService(PortSlot ?? new byte[2] { 1, b }, array));
						list[i] = value;
					}
					return OResult.CreateSuccessResult(list);
				}
				byte[] array2 = AllenBradleyHelper.PackRequestWrite(address, typeCode, data, length, isConnectedAddress: false, GetBoolWritePadding());
				byte[] item2 = AllenBradleyHelper.PackCommandSpecificData(new byte[4], PackCommandService(PortSlot ?? new byte[2] { 1, b }, array2));
				return OResult.CreateSuccessResult(new List<byte[]> { item2 });
			}
			catch (Exception ex)
			{
				return new OResult<List<byte[]>>("Address Wrong:" + ex.Message);
			}
		}

		/// <summary>
		/// 当进行bool写入的时候，是否需要补齐到字节长度，默认不需要<br />
		/// When performing bool writing, whether it is necessary to complement to the byte length is not required by default
		/// </summary>
		/// <returns>是否需要字节对齐</returns>
		protected virtual bool GetBoolWritePadding()
		{
			return false;
		}

		/// <summary>
		/// Create a written message instruction
		/// </summary>
		/// <param name="address">The address of the tag name </param>
		/// <param name="data">Bool Data </param>
		/// <returns>Message information that contains the result object</returns>
		public OResult<byte[]> BuildWriteCommand(string address, bool data)
		{
			try
			{
				byte b = (byte)SnetHelper.ExtractParameter(ref address, "slot", Slot);
				address = AllenBradleyHelper.AnalysisArrayIndex(address, out var arrayIndex);
				OResult<int> boolValueTypeBitLength = GetBoolValueTypeBitLength(address);
				if (!boolValueTypeBitLength.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(boolValueTypeBitLength);
				}
				byte[] array = AllenBradleyHelper.PackRequestReadModifyWrite(address, arrayIndex, data, boolValueTypeBitLength.Content);
				return OResult.CreateSuccessResult(AllenBradleyHelper.PackCommandSpecificData(new byte[4], PackCommandService(PortSlot ?? new byte[2] { 1, b }, array)));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address Wrong:" + ex.Message);
			}
		}

		private OResult CheckResponse(byte[] response)
		{
			OResult oResult = AllenBradleyHelper.CheckResponse(response);
			if (!oResult.IsSuccess && oResult.ErrorCode == 100)
			{
				CommunicationPipe.RaisePipeError();
			}
			return oResult;
		}

		/// <summary>
		/// 读取指定地址的二进制数据内容，长度为地址长度，一般都是1，除非读取数组时，如果需要强制使用 片段读取功能码，则地址里携带 x=0x52; 或是 x=82; 则强制使用片段读取。<br />
		/// Read the binary data content of the specified address, the length is the address length, generally 1, unless the array is read, if you need to force the fragment reading function code, 
		/// the address carries x=0x52; or x=82; then the fragment read is forced.
		/// </summary>
		/// <remarks>
		/// 使用片段读取的时候，可以读取一些数量量非常大的地址，例如一个结构体标签有100_000个字节长度的时候。<br />
		/// When using fragment reading, you can read a very large number of addresses, such as when a struct tag is 100_000 bytes long.
		/// </remarks>
		/// <param name="address">Address format of the node</param>
		/// <param name="length">In the case of arrays, the length of the array </param>
		/// <returns>Result data with result object </returns>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			SnetHelper.ExtractParameter(ref address, "type", 0);
			int num = SnetHelper.ExtractParameter(ref address, "x", -1);
			if (num == 82 || num == 83)
			{
				return ReadSegment(address, 0, length);
			}
			if (length > 1 && ReadArrayUseSegment)
			{
				return ReadSegment(address, 0, length);
			}
			return Read(new string[1] { address }, new ushort[1] { length });
		}

		/// <summary>
		/// 批量读取多地址的数据信息，例如我可以读取两个标签的数据 "A","B[0]"，每个地址的数据长度为1，表示一个数据，最终读取返回的是一整个的字节数组，需要自行解析<br />
		/// Batch read data information of multiple addresses, for example, I can read the data of two tags "A", "B[0]", the data length of each address is 1, 
		/// which means one data, and the final read returns a The entire byte array, which needs to be parsed by itself
		/// </summary>
		/// <param name="address">Name of the node </param>
		/// <returns>Result data with result object </returns>
		public OResult<byte[]> Read(string[] address)
		{
			if (address == null)
			{
				return new OResult<byte[]>("address can not be null");
			}
			ushort[] array = new ushort[address.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = 1;
			}
			return Read(address, array);
		}

		/// <summary>
		/// 批量读取多地址的数据信息，例如我可以读取两个标签的数据 "A","B[0]"， 长度为 [1, 5]，返回的是一整个的字节数组，需要自行解析<br />
		/// Read the data information of multiple addresses in batches. For example, I can read the data "A", "B[0]" of two tags, 
		/// the length is [1, 5], and the return is an entire byte array, and I need to do it myself Parsing
		/// </summary>
		/// <param name="address">节点的名称 -&gt; Name of the node </param>
		/// <param name="length">如果是数组，就为数组长度 -&gt; In the case of arrays, the length of the array </param>
		/// <returns>带有结果对象的结果数据 -&gt; Result data with result object </returns>
		public OResult<byte[]> Read(string[] address, ushort[] length)
		{
			OResult<byte[], ushort, bool> oResult = ReadWithType(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult(oResult.Content1);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.Read(System.String[],System.UInt16[])" />
		public OResult<AbTagValue[]> ReadTags(string[] address, ushort[] length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<AbTagValue[]>(oResult);
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<AbTagValue[]>(oResult2);
			}
			OResult oResult3 = CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<AbTagValue[]>(oResult3);
			}
			OResult<List<AbTagValue>, bool> oResult4 = AllenBradleyHelper.ExtractActualDataList(oResult2.Content, isRead: true);
			if (!oResult4.IsSuccess)
			{
				return OResult.CreateFailedResult<AbTagValue[]>(oResult4);
			}
			return OResult.CreateSuccessResult(oResult4.Content1.ToArray());
		}

		private OResult<byte[], ushort, bool> ReadWithType(string[] address, ushort[] length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], ushort, bool>(oResult);
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], ushort, bool>(oResult2);
			}
			OResult oResult3 = CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], ushort, bool>(oResult3);
			}
			return AllenBradleyHelper.ExtractActualData(oResult2.Content, isRead: true);
		}

		/// <summary>
		/// Read Segment Data Array form plc, use address tag name
		/// </summary>
		/// <param name="address">Tag name in plc</param>
		/// <param name="startIndex">array start index, uint byte index</param>
		/// <param name="length">array length, data item length</param>
		/// <returns>Results Bytes</returns>
		public OResult<byte[]> ReadSegment(string address, int startIndex, int length)
		{
			try
			{
				List<byte> list = new List<byte>();
				OResult<byte[], ushort, bool> oResult2;
				do
				{
					OResult<byte[]> oResult = ReadCipFromServer(AllenBradleyHelper.PackRequestReadSegment(address, startIndex, length));
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					oResult2 = AllenBradleyHelper.ExtractActualData(oResult.Content, isRead: true);
					if (!oResult2.IsSuccess)
					{
						return OResult.CreateFailedResult<byte[]>(oResult2);
					}
					startIndex += oResult2.Content1.Length;
					if (list.Count != 0 && oResult2.Content2 == 672 && oResult2.Content1.Length >= 2 && oResult2.Content1[0] == list[0] && oResult2.Content1[1] == list[1])
					{
						list.AddRange(oResult2.Content1.Skip(2));
					}
					else
					{
						list.AddRange(oResult2.Content1);
					}
					if (oResult2.Content2 == 672)
					{
						startIndex -= 2;
					}
				}
				while (oResult2.Content3);
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address Wrong:" + ex.Message);
			}
		}

		private OResult<byte[]> ReadByCips(params byte[][] cips)
		{
			OResult<byte[]> oResult = ReadCipFromServer(cips);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[], ushort, bool> oResult2 = AllenBradleyHelper.ExtractActualData(oResult.Content, isRead: true);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult2.Content1);
		}

		/// <summary>
		/// 使用CIP报文和服务器进行核心的数据交换
		/// </summary>
		/// <param name="cips">Cip commands</param>
		/// <returns>Results Bytes</returns>
		public OResult<byte[]> ReadCipFromServer(params byte[][] cips)
		{
			byte[] send = AllenBradleyHelper.PackCommandSpecificData(new byte[4], PackCommandService(PortSlot ?? new byte[2] { 1, Slot }, cips.ToArray()));
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult oResult2 = CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult.Content);
		}

		/// <summary>
		/// 使用EIP报文和服务器进行核心的数据交换
		/// </summary>
		/// <param name="eip">eip commands</param>
		/// <returns>Results Bytes</returns>
		public OResult<byte[]> ReadEipFromServer(params byte[][] eip)
		{
			byte[] send = AllenBradleyHelper.PackCommandSpecificData(eip);
			OResult<byte[]> oResult = ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult oResult2 = CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult(oResult.Content);
		}

		/// <summary>
		/// 读取单个的bool数据信息，如果读取的是单bool变量，就直接写变量名，如果是由int组成的bool数组的一个值，一律带"i="开头访问，例如"i=A[0]" <br />
		/// Read a single bool data information, if it is a single bool variable, write the variable name directly, 
		/// if it is a value of a bool array composed of int, it is always accessed with "i=" at the beginning, for example, "i=A[0]"
		/// </summary>
		/// <param name="address">节点的名称 -&gt; Name of the node </param>
		/// <returns>带有结果对象的结果数据 -&gt; Result data with result info </returns>
		public override OResult<bool> ReadBool(string address)
		{
			if (address.StartsWith("i="))
			{
				return ByteTransformHelper.GetResultFromArray(ReadBool(address, 1));
			}
			OResult<byte[]> oResult = Read(address, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			return OResult.CreateSuccessResult(base.ByteTransform.TransBool(oResult.Content, 0));
		}

		/// <inheritdoc />
		public override OResult<bool[]> ReadBool(string address, ushort length)
		{
			if (address.StartsWith("i="))
			{
				address = address.Substring(2);
				address = AllenBradleyHelper.AnalysisArrayIndex(address, out var arrayIndex);
				OResult<int> boolValueTypeBitLength = GetBoolValueTypeBitLength(address);
				if (!boolValueTypeBitLength.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(boolValueTypeBitLength);
				}
				int content = boolValueTypeBitLength.Content;
				string text = ((arrayIndex / content == 0) ? "" : $"[{arrayIndex / content}]");
				ushort length2 = (ushort)SnetHelper.CalculateOccupyLength(arrayIndex, length, content);
				OResult<byte[]> oResult = Read(address + text, length2);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				return OResult.CreateSuccessResult(oResult.Content.ToBoolArray().SelectMiddle(arrayIndex % content, length));
			}
			OResult<byte[]> oResult2 = Read(address, length);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(SoftBasic.ByteToBoolArray(oResult2.Content, length));
		}

		/// <summary>
		/// 批量读取的bool数组信息，如果你有个Bool数组变量名为 A, 那么读第0个位，可以通过 ReadBool("A")，但是第二个位需要使用 
		/// ReadBoolArray("A[0]")   // 返回32个bool长度，0-31的索引，如果我想读取32-63的位索引，就需要 ReadBoolArray("A[1]") ，以此类推。<br />
		/// For batch read bool array information, if you have a Bool array variable named A, then you can read the 0th bit through ReadBool("A"), 
		/// but the second bit needs to use ReadBoolArray("A[0]" ) // Returns the length of 32 bools, the index is 0-31, 
		/// if I want to read the bit index of 32-63, I need ReadBoolArray("A[1]"), and so on.
		/// </summary>
