		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.Read(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			SnetHelper.ExtractParameter(ref address, "type", 0);
			int num = SnetHelper.ExtractParameter(ref address, "x", -1);
			if (num == 82 || num == 83)
			{
				return await ReadSegmentAsync(address, 0, length).ConfigureAwait(continueOnCapturedContext: false);
			}
			if (length > 1 && ReadArrayUseSegment)
			{
				return await ReadSegmentAsync(address, 0, length).ConfigureAwait(continueOnCapturedContext: false);
			}
			return await ReadAsync(new string[1] { address }, new ushort[1] { length }).ConfigureAwait(continueOnCapturedContext: false);
		}

