		{
			if (address == null)
			{
				return new OResult<byte[]>("address can not be null");
			}
			ushort[] array = new ushort[address.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = 1;
			}
			return await ReadAsync(address, array);
		}

