		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.ReadSegment(System.String,System.Int32,System.Int32)" />
		public async Task<OResult<byte[]>> ReadSegmentAsync(string address, int startIndex, int length)
		{
			try
			{
				List<byte> bytesContent = new List<byte>();
				OResult<byte[], ushort, bool> oResult2;
				do
				{
					OResult<byte[]> oResult = await ReadCipFromServerAsync(AllenBradleyHelper.PackRequestReadSegment(address, startIndex, length)).ConfigureAwait(continueOnCapturedContext: false);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					oResult2 = AllenBradleyHelper.ExtractActualData(oResult.Content, isRead: true);
					if (!oResult2.IsSuccess)
					{
						return OResult.CreateFailedResult<byte[]>(oResult2);
					}
					startIndex += oResult2.Content1.Length;
					if (bytesContent.Count != 0 && oResult2.Content2 == 672 && oResult2.Content1.Length >= 2 && oResult2.Content1[0] == bytesContent[0] && oResult2.Content1[1] == bytesContent[1])
					{
						bytesContent.AddRange(oResult2.Content1.Skip(2));
					}
					else
					{
						bytesContent.AddRange(oResult2.Content1);
					}
					if (oResult2.Content2 == 672)
					{
						startIndex -= 2;
					}
				}
				while (oResult2.Content3);
				return OResult.CreateSuccessResult(bytesContent.ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("Address Wrong:" + ex.Message);
			}
		}

