		public override async Task<OResult<bool>> ReadBoolAsync(string address)
		{
			if (address.StartsWith("i="))
			{
				return ByteTransformHelper.GetResultFromArray(await ReadBoolAsync(address, 1).ConfigureAwait(continueOnCapturedContext: false));
			}
			OResult<byte[]> oResult = await ReadAsync(address, 1).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			return OResult.CreateSuccessResult(base.ByteTransform.TransBool(oResult.Content, 0));
		}

		/// <inheritdoc />
		public override async Task<OResult<bool[]>> ReadBoolAsync(string address, ushort length)
		{
			if (address.StartsWith("i="))
			{
				address = address.Substring(2);
				address = AllenBradleyHelper.AnalysisArrayIndex(address, out var bitIndex);
				OResult<int> boolValueTypeBitLength = GetBoolValueTypeBitLength(address);
				if (!boolValueTypeBitLength.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(boolValueTypeBitLength);
				}
				int dataBits = boolValueTypeBitLength.Content;
				string text = ((bitIndex / dataBits == 0) ? "" : $"[{bitIndex / dataBits}]");
				OResult<byte[]> oResult = await ReadAsync(length: (ushort)SnetHelper.CalculateOccupyLength(bitIndex, length, dataBits), address: address + text).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				return OResult.CreateSuccessResult(oResult.Content.ToBoolArray().SelectMiddle(bitIndex % dataBits, length));
			}
			OResult<byte[]> oResult2 = await ReadAsync(address, length).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult2);
			}
			return OResult.CreateSuccessResult(SoftBasic.ByteToBoolArray(oResult2.Content, length));
		}

