		/// <summary>
		/// 枚举当前的所有的变量名字，包含结构体信息，除去系统自带的名称数据信息<br />
		/// Enumerate all the current variable names, including structure information, except the name data information that comes with the system
		/// </summary>
		/// <returns>结果对象</returns>
		public OResult<AbTagItem[]> TagEnumerator()
		{
			List<AbTagItem> list = new List<AbTagItem>();
			for (int i = 0; i < 2; i++)
			{
				uint startInstance = 0u;
				OResult<byte[], ushort, bool> oResult2;
				do
				{
					OResult<byte[]> oResult = ReadCipFromServer((i == 0) ? AllenBradleyHelper.BuildEnumeratorCommand(startInstance) : AllenBradleyHelper.BuildEnumeratorProgrameMainCommand(startInstance));
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<AbTagItem[]>(oResult);
					}
					oResult2 = AllenBradleyHelper.ExtractActualData(oResult.Content, isRead: true);
					if (!oResult2.IsSuccess)
					{
						if (i == 1)
						{
							return OResult.CreateSuccessResult(list.ToArray());
						}
						return OResult.CreateFailedResult<AbTagItem[]>(oResult2);
					}
					if (oResult.Content.Length >= 43 && BitConverter.ToUInt16(oResult.Content, 40) == 213)
					{
						list.AddRange(AbTagItem.PraseAbTagItems(oResult.Content, 44, i == 0, out var instance));
						startInstance = instance + 1;
						continue;
					}
					return new OResult<AbTagItem[]>(StringResources.Language.UnknownError + " Source: " + oResult.Content.ToHexString(' '));
				}
				while (oResult2.Content3);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.TagEnumerator" />
		public async Task<OResult<AbTagItem[]>> TagEnumeratorAsync()
		{
			List<AbTagItem> lists = new List<AbTagItem>();
			for (int i = 0; i < 2; i++)
			{
				uint startInstance = 0u;
				OResult<byte[], ushort, bool> oResult2;
				do
				{
					OResult<byte[]> oResult = await ReadCipFromServerAsync((i == 0) ? AllenBradleyHelper.BuildEnumeratorCommand(startInstance) : AllenBradleyHelper.BuildEnumeratorProgrameMainCommand(startInstance));
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<AbTagItem[]>(oResult);
					}
					oResult2 = AllenBradleyHelper.ExtractActualData(oResult.Content, isRead: true);
					if (!oResult2.IsSuccess)
					{
						if (i == 1)
						{
							return OResult.CreateSuccessResult(lists.ToArray());
						}
						return OResult.CreateFailedResult<AbTagItem[]>(oResult2);
					}
					if (oResult.Content.Length >= 43 && BitConverter.ToUInt16(oResult.Content, 40) == 213)
					{
						lists.AddRange(AbTagItem.PraseAbTagItems(oResult.Content, 44, i == 0, out var instance));
						startInstance = instance + 1;
						continue;
					}
					return new OResult<AbTagItem[]>(StringResources.Language.UnknownError + " Source: " + oResult.Content.ToHexString(' '));
				}
				while (oResult2.Content3);
			}
			return OResult.CreateSuccessResult(lists.ToArray());
		}

		private OResult<AbStructHandle> ReadTagStructHandle(AbTagItem structTag)
		{
			OResult<byte[]> oResult = ReadCipFromServer(AllenBradleyHelper.GetStructHandleCommand(structTag.SymbolType));
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<AbStructHandle>(oResult);
			}
			if (oResult.Content.Length >= 43 && BitConverter.ToInt32(oResult.Content, 40) == 131)
			{
				return OResult.CreateSuccessResult(new AbStructHandle(oResult.Content, 44));
			}
			return new OResult<AbStructHandle>(StringResources.Language.UnknownError + " Source Data: " + oResult.Content.ToHexString(' '));
		}

		/// <summary>
		/// 枚举结构体的方法，传入结构体的标签对象，返回结构体子属性标签列表信息，子属性有可能是标量数据，也可能是另一个结构体。<br />
		/// The method of enumerating the structure, passing in the tag object of the structure, 
		/// and returning the tag list information of the sub-attributes of the structure. The sub-attributes may be scalar data or another structure.
		/// </summary>
		/// <param name="structTag">结构体的标签</param>
		/// <returns>是否成功</returns>
		public OResult<AbTagItem[]> StructTagEnumerator(AbTagItem structTag)
		{
			OResult<AbStructHandle> oResult = ReadTagStructHandle(structTag);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<AbTagItem[]>(oResult);
			}
			OResult<byte[]> oResult2 = ReadCipFromServer(AllenBradleyHelper.GetStructItemNameType(structTag.SymbolType, oResult.Content, 0));
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<AbTagItem[]>(oResult2);
			}
			if (oResult2.Content.Length >= 43 && oResult2.Content[40] == 204 && oResult2.Content[41] == 0 && oResult2.Content[42] == 0)
			{
				return OResult.CreateSuccessResult(AbTagItem.PraseAbTagItemsFromStruct(oResult2.Content, 44, oResult.Content).ToArray());
			}
			return new OResult<AbTagItem[]>(StringResources.Language.UnknownError + " Status:" + oResult2.Content[42]);
		}

