		/// <summary>
		/// 当前写入字节数组使用数据类型 0xD1 写入，如果其他的字节类型需要调用 <see cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.WriteTag(System.String,System.UInt16,System.Byte[],System.Int32)" /> 方法来实现。<br />
		/// The currently written byte array is written using the data type 0xD1. If other byte types need to be called <see cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.WriteTag(System.String,System.UInt16,System.Byte[],System.Int32)" /> Method to achieve. <br />
		/// </summary>
		/// <param name="address">地址</param>
		/// <param name="value">值</param>
		/// <returns>写入结果值</returns>
		public override OResult Write(string address, byte[] value)
		{
			return WriteTag(address, 209, value, (!SnetHelper.IsAddressEndWithIndex(address)) ? 1 : value.Length);
		}

		/// <summary>
		/// 使用指定的类型写入指定的节点数据，类型信息参考API文档，地址支持协议类型代号信息，例如 "type=0xD1;A"<br />
		/// Use the specified type to write the specified node data. For type information, refer to the API documentation. The address supports protocol type code information, such as "type=0xD1;A"
		/// </summary>
		/// <remarks>
		/// 关于参数 length 的含义，表示的是地址长度，一般的标量数据都是 1，如果PLC有个标签是 A，数据类型为 byte[10]，那我们写入 3 个byte就是 WriteTag( "A[5]", 0xD1, new byte[]{1,2,3}, 3 );<br />
		/// Regarding the meaning of the parameter length, it represents the address length. The general scalar data is 1. If the PLC has a tag of A and the data type is byte[10], then we write 3 bytes as WriteTag( "A[5 ]", 0xD1, new byte[]{1,2,3}, 3 );
		/// </remarks>
		/// <param name="address">节点的名称 -&gt; Name of the node </param>
		/// <param name="typeCode">类型代码，详细参见<see cref="T:Snet.Driver.Profinet.AllenBradley.AllenBradleyHelper" />上的常用字段 -&gt;  Type code, see the commonly used Fields section on the <see cref="T:Snet.Driver.Profinet.AllenBradley.AllenBradleyHelper" /> in detail</param>
		/// <param name="value">实际的数据值 -&gt; The actual data value </param>
		/// <param name="length">如果节点是数组，就是数组长度 -&gt; If the node is an array, it is the array length </param>
		/// <returns>是否写入成功 -&gt; Whether to write successfully</returns>
		public virtual OResult WriteTag(string address, ushort typeCode, byte[] value, int length = 1)
		{
			OResult<int> oResult = SnetHelper.ExtractParameterWithDefault(ref address, "type", typeCode);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			typeCode = (ushort)oResult.Content;
			OResult<List<byte[]>> oResult2 = BuildWriteCommand(address, typeCode, value, length);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			for (int i = 0; i < oResult2.Content.Count; i++)
			{
				OResult<byte[]> oResult3 = ReadFromCoreServer(oResult2.Content[i]);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				OResult oResult4 = CheckResponse(oResult3.Content);
				if (!oResult4.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult4);
				}
				OResult oResult5 = AllenBradleyHelper.ExtractActualData(oResult3.Content, isRead: false);
				if (!oResult5.IsSuccess)
				{
					return oResult5;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.Write(System.String,System.Byte[])" />
