			OResult<List<byte[]>> command = BuildWriteCommand(address, typeCode, value, length);
			if (!command.IsSuccess)
			{
				return command;
			}
			for (int i = 0; i < command.Content.Count; i++)
			{
				OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(command.Content[i]).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult oResult3 = CheckResponse(oResult2.Content);
