		/// <inheritdoc />
		public override OResult Write(string address, string value, Encoding encoding)
		{
			if (string.IsNullOrEmpty(value))
			{
				value = string.Empty;
			}
			ushort num = (ushort)SnetHelper.ExtractParameter(ref address, "type", 194);
			if (num == 218)
			{
				byte[] bytes = encoding.GetBytes(value);
				return WriteTag(address, num, SoftBasic.SpliceArray<byte>(new byte[1] { (byte)bytes.Length }, bytes));
			}
			byte[] bytes2 = encoding.GetBytes(value);
			OResult oResult = Write(address + ".LEN", bytes2.Length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (bytes2 != null && bytes2.Length != 0)
			{
				byte[] value2 = SoftBasic.ArrayExpandToLengthEven(bytes2);
				return WriteTag(address + ".DATA[0]", num, value2, bytes2.Length);
			}
			return oResult;
		}

		/// <summary>
		/// 写入单个Bool的数据信息。如果读取的是单bool变量，就直接写变量名，如果是bool数组的一个值，一律带下标访问，例如a[0]<br />
		/// Write the data information of a single Bool. If the read is a single bool variable, write the variable name directly, 
		/// if it is a value of the bool array, it will always be accessed with a subscript, such as a[0]
		/// </summary>
		/// <remarks>
		/// 如果写入的是类型代号 0xC1 的bool变量或是数组，直接使用标签名即可，比如：A,A[10]，如果写入的是类型代号0xD3的bool数组的值，则需要使用地址"i="开头，例如：i=A[10]<br />
		/// If you write a bool variable or array of type code 0xC1, you can use the tag name directly, such as: A,A[10], 
		/// if you write the value of a bool array of type code 0xD3, you need to use the address" i=" at the beginning, for example: i=A[10]
		/// </remarks>
		/// <param name="address">标签的地址数据</param>
		/// <param name="value">bool数据值</param>
		/// <returns>是否写入成功</returns>
		public override OResult Write(string address, bool value)
		{
			if (address.StartsWith("i=") && (Regex.IsMatch(address, "\\[[0-9]+\\]$") || Regex.IsMatch(address, "\\.[0-9]+$")))
			{
				OResult<byte[]> oResult = BuildWriteCommand(address.Substring(2), value);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				OResult oResult3 = CheckResponse(oResult2.Content);
				if (!oResult3.IsSuccess)
				{
					ClearBoolTypeCache(oResult3, address.Substring(2));
					return OResult.CreateFailedResult<byte[]>(oResult3);
				}
				return AllenBradleyHelper.ExtractActualData(oResult2.Content, isRead: false);
			}
			return WriteTag(address, 193, (!value) ? new byte[2] : new byte[2] { 255, 255 });
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Boolean[])" />
