		/// <summary>
		/// 获取写入数据的长度信息，此处直接返回数组的长度信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数组长度信息</param>
		/// <returns>实际的写入长度信息</returns>
		protected virtual int GetWriteValueLength(string address, int length)
		{
			return length;
		}

		private OResult<int> GetBoolValueTypeBitLength(string address)
		{
			lock (boolLock)
			{
				if (boolValueDataBits.ContainsKey(address))
				{
					return OResult.CreateSuccessResult(boolValueDataBits[address]);
				}
			}
			OResult<AbTagValue[]> oResult = ReadTags(new string[1] { address }, new ushort[1] { 1 });
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int>(oResult);
			}
			ushort type = oResult.Content[0].Type;
			lock (boolLock)
			{
				if (boolValueDataBits.ContainsKey(address))
				{
					return OResult.CreateSuccessResult(boolValueDataBits[address]);
				}
				int value = 32;
				switch (type)
				{
				case 194:
				case 198:
				case 209:
					value = 8;
					break;
				case 195:
				case 199:
				case 210:
					value = 16;
					break;
				case 196:
				case 200:
				case 211:
					value = 32;
					break;
				case 197:
				case 201:
				case 212:
					value = 64;
					break;
				}
				boolValueDataBits.Add(address, value);
				return OResult.CreateSuccessResult(value);
			}
		}

		private void ClearBoolTypeCache()
		{
			lock (boolLock)
			{
				boolValueDataBits.Clear();
			}
		}

		private void ClearBoolTypeCache(OResult check, string address)
		{
			if (check.IsSuccess || check.ErrorCode == 10000)
			{
				return;
			}
			lock (boolLock)
			{
				address = AllenBradleyHelper.AnalysisArrayIndex(address, out var _);
				if (boolValueDataBits.ContainsKey(address))
				{
					boolValueDataBits.Remove(address);
				}
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"AllenBradleyNet[{IpAddress}:{Port}]";
		}
	}
