	/// </summary>
	/// <remarks>
	/// <inheritdoc cref="T:Snet.Driver.Profinet.AllenBradley.AllenBradleySLCNet" path="remarks" />
	/// </remarks>
	/// <example>
	/// <inheritdoc cref="T:Snet.Driver.Profinet.AllenBradley.AllenBradleySLCNet" path="example" />
	/// </example>
	public class AllenBradleyPcccNet : NetworkConnectedCip
	{
		private SoftIncrementCount incrementCount = new SoftIncrementCount(65535L, 2L, 2);

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public AllenBradleyPcccNet()
		{
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 根据指定的IP及端口来实例化这个连接对象
		/// </summary>
		/// <param name="ipAddress">PLC的Ip地址</param>
