		public AllenBradleyPcccNet(string ipAddress, int port = 44818)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override byte[] GetLargeForwardOpen(ushort connectionID)
		{
			base.TOConnectionId = (uint)SnetHelper.SnetRandom.Next();
			byte[] array = "\r\n00 00 00 00 0a 00 02 00 00 00 00 00 b2 00 30 00\r\n54 02 20 06 24 01 0a 05 00 00 00 00 e8 a3 14 00\r\n27 04 09 10 0b 46 a5 c1 07 00 00 00 01 40 20 00\r\nf4 43 01 40 20 00 f4 43 a3 03 01 00 20 02 24 01".ToHexBytes();
			BitConverter.GetBytes((ushort)4105).CopyTo(array, 34);
			BitConverter.GetBytes(3248834059u).CopyTo(array, 36);
			BitConverter.GetBytes(base.TOConnectionId).CopyTo(array, 28);
			return array;
		}

		/// <inheritdoc />
		protected override byte[] GetLargeForwardClose()
		{
			return "\r\n00 00 00 00 0a 00 02 00 00 00 00 00 b2 00 18 00\r\n4e 02 20 06 24 01 0a 05 27 04 09 10 0b 46 a5 c1\r\n03 00 01 00 20 02 24 01".ToHexBytes();
		}

		/// <inheritdoc />
		/// <remarks>
		/// 读取PLC的原始数据信息，地址示例：N7:0
		/// </remarks>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = AllenBradleyHelper.PackExecutePCCCRead((int)incrementCount.GetCurrentValue(), address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(PackCommandService(oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = AllenBradleyHelper.CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			OResult<byte[], ushort, bool> oResult4 = NetworkConnectedCip.ExtractActualData(oResult2.Content, isRead: true);
			if (!oResult4.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult4);
			}
			return OResult.CreateSuccessResult(oResult4.Content1);
		}

		/// <inheritdoc />
