		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyPcccNet.Read(System.String,System.UInt16)" />
		public OResult<string> ReadString(string address)
		{
			return ReadString(address, 0, Encoding.ASCII);
		}

		/// <inheritdoc />
		/// <remarks>
		/// 读取PLC的地址信息，如果输入了 ST 的地址，例如 ST10:2, 当长度指定为 0 的时候，这时候就是动态的读取PLC来获取实际的字符串长度。<br />
		/// Read the PLC address information, if the ST address is entered, such as ST10:2, when the length is specified as 0, then the PLC is dynamically read to obtain the actual string length.
		/// </remarks>
		public override OResult<string> ReadString(string address, ushort length, Encoding encoding)
		{
			if (!string.IsNullOrEmpty(address) && address.StartsWith("ST"))
			{
				if (length <= 0)
				{
					OResult<byte[]> oResult = Read(address, 2);
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<string>(oResult);
					}
					int num = base.ByteTransform.TransUInt16(oResult.Content, 0);
					oResult = Read(address, (ushort)(2 + ((num % 2 != 0) ? (num + 1) : num)));
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<string>(oResult);
					}
					return OResult.CreateSuccessResult(encoding.GetString(SoftBasic.BytesReverseByWord(oResult.Content), 2, num));
				}
				OResult<byte[]> oResult2 = Read(address, (ushort)((length % 2 != 0) ? (length + 3) : (length + 2)));
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult2);
				}
				int num2 = base.ByteTransform.TransUInt16(oResult2.Content, 0);
				if (num2 + 2 > oResult2.Content.Length)
				{
					num2 = oResult2.Content.Length - 2;
				}
				return OResult.CreateSuccessResult(encoding.GetString(SoftBasic.BytesReverseByWord(oResult2.Content), 2, num2));
			}
			return base.ReadString(address, length, encoding);
		}

		/// <inheritdoc />
		public override OResult Write(string address, string value, Encoding encoding)
		{
			if (!string.IsNullOrEmpty(address) && address.StartsWith("ST"))
			{
				byte[] array = base.ByteTransform.TransByte(value, encoding);
				int value2 = array.Length;
				array = SoftBasic.ArrayExpandToLengthEven(array);
				return Write(address, SoftBasic.SpliceArray<byte>(new byte[2]
				{
					BitConverter.GetBytes(value2)[0],
					BitConverter.GetBytes(value2)[1]
				}, SoftBasic.BytesReverseByWord(array)));
			}
			return base.Write(address, value, encoding);
		}

