		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyPcccNet.ReadString(System.String,System.UInt16,System.Text.Encoding)" />
		public override async Task<OResult<string>> ReadStringAsync(string address, ushort length, Encoding encoding)
		{
			if (!string.IsNullOrEmpty(address) && address.StartsWith("ST"))
			{
				if (length <= 0)
				{
					OResult<byte[]> oResult = await ReadAsync(address, 2);
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<string>(oResult);
					}
					int len = base.ByteTransform.TransUInt16(oResult.Content, 0);
					oResult = await ReadAsync(address, (ushort)(2 + ((len % 2 != 0) ? (len + 1) : len)));
					if (!oResult.IsSuccess)
					{
						return OResult.CreateFailedResult<string>(oResult);
					}
					return OResult.CreateSuccessResult(encoding.GetString(SoftBasic.BytesReverseByWord(oResult.Content), 2, len));
				}
				OResult<byte[]> oResult2 = await ReadAsync(address, (ushort)((length % 2 != 0) ? (length + 3) : (length + 2)));
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<string>(oResult2);
				}
				int num = base.ByteTransform.TransUInt16(oResult2.Content, 0);
				if (num + 2 > oResult2.Content.Length)
				{
					num = oResult2.Content.Length - 2;
				}
				return OResult.CreateSuccessResult(encoding.GetString(SoftBasic.BytesReverseByWord(oResult2.Content), 2, num));
			}
			return base.ReadString(address, length, encoding);
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, string value, Encoding encoding)
		{
			if (!string.IsNullOrEmpty(address) && address.StartsWith("ST"))
			{
				byte[] array = base.ByteTransform.TransByte(value, encoding);
				int value2 = array.Length;
				array = SoftBasic.ArrayExpandToLengthEven(array);
				return await WriteAsync(address, SoftBasic.SpliceArray<byte>(new byte[2]
				{
					BitConverter.GetBytes(value2)[0],
					BitConverter.GetBytes(value2)[1]
				}, SoftBasic.BytesReverseByWord(array)));
			}
			return await base.WriteAsync(address, value, encoding);
		}

