	/// <summary>
	/// 虚拟的PCCC服务器，模拟的AB 1400通信
	/// </summary>
	public class AllenBradleyPcccServer : DeviceServer
	{
		private SoftBuffer aBuffer;

		private SoftBuffer bBuffer;

		private SoftBuffer nBuffer;

		private SoftBuffer fBuffer;

		private SoftBuffer sBuffer;

		private SoftBuffer iBuffer;

		private SoftBuffer oBuffer;

		private uint sessionID = 3305331106u;

		private const int DataPoolLength = 65536;

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public AllenBradleyPcccServer()
		{
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 2;
			aBuffer = new SoftBuffer(65536);
			bBuffer = new SoftBuffer(65536);
			nBuffer = new SoftBuffer(65536);
			fBuffer = new SoftBuffer(65536);
			sBuffer = new SoftBuffer(65536);
			iBuffer = new SoftBuffer(65536);
			oBuffer = new SoftBuffer(65536);
		}

		/// <inheritdoc />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<AllenBradleySLCAddress> oResult = AllenBradleySLCAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return oResult.Content.DataCode switch
			{
				142 => OResult.CreateSuccessResult(aBuffer.GetBytes(oResult.Content.AddressStart, length)), 
				133 => OResult.CreateSuccessResult(bBuffer.GetBytes(oResult.Content.AddressStart, length)), 
				137 => OResult.CreateSuccessResult(nBuffer.GetBytes(oResult.Content.AddressStart, length)), 
				138 => OResult.CreateSuccessResult(fBuffer.GetBytes(oResult.Content.AddressStart, length)), 
				132 => OResult.CreateSuccessResult(sBuffer.GetBytes(oResult.Content.AddressStart, length)), 
				131 => OResult.CreateSuccessResult(iBuffer.GetBytes(oResult.Content.AddressStart, length)), 
				130 => OResult.CreateSuccessResult(oBuffer.GetBytes(oResult.Content.AddressStart, length)), 
				_ => new OResult<byte[]>(StringResources.Language.NotSupportedDataType), 
			};
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<AllenBradleySLCAddress> oResult = AllenBradleySLCAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			switch (oResult.Content.DataCode)
			{
			case 142:
				aBuffer.SetBytes(value, oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			case 133:
				bBuffer.SetBytes(value, oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			case 137:
				nBuffer.SetBytes(value, oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			case 138:
				fBuffer.SetBytes(value, oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			case 132:
				sBuffer.SetBytes(value, oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			case 131:
				iBuffer.SetBytes(value, oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			case 130:
				oBuffer.SetBytes(value, oResult.Content.AddressStart);
				return OResult.CreateSuccessResult();
			default:
				return new OResult(StringResources.Language.NotSupportedDataType);
			}
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new AllenBradleyMessage();
		}

		/// <inheritdoc />
		protected override OResult ThreadPoolLoginAfterClientCheck(PipeSession session, IPEndPoint endPoint)
		{
			CommunicationPipe communication = session.Communication;
			AllenBradleyMessage netMessage = new AllenBradleyMessage();
			OResult<byte[]> oResult = communication.ReceiveMessage(netMessage, null, useActivePush: false, null, delegate(byte[] m)
			{
				LogRevcMessage(m, session);
			});
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			oResult.Content.SelectMiddle(12, 8).ToHexString();
			byte[] array = AllenBradleyHelper.PackRequestHeader(101, sessionID, new byte[4] { 1, 0, 0, 0 });
			LogSendMessage(array, session);
			OResult oResult2 = communication.Send(array);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = communication.ReceiveMessage(netMessage, null, useActivePush: false, null, delegate(byte[] m)
			{
				LogRevcMessage(m, session);
			});
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			byte[] array2 = AllenBradleyHelper.PackRequestHeader(111, sessionID, "00 00 00 00 00 04 02 00 00 00 00 00 b2 00 1e 00 d4 00 00 00 cc 31 59 a2 e8 a3 14 00 27 04 09 10 0b 46 a5 c1 01 40 20 00 01 40 20 00 00 00".ToHexBytes());
			LogSendMessage(array2, session);
			OResult oResult4 = communication.Send(array2);
			if (!oResult4.IsSuccess)
			{
				return oResult4;
			}
			return base.ThreadPoolLoginAfterClientCheck(session, endPoint);
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive.Length == 28 && receive[0] == 101)
			{
				return OResult.CreateSuccessResult(AllenBradleyHelper.PackRequestHeader(101, sessionID, new byte[4] { 1, 0, 0, 0 }));
			}
