		private int GetDynamicLengthData(byte[] fccc, ref int offset)
		{
			int num = fccc[offset++];
			if (num == 255)
			{
				num = BitConverter.ToUInt16(fccc, offset);
				offset += 2;
			}
			return num;
		}

		private byte[] ReadWriteCommand(byte[] fccc)
		{
			int length = fccc[5];
			int offset = 6;
			GetDynamicLengthData(fccc, ref offset);
			byte b = fccc[offset++];
			int dynamicLengthData = GetDynamicLengthData(fccc, ref offset);
			GetDynamicLengthData(fccc, ref offset);
			if (fccc[4] == 162)
			{
				return b switch
				{
					142 => GetResponse(0, aBuffer.GetBytes(dynamicLengthData, length)), 
					133 => GetResponse(0, bBuffer.GetBytes(dynamicLengthData, length)), 
					137 => GetResponse(0, nBuffer.GetBytes(dynamicLengthData, length)), 
					138 => GetResponse(0, fBuffer.GetBytes(dynamicLengthData, length)), 
					132 => GetResponse(0, sBuffer.GetBytes(dynamicLengthData, length)), 
					131 => GetResponse(0, iBuffer.GetBytes(dynamicLengthData, length)), 
					130 => GetResponse(0, oBuffer.GetBytes(dynamicLengthData, length)), 
					_ => GetResponse(1, null), 
				};
			}
			if (fccc[4] == 170)
			{
				byte[] data = fccc.RemoveBegin(offset);
				switch (b)
				{
				case 142:
					aBuffer.SetBytes(data, dynamicLengthData);
					return GetResponse(0, null);
				case 133:
					bBuffer.SetBytes(data, dynamicLengthData);
					return GetResponse(0, null);
				case 137:
					nBuffer.SetBytes(data, dynamicLengthData);
					return GetResponse(0, null);
				case 138:
					fBuffer.SetBytes(data, dynamicLengthData);
					return GetResponse(0, null);
				case 132:
					sBuffer.SetBytes(data, dynamicLengthData);
					return GetResponse(0, null);
				case 131:
					iBuffer.SetBytes(data, dynamicLengthData);
					return GetResponse(0, null);
				case 130:
					oBuffer.SetBytes(data, dynamicLengthData);
					return GetResponse(0, null);
				default:
					return GetResponse(1, null);
				}
			}
			if (fccc[4] == 171)
			{
				SoftBuffer softBuffer = null;
				switch (b)
				{
				case 142:
					softBuffer = aBuffer;
					break;
				case 133:
					softBuffer = bBuffer;
					break;
				case 137:
					softBuffer = nBuffer;
					break;
				case 138:
					softBuffer = fBuffer;
					break;
				case 132:
					softBuffer = sBuffer;
					break;
				case 131:
					softBuffer = iBuffer;
					break;
				case 130:
					softBuffer = oBuffer;
					break;
				default:
					return GetResponse(1, null);
				}
				int num = BitConverter.ToUInt16(fccc, offset);
				int num2 = BitConverter.ToUInt16(fccc, offset + 2);
				ushort value = (ushort)((softBuffer.GetUInt16(dynamicLengthData) & ~num) | num2);
				softBuffer.SetValue(value, dynamicLengthData);
				return GetResponse(0, null);
			}
			return GetResponse(1, null);
		}

