		/// <inheritdoc />
		protected override byte[] SaveToBytes()
		{
			XElement xElement = new XElement("Tags");
			foreach (KeyValuePair<string, AllenBradleyItemValue> abValue in abValues)
			{
				abValue.Value.Name = abValue.Key;
				xElement.Add(abValue.Value.ToXml());
			}
			return Encoding.UTF8.GetBytes(xElement.ToString());
		}

		/// <inheritdoc />
		protected override void LoadFromBytes(byte[] content)
		{
			abValues.Clear();
			foreach (XElement item in XElement.Parse(Encoding.UTF8.GetString(content)).Elements())
			{
				if (item.Name == "AllenBradleyItemValue")
				{
					AllenBradleyItemValue allenBradleyItemValue = new AllenBradleyItemValue(item);
					abValues.Add(allenBradleyItemValue.Name, allenBradleyItemValue);
				}
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"AllenBradleyServer[{base.Port}]";
		}
	}
	/// <summary>
	/// AllenBradley品牌的PLC，针对SLC系列的通信的实现，测试PLC为1747。<br />
	/// AllenBradley brand PLC, for the realization of SLC series communication, the test PLC is 1747.
	/// </summary>
	/// <remarks>
	/// 地址支持的举例：A9:0, N9:0, B9:0, F9:0, S:0, ST1:0, C9:0, I:0/10, O:0/1, R9:0, T9:0, L9:0
	/// </remarks>
	/// <example>
	/// 地址格式如下：
	/// <list type="table">
	///   <listheader>
	///     <term>地址代号</term>
	///     <term>字操作</term>
	///     <term>位操作</term>
	///     <term>备注</term>
	///   </listheader>
	///   <item>
	///     <term>A</term>
	///     <term>A9:0</term>
	///     <term>A9:0/1 或 A9:0.1</term>
	///     <term>ASCII</term>
	///   </item>
	///   <item>
	///     <term>B</term>
	///     <term>B9:0</term>
	///     <term>B9:0/1 或 B9:0.1</term>
	///     <term>Bit</term>
	///   </item>
	///   <item>
	///     <term>N</term>
	///     <term>N9:0</term>
	///     <term>N9:0/1 或 N9:0.1</term>
	///     <term>Integer</term>
	///   </item>
	///   <item>
	///     <term>F</term>
	///     <term>F9:0</term>
	///     <term>F9:0/1 或 F9:0.1</term>
	///     <term>Floating point</term>
	///   </item>
	///   <item>
	///     <term>S</term>
	///     <term>S:0</term>
	///     <term>S:0/1 或 S:0.1</term>
	///     <term>Status  S:0 等同于 S2:0</term>
	///   </item>
	///   <item>
	///     <term>ST</term>
	///     <term>ST1:0</term>
	///     <term></term>
	///     <term>String</term>
	///   </item>
	///   <item>
	///     <term>C</term>
	///     <term>C9:0</term>
	///     <term>C9:0/1 或 C9:0.1</term>
	///     <term>Counter</term>
	///   </item>
	///   <item>
	///     <term>I</term>
	///     <term>I:0</term>
	///     <term>I:0/1 或 I9:0.1</term>
	///     <term>Input</term>
	///   </item>
	///   <item>
	///     <term>O</term>
	///     <term>O:0</term>
	///     <term>O:0/1 或 O9:0.1</term>
	///     <term>Output</term>
	///   </item>
	///   <item>
	///     <term>R</term>
	///     <term>R9:0</term>
	///     <term>R9:0/1 或 R9:0.1</term>
	///     <term>Control</term>
	///   </item>
	///   <item>
	///     <term>T</term>
	///     <term>T9:0</term>
	///     <term>T9:0/1 或 T9:0.1</term>
	///     <term>Timer</term>
	///   </item>
	///   <item>
	///     <term>L</term>
	///     <term>L9:0</term>
	///     <term>L9:0/1 或 L9:0.1</term>
	///     <term>long integer</term>
	///   </item>
	/// </list>
	/// 感谢 seedee 的测试支持。
	/// </example>
	public class AllenBradleySLCNet : DeviceTcpNet
	{
		/// <summary>
		/// The current session handle, which is determined by the PLC when communicating with the PLC handshake
		/// </summary>
		public uint SessionHandle { get; protected set; }

		/// <summary>
		/// Instantiate a communication object for a Allenbradley PLC protocol
		/// </summary>
		public AllenBradleySLCNet()
		{
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// Instantiate a communication object for a Allenbradley PLC protocol
		/// </summary>
		/// <param name="ipAddress">PLC IpAddress</param>
		/// <param name="port">PLC Port</param>
		public AllenBradleySLCNet(string ipAddress, int port = 44818)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new AllenBradleySLCMessage();
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, "01 01 00 00 00 00 00 00 00 00 00 00 00 04 00 05 00 00 00 00 00 00 00 00 00 00 00 00".ToHexBytes(), hasResponseData: true, usePackAndUnpack: true);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content.Length >= 8)
			{
				SessionHandle = base.ByteTransform.TransUInt32(oResult.Content, 4);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(CommunicationPipe, "01 01 00 00 00 00 00 00 00 00 00 00 00 04 00 05 00 00 00 00 00 00 00 00 00 00 00 00".ToHexBytes(), hasResponseData: true, usePackAndUnpack: true).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content.Length >= 8)
			{
				SessionHandle = base.ByteTransform.TransUInt32(oResult.Content, 4);
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// Read data information, data length for read array length information
		/// </summary>
		/// <param name="address">Address format of the node</param>
		/// <param name="length">In the case of arrays, the length of the array </param>
		/// <returns>Result data with result object </returns>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(PackCommand(oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ExtraActualContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult(oResult3.Content);
		}

		/// <inheritdoc />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(PackCommand(oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ExtraActualContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult(oResult3.Content);
		}

		/// <inheritdoc />
		public override OResult<bool> ReadBool(string address)
		{
			address = AnalysisBitIndex(address, out var bitIndex);
			OResult<byte[]> oResult = Read(address, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			return OResult.CreateSuccessResult(oResult.Content.ToBoolArray()[bitIndex]);
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(PackCommand(oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ExtraActualContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult(oResult3.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleySLCNet.Read(System.String,System.UInt16)" />
		public override async Task<OResult<byte[]>> ReadAsync(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(PackCommand(oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ExtraActualContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult(oResult3.Content);
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(PackCommand(oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ExtraActualContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult(oResult3.Content);
		}

		/// <inheritdoc />
		public override async Task<OResult<bool>> ReadBoolAsync(string address)
		{
			address = AnalysisBitIndex(address, out var bitIndex);
			OResult<byte[]> oResult = await ReadAsync(address, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool>(oResult);
			}
			return OResult.CreateSuccessResult(oResult.Content.ToBoolArray()[bitIndex]);
		}

		/// <inheritdoc />
		public override async Task<OResult> WriteAsync(string address, bool value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(PackCommand(oResult.Content));
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = ExtraActualContent(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult(oResult3.Content);
		}

		private byte[] PackCommand(byte[] coreCmd)
		{
			byte[] array = new byte[28 + coreCmd.Length];
			array[0] = 1;
			array[1] = 7;
			array[2] = (byte)(coreCmd.Length / 256);
			array[3] = (byte)(coreCmd.Length % 256);
			BitConverter.GetBytes(SessionHandle).CopyTo(array, 4);
			coreCmd.CopyTo(array, 28);
			return array;
		}

		/// <summary>
		/// 分析地址数据信息里的位索引的信息
		/// </summary>
		/// <param name="address">数据地址</param>
		/// <param name="bitIndex">位索引</param>
		/// <returns>地址信息</returns>
		public static string AnalysisBitIndex(string address, out int bitIndex)
		{
			bitIndex = 0;
			int num = address.IndexOf('/');
			if (num < 0)
			{
				num = address.IndexOf('.');
			}
			if (num > 0)
			{
				bitIndex = int.Parse(address.Substring(num + 1));
				address = address.Substring(0, num);
			}
			return address;
		}

		/// <summary>
		/// 构建读取的指令信息
		/// </summary>
		/// <param name="address">地址信息，举例：A9:0</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>是否成功</returns>
		public static OResult<byte[]> BuildReadCommand(string address, int length)
		{
			OResult<AllenBradleySLCAddress> oResult = AllenBradleySLCAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (length < 2)
			{
				length = 2;
			}
			if (oResult.Content.DataCode == 142)
			{
				oResult.Content.AddressStart /= 2;
			}
			byte[] obj = new byte[14]
			{
				0, 5, 0, 0, 15, 0, 0, 1, 162, 0,
				0, 0, 0, 0
			};
			obj[9] = (byte)length;
			obj[10] = (byte)oResult.Content.DbBlock;
			obj[11] = oResult.Content.DataCode;
			byte[] array = obj;
			BitConverter.GetBytes((ushort)oResult.Content.AddressStart).CopyTo(array, 12);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建写入的报文内容，变成实际的数据
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="value">数据值</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, byte[] value)
		{
			OResult<AllenBradleySLCAddress> oResult = AllenBradleySLCAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content.DataCode == 142)
			{
				oResult.Content.AddressStart /= 2;
			}
			byte[] array = new byte[18 + value.Length];
			array[0] = 0;
			array[1] = 5;
			array[2] = 0;
			array[3] = 0;
			array[4] = 15;
			array[5] = 0;
			array[6] = 0;
			array[7] = 1;
			array[8] = 171;
			array[9] = byte.MaxValue;
			array[10] = BitConverter.GetBytes(value.Length)[0];
			array[11] = BitConverter.GetBytes(value.Length)[1];
			array[12] = (byte)oResult.Content.DbBlock;
			array[13] = oResult.Content.DataCode;
			BitConverter.GetBytes((ushort)oResult.Content.AddressStart).CopyTo(array, 14);
			array[16] = byte.MaxValue;
			array[17] = byte.MaxValue;
			value.CopyTo(array, 18);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建写入的报文内容，变成实际的数据
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="value">数据值</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<byte[]> BuildWriteCommand(string address, bool value)
		{
			address = AnalysisBitIndex(address, out var bitIndex);
			OResult<AllenBradleySLCAddress> oResult = AllenBradleySLCAddress.ParseFrom(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (oResult.Content.DataCode == 142)
			{
				oResult.Content.AddressStart /= 2;
			}
			int value2 = 1 << bitIndex;
			byte[] obj = new byte[20]
			{
				0, 5, 0, 0, 15, 0, 0, 1, 171, 255,
				2, 0, 0, 0, 0, 0, 0, 0, 0, 0
			};
			obj[12] = (byte)oResult.Content.DbBlock;
			obj[13] = oResult.Content.DataCode;
			byte[] array = obj;
			BitConverter.GetBytes((ushort)oResult.Content.AddressStart).CopyTo(array, 14);
			array[16] = BitConverter.GetBytes(value2)[0];
			array[17] = BitConverter.GetBytes(value2)[1];
			if (value)
			{
				array[18] = BitConverter.GetBytes(value2)[0];
				array[19] = BitConverter.GetBytes(value2)[1];
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 解析当前的实际报文内容，变成数据内容
		/// </summary>
		/// <param name="content">报文内容</param>
		/// <returns>是否成功</returns>
		public static OResult<byte[]> ExtraActualContent(byte[] content)
		{
			if (content.Length < 36)
			{
				return new OResult<byte[]>(StringResources.Language.ReceiveDataLengthTooShort + content.ToHexString(' '));
			}
			return OResult.CreateSuccessResult(content.RemoveBegin(36));
		}
	}
	internal class CipSessionTag
	{
		public bool IsConnectedCIP { get; set; }

		public byte[] TOConnectID { get; set; } = new byte[4];
	}
	/// <summary>
	/// CIP协议的基础接口信息
	/// </summary>
	public interface IReadWriteCip : IReadWriteNet
	{
		/// <summary>
		/// 使用指定的类型写入指定的节点数据，类型信息参考API文档，地址支持携带类型代号信息，可以强制指定本次写入数据的类型信息，例如 "type=0xD1;A"<br />
		/// Use the specified type to write the specified node data. For the type information, refer to the API documentation. The address supports carrying type code information. 
		/// You can force the type information of the data to be written this time. For example, "type=0xD1;A"
		/// </summary>
		/// <remarks>
		/// 关于参数 length 的含义，表示的是地址长度，一般的标量数据都是 1，如果PLC有个标签是 A，数据类型为 byte[10]，那我们写入 3 个byte就是 WriteTag( "A[5]", 0xD1, new byte[]{1,2,3}, 3 );<br />
		/// Regarding the meaning of the parameter length, it represents the address length. The general scalar data is 1. If the PLC has a tag of A and the data type is byte[10], then we write 3 bytes as WriteTag( "A[5 ]", 0xD1, new byte[]{1,2,3}, 3 );
		/// </remarks>
		/// <param name="address">节点的名称 -&gt; Name of the node </param>
		/// <param name="typeCode">类型代码，详细参见<see cref="T:Snet.Driver.Profinet.AllenBradley.AllenBradleyHelper" />上的常用字段 -&gt;  Type code, see the commonly used Fields section on the <see cref="T:Snet.Driver.Profinet.AllenBradley.AllenBradleyHelper" /> in detail</param>
		/// <param name="value">实际的数据值 -&gt; The actual data value </param>
		/// <param name="length">如果节点是数组，就是数组长度 -&gt; If the node is an array, it is the array length </param>
		/// <returns>是否写入成功 -&gt; Whether to write successfully</returns>
		OResult WriteTag(string address, ushort typeCode, byte[] value, int length = 1);

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.ReadTag(System.String,System.UInt16)" />
		OResult<ushort, byte[]> ReadTag(string address, ushort length = 1);

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyHelper.ReadPlcType(Snet.Driver.Core.IReadWriteDevice)" />
		OResult<string> ReadPlcType();

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.IReadWriteCip.WriteTag(System.String,System.UInt16,System.Byte[],System.Int32)" />
		Task<OResult> WriteTagAsync(string address, ushort typeCode, byte[] value, int length = 1);

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyHelper.ReadDate(Snet.Driver.Profinet.AllenBradley.IReadWriteCip,System.String)" />
		OResult<DateTime> ReadDate(string address);

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.AllenBradleyHelper.WriteDate(Snet.Driver.Profinet.AllenBradley.IReadWriteCip,System.String,System.DateTime)" />
		OResult WriteDate(string address, DateTime date);

		/// <inheritdoc cref="M:Snet.Driver.Profinet.AllenBradley.IReadWriteCip.WriteDate(System.String,System.DateTime)" />
