	/// <summary>
	/// Modbus设备的接口，用来表示Modbus相关的设备对象，<see cref="T:Snet.Driver.ModBus.ModbusTcpNet" />, <see cref="T:Snet.Driver.ModBus.ModbusRtu" />,
	/// <see cref="T:Snet.Driver.ModBus.ModbusAscii" />,<see cref="T:Snet.Driver.ModBus.ModbusRtuOverTcp" />,<see cref="T:Snet.Driver.ModBus.ModbusUdpNet" />均实现了该接口信息<br />
	/// Modbus device interface, used to represent Modbus-related device objects, <see cref="T:Snet.Driver.ModBus.ModbusTcpNet" />, 
	/// <see cref="T:Snet.Driver.ModBus.ModbusRtu" />,<see cref="T:Snet.Driver.ModBus.ModbusAscii" />,<see cref="T:Snet.Driver.ModBus.ModbusRtuOverTcp" />,<see cref="T:Snet.Driver.ModBus.ModbusUdpNet" /> all implement the interface information
	/// </summary>
	public interface IModbus : IReadWriteDevice, IReadWriteNet
	{
		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.AddressStartWithZero" />
		bool AddressStartWithZero { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.Station" />
		byte Station { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.DataFormat" />
		DataFormat DataFormat { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.IsStringReverse" />
		bool IsStringReverse { get; set; }

		/// <summary>
		/// 获取或是设置当前广播模式对应的站号，广播模式意味着不接收设备方的数据返回操作，默认为 -1，表示不使用广播模式。<br />
		/// Gets or sets the station number corresponding to the current broadcast mode. Broadcast mode means that the data return operation of the device is not received. The default value is -1, indicating that broadcast mode is not used.
		/// </summary>
		int BroadcastStation { get; set; }

		/// <summary>
		/// 获取或设置当前掩码写入的功能码是否激活状态，设置为 false 时，再执行写入位时，会通过读字，修改位，写字的方式来间接实现。<br />
		/// When the function code is set to false, and then the write bit is executed, it will be indirectly implemented by reading, modifying the bit, and writing the word.
		/// </summary>
		bool EnableWriteMaskCode { get; set; }

		/// <summary>
		/// 当进行字读取的时候，商业授权用户支持分批读取，本属性表示分批的长度信息，默认为 120，可以根据实际情况来设置其他值。<br />
		/// When reading of word type, commercial authorization users support batch reading. This attribute represents the length information of the batch, with a default of 120. Other values can be set according to the actual situation.
		/// </summary>
		int WordReadBatchLength { get; set; }

		/// <summary>
		/// 获取或设置是否禁用功能码05的写入操作，设置为true时，表示不允许使用功能码 06 进行写入操作。写入单个的字数据也使用 0x10 功能码<br />
		/// Get or set whether to disable the write operation of function code 06. When set to true, it indicates that the write operation of function code 05 is not allowed. Writing individual character data also uses the 0x10 function code
		/// </summary>
		bool DisableFunctionCode06 { get; set; }

		/// <summary>
		/// 将当前的地址信息转换成Modbus格式的地址，如果转换失败，返回失败的消息。默认不进行任何的转换。<br />
		/// Convert the current address information into a Modbus format address. If the conversion fails, a failure message will be returned. No conversion is performed by default.
		/// </summary>
		/// <param name="address">传入的地址</param>
		/// <param name="modbusCode">Modbus的功能码</param>
		/// <returns>转换之后Modbus的地址</returns>
		OResult<string> TranslateToModbusAddress(string address, byte modbusCode);

		/// <summary>
		/// 注册一个新的地址映射关系，注册地址映射关系后，就可以使用新的地址来读写Modbus数据了，通常用于其他的支持Modbus协议的PLC。<br />
		/// After registering a new address mapping, you can use the new address to read and write Modbus data, which is usually used for other PLCs that support the Modbus protocol.
		/// </summary>
		/// <param name="mapping">地址映射关系信息</param>
		void RegisteredAddressMapping(Func<string, byte, OResult<string>> mapping);

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusHelper.ReadWrite(Snet.Driver.ModBus.IModbus,System.String,System.UInt16,System.String,System.Byte[])" />
		OResult<byte[]> ReadWrite(string readAddress, ushort length, string writeAddress, byte[] value);

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusHelper.ReadFile(Snet.Driver.ModBus.IModbus,System.Byte,System.UInt16,System.UInt16,System.UInt16)" />
		OResult<byte[]> ReadFile(ushort fileNumber, ushort address, ushort length);

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusHelper.WriteFile(Snet.Driver.ModBus.IModbus,System.Byte,System.UInt16,System.UInt16,System.Byte[])" />
		OResult WriteFile(ushort fileNumber, ushort address, byte[] data);
	}
