	/// <summary>
	/// Modbus协议相关辅助类，关于Modbus消息的组装以及拆分<br />
	/// Modbus protocol related auxiliary classes, about the assembly and splitting of Modbus messages
	/// </summary>
	internal class ModbusHelper
	{
		public static OResult<byte[]> ExtraRtuResponseContent(byte[] send, byte[] response, bool crcCheck = true, int broadcastStation = -1)
		{
			if (broadcastStation >= 0 && send[0] == broadcastStation)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (response == null || response.Length < 5)
			{
				return new OResult<byte[]>(StringResources.Language.ReceiveDataLengthTooShort + "5 Content: " + response.ToHexString(' '));
			}
			byte[] array = response.ToArray();
			int num = 0;
			if (send != null && send.Length >= 6 && (send[1] == 3 || send[1] == 4))
			{
				num = (send[4] * 256 + send[5]) * 2 + 5;
				if (response.Length > num + 1)
				{
					int num2 = response.Length - num;
					for (int i = 0; i <= num2; i++)
					{
						if (((response[i] == send[0] && response[i + 1] == send[1] && response[i + 2] == (byte)((send[4] * 256 + send[5]) * 2)) & crcCheck) && SoftCRC16.CheckCRC16(response.SelectMiddle(i, num)))
						{
							array = response.SelectMiddle(i, num);
							break;
						}
					}
				}
			}
			for (int j = 0; j < 2; j++)
			{
				if (array[1] == 1 || array[1] == 2 || array[1] == 3 || array[1] == 4 || array[1] == 23)
				{
					if (array.Length > 5 + array[2])
					{
						array = array.SelectBegin(5 + array[2]);
					}
				}
				else if (array[1] == 5 || array[1] == 6 || array[1] == 15 || array[1] == 16)
				{
					if (array.Length > 8)
					{
						array = array.SelectBegin(8);
					}
				}
				else if (array[1] > 128 && array.Length > 5)
				{
					array = array.SelectBegin(5);
				}
				if (!crcCheck || SoftCRC16.CheckCRC16(array))
				{
					break;
				}
				if (j == 0)
				{
					array = response.RemoveBegin(1);
					continue;
				}
				return new OResult<byte[]>(int.MinValue, StringResources.Language.ModbusCRCCheckFailed + SoftBasic.ByteToHexString(response, ' '));
			}
			if (send[0] != array[0])
			{
				return new OResult<byte[]>($"Station not match, request: {send[0]}, but response is {array[0]}");
			}
			if (send[1] + 128 == array[1])
			{
				return new OResult<byte[]>(array[2], ModbusInfo.GetDescriptionByErrorCode(array[2]));
			}
			if (send[1] != array[1])
			{
				return new OResult<byte[]>(array[1], "Receive Command Check Failed: ");
			}
			return ModbusInfo.ExtractActualData(ModbusInfo.ExplodeRtuCommandToCore(array));
		}

		public static OResult<byte[]> ExtraAsciiResponseContent(byte[] send, byte[] response, int broadcastStation = -1)
		{
			if (broadcastStation >= 0)
			{
				try
				{
					if (Convert.ToInt32(Encoding.ASCII.GetString(send, 1, 2), 16) == broadcastStation)
					{
						return OResult.CreateSuccessResult(new byte[0]);
					}
				}
				catch
				{
				}
			}
			OResult<byte[]> oResult = ModbusInfo.TransAsciiPackCommandToCore(response);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content.Length < 3)
			{
				return new OResult<byte[]>(StringResources.Language.ReceiveDataLengthTooShort + " 3, Content: " + oResult.Content.ToHexString(' '));
			}
			if (send[1] + 128 == oResult.Content[1])
			{
				return new OResult<byte[]>(oResult.Content[2], ModbusInfo.GetDescriptionByErrorCode(oResult.Content[2]));
			}
			return ModbusInfo.ExtractActualData(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusTcpNet.Read(System.String,System.UInt16)" />
		public static OResult<byte[]> Read(IModbus modbus, string address, ushort length)
		{
			if (CheckFileAddress(address))
			{
				int num = SnetHelper.ExtractParameter(ref address, "file", 0);
				int num2 = SnetHelper.ExtractParameter(ref address, "s", modbus.Station);
				return ReadFile(modbus, (byte)num2, (ushort)num, ushort.Parse(address), length);
			}
			OResult<string> oResult = modbus.TranslateToModbusAddress(address, 3);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			OResult<byte[][]> oResult2 = ModbusInfo.BuildReadModbusCommand(modbus, oResult.Content, length, 3);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return modbus.ReadFromCoreServer(oResult2.Content);
		}

		private static OResult<byte[]> CreateReadFileResult(OResult<byte[]> read)
		{
			if (!read.IsSuccess)
			{
				return read;
			}
			if (read.Content.Length < 2)
			{
				return new OResult<byte[]>(StringResources.Language.ReceiveDataLengthTooShort + "2");
			}
			MemoryStream memoryStream = new MemoryStream();
			int num;
			for (int i = 0; i < read.Content.Length; i += num + 1)
			{
				num = read.Content[i];
				memoryStream.Write(read.Content.SelectMiddle(i + 2, num - 1));
			}
			return OResult.CreateSuccessResult(memoryStream.ToArray());
		}

		private static bool CheckFileAddress(string address)
		{
			return Regex.IsMatch(address, "file=", RegexOptions.IgnoreCase);
		}

		/// <summary>
