		public static OResult<bool[]> ReadBoolHelper(IModbus modbus, string address, ushort length, byte function)
		{
			OResult<string> oResult = modbus.TranslateToModbusAddress(address, function);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<bool[]>();
			}
			if (oResult.Content.IndexOf('.') > 0)
			{
				string[] array = address.SplitDot();
				int num = 0;
				try
				{
					num = Convert.ToInt32(oResult.Content.SplitDot()[1]);
				}
				catch (Exception ex)
				{
					return new OResult<bool[]>("Bit Index format wrong, " + ex.Message);
				}
				ushort length2 = (ushort)((length + num + 15) / 16);
				OResult<byte[]> oResult2 = modbus.Read(array[0], length2);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				if (modbus.DataFormat == DataFormat.ABCD || modbus.DataFormat == DataFormat.CDAB)
				{
					return OResult.CreateSuccessResult(SoftBasic.BytesReverseByWord(oResult2.Content).ToBoolArray().SelectMiddle(num, length));
				}
				return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectMiddle(num, length));
			}
			OResult<byte[][]> oResult3 = ModbusInfo.BuildReadModbusCommand(oResult.Content, length, modbus.Station, modbus.AddressStartWithZero, function);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult3);
			}
			List<bool> list = new List<bool>();
			for (int i = 0; i < oResult3.Content.Length; i++)
			{
				OResult<byte[]> oResult4 = modbus.ReadFromCoreServer(oResult3.Content[i]);
				if (!oResult4.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult4);
				}
				int length3 = oResult3.Content[i][4] * 256 + oResult3.Content[i][5];
				list.AddRange(SoftBasic.ByteToBoolArray(oResult4.Content, length3));
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		internal static async Task<OResult<bool[]>> ReadBoolHelperAsync(IModbus modbus, string address, ushort length, byte function)
		{
			OResult<string> oResult = modbus.TranslateToModbusAddress(address, function);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<bool[]>();
			}
			if (oResult.Content.IndexOf('.') > 0)
			{
				string[] array = address.SplitDot();
				int bitIndex;
				try
				{
					string[] array2 = oResult.Content.SplitDot();
					bitIndex = Convert.ToInt32(array2[1]);
				}
				catch (Exception ex)
				{
					return new OResult<bool[]>("Bit Index format wrong, " + ex.Message);
				}
				OResult<byte[]> oResult2 = await modbus.ReadAsync(length: (ushort)((length + bitIndex + 15) / 16), address: array[0]).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult2);
				}
				if (modbus.DataFormat == DataFormat.ABCD || modbus.DataFormat == DataFormat.CDAB)
				{
					return OResult.CreateSuccessResult(SoftBasic.BytesReverseByWord(oResult2.Content).ToBoolArray().SelectMiddle(bitIndex, length));
				}
				return OResult.CreateSuccessResult(oResult2.Content.ToBoolArray().SelectMiddle(bitIndex, length));
			}
			OResult<byte[][]> command = ModbusInfo.BuildReadModbusCommand(oResult.Content, length, modbus.Station, modbus.AddressStartWithZero, function);
			if (!command.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(command);
			}
			List<bool> resultArray = new List<bool>();
			for (int bitIndex = 0; bitIndex < command.Content.Length; bitIndex++)
			{
				OResult<byte[]> oResult3 = await modbus.ReadFromCoreServerAsync(command.Content[bitIndex]).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult3);
				}
				resultArray.AddRange(SoftBasic.ByteToBoolArray(length: command.Content[bitIndex][4] * 256 + command.Content[bitIndex][5], inBytes: oResult3.Content));
			}
			return OResult.CreateSuccessResult(resultArray.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusTcpNet.Write(System.String,System.Boolean[])" />
		public static OResult Write(IModbus modbus, string address, bool[] values)
		{
			OResult<string> oResult = modbus.TranslateToModbusAddress(address, 15);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (oResult.Content.IndexOf('.') > 0)
			{
				bool reverseWord = true;
				if (modbus.DataFormat == DataFormat.BADC || modbus.DataFormat == DataFormat.DCBA)
				{
					reverseWord = false;
				}
				return ReadWriteNetHelper.WriteBoolWithWord(modbus, address, values, 16, reverseWord, oResult.Content.SplitDot()[1]);
			}
			OResult<byte[]> oResult2 = ModbusInfo.BuildWriteBoolModbusCommand(oResult.Content, values, modbus.Station, modbus.AddressStartWithZero, 15);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return modbus.ReadFromCoreServer(oResult2.Content);
		}

