		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusTcpNet.Write(System.String,System.Boolean)" />
		public static OResult Write(IModbus modbus, string address, bool value)
		{
			OResult<string> oResult = modbus.TranslateToModbusAddress(address, 5);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (address.IndexOf('.') > 0 && !modbus.EnableWriteMaskCode)
			{
				return Write(modbus, address, new bool[1] { value });
			}
			OResult<byte[]> oResult2 = ModbusInfo.BuildWriteBoolModbusCommand(modbus.DataFormat, oResult.Content, value, modbus.Station, modbus.AddressStartWithZero, 5);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = modbus.ReadFromCoreServer(oResult2.Content);
			if (oResult3.IsSuccess)
			{
				return oResult3;
			}
			if (address.IndexOf('.') > 0 && oResult3.ErrorCode == 1)
			{
				modbus.EnableWriteMaskCode = false;
				return Write(modbus, address, new bool[1] { value });
			}
			return oResult3;
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusHelper.Write(Snet.Driver.ModBus.IModbus,System.String,System.Boolean)" />
		public static async Task<OResult> WriteAsync(IModbus modbus, string address, bool value)
		{
			OResult<string> oResult = modbus.TranslateToModbusAddress(address, 5);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			if (address.IndexOf('.') > 0 && !modbus.EnableWriteMaskCode)
			{
				return await WriteAsync(modbus, address, new bool[1] { value }).ConfigureAwait(continueOnCapturedContext: false);
			}
			OResult<byte[]> oResult2 = ModbusInfo.BuildWriteBoolModbusCommand(modbus.DataFormat, oResult.Content, value, modbus.Station, modbus.AddressStartWithZero, 5);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = await modbus.ReadFromCoreServerAsync(oResult2.Content).ConfigureAwait(continueOnCapturedContext: false);
			if (oResult3.IsSuccess)
			{
				return oResult3;
			}
			if (address.IndexOf('.') > 0 && oResult3.ErrorCode == 1)
			{
				modbus.EnableWriteMaskCode = false;
				return await WriteAsync(modbus, address, new bool[1] { value }).ConfigureAwait(continueOnCapturedContext: false);
			}
			return oResult3;
		}

		public static bool TransAddressToModbus(string station, string address, string[] code, int[] offset, Func<string, int> prase, out string newAddress)
		{
			newAddress = string.Empty;
			for (int i = 0; i < code.Length; i++)
			{
				if (address.StartsWithAndNumber(code[i]))
				{
					newAddress = station + (prase(address.Substring(code[i].Length)) + offset[i]);
					return true;
				}
			}
			return false;
		}

		public static bool TransAddressToModbus(string station, string address, string[] code, int[] offset, out string newAddress)
		{
			return TransAddressToModbus(station, address, code, offset, int.Parse, out newAddress);
		}

		public static bool TransPointAddressToModbus(string station, string address, string[] code, int[] offset, Func<string, int> prase, out string newAddress)
		{
			newAddress = string.Empty;
			int num = address.IndexOf('.');
			if (num > 0)
			{
				string text = address.Substring(num);
				address = address.Substring(0, num);
				if (TransAddressToModbus(station, address, code, offset, prase, out newAddress))
				{
					newAddress += text;
					return true;
				}
			}
			return false;
		}

		/// <summary>
		/// 针对带有小数点的地址进行转换，例如 D100.0 转成 100.0 
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">地址</param>
		/// <param name="code">地址类型</param>
		/// <param name="offset">起始偏移地址</param>
		/// <param name="newAddress">返回的新的地址</param>
		/// <returns>是否匹配当前的地址类型</returns>
		public static bool TransPointAddressToModbus(string station, string address, string[] code, int[] offset, out string newAddress)
		{
			return TransPointAddressToModbus(station, address, code, offset, int.Parse, out newAddress);
		}
	}
	/// <summary>
	/// Modbus协议相关的一些信息，包括功能码定义，报文的生成的定义等等信息<br />
	/// Some information related to Modbus protocol, including function code definition, definition of message generation, etc.
	/// </summary>
	public class ModbusInfo
	{
		/// <summary>
		/// 读取线圈
		/// </summary>
		public const byte ReadCoil = 1;

		/// <summary>
		/// 读取离散量
		/// </summary>
		public const byte ReadDiscrete = 2;

		/// <summary>
		/// 读取寄存器
		/// </summary>
		public const byte ReadRegister = 3;

		/// <summary>
		/// 读取输入寄存器
		/// </summary>
		public const byte ReadInputRegister = 4;

		/// <summary>
		/// 写单个线圈
		/// </summary>
		public const byte WriteOneCoil = 5;

		/// <summary>
		/// 写单个寄存器
		/// </summary>
		public const byte WriteOneRegister = 6;

		/// <summary>
		/// 写多个线圈
		/// </summary>
		public const byte WriteCoil = 15;

		/// <summary>
		/// 写多个寄存器
		/// </summary>
		public const byte WriteRegister = 16;

		/// <summary>
		/// 读取文件记录
		/// </summary>
		public const byte ReadFileRecord = 20;

		/// <summary>
		/// 写入文件记录
		/// </summary>
		public const byte WriteFileRecord = 21;

		/// <summary>
		/// 使用掩码的方式写入寄存器
		/// </summary>
		public const byte WriteMaskRegister = 22;

		/// <summary>
		/// 读写同时的功能码，只有极个别的设备可能会支持的功能码
		/// </summary>
		public const byte ReadWrite = 23;

		/// <summary>
		/// 不支持该功能码
		/// </summary>
		public const byte FunctionCodeNotSupport = 1;

		/// <summary>
		/// 该地址越界
		/// </summary>
		public const byte FunctionCodeOverBound = 2;

		/// <summary>
		/// 读取长度超过最大值
		/// </summary>
		public const byte FunctionCodeQuantityOver = 3;

		/// <summary>
		/// 读写异常
		/// </summary>
		public const byte FunctionCodeReadWriteException = 4;

		private static void CheckModbusAddressStart(ModbusAddress mAddress, bool isStartWithZero)
		{
			if (!isStartWithZero)
			{
				if (mAddress.AddressStart < 1)
				{
					throw new Exception(StringResources.Language.ModbusAddressMustMoreThanOne);
				}
				mAddress.AddressStart--;
			}
			if (mAddress.AddressStart >= 65536)
			{
				throw new Exception(StringResources.Language.ModbusAddressMustLessThan65536);
			}
		}

		/// <summary>
		/// 构建Modbus读取数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码应该根据bool或是字来区分<br />
		/// To construct the core message of Modbus reading data, you need to specify the address, length, station number, 
		/// whether the starting address is 0, and the default function code should be distinguished according to bool or word
		/// </summary>
		/// <param name="address">Modbus的富文本地址</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="station">默认的站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[][]> BuildReadModbusCommand(string address, int length, byte station, bool isStartWithZero, byte defaultFunction)
		{
			try
			{
				ModbusAddress mAddress = new ModbusAddress(address, station, defaultFunction);
				CheckModbusAddressStart(mAddress, isStartWithZero);
				return BuildReadModbusCommand(mAddress, length, 120);
			}
			catch (Exception ex)
			{
				return new OResult<byte[][]>(ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusInfo.BuildReadModbusCommand(System.String,System.Int32,System.Byte,System.Boolean,System.Byte)" />
		public static OResult<byte[][]> BuildReadModbusCommand(IModbus modbus, string address, int length, byte defaultFunction)
		{
			try
			{
				ModbusAddress mAddress = new ModbusAddress(address, modbus.Station, defaultFunction);
				CheckModbusAddressStart(mAddress, modbus.AddressStartWithZero);
				return BuildReadModbusCommand(mAddress, length, modbus.WordReadBatchLength);
			}
			catch (Exception ex)
			{
				return new OResult<byte[][]>(ex.Message);
			}
		}

		internal static OResult<byte[][]> BuildReadFileModbusCommand(ushort fileNumber, ushort address, ushort length, byte station, bool addressStartWithZero)
		{
			OResult<int[], int[]> oResult = SnetHelper.SplitReadLength(address, length, 124);
			List<byte[]> list = new List<byte[]>();
			for (int i = 0; i < oResult.Content1.Length; i++)
			{
				byte[] array = new byte[10];
				array[0] = station;
				array[1] = 20;
				array[2] = (byte)(array.Length - 3);
				array[3] = 6;
				array[4] = BitConverter.GetBytes(fileNumber)[1];
				array[5] = BitConverter.GetBytes(fileNumber)[0];
				array[6] = BitConverter.GetBytes(oResult.Content1[i])[1];
				array[7] = BitConverter.GetBytes(oResult.Content1[i])[0];
				array[8] = BitConverter.GetBytes(oResult.Content2[i])[1];
				array[9] = BitConverter.GetBytes(oResult.Content2[i])[0];
				list.Add(array);
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		internal static OResult<byte[]> BuildWriteFileModbusCommand(ushort fileNumber, ushort address, byte[] data, byte station, bool addressStartWithZero)
		{
			if (data.Length + 7 > 255)
			{
				return new OResult<byte[]>("the data length must less than 248 bytes( 124 word)");
			}
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(station);
			memoryStream.WriteByte(21);
			memoryStream.WriteByte((byte)(7 + data.Length));
			memoryStream.WriteByte(6);
			memoryStream.WriteByte(BitConverter.GetBytes(fileNumber)[1]);
			memoryStream.WriteByte(BitConverter.GetBytes(fileNumber)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(address)[1]);
			memoryStream.WriteByte(BitConverter.GetBytes(address)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(data.Length / 2)[1]);
			memoryStream.WriteByte(BitConverter.GetBytes(data.Length / 2)[0]);
			memoryStream.Write(data);
			return OResult.CreateSuccessResult(memoryStream.ToArray());
		}

		/// <summary>
		/// 构建一个同时读写的命令报文，指定读取地址，读取长度，写入地址，写入的字节数据信息，然后整个命令返回读取成功的字节数据信息
		/// </summary>
		/// <param name="readAddress">读取的地址信息</param>
		/// <param name="length">读取的地址长度</param>
		/// <param name="writeAddress">写入的地址信息</param>
		/// <param name="value">写入的字节数据</param>
		/// <param name="station">站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildReadWriteModbusCommand(string readAddress, ushort length, string writeAddress, byte[] value, byte station, bool isStartWithZero, byte defaultFunction)
		{
			try
			{
				ModbusAddress modbusAddress = new ModbusAddress(readAddress, station, defaultFunction);
				CheckModbusAddressStart(modbusAddress, isStartWithZero);
				ModbusAddress modbusAddress2 = new ModbusAddress(writeAddress, station, defaultFunction);
				CheckModbusAddressStart(modbusAddress2, isStartWithZero);
				byte[] array = new byte[11 + value.Length];
				array[0] = (byte)modbusAddress.Station;
				array[1] = (byte)modbusAddress.Function;
				array[2] = BitConverter.GetBytes(modbusAddress.AddressStart)[1];
				array[3] = BitConverter.GetBytes(modbusAddress.AddressStart)[0];
				array[4] = BitConverter.GetBytes(length)[1];
				array[5] = BitConverter.GetBytes(length)[0];
				array[6] = BitConverter.GetBytes(modbusAddress2.AddressStart)[1];
				array[7] = BitConverter.GetBytes(modbusAddress2.AddressStart)[0];
				array[8] = (byte)(value.Length / 2 / 256);
				array[9] = (byte)(value.Length / 2 % 256);
				array[10] = (byte)value.Length;
				value.CopyTo(array, 11);
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建Modbus读取数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码应该根据bool或是字来区分<br />
		/// To construct the core message of Modbus reading data, you need to specify the address, length, station number, 
		/// whether the starting address is 0, and the default function code should be distinguished according to bool or word
		/// </summary>
		/// <param name="mAddress">Modbus的富文本地址</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="cuttingBatchLength">切割长度信息，针对字读取的情况下，切割多次读取的设置值信息</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[][]> BuildReadModbusCommand(ModbusAddress mAddress, int length, int cuttingBatchLength)
		{
			List<byte[]> list = new List<byte[]>();
			if (mAddress.Function == 1 || mAddress.Function == 2 || mAddress.Function == 3 || mAddress.Function == 4)
			{
				OResult<int[], int[]> oResult = SnetHelper.SplitReadLength(mAddress.AddressStart, length, (mAddress.Function == 1 || mAddress.Function == 2) ? 2000 : cuttingBatchLength);
				for (int i = 0; i < oResult.Content1.Length; i++)
				{
					list.Add(new byte[6]
					{
						(byte)mAddress.Station,
						(byte)mAddress.Function,
						BitConverter.GetBytes(oResult.Content1[i])[1],
						BitConverter.GetBytes(oResult.Content1[i])[0],
						BitConverter.GetBytes(oResult.Content2[i])[1],
						BitConverter.GetBytes(oResult.Content2[i])[0]
					});
				}
			}
			else
			{
				list.Add(new byte[6]
				{
					(byte)mAddress.Station,
					(byte)mAddress.Function,
					BitConverter.GetBytes(mAddress.AddressStart)[1],
					BitConverter.GetBytes(mAddress.AddressStart)[0],
					BitConverter.GetBytes(length)[1],
					BitConverter.GetBytes(length)[0]
				});
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <summary>
		/// 构建Modbus写入bool数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message that Modbus writes to bool data, you need to specify the address, length,
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="address">Modbus的富文本地址</param>
		/// <param name="values">bool数组的信息</param>
		/// <param name="station">默认的站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteBoolModbusCommand(string address, bool[] values, byte station, bool isStartWithZero, byte defaultFunction)
		{
			try
			{
				ModbusAddress modbusAddress = new ModbusAddress(address, station, defaultFunction);
				CheckModbusAddressStart(modbusAddress, isStartWithZero);
				if (modbusAddress.Function == 1)
				{
					modbusAddress.Function = defaultFunction;
				}
				return BuildWriteBoolModbusCommand(modbusAddress, values);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建Modbus写入bool数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message that Modbus writes to bool data, you need to specify the address, length, station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="dataFormat">数据规则变化</param>
		/// <param name="address">Modbus的富文本地址</param>
		/// <param name="value">bool的信息</param>
		/// <param name="station">默认的站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteBoolModbusCommand(DataFormat dataFormat, string address, bool value, byte station, bool isStartWithZero, byte defaultFunction)
		{
			try
			{
				if (address.IndexOf('.') <= 0)
				{
					ModbusAddress modbusAddress = new ModbusAddress(address, station, defaultFunction);
					CheckModbusAddressStart(modbusAddress, isStartWithZero);
					if (modbusAddress.Function == 1)
					{
						modbusAddress.Function = defaultFunction;
					}
					return BuildWriteBoolModbusCommand(modbusAddress, value);
				}
				int num = Convert.ToInt32(address.Substring(address.IndexOf('.') + 1));
				if (num < 0 || num > 15)
				{
					return new OResult<byte[]>(StringResources.Language.ModbusBitIndexOverstep);
				}
				if (dataFormat == DataFormat.BADC || dataFormat == DataFormat.DCBA)
				{
					num = ((num < 8) ? (num + 8) : (num - 8));
				}
				int num2 = 1 << num;
				int num3 = ~num2;
				if (!value)
				{
					num2 = 0;
				}
				return BuildWriteMaskModbusCommand(address.Substring(0, address.IndexOf('.')), (ushort)num3, (ushort)num2, station, isStartWithZero, 22);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建Modbus写入bool数组的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message that Modbus writes to the bool array, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="mAddress">Modbus的富文本地址</param>
		/// <param name="values">bool数组的信息</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteBoolModbusCommand(ModbusAddress mAddress, bool[] values)
		{
			try
			{
				byte[] array = SoftBasic.BoolArrayToByte(values);
				byte[] array2 = new byte[7 + array.Length];
				array2[0] = (byte)mAddress.Station;
				if (mAddress.WriteFunction < 0)
				{
					array2[1] = (byte)mAddress.Function;
				}
				else
				{
					array2[1] = (byte)mAddress.WriteFunction;
				}
				array2[2] = BitConverter.GetBytes(mAddress.AddressStart)[1];
				array2[3] = BitConverter.GetBytes(mAddress.AddressStart)[0];
				array2[4] = (byte)(values.Length / 256);
				array2[5] = (byte)(values.Length % 256);
				array2[6] = (byte)array.Length;
				array.CopyTo(array2, 7);
				return OResult.CreateSuccessResult(array2);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建Modbus写入bool数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message that Modbus writes to bool data, you need to specify the address, length, station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="mAddress">Modbus的富文本地址</param>
		/// <param name="value">bool数据的信息</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteBoolModbusCommand(ModbusAddress mAddress, bool value)
		{
			byte[] array = new byte[6]
			{
				(byte)mAddress.Station,
				0,
				0,
				0,
				0,
				0
			};
			if (mAddress.WriteFunction < 0)
			{
				array[1] = (byte)mAddress.Function;
			}
			else
			{
				array[1] = (byte)mAddress.WriteFunction;
			}
			array[2] = BitConverter.GetBytes(mAddress.AddressStart)[1];
			array[3] = BitConverter.GetBytes(mAddress.AddressStart)[0];
			if (value)
			{
				array[4] = byte.MaxValue;
				array[5] = 0;
			}
			else
			{
				array[4] = 0;
				array[5] = 0;
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建Modbus写入字数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message of Modbus writing word data, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="address">Modbus的富文本地址</param>
		/// <param name="values">bool数组的信息</param>
		/// <param name="station">默认的站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteWordModbusCommand(string address, byte[] values, byte station, bool isStartWithZero, byte defaultFunction)
		{
			try
			{
				ModbusAddress modbusAddress = new ModbusAddress(address, station, defaultFunction);
				if (modbusAddress.Function == 3)
				{
					modbusAddress.Function = defaultFunction;
				}
				CheckModbusAddressStart(modbusAddress, isStartWithZero);
				return BuildWriteWordModbusCommand(modbusAddress, values);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建Modbus写入字数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message of Modbus writing word data, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="address">Modbus的富文本地址</param>
		/// <param name="value">short数据信息</param>
		/// <param name="station">默认的站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码</param>
		/// <param name="byteTransform">数据的变换规则</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteWordModbusCommand(string address, short value, byte station, bool isStartWithZero, byte defaultFunction, IByteTransform byteTransform)
		{
			try
			{
				ModbusAddress modbusAddress = new ModbusAddress(address, station, defaultFunction);
				if (modbusAddress.Function == 3)
				{
					modbusAddress.Function = defaultFunction;
				}
				if (modbusAddress.WriteFunction == 16 || modbusAddress.Function == 16)
				{
					CheckModbusAddressStart(modbusAddress, isStartWithZero);
					byte[] values = byteTransform.TransByte(value);
					return BuildWriteWordModbusCommand(modbusAddress, values);
				}
				CheckModbusAddressStart(modbusAddress, isStartWithZero);
				return BuildWriteOneRegisterModbusCommand(modbusAddress, value, byteTransform);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建Modbus写入字数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message of Modbus writing word data, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="address">Modbus的富文本地址</param>
		/// <param name="value">bool数组的信息</param>
		/// <param name="station">默认的站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码</param>
		/// <param name="byteTransform">数据的变换规则</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteWordModbusCommand(string address, ushort value, byte station, bool isStartWithZero, byte defaultFunction, IByteTransform byteTransform)
		{
			try
			{
				ModbusAddress modbusAddress = new ModbusAddress(address, station, defaultFunction);
				if (modbusAddress.Function == 3)
				{
					modbusAddress.Function = defaultFunction;
				}
				if (modbusAddress.WriteFunction == 16 || modbusAddress.Function == 16)
				{
					CheckModbusAddressStart(modbusAddress, isStartWithZero);
					byte[] values = byteTransform.TransByte(value);
					return BuildWriteWordModbusCommand(modbusAddress, values);
				}
				CheckModbusAddressStart(modbusAddress, isStartWithZero);
				return BuildWriteOneRegisterModbusCommand(modbusAddress, value, byteTransform);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建Modbus写入掩码的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the Modbus write mask core message, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="address">Modbus的富文本地址</param>
		/// <param name="andMask">进行与操作的掩码信息</param>
		/// <param name="orMask">进行或操作的掩码信息</param>
		/// <param name="station">默认的站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteMaskModbusCommand(string address, ushort andMask, ushort orMask, byte station, bool isStartWithZero, byte defaultFunction)
		{
			try
			{
				ModbusAddress modbusAddress = new ModbusAddress(address, station, defaultFunction);
				if (modbusAddress.Function == 3)
				{
					modbusAddress.Function = defaultFunction;
				}
				CheckModbusAddressStart(modbusAddress, isStartWithZero);
				return BuildWriteMaskModbusCommand(modbusAddress, andMask, orMask);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建Modbus写入字数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message of Modbus writing word data, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="mAddress">Modbus的富文本地址</param>
		/// <param name="values">bool数组的信息</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteWordModbusCommand(ModbusAddress mAddress, byte[] values)
		{
			byte[] array = new byte[7 + values.Length];
			array[0] = (byte)mAddress.Station;
			if (mAddress.WriteFunction < 0)
			{
				array[1] = (byte)mAddress.Function;
			}
			else
			{
				array[1] = (byte)mAddress.WriteFunction;
			}
			array[2] = BitConverter.GetBytes(mAddress.AddressStart)[1];
			array[3] = BitConverter.GetBytes(mAddress.AddressStart)[0];
			array[4] = (byte)(values.Length / 2 / 256);
			array[5] = (byte)(values.Length / 2 % 256);
			array[6] = (byte)values.Length;
			values.CopyTo(array, 7);
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建Modbus写入掩码数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message of Modbus writing mask data, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="mAddress">Modbus的富文本地址</param>
		/// <param name="andMask">等待进行与操作的掩码</param>
		/// <param name="orMask">等待进行或操作的掩码</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteMaskModbusCommand(ModbusAddress mAddress, ushort andMask, ushort orMask)
		{
			return OResult.CreateSuccessResult(new byte[8]
			{
				(byte)mAddress.Station,
				(byte)mAddress.Function,
				BitConverter.GetBytes(mAddress.AddressStart)[1],
				BitConverter.GetBytes(mAddress.AddressStart)[0],
				BitConverter.GetBytes(andMask)[1],
				BitConverter.GetBytes(andMask)[0],
				BitConverter.GetBytes(orMask)[1],
				BitConverter.GetBytes(orMask)[0]
			});
		}

		/// <summary>
		/// 构建Modbus写入字数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message of Modbus writing word data, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="mAddress">Modbus的富文本地址</param>
		/// <param name="value">short的值</param>
		/// <param name="byteTransform">数据的变换规则</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteOneRegisterModbusCommand(ModbusAddress mAddress, short value, IByteTransform byteTransform)
		{
			byte[] array = new byte[6]
			{
				(byte)mAddress.Station,
				0,
				0,
				0,
				0,
				0
			};
			if (mAddress.WriteFunction < 0)
			{
				array[1] = (byte)mAddress.Function;
			}
			else
			{
				array[1] = (byte)mAddress.WriteFunction;
			}
			array[2] = BitConverter.GetBytes(mAddress.AddressStart)[1];
			array[3] = BitConverter.GetBytes(mAddress.AddressStart)[0];
			array[4] = byteTransform.TransByte(value)[0];
			array[5] = byteTransform.TransByte(value)[1];
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 构建Modbus写入字数据的核心报文，需要指定地址，长度，站号，是否起始地址0，默认的功能码<br />
		/// To construct the core message of Modbus writing word data, you need to specify the address, length, 
		/// station number, whether the starting address is 0, and the default function code
		/// </summary>
		/// <param name="mAddress">Modbus的富文本地址</param>
		/// <param name="value">ushort的值</param>
		/// <param name="byteTransform">数据的变换规则</param>
		/// <returns>包含最终命令的结果对象</returns>
		public static OResult<byte[]> BuildWriteOneRegisterModbusCommand(ModbusAddress mAddress, ushort value, IByteTransform byteTransform)
		{
			byte[] array = new byte[6]
			{
				(byte)mAddress.Station,
				0,
				0,
				0,
				0,
				0
			};
			if (mAddress.WriteFunction < 0)
			{
				array[1] = (byte)mAddress.Function;
			}
			else
			{
				array[1] = (byte)mAddress.WriteFunction;
			}
			array[2] = BitConverter.GetBytes(mAddress.AddressStart)[1];
			array[3] = BitConverter.GetBytes(mAddress.AddressStart)[0];
			array[4] = byteTransform.TransByte(value)[0];
			array[5] = byteTransform.TransByte(value)[1];
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 从返回的modbus的书内容中，提取出真实的数据，适用于写入和读取操作<br />
		/// Extract real data from the content of the returned modbus book, suitable for writing and reading operations
		/// </summary>
		/// <param name="response">返回的核心modbus报文信息</param>
		/// <returns>结果数据内容</returns>
		public static OResult<byte[]> ExtractActualData(byte[] response)
		{
			try
			{
				if (response[1] >= 128)
				{
					return new OResult<byte[]>(response[2], GetDescriptionByErrorCode(response[2]));
				}
				if (response.Length > 3)
				{
					return OResult.CreateSuccessResult(SoftBasic.ArrayRemoveBegin(response, 3));
				}
				return OResult.CreateSuccessResult(new byte[0]);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 将modbus指令打包成Modbus-Tcp指令，需要指定ID信息来添加6个字节的报文头<br />
		/// Pack the Modbus command into Modbus-Tcp command, you need to specify the ID information to add a 6-byte message header
		/// </summary>
		/// <param name="modbus">Modbus核心指令</param>
		/// <param name="id">消息的序号</param>
		/// <returns>Modbus-Tcp指令</returns>
		public static byte[] PackCommandToTcp(byte[] modbus, ushort id)
		{
			byte[] array = new byte[modbus.Length + 6];
			array[0] = BitConverter.GetBytes(id)[1];
			array[1] = BitConverter.GetBytes(id)[0];
			array[4] = BitConverter.GetBytes(modbus.Length)[1];
			array[5] = BitConverter.GetBytes(modbus.Length)[0];
			modbus.CopyTo(array, 6);
			return array;
		}

		/// <summary>
		/// 将modbus-tcp的报文数据重新还原成modbus指令，移除6个字节的报文头数据<br />
		/// Re-modify the message data of modbus-tcp into the modbus command, remove the 6-byte message header data
		/// </summary>
		/// <param name="modbusTcp">modbus-tcp的报文</param>
		/// <returns>modbus数据报文</returns>
		public static byte[] ExplodeTcpCommandToCore(byte[] modbusTcp)
		{
			return modbusTcp.RemoveBegin(6);
		}

		/// <summary>
		/// 将modbus-rtu的数据重新还原成modbus数据，移除CRC校验的内容<br />
		/// Restore the data of modbus-rtu to modbus data again, remove the content of CRC check
		/// </summary>
		/// <param name="modbusRtu">modbus-rtu的报文</param>
		/// <returns>modbus数据报文</returns>
		public static byte[] ExplodeRtuCommandToCore(byte[] modbusRtu)
		{
			return modbusRtu.RemoveLast(2);
		}

		/// <summary>
		/// 将modbus指令打包成Modbus-Rtu指令，在报文的末尾添加CRC16的校验码<br />
		/// Pack the modbus instruction into Modbus-Rtu instruction, add CRC16 check code at the end of the message
		/// </summary>
		/// <param name="modbus">Modbus指令</param>
		/// <returns>Modbus-Rtu指令</returns>
		public static byte[] PackCommandToRtu(byte[] modbus)
		{
			return SoftCRC16.CRC16(modbus);
		}

		/// <summary>
		/// 将一个modbus核心的数据报文，转换成modbus-ascii的数据报文，增加LRC校验，增加首尾标记数据<br />
		/// Convert a Modbus core data message into a Modbus-ascii data message, add LRC check, and add head and tail tag data
		/// </summary>
		/// <param name="modbus">modbus-rtu的完整报文，携带相关的校验码</param>
		/// <returns>可以用于直接发送的modbus-ascii的报文</returns>
		public static byte[] TransModbusCoreToAsciiPackCommand(byte[] modbus)
		{
			byte[] array = SoftBasic.BytesToAsciiBytes(SoftLRC.LRC(modbus));
			return SoftBasic.SpliceArray<byte>(new byte[1] { 58 }, array, new byte[2] { 13, 10 });
		}

		/// <summary>
		/// 将一个modbus-ascii的数据报文，转换成的modbus核心数据报文，移除首尾标记，移除LRC校验<br />
		/// Convert a Modbus-ascii data message into a Modbus core data message, remove the first and last tags, and remove the LRC check
		/// </summary>
		/// <param name="modbusAscii">modbus-ascii的完整报文，携带相关的校验码</param>
		/// <returns>可以用于直接发送的modbus的报文</returns>
		public static OResult<byte[]> TransAsciiPackCommandToCore(byte[] modbusAscii)
		{
			try
			{
				if (modbusAscii[0] != 58 || modbusAscii[^2] != 13 || modbusAscii[^1] != 10)
				{
					return new OResult<byte[]>
					{
						Message = StringResources.Language.ModbusAsciiFormatCheckFailed + modbusAscii.ToHexString(' ')
					};
				}
				int num = -1;
				for (int i = 1; i < modbusAscii.Length - 1; i++)
				{
					if (modbusAscii[i] == 13 && modbusAscii[i + 1] == 10)
					{
						num = i;
						break;
					}
				}
				if (num > 1 && num != modbusAscii.Length - 2)
				{
					modbusAscii = modbusAscii.SelectBegin(num + 2);
				}
				byte[] array = SoftBasic.AsciiBytesToBytes(modbusAscii.RemoveDouble(1, 2));
				if (!SoftLRC.CheckLRC(array))
				{
					return new OResult<byte[]>
					{
						Message = StringResources.Language.ModbusLRCCheckFailed + array.ToHexString(' ')
					};
				}
				return OResult.CreateSuccessResult(array.RemoveLast(1));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>
				{
					Message = ex.Message + modbusAscii.ToHexString(' ')
				};
			}
		}

		/// <summary>
		/// 分析Modbus协议的地址信息，该地址适应于tcp及rtu模式<br />
		/// Analysis of the address information of Modbus protocol, the address is adapted to tcp and rtu mode
		/// </summary>
		/// <param name="address">带格式的地址，比如"100"，"x=4;100"，"s=1;100","s=1;x=4;100"</param>
		/// <param name="defaultStation">默认的站号信息</param>
		/// <param name="isStartWithZero">起始地址是否从0开始</param>
		/// <param name="defaultFunction">默认的功能码信息</param>
		/// <returns>转换后的地址信息</returns>
		public static OResult<ModbusAddress> AnalysisAddress(string address, byte defaultStation, bool isStartWithZero, byte defaultFunction)
		{
			try
			{
				ModbusAddress modbusAddress = new ModbusAddress(address, defaultStation, defaultFunction);
				if (!isStartWithZero)
				{
					if (modbusAddress.AddressStart < 1)
					{
						throw new Exception(StringResources.Language.ModbusAddressMustMoreThanOne);
					}
					modbusAddress.AddressStart--;
				}
				return OResult.CreateSuccessResult(modbusAddress);
			}
			catch (Exception ex)
			{
				return new OResult<ModbusAddress>
				{
					Message = ex.Message
				};
			}
		}

		/// <summary>
		/// 通过错误码来获取到对应的文本消息<br />
		/// Get the corresponding text message through the error code
		/// </summary>
		/// <param name="code">错误码</param>
		/// <returns>错误的文本描述</returns>
		public static string GetDescriptionByErrorCode(byte code)
		{
			return code switch
			{
				1 => StringResources.Language.ModbusTcpFunctionCodeNotSupport, 
				2 => StringResources.Language.ModbusTcpFunctionCodeOverBound, 
				3 => StringResources.Language.ModbusTcpFunctionCodeQuantityOver, 
				4 => StringResources.Language.ModbusTcpFunctionCodeReadWriteException, 
				_ => StringResources.Language.UnknownError, 
			};
		}

		private static bool CheckRtuReceiveDataComplete(byte[] response, int startIndex = 0, bool checkCrc = true)
		{
			if (response.Length > 3 + startIndex)
			{
				if (response[startIndex + 1] == 6 || response[startIndex + 1] == 16 || response[startIndex + 1] == 15 || response[startIndex + 1] == 5)
				{
					if (response.Length >= 8 + startIndex)
					{
						if (checkCrc)
						{
							return SoftCRC16.CheckCRC16(response.SelectMiddle(startIndex, 8));
						}
						return true;
					}
				}
				else if (response[startIndex + 1] == 1 || response[startIndex + 1] == 2 || response[startIndex + 1] == 3 || response[startIndex + 1] == 4 || response[startIndex + 1] == 23 || response[startIndex + 1] == 20 || response[startIndex + 1] == 21)
				{
					if (response.Length >= response[2 + startIndex] + 3 + 2 + startIndex)
					{
						if (checkCrc)
						{
							return SoftCRC16.CheckCRC16(response.SelectMiddle(startIndex, response[2 + startIndex] + 3 + 2));
						}
						return true;
					}
				}
				else if (response[startIndex + 1] == 22)
				{
					if (response.Length >= 10 + startIndex)
					{
						if (checkCrc)
						{
							return SoftCRC16.CheckCRC16(response.SelectMiddle(startIndex, 10));
						}
						return true;
					}
				}
				else
				{
					if (response[startIndex + 1] <= 128)
					{
						if (checkCrc)
						{
							return SoftCRC16.CheckCRC16(response.RemoveBegin(startIndex));
						}
						return true;
					}
					if (response.Length >= 5 + startIndex)
					{
						if (checkCrc)
						{
							return SoftCRC16.CheckCRC16(response.SelectMiddle(startIndex, 5));
						}
						return true;
					}
				}
			}
			return false;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.NetMessageBase.CheckReceiveDataComplete(System.Byte[],System.IO.MemoryStream)" />
		public static bool CheckRtuReceiveDataComplete(byte[] send, byte[] response)
		{
			if (send == null)
			{
				return CheckRtuReceiveDataComplete(response);
			}
			if (send.Length < 5)
			{
				return CheckRtuReceiveDataComplete(response);
			}
			if (response == null)
			{
				return false;
			}
			int num = Math.Min(response.Length - 3, 3);
			for (int i = 0; i <= num; i++)
			{
				if (CheckModbusStationFunction(send, response, i) && CheckRtuReceiveDataComplete(response, i))
				{
					return true;
				}
			}
			for (int j = 0; j < num; j++)
			{
				if (CheckModbusStationFunction(send, response, j) && CheckRtuReceiveDataComplete(response, j, checkCrc: false))
				{
					return true;
				}
			}
			return false;
		}

		private static bool CheckModbusStationFunction(byte[] send, byte[] receive, int index)
		{
			if (send[0] != receive[index])
			{
				return false;
			}
			if (index + 1 >= receive.Length)
			{
				return false;
			}
			if (send[1] != receive[index + 1])
			{
				return receive[index + 1] == send[1] + 128;
			}
			return true;
		}

		/// <summary>
		/// 检查当前发送和接收的modbusrtu报文是否站号匹配，匹配返回 1，此处进行匹配的时候，还有一定的容错范围
		/// </summary>
		/// <param name="send">发送的数据</param>
		/// <param name="receive">接收的数据</param>
		/// <returns>modbus的报文是否站号匹配</returns>
		public static int CheckRtuMessageMatch(byte[] send, byte[] receive)
		{
			if (send == null)
			{
				return 1;
			}
			if (send.Length < 5)
			{
				return 1;
			}
			if (receive == null)
			{
				return 1;
			}
			for (int i = 0; i < receive.Length - 3; i++)
			{
				if (send[0] == receive[i] && CheckRtuReceiveDataComplete(receive, i, checkCrc: false))
				{
					return 1;
				}
			}
			return -1;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.NetMessageBase.CheckReceiveDataComplete(System.Byte[],System.IO.MemoryStream)" />
		public static bool CheckServerRtuReceiveDataComplete(byte[] receive)
		{
			if (receive.Length > 2)
			{
				if (receive[1] == 16 || receive[1] == 15)
				{
					if (receive.Length > 8)
					{
						return receive.Length >= receive[6] + 7 + 2;
					}
					return false;
				}
				if (receive[1] == 1 || receive[1] == 2 || receive[1] == 3 || receive[1] == 4 || receive[1] == 6 || receive[1] == 5)
				{
					return receive.Length >= 8;
				}
				if (receive[1] == 22)
				{
					return receive.Length >= 10;
				}
				if (receive[1] == 23)
				{
					return receive.Length >= 11 + receive[10] + 2;
				}
				if (receive[1] == 20 || receive[1] == 21)
				{
					return receive.Length >= 3 + receive[2] + 2;
				}
			}
			return false;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.NetMessageBase.CheckReceiveDataComplete(System.Byte[],System.IO.MemoryStream)" />
		public static bool CheckAsciiReceiveDataComplete(byte[] modbusAscii)
		{
			return CheckAsciiReceiveDataComplete(modbusAscii, modbusAscii.Length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.NetMessageBase.CheckReceiveDataComplete(System.Byte[],System.IO.MemoryStream)" />
		public static bool CheckAsciiReceiveDataComplete(byte[] modbusAscii, int length)
		{
			if (length > 5)
			{
				if (modbusAscii[0] == 58 && modbusAscii[length - 2] == 13)
				{
					return modbusAscii[length - 1] == 10;
				}
				return false;
			}
			return false;
		}
	}
	/// <summary>
	/// Modbus的地址映射类
	/// </summary>
	public class ModbusMappingAddress
	{
		private static int ParseBitAddress(string address, int wordLength = 16)
		{
			int num = address.IndexOf('.');
			if (num > 0)
			{
				return Convert.ToInt32(address.Substring(0, num)) * wordLength + SnetHelper.CalculateBitStartIndex(address.Substring(num + 1));
			}
			return Convert.ToInt32(address) * wordLength;
		}

		/// <summary>
		/// 根据台达AS300的PLC的地址，解析出转换后的modbus协议信息，适用AS300系列，当前的地址仍然支持站号指定，例如s=2;D100<br />
		/// According to the PLC address of Delta AS300, the converted modbus protocol information is parsed, 
		/// and it is applicable to AS300 series. The current address still supports station number designation, for example, s=2;D100
		/// </summary>
		/// <param name="address">台达plc的地址信息</param>
		/// <param name="modbusCode">原始的对应的modbus信息</param>
		/// <returns>还原后的modbus地址</returns>
		public static OResult<string> Delta_AS(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWithNoCase("SM"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 16384));
					}
					if (address.StartsWithNoCase("HC"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 64512));
					}
					if (address.StartsWithNoCase("S"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 20480));
					}
					if (address.StartsWithNoCase("X"))
					{
						return OResult.CreateSuccessResult(text + "x=2;" + (ParseBitAddress(address.Substring(1)) + 24576));
					}
					if (address.StartsWithNoCase("Y"))
					{
						return OResult.CreateSuccessResult(text + (ParseBitAddress(address.Substring(1)) + 40960));
					}
					if (address.StartsWithNoCase("T"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 57344));
					}
					if (address.StartsWithNoCase("C"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 61440));
					}
					if (address.StartsWithNoCase("M"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWithNoCase("D") && address.Contains("."))
					{
						return OResult.CreateSuccessResult(text + address);
					}
				}
				else
				{
					if (address.StartsWithNoCase("SR"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 49152));
					}
					if (address.StartsWithNoCase("HC"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 64512));
					}
					if (address.StartsWithNoCase("D"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWithNoCase("X"))
					{
						return OResult.CreateSuccessResult(text + "x=4;" + (Convert.ToInt32(address.Substring(1)) + 32768));
					}
					if (address.StartsWithNoCase("Y"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 40960));
					}
					if (address.StartsWithNoCase("C"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 61440));
					}
					if (address.StartsWithNoCase("T"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 57344));
					}
					if (address.StartsWithNoCase("E"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 65024));
					}
				}
				return new OResult<string>(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message);
			}
		}

		/// <summary>
		/// 维控的Lx5v的Modbus地址转换方法，主要注入到Modbus类，即可以在Modbus里使用维控的地址进行通信
		/// </summary>
		/// <param name="address">维控plc的地址信息</param>
		/// <param name="modbusCode">原始的对应的modbus信息</param>
		/// <returns>还原后的modbus地址</returns>
		public static OResult<string> WeCon_Lx5v(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWithAndNumber("T"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWithAndNumber("C"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 1536));
					}
					if (address.StartsWithAndNumber("LC"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 2560));
					}
					if (address.StartsWithAndNumber("HSC"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(3)) + 3584));
					}
					if (address.StartsWithAndNumber("M"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 4096));
					}
					if (address.StartsWithAndNumber("SM"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 20480));
					}
					if (address.StartsWithAndNumber("S"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 49152));
					}
					if (address.StartsWithAndNumber("X"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1), 8) + 57344));
					}
					if (address.StartsWithAndNumber("Y"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1), 8) + 61440));
					}
					if (ModbusHelper.TransPointAddressToModbus(text, address, new string[3] { "D", "SD", "R" }, new int[3] { 4096, 20480, 32768 }, int.Parse, out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
				}
				else
				{
					if (address.StartsWithAndNumber("T"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWithAndNumber("C"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 1536));
					}
					if (address.StartsWithAndNumber("LC"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) * 2 + 2560));
					}
					if (address.StartsWithAndNumber("HSC"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(3)) * 2 + 3584));
					}
					if (address.StartsWithAndNumber("D"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 4096));
					}
					if (address.StartsWithAndNumber("SD"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) + 20480));
					}
					if (address.StartsWithAndNumber("R"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 32768));
					}
				}
				throw new Exception(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}

		/// <summary>
		/// 英威腾 TS600 的modbus地址变换
		/// </summary>
		/// <param name="address">英威腾PLC的地址</param>
		/// <param name="modbusCode">默认的modbus功能码</param>
		/// <returns>还原后的modbus地址</returns>
		public static OResult<string> Invt_Ts(string address, byte modbusCode)
		{
			try
			{
				string text = string.Empty;
				OResult<int> oResult = SnetHelper.ExtractParameter(ref address, "s");
				if (oResult.IsSuccess)
				{
					text = $"s={oResult.Content};";
				}
				if (modbusCode == 1 || modbusCode == 15 || modbusCode == 5)
				{
					if (address.StartsWithAndNumber("M"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWithAndNumber("S"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 32768));
					}
					if (address.StartsWithAndNumber("X"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1), 8) + 40960));
					}
					if (address.StartsWithAndNumber("Y"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1), 8) + 45056));
					}
					if (address.StartsWithAndNumber("T"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 49152));
					}
					if (address.StartsWithAndNumber("C"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 49664));
					}
					if (ModbusHelper.TransPointAddressToModbus(text, address, new string[2] { "D", "R" }, new int[2] { 0, 32768 }, int.Parse, out string newAddress))
					{
						return OResult.CreateSuccessResult(newAddress);
					}
				}
				else
				{
					if (address.StartsWithAndNumber("T"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 57344));
					}
					if (address.StartsWithAndNumber("C"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 57856));
					}
					if (address.StartsWithAndNumber("Z"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(2)) * 2 + 58368));
					}
					if (address.StartsWithAndNumber("D"))
					{
						return OResult.CreateSuccessResult(text + Convert.ToInt32(address.Substring(1)));
					}
					if (address.StartsWithAndNumber("R"))
					{
						return OResult.CreateSuccessResult(text + (Convert.ToInt32(address.Substring(1)) + 32768));
					}
					if (address.StartsWithAndNumber("M"))
					{
						return OResult.CreateSuccessResult(text + "x=1;" + Convert.ToInt32(address.Substring(1)));
					}
				}
				throw new Exception(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<string>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}
	}
	/// <summary>
	/// 服务器端提供的数据监视服务
	/// </summary>
	public class ModBusMonitorAddress
	{
		/// <summary>
		/// 本次数据监视的地址
		/// </summary>
		public ushort Address { get; set; }

		/// <summary>
		/// 数据写入时触发的事件
		/// </summary>
		public event Action<ModBusMonitorAddress, short> OnWrite;

		/// <summary>
		/// 数据改变时触发的事件
		/// </summary>
		public event Action<ModBusMonitorAddress, short, short> OnChange;

		/// <summary>
		/// 强制设置触发事件
		/// </summary>
		/// <param name="value">数据值信息</param>
		public void SetValue(short value)
		{
			OnWrite?.Invoke(this, value);
		}

		/// <summary>
		/// 强制设置触发值变更事件
		/// </summary>
		/// <param name="before">变更前的值</param>
		/// <param name="after">变更后的值</param>
		public void SetChangeValue(short before, short after)
		{
			if (before != after)
			{
				OnChange?.Invoke(this, before, after);
			}
		}
	}
	/// <summary>
	/// Modbus-Rtu通讯协议的类库，多项式码0xA001，支持标准的功能码，也支持扩展的功能码实现，地址采用富文本的形式，详细见备注说明<br />
	/// Modbus-Rtu communication protocol class library, polynomial code 0xA001, supports standard function codes, 
	/// and also supports extended function code implementation. The address is in rich text. For details, see the remark
	/// </summary>
	/// <remarks>
	/// 本客户端支持的标准的modbus协议，Modbus-Tcp及Modbus-Udp内置的消息号会进行自增，地址支持富文本格式，具体参考示例代码。<br />
	/// 读取线圈，输入线圈，寄存器，输入寄存器的方法中的读取长度对商业授权用户不限制，内部自动切割读取，结果合并。
	/// </remarks>
	/// <example>
	/// <inheritdoc cref="T:Snet.Driver.ModBus.ModbusTcpNet" path="example" />
	/// </example>
	public class ModbusRtu : DeviceSerialPort, IModbus, IReadWriteDevice, IReadWriteNet
	{
		private byte station = 1;

		private bool isAddressStartWithZero = true;

		private Func<string, byte, OResult<string>> addressMapping = (string address, byte modbusCode) => OResult.CreateSuccessResult(address);

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.AddressStartWithZero" />
		public bool AddressStartWithZero
		{
			get
			{
				return isAddressStartWithZero;
			}
			set
			{
				isAddressStartWithZero = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.Station" />
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.DataFormat" />
		public DataFormat DataFormat
		{
			get
			{
				return base.ByteTransform.DataFormat;
			}
			set
			{
				base.ByteTransform.DataFormat = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.IsStringReverse" />
		public bool IsStringReverse
		{
			get
			{
				return base.ByteTransform.IsStringReverseByteWord;
			}
			set
			{
				base.ByteTransform.IsStringReverseByteWord = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.IModbus.EnableWriteMaskCode" />
		public bool EnableWriteMaskCode { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.IModbus.BroadcastStation" />
		public int BroadcastStation { get; set; } = -1;

		/// <summary>
		/// 获取或设置当前是否启用站号检查的功能，默认启用，读写数据时将进行站号确认操作，如果需要忽略站号，则设置为 false 即可。<br />
		/// Gets or sets whether the station ID check function is enabled. It is enabled by default. When reading or writing data, the station ID is confirmed.
		/// </summary>
		public bool StationCheckMatch { get; set; } = true;

		/// <summary>
		/// 获取或设置是否启用CRC16校验码的检查功能，默认启用，如果需要忽略检查CRC16，则设置为 false 即可。<br />
		/// Gets or sets whether to enable the check function of CRC16 check code. It is enabled by default. If you need to ignore the check of CRC16, you can set it to false.
		/// </summary>
		public bool Crc16CheckEnable { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.IModbus.WordReadBatchLength" />
		public int WordReadBatchLength { get; set; } = 120;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.IModbus.DisableFunctionCode06" />
		public bool DisableFunctionCode06 { get; set; }

		/// <summary>
		/// 实例化一个Modbus-Rtu协议的客户端对象<br />
		/// Instantiate a client object of the Modbus-Rtu protocol
		/// </summary>
		public ModbusRtu()
		{
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
			base.ReceiveEmptyDataCount = 8;
		}

		/// <summary>
		/// 指定Modbus从站的站号来初始化<br />
		/// Specify the station number of the Modbus slave to initialize
		/// </summary>
		/// <param name="station">Modbus从站的站号</param>
		public ModbusRtu(byte station = 1)
			: this()
		{
			this.station = station;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new ModbusRtuMessage(StationCheckMatch);
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.IModbus.TranslateToModbusAddress(System.String,System.Byte)" />
		public virtual OResult<string> TranslateToModbusAddress(string address, byte modbusCode)
		{
			if (addressMapping != null)
			{
				return addressMapping(address, modbusCode);
			}
			return OResult.CreateSuccessResult(address);
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.IModbus.RegisteredAddressMapping(System.Func{System.String,System.Byte,Snet.Driver.OResult{System.String}})" />
		public void RegisteredAddressMapping(Func<string, byte, OResult<string>> mapping)
		{
			addressMapping = mapping;
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			return ModbusInfo.PackCommandToRtu(command);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			return ModbusHelper.ExtraRtuResponseContent(send, response, Crc16CheckEnable, BroadcastStation);
		}

		/// <summary>
		/// 将Modbus报文数据发送到当前的通道中，并从通道中接收Modbus的报文，通道将根据当前连接自动获取，本方法是线程安全的。<br />
		/// Send Modbus message data to the current channel, and receive Modbus messages from the channel. The channel will automatically obtain it according to the current connection. This method is thread-safe.
		/// </summary>
		/// <param name="send">发送的完整的报文信息</param>
		/// <returns>接收到的Modbus报文信息</returns>
		/// <remarks>
		/// 需要注意的是，本方法的发送和接收都只需要输入Modbus核心报文，例如读取寄存器0的字数据 01 03 00 00 00 01，最后面两个字节的CRC是自动添加的，收到的数据也是只有modbus核心报文，例如：01 03 02 00 00 , 已经成功校验CRC校验并移除了，所以在解析的时候需要注意。<br />
		/// It should be noted that the sending and receiving of this method only need to input Modbus core messages, for example, read the word data 01 03 00 00 00 01 of register 0, the last two bytes of CRC are automatically added, 
		/// and received The data is also only modbus core messages, for example: 01 03 02 00 00, CRC has been successfully checked and removed, so you need to pay attention when parsing.
		/// </remarks>
		public override OResult<byte[]> ReadFromCoreServer(byte[] send)
		{
			if (BroadcastStation >= 0 && send[0] == BroadcastStation)
			{
				return ReadFromCoreServer(send, hasResponseData: false, usePackAndUnpack: true);
			}
			return base.ReadFromCoreServer(send);
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusRtu.ReadFromCoreServer(System.Byte[])" />
		public override async Task<OResult<byte[]>> ReadFromCoreServerAsync(byte[] send)
		{
			if (BroadcastStation >= 0 && send[0] == BroadcastStation)
			{
				return ReadFromCoreServer(send, hasResponseData: false, usePackAndUnpack: true);
			}
			return await base.ReadFromCoreServerAsync(send);
		}

