	/// <inheritdoc cref="T:Snet.Driver.ModBus.ModbusRtu" />
	public class ModbusRtuOverTcp : DeviceTcpNet, IModbus, IReadWriteDevice, IReadWriteNet
	{
		private byte station = 1;

		private bool isAddressStartWithZero = true;

		private Func<string, byte, OResult<string>> addressMapping = (string address, byte modbusCode) => OResult.CreateSuccessResult(address);

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.AddressStartWithZero" />
		public bool AddressStartWithZero
		{
			get
			{
				return isAddressStartWithZero;
			}
			set
			{
				isAddressStartWithZero = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.Station" />
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.DataFormat" />
		public DataFormat DataFormat
		{
			get
			{
				return base.ByteTransform.DataFormat;
			}
			set
			{
				base.ByteTransform.DataFormat = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusTcpNet.IsStringReverse" />
		public bool IsStringReverse
		{
			get
			{
				return base.ByteTransform.IsStringReverseByteWord;
			}
			set
			{
				base.ByteTransform.IsStringReverseByteWord = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusRtu.Crc16CheckEnable" />
		public bool Crc16CheckEnable { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusRtu.StationCheckMatch" />
		public bool StationCheckMatch { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.IModbus.EnableWriteMaskCode" />
		public bool EnableWriteMaskCode { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.IModbus.BroadcastStation" />
		public int BroadcastStation { get; set; } = -1;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.IModbus.WordReadBatchLength" />
		public int WordReadBatchLength { get; set; } = 120;

		/// <inheritdoc cref="P:Snet.Driver.ModBus.IModbus.DisableFunctionCode06" />
		public bool DisableFunctionCode06 { get; set; }

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusRtu.#ctor" />
		public ModbusRtuOverTcp()
		{
			base.ByteTransform = new RegularByteTransform(DataFormat.CDAB);
			base.WordLength = 1;
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusTcpNet.#ctor(System.String,System.Int32,System.Byte)" />
		public ModbusRtuOverTcp(string ipAddress, int port = 502, byte station = 1)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
			this.station = station;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new ModbusRtuMessage(StationCheckMatch);
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.IModbus.TranslateToModbusAddress(System.String,System.Byte)" />
		public virtual OResult<string> TranslateToModbusAddress(string address, byte modbusCode)
		{
			if (addressMapping != null)
			{
				return addressMapping(address, modbusCode);
			}
			return OResult.CreateSuccessResult(address);
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.IModbus.RegisteredAddressMapping(System.Func{System.String,System.Byte,Snet.Driver.OResult{System.String}})" />
		public void RegisteredAddressMapping(Func<string, byte, OResult<string>> mapping)
		{
			addressMapping = mapping;
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			return ModbusInfo.PackCommandToRtu(command);
		}

		/// <inheritdoc />
		public override OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			return ModbusHelper.ExtraRtuResponseContent(send, response, Crc16CheckEnable, BroadcastStation);
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReadFromCoreServer(byte[] send)
		{
			if (BroadcastStation >= 0 && send[0] == BroadcastStation)
			{
				return ReadFromCoreServer(send, hasResponseData: false, usePackAndUnpack: true);
			}
			return base.ReadFromCoreServer(send);
		}

		/// <inheritdoc cref="M:Snet.Driver.ModBus.ModbusRtuOverTcp.ReadFromCoreServer(System.Byte[])" />
		public override async Task<OResult<byte[]>> ReadFromCoreServerAsync(byte[] send)
		{
			if (BroadcastStation >= 0 && send[0] == BroadcastStation)
			{
				return ReadFromCoreServer(send, hasResponseData: false, usePackAndUnpack: true);
			}
			return await base.ReadFromCoreServerAsync(send);
		}

