		public override async Task<OResult<uint[]>> ReadUInt32Async(string address, ushort length)
		{
			IByteTransform transform = SnetHelper.ExtractTransformParameter(ref address, base.ByteTransform);
			return ByteTransformHelper.GetResultFromBytes(await ReadAsync(address, (ushort)(length * base.WordLength * 2)), (byte[] m) => transform.TransUInt32(m, 0, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadFloatAsync(System.String,System.UInt16)" />
		public override async Task<OResult<float[]>> ReadFloatAsync(string address, ushort length)
		{
			IByteTransform transform = SnetHelper.ExtractTransformParameter(ref address, base.ByteTransform);
			return ByteTransformHelper.GetResultFromBytes(await ReadAsync(address, (ushort)(length * base.WordLength * 2)), (byte[] m) => transform.TransSingle(m, 0, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadInt64Async(System.String,System.UInt16)" />
		public override async Task<OResult<long[]>> ReadInt64Async(string address, ushort length)
		{
			IByteTransform transform = SnetHelper.ExtractTransformParameter(ref address, base.ByteTransform);
			return ByteTransformHelper.GetResultFromBytes(await ReadAsync(address, (ushort)(length * base.WordLength * 4)), (byte[] m) => transform.TransInt64(m, 0, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadUInt64Async(System.String,System.UInt16)" />
		public override async Task<OResult<ulong[]>> ReadUInt64Async(string address, ushort length)
		{
