		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadDoubleAsync(System.String,System.UInt16)" />
		public override async Task<OResult<double[]>> ReadDoubleAsync(string address, ushort length)
		{
			IByteTransform transform = SnetHelper.ExtractTransformParameter(ref address, base.ByteTransform);
			return ByteTransformHelper.GetResultFromBytes(await ReadAsync(address, (ushort)(length * base.WordLength * 4)), (byte[] m) => transform.TransDouble(m, 0, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.WriteAsync(System.String,System.Int32[])" />
		public override async Task<OResult> WriteAsync(string address, int[] values)
		{
			return await WriteAsync(value: SnetHelper.ExtractTransformParameter(ref address, base.ByteTransform).TransByte(values), address: address);
