	/// <summary>
	/// 一个通用的日志接口，支持5个等级的日志消息写入，支持设置当前的消息等级，定义一个消息存储前的触发事件。<br />
	/// A general-purpose log interface, supports the writing of 5 levels of log messages, supports setting the current message level, and defining a trigger event before a message is stored.
	/// </summary>
	/// <remarks>
	/// 本组件的日志核心机制，如果您使用了本组件却不想使用本组件的日志组件功能，可以自己实现新的日志组件，只要继承本接口接口。其他常用的日志组件如下：（都是可以实现的）
	/// <list type="number">
	/// <item>Log4Net</item>
	/// <item>NLog</item>
	/// </list>
	/// </remarks>
	/// <example>
	/// 自己实例化操作，在Snet.Driver里面，可选三种类型
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example1" title="单文件实例化" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example2" title="限制文件大小实例化" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example3" title="日期存储实例化" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example4" title="基本的使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example5" title="所有日志不存储" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example6" title="仅存储ERROR等级" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example7" title="不指定路径" />
	/// Form的示例，存储日志的使用都是一样的，就是实例化的时候不一致，以下示例代码以单文件日志为例
	/// <code lang="cs" source="TestProject\Snet.DriverDemo\Snet\FormLogNet.cs" region="ILogNet" title="ILogNet示例" />
	/// </example>
	public interface ILogNet : IDisposable
	{
		/// <summary>
		/// 日志存储模式，1:单文件，2:按大小存储，3:按时间存储<br />
		/// Log storage mode, 1: single file, 2: storage by size, 3: storage by time
		/// </summary>
		LogSaveMode LogSaveMode { get; }

		/// <summary>
		/// 获取或设置当前的日志记录统计信息，如果你需要统计最近30天的日志，就需要对其实例化，详细参照<see cref="T:Snet.Driver.LogNet.LogStatistics" /><br />
		/// Get or set the current log record statistics. If you need to count the logs of the last 30 days, 
		/// you need to instantiate it. For details, please refer to <see cref="T:Snet.Driver.LogNet.LogStatistics" />
		/// </summary>
		LogStatistics LogNetStatistics { get; set; }

		/// <summary>
		/// 获取或设置当前的日志信息在存储的时候是否在控制台进行输出，默认不输出。<br />
		/// Gets or sets whether the current log information is output on the console when it is stored. It is not output by default.
		/// </summary>
		bool ConsoleOutput { get; set; }

		/// <summary>
		/// 获取或设置是否记录线程ID的数据信息，默认为 <c>True</c>，表示记录，否则，需要设置为 <c>False</c><br />
		/// Get or set whether to record the data information of the thread ID, the default is <c>True</c>, which means record, otherwise, it needs to be set to <c>False</c><br />
		/// </summary>
		bool LogThreadID { get; set; }

		/// <summary>
		/// 获取或设置在记录文件日志的时候，是否记录不可见字符STX(也即是ASCII字符集的0x02)。默认为 <c>True</c>, 也即是记录这个字符，在日志分析的时候，可以更加方便的分析。<br />
		/// Gets or sets whether to record the invisible character STX (that is, 0x02 of the ASCII character set) when recording the file log. 
		/// The default is <c>True</c>, that is, this character is recorded, which can be analyzed more conveniently during log analysis.
		/// </summary>
		bool LogStxAsciiCode { get; set; }

		/// <summary>
		/// 获取或设置当前日志时间的小时偏差信息，用来解决某些情况下时区设置异常导致记录时间一直不正确的问题，默认为 0，也就是不处理。可以为正数，也可以为负数。<br />
		/// Obtain or set the hourly deviation information of the current log time to solve the problem that the recording time has been incorrect due to abnormal time zone setting in some cases, 
		/// and the default is 0, that is, it is not processed. Can be positive or negative.
		/// </summary>
		int HourDeviation { get; set; }

		/// <summary>
		/// 当日志设置了<see cref="P:Snet.Driver.LogNet.ILogNet.ConsoleOutput" />后， 是否启用控制台颜色输出，默认启用<br />
		/// When the log sets <see cref="P:Snet.Driver.LogNet.ILogNet.ConsoleOutput" />, whether to enable console color output is enabled by default
		/// </summary>
		bool ConsoleColorEnable { get; set; }

		/// <summary>
		/// 获取或设置日志记录的最大缓存数量，默认为10000000条，当日志文件达到这个数量的时候，说明已经来不及存储日志到文件，直接丢弃日志<br />
		/// Get or set the maximum cache count for log records. The default is 10,000,000. When the log file reaches this number, it indicates that the logs can no longer be stored to the file and will be discarded.
		/// </summary>
		int MaxCacheCount { get; set; }

		/// <summary>
		/// 获取或设置日志文件的UTF8编码是否携带标记头信息，默认为 <c>True</c><br />
		/// Gets or sets whether the UTF8 encoding of the log file carries tag header information, which defaults to <c>True</c>
		/// </summary>
		bool EncoderShouldEmitUTF8Identifier { get; set; }

		/// <summary>
		/// 存储之前引发的事件，允许额外的操作，比如打印控制台，存储数据库等等<br />
		/// Store previously raised events, allowing additional operations, such as print console, store database, etc.
		/// </summary>
		event EventHandler<SnetEventArgs> BeforeSaveToFile;

		/// <summary>
		/// 通过指定消息等级，关键字，日志信息进行消息记录<br />
		/// Record messages by specifying message level, keywords, and log information
		/// </summary>
		/// <param name="degree">消息等级</param>
		/// <param name="keyWord">关键字</param>
		/// <param name="text">日志内容</param>
		void RecordMessage(SnetMessageDegree degree, string keyWord, string text);

		/// <summary>
		/// 写入一条解释性的信息，不属于消息等级控制的范畴<br />
		/// Write an explanatory message that is not part of message level control
		/// </summary>
		/// <param name="description">解释文本</param>
		void WriteDescrition(string description);

		/// <summary>
		/// 写入一条调试日志<br />
		/// Write a debug log
		/// </summary>
		/// <param name="text">日志内容</param>
		void WriteDebug(string text);

		/// <summary>
		/// 写入一条带关键字的调试日志<br />
		/// Write a debug log with keywords
		/// </summary>
		/// <param name="keyWord">关键字</param>
		/// <param name="text">日志内容</param>
		void WriteDebug(string keyWord, string text);

		/// <summary>
		/// 写入一条错误日志<br />
		/// Write an error log
		/// </summary>
		/// <param name="text">日志内容</param>
		void WriteError(string text);

		/// <summary>
		/// 写入一条带关键字的错误日志<br />
		/// Write an error log with keywords
		/// </summary>
		/// <param name="keyWord">关键字</param>
		/// <param name="text">日志内容</param>
		void WriteError(string keyWord, string text);

		/// <summary>
		/// 写入一条带关键字的异常信息<br />
		/// Write an exception log with keywords
		/// </summary>
		/// <param name="keyWord">关键字</param>
		/// <param name="ex">异常</param>
		void WriteException(string keyWord, Exception ex);

		/// <summary>
		/// 写入一条带关键字和描述信息的异常信息<br />
		/// Write an exception log with keywords and text
		/// </summary>
		/// <param name="keyWord">关键字</param>
		/// <param name="text">内容</param>
		/// <param name="ex">异常</param>
		void WriteException(string keyWord, string text, Exception ex);

		/// <summary>
		/// 写入一条致命日志<br />
		/// Write an fatal log
		/// </summary>
		/// <param name="text">日志内容</param>
		void WriteFatal(string text);

		/// <summary>
		/// 写入一条带关键字的致命日志<br />
		/// Write an fatal log with keywords
		/// </summary>
		/// <param name="keyWord">关键字</param>
		/// <param name="text">日志内容</param>
		void WriteFatal(string keyWord, string text);

		/// <summary>
		/// 写入一条普通日志<br />
		/// Write an infomation log
		/// </summary>
		/// <param name="text">日志内容</param>
		void WriteInfo(string text);

		/// <summary>
		/// 写入一条带关键字的普通日志<br />
		/// Write an information log with keywords
		/// </summary>
		/// <param name="keyWord">关键字</param>
		/// <param name="text">日志内容</param>
		void WriteInfo(string keyWord, string text);

		/// <summary>
		/// 写入一行换行符<br />
		/// Write a newline
		/// </summary>
		void WriteNewLine();

		/// <summary>
		/// 写入任意字符串<br />
		/// Write arbitrary string
		/// </summary>
		/// <param name="text">文本</param>
		void WriteAnyString(string text);

		/// <summary>
		/// 写入一条警告日志<br />
		/// Write an warn log
		/// </summary>
		/// <param name="text">日志内容</param>
		void WriteWarn(string text);

		/// <summary>
		/// 写入一条带关键字的警告日志<br />
		/// Write an warn log  with keywords
		/// </summary>
		/// <param name="keyWord">关键字</param>
		/// <param name="text">日志内容</param>
		void WriteWarn(string keyWord, string text);

		/// <summary>
		/// 设置日志的存储等级，高于该等级的才会被存储<br />
		/// Set the storage level of the logs. Only the logs above this level will be stored.
		/// </summary>
		/// <param name="degree">登记信息</param>
		void SetMessageDegree(SnetMessageDegree degree);

		/// <summary>
