		/// Filter out the logs of the specified keywords, the information is not stored, but the <see cref="E:Snet.Driver.LogNet.ILogNet.BeforeSaveToFile" /> event is still triggered
		/// </summary>
		/// <param name="keyword">关键字</param>
		void FiltrateKeyword(string keyword);

		/// <summary>
		/// 移除过滤的关键字存储<br />
		/// Remove filtered keyword storage
		/// </summary>
		/// <param name="keyword">关键字</param>
		void RemoveFiltrate(string keyword);
