	/// <summary>
	/// 日志存储类的基类，提供一些基础的服务
	/// </summary>
	/// <remarks>
	/// 基于此类可以实现任意的规则的日志存储规则，欢迎大家补充实现，本组件实现了3个日志类
	/// <list type="number">
	/// <item>单文件日志类 <see cref="T:Snet.Driver.LogNet.LogNetSingle" /></item>
	/// <item>根据文件大小的类 <see cref="T:Snet.Driver.LogNet.LogNetFileSize" /></item>
	/// <item>根据时间进行存储的类 <see cref="T:Snet.Driver.LogNet.LogNetDateTime" /></item>
	/// </list>
	/// </remarks>
	public abstract class LogNetBase : IDisposable
	{
		/// <summary>
		/// 文件存储的锁
		/// </summary>
		protected SimpleHybirdLock m_fileSaveLock;

		private SnetMessageDegree m_messageDegree = SnetMessageDegree.DEBUG;

		private Queue<SnetMessageItem> m_WaitForSave;

		private SimpleHybirdLock m_simpleHybirdLock;

		private int m_SaveStatus;

		private List<string> filtrateKeyword;

		private object filtrateLock;

		private string lastLogSaveFileName = string.Empty;

		private int lastConsoleDegree = -1;

		private bool disposedValue;

		private long dropLogCount;

		private int maxCacheCount = 10000000;

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.LogSaveMode" />
		public LogSaveMode LogSaveMode { get; protected set; }

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.LogNetStatistics" />
		public LogStatistics LogNetStatistics { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.ConsoleOutput" />
		public bool ConsoleOutput { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.LogThreadID" />
		public bool LogThreadID { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.LogStxAsciiCode" />
		public bool LogStxAsciiCode { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.HourDeviation" />
		public int HourDeviation { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.EncoderShouldEmitUTF8Identifier" />
		public bool EncoderShouldEmitUTF8Identifier { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.ConsoleColorEnable" />
		public bool ConsoleColorEnable { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.LogNet.ILogNet.MaxCacheCount" />
		public int MaxCacheCount
		{
			get
			{
				return maxCacheCount;
			}
			set
			{
				if (value <= 100)
				{
					throw new ArgumentException("MaxCacheCount must be greater than 100");
				}
				maxCacheCount = value;
			}
		}

		/// <inheritdoc cref="E:Snet.Driver.LogNet.ILogNet.BeforeSaveToFile" />
		public event EventHandler<SnetEventArgs> BeforeSaveToFile;

		/// <summary>
		/// 实例化一个日志对象<br />
		/// Instantiate a log object
		/// </summary>
		public LogNetBase()
		{
			m_fileSaveLock = new SimpleHybirdLock();
			m_simpleHybirdLock = new SimpleHybirdLock();
			m_WaitForSave = new Queue<SnetMessageItem>();
			filtrateKeyword = new List<string>();
			filtrateLock = new object();
		}

		private void OnBeforeSaveToFile(SnetEventArgs args)
		{
			BeforeSaveToFile?.Invoke(this, args);
		}

		/// <inheritdoc cref="M:Snet.Driver.LogNet.ILogNet.WriteDebug(System.String)" />
		public void WriteDebug(string text)
		{
			WriteDebug(string.Empty, text);
		}

		/// <inheritdoc cref="M:Snet.Driver.LogNet.ILogNet.WriteDebug(System.String,System.String)" />
		public void WriteDebug(string keyWord, string text)
		{
			RecordMessage(SnetMessageDegree.DEBUG, keyWord, text);
		}

		/// <inheritdoc cref="M:Snet.Driver.LogNet.ILogNet.WriteInfo(System.String)" />
