		/// <summary>
		/// 获取当前因为缓存过大导致被过滤掉的日志数量<br />
		/// Get the number of logs currently filtered out due to excessive caching
		/// </summary>
		/// <returns>日志数量</returns>
		public long GetDropLogCount()
		{
			return dropLogCount;
		}

		private void WriteToFile(SnetMessageDegree degree, string keyword, string text)
		{
			if (degree <= m_messageDegree)
			{
				SnetMessageItem snetMessageItem = GetSnetMessageItem(degree, keyword, text);
				AddItemToCache(snetMessageItem, start: true);
			}
		}

		private void AddItemToCache(SnetMessageItem item, bool start)
		{
			m_simpleHybirdLock.Enter();
			if (m_WaitForSave.Count >= MaxCacheCount)
			{
				Interlocked.Increment(ref dropLogCount);
			}
			else
			{
				m_WaitForSave.Enqueue(item);
			}
			m_simpleHybirdLock.Leave();
			if (start)
			{
				StartSaveFile();
			}
		}

		private void StartSaveFile()
		{
			if (Interlocked.CompareExchange(ref m_SaveStatus, 1, 0) == 0)
			{
				ThreadPool.QueueUserWorkItem(ThreadPoolSaveFile, null);
			}
		}

		private SnetMessageItem GetAndRemoveLogItem()
		{
			SnetMessageItem result = null;
			m_simpleHybirdLock.Enter();
			try
			{
				result = ((m_WaitForSave.Count > 0) ? m_WaitForSave.Dequeue() : null);
			}
			catch
			{
			}
			m_simpleHybirdLock.Leave();
			return result;
		}

		private List<SnetMessageItem> GetAndRemoveLogItemArray()
		{
			List<SnetMessageItem> list = new List<SnetMessageItem>();
			m_simpleHybirdLock.Enter();
			try
			{
				while (m_WaitForSave.Count > 0)
				{
					list.Add(m_WaitForSave.Dequeue());
				}
			}
			catch
			{
			}
			m_simpleHybirdLock.Leave();
			return list;
		}

		private void SetConsoleWriteForeColor(SnetMessageDegree degree)
		{
			if (!ConsoleColorEnable)
			{
				return;
			}
			if (lastConsoleDegree < 0)
			{
				lastConsoleDegree = (int)degree;
			}
			if (lastConsoleDegree != (int)degree)
			{
				lastConsoleDegree = (int)degree;
				switch (degree)
				{
				case SnetMessageDegree.DEBUG:
					Console.ForegroundColor = ConsoleColor.DarkGray;
					break;
				case SnetMessageDegree.INFO:
					Console.ForegroundColor = ConsoleColor.White;
					break;
				case SnetMessageDegree.WARN:
					Console.ForegroundColor = ConsoleColor.Yellow;
					break;
				case SnetMessageDegree.ERROR:
					Console.ForegroundColor = ConsoleColor.Red;
					break;
				case SnetMessageDegree.FATAL:
					Console.ForegroundColor = ConsoleColor.DarkRed;
					break;
				default:
					Console.ForegroundColor = ConsoleColor.White;
					break;
				}
			}
		}

		private void ConsoleWriteLog(SnetMessageItem log)
		{
			SetConsoleWriteForeColor(log.Degree);
			Console.WriteLine(SnetMessageFormat(log, writeFile: false));
		}

		private void ThreadPoolSaveFile(object obj)
		{
			SnetMessageItem andRemoveLogItem = GetAndRemoveLogItem();
			m_fileSaveLock.Enter();
			string fileSaveName = GetFileSaveName();
			bool createNewLogFile = false;
			if (!string.IsNullOrEmpty(fileSaveName))
			{
				if (fileSaveName != lastLogSaveFileName)
				{
					createNewLogFile = true;
					lastLogSaveFileName = fileSaveName;
				}
				StreamWriter streamWriter = null;
				int num = 0;
				try
				{
					streamWriter = new StreamWriter(fileSaveName, append: true, EncoderShouldEmitUTF8Identifier ? Encoding.UTF8 : new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
					while (andRemoveLogItem != null)
					{
						if (!andRemoveLogItem.HasLogOutput)
						{
							andRemoveLogItem.HasLogOutput = true;
							if (ConsoleOutput)
							{
								ConsoleWriteLog(andRemoveLogItem);
							}
							OnBeforeSaveToFile(new SnetEventArgs
							{
								SnetMessage = andRemoveLogItem
							});
							LogNetStatistics?.StatisticsAdd(1L);
						}
						bool flag = true;
						if (filtrateKeyword.Count > 0)
						{
							lock (filtrateLock)
							{
								flag = !filtrateKeyword.Contains(andRemoveLogItem.KeyWord);
							}
						}
						if (andRemoveLogItem.Cancel)
						{
							flag = false;
						}
						if (flag)
						{
							streamWriter.Write(SnetMessageFormat(andRemoveLogItem, writeFile: true));
							streamWriter.Write(Environment.NewLine);
							num++;
						}
						andRemoveLogItem = GetAndRemoveLogItem();
					}
					if (num > 0)
					{
						streamWriter.Flush();
					}
				}
				catch (Exception ex)
				{
					if (ex is DirectoryNotFoundException)
					{
						try
						{
							string directoryName = Path.GetDirectoryName(fileSaveName);
							if (!string.IsNullOrEmpty(directoryName) && !Directory.Exists(directoryName))
							{
								Directory.CreateDirectory(directoryName);
							}
						}
						catch
						{
						}
					}
					if (andRemoveLogItem != null)
					{
						Interlocked.Increment(ref andRemoveLogItem.WriteRetryTimes);
						AddItemToCache(andRemoveLogItem, start: false);
					}
				}
				finally
				{
					streamWriter?.Dispose();
				}
			}
			else if (ConsoleOutput)
			{
				if (andRemoveLogItem != null)
				{
					ConsoleWriteLog(andRemoveLogItem);
					OnBeforeSaveToFile(new SnetEventArgs
					{
						SnetMessage = andRemoveLogItem
					});
				}
				List<SnetMessageItem> andRemoveLogItemArray = GetAndRemoveLogItemArray();
				while (andRemoveLogItemArray.Count > 0)
				{
					StringBuilder stringBuilder = new StringBuilder();
					SnetMessageDegree degree = andRemoveLogItemArray[0].Degree;
					for (int i = 0; i < andRemoveLogItemArray.Count; i++)
					{
						if (andRemoveLogItemArray[i].Degree != degree)
						{
							SetConsoleWriteForeColor(degree);
							Console.Write(stringBuilder.ToString());
							degree = andRemoveLogItemArray[i].Degree;
							stringBuilder = new StringBuilder();
						}
						stringBuilder.AppendLine(SnetMessageFormat(andRemoveLogItemArray[i], writeFile: false));
						if (i >= andRemoveLogItemArray.Count - 1)
						{
							SetConsoleWriteForeColor(degree);
							Console.Write(stringBuilder.ToString());
						}
						OnBeforeSaveToFile(new SnetEventArgs
						{
							SnetMessage = andRemoveLogItemArray[i]
						});
					}
					andRemoveLogItemArray = GetAndRemoveLogItemArray();
				}
			}
			else
			{
				while (andRemoveLogItem != null)
				{
					if (ConsoleOutput)
					{
						ConsoleWriteLog(andRemoveLogItem);
					}
					OnBeforeSaveToFile(new SnetEventArgs
					{
						SnetMessage = andRemoveLogItem
					});
					andRemoveLogItem = GetAndRemoveLogItem();
				}
			}
			m_fileSaveLock.Leave();
			Interlocked.Exchange(ref m_SaveStatus, 0);
			OnWriteCompleted(createNewLogFile);
			if (m_WaitForSave.Count > 0)
			{
				SnetHelper.ThreadSleep(0);
				StartSaveFile();
			}
		}

		/// <summary>
		/// 根据需要存储的日志消息，获取实际存储的字符串，重写本方法就可以自定义输出内容<br />
		/// According to the log message that needs to be stored, get the actual stored string, and the rewrite method can customize the output content
		/// </summary>
		/// <param name="SnetMessage">等待存储或是输出的日志对象</param>
		/// <param name="writeFile">是否输出到文件里</param>
		/// <returns>最终等待存储的字符串内容</returns>
		protected virtual string SnetMessageFormat(SnetMessageItem SnetMessage, bool writeFile)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (SnetMessage.Degree != SnetMessageDegree.None)
			{
				if (writeFile && LogStxAsciiCode)
				{
					stringBuilder.Append("\u0002");
				}
				stringBuilder.Append("[");
				stringBuilder.Append(LogNetManagment.GetDegreeDescription(SnetMessage.Degree));
				stringBuilder.Append("] ");
				stringBuilder.Clear();
				stringBuilder.Append(SnetMessage.Time.ToString("yyyy-MM-dd HH:mm:ss.ffffff"));
				stringBuilder.Append(" ");
				if (LogThreadID)
				{
					stringBuilder.Append("Thread:[");
					stringBuilder.Append(SnetMessage.ThreadId.ToString("D3"));
					stringBuilder.Append("] ");
				}
				if (SnetMessage.WriteRetryTimes == 2)
				{
					stringBuilder.Append("[Retry] ");
				}
				else if (SnetMessage.WriteRetryTimes > 2)
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(9, 1, stringBuilder2);
					handler.AppendLiteral("[Retry:");
					handler.AppendFormatted(SnetMessage.WriteRetryTimes);
					handler.AppendLiteral("] ");
					stringBuilder2.Append(ref handler);
				}
				if (!string.IsNullOrEmpty(SnetMessage.KeyWord))
				{
					stringBuilder.Append(SnetMessage.KeyWord);
					stringBuilder.Append(" : ");
				}
			}
			stringBuilder.Append(SnetMessage.Text);
			return stringBuilder.ToString();
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"LogNetBase[{LogSaveMode}]";
		}

		/// <inheritdoc />
		protected virtual string GetFileSaveName()
		{
			return string.Empty;
		}

		/// <summary>
		/// 当写入文件完成的时候触发，这时候已经释放了文件的句柄了。<br />
		/// Triggered when writing to the file is complete, and the file handle has been released.
		/// </summary>
		protected virtual void OnWriteCompleted(bool createNewLogFile)
		{
		}

		private SnetMessageItem GetSnetMessageItem(SnetMessageDegree degree, string keyWord, string text)
		{
			if (HourDeviation == 0)
			{
				return new SnetMessageItem
				{
					KeyWord = keyWord,
					Degree = degree,
					Text = text,
					ThreadId = Thread.CurrentThread.ManagedThreadId
				};
			}
			return new SnetMessageItem
			{
				KeyWord = keyWord,
				Degree = degree,
				Text = text,
				ThreadId = Thread.CurrentThread.ManagedThreadId,
				Time = DateTime.Now.AddHours(HourDeviation)
			};
		}

		private int CalculateStringOccupyLength(string str)
		{
			if (string.IsNullOrEmpty(str))
			{
				return 0;
			}
			int num = 0;
			for (int i = 0; i < str.Length; i++)
			{
				num = ((str[i] < '一' || str[i] > '龻') ? (num + 1) : (num + 2));
			}
			return num;
		}

		private void AppendCharToStringBuilder(StringBuilder sb, char c, int count)
		{
			for (int i = 0; i < count; i++)
			{
				sb.Append(c);
			}
		}

		/// <summary>
		/// 释放资源
		/// </summary>
		/// <param name="disposing">是否初次调用</param>
		protected virtual void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				if (disposing)
				{
					BeforeSaveToFile = null;
					m_simpleHybirdLock.Enter();
					m_WaitForSave.Clear();
					m_simpleHybirdLock.Leave();
					m_simpleHybirdLock.Dispose();
					m_fileSaveLock.Dispose();
				}
				disposedValue = true;
			}
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			Dispose(disposing: true);
		}
	}
	/// <summary>
	/// 一个日志组件，可以根据时间来区分不同的文件存储<br />
	/// A log component that can distinguish different file storages based on time
	/// </summary>
	/// <remarks>
	/// 此日志实例将根据日期时间来进行分类，支持的时间分类如下：分钟, 小时, 天, 周, 月份, 季度, 年<br />
	/// 当然你也可以指定允许存在多少个日志文件，比如我允许存在最多10个文件，如果你的日志是根据天来分文件的，那就是10天的数据。
	/// 同理，如果你的日志是根据年来分文件的，那就是10年的日志文件。<br /><br />
	/// 2025年9月9日更新: 路径里支持日期时间的格式化，支持动态路径，例如我希望按照"年"，"月"，"日"目录逐级存储，可以指定路径：D:\\Logs\\{yyyy}\\{MM}\\{dd}\\ 日志文件再按小时存储
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example3" title="日期存储实例化" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example4" title="基本的使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example5" title="所有日志不存储" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example6" title="仅存储ERROR等级" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example7" title="不指定路径" />
	/// </example>
	public class LogNetDateTime : LogPathBase, ILogNet, IDisposable
	{
		private GenerateMode generateMode = GenerateMode.ByEveryYear;

		private int fileSize = -1;

		/// <summary>
		/// 实例化一个根据时间存储的日志组件，需要指定每个文件的存储时间范围<br />
		/// Instantiate a log component based on time, you need to specify the storage time range for each file
		/// </summary>
		/// <param name="filePath">文件存储的路径</param>
		/// <param name="generateMode">存储文件的间隔</param>
		/// <param name="fileQuantity">指定当前的日志文件数量上限，如果小于0，则不限制，文件一直增加，如果设置为10，就限制最多10个文件，会删除最近时间的10个文件之外的文件。</param>
		public LogNetDateTime(string filePath, GenerateMode generateMode = GenerateMode.ByEveryYear, int fileQuantity = -1)
		{
			base.filePath = filePath;
			this.generateMode = generateMode;
			base.LogSaveMode = LogSaveMode.Time;
			controlFileQuantity = fileQuantity;
			if (string.IsNullOrEmpty(filePath))
			{
				return;
			}
			if (filePath.Contains("{") && filePath.Contains("}"))
			{
				string path = Regex.Replace(filePath, "{[yYmMdDHhsS]+}", DateMatchEvaluator);
				if (!Directory.Exists(path))
				{
					Directory.CreateDirectory(path);
				}
			}
			else if (!Directory.Exists(filePath))
			{
				Directory.CreateDirectory(filePath);
			}
		}

		/// <summary>
		/// 实例化一个根据时间存储的日志组件，需要指定每个文件的存储时间范围<br />
		/// Instantiate a log component based on time, you need to specify the storage time range for each file
		/// </summary>
		/// <param name="filePath">文件存储的路径</param>
		/// <param name="generateMode">存储文件的间隔</param>
		/// <param name="timeQuantity">指定当前的日志文件的时间单位数量，如果小于0，则不限制，文件一直增加，如果设置为10，就限制最多10个单位的文件，会删除最近时间的10天之外的文件。</param>
		/// <param name="fileSize">指定文件的大小</param>
		public LogNetDateTime(string filePath, GenerateMode generateMode, int timeQuantity, int fileSize)
			: this(filePath, generateMode, timeQuantity)
		{
			this.fileSize = fileSize;
		}

		private string DateMatchEvaluator(Match match)
		{
			return DateTime.Now.ToString(match.Value.Substring(1, match.Value.Length - 2));
		}

		private string GetFileSaveName(int index)
		{
			if (string.IsNullOrEmpty(filePath))
			{
				return string.Empty;
			}
			string text = ((index > 0) ? $"({index}).log" : ".log");
			string path = Regex.Replace(filePath, "{[yYmMdDHhsS]+}", DateMatchEvaluator);
			switch (generateMode)
			{
			case GenerateMode.ByEveryMinute:
				return Path.Combine(path, LogNetManagment.LogFileHeadString + DateTime.Now.ToString("yyyyMMddHHmm") + text);
			case GenerateMode.ByEveryHour:
				return Path.Combine(path, LogNetManagment.LogFileHeadString + DateTime.Now.ToString("yyyyMMddHH") + text);
			case GenerateMode.ByEveryDay:
				return Path.Combine(path, LogNetManagment.LogFileHeadString + DateTime.Now.ToString("yyyyMMdd") + text);
			case GenerateMode.ByEveryWeek:
			{
				int weekOfYear = new GregorianCalendar().GetWeekOfYear(DateTime.Now, CalendarWeekRule.FirstDay, DayOfWeek.Monday);
				return Path.Combine(path, LogNetManagment.LogFileHeadString + DateTime.Now.Year + "_W" + weekOfYear + text);
			}
			case GenerateMode.ByEveryMonth:
				return Path.Combine(path, LogNetManagment.LogFileHeadString + DateTime.Now.ToString("yyyyMM") + text);
			case GenerateMode.ByEverySeason:
				return Path.Combine(path, LogNetManagment.LogFileHeadString + DateTime.Now.Year + "_Q" + (DateTime.Now.Month / 3 + 1) + text);
			case GenerateMode.ByEveryYear:
				return Path.Combine(path, LogNetManagment.LogFileHeadString + DateTime.Now.Year + text);
			default:
				return string.Empty;
			}
		}

		/// <inheritdoc />
		protected override string GetFileSaveName()
		{
			if (string.IsNullOrEmpty(filePath))
			{
				return string.Empty;
			}
			if (fileSize <= 0)
			{
				return GetFileSaveName(0);
			}
			int num = 0;
			string fileSaveName;
			while (true)
			{
				fileSaveName = GetFileSaveName(num);
				if (!File.Exists(fileSaveName))
				{
					break;
				}
				try
				{
					if (new FileInfo(fileSaveName).Length < fileSize)
					{
						return fileSaveName;
					}
				}
				catch
				{
					return fileSaveName;
				}
				num++;
			}
			return fileSaveName;
		}

		private DateTime GetDeleteTime()
		{
			return generateMode switch
			{
				GenerateMode.ByEveryMinute => DateTime.Now.AddMinutes(-controlFileQuantity), 
				GenerateMode.ByEveryHour => DateTime.Now.AddHours(-controlFileQuantity), 
				GenerateMode.ByEveryDay => DateTime.Now.AddDays(-controlFileQuantity), 
				GenerateMode.ByEveryWeek => DateTime.Now.AddDays(-controlFileQuantity * 7), 
				GenerateMode.ByEveryMonth => DateTime.Now.AddMonths(-controlFileQuantity), 
				GenerateMode.ByEverySeason => DateTime.Now.AddMonths(-controlFileQuantity * 3), 
				GenerateMode.ByEveryYear => DateTime.Now.AddYears(-controlFileQuantity), 
				_ => DateTime.Now.AddDays(-controlFileQuantity), 
			};
		}

		/// <inheritdoc />
		public override string[] GetExistLogFileNames()
		{
			if (!string.IsNullOrEmpty(filePath))
			{
				return Directory.GetFiles(Regex.Replace(filePath, "{[yYmMdDHhsS]+}", DateMatchEvaluator), LogNetManagment.LogFileHeadString + "*.txt");
			}
			return new string[0];
		}

		/// <inheritdoc />
		protected override void OnWriteCompleted(bool createNewLogFile)
		{
			if (fileSize <= 0)
			{
				base.OnWriteCompleted(createNewLogFile);
			}
			else
			{
				if (!createNewLogFile || controlFileQuantity <= 1)
				{
					return;
				}
				try
				{
					string[] existLogFileNames = GetExistLogFileNames();
					if (existLogFileNames.Length > controlFileQuantity)
					{
						List<FileInfo> list = new List<FileInfo>();
						for (int i = 0; i < existLogFileNames.Length; i++)
						{
							list.Add(new FileInfo(existLogFileNames[i]));
						}
						list.Sort((FileInfo m, FileInfo n) => m.CreationTime.CompareTo(n.CreationTime));
						DateTime deleteTime = GetDeleteTime();
						for (int num = 0; num < list.Count && list[num].CreationTime < deleteTime; num++)
						{
							File.Delete(list[num].FullName);
						}
					}
				}
				catch
				{
				}
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"LogNetDateTime[{generateMode}]";
		}
	}
	/// <summary>
	/// 日志存储回调的异常信息
	/// </summary>
	public class LogNetException : Exception
	{
		/// <summary>
		/// 使用其他的异常信息来初始化日志异常
		/// </summary>
		/// <param name="innerException">异常信息</param>
		public LogNetException(Exception innerException)
			: base(innerException.Message, innerException)
		{
		}
	}
	/// <summary>
	/// 根据文件的大小来存储日志信息，当前的文件大小增长超过设定值，就会创建新的文件来存储，新的文件命名为当前时间。<br />
	/// Log information is stored according to the size of the file. If the current file size exceeds the set value, a new file is created for storage, and the new file is named the current time.
	/// </summary>
	/// <remarks>
	/// 此日志的实例是根据文件的大小储存，例如设置了2M，每隔2M，系统将生成一个新的日志文件。当然你也可以指定允许存在多少个日志文件，
	/// 比如我允许存在最多10个文件，那总量就是20M，旧的文件会被删除掉。
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example2" title="限制文件大小实例化" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example4" title="基本的使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example5" title="所有日志不存储" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example6" title="仅存储ERROR等级" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example7" title="不指定路径" />
	/// </example>
	public class LogNetFileSize : LogPathBase, ILogNet, IDisposable
	{
		private int fileMaxSize = 2097152;

		private int currentFileSize;

		/// <summary>
		/// 实例化一个根据文件大小生成新文件的，默认是2M大的文件<br />
		/// Instantiate a new file based on the file size. The default is 2M.
		/// </summary>
		/// <param name="filePath">日志文件的保存路径</param>
		/// <param name="fileMaxSize">每个日志文件的最大大小，默认2M</param>
		/// <param name="fileQuantity">指定当前的日志文件数量上限，如果小于0，则不限制，文件一直增加，如果设置为10，就限制最多10个文件，会删除最近时间的10个文件之外的文件。</param>
		public LogNetFileSize(string filePath, int fileMaxSize = 2097152, int fileQuantity = -1)
		{
			base.filePath = filePath;
			this.fileMaxSize = fileMaxSize;
			controlFileQuantity = fileQuantity;
			base.LogSaveMode = LogSaveMode.FileFixedSize;
			if (!string.IsNullOrEmpty(filePath) && !Directory.Exists(filePath))
			{
				Directory.CreateDirectory(filePath);
			}
		}

		/// <inheritdoc />
		protected override string GetFileSaveName()
		{
			if (string.IsNullOrEmpty(filePath))
			{
				return string.Empty;
			}
			if (string.IsNullOrEmpty(fileName))
			{
				fileName = GetLastAccessFileName();
			}
			if (File.Exists(fileName))
			{
				FileInfo fileInfo = new FileInfo(fileName);
				if (fileInfo.Length > fileMaxSize)
				{
					fileName = GetDefaultFileName();
				}
				else
				{
					currentFileSize = (int)fileInfo.Length;
				}
			}
			return fileName;
		}

		/// <summary>
		/// 获取之前保存的日志文件，如果文件大小超过了设定值，将会生成新的文件名称<br />
		/// Obtain the previously saved log file. If the file size exceeds the set value, a new file name will be generated
		/// </summary>
		/// <returns>文件名称</returns>
		private string GetLastAccessFileName()
		{
			string[] existLogFileNames = GetExistLogFileNames();
			foreach (string result in existLogFileNames)
			{
				FileInfo fileInfo = new FileInfo(result);
				if (fileInfo.Length < fileMaxSize)
				{
					currentFileSize = (int)fileInfo.Length;
					return result;
				}
			}
			return GetDefaultFileName();
		}

		/// <summary>
		/// 获取一个新的默认的文件名称<br />
		/// Get a new default file name
		/// </summary>
		/// <returns>完整的文件名</returns>
		private string GetDefaultFileName()
		{
			return Path.Combine(filePath, LogNetManagment.LogFileHeadString + DateTime.Now.ToString("yyyyMMddHHmmss") + ".txt");
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"LogNetFileSize[{fileMaxSize}]";
		}
	}
	/// <summary>
	/// 日志类的管理器，提供了基本的功能代码。<br />
	/// The manager of the log class provides the basic function code.
	/// </summary>
	public class LogNetManagment
	{
		/// <summary>
		/// 日志文件的头标志
		/// </summary>
		public static string LogFileHeadString = "";

		/// <summary>
		/// 公开的一个静态变量，允许随意的设置<br />
		/// Public static variable, allowing arbitrary setting
		/// </summary>
		public static ILogNet LogNet { get; set; }

		internal static string GetDegreeDescription(SnetMessageDegree degree)
		{
			return degree switch
			{
				SnetMessageDegree.DEBUG => StringResources.Language.LogNetDebug, 
				SnetMessageDegree.INFO => StringResources.Language.LogNetInfo, 
				SnetMessageDegree.WARN => StringResources.Language.LogNetWarn, 
				SnetMessageDegree.ERROR => StringResources.Language.LogNetError, 
				SnetMessageDegree.FATAL => StringResources.Language.LogNetFatal, 
				SnetMessageDegree.None => StringResources.Language.LogNetAbandon, 
				_ => StringResources.Language.LogNetAbandon, 
			};
		}

		/// <summary>
		/// 通过异常文本格式化成字符串用于保存或发送<br />
		/// Formatted as a string with exception text for saving or sending
		/// </summary>
		/// <param name="text">文本消息</param>
		/// <param name="ex">异常</param>
		/// <returns>异常最终信息</returns>
		public static string GetSaveStringFromException(string text, Exception ex)
		{
			StringBuilder stringBuilder = new StringBuilder(text);
			if (ex != null)
			{
				if (!string.IsNullOrEmpty(text))
				{
					stringBuilder.Append(" : ");
				}
				try
				{
					stringBuilder.Append(StringResources.Language.ExceptionMessage);
					stringBuilder.Append(ex.Message);
					stringBuilder.Append(Environment.NewLine);
					stringBuilder.Append(StringResources.Language.ExceptionSource);
					stringBuilder.Append(ex.Source);
					stringBuilder.Append(Environment.NewLine);
					stringBuilder.Append(StringResources.Language.ExceptionStackTrace);
					stringBuilder.Append(ex.StackTrace);
					stringBuilder.Append(Environment.NewLine);
					stringBuilder.Append(StringResources.Language.ExceptionType);
					stringBuilder.Append(ex.GetType().ToString());
					stringBuilder.Append(Environment.NewLine);
					stringBuilder.Append(StringResources.Language.ExceptionTargetSite);
					stringBuilder.Append(ex.TargetSite?.ToString());
				}
				catch
				{
				}
				stringBuilder.Append(Environment.NewLine);
				stringBuilder.Append("\u0002/=================================================[    Exception    ]================================================/");
			}
			try
			{
				return stringBuilder.ToString();
			}
			catch
			{
				return string.IsNullOrEmpty(text) ? ex.Message : (text + ":" + ex.Message);
			}
		}
	}
	/// <summary>
	/// 单日志文件对象，所有的日志信息的记录都会写入一个文件里面去。文件名指定为空的时候，自动不存储文件。<br />
	/// Single log file object, all log information records will be written to a file. When the file name is specified as empty, the file is not stored automatically.
	/// </summary>
	/// <remarks>
	/// 此日志实例化需要指定一个完整的文件路径，当需要记录日志的时候调用方法，会使得日志越来越大，对于写入的性能没有太大影响，但是会影响文件读取。
	/// </remarks>
	/// <example>
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example1" title="单文件实例化" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example4" title="基本的使用" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example5" title="所有日志不存储" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example6" title="仅存储ERROR等级" />
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogNetSingle.cs" region="Example7" title="不指定路径" />
	/// </example>
	public class LogNetSingle : LogNetBase, ILogNet, IDisposable
	{
		private readonly string fileName = string.Empty;

		/// <summary>
		/// 实例化一个单文件日志的对象，如果日志的路径为空，那么就不存储数据，只触发<see cref="E:Snet.Driver.LogNet.LogNetBase.BeforeSaveToFile" />事件<br />
		/// Instantiate a single file log object. If the log path is empty, then no data is stored and only the <see cref="E:Snet.Driver.LogNet.LogNetBase.BeforeSaveToFile" /> event is triggered.
		/// </summary>
		/// <param name="filePath">文件的路径</param>
		public LogNetSingle(string filePath)
		{
			fileName = filePath;
			base.LogSaveMode = LogSaveMode.SingleFile;
			if (!string.IsNullOrEmpty(fileName))
			{
				FileInfo fileInfo = new FileInfo(filePath);
				if (!Directory.Exists(fileInfo.DirectoryName))
				{
					Directory.CreateDirectory(fileInfo.DirectoryName);
				}
			}
		}

		/// <summary>
		/// 单日志文件允许清空日志内容<br />
		/// Single log file allows clearing log contents
		/// </summary>
		public void ClearLog()
		{
			m_fileSaveLock.Enter();
			try
			{
				if (!string.IsNullOrEmpty(fileName))
				{
					File.Create(fileName).Dispose();
				}
			}
			catch
			{
				throw;
			}
			finally
			{
				m_fileSaveLock.Leave();
			}
		}

		/// <summary>
		/// 获取单日志文件的所有保存记录<br />
		/// Get all saved records of a single log file
		/// </summary>
		/// <returns>字符串信息</returns>
		public string GetAllSavedLog()
		{
			string result = string.Empty;
			m_fileSaveLock.Enter();
			try
			{
				if (!string.IsNullOrEmpty(fileName) && File.Exists(fileName))
				{
					StreamReader streamReader = new StreamReader(fileName, Encoding.UTF8);
					result = streamReader.ReadToEnd();
					streamReader.Dispose();
				}
			}
			catch
			{
				throw;
			}
			finally
			{
				m_fileSaveLock.Leave();
			}
			return result;
		}

		/// <summary>
		/// 获取所有的日志文件数组，对于单日志文件来说就只有一个<br />
		/// Get all log file arrays, only one for a single log file
		/// </summary>
		/// <returns>字符串数组，包含了所有的存在的日志数据</returns>
		public string[] GetExistLogFileNames()
		{
			return new string[1] { fileName };
		}

		/// <inheritdoc />
		protected override string GetFileSaveName()
		{
			return fileName;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return "LogNetSingle[" + fileName + "]";
		}
	}
	/// <summary>
	/// 日志操作扩展类
	/// </summary>
	public class LogOperate : IDisposable, IAsyncDisposable
	{
		/// <summary>
		/// 通信对象
		/// </summary>
		private object baseObject;

		/// <summary>
		/// 二进制通信对象
		/// </summary>
		private BinaryCommunication baseLog;

		/// <summary>
		/// 日志的文件夹名
		/// </summary>
		private string folderName;

		/// <summary>
		/// 操作库的名称
		/// </summary>
		private string operateLibName;

		/// <summary>
		/// 是否启动底层日志输出至文件
		/// </summary>
		private bool outLog = true;

		/// <summary>
		/// 是否启控制台输出
		/// </summary>
		private bool consoleOutLog;

		/// <summary>
		/// 信号量，用于控制对日志文件的并发访问，确保多线程环境下日志写入线程安全。<br />
		/// 初始计数和最大计数都设置为 1，相当于一个异步锁（Mutex），同一时间只允许一个线程进入临界区。
		/// </summary>
		private readonly SemaphoreSlim logSemaphore = new SemaphoreSlim(1, 1);

		/// <summary>
		/// 缓存当前日期字符串（格式：yyyy-MM-dd），避免频繁调用 DateTime.Now.ToString()。<br />
		/// 初始化时设置为当天日期，后续在跨天时才会更新。
		/// </summary>
		private string cachedDate = DateTime.Today.ToString("yyyy-MM-dd");

		/// <summary>
		/// 缓存上次的日期对象（只包含年月日，不含时分秒），用于判断是否跨天。<br />
		/// 与 cachedDate 配合使用，避免重复字符串转换。
		/// </summary>
		private DateTime cachedDay = DateTime.Today;

		/// <summary>
		/// 保存对 BeforeSaveToFile 事件处理程序的引用，用于后续能够正确注销事件。<br />
		/// 这是因为匿名方法/lambda 即使代码相同也会生成新的委托实例，必须保存引用才能正确注销。
		/// </summary>
		private EventHandler<SnetEventArgs>? beforeSaveHandler;

		/// <summary>
		/// 用于将 PascalCase 类名转换为带点分隔的小写形式的正则表达式。<br />
		/// 例如：MyClassName → my.class.name
		/// </summary>
		private readonly Regex pascalCaseSplitRegex = new Regex("(\\B[A-Z])", RegexOptions.Compiled);

		/// <summary>
		/// 通知事件异步<br />
		/// true : 日期切换了<br />
		/// false : 异常了
		/// </summary>
		public event Func<LogOperate, bool, Exception?, DateTime, Task> OnNoticeEventAsync;

		/// <summary>
		/// 日志操作扩展类构造函数
		/// </summary>
		/// <param name="_baseObject">通信对象</param>
		/// <param name="_folderName">日志的文件夹名</param>
		/// <param name="_outLog">是否启动底层日志输出至文件</param>
		/// <param name="_consoleOutLog">是否启控制台输出</param>
		/// <param name="filePath">在那个库中操作的此对象</param>
		public LogOperate(object _baseObject, string _folderName, bool _outLog = true, bool _consoleOutLog = false, [CallerFilePath] string filePath = "")
		{
			folderName = _folderName;
			baseObject = _baseObject;
			operateLibName = Path.GetFileNameWithoutExtension(filePath);
			Init(_outLog, _consoleOutLog);
		}

		/// <summary>
		/// 初始化或更新日志对象。<br />
		/// 当日期变化（跨天）时，重新生成日志文件路径并更新日志实例。
		/// </summary>
		private void LogHandler()
		{
			baseLog = baseObject as BinaryCommunication;
			if (baseLog == null)
			{
				return;
			}
			(string date, string path) info = GetLogInfo();
			baseLog.LogNet?.Dispose();
			baseLog.LogNet = new LogNetDateTime(info.path, GenerateMode.ByEveryHour);
			baseLog.LogNet.ConsoleOutput = consoleOutLog;
			if (beforeSaveHandler != null)
			{
				baseLog.LogNet.BeforeSaveToFile -= beforeSaveHandler;
			}
			beforeSaveHandler = async delegate(object? sender, SnetEventArgs e)
			{
				await LogEventAsycn(sender, e, info.date);
			};
			baseLog.LogNet.BeforeSaveToFile += beforeSaveHandler;
			if (!outLog)
			{
				if (beforeSaveHandler != null)
				{
					baseLog.LogNet.BeforeSaveToFile -= beforeSaveHandler;
				}
				baseLog.LogNet?.Dispose();
				baseLog.LogNet = null;
			}
		}

		/// <summary>
		/// 初始化底层日志输出至文件
		/// </summary>
		/// <param name="_outLog">是否启动底层日志输出至文件</param>
		/// <param name="_consoleOutLog">是否启控制台输出</param>
		private void Init(bool _outLog = true, bool _consoleOutLog = false)
		{
			outLog = _outLog;
			consoleOutLog = _consoleOutLog;
			LogHandler();
		}

		/// <summary>
		/// 启动底层日志输出至文件
		/// </summary>
		public void Start()
		{
			Init();
		}

		/// <summary>
		/// 停止底层日志输出至文件
		/// </summary>
		public void Stop()
		{
			Init(_outLog: false);
		}

		/// <summary>
		/// 日志事件接收（在日志保存前触发）。<br />
		/// 主要作用：检查日期是否已跨天，如果跨天则重新初始化日志。
		/// </summary>
		private async Task LogEventAsycn(object? sender, SnetEventArgs e, string historyDate)
		{
			try
			{
				if (await logSemaphore.WaitAsync(0) && GetCurrentDate() != historyDate)
				{
					LogHandler();
					OnNoticeEventAsync?.BeginInvoke(this, arg2: true, null, DateTime.Now, null, null);
				}
			}
			catch (Exception arg)
			{
				OnNoticeEventAsync?.BeginInvoke(this, arg2: false, arg, DateTime.Now, null, null);
			}
			finally
			{
				logSemaphore.Release();
			}
		}

		/// <summary>
		/// 获取当前日期（格式：yyyy-MM-dd），使用缓存减少 DateTime.Now 调用。<br />
		/// 仅在跨天时更新缓存。
		/// </summary>
		private string GetCurrentDate()
		{
			DateTime today = DateTime.Today;
			if (today != cachedDay)
			{
				cachedDay = today;
				cachedDate = today.ToString("yyyy-MM-dd");
			}
			return cachedDate;
		}

		/// <summary>
		/// 获取日志信息，包括日期和日志文件路径。<br />
		/// 日志路径格式：{根目录}/{日期}/{类名}/{PLC类名}
		/// </summary>
		private (string date, string path) GetLogInfo()
		{
			string text = cachedDate;
			string item = Path.Combine(folderName, text, pascalCaseSplitRegex.Replace(operateLibName, ".$1").ToLower(), pascalCaseSplitRegex.Replace(baseObject.GetType().Name, ".$1").ToLower());
			return (date: text, path: item);
		}

		/// <summary>
		/// 异步释放资源
		/// </summary>
		/// <returns></returns>
		public ValueTask DisposeAsync()
		{
			Dispose();
			return ValueTask.CompletedTask;
		}

		/// <summary>
		/// 释放资源
		/// </summary>
		public void Dispose()
		{
			try
			{
				if (baseLog?.LogNet != null)
				{
					baseLog.LogNet.BeforeSaveToFile -= beforeSaveHandler;
					beforeSaveHandler = null;
					baseLog.LogNet?.Dispose();
					baseLog.LogNet = null;
				}
				logSemaphore?.Dispose();
			}
			catch (Exception ex)
			{
				baseLog?.LogNet?.WriteError("Dispose failed: " + ex.Message);
			}
		}
	}
	/// <summary>
	/// 基于路径实现的日志类的基类，提供几个基础的方法信息。<br />
	/// The base class of the log class implemented based on the path provides several basic method information.
	/// </summary>
	public abstract class LogPathBase : LogNetBase
	{
		/// <summary>
		/// 当前正在存储的文件名<br />
		/// File name currently being stored
		/// </summary>
		protected string fileName = string.Empty;

		/// <summary>
		/// 存储文件的路径，如果设置为空，就不进行存储。<br />
		/// The path for storing the file. If it is set to empty, it will not be stored.
		/// </summary>
		protected string filePath = string.Empty;

		/// <summary>
		/// 控制文件的数量，小于1则不进行任何操作，当设置为10的时候，就限制文件数量为10。<br />
		/// Control the number of files. If it is less than 1, no operation is performed. When it is set to 10, the number of files is limited to 10.
		/// </summary>
		protected int controlFileQuantity = -1;

		/// <inheritdoc />
		protected override void OnWriteCompleted(bool createNewLogFile)
		{
			if (!createNewLogFile || controlFileQuantity <= 1)
			{
				return;
			}
			try
			{
				string[] existLogFileNames = GetExistLogFileNames();
				if (existLogFileNames.Length > controlFileQuantity)
				{
					List<FileInfo> list = new List<FileInfo>();
					for (int i = 0; i < existLogFileNames.Length; i++)
					{
						list.Add(new FileInfo(existLogFileNames[i]));
					}
					list.Sort((FileInfo m, FileInfo n) => m.CreationTime.CompareTo(n.CreationTime));
					for (int num = 0; num < list.Count - controlFileQuantity; num++)
					{
						File.Delete(list[num].FullName);
					}
				}
			}
			catch
			{
			}
		}

		/// <summary>
		/// 返回所有的日志文件名称，返回一个列表<br />
		/// Returns all log file names, returns a list
		/// </summary>
		/// <returns>所有的日志文件信息</returns>
		public virtual string[] GetExistLogFileNames()
		{
			if (!string.IsNullOrEmpty(filePath))
			{
				return Directory.GetFiles(filePath, LogNetManagment.LogFileHeadString + "*.txt");
			}
			return new string[0];
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return "LogPathBase";
		}
	}
	/// <summary>
	/// 日志文件的存储模式
	/// </summary>
	public enum LogSaveMode
	{
		/// <summary>
		/// 单个文件的存储模式
		/// </summary>
		SingleFile = 1,
		/// <summary>
		/// 根据文件的大小来存储，固定一个大小，不停的生成文件
		/// </summary>
		FileFixedSize,
		/// <summary>
		/// 根据时间来存储，可以设置年，季，月，日，小时等等
		/// </summary>
		Time
	}
	/// <summary>
	/// 一个统计次数的辅助类，可用于实现分析一些次数统计信息，比如统计某个API最近每天的访问次数，
	/// 统计日志组件最近每天访问的次数，调用者只需要关心统计方式和数据个数，详细参照API文档。<br />
	/// An auxiliary class for counting the number of times, which can be used to realize the analysis of some number of times statistical information, 
	/// such as counting the number of daily visits of an API, and counting the number of daily visits of the log component. 
	/// The caller only needs to care about the statistical method and the number of data. Refer to details API documentation.
	/// </summary>
	/// <example>
	/// 我们来举个例子：我有个方法，AAA需要记录一下连续60天的调用次数信息
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogStatisticsSample.cs" region="Sample1" title="简单的记录调用次数" />
	/// 因为这个数据是保存在内存里的，程序重新运行就丢失了，如果希望让这个数据一直在程序的话，在软件退出的时候需要存储文件，在软件启动的时候，加载文件数据
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogStatisticsSample.cs" region="Sample2" title="存储与加载" />
	/// </example>
	public class LogStatistics : LogStatisticsBase<long>
	{
		private RegularByteTransform byteTransform;

		private long totalSum;

		/// <summary>
		/// 获取当前的所有的值的总和<br />
		/// Get the sum of all current values
		/// </summary>
		public long TotalSum => totalSum;

		/// <inheritdoc cref="M:Snet.Driver.LogNet.LogStatisticsBase`1.#ctor(Snet.Driver.LogNet.GenerateMode,System.Int32)" />
		public LogStatistics(GenerateMode generateMode, int dataCount)
			: base(generateMode, dataCount)
		{
			byteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 新增一个统计信息，将会根据当前的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行新增数据 frequency 次<br />
		/// Adding a new statistical information will determine the position to insert the data according to the current time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, add data to the last number frequency times
		/// </summary>
		/// <param name="frequency">新增的次数信息，默认为1</param>
		public void StatisticsAdd(long frequency = 1L)
		{
			Interlocked.Add(ref totalSum, frequency);
			StatisticsCustomAction((long m) => m + frequency);
		}

		/// <summary>
		/// 新增一个统计信息，将会根据指定的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行新增数据 frequency 次<br />
		/// Adding a new statistical information will determine the position to insert the data according to the specified time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, add data to the last number frequency times
		/// </summary>
		/// <param name="frequency">新增的次数信息</param>
		/// <param name="time">新增的次数的时间</param>
		public void StatisticsAddByTime(long frequency, DateTime time)
		{
			Interlocked.Add(ref totalSum, frequency);
			StatisticsCustomAction((long m) => m + frequency, time);
		}

		/// <summary>
		/// 将当前所有的数据都写入到二进制的内存里去，可以用来写入文件或是网络发送。<br />
		/// Write all current data into binary memory, which can be used to write files or send over the network.
		/// </summary>
		/// <returns>二进制的byte数组</returns>
		public byte[] SaveToBinary()
		{
			OResult<long, long[]> statisticsSnapAndDataMark = GetStatisticsSnapAndDataMark();
			int num = 1024;
			byte[] array = new byte[statisticsSnapAndDataMark.Content2.Length * 8 + num];
			BitConverter.GetBytes(305419896).CopyTo(array, 0);
			BitConverter.GetBytes((ushort)num).CopyTo(array, 4);
			BitConverter.GetBytes((ushort)base.GenerateMode).CopyTo(array, 6);
			BitConverter.GetBytes(statisticsSnapAndDataMark.Content2.Length).CopyTo(array, 8);
			BitConverter.GetBytes(statisticsSnapAndDataMark.Content1).CopyTo(array, 12);
			BitConverter.GetBytes(TotalSum).CopyTo(array, 20);
			for (int i = 0; i < statisticsSnapAndDataMark.Content2.Length; i++)
			{
				BitConverter.GetBytes(statisticsSnapAndDataMark.Content2[i]).CopyTo(array, num + i * 8);
			}
			return array;
		}

		/// <summary>
		/// 将当前的统计信息及数据内容写入到指定的文件里面，需要指定文件的路径名称<br />
		/// Write the current statistical information and data content to the specified file, you need to specify the path name of the file
		/// </summary>
		/// <param name="fileName">文件的完整的路径名称</param>
		public void SaveToFile(string fileName)
		{
			File.WriteAllBytes(fileName, SaveToBinary());
		}

		/// <summary>
		/// 从二进制的数据内容加载，会对数据的合法性进行检查，如果数据不匹配，会报异常<br />
		/// Loading from the binary data content will check the validity of the data. If the data does not match, an exception will be reported
		/// </summary>
		/// <param name="buffer">等待加载的二进制数据</param>
		/// <exception cref="T:System.Exception"></exception>
		public void LoadFromBinary(byte[] buffer)
		{
			if (BitConverter.ToInt32(buffer, 0) != 305419896)
			{
				throw new Exception("File is not LogStatistics file, can't load data.");
			}
			int index = BitConverter.ToUInt16(buffer, 4);
			GenerateMode generateMode = (GenerateMode)BitConverter.ToUInt16(buffer, 6);
			int length = BitConverter.ToInt32(buffer, 8);
			long num = BitConverter.ToInt64(buffer, 12);
			long num2 = BitConverter.ToInt64(buffer, 20);
			base.generateMode = generateMode;
			totalSum = num2;
			long[] array = byteTransform.TransInt64(buffer, index, length);
			Reset(array, num);
		}

		/// <summary>
		/// 从指定的文件加载对应的统计信息，通常是调用<see cref="M:Snet.Driver.LogNet.LogStatistics.SaveToFile(System.String)" />方法存储的文件，如果文件不存在，将会跳过加载<br />
		/// Load the corresponding statistical information from the specified file, usually the file stored by calling the <see cref="M:Snet.Driver.LogNet.LogStatistics.SaveToFile(System.String)" /> method. 
		/// If the file does not exist, the loading will be skipped
		/// </summary>
		/// <param name="fileName">文件的完整的路径名称</param>
		/// <exception cref="T:System.Exception">当文件的模式和当前的模式设置不一样的时候，会引发异常</exception>
		public void LoadFromFile(string fileName)
		{
			if (File.Exists(fileName))
			{
				LoadFromBinary(File.ReadAllBytes(fileName));
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"LogStatistics[{base.GenerateMode}:{base.ArrayLength}]";
		}
	}
	/// <summary>
	/// 一个按照实际进行数据分割的辅助基类，可以用于实现对某个的API按照每天进行调用次数统计，也可以实现对某个设备数据按照天进行最大最小值均值分析，这些都是需要继承实现。<br />
	/// An auxiliary base class that divides the data according to the actual data can be used to implement statistics on the number of calls per day for a certain API, and it can also implement the maximum and minimum average analysis of a certain device data according to the day. These all need to be inherited. .
	/// </summary>
	/// <typeparam name="T">统计的数据类型</typeparam>
	public class LogStatisticsBase<T>
	{
		private T[] statistics;

		/// <summary>
		/// 当前的实际模式
		/// </summary>
		protected GenerateMode generateMode = GenerateMode.ByEveryDay;

		private int arrayLength = 30;

		private long lastDataMark = -1L;

		private object lockStatistics;

		/// <summary>
		/// 获取当前的统计类信息时间统计规则<br />
		/// Get the current statistical information time statistics rule
		/// </summary>
		public GenerateMode GenerateMode => generateMode;

		/// <summary>
		/// 获取当前的统计类信息的数据总量<br />
		/// Get the total amount of current statistical information
		/// </summary>
		public int ArrayLength => arrayLength;

		/// <summary>
		/// 实例化一个新的数据统计内容，需要指定当前的时间统计方式，按小时，按天，按月等等，还需要指定统计的数据数量，比如按天统计30天。<br />
		/// To instantiate a new data statistics content, you need to specify the current time statistics method, by hour, by day, by month, etc., 
		/// and also need to specify the number of statistics, such as 30 days by day.
		/// </summary>
		/// <param name="generateMode">时间的统计方式</param>
		/// <param name="arrayLength">数据的数量信息，如果本值为-1，则表示数据一直增长</param>
		public LogStatisticsBase(GenerateMode generateMode, int arrayLength)
		{
			this.generateMode = generateMode;
			this.arrayLength = arrayLength;
			if (this.arrayLength >= 0)
			{
				statistics = new T[arrayLength];
			}
			else
			{
				statistics = new T[1024];
			}
			lastDataMark = GetDataMarkFromDateTime(DateTime.Now);
			lockStatistics = new object();
		}

		/// <summary>
		/// 重置当前的统计信息，需要指定统计的数据内容，最后一个数据的标记信息，本方法主要用于还原统计信息<br />
		/// To reset the current statistical information, you need to specify the content of the statistical data, 
		/// and the tag information of the last data. This method is mainly used to restore statistical information
		/// </summary>
		/// <param name="statistics">统计结果数据信息</param>
		/// <param name="lastDataMark">最后一次标记的内容</param>
		public void Reset(T[] statistics, long lastDataMark)
		{
			if (arrayLength >= 0)
			{
				if (statistics.Length > arrayLength)
				{
					Array.Copy(statistics, statistics.Length - arrayLength, this.statistics, 0, arrayLength);
				}
				else if (statistics.Length < arrayLength)
				{
					Array.Copy(statistics, 0, this.statistics, arrayLength - statistics.Length, statistics.Length);
				}
				else
				{
					this.statistics = statistics;
				}
				arrayLength = statistics.Length;
			}
			else
			{
				this.statistics = statistics;
			}
			this.lastDataMark = lastDataMark;
		}

		/// <summary>
		/// 新增一个统计信息，将会根据当前的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行自定义的数据操作<br />
		/// Adding a new statistical information will determine the position to insert the data according to the current time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, Custom data operations on the last number
		/// </summary>
		/// <param name="newValue">增对最后一个数的自定义操作</param>
		protected void StatisticsCustomAction(Func<T, T> newValue)
		{
			lock (lockStatistics)
			{
				long dataMarkFromDateTime = GetDataMarkFromDateTime(DateTime.Now);
				if (lastDataMark != dataMarkFromDateTime)
				{
					int times = (int)(dataMarkFromDateTime - lastDataMark);
					statistics = GetLeftMoveTimes(times);
					lastDataMark = dataMarkFromDateTime;
				}
				statistics[statistics.Length - 1] = newValue(statistics[statistics.Length - 1]);
			}
		}

		/// <summary>
		/// 新增一个统计信息，将会根据当前的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行自定义的数据操作<br />
		/// Adding a new statistical information will determine the position to insert the data according to the current time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, Custom data operations on the last number
		/// </summary>
		/// <param name="newValue">增对最后一个数的自定义操作</param>
		/// <param name="time">增加的时间信息</param>
		protected void StatisticsCustomAction(Func<T, T> newValue, DateTime time)
		{
			lock (lockStatistics)
			{
				long dataMarkFromDateTime = GetDataMarkFromDateTime(DateTime.Now);
				if (lastDataMark != dataMarkFromDateTime)
				{
					int num = (int)(dataMarkFromDateTime - lastDataMark);
					if (num > 0)
					{
						statistics = GetLeftMoveTimes(num);
					}
					lastDataMark = dataMarkFromDateTime;
				}
				long dataMarkFromDateTime2 = GetDataMarkFromDateTime(time);
				if (dataMarkFromDateTime2 <= dataMarkFromDateTime)
				{
					int num2 = (int)(dataMarkFromDateTime2 - (dataMarkFromDateTime - statistics.Length + 1));
					if (num2 >= 0 && num2 < statistics.Length)
					{
						statistics[num2] = newValue(statistics[num2]);
					}
				}
			}
		}

		/// <summary>
		/// 获取当前的统计信息的数据快照，这是数据的副本，修改了里面的值不影响<br />
		/// Get a data snapshot of the current statistics. This is a copy of the data. Modifying the value inside does not affect
		/// </summary>
		/// <returns>实际的统计数据信息</returns>
		public T[] GetStatisticsSnapshot()
		{
			return GetStatisticsSnapAndDataMark().Content2;
		}

		/// <summary>
		/// 根据指定的时间范围来获取统计的数据信息快照，包含起始时间，包含结束时间，这是数据的副本，修改了里面的值不影响<br />
		/// Get a snapshot of statistical data information according to the specified time range, including the start time, 
		/// also the end time. This is a copy of the data. Modifying the value inside does not affect
		/// </summary>
		/// <param name="start">起始时间</param>
		/// <param name="finish">结束时间</param>
		/// <returns>指定实际范围内的数据副本</returns>
		public T[] GetStatisticsSnapshotByTime(DateTime start, DateTime finish)
		{
			if (finish <= start)
			{
				return new T[0];
			}
			lock (lockStatistics)
			{
				long dataMarkFromDateTime = GetDataMarkFromDateTime(DateTime.Now);
				if (lastDataMark != dataMarkFromDateTime)
				{
					int times = (int)(dataMarkFromDateTime - lastDataMark);
					statistics = GetLeftMoveTimes(times);
					lastDataMark = dataMarkFromDateTime;
				}
				long num = dataMarkFromDateTime - statistics.Length + 1;
				long num2 = GetDataMarkFromDateTime(start);
				long num3 = GetDataMarkFromDateTime(finish);
				if (num2 < num)
				{
					num2 = num;
				}
				if (num3 > dataMarkFromDateTime)
				{
					num3 = dataMarkFromDateTime;
				}
				int num4 = (int)(num2 - num);
				int num5 = (int)(num3 - num2 + 1);
				if (num2 == num3)
				{
					return new T[1] { statistics[num4] };
				}
				T[] array = new T[num5];
				for (int i = 0; i < num5; i++)
				{
					array[i] = statistics[num4 + i];
				}
				return array;
			}
		}

		/// <summary>
		/// 获取当前的统计信息的数据快照，这是数据的副本，修改了里面的值不影响<br />
		/// Get a data snapshot of the current statistics. This is a copy of the data. Modifying the value inside does not affect
		/// </summary>
		/// <returns>实际的统计数据信息</returns>
		public OResult<long, T[]> GetStatisticsSnapAndDataMark()
		{
			lock (lockStatistics)
			{
				long dataMarkFromDateTime = GetDataMarkFromDateTime(DateTime.Now);
				if (lastDataMark != dataMarkFromDateTime)
				{
					int times = (int)(dataMarkFromDateTime - lastDataMark);
					statistics = GetLeftMoveTimes(times);
					lastDataMark = dataMarkFromDateTime;
				}
				return OResult.CreateSuccessResult(dataMarkFromDateTime, statistics.CopyArray());
			}
		}

		/// <summary>
		/// 根据当前数据统计的时间模式，获取最新的数据标记信息<br />
		/// Obtain the latest data mark information according to the time mode of current data statistics
		/// </summary>
		/// <returns>数据标记</returns>
		public long GetDataMarkFromTimeNow()
		{
			return GetDataMarkFromDateTime(DateTime.Now);
		}

		/// <summary>
		/// 根据指定的时间，获取到该时间指定的数据标记信息<br />
		/// According to the specified time, get the data mark information specified at that time
		/// </summary>
		/// <param name="dateTime">指定的时间</param>
		/// <returns>数据标记</returns>
		public long GetDataMarkFromDateTime(DateTime dateTime)
		{
			return generateMode switch
			{
				GenerateMode.ByEveryMinute => GetMinuteFromTime(dateTime), 
				GenerateMode.ByEveryHour => GetHourFromTime(dateTime), 
				GenerateMode.ByEveryDay => GetDayFromTime(dateTime), 
				GenerateMode.ByEveryWeek => GetWeekFromTime(dateTime), 
				GenerateMode.ByEveryMonth => GetMonthFromTime(dateTime), 
				GenerateMode.ByEverySeason => GetSeasonFromTime(dateTime), 
				GenerateMode.ByEveryYear => GetYearFromTime(dateTime), 
				_ => GetDayFromTime(dateTime), 
			};
		}

		private long GetMinuteFromTime(DateTime dateTime)
		{
			return (long)(dateTime.Date - new DateTime(1970, 1, 1)).Days * 24L * 60 + dateTime.Hour * 60 + dateTime.Minute;
		}

		private long GetHourFromTime(DateTime dateTime)
		{
			return (long)(dateTime.Date - new DateTime(1970, 1, 1)).Days * 24L + dateTime.Hour;
		}

		private long GetDayFromTime(DateTime dateTime)
		{
			return (dateTime.Date - new DateTime(1970, 1, 1)).Days;
		}

		private long GetWeekFromTime(DateTime dateTime)
		{
			return ((long)(dateTime.Date - new DateTime(1970, 1, 1)).Days + 3L) / 7;
		}

		private long GetMonthFromTime(DateTime dateTime)
		{
			return (long)(dateTime.Year - 1970) * 12L + (dateTime.Month - 1);
		}

		private long GetSeasonFromTime(DateTime dateTime)
		{
			return (long)(dateTime.Year - 1970) * 4L + (dateTime.Month - 1) / 3;
		}

		private long GetYearFromTime(DateTime dateTime)
		{
			return dateTime.Year - 1970;
		}

		private T[] GetLeftMoveTimes(int times)
		{
			if (arrayLength >= 0)
			{
				if (times >= statistics.Length || times <= -statistics.Length)
				{
					return new T[arrayLength];
				}
				T[] array = new T[arrayLength];
				if (times >= 0)
				{
					Array.Copy(statistics, times, array, 0, statistics.Length - times);
				}
				else
				{
					Array.Copy(statistics, 0, array, -times, statistics.Length + times);
				}
				return array;
			}
			T[] array2 = new T[statistics.Length + times];
			Array.Copy(statistics, 0, array2, 0, Math.Min(statistics.Length, array2.Length));
			return array2;
		}
	}
	/// <summary>
	/// <seealso cref="T:Snet.Driver.LogNet.LogStatistics" />的词典集合类，用于多个数据的统计信息，例如可以统计多个规格的产量信息，统计多个方法的调用次数信息<br />
	/// The dictionary collection class of <seealso cref="T:Snet.Driver.LogNet.LogStatistics" /> is used for the statistical information of multiple data, for example, 
	/// the output information of multiple specifications can be counted, and the number of calls of multiple methods can be counted.
	/// </summary>
	public class LogStatisticsDict
	{
		private GenerateMode generateMode = GenerateMode.ByEveryDay;

		private int arrayLength = 30;

		private Dictionary<string, LogStatistics> dict;

		private object dictLock;

		private LogStatistics logStat;

		/// <summary>
		/// 获取当前的统计类信息时间统计规则<br />
		/// Get the current statistical information time statistics rule
		/// </summary>
		public GenerateMode GenerateMode => generateMode;

		/// <summary>
		/// 获取当前的统计类信息的数据总量<br />
		/// Get the total amount of current statistical information
		/// </summary>
		public int ArrayLength => arrayLength;

		/// <summary>
		/// 获取当前词典类自身的日志统计对象，统计所有的元素的统计信息<br />
		/// Get the log statistics object of the current dictionary class itself, and count the statistics of all elements
		/// </summary>
		public LogStatistics LogStat => logStat;

		/// <summary>
		/// 根据指定的存储模式，数据个数来实例化一个对象<br />
		/// According to the specified storage mode, the number of data to instantiate an object
		/// </summary>
		/// <param name="generateMode">当前的数据存储模式</param>
		/// <param name="arrayLength">准备存储的数据总个数</param>
		public LogStatisticsDict(GenerateMode generateMode, int arrayLength)
		{
			this.generateMode = generateMode;
			this.arrayLength = arrayLength;
			dictLock = new object();
			dict = new Dictionary<string, LogStatistics>(128);
			logStat = new LogStatistics(generateMode, arrayLength);
		}

		/// <summary>
		/// 根据给定的关键字信息，获取相关的 <seealso cref="T:Snet.Driver.LogNet.LogStatistics" /> 对象，进而执行很多的操作<br />
		/// According to the given keyword information, obtain related <seealso cref="T:Snet.Driver.LogNet.LogStatistics" /> objects, and then perform many operations
		/// </summary>
		/// <param name="key">关键字</param>
		/// <returns>日志对象，如果当前的日志对象不存在，就返回为NULL</returns>
		public LogStatistics GetLogStatistics(string key)
		{
			lock (dictLock)
			{
				if (dict.ContainsKey(key))
				{
					return dict[key];
				}
				return null;
			}
		}

		/// <summary>
		/// 手动新增一个<seealso cref="T:Snet.Driver.LogNet.LogStatistics" />对象，需要指定相关的关键字<br />
		/// Manually add a <seealso cref="T:Snet.Driver.LogNet.LogStatistics" /> object, you need to specify related keywords
		/// </summary>
		/// <param name="key">关键字信息</param>
		/// <param name="logStatistics">日志统计对象</param>
		public void AddLogStatistics(string key, LogStatistics logStatistics)
		{
			lock (dictLock)
			{
				if (dict.ContainsKey(key))
				{
					dict[key] = logStatistics;
				}
				else
				{
					dict.Add(key, logStatistics);
				}
			}
		}

		/// <summary>
		/// 移除一个<seealso cref="T:Snet.Driver.LogNet.LogStatistics" />对象，需要指定相关的关键字，如果关键字本来就存在，返回 <c>True</c>, 如果不存在，返回 <c>False</c> <br />
		/// To remove a <seealso cref="T:Snet.Driver.LogNet.LogStatistics" /> object, you need to specify the relevant keyword. If the keyword already exists, return <c>True</c>, if it does not exist, return <c>False</c>
		/// </summary>
		/// <param name="key">关键字信息</param>
		/// <returns>如果关键字本来就存在，返回 <c>True</c>, 如果不存在，返回 <c>False</c> </returns>
		public bool RemoveLogStatistics(string key)
		{
			lock (dictLock)
			{
				if (dict.ContainsKey(key))
				{
					dict.Remove(key);
					return true;
				}
				return false;
			}
		}

		/// <summary>
		/// 新增一个统计信息，将会根据当前的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行新增数据 frequency 次<br />
		/// Adding a new statistical information will determine the position to insert the data according to the current time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, add data to the last number frequency times
		/// </summary>
		/// <param name="key">当前选择的关键字</param>
		/// <param name="frequency">新增的次数信息，默认为1</param>
		public void StatisticsAdd(string key, long frequency = 1L)
		{
			logStat.StatisticsAdd(frequency);
			LogStatistics logStatistics = GetLogStatistics(key);
			if (logStatistics == null)
			{
				lock (dictLock)
				{
					if (!dict.ContainsKey(key))
					{
						logStatistics = new LogStatistics(generateMode, arrayLength);
						dict.Add(key, logStatistics);
					}
					else
					{
						logStatistics = dict[key];
					}
				}
			}
			logStatistics?.StatisticsAdd(frequency);
		}

		/// <summary>
		/// 新增一个统计信息，将会根据当前的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行新增数据 frequency 次<br />
		/// Adding a new statistical information will determine the position to insert the data according to the current time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, add data to the last number frequency times
		/// </summary>
		/// <param name="key">当前的关键字</param>
		/// <param name="frequency">新增的次数信息</param>
		/// <param name="time">新增的次数的时间</param>
		public void StatisticsAddByTime(string key, long frequency, DateTime time)
		{
			logStat.StatisticsAddByTime(frequency, time);
			LogStatistics logStatistics = GetLogStatistics(key);
			if (logStatistics == null)
			{
				lock (dictLock)
				{
					if (!dict.ContainsKey(key))
					{
						logStatistics = new LogStatistics(generateMode, arrayLength);
						dict.Add(key, logStatistics);
					}
					else
					{
						logStatistics = dict[key];
					}
				}
			}
			logStatistics?.StatisticsAddByTime(frequency, time);
		}

		/// <summary>
		/// 获取当前的统计信息的数据快照，这是数据的副本，修改了里面的值不影响<br />
		/// Get a data snapshot of the current statistics. This is a copy of the data. Modifying the value inside does not affect
		/// </summary>
		/// <param name="key">当前的关键字的信息</param>
		/// <returns>实际的统计数据信息</returns>
		public long[] GetStatisticsSnapshot(string key)
		{
			return GetLogStatistics(key)?.GetStatisticsSnapshot();
		}

		/// <summary>
		/// 根据指定的时间范围来获取统计的数据信息快照，包含起始时间，包含结束时间，这是数据的副本，修改了里面的值不影响<br />
		/// Get a snapshot of statistical data information according to the specified time range, including the start time, 
		/// also the end time. This is a copy of the data. Modifying the value inside does not affect
		/// </summary>
		/// <param name="key">当前的关键字信息</param>
		/// <param name="start">起始时间</param>
		/// <param name="finish">结束时间</param>
		/// <returns>指定实际范围内的数据副本</returns>
		public long[] GetStatisticsSnapshotByTime(string key, DateTime start, DateTime finish)
		{
			return GetLogStatistics(key)?.GetStatisticsSnapshotByTime(start, finish);
		}

		/// <summary>
		/// 获取所有的关键字的数据信息<br />
		/// Get data information of all keywords
		/// </summary>
		/// <returns>字符串数组</returns>
		public string[] GetKeys()
		{
			lock (dictLock)
			{
				return dict.Keys.ToArray();
			}
		}

		/// <summary>
		/// 将当前的统计信息及数据内容写入到指定的文件里面，需要指定文件的路径名称<br />
		/// Write the current statistical information and data content to the specified file, you need to specify the path name of the file
		/// </summary>
		/// <param name="fileName">文件的完整的路径名称</param>
		public void SaveToFile(string fileName)
		{
			using FileStream fileStream = new FileStream(fileName, FileMode.Create, FileAccess.Write);
			byte[] array = new byte[1024];
			BitConverter.GetBytes(305419906).CopyTo(array, 0);
			BitConverter.GetBytes((ushort)array.Length).CopyTo(array, 4);
			BitConverter.GetBytes((ushort)GenerateMode).CopyTo(array, 6);
			string[] keys = GetKeys();
			BitConverter.GetBytes(keys.Length).CopyTo(array, 8);
			fileStream.Write(array, 0, array.Length);
			string[] array2 = keys;
			foreach (string text in array2)
			{
				LogStatistics logStatistics = GetLogStatistics(text);
				if (logStatistics != null)
				{
					SnetHelper.WriteStringToStream(fileStream, text);
					SnetHelper.WriteBinaryToStream(fileStream, logStatistics.SaveToBinary());
				}
			}
		}

		/// <summary>
		/// 从指定的文件加载对应的统计信息，通常是调用<see cref="M:Snet.Driver.LogNet.LogStatisticsDict.SaveToFile(System.String)" />方法存储的文件，如果文件不存在，将会跳过加载<br />
		/// Load the corresponding statistical information from the specified file, usually the file stored by calling the <see cref="M:Snet.Driver.LogNet.LogStatisticsDict.SaveToFile(System.String)" /> method. 
		/// If the file does not exist, the loading will be skipped
		/// </summary>
		/// <param name="fileName">文件的完整的路径名称</param>
		/// <exception cref="T:System.Exception">当文件的模式和当前的模式设置不一样的时候，会引发异常</exception>
		public void LoadFromFile(string fileName)
		{
			if (!File.Exists(fileName))
			{
				return;
			}
			using FileStream stream = new FileStream(fileName, FileMode.Open, FileAccess.Read);
			byte[] value = SnetHelper.ReadSpecifiedLengthFromStream(stream, 1024);
			generateMode = (GenerateMode)BitConverter.ToUInt16(value, 6);
			int num = BitConverter.ToInt32(value, 8);
			for (int i = 0; i < num; i++)
			{
				string key = SnetHelper.ReadStringFromStream(stream);
				byte[] buffer = SnetHelper.ReadBinaryFromStream(stream);
				LogStatistics logStatistics = new LogStatistics(generateMode, arrayLength);
				logStatistics.LoadFromBinary(buffer);
				AddLogStatistics(key, logStatistics);
			}
		}
	}
	/// <summary>
	/// 一个用于数值范围记录的类，可以按照时间进行分类统计，比如计算一个温度值的每天的开始值，结束值，最大值，最小值，平均值信息。详细见API文档信息。<br />
	/// A class used to record the value range, which can be classified according to time, such as calculating the start value, end value, 
	/// maximum value, minimum value, and average value of a temperature value. See the API documentation for details.
	/// </summary>
	/// <example>
	/// 我们来举个例子：我们需要对一个温度数据进行分析，分析60天之内的最大值最小值等等信息
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogValueLimitSample.cs" region="Sample1" title="简单的记录调用次数" />
	/// 因为这个数据是保存在内存里的，程序重新运行就丢失了，如果希望让这个数据一直在程序的话，在软件退出的时候需要存储文件，在软件启动的时候，加载文件数据
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\LogNet\LogValueLimitSample.cs" region="Sample2" title="存储与加载" />
	/// </example>
	public class LogValueLimit : LogStatisticsBase<ValueLimit>
	{
		private RegularByteTransform byteTransform;

		private long valueCount;

		/// <summary>
		/// 当前设置数据的总的数量<br />
		/// The total amount of data currently set
		/// </summary>
		public long ValueCount => valueCount;

		/// <inheritdoc cref="M:Snet.Driver.LogNet.LogStatisticsBase`1.#ctor(Snet.Driver.LogNet.GenerateMode,System.Int32)" />
		public LogValueLimit(GenerateMode generateMode, int dataCount)
			: base(generateMode, dataCount)
		{
			byteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 新增一个数据用于分析，将会根据当前的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行数据更新，包括最大值，最小值，平均值。<br />
		/// Add a new data for analysis, and will determine the position to insert the data according to the current time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, data update for the last number, including maximum, minimum, and average.
		/// </summary>
		/// <param name="value">当前的新的数据值</param>
		public void AnalysisNewValue(double value)
		{
			Interlocked.Increment(ref valueCount);
			StatisticsCustomAction((ValueLimit m) => m.SetNewValue(value));
		}

		/// <summary>
		/// 新增一个数据用于分析，将会指定的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行数据更新，包括最大值，最小值，平均值。<br />
		/// dd a new data for analysis, and will determine the position to insert the data according to the specified time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, data update for the last number, including maximum, minimum, and average.
		/// </summary>
		/// <param name="value">当前的新的数据值</param>
		/// <param name="time">指定的时间信息</param>
		public void AnalysisNewValueByTime(double value, DateTime time)
		{
			Interlocked.Increment(ref valueCount);
			StatisticsCustomAction((ValueLimit m) => m.SetNewValue(value), time);
		}

		/// <summary>
		/// 将当前所有的数据都写入到二进制的内存里去，可以用来写入文件或是网络发送。<br />
		/// Write all current data into binary memory, which can be used to write files or send over the network.
		/// </summary>
		/// <returns>二进制的byte数组</returns>
		public byte[] SaveToBinary()
		{
			OResult<long, ValueLimit[]> statisticsSnapAndDataMark = GetStatisticsSnapAndDataMark();
			int num = 1024;
			int num2 = 64;
			byte[] array = new byte[statisticsSnapAndDataMark.Content2.Length * num2 + num];
			BitConverter.GetBytes(305419897).CopyTo(array, 0);
			BitConverter.GetBytes((ushort)num).CopyTo(array, 4);
			BitConverter.GetBytes((ushort)base.GenerateMode).CopyTo(array, 6);
			BitConverter.GetBytes(statisticsSnapAndDataMark.Content2.Length).CopyTo(array, 8);
			BitConverter.GetBytes(statisticsSnapAndDataMark.Content1).CopyTo(array, 12);
			BitConverter.GetBytes(valueCount).CopyTo(array, 20);
			BitConverter.GetBytes(num2).CopyTo(array, 28);
			for (int i = 0; i < statisticsSnapAndDataMark.Content2.Length; i++)
			{
				byteTransform.TransByte(statisticsSnapAndDataMark.Content2[i].StartValue).CopyTo(array, i * num2 + num);
				byteTransform.TransByte(statisticsSnapAndDataMark.Content2[i].Current).CopyTo(array, i * num2 + num + 8);
				byteTransform.TransByte(statisticsSnapAndDataMark.Content2[i].MaxValue).CopyTo(array, i * num2 + num + 16);
				byteTransform.TransByte(statisticsSnapAndDataMark.Content2[i].MinValue).CopyTo(array, i * num2 + num + 24);
				byteTransform.TransByte(statisticsSnapAndDataMark.Content2[i].Average).CopyTo(array, i * num2 + num + 32);
				byteTransform.TransByte(statisticsSnapAndDataMark.Content2[i].Count).CopyTo(array, i * num2 + num + 40);
			}
			return array;
		}

		/// <summary>
		/// 将当前的统计信息及数据内容写入到指定的文件里面，需要指定文件的路径名称<br />
		/// Write the current statistical information and data content to the specified file, you need to specify the path name of the file
		/// </summary>
		/// <param name="fileName">文件的完整的路径名称</param>
		public void SaveToFile(string fileName)
		{
			File.WriteAllBytes(fileName, SaveToBinary());
		}

		/// <summary>
		/// 从二进制的数据内容加载，会对数据的合法性进行检查，如果数据不匹配，会报异常<br />
		/// Loading from the binary data content will check the validity of the data. If the data does not match, an exception will be reported
		/// </summary>
		/// <param name="buffer">等待加载的二进制数据</param>
		/// <exception cref="T:System.Exception"></exception>
		public void LoadFromBinary(byte[] buffer)
		{
			if (BitConverter.ToInt32(buffer, 0) != 305419897)
			{
				throw new Exception("File is not LogValueLimit file, can't load data.");
			}
			int num = BitConverter.ToUInt16(buffer, 4);
			GenerateMode generateMode = (GenerateMode)BitConverter.ToUInt16(buffer, 6);
			int num2 = BitConverter.ToInt32(buffer, 8);
			long num3 = BitConverter.ToInt64(buffer, 12);
			long num4 = BitConverter.ToInt64(buffer, 20);
			int num5 = BitConverter.ToInt32(buffer, 28);
			base.generateMode = generateMode;
			valueCount = num4;
			ValueLimit[] array = new ValueLimit[num2];
			for (int i = 0; i < array.Length; i++)
			{
				array[i].StartValue = byteTransform.TransDouble(buffer, i * num5 + num);
				array[i].Current = byteTransform.TransDouble(buffer, i * num5 + num + 8);
				array[i].MaxValue = byteTransform.TransDouble(buffer, i * num5 + num + 16);
				array[i].MinValue = byteTransform.TransDouble(buffer, i * num5 + num + 24);
				array[i].Average = byteTransform.TransDouble(buffer, i * num5 + num + 32);
				array[i].Count = byteTransform.TransInt32(buffer, i * num5 + num + 40);
			}
			Reset(array, num3);
		}

		/// <summary>
		/// 从指定的文件加载对应的统计信息，通常是调用<see cref="M:Snet.Driver.LogNet.LogValueLimit.SaveToFile(System.String)" />方法存储的文件，如果文件不存在，将会跳过加载<br />
		/// Load the corresponding statistical information from the specified file, usually the file stored by calling the <see cref="M:Snet.Driver.LogNet.LogValueLimit.SaveToFile(System.String)" /> method. 
		/// If the file does not exist, the loading will be skipped
		/// </summary>
		/// <param name="fileName">文件的完整的路径名称</param>
		public void LoadFromFile(string fileName)
		{
			if (File.Exists(fileName))
			{
				LoadFromBinary(File.ReadAllBytes(fileName));
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"LogValueLimit[{base.GenerateMode}:{base.ArrayLength}]";
		}
	}
	/// <summary>
	/// <seealso cref="T:Snet.Driver.LogNet.LogValueLimit" /> 的词典集合类，用于多个数据的统计信息，例如可以统计多个温度变量的最大值，最小值，平均值<br />
	/// <seealso cref="T:Snet.Driver.LogNet.LogValueLimit" /> The dictionary collection class, used for statistical information of multiple data, 
	/// for example, it can count the maximum, minimum, and average values of multiple temperature variables
	/// </summary>
	public class LogValueLimitDict
	{
		private GenerateMode generateMode = GenerateMode.ByEveryDay;

		private int arrayLength = 30;

		private Dictionary<string, LogValueLimit> dict;

		private object dictLock;

		private LogStatistics logStat;

		/// <summary>
		/// 获取当前的统计类信息时间统计规则<br />
		/// Get the current statistical information time statistics rule
		/// </summary>
		public GenerateMode GenerateMode => generateMode;

		/// <summary>
		/// 获取当前的统计类信息的数据总量<br />
		/// Get the total amount of current statistical information
		/// </summary>
		public int ArrayLength => arrayLength;

		/// <summary>
		/// 获取当前词典类自身的日志统计对象，统计所有的元素的数据分析次数<br />
		/// Get the log statistics object of the current dictionary class itself, count the data analysis times of all elements
		/// </summary>
		public LogStatistics LogStat => logStat;

		/// <summary>
		/// 根据指定的存储模式，数据个数来实例化一个对象<br />
		/// According to the specified storage mode, the number of data to instantiate an object
		/// </summary>
		/// <param name="generateMode">当前的数据存储模式</param>
		/// <param name="arrayLength">准备存储的数据总个数</param>
		public LogValueLimitDict(GenerateMode generateMode, int arrayLength)
		{
			this.generateMode = generateMode;
			this.arrayLength = arrayLength;
			dictLock = new object();
			dict = new Dictionary<string, LogValueLimit>(128);
			logStat = new LogStatistics(generateMode, arrayLength);
		}

		/// <summary>
		/// 根据给定的关键字信息，获取相关的 <see cref="T:Snet.Driver.LogNet.LogValueLimit" /> 对象，进而执行很多的操作<br />
		/// According to the given keyword information, obtain related <see cref="T:Snet.Driver.LogNet.LogValueLimit" /> objects, and then perform many operations
		/// </summary>
		/// <param name="key">关键字</param>
		/// <returns>日志对象，如果当前的日志对象不存在，就返回为NULL</returns>
		public LogValueLimit GetLogValueLimit(string key)
		{
			lock (dictLock)
			{
				if (dict.ContainsKey(key))
				{
					return dict[key];
				}
				return null;
			}
		}

		/// <summary>
		/// 手动新增一个 <see cref="T:Snet.Driver.LogNet.LogValueLimit" /> 对象，需要指定相关的关键字<br />
		/// Manually add a <see cref="T:Snet.Driver.LogNet.LogValueLimit" /> object, you need to specify related keywords
		/// </summary>
		/// <param name="key">关键字信息</param>
		/// <param name="logValueLimit">日志数据分析对象</param>
		public void AddLogValueLimit(string key, LogValueLimit logValueLimit)
		{
			lock (dictLock)
			{
				if (dict.ContainsKey(key))
				{
					dict[key] = logValueLimit;
				}
				else
				{
					dict.Add(key, logValueLimit);
				}
			}
		}

		/// <summary>
		/// 移除一个<seealso cref="T:Snet.Driver.LogNet.LogValueLimit" />对象，需要指定相关的关键字，如果关键字本来就存在，返回 <c>True</c>, 如果不存在，返回 <c>False</c> <br />
		/// To remove a <seealso cref="T:Snet.Driver.LogNet.LogValueLimit" /> object, you need to specify the relevant keyword. If the keyword already exists, return <c>True</c>, if it does not exist, return <c>False</c>
		/// </summary>
		/// <param name="key">关键字信息</param>
		/// <returns>如果关键字本来就存在，返回 <c>True</c>, 如果不存在，返回 <c>False</c> </returns>
		public bool RemoveLogValueLimit(string key)
		{
			lock (dictLock)
			{
				if (dict.ContainsKey(key))
				{
					dict.Remove(key);
					return true;
				}
				return false;
			}
		}

		/// <summary>
		/// 新增一个数据用于分析，将会根据当前的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行数据更新，包括最大值，最小值，平均值。<br />
		/// Add a new data for analysis, and will determine the position to insert the data according to the current time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, data update for the last number, including maximum, minimum, and average.
		/// </summary>
		/// <param name="key">当前的关键字</param>
		/// <param name="value">当前的新的数据值</param>
		public void AnalysisNewValue(string key, double value)
		{
			logStat.StatisticsAdd(1L);
			LogValueLimit logValueLimit = GetLogValueLimit(key);
			if (logValueLimit == null)
			{
				lock (dictLock)
				{
					if (!dict.ContainsKey(key))
					{
						logValueLimit = new LogValueLimit(generateMode, arrayLength);
						dict.Add(key, logValueLimit);
					}
					else
					{
						logValueLimit = dict[key];
					}
				}
			}
			logValueLimit?.AnalysisNewValue(value);
		}

		/// <summary>
		/// 新增一个数据用于分析，将会指定的时间来决定插入数据位置，如果数据位置发生了变化，则数据向左发送移动。如果没有移动或是移动完成后，最后一个数进行数据更新，包括最大值，最小值，平均值。<br />
		/// dd a new data for analysis, and will determine the position to insert the data according to the specified time. If the data position changes, 
		/// the data will be sent to the left. If there is no movement or after the movement is completed, data update for the last number, including maximum, minimum, and average.
		/// </summary>
		/// <param name="key">关键字信息</param>
		/// <param name="value">当前的新的数据值</param>
		/// <param name="time">指定的时间信息</param>
		public void AnalysisNewValueByTime(string key, double value, DateTime time)
		{
			logStat.StatisticsAddByTime(1L, time);
			LogValueLimit logValueLimit = GetLogValueLimit(key);
			if (logValueLimit == null)
			{
				lock (dictLock)
				{
					if (!dict.ContainsKey(key))
					{
						logValueLimit = new LogValueLimit(generateMode, arrayLength);
						dict.Add(key, logValueLimit);
					}
					else
					{
						logValueLimit = dict[key];
					}
				}
			}
			logValueLimit?.AnalysisNewValueByTime(value, time);
		}

		/// <summary>
		/// 获取当前的统计信息的数据快照，这是数据的副本，修改了里面的值不影响<br />
		/// Get a data snapshot of the current statistics. This is a copy of the data. Modifying the value inside does not affect
		/// </summary>
		/// <param name="key">当前的关键字的信息</param>
		/// <returns>实际的统计数据信息</returns>
		public ValueLimit[] GetStatisticsSnapshot(string key)
		{
			return GetLogValueLimit(key)?.GetStatisticsSnapshot();
		}

		/// <summary>
		/// 根据指定的时间范围来获取统计的数据信息快照，包含起始时间，包含结束时间，这是数据的副本，修改了里面的值不影响<br />
		/// Get a snapshot of statistical data information according to the specified time range, including the start time, 
		/// also the end time. This is a copy of the data. Modifying the value inside does not affect
		/// </summary>
		/// <param name="key">当前的关键字信息</param>
		/// <param name="start">起始时间</param>
		/// <param name="finish">结束时间</param>
		/// <returns>指定实际范围内的数据副本</returns>
		public ValueLimit[] GetStatisticsSnapshotByTime(string key, DateTime start, DateTime finish)
		{
			return GetLogValueLimit(key)?.GetStatisticsSnapshotByTime(start, finish);
		}

		/// <summary>
		/// 获取所有的关键字的数据信息<br />
		/// Get data information of all keywords
		/// </summary>
		/// <returns>字符串数组</returns>
		public string[] GetKeys()
		{
			lock (dictLock)
			{
				return dict.Keys.ToArray();
			}
		}

		/// <summary>
		/// 将当前的统计信息及数据内容写入到指定的文件里面，需要指定文件的路径名称<br />
		/// Write the current statistical information and data content to the specified file, you need to specify the path name of the file
		/// </summary>
		/// <param name="fileName">文件的完整的路径名称</param>
		public void SaveToFile(string fileName)
		{
			using FileStream fileStream = new FileStream(fileName, FileMode.Create, FileAccess.Write);
			byte[] array = new byte[1024];
			BitConverter.GetBytes(305419906).CopyTo(array, 0);
			BitConverter.GetBytes((ushort)array.Length).CopyTo(array, 4);
			BitConverter.GetBytes((ushort)GenerateMode).CopyTo(array, 6);
			string[] keys = GetKeys();
			BitConverter.GetBytes(keys.Length).CopyTo(array, 8);
			fileStream.Write(array, 0, array.Length);
			string[] array2 = keys;
			foreach (string text in array2)
			{
				LogValueLimit logValueLimit = GetLogValueLimit(text);
				if (logValueLimit != null)
				{
					SnetHelper.WriteStringToStream(fileStream, text);
					SnetHelper.WriteBinaryToStream(fileStream, logValueLimit.SaveToBinary());
				}
			}
		}

		/// <summary>
		/// 从指定的文件加载对应的统计信息，通常是调用<see cref="M:Snet.Driver.LogNet.LogValueLimitDict.SaveToFile(System.String)" />方法存储的文件，如果文件不存在，将会跳过加载<br />
		/// Load the corresponding statistical information from the specified file, usually the file stored by calling the <see cref="M:Snet.Driver.LogNet.LogValueLimitDict.SaveToFile(System.String)" /> method. 
		/// If the file does not exist, the loading will be skipped
		/// </summary>
		/// <param name="fileName">文件的完整的路径名称</param>
		/// <exception cref="T:System.Exception">当文件的模式和当前的模式设置不一样的时候，会引发异常</exception>
		public void LoadFromFile(string fileName)
		{
			if (!File.Exists(fileName))
			{
				return;
			}
			using FileStream stream = new FileStream(fileName, FileMode.Open, FileAccess.Read);
			byte[] value = SnetHelper.ReadSpecifiedLengthFromStream(stream, 1024);
			generateMode = (GenerateMode)BitConverter.ToUInt16(value, 6);
			int num = BitConverter.ToInt32(value, 8);
			for (int i = 0; i < num; i++)
			{
				string key = SnetHelper.ReadStringFromStream(stream);
				byte[] buffer = SnetHelper.ReadBinaryFromStream(stream);
				LogValueLimit logValueLimit = new LogValueLimit(generateMode, arrayLength);
				logValueLimit.LoadFromBinary(buffer);
				AddLogValueLimit(key, logValueLimit);
			}
		}
	}
	/// <summary>
	/// 带有日志消息的事件
	/// </summary>
	public class SnetEventArgs : EventArgs
	{
		/// <summary>
		/// 消息信息
		/// </summary>
		public SnetMessageItem SnetMessage { get; set; }
	}
	/// <summary>
	/// 记录消息的等级
	/// </summary>
	public enum SnetMessageDegree
	{
		/// <summary>
		/// 一条消息都不记录
		/// </summary>
		None = 1,
		/// <summary>
		/// 记录致命等级及以上日志的消息
		/// </summary>
		FATAL,
		/// <summary>
		/// 记录异常等级及以上日志的消息
		/// </summary>
		ERROR,
		/// <summary>
		/// 记录警告等级及以上日志的消息
		/// </summary>
		WARN,
		/// <summary>
		/// 记录信息等级及以上日志的消息
		/// </summary>
		INFO,
		/// <summary>
		/// 记录调试等级及以上日志的信息
		/// </summary>
		DEBUG
	}
	/// <summary>
	/// 单条日志的记录信息，包含了消息等级，线程号，关键字，文本信息<br />
	/// Record information of a single log, including message level, thread number, keywords, text information
	/// </summary>
	public class SnetMessageItem
	{
		private static long IdNumber;

		/// <summary>
		/// 写入到文件的尝试的次数，一般都是1次，可能部分情况会存在多次写入才成功，那么此处的数字就是变为实际尝试的次数。<br />
		/// </summary>
		internal int WriteRetryTimes = 1;

		/// <summary>
		/// 指示当前的日志是否已经输出到控制台，有可能因为可能异常，不进行重复输出
		/// </summary>
		internal bool HasLogOutput;

		/// <summary>
		/// 单个记录信息的标识ID，程序重新运行时清空，代表程序从运行以来的日志计数，不管存储的或是未存储的<br />
		/// The ID of a single record of information. It is cleared when the program is re-run. 
		/// It represents the log count of the program since it was run, whether stored or unstored.
		/// </summary>
		public long Id { get; private set; }

		/// <summary>
		/// 消息的等级，包括DEBUG，INFO，WARN，ERROR，FATAL，NONE共计六个等级<br />
		/// Message levels, including DEBUG, INFO, WARN, ERROR, FATAL, NONE total six levels
		/// </summary>
		public SnetMessageDegree Degree { get; set; } = SnetMessageDegree.DEBUG;

		/// <summary>
		/// 线程ID，发生异常时的线程号<br />
		/// Thread ID, the thread number when the exception occurred
		/// </summary>
		public int ThreadId { get; set; }

		/// <summary>
		/// 消息文本，记录日志的时候给定<br />
		/// Message text, given when logging
		/// </summary>
		public string Text { get; set; }

		/// <summary>
		/// 记录日志的时间，而非存储日志的时间<br />
		/// The time the log was recorded, not the time it was stored
		/// </summary>
		public DateTime Time { get; set; }

		/// <summary>
		/// 消息的关键字<br />
		/// Keyword of the message
		/// </summary>
		public string KeyWord { get; set; }

		/// <summary>
		/// 是否取消写入到文件中去，在事件 <see cref="E:Snet.Driver.LogNet.LogNetBase.BeforeSaveToFile" /> 触发的时候捕获即可设置。<br />
		/// Whether to cancel writing to the file, can be set when the event <see cref="E:Snet.Driver.LogNet.LogNetBase.BeforeSaveToFile" /> is triggered.
		/// </summary>
		public bool Cancel { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public SnetMessageItem()
		{
			Id = Interlocked.Increment(ref IdNumber);
			Time = DateTime.Now;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			if (Degree != SnetMessageDegree.None)
			{
				if (!string.IsNullOrEmpty(KeyWord))
				{
					return $"[{LogNetManagment.GetDegreeDescription(Degree)}] {Time:yyyy-MM-dd HH:mm:ss.ffffff} Thread [{ThreadId:D3}] {KeyWord} : {Text}";
				}
				return $"[{LogNetManagment.GetDegreeDescription(Degree)}] {Time:yyyy-MM-dd HH:mm:ss.ffffff} Thread [{ThreadId:D3}] {Text}";
			}
			return Text;
		}

		/// <summary>
		/// 返回表示当前对象的字符串，剔除了关键字<br />
		/// Returns a string representing the current object, excluding keywords
		/// </summary>
		/// <returns>字符串信息</returns>
		public string ToStringWithoutKeyword()
		{
			if (Degree != SnetMessageDegree.None)
			{
				return $"[{LogNetManagment.GetDegreeDescription(Degree)}] {Time:yyyy-MM-dd HH:mm:ss.ffffff} Thread [{ThreadId:D3}] {Text}";
			}
			return Text;
		}
	}
}
