namespace Snet.Driver.Instrument.Temperature
{
	/// <summary>
	/// 阿尔泰科技发展有限公司的DAM3601温度采集模块，基于ModbusRtu开发完成。
	/// </summary>
	/// <remarks>
	/// 该温度采集模块是基于modbus-rtu，但不是标准的modbus协议，存在一些小误差，需要重写实现，并且提供了基础的数据转换
	/// </remarks>
	public class DAM3601 : ModbusRtu
	{
		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public DAM3601()
		{
			base.SleepTime = 200;
		}

		/// <summary>
		/// 使用站号实例化默认的对象
		/// </summary>
		/// <param name="station">站号信息</param>
		public DAM3601(byte station)
			: base(station)
		{
			base.SleepTime = 200;
		}

		/// <summary>
		/// 读取所有的温度数据，并转化成相关的信息
		/// </summary>
		/// <returns>结果数据对象</returns>
		public OResult<float[]> ReadAllTemperature()
		{
			string address = "x=4;1";
			if (base.AddressStartWithZero)
			{
				address = "x=4;0";
			}
			OResult<short[]> oResult = ReadInt16(address, 128);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<float[]>(oResult);
			}
			return OResult.CreateSuccessResult(oResult.Content.Select((short m) => TransformValue(m)).ToArray());
		}

		/// <summary>
		/// 数据转换方法，将读取的值，
		/// </summary>
		/// <param name="value">读取的值</param>
		/// <returns>转换后的值</returns>
		private float TransformValue(short value)
		{
			if ((value & 0x800) > 0)
			{
				return (float)(((value & 0xFFF) ^ 0xFFF) + 1) * -0.0625f;
			}
			return (float)(value & 0x7FF) * 0.0625f;
		}

		/// <summary>
		/// 从Modbus服务器批量读取寄存器的信息，需要指定起始地址，读取长度
		/// </summary>
		/// <param name="address">起始地址，格式为"1234"，或者是带功能码格式x=3;1234</param>
		/// <param name="length">读取的数量</param>
		/// <returns>带有成功标志的字节信息</returns>
		/// <example>
		/// 此处演示批量读取的示例
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Modbus\Modbus.cs" region="ReadExample2" title="Read示例" />
		/// </example>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[][]> oResult = ModbusInfo.BuildReadModbusCommand(address, length, base.Station, base.AddressStartWithZero, 16);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[]>();
			}
			return ReadFromCoreServer(oResult.Content[0]);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"DAM3601[{base.PortName}:{base.BaudRate}]";
		}
	}
	/// <summary>
	/// 宇电AIBus协议的温度采集模块，基于串口通讯实现。
	/// </summary>
	public class YuDianAIBus : DeviceSerialPort
	{
		/// <inheritdoc cref="P:Snet.Driver.ModBus.ModbusRtu.Station" />
		public byte Station { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Initializes a new instance of the <see cref="T:Snet.Driver.Instrument.Temperature.YuDianAIBus" /> class.
		/// </summary>
		/// <remarks>This constructor sets up the default configuration for the <see cref="T:Snet.Driver.Instrument.Temperature.YuDianAIBus" /> instance, 
		/// including initializing the byte transformation mechanism, setting the word length, and defining  the default sleep
		/// time between operations.</remarks>
		public YuDianAIBus()
		{
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
			base.SleepTime = 20;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new YuDianMessage();
		}

		private OResult<byte[]> BuildCommandHelper(string address, byte code, byte data1, byte data2)
		{
			byte b = (byte)SnetHelper.ExtractParameter(ref address, "s", Station);
			if (!byte.TryParse(address, out var result))
			{
				return new OResult<byte[]>($"Address [{result}] Wrong!");
			}
			byte b2 = ((b < 128) ? ((byte)(b + 128)) : b);
			byte[] array = new byte[8] { b2, b2, code, result, data1, data2, 0, 0 };
			int num = b;
			for (int i = 2; i < array.Length - 2; i += 2)
			{
				num += BitConverter.ToUInt16(array, i);
			}
			array[6] = (byte)(num % 256);
			array[7] = (byte)(num / 256);
			return OResult.CreateSuccessResult(array);
		}

		private OResult<byte[]> BuildReadCommand(string address, ushort length, bool isBit)
		{
			return BuildCommandHelper(address, 82, 0, 0);
		}

		private OResult<byte[]> BuildWriteCommand(string address, byte[] value)
		{
			if (value.Length != 2)
			{
				return new OResult<byte[]>("Value Length Must Be 2 Bytes");
			}
			return BuildCommandHelper(address, 67, value[0], value[1]);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Read(System.String,System.UInt16)" />
		public override OResult<byte[]> Read(string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadCommand(address, length, isBit: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (length == 1)
			{
				return OResult.CreateSuccessResult(oResult2.Content.SelectMiddle(6, 2));
			}
			return OResult.CreateSuccessResult(oResult2.Content.SelectMiddle(0, 8));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadDouble(System.String,System.UInt16)" />
		public override OResult<double[]> ReadDouble(string address, ushort length)
		{
			OResult<short[]> oResult = ReadInt16(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<double[]>(oResult);
			}
			return OResult.CreateSuccessResult(((IEnumerable<short>)oResult.Content).Select((Func<short, double>)((short m) => m)).ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Byte[])" />
		public override OResult Write(string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			return ReadFromCoreServer(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Double[])" />
		public override OResult Write(string address, double[] values)
		{
			return Write(address, values.Select((double m) => (short)m).ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadDoubleAsync(System.String,System.UInt16)" />
		public override async Task<OResult<double[]>> ReadDoubleAsync(string address, ushort length)
		{
			OResult<short[]> oResult = await ReadInt16Async(address, length).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<double[]>(oResult);
			}
			return OResult.CreateSuccessResult(((IEnumerable<short>)oResult.Content).Select((Func<short, double>)((short m) => m)).ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.WriteAsync(System.String,System.Double[])" />
		public override async Task<OResult> WriteAsync(string address, double[] values)
		{
			return await WriteAsync(address, values.Select((double m) => (short)m).ToArray()).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"YuDianAIBus<{CommunicationPipe}>";
		}
	}
	/// <summary>
	/// Represents a message structure used in the YuDian communication protocol.
	/// </summary>
	public class YuDianMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 10;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			return 0;
		}
	}
