namespace Snet.Driver.Instrument.RKC
{
	/// <summary>
	/// RKC的CD/CH系列数字式温度控制器的串口类对象，可以读取测量值，CT1输入值，CT2输入值等等，地址的地址需要参考API文档的示例<br />
	/// The serial port object of RKC's CD/CH series digital temperature controller can read the measured value, CT1 input value, 
	/// CT2 input value, etc. The address of the address needs to refer to the example of the API document
	/// </summary>
	/// <remarks>
	/// 只能使用ReadDouble(string),Write(string,double)方法来读写数据，设备的串口默认参数为 8-1-N,8 个数据位，一个停止位，无奇偶校验<br />
	/// 地址支持站号信息，例如 s=2;M1
	/// </remarks>
	public class TemperatureController : DeviceSerialPort
	{
		private byte station = 1;

		/// <inheritdoc cref="P:Snet.Driver.Instrument.RKC.TemperatureControllerOverTcp.Station" />
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.TemperatureControllerOverTcp.#ctor" />
		public TemperatureController()
		{
			base.ByteTransform = new RegularByteTransform();
			base.WordLength = 1;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new RkcTemperatureMessage();
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.ReadDouble(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String)" />
		public override OResult<double[]> ReadDouble(string address, ushort length)
		{
			OResult<double> oResult = TemperatureControllerHelper.ReadDouble(this, station, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<double[]>(oResult);
			}
			return OResult.CreateSuccessResult(new double[1] { oResult.Content });
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Double)" />
		public override OResult Write(string address, double[] values)
		{
			if (values == null || values.Length == 0)
			{
				return OResult.CreateSuccessResult();
			}
			return TemperatureControllerHelper.Write(this, station, address, values[0]);
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.ReadDouble(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String)" />
		public override async Task<OResult<double[]>> ReadDoubleAsync(string address, ushort length)
		{
			return await Task.Run(() => ReadDouble(address, length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Double)" />
		public override async Task<OResult> WriteAsync(string address, double[] values)
		{
			return await Task.Run(() => Write(address, values));
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"RkcTemperatureController[{base.PortName}:{base.BaudRate}]";
		}
	}
	/// <summary>
	/// RKC的CD/CH系列数字式温度控制器的网口透传类对象，可以读取测量值，CT1输入值，CT2输入值等等，地址的地址需要参考API文档的示例<br />
	/// RKC's CD/CH series digital temperature controller's network port transparently transmits objects, which can read measured values, CT1 input values, 
	/// CT2 input values, etc. The address of the address needs to refer to the example of the API document
	/// </summary>
	/// <remarks>
	/// 只能使用ReadDouble(string),Write(string,double)方法来读写数据<br />
	/// 地址支持站号信息，例如 s=2;M1 其他的地址直接参考demo程序演示
	/// </remarks>
	public class TemperatureControllerOverTcp : DeviceTcpNet
	{
		private byte station = 1;

		/// <summary>
		/// PLC的站号信息，需要和实际的设置值一致，默认为1<br />
		/// The station number information of the PLC needs to be consistent with the actual setting value. The default is 1.
		/// </summary>
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 实例化默认的构造方法<br />
		/// Instantiate the default constructor
		/// </summary>
		public TemperatureControllerOverTcp()
		{
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform();
			base.SleepTime = 20;
		}

		/// <summary>
		/// 使用指定的ip地址和端口来实例化一个对象<br />
		/// Instantiate an object with the specified IP address and port
		/// </summary>
		/// <param name="ipAddress">设备的Ip地址</param>
		/// <param name="port">设备的端口号</param>
		public TemperatureControllerOverTcp(string ipAddress, int port)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new RkcTemperatureMessage();
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.ReadDouble(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String)" />
		public override OResult<double[]> ReadDouble(string address, ushort length)
		{
			OResult<double> oResult = TemperatureControllerHelper.ReadDouble(this, station, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<double[]>(oResult);
			}
			return OResult.CreateSuccessResult(new double[1] { oResult.Content });
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Double)" />
		public override OResult Write(string address, double[] values)
		{
			if (values == null || values.Length == 0)
			{
				return OResult.CreateSuccessResult();
			}
			return TemperatureControllerHelper.Write(this, station, address, values[0]);
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.ReadDouble(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String)" />
		public override async Task<OResult<double[]>> ReadDoubleAsync(string address, ushort length)
		{
			OResult<double> oResult = await TemperatureControllerHelper.ReadDoubleAsync(this, station, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<double[]>(oResult);
			}
			return OResult.CreateSuccessResult(new double[1] { oResult.Content });
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Double)" />
		public override async Task<OResult> WriteAsync(string address, double[] values)
		{
			if (values == null || values.Length == 0)
			{
				return OResult.CreateSuccessResult();
			}
			return await TemperatureControllerHelper.WriteAsync(this, station, address, values[0]);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"RkcTemperatureControllerOverTcp[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// RKC的CD/CH系列数字式温度控制器的虚拟设备，可以读取测量值，CT1输入值，CT2输入值等等，地址的地址需要参考API文档的示例<br />
	/// The serial port object of RKC's CD/CH series digital temperature controller can read the measured value, CT1 input value, 
	/// CT2 input value, etc. The address of the address needs to refer to the example of the API document
	/// </summary>
	/// <remarks>
	/// 只能使用ReadDouble(string),Write(string,double)方法来读写数据，设备的串口默认参数为 8-1-N,8 个数据位，一个停止位，无奇偶校验<br />
	/// 地址支持站号信息，例如 s=2;M1
	/// </remarks>
	public class TemperatureControllerServer : DeviceServer
	{
		private List<string> tagList;

		private string readTag = string.Empty;

		private byte station;

		private Dictionary<string, double> tagValues;

		/// <summary>
		/// 获取或设置当前的站号信息
		/// </summary>
		public byte Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 实例化一个默认的方法
		/// </summary>
		public TemperatureControllerServer()
		{
			string[] array = new string[26]
			{
				"M1", "M2", "M3", "AA", "AB", "B1", "ER", "SR", "G1", "S1",
				"A1", "A2", "A3", "A4", "A5", "P1", "I1", "D1", "W1", "P2",
				"V1", "T0", "T1", "G2", "PB", "LK"
			};
			tagValues = new Dictionary<string, double>();
			tagList = new List<string>(array);
			string[] array2 = array;
			foreach (string key in array2)
			{
				tagValues.Add(key, 0.0);
			}
			LogMsgFormatBinary = false;
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <inheritdoc />
		public override OResult<double[]> ReadDouble(string address, ushort length)
		{
			string[] array = address.Split(new char[1] { ';' }, StringSplitOptions.RemoveEmptyEntries);
			double[] array2 = new double[array.Length];
			for (int i = 0; i < array.Length; i++)
			{
				if (tagValues.ContainsKey(array[i]))
				{
					array2[i] = tagValues[array[i]];
					continue;
				}
				return new OResult<double[]>("Tag[" + array[i] + "] is not exist");
			}
			return OResult.CreateSuccessResult(array2);
		}

		/// <inheritdoc />
		public override OResult Write(string address, double[] values)
		{
			string[] array = address.Split(new char[1] { ';' }, StringSplitOptions.RemoveEmptyEntries);
			for (int i = 0; i < array.Length; i++)
			{
				if (tagValues.ContainsKey(array[i]))
				{
					tagValues[array[i]] = values[i];
					continue;
				}
				return new OResult<double[]>("Tag[" + array[i] + "] is not exist");
			}
			return OResult.CreateSuccessResult();
		}

		private OResult<byte[]> CreateResponseByAddress(string add)
		{
			if (!tagValues.ContainsKey(add))
			{
				return new OResult<byte[]>("Read tag [" + add + "] is not exist");
			}
			readTag = add;
			List<byte> list = new List<byte>(20);
			list.Add(2);
			list.AddRange(Encoding.ASCII.GetBytes(add));
			list.AddRange(Encoding.ASCII.GetBytes(tagValues[add].ToString().PadLeft(6, '0').Substring(0, 6)));
			list.Add(3);
			int num = list[3];
			for (int i = 4; i < list.Count; i++)
			{
				num ^= list[i];
			}
			list.Add((byte)num);
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive.Length == 1)
			{
				if (!string.IsNullOrEmpty(readTag))
				{
					if (receive[0] == 6)
					{
						int num = tagList.IndexOf(readTag);
						num++;
						if (num >= tagList.Count)
						{
							num = 0;
						}
						return CreateResponseByAddress(tagList[num]);
					}
					if (receive[0] == 21)
					{
						return CreateResponseByAddress(readTag);
					}
				}
				return new OResult<byte[]>("not legal: " + receive.ToHexString(' '));
			}
			byte b = byte.Parse(Encoding.ASCII.GetString(receive, 1, 2));
			if (b != Station)
			{
				return new OResult<byte[]>($"Station not match, need [{Station}] but [{b}]");
			}
			if (receive[3] == 2)
			{
				if (!base.EnableWrite)
				{
					return new OResult<byte[]>("Not allow client write");
				}
				string text = Encoding.ASCII.GetString(receive, 4, 2);
				double value = double.Parse(Encoding.ASCII.GetString(receive, 6, receive.Length - 8));
				if (!tagValues.ContainsKey(text))
				{
					return new OResult<byte[]>("Write tag [" + text + "] is not exist");
				}
				tagValues[text] = value;
				return OResult.CreateSuccessResult(new byte[1] { 6 });
			}
			string add = Encoding.ASCII.GetString(receive, 3, 2);
			return CreateResponseByAddress(add);
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.Write(buffer.SelectBegin(receivedLength));
			return new RkcTemperatureMessage().CheckReceiveDataComplete(null, memoryStream);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"TemperatureControllerServer[{base.Port}]";
		}
	}
}
namespace Snet.Driver.Instrument.RKC.Helper
{
	/// <summary>
	/// RKC温度控制器的辅助类信息，提供了报文的生成，读写的实现的方法<br />
	/// Auxiliary information of the RKC temperature controller provides a method for message generation and reading and writing
	/// </summary>
	public class TemperatureControllerHelper
	{
		/// <summary>
		/// 构建读取的报文命令，需要指定站号信息，数据地址
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">数据的地址</param>
		/// <returns>是否成功</returns>
		public static OResult<byte[]> BuildReadCommand(byte station, string address)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			if (station >= 100)
			{
				return new OResult<byte[]>("Station must less than 100");
			}
			try
			{
				byte[] array = new byte[4 + address.Length];
				array[0] = 4;
				Encoding.ASCII.GetBytes(station.ToString("D2")).CopyTo(array, 1);
				Encoding.ASCII.GetBytes(address).CopyTo(array, 3);
				array[^1] = 5;
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 构建一个写入的报文信息
		/// </summary>
		/// <param name="station">站号信息</param>
		/// <param name="address">地址信息</param>
		/// <param name="value">等待写入的值</param>
		/// <returns>是否成功的结果报文</returns>
		public static OResult<byte[]> BuildWriteCommand(byte station, string address, double value)
		{
			station = (byte)SnetHelper.ExtractParameter(ref address, "s", station);
			if (station >= 100)
			{
				return new OResult<byte[]>("Station must less than 100");
			}
			if (value.ToString().Length > 6)
			{
				return new OResult<byte[]>("The data consists of up to 6 characters");
			}
			try
			{
				List<byte> list = new List<byte>(20);
				list.Add(4);
				list.AddRange(Encoding.ASCII.GetBytes(station.ToString("D2")));
				list.Add(2);
				list.AddRange(Encoding.ASCII.GetBytes(address));
				list.AddRange(Encoding.ASCII.GetBytes(value.ToString()));
				list.Add(3);
				int num = list[4];
				for (int i = 5; i < list.Count; i++)
				{
					num ^= list[i];
				}
				list.Add((byte)num);
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 从RKC设备读取Double类型的数据信息，地址示例：M1,M2,M3,AA,AB,B1,ER等，更详细的地址及具体含义需要参考API文档<br />
		/// Read Double type data information from RKC device. Examples of addresses: M1, M2, M3, AA, AB, B1, ER, etc. 
		/// For more detailed addresses and specific meanings, please refer to the API documentation
		/// </summary>
		/// <param name="device">设备通信对象</param>
		/// <param name="station">表号信息，也叫站号信息</param>
		/// <param name="address">数据地址信息，地址示例：M1,M2,M3,AA,AB,B1,ER等</param>
		/// <returns>结果数据对象信息</returns>
		public static OResult<double> ReadDouble(IReadWriteDevice device, byte station, string address)
		{
			OResult<byte[]> oResult = BuildReadCommand(station, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<double>(oResult);
			}
			OResult<byte[]> oResult2 = device.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<double>(oResult2);
			}
			if (oResult2.Content[0] != 2)
			{
				return new OResult<double>("STX check failed: " + oResult2.Content.ToHexString(' '));
			}
			try
			{
				return OResult.CreateSuccessResult(double.Parse(Encoding.ASCII.GetString(oResult2.Content, 3, oResult2.Content.Length - 5)));
			}
			catch (Exception ex)
			{
				return new OResult<double>(ex.Message + Environment.NewLine + "Source: " + oResult2.Content.ToHexString(' '));
			}
		}

		/// <summary>
		/// 将Double类型的数据写入到RKC设备中去，地址示例：M1,M2,M3,AA,AB,B1,ER等，更详细的地址及具体含义需要参考API文档<br />
		/// Write Double type data to the RKC device. Examples of addresses: M1, M2, M3, AA, AB, B1, ER, etc. 
		/// For more detailed addresses and specific meanings, please refer to the API documentation
		/// </summary>
		/// <param name="device">设备通信对象</param>
		/// <param name="station">表号信息，也叫站号信息</param>
		/// <param name="address">数据的地址信息，地址示例：M1,M2,M3,AA,AB,B1,ER等</param>
		/// <param name="value">等待写入的值</param>
		/// <returns>是否写入成功</returns>
		public static OResult Write(IReadWriteDevice device, byte station, string address, double value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = device.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (oResult2.Content[0] != 6)
			{
				return new OResult<double>("ACK check failed: " + oResult2.Content.ToHexString(' '));
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.ReadDouble(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String)" />
		public static async Task<OResult<double>> ReadDoubleAsync(IReadWriteDevice device, byte station, string address)
		{
			OResult<byte[]> oResult = BuildReadCommand(station, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<double>(oResult);
			}
			OResult<byte[]> oResult2 = await device.ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<double>(oResult2);
			}
			if (oResult2.Content[0] != 2)
			{
				return new OResult<double>("STX check failed: " + oResult2.Content.ToHexString(' '));
			}
			try
			{
				return OResult.CreateSuccessResult(double.Parse(Encoding.ASCII.GetString(oResult2.Content, 3, oResult2.Content.Length - 5)));
			}
			catch (Exception ex)
			{
				return new OResult<double>(ex.Message + Environment.NewLine + "Source: " + oResult2.Content.ToHexString(' '));
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.RKC.Helper.TemperatureControllerHelper.Write(Snet.Driver.Core.IReadWriteDevice,System.Byte,System.String,System.Double)" />
		public static async Task<OResult> WriteAsync(IReadWriteDevice device, byte station, string address, double value)
		{
			OResult<byte[]> oResult = BuildWriteCommand(station, address, value);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await device.ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (oResult2.Content[0] != 6)
			{
				return new OResult<double>("ACK check failed: " + oResult2.Content.ToHexString(' '));
			}
			return OResult.CreateSuccessResult();
		}
	}
}
namespace Snet.Driver.Instrument.Light
{
	/// <summary>
	/// 光源的数据信息
	/// </summary>
	public class ShineInLightData
	{
		/// <summary>
		/// 光源颜色信息，1:红色  2:绿色  3:蓝色  4:白色(默认)
		/// </summary>
		public byte Color { get; set; }

		/// <summary>
		/// 光源的亮度信息，00-FF，值越大，亮度越大
		/// </summary>
		public byte Light { get; set; }

		/// <summary>
		/// 光源的亮度等级，1-3
		/// </summary>
		public byte LightDegree { get; set; }

		/// <summary>
		/// 光源的工作模式，00:延时常亮  01:通道一频闪  02:通道二频闪  03:通道一二频闪  04:普通常亮  05:关闭
		/// </summary>
		public byte WorkMode { get; set; }

		/// <summary>
		/// 控制器的地址选择位
		/// </summary>
		public byte Address { get; set; }

		/// <summary>
		/// 脉冲宽度，01-14H
		/// </summary>
		public byte PulseWidth { get; set; }

		/// <summary>
		/// 通道数据，01-08H的值
		/// </summary>
		public byte Channel { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public ShineInLightData()
		{
			Color = 4;
			LightDegree = 1;
			PulseWidth = 1;
		}

		/// <summary>
		/// 使用指定的原始数据来获取当前的对象
		/// </summary>
		/// <param name="data">原始数据</param>
		public ShineInLightData(byte[] data)
			: this()
		{
			ParseFrom(data);
		}

		/// <summary>
		/// 获取原始的数据信息
		/// </summary>
		/// <returns>原始的字节信息</returns>
		public byte[] GetSourceData()
		{
			return new byte[7] { Color, Light, LightDegree, WorkMode, Address, PulseWidth, Channel };
		}

		/// <summary>
		/// 从原始的信息解析光源的数据
		/// </summary>
		/// <param name="data">原始的数据信息</param>
		public void ParseFrom(byte[] data)
		{
			if (data == null || data.Length >= 7)
			{
				Color = data[0];
				Light = data[1];
				LightDegree = data[2];
				WorkMode = data[3];
				Address = data[4];
				PulseWidth = data[5];
				Channel = data[6];
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"ShineInLightData[{Color}]";
		}
	}
	/// <summary>
	/// 昱行智造科技（深圳）有限公司的光源控制器，可以控制灯的亮暗，控制灯的颜色，通道等信息。
	/// </summary>
	public class ShineInLightSourceController : SerialBase
	{
		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public ShineInLightSourceController()
		{
		}

		/// <summary>
		/// 初始化串口信息，波特率，8位数据位，1位停止位，偶校验<br />
		/// Initializes serial port information, baud rate, 8-bit data bit, 1-bit stop bit, even parity
		/// </summary>
		/// <param name="portName">端口号信息，例如"COM3"</param>
		/// <param name="baudRate">波特率</param>
		public override void SerialPortInni(string portName, int baudRate)
		{
			SerialPortInni(portName, baudRate, 8, (StopBits)1, (Parity)2);
		}

		/// <summary>
		/// 初始化串口信息，57600波特率，8位数据位，1位停止位，偶校验<br />
		/// Initial serial port information, 57600 baud rate, 8 data bits, 1 stop bit, even parity
		/// </summary>
		/// <param name="portName">端口号信息，例如"COM3"</param>
		public override void SerialPortInni(string portName)
		{
			SerialPortInni(portName, 57600);
		}

		/// <summary>
		/// 读取光源控制器的参数信息，需要传入通道号信息，读取到详细的内容参照<see cref="T:Snet.Driver.Instrument.Light.ShineInLightData" />的值
		/// </summary>
		/// <param name="channel">读取的通道信息</param>
		/// <returns>读取的参数值</returns>
		public OResult<ShineInLightData> Read(byte channel)
		{
			OResult<byte[]> oResult = ReadFromCoreServer(BuildReadCommand(channel));
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<ShineInLightData>();
			}
			OResult<byte[]> oResult2 = ExtractActualData(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2.ConvertFailed<ShineInLightData>();
			}
			return OResult.CreateSuccessResult(new ShineInLightData(oResult2.Content));
		}

		/// <summary>
		/// 将光源控制器的数据写入到设备，返回是否写入成功
		/// </summary>
		/// <param name="data">光源数据</param>
		/// <returns>是否写入成功</returns>
		public OResult Write(ShineInLightData data)
		{
			OResult<byte[]> oResult = ReadFromCoreServer(BuildWriteCommand(data));
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<ShineInLightData>();
			}
			return ExtractActualData(oResult.Content);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return "ShineInLightSourceController[" + base.PortName + "]";
		}

		/// <summary>
		/// 将命令和数据打包成用于发送的报文
		/// </summary>
		/// <param name="cmd">命令</param>
		/// <param name="data">命令数据</param>
		/// <returns>可用于发送的报文</returns>
		public static byte[] PackCommand(byte cmd, byte[] data)
		{
			if (data == null)
			{
				data = new byte[0];
			}
			byte[] array = new byte[data.Length + 8];
			array[0] = 47;
			array[1] = 42;
			array[2] = 240;
			array[3] = cmd;
			array[4] = (byte)(array.Length - 4);
			data.CopyTo(array, 5);
			array[^2] = 42;
			array[^1] = 47;
			int num = array[2];
			for (int i = 3; i < array.Length - 3; i++)
			{
				num ^= array[i];
			}
			array[^3] = (byte)num;
			return array;
		}

		/// <summary>
		/// 构建写入数据的报文命令
		/// </summary>
		/// <param name="shineInLightData">准备写入的数据</param>
		/// <returns>报文命令</returns>
		public static byte[] BuildWriteCommand(ShineInLightData shineInLightData)
		{
			return PackCommand(1, shineInLightData.GetSourceData());
		}

		/// <summary>
		/// 构建读取数据的报文命令
		/// </summary>
		/// <param name="channel">通道信息</param>
		/// <returns>构建读取的命令</returns>
		public static byte[] BuildReadCommand(byte channel)
		{
			return PackCommand(2, new byte[1] { channel });
		}

		/// <summary>
		/// 把服务器反馈的数据解析成实际的命令
		/// </summary>
		/// <param name="response">反馈的数据</param>
		/// <returns>结果内容</returns>
		public static OResult<byte[]> ExtractActualData(byte[] response)
		{
			if (response.Length < 9)
			{
				return new OResult<byte[]>("Receive Data is too short; source:" + response.ToHexString(' '));
			}
			if (response[0] != 47 || response[1] != 42 || response[^2] != 42 || response[^1] != 47)
			{
				return new OResult<byte[]>("Receive Data not start with /* or end with */; source:" + response.ToHexString());
			}
			if (response[3] == 1)
			{
				if (response[5] != 170)
				{
					return new OResult<byte[]>(response[5], "set not success");
				}
				return OResult.CreateSuccessResult(new byte[0]);
			}
			return OResult.CreateSuccessResult(response.SelectMiddle(5, response.Length - 8));
		}
	}
}
namespace Snet.Driver.Instrument.IEC
{
	/// <summary>
	/// IEC104规约实现的电力协议，支持总召唤，支持回调任意的突发上传事件
	/// </summary>
	/// <remarks>
	/// 手动绑定事件 <see cref="E:Snet.Driver.Instrument.IEC.IEC104.OnIEC104MessageReceived" />，当收到设备的数据时就可以触发，如果需要总召唤，调用方法 <see cref="M:Snet.Driver.Instrument.IEC.IEC104.TotalSubscriptions(System.Byte)" />
	/// </remarks>
	/// <example>
	/// 一般来说，实例化之后，绑定事件，连接即可，然后定时调用总召唤（定时调用时还可以判断是否连接成功）
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Instrument\IEC104Sample.cs" region="Sample1" title="自定义的使用" />
	/// 当然可以使用Snet辅助解析数据
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Instrument\IEC104Sample.cs" region="Sample2" title="便捷的解析" />
	/// </example>
