		private int deviceSendLastID;

		private object receiveLock = new object();

		private readonly SoftIncrementCount sendIncrementCount;

		private int receiveIncrementCount;

		private int station = 1;

		/// <summary>
		/// 公共单元地址，在低版本远动程序中，站地址范围一般在1~254，255表示全局地址。新远动程序则可支持1~65534为站地址，而65535为全局地址。默认值为1
		/// </summary>
		public int Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 当接收到了IEC104的消息触发的事件
		/// </summary>
		public event EventHandler<IEC104MessageEventArgs> OnIEC104MessageReceived;

		/// <summary>
		/// 实例化IEC104协议的通讯对象<br />
		/// Instantiate the communication object of the IEC104 protocol
		/// </summary>
		public IEC104()
		{
			base.WordLength = 2;
			base.ByteTransform = new RegularByteTransform();
			sendIncrementCount = new SoftIncrementCount(32767L, 0L);
		}

		/// <summary>
		/// 指定ip地址和端口号来实例化一个默认的对象<br />
		/// Specify the IP address and port number to instantiate a default object
		/// </summary>
		/// <param name="ipAddress">IEC104的Ip地址</param>
		/// <param name="port">IEC104的端口, 默认是2404端口</param>
		public IEC104(string ipAddress, int port = 2404)
			: this()
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new IEC104Message();
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			OResult oResult = CommunicationPipe.Send(IECHelper.BuildFrameUMessage(7));
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			LogSendMessage(IECHelper.BuildFrameUMessage(7));
			OResult oResult2 = CommunicationPipe.ReceiveMessage(GetNewNetMessage(), null, useActivePush: false, null, base.LogRevcMessage);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			CommunicationPipe.UseServerActivePush = true;
			sendIncrementCount.ResetCurrentValue(0L);
			receiveIncrementCount = 0;
			deviceSendLastID = 0;
			return base.InitializationOnConnect();
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			OResult oResult = await CommunicationPipe.SendAsync(IECHelper.BuildFrameUMessage(7)).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			LogSendMessage(IECHelper.BuildFrameUMessage(7));
			OResult oResult2 = await CommunicationPipe.ReceiveMessageAsync(GetNewNetMessage(), null, useActivePush: false, null, base.LogRevcMessage).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			CommunicationPipe.UseServerActivePush = true;
			sendIncrementCount.ResetCurrentValue(0L);
			receiveIncrementCount = 0;
			deviceSendLastID = 0;
			return await base.InitializationOnConnectAsync();
		}

		/// <inheritdoc />
		public override OResult Write(string address, bool value)
		{
			byte[] obj = new byte[10] { 45, 1, 3, 0, 0, 0, 0, 0, 0, 0 };
			obj[4] = BitConverter.GetBytes(station)[0];
			obj[5] = BitConverter.GetBytes(station)[1];
			byte[] array = obj;
			BitConverter.GetBytes(ushort.Parse(address)).CopyTo(array, 6);
			if (value)
			{
				array[9] = 1;
			}
			return SendFrameIMessage(array);
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.IEC.IEC104.WriteIec(System.Byte,System.UInt16,System.UInt16,System.Byte[])" />
		public OResult WriteIec(byte type, ushort reason, ushort address, bool value)
		{
			return WriteIec(type, reason, address, (!value) ? new byte[1] : new byte[1] { 1 });
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.IEC.IEC104.WriteIec(System.Byte,System.UInt16,System.UInt16,System.Byte[])" />
		public OResult WriteIec(byte type, ushort reason, ushort address, short value)
		{
			return WriteIec(type, reason, address, BitConverter.GetBytes(value));
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.IEC.IEC104.WriteIec(System.Byte,System.UInt16,System.UInt16,System.Byte[])" />
		public OResult WriteIec(byte type, ushort reason, ushort address, float value)
		{
			return WriteIec(type, reason, address, BitConverter.GetBytes(value));
		}

		/// <summary>
		/// 指定类型标识，传送原因，数据地址，数据值信息来写入到IEC的仪表中去
		/// </summary>
		/// <param name="type">类型标识</param>
		/// <param name="reason">传送原因</param>
		/// <param name="address">信息对象地址</param>
		/// <param name="value">值信息</param>
		/// <returns>是否发送到仪表成功</returns>
		public OResult WriteIec(byte type, ushort reason, ushort address, byte[] value)
		{
			return SendFrameIMessage(IECHelper.BuildWriteIec(type, reason, (ushort)station, address, value));
		}

		private int GetReceiveIncrementCount(int deviceSendID)
		{
			lock (receiveLock)
			{
				if (deviceSendID != deviceSendLastID)
				{
					deviceSendLastID = deviceSendID;
					receiveIncrementCount++;
				}
				int result = receiveIncrementCount;
				if (receiveIncrementCount > 32767)
				{
					receiveIncrementCount = 0;
				}
				return result;
			}
		}

		/// <inheritdoc />
		protected override bool DecideWhetherQAMessage(CommunicationPipe pipe, OResult<byte[]> receive)
		{
			if (!receive.IsSuccess)
			{
				return false;
			}
			LogRevcMessage(receive.Content);
			byte[] content = receive.Content;
			if (content.Length < 6)
			{
				return false;
			}
			if (!content[2].GetBoolByIndex(0) && !content[4].GetBoolByIndex(0))
			{
				int num = BitConverter.ToUInt16(content, 2) / 2;
				_ = BitConverter.ToUInt16(content, 4) / 2;
				int num2 = GetReceiveIncrementCount(num);
				byte[] array = IECHelper.BuildFrameSMessage(num2);
				LogSendMessage(array);
				pipe.Send(array);
				if (num2 != num)
				{
					base.LogNet?.WriteError(ToString(), $"send[{num}] receive[{num2}] message id check failed: ");
				}
				IEC104MessageEventArgs e = null;
				try
				{
					e = new IEC104MessageEventArgs(content.RemoveBegin(6));
				}
				catch (Exception ex)
				{
					base.LogNet?.WriteException(ToString(), "IEC104MessageEventArg..ctor failed: " + content.ToHexString(' '), ex);
				}
				if (e != null)
				{
					OnIEC104MessageReceived?.Invoke(this, e);
				}
			}
			else if (((content[2] & 3) != 1 || content[4].GetBoolByIndex(0)) && (content[2] & 3) == 3 && !content[4].GetBoolByIndex(0) && content[2] == 67)
			{
				byte[] array2 = IECHelper.BuildFrameUMessage(131);
				LogSendMessage(array2);
				pipe.Send(array2);
			}
			return false;
		}

		/// <summary>
		/// 以I消息的格式发送传入的原始字节数据，传入的消息为asdu信息
		/// </summary>
		/// <param name="asdu">ASDU报文信息</param>
		/// <returns>是否发送成功</returns>
		public OResult SendFrameIMessage(byte[] asdu)
		{
			if (CommunicationPipe.IsConnectError())
			{
				OResult oResult = ConnectServer();
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			int sendID = (int)sendIncrementCount.GetCurrentValue();
			int receiveID = receiveIncrementCount;
			byte[] array = IECHelper.BuildFrameIMessage(sendID, receiveID, asdu[0], asdu[1], base.ByteTransform.TransUInt16(asdu, 2), base.ByteTransform.TransUInt16(asdu, 4), asdu.RemoveBegin(6));
			LogSendMessage(array);
			return CommunicationPipe.Send(array);
		}

		/// <summary>
		/// 向设备发送U帧消息的报文信息，传入功能码，STARTDT: 0x07, STOPDT: 0x13; TESTFR: 0x43
		/// </summary>
		/// <param name="controlField">功能码，STARTDT: 0x07, STOPDT: 0x13; TESTFR: 0x43</param>
		/// <returns>是否发送成功</returns>
		public OResult SendFrameUMessage(byte controlField)
		{
			if (CommunicationPipe.IsConnectError())
			{
				OResult oResult = ConnectServer();
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			byte[] array = IECHelper.BuildFrameUMessage(controlField);
			LogSendMessage(array);
			return CommunicationPipe.Send(array);
		}

		/// <summary>
		/// 总召唤，支持设置总召唤代码，0x01: 定时主动上送,  0x14: 相应总召唤上送,  0x03: 越限上送
		/// </summary>
		/// <param name="code">总召唤的代码，0x01: 定时主动上送,  0x14: 相应总召唤上送,  0x03: 越限上送</param>
		/// <returns>是否召唤成功</returns>
		public OResult TotalSubscriptions(byte code = 20)
		{
			return TotalSubscriptions(code, 6);
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.IEC.IEC104.TotalSubscriptions(System.UInt16,System.Byte,System.Byte)" />
		public OResult TotalSubscriptions(byte code, byte reason)
		{
			return TotalSubscriptions((ushort)Station, code, reason);
		}

		/// <summary>
		/// 总召唤，支持设置总召唤代码，0x01: 定时主动上送,  0x14: 相应总召唤上送,  0x03: 越限上送
		/// </summary>
		/// <param name="station">公共单元地址</param>
		/// <param name="code">总召唤的代码，0x01: 定时主动上送,  0x14: 相应总召唤上送,  0x03: 越限上送</param>
		/// <param name="reason">传送原因，通常可选 06:激活，07:激活确认</param>
		/// <returns>是否总召唤成功</returns>
		public OResult TotalSubscriptions(ushort station, byte code, byte reason)
		{
			byte[] obj = new byte[10] { 100, 1, 0, 0, 1, 0, 0, 0, 0, 0 };
			obj[2] = reason;
			obj[9] = code;
			byte[] array = obj;
			array[4] = BitConverter.GetBytes(station)[0];
			array[5] = BitConverter.GetBytes(station)[1];
			return SendFrameIMessage(array);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"IEC104[{IpAddress}:{Port}]";
		}
	}
	/// <summary>
	/// IEC104的消息事件
	/// </summary>
	public class IEC104MessageEventArgs : EventArgs
	{
		/// <summary>
		/// 获取或设置当前的asdu信息
		/// </summary>
		public byte[] ASDU { get; }

		/// <summary>
		/// 类型标识
		/// </summary>
		public byte TypeID { get; set; }

		/// <summary>
		/// 地址是否连续
		/// </summary>
		public bool IsAddressContinuous { get; set; }

		/// <summary>
		/// 信息对象个数
		/// </summary>
		public int InfoObjectCount { get; set; }

		/// <summary>
		/// 传送原因
		/// </summary>
		public int TransmissionReason { get; set; }

		/// <summary>
		/// 站地址
		/// </summary>
		public int StationAddress { get; set; }

		/// <summary>
		/// 信息体
		/// </summary>
		public byte[] Body { get; set; }

		/// <summary>
		/// 指定asdu消息进行实例化一个对象
		/// </summary>
		/// <param name="asdu">asdu报文</param>
		public IEC104MessageEventArgs(byte[] asdu)
		{
			ASDU = asdu;
			if (asdu != null)
			{
				TypeID = asdu[0];
				IsAddressContinuous = (asdu[1] & 0x80) == 128;
				InfoObjectCount = asdu[1] & 0x7F;
				TransmissionReason = asdu[2] & 0x3F;
				StationAddress = BitConverter.ToUInt16(asdu, 4);
				Body = asdu.RemoveBegin(6);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.IEC.Helper.IECHelper.GetTransmissionReasonText(System.Int32)" />
		public string GetTransmissionReasonText()
		{
			return IECHelper.GetTransmissionReasonText(TransmissionReason);
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.IEC.Helper.IECHelper.GetTypeIDText(System.Int32)" />
		public string GetTypeIDText()
		{
			return IECHelper.GetTypeIDText(TypeID);
		}

		/// <summary>
		/// 获取当前的消息是否带时标信息
		/// </summary>
		/// <returns>是否携带时间标度信息</returns>
		public bool WithTimeInfo()
		{
			if (TypeID < 30)
			{
				return false;
			}
			if (TypeID < 45)
			{
				return true;
			}
			if (TypeID < 58)
			{
				return false;
			}
			if (TypeID < 70)
			{
				return true;
			}
			return false;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return string.Format("{0} [{1}:{2}] Reason[{3}] Pub-Address[{4}]", GetTypeIDText(), IsAddressContinuous ? "Continuous" : "Uncontinuous", InfoObjectCount, GetTransmissionReasonText(), StationAddress);
		}
	}
	/// <summary>
	/// IEC104的虚拟服务器，支持总召唤操作，数据区包含单点遥信，双点遥信，归一化遥测值，标度化遥测值，短浮点遥测值，32位比特串，默认地址数量100，也可以手动设置更大的地址范围<br />
	/// The virtual server of IEC104 supports total call operation. The data area includes single-point remote signaling, dual-point remote signaling, 
	/// normalized telemetry values, scaled telemetry values, short floating-point telemetry values, 32-bit bit strings, and the default address range is 100. A larger address range can also be manually set
	/// </summary>
	/// <remarks>
	/// 如果需要手动设置更大的地址范围，例如短浮点遥测1000个地址，可以使用代码 server.YaoCeC.SetValues( 0, 1000 );<br />
	/// If you need to manually set a larger address range, such as 1000 short floating-point telemetry addresses, you can use the code server.YaoCeC.SetValues(0, 1000);
	/// </remarks>
	public class IEC104Server : DeviceServer
	{
		private IecValueServerObject<byte> list_单点遥信 = new IecValueServerObject<byte>(0, 100, 1, (IecValueObject<byte> m) => new byte[1] { (byte)(m.Quality | m.Value) });

		private IecValueServerObject<byte> list_双点遥信 = new IecValueServerObject<byte>(0, 100, 3, (IecValueObject<byte> m) => new byte[1] { (byte)(m.Quality | m.Value) });

		private IecValueServerObject<short> list_归一化遥测值 = new IecValueServerObject<short>(0, 100, 9, (IecValueObject<short> m) => BitConverter.GetBytes(m.Value));

		private IecValueServerObject<short> list_标度化遥测值 = new IecValueServerObject<short>(0, 100, 11, (IecValueObject<short> m) => BitConverter.GetBytes(m.Value));

		private IecValueServerObject<float> list_短浮点遥测值 = new IecValueServerObject<float>(0, 100, 13, (IecValueObject<float> m) => BitConverter.GetBytes(m.Value));

		private IecValueServerObject<uint> list_比特串 = new IecValueServerObject<uint>(0, 100, 7, (IecValueObject<uint> m) => BitConverter.GetBytes(m.Value));

		/// <summary>
		/// 获取或设置默认的数据单元公共地址，默认值为 1
		/// </summary>
		public byte PubAddress { get; set; } = 1;

		/// <summary>
		/// 单点遥信，类型ID为: M_SP_NA_1
		/// </summary>
		public IecValueServerObject<byte> SingleYaoXin => list_单点遥信;

		/// <summary>
		/// 双点遥信，类型ID为: M_DP_NA_1
		/// </summary>
		public IecValueServerObject<byte> DoubleYaoXin => list_双点遥信;

		/// <summary>
		/// 归一化遥测值，类型ID: M_ME_NA_1
		/// </summary>
		public IecValueServerObject<short> YaoCeA => list_归一化遥测值;

		/// <summary>
		/// 标度化遥测值，类型ID: M_ME_NB_1
		/// </summary>
		public IecValueServerObject<short> YaoCeB => list_标度化遥测值;

		/// <summary>
		/// 短浮点遥测值，类型ID: M_ME_NC_1
		/// </summary>
		public IecValueServerObject<float> YaoCeC => list_短浮点遥测值;

		/// <summary>
		/// 32位比特串，类型ID: M_BO_NA_1
		/// </summary>
		public IecValueServerObject<uint> BitArray => list_比特串;

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public IEC104Server()
		{
			base.Port = 2404;
			list_单点遥信.OnIecValueChanged = IecValueChangedHelper;
			list_双点遥信.OnIecValueChanged = IecValueChangedHelper;
			list_归一化遥测值.OnIecValueChanged = IecValueChangedHelper;
			list_标度化遥测值.OnIecValueChanged = IecValueChangedHelper;
			list_短浮点遥测值.OnIecValueChanged = IecValueChangedHelper;
			list_比特串.OnIecValueChanged = IecValueChangedHelper;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new IEC104Message();
		}

		private void IecValueChangedHelper<T>(IecValueServerObject<T> iecValueServer, IecValueObject<T> iecValue)
		{
			PipeSession[] pipeSessions = GetCommunicationServer().GetPipeSessions();
			foreach (PipeSession pipeSession in pipeSessions)
			{
				IECSessionInfo sessionInfo = pipeSession.Tag as IECSessionInfo;
				SendAsdu(pipeSession, sessionInfo, iecValueServer.GetAsduBreakOut(iecValue, PubAddress));
			}
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive == null || receive.Length < 6)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (receive[0] != 104)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (session.Tag == null)
			{
				session.Tag = new IECSessionInfo();
			}
			if (!receive[2].GetBoolByIndex(0) && !receive[4].GetBoolByIndex(0))
			{
				IECSessionInfo iECSessionInfo = session.Tag as IECSessionInfo;
				iECSessionInfo.IncrRecvMessageID();
				StringBuilder stringBuilder = new StringBuilder(IECHelper.GetTypeIDText(receive[6]) + " 传送原因[" + IECHelper.GetTransmissionReasonText(receive[8]) + "] ");
				if (receive[6] == 100)
				{
					if (receive[8] == 6)
					{
						SendAsdu(session, iECSessionInfo, "64 01 07 00 01 00 00 00 00 14");
						SendAdsu(session, iECSessionInfo, list_单点遥信, 20, PubAddress);
						SendAdsu(session, iECSessionInfo, list_双点遥信, 20, PubAddress);
						SendAdsu(session, iECSessionInfo, list_归一化遥测值, 20, PubAddress);
						SendAdsu(session, iECSessionInfo, list_标度化遥测值, 20, PubAddress);
						SendAdsu(session, iECSessionInfo, list_短浮点遥测值, 20, PubAddress);
						SendAdsu(session, iECSessionInfo, list_比特串, 20, PubAddress);
						SendAsdu(session, iECSessionInfo, "64 01 0A 00 01 00 00 00 00 14");
					}
				}
				else if (receive[6] == 48)
				{
					SetReceiveValue(list_归一化遥测值, receive, BitConverter.ToInt16, stringBuilder);
				}
				else if (receive[6] == 49)
				{
					SetReceiveValue(list_标度化遥测值, receive, BitConverter.ToInt16, stringBuilder);
				}
				else if (receive[6] == 50)
				{
					SetReceiveValue(list_短浮点遥测值, receive, BitConverter.ToSingle, stringBuilder);
				}
				else if (receive[6] == 51)
				{
					SetReceiveValue(list_比特串, receive, BitConverter.ToUInt32, stringBuilder);
				}
				else if (receive[6] == 45)
				{
					SetReceiveValue(list_单点遥信, receive, (byte[] m, int index) => m[index], stringBuilder);
				}
				else if (receive[6] == 46)
				{
					SetReceiveValue(list_双点遥信, receive, (byte[] m, int index) => m[index], stringBuilder);
				}
				base.LogNet?.WriteInfo(ToString(), stringBuilder.ToString());
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (receive[2].GetBoolByIndex(0) && !receive[4].GetBoolByIndex(0))
			{
				if (receive[2].GetBoolByIndex(1))
				{
					base.LogNet?.WriteInfo(ToString(), "U帧报文-" + ((receive[2] == 7) ? "启动" : ((receive[2] == 19) ? "停止" : "测试")));
					if (receive[2] == 7)
					{
						return OResult.CreateSuccessResult(IECHelper.PackIEC104Message(11, 0, 0, 0, null));
					}
					if (receive[2] == 19)
					{
						return OResult.CreateSuccessResult(IECHelper.PackIEC104Message(35, 0, 0, 0, null));
					}
					if (receive[2] == 67)
					{
						return OResult.CreateSuccessResult(IECHelper.PackIEC104Message(131, 0, 0, 0, null));
					}
					return OResult.CreateSuccessResult(new byte[0]);
				}
				base.LogNet?.WriteInfo(ToString(), "S帧报文");
				return OResult.CreateSuccessResult(new byte[0]);
			}
			return base.ReadFromCoreServer(session, receive);
		}

		private void SetReceiveValue<T>(IecValueServerObject<T> serverObject, byte[] receive, Func<byte[], int, T> trans, StringBuilder stringBuilder)
		{
			int add = BitConverter.ToUInt16(receive, 12);
			T value = trans(receive, 15);
			IecValueObject<T> iecValueObject = serverObject.Values.FirstOrDefault((IecValueObject<T> m) => m.Address == add);
			if (iecValueObject != null)
			{
				iecValueObject.Value = value;
			}
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(13, 2, stringBuilder);
			handler.AppendLiteral("Address[");
			handler.AppendFormatted(add);
			handler.AppendLiteral("] = ");
			handler.AppendFormatted(value);
			handler.AppendLiteral(" ");
			stringBuilder.Append(ref handler);
		}

		private void SendAdsu<T>(PipeSession session, IECSessionInfo sessionInfo, IecValueServerObject<T> value, byte reason, byte station)
		{
			List<byte[]> asduCommand = value.GetAsduCommand(reason, station);
			for (int i = 0; i < asduCommand.Count; i++)
			{
				SendAsdu(session, sessionInfo, asduCommand[i]);
			}
		}

		private void SendAsdu(PipeSession session, IECSessionInfo sessionInfo, string asdu)
		{
			SendAsdu(session, sessionInfo, asdu.ToHexBytes());
		}

		private void SendAsdu(PipeSession session, IECSessionInfo sessionInfo, byte[] asdu)
		{
			byte[] array = IECHelper.PackIEC104Message((ushort)(sessionInfo.GetSendMessageID() * 2), (ushort)(sessionInfo.RecvMessageID * 2), asdu);
			session.Communication.Send(array);
			LogSendMessage(array, session);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"IEC104Server[{base.Port}]";
		}
	}
	/// <summary>
	/// IEC的数据对象，带值，品质信息，地址信息，时标信息
	/// </summary>
	/// <typeparam name="T">数据的类型</typeparam>
	public class IecValueObject<T>
	{
		private T m_value;

		/// <summary>
		/// 值信息
		/// </summary>
		public T Value
		{
			get
			{
				return m_value;
			}
			set
			{
				bool flag = false;
				if (!m_value.Equals(value))
				{
					flag = true;
				}
				m_value = value;
				if (flag)
				{
					OnValueChanged?.Invoke(this);
				}
			}
		}

		/// <summary>
		/// 品质数据
		/// </summary>
		public byte Quality { get; set; }

		/// <summary>
		/// 时间信息，对于不带绝对时标的则无效
		/// </summary>
		public DateTime Time { get; set; }

		/// <summary>
		/// 地址
		/// </summary>
		public int Address { get; set; }

		/// <summary>
		/// 值发生变化的事件
		/// </summary>
		public Action<IecValueObject<T>> OnValueChanged { get; set; }

		/// <summary>
		/// 用户关联的自定义对象
		/// </summary>
		public object Tag { get; set; }

		/// <summary>
		/// 解析不连续的遥信值的方法，对于返回的 byte 类型的指，单点遥信：0 开，1合、双点遥信: 1开，2合，0和3不确定状态或中间填充
		/// </summary>
		/// <param name="message">IEC104的消息</param>
		/// <returns>列表值</returns>
		public static List<IecValueObject<byte>> ParseYaoXinValue(IEC104MessageEventArgs message)
		{
			bool flag = message.WithTimeInfo();
			List<IecValueObject<byte>> list = new List<IecValueObject<byte>>();
			DateTime time = DateTime.MinValue;
			if (message.IsAddressContinuous)
			{
				if (flag && message.Body.Length >= message.InfoObjectCount + 3 + 7)
				{
					time = IECHelper.PraseTimeFromAbsoluteTimeScale(message.Body, message.InfoObjectCount + 3);
				}
				ushort num = BitConverter.ToUInt16(message.Body, 0);
				for (int i = 0; i < message.InfoObjectCount; i++)
				{
					int num2 = 3 + i;
					if (num2 >= message.Body.Length)
					{
						return list;
					}
					IecValueObject<byte> iecValueObject = new IecValueObject<byte>();
					iecValueObject.Address = num + i;
					iecValueObject.Value = (byte)(message.Body[num2] & 0xF);
					iecValueObject.Quality = (byte)(message.Body[num2] & 0xF0);
					if (flag)
					{
						iecValueObject.Time = time;
					}
					list.Add(iecValueObject);
				}
			}
			else
			{
				if (flag && message.Body.Length >= message.InfoObjectCount * 4 + 7)
				{
					time = IECHelper.PraseTimeFromAbsoluteTimeScale(message.Body, message.InfoObjectCount * 4);
				}
				for (int j = 0; j < message.InfoObjectCount; j++)
				{
					int num3 = 4 * j;
					if (num3 >= message.Body.Length)
					{
						return list;
					}
					IecValueObject<byte> iecValueObject2 = new IecValueObject<byte>();
					iecValueObject2.Address = BitConverter.ToUInt16(message.Body, num3);
					iecValueObject2.Value = (byte)(message.Body[num3 + 3] & 0xF);
					iecValueObject2.Quality = (byte)(message.Body[num3 + 3] & 0xF0);
					if (flag)
					{
						iecValueObject2.Time = time;
					}
					list.Add(iecValueObject2);
				}
			}
			return list;
		}

		/// <summary>
		/// 解析不连续的的数据，返回指定的类型信息
		/// </summary>
		/// <param name="iEC104Message">IEC104的消息</param>
		/// <returns>值列表信息</returns>
		public static List<IecValueObject<short>> ParseInt16Value(IEC104MessageEventArgs iEC104Message)
		{
			return IECHelper.ParseYaoCeValue(iEC104Message, BitConverter.ToInt16, 2);
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.IEC.IecValueObject`1.ParseInt16Value(Snet.Driver.Instrument.IEC.IEC104MessageEventArgs)" />
		public static List<IecValueObject<float>> ParseFloatValue(IEC104MessageEventArgs iEC104Message)
		{
			return IECHelper.ParseYaoCeValue(iEC104Message, BitConverter.ToSingle, 4);
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.IEC.IecValueObject`1.ParseInt16Value(Snet.Driver.Instrument.IEC.IEC104MessageEventArgs)" />
		public static List<IecValueObject<uint>> ParseUInt32Value(IEC104MessageEventArgs iEC104Message)
		{
			return IECHelper.ParseYaoCeValue(iEC104Message, BitConverter.ToUInt32, 4);
		}
	}
	/// <summary>
	/// 服务器端的IEC数据对象信息，可以实例化不连续地址，或是连续地址信息
	/// </summary>
	/// <typeparam name="T">类型信息</typeparam>
	public class IecValueServerObject<T>
	{
		private Func<IecValueObject<T>, byte[]> _trans;

		private byte _typeID;

		/// <summary>
		/// 地址是否连续
		/// </summary>
		public bool IsAddressContinuous { get; private set; }

		/// <summary>
		/// 类型ID信息
		/// </summary>
		public byte TypeID => _typeID;

		/// <summary>
		/// IEC数据对象值
		/// </summary>
		public List<IecValueObject<T>> Values { get; private set; }

		/// <summary>
		/// 当值发生变化的时候
		/// </summary>
		public Action<IecValueServerObject<T>, IecValueObject<T>> OnIecValueChanged { get; set; }

		/// <summary>
		/// 实例化一个不连续地址的数据对象
		/// </summary>
		/// <param name="value">列表值</param>
		/// <param name="typeID">数据标识</param>
		/// <param name="trans">转换方法</param>
		public IecValueServerObject(List<IecValueObject<T>> value, byte typeID, Func<IecValueObject<T>, byte[]> trans)
		{
			_typeID = typeID;
			_trans = trans;
			SetValues(value);
		}

		/// <summary>
		/// 实例化一个连续地址的数据对象
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="length">长度</param>
		/// <param name="typeID">数据标识</param>
		/// <param name="trans">原始字节转换关系</param>
		public IecValueServerObject(ushort address, int length, byte typeID, Func<IecValueObject<T>, byte[]> trans)
		{
			_typeID = typeID;
			_trans = trans;
			SetValues(address, length);
		}

		/// <summary>
		/// 设置不连续的地址数据信息
		/// </summary>
		/// <param name="values">iec的值对象</param>
		public void SetValues(List<IecValueObject<T>> values)
		{
			Values = values;
			IsAddressContinuous = false;
			values.ForEach(delegate(IecValueObject<T> m)
			{
				m.OnValueChanged = Iec104ValueChanged;
			});
		}

		/// <summary>
		/// 设置连续的地址数据信息
		/// </summary>
		/// <param name="address">起始地址</param>
		/// <param name="length">数据长度</param>
		public void SetValues(ushort address, int length)
		{
			Values = new List<IecValueObject<T>>();
			for (int i = 0; i < length; i++)
			{
				IecValueObject<T> iecValueObject = new IecValueObject<T>();
				iecValueObject.Address = address + i;
				iecValueObject.OnValueChanged = Iec104ValueChanged;
				Values.Add(iecValueObject);
			}
			IsAddressContinuous = true;
		}

		private List<byte[]> GetAsduCommandByList(List<IecValueObject<T>> iecValues, bool isAddressContinuous, byte reason, byte station)
		{
			List<byte[]> list = new List<byte[]>();
			int i = 0;
			int num = _trans(iecValues[0]).Length + ((!isAddressContinuous) ? 3 : 0);
			if (_typeID != 1 && _typeID != 3)
			{
				num++;
			}
			if (isAddressContinuous)
			{
				int num3;
				for (; i < iecValues.Count; i += num3)
				{
					MemoryStream memoryStream = new MemoryStream();
					memoryStream.WriteByte(_typeID);
					int num2 = 128;
					int val = 240 / num;
					num3 = Math.Min(iecValues.Count - i, val);
					if (num3 > 127)
					{
						num3 = 127;
					}
					num2 |= num3;
					memoryStream.WriteByte((byte)num2);
					memoryStream.WriteByte(reason);
					memoryStream.WriteByte(0);
					memoryStream.WriteByte(station);
					memoryStream.WriteByte(0);
					memoryStream.Write(BitConverter.GetBytes((ushort)iecValues[i].Address));
					memoryStream.WriteByte(0);
					for (int j = 0; j < num3; j++)
					{
						memoryStream.Write(_trans(iecValues[j + i]));
						if (_typeID != 1 && _typeID != 3)
						{
							memoryStream.WriteByte(iecValues[j + i].Quality);
						}
					}
					list.Add(memoryStream.ToArray());
				}
			}
			else
			{
				int num5;
				for (; i < iecValues.Count; i += num5)
				{
					MemoryStream memoryStream2 = new MemoryStream();
					memoryStream2.WriteByte(_typeID);
					int num4 = 0;
					int val2 = 243 / num;
					num5 = Math.Min(iecValues.Count - i, val2);
					if (num5 > 127)
					{
						num5 = 127;
					}
					num4 |= num5;
					memoryStream2.WriteByte((byte)num4);
					memoryStream2.WriteByte(reason);
					memoryStream2.WriteByte(0);
					memoryStream2.WriteByte(station);
					memoryStream2.WriteByte(0);
					for (int k = 0; k < num5; k++)
					{
						memoryStream2.Write(BitConverter.GetBytes((ushort)iecValues[k + i].Address));
						memoryStream2.WriteByte(0);
						memoryStream2.Write(_trans(iecValues[k + i]));
						if (_typeID != 1 && _typeID != 3)
						{
							memoryStream2.WriteByte(iecValues[k + i].Quality);
						}
					}
					list.Add(memoryStream2.ToArray());
				}
			}
			return list;
		}

		/// <summary>
		/// 获取发送的Asdu报文信息
		/// </summary>
		/// <param name="reason">传送原因</param>
		/// <param name="station">公共地址</param>
		/// <returns></returns>
		public List<byte[]> GetAsduCommand(byte reason, byte station)
		{
			return GetAsduCommandByList(Values, IsAddressContinuous, reason, station);
		}

		/// <summary>
		/// 获取一个突发的数据变化的报文信息
		/// </summary>
		/// <param name="iecValue">数据变化值</param>
		/// <param name="station">公共地址</param>
		/// <returns>发送客户端的报文</returns>
		public byte[] GetAsduBreakOut(IecValueObject<T> iecValue, byte station)
		{
			return GetAsduCommandByList(new List<IecValueObject<T>> { iecValue }, isAddressContinuous: false, 3, station)[0];
		}

		private void Iec104ValueChanged(IecValueObject<T> iecValue)
		{
			OnIecValueChanged?.Invoke(this, iecValue);
		}
	}
}
namespace Snet.Driver.Instrument.IEC.Helper
{
	/// <summary>
	/// IEC协议的辅助类信息
	/// </summary>
	public class IECHelper
	{
		/// <summary>
		/// U帧协议里，启动的功能
		/// </summary>
		public const byte IEC104ControlStartDT = 7;

		/// <summary>
		/// U帧协议里，停止的功能
		/// </summary>
		public const byte IEC104ControlStopDT = 19;

		/// <summary>
		/// U帧协议里，测试的功能，主站和子站均可发出
		/// </summary>
		public const byte IEC104ControlTestFR = 67;

		/// <summary>
		/// 将IEC104的报文打包成完整的IEC104标准的协议报文
		/// </summary>
		/// <param name="controlField1">控制域1</param>
		/// <param name="controlField2">控制域2</param>
		/// <param name="controlField3">控制域3</param>
		/// <param name="controlField4">控制域4</param>
		/// <param name="asdu">ASDU报文，包含类型标识，可变结构限定词，传送原因，应用服务器数据单元公共地址，信息体</param>
		/// <returns>完整的报文消息</returns>
		public static byte[] PackIEC104Message(byte controlField1, byte controlField2, byte controlField3, byte controlField4, byte[] asdu)
		{
			byte[] array = new byte[6 + ((asdu != null) ? asdu.Length : 0)];
			array[0] = 104;
			array[1] = (byte)(array.Length - 2);
			array[2] = controlField1;
			array[3] = controlField2;
			array[4] = controlField3;
			array[5] = controlField4;
			if (asdu != null && asdu.Length != 0)
			{
				asdu.CopyTo(array, 6);
			}
			return array;
		}

		internal static byte[] PackIEC104Message(ushort controlField1, ushort controlField2, byte[] asdu)
		{
			return PackIEC104Message(BitConverter.GetBytes(controlField1)[0], BitConverter.GetBytes(controlField1)[1], BitConverter.GetBytes(controlField2)[0], BitConverter.GetBytes(controlField2)[1], asdu);
		}

		/// <summary>
		/// 根据给定的时间，获取绝对时标的报文数据信息
		/// </summary>
		/// <param name="dateTime">时间信息</param>
		/// <param name="valid">时标是否有效</param>
		/// <returns>可用于发送的绝对时标的报文</returns>
		public static byte[] GetAbsoluteTimeScale(DateTime dateTime, bool valid)
		{
			byte[] array = new byte[7]
			{
				BitConverter.GetBytes(dateTime.Millisecond + dateTime.Second * 1000)[0],
				BitConverter.GetBytes(dateTime.Millisecond + dateTime.Second * 1000)[1],
				BitConverter.GetBytes(dateTime.Minute)[0],
				0,
				0,
				0,
				0
			};
			if (!valid)
			{
				array[2] = (byte)(array[2] | 0x80);
			}
			array[3] = BitConverter.GetBytes(dateTime.Hour)[0];
			int num = 1;
			switch (dateTime.DayOfWeek)
			{
			case DayOfWeek.Monday:
				num = 1;
				break;
			case DayOfWeek.Tuesday:
				num = 2;
				break;
			case DayOfWeek.Wednesday:
				num = 3;
				break;
			case DayOfWeek.Thursday:
				num = 4;
				break;
			case DayOfWeek.Friday:
				num = 5;
				break;
			case DayOfWeek.Saturday:
				num = 6;
				break;
			case DayOfWeek.Sunday:
				num = 7;
				break;
			}
			array[4] = BitConverter.GetBytes(dateTime.Day + num * 32)[0];
			array[5] = BitConverter.GetBytes(dateTime.Month)[0];
			array[6] = BitConverter.GetBytes(dateTime.Year - 2000)[0];
			return array;
		}

		/// <summary>
		/// 根据给定的绝对时标的原始内容，解析出实际的时间信息。
		/// </summary>
		/// <param name="source">原始字节</param>
		/// <param name="index">数据的偏移索引</param>
		/// <returns>时间信息</returns>
		public static DateTime PraseTimeFromAbsoluteTimeScale(byte[] source, int index)
		{
			int year = (source[index + 6] & 0x7F) + 2000;
			int month = source[index + 5] & 0xF;
			int day = source[index + 4] & 0x1F;
			int hour = source[index + 3] & 0x1F;
			int minute = source[index + 2] & 0x3F;
			int num = BitConverter.ToUInt16(source, index);
			return new DateTime(year, month, day, hour, minute, num / 1000, num % 1000);
		}

		/// <summary>
		/// 构建一个S帧协议的内容，需要传入接收需要信息
		/// </summary>
		/// <param name="receiveID">接收序号信息</param>
		/// <returns>S帧协议的报文信息</returns>
		public static byte[] BuildFrameSMessage(int receiveID)
		{
			receiveID *= 2;
			return PackIEC104Message(1, (ushort)receiveID, null);
		}

		/// <summary>
		/// 构建一个U帧消息的报文信息，传入功能码，STARTDT: 0x07, STOPDT: 0x13; TESTFR: 0x43
		/// </summary>
		/// <param name="controlField">控制码信息</param>
		/// <returns>U帧的报文信息</returns>
		public static byte[] BuildFrameUMessage(byte controlField)
		{
			return PackIEC104Message(controlField, 0, 0, 0, null);
		}

		/// <summary>
		/// 构建一个I帧消息的报文信息，传入相关的参数信息，返回完整的104消息报文
		/// </summary>
		/// <param name="sendID">发送的序列号</param>
		/// <param name="receiveID">接收的序列号</param>
		/// <param name="typeId">类型标识</param>
		/// <param name="variableStructureQualifier">可变结构限定词</param>
		/// <param name="reason">传送原因</param>
		/// <param name="station">应用服务数据单元公共地址</param>
		/// <param name="body">信息体，最大243个字节的长度</param>
		/// <returns>用于发送的104报文信息</returns>
		public static byte[] BuildFrameIMessage(int sendID, int receiveID, byte typeId, byte variableStructureQualifier, ushort reason, ushort station, byte[] body)
		{
			sendID *= 2;
			receiveID *= 2;
			byte[] array = new byte[6 + ((body != null) ? body.Length : 0)];
			array[0] = typeId;
			array[1] = variableStructureQualifier;
			array[2] = BitConverter.GetBytes(reason)[0];
			array[3] = BitConverter.GetBytes(reason)[1];
			array[4] = BitConverter.GetBytes(station)[0];
			array[5] = BitConverter.GetBytes(station)[1];
			if (body != null && body.Length != 0)
			{
				body.CopyTo(array, 6);
			}
			return PackIEC104Message((ushort)sendID, (ushort)receiveID, array);
		}

		/// <summary>
		/// 构建写入IEC仪表的报文信息
		/// </summary>
		/// <param name="type">指令类型信息</param>
		/// <param name="reason">原因信息</param>
		/// <param name="station">公共单元地址</param>
		/// <param name="address">信息对象地址</param>
		/// <param name="value">值数据</param>
		/// <returns>发送仪表的报文</returns>
		public static byte[] BuildWriteIec(byte type, ushort reason, ushort station, ushort address, byte[] value)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(type);
			memoryStream.WriteByte(1);
			memoryStream.Write(BitConverter.GetBytes(reason));
			memoryStream.Write(BitConverter.GetBytes(station));
			memoryStream.Write(BitConverter.GetBytes(address));
			memoryStream.WriteByte(0);
			memoryStream.Write(value);
			if (type == 45 || type == 46 || type == 47)
			{
				return memoryStream.ToArray();
			}
			memoryStream.WriteByte(0);
			return memoryStream.ToArray();
		}

		/// <summary>
		/// 解析遥信值的方法
		/// </summary>
		/// <param name="message">IEC104的消息</param>
		/// <param name="trans">从实际的字节数据转换指定类型的方法</param>
		/// <param name="unitLength">数据类型的字节长度信息</param>
		/// <typeparam name="T">转换后的类型信息</typeparam>
		/// <returns>列表值</returns>
		public static List<IecValueObject<T>> ParseYaoCeValue<T>(IEC104MessageEventArgs message, Func<byte[], int, T> trans, int unitLength)
		{
			bool flag = message.TypeID >= 30;
			List<IecValueObject<T>> list = new List<IecValueObject<T>>();
			DateTime time = DateTime.MinValue;
			int num = ((message.TypeID == 21) ? 3 : 4);
			if (message.IsAddressContinuous)
			{
				if (message.TypeID != 21)
				{
					unitLength++;
				}
				if (flag && message.Body.Length >= message.InfoObjectCount * unitLength + 3 + 7)
				{
					time = PraseTimeFromAbsoluteTimeScale(message.Body, message.InfoObjectCount * unitLength + 3);
				}
				ushort num2 = BitConverter.ToUInt16(message.Body, 0);
				for (int i = 0; i < message.InfoObjectCount; i++)
				{
					int num3 = unitLength * i + 3;
					if (num3 >= message.Body.Length)
					{
						return list;
					}
					IecValueObject<T> iecValueObject = new IecValueObject<T>();
					iecValueObject.Address = num2 + i;
					iecValueObject.Value = trans(message.Body, num3);
					if (message.TypeID != 21)
					{
						iecValueObject.Quality = message.Body[num3 + unitLength - 1];
					}
					if (flag)
					{
						iecValueObject.Time = time;
					}
					list.Add(iecValueObject);
				}
			}
			else
			{
				if (flag && message.Body.Length >= message.InfoObjectCount * (num + unitLength) + 7)
				{
					time = PraseTimeFromAbsoluteTimeScale(message.Body, message.InfoObjectCount * (num + unitLength));
				}
				for (int j = 0; j < message.InfoObjectCount; j++)
				{
					int num4 = (num + unitLength) * j;
					if (num4 >= message.Body.Length)
					{
						return list;
					}
					IecValueObject<T> iecValueObject2 = new IecValueObject<T>();
					iecValueObject2.Address = BitConverter.ToUInt16(message.Body, num4);
					iecValueObject2.Value = trans(message.Body, num4 + 3);
					if (message.TypeID != 21)
					{
						iecValueObject2.Quality = message.Body[num4 + 3 + unitLength];
					}
					if (flag)
					{
						iecValueObject2.Time = time;
					}
					list.Add(iecValueObject2);
				}
			}
			return list;
		}

		/// <summary>
		/// 获取在传送原因的文本描述信息
		/// </summary>
		/// <returns>字符串值</returns>
		public static string GetTransmissionReasonText(int transmissionReason)
		{
			return transmissionReason switch
			{
				1 => "周期循环", 
				2 => "背景扫描", 
				3 => "突发", 
				4 => "初始化", 
				5 => "请求或被请求", 
				6 => "激活", 
				7 => "激活确认", 
				8 => "停止激活", 
				9 => "停止激活确认", 
				10 => "激活终止", 
				11 => "远方命令引起的返送信息", 
				12 => "当地命令引起的返送信息", 
				20 => "响应站召唤", 
				21 => "响应第1组召唤", 
				44 => "未知的类型标识", 
				45 => "未知的传送原因", 
				46 => "未知的应用服务器数据单元公共地址", 
				47 => "未知的信息对象地址", 
				_ => transmissionReason.ToString(), 
			};
		}

