	/// 直接串口初始化，打开串口，就可以对数据进行读取了，地址如上图所示。
	/// </example>
	public class DLT645 : DeviceSerialPort, IDlt645, IReadWriteDevice, IReadWriteNet
	{
		private string station = "1";

		private string password = "00000000";

		private string opCode = "00000000";

