	/// <summary>
	/// 基于多功能电能表通信协议实现的通讯类，参考的文档是DLT645-2007，主要实现了对电表数据的读取和一些功能方法，
	/// 在点对点模式下，需要在连接后调用 <see cref="M:Snet.Driver.Instrument.DLT.DLT645OverTcp.ReadAddress" /> 方法，数据标识格式为 00-00-00-00，具体参照文档手册。<br />
	/// The communication type based on the communication protocol of the multifunctional electric energy meter. 
	/// The reference document is DLT645-2007, which mainly realizes the reading of the electric meter data and some functional methods. 
	/// In the point-to-point mode, you need to call <see cref="M:Snet.Driver.Instrument.DLT.DLT645OverTcp.ReadAddress" /> method after connect the device.
	/// the data identification format is 00-00-00-00, refer to the documentation manual for details.
	/// </summary>
	/// <remarks>
	/// 如果一对多的模式，地址可以携带地址域访问，例如 "s=2;00-00-00-00"，主要使用 <see cref="M:Snet.Driver.Instrument.DLT.DLT645OverTcp.ReadDouble(System.String,System.UInt16)" /> 方法来读取浮点数，
	/// <see cref="M:Snet.Driver.Core.Device.DeviceCommunication.ReadString(System.String,System.UInt16)" /> 方法来读取字符串
	/// </remarks>
	/// <example>
	/// <inheritdoc cref="T:Snet.Driver.Instrument.DLT.DLT645" path="example" />
	/// </example>
	public class DLT645OverTcp : DeviceTcpNet, IDlt645, IReadWriteDevice, IReadWriteNet
	{
		private string station = "1";

		private string password = "00000000";

		private string opCode = "00000000";

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.DLT645.Station" />
		public string Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.DLT645.EnableCodeFE" />
		public bool EnableCodeFE { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.DLTType" />
		public DLT645Type DLTType { get; } = DLT645Type.DLT2007;

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.Password" />
		public string Password
		{
			get
			{
				return password;
			}
			set
			{
				password = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.OpCode" />
		public string OpCode
		{
			get
			{
				return opCode;
			}
			set
			{
				opCode = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.CheckDataId" />"/&gt;
		public bool CheckDataId { get; set; } = true;

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.BinaryCommunication.#ctor" />
		public DLT645OverTcp()
		{
			base.ByteTransform = new RegularByteTransform();
			password = "00000000";
			opCode = "00000000";
			base.WordLength = 1;
		}

		/// <summary>
		/// 指定IP地址，端口，地址域，密码，操作者代码来实例化一个对象<br />
		/// Specify the IP address, port, address field, password, and operator code to instantiate an object
		/// </summary>
		/// <param name="ipAddress">TcpServer的IP地址</param>
		/// <param name="port">TcpServer的端口</param>
		/// <param name="station">设备的站号信息</param>
		/// <param name="password">密码，写入的时候进行验证的信息</param>
		/// <param name="opCode">操作者代码</param>
		public DLT645OverTcp(string ipAddress, int port = 502, string station = "1", string password = "", string opCode = "")
		{
			IpAddress = ipAddress;
			Port = port;
			base.WordLength = 1;
			base.ByteTransform = new RegularByteTransform();
			this.station = station;
			this.password = (string.IsNullOrEmpty(password) ? "00000000" : password);
			this.opCode = (string.IsNullOrEmpty(opCode) ? "00000000" : opCode);
		}

