	/// <summary>
	/// DLT645协议的虚拟服务器
	/// </summary>
	public class DLT645Server : DeviceServer
	{
		/// <summary>
		/// DLT的地址信息
		/// </summary>
		protected class DLTAddress
		{
			/// <summary>
			/// 地址
			/// </summary>
			public string Address { get; set; }

			/// <summary>
			/// 原始字节的数据
			/// </summary>
			public byte[] Buffer { get; set; }

			/// <summary>
			/// 小数位，小于0则表示字符串
			/// </summary>
			public int Digtal { get; set; }

			/// <summary>
			/// 实例化一个默认的对象
			/// </summary>
			public DLTAddress()
			{
			}

			/// <summary>
			/// 指定地址，数据，小数位实例化对象
			/// </summary>
			/// <param name="address">地址</param>
			/// <param name="buffer">数据</param>
			/// <param name="digtal">小数位</param>
			public DLTAddress(string address, byte[] buffer, int digtal)
			{
				Address = address;
				Buffer = buffer;
				Digtal = digtal;
			}
		}

		/// <summary>
		/// 服务器的所有数据信息
		/// </summary>
		protected Dictionary<string, DLTAddress> allDatas = new Dictionary<string, DLTAddress>();

		private string station = "1";

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.DLT645.Station" />
		public virtual string Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <summary>
		/// 字符串的数据是否发生反转，默认为 <c>True</c>, 将根据高地位进行翻转操作<br />
		/// Whether the data of the string is reversed or not, the default is <c>True</c>, and the flip operation will be performed according to the high status
		/// </summary>
		public bool StringReverse { get; set; } = true;

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.EnableCodeFE" />
		public bool EnableCodeFE { get; set; }

		/// <summary>
		/// 是否对客户端及主站的站号进行强制校验，只有两者站号匹配才进行返回数据，默认为false，对站号信息不校验操作<br />
		/// Whether to forcibly verify the station ids of the client and the master station. The data is returned only when the station ids of the client and master station match. The default value is false
		/// </summary>
		public bool StationMatch { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public DLT645Server()
		{
			CreateAddressTags();
			base.SerialReceiveAtleastTime = 2000;
		}

		/// <summary>
		/// 创建一系列的地址标签<br />
		/// </summary>
		protected virtual void CreateAddressTags()
		{
			AddDltTag("02010100", "2311", 1);
			AddDltTag("02010200", "2312", 1);
			AddDltTag("02010300", "2313", 1);
			AddDltTag("02020100", "012345", 3);
			AddDltTag("02020200", "012346", 3);
			AddDltTag("02020300", "012347", 3);
			AddDltTag("02030000", "123456", 4);
			AddDltTag("02030100", "123457", 4);
			AddDltTag("02030200", "123458", 4);
			AddDltTag("02030300", "123459", 4);
			AddDltTag("02040000", "654321", 4);
			AddDltTag("02040100", "654322", 4);
			AddDltTag("02040200", "654323", 4);
			AddDltTag("02040300", "654324", 4);
			AddDltTag("02050000", "553322", 4);
			AddDltTag("02050100", "553323", 4);
			AddDltTag("02050200", "553324", 4);
			AddDltTag("02050300", "553325", 4);
			AddDltTag("02060000", "1236", 3);
			AddDltTag("02060100", "1237", 3);
			AddDltTag("02060200", "1238", 3);
			AddDltTag("02060300", "1239", 3);
			AddDltTag("02070100", "2345", 1);
			AddDltTag("02070200", "2346", 1);
			AddDltTag("02070300", "2347", 1);
			AddDltTag("02080001", "123789", 3);
			AddDltTag("02080002", "5012", 2);
			AddDltTag("02080003", "112233", 4);
			AddDltTag("02080004", "223344", 4);
			AddDltTag("02080005", "223355", 4);
			AddDltTag("02080006", "223366", 4);
			AddDltTag("02080007", "2312", 1);
			AddDltTag("02080008", "1221", 2);
			AddDltTag("02080009", "1223", 2);
			AddDltTag("0208000A", "11223344", 0);
			AddDltTag("00000000", "12345612", 2);
			AddDltTag("00010000", "12345613", 2);
			AddDltTag("00020000", "12345614", 2);
			AddDltTag("00030000", "12345615", 2);
			AddDltTag("04000101", "23110904", -1);
			AddDltTag("04000102", DateTime.Now.ToString("HH:mm:ss").Replace(":", ""), -1);
			AddDltTag("04000401", "112233665544", -1);
			AddDltTag("04000402", "552233665544", -1);
			AddDltAsciiTag("0400040B", "DLTServer ", -1);
			AddDltAsciiTag("0400040C", "2023111101 ", -1);
		}

		/// <summary>
		/// 新增一个DLT的Tag标签<br />
		/// </summary>
		/// <param name="address">地址名称</param>
		/// <param name="hex">数据内容</param>
		/// <param name="digtal"></param>
		protected void AddDltTag(string address, string hex, int digtal)
		{
			allDatas.Add(address, new DLTAddress(address, hex.ToHexBytes(), digtal));
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.DLT.DLT645Server.AddDltTag(System.String,System.String,System.Int32)" />
		protected void AddDltTag(string address, byte[] data, int digtal)
		{
			allDatas.Add(address, new DLTAddress(address, data, digtal));
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.DLT.DLT645Server.AddDltTag(System.String,System.String,System.Int32)" />
		protected void AddDltAsciiTag(string address, string ascii, int digtal)
		{
			allDatas.Add(address, new DLTAddress(address, Encoding.ASCII.GetBytes(ascii), digtal));
		}

		/// <summary>
		/// 获取当前的DLT645协议类型
		/// </summary>
		/// <returns>DLT类型信息</returns>
		protected virtual DLT645Type GetLT645Type()
		{
			return DLT645Type.DLT2007;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadDouble(System.String,System.UInt16)" />
		public override OResult<double[]> ReadDouble(string address, ushort length)
		{
			OResult<string[]> oResult = ReadStringArray(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<double[]>(oResult);
			}
			try
			{
				return OResult.CreateSuccessResult((from m in oResult.Content.Take(length)
					select double.Parse(m)).ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<double[]>("double.Parse failed: " + ex.Message + Environment.NewLine + "Source: " + oResult.Content.ToArrayString());
			}
		}

		/// <inheritdoc />
		public override OResult<string> ReadString(string address, ushort length, Encoding encoding)
		{
			return ByteTransformHelper.GetResultFromArray(ReadStringArray(address));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.Double)" />
		public override OResult Write(string address, double value)
		{
			OResult<string, byte[]> oResult = DLT645Helper.AnalysisBytesAddress(GetLT645Type(), address, Station, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult);
			}
			string key = Enumerable.Reverse(oResult.Content2).ToArray().ToHexString();
			if (allDatas.ContainsKey(key))
			{
				value *= Math.Pow(10.0, allDatas[key].Digtal);
				string text = Convert.ToInt32(value).ToString().PadLeft(allDatas[key].Buffer.Length * 2, '0');
				if (text.Length > allDatas[key].Buffer.Length * 2)
				{
					text = text.Substring(text.Length - allDatas[key].Buffer.Length * 2);
				}
				text.ToHexBytes().CopyTo(allDatas[key].Buffer, 0);
				return OResult.CreateSuccessResult();
			}
			return new OResult<string[]>("None address data");
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Write(System.String,System.String,System.Text.Encoding)" />
		public override OResult Write(string address, string value, Encoding encoding)
		{
			OResult<string, byte[]> oResult = DLT645Helper.AnalysisBytesAddress(GetLT645Type(), address, Station, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult);
			}
			string key = Enumerable.Reverse(oResult.Content2).ToArray().ToHexString();
			if (allDatas.ContainsKey(key))
			{
				byte[] array = value.PadLeft(allDatas[key].Buffer.Length * 2, '0').ToHexBytes();
				if (array.Length > allDatas[key].Buffer.Length)
				{
					array = array.SelectBegin(allDatas[key].Buffer.Length);
				}
				array.CopyTo(allDatas[key].Buffer, 0);
				return OResult.CreateSuccessResult();
			}
			return new OResult<string[]>("None address data");
		}

		/// <summary>
		/// 根据指定的地址，读取DLT设备的字符串格式的数据信息<br />
		/// Read the DLT device data in string format based on the specified address
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <returns>包含字符串结果数组的对象</returns>
		public virtual OResult<string[]> ReadStringArray(string address)
		{
			bool reverse = SnetHelper.ExtractBooleanParameter(ref address, "reverse", defaultValue: true);
			OResult<string, byte[]> oResult = DLT645Helper.AnalysisBytesAddress(GetLT645Type(), address, Station, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult);
			}
			string key = Enumerable.Reverse(oResult.Content2).ToArray().ToHexString();
			if (allDatas.ContainsKey(key))
			{
				return DLTTransform.TransStringsFromDLt(GetLT645Type(), Enumerable.Reverse(allDatas[key].Buffer).ToArray().EveryByteAdd(51), oResult.Content2, reverse);
			}
			return new OResult<string[]>("None address data");
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new DLT645Message();
		}

		/// <inheritdoc />
		protected override OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			if (receive.Length == 4 && receive[0] == 254 && receive[1] == 254 && receive[2] == 254 && receive[3] == 254)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (receive.Length < 5)
			{
				return new OResult<byte[]>("Uknown message");
			}
			int num = DLT645Helper.FindHeadCode68H(receive);
			if (num < 0)
			{
				return new OResult<byte[]>("Uknown message: " + receive.ToHexString(' '));
			}
			if (num > 0)
			{
				receive = receive.RemoveBegin(num);
			}
			return ReadFromDLTCore(receive);
		}

		private OResult CheckStationMatch(byte[] command)
		{
			if (CheckAddress(command, 170))
			{
				return OResult.CreateSuccessResult();
			}
			if (!StationMatch)
			{
				return OResult.CreateSuccessResult();
			}
			string text = command.SelectMiddle(1, 6).ReverseNew().ToHexString();
			try
			{
				if (Convert.ToInt32(text) != Convert.ToInt32(station))
				{
					return new OResult("Station not match, need[" + station + "] actual[" + text + "]");
				}
				return OResult.CreateSuccessResult();
			}
			catch
			{
				return OResult.CreateSuccessResult();
			}
		}

		private bool CheckAddress(byte[] command, byte match)
		{
			for (int i = 1; i < 7; i++)
			{
				if (command[i] != match)
				{
					return false;
				}
			}
			return true;
		}

		private OResult<byte[]> CreateResponseBack(byte err, byte[] command, byte[] data, bool withAddress)
		{
			if ((err == 0) & withAddress)
			{
				data = SoftBasic.SpliceArray<byte>(command.SelectMiddle(10, GetDataIdLength()).EveryByteAdd(-51), data);
			}
			byte[] array = null;
			string address = station;
			if (!CheckAddress(command, 170))
			{
				address = command.SelectMiddle(1, 6).ReverseNew().ToHexString();
			}
			array = ((err <= 0) ? DLT645Helper.BuildDlt645EntireCommand(address, (byte)(command[8] + 128), data).Content : DLT645Helper.BuildDlt645EntireCommand(address, (byte)(command[8] + 192), new byte[1] { err }).Content);
			if (EnableCodeFE)
			{
				array = SoftBasic.SpliceArray<byte>(new byte[4] { 254, 254, 254, 254 }, array);
			}
			return OResult.CreateSuccessResult(array);
		}

		private bool IsCommandRead(byte command)
		{
			if (GetLT645Type() == DLT645Type.DLT2007)
			{
				return command == 17;
			}
			return command == 1;
		}

		private bool IsCommandWrite(byte command)
		{
			if (GetLT645Type() == DLT645Type.DLT2007)
			{
				return command == 20;
			}
			return command == 4;
		}

		private int GetDataIdLength()
		{
			if (GetLT645Type() == DLT645Type.DLT2007)
			{
				return 4;
			}
			return 2;
		}

		/// <summary>
		/// 从DLT协议中读取数据信息<br />
		/// </summary>
		/// <param name="receive">接收到的报文数据信息</param>
		/// <returns>返回的报文结果数据</returns>
		protected virtual OResult<byte[]> ReadFromDLTCore(byte[] receive)
		{
			int dataIdLength = GetDataIdLength();
			if (IsCommandRead(receive[8]))
			{
				OResult oResult = CheckStationMatch(receive);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult);
				}
				string key = Enumerable.Reverse(receive.SelectMiddle(10, dataIdLength).EveryByteAdd(-51)).ToArray().ToHexString();
				if (allDatas.ContainsKey(key))
				{
					if (allDatas[key].Digtal < 0)
					{
						_ = StringReverse;
						return CreateResponseBack(0, receive, Enumerable.Reverse(allDatas[key].Buffer).ToArray(), withAddress: true);
					}
					return CreateResponseBack(0, receive, Enumerable.Reverse(allDatas[key].Buffer).ToArray(), withAddress: true);
				}
				return CreateResponseBack(2, receive, null, withAddress: true);
			}
			if (receive[8] == 19)
			{
				return CreateResponseBack(0, receive, station.PadLeft(12, '0').ToHexBytes(), withAddress: false);
			}
			if (IsCommandWrite(receive[8]))
			{
				OResult oResult2 = CheckStationMatch(receive);
				if (!oResult2.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult2);
				}
				string key2 = Enumerable.Reverse(receive.SelectMiddle(10, dataIdLength).EveryByteAdd(-51)).ToArray().ToHexString();
				if (allDatas.ContainsKey(key2))
				{
					Enumerable.Reverse((GetLT645Type() == DLT645Type.DLT2007) ? receive.SelectMiddle(22, receive.Length - 24) : receive.SelectMiddle(12, receive.Length - 14)).ToArray().EveryByteAdd(-51)
						.CopyTo(allDatas[key2].Buffer, 0);
					return CreateResponseBack(0, receive, new byte[0], withAddress: false);
				}
				return CreateResponseBack(2, receive, null, withAddress: false);
			}
			if (receive[8] == 21)
			{
				OResult oResult3 = CheckStationMatch(receive);
				if (!oResult3.IsSuccess)
				{
					return OResult.CreateFailedResult<byte[]>(oResult3);
				}
				string text = receive.SelectMiddle(10, 6).EveryByteAdd(-51).ReverseNew()
					.ToHexString();
				base.LogNet?.WriteInfo(ToString(), "Station change, " + station + " -> " + text);
				station = text;
				return CreateResponseBack(0, receive, new byte[0], withAddress: false);
			}
			if (receive[8] == 8)
			{
				string text2 = Enumerable.Reverse(receive.SelectMiddle(13, 3).EveryByteAdd(-51)).ToArray().ToHexString();
				Write("04000101", text2 + "00");
				string value = Enumerable.Reverse(receive.SelectMiddle(10, 3).EveryByteAdd(-51)).ToArray().ToHexString();
				Write("04000102", value);
				return new OResult<byte[]>
				{
					ErrorCode = int.MinValue
				};
			}
			if (receive[8] == 22)
			{
				base.LogNet?.WriteDebug(ToString(), "FreezeCommand: " + receive.SelectMiddle(10, 4).ToHexString(' '));
				if (receive[1] != 153 || receive[2] != 153 || receive[3] != 153 || receive[4] != 153 || receive[5] != 153 || receive[6] != 153)
				{
					return CreateResponseBack(0, receive, new byte[0], withAddress: false);
				}
			}
			else
			{
				if (receive[8] == 23)
				{
					int num = receive[10] - 51;
					string text3 = num switch
					{
						64 => "19200", 
						32 => "9600", 
						16 => "4800", 
						8 => "2400", 
						4 => "1200", 
						2 => "600", 
						_ => $"Unkown[{receive[10]}]", 
					};
					base.LogNet?.WriteDebug(ToString(), "Modify baud rate: " + text3);
					if (text3.StartsWith("Unkown"))
					{
						return CreateResponseBack(3, receive, null, withAddress: false);
					}
					return CreateResponseBack(0, receive, new byte[1] { (byte)num }, withAddress: false);
				}
				if (receive[8] == 28)
				{
					return CreateResponseBack(0, receive, new byte[0], withAddress: false);
				}
			}
			return CreateResponseBack(2, receive, null, withAddress: false);
		}

		/// <inheritdoc />
		protected override bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.Write(buffer.SelectBegin(receivedLength));
			return DLT645Helper.CheckReceiveDataComplete(memoryStream);
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			base.Dispose(disposing);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"DLT645Server[{base.Port}]";
		}
	}
	/// <summary>
	/// 基于多功能电能表通信协议实现的通讯类，参考的文档是DLT645-1997，主要实现了对电表数据的读取和一些功能方法，数据标识格式为 B6-11，具体参照文档手册。<br />
	/// Based on the communication class implemented by the multi-function energy meter communication protocol, the reference document is DLT645-1997, 
	/// which mainly implements the reading of meter data and some functional methods, the data identification format is B6-11, please refer to the document manual for details.
	/// </summary>
	/// <remarks>
	/// 如果一对多的模式，地址可以携带地址域访问，例如 "s=2;B6-11"，主要使用 <see cref="M:Snet.Driver.Instrument.DLT.DLT645With1997.ReadDouble(System.String,System.UInt16)" /> 方法来读取浮点数，<see cref="M:Snet.Driver.Core.Device.DeviceCommunication.ReadString(System.String,System.UInt16)" /> 方法来读取字符串
	/// </remarks>
	/// <example>
	/// 具体的地址请参考相关的手册内容，如果没有，可以联系Snet作者或者，下面列举一些常用的地址<br />
	/// <list type="table">
	///   <listheader>
	///     <term>DI1-DI0</term>
	///     <term>读取方式</term>
	///     <term>数据项名称</term>
	///     <term>备注</term>
	///   </listheader>
	///   <item>
	///     <term>90-10</term>
	///     <term>ReadDouble</term>
	///     <term>(当前)正向有功总电能(kwh)</term>
	///     <term>90-11至90-1E表示费率1-14的正向有功电能，90-1F表示正向有功电能数据块</term>
	///   </item>
	///   <item>
	///     <term>90-20</term>
	///     <term>ReadDouble</term>
	///     <term>(当前)反向有功总电能(kwh)</term>
	///     <term>90-21至90-2E表示费率1-14的反向有功电能，90-2F表示反向有功电能数据块</term>
	///   </item>
	///   <item>
	///     <term>91-10</term>
	///     <term>ReadDouble</term>
	///     <term>(当前)正向无功总电能(kvarh)</term>
	///     <term>91-11至91-1E表示费率1-14的正向无功电能，91-1F表示正向无功电能数据块</term>
	///   </item>
	///   <item>
	///     <term>91-20</term>
	///     <term>ReadDouble</term>
	///     <term>(当前)反向无功总电能(kvarh)</term>
	///     <term>91-21至91-2E表示费率1-14的反向无功电能，91-2F表示正向无功电能数据块</term>
	///   </item>
	///   <item>
	///     <term>A0-10</term>
	///     <term>ReadDouble</term>
	///     <term>(当前)正向有功总最大需量( kw)</term>
	///     <term>A0-11至A0-1E表示费率1-14的正向有功最大需，A0-1F表示有功最大需量数据块</term>
	///   </item>
	///   <item>
	///     <term>A0-20</term>
	///     <term>ReadDouble</term>
	///     <term>(当前)反向有功总最大需量( kw)</term>
	///     <term>A0-21至A0-2E表示费率1-14的反向有功最大需，A0-2F表示反向有功最大需量数据块</term>
	///   </item>
	///   <item>
	///     <term>A1-10</term>
	///     <term>ReadDouble</term>
	///     <term>(当前)正向无功总最大需量( kvar)</term>
	///     <term>A1-11至A1-1E表示费率1-14的正向无功最大需，A1-1F表示无功最大需量数据块</term>
	///   </item>
	///   <item>
	///     <term>A1-20</term>
	///     <term>ReadDouble</term>
	///     <term>(当前)反向无功总最大需量( kvar)</term>
	///     <term>A1-21至A1-2E表示费率1-14的反向无功最大需，A1-2F表示反向无功最大需量数据块</term>
	///   </item>
	///   <item>
	///     <term>B2-10</term>
	///     <term>ReadString</term>
	///     <term>最近一次编程时间</term>
	///     <term>单位月日小时分钟，MMDDHHmm</term>
	///   </item>
	///   <item>
	///     <term>B2-12</term>
	///     <term>ReadDouble</term>
	///     <term>编程次数</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>B2-14</term>
	///     <term>ReadDouble</term>
	///     <term>电池工作时间(min)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>B3-10</term>
	///     <term>ReadDouble</term>
	///     <term>总断相次数</term>
	///     <term>B3-11至B3-13分别表示A相，B相，C相</term>
	///   </item>
	///   <item>
	///     <term>B3-20</term>
	///     <term>ReadDouble</term>
	///     <term>断相时间累计值(min)</term>
	///     <term>B3-21至B3-23分别表示A相，B相，C相</term>
	///   </item>
	///   <item>
	///     <term>B6-11</term>
	///     <term>ReadDouble</term>
	///     <term>A相电压(V)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>B6-12</term>
	///     <term>ReadDouble</term>
	///     <term>B相电压(V)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>B6-13</term>
	///     <term>ReadDouble</term>
	///     <term>C相电压(V)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>B6-21</term>
	///     <term>ReadDouble</term>
	///     <term>A相电流(A)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>B6-22</term>
	///     <term>ReadDouble</term>
	///     <term>B相电流(A)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>B6-23</term>
	///     <term>ReadDouble</term>
	///     <term>C相电流(A)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>B6-30</term>
	///     <term>ReadDouble</term>
	///     <term>瞬时有功功率(kw)</term>
	///     <term>B6-31至B6-33分别表示A相，B相，C相</term>
	///   </item>
	///   <item>
	///     <term>B6-40</term>
	///     <term>ReadDouble</term>
	///     <term>瞬时无功功率(kvarh)</term>
	///     <term>B6-41至B6-43分别表示A相，B相，C相</term>
	///   </item>
	///   <item>
	///     <term>B6-50</term>
	///     <term>ReadDouble</term>
	///     <term>总功率因数</term>
	///     <term>B6-41至B6-43分别表示A相，B相，C相</term>
	///   </item>
	///   <item>
	///     <term>C0-10</term>
	///     <term>ReadString</term>
	///     <term>日期及周次</term>
	///     <term>年月日，YYMMDDWW</term>
	///   </item>
	///   <item>
	///     <term>C0-11</term>
	///     <term>ReadString</term>
	///     <term>时间</term>
	///     <term>时分秒，hhmmss</term>
	///   </item>
	///   <item>
	///     <term>C0-30</term>
	///     <term>ReadString</term>
	///     <term>电表常数(有功)</term>
	///     <term>p/(kwh)</term>
	///   </item>
	///   <item>
	///     <term>C0-31</term>
	///     <term>ReadString</term>
	///     <term>电表常数(无功)</term>
	///     <term>p/(kvarh)</term>
	///   </item>
	///   <item>
	///     <term>C0-32</term>
	///     <term>ReadString</term>
	///     <term>表号</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>C0-33</term>
	///     <term>ReadString</term>
	///     <term>用户号</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>C0-34</term>
	///     <term>ReadString</term>
	///     <term>设备码</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>C1-12</term>
	///     <term>ReadDouble</term>
	///     <term>滑差时间(s)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>C1-13</term>
	///     <term>ReadDouble</term>
	///     <term>循显时间(s)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>C1-14</term>
	///     <term>ReadDouble</term>
	///     <term>停显时间(s)</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>C1-15</term>
	///     <term>ReadDouble</term>
	///     <term>显示电能小数位数</term>
	///     <term></term>
	///   </item>
	///   <item>
	///     <term>C1-17</term>
	///     <term>ReadString</term>
	///     <term>自动抄表日期</term>
	///     <term>日时，DDhh</term>
	///   </item>
	///  </list>
	///             </example>
	public class DLT645With1997 : DeviceSerialPort, IDlt645, IReadWriteDevice, IReadWriteNet
	{
		private string station = "1";

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.Station" />
		public string Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.EnableCodeFE" />
		public bool EnableCodeFE { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.DLTType" />
		public DLT645Type DLTType { get; }

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.Password" />
		public string Password { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.OpCode" />
		public string OpCode { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.CheckDataId" />"/&gt;
		public bool CheckDataId { get; set; } = true;

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.BinaryCommunication.#ctor" />
		public DLT645With1997()
		{
			base.ByteTransform = new RegularByteTransform();
			base.ReceiveEmptyDataCount = 5;
		}

		/// <summary>
		/// 通过指定的站号实例化一个设备对象
		/// </summary>
		/// <param name="station">设备的地址信息，是一个12字符的BCD码</param>
		public DLT645With1997(string station)
			: this()
		{
			this.station = station;
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new DLT645Message(CheckDataId);
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReadFromCoreServer(byte[] send)
		{
			OResult<byte[]> oResult = base.ReadFromCoreServer(send);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			int num = DLT645Helper.FindHeadCode68H(oResult.Content);
			if (num > 0)
			{
				return OResult.CreateSuccessResult(oResult.Content.RemoveBegin(num));
			}
			return oResult;
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			if (EnableCodeFE)
			{
				return SoftBasic.SpliceArray<byte>(new byte[4] { 254, 254, 254, 254 }, command);
			}
			return base.PackCommandWithHeader(command);
		}

		/// <summary>
		/// 激活设备的命令，只发送数据到设备，不等待设备数据返回<br />
		/// The command to activate the device, only send data to the device, do not wait for the device data to return
		/// </summary>
		/// <returns>是否发送成功</returns>
		public OResult ActiveDeveice()
		{
			return ReadFromCoreServer(new byte[4] { 254, 254, 254, 254 }, hasResponseData: false, usePackAndUnpack: false);
		}

		/// <summary>
		/// 根据指定的数据标识来读取相关的原始数据信息，地址标识根据手册来，从高位到地位，例如 B6-11，分割符可以任意特殊字符或是没有分隔符。<br />
		/// Read the relevant original data information according to the specified data identifier. The address identifier is based on the manual, 
		/// from high to position, such as B6-11. The separator can be any special character or no separator.
		/// </summary>
		/// <remarks>
		/// 地址可以携带地址域信息，例如 "s=2;B6-11" 或是 "s=100000;B6-11"，关于数据域信息，需要查找手册，例如:B6-30 表示： (当前)正向有功总电能
		/// </remarks>
		/// <param name="address">数据标识，具体需要查找手册来对应</param>
		/// <param name="length">数据长度信息</param>
		/// <returns>结果信息</returns>
		public override OResult<byte[]> Read(string address, ushort length)
		{
			return DLT645Helper.Read(this, address, length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadInt32(System.String,System.UInt16)" />
		public override OResult<int[]> ReadInt32(string address, ushort length)
		{
			OResult<double[]> oResult = ReadDouble(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int[]>(oResult);
			}
			return OResult.CreateSuccessResult(oResult.Content.Select((double m) => Convert.ToInt32(m)).ToArray());
		}

		/// <inheritdoc />
		/// <remarks>
		/// 地址可以携带地址域信息，例如 "s=2;B6-11" 或是 "s=100000;B6-11"，关于数据域信息，需要查找手册，例如:B6-30 表示： 瞬时有功功率
		/// </remarks>
		public override OResult<double[]> ReadDouble(string address, ushort length)
		{
			return DLT645Helper.ReadDouble(this, address, length);
		}

		/// <inheritdoc />
		/// <remarks>
		/// 地址可以携带地址域信息，例如 "s=2;B6-11" 或是 "s=100000;B6-11"，关于数据域信息，需要查找手册，例如:B6-30 表示： (当前)正向有功总电能
		/// </remarks>
