	public class DLT645With1997OverTcp : DeviceTcpNet, IDlt645, IReadWriteDevice, IReadWriteNet
	{
		private string station = "1";

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.DLT645.Station" />
		public string Station
		{
			get
			{
				return station;
			}
			set
			{
				station = value;
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.DLT645.EnableCodeFE" />
