		/// <inheritdoc cref="M:Snet.Driver.Instrument.DLT.DLT698OverTcp.ReadAddress" />
		public async Task<OResult<string>> ReadAddressAsync()
		{
			OResult<byte[]> oResult = DLT698Helper.BuildReadSingleObject("40-01-02-00", "AAAAAAAAAAAA", this);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			OResult<byte[]> oResult3 = DLT698Helper.CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			station = oResult3.Content.SelectMiddle(10, oResult3.Content[9]).ToHexString();
			return OResult.CreateSuccessResult(station);
		}

