	/// <summary>
	/// DTL数据转换
	/// </summary>
	public class DLTTransform
	{
		/// <summary>
		/// Byte[]转ToHexString
		/// </summary>
		/// <param name="content">原始的字节内容</param>
		/// <param name="length">长度信息</param>
		/// <returns>字符串的结果信息</returns>
		public static OResult<string> TransStringFromDLt(byte[] content, ushort length)
		{
			try
			{
				_ = string.Empty;
				byte[] bytes = Enumerable.Reverse(content.SelectBegin(length)).ToArray().EveryByteAdd(-51);
				return OResult.CreateSuccessResult(Encoding.ASCII.GetString(bytes));
			}
			catch (Exception ex)
			{
				return new OResult<string>(ex.Message + " Reason: " + content.ToHexString(' '));
			}
		}

		private static byte[] CreateFromStrings(string[] content, bool reverse)
		{
			MemoryStream memoryStream = new MemoryStream();
			for (int i = 0; i < content.Length; i++)
			{
				if (reverse)
				{
					memoryStream.Write(Enumerable.Reverse(content[i].ToHexBytes()).ToArray());
				}
				else
				{
					memoryStream.Write(content[i].ToHexBytes().ToArray());
				}
			}
			return memoryStream.ToArray();
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.DLT.DLTTransform.TransDltFromStrings(Snet.Driver.Instrument.DLT.Helper.DLT645Type,System.String[],System.Byte[],System.Boolean)" />
		public static OResult<byte[]> TransDltFromStrings(DLT645Type type, string content, byte[] dataID, bool reverse)
		{
			return TransDltFromStrings(type, new string[1] { content }, dataID, reverse);
		}

		/// <summary>
		/// 将字符串数据，转变为实际的等待写入的数据信息
		/// </summary>
		/// <param name="type">DLT类型</param>
		/// <param name="contents">字符串数据信息</param>
		/// <param name="dataID">数据ID信息</param>
		/// <param name="reverse">数据是否反转</param>
		/// <returns>原始数据信息</returns>
		public static OResult<byte[]> TransDltFromStrings(DLT645Type type, string[] contents, byte[] dataID, bool reverse)
		{
			try
			{
				int[] array = ((type == DLT645Type.DLT2007) ? GetDLT2007FormatWithDataArea(dataID) : GetDLT1997FormatWithDataArea(dataID));
				if (array == null)
				{
					return OResult.CreateSuccessResult(CreateFromStrings(contents, reverse));
				}
				MemoryStream memoryStream = new MemoryStream();
				for (int i = 0; i < contents.Length && i < array.Length; i++)
				{
					byte[] bytes = BitConverter.GetBytes(array[i]);
					int num = bytes[0];
					int num2 = bytes[1];
					_ = bytes[2];
					string text = contents[i];
					if (bytes[3] == 1)
					{
						if (reverse)
						{
							memoryStream.Write(Enumerable.Reverse(Encoding.ASCII.GetBytes(text)).ToArray());
						}
						else
						{
							memoryStream.Write(Encoding.ASCII.GetBytes(text).ToArray());
						}
						continue;
					}
					bool flag = false;
					if (num2 >= 128)
					{
						num2 -= 128;
					}
					if (num2 != 0)
					{
						try
						{
							text = Convert.ToInt32(Convert.ToDouble(text) * Math.Pow(10.0, num2)).ToString();
						}
						catch (Exception ex)
						{
							return new OResult<byte[]>(ex.Message + " ID:" + dataID.ToHexString('-') + " Value:" + text + Environment.NewLine + ex.StackTrace);
						}
					}
					if (text.StartsWith("-"))
					{
						flag = true;
						text = text.Substring(1);
					}
					if (text.Length < num * 2)
					{
						text = text.PadLeft(num * 2, '0');
					}
					if (text.Length > num * 2)
					{
						text = text.Substring(0, num * 2);
					}
					byte[] array2 = (reverse ? Enumerable.Reverse(text.ToHexBytes()).ToArray() : text.ToHexBytes().ToArray());
					if (flag)
					{
						array2[0] = (byte)(array2[0] & 0x80);
					}
					memoryStream.Write(array2);
				}
				return OResult.CreateSuccessResult(memoryStream.ToArray());
			}
			catch (Exception ex2)
			{
				return new OResult<byte[]>(ex2.Message + " ID:" + dataID.ToHexString('-') + Environment.NewLine + ex2.StackTrace);
			}
		}

		/// <summary>
		/// 从读取的原始字节里解析出实际的字符串数组
		/// </summary>
		/// <param name="type">类型信息</param>
		/// <param name="content">原始字节内容</param>
		/// <param name="dataID">地址信息</param>
		/// <param name="reverse">指示当前的结果数据是否发生数据反转的操作</param>
		/// <returns>字符串的数组内容</returns>
		public static OResult<string[]> TransStringsFromDLt(DLT645Type type, byte[] content, byte[] dataID, bool reverse)
		{
			List<string> list = new List<string>();
			try
			{
				int[] array = ((type == DLT645Type.DLT2007) ? GetDLT2007FormatWithDataArea(dataID) : GetDLT1997FormatWithDataArea(dataID));
				if (array == null)
				{
					if (reverse)
					{
						list.Add(Enumerable.Reverse(content).ToArray().EveryByteAdd(-51)
							.ToHexString());
					}
					else
					{
						list.Add(content.EveryByteAdd(-51).ToHexString());
					}
					return OResult.CreateSuccessResult(list.ToArray());
				}
				int num = 0;
				for (int i = 0; i < array.Length; i++)
				{
					if (num >= content.Length)
					{
						return OResult.CreateSuccessResult(list.ToArray());
					}
					byte[] bytes = BitConverter.GetBytes(array[i]);
					int num2 = bytes[0];
					int num3 = bytes[1];
					_ = bytes[2];
					if (bytes[3] == 1)
					{
						if (reverse)
						{
							list.Add(Encoding.ASCII.GetString(Enumerable.Reverse(content.SelectMiddle(num, num2)).ToArray().EveryByteAdd(-51)));
						}
						else
						{
							list.Add(Encoding.ASCII.GetString(content.SelectMiddle(num, num2).EveryByteAdd(-51)));
						}
					}
					else
					{
						double num4 = 1.0;
						byte[] array2 = (reverse ? Enumerable.Reverse(content.SelectMiddle(num, num2)).ToArray().EveryByteAdd(-51) : content.SelectMiddle(num, num2).EveryByteAdd(-51));
						if (num3 >= 128)
						{
							num3 -= 128;
							num4 = (((array2[0] & 0x80) == 128) ? (-1.0) : 1.0);
							array2[0] = (byte)(array2[0] & 0x7F);
						}
						string text = array2.ToHexString();
						if (num3 == 0)
						{
							list.Add(text);
						}
						else
						{
							try
							{
								list.Add((Convert.ToDouble(text) * num4 / Math.Pow(10.0, num3)).ToString());
							}
							catch (Exception ex)
							{
								return new OResult<string[]>(ex.Message + " ID:" + dataID.ToHexString('-') + " Value:" + text + Environment.NewLine + ex.StackTrace);
							}
						}
					}
					num += num2;
				}
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex2)
			{
				return new OResult<string[]>(ex2.Message + " ID:" + dataID.ToHexString('-') + Environment.NewLine + ex2.StackTrace);
			}
		}

		/// <summary>
		/// Byte[]转Dlt double[]，使用一样的 format 格式来转换多个double类型的数据
		/// </summary>
		/// <param name="content">原始的字节数据</param>
		/// <param name="length">需要转换的数据长度</param>
		/// <param name="format">当前数据的解析格式</param>
		/// <returns>结果内容</returns>
		public static OResult<double[]> TransDoubleFromDLt(byte[] content, ushort length, string format = "XXXXXX.XX")
		{
			try
			{
				format = format.ToUpper();
				int num = format.Count((char m) => m != '.') / 2;
				int num2 = ((format.IndexOf('.') >= 0) ? (format.Length - format.IndexOf('.') - 1) : 0);
				double[] array = new double[length];
				for (int num3 = 0; num3 < array.Length; num3++)
				{
					byte[] inBytes = Enumerable.Reverse(content.SelectMiddle(num3 * num, num)).ToArray().EveryByteAdd(-51);
					array[num3] = Convert.ToDouble(inBytes.ToHexString()) / Math.Pow(10.0, num2);
				}
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				return new OResult<double[]>(ex.Message);
			}
		}

		private static int GetFormat(byte byteLength, int digtal, byte length = 1, bool negativeFlag = false)
		{
			if (digtal >= 0)
			{
				return BitConverter.ToInt32(new byte[4]
				{
					byteLength,
					(byte)(digtal + (negativeFlag ? 128 : 0)),
					length,
					0
				}, 0);
			}
			return BitConverter.ToInt32(new byte[4] { byteLength, 0, length, 1 }, 0);
		}

		private static int[] get03_30_02()
		{
			List<int> list = new List<int>(50);
			list.Add(GetFormat(6, 0, 1));
			list.Add(GetFormat(4, 0, 1));
			for (int i = 0; i < 24; i++)
			{
				list.Add(GetFormat(3, 4, 1));
				list.Add(GetFormat(5, 0, 1));
			}
			return list.ToArray();
		}

