	/// <summary>
	/// 校验部分的辅助方法
	/// </summary>
	public class DLT698FcsHelper
	{
		private static readonly ushort[] fcstab = new ushort[256]
		{
			0, 4489, 8978, 12955, 17956, 22445, 25910, 29887, 35912, 40385,
			44890, 48851, 51820, 56293, 59774, 63735, 4225, 264, 13203, 8730,
			22181, 18220, 30135, 25662, 40137, 36160, 49115, 44626, 56045, 52068,
			63999, 59510, 8450, 12427, 528, 5017, 26406, 30383, 17460, 21949,
			44362, 48323, 36440, 40913, 60270, 64231, 51324, 55797, 12675, 8202,
			4753, 792, 30631, 26158, 21685, 17724, 48587, 44098, 40665, 36688,
			64495, 60006, 55549, 51572, 16900, 21389, 24854, 28831, 1056, 5545,
			10034, 14011, 52812, 57285, 60766, 64727, 34920, 39393, 43898, 47859,
			21125, 17164, 29079, 24606, 5281, 1320, 14259, 9786, 57037, 53060,
			64991, 60502, 39145, 35168, 48123, 43634, 25350, 29327, 16404, 20893,
			9506, 13483, 1584, 6073, 61262, 65223, 52316, 56789, 43370, 47331,
			35448, 39921, 29575, 25102, 20629, 16668, 13731, 9258, 5809, 1848,
			65487, 60998, 56541, 52564, 47595, 43106, 39673, 35696, 33800, 38273,
			42778, 46739, 49708, 54181, 57662, 61623, 2112, 6601, 11090, 15067,
			20068, 24557, 28022, 31999, 38025, 34048, 47003, 42514, 53933, 49956,
			61887, 57398, 6337, 2376, 15315, 10842, 24293, 20332, 32247, 27774,
			42250, 46211, 34328, 38801, 58158, 62119, 49212, 53685, 10562, 14539,
			2640, 7129, 28518, 32495, 19572, 24061, 46475, 41986, 38553, 34576,
			62383, 57894, 53437, 49460, 14787, 10314, 6865, 2904, 32743, 28270,
			23797, 19836, 50700, 55173, 58654, 62615, 32808, 37281, 41786, 45747,
			19012, 23501, 26966, 30943, 3168, 7657, 12146, 16123, 54925, 50948,
			62879, 58390, 37033, 33056, 46011, 41522, 23237, 19276, 31191, 26718,
			7393, 3432, 16371, 11898, 59150, 63111, 50204, 54677, 41258, 45219,
			33336, 37809, 27462, 31439, 18516, 23005, 11618, 15595, 3696, 8185,
			63375, 58886, 54429, 50452, 45483, 40994, 37561, 33584, 31687, 27214,
			22741, 18780, 15843, 11370, 7921, 3960
		};

		private const ushort PPPINITFCS16 = ushort.MaxValue;

		private const ushort PPPGOODFCS16 = 61624;

		private static ushort CalculateFcs16(ushort fcs, byte[] cp, int index, int length)
		{
			for (int i = 0; i < length; i++)
			{
				fcs = (ushort)((fcs >> 8) ^ fcstab[(fcs ^ cp[i + index]) & 0xFF]);
			}
			return fcs;
		}

		/// <summary>
		/// 根据传入的原始字节数组，来计算当前的部分字节的FCS校验数据，并返回最终校验结果
		/// </summary>
		/// <param name="buffer">等待计算校验的字节缓存</param>
		/// <param name="index">开始计算的字节索引</param>
		/// <param name="length">等待计算的字节的长度</param>
		/// <returns>最终计算的Fcs结果</returns>
		public static byte[] CalculateFcs16(byte[] buffer, int index, int length)
		{
			return BitConverter.GetBytes((ushort)(CalculateFcs16(ushort.MaxValue, buffer, index, length) ^ 0xFFFF));
		}

		/// <summary>
		/// 验证当前的Fcs校验码是否正确，长度信息参数不应该包含FCS校验字节信息
		/// </summary>
		/// <param name="buffer">等待计算校验的字节缓存</param>
		/// <param name="index">开始计算的字节索引</param>
		/// <param name="length">等待计算的字节的长度，不包含FCS字节</param>
		/// <returns>是否计算符合的结果</returns>
		public static bool CheckFcs16(byte[] buffer, int index, int length)
		{
			return CalculateFcs16(ushort.MaxValue, buffer, index, length + 2) == 61624;
		}
	}
	/// <summary>
	/// 698 协议的帮助类
	/// </summary>
	public class DLT698Helper
	{
		/// <summary>
		/// 预连接请求
		/// </summary>
		public const byte LinkRequest = 1;

		/// <summary>
		/// 建立应用连接请求
		/// </summary>
		public const byte ConnectRequest = 2;

		/// <summary>
		/// 断开应用连接请求
		/// </summary>
		public const byte ReleaseRequest = 3;

		/// <summary>
		/// 读取请求
		/// </summary>
		public const byte GetRequest = 5;

		/// <summary>
		/// 设置请求
		/// </summary>
		public const byte SetRequest = 6;

		/// <summary>
		/// 操作请求 
		/// </summary>
		public const byte ActionRequest = 7;

		/// <summary>
		/// 操作请求
		/// </summary>
		public const byte ReportRequest = 8;

		/// <summary>
		/// 代理请求
		/// </summary>
		public const byte ReportResponse = 9;

		/// <summary>
		/// 安全请求
		/// </summary>
		public const byte SecurityResquest = 16;

		/// <summary>
		/// 预连接响应
		/// </summary>
		public const byte LinkResponse = 129;

		/// <summary>
		/// 建立应用连接响应
		/// </summary>
		public const byte ConnectResponse = 130;

		/// <summary>
		/// 断开应用连接响应 
		/// </summary>
		public const byte ReleaseResponse = 131;

		/// <summary>
		/// 断开应用连接通知
		/// </summary>
		public const byte ReleaseNotification = 132;

		/// <summary>
		/// 读取响应
		/// </summary>
		public const byte GetResponse = 133;

		/// <summary>
		/// 设置响应
		/// </summary>
		public const byte SetResponse = 134;

		/// <summary>
		/// 操作响应
		/// </summary>
		public const byte ActionResponse = 135;

		/// <summary>
		/// 上报通知
		/// </summary>
		public const byte ReportNotification = 136;

		/// <summary>
		/// 代理响应
		/// </summary>
		public const byte ProxyResponse = 137;

		/// <summary>
		/// 安全响应
		/// </summary>
		public const byte SecurityResponse = 144;

		/// <inheritdoc cref="M:Snet.Driver.Instrument.DLT.Helper.DLT645Helper.CheckReceiveDataComplete(System.IO.MemoryStream)" />
		public static bool CheckReceiveDataComplete(MemoryStream ms)
		{
			byte[] array = ms.ToArray();
			if (array.Length < 10)
			{
				return false;
			}
			int num = DLT645Helper.FindHeadCode68H(array);
			if (num < 0)
			{
				return false;
			}
			if (array.Length < num + 10)
			{
				return false;
			}
			if (array[num + 1] + num + 2 == array.Length && array[^1] == 22)
			{
				return true;
			}
			return false;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.BinaryCommunication.PackCommandWithHeader(System.Byte[])" />
		public static byte[] PackCommandWithHeader(IDlt698 dlt, byte[] command)
		{
			if (dlt.EnableCodeFE)
			{
				return SoftBasic.SpliceArray<byte>(new byte[4] { 254, 254, 254, 254 }, command);
			}
			return command;
		}

		/// <summary>
		/// 根据地址类型，逻辑地址，实际的地址信息构建出真实的地址报文
		/// </summary>
		/// <param name="addressType">地址类型，0：单地址, 1：通配地址，2：组地址，3：广播地址</param>
		/// <param name="logicAddress">逻辑地址</param>
		/// <param name="address">地址信息</param>
		/// <param name="ca">客户机地址</param>
		/// <returns>原始字节信息</returns>
		private static byte[] CalculateAddressArea(int addressType, int logicAddress, string address, byte ca)
		{
			if (address.Length % 2 == 1)
			{
				address += "F";
			}
			if (logicAddress > 3)
			{
				logicAddress = 3;
			}
			byte[] array = new byte[2 + address.Length / 2];
			array[0] = (byte)((addressType << 6) | (logicAddress << 4) | (address.Length / 2 - 1));
			Enumerable.Reverse(address.ToHexBytes()).ToArray().CopyTo(array, 1);
			array[^1] = ca;
			return array;
		}

		internal static byte[] CreateStringValueBuffer(string value)
		{
			if (value.Length % 2 == 1)
			{
				value += "F";
			}
			byte[] array = value.ToHexBytes();
			byte[] array2 = new byte[array.Length + 2];
			array2[0] = 9;
			array2[1] = (byte)array.Length;
			array.CopyTo(array2, 2);
			return array2;
		}

		internal static byte[] CreateDateTimeValue(DateTime time)
		{
			return new byte[8]
			{
				28,
				BitConverter.GetBytes(time.Year)[1],
				BitConverter.GetBytes(time.Year)[0],
				(byte)time.Month,
				(byte)time.Day,
				(byte)time.Hour,
				(byte)time.Minute,
				(byte)time.Second
			};
		}

		internal static byte[] CreatePreLogin(byte[] time)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(129);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(128);
			memoryStream.Write(time);
			memoryStream.Write(CreateDateTimeWithMs(DateTime.Now));
			memoryStream.Write(CreateDateTimeWithMs(DateTime.Now));
			return memoryStream.ToArray();
		}

		/// <summary>
		/// 将指定的地址信息，控制码信息，数据域信息打包成完整的报文命令
		/// </summary>
		/// <param name="control">控制码信息</param>
		/// <param name="sa">服务器的地址</param>
		/// <param name="ca">客户机地址</param>
		/// <param name="apdu">链路用户数据</param>
		/// <returns>返回是否报文创建成功</returns>
		public static OResult<byte[]> BuildEntireCommand(byte control, string sa, byte ca, byte[] apdu)
		{
			int addressType = 0;
			if (sa == "AA")
			{
				addressType = 3;
			}
			else if (sa.Contains("A"))
			{
				addressType = 1;
			}
			byte[] array = CalculateAddressArea(addressType, 0, sa, ca);
			int num = 0;
			byte[] array2 = new byte[4 + array.Length + 2 + apdu.Length + 2 + 1];
			array2[num++] = 104;
			array2[num++] = BitConverter.GetBytes(array2.Length - 2)[0];
			array2[num++] = BitConverter.GetBytes(array2.Length - 2)[1];
			array2[num++] = control;
			array.CopyTo(array2, num);
			num += array.Length;
			DLT698FcsHelper.CalculateFcs16(array2, 1, num - 1).CopyTo(array2, num);
			num += 2;
			apdu.CopyTo(array2, num);
			num += apdu.Length;
			DLT698FcsHelper.CalculateFcs16(array2, 1, num - 1).CopyTo(array2, num);
			num += 2;
			array2[num] = 22;
			return OResult.CreateSuccessResult(array2);
		}

		private static byte[] CreateApduBySecurity(byte[] apdu, bool useSecurity)
		{
			if (useSecurity)
			{
				byte[] array = new byte[21 + apdu.Length];
				array[0] = 16;
				array[1] = BitConverter.GetBytes(apdu.Length)[1];
				array[2] = BitConverter.GetBytes(apdu.Length)[0];
				array[apdu.Length + 3] = 1;
				array[apdu.Length + 4] = 16;
				array[apdu.Length + 5] = 17;
				array[apdu.Length + 6] = 34;
				array[apdu.Length + 7] = 51;
				array[apdu.Length + 8] = 68;
				array[apdu.Length + 9] = 85;
				array[apdu.Length + 10] = 102;
				array[apdu.Length + 11] = 119;
				array[apdu.Length + 12] = 136;
				array[apdu.Length + 13] = 153;
				array[apdu.Length + 14] = 0;
				array[apdu.Length + 15] = 170;
				array[apdu.Length + 16] = 187;
				array[apdu.Length + 17] = 204;
				array[apdu.Length + 18] = 221;
				array[apdu.Length + 19] = 238;
				array[apdu.Length + 20] = byte.MaxValue;
				apdu.CopyTo(array, 3);
				return array;
			}
			return apdu;
		}

		/// <summary>
		/// 构建读取单个对象的报文数据
		/// </summary>
		/// <param name="address">数据地址信息</param>
		/// <param name="station">特殊指定的站号信息</param>
		/// <param name="dlt">通信的DLT对象</param>
		/// <returns>单次读取的报文信息</returns>
		public static OResult<byte[]> BuildReadSingleObject(string address, string station, IDlt698 dlt)
		{
			bool useSecurityResquest = dlt.UseSecurityResquest;
			if (address.IndexOf(';') > 0)
			{
				string[] array = address.Split(new char[1] { ';' }, StringSplitOptions.RemoveEmptyEntries);
				if (array[0].StartsWith("s="))
				{
					station = array[0].Substring(2);
				}
				address = array[1];
			}
			byte[] array2 = new byte[8] { 5, 1, 1, 0, 0, 2, 0, 0 };
			address.ToHexBytes().CopyTo(array2, 3);
			return BuildEntireCommand(67, station, dlt.CA, CreateApduBySecurity(array2, useSecurityResquest));
		}

		/// <summary>
		/// 构建一个读取多个地址数据的报文信息
		/// </summary>
		/// <param name="address">地址数组</param>
		/// <param name="station">站号信息</param>
		/// <param name="dlt">DLT通信对象</param>
		/// <returns>结果报文内容</returns>
		public static OResult<byte[]> BuildReadMultiObject(string[] address, string station, IDlt698 dlt)
		{
			bool useSecurityResquest = dlt.UseSecurityResquest;
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(5);
			memoryStream.WriteByte(2);
			memoryStream.WriteByte(2);
			memoryStream.WriteByte((byte)address.Length);
			for (int i = 0; i < address.Length; i++)
			{
				string text = address[i];
				if (text.IndexOf(';') > 0)
				{
					string[] array = text.Split(new char[1] { ';' }, StringSplitOptions.RemoveEmptyEntries);
					if (array[0].StartsWith("s="))
					{
						station = array[0].Substring(2);
					}
					text = array[1];
				}
				memoryStream.Write(text.ToHexBytes());
			}
			memoryStream.WriteByte(0);
			return BuildEntireCommand(67, station, dlt.CA, CreateApduBySecurity(memoryStream.ToArray(), useSecurityResquest));
		}

		/// <summary>
		/// 构建单个写得对象的数据操作
		/// </summary>
		/// <param name="address">数据地址信息</param>
		/// <param name="station">站号信息</param>
		/// <param name="data">数据信息</param>
		/// <param name="dlt">通信的DLT对象</param>
		/// <returns>最终报文</returns>
		public static OResult<byte[]> BuildWriteSingleObject(string address, string station, byte[] data, IDlt698 dlt)
		{
			bool useSecurityResquest = dlt.UseSecurityResquest;
			if (address.IndexOf(';') > 0)
			{
				string[] array = address.Split(new char[1] { ';' }, StringSplitOptions.RemoveEmptyEntries);
				if (array[0].StartsWith("s="))
				{
					station = array[0].Substring(2);
				}
				address = array[1];
			}
			byte[] array2 = new byte[8 + data.Length];
			array2[0] = 6;
			array2[1] = 1;
			array2[2] = 2;
			array2[3] = 0;
			array2[4] = 0;
			array2[5] = 2;
			array2[6] = 0;
			data.CopyTo(array2, 7);
			array2[7 + data.Length] = 0;
			address.ToHexBytes().CopyTo(array2, 3);
			return BuildEntireCommand(67, station, dlt.CA, CreateApduBySecurity(array2, useSecurityResquest));
		}

		private static byte GetDayOfWeek(DayOfWeek dayOfWeek)
		{
			return dayOfWeek switch
			{
				DayOfWeek.Monday => 1, 
				DayOfWeek.Tuesday => 2, 
				DayOfWeek.Wednesday => 3, 
				DayOfWeek.Thursday => 4, 
				DayOfWeek.Friday => 5, 
				DayOfWeek.Saturday => 6, 
				_ => 7, 
			};
		}

		/// <summary>
		/// 设置一个事件时间到DLT的报文中去
		/// </summary>
		/// <param name="apdu"></param>
		/// <param name="index"></param>
		/// <param name="time"></param>
		public static void SetDltDataTime(byte[] apdu, int index, DateTime time)
		{
			apdu[index] = BitConverter.GetBytes(time.Year)[1];
			apdu[index + 1] = BitConverter.GetBytes(time.Year)[0];
			apdu[index + 2] = BitConverter.GetBytes(time.Month)[0];
			apdu[index + 3] = BitConverter.GetBytes(time.Day)[0];
			apdu[index + 4] = GetDayOfWeek(time.DayOfWeek);
			apdu[index + 5] = (byte)time.Hour;
			apdu[index + 6] = (byte)time.Minute;
			apdu[index + 7] = (byte)time.Second;
			apdu[index + 8] = BitConverter.GetBytes(time.Millisecond)[1];
			apdu[index + 9] = BitConverter.GetBytes(time.Millisecond)[0];
		}

		/// <summary>
		/// 根据给定的时间信息创建一个DLT的时间报文
		/// </summary>
		/// <param name="time">时间信息</param>
		/// <returns>时间报文</returns>
		public static byte[] CreateDateTimeWithMs(DateTime time)
		{
			byte[] array = new byte[10];
			SetDltDataTime(array, 0, time);
			return array;
		}

		/// <summary>
		/// 检查当前的反馈数据信息是否正确
		/// </summary>
		/// <param name="response">从仪表反馈的数据信息</param>
		/// <returns>是否校验成功</returns>
		public static OResult<byte[]> CheckResponse(byte[] response)
		{
			try
			{
				if (response.Length < 9)
				{
					return new OResult<byte[]>(StringResources.Language.ReceiveDataLengthTooShort);
				}
				int startIndex = 1;
				if (BitConverter.ToUInt16(response, startIndex) != response.Length - 2)
				{
					return new OResult<byte[]>("Receive length check faild, source: " + response.ToHexString(' '));
				}
				if (!DLT698FcsHelper.CheckFcs16(response, 1, response.Length - 4))
				{
					return new OResult<byte[]>("fcs 16 check failed: " + response.ToHexString(' '));
				}
				startIndex = 5 + (response[4] + 1) + 1 + 2;
				byte[] array = null;
				if (response[startIndex] == 144)
				{
					startIndex++;
					int length = response[startIndex] * 256 + response[startIndex + 1];
					startIndex += 2;
					array = response.SelectMiddle(startIndex, length);
				}
				else
				{
					if (response[startIndex] == 238)
					{
						return new OResult<byte[]>(response[startIndex + 2], "Current device not support request type");
					}
					array = response.SelectMiddle(startIndex, response.Length - startIndex - 3);
				}
				if (array[0] == 134)
				{
					if (array.Length >= 9 && array[1] == 1 && array[7] != 0)
					{
						return new OResult<byte[]>(array[8], GetErrorText(array[8]));
					}
					if (array.Length >= 9 && array[1] == 2 && array[8] != 0)
					{
						return new OResult<byte[]>(array[8], GetErrorText(array[8]));
					}
				}
				else if (array[0] == 133 && array[1] == 2)
				{
					if (array.Length >= 10 && array[8] == 0)
					{
						return new OResult<byte[]>(array[9], GetErrorText(array[9]));
					}
				}
				else if (array.Length >= 9 && array[7] == 0)
				{
					return new OResult<byte[]>(array[8], GetErrorText(array[8]));
				}
				return OResult.CreateSuccessResult(array);
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("CheckResponse failed: " + ex.Message + Environment.NewLine + "Source: " + response.ToHexString(' '));
			}
		}

		private static string ExtraData(byte[] content, IByteTransform byteTransform, ref int index, byte oi1, byte oi2, byte attr)
		{
			byte b = content[index++];
			switch (b)
			{
			case 3:
				return (content[index++] != 0).ToString();
			case 4:
			{
				byte b12 = content[index++];
				int num6 = (b12 + 7) / 8;
				byte[] inBytes = content.SelectMiddle(index, num6);
				index += num6;
				return inBytes.ToBoolArray().SelectBegin(b12).ToArrayString();
			}
			case 5:
			{
				int value11 = byteTransform.TransInt32(content, index);
				index += 4;
				return GetScale(value11, oi1, oi2, attr);
			}
			case 6:
			{
				uint value10 = byteTransform.TransUInt32(content, index);
				index += 4;
				return GetScale(value10, oi1, oi2, attr);
			}
			case 9:
			{
				int num5 = content[index++];
				string result3 = content.SelectMiddle(index, num5).ToHexString();
				index += num5;
				return result3;
			}
			case 10:
			{
				int num4 = content[index++];
				string result2 = Encoding.ASCII.GetString(content, index, num4);
				index += num4;
				return result2;
			}
			default:
				switch (b)
				{
				case 10:
				{
					int num3 = content[index++];
					string result = Encoding.UTF8.GetString(content, index, num3);
					index += num3;
					return result;
				}
				case 15:
					return GetScale((sbyte)content[index++], oi1, oi2, attr);
				case 16:
				{
					short value9 = byteTransform.TransInt16(content, index);
					index += 2;
					return GetScale(value9, oi1, oi2, attr);
				}
				case 17:
					return GetScale(content[index++], oi1, oi2, attr);
				case 18:
				{
					ushort value8 = byteTransform.TransUInt16(content, index);
					index += 2;
					return GetScale(value8, oi1, oi2, attr);
				}
				case 20:
				{
					long value7 = byteTransform.TransInt64(content, index);
					index += 8;
					return GetScale(value7, oi1, oi2, attr);
				}
				case 21:
				{
					ulong value6 = byteTransform.TransUInt64(content, index);
					index += 8;
					return GetScale(value6, oi1, oi2, attr);
				}
				case 22:
					return content[index++].ToString();
				case 23:
				{
					float value5 = byteTransform.TransSingle(content, index);
					index += 4;
					return GetScale(value5, oi1, oi2, attr);
				}
				case 24:
				{
					double value4 = byteTransform.TransDouble(content, index);
					index += 8;
					return GetScale(value4, oi1, oi2, attr);
				}
				case 25:
				{
					ushort num2 = byteTransform.TransUInt16(content, index);
					index += 2;
					byte b7 = content[index++];
					byte b8 = content[index++];
					index++;
					byte b9 = content[index++];
					byte b10 = content[index++];
					byte b11 = content[index++];
					ushort millisecond = byteTransform.TransUInt16(content, index);
					index += 2;
					try
					{
						return new DateTime(num2, b7, b8, b9, b10, b11, millisecond).ToString();
					}
					catch
					{
						return $"{num2}-{b7}-{b8} {b9}:{b10}:{b11}";
					}
				}
				case 28:
				{
					ushort num = byteTransform.TransUInt16(content, index);
					index += 2;
					byte b2 = content[index++];
					byte b3 = content[index++];
					byte b4 = content[index++];
					byte b5 = content[index++];
					byte b6 = content[index++];
					try
					{
						return new DateTime(num, b2, b3, b4, b5, b6).ToString();
					}
					catch
					{
						return $"{num}-{b2}-{b3} {b4}:{b5}:{b6}";
					}
				}
				case 26:
				{
					ushort value = byteTransform.TransUInt16(content, index);
					index += 2;
					byte value2 = content[index++];
					byte value3 = content[index++];
					index++;
					return $"{value}-{value2}-{value3}";
				}
				case 27:
				{
					byte hours = content[index++];
					byte minutes = content[index++];
					byte seconds = content[index++];
					return new TimeSpan(hours, minutes, seconds).ToString();
				}
				default:
					return null;
				}
			}
		}

		internal static int GetScale(byte oi1, byte oi2, byte attr)
		{
			attr &= 0xF;
			int result = 0;
			if ((oi1 & 0xF0) == 0)
			{
				result = ((attr != 4) ? (-2) : (-4));
			}
			else if ((oi1 & 0xF0) == 16)
			{
				result = -4;
			}
			else
			{
				switch (oi1)
				{
				case 32:
					if (oi2 == 0)
					{
						result = -1;
						break;
					}
					if (oi2 == 1)
					{
						result = -3;
						break;
					}
					if (oi2 < 10)
					{
						result = -1;
						break;
					}
					if (oi2 == 10)
					{
						result = -3;
						break;
					}
					if (oi2 < 16)
					{
						result = -2;
						break;
					}
					if (oi2 == 16)
					{
						result = -1;
						break;
					}
					if (oi2 < 19)
					{
						result = -2;
						break;
					}
					if (oi2 < 23)
					{
						result = 0;
						break;
					}
					if (oi2 < 30)
					{
						result = -4;
						break;
					}
					if (oi2 < 38)
					{
						result = 0;
						break;
					}
					if (oi2 < 42)
					{
						result = -2;
						break;
					}
					switch (oi2)
					{
					case 49:
					case 50:
						result = -2;
						break;
					case 128:
					case 144:
						result = -4;
						break;
					}
					break;
				case 37:
					if (oi2 < 2)
					{
						result = -4;
					}
					else if (oi2 < 4)
					{
						result = -2;
					}
					break;
				case 64:
					if (oi2 == 48)
					{
						result = -1;
					}
					break;
				case 65:
					if (oi2 == 12 || oi2 == 13 || oi2 == 14 || oi2 == 15)
					{
						result = -3;
					}
					break;
				}
			}
			return result;
		}

		private static string GetScale<T>(T value, byte oi1, byte oi2, byte attr)
		{
			int scale = GetScale(oi1, oi2, attr);
			if (scale == 0)
			{
				return value.ToString();
			}
			return (Convert.ToDouble(value) * Math.Pow(10.0, scale)).ToString();
		}

		internal static string[] ExtraStringsValues(IByteTransform byteTransform, byte[] response, ref int index)
		{
			List<string> list = new List<string>();
			if (response[index] == 1 || response[index] == 2)
			{
				index++;
				int num = response[index++];
				for (int i = 0; i < num; i++)
				{
					list.AddRange(ExtraStringsValues(byteTransform, response, ref index));
				}
				return list.ToArray();
			}
			if (response[index] == 0)
			{
				return list.ToArray();
			}
			list.Add(ExtraData(response, byteTransform, ref index, response[3], response[4], response[5]));
			return list.ToArray();
		}

