		/// <summary>
		/// 根据传入的APDU的命令读取原始的字节数据返回，并检查返回的字节数据是否合法<br />
		/// Read the original byte data return according to the incoming APDU command, and check whether the returned byte data is valid
		/// </summary>
		/// <param name="dlt">通信的DLT对象</param>
		/// <param name="apdu">apdu报文信息</param>
		/// <returns>原始字节数据信息</returns>
		public static OResult<byte[]> ReadByApdu(IDlt698 dlt, byte[] apdu)
		{
			OResult<byte[]> oResult = BuildEntireCommand(67, dlt.Station, dlt.CA, apdu);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = dlt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return CheckResponse(oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Instrument.DLT.Helper.DLT698Helper.ReadByApdu(Snet.Driver.Instrument.DLT.Helper.IDlt698,System.Byte[])" />
		public static async Task<OResult<byte[]>> ReadByApduAsync(IDlt698 dlt, byte[] apdu)
		{
			OResult<byte[]> oResult = BuildEntireCommand(67, dlt.Station, dlt.CA, apdu);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await dlt.ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return CheckResponse(oResult2.Content);
		}

		/// <summary>
		/// 激活设备的命令，只发送数据到设备，不等待设备数据返回<br />
		/// The command to activate the device, only send data to the device, do not wait for the device data to return
		/// </summary>
		/// <returns>是否发送成功</returns>
		public static OResult ActiveDeveice(IDlt698 dlt)
		{
			return dlt.ReadFromCoreServer(new byte[4] { 254, 254, 254, 254 }, hasResponseData: false, usePackAndUnpack: false);
		}

		/// <summary>
		/// 根据指定的数据标识来读取相关的原始数据信息，地址标识根据手册来，从高位到地位，例如 00-00-00-00，分割符可以任意特殊字符或是没有分隔符。<br />
		/// Read the relevant original data information according to the specified data identifier. The address identifier is based on the manual, 
		/// from high to position, such as 00-00-00-00. The separator can be any special character or no separator.
		/// </summary>
		/// <remarks>
		/// 地址可以携带地址域信息，例如 "s=2;00-00-00-00" 或是 "s=100000;00-00-02-00"，关于数据域信息，需要查找手册，例如:00-01-00-00 表示： (当前)正向有功总电能
		/// </remarks>
		/// <param name="dlt">通信的DLT对象</param>
		/// <param name="address">数据标识，具体需要查找手册来对应</param>
		/// <param name="length">数据长度信息</param>
		/// <returns>结果信息</returns>
		public static OResult<byte[]> Read(IDlt698 dlt, string address, ushort length)
		{
			OResult<byte[]> oResult = BuildReadSingleObject(address, dlt.Station, dlt);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = dlt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return CheckResponse(oResult2.Content);
		}

		/// <summary>
		/// 读取指定地址的所有的字符串数据信息，一般来说，一个地址只有一个数据，当属性为数组或是结构体的时候，存在多个数据，具体几个数据，需要根据
		/// </summary>
		/// <remarks>
		/// 地址可以携带地址域信息，例如 "s=2;20-00-02-00" 或是 "s=100000;20-00-02-00"，
		/// </remarks>
		/// <param name="dlt">通信的DLT对象</param>
		/// <param name="address">数据标识，具体需要查找手册来对应</param>
		/// <returns>字符串数组信息</returns>
		public static OResult<string[]> ReadStringArray(IDlt698 dlt, string address)
		{
			OResult<byte[]> oResult = Read(dlt, address, 1);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult);
			}
			int index = 8;
			return OResult.CreateSuccessResult(ExtraStringsValues(dlt.ByteTransform, oResult.Content, ref index));
		}

		/// <summary>
		/// 批量读取多个地址的数据信息，返回所有的数据对象信息<br />
		/// </summary>
		/// <param name="dlt">DLT通信对象</param>
		/// <param name="address">地址数组信息</param>
		/// <returns>字符串结果数据</returns>
		public static OResult<string[]> ReadStringArray(IDlt698 dlt, string[] address)
		{
			OResult<byte[]> oResult = BuildReadMultiObject(address, dlt.Station, dlt);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult);
			}
			OResult<byte[]> oResult2 = dlt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult2);
			}
			OResult<byte[]> oResult3 = CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult3);
			}
			int num = oResult3.Content[3];
			List<string> list = new List<string>();
			int index = 9;
			for (int i = 0; i < num; i++)
			{
				list.AddRange(ExtraStringsValues(dlt.ByteTransform, oResult3.Content, ref index));
				index += 5;
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		internal static OResult<T[]> ReadDataAndParse<T>(OResult<string[]> read, ushort length, Func<string, T> trans)
		{
			if (!read.IsSuccess)
			{
				return OResult.CreateFailedResult<T[]>(read);
			}
			try
			{
				return OResult.CreateSuccessResult((from m in read.Content.Take(length)
					select trans(m)).ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<T[]>(typeof(T).Name + ".Parse failed: " + ex.Message + Environment.NewLine + "Source: " + read.Content.ToArrayString());
			}
		}

		internal static OResult<bool[]> ReadBool(OResult<string[]> read, ushort length)
		{
			if (!read.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(read);
			}
			try
			{
				List<bool> list = new List<bool>();
				for (int i = 0; i < read.Content.Length; i++)
				{
					list.AddRange(read.Content[i].ToStringArray<bool>());
				}
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<bool[]>("bool.Parse failed: " + ex.Message + Environment.NewLine + "Source: " + read.Content.ToArrayString());
			}
		}

		/// <summary>
		/// 根据指定的数据标识来写入相关的原始数据信息，地址标识根据手册来，从高位到地位，例如 00-00-00-00，分割符可以任意特殊字符或是没有分隔符。<br />
		/// Read the relevant original data information according to the specified data identifier. The address identifier is based on the manual, 
		/// from high to position, such as 00-00-00-00. The separator can be any special character or no separator.
		/// </summary>
		/// <remarks>
		/// 写入数据的时候，需要使用类型+值信息，例如写入地址 40-00-02-00  值为 1C 07 E0 01 14 10 1B 0B  表示 时间：2016-01-20 16：27：11
		/// </remarks>
		/// <param name="dlt">通信的DLT对象</param>
		/// <param name="address">地址信息</param>
		/// <param name="value">写入的数据值</param>
		/// <returns>是否写入成功</returns>
		public static OResult Write(IDlt698 dlt, string address, byte[] value)
		{
			OResult<byte[]> oResult = BuildWriteSingleObject(address, dlt.Station, value, dlt);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = dlt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			return CheckResponse(oResult2.Content);
		}

		/// <summary>
		/// 读取设备的通信地址，仅支持点对点通讯的情况，返回地址域数据，例如：149100007290<br />
		/// Read the communication address of the device, only support point-to-point communication, and return the address field data, for example: 149100007290
		/// </summary>
		/// <param name="dlt">通信的DLT对象</param>
		/// <returns>设备的通信地址</returns>
		public static OResult<string> ReadAddress(IDlt698 dlt)
		{
			OResult<byte[]> oResult = BuildReadSingleObject("40-01-02-00", "AAAAAAAAAAAA", dlt);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = dlt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			OResult<byte[]> oResult3 = CheckResponse(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			dlt.Station = oResult3.Content.SelectMiddle(10, oResult3.Content[9]).ToHexString();
			return OResult.CreateSuccessResult(dlt.Station);
		}

		/// <summary>
		/// 写入设备的地址域信息，仅支持点对点通讯的情况，需要指定地址域信息，例如：149100007290<br />
		/// Write the address domain information of the device, only support point-to-point communication, 
		/// you need to specify the address domain information, for example: 149100007290
		/// </summary>
		/// <param name="dlt">通信的DLT对象</param>
		/// <param name="address">等待写入的地址域</param>
		/// <returns>是否写入成功</returns>
		public static OResult WriteAddress(IDlt698 dlt, string address)
		{
			OResult<byte[]> oResult = BuildWriteSingleObject("40-01-02-00", "AAAAAAAAAAAA", CreateStringValueBuffer(address), dlt);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = dlt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			return CheckResponse(oResult2.Content);
		}

		/// <summary>
		/// 写入设备的时间信息到指定的地址，返回是否成功，使用的时间类型为 0x1C, 有效数据为 年月日时分秒。<br />
		/// Write the time information of the device to the specified address, return whether it is successful, the time type used is 0x1C, and the valid data is year, month, day, hour, minute, and second.
		/// </summary>
		/// <param name="dlt">通信的DLT对象</param>
		/// <param name="address">写入的地址的信息</param>
		/// <param name="time">时间数据</param>
		/// <returns>是否写入成功</returns>
		public static OResult WriteDateTime(IDlt698 dlt, string address, DateTime time)
		{
			OResult<byte[]> oResult = BuildWriteSingleObject(address, dlt.Station, CreateDateTimeValue(time), dlt);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = dlt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			return CheckResponse(oResult2.Content);
		}
	}
