namespace Snet.Driver.Instrument.CJT.Helper
{
	/// <summary>
	/// CJT188辅助方法
	/// </summary>
	public class CJT188Helper
	{
		/// <summary>
		/// 从用户输入的地址信息中解析出真实的地址及数据标识
		/// </summary>
		/// <param name="address">用户输入的地址信息</param>
		/// <param name="defaultStation">默认的地址域</param>
		/// <returns>解析结果信息</returns>
		public static OResult<string, byte[]> AnalysisBytesAddress(string address, string defaultStation)
		{
			try
			{
				string value = defaultStation;
				byte[] array = new byte[3];
				if (address.IndexOf(';') > 0)
				{
					string[] array2 = address.Split(new char[1] { ';' }, StringSplitOptions.RemoveEmptyEntries);
					for (int i = 0; i < array2.Length; i++)
					{
						if (array2[i].StartsWith("s="))
						{
							value = array2[i].Substring(2);
						}
						else
						{
							array2[i].ToHexBytes().ToArray().CopyTo(array, 0);
						}
					}
				}
				else
				{
					address.ToHexBytes().ToArray().CopyTo(array, 0);
				}
				return OResult.CreateSuccessResult(value, array);
			}
			catch (Exception ex)
			{
				return new OResult<string, byte[]>("Address prase wrong: " + ex.Message);
			}
		}

		/// <summary>
		/// 将地址解析成BCD码的地址，并且扩充到14位，不够的补0操作
		/// </summary>
		/// <param name="address">地址域信息</param>
		/// <returns>实际的结果</returns>
		public static OResult<byte[]> GetAddressByteFromString(string address)
		{
			if (address == null || address.Length == 0)
			{
				return new OResult<byte[]>(StringResources.Language.DLTAddressCannotNull);
			}
			if (address.Length > 14)
			{
				return new OResult<byte[]>(StringResources.Language.DLTAddressCannotMoreThan12);
			}
			if (!Regex.IsMatch(address, "^[0-9A-A]+$"))
			{
				return new OResult<byte[]>(StringResources.Language.DLTAddressMatchFailed);
			}
			if (address.Length < 14)
			{
				address = address.PadLeft(14, '0');
			}
			return OResult.CreateSuccessResult(Enumerable.Reverse(address.ToHexBytes()).ToArray());
		}

		/// <summary>
		/// 将指定的地址信息，控制码信息，数据域信息打包成完整的报文命令
		/// </summary>
		/// <param name="address">地址域信息，地址域由7个字节构成，每字节2位BCD码，地址长度可达14位十进制数。地址域支持锁位寻址，即从若干低位起，剩余高位补AAH作为通配符进行读表操作</param>
		/// <param name="type">仪表类型</param>
		/// <param name="control">控制码信息</param>
		/// <param name="dataArea">数据域的内容</param>
		/// <returns>返回是否报文创建成功</returns>
		public static OResult<byte[]> Build188EntireCommand(string address, byte type, byte control, byte[] dataArea)
		{
			if (dataArea == null)
			{
				dataArea = new byte[0];
			}
			OResult<byte[]> addressByteFromString = GetAddressByteFromString(address);
			if (!addressByteFromString.IsSuccess)
			{
				return addressByteFromString;
			}
			byte[] array = new byte[13 + dataArea.Length];
			array[0] = 104;
			array[1] = type;
			addressByteFromString.Content.CopyTo(array, 2);
			array[9] = control;
			array[10] = (byte)dataArea.Length;
			if (dataArea.Length != 0)
			{
				dataArea.CopyTo(array, 11);
			}
			int num = 0;
			for (int i = 0; i < array.Length - 2; i++)
			{
				num += array[i];
			}
			array[^2] = (byte)num;
			array[^1] = 22;
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 检查当前的反馈数据信息是否正确
		/// </summary>
		/// <param name="cjt">CJT188的通信对象</param>
		/// <param name="response">从仪表反馈的数据信息</param>
		/// <returns>是否校验成功</returns>
		public static OResult CheckResponse(ICjt188 cjt, byte[] response)
		{
			if (response.Length < 13)
			{
				return new OResult(StringResources.Language.ReceiveDataLengthTooShort);
			}
			if ((response[9] & 0x40) == 64)
			{
				byte b = response[12];
				if (b.GetBoolByIndex(0))
				{
					return new OResult("阀门关");
				}
				if (b.GetBoolByIndex(1))
				{
					return new OResult("阀门异常");
				}
				if (b.GetBoolByIndex(2))
				{
					return new OResult("电池欠压");
				}
				if (b > 0)
				{
					return new OResult(b, "厂商定义的异常");
				}
				return OResult.CreateSuccessResult();
			}
			return OResult.CreateSuccessResult();
		}

		private static OResult<byte[]> ExtraActualContent(byte[] dataArea, byte[] content)
		{
			try
			{
				if (dataArea[0] == 10 && dataArea[1] == 129)
				{
					return OResult.CreateSuccessResult(Enumerable.Reverse(content.SelectMiddle(2, 7)).ToArray());
				}
				if (content.Length < 16)
				{
					return OResult.CreateSuccessResult(new byte[0]);
				}
				return OResult.CreateSuccessResult(content.SelectMiddle(14, content[10] - 3));
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>("ExtraActualContent failed: " + ex.Message + Environment.NewLine + "Content: " + content.ToHexString(' '));
			}
		}

		private static OResult<byte[]> ReadWithAddress(ICjt188 cjt, string address, byte[] dataArea)
		{
			OResult<byte[]> oResult = Build188EntireCommand(address, cjt.InstrumentType, 1, dataArea);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = cjt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponse(cjt, oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return ExtraActualContent(dataArea, oResult2.Content);
		}

		private static async Task<OResult<byte[]>> ReadWithAddressAsync(ICjt188 cjt, string address, byte[] dataArea)
		{
			OResult<byte[]> oResult = Build188EntireCommand(address, cjt.InstrumentType, 1, dataArea);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = await cjt.ReadFromCoreServerAsync(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponse(cjt, oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return ExtraActualContent(dataArea, oResult2.Content);
		}

		/// <summary>
		/// 根据指定的数据标识来读取相关的原始数据信息，地址标识根据手册来，从高位到地位，例如 91-1F，分割符可以任意特殊字符或是没有分隔符。<br />
		/// Read the relevant original data information according to the specified data identifier. The address identifier is based on the manual, 
		/// from high to position, such as 91-1F. The separator can be any special character or no separator.
		/// </summary>
		/// <remarks>
		/// 地址可以携带地址域信息，例如 "s=2;90-1F" 或是 "s=100000;90-1F"，关于数据域信息，需要查找手册，例如:D1-20 表示： 上一月结算日累积流量
		/// </remarks>
		/// <param name="cjt">CJT188的通信对象</param>
		/// <param name="address">数据标识，具体需要查找手册来对应</param>
		/// <param name="length">数据长度信息</param>
		/// <returns>结果信息</returns>
		public static OResult<byte[]> Read(ICjt188 cjt, string address, int length)
		{
			OResult<string, byte[]> oResult = AnalysisBytesAddress(address, cjt.Station);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return ReadWithAddress(cjt, oResult.Content1, oResult.Content2);
		}

		/// <summary>
		/// 根据指定的数据标识来写入相关的原始数据信息，地址标识根据手册来，从高位到地位，例如 90-1F，分割符可以任意特殊字符或是没有分隔符。<br />
		/// Read the relevant original data information according to the specified data identifier. The address identifier is based on the manual, 
		/// from high to position, such as 90-1F. The separator can be any special character or no separator.
		/// </summary>
		/// <remarks>
		/// 地址可以携带地址域信息，例如 "s=2;90-1F" 或是 "s=100000;90-1F"，关于数据域信息，需要查找手册，例如:00-01-00-00 表示： (当前)正向有功总电能<br />
		/// 注意：本命令必须与编程键配合使用
		/// </remarks>
		/// <param name="cjt">CJT188的通信对象</param>
		/// <param name="address">地址信息</param>
		/// <param name="value">写入的数据值</param>
		/// <returns>是否写入成功</returns>
		public static OResult Write(ICjt188 cjt, string address, byte[] value)
		{
			OResult<string, byte[]> oResult = AnalysisBytesAddress(address, cjt.Station);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			byte[] dataArea = SoftBasic.SpliceArray<byte>(oResult.Content2, value);
			OResult<byte[]> oResult2 = Build188EntireCommand(oResult.Content1, cjt.InstrumentType, 4, dataArea);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult<byte[]> oResult3 = cjt.ReadFromCoreServer(oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return CheckResponse(cjt, oResult3.Content);
		}

		/// <summary>
		/// 读取数据的数组信息，需要指定如何从字符串转换的功能方法
		/// </summary>
		/// <typeparam name="T">类型信息</typeparam>
		/// <param name="cjt">CJT188的通信对象</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <param name="trans">转换方法</param>
		/// <returns>包含泛型数组的结果对象</returns>
		public static OResult<T[]> ReadValue<T>(ICjt188 cjt, string address, ushort length, Func<string, T> trans)
		{
			OResult<string[]> oResult = ReadStringArray(cjt, address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<T[]>(oResult);
			}
			return OResult.CreateSuccessResult((from m in oResult.Content.SelectBegin(length)
				select trans(m)).ToArray());
		}

		/// <summary>
		/// 读取设备的通信地址，仅支持点对点通讯的情况，返回地址域数据，例如：14910000729012<br />
		/// Read the communication address of the device, only support point-to-point communication, and return the address field data, for example: 149100007290
		/// </summary>
		/// <param name="cjt">CJT188的通信对象</param>
		/// <returns>设备的通信地址</returns>
		public static OResult<string> ReadAddress(ICjt188 cjt)
		{
			OResult<byte[]> oResult = Build188EntireCommand("AAAAAAAAAAAAAA", cjt.InstrumentType, 3, new byte[3] { 129, 10, 0 });
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult<byte[]> oResult2 = cjt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult2);
			}
			OResult oResult3 = CheckResponse(cjt, oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult3);
			}
			if (oResult2.Content.Length >= 9)
			{
				cjt.Station = Enumerable.Reverse(oResult2.Content.SelectMiddle(2, 7)).ToArray().ToHexString();
				return OResult.CreateSuccessResult(Enumerable.Reverse(oResult2.Content.SelectMiddle(2, 7)).ToArray().ToHexString());
			}
			return new OResult<string>(StringResources.Language.ReceiveDataLengthTooShort + " Content: " + oResult2.Content.ToHexString(' '));
		}

		/// <summary>
		/// 写入设备的地址域信息，仅支持点对点通讯的情况，需要指定地址域信息，例如：14910000729011<br />
		/// Write the address domain information of the device, only support point-to-point communication, 
		/// you need to specify the address domain information, for example: 14910000729011
		/// </summary>
		/// <param name="cjt">CJT188的通信对象</param>
		/// <param name="address">等待写入的地址域</param>
		/// <returns>是否写入成功</returns>
		public static OResult WriteAddress(ICjt188 cjt, string address)
		{
			OResult<byte[]> addressByteFromString = GetAddressByteFromString(address);
			if (!addressByteFromString.IsSuccess)
			{
				return addressByteFromString;
			}
			OResult<byte[]> oResult = Build188EntireCommand(cjt.Station, cjt.InstrumentType, 21, SoftBasic.SpliceArray<byte>(new byte[3] { 160, 24, 0 }, addressByteFromString.Content));
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<byte[]> oResult2 = cjt.ReadFromCoreServer(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			OResult oResult3 = CheckResponse(cjt, oResult2.Content);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			return OResult.CreateSuccessResult();
		}

