					num = 100.0;
					break;
				}
			}
			if (text.Contains("FF"))
			{
				return OResult.CreateSuccessResult(double.NaN, defaultUnit);
			}
			try
			{
				return OResult.CreateSuccessResult(Convert.ToDouble(text) / scale * num, defaultUnit);
			}
			catch
			{
				return OResult.CreateSuccessResult(double.NaN, defaultUnit);
			}
