		private static string GetDateTime(byte[] source, int index)
		{
			return source.SelectMiddle(index, 2).ToHexString() + "-" + source.SelectMiddle(index + 2, 1).ToHexString() + "-" + source.SelectMiddle(index + 3, 1).ToHexString() + " " + source.SelectMiddle(index + 4, 1).ToHexString() + ":" + source.SelectMiddle(index + 5, 1).ToHexString() + ":" + source.SelectMiddle(index + 6, 1).ToHexString();
		}

		private static string GetUnitScale(string unit, double unitScale)
		{
			if (unitScale == 1.0)
			{
				return unit;
			}
			if (unitScale == 10.0)
			{
				return unit + "*10";
			}
			if (unitScale == 100.0)
			{
				return unit + "*100";
			}
			if (unitScale == 1000.0)
			{
				return "k" + unit;
			}
			if (unitScale == 10000.0)
			{
				return "k" + unit + "*10";
			}
			if (unitScale == 100000.0)
			{
				return "k" + unit + "*100";
			}
			if (unitScale == 1000000.0)
			{
				return "M" + unit;
			}
			if (unitScale == 10000000.0)
			{
				return "M" + unit + "*10";
			}
			if (unitScale == 100000000.0)
			{
				return "M" + unit + "*100";
			}
			if (unitScale == 1000000000.0)
			{
				return "G" + unit;
			}
			if (unitScale == 10000000000.0)
			{
				return "G" + unit + "*10";
			}
			if (unitScale == 100000000000.0)
			{
				return "G" + unit + "*100";
			}
			return unit + "*" + unitScale;
		}

		private static string[] TransStringsFromCJT(ICjt188 cjt, byte[] source, ushort dido)
		{
			switch (dido)
			{
			case 36895:
			{
				OResult<double, string> actualValueAndUnit2 = GetActualValueAndUnit(source, 0, 4, 100.0, hasUnit: true, string.Empty);
				OResult<double, string> actualValueAndUnit3 = GetActualValueAndUnit(source, 5, 4, 100.0, hasUnit: true, string.Empty);
				return new string[5]
				{
					actualValueAndUnit2.Content1.ToString(),
					actualValueAndUnit2.Content2,
					actualValueAndUnit3.Content1.ToString(),
					actualValueAndUnit3.Content2,
					GetDateTime(source, 10)
				};
			}
			case 53536:
			case 53537:
			case 53538:
			case 53539:
			case 53540:
			case 53541:
			case 53542:
			case 53543:
			case 53544:
			case 53545:
			case 53546:
			case 53547:
			case 53548:
			case 53549:
			case 53550:
			case 53551:
			{
				OResult<double, string> actualValueAndUnit = GetActualValueAndUnit(source, 0, 4, 100.0, hasUnit: true, string.Empty);
				return new string[2]
				{
					actualValueAndUnit.Content1.ToString(),
					actualValueAndUnit.Content2
				};
			}
			default:
				switch (dido)
				{
				case 33026:
					return new string[5]
					{
						GetActualValueAndUnit(source, 0, 3, 100.0, hasUnit: false, "").Content1.ToString(),
						GetActualValueAndUnit(source, 3, 3, 1.0, hasUnit: false, "").Content1.ToString(),
						GetActualValueAndUnit(source, 6, 3, 100.0, hasUnit: false, "").Content1.ToString(),
						GetActualValueAndUnit(source, 9, 3, 1.0, hasUnit: false, "").Content1.ToString(),
						GetActualValueAndUnit(source, 12, 3, 100.0, hasUnit: false, "").Content1.ToString()
					};
				case 33029:
					return new string[5]
					{
						source.SelectMiddle(0, 1).ToHexString(),
						GetActualValueAndUnit(source, 1, 4, 100.0, hasUnit: false, "").Content1.ToString(),
						GetActualValueAndUnit(source, 5, 4, 100.0, hasUnit: false, "").Content1.ToString(),
						GetActualValueAndUnit(source, 9, 4, 100.0, hasUnit: false, "").Content1.ToString(),
						GetActualValueAndUnit(source, 13, 2, 1.0, hasUnit: false, "").Content1.ToString()
					};
				case 33030:
					return new string[1] { source.SelectMiddle(0, 1).ToHexString() };
				case 33034:
					return new string[1] { source.ToHexString() };
				default:
					return new string[1] { source.ToHexString() };
				case 33027:
				case 33028:
					return new string[1] { source.ToHexString() };
				}
			}
		}

		/// <summary>
		/// 读取指定地址的所有的字符串数据信息，一般来说，一个地址只有一个数据
		/// </summary>
		/// <remarks>
		/// 地址可以携带地址域信息，例如 "s=2;90-1F" 或是 "s=100000;90-1F"
		/// </remarks>
		/// <param name="cjt">CJT通信对象</param>
		/// <param name="address">数据标识，具体需要查找手册来对应</param>
		/// <returns>字符串数组信息</returns>
		public static OResult<string[]> ReadStringArray(ICjt188 cjt, string address)
		{
			OResult<string, byte[]> oResult = AnalysisBytesAddress(address, cjt.Station);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult);
			}
			OResult<byte[]> oResult2 = ReadWithAddress(cjt, oResult.Content1, oResult.Content2);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<string[]>(oResult2);
			}
			try
			{
				ushort dido = BitConverter.ToUInt16(new byte[2]
				{
					oResult.Content2[1],
					oResult.Content2[0]
				}, 0);
				return OResult.CreateSuccessResult(TransStringsFromCJT(cjt, oResult2.Content, dido));
			}
			catch (Exception ex)
			{
				return new OResult<string[]>("TransStringsFromCJT failed: " + ex.Message + Environment.NewLine + "Content: " + oResult2.Content.ToHexString(' '));
			}
		}
	}
