	{
		/// <summary>
		/// 仪表的类型
		/// </summary>
		byte InstrumentType { get; set; }

		/// <inheritdoc cref="P:Snet.Driver.Instrument.DLT.Helper.IDlt645.Station" />
		string Station { get; set; }

		/// <summary>
		/// 获取或设置是否在每一次的报文通信时，增加"FE FE"的命令头<br />
		/// Get or set whether to add the command header of "FE FE" in each message communication
		/// </summary>
		bool EnableCodeFE { get; set; }

		/// <summary>
		/// 激活设备的命令，只发送数据到设备，不等待设备数据返回<br />
		/// The command to activate the device, only send data to the device, do not wait for the device data to return
		/// </summary>
		/// <returns>是否发送成功</returns>
		OResult ActiveDeveice();

		/// <inheritdoc cref="M:Snet.Driver.Instrument.CJT.Helper.CJT188Helper.WriteAddress(Snet.Driver.Instrument.CJT.Helper.ICjt188,System.String)" />
		OResult WriteAddress(string address);

		/// <inheritdoc cref="M:Snet.Driver.Instrument.CJT.Helper.CJT188Helper.ReadAddress(Snet.Driver.Instrument.CJT.Helper.ICjt188)" />
		OResult<string> ReadAddress();

		/// <inheritdoc cref="M:Snet.Driver.Instrument.CJT.Helper.CJT188Helper.ReadStringArray(Snet.Driver.Instrument.CJT.Helper.ICjt188,System.String)" />
		OResult<string[]> ReadStringArray(string address);
	}
