namespace Snet.Driver.Core
{
	/// <summary>
	/// 所有数据转换类的静态辅助方法<br />
	/// Static helper method for all data conversion classes
	/// </summary>
	public static class ByteTransformHelper
	{
		/// <summary>
		/// 结果转换操作的基础方法，需要支持类型，及转换的委托，并捕获转换时的异常方法
		/// </summary>
		/// <typeparam name="TResult">结果类型</typeparam>
		/// <param name="result">源</param>
		/// <param name="translator">实际转换的委托</param>
		/// <returns>转换结果</returns>
		public static OResult<TResult> GetResultFromBytes<TResult>(OResult<byte[]> result, Func<byte[], TResult> translator)
		{
			try
			{
				if (result.IsSuccess)
				{
					return OResult.CreateSuccessResult(translator(result.Content));
				}
				return OResult.CreateFailedResult<TResult>(result);
			}
			catch (Exception ex)
			{
				return new OResult<TResult>
				{
					Message = $"{StringResources.Language.DataTransformError} {SoftBasic.ByteToHexString(result.Content)} : Length({result.Content.Length}) {ex.Message}"
				};
			}
		}

		/// <summary>
		/// 结果转换操作的基础方法，需要支持类型，及转换的委托
		/// </summary>
		/// <typeparam name="TResult">结果类型</typeparam>
		/// <param name="result">源结果</param>
		/// <returns>转换结果</returns>
		public static OResult<TResult> GetResultFromArray<TResult>(OResult<TResult[]> result)
		{
			return GetSuccessResultFromOther<TResult, TResult[]>(result, (TResult[] m) => m[0]);
		}

		/// <summary>
		/// 使用指定的转换方法，来获取到实际的结果对象内容，所转换的规则
		/// </summary>
		/// <typeparam name="TResult">结果类型</typeparam>
		/// <typeparam name="TIn">输入类型</typeparam>
		/// <param name="result">原始的结果对象</param>
		/// <param name="trans">转换方法，从类型TIn转换拿到TResult的泛型委托</param>
		/// <returns>类型为TResult的对象</returns>
		public static OResult<TResult> GetSuccessResultFromOther<TResult, TIn>(OResult<TIn> result, Func<TIn, TResult> trans)
		{
			if (!result.IsSuccess)
			{
				return OResult.CreateFailedResult<TResult>(result);
			}
			try
			{
				return OResult.CreateSuccessResult(trans(result.Content));
			}
			catch (Exception ex)
			{
				return new OResult<TResult>(StringResources.Language.DataTransformError + " " + ex.Message);
			}
		}

		/// <summary>
		/// 使用指定的转换方法，来获取到实际的结果对象内容
		/// </summary>
		/// <typeparam name="TIn">输入类型</typeparam>
		/// <param name="result">原始的结果对象</param>
		/// <param name="trans">转换方法，从类型TIn转换拿到OResult的TResult的泛型委托</param>
		/// <returns>类型为TResult的对象</returns>
		public static OResult GetResultFromOther<TIn>(OResult<TIn> result, Func<TIn, OResult> trans)
		{
			if (!result.IsSuccess)
			{
				return result;
			}
			return trans(result.Content);
		}

		/// <summary>
		/// 使用指定的转换方法，来获取到实际的结果对象内容
		/// </summary>
		/// <typeparam name="TResult">结果类型</typeparam>
		/// <typeparam name="TIn">输入类型</typeparam>
		/// <param name="result">原始的结果对象</param>
		/// <param name="trans">转换方法，从类型TIn转换拿到OResult的TResult的泛型委托</param>
		/// <returns>类型为TResult的对象</returns>
		public static OResult<TResult> GetResultFromOther<TResult, TIn>(OResult<TIn> result, Func<TIn, OResult<TResult>> trans)
		{
			return result.Then(trans);
		}

		/// <summary>
		/// 使用指定的转换方法，来获取到实际的结果对象内容
		/// </summary>
		/// <typeparam name="TResult">结果类型</typeparam>
		/// <typeparam name="TIn1">输入类型1</typeparam>
		/// <typeparam name="TIn2">输入类型2</typeparam>
		/// <param name="result">原始的结果对象</param>
		/// <param name="trans1">转换方法1，从类型TIn1转换拿到OResult的TIn2的泛型委托</param>
