		/// <summary>
		/// 将多个SoftBuffer实例中的字节数组合并成一个MemoryStream<br />
		/// Combines the byte arrays from multiple SoftBuffer instances into a single MemoryStream.
		/// </summary>
		/// <param name="softBuffers">An array of SoftBuffer instances whose bytes will be combined.</param>
		/// <returns>A MemoryStream containing the concatenated bytes from all provided SoftBuffer instances.</returns>
		public static MemoryStream GetByteFromSoftBuffer(params SoftBuffer[] softBuffers)
		{
			MemoryStream memoryStream = new MemoryStream();
			for (int i = 0; i < softBuffers.Length; i++)
			{
				memoryStream.Write(softBuffers[i].GetBytes());
			}
			return memoryStream;
		}

		/// <summary>
		/// 将一个字节数组的内容依次分配到多个SoftBuffer实例中<br />
		/// Distributes the contents of a byte array into multiple SoftBuffer instances sequentially.
		/// </summary>
		/// <param name="buffer">The source byte array to be distributed.</param>
		/// <param name="startIndex">起始偏移的字节索引</param>
		/// <param name="softBuffers">The target SoftBuffer instances to receive the byte data.</param>
		public static void SetByteToSoftBuffer(byte[] buffer, int startIndex, params SoftBuffer[] softBuffers)
		{
			if (buffer != null && buffer.Length != 0)
			{
				int num = startIndex;
				for (int i = 0; i < softBuffers.Length && num + softBuffers[i].Capacity <= buffer.Length; i++)
				{
					softBuffers[i].SetBytes(buffer, num, 0, softBuffers[i].Capacity);
					num += softBuffers[i].Capacity;
				}
			}
		}
	}
	/// <summary>
	/// 用于通信的锁的基类
	/// </summary>
	public class CommunicationLockNone : ICommunicationLock, IDisposable
	{
		private bool disposedValue;

		/// <inheritdoc cref="M:Snet.Driver.Core.ICommunicationLock.EnterLock(System.Int32)" />
		public virtual OResult EnterLock(int timeout)
		{
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.ICommunicationLock.LeaveLock" />
		public virtual void LeaveLock()
		{
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		protected virtual void Dispose(bool disposing)
		{
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			if (!disposedValue)
			{
				Dispose(disposing: true);
				disposedValue = true;
			}
		}
	}
	/// <summary>
	/// 用于通信的一个简单的基元混合锁
	/// </summary>
	public class CommunicationLockSimple : CommunicationLockNone
	{
		private int m_waiters;

		private readonly AutoResetEvent m_waiterLock = new AutoResetEvent(initialState: false);

		/// <summary>
		/// 获取当前锁是否在等待当中<br />
		/// Gets whether the current lock is waiting
		/// </summary>
		public bool IsWaitting => m_waiters != 0;

		/// <inheritdoc />
		public override OResult EnterLock(int timeout)
		{
			try
			{
				if (Interlocked.Increment(ref m_waiters) == 1)
				{
					return OResult.CreateSuccessResult();
				}
				return m_waiterLock.WaitOne(timeout) ? OResult.CreateSuccessResult() : new OResult($"Enter lock failed, timeout: {timeout}");
			}
			catch (Exception ex)
			{
				return new OResult("Enter lock failed, message: " + ex.Message);
			}
		}

		/// <inheritdoc />
		public override void LeaveLock()
		{
			if (Interlocked.Decrement(ref m_waiters) != 0)
			{
				m_waiterLock.Set();
			}
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			m_waiterLock.Close();
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return "CommunicationLockSimple[" + (IsWaitting ? "Locking" : "Unlock") + "]";
		}
	}
	/// <summary>
	/// 线程的协调逻辑状态
	/// </summary>
	internal enum CoordinationStatus
	{
		/// <summary>
