	/// <summary>
	/// 静态的方法支持类，提供一些网络的静态支持，支持从套接字从同步接收指定长度的字节数据，并支持报告进度。<br />
	/// The static method support class provides some static support for the network, supports receiving byte data of a specified length from the socket from synchronization, and supports reporting progress.
	/// </summary>
	/// <remarks>
	/// 在接收指定数量的字节数据的时候，如果一直接收不到，就会发生假死的状态。接收的数据时保存在内存里的，不适合大数据块的接收。
	/// </remarks>
	public static class NetSupport
	{
		/// <summary>
		/// Socket传输中的缓冲池大小<br />
		/// Buffer pool size in socket transmission
		/// </summary>
		internal const int SocketBufferSize = 16384;

		/// <summary>
		/// 表示Socket发生异常的错误码<br />
		/// An error code indicates that an exception has occurred in the socket
		/// </summary>
		public static int SocketErrorCode { get; } = -1;

		/// <summary>
		/// 根据接收数据的长度信息，合理的分割出单次的长度信息
		/// </summary>
		/// <param name="length">要接收数据的总长度信息</param>
		/// <returns>本次接收数据的长度</returns>
		internal static int GetSplitLengthFromTotal(int length)
		{
			if (length < 1024)
			{
				return length;
			}
			if (length <= 8192)
			{
				return 2048;
			}
			if (length <= 32768)
			{
				return 8192;
			}
			if (length <= 262144)
			{
				return 32768;
			}
			if (length <= 1048576)
			{
				return 262144;
			}
			if (length <= 8388608)
			{
				return 1048576;
			}
			return 2097152;
		}

		/// <summary>
		/// 从socket的网络中读取数据内容，需要指定数据长度和超时的时间，为了防止数据太大导致接收失败，所以此处接收到新的数据之后就更新时间。<br />
		/// To read the data content from the socket network, you need to specify the data length and timeout period. In order to prevent the data from being too large and cause the reception to fail, the time is updated after new data is received here.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="receive">接收的长度</param>
		/// <param name="reportProgress">当前接收数据的进度报告，有些协议支持传输非常大的数据内容，可以给与进度提示的功能</param>
		/// <returns>最终接收的指定长度的byte[]数据</returns>
		internal static byte[] ReadBytesFromSocket(Socket socket, int receive, Action<long, long> reportProgress = null)
		{
			byte[] array = new byte[receive];
			ReceiveBytesFromSocket(socket, array, 0, receive, reportProgress);
			return array;
		}

		/// <summary>
		/// 从socket的网络中读取数据内容，需要指定数据长度和超时的时间，为了防止数据太大导致接收失败，所以此处接收到新的数据之后就更新时间。<br />
		/// To read the data content from the socket network, you need to specify the data length and timeout period. In order to prevent the data from being too large and cause the reception to fail, the time is updated after new data is received here.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="buffer">缓存的字节数组</param>
		/// <param name="offset">偏移信息</param>
		/// <param name="length">接收长度</param>
		/// <param name="reportProgress">当前接收数据的进度报告，有些协议支持传输非常大的数据内容，可以给与进度提示的功能</param>
		/// <exception cref="T:Snet.Driver.Core.RemoteCloseException">远程关闭的异常信息</exception>
		internal static void ReceiveBytesFromSocket(Socket socket, byte[] buffer, int offset, int length, Action<long, long> reportProgress = null)
		{
			int num = 0;
			while (num < length)
			{
				int size = Math.Min(length - num, 16384);
				int num2 = socket.Receive(buffer, num + offset, size, SocketFlags.None);
				num += num2;
				if (num2 == 0)
				{
					throw new RemoteCloseException();
				}
				reportProgress?.Invoke(num, length);
			}
		}

		/// <summary>
		/// 从socket的网络中读取数据内容，然后写入到流中
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="stream">等待写入的流</param>
		/// <param name="length">长度信息</param>
		/// <param name="reportProgress">当前接收数据的进度报告，有些协议支持传输非常大的数据内容，可以给与进度提示的功能</param>
		/// <exception cref="T:Snet.Driver.Core.RemoteCloseException">远程关闭的异常信息</exception>
		internal static void ReceiveBytesFromSocket(Socket socket, Stream stream, int length, Action<long, long> reportProgress = null)
		{
			int num = 0;
			byte[] array = new byte[GetSplitLengthFromTotal(length)];
			while (num < length)
			{
				int num2 = socket.Receive(array, 0, array.Length, SocketFlags.None);
				stream.Write(array, 0, num2);
				num += num2;
				if (num2 == 0)
				{
					throw new RemoteCloseException();
				}
				reportProgress?.Invoke(num, length);
			}
		}

		/// <summary>
		/// 创建一个新的socket对象并连接到远程的地址，需要指定远程终结点，超时时间（单位是毫秒），如果需要绑定本地的IP或是端口，传入 local对象<br />
		/// To create a new socket object and connect to the remote address, you need to specify the remote endpoint, 
		/// the timeout period (in milliseconds), if you need to bind the local IP or port, pass in the local object
		/// </summary>
		/// <param name="ipAddress">IP地址信息，支持Ipv4，Ipv6，以及域名</param>
		/// <param name="port">端口号信息</param>
		/// <param name="timeOut">连接的超时时间</param>
		/// <param name="local">如果需要绑定本地的IP地址，就需要设置当前的对象</param>
		/// <returns>返回套接字的封装结果对象</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkBase.cs" region="CreateSocketAndConnectExample" title="创建连接示例" />
		/// </example>
		internal static OResult<Socket> CreateSocketAndConnect(string ipAddress, int port, int timeOut, IPEndPoint local = null)
		{
			return CreateSocketAndConnect(new IPEndPoint(IPAddress.Parse(SnetHelper.GetIpAddressFromInput(ipAddress)), port), timeOut, local);
		}

		private static void SetSocketOption(Socket socket)
		{
			try
			{
				socket.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, optionValue: true);
			}
			catch
			{
			}
		}

		/// <summary>
		/// 创建一个新的socket对象并连接到远程的地址，需要指定远程终结点，超时时间（单位是毫秒），如果需要绑定本地的IP或是端口，传入 local对象<br />
		/// To create a new socket object and connect to the remote address, you need to specify the remote endpoint, 
		/// the timeout period (in milliseconds), if you need to bind the local IP or port, pass in the local object
		/// </summary>
		/// <param name="endPoint">连接的目标终结点</param>
		/// <param name="timeOut">连接的超时时间</param>
		/// <param name="local">如果需要绑定本地的IP地址，就需要设置当前的对象</param>
		/// <returns>返回套接字的封装结果对象</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkBase.cs" region="CreateSocketAndConnectExample" title="创建连接示例" />
		/// </example>
		internal static OResult<Socket> CreateSocketAndConnect(IPEndPoint endPoint, int timeOut, IPEndPoint local = null)
		{
			int num = 0;
			while (true)
			{
				num++;
				Socket socket = null;
				try
				{
					socket = new Socket(endPoint.AddressFamily, SocketType.Stream, ProtocolType.Tcp);
				}
				catch (Exception ex)
				{
					return new OResult<Socket>("Socket Create Exception -> " + ex.Message);
				}
				SetSocketOption(socket);
				SnetTimeOut snetTimeOut = SnetTimeOut.HandleTimeOutCheck(socket, timeOut);
				try
				{
					if (local != null)
					{
						socket.Bind(local);
					}
					socket.Connect(endPoint);
					snetTimeOut.IsSuccessful = true;
					return OResult.CreateSuccessResult(socket);
				}
				catch (Exception ex2)
				{
					socket?.Close();
					snetTimeOut.IsSuccessful = true;
					if (snetTimeOut.GetConsumeTime() < TimeSpan.FromMilliseconds(500.0) && num < 2)
					{
						SnetHelper.ThreadSleep(100);
						continue;
					}
					if (snetTimeOut.IsTimeout)
					{
						return new OResult<Socket>(string.Format(StringResources.Language.ConnectTimeout, endPoint, timeOut) + " ms");
					}
					return new OResult<Socket>($"Socket Connect {endPoint} Exception -> " + ex2.Message);
				}
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteDevice.ReadFromCoreServer(System.Collections.Generic.IEnumerable{System.Byte[]})" />
		public static OResult<byte[]> ReadFromCoreServer(IEnumerable<byte[]> send, Func<byte[], OResult<byte[]>> funcRead)
		{
			List<byte> list = new List<byte>();
			foreach (byte[] item in send)
			{
				OResult<byte[]> oResult = funcRead(item);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				if (oResult.Content != null)
				{
					list.AddRange(oResult.Content);
				}
			}
			return OResult.CreateSuccessResult(list.ToArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.NetSupport.CreateSocketAndConnect(System.Net.IPEndPoint,System.Int32,System.Net.IPEndPoint)" />
		internal static async Task<OResult<Socket>> CreateSocketAndConnectAsync(IPEndPoint endPoint, int timeOut, IPEndPoint local = null)
		{
			int connectCount = 0;
			while (true)
			{
				connectCount++;
				Socket socket;
				try
				{
					socket = new Socket(endPoint.AddressFamily, SocketType.Stream, ProtocolType.Tcp);
				}
				catch (Exception ex)
				{
					return new OResult<Socket>("Socket Create Exception -> " + ex.Message);
				}
				SetSocketOption(socket);
				SnetTimeOut connectTimeout = SnetTimeOut.HandleTimeOutCheck(socket, timeOut);
				try
				{
					if (local != null)
					{
						socket.Bind(local);
					}
					await Task.Factory.FromAsync(socket.BeginConnect(endPoint, null, socket), socket.EndConnect).ConfigureAwait(continueOnCapturedContext: false);
					connectTimeout.IsSuccessful = true;
					return OResult.CreateSuccessResult(socket);
				}
				catch (Exception ex2)
				{
					connectTimeout.IsSuccessful = true;
					socket?.Close();
					if (!(connectTimeout.GetConsumeTime() < TimeSpan.FromMilliseconds(500.0)) || connectCount >= 2)
					{
						if (connectTimeout.IsTimeout)
						{
							return new OResult<Socket>(string.Format(StringResources.Language.ConnectTimeout, endPoint, timeOut) + " ms");
						}
						return new OResult<Socket>("Socket BeginConnect Exception -> " + ex2.Message);
					}
					await Task.Delay(100);
				}
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteDevice.ReadFromCoreServer(System.Collections.Generic.IEnumerable{System.Byte[]})" />
		public static async Task<OResult<byte[]>> ReadFromCoreServerAsync(IEnumerable<byte[]> send, Func<byte[], Task<OResult<byte[]>>> funcRead)
		{
			List<byte> array = new List<byte>();
			foreach (byte[] item in send)
			{
				OResult<byte[]> oResult = await funcRead(item).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				if (oResult.Content != null)
				{
					array.AddRange(oResult.Content);
				}
			}
			return OResult.CreateSuccessResult(array.ToArray());
		}

