		/// <summary>
		/// 发送消息给套接字，直到完成的时候返回，经过测试，本方法是线程安全的。<br />
		/// Send a message to the socket until it returns when completed. After testing, this method is thread-safe.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="data">字节数据</param>
		/// <param name="offset">偏移的位置信息</param>
		/// <param name="size">发送的数据总数</param>
		/// <returns>发送是否成功的结果</returns>
		public static OResult SocketSend(Socket socket, byte[] data, int offset, int size)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			if (socket == null)
			{
				return new OResult<byte[]>(SocketErrorCode, "Socket is null");
			}
			try
			{
				int num = 0;
				do
				{
					int num2 = socket.Send(data, offset, size - num, SocketFlags.None);
					num += num2;
					offset += num2;
				}
				while (num < size && num < data.Length);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult<byte[]>(SocketErrorCode, ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.NetSupport.SocketSend(System.Net.Sockets.Socket,System.Byte[],System.Int32,System.Int32)" />
		public static async Task<OResult> SocketSendAsync(Socket socket, byte[] data)
		{
			if (data == null)
			{
				return await Task.FromResult(OResult.CreateSuccessResult()).ConfigureAwait(continueOnCapturedContext: false);
			}
			return await SocketSendAsync(socket, data, 0, data.Length).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.NetSupport.SocketSend(System.Net.Sockets.Socket,System.Byte[],System.Int32,System.Int32)" />
		public static async Task<OResult> SocketSendAsync(Socket socket, byte[] data, int offset, int size)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			if (socket == null)
			{
				return new OResult<byte[]>(SocketErrorCode, "Socket is null");
			}
			int sendCount = 0;
			try
			{
				do
				{
					int num = await Task.Factory.FromAsync(socket.BeginSend(data, offset, size - sendCount, SocketFlags.None, null, socket), (Func<IAsyncResult, int>)socket.EndSend).ConfigureAwait(continueOnCapturedContext: false);
					sendCount += num;
					offset += num;
				}
				while (sendCount < size && sendCount < data.Length);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult<byte[]>(SocketErrorCode, ex.Message);
			}
		}

