		/// <summary>
		/// 读取流中的数据到缓存区，读取的长度需要按照实际的情况来判断<br />
		/// Read the data in the stream to the buffer area. The length of the read needs to be determined according to the actual situation.
		/// </summary>
		/// <param name="stream">数据流</param>
		/// <param name="buffer">缓冲区</param>
		/// <returns>带有成功标志的读取数据长度</returns>
		public static OResult<int> ReadStream(Stream stream, byte[] buffer)
		{
			ManualResetEvent manualResetEvent = new ManualResetEvent(initialState: false);
			FileStateObject fileStateObject = new FileStateObject
			{
				WaitDone = manualResetEvent,
				Stream = stream,
				DataLength = buffer.Length,
				Buffer = buffer
			};
			try
			{
				stream.BeginRead(buffer, 0, fileStateObject.DataLength, ReadStreamCallBack, fileStateObject);
			}
			catch (Exception ex)
			{
				fileStateObject = null;
				manualResetEvent.Close();
				return new OResult<int>("stream.BeginRead Exception -> " + ex.Message);
			}
			manualResetEvent.WaitOne();
			manualResetEvent.Close();
			if (!fileStateObject.IsError)
			{
				return OResult.CreateSuccessResult(fileStateObject.AlreadyDealLength);
			}
			return new OResult<int>(fileStateObject.ErrerMsg);
		}

		private static void ReadStreamCallBack(IAsyncResult ar)
		{
			if (ar.AsyncState is FileStateObject fileStateObject)
			{
				try
				{
					fileStateObject.AlreadyDealLength += fileStateObject.Stream.EndRead(ar);
					fileStateObject.WaitDone.Set();
				}
				catch (Exception ex)
				{
					fileStateObject.IsError = true;
					fileStateObject.ErrerMsg = ex.Message;
					fileStateObject.WaitDone.Set();
				}
			}
		}

		/// <summary>
		/// 将缓冲区的数据写入到流里面去<br />
		/// Write the buffer data to the stream
		/// </summary>
		/// <param name="stream">数据流</param>
		/// <param name="buffer">缓冲区</param>
		/// <returns>是否写入成功</returns>
		public static OResult WriteStream(Stream stream, byte[] buffer)
		{
			ManualResetEvent manualResetEvent = new ManualResetEvent(initialState: false);
			FileStateObject fileStateObject = new FileStateObject
			{
				WaitDone = manualResetEvent,
				Stream = stream
			};
			try
			{
				stream.BeginWrite(buffer, 0, buffer.Length, WriteStreamCallBack, fileStateObject);
			}
			catch (Exception ex)
			{
				fileStateObject = null;
				manualResetEvent.Close();
				return new OResult("stream.BeginWrite Exception -> " + ex.Message);
			}
			manualResetEvent.WaitOne();
			manualResetEvent.Close();
			if (fileStateObject.IsError)
			{
				return new OResult
				{
					Message = fileStateObject.ErrerMsg
				};
			}
			return OResult.CreateSuccessResult();
		}

		private static void WriteStreamCallBack(IAsyncResult ar)
		{
			if (!(ar.AsyncState is FileStateObject fileStateObject))
			{
				return;
			}
			try
			{
				fileStateObject.Stream.EndWrite(ar);
			}
			catch (Exception ex)
			{
				fileStateObject.IsError = true;
				fileStateObject.ErrerMsg = ex.Message;
			}
			finally
			{
				fileStateObject.WaitDone.Set();
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.NetSupport.ReadStream(System.IO.Stream,System.Byte[])" />
		public static async Task<OResult<int>> ReadStreamAsync(Stream stream, byte[] buffer)
		{
			try
			{
				return OResult.CreateSuccessResult(await stream.ReadAsync(buffer, 0, buffer.Length).ConfigureAwait(continueOnCapturedContext: false));
			}
			catch (Exception ex)
			{
				stream?.Close();
				return new OResult<int>(ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.NetSupport.WriteStream(System.IO.Stream,System.Byte[])" />
		public static async Task<OResult> WriteStreamAsync(Stream stream, byte[] buffer)
		{
			int alreadyCount = 0;
			try
			{
				await stream.WriteAsync(buffer, alreadyCount, buffer.Length - alreadyCount).ConfigureAwait(continueOnCapturedContext: false);
				return OResult.CreateSuccessResult(alreadyCount);
			}
			catch (Exception ex)
			{
				stream?.Close();
				return new OResult<int>(ex.Message);
			}
		}
	}
	/// <summary>
	/// 数据转换类的基础，提供了一些基础的方法实现，默认 <see cref="F:Snet.Driver.Core.DataFormat.CDAB" /> 的顺序，和C#的字节顺序是一致的。<br />
	/// The basis of the data conversion class provides some basic method implementations. 
	/// The default order of <see cref="F:Snet.Driver.Core.DataFormat.CDAB" /> is consistent with the byte order of C#.
	/// </summary>
