			}
			byte[] bytes = encoding.GetBytes(value);
			if (!IsStringReverseByteWord)
			{
				return bytes;
			}
			return SoftBasic.BytesReverseByWord(bytes);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IByteTransform.TransByte(System.String,System.Int32,System.Text.Encoding)" />
