	/// <summary>
	/// 一个简单的混合线程同步锁，采用了基元用户加基元内核同步构造实现<br />
	/// A simple hybrid thread editing lock, implemented by the base user plus the element kernel synchronization.
	/// </summary>
	/// <remarks>
	/// 当前的锁适用于，竞争频率比较低，锁部分的代码运行时间比较久的情况，当前的简单混合锁可以达到最大性能。
	/// </remarks>
	/// <example>
	/// 以下演示常用的锁的使用方式，还包含了如何优雅的处理异常锁
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\ThreadLock.cs" region="SimpleHybirdLockExample1" title="SimpleHybirdLock示例" />
	/// </example>
	public sealed class SimpleHybirdLock : IDisposable
	{
		private bool disposedValue;

		/// <summary>
		/// 基元用户模式构造同步锁
		/// </summary>
		private int m_waiters;

		private int m_lock_tick;

		private DateTime m_enterlock_time = DateTime.Now;

		/// <summary>
		/// 基元内核模式构造同步锁
		/// </summary>
		private readonly Lazy<AutoResetEvent> m_waiterLock = new Lazy<AutoResetEvent>(() => new AutoResetEvent(initialState: false));

		private static long simpleHybirdLockCount;

		private static long simpleHybirdLockWaitCount;

		/// <summary>
		/// 获取当前锁是否在等待当中<br />
		/// Gets whether the current lock is waiting
		/// </summary>
		public bool IsWaitting => m_waiters != 0;

		/// <summary>
		/// 获取当前进入等待锁的数量<br />
		/// Gets the number of pending locks currently entered
		/// </summary>
		public int LockingTick => m_lock_tick;

		/// <summary>
		/// 获取当前Snet.Driver组件里正总的所有进入锁的信息<br />
		/// Gets the information about all incoming locks in the current Snet.Driver component
		/// </summary>
		public static long SimpleHybirdLockCount => simpleHybirdLockCount;

		/// <summary>
		/// 当前Snet.Driver组件里正在等待的锁的统计信息，此时已经发生了竞争了<br />
		/// Statistics on locks currently waiting in the Snet.Driver component are now in contention
		/// </summary>
		public static long SimpleHybirdLockWaitCount => simpleHybirdLockWaitCount;

		private void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				m_waiterLock.Value.Close();
				disposedValue = true;
			}
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			Dispose(disposing: true);
		}

		/// <summary>
		/// 获取锁，可以指定获取锁的超时时间，如果指定的时间没有获取锁，则返回<c>False</c>，反之，返回<c>True</c><br />
		/// To acquire a lock, you can specify the timeout period for acquiring a lock, return <c>False</c> if the specified time does not acquire a lock, and vice versa, return <c>True</c>
		/// </summary>
		/// <returns>是否正确的获得锁</returns>
		public bool Enter()
		{
			Interlocked.Increment(ref simpleHybirdLockCount);
			if (Interlocked.Increment(ref m_waiters) == 1)
			{
				m_enterlock_time = DateTime.Now;
				return true;
			}
			Interlocked.Increment(ref simpleHybirdLockWaitCount);
			Interlocked.Increment(ref m_lock_tick);
			bool num = m_waiterLock.Value.WaitOne();
			if (!num)
			{
				Interlocked.Decrement(ref simpleHybirdLockCount);
				Interlocked.Decrement(ref simpleHybirdLockWaitCount);
				Interlocked.Decrement(ref m_lock_tick);
				return num;
			}
			m_enterlock_time = DateTime.Now;
			return num;
		}

		/// <summary>
		/// 离开锁<br />
		/// Leave the lock
		/// </summary>
		/// <returns>如果该操作成功，返回<c>True</c>，反之，返回<c>False</c></returns>
		public bool Leave()
		{
			Interlocked.Decrement(ref simpleHybirdLockCount);
			if (Interlocked.Decrement(ref m_waiters) == 0)
			{
				return true;
			}
			bool result = m_waiterLock.Value.Set();
			Interlocked.Decrement(ref simpleHybirdLockWaitCount);
			Interlocked.Decrement(ref m_lock_tick);
			return result;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			if (m_lock_tick > 0)
			{
				return $"SimpleHybirdLock[WaitOne-{DateTime.Now - m_enterlock_time}]";
			}
			if (m_waiters != 0)
			{
				return $"SimpleHybirdLock[OneLock-{DateTime.Now - m_enterlock_time}]";
			}
			return "SimpleHybirdLock[NoneLock]";
		}
	}
	/// <summary>
	/// 一个双检锁的示例，适合一些占内存的静态数据对象，获取的时候才实例化真正的对象
	/// </summary>
	internal sealed class Singleton
	{
		private static object m_lock = new object();

		private static Singleton SValue = null;

		public static Singleton GetSingleton()
		{
			if (SValue != null)
			{
				return SValue;
			}
			Monitor.Enter(m_lock);
			if (SValue == null)
			{
				Singleton value = new Singleton();
				Volatile.Write(ref SValue, value);
				SValue = new Singleton();
			}
			Monitor.Exit(m_lock);
			return SValue;
		}
	}
	/// <summary>
	/// 一个用于高性能，乐观并发模型控制操作的类，允许一个方法(隔离方法)的安全单次执行
	/// </summary>
	public sealed class SnetAsyncCoordinator
	{
		private Action action;

		private int OperaterStatus;

		private long Target;

		/// <summary>
		/// 实例化一个对象，需要传入隔离执行的方法
		/// </summary>
		/// <param name="operater">隔离执行的方法</param>
		public SnetAsyncCoordinator(Action operater)
		{
			action = operater;
		}

		/// <summary>
		/// 启动线程池执行隔离方法
		/// </summary>
		public void StartOperaterInfomation()
		{
			Interlocked.Increment(ref Target);
			if (Interlocked.CompareExchange(ref OperaterStatus, 1, 0) == 0)
			{
				ThreadPool.QueueUserWorkItem(ThreadPoolOperater, null);
			}
		}

		private void ThreadPoolOperater(object obj)
		{
			long num = Target;
			long num2 = 0L;
			long num3;
			do
			{
				num3 = num;
				action?.Invoke();
				num = Interlocked.CompareExchange(ref Target, num2, num3);
			}
			while (num3 != num);
			Interlocked.Exchange(ref OperaterStatus, 0);
			if (Target != num2)
			{
				StartOperaterInfomation();
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return "SnetAsyncCoordinator";
		}
	}
	/// <summary>
	/// Snet.Driver的一些静态辅助方法<br />
	/// Some static auxiliary methods of Snet.Driver
	/// </summary>
	public class SnetHelper
	{
		/// <summary>
		/// 本通讯项目的随机数信息<br />
		/// Random number information for this newsletter
		/// </summary>
		public static Random SnetRandom { get; private set; } = new Random();

		/// <summary>
		/// 本通讯项目单个通信对象最多的锁累积次数，超过该次数，将直接返回失败。<br />
		/// The maximum number of lock accumulations for a single communication object in this communication item, beyond which the number will be returned as a failure.
		/// </summary>
		/// <remarks>
		/// 默认为 1000 次
		/// </remarks>
		public static int LockLimit { get; set; } = 1000;

		/// <summary>
		/// 本通信库的单个通信对象在异步通信的时候是否使用异步锁，默认<b>True</b>，适用于winform，wpf等UI程序(有效防止UI上同时读写PLC时发生死锁问题)，如果是控制台程序或是纯后台线程采集的程序，适合配置<b>False</b><br />
		/// Whether a single communication object of this communication library uses asynchronous locks during asynchronous communication, the default is <b>True</b>, which is suitable for UI programs such as winform, 
		/// wpf and so on (effectively preventing deadlock problems when reading and writing PLCs at the same time on the UI), and if it is a console program or a program collected by pure background threads, it is suitable to configure <b>False</b>
		/// </summary>
		public static bool UseAsyncLock { get; set; } = true;

		/// <summary>
		/// 解析地址的附加参数方法，比如你的地址是s=100;D100，可以提取出"s"的值的同时，修改地址本身，如果"s"不存在的话，返回给定的默认值<br />
		/// The method of parsing additional parameters of the address, for example, if your address is s=100;D100, you can extract the value of "s" and modify the address itself. If "s" does not exist, return the given default value
		/// </summary>
		/// <param name="address">复杂的地址格式，比如：s=100;D100</param>
		/// <param name="paraName">等待提取的参数名称</param>
		/// <param name="defaultValue">如果提取的参数信息不存在，返回的默认值信息</param>
		/// <returns>解析后的新的数据值或是默认的给定的数据值</returns>
		public static int ExtractParameter(ref string address, string paraName, int defaultValue)
		{
			OResult<int> oResult = ExtractParameter(ref address, paraName);
			if (!oResult.IsSuccess)
			{
				return defaultValue;
			}
			return oResult.Content;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.SnetHelper.ExtractParameter(System.String@,System.String,System.Int32)" />
		public static OResult<int> ExtractParameterWithDefault(ref string address, string paraName, int defaultValue)
		{
			if (!Regex.Match(address, paraName + "=[0-9A-Fa-fxX]+;", RegexOptions.IgnoreCase).Success)
			{
				return OResult.CreateSuccessResult(defaultValue);
			}
			return ExtractParameter(ref address, paraName);
		}

		/// <summary>
		/// 解析地址的附加Bool类型参数方法，比如你的地址是s=true;D100，可以提取出"s"的值的同时，修改地址本身，如果"s"不存在的话，返回给定的默认值<br />
		/// The method of parsing additional parameters of the address, for example, if your address is s=true;D100, you can extract the value of "s" and modify the address itself. If "s" does not exist, return the given default value
		/// </summary>
		/// <param name="address">复杂的地址格式，比如：s=true;D100</param>
		/// <param name="paraName">等待提取的参数名称</param>
		/// <param name="defaultValue">如果提取的参数信息不存在，返回的默认值信息</param>
		/// <returns>解析后的新的数据值或是默认的给定的数据值</returns>
		public static bool ExtractBooleanParameter(ref string address, string paraName, bool defaultValue)
		{
			OResult<bool> oResult = ExtractBooleanParameter(ref address, paraName);
			if (!oResult.IsSuccess)
			{
				return defaultValue;
			}
			return oResult.Content;
		}

		/// <summary>
		/// 解析地址的附加参数方法，比如你的地址是s=100;D100，可以提取出"s"的值的同时，修改地址本身，如果"s"不存在的话，返回错误的消息内容<br />
		/// The method of parsing additional parameters of the address, for example, if your address is s=100;D100, you can extract the value of "s" and modify the address itself. 
		/// If "s" does not exist, return the wrong message content
		/// </summary>
		/// <param name="address">复杂的地址格式，比如：s=100;D100</param>
		/// <param name="paraName">等待提取的参数名称</param>
		/// <returns>解析后的参数结果内容</returns>
		public static OResult<int> ExtractParameter(ref string address, string paraName)
		{
			Match match = Regex.Match(address, paraName + "=[0-9A-Fa-fxX]+;", RegexOptions.IgnoreCase);
			if (!match.Success)
			{
				return new OResult<int>("Address [" + address + "] can't find [" + paraName + "] Parameters. for example : " + paraName + "=1;100");
			}
			try
			{
				string text = match.Value.Substring(paraName.Length + 1, match.Value.Length - paraName.Length - 2);
				int value = ((text.StartsWith("0x") || text.StartsWith("0X")) ? Convert.ToInt32(text.Substring(2), 16) : (text.StartsWith("0") ? Convert.ToInt32(text, 8) : Convert.ToInt32(text)));
				address = address.Replace(match.Value, "");
				return OResult.CreateSuccessResult(value);
			}
			catch (Exception ex)
			{
				return new OResult<int>("Address [" + address + "] Get [" + paraName + "] Parameters failed: " + ex.Message);
			}
		}

		/// <summary>
		/// 解析地址的附加bool参数方法，比如你的地址是s=true;D100，可以提取出"s"的值的同时，修改地址本身，如果"s"不存在的话，返回错误的消息内容<br />
		/// The method of parsing additional parameters of the address, for example, if your address is s=true;D100, you can extract the value of "s" and modify the address itself. 
		/// If "s" does not exist, return the wrong message content
		/// </summary>
		/// <param name="address">复杂的地址格式，比如：s=true;D100</param>
		/// <param name="paraName">等待提取的参数名称</param>
		/// <returns>解析后的参数结果内容</returns>
		public static OResult<bool> ExtractBooleanParameter(ref string address, string paraName)
		{
			try
			{
				Match match = Regex.Match(address, paraName + "=[0-1A-Za-z]+;");
				if (!match.Success)
				{
					return new OResult<bool>("Address [" + address + "] can't find [" + paraName + "] Parameters. for example : " + paraName + "=True;100");
				}
				string text = match.Value.Substring(paraName.Length + 1, match.Value.Length - paraName.Length - 2);
				bool value = ((!Regex.IsMatch(text, "^[0-1]+$")) ? Convert.ToBoolean(text) : (Convert.ToInt32(text) != 0));
				address = address.Replace(match.Value, "");
				return OResult.CreateSuccessResult(value);
			}
			catch (Exception ex)
			{
				return new OResult<bool>("Address [" + address + "] Get [" + paraName + "] Parameters failed: " + ex.Message);
			}
		}

		/// <summary>
		/// 解析地址的起始地址的方法，比如你的地址是 A[1] , 那么将会返回 1，地址修改为 A，如果不存在起始地址，那么就不修改地址，返回 -1<br />
		/// The method of parsing the starting address of the address, for example, if your address is A[1], then it will return 1, 
		/// and the address will be changed to A. If the starting address does not exist, then the address will not be changed and return -1
		/// </summary>
		/// <param name="address">复杂的地址格式，比如：A[0] </param>
		/// <returns>如果存在，就起始位置，不存在就返回 -1</returns>
		public static int ExtractStartIndex(ref string address)
		{
			try
			{
				Match match = Regex.Match(address, "\\[[0-9]+\\]$");
				if (!match.Success)
				{
					return -1;
				}
				int result = Convert.ToInt32(match.Value.Substring(1, match.Value.Length - 2));
				address = address.Remove(address.Length - match.Value.Length);
				return result;
			}
			catch
			{
				return -1;
			}
		}

		/// <summary>
		/// 解析地址的附加<see cref="T:Snet.Driver.Core.DataFormat" />参数方法，比如你的地址是format=ABCD;D100，可以提取出"format"的值的同时，修改地址本身，如果"format"不存在的话，返回默认的<see cref="T:Snet.Driver.Core.IByteTransform" />对象<br />
		/// Parse the additional <see cref="T:Snet.Driver.Core.DataFormat" /> parameter method of the address. For example, if your address is format=ABCD;D100,
		/// you can extract the value of "format" and modify the address itself. If "format" does not exist, 
		/// Return the default <see cref="T:Snet.Driver.Core.IByteTransform" /> object
		/// </summary>
		/// <param name="address">复杂的地址格式，比如：format=ABCD;D100</param>
		/// <param name="defaultTransform">默认的数据转换信息</param>
		/// <returns>解析后的参数结果内容</returns>
		public static IByteTransform ExtractTransformParameter(ref string address, IByteTransform defaultTransform)
		{
			try
			{
				string text = "format";
				Match match = Regex.Match(address, text + "=(ABCD|BADC|DCBA|CDAB);", RegexOptions.IgnoreCase);
				if (!match.Success)
				{
					return defaultTransform;
				}
				string text2 = match.Value.Substring(text.Length + 1, match.Value.Length - text.Length - 2);
				DataFormat dataFormat = defaultTransform.DataFormat;
				switch (text2.ToUpper())
				{
				case "ABCD":
					dataFormat = DataFormat.ABCD;
					break;
				case "BADC":
					dataFormat = DataFormat.BADC;
					break;
				case "DCBA":
					dataFormat = DataFormat.DCBA;
					break;
				case "CDAB":
					dataFormat = DataFormat.CDAB;
					break;
				}
				address = address.Replace(match.Value, "");
				if (dataFormat != defaultTransform.DataFormat)
				{
					return defaultTransform.CreateByDateFormat(dataFormat);
				}
				return defaultTransform;
			}
			catch
			{
				throw;
			}
		}

		/// <summary>
		/// 切割当前的地址数据信息，根据读取的长度来分割成多次不同的读取内容，需要指定地址，总的读取长度，切割读取长度<br />
		/// Cut the current address data information, and divide it into multiple different read contents according to the read length. 
		/// You need to specify the address, the total read length, and the cut read length
		/// </summary>
		/// <param name="address">整数的地址信息</param>
		/// <param name="length">读取长度信息</param>
		/// <param name="segment">切割长度信息</param>
		/// <returns>切割结果</returns>
		public static OResult<int[], int[]> SplitReadLength(int address, int length, int segment)
		{
			int[] array = SoftBasic.SplitIntegerToArray(length, segment);
			int[] array2 = new int[array.Length];
			for (int i = 0; i < array2.Length; i++)
			{
				if (i == 0)
				{
					array2[i] = address;
				}
				else
				{
					array2[i] = array2[i - 1] + array[i - 1];
				}
			}
			return OResult.CreateSuccessResult(array2, array);
		}

		/// <summary>
		/// 根据指定的长度切割数据数组，返回地址偏移量信息和数据分割信息
		/// </summary>
		/// <typeparam name="T">数组类型</typeparam>
		/// <param name="address">起始的地址</param>
		/// <param name="value">实际的数据信息</param>
		/// <param name="segment">分割的基本长度</param>
		/// <param name="addressLength">一个地址代表的数据长度</param>
		/// <returns>切割结果内容</returns>
		public static OResult<int[], List<T[]>> SplitWriteData<T>(int address, T[] value, ushort segment, int addressLength)
		{
			List<T[]> list = SoftBasic.ArraySplitByLength(value, segment * addressLength);
			int[] array = new int[list.Count];
			for (int i = 0; i < array.Length; i++)
			{
				if (i == 0)
				{
					array[i] = address;
				}
				else
				{
					array[i] = array[i - 1] + list[i - 1].Length / addressLength;
				}
			}
			return OResult.CreateSuccessResult(array, list);
		}

		/// <summary>
		/// 获取地址信息的位索引，在地址最后一个小数点的位置
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <returns>位索引的位置</returns>
		public static int GetBitIndexInformation(ref string address)
		{
			int result = 0;
			int num = address.LastIndexOf('.');
			if (num > 0 && num < address.Length - 1)
			{
				string text = address.Substring(num + 1);
				result = ((!text.Contains(new string[6] { "A", "B", "C", "D", "E", "F" })) ? Convert.ToInt32(text) : Convert.ToInt32(text, 16));
				address = address.Substring(0, num);
			}
			return result;
		}

		/// <summary>
		/// 从当前的字符串信息获取IP地址数据，如果是ip地址直接返回，如果是域名，会自动解析IP地址，否则抛出异常<br />
		/// Get the IP address data from the current string information, if it is an ip address, return directly, 
		/// if it is a domain name, it will automatically resolve the IP address, otherwise an exception will be thrown
		/// </summary>
		/// <param name="value">输入的字符串信息</param>
		/// <returns>真实的IP地址信息</returns>
		public static string GetIpAddressFromInput(string value)
		{
			if (!string.IsNullOrEmpty(value))
			{
				if (!value.EndsWith(new string[6] { ".com", ".cn", ".net", ".top", ".vip", ".club" }) && IPAddress.TryParse(value, out IPAddress _))
				{
					return value;
				}
				IPAddress[] addressList = Dns.GetHostEntry(value).AddressList;
				if (addressList.Length != 0)
				{
					return addressList[0].ToString();
				}
			}
			return "127.0.0.1";
		}

		/// <summary>
		/// 从流中接收指定长度的字节数组
		/// </summary>
		/// <param name="stream">流</param>
		/// <param name="length">数据长度</param>
		/// <returns>二进制的字节数组</returns>
		public static byte[] ReadSpecifiedLengthFromStream(Stream stream, int length)
		{
			byte[] array = new byte[length];
			int num = 0;
			while (num < length)
			{
				int num2 = stream.Read(array, num, array.Length - num);
				num += num2;
				if (num2 == 0)
				{
					break;
				}
			}
			return array;
		}

		/// <summary>
		/// 将字符串的内容写入到流中去
		/// </summary>
		/// <param name="stream">数据流</param>
		/// <param name="value">字符串内容</param>
		public static void WriteStringToStream(Stream stream, string value)
		{
			byte[] value2 = (string.IsNullOrEmpty(value) ? new byte[0] : Encoding.UTF8.GetBytes(value));
			WriteBinaryToStream(stream, value2);
		}

		/// <summary>
		/// 从流中读取一个字符串内容
		/// </summary>
		/// <param name="stream">数据流</param>
		/// <returns>字符串信息</returns>
		public static string ReadStringFromStream(Stream stream)
		{
			byte[] bytes = ReadBinaryFromStream(stream);
			return Encoding.UTF8.GetString(bytes);
		}

		/// <summary>
		/// 将二进制的内容写入到数据流之中
		/// </summary>
		/// <param name="stream">数据流</param>
		/// <param name="value">原始字节数组</param>
		public static void WriteBinaryToStream(Stream stream, byte[] value)
		{
			stream.Write(BitConverter.GetBytes(value.Length), 0, 4);
			stream.Write(value, 0, value.Length);
		}

		/// <summary>
		/// 从流中读取二进制的内容
		/// </summary>
		/// <param name="stream">数据流</param>
		/// <returns>字节数组</returns>
		public static byte[] ReadBinaryFromStream(Stream stream)
		{
			int num = BitConverter.ToInt32(ReadSpecifiedLengthFromStream(stream, 4), 0);
			if (num <= 0)
			{
				return new byte[0];
			}
			return ReadSpecifiedLengthFromStream(stream, num);
		}

		/// <summary>
		/// 从字符串的内容提取UTF8编码的字节，加了对空的校验
		/// </summary>
		/// <param name="message">字符串内容</param>
		/// <returns>结果</returns>
		public static byte[] GetUTF8Bytes(string message)
		{
			if (!string.IsNullOrEmpty(message))
			{
				return Encoding.UTF8.GetBytes(message);
			}
			return new byte[0];
		}

