		/// <summary>
		/// 将原始的字节数组，转换成实际的结构体对象，需要事先定义好结构体内容，否则会转换失败<br />
		/// To convert the original byte array into an actual structure object, 
		/// the structure content needs to be defined in advance, otherwise the conversion will fail
		/// </summary>
		/// <typeparam name="T">自定义的结构体</typeparam>
		/// <param name="content">原始的字节内容</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<T> ByteArrayToStruct<T>(byte[] content) where T : struct
		{
			int num = Marshal.SizeOf(typeof(T));
			nint num2 = Marshal.AllocHGlobal(num);
			try
			{
				Marshal.Copy(content, 0, num2, num);
				T? value = Marshal.PtrToStructure<T>(num2);
				Marshal.FreeHGlobal(num2);
				return OResult.CreateSuccessResult(value);
			}
			catch (Exception ex)
			{
				Marshal.FreeHGlobal(num2);
				return new OResult<T>(ex.Message);
			}
		}

		/// <summary>
		/// 根据当前的位偏移地址及读取位长度信息，计算出实际的字节索引，字节数，字节位偏移
		/// </summary>
		/// <param name="addressStart">起始地址</param>
		/// <param name="length">读取的长度</param>
		/// <param name="newStart">返回的新的字节的索引，仍然按照位单位</param>
		/// <param name="byteLength">字节长度</param>
		/// <param name="offset">当前偏移的信息</param>
		public static void CalculateStartBitIndexAndLength(int addressStart, ushort length, out int newStart, out ushort byteLength, out int offset)
		{
			byteLength = (ushort)((addressStart + length - 1) / 8 - addressStart / 8 + 1);
			offset = addressStart % 8;
			newStart = addressStart - offset;
		}

		/// <summary>
		/// 根据字符串内容，获取当前的位索引地址，例如输入 6,返回6，输入15，返回15，输入B，返回11
		/// </summary>
		/// <param name="bit">位字符串</param>
		/// <returns>结束数据</returns>
		public static int CalculateBitStartIndex(string bit)
		{
			if (Regex.IsMatch(bit, "[ABCDEF]", RegexOptions.IgnoreCase))
			{
				return Convert.ToInt32(bit, 16);
			}
			return Convert.ToInt32(bit);
		}

		/// <summary>
		/// 将一个一维数组中的所有数据按照行列信息拷贝到二维数组里，返回当前的二维数组
		/// </summary>
		/// <typeparam name="T">数组的类型对象</typeparam>
		/// <param name="array">一维数组信息</param>
		/// <param name="row">行</param>
		/// <param name="col">列</param>
		public static T[,] CreateTwoArrayFromOneArray<T>(T[] array, int row, int col)
		{
			T[,] array2 = new T[row, col];
			int num = 0;
			for (int i = 0; i < row; i++)
			{
				for (int j = 0; j < col; j++)
				{
					array2[i, j] = array[num];
					num++;
				}
			}
			return array2;
		}

		/// <summary>
		/// 判断当前的字符串表示的地址，是否以索引为结束
		/// </summary>
		/// <param name="address">PLC的字符串地址信息</param>
		/// <returns>是否以索引结束</returns>
		public static bool IsAddressEndWithIndex(string address)
		{
			return Regex.IsMatch(address, "\\[[0-9]+\\]$");
		}

		/// <summary>
		/// 根据位偏移的地址，长度信息，计算出实际的地址占用长度
		/// </summary>
		/// <param name="address">偏移地址</param>
		/// <param name="length">长度信息</param>
		/// <param name="hex">地址的进制信息，一般为8 或是 16</param>
		/// <returns>占用的地址长度信息</returns>
		public static int CalculateOccupyLength(int address, int length, int hex = 8)
		{
			return (address + length - 1) / hex - address / hex + 1;
		}

		/// <summary>
		/// 根据地址的临界条件来切割读取地址的方法，支持bool地址的切割，支持字地址的切割
		/// </summary>
		/// <typeparam name="T">数据的类型信息</typeparam>
		/// <param name="readFunc">读取的功能方法</param>
		/// <param name="cuttings">切割的地址信息</param>
		/// <param name="address">实际的数据地址</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>使用底层的读取机制来实现真正的读取操作</returns>
		public static OResult<T[]> ReadCuttingHelper<T>(Func<string, ushort, OResult<T[]>> readFunc, List<CuttingAddress> cuttings, string address, ushort length)
		{
			string text = string.Empty;
			OResult<int> oResult = ExtractParameter(ref address, "s");
			if (oResult.IsSuccess)
			{
				text = $"s={oResult.Content};";
			}
			foreach (CuttingAddress cutting in cuttings)
			{
				if (address.StartsWith(cutting.DataType, StringComparison.OrdinalIgnoreCase))
				{
					int num = 0;
					try
					{
						num = Convert.ToInt32(address.Substring(cutting.DataType.Length), cutting.FromBase);
					}
					catch
					{
						break;
					}
					if (num < cutting.Address && num + length > cutting.Address)
					{
						ushort num2 = (ushort)(cutting.Address - num);
						ushort arg = (ushort)(length - num2);
						OResult<T[]> oResult2 = readFunc(text + address, num2);
						if (!oResult2.IsSuccess)
						{
							return oResult2;
						}
						OResult<T[]> oResult3 = readFunc(text + cutting.DataType + Convert.ToString(cutting.Address, cutting.FromBase), arg);
						if (!oResult3.IsSuccess)
						{
							return oResult3;
						}
						return OResult.CreateSuccessResult(SoftBasic.SpliceArray<T>(oResult2.Content, oResult3.Content));
					}
					break;
				}
			}
			return readFunc(address, length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.SnetHelper.ReadCuttingHelper``1(System.Func{System.String,System.UInt16,Snet.Driver.OResult{``0[]}},System.Collections.Generic.List{Snet.Driver.Core.CuttingAddress},System.String,System.UInt16)" />
		public static async Task<OResult<T[]>> ReadCuttingAsyncHelper<T>(Func<string, ushort, Task<OResult<T[]>>> readFunc, List<CuttingAddress> cuttings, string address, ushort length)
		{
			string station = string.Empty;
			OResult<int> oResult = ExtractParameter(ref address, "s");
			if (oResult.IsSuccess)
			{
				station = $"s={oResult.Content};";
			}
			foreach (CuttingAddress item in cuttings)
			{
				if (address.StartsWith(item.DataType, StringComparison.OrdinalIgnoreCase))
				{
					int num;
					try
					{
						num = Convert.ToInt32(address.Substring(item.DataType.Length), item.FromBase);
					}
					catch
					{
						break;
					}
					if (num < item.Address && num + length > item.Address)
					{
						ushort num2 = (ushort)(item.Address - num);
						ushort len2 = (ushort)(length - num2);
						OResult<T[]> read1 = await readFunc(station + address, num2);
						if (!read1.IsSuccess)
						{
							return read1;
						}
						OResult<T[]> oResult2 = await readFunc(station + item.DataType + Convert.ToString(item.Address, item.FromBase), len2);
						if (!oResult2.IsSuccess)
						{
							return oResult2;
						}
						return OResult.CreateSuccessResult(SoftBasic.SpliceArray<T>(read1.Content, oResult2.Content));
					}
					break;
				}
			}
			return await readFunc(address, length);
		}

		private static string[] SplitsAddressDot(string address, string split = ".")
		{
			int num = address.LastIndexOf(split);
			if (num > 0 && num < address.Length - 1)
			{
				return new string[2]
				{
					address.Substring(0, num),
					address.Substring(num + 1)
				};
			}
			return new string[1] { address };
		}

		/// <summary>
		/// 按照位为单位从设备中批量读取bool数组，如果地址中包含了小数点，则使用字的方式读取数据，然后解析出位数据<br />
		/// The BOOL array is read in batches from the device in bits, and if the address contains decimal points, the data is read in a word manner, and then the bit data is parsed
		/// </summary>
		/// <param name="device">设备的通信对象</param>
		/// <param name="address">地址信息</param>
		/// <param name="length">读取的位长度信息</param>
		/// <param name="addressLength">单位地址的占位长度信息</param>
		/// <param name="reverseByWord">是否根据字进行反转操作</param>
		/// <param name="split">位分割字符串</param>
		/// <returns>bool数组的结果对象</returns>
		public static OResult<bool[]> ReadBool(IReadWriteNet device, string address, ushort length, int addressLength = 16, bool reverseByWord = false, string split = ".")
		{
			if (address.IndexOf(split) > 0)
			{
				string[] array = SplitsAddressDot(address, split);
				int num = 0;
				try
				{
					num = CalculateBitStartIndex(array[1]);
				}
				catch (Exception ex)
				{
					return new OResult<bool[]>("Bit Index format wrong, " + ex.Message);
				}
				ushort length2 = (ushort)((length + num + addressLength - 1) / addressLength);
				OResult<byte[]> oResult = device.Read(array[0], length2);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				if (reverseByWord)
				{
					return OResult.CreateSuccessResult(oResult.Content.ReverseByWord().ToBoolArray().SelectMiddle(num, length));
				}
				return OResult.CreateSuccessResult(oResult.Content.ToBoolArray().SelectMiddle(num, length));
			}
			return device.ReadBool(address, length);
		}

		/// <summary>
		/// 将bool数组写入到设备中去，如果地址中包含了小数点，则使用字的方式读取数据，然后解析出位数据，再修改其中的位数据，然后写入到设备中去，解决那些没有位读写的功能码的设备的问题<br />
		/// Write the bool array into the device. If the address contains a decimal point, read the data in word form, then parse out the bit data, modify the bit data within it, 
		/// and then write it back into the device to solve the problem of devices without bit read and write function codes
		/// </summary>
		/// <param name="device">设备的通信对象</param>
		/// <param name="address">地址信息</param>
		/// <param name="value">实际写入的bool数据信息</param>
		/// <param name="addressLength">单位地址的占位长度信息</param>
		/// <param name="reverseByWord">是否根据字进行反转操作</param>
		/// <param name="insertPoint">当地址里缺失小数点的时候，是否进行额外补充小数点</param>
		/// <returns>bool数组的结果对象</returns>
		public static OResult WriteBool(IReadWriteNet device, string address, bool[] value, int addressLength = 16, bool reverseByWord = false, bool insertPoint = false)
		{
			if (address.IndexOf('.') > 0)
			{
				string[] array = SplitsAddressDot(address);
				int num = 0;
				try
				{
					num = CalculateBitStartIndex(array[1]);
				}
				catch (Exception ex)
				{
					return new OResult<bool[]>("Bit Index format wrong, " + ex.Message);
				}
				ushort length = (ushort)((value.Length + num + addressLength - 1) / addressLength);
				OResult<byte[]> oResult = device.Read(array[0], length);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				bool[] array2 = (reverseByWord ? oResult.Content.ReverseByWord().ToBoolArray() : oResult.Content.ToBoolArray());
				value.CopyTo(array2, num);
				byte[] value2 = (reverseByWord ? array2.ToByteArray().ReverseByWord() : array2.ToByteArray());
				return device.Write(array[0], value2);
			}
			if (insertPoint && address.Length > 1)
			{
				string address2 = AddressAddPoint(address);
				return WriteBool(device, address2, value, addressLength, reverseByWord, insertPoint);
			}
			return device.Write(address, value);
		}

		private static string AddressAddPoint(string address)
		{
			return address.Substring(0, address.Length - 1) + "." + address[address.Length - 1];
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.SnetHelper.ReadBool(Snet.Driver.Core.IReadWriteNet,System.String,System.UInt16,System.Int32,System.Boolean,System.String)" />
		public static async Task<OResult<bool[]>> ReadBoolAsync(IReadWriteNet device, string address, ushort length, int addressLength = 16, bool reverseByWord = false, string split = ".")
		{
			if (address.IndexOf(split) > 0)
			{
				string[] array = SplitsAddressDot(address, split);
				int bitIndex;
				try
				{
					bitIndex = CalculateBitStartIndex(array[1]);
				}
				catch (Exception ex)
				{
					return new OResult<bool[]>("Bit Index format wrong, " + ex.Message);
				}
				OResult<byte[]> oResult = await device.ReadAsync(length: (ushort)((length + bitIndex + addressLength - 1) / addressLength), address: array[0]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				if (reverseByWord)
				{
					return OResult.CreateSuccessResult(oResult.Content.ReverseByWord().ToBoolArray().SelectMiddle(bitIndex, length));
				}
				return OResult.CreateSuccessResult(oResult.Content.ToBoolArray().SelectMiddle(bitIndex, length));
			}
			return await device.ReadBoolAsync(address, length);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.SnetHelper.WriteBool(Snet.Driver.Core.IReadWriteNet,System.String,System.Boolean[],System.Int32,System.Boolean,System.Boolean)" />
		public static async Task<OResult> WriteBoolAsync(IReadWriteNet device, string address, bool[] value, int addressLength = 16, bool reverseByWord = false, bool insertPoint = false)
		{
			if (address.IndexOf('.') > 0)
			{
				string[] addressSplits = SplitsAddressDot(address);
				int bitIndex;
				try
				{
					bitIndex = CalculateBitStartIndex(addressSplits[1]);
				}
				catch (Exception ex)
				{
					return new OResult<bool[]>("Bit Index format wrong, " + ex.Message);
				}
				OResult<byte[]> oResult = await device.ReadAsync(length: (ushort)((value.Length + bitIndex + addressLength - 1) / addressLength), address: addressSplits[0]);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<bool[]>(oResult);
				}
				bool[] array = (reverseByWord ? oResult.Content.ReverseByWord().ToBoolArray() : oResult.Content.ToBoolArray());
				value.CopyTo(array, bitIndex);
				return await device.WriteAsync(value: reverseByWord ? array.ToByteArray().ReverseByWord() : array.ToByteArray(), address: addressSplits[0]);
			}
			if (insertPoint && address.Length > 1)
			{
				string address2 = AddressAddPoint(address);
				return await WriteBoolAsync(device, address2, value, addressLength, reverseByWord, insertPoint);
			}
			return device.Write(address, value);
		}

		/// <summary>
		/// 将串口的一些参数，变成一个统一的格式化的字符串，例如 COM3-9600-8-N-1
		/// </summary>
		/// <param name="portName">端口号</param>
		/// <param name="baudRate">波特率</param>
		/// <param name="dataBits">数据位</param>
		/// <param name="parity">奇偶校验位</param>
		/// <param name="stopBits">停止位</param>
		/// <returns>格式化的字符串</returns>
		public static string ToFormatString(string portName, int baudRate, int dataBits, Parity parity, StopBits stopBits)
		{
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0068: Expected I4, but got Unknown
			//IL_00ba: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cd: Expected I4, but got Unknown
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(portName);
			stringBuilder.Append("-");
			stringBuilder.Append(baudRate.ToString());
			stringBuilder.Append("-");
			stringBuilder.Append(dataBits.ToString());
			stringBuilder.Append("-");
			switch ((int)parity)
			{
			case 0:
				stringBuilder.Append("N");
				break;
			case 2:
				stringBuilder.Append("E");
				break;
			case 1:
				stringBuilder.Append("O");
				break;
			case 4:
				stringBuilder.Append("S");
				break;
			default:
				stringBuilder.Append("M");
				break;
			}
			stringBuilder.Append("-");
			switch ((int)stopBits)
			{
			case 0:
				stringBuilder.Append("0");
				break;
			case 1:
				stringBuilder.Append("1");
				break;
			case 2:
				stringBuilder.Append("2");
				break;
			default:
				stringBuilder.Append("1.5");
				break;
			}
			return stringBuilder.ToString();
		}
	}
	/// <summary>
	/// 一个数据范围管理的的类型对象，可以方便的管理一个数据值的最大值，最小值，平均值信息。<br />
	/// A type object managed by a data range can conveniently manage the maximum, minimum, and average information of a data value.
	/// </summary>
	public struct ValueLimit
	{
		/// <summary>
		/// 当前的数据的最大值<br />
		/// The maximum value of the current data
		/// </summary>
		public double MaxValue { get; set; }

		/// <summary>
		/// 当前的数据的最小值<br />
		/// The minimum value of the current data
		/// </summary>
		public double MinValue { get; set; }

		/// <summary>
		/// 当前的数据的平均值<br />
		/// Average value of current data
		/// </summary>
		public double Average { get; set; }

		/// <summary>
		/// 当前的数据的起始值<br />
		/// The starting value of the current data
		/// </summary>
		public double StartValue { get; set; }

		/// <summary>
		/// 当前的数据的当前值，也是最后一次更新的数据值<br />
		/// The current value of the current data is also the last updated data value
		/// </summary>
		public double Current { get; set; }

		/// <summary>
		/// 当前的数据的更新总个数<br />
		/// The total number of current data updates
		/// </summary>
		public int Count { get; set; }

		/// <summary>
		/// 重新设置当前的最新值，然后计算新的最大值，最小值，平均值等信息<br />
		/// Reset the current latest value, and then calculate the new maximum, minimum, average and other information
		/// </summary>
		/// <param name="value">新的数据值信息</param>
		/// <returns>新的值对象</returns>
		public ValueLimit SetNewValue(double value)
		{
			if (!double.IsNaN(value))
			{
				if (Count == 0)
				{
					MaxValue = value;
					MinValue = value;
					Count = 1;
					Current = value;
					Average = value;
					StartValue = value;
				}
				else
				{
					if (value < MinValue)
					{
						MinValue = value;
					}
					if (value > MaxValue)
					{
						MaxValue = value;
					}
					Current = value;
					Average = ((double)Count * Average + value) / (double)(Count + 1);
					Count++;
				}
			}
			return this;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"Avg[{Current}]";
		}

		/// <summary>
		/// 判断是否相等
		/// </summary>
		/// <param name="value1">第一个数据值</param>
		/// <param name="value2">第二个数据值</param>
		/// <returns>是否相同</returns>
		public static bool operator ==(ValueLimit value1, ValueLimit value2)
		{
			if (value1.Count != value2.Count)
			{
				return false;
			}
			if (value1.MaxValue != value2.MaxValue)
			{
				return false;
			}
			if (value1.MinValue != value2.MinValue)
			{
				return false;
			}
			if (value1.Current != value2.Current)
			{
				return false;
			}
			if (value1.Average != value2.Average)
			{
				return false;
			}
			if (value1.StartValue != value2.StartValue)
			{
				return false;
			}
			return true;
		}

		/// <summary>
		/// 判断是否相等
		/// </summary>
		/// <param name="value1">第一个数据值</param>
		/// <param name="value2">第二个数据值</param>
		/// <returns>是否相同</returns>
		public static bool operator !=(ValueLimit value1, ValueLimit value2)
		{
			return !(value1 == value2);
		}

		/// <inheritdoc />
		public override bool Equals(object obj)
		{
			if (obj is ValueLimit valueLimit)
			{
				return this == valueLimit;
			}
			return false;
		}

		/// <inheritdoc />
		public override int GetHashCode()
		{
			return base.GetHashCode();
		}
	}
}
