		public static string StaticString(nint ptr)
		{
			return Marshal.PtrToStringAnsi(ptr);
		}

		public static string PtrToStringAnsi(nint ptr, bool hasOwnership)
		{
			int num = 0;
			int num2 = 0;
			while (num2 < 1024 && Marshal.ReadByte(ptr, num2) != 0)
			{
				num2++;
				num++;
			}
			if (num == 1024)
			{
				return "Invalid string";
			}
			byte[] array = new byte[num];
			Marshal.Copy(ptr, array, 0, num);
			if (hasOwnership)
			{
				OPENSSL_free(ptr);
			}
			return Encoding.ASCII.GetString(array, 0, num);
		}

		public static nint ExpectNonNull(nint ptr)
		{
			if (ptr == IntPtr.Zero)
			{
				throw new Exception();
			}
			return ptr;
		}

		public static int ExpectSuccess(int ret)
		{
			if (ret <= 0)
			{
				throw new Exception();
			}
			return ret;
		}
