	/// <summary>
	/// RSA加密解密算法的辅助方法，可以用PEM格式的密钥创建公钥，或是私钥对象，然后用来加解密操作。
	/// </summary>
	public class RSAHelper
	{
		private const string privateKeyHead = "-----BEGIN RSA PRIVATE KEY-----";

		private const string privateKeyEnd = "-----END RSA PRIVATE KEY-----";

		private const string publicKeyHead = "-----BEGIN PUBLIC KEY-----";

		private const string publicKeyEnd = "-----END PUBLIC KEY-----";

		private static readonly byte[] SeqOID = new byte[15]
		{
			48, 13, 6, 9, 42, 134, 72, 134, 247, 13,
			1, 1, 1, 5, 0
		};

		/// <summary>
		/// 使用 PEM 格式基于base64编码的私钥来创建一个 RSA 算法加密解密的对象，可以直接用于加密解密操作<br />
		/// Use the PEM format based on the base64-encoded private key to create an RSA algorithm encryption and decryption object, 
		/// which can be directly used for encryption and decryption operations
		/// </summary>
		/// <param name="privateKeyString">私钥</param>
		/// <returns>RSA 算法的加密解密对象</returns>
		public static RSACryptoServiceProvider CreateRsaProviderFromPrivateKey(string privateKeyString)
		{
			privateKeyString = privateKeyString.Trim();
			if (privateKeyString.StartsWith("-----BEGIN RSA PRIVATE KEY-----"))
			{
				privateKeyString = privateKeyString.Replace("-----BEGIN RSA PRIVATE KEY-----", string.Empty);
			}
			if (privateKeyString.EndsWith("-----END RSA PRIVATE KEY-----"))
			{
				privateKeyString = privateKeyString.Replace("-----END RSA PRIVATE KEY-----", string.Empty);
			}
			return CreateRsaProviderFromPrivateKey(Convert.FromBase64String(privateKeyString));
		}

		/// <summary>
		/// 使用原始的私钥数据（PEM格式）来创建一个 RSA 算法加密解密的对象，可以直接用于加密解密操作<br />
		/// Use the original private key data (PEM format) to create an RSA algorithm encryption and decryption object, 
		/// which can be directly used for encryption and decryption operations
		/// </summary>
		/// <param name="privateKey">原始的私钥数据</param>
		/// <returns>RSA 算法的加密解密对象</returns>
		public static RSACryptoServiceProvider CreateRsaProviderFromPrivateKey(byte[] privateKey)
		{
			RSACryptoServiceProvider rSACryptoServiceProvider = new RSACryptoServiceProvider();
			RSAParameters parameters = default(RSAParameters);
			using (BinaryReader binaryReader = new BinaryReader(new MemoryStream(privateKey)))
			{
				switch (binaryReader.ReadUInt16())
				{
				case 33072:
					binaryReader.ReadByte();
					break;
				case 33328:
					binaryReader.ReadInt16();
					break;
				default:
					throw new Exception("Unexpected value read binr.ReadUInt16()");
				}
				if (binaryReader.ReadUInt16() != 258)
				{
					throw new Exception("Unexpected version");
				}
				if (binaryReader.ReadByte() != 0)
				{
					throw new Exception("Unexpected value read binr.ReadByte()");
				}
				parameters.Modulus = binaryReader.ReadBytes(GetIntegerSize(binaryReader));
				parameters.Exponent = binaryReader.ReadBytes(GetIntegerSize(binaryReader));
				parameters.D = binaryReader.ReadBytes(GetIntegerSize(binaryReader));
				parameters.P = binaryReader.ReadBytes(GetIntegerSize(binaryReader));
				parameters.Q = binaryReader.ReadBytes(GetIntegerSize(binaryReader));
				parameters.DP = binaryReader.ReadBytes(GetIntegerSize(binaryReader));
				parameters.DQ = binaryReader.ReadBytes(GetIntegerSize(binaryReader));
				parameters.InverseQ = binaryReader.ReadBytes(GetIntegerSize(binaryReader));
			}
			rSACryptoServiceProvider.ImportParameters(parameters);
			return rSACryptoServiceProvider;
		}

		private static int GetIntegerSize(BinaryReader binr)
		{
			byte b = 0;
			byte b2 = 0;
			byte b3 = 0;
			int num = 0;
			b = binr.ReadByte();
			if (b != 2)
			{
				return 0;
			}
			b = binr.ReadByte();
			switch (b)
			{
			case 129:
				num = binr.ReadByte();
				break;
			case 130:
				b3 = binr.ReadByte();
				b2 = binr.ReadByte();
				num = BitConverter.ToInt32(new byte[4] { b2, b3, 0, 0 }, 0);
				break;
			default:
				num = b;
				break;
			}
			while (binr.ReadByte() == 0)
			{
				num--;
			}
			binr.BaseStream.Seek(-1L, SeekOrigin.Current);
			return num;
		}

		private static byte[] PackKeyHead(byte[] content)
		{
			if (content.Length < 256)
			{
				byte[] array = SoftBasic.SpliceArray<byte>("30 81 00".ToHexBytes(), content);
				array[2] = BitConverter.GetBytes(array.Length - 3)[0];
				return array;
			}
			byte[] array2 = SoftBasic.SpliceArray<byte>("30 82 00 00".ToHexBytes(), content);
			array2[2] = BitConverter.GetBytes(array2.Length - 4)[1];
			array2[3] = BitConverter.GetBytes(array2.Length - 4)[0];
			return array2;
		}

		/// <summary>
		/// 从RSA的算法对象里，获取到PEM格式的原始私钥数据，如果需要存储，或是显示，只需要 Convert.ToBase64String 方法<br />
		/// Obtain the original private key data in PEM format from the RSA algorithm object. If you need to store or display it, 
		/// you only need the Convert.ToBase64String method
		/// </summary>
		/// <param name="rsa">RSA 算法的加密解密对象</param>
		/// <returns>原始的私钥数据</returns>
		public static byte[] GetPrivateKeyFromRSA(RSACryptoServiceProvider rsa)
		{
			RSAParameters rSAParameters = rsa.ExportParameters(includePrivateParameters: true);
			byte[] modulus = rSAParameters.Modulus;
			byte[] exponent = rSAParameters.Exponent;
			byte[] d = rSAParameters.D;
			byte[] p = rSAParameters.P;
			byte[] q = rSAParameters.Q;
			byte[] dP = rSAParameters.DP;
			byte[] dQ = rSAParameters.DQ;
			byte[] inverseQ = rSAParameters.InverseQ;
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.Write(new byte[3] { 2, 1, 0 }, 0, 3);
			WriteByteStream(memoryStream, modulus);
			WriteByteStream(memoryStream, exponent);
			WriteByteStream(memoryStream, d);
			WriteByteStream(memoryStream, p);
			WriteByteStream(memoryStream, q);
			WriteByteStream(memoryStream, dP);
			WriteByteStream(memoryStream, dQ);
			WriteByteStream(memoryStream, inverseQ);
			return PackKeyHead(memoryStream.ToArray());
		}

		private static void WriteByteStream(MemoryStream ms, byte[] data)
		{
			bool num = data[0] > 127;
			int num2 = (num ? (data.Length + 1) : data.Length);
			ms.WriteByte(2);
			if (num2 < 128)
			{
				ms.WriteByte((byte)num2);
			}
			else if (num2 < 256)
			{
				ms.WriteByte(129);
				ms.WriteByte((byte)num2);
			}
			else
			{
				ms.WriteByte(130);
				ms.WriteByte(BitConverter.GetBytes(num2)[1]);
				ms.WriteByte(BitConverter.GetBytes(num2)[0]);
			}
			if (num)
			{
				ms.WriteByte(0);
			}
			ms.Write(data, 0, data.Length);
		}

		/// <summary>
		/// 从RSA的算法对象里，获取到PEM格式的原始公钥数据，如果需要存储，或是显示，只需要 Convert.ToBase64String 方法<br />
		/// Obtain the original public key data in PEM format from the RSA algorithm object. If you need to store or display it, 
		/// you only need the Convert.ToBase64String method
		/// </summary>
		/// <param name="rsa">RSA 算法的加密解密对象</param>
		/// <returns>原始的公钥数据</returns>
		public static byte[] GetPublicKeyFromRSA(RSACryptoServiceProvider rsa)
		{
			RSAParameters rSAParameters = rsa.ExportParameters(includePrivateParameters: false);
			byte[] modulus = rSAParameters.Modulus;
			byte[] exponent = rSAParameters.Exponent;
			MemoryStream memoryStream = new MemoryStream();
			WriteByteStream(memoryStream, modulus);
			WriteByteStream(memoryStream, exponent);
			byte[] array = PackKeyHead(SoftBasic.SpliceArray<byte>(new byte[1], PackKeyHead(memoryStream.ToArray())));
			array[0] = 3;
			return PackKeyHead(SoftBasic.SpliceArray<byte>(SeqOID, array));
		}

		/// <summary>
		/// PEM 格式基于base64编码的公钥来创建一个 RSA 算法加密解密的对象，可以直接用于加密或是验证签名操作<br />
		/// Use the original public key data (PEM format) to create an RSA algorithm encryption and decryption object, 
		/// which can be directly used for encryption or signature verification
		/// </summary>
		/// <param name="publicKeyString">公钥</param>
		/// <returns>RSA 算法的加密解密对象</returns>
		public static RSACryptoServiceProvider CreateRsaProviderFromPublicKey(string publicKeyString)
		{
			publicKeyString = publicKeyString.Trim();
			if (publicKeyString.StartsWith("-----BEGIN PUBLIC KEY-----"))
			{
				publicKeyString = publicKeyString.Replace("-----BEGIN PUBLIC KEY-----", string.Empty);
			}
			if (publicKeyString.EndsWith("-----END PUBLIC KEY-----"))
			{
				publicKeyString = publicKeyString.Replace("-----END PUBLIC KEY-----", string.Empty);
			}
			return CreateRsaProviderFromPublicKey(Convert.FromBase64String(publicKeyString));
		}

		/// <summary>
		/// 对原始字节的数据进行加密，不限制长度，因为RSA本身限制了117字节，所以此处进行数据切割加密。<br />
		/// Encrypt the original byte data without limiting the length, because RSA itself limits 117 bytes, so the data is cut and encrypted here.
		/// </summary>
		/// <param name="provider">RSA公钥对象</param>
		/// <param name="data">等待加密的原始数据</param>
		/// <returns>加密之后的结果信息</returns>
		public static byte[] EncryptLargeDataByRSA(RSACryptoServiceProvider provider, byte[] data)
		{
			MemoryStream memoryStream = new MemoryStream();
			List<byte[]> list = SoftBasic.ArraySplitByLength(data, 110);
			for (int i = 0; i < list.Count; i++)
			{
				byte[] array = provider.Encrypt(list[i], fOAEP: false);
				memoryStream.Write(array, 0, array.Length);
			}
			return memoryStream.ToArray();
		}

		/// <summary>
		/// 对超过117字节限制的加密数据进行解密，解密出原始的字节数据，因为RSA本身限制了117字节，所以此处进行数据切割解密。<br />
		/// Decrypt the encrypted data that exceeds the 117-byte limit and decrypt the original byte data, because RSA itself limits 117 bytes, so the data is cut and decrypted here.
		/// </summary>
		/// <param name="provider">RSA私钥对象</param>
		/// <param name="data">等待解密的数据</param>
		/// <returns>解密之后的结果数据</returns>
		public static byte[] DecryptLargeDataByRSA(RSACryptoServiceProvider provider, byte[] data)
		{
			MemoryStream memoryStream = new MemoryStream();
			List<byte[]> list = SoftBasic.ArraySplitByLength(data, 128);
			for (int i = 0; i < list.Count; i++)
			{
				byte[] array = provider.Decrypt(list[i], fOAEP: false);
				memoryStream.Write(array, 0, array.Length);
			}
			return memoryStream.ToArray();
		}

		/// <summary>
		/// 使用原始的公钥数据（PEM格式）来创建一个 RSA 算法加密解密的对象，可以直接用于加密或是验证签名操作<br />
		/// Use the original public key data (PEM format) to create an RSA algorithm encryption and decryption object, 
		/// which can be directly used for encryption or signature verification
		/// </summary>
		/// <param name="publicKey">公钥</param>
		/// <returns>RSA 算法的加密解密对象</returns>
		public static RSACryptoServiceProvider CreateRsaProviderFromPublicKey(byte[] publicKey)
		{
			_ = new byte[15];
			_ = publicKey.Length;
			using MemoryStream input = new MemoryStream(publicKey);
			using BinaryReader binaryReader = new BinaryReader(input);
			ushort num = 0;
			switch (binaryReader.ReadUInt16())
			{
			case 33072:
				binaryReader.ReadByte();
				break;
			case 33328:
				binaryReader.ReadInt16();
				break;
			default:
				return null;
			}
			if (!CompareBytearrays(binaryReader.ReadBytes(15), SeqOID))
			{
				return null;
			}
			switch (binaryReader.ReadUInt16())
			{
			case 33027:
				binaryReader.ReadByte();
				break;
			case 33283:
				binaryReader.ReadInt16();
				break;
			default:
				return null;
			}
			if (binaryReader.ReadByte() != 0)
			{
				return null;
			}
			switch (binaryReader.ReadUInt16())
			{
			case 33072:
				binaryReader.ReadByte();
				break;
			case 33328:
				binaryReader.ReadInt16();
				break;
			default:
				return null;
			}
			num = binaryReader.ReadUInt16();
			byte b = 0;
			byte b2 = 0;
			switch (num)
			{
			case 33026:
				b = binaryReader.ReadByte();
				break;
			case 33282:
				b2 = binaryReader.ReadByte();
				b = binaryReader.ReadByte();
				break;
			default:
				return null;
			}
			int num2 = BitConverter.ToInt32(new byte[4] { b, b2, 0, 0 }, 0);
			if (binaryReader.PeekChar() == 0)
			{
				binaryReader.ReadByte();
				num2--;
			}
			byte[] modulus = binaryReader.ReadBytes(num2);
			if (binaryReader.ReadByte() != 2)
			{
				return null;
			}
			int count = binaryReader.ReadByte();
			byte[] exponent = binaryReader.ReadBytes(count);
			RSACryptoServiceProvider rSACryptoServiceProvider = new RSACryptoServiceProvider();
			rSACryptoServiceProvider.ImportParameters(new RSAParameters
			{
				Modulus = modulus,
				Exponent = exponent
			});
			return rSACryptoServiceProvider;
		}

		private static bool CompareBytearrays(byte[] a, byte[] b)
		{
			if (a.Length != b.Length)
			{
				return false;
			}
			int num = 0;
			for (int i = 0; i < a.Length; i++)
			{
				if (a[i] != b[num])
				{
					return false;
				}
				num++;
			}
			return true;
		}
	}
}
namespace Snet.Driver.Core.Pipe
{
	/// <summary>
	/// 用于通信的管道信息，包含基本的通信实现，当前类是抽象类，需要继承实现具体的收发报文才可以使用。<br />
	/// Channel information for communication, including the basic communication implementation, the current class is an abstract class, need to inherit the implementation of specific messages can be used.
	/// </summary>
	public abstract class CommunicationPipe : IDisposable
	{
		private bool disposedValue;

		private int receiveTimeOut = 5000;

		private int sleepTime;

		private bool useServerActivePush;

		private int connectErrorCount;

		private ICommunicationLock communicationLock;

		/// <summary>
		/// 当启用设备方主动发送数据时，用于同步访问方法的信号同步功能
		/// </summary>
		protected AutoResetEvent autoResetEvent;

		/// <summary>
		/// 当启用设备方主动发送数据时，用于应答服务机制的数据缓存
		/// </summary>
		protected byte[] bufferQA;

		/// <summary>
		/// 是否是长连接的状态<br />
		/// Whether it is a long connection state
		/// </summary>
		protected bool isPersistentConn;

		/// <summary>
		/// 获取或设置接收服务器反馈的时间，如果为负数，则不接收反馈 <br />
		/// Gets or sets the time to receive server feedback, and if it is a negative number, does not receive feedback
		/// </summary>
		/// <example>
		/// 设置1秒的接收超时的示例
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="ReceiveTimeOutExample" title="ReceiveTimeOut示例" />
		/// </example>
		/// <remarks>
		/// 超时的通常原因是服务器端没有配置好，导致访问失败，为了不卡死软件，所以有了这个超时的属性。
		/// </remarks>
		public int ReceiveTimeOut
		{
			get
			{
				return receiveTimeOut;
			}
			set
			{
				receiveTimeOut = value;
			}
		}

		/// <summary>
		/// 获取或设置在正式接收对方返回数据前的时候，需要休息的时间，当设置为0的时候，不需要休息。<br />
		/// Get or set the time required to rest before officially receiving the data from the other party. When it is set to 0, no rest is required.
		/// </summary>
		public int SleepTime
		{
			get
			{
				return sleepTime;
			}
			set
			{
				sleepTime = value;
			}
		}

		/// <summary>
		/// 获取或设置当前的管道是否激活从设备主动推送的功能，设置为 true 时支持主动从设备方接收数据信息<br />
		/// Gets or sets whether the current pipeline activates the function of actively pushing data from the device. If this is set to true, it supports actively receiving data information from the device
		/// </summary>
		public bool UseServerActivePush
		{
			get
			{
				return useServerActivePush;
			}
			set
			{
				if (value)
				{
					if (autoResetEvent == null)
					{
						autoResetEvent = new AutoResetEvent(initialState: false);
					}
					isPersistentConn = true;
				}
				useServerActivePush = value;
			}
		}

		/// <summary>
		/// 获取或设置当前管道的线程锁对象，默认是简单的一个互斥锁<br />
		/// Gets or sets the thread lock object of the current pipeline, which defaults to a simple mutex
		/// </summary>
		public ICommunicationLock CommunicationLock
		{
			get
			{
				return communicationLock;
			}
			set
			{
				communicationLock = value;
			}
		}

		/// <summary>
		/// 获取或设置当前的管道是否是长连接，仅对于串口及TCP是有效的，默认都是长连接<br />
		/// Gets or sets whether the current pipe is a long connection. This is valid only for serial ports and TCP. The default is a long connection
		/// </summary>
		public bool IsPersistentConnection { get; set; } = true;

		/// <summary>
		/// 用来决定当前接收的消息是否是问答服务的消息，可由外界设置委托来决定<br />
		/// It is used to determine whether the currently received message is a message of the question answering service, which can be determined by the external setting delegate
		/// </summary>
		public Func<CommunicationPipe, OResult<byte[]>, bool> DecideWhetherQAMessageFunction { get; set; }

		/// <summary>
		/// 实例化一个默认的构造对象<br />
		/// Instantiate a default constructor object
		/// </summary>
		public CommunicationPipe()
		{
			communicationLock = new CommunicationLockSimple();
		}

		/// <summary>
		/// 根据给定的消息，发送的数据，接收到数据来判断是否接收完成报文<br />
		/// According to the given message, sent data, received data to determine whether to receive the completed message
		/// </summary>
		/// <param name="netMessage">消息类对象</param>
		/// <param name="sendValue">发送的数据内容</param>
		/// <param name="ms">接收数据的流</param>
		/// <returns>是否接收完成数据</returns>
		protected bool CheckMessageComplete(INetMessage netMessage, byte[] sendValue, ref MemoryStream ms)
		{
			if (netMessage == null)
			{
				return true;
			}
			if (netMessage is SpecifiedCharacterMessage specifiedCharacterMessage)
			{
				byte[] array = ms.ToArray();
				byte[] bytes = BitConverter.GetBytes(specifiedCharacterMessage.ProtocolHeadBytesLength);
				switch (bytes[3] & 0xF)
				{
				case 1:
					if (array.Length > specifiedCharacterMessage.EndLength && array[array.Length - 1 - specifiedCharacterMessage.EndLength] == bytes[1])
					{
						return true;
					}
					break;
				case 2:
					if (array.Length > specifiedCharacterMessage.EndLength + 1 && array[array.Length - 2 - specifiedCharacterMessage.EndLength] == bytes[1] && array[array.Length - 1 - specifiedCharacterMessage.EndLength] == bytes[0])
					{
						return true;
					}
					break;
				}
			}
			else if (netMessage.ProtocolHeadBytesLength > 0)
			{
				byte[] array2 = ms.ToArray();
				if (array2.Length >= netMessage.ProtocolHeadBytesLength)
				{
					int num = netMessage.PependedUselesByteLength(array2);
					if (num > 0)
					{
						array2 = array2.RemoveBegin(num);
						ms = new MemoryStream();
						ms.Write(array2);
						if (array2.Length < netMessage.ProtocolHeadBytesLength)
						{
							return false;
						}
					}
					netMessage.HeadBytes = array2.SelectBegin(netMessage.ProtocolHeadBytesLength);
					netMessage.SendBytes = sendValue;
					int contentLengthByHeadBytes = netMessage.GetContentLengthByHeadBytes();
					if (array2.Length >= netMessage.ProtocolHeadBytesLength + contentLengthByHeadBytes)
					{
						if (netMessage.ProtocolHeadBytesLength > netMessage.HeadBytes.Length)
						{
							ms = new MemoryStream();
							ms.Write(array2.RemoveBegin(netMessage.ProtocolHeadBytesLength - netMessage.HeadBytes.Length));
						}
						return true;
					}
				}
			}
			else if (netMessage.CheckReceiveDataComplete(sendValue, ms))
			{
				return true;
			}
			return false;
		}

		/// <summary>
		/// 重置当前的连续错误计数为0，并且返回重置前时候的值<br />
		/// Resets the current consecutive error count to 0 and returns the value before the reset
		/// </summary>
		/// <returns>重置前的值</returns>
		public int ResetConnectErrorCount()
		{
			return Interlocked.Exchange(ref connectErrorCount, 0);
		}

		/// <summary>
		/// 自增当前的连续错误计数，并且获取自增后的值信息，最大到20亿为止，无法继续增加了。<br />
		/// Increment the current continuous error count, and obtain the value information after increment, up to 2 billion, can not continue to increase.
		/// </summary>
		/// <returns>自增后的值信息</returns>
		protected int IncrConnectErrorCount()
		{
			int num = Interlocked.Increment(ref connectErrorCount);
			if (num > 2000000000)
			{
				Interlocked.Exchange(ref connectErrorCount, 1000000000);
			}
			return num;
		}

		/// <summary>
		/// 主动引发一个管道错误，从而让管道可以重新打开<br />
		/// Actively causes a pipe error so that the pipe can be reopened
		/// </summary>
		public void RaisePipeError()
		{
			Interlocked.CompareExchange(ref connectErrorCount, 1, 0);
		}

		/// <summary>
		/// 当前管道的缓存里是否有数据存在，有就返回 <c>True</c><br />
		/// If there is any data in the cache of the current pipeline, return <c>True</c>
		/// </summary>
		/// <returns>是否有缓存数据</returns>
		public virtual bool HasCacheData()
		{
			return false;
		}

		/// <summary>
		/// 当前的管道连接对象是否发生了错误，这里的错误通常是串口，或是网络错误<br />
		/// Whether there is an error in the current pipe connection object, where the error is usually a serial port, or a network error
		/// </summary>
		/// <returns>是否发生了通道的异常</returns>
		public virtual bool IsConnectError()
		{
			return connectErrorCount > 0;
		}

		/// <summary>
		/// 发送数据到当前的管道中去<br />
		/// Send data to the current pipe
		/// </summary>
		/// <param name="data">等待发送的数据</param>
		/// <returns>是否发送成功</returns>
		public OResult Send(byte[] data)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			return Send(data, 0, data.Length);
		}

		/// <summary>
		/// 将一个数据缓存中的指定的部分字段，发送到当前的管道中去<br />
		/// Sends the specified partial field from a data cache to the current pipeline
		/// </summary>
		/// <param name="data">等待发送的缓存数据</param>
		/// <param name="offset">起始偏移的地址</param>
		/// <param name="size">发送的字节长度信息</param>
		/// <returns>是否发送成功</returns>
		public virtual OResult Send(byte[] data, int offset, int size)
		{
			return new OResult<int>(StringResources.Language.NotSupportedFunction);
		}

		/// <summary>
		/// 从管道里，接收指定长度的报文数据信息，如果长度指定为-1，表示接收不超过2048字节的动态长度。另外可以指定超时时间，进度报告等<br />
		/// Receives the packet data of a specified length from the pipe. If the length is set to -1, 
		/// it indicates that the dynamic length of the packet is not more than 2048 bytes. You can also specify timeouts, progress reports, etc
		/// </summary>
		/// <param name="length">接收的长度信息</param>
		/// <param name="timeOut">指定的超时时间</param>
		/// <param name="reportProgress">进行进度报告的委托</param>
		/// <returns>是否接收成功的结果对象</returns>
		public virtual OResult<byte[]> Receive(int length, int timeOut, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			OResult<byte[]> oResult = NetSupport.CreateReceiveBuffer(length);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<int> oResult2 = Receive(oResult.Content, 0, length, timeOut, reportProgress);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult2);
			}
			return OResult.CreateSuccessResult((length > 0) ? oResult.Content : oResult.Content.SelectBegin(oResult2.Content));
		}

		/// <summary>
