		/// <summary>
		/// 设置当前的问答状态下的缓存数据<br />
		/// Set the cache data in the current Q&amp;A state
		/// </summary>
		/// <param name="buffer">设置的缓存</param>
		protected void SetBufferQA(byte[] buffer)
		{
			bufferQA = buffer;
			autoResetEvent.Set();
		}

		/// <summary>
		/// 包含了一个复杂的逻辑，从管道里根据当前的消息格式定义，接收报文信息，这个报文可能是来自服务器主动推送的。具体可以通过参数 <paramref name="useActivePush" /> 来特殊控制。<br />
		/// Contains a complex logic from the pipeline, according to the current message format definition, to receive message information, 
		/// this message may be actively pushed from the server. The parameter <paramref name="useActivePush" /> can be used for special control.
		/// </summary>
		/// <param name="netMessage">消息对象</param>
		/// <param name="sendValue">发送的数据，大多数的情况，都可以为空</param>
		/// <param name="useActivePush">是否使用服务方主动推送的数据，默认为 true</param>
		/// <param name="reportProgress">进行进度报告的委托</param>
		/// <param name="logMessage">用于消息记录的日志信息</param>
		/// <returns>是否</returns>
		public virtual OResult<byte[]> ReceiveMessage(INetMessage netMessage, byte[] sendValue, bool useActivePush = true, Action<long, long> reportProgress = null, Action<byte[]> logMessage = null)
		{
			if (useServerActivePush & useActivePush)
			{
				if (autoResetEvent.WaitOne(ReceiveTimeOut))
				{
					if (netMessage != null)
					{
						netMessage.HeadBytes = bufferQA;
					}
					logMessage?.Invoke(bufferQA);
					return OResult.CreateSuccessResult(bufferQA);
				}
				CloseCommunication();
				return new OResult<byte[]>(-IncrConnectErrorCount(), StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut);
			}
			if (netMessage == null || netMessage.ProtocolHeadBytesLength == -1)
			{
				if (netMessage != null && netMessage.SendBytes == null)
				{
					netMessage.SendBytes = sendValue;
				}
				DateTime now = DateTime.Now;
				MemoryStream memoryStream = new MemoryStream();
				do
				{
					OResult<byte[]> oResult = ReceiveByMessage(ReceiveTimeOut, null, reportProgress);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					if (oResult.Content != null && oResult.Content.Length != 0)
					{
						memoryStream.Write(oResult.Content);
						logMessage?.Invoke(oResult.Content);
					}
					if (netMessage == null)
					{
						return OResult.CreateSuccessResult(memoryStream.ToArray());
					}
					if (netMessage.CheckReceiveDataComplete(sendValue, memoryStream))
					{
						return OResult.CreateSuccessResult(memoryStream.ToArray());
					}
				}
				while (ReceiveTimeOut < 0 || !((DateTime.Now - now).TotalMilliseconds > (double)ReceiveTimeOut));
				return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut + " Received: " + memoryStream.ToArray().ToHexString(' '));
			}
			OResult<byte[]> oResult2 = ReceiveByMessage(ReceiveTimeOut, netMessage, reportProgress);
			if (oResult2.IsSuccess)
			{
				logMessage?.Invoke(oResult2.Content);
			}
			return oResult2;
		}

		/// <summary>
		/// 将数据发送到当前的管道里，并从管道接收相关的数据信息，可以指定消息类型，发送数据，是否有数据响应，休眠时间<br />
		/// To send data to the current pipeline and receive relevant data information from the pipeline, you can specify the message type, 
		/// the data sent, whether there is a data response, and the sleep time
		/// </summary>
		/// <param name="netMessage">当前接收的消息体信息</param>
		/// <param name="sendValue">等待发送的数据</param>
		/// <param name="hasResponseData">是否有数据返回</param>
		/// <param name="sleep">休眠时间</param>
		/// <param name="logMessage">用于消息记录的日志信息</param>
		/// <returns>读取的结果对象</returns>
		protected OResult<byte[]> ReadFromCoreServerHelper(INetMessage netMessage, byte[] sendValue, bool hasResponseData, int sleep, Action<byte[]> logMessage = null)
		{
			if (netMessage != null)
			{
				netMessage.SendBytes = sendValue;
			}
			OResult oResult = Send(sendValue);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (ReceiveTimeOut < 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (!hasResponseData)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (sleep > 0)
			{
				SnetHelper.ThreadSleep(sleep);
			}
			DateTime now = DateTime.Now;
			int num = 0;
			OResult<byte[]> oResult2;
			while (true)
			{
				oResult2 = ReceiveMessage(netMessage, sendValue, useActivePush: true, null, logMessage);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				if (netMessage == null)
				{
					break;
				}
				switch (netMessage.CheckMessageMatch(sendValue, oResult2.Content))
				{
				case 0:
					return new OResult<byte[]>("INetMessage.CheckMessageMatch failed" + Environment.NewLine + StringResources.Language.Send + ": " + SoftBasic.ByteToHexString(sendValue, ' ') + Environment.NewLine + StringResources.Language.Receive + ": " + SoftBasic.ByteToHexString(oResult2.Content, ' '));
				default:
					num++;
					if (ReceiveTimeOut < 0 || !((DateTime.Now - now).TotalMilliseconds > (double)ReceiveTimeOut))
					{
						continue;
					}
					return new OResult<byte[]>("Receive Message timeout: " + ReceiveTimeOut + " CheckMessageMatch times:" + num);
				case 1:
					break;
				}
				break;
			}
			if (netMessage != null && !netMessage.CheckHeadBytesLegal(null))
			{
				return new OResult<byte[]>(StringResources.Language.CommandHeadCodeCheckFailed + Environment.NewLine + StringResources.Language.Send + ": " + SoftBasic.ByteToHexString(sendValue, ' ') + Environment.NewLine + StringResources.Language.Receive + ": " + SoftBasic.ByteToHexString(oResult2.Content, ' '));
			}
			return OResult.CreateSuccessResult(oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.CommunicationPipe.ReadFromCoreServerHelper(Snet.Driver.Core.IMessage.INetMessage,System.Byte[],System.Boolean,System.Int32,System.Action{System.Byte[]})" />
		public virtual OResult<byte[]> ReadFromCoreServer(INetMessage netMessage, byte[] sendValue, bool hasResponseData, Action<byte[]> logMessage = null)
		{
			OResult<byte[]> oResult = ReadFromCoreServerHelper(netMessage, sendValue, hasResponseData, SleepTime, logMessage);
			if (!oResult.IsSuccess)
			{
				if (oResult.ErrorCode < 0)
				{
					_ = oResult.ErrorCode;
					_ = int.MinValue;
				}
				return oResult;
			}
			ResetConnectErrorCount();
			return oResult;
		}

		/// <summary>
		/// 接收一条完整的 <seealso cref="T:Snet.Driver.Core.IMessage.INetMessage" /> 数据内容，需要指定超时时间，单位为毫秒。 <br />
		/// Receive a complete <seealso cref="T:Snet.Driver.Core.IMessage.INetMessage" /> data content, Need to specify a timeout period in milliseconds
		/// </summary>
		/// <param name="timeOut">超时时间，单位：毫秒</param>
		/// <param name="netMessage">消息的格式定义</param>
		/// <param name="reportProgress">接收消息的时候的进度报告</param>
		/// <returns>带有是否成功的byte数组对象</returns>
		private OResult<byte[]> ReceiveByMessage(int timeOut, INetMessage netMessage, Action<long, long> reportProgress = null)
		{
			if (netMessage == null)
			{
				return Receive(-1, timeOut);
			}
			if (netMessage.ProtocolHeadBytesLength < 0)
			{
				byte[] bytes = BitConverter.GetBytes(netMessage.ProtocolHeadBytesLength);
				int num = bytes[3] & 0xF;
				OResult<byte[]> oResult = null;
				switch (num)
				{
				case 1:
					oResult = ReceiveCommandLineFromPipe(bytes[1], timeOut);
					break;
				case 2:
					oResult = ReceiveCommandLineFromPipe(bytes[1], bytes[0], timeOut);
					break;
				}
				if (oResult == null)
				{
					return new OResult<byte[]>("Receive by specified code failed, length check failed");
				}
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				netMessage.HeadBytes = oResult.Content;
				if (netMessage is SpecifiedCharacterMessage specifiedCharacterMessage)
				{
					if (specifiedCharacterMessage.EndLength == 0)
					{
						return oResult;
					}
					OResult<byte[]> oResult2 = Receive(specifiedCharacterMessage.EndLength, timeOut);
					if (!oResult2.IsSuccess)
					{
						return oResult2;
					}
					return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(oResult.Content, oResult2.Content));
				}
				return oResult;
			}
			OResult<byte[]> oResult3 = Receive(netMessage.ProtocolHeadBytesLength, timeOut);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			int num2 = netMessage.PependedUselesByteLength(oResult3.Content);
			int num3 = 0;
			while (num2 >= netMessage.ProtocolHeadBytesLength)
			{
				oResult3 = Receive(netMessage.ProtocolHeadBytesLength, timeOut);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				num2 = netMessage.PependedUselesByteLength(oResult3.Content);
				num3++;
				if (num3 > 10)
				{
					break;
				}
			}
			if (num2 > 0)
			{
				OResult<byte[]> oResult4 = Receive(num2, timeOut);
				if (!oResult4.IsSuccess)
				{
					return oResult4;
				}
				oResult3.Content = SoftBasic.SpliceArray<byte>(oResult3.Content.RemoveBegin(num2), oResult4.Content);
			}
			netMessage.HeadBytes = oResult3.Content;
			int contentLengthByHeadBytes = netMessage.GetContentLengthByHeadBytes();
			if (contentLengthByHeadBytes <= 0)
			{
				return OResult.CreateSuccessResult(oResult3.Content);
			}
			byte[] array = new byte[netMessage.HeadBytes.Length + contentLengthByHeadBytes];
			netMessage.HeadBytes.CopyTo(array, 0);
			OResult oResult5 = Receive(array, netMessage.HeadBytes.Length, contentLengthByHeadBytes, timeOut, reportProgress);
			if (!oResult5.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult5);
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 接收一行命令数据，需要自己指定这个结束符，默认超时时间为60秒，也即是60000，单位是毫秒<br />
		/// To receive a line of command data, you need to specify the terminator yourself. The default timeout is 60 seconds, which is 60,000, in milliseconds.
		/// </summary>
		/// <param name="endCode">结束符信息</param>
		/// <param name="timeout">超时时间，默认为60000，单位为毫秒，也就是60秒</param>
		/// <returns>带有结果对象的数据信息</returns>
		private OResult<byte[]> ReceiveCommandLineFromPipe(byte endCode, int timeout = 60000)
		{
			try
			{
				List<byte> list = new List<byte>(128);
				DateTime now = DateTime.Now;
				bool flag = false;
				while ((DateTime.Now - now).TotalMilliseconds < (double)timeout)
				{
					OResult<byte[]> oResult = Receive(1, timeout);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					list.AddRange(oResult.Content);
					if (oResult.Content[0] == endCode)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout + " " + timeout);
				}
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 接收一行命令数据，需要自己指定这个结束符，默认超时时间为60秒，也即是60000，单位是毫秒<br />
		/// To receive a line of command data, you need to specify the terminator yourself. The default timeout is 60 seconds, which is 60,000, in milliseconds.
		/// </summary>
		/// <param name="endCode1">结束符1信息</param>
		/// <param name="endCode2">结束符2信息</param>
		/// /// <param name="timeout">超时时间，默认无穷大，单位毫秒</param>
		/// <returns>带有结果对象的数据信息</returns>
		private OResult<byte[]> ReceiveCommandLineFromPipe(byte endCode1, byte endCode2, int timeout = 60000)
		{
			try
			{
				List<byte> list = new List<byte>(128);
				DateTime now = DateTime.Now;
				bool flag = false;
				while ((DateTime.Now - now).TotalMilliseconds < (double)timeout)
				{
					OResult<byte[]> oResult = Receive(1, timeout);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					list.AddRange(oResult.Content);
					if (oResult.Content[0] == endCode2 && list.Count > 1 && list[list.Count - 2] == endCode1)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout + " " + timeout);
				}
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
		}

