		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.CommunicationPipe.Receive(System.Int32,System.Int32,System.Action{System.Int64,System.Int64})" />
		public virtual async Task<OResult<byte[]>> ReceiveAsync(int length, int timeOut, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			OResult<byte[]> buffer = NetSupport.CreateReceiveBuffer(length);
			if (!buffer.IsSuccess)
			{
				return buffer;
			}
			OResult<int> oResult = await ReceiveAsync(buffer.Content, 0, length, timeOut, reportProgress).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult((length > 0) ? buffer.Content : buffer.Content.SelectBegin(oResult.Content));
		}

