		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.CommunicationPipe.ReceiveByMessage(System.Int32,Snet.Driver.Core.IMessage.INetMessage,System.Action{System.Int64,System.Int64})" />
		private async Task<OResult<byte[]>> ReceiveByMessageAsync(int timeOut, INetMessage netMessage, Action<long, long> reportProgress = null)
		{
			if (netMessage == null)
			{
				return await ReceiveAsync(-1, timeOut).ConfigureAwait(continueOnCapturedContext: false);
			}
			if (netMessage.ProtocolHeadBytesLength < 0)
			{
				byte[] bytes = BitConverter.GetBytes(netMessage.ProtocolHeadBytesLength);
				int num = bytes[3] & 0xF;
				OResult<byte[]> receive = null;
				switch (num)
				{
				case 1:
					receive = await ReceiveCommandLineFromPipeAsync(bytes[1], timeOut).ConfigureAwait(continueOnCapturedContext: false);
					break;
				case 2:
					receive = await ReceiveCommandLineFromPipeAsync(bytes[1], bytes[0], timeOut).ConfigureAwait(continueOnCapturedContext: false);
					break;
				}
				if (receive == null)
				{
					return new OResult<byte[]>("Receive by specified code failed, length check failed");
				}
				if (!receive.IsSuccess)
				{
					return receive;
				}
				netMessage.HeadBytes = receive.Content;
				if (netMessage is SpecifiedCharacterMessage specifiedCharacterMessage)
				{
					if (specifiedCharacterMessage.EndLength == 0)
					{
						return receive;
					}
					OResult<byte[]> oResult = await ReceiveAsync(specifiedCharacterMessage.EndLength, timeOut).ConfigureAwait(continueOnCapturedContext: false);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(receive.Content, oResult.Content));
				}
				return receive;
			}
			OResult<byte[]> headResult = await ReceiveAsync(netMessage.ProtocolHeadBytesLength, timeOut).ConfigureAwait(continueOnCapturedContext: false);
			if (!headResult.IsSuccess)
			{
				return headResult;
			}
			int start = netMessage.PependedUselesByteLength(headResult.Content);
			int cycleCount = 0;
			while (start >= netMessage.ProtocolHeadBytesLength)
			{
				headResult = await ReceiveAsync(netMessage.ProtocolHeadBytesLength, timeOut).ConfigureAwait(continueOnCapturedContext: false);
				if (!headResult.IsSuccess)
				{
					return headResult;
				}
				start = netMessage.PependedUselesByteLength(headResult.Content);
				cycleCount++;
				if (cycleCount > 10)
				{
					break;
				}
			}
			if (start > 0)
			{
				OResult<byte[]> oResult2 = await ReceiveAsync(start, timeOut).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				headResult.Content = SoftBasic.SpliceArray<byte>(headResult.Content.RemoveBegin(start), oResult2.Content);
			}
			netMessage.HeadBytes = headResult.Content;
			int contentLengthByHeadBytes = netMessage.GetContentLengthByHeadBytes();
			if (contentLengthByHeadBytes <= 0)
			{
				return OResult.CreateSuccessResult(headResult.Content);
			}
			byte[] result = new byte[netMessage.HeadBytes.Length + contentLengthByHeadBytes];
			netMessage.HeadBytes.CopyTo(result, 0);
			OResult oResult3 = await ReceiveAsync(result, netMessage.HeadBytes.Length, contentLengthByHeadBytes, timeOut, reportProgress).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult(result);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.CommunicationPipe.ReceiveMessage(Snet.Driver.Core.IMessage.INetMessage,System.Byte[],System.Boolean,System.Action{System.Int64,System.Int64},System.Action{System.Byte[]})" />
		public virtual async Task<OResult<byte[]>> ReceiveMessageAsync(INetMessage netMessage, byte[] sendValue, bool useActivePush = true, Action<long, long> reportProgress = null, Action<byte[]> logMessage = null)
		{
			if (useServerActivePush & useActivePush)
			{
				if (autoResetEvent.WaitOne(ReceiveTimeOut))
				{
					if (netMessage != null)
					{
						netMessage.HeadBytes = bufferQA;
					}
					logMessage?.Invoke(bufferQA);
					return OResult.CreateSuccessResult(bufferQA);
				}
				CloseCommunication();
				return new OResult<byte[]>(-IncrConnectErrorCount(), StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut);
			}
			if (netMessage == null || netMessage.ProtocolHeadBytesLength == -1)
			{
				if (netMessage != null && netMessage.SendBytes == null)
				{
					netMessage.SendBytes = sendValue;
				}
				DateTime startTime = DateTime.Now;
				MemoryStream ms = new MemoryStream();
				do
				{
					OResult<byte[]> oResult = await ReceiveByMessageAsync(ReceiveTimeOut, null, reportProgress).ConfigureAwait(continueOnCapturedContext: false);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					if (oResult.Content != null && oResult.Content.Length != 0)
					{
						ms.Write(oResult.Content);
						logMessage?.Invoke(oResult.Content);
					}
					if (netMessage == null)
					{
						return OResult.CreateSuccessResult(ms.ToArray());
					}
					if (netMessage.CheckReceiveDataComplete(sendValue, ms))
					{
						return OResult.CreateSuccessResult(ms.ToArray());
					}
				}
				while (ReceiveTimeOut < 0 || !((DateTime.Now - startTime).TotalMilliseconds > (double)ReceiveTimeOut));
				return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut + " Received: " + ms.ToArray().ToHexString(' '));
			}
			OResult<byte[]> oResult2 = await ReceiveByMessageAsync(ReceiveTimeOut, netMessage, reportProgress).ConfigureAwait(continueOnCapturedContext: false);
			if (oResult2.IsSuccess)
			{
				logMessage?.Invoke(oResult2.Content);
			}
			return oResult2;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.CommunicationPipe.ReadFromCoreServerHelper(Snet.Driver.Core.IMessage.INetMessage,System.Byte[],System.Boolean,System.Int32,System.Action{System.Byte[]})" />
		protected async Task<OResult<byte[]>> ReadFromCoreServerHelperAsync(INetMessage netMessage, byte[] sendValue, bool hasResponseData, int sleep, Action<byte[]> logMessage = null)
		{
			if (netMessage != null)
			{
				netMessage.SendBytes = sendValue;
			}
			OResult oResult = await SendAsync(sendValue).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (ReceiveTimeOut < 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (!hasResponseData)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (sleep > 0)
			{
				SnetHelper.ThreadSleep(sleep);
			}
			DateTime start = DateTime.Now;
			int times = 0;
			OResult<byte[]> oResult2;
			while (true)
			{
				oResult2 = await ReceiveMessageAsync(netMessage, sendValue, useActivePush: true, null, logMessage).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				bool num;
				if (netMessage != null)
				{
					switch (netMessage.CheckMessageMatch(sendValue, oResult2.Content))
					{
					case 0:
						return new OResult<byte[]>("INetMessage.CheckMessageMatch failed" + Environment.NewLine + StringResources.Language.Send + ": " + SoftBasic.ByteToHexString(sendValue, ' ') + Environment.NewLine + StringResources.Language.Receive + ": " + SoftBasic.ByteToHexString(oResult2.Content, ' '));
					default:
						times++;
						num = ReceiveTimeOut >= 0 && (DateTime.Now - start).TotalMilliseconds > (double)ReceiveTimeOut;
						goto IL_0289;
					case 1:
						break;
					}
				}
				break;
				IL_0289:
				if (num)
				{
					return new OResult<byte[]>("Receive Message timeout: " + ReceiveTimeOut + " CheckMessageMatch times:" + times);
				}
			}
			if (netMessage != null && !netMessage.CheckHeadBytesLegal(null))
			{
				return new OResult<byte[]>(StringResources.Language.CommandHeadCodeCheckFailed + Environment.NewLine + StringResources.Language.Send + ": " + SoftBasic.ByteToHexString(sendValue, ' ') + Environment.NewLine + StringResources.Language.Receive + ": " + SoftBasic.ByteToHexString(oResult2.Content, ' '));
			}
			return OResult.CreateSuccessResult(oResult2.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.CommunicationPipe.ReadFromCoreServer(Snet.Driver.Core.IMessage.INetMessage,System.Byte[],System.Boolean,System.Action{System.Byte[]})" />
		public virtual async Task<OResult<byte[]>> ReadFromCoreServerAsync(INetMessage netMessage, byte[] sendValue, bool hasResponseData, Action<byte[]> logMessage = null)
		{
			OResult<byte[]> oResult = await ReadFromCoreServerHelperAsync(netMessage, sendValue, hasResponseData, SleepTime, logMessage).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				if (oResult.ErrorCode < 0)
				{
					_ = oResult.ErrorCode;
					_ = int.MinValue;
				}
				return oResult;
			}
			ResetConnectErrorCount();
			return oResult;
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		protected virtual void Dispose(bool disposing)
		{
			if (disposing)
			{
				autoResetEvent?.Dispose();
				communicationLock?.Dispose();
			}
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			if (!disposedValue)
			{
				Dispose(disposing: true);
				GC.SuppressFinalize(this);
				disposedValue = true;
			}
		}
	}
