	/// <summary>
	/// 管道的基础类对象
	/// </summary>
	public class PipeBase : IDisposable
	{
		private SimpleHybirdLock hybirdLock;

		/// <inheritdoc cref="P:Snet.Driver.Core.SimpleHybirdLock.LockingTick" />
		public int LockingTick => hybirdLock.LockingTick;

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public PipeBase()
		{
			hybirdLock = new SimpleHybirdLock();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.SimpleHybirdLock.Enter" />
		public bool PipeLockEnter()
		{
			return hybirdLock.Enter();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.SimpleHybirdLock.Leave" />
		public bool PipeLockLeave()
		{
			return hybirdLock.Leave();
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public virtual void Dispose()
		{
			hybirdLock?.Dispose();
		}
	}
	/// <summary>
	/// 用于调试的远程管道信息<br />
	/// Remote pipeline information for debugging
	/// </summary>
	/// <remarks>
	/// 当前的管道主要用于调试，DEMO界面测试时可以直接连接远程的Debug服务器，方便调试，屏蔽了握手报文
	/// </remarks>
	public class PipeDebugRemote : PipeTcpNet
	{
		/// <summary>
		/// 获取或设置客户端的key信息，用于调试服务器区分不同的客户端，这样就支持多个客户端连接到同一个服务器，默认是0<br />
		/// Get or set the client's key information, used to distinguish different clients in the debug server, so that multiple clients can connect to the same server, the default is 0
		/// </summary>
		public ushort ClientKey { get; set; }

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSslNet.#ctor(System.Boolean)" />
		public PipeDebugRemote()
		{
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSslNet.#ctor(System.String,System.Int32,System.Boolean)" />
		public PipeDebugRemote(string ipAddress, int port)
		{
			base.IpAddress = ipAddress;
			base.Port = port;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSslNet.#ctor(System.Net.Sockets.Socket,System.Net.IPEndPoint,System.Boolean)" />
		public PipeDebugRemote(Socket socket, IPEndPoint iPEndPoint)
		{
			base.Socket = socket;
			base.IpAddress = iPEndPoint.Address.ToString();
			base.Port = iPEndPoint.Port;
		}

		private byte[] CreateHeaderBytes(byte[] sendValue)
		{
			byte[] array = new byte[6];
			BitConverter.GetBytes(ClientKey).CopyTo(array, 0);
			BitConverter.GetBytes(sendValue.Length).CopyTo(array, 2);
			return array;
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReadFromCoreServer(INetMessage netMessage, byte[] sendValue, bool hasResponseData, Action<byte[]> logMessage = null)
		{
			Send(CreateHeaderBytes(sendValue));
			return base.ReadFromCoreServer(netMessage, sendValue, hasResponseData, logMessage);
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReadFromCoreServerAsync(INetMessage netMessage, byte[] sendValue, bool hasResponseData, Action<byte[]> logMessage = null)
		{
			await SendAsync(CreateHeaderBytes(sendValue));
			return await base.ReadFromCoreServerAsync(netMessage, sendValue, hasResponseData, logMessage);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"PipeTcpNet[{base.IpAddress}:{base.Port}]";
		}
	}
	/// <summary>
	/// DTU(数据转换模块)的管道信息<br />
	/// Pipeline information of the DTU (Data Transfer unit) 
	/// </summary>
	public class PipeDtuNet : PipeTcpNet
	{
		/// <summary>
		/// 唯一的标识<br />
		/// Unique identification
		/// </summary>
		public string DTU { get; set; }

		/// <summary>
		/// 注册报文里的端口号信息，实际的使用过程中，你可以用来做一些额外的标记<br />
		/// You can use the port number information in the registration packet to make some other markings during actual use
		/// </summary>
		public ushort DTUPort { get; set; }

		/// <summary>
		/// 注册报文里的IP地址信息，实际的使用过程中，你也可以用来做一些额外的标记<br />
		/// You can also use the IP address information in the registration packet to make some other markings during actual use
		/// </summary>
		public int DTUIpAddress { get; set; }

		/// <summary>
		/// 密码信息<br />
		/// Password information
		/// </summary>
		public string Pwd { get; set; }

		/// <summary>
		/// 当前的DTU会话关联的服务器信息
		/// </summary>
		public NetworkAlienClient DtuServer { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public PipeDtuNet()
		{
		}

		/// <summary>
		/// 根据传入的TCP管道来初始化新的DTU管道实例<br />
		/// Initialize the new DTU pipe instance based on the incoming TCP pipe
		/// </summary>
		/// <param name="pipeTcpNet">TCP管道</param>
		public PipeDtuNet(PipeTcpNet pipeTcpNet)
		{
			base.Socket = pipeTcpNet.Socket;
			base.ReceiveTimeOut = pipeTcpNet.ReceiveTimeOut;
			base.IpAddress = pipeTcpNet.IpAddress;
			base.Port = pipeTcpNet.Port;
		}

		/// <inheritdoc />
		public override OResult<bool> OpenCommunication()
		{
			if (IsConnectError())
			{
				NetSupport.CloseSocket(base.Socket);
				return new OResult<bool>(StringResources.Language.ConnectionIsNotAvailable);
			}
			return OResult.CreateSuccessResult(value: false);
		}

		/// <inheritdoc />
		public override async Task<OResult<bool>> OpenCommunicationAsync()
		{
			if (IsConnectError())
			{
				return await Task.FromResult(new OResult<bool>(StringResources.Language.ConnectionIsNotAvailable)).ConfigureAwait(continueOnCapturedContext: false);
			}
			return await Task.FromResult(OResult.CreateSuccessResult(value: false)).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"PipeDtuNet[{base.IpAddress}:{base.Port}-{DTU}]";
		}
	}
	/// <summary>
	/// 基于MOXA公司提供的串口驱动实现的管道类，目前仅支持windows平台，需要当前目录下存在 PCOMM.DLL 组件<br />
	/// The pipe class based on the serial port driver provided by MOXA currently only supports the windows platform and requires the existence of the PCOMM.DLL component in the current directory
	/// </summary>
	public class PipeMoxa : CommunicationPipe, IDisposable
	{
		private int portNumber = -1;

		private bool rts;

		private bool dtr;

		private bool isOpen;

		private int moxaBaudRate = 12;

		private int moxaDataBits = 3;

		private int moxaStopBits;

		private int moxaParity;

		private string moxaFormate = string.Empty;

		/// <summary>
		/// 获取或设置一个值，该值指示在串行通信中是否启用请求发送 (RTS) 信号。<br />
		/// Gets or sets a value indicating whether the request sending (RTS) signal is enabled in serial communication.
		/// </summary>
		public bool RtsEnable
		{
			get
			{
				return rts;
			}
			set
			{
				rts = value;
				if (isOpen)
				{
					PCommHelper.sio_RTS(portNumber, value ? 1 : 0);
				}
			}
		}

		/// <summary>
		/// 获取或设置一个值，该值指示在串行通信中是否启用数据终端就绪 (Drt) 信号。<br />
		/// Gets or sets a value that indicates whether the Data Terminal Ready (DRT) signal is enabled in serial communication.
		/// </summary>
		public bool DtrEnable
		{
			get
			{
				return dtr;
			}
			set
			{
				dtr = value;
				if (isOpen)
				{
					PCommHelper.sio_DTR(portNumber, value ? 1 : 0);
				}
			}
		}

		/// <summary>
		/// 从串口中至少接收的字节长度信息，默认为1个字节
		/// </summary>
		public int AtLeastReceiveLength { get; set; } = 1;

		/// <summary>
		/// 获取或设置连续接收空的数据次数，在数据接收完成时有效，每个单位消耗的时间为<see cref="P:Snet.Driver.Core.Pipe.CommunicationPipe.SleepTime" />。<br />
		/// Obtain or set the number of consecutive times to receive empty data, which is valid when the data is received, and the time consumed by each unit is <see cref="P:Snet.Driver.Core.Pipe.CommunicationPipe.SleepTime" />
		/// </summary>
		public int ReceiveEmptyDataCount { get; set; } = 1;

		/// <summary>
		/// 是否在发送数据前清空缓冲数据，默认是false<br />
		/// Whether to empty the buffer before sending data, the default is false
		/// </summary>
		public bool IsClearCacheBeforeRead { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public PipeMoxa()
		{
			base.SleepTime = 5;
			ReceiveEmptyDataCount = 4;
		}

		/// <summary>
		/// 根据串口的名称来实例化一个对象<br />
		/// Instantiate a default object
		/// </summary>
		/// <remarks>
		/// portName 支持格式化的方式，例如输入 COM3-9600-8-N-1，COM5-19200-7-E-2，其中奇偶校验的字母可选，N:无校验，O：奇校验，E:偶校验，停止位可选 0, 1, 2, 1.5 四种选项
		/// </remarks>
		public PipeMoxa(string portName)
		{
			base.SleepTime = 5;
			ReceiveEmptyDataCount = 4;
			SerialPortInni(portName);
		}

		/// <summary>
		/// 初始化串口信息，9600波特率，8位数据位，1位停止位，无奇偶校验<br />
		/// Initial serial port information, 9600 baud rate, 8 data bits, 1 stop bit, no parity
		/// </summary>
		/// <remarks>
		/// portName 支持格式化的方式，例如输入 COM3-9600-8-N-1，COM5-19200-7-E-2，其中奇偶校验的字母可选，N:无校验，O：奇校验，E:偶校验，停止位可选 0, 1, 2, 1.5 四种选项
		/// </remarks>
		/// <param name="portName">端口号信息，例如"COM3"</param>
		public void SerialPortInni(string portName)
		{
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0143: Unknown result type (might be due to invalid IL or missing references)
			//IL_0145: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d5: Unknown result type (might be due to invalid IL or missing references)
			//IL_012a: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00da: Unknown result type (might be due to invalid IL or missing references)
			//IL_013b: Unknown result type (might be due to invalid IL or missing references)
			//IL_013d: Unknown result type (might be due to invalid IL or missing references)
			//IL_012f: Unknown result type (might be due to invalid IL or missing references)
			//IL_00df: Unknown result type (might be due to invalid IL or missing references)
			//IL_0134: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e4: Unknown result type (might be due to invalid IL or missing references)
			//IL_0139: Unknown result type (might be due to invalid IL or missing references)
			if (portName.Contains("-"))
			{
				string portName2 = "COM1";
				int baudRate = 9600;
				int dataBits = 8;
				Parity parity = (Parity)0;
				StopBits stopBits = (StopBits)1;
				string[] array = portName.Split(new char[2] { '-', ';' }, StringSplitOptions.RemoveEmptyEntries);
				if (array.Length != 0)
				{
					int num = 0;
					if (!Regex.IsMatch(array[0], "^[0-9]+$"))
					{
						portName2 = array[0];
						num = 1;
					}
					if (num < array.Length)
					{
						baudRate = Convert.ToInt32(array[num++]);
					}
					if (num < array.Length)
					{
						dataBits = Convert.ToInt32(array[num++]);
					}
					if (num < array.Length)
					{
						parity = (Parity)(array[num++].ToUpper() switch
						{
							"E" => 2, 
							"O" => 1, 
							"N" => 0, 
							_ => 4, 
						});
					}
					if (num < array.Length)
					{
						stopBits = (StopBits)(array[num++] switch
						{
							"0" => 0, 
							"2" => 2, 
							"1" => 1, 
							_ => 3, 
						});
					}
					SerialPortInni(portName2, baudRate, dataBits, stopBits, parity);
				}
			}
			else
			{
				SerialPortInni(portName, 9600, 8, (StopBits)1, (Parity)0);
			}
		}

		/// <summary>
		/// 初始化串口信息，波特率，数据位，停止位，奇偶校验需要全部自己来指定<br />
		/// Start serial port information, baud rate, data bit, stop bit, parity all need to be specified
		/// </summary>
		/// <param name="portName">端口号信息，例如"COM3"</param>
		/// <param name="baudRate">波特率</param>
		/// <param name="dataBits">数据位</param>
		/// <param name="stopBits">停止位</param>
		/// <param name="parity">奇偶校验</param>
		public void SerialPortInni(string portName, int baudRate, int dataBits, StopBits stopBits, Parity parity)
		{
			//IL_026c: Unknown result type (might be due to invalid IL or missing references)
			//IL_026f: Invalid comparison between Unknown and I4
			//IL_0271: Unknown result type (might be due to invalid IL or missing references)
			//IL_0274: Invalid comparison between Unknown and I4
			//IL_0288: Unknown result type (might be due to invalid IL or missing references)
			//IL_02a3: Expected I4, but got Unknown
			//IL_02d7: Unknown result type (might be due to invalid IL or missing references)
			//IL_02d9: Unknown result type (might be due to invalid IL or missing references)
			if (portName.StartsWith("COM", StringComparison.OrdinalIgnoreCase))
			{
				portNumber = Convert.ToInt32(portName.Substring(3));
			}
			else
			{
				portNumber = Convert.ToInt32(portName);
			}
			switch (baudRate)
			{
			case 50:
				moxaBaudRate = 0;
				break;
			case 75:
				moxaBaudRate = 1;
				break;
			case 110:
				moxaBaudRate = 2;
				break;
			case 134:
				moxaBaudRate = 3;
				break;
			case 150:
				moxaBaudRate = 4;
				break;
			case 300:
				moxaBaudRate = 5;
				break;
			case 600:
				moxaBaudRate = 6;
				break;
			case 1200:
				moxaBaudRate = 7;
				break;
			case 1800:
				moxaBaudRate = 8;
				break;
			case 2400:
				moxaBaudRate = 9;
				break;
			case 4800:
				moxaBaudRate = 10;
				break;
			case 7200:
				moxaBaudRate = 11;
				break;
			case 9600:
				moxaBaudRate = 12;
				break;
			case 19200:
				moxaBaudRate = 13;
				break;
			case 38400:
				moxaBaudRate = 14;
				break;
			case 57600:
				moxaBaudRate = 15;
				break;
			case 115200:
				moxaBaudRate = 16;
				break;
			case 230400:
				moxaBaudRate = 17;
				break;
			case 460800:
				moxaBaudRate = 18;
				break;
			case 921600:
				moxaBaudRate = 19;
				break;
			}
			switch (dataBits)
			{
			case 5:
				moxaDataBits = 0;
				break;
			case 6:
				moxaDataBits = 1;
				break;
			case 7:
				moxaDataBits = 2;
				break;
			case 8:
				moxaDataBits = 3;
				break;
			}
			if ((int)stopBits != 1)
			{
				if ((int)stopBits == 2)
				{
					moxaStopBits = 4;
				}
			}
			else
			{
				moxaStopBits = 0;
			}
			switch ((int)parity)
			{
			case 0:
				moxaParity = 0;
				break;
			case 2:
				moxaParity = 24;
				break;
			case 1:
				moxaParity = 8;
				break;
			case 3:
				moxaParity = 40;
				break;
			case 4:
				moxaParity = 48;
				break;
			}
			moxaFormate = SnetHelper.ToFormatString(portName, baudRate, dataBits, parity, stopBits);
		}

		/// <summary>
		/// 获取一个值，指示串口是否处于打开状态<br />
		/// Gets a value indicating whether the serial port is open
		/// </summary>
		/// <returns>是或否</returns>
		public bool IsOpen()
		{
			return isOpen;
		}

		/// <summary>
		/// 清除串口缓冲区的数据，并返回该数据，如果缓冲区没有数据，返回的字节数组长度为0<br />
		/// The number sent clears the data in the serial port buffer and returns that data, or if there is no data in the buffer, the length of the byte array returned is 0
		/// </summary>
		/// <returns>是否操作成功的方法</returns>
		public OResult<byte[]> ClearSerialCache()
		{
			return SPReceived(null, null, awaitData: false);
		}

		private string GetErrorText(int ret)
		{
			return ret switch
			{
				0 => "OK", 
				-1 => "Port number is invalid.", 
				-2 => "The board is not the MOXA compatible intelligent board", 
				-4 => "No data to read.", 
				-5 => "No such port or port is occupied by other program.", 
				-6 => "Can't control the port because it is set as auto H/W flow control by sio_flowctrl.", 
				-7 => "Bad parameter.", 
				-8 => "Calling Win32 function failed Call GetLastError to get the error code.", 
				-9 => "The com port does not support this function.", 
				-11 => "User abort blocked write.", 
				-12 => "Write timeout.", 
				_ => "Unkown", 
			};
		}

		/// <inheritdoc />
		public override OResult<bool> OpenCommunication()
		{
			try
			{
				if (!isOpen)
				{
					int num = PCommHelper.sio_open(portNumber);
					if (num == 0)
					{
						int mode = moxaDataBits | moxaParity | moxaStopBits;
						PCommHelper.sio_ioctl(portNumber, moxaBaudRate, mode);
						if (RtsEnable)
						{
							PCommHelper.sio_RTS(portNumber, 1);
						}
						if (DtrEnable)
						{
							PCommHelper.sio_DTR(portNumber, 1);
						}
						ResetConnectErrorCount();
						isOpen = true;
						return OResult.CreateSuccessResult(value: true);
					}
					return new OResult<bool>(num, GetErrorText(num));
				}
				return OResult.CreateSuccessResult(value: false);
			}
			catch (Exception ex)
			{
				return new OResult<bool>("OpenCommunication failed: " + ex.Message);
			}
		}

		/// <inheritdoc />
		public override OResult CloseCommunication()
		{
			if (isOpen)
			{
				try
				{
					PCommHelper.sio_close(portNumber);
					isOpen = false;
				}
				catch (Exception ex)
				{
					return new OResult(ex.Message);
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult Send(byte[] data, int offset, int size)
		{
			if (data != null && data.Length != 0)
			{
				try
				{
					int num = 0;
					if (offset == 0)
					{
						num = PCommHelper.sio_write(portNumber, data, data.Length);
					}
					else
					{
						byte[] array = data.SelectMiddle(offset, size);
						num = PCommHelper.sio_write(portNumber, array, array.Length);
					}
					if (num >= 0)
					{
						return OResult.CreateSuccessResult();
					}
					return new OResult(num, GetErrorText(num));
				}
				catch (Exception ex)
				{
					return new OResult(-IncrConnectErrorCount(), ex.Message);
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult<int> Receive(byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			try
			{
				if (length > 0)
				{
					int num = PCommHelper.sio_read(portNumber, ref buffer[offset], length);
					if (num >= 0)
					{
						return OResult.CreateSuccessResult(num);
					}
					return new OResult<int>(num, GetErrorText(num));
				}
				int num2 = PCommHelper.sio_read(portNumber, ref buffer[offset], buffer.Length - offset);
				if (num2 >= 0)
				{
					return OResult.CreateSuccessResult(num2);
				}
				return new OResult<int>(num2, GetErrorText(num2));
			}
			catch (Exception ex)
			{
				return new OResult<int>(-IncrConnectErrorCount(), ex.Message);
			}
		}

		/// <summary>
		/// 从串口接收一串字节数据信息，直到没有数据为止，如果参数awaitData为false, 第一轮接收没有数据则返回<br />
		/// Receives a string of bytes of data information from the serial port until there is no data, and returns if the parameter awaitData is false
		/// </summary>
		/// <param name="netMessage">定义的消息体对象</param>
		/// <param name="sendValue">等待发送的数据对象</param>
		/// <param name="awaitData">是否必须要等待数据返回</param>
		/// <param name="logMessage">用于消息记录的日志信息</param>
		/// <returns>结果数据对象</returns>
		private OResult<byte[]> SPReceived(INetMessage netMessage, byte[] sendValue, bool awaitData, Action<byte[]> logMessage = null)
		{
			byte[] array = null;
			MemoryStream memoryStream = null;
			try
			{
				array = new byte[1024];
				memoryStream = new MemoryStream();
			}
			catch (Exception ex)
			{
				return new OResult<byte[]>(ex.Message);
			}
			DateTime now = DateTime.Now;
			int num = 0;
			int num2 = 0;
			while (true)
			{
				num2++;
				if (num2 > 1 && base.SleepTime >= 0)
				{
					SnetHelper.ThreadSleep(base.SleepTime);
				}
				try
				{
					if (PCommHelper.sio_iqueue(portNumber) < 1)
					{
						if (num2 == 1)
						{
							continue;
						}
						if ((DateTime.Now - now).TotalMilliseconds > (double)base.ReceiveTimeOut)
						{
							return new OResult<byte[]>(-IncrConnectErrorCount(), $"Time out: {base.ReceiveTimeOut}, received: {memoryStream.ToArray().ToHexString(' ')}");
						}
						if (memoryStream.Length >= AtLeastReceiveLength)
						{
							num++;
							if (netMessage != null || num < ReceiveEmptyDataCount)
							{
								continue;
							}
						}
						else if (awaitData)
						{
							continue;
						}
						break;
					}
					num = 0;
					int num3 = PCommHelper.sio_read(portNumber, ref array[0], array.Length);
					if (num3 < 0)
					{
						return new OResult<byte[]>(num3, GetErrorText(num3));
					}
					if (num3 > 0)
					{
						memoryStream.Write(array, 0, num3);
						logMessage?.Invoke(array.SelectBegin(num3));
					}
					if (netMessage != null && CheckMessageComplete(netMessage, sendValue, ref memoryStream))
					{
						break;
					}
					if (base.ReceiveTimeOut > 0 && (DateTime.Now - now).TotalMilliseconds > (double)base.ReceiveTimeOut)
					{
						return new OResult<byte[]>(-IncrConnectErrorCount(), $"Time out: {base.ReceiveTimeOut}, received: {memoryStream.ToArray().ToHexString(' ')}");
					}
					continue;
				}
				catch (Exception ex2)
				{
					return new OResult<byte[]>(-IncrConnectErrorCount(), ex2.Message);
				}
			}
			ResetConnectErrorCount();
			return OResult.CreateSuccessResult(memoryStream.ToArray());
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReceiveMessage(INetMessage netMessage, byte[] sendValue, bool useActivePush = true, Action<long, long> reportProgress = null, Action<byte[]> logMessage = null)
		{
			if (base.UseServerActivePush)
			{
				return base.ReceiveMessage(netMessage, sendValue, useActivePush, reportProgress);
			}
			return SPReceived(netMessage, sendValue, awaitData: true, logMessage);
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReadFromCoreServer(INetMessage netMessage, byte[] sendValue, bool hasResponseData, Action<byte[]> logMessage = null)
		{
			if (IsClearCacheBeforeRead)
			{
				ClearSerialCache();
			}
			OResult<byte[]> oResult = ReadFromCoreServerHelper(netMessage, sendValue, hasResponseData, 0, logMessage);
			if (oResult.IsSuccess)
			{
				ResetConnectErrorCount();
			}
			return oResult;
		}

		/// <inheritdoc />
