				return sleepTime;
			}
			set
			{
				sleepTime = value;
			}
		}

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public PipeSocket()
		{
		}

		/// <summary>
		/// 通过指定的IP地址和端口号来实例化一个对象<br />
		/// Instantiate an object with the specified IP address and port number
		/// </summary>
		/// <param name="ipAddress">IP地址信息</param>
		/// <param name="port">端口号</param>
		public PipeSocket(string ipAddress, int port)
		{
			this.ipAddress = ipAddress;
			_port = new int[1] { port };
		}

		/// <summary>
		/// 获取当前的连接状态是否发生了异常，如果发生了异常，返回 False<br />
		/// Gets whether an exception has occurred in the current connection state, and returns False if an exception has occurred
		/// </summary>
		/// <returns>如果有异常，返回 True, 否则返回 False</returns>
		public bool IsConnectitonError()
		{
			if (!IsSocketError)
			{
				return socket == null;
			}
			return true;
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public override void Dispose()
		{
			base.Dispose();
			socket?.Close();
		}

		/// <summary>
		/// 设置多个可选的端口号信息，例如在三菱的PLC里，支持配置多个端口号，当一个网络发生异常时，立即切换端口号连接读写，提升系统的稳定性<br />
		/// Set multiple optional port number information. For example, in Mitsubishi PLC, it supports to configure multiple port numbers. 
		/// When an abnormality occurs in a network, the port number is immediately switched to connect to read and write to improve the stability of the system.
		/// </summary>
		/// <param name="ports">端口号数组信息</param>
		public void SetMultiPorts(int[] ports)
		{
			if (ports != null && ports.Length != 0)
			{
				_port = ports;
				indexPort = -1;
			}
		}

		/// <summary>
		/// 获取当前的远程连接信息，如果端口号设置了可选的数组，那么每次获取对象就会发生端口号切换的操作。<br />
		/// Get the current remote connection information. If the port number is set to an optional array, the port number switching operation will occur every time the object is obtained.
		/// </summary>
		/// <returns>远程连接的对象</returns>
		public IPEndPoint GetConnectIPEndPoint()
		{
			if (_port.Length == 1)
			{
				return new IPEndPoint(IPAddress.Parse(IpAddress), _port[0]);
			}
			ChangePorts();
			int port = _port[indexPort];
			return new IPEndPoint(IPAddress.Parse(IpAddress), port);
		}

		/// <summary>
		/// 变更当前的端口号信息，如果设置了多个端口号的话，就切换其他可用的端口<br />
		/// Change the current port number information, and if multiple port numbers are set, switch to other available ports
		/// </summary>
		public void ChangePorts()
		{
			if (_port.Length != 1)
			{
				if (indexPort < _port.Length - 1)
				{
					indexPort++;
				}
				else
				{
					indexPort = 0;
				}
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"PipeSocket[{ipAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 基于SSL/TLS加密的管道信息，内部基于 TCP/IP 通信实现<br />
	/// Pipe information based on SSL/TLS encryption, and internal TCP/IP communication
	/// </summary>
	public class PipeSslNet : PipeTcpNet
	{
		private bool isServerMode = true;

		private NetworkStream networkStream;

		private SslStream sslStream;

		private X509Certificate certificate;

		/// <summary>
		/// 获取或设置当前的证书内容，
		/// </summary>
		public X509Certificate Certificate
		{
			get
			{
				return certificate;
			}
			set
			{
				certificate = value;
			}
		}

		/// <summary>
		/// 获取或设置是否检查远程的证书，默认为不检查<br />
		/// </summary>
		public bool RemoteCertificateCheck { get; set; }

		/// <summary>
		/// 获取或设置当前的 SSL/TLS 协议版本，默认为 Tls | Tls11 | Tls12<br />
		/// </summary>
		public SslProtocols SslProtocols { get; set; } = SslProtocols.Tls;

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		/// <param name="serverMode">是否为服务器模式</param>
		public PipeSslNet(bool serverMode)
		{
			isServerMode = serverMode;
			sslInit();
		}

		/// <summary>
		/// 通过指定的IP地址和端口号来实例化一个对象<br />
		/// Instantiate an object with the specified IP address and port number
		/// </summary>
		/// <param name="ipAddress">IP地址信息</param>
		/// <param name="port">端口号</param>
		/// <param name="serverMode">是否为服务器模式</param>
		public PipeSslNet(string ipAddress, int port, bool serverMode)
			: base(ipAddress, port)
		{
			isServerMode = serverMode;
			sslInit();
		}

		/// <summary>
		/// 通过指定的套接字及连接的终结点来实例化一个对象<br />
		/// Instantiate an object by specifying the socket and the endpoint of the connection
		/// </summary>
		/// <param name="socket">连接的套接字对象</param>
		/// <param name="iPEndPoint">连接的远程地址信息</param>
		/// <param name="serverMode">是否为服务器模式</param>
		public PipeSslNet(Socket socket, IPEndPoint iPEndPoint, bool serverMode)
			: base(socket, iPEndPoint)
		{
			isServerMode = serverMode;
			sslInit();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSslNet.#ctor(System.Net.Sockets.Socket,System.Net.IPEndPoint,System.Boolean)" />
		public PipeSslNet(Socket socket, bool serverMode)
		{
			isServerMode = serverMode;
			base.Socket = socket;
			sslInit();
			CreateSslStream(socket, createNew: true);
		}

		private void sslInit()
		{
			SslProtocols = SslProtocols.Tls | SslProtocols.Tls11 | SslProtocols.Tls12;
		}

		/// <summary>
		/// 使用一个证书路径来初始化 SSL/TLS 通信<br />
		/// Use a certificate path to initialize SSL/TLS communication
		/// </summary>
		/// <param name="certificateFile">证书路径</param>
		public void SetCertficate(string certificateFile)
		{
			if (!string.IsNullOrEmpty(certificateFile))
			{
				certificate = X509Certificate.CreateFromCertFile(certificateFile);
			}
		}

		/// <inheritdoc />
		protected override OResult OnCommunicationOpen(Socket socket)
		{
			OResult<SslStream> oResult = CreateSslStream(socket, createNew: true);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			return base.OnCommunicationOpen(socket);
		}

		/// <summary>
		/// 当前的管道创建一个 SSL/TLS 加密的流<br />
		/// The current pipeline creates an SSL/TLS encrypted stream
		/// </summary>
		/// <param name="socket">套接字对象</param>
		/// <param name="createNew">是否创建一个新的流</param>
		/// <returns>如果创建成功，返回流对象</returns>
		public OResult<SslStream> CreateSslStream(Socket socket, bool createNew = false)
		{
			if (createNew)
			{
				networkStream?.Close();
				sslStream?.Close();
				networkStream = new NetworkStream(socket, ownsSocket: false);
				sslStream = new SslStream(networkStream, leaveInnerStreamOpen: false, ValidateCertificate, null);
				try
				{
					if (isServerMode)
					{
						sslStream.AuthenticateAsServer(certificate, clientCertificateRequired: false, SslProtocols, checkCertificateRevocation: true);
						return OResult.CreateSuccessResult(sslStream);
					}
					if (certificate == null)
					{
						sslStream.AuthenticateAsClient(host);
					}
					else
					{
						X509CertificateCollection clientCertificates = new X509CertificateCollection(new X509Certificate[1] { certificate });
						sslStream.AuthenticateAsClient(host, clientCertificates, SslProtocols, checkCertificateRevocation: false);
					}
					return OResult.CreateSuccessResult(sslStream);
				}
				catch (Exception ex)
				{
					if (ex.InnerException != null)
					{
						return new OResult<SslStream>(ex.InnerException.Message);
					}
					return new OResult<SslStream>(ex.Message);
				}
			}
			return OResult.CreateSuccessResult(sslStream);
		}

		private bool ValidateCertificate(object sender, X509Certificate certificate, X509Chain chain, SslPolicyErrors sslPolicyErrors)
		{
			if (sslPolicyErrors == SslPolicyErrors.None)
			{
				return true;
			}
			return !RemoteCertificateCheck;
		}

		/// <inheritdoc />
		public override OResult Send(byte[] data, int offset, int size)
		{
			OResult<SslStream> oResult = CreateSslStream(base.Socket);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult oResult2 = NetSupport.SocketSend(oResult.Content, data, offset, size);
			if (!oResult2.IsSuccess && oResult2.ErrorCode == NetSupport.SocketErrorCode)
			{
				CloseCommunication();
				return new OResult<byte[]>(-IncrConnectErrorCount(), oResult2.Message);
			}
			return oResult2;
		}

		/// <inheritdoc />
		public override OResult<int> Receive(byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			OResult<SslStream> oResult = CreateSslStream(base.Socket);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int>(oResult);
			}
			OResult<int> oResult2 = NetSupport.SocketReceive(oResult.Content, buffer, offset, length, timeOut, reportProgress);
			if (!oResult2.IsSuccess && oResult2.ErrorCode == NetSupport.SocketErrorCode)
			{
				CloseCommunication();
				return new OResult<int>(-IncrConnectErrorCount(), "Socket Exception -> " + oResult2.Message);
			}
			return oResult2;
		}

		/// <inheritdoc />
		public override async Task<OResult> SendAsync(byte[] data, int offset, int size)
		{
			OResult<SslStream> oResult = CreateSslStream(base.Socket);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<string>(oResult);
			}
			OResult send = await NetSupport.SocketSendAsync(oResult.Content, data, offset, size).ConfigureAwait(continueOnCapturedContext: false);
			if (!send.IsSuccess && send.ErrorCode == NetSupport.SocketErrorCode)
			{
				await CloseCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
				return new OResult<byte[]>(-IncrConnectErrorCount(), send.Message);
			}
			return send;
		}

		/// <inheritdoc />
		public override async Task<OResult<int>> ReceiveAsync(byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			OResult<SslStream> oResult = CreateSslStream(base.Socket);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int>(oResult);
			}
			OResult<int> receive = await NetSupport.SocketReceiveAsync(oResult.Content, buffer, offset, length, timeOut, reportProgress).ConfigureAwait(continueOnCapturedContext: false);
			if (!receive.IsSuccess && receive.ErrorCode == NetSupport.SocketErrorCode)
			{
				await CloseCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
				return new OResult<int>(-IncrConnectErrorCount(), "Socket Exception -> " + receive.Message);
			}
			return receive;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"PipeSslNet[{host}:{base.Port}]";
		}
	}
	/// <summary>
	/// 用于TCP/IP协议的传输管道信息<br />
	/// Transport pipe information of the IP protocol
	/// </summary>
	public class PipeTcpNet : CommunicationPipe
	{
		/// <summary>
		/// 配置的远程主机的名称，有可能是网址，也可能是IP
		/// </summary>
		protected string host = "127.0.0.1";

		private string ipAddress = "127.0.0.1";

		private int[] _port = new int[1] { 2000 };

		private int indexPort = -1;

		private Socket socket;

		private int connectTimeOut = 10000;

		private int recvTimeOutTick;

		private Func<IAsyncResult, int> socketEndMethod;

		/// <summary>
		/// 获取或设置绑定的本地的IP地址和端口号信息，如果端口设置为0，代表任何可用的端口<br />
		/// Get or set the bound local IP address and port number information, if the port is set to 0, it means any available port
		/// </summary>
		/// <remarks>
		/// 默认为NULL, 也即是不绑定任何本地的IP及端口号信息，使用系统自动分配的方式。<br />
		/// The default is NULL, which means that no local IP and port number information are bound, and the system automatically assigns it.
		/// </remarks>
		public IPEndPoint LocalBinding { get; set; }

		/// <summary>
		/// 获取或是设置远程服务器的IP地址，如果是本机测试，那么需要设置为127.0.0.1 <br />
		/// Get or set the IP address of the remote server. If it is a local test, then it needs to be set to 127.0.0.1
		/// </summary>
		/// <remarks>
		/// 最好实在初始化的时候进行指定，当使用短连接的时候，支持动态更改，切换；当使用长连接后，无法动态更改<br />
		/// 支持使用域名的网址方式，例如：www.Snetcommunication.cn
		/// </remarks>
		/// <example>
		/// 以下举例modbus-tcp的短连接及动态更改ip地址的示例
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="IpAddressExample" title="IpAddress示例" />
		/// </example>
		public string IpAddress
		{
			get
			{
				return ipAddress;
			}
			set
			{
				host = value;
				ipAddress = SnetHelper.GetIpAddressFromInput(value);
			}
		}

		/// <summary>
		/// 获取当前设置的远程的地址，可能是IP地址，也可能是网址，也就是初始设置的地址信息<br />
		/// Obtain the address of the remote address that is currently set, which may be an IP address or a web address, that is, the address information that is initially set
		/// </summary>
		public string Host => host;

		/// <inheritdoc cref="P:Snet.Driver.Core.Net.NetworkServerBase.SocketKeepAliveTime" />
		public int SocketKeepAliveTime { get; set; } = -1;

		/// <inheritdoc cref="P:Snet.Driver.Core.Net.NetworkDoubleBase.Port" />
		public int Port
		{
			get
			{
				if (_port.Length == 1)
				{
					return _port[0];
				}
				int num = indexPort;
				if (num < 0 || num >= _port.Length)
				{
					num = 0;
				}
				return _port[num];
			}
			set
			{
				if (_port.Length == 1)
				{
					_port[0] = value;
					return;
				}
				int num = indexPort;
				if (num < 0 || num >= _port.Length)
				{
					num = 0;
				}
				_port[num] = value;
			}
		}

		/// <summary>
		/// 获取或设置当前的客户端用于服务器连接的套接字。<br />
		/// Gets or sets the socket currently used by the client for server connection.
		/// </summary>
		public Socket Socket
		{
			get
			{
				return socket;
			}
			set
			{
				socket = value;
				if (socket != null)
				{
					socketEndMethod = socket.EndReceive;
				}
				else
				{
					socketEndMethod = null;
				}
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.Net.NetworkDoubleBase.ReceiveTimeOut" />
		public int ConnectTimeOut
		{
			get
			{
				return connectTimeOut;
			}
			set
			{
				connectTimeOut = value;
			}
		}

		/// <summary>
		/// 当因为接收超时而关闭连接的时候，获取或设置超过指定次数的时候，是否需要重新连接<br />
		/// When the connection is closed due to a reception timeout, and when the number of retrieves or Settings exceeds the specified limit, is it necessary to reconnect
		/// </summary>
		/// <remarks>
		/// 需要注意的是，当异步方法通信的时候，是不支持的，异步方法会自动处理连接的关闭和重新连接，如果小于0，则接收数据超时的次数无论多少，都不再关闭连接<br />
		/// </remarks>
		public int CloseOnRecvTimeOutTick { get; set; } = 1;

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSslNet.#ctor(System.Boolean)" />
		public PipeTcpNet()
		{
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSslNet.#ctor(System.String,System.Int32,System.Boolean)" />
		public PipeTcpNet(string ipAddress, int port)
		{
			IpAddress = ipAddress;
			Port = port;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeSslNet.#ctor(System.Net.Sockets.Socket,System.Net.IPEndPoint,System.Boolean)" />
		public PipeTcpNet(Socket socket, IPEndPoint iPEndPoint)
		{
			Socket = socket;
			if (iPEndPoint != null)
			{
				IpAddress = iPEndPoint.Address.ToString();
				Port = iPEndPoint.Port;
			}
		}

		/// <summary>
		/// 设置多个可选的端口号信息，例如在三菱的PLC里，支持配置多个端口号，当一个网络发生异常时，立即切换端口号连接读写，提升系统的稳定性<br />
		/// Set multiple optional port number information. For example, in Mitsubishi PLC, it supports to configure multiple port numbers. 
		/// When an abnormality occurs in a network, the port number is immediately switched to connect to read and write to improve the stability of the system.
		/// </summary>
		/// <param name="ports">端口号数组信息</param>
		public void SetMultiPorts(int[] ports)
		{
			if (ports != null && ports.Length != 0)
			{
				_port = ports;
				indexPort = -1;
			}
		}

		/// <summary>
		/// 获取当前的远程连接信息，如果端口号设置了可选的数组，那么每次获取对象就会发生端口号切换的操作。<br />
		/// Get the current remote connection information. If the port number is set to an optional array, the port number switching operation will occur every time the object is obtained.
		/// </summary>
		/// <returns>远程连接的对象</returns>
		public IPEndPoint GetConnectIPEndPoint()
		{
			if (_port.Length == 1)
			{
				return new IPEndPoint(IPAddress.Parse(IpAddress), _port[0]);
			}
			ChangePorts();
			int port = _port[indexPort];
			return new IPEndPoint(IPAddress.Parse(IpAddress), port);
		}

		/// <summary>
		/// 变更当前的端口号信息，如果设置了多个端口号的话，就切换其他可用的端口<br />
		/// Change the current port number information, and if multiple port numbers are set, switch to other available ports
		/// </summary>
		private void ChangePorts()
		{
			if (_port.Length != 1)
			{
				if (indexPort < _port.Length - 1)
				{
					indexPort++;
				}
				else
				{
					indexPort = 0;
				}
			}
		}

		/// <inheritdoc />
		public override bool IsConnectError()
		{
			if (socket == null)
			{
				return true;
			}
			return base.IsConnectError();
		}

		/// <summary>
		/// 当管道打开成功的时候执行的事件，如果返回失败，则管道的打开操作返回失败
		/// </summary>
		/// <param name="socket">通信的套接字</param>
		/// <returns>是否真的打开成功</returns>
		protected virtual OResult OnCommunicationOpen(Socket socket)
		{
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult<bool> OpenCommunication()
		{
			if (IsConnectError())
			{
				NetSupport.CloseSocket(socket);
				Socket = null;
				OResult<Socket> oResult = NetSupport.CreateSocketAndConnect(GetConnectIPEndPoint(), ConnectTimeOut, LocalBinding);
				if (oResult.IsSuccess)
				{
					OResult oResult2 = OnCommunicationOpen(oResult.Content);
					if (!oResult2.IsSuccess)
					{
						return oResult2.ConvertFailed<bool>();
					}
					if (SocketKeepAliveTime > 0)
					{
						oResult.Content.SetKeepAlive(SocketKeepAliveTime, SocketKeepAliveTime);
					}
					Socket = oResult.Content;
					ResetConnectErrorCount();
					return OResult.CreateSuccessResult(value: true);
				}
				return new OResult<bool>(-IncrConnectErrorCount(), oResult.Message);
			}
			return OResult.CreateSuccessResult(value: false);
		}

		/// <inheritdoc />
		public override OResult CloseCommunication()
		{
			NetSupport.CloseSocket(socket);
			Socket = null;
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		public override OResult Send(byte[] data, int offset, int size)
		{
			OResult oResult = NetSupport.SocketSend(socket, data, offset, size);
			if (!oResult.IsSuccess && oResult.ErrorCode == NetSupport.SocketErrorCode)
			{
				CloseCommunication();
				return new OResult<byte[]>(-IncrConnectErrorCount(), oResult.Message);
			}
			return oResult;
		}

		/// <inheritdoc />
		public override OResult<int> Receive(byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			OResult<int> oResult = NetSupport.SocketReceive(socket, buffer, offset, length, timeOut, reportProgress);
			if (!oResult.IsSuccess && oResult.ErrorCode == NetSupport.SocketErrorCode)
			{
				if (oResult.Content == int.MaxValue)
				{
					if (CloseOnRecvTimeOutTick < 0 || Interlocked.Increment(ref recvTimeOutTick) < CloseOnRecvTimeOutTick)
					{
						return new OResult<int>(-1, oResult.Message);
					}
					CloseCommunication();
					Interlocked.Exchange(ref recvTimeOutTick, 0);
				}
				else
				{
					CloseCommunication();
				}
				return new OResult<int>(-IncrConnectErrorCount(), oResult.Message);
			}
			if (oResult.IsSuccess)
			{
				Interlocked.Exchange(ref recvTimeOutTick, 0);
			}
			return oResult;
		}

		/// <inheritdoc />
		public override OResult StartReceiveBackground(INetMessage netMessage)
		{
			if (base.UseServerActivePush)
			{
				OResult oResult = socket.BeginReceiveResult(ServerSocketActivePushAsync, netMessage);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			return base.StartReceiveBackground(netMessage);
		}

		private async void ServerSocketActivePushAsync(IAsyncResult ar)
		{
			object asyncState = ar.AsyncState;
			if (!(asyncState is INetMessage netMessage))
			{
				return;
			}
			if (!socket.EndReceiveResult(ar).IsSuccess)
			{
				IncrConnectErrorCount();
				return;
			}
			OResult<byte[]> oResult = await ReceiveMessageAsync(netMessage, null, useActivePush: false).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				IncrConnectErrorCount();
				return;
			}
			if (base.DecideWhetherQAMessageFunction != null)
			{
				if (base.DecideWhetherQAMessageFunction(this, oResult))
				{
					SetBufferQA(oResult.Content);
				}
			}
			else
			{
				SetBufferQA(oResult.Content);
			}
			if (!socket.BeginReceiveResult(ServerSocketActivePushAsync, netMessage).IsSuccess)
			{
				IncrConnectErrorCount();
			}
		}

		/// <inheritdoc />
		public override async Task<OResult<bool>> OpenCommunicationAsync()
		{
			if (IsConnectError())
			{
				NetSupport.CloseSocket(socket);
				Socket = null;
				OResult<Socket> oResult = await NetSupport.CreateSocketAndConnectAsync(GetConnectIPEndPoint(), ConnectTimeOut, LocalBinding).ConfigureAwait(continueOnCapturedContext: false);
				if (oResult.IsSuccess)
				{
					OResult oResult2 = OnCommunicationOpen(oResult.Content);
					if (!oResult2.IsSuccess)
					{
						return oResult2.ConvertFailed<bool>();
					}
					if (SocketKeepAliveTime > 0)
					{
						oResult.Content.SetKeepAlive(SocketKeepAliveTime, SocketKeepAliveTime);
					}
					Socket = oResult.Content;
					ResetConnectErrorCount();
					return OResult.CreateSuccessResult(value: true);
				}
				return new OResult<bool>(-IncrConnectErrorCount(), oResult.Message);
			}
			return OResult.CreateSuccessResult(value: false);
		}

		/// <inheritdoc />
		public override async Task<OResult> CloseCommunicationAsync()
		{
			NetSupport.CloseSocket(socket);
			Socket = null;
			return await Task.FromResult(OResult.CreateSuccessResult());
		}

		/// <inheritdoc />
		public override async Task<OResult> SendAsync(byte[] data, int offset, int size)
		{
			OResult send = await NetSupport.SocketSendAsync(socket, data, offset, size).ConfigureAwait(continueOnCapturedContext: false);
			if (!send.IsSuccess && send.ErrorCode == NetSupport.SocketErrorCode)
			{
				await CloseCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
				return new OResult<byte[]>(-IncrConnectErrorCount(), send.Message);
			}
			return send;
		}

		/// <inheritdoc />
		public override async Task<OResult<int>> ReceiveAsync(byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			Func<IAsyncResult, int> func = socketEndMethod;
			if (func == null && socket != null)
			{
				func = socket.EndReceive;
			}
			OResult<int> receive = await NetSupport.SocketReceiveAsync2(socket, buffer, offset, length, timeOut, reportProgress, func).ConfigureAwait(continueOnCapturedContext: false);
			if (!receive.IsSuccess && receive.ErrorCode == NetSupport.SocketErrorCode)
			{
				await CloseCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
				return new OResult<int>(-IncrConnectErrorCount(), receive.Message);
			}
			return receive;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"PipeTcpNet[{ipAddress}:{Port}]";
		}
	}
	/// <summary>
	/// 基于UDP/IT通信的管道信息<br />
	/// Pipeline information based on UDP/IT communication
	/// </summary>
	public class PipeUdpNet : PipeTcpNet
	{
		/// <summary>
		/// 获取或设置一次接收时的数据长度，默认2KB数据长度，特殊情况的时候需要调整<br />
		/// Gets or sets the length of data received at a time. The default length is 2KB
		/// </summary>
		public int ReceiveCacheLength { get; set; } = 2048;

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public PipeUdpNet()
		{
		}

		/// <summary>
		/// 通过指定的IP地址和端口号来实例化一个对象<br />
		/// Instantiate an object with the specified IP address and port number
		/// </summary>
		/// <param name="ipAddress">IP地址信息</param>
		/// <param name="port">端口号</param>
		public PipeUdpNet(string ipAddress, int port)
		{
			base.IpAddress = ipAddress;
			base.Port = port;
		}

		/// <inheritdoc />
		public override OResult<bool> OpenCommunication()
		{
			if (IsConnectError())
			{
				try
				{
					Socket socket = new Socket(GetConnectIPEndPoint().AddressFamily, SocketType.Dgram, ProtocolType.Udp);
					if (base.LocalBinding != null)
					{
						socket.Bind(base.LocalBinding);
					}
					base.Socket = socket;
					ResetConnectErrorCount();
					return OResult.CreateSuccessResult(value: true);
				}
				catch (Exception ex)
				{
					CloseCommunication();
					return new OResult<bool>(-IncrConnectErrorCount(), ex.Message);
				}
			}
			return OResult.CreateSuccessResult(value: false);
		}

		/// <inheritdoc />
		public override async Task<OResult<bool>> OpenCommunicationAsync()
		{
			return await Task.Run(() => OpenCommunication()).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override OResult Send(byte[] data, int offset, int size)
		{
			IPEndPoint remoteEP = new IPEndPoint(IPAddress.Parse(base.IpAddress), base.Port);
			try
			{
				base.Socket.SendTo(data, offset, size, SocketFlags.None, remoteEP);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				CloseCommunication();
				return new OResult<byte[]>(-IncrConnectErrorCount(), ex.Message);
			}
		}

		/// <inheritdoc />
		public override async Task<OResult> SendAsync(byte[] data, int offset, int size)
		{
			return await Task.Run(() => Send(data, offset, size)).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override OResult<int> Receive(byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			try
			{
				base.Socket.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReceiveTimeout, base.ReceiveTimeOut);
				EndPoint remoteEP = new IPEndPoint((new IPEndPoint(IPAddress.Parse(base.IpAddress), base.Port).AddressFamily == AddressFamily.InterNetworkV6) ? IPAddress.IPv6Any : IPAddress.Any, 0);
				if (length > 0)
				{
					return OResult.CreateSuccessResult(base.Socket.ReceiveFrom(buffer, offset, length, SocketFlags.None, ref remoteEP));
				}
				return OResult.CreateSuccessResult(base.Socket.ReceiveFrom(buffer, offset, buffer.Length - offset, SocketFlags.None, ref remoteEP));
			}
			catch (Exception ex)
			{
				CloseCommunication();
				return new OResult<int>(-IncrConnectErrorCount(), "Socket Exception -> " + ex.Message);
			}
		}

		/// <inheritdoc />
		public override async Task<OResult<int>> ReceiveAsync(byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			return await Task.Run(() => Receive(buffer, offset, length, timeOut, reportProgress)).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override OResult<byte[]> ReceiveMessage(INetMessage netMessage, byte[] sendValue, bool useActivePush = true, Action<long, long> reportProgress = null, Action<byte[]> logMessage = null)
		{
			if (base.UseServerActivePush)
			{
				return base.ReceiveMessage(netMessage, sendValue, useActivePush, reportProgress, logMessage);
			}
			return ReceiveMessage(netMessage, sendValue, null, logMessage);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Pipe.PipeUdpNet.ReceiveMessage(Snet.Driver.Core.IMessage.INetMessage,System.Byte[],System.Boolean,System.Action{System.Int64,System.Int64},System.Action{System.Byte[]})" />
		/// <param name="alreadyReceive">已经接收的数据信息</param>
		public OResult<byte[]> ReceiveMessage(INetMessage netMessage, byte[] sendValue, byte[] alreadyReceive, Action<byte[]> logMessage = null, bool closeOnException = true)
		{
			try
			{
				MemoryStream ms = new MemoryStream();
				if (alreadyReceive != null && alreadyReceive.Length != 0)
				{
					ms.Write(alreadyReceive);
					if (CheckMessageComplete(netMessage, sendValue, ref ms))
					{
						return OResult.CreateSuccessResult(ms.ToArray());
					}
				}
				base.Socket.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReceiveTimeout, base.ReceiveTimeOut);
				EndPoint remoteEP = new IPEndPoint((new IPEndPoint(IPAddress.Parse(base.IpAddress), base.Port).AddressFamily == AddressFamily.InterNetworkV6) ? IPAddress.IPv6Any : IPAddress.Any, 0);
				OResult<byte[]> oResult = NetSupport.CreateReceiveBuffer(ReceiveCacheLength);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				DateTime now = DateTime.Now;
				while (true)
				{
					int length = base.Socket.ReceiveFrom(oResult.Content, ref remoteEP);
					byte[] array = oResult.Content.SelectBegin(length);
					ms.Write(array);
					logMessage?.Invoke(array);
					if (netMessage == null || CheckMessageComplete(netMessage, sendValue, ref ms))
					{
						break;
					}
					if (base.ReceiveTimeOut >= 0 && (DateTime.Now - now).TotalMilliseconds > (double)base.ReceiveTimeOut)
					{
						return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout + base.ReceiveTimeOut + " Received: " + ms.ToArray().ToHexString(' '));
					}
				}
				return OResult.CreateSuccessResult(ms.ToArray());
			}
			catch (Exception ex)
			{
				if (closeOnException)
				{
					CloseCommunication();
				}
				return new OResult<byte[]>(-IncrConnectErrorCount(), "Socket Exception -> " + ex.Message);
			}
		}

		/// <inheritdoc />
		public override async Task<OResult<byte[]>> ReceiveMessageAsync(INetMessage netMessage, byte[] sendValue, bool useActivePush = true, Action<long, long> reportProgress = null, Action<byte[]> logMessage = null)
		{
			return await Task.Run(() => ReceiveMessage(netMessage, sendValue, useActivePush, reportProgress, logMessage)).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"PipeUdpNet[{base.IpAddress}:{base.Port}]";
		}
	}
}
namespace Snet.Driver.Core.Net
