	/// <summary>
	/// 异形客户端的基类，提供了基础的异形操作<br />
	/// The base class of the profiled client provides the basic profiled operation
	/// </summary>
	public class NetworkAlienClient : CommunicationTcpServer, IDisposable
	{
		/// <summary>
		/// 远程连接的客户端上线的委托事件<br />
		/// The delegate event for the client to which the remote connection goes online
		/// </summary>
		/// <param name="pipe">异形客户端的会话信息</param>
		public delegate void OnClientConnectedDelegate(PipeDtuNet pipe);

		private byte[] password;

		private List<string> trustOnline;

		private SimpleHybirdLock trustLock;

		private bool isResponseAck = true;

		private bool isCheckPwd = true;

		private bool disposedValue;

		private bool useRegistrationPackage = true;

		/// <summary>
		/// 状态登录成功
		/// </summary>
		public const byte StatusOk = 0;

		/// <summary>
		/// 重复登录
		/// </summary>
		public const byte StatusLoginRepeat = 1;

		/// <summary>
		/// 禁止登录
		/// </summary>
		public const byte StatusLoginForbidden = 2;

		/// <summary>
		/// 密码错误
		/// </summary>
		public const byte StatusPasswodWrong = 3;

		/// <summary>
		/// 在DTU设备发送了注册报文的时候，指示是否返回响应报文，用来通知DTU设备是否登录成功，默认为 <c>True</c><br />
		/// When a DTU sends a registration packet, it indicates whether to return a response packet to notify the DTU whether the DTU is logged in, The default is <c>True</c>
		/// </summary>
		public bool IsResponseAck
		{
			get
			{
				return isResponseAck;
			}
			set
			{
				isResponseAck = value;
			}
		}

		/// <summary>
		/// 是否统一检查密码，如果每个会话需要自己检查密码，就需要设置为false<br />
		/// Whether to check the password uniformly, if each session needs to check the password by itself, it needs to be set to false
		/// </summary>
		public bool IsCheckPwd
		{
			get
			{
				return isCheckPwd;
			}
			set
			{
				isCheckPwd = value;
			}
		}

		/// <summary>
		/// 是否启用注册包的功能，如果不启用，就不会进行注册包的验证，有连接上来就自动覆盖本地的会话信息，不是很安全<br />
		/// Whether to enable the registration package function. If not enabled, the registration package verification will not be performed, 
		/// and the local session information will be automatically overwritten when a connection is made, which is not very secure
		/// </summary>
		public bool UseRegistrationPackage
		{
			get
			{
				return useRegistrationPackage;
			}
			set
			{
				useRegistrationPackage = value;
			}
		}

		/// <summary>
		/// 当有服务器连接上来的时候触发<br />
		/// Triggered when a server is connected
		/// </summary>
		public event OnClientConnectedDelegate OnClientConnected;

		/// <summary>
		/// 默认的无参构造方法<br />
		/// The default parameterless constructor
		/// </summary>
		public NetworkAlienClient()
		{
			password = new byte[6];
			trustOnline = new List<string>();
			trustLock = new SimpleHybirdLock();
		}

		/// <summary>
		/// 当接收到了新的请求的时候执行的操作<br />
		/// An action performed when a new request is received
		/// </summary>
		/// <param name="pipeTcpNet">管道对象</param>
		/// <param name="endPoint">终结点</param>
		protected override async void ThreadPoolLogin(PipeTcpNet pipeTcpNet, IPEndPoint endPoint)
		{
			if (useRegistrationPackage)
			{
				OResult<byte[]> oResult = await pipeTcpNet.ReceiveMessageAsync(new AlienMessage(), null, useActivePush: false);
				if (!oResult.IsSuccess)
				{
					base.LogNet?.WriteDebug(ToString(), $"Initialize [{endPoint}] DTU failed: " + oResult.Message);
					return;
				}
				byte[] content = oResult.Content;
				if (content != null && content.Length < 16)
				{
					pipeTcpNet.CloseCommunication();
					return;
				}
				if (oResult.Content[0] != 72)
				{
					pipeTcpNet.CloseCommunication();
					return;
				}
				string text = Encoding.ASCII.GetString(oResult.Content, 5, 11).Trim('\0', ' ');
				bool flag = true;
				if (oResult.Content.Length >= 29)
				{
					if (oResult.Content[28] == 1 || oResult.Content[28] == 49)
					{
						flag = false;
					}
				}
				else if (oResult.Content.Length <= 16)
				{
					flag = false;
				}
				bool flag2 = true;
				if (isCheckPwd)
				{
					for (int i = 0; i < password.Length; i++)
					{
						if (oResult.Content.Length > 16 + i)
						{
							if (oResult.Content[16 + i] != password[i])
							{
								flag2 = false;
								break;
							}
						}
						else if (password[i] != 0 && password[i] != 48)
						{
							flag2 = false;
							break;
						}
					}
				}
				if (!flag2)
				{
					if (isResponseAck & flag)
					{
						if (pipeTcpNet.Send(GetResponse(3)).IsSuccess)
						{
							pipeTcpNet.CloseCommunication();
						}
					}
					else
					{
						pipeTcpNet.CloseCommunication();
					}
					base.LogNet?.WriteWarn(ToString(), $"[{endPoint}] DTU:{text} Login Password Wrong, Id:" + text);
					return;
				}
				PipeDtuNet pipeDtuNet = new PipeDtuNet(pipeTcpNet)
				{
					DTU = text,
					DtuServer = this
				};
				int num = oResult.Content.Length - 16;
				if (num > 6)
				{
					num = 6;
				}
				pipeDtuNet.Pwd = ((num > 0) ? oResult.Content.SelectMiddle(16, num).ToHexString() : "");
				if (oResult.Content.Length >= 28)
				{
					pipeDtuNet.DTUIpAddress = BitConverter.ToInt32(oResult.Content, 22);
					pipeDtuNet.DTUPort = BitConverter.ToUInt16(oResult.Content, 26);
				}
				if (!IsClientPermission(pipeDtuNet))
				{
					if (isResponseAck & flag)
					{
						if (pipeTcpNet.Send(GetResponse(2)).IsSuccess)
						{
							pipeTcpNet.CloseCommunication();
						}
					}
					else
					{
						pipeTcpNet.CloseCommunication();
					}
					base.LogNet?.WriteWarn(ToString(), $"Initialize [{endPoint}] DTU:{text} Login Forbidden");
					return;
				}
				int num2 = IsClientOnline(pipeDtuNet);
				if (num2 != 0)
				{
					if (isResponseAck & flag)
					{
						if (pipeTcpNet.Send(GetResponse(1)).IsSuccess)
						{
							pipeTcpNet.CloseCommunication();
						}
					}
					else
					{
						pipeTcpNet.CloseCommunication();
					}
					base.LogNet?.WriteDebug(ToString(), GetMsgFromCode($"Initialize [{endPoint}] DTU:{text}", num2, "  Ack :" + (isResponseAck & flag)));
				}
				else if (!(isResponseAck & flag) || pipeTcpNet.Send(GetResponse(0)).IsSuccess)
				{
					base.LogNet?.WriteDebug(ToString(), GetMsgFromCode($"Initialize [{endPoint}] DTU:{text}", num2, "  Ack :" + (isResponseAck & flag)));
					RaiseClientConnected(pipeDtuNet);
				}
			}
			else
			{
				RaiseClientConnected(new PipeDtuNet(pipeTcpNet)
				{
					DtuServer = this
				});
			}
		}

		private void RaiseClientConnected(PipeDtuNet pipeDtuNet)
		{
			base.LogNet?.WriteDebug(ToString(), $"Dtu Session<{pipeDtuNet}> Connected");
			OnClientConnected?.Invoke(pipeDtuNet);
		}

		/// <summary>
		/// 获取取返回的命令信息
		/// </summary>
		/// <param name="status">状态</param>
		/// <returns>回发的指令信息</returns>
		private byte[] GetResponse(byte status)
		{
			byte[] obj = new byte[6] { 72, 115, 110, 0, 1, 0 };
			obj[5] = status;
			return obj;
		}

		/// <summary>
		/// 检测当前的DTU是否在线
		/// </summary>
		/// <param name="pipe">当前的会话信息</param>
		/// <returns>当前的会话是否在线</returns>
		public virtual int IsClientOnline(PipeDtuNet pipe)
		{
			return 0;
		}

		/// <summary>
		/// 检测当前的dtu是否允许登录
		/// </summary>
		/// <param name="session">当前的会话信息</param>
		/// <returns>当前的id是否可允许登录</returns>
		private bool IsClientPermission(PipeDtuNet session)
		{
			bool result = false;
			trustLock.Enter();
			if (trustOnline.Count == 0)
			{
				result = true;
			}
			else
			{
				for (int i = 0; i < trustOnline.Count; i++)
				{
					if (trustOnline[i] == session.DTU)
					{
						result = true;
						break;
					}
				}
			}
			trustLock.Leave();
			return result;
		}

		/// <summary>
		/// 设置密码，需要传入长度为6的字节数组<br />
		/// To set the password, you need to pass in an array of bytes of length 6
		/// </summary>
		/// <param name="password">密码信息</param>
		public void SetPassword(byte[] password)
		{
			if (password != null && password.Length == 6)
			{
				password.CopyTo(this.password, 0);
			}
		}

		/// <summary>
		/// 设置可信任的客户端列表，传入一个DTU的列表信息<br />
		/// Set up the list of trusted clients, passing in the list information for a DTU
		/// </summary>
		/// <param name="clients">客户端列表</param>
		public void SetTrustClients(string[] clients)
		{
			trustOnline = new List<string>(clients);
		}

		/// <summary>
		/// 释放当前的对象
		/// </summary>
		/// <param name="disposing"></param>
		protected virtual void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				if (disposing)
				{
					trustLock?.Dispose();
					OnClientConnected = null;
				}
				disposedValue = true;
			}
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return "NetworkAlienBase";
		}

		/// <summary>
		/// 获取错误的描述信息
		/// </summary>
		/// <param name="head">dtu信息</param>
		/// <param name="code">错误码</param>
		/// <param name="info">其他消息</param>
		/// <returns>错误信息</returns>
		public static string GetMsgFromCode(string head, int code, string info)
		{
			return code switch
			{
				0 => head + "  Login Success" + info, 
				1 => head + "  Login Repeat" + info, 
				2 => head + "  Login Forbidden" + info, 
				3 => head + "  Login Passwod Wrong" + info, 
				_ => head + "  Login Unknow reason:" + info, 
			};
		}
	}
	/// <summary>
	/// 带登录认证的服务器类，可以对连接的客户端进行筛选，放行用户名密码正确的连接，并支持对在线的客户端对象进行管理<br />
	/// The server class with login authentication can filter connected clients, allow connections with correct username and password, and support online client objects
	/// </summary>
	public class NetworkAuthenticationServerBase : NetworkServerBase, IDisposable
	{
		/// <summary>
		/// 表示客户端状态变化的委托信息<br />
		/// Delegate information representing the state change of the client
		/// </summary>
		/// <param name="server">当前的服务器对象信息</param>
		/// <param name="session">当前的客户端会话信息</param>
		public delegate void OnClientStatusChangeDelegate(object server, AppSession session);

		private Dictionary<string, string> accounts = new Dictionary<string, string>();

		private SimpleHybirdLock lockLoginAccount = new SimpleHybirdLock();

		private List<string> TrustedClients;

		private bool IsTrustedClientsOnly;

		private SimpleHybirdLock lock_trusted_clients;

		private Timer timerHeart;

		private List<AppSession> listsOnlineClient;

		private object lockOnlineClient;

		private int onlineCount;

		private bool disposedValue;

		/// <summary>
		/// 获取或设置是否对客户端启动账号认证<br />
		/// Gets or sets whether to enable account authentication on the client
		/// </summary>
		public bool IsUseAccountCertificate { get; set; }

		/// <summary>
		/// 获取在线的客户端的数量<br />
		/// Get the number of clients online
		/// </summary>
		public int OnlineCount => onlineCount;

		/// <summary>
		/// 获取当前所有在线的客户端信息，包括IP地址和端口号信息<br />
		/// Get all current online client information, including IP address and port number information
		/// </summary>
		public AppSession[] GetOnlineSessions
		{
			get
			{
				lock (lockOnlineClient)
				{
					return listsOnlineClient.ToArray();
				}
			}
		}

		/// <summary>
		/// 获取或设置两次数据交互时的最小时间间隔，默认为24小时。如果超过该设定的时间不进行数据交互，服务器就会强制断开当前的连接操作。<br />
		/// Get or set the minimum time interval between two data interactions, the default is 24 hours. 
		/// If the data exchange is not performed for more than the set time, the server will forcibly disconnect the current connection operation.
		/// </summary>
		/// <remarks>
		/// 举例设置为10分钟，ActiveTimeSpan = TimeSpan.FromMinutes( 10 );
		/// </remarks>
		public TimeSpan ActiveTimeSpan { get; set; }

		/// <summary>
		/// 当客户端上线时候的触发的事件<br />
		/// Event triggered when the client goes online
		/// </summary>
		public event OnClientStatusChangeDelegate OnClientOnline;

		/// <summary>
		/// 当客户端下线时候的触发的事件<br />
		/// Event triggered when the client goes offline
		/// </summary>
		public event OnClientStatusChangeDelegate OnClientOffline;

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// instantiate a default object
		/// </summary>
		public NetworkAuthenticationServerBase()
		{
			lock_trusted_clients = new SimpleHybirdLock();
			lockOnlineClient = new object();
			listsOnlineClient = new List<AppSession>();
			timerHeart = new Timer(ThreadTimerHeartCheck, null, 2000, 10000);
			ActiveTimeSpan = TimeSpan.FromHours(24.0);
		}

		/// <summary>
		/// 当客户端的socket登录的时候额外检查的信息，检查当前会话的用户名和密码<br />
		/// Additional check information when the client's socket logs in, check the username and password of the current session
		/// </summary>
		/// <param name="socket">套接字</param>
		/// <param name="endPoint">终结点</param>
		/// <returns>验证的结果</returns>
		protected override OResult SocketAcceptExtraCheck(Socket socket, IPEndPoint endPoint)
		{
			if (IsUseAccountCertificate)
			{
				OResult<byte[], byte[]> oResult = ReceiveAndCheckBytes(socket, 2000);
				if (!oResult.IsSuccess)
				{
					return new OResult($"Client login failed[{endPoint}]");
				}
				if (BitConverter.ToInt32(oResult.Content1, 0) != 5)
				{
					base.LogNet?.WriteError(ToString(), StringResources.Language.NetClientAccountTimeout);
					socket?.Close();
					return new OResult($"Authentication failed[{endPoint}]");
				}
				string[] array = SnetProtocol.UnPackStringArrayFromByte(oResult.Content2);
				string text = CheckAccountLegal(array);
				SendStringAndCheckReceive(socket, (text == "success") ? 1 : 0, new string[1] { text });
				if (text != "success")
				{
					return new OResult($"Client login failed[{endPoint}]:{text} {SoftBasic.ArrayFormat(array)}");
				}
				base.LogNet?.WriteDebug(ToString(), $"Account Login:{array[0]} Endpoint:[{endPoint}]");
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 新增账户，如果想要启动账户登录，必须将<see cref="P:Snet.Driver.Core.Net.NetworkAuthenticationServerBase.IsUseAccountCertificate" />设置为<c>True</c>。<br />
		/// Add an account. If you want to activate account login, you must set <see cref="P:Snet.Driver.Core.Net.NetworkAuthenticationServerBase.IsUseAccountCertificate" /> to <c> True </c>
		/// </summary>
		/// <param name="userName">账户名称</param>
		/// <param name="password">账户名称</param>
		public void AddAccount(string userName, string password)
		{
			if (!string.IsNullOrEmpty(userName))
			{
				lockLoginAccount.Enter();
				if (accounts.ContainsKey(userName))
				{
					accounts[userName] = password;
				}
				else
				{
					accounts.Add(userName, password);
				}
				lockLoginAccount.Leave();
			}
		}

		/// <summary>
		/// 删除一个账户的信息<br />
		/// Delete an account's information
		/// </summary>
		/// <param name="userName">账户名称</param>
		public void DeleteAccount(string userName)
		{
			lockLoginAccount.Enter();
			if (accounts.ContainsKey(userName))
			{
				accounts.Remove(userName);
			}
			lockLoginAccount.Leave();
		}

		private string CheckAccountLegal(string[] infos)
		{
			if (infos != null && infos.Length < 2)
			{
				return "User Name input wrong";
			}
			lockLoginAccount.Enter();
			string result = ((!accounts.ContainsKey(infos[0])) ? "User Name input wrong" : ((!(accounts[infos[0]] != infos[1])) ? "success" : "Password is not corrent"));
			lockLoginAccount.Leave();
			return result;
		}

		/// <summary>
		/// 当客户端登录后，在Ip信息的过滤后，然后触发本方法，进行后续的数据接收，处理，并返回相关的数据信息<br />
		/// When the client logs in, after filtering the IP information, this method is then triggered to perform subsequent data reception, 
		/// processing, and return related data information
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="endPoint">终端节点</param>
		protected virtual void ThreadPoolLoginAfterClientCheck(Socket socket, IPEndPoint endPoint)
		{
			AppSession appSession = new AppSession(socket);
			try
			{
				socket.BeginReceive(new byte[0], 0, 0, SocketFlags.None, SocketAsyncCallBack, appSession);
				AddClient(appSession);
			}
			catch
			{
				socket.Close();
				base.LogNet?.WriteDebug(ToString(), string.Format(StringResources.Language.ClientOfflineInfo, endPoint));
			}
		}

		/// <summary>
		/// 从远程Socket异步接收的数据信息
		/// </summary>
		/// <param name="ar">异步接收的对象</param>
		protected virtual void SocketAsyncCallBack(IAsyncResult ar)
		{
			if (ar.AsyncState is AppSession appSession)
			{
				appSession?.WorkSocket?.Close();
			}
		}

		/// <summary>
		/// 当接收到了新的请求的时候执行的操作，此处进行账户的安全验证<br />
		/// The operation performed when a new request is received, and the account security verification is performed here
		/// </summary>
		/// <param name="socket">异步对象</param>
		/// <param name="endPoint">终结点</param>
		protected override void ThreadPoolLogin(Socket socket, IPEndPoint endPoint)
		{
			string ipAddress = ((endPoint == null) ? string.Empty : endPoint.Address.ToString());
			if (IsTrustedClientsOnly && !CheckIpAddressTrusted(ipAddress))
			{
				base.LogNet?.WriteDebug(ToString(), string.Format(StringResources.Language.ClientDisableLogin, endPoint));
				socket.Close();
				return;
			}
			if (!IsUseAccountCertificate)
			{
				base.LogNet?.WriteDebug(ToString(), string.Format(StringResources.Language.ClientOnlineInfo, endPoint));
			}
			ThreadPoolLoginAfterClientCheck(socket, endPoint);
		}

		/// <summary>
		/// 设置并启动受信任的客户端登录并读写，如果为null，将关闭对客户端的ip验证<br />
		/// Set and start the trusted client login and read and write, if it is null, the client's IP verification will be turned off
		/// </summary>
		/// <param name="clients">受信任的客户端列表</param>
		public void SetTrustedIpAddress(List<string> clients)
		{
			lock_trusted_clients.Enter();
			if (clients != null)
			{
				TrustedClients = clients.Select((string m) => IPAddress.Parse(m).ToString()).ToList();
				IsTrustedClientsOnly = true;
			}
			else
			{
				TrustedClients = new List<string>();
				IsTrustedClientsOnly = false;
			}
			lock_trusted_clients.Leave();
		}

		/// <summary>
		/// 检查该Ip地址是否是受信任的<br />
		/// Check if the IP address is trusted
		/// </summary>
		/// <param name="ipAddress">Ip地址信息</param>
		/// <returns>是受信任的返回<c>True</c>，否则返回<c>False</c></returns>
		private bool CheckIpAddressTrusted(string ipAddress)
		{
			if (IsTrustedClientsOnly)
			{
				bool result = false;
				lock_trusted_clients.Enter();
				for (int i = 0; i < TrustedClients.Count; i++)
				{
					if (TrustedClients[i] == ipAddress)
					{
						result = true;
						break;
					}
				}
				lock_trusted_clients.Leave();
				return result;
			}
			return false;
		}

		/// <summary>
		/// 获取受信任的客户端列表<br />
		/// Get a list of trusted clients
		/// </summary>
		/// <returns>字符串数据信息</returns>
		public string[] GetTrustedClients()
		{
			string[] result = new string[0];
			lock_trusted_clients.Enter();
			if (TrustedClients != null)
			{
				result = TrustedClients.ToArray();
			}
			lock_trusted_clients.Leave();
			return result;
		}

		/// <inheritdoc />
		protected override void CloseAction()
		{
			lock (lockOnlineClient)
			{
				for (int i = 0; i < listsOnlineClient.Count; i++)
				{
					listsOnlineClient[i]?.WorkSocket?.Close();
					base.LogNet?.WriteDebug(ToString(), string.Format(StringResources.Language.ClientOfflineInfo, listsOnlineClient[i].IpEndPoint));
				}
				listsOnlineClient.Clear();
				onlineCount = 0;
			}
			base.CloseAction();
		}

		/// <summary>
		/// 新增一个在线的客户端信息<br />
		/// Add an online client information
		/// </summary>
		/// <param name="session">会话内容</param>
		protected void AddClient(AppSession session)
		{
			lock (lockOnlineClient)
			{
				listsOnlineClient.Add(session);
				onlineCount++;
			}
			OnClientOnline?.Invoke(this, session);
		}

		/// <summary>
		/// 移除一个在线的客户端信息<br />
		/// Remove an online client message
		/// </summary>
		/// <param name="session">会话内容</param>
		/// <param name="reason">下线的原因</param>
		protected void RemoveClient(AppSession session, string reason = "")
		{
			bool flag = false;
			lock (lockOnlineClient)
			{
				if (listsOnlineClient.Remove(session))
				{
					base.LogNet?.WriteDebug(ToString(), string.Format(StringResources.Language.ClientOfflineInfo, session.IpEndPoint) + " " + reason);
					session.WorkSocket?.Close();
					onlineCount--;
					flag = true;
				}
			}
			if (flag)
			{
				OnClientOffline?.Invoke(this, session);
			}
		}

		private void ThreadTimerHeartCheck(object obj)
		{
			AppSession[] array = null;
			lock (lockOnlineClient)
			{
				array = listsOnlineClient.ToArray();
			}
			if (array == null || array.Length == 0)
			{
				return;
			}
			for (int i = 0; i < array.Length; i++)
			{
				if (DateTime.Now - array[i].HeartTime > ActiveTimeSpan)
				{
					RemoveClient(array[i]);
				}
			}
		}

		/// <summary>
		/// 释放当前的对象
		/// </summary>
		/// <param name="disposing">是否托管对象</param>
		protected virtual void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				if (disposing)
				{
					ServerClose();
					lockLoginAccount?.Dispose();
					lock_trusted_clients?.Dispose();
				}
				disposedValue = true;
			}
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			Dispose(disposing: true);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"NetworkAuthenticationServerBase[{base.Port}]";
		}
	}
	/// <summary>
	/// 本系统所有网络类的基类，该类为抽象类，无法进行实例化，如果想使用里面的方法来实现自定义的网络通信，请通过继承使用。<br />
	/// The base class of all network classes in this system. This class is an abstract class and cannot be instantiated. 
	/// If you want to use the methods inside to implement custom network communication, please use it through inheritance.
	/// </summary>
	/// <remarks>
	/// 本类提供了丰富的底层数据的收发支持，包含<see cref="T:Snet.Driver.Core.IMessage.INetMessage" />消息的接收，<c>MQTT</c>以及<c>Redis</c>,<c>websocket</c>协议的实现
	/// </remarks>
	public abstract class NetworkBase
	{
		/// <summary>
		/// 文件传输的时候的缓存大小，直接影响传输的速度，值越大，传输速度越快，越占内存，默认为100K大小<br />
		/// The size of the cache during file transfer directly affects the speed of the transfer. The larger the value, the faster the transfer speed and the more memory it takes. The default size is 100K.
		/// </summary>
		protected int fileCacheSize = 102400;

		private int connectErrorCount;

		/// <summary>
		/// 组件的日志工具，支持日志记录，只要实例化后，当前网络的基本信息，就以<see cref="F:Snet.Driver.LogNet.SnetMessageDegree.DEBUG" />等级进行输出<br />
		/// The component's logging tool supports logging. As long as the instantiation of the basic network information, the output will be output at <see cref="F:Snet.Driver.LogNet.SnetMessageDegree.DEBUG" />
		/// </summary>
		/// <remarks>
		/// 只要实例化即可以记录日志，实例化的对象需要实现接口 <see cref="T:Snet.Driver.LogNet.ILogNet" /> ，本组件提供了三个日志记录类，你可以实现基于 <see cref="T:Snet.Driver.LogNet.ILogNet" />  的对象。</remarks>
		/// <example>
		/// 如下的实例化适用于所有的Network及其派生类，以下举两个例子，三菱的设备类及服务器类
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkBase.cs" region="LogNetExample1" title="LogNet示例" />
