		/// <summary>
		/// 接收固定长度的字节数组，允许指定超时时间，默认为60秒，当length大于0时，接收固定长度的数据内容，当length小于0时，buffer长度的缓存数据<br />
		/// Receiving a fixed-length byte array, allowing a specified timeout time. The default is 60 seconds. When length is greater than 0, 
		/// fixed-length data content is received. When length is less than 0, random data information of a length not greater than 2048 is received.
		/// </summary>
		/// <param name="socket">网络通讯的套接字<br />Network communication socket</param>
		/// <param name="buffer">等待接收的数据缓存信息</param>
		/// <param name="offset">开始接收数据的偏移地址</param>
		/// <param name="length">准备接收的数据长度，当length大于0时，接收固定长度的数据内容，当length小于0时，接收不大于1024长度的随机数据信息</param>
		/// <param name="timeOut">单位：毫秒，超时时间，默认为60秒，如果设置小于0，则不检查超时时间</param>
		/// <param name="reportProgress">当前接收数据的进度报告，有些协议支持传输非常大的数据内容，可以给与进度提示的功能</param>
		/// <returns>包含了字节数据的结果类</returns>
		protected OResult<int> Receive(Socket socket, byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(0);
			}
			try
			{
				socket.ReceiveTimeout = timeOut;
				if (length > 0)
				{
					NetSupport.ReceiveBytesFromSocket(socket, buffer, offset, length, reportProgress);
					return OResult.CreateSuccessResult(length);
				}
				int num = socket.Receive(buffer, offset, buffer.Length - offset, SocketFlags.None);
				if (num == 0)
				{
					throw new RemoteCloseException();
				}
				return OResult.CreateSuccessResult(num);
			}
			catch (RemoteCloseException)
			{
				socket?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<int>(-connectErrorCount, "Socket Exception -> " + StringResources.Language.RemoteClosedConnection);
			}
			catch (Exception ex2)
			{
				socket?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<int>(-connectErrorCount, "Socket Exception -> " + ex2.Message);
			}
		}

		/// <summary>
		/// 接收固定长度的字节数组，允许指定超时时间，默认为60秒，当length大于0时，接收固定长度的数据内容，当length小于0时，接收不大于2048长度的随机数据信息<br />
		/// Receiving a fixed-length byte array, allowing a specified timeout time. The default is 60 seconds. When length is greater than 0, 
		/// fixed-length data content is received. When length is less than 0, random data information of a length not greater than 2048 is received.
		/// </summary>
		/// <param name="socket">网络通讯的套接字<br />Network communication socket</param>
		/// <param name="length">准备接收的数据长度，当length大于0时，接收固定长度的数据内容，当length小于0时，接收不大于1024长度的随机数据信息</param>
		/// <param name="timeOut">单位：毫秒，超时时间，默认为60秒，如果设置小于0，则不检查超时时间</param>
		/// <param name="reportProgress">当前接收数据的进度报告，有些协议支持传输非常大的数据内容，可以给与进度提示的功能</param>
		/// <returns>包含了字节数据的结果类</returns>
		protected OResult<byte[]> Receive(Socket socket, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			int num = ((length > 0) ? length : 2048);
			byte[] array;
			try
			{
				array = new byte[num];
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult<byte[]>($"Create byte[{num}] buffer failed: " + ex.Message);
			}
			OResult<int> oResult = Receive(socket, array, 0, length, timeOut, reportProgress);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult((length > 0) ? array : array.SelectBegin(oResult.Content));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Receive(System.Net.Sockets.Socket,System.Byte[],System.Int32,System.Int32,System.Int32,System.Action{System.Int64,System.Int64})" />
		protected OResult<int> Receive(SslStream ssl, byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(0);
			}
			try
			{
				ssl.ReadTimeout = timeOut;
				if (length > 0)
				{
					int num = 0;
					while (num < length)
					{
						int count = Math.Min(length - num, 16384);
						int num2 = ssl.Read(buffer, num + offset, count);
						num += num2;
						if (num2 == 0)
						{
							throw new RemoteCloseException();
						}
						reportProgress?.Invoke(num, length);
					}
					return OResult.CreateSuccessResult(length);
				}
				int num3 = ssl.Read(buffer, offset, buffer.Length - offset);
				if (num3 == 0)
				{
					throw new RemoteCloseException();
				}
				return OResult.CreateSuccessResult(num3);
			}
			catch (RemoteCloseException)
			{
				ssl?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<int>(-1, "Socket Exception -> " + StringResources.Language.RemoteClosedConnection);
			}
			catch (Exception ex2)
			{
				ssl?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<int>(-1, "Socket Exception -> " + ex2.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Receive(System.Net.Sockets.Socket,System.Int32,System.Int32,System.Action{System.Int64,System.Int64})" />
		protected OResult<byte[]> Receive(SslStream ssl, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			int num = ((length > 0) ? length : 2048);
			byte[] array;
			try
			{
				array = new byte[num];
			}
			catch (Exception ex)
			{
				ssl?.Close();
				return new OResult<byte[]>($"Create byte[{num}] buffer failed: " + ex.Message);
			}
			OResult<int> oResult = Receive(ssl, array, 0, length, timeOut, reportProgress);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult((length > 0) ? array : array.SelectBegin(oResult.Content));
		}

		/// <summary>
		/// 接收一行命令数据，需要自己指定这个结束符，默认超时时间为60秒，也即是60000，单位是毫秒<br />
		/// To receive a line of command data, you need to specify the terminator yourself. The default timeout is 60 seconds, which is 60,000, in milliseconds.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="endCode">结束符信息</param>
		/// <param name="timeout">超时时间，默认为60000，单位为毫秒，也就是60秒</param>
		/// <returns>带有结果对象的数据信息</returns>
		protected OResult<byte[]> ReceiveCommandLineFromSocket(Socket socket, byte endCode, int timeout = 60000)
		{
			List<byte> list = new List<byte>(128);
			try
			{
				DateTime now = DateTime.Now;
				bool flag = false;
				while ((DateTime.Now - now).TotalMilliseconds < (double)timeout)
				{
					if (socket.Poll(timeout, SelectMode.SelectRead))
					{
						OResult<byte[]> oResult = Receive(socket, 1, timeout);
						if (!oResult.IsSuccess)
						{
							return oResult;
						}
						list.AddRange(oResult.Content);
						if (oResult.Content[0] == endCode)
						{
							flag = true;
							break;
						}
					}
				}
				if (!flag)
				{
					return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout);
				}
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 接收一行命令数据，需要自己指定这个结束符，默认超时时间为60秒，也即是60000，单位是毫秒<br />
		/// To receive a line of command data, you need to specify the terminator yourself. The default timeout is 60 seconds, which is 60,000, in milliseconds.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="endCode1">结束符1信息</param>
		/// <param name="endCode2">结束符2信息</param>
		/// /// <param name="timeout">超时时间，默认无穷大，单位毫秒</param>
		/// <returns>带有结果对象的数据信息</returns>
		protected OResult<byte[]> ReceiveCommandLineFromSocket(Socket socket, byte endCode1, byte endCode2, int timeout = 60000)
		{
			List<byte> list = new List<byte>(128);
			try
			{
				DateTime now = DateTime.Now;
				bool flag = false;
				while ((DateTime.Now - now).TotalMilliseconds < (double)timeout)
				{
					if (socket.Poll(timeout, SelectMode.SelectRead))
					{
						OResult<byte[]> oResult = Receive(socket, 1, timeout);
						if (!oResult.IsSuccess)
						{
							return oResult;
						}
						list.AddRange(oResult.Content);
						if (oResult.Content[0] == endCode2 && list.Count > 1 && list[list.Count - 2] == endCode1)
						{
							flag = true;
							break;
						}
					}
				}
				if (!flag)
				{
					return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout);
				}
				return OResult.CreateSuccessResult(list.ToArray());
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <summary>
		/// 接收一条完整的 <seealso cref="T:Snet.Driver.Core.IMessage.INetMessage" /> 数据内容，需要指定超时时间，单位为毫秒。 <br />
		/// Receive a complete <seealso cref="T:Snet.Driver.Core.IMessage.INetMessage" /> data content, Need to specify a timeout period in milliseconds
		/// </summary>
		/// <param name="socket">网络的套接字</param>
		/// <param name="timeOut">超时时间，单位：毫秒</param>
		/// <param name="netMessage">消息的格式定义</param>
		/// <param name="reportProgress">接收消息的时候的进度报告</param>
		/// <returns>带有是否成功的byte数组对象</returns>
		protected virtual OResult<byte[]> ReceiveByMessage(Socket socket, int timeOut, INetMessage netMessage, Action<long, long> reportProgress = null)
		{
			if (netMessage == null)
			{
				return Receive(socket, -1, timeOut);
			}
			if (netMessage.ProtocolHeadBytesLength < 0)
			{
				byte[] bytes = BitConverter.GetBytes(netMessage.ProtocolHeadBytesLength);
				int num = bytes[3] & 0xF;
				OResult<byte[]> oResult = null;
				switch (num)
				{
				case 1:
					oResult = ReceiveCommandLineFromSocket(socket, bytes[1], timeOut);
					break;
				case 2:
					oResult = ReceiveCommandLineFromSocket(socket, bytes[1], bytes[0], timeOut);
					break;
				}
				if (oResult == null)
				{
					return new OResult<byte[]>("Receive by specified code failed, length check failed");
				}
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				netMessage.HeadBytes = oResult.Content;
				if (netMessage is SpecifiedCharacterMessage specifiedCharacterMessage)
				{
					if (specifiedCharacterMessage.EndLength == 0)
					{
						return oResult;
					}
					OResult<byte[]> oResult2 = Receive(socket, specifiedCharacterMessage.EndLength, timeOut);
					if (!oResult2.IsSuccess)
					{
						return oResult2;
					}
					return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(oResult.Content, oResult2.Content));
				}
				return oResult;
			}
			OResult<byte[]> oResult3 = Receive(socket, netMessage.ProtocolHeadBytesLength, timeOut);
			if (!oResult3.IsSuccess)
			{
				return oResult3;
			}
			int num2 = netMessage.PependedUselesByteLength(oResult3.Content);
			int num3 = 0;
			while (num2 >= netMessage.ProtocolHeadBytesLength)
			{
				oResult3 = Receive(socket, netMessage.ProtocolHeadBytesLength, timeOut);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				num2 = netMessage.PependedUselesByteLength(oResult3.Content);
				num3++;
				if (num3 > 10)
				{
					break;
				}
			}
			if (num2 > 0)
			{
				OResult<byte[]> oResult4 = Receive(socket, num2, timeOut);
				if (!oResult4.IsSuccess)
				{
					return oResult4;
				}
				oResult3.Content = SoftBasic.SpliceArray<byte>(oResult3.Content.RemoveBegin(num2), oResult4.Content);
			}
			netMessage.HeadBytes = oResult3.Content;
			int contentLengthByHeadBytes = netMessage.GetContentLengthByHeadBytes();
			if (contentLengthByHeadBytes <= 0)
			{
				return OResult.CreateSuccessResult(oResult3.Content);
			}
			byte[] array = new byte[netMessage.ProtocolHeadBytesLength + contentLengthByHeadBytes];
			oResult3.Content.CopyTo(array, 0);
			OResult oResult5 = Receive(socket, array, netMessage.ProtocolHeadBytesLength, contentLengthByHeadBytes, timeOut, reportProgress);
			if (!oResult5.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult5);
			}
			return OResult.CreateSuccessResult(array);
		}

		/// <summary>
		/// 发送消息给套接字，直到完成的时候返回，经过测试，本方法是线程安全的。<br />
		/// Send a message to the socket until it returns when completed. After testing, this method is thread-safe.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="data">字节数据</param>
		/// <returns>发送是否成功的结果</returns>
		protected OResult Send(Socket socket, byte[] data)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			return Send(socket, data, 0, data.Length);
		}

		/// <summary>
		/// 发送消息给套接字，直到完成的时候返回，经过测试，本方法是线程安全的。<br />
		/// Send a message to the socket until it returns when completed. After testing, this method is thread-safe.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="data">字节数据</param>
		/// <param name="offset">偏移的位置信息</param>
		/// <param name="size">发送的数据总数</param>
		/// <returns>发送是否成功的结果</returns>
		protected OResult Send(Socket socket, byte[] data, int offset, int size)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			try
			{
				int num = 0;
				do
				{
					int num2 = socket.Send(data, offset, size - num, SocketFlags.None);
					num += num2;
					offset += num2;
				}
				while (num < size);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				socket?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<byte[]>(-connectErrorCount, ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Send(System.Net.Sockets.Socket,System.Byte[],System.Int32,System.Int32)" />
		protected OResult Send(SslStream ssl, byte[] data, int offset, int size)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			try
			{
				ssl.Write(data, offset, size);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				ssl?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<byte[]>(-connectErrorCount, ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Send(System.Net.Sockets.Socket,System.Byte[])" />
		protected OResult Send(SslStream ssl, byte[] data)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			return Send(ssl, data, 0, data.Length);
		}

