		/// <summary>
		/// [自校验] 接收一条完整的同步数据，包含头子节和内容字节，基础的数据，如果结果异常，则结束通讯<br />
		/// [Self-checking] Receive a complete synchronization data, including header subsection and content bytes, basic data, if the result is abnormal, the communication ends
		/// </summary>
		/// <param name="socket">套接字</param>
		/// <param name="timeOut">超时时间设置，如果为负数，则不检查超时</param>
		/// <returns>包含是否成功的结果对象</returns>
		/// <exception cref="T:System.ArgumentNullException">result</exception>
		protected OResult<byte[], byte[]> ReceiveAndCheckBytes(Socket socket, int timeOut)
		{
			OResult<byte[]> oResult = Receive(socket, 32, timeOut);
			if (!oResult.IsSuccess)
			{
				return oResult.ConvertFailed<byte[], byte[]>();
			}
			if (!CheckRemoteToken(oResult.Content))
			{
				socket?.Close();
				return new OResult<byte[], byte[]>(StringResources.Language.TokenCheckFailed);
			}
			int num = BitConverter.ToInt32(oResult.Content, 28);
			OResult<byte[]> oResult2 = Receive(socket, num, timeOut);
			if (!oResult2.IsSuccess)
			{
				return oResult2.ConvertFailed<byte[], byte[]>();
			}
			OResult oResult3 = SendLong(socket, 32 + num);
			if (!oResult3.IsSuccess)
			{
				return oResult3.ConvertFailed<byte[], byte[]>();
			}
			byte[] content = oResult.Content;
			byte[] content2 = oResult2.Content;
			content2 = SnetProtocol.CommandAnalysis(content, content2);
			return OResult.CreateSuccessResult(content, content2);
		}

		/// <summary>
		/// [自校验] 从网络中接收一个字符串数据，如果结果异常，则结束通讯<br />
		/// [Self-checking] Receive a string of data from the network. If the result is abnormal, the communication ends.
		/// </summary>
		/// <param name="socket">套接字</param>
		/// <param name="timeOut">接收数据的超时时间</param>
		/// <returns>包含是否成功的结果对象</returns>
		protected OResult<int, string> ReceiveStringContentFromSocket(Socket socket, int timeOut = 30000)
		{
			OResult<byte[], byte[]> oResult = ReceiveAndCheckBytes(socket, timeOut);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int, string>(oResult);
			}
			if (BitConverter.ToInt32(oResult.Content1, 0) != 1001)
			{
				socket?.Close();
				return new OResult<int, string>(StringResources.Language.CommandHeadCodeCheckFailed);
			}
			if (oResult.Content2 == null)
			{
				oResult.Content2 = new byte[0];
			}
			return OResult.CreateSuccessResult(BitConverter.ToInt32(oResult.Content1, 4), Encoding.Unicode.GetString(oResult.Content2));
		}

