		/// <summary>
		/// 从网络中接收Long数据<br />
		/// Receive Long data from the network
		/// </summary>
		/// <param name="socket">套接字网络</param>
		/// <returns>long数据结果</returns>
		private OResult<long> ReceiveLong(Socket socket)
		{
			OResult<byte[]> oResult = Receive(socket, 8, -1);
			if (oResult.IsSuccess)
			{
				return OResult.CreateSuccessResult(BitConverter.ToInt64(oResult.Content, 0));
			}
			return OResult.CreateFailedResult<long>(oResult);
		}

