		{
			return Send(socket, BitConverter.GetBytes(value));
		}

		/// <summary>
		/// 发送一个流的所有数据到指定的网络套接字，需要指定发送的数据长度，支持按照百分比的进度报告<br />
		/// Send all the data of a stream to the specified network socket. You need to specify the length of the data to be sent. It supports the progress report in percentage.
		/// </summary>
		/// <param name="socket">套接字</param>
		/// <param name="stream">内存流</param>
		/// <param name="receive">发送的数据长度</param>
		/// <param name="report">进度报告的委托</param>
		/// <param name="reportByPercent">进度报告是否按照百分比报告</param>
		/// <returns>是否成功的结果对象</returns>
		protected OResult SendStreamToSocket(Socket socket, Stream stream, long receive, Action<long, long> report, bool reportByPercent)
		{
			byte[] array = new byte[fileCacheSize];
			long num = 0L;
			long num2 = 0L;
			stream.Position = 0L;
			while (num < receive)
			{
				OResult<int> oResult = NetSupport.ReadStream(stream, array);
				if (!oResult.IsSuccess)
				{
					socket?.Close();
					return oResult;
				}
				num += oResult.Content;
				byte[] array2 = new byte[oResult.Content];
				Array.Copy(array, 0, array2, 0, array2.Length);
				OResult oResult2 = SendBytesAndCheckReceive(socket, oResult.Content, array2);
				if (!oResult2.IsSuccess)
				{
					socket?.Close();
					return oResult2;
				}
				if (reportByPercent)
				{
					long num3 = num * 100 / receive;
					if (num2 != num3)
					{
						num2 = num3;
						report?.Invoke(num, receive);
					}
				}
				else
				{
					report?.Invoke(num, receive);
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 从套接字中接收所有的数据然后写入到指定的流当中去，需要指定数据的长度，支持按照百分比进行进度报告<br />
		/// Receives all data from the socket and writes it to the specified stream. The length of the data needs to be specified, and progress reporting is supported in percentage.
		/// </summary>
		/// <param name="socket">套接字</param>
		/// <param name="stream">数据流</param>
		/// <param name="totalLength">所有数据的长度</param>
		/// <param name="report">进度报告</param>
		/// <param name="reportByPercent">进度报告是否按照百分比</param>
		/// <returns>是否成功的结果对象</returns>
		protected OResult WriteStreamFromSocket(Socket socket, Stream stream, long totalLength, Action<long, long> report, bool reportByPercent)
		{
			long num = 0L;
			long num2 = 0L;
			while (num < totalLength)
			{
				OResult<int, byte[]> oResult = ReceiveBytesContentFromSocket(socket, 60000);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				num += oResult.Content1;
				OResult oResult2 = NetSupport.WriteStream(stream, oResult.Content2);
				if (!oResult2.IsSuccess)
				{
					socket?.Close();
					return oResult2;
				}
				if (reportByPercent)
				{
					long num3 = num * 100 / totalLength;
					if (num2 != num3)
					{
						num2 = num3;
						report?.Invoke(num, totalLength);
					}
				}
				else
				{
					report?.Invoke(num, totalLength);
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.CreateSocketAndConnect(System.Net.IPEndPoint,System.Int32,System.Net.IPEndPoint)" />
		protected async Task<OResult<Socket>> CreateSocketAndConnectAsync(IPEndPoint endPoint, int timeOut, IPEndPoint local = null)
		{
			OResult<Socket> oResult = await NetSupport.CreateSocketAndConnectAsync(endPoint, timeOut, local).ConfigureAwait(continueOnCapturedContext: false);
			if (oResult.IsSuccess)
			{
				connectErrorCount = 0;
				return oResult;
			}
			if (connectErrorCount < 1000000000)
			{
				connectErrorCount++;
			}
			return new OResult<Socket>(-connectErrorCount, oResult.Message);
		}

