		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Receive(System.Net.Sockets.Socket,System.Int32,System.Int32,System.Action{System.Int64,System.Int64})" />
		protected async Task<OResult<byte[]>> ReceiveAsync(Socket socket, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			int num = ((length > 0) ? length : 2048);
			byte[] buffer;
			try
			{
				buffer = new byte[num];
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult<byte[]>($"Create byte[{num}] buffer failed: " + ex.Message);
			}
			OResult<int> oResult = await ReceiveAsync(socket, buffer, 0, length, timeOut, reportProgress).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult((length > 0) ? buffer : buffer.SelectBegin(oResult.Content));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Receive(System.Net.Sockets.Socket,System.Byte[],System.Int32,System.Int32,System.Int32,System.Action{System.Int64,System.Int64})" />
		protected async Task<OResult<int>> ReceiveAsync(Socket socket, byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(length);
			}
			SnetTimeOut SnetTimeOut = SnetTimeOut.HandleTimeOutCheck(socket, timeOut);
			try
			{
				if (length > 0)
				{
					int alreadyCount = 0;
					do
					{
						int size = ((length - alreadyCount > 16384) ? 16384 : (length - alreadyCount));
						int num = await Task.Factory.FromAsync(socket.BeginReceive(buffer, alreadyCount + offset, size, SocketFlags.None, null, socket), (Func<IAsyncResult, int>)socket.EndReceive).ConfigureAwait(continueOnCapturedContext: false);
						alreadyCount += num;
						if (num > 0)
						{
							SnetTimeOut.StartTime = DateTime.Now;
							reportProgress?.Invoke(alreadyCount, length);
							continue;
						}
						throw new RemoteCloseException();
					}
					while (alreadyCount < length);
					SnetTimeOut.IsSuccessful = true;
					return OResult.CreateSuccessResult(length);
				}
				int num2 = await Task.Factory.FromAsync(socket.BeginReceive(buffer, offset, buffer.Length - offset, SocketFlags.None, null, socket), (Func<IAsyncResult, int>)socket.EndReceive).ConfigureAwait(continueOnCapturedContext: false);
				if (num2 == 0)
				{
					throw new RemoteCloseException();
				}
				SnetTimeOut.IsSuccessful = true;
				return OResult.CreateSuccessResult(num2);
			}
			catch (RemoteCloseException)
			{
				socket?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				SnetTimeOut.IsSuccessful = true;
				return new OResult<int>(-connectErrorCount, StringResources.Language.RemoteClosedConnection);
			}
			catch (Exception ex2)
			{
				socket?.Close();
				SnetTimeOut.IsSuccessful = true;
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				if (SnetTimeOut.IsTimeout)
				{
					return new OResult<int>(-connectErrorCount, StringResources.Language.ReceiveDataTimeout + SnetTimeOut.DelayTime);
				}
				return new OResult<int>(-connectErrorCount, "Socket Exception -> " + ex2.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.ReceiveAsync(System.Net.Sockets.Socket,System.Int32,System.Int32,System.Action{System.Int64,System.Int64})" />
		protected async Task<OResult<byte[]>> ReceiveAsync(SslStream ssl, int length, int timeOut, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			int num = ((length > 0) ? length : 2048);
			byte[] buffer;
			try
			{
				buffer = new byte[num];
			}
			catch (Exception ex)
			{
				ssl?.Close();
				return new OResult<byte[]>($"Create byte[{num}] buffer failed: " + ex.Message);
			}
			OResult<int> oResult = await ReceiveAsync(ssl, buffer, 0, length, timeOut, reportProgress).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			return OResult.CreateSuccessResult((length > 0) ? buffer : buffer.SelectBegin(oResult.Content));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.ReceiveAsync(System.Net.Sockets.Socket,System.Byte[],System.Int32,System.Int32,System.Int32,System.Action{System.Int64,System.Int64})" />
		protected async Task<OResult<int>> ReceiveAsync(SslStream ssl, byte[] buffer, int offset, int length, int timeOut = 60000, Action<long, long> reportProgress = null)
		{
			if (length == 0)
			{
				return OResult.CreateSuccessResult(length);
			}
			try
			{
				if (length > 0)
				{
					int alreadyCount = 0;
					do
					{
						int count = ((length - alreadyCount > 16384) ? 16384 : (length - alreadyCount));
						int num = await ssl.ReadAsync(buffer, alreadyCount + offset, count).ConfigureAwait(continueOnCapturedContext: false);
						alreadyCount += num;
						if (num == 0)
						{
							throw new RemoteCloseException();
						}
						reportProgress?.Invoke(alreadyCount, length);
					}
					while (alreadyCount < length);
					return OResult.CreateSuccessResult(length);
				}
				int num2 = await ssl.ReadAsync(buffer, offset, buffer.Length - offset).ConfigureAwait(continueOnCapturedContext: false);
				if (num2 == 0)
				{
					throw new RemoteCloseException();
				}
				return OResult.CreateSuccessResult(num2);
			}
			catch (RemoteCloseException)
			{
				ssl?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<int>(-connectErrorCount, StringResources.Language.RemoteClosedConnection);
			}
			catch (Exception ex2)
			{
				ssl?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<int>(-connectErrorCount, "Socket Exception -> " + ex2.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.ReceiveCommandLineFromSocket(System.Net.Sockets.Socket,System.Byte,System.Int32)" />
		protected async Task<OResult<byte[]>> ReceiveCommandLineFromSocketAsync(Socket socket, byte endCode, int timeout = int.MaxValue)
		{
			List<byte> bufferArray = new List<byte>(128);
			try
			{
				DateTime st = DateTime.Now;
				bool bOK = false;
				while ((DateTime.Now - st).TotalMilliseconds < (double)timeout)
				{
					if (socket.Poll(timeout, SelectMode.SelectRead))
					{
						OResult<byte[]> oResult = await ReceiveAsync(socket, 1, timeout).ConfigureAwait(continueOnCapturedContext: false);
						if (!oResult.IsSuccess)
						{
							return oResult;
						}
						bufferArray.AddRange(oResult.Content);
						if (oResult.Content[0] == endCode)
						{
							bOK = true;
							break;
						}
					}
				}
				if (!bOK)
				{
					return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout);
				}
				return OResult.CreateSuccessResult(bufferArray.ToArray());
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.ReceiveCommandLineFromSocket(System.Net.Sockets.Socket,System.Byte,System.Byte,System.Int32)" />
		protected async Task<OResult<byte[]>> ReceiveCommandLineFromSocketAsync(Socket socket, byte endCode1, byte endCode2, int timeout = 60000)
		{
			List<byte> bufferArray = new List<byte>(128);
			try
			{
				DateTime st = DateTime.Now;
				bool bOK = false;
				while ((DateTime.Now - st).TotalMilliseconds < (double)timeout)
				{
					if (socket.Poll(timeout, SelectMode.SelectRead))
					{
						OResult<byte[]> oResult = await ReceiveAsync(socket, 1, timeout).ConfigureAwait(continueOnCapturedContext: false);
						if (!oResult.IsSuccess)
						{
							return oResult;
						}
						bufferArray.AddRange(oResult.Content);
						if (oResult.Content[0] == endCode2 && bufferArray.Count > 1 && bufferArray[bufferArray.Count - 2] == endCode1)
						{
							bOK = true;
							break;
						}
					}
				}
				if (!bOK)
				{
					return new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout);
				}
				return OResult.CreateSuccessResult(bufferArray.ToArray());
			}
			catch (Exception ex)
			{
				socket?.Close();
				return new OResult<byte[]>(ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Send(System.Net.Sockets.Socket,System.Byte[])" />
		protected async Task<OResult> SendAsync(Socket socket, byte[] data)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			return await SendAsync(socket, data, 0, data.Length).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Send(System.Net.Sockets.Socket,System.Byte[],System.Int32,System.Int32)" />
		protected async Task<OResult> SendAsync(Socket socket, byte[] data, int offset, int size)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			int alreadyCount = 0;
			try
			{
				do
				{
					int num = await Task.Factory.FromAsync(socket.BeginSend(data, offset, size - alreadyCount, SocketFlags.None, null, socket), (Func<IAsyncResult, int>)socket.EndSend).ConfigureAwait(continueOnCapturedContext: false);
					alreadyCount += num;
					offset += num;
				}
				while (alreadyCount < size);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				socket?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<byte[]>(-connectErrorCount, ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Send(System.Net.Sockets.Socket,System.Byte[])" />
