		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.Send(System.Net.Sockets.Socket,System.Byte[],System.Int32,System.Int32)" />
		protected async Task<OResult> SendAsync(SslStream ssl, byte[] data, int offset, int size)
		{
			if (data == null)
			{
				return OResult.CreateSuccessResult();
			}
			try
			{
				await ssl.WriteAsync(data, offset, size).ConfigureAwait(continueOnCapturedContext: false);
				return OResult.CreateSuccessResult();
			}
			catch (Exception ex)
			{
				ssl?.Close();
				if (connectErrorCount < 1000000000)
				{
					connectErrorCount++;
				}
				return new OResult<byte[]>(-connectErrorCount, ex.Message);
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.ReceiveByMessage(System.Net.Sockets.Socket,System.Int32,Snet.Driver.Core.IMessage.INetMessage,System.Action{System.Int64,System.Int64})" />
		protected virtual async Task<OResult<byte[]>> ReceiveByMessageAsync(Socket socket, int timeOut, INetMessage netMessage, Action<long, long> reportProgress = null)
		{
			if (netMessage == null)
			{
				return await ReceiveAsync(socket, -1, timeOut).ConfigureAwait(continueOnCapturedContext: false);
			}
			if (netMessage.ProtocolHeadBytesLength < 0)
			{
				byte[] bytes = BitConverter.GetBytes(netMessage.ProtocolHeadBytesLength);
				int num = bytes[3] & 0xF;
				OResult<byte[]> receive = null;
				switch (num)
				{
				case 1:
					receive = await ReceiveCommandLineFromSocketAsync(socket, bytes[1], timeOut).ConfigureAwait(continueOnCapturedContext: false);
					break;
				case 2:
					receive = await ReceiveCommandLineFromSocketAsync(socket, bytes[1], bytes[0], timeOut).ConfigureAwait(continueOnCapturedContext: false);
					break;
				}
				if (receive == null)
				{
					return new OResult<byte[]>("Receive by specified code failed, length check failed");
				}
				if (!receive.IsSuccess)
				{
					return receive;
				}
				netMessage.HeadBytes = receive.Content;
				if (netMessage is SpecifiedCharacterMessage specifiedCharacterMessage)
				{
					if (specifiedCharacterMessage.EndLength == 0)
					{
						return receive;
					}
					OResult<byte[]> oResult = await ReceiveAsync(socket, specifiedCharacterMessage.EndLength, timeOut).ConfigureAwait(continueOnCapturedContext: false);
					if (!oResult.IsSuccess)
					{
						return oResult;
					}
					return OResult.CreateSuccessResult(SoftBasic.SpliceArray<byte>(receive.Content, oResult.Content));
				}
				return receive;
			}
			OResult<byte[]> headResult = await ReceiveAsync(socket, netMessage.ProtocolHeadBytesLength, timeOut).ConfigureAwait(continueOnCapturedContext: false);
			if (!headResult.IsSuccess)
			{
				return headResult;
			}
			int start = netMessage.PependedUselesByteLength(headResult.Content);
			int cycleCount = 0;
			while (start >= netMessage.ProtocolHeadBytesLength)
			{
				headResult = await ReceiveAsync(socket, netMessage.ProtocolHeadBytesLength, timeOut).ConfigureAwait(continueOnCapturedContext: false);
				if (!headResult.IsSuccess)
				{
					return headResult;
				}
				start = netMessage.PependedUselesByteLength(headResult.Content);
				cycleCount++;
				if (cycleCount > 10)
				{
					break;
				}
			}
			if (start > 0)
			{
				OResult<byte[]> oResult2 = await ReceiveAsync(socket, start, timeOut).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					return oResult2;
				}
				headResult.Content = SoftBasic.SpliceArray<byte>(headResult.Content.RemoveBegin(start), oResult2.Content);
			}
			netMessage.HeadBytes = headResult.Content;
			int contentLengthByHeadBytes = netMessage.GetContentLengthByHeadBytes();
			if (contentLengthByHeadBytes <= 0)
			{
				return OResult.CreateSuccessResult(headResult.Content);
			}
			byte[] buffer = new byte[netMessage.ProtocolHeadBytesLength + contentLengthByHeadBytes];
			headResult.Content.CopyTo(buffer, 0);
			OResult<int> oResult3 = await ReceiveAsync(socket, buffer, netMessage.ProtocolHeadBytesLength, contentLengthByHeadBytes, timeOut, reportProgress).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult3.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult3);
			}
			return OResult.CreateSuccessResult(buffer);
		}

