		protected async Task<OResult> SendBaseAndCheckReceiveAsync(Socket socket, int headCode, int customer, byte[] send)
		{
			send = SnetProtocol.CommandBytes(headCode, customer, Token, send);
			OResult oResult = await SendAsync(socket, send).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
