			}
			OResult<long> oResult2 = await ReceiveLongAsync(socket).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (oResult2.Content != send.Length)
			{
				socket?.Close();
				return new OResult(StringResources.Language.CommandLengthCheckFailed);
