		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.ReceiveAndCheckBytes(System.Net.Sockets.Socket,System.Int32)" />
		protected async Task<OResult<byte[], byte[]>> ReceiveAndCheckBytesAsync(Socket socket, int timeout)
		{
			OResult<byte[]> headResult = await ReceiveAsync(socket, 32, timeout).ConfigureAwait(continueOnCapturedContext: false);
			if (!headResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], byte[]>(headResult);
			}
			if (!CheckRemoteToken(headResult.Content))
			{
				socket?.Close();
				return new OResult<byte[], byte[]>(StringResources.Language.TokenCheckFailed);
			}
			int contentLength = BitConverter.ToInt32(headResult.Content, 28);
			OResult<byte[]> contentResult = await ReceiveAsync(socket, contentLength, timeout).ConfigureAwait(continueOnCapturedContext: false);
			if (!contentResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], byte[]>(contentResult);
			}
			OResult oResult = await SendLongAsync(socket, 32 + contentLength).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[], byte[]>(oResult);
			}
			byte[] content = headResult.Content;
			byte[] content2 = contentResult.Content;
			content2 = SnetProtocol.CommandAnalysis(content, content2);
			return OResult.CreateSuccessResult(content, content2);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.ReceiveStringContentFromSocket(System.Net.Sockets.Socket,System.Int32)" />
		protected async Task<OResult<int, string>> ReceiveStringContentFromSocketAsync(Socket socket, int timeOut = 30000)
		{
			OResult<byte[], byte[]> oResult = await ReceiveAndCheckBytesAsync(socket, timeOut).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int, string>(oResult);
			}
			if (BitConverter.ToInt32(oResult.Content1, 0) != 1001)
			{
				socket?.Close();
				return new OResult<int, string>(StringResources.Language.CommandHeadCodeCheckFailed);
			}
			if (oResult.Content2 == null)
			{
				oResult.Content2 = new byte[0];
			}
			return OResult.CreateSuccessResult(BitConverter.ToInt32(oResult.Content1, 4), Encoding.Unicode.GetString(oResult.Content2));
		}

