		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.SendStreamToSocket(System.Net.Sockets.Socket,System.IO.Stream,System.Int64,System.Action{System.Int64,System.Int64},System.Boolean)" />
		protected async Task<OResult> SendStreamToSocketAsync(Socket socket, Stream stream, long receive, Action<long, long> report, bool reportByPercent)
		{
			byte[] buffer = new byte[fileCacheSize];
			long SendTotal = 0L;
			long percent = 0L;
			stream.Position = 0L;
			while (SendTotal < receive)
			{
				OResult<int> oResult = await NetSupport.ReadStreamAsync(stream, buffer).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult.IsSuccess)
				{
					socket?.Close();
					return oResult;
				}
				SendTotal += oResult.Content;
				byte[] array = new byte[oResult.Content];
				Array.Copy(buffer, 0, array, 0, array.Length);
				OResult oResult2 = await SendBytesAndCheckReceiveAsync(socket, oResult.Content, array).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					socket?.Close();
					return oResult2;
				}
				if (reportByPercent)
				{
					long num = SendTotal * 100 / receive;
					if (percent != num)
					{
						percent = num;
						report?.Invoke(SendTotal, receive);
					}
				}
				else
				{
					report?.Invoke(SendTotal, receive);
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.WriteStreamFromSocket(System.Net.Sockets.Socket,System.IO.Stream,System.Int64,System.Action{System.Int64,System.Int64},System.Boolean)" />
		protected async Task<OResult> WriteStreamFromSocketAsync(Socket socket, Stream stream, long totalLength, Action<long, long> report, bool reportByPercent)
		{
			long count_receive = 0L;
			long percent = 0L;
			while (count_receive < totalLength)
			{
				OResult<int, byte[]> oResult = await ReceiveBytesContentFromSocketAsync(socket, 60000).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
				count_receive += oResult.Content1;
				OResult oResult2 = await NetSupport.WriteStreamAsync(stream, oResult.Content2).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult2.IsSuccess)
				{
					socket?.Close();
					return oResult2;
				}
				if (reportByPercent)
				{
					long num = count_receive * 100 / totalLength;
					if (percent != num)
					{
						percent = num;
						report?.Invoke(count_receive, totalLength);
					}
				}
				else
				{
					report?.Invoke(count_receive, totalLength);
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 接收一条Snet协议的数据信息，自动解析，解压，解码操作，获取最后的实际的数据，接收结果依次为暗号，用户码，负载数据<br />
		/// Receive a piece of Snet protocol data information, automatically parse, decompress, and decode operations to obtain the last actual data. 
		/// The result is a opCode, user code, and payload data in order.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <returns>接收结果，依次为暗号，用户码，负载数据</returns>
		protected OResult<int, int, byte[]> ReceiveSnetMessage(Socket socket)
		{
			OResult<byte[]> oResult = Receive(socket, 32, 10000);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int, int, byte[]>(oResult);
			}
			int length = BitConverter.ToInt32(oResult.Content, oResult.Content.Length - 4);
			OResult<byte[]> oResult2 = Receive(socket, length);
			if (!oResult2.IsSuccess)
			{
				return OResult.CreateFailedResult<int, int, byte[]>(oResult2);
			}
			byte[] value = SnetProtocol.CommandAnalysis(oResult.Content, oResult2.Content);
			int value2 = BitConverter.ToInt32(oResult.Content, 0);
			int value3 = BitConverter.ToInt32(oResult.Content, 4);
			return OResult.CreateSuccessResult(value2, value3, value);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkBase.ReceiveSnetMessage(System.Net.Sockets.Socket)" />
		protected async Task<OResult<int, int, byte[]>> ReceiveSnetMessageAsync(Socket socket)
		{
			OResult<byte[]> receiveHead = await ReceiveAsync(socket, 32, 10000).ConfigureAwait(continueOnCapturedContext: false);
			if (!receiveHead.IsSuccess)
			{
				return OResult.CreateFailedResult<int, int, byte[]>(receiveHead);
			}
			int length = BitConverter.ToInt32(receiveHead.Content, receiveHead.Content.Length - 4);
			OResult<byte[]> oResult = await ReceiveAsync(socket, length).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<int, int, byte[]>(oResult);
			}
			byte[] value = SnetProtocol.CommandAnalysis(receiveHead.Content, oResult.Content);
			int value2 = BitConverter.ToInt32(receiveHead.Content, 0);
			int value3 = BitConverter.ToInt32(receiveHead.Content, 4);
			return OResult.CreateSuccessResult(value2, value3, value);
		}

		/// <summary>
		/// 删除一个指定的文件，如果文件不存在，直接返回 <c>True</c>，如果文件存在则直接删除，删除成功返回 <c>True</c>，如果发生了异常，返回<c>False</c><br />
		/// Delete a specified file, if the file does not exist, return <c>True</c> directly, if the file exists, delete it directly, 
		/// if the deletion is successful, return <c>True</c>, if an exception occurs, return <c> False</c>
		/// </summary>
		/// <param name="fileName">完整的文件路径</param>
		/// <returns>是否删除成功</returns>
		protected bool DeleteFileByName(string fileName)
		{
			try
			{
				if (!File.Exists(fileName))
				{
					return true;
				}
				File.Delete(fileName);
				return true;
			}
			catch (Exception ex)
			{
				LogNet?.WriteException(ToString(), "delete file [" + fileName + "] failed: ", ex);
				return false;
			}
		}

