	/// <summary>
	/// 基于连接的CIP协议的基类
	/// </summary>
	public class NetworkConnectedCip : DeviceTcpNet
	{
		private SoftIncrementCount incrementCount = new SoftIncrementCount(65535L, 3L, 2);

		private long openForwardId = 256L;

		private long context;

		/// <inheritdoc cref="P:Snet.Driver.Profinet.AllenBradley.AllenBradleyNet.SessionHandle" />
		public uint SessionHandle { get; protected set; }

		/// <summary>
		/// O -&gt; T Network Connection ID
		/// </summary>
		public uint OTConnectionId { get; set; }

		/// <summary>
		/// T -&gt; O Network Connection ID
		/// </summary>
		public uint TOConnectionId { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public NetworkConnectedCip()
		{
		}

		/// <inheritdoc />
		protected override INetMessage GetNewNetMessage()
		{
			return new AllenBradleyMessage();
		}

		/// <inheritdoc />
		public override byte[] PackCommandWithHeader(byte[] command)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(177);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(0);
			long currentValue = incrementCount.GetCurrentValue();
			memoryStream.WriteByte(BitConverter.GetBytes(currentValue)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(currentValue)[1]);
			memoryStream.Write(command);
			byte[] array = memoryStream.ToArray();
			memoryStream.Dispose();
			BitConverter.GetBytes((ushort)(array.Length - 4)).CopyTo(array, 2);
			return AllenBradleyHelper.PackRequestHeader(112, SessionHandle, AllenBradleyHelper.PackCommandSpecificData(GetOTConnectionIdService(), array));
		}

		/// <summary>
		/// 从握手报文里提取ConnectionId的方法
		/// </summary>
		/// <param name="content">原始报文</param>
		protected virtual void ExtraConnectionId(byte[] content)
		{
			OTConnectionId = base.ByteTransform.TransUInt32(content, 44);
		}

		/// <inheritdoc />
		protected override OResult InitializationOnConnect()
		{
			OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.RegisterSessionHandle(BitConverter.GetBytes(Interlocked.Increment(ref context))), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult oResult2 = AllenBradleyHelper.CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			uint num = base.ByteTransform.TransUInt32(oResult.Content, 4);
			for (int i = 0; i < 10; i++)
			{
				long value = Interlocked.Increment(ref openForwardId);
				ushort connectionID = ((i < 7) ? ((ushort)i) : ((ushort)SnetHelper.SnetRandom.Next(7, 200)));
				OResult<byte[]> oResult3 = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, num, GetLargeForwardOpen(connectionID), base.ByteTransform.TransByte(value)), hasResponseData: true, usePackAndUnpack: false);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				try
				{
					if (oResult3.Content.Length >= 46 && oResult3.Content[42] != 0)
					{
						ushort num2 = base.ByteTransform.TransUInt16(oResult3.Content, 44);
						if (num2 == 256 && i < 9)
						{
							continue;
						}
						return num2 switch
						{
							256 => new OResult("Connection in use or duplicate Forward Open"), 
							275 => new OResult("Extended Status: Out of connections (0x0113)"), 
							_ => new OResult("Forward Open failed, Code: " + base.ByteTransform.TransUInt16(oResult3.Content, 44)), 
						};
					}
					ExtraConnectionId(oResult3.Content);
				}
				catch (Exception ex)
				{
					return new OResult(ex.Message + Environment.NewLine + "Source: " + oResult3.Content.ToHexString(' '));
				}
				break;
			}
			incrementCount.ResetCurrentValue();
			SessionHandle = num;
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override OResult ExtraOnDisconnect()
		{
			if (CommunicationPipe == null)
			{
				return OResult.CreateSuccessResult();
			}
			byte[] largeForwardClose = GetLargeForwardClose();
			if (largeForwardClose != null)
			{
				OResult<byte[]> oResult = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, SessionHandle, largeForwardClose), hasResponseData: true, usePackAndUnpack: false);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			OResult<byte[]> oResult2 = ReadFromCoreServer(CommunicationPipe, AllenBradleyHelper.UnRegisterSessionHandle(SessionHandle), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override async Task<OResult> InitializationOnConnectAsync()
		{
			OResult<byte[]> oResult = await ReadFromCoreServerAsync(CommunicationPipe, AllenBradleyHelper.RegisterSessionHandle(BitConverter.GetBytes(Interlocked.Increment(ref context))), hasResponseData: true, usePackAndUnpack: false).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult oResult2 = AllenBradleyHelper.CheckResponse(oResult.Content);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			uint sessionHandle = base.ByteTransform.TransUInt32(oResult.Content, 4);
			for (int i = 0; i < 10; i++)
			{
				long value = Interlocked.Increment(ref openForwardId);
				OResult<byte[]> oResult3 = await ReadFromCoreServerAsync(send: AllenBradleyHelper.PackRequestHeader(111, sessionHandle, GetLargeForwardOpen((i < 7) ? ((ushort)i) : ((ushort)SnetHelper.SnetRandom.Next(7, 200))), base.ByteTransform.TransByte(value)), pipe: CommunicationPipe, hasResponseData: true, usePackAndUnpack: false).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult3.IsSuccess)
				{
					return oResult3;
				}
				try
				{
					if (oResult3.Content.Length >= 46 && oResult3.Content[42] != 0)
					{
						ushort num = base.ByteTransform.TransUInt16(oResult3.Content, 44);
						if (num == 256 && i < 9)
						{
							continue;
						}
						return num switch
						{
							256 => new OResult("Connection in use or duplicate Forward Open"), 
							275 => new OResult("Extended Status: Out of connections (0x0113)"), 
							_ => new OResult("Forward Open failed, Code: " + base.ByteTransform.TransUInt16(oResult3.Content, 44)), 
						};
					}
					ExtraConnectionId(oResult3.Content);
				}
				catch (Exception ex)
				{
					return new OResult(ex.Message + Environment.NewLine + "Source: " + oResult3.Content.ToHexString(' '));
				}
				break;
			}
			incrementCount.ResetCurrentValue();
			SessionHandle = sessionHandle;
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override async Task<OResult> ExtraOnDisconnectAsync()
		{
			if (CommunicationPipe == null)
			{
				return OResult.CreateSuccessResult();
			}
			byte[] largeForwardClose = GetLargeForwardClose();
			if (largeForwardClose != null)
			{
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(CommunicationPipe, AllenBradleyHelper.PackRequestHeader(111, SessionHandle, largeForwardClose), hasResponseData: true, usePackAndUnpack: false);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			OResult<byte[]> oResult2 = await ReadFromCoreServerAsync(CommunicationPipe, AllenBradleyHelper.UnRegisterSessionHandle(SessionHandle), hasResponseData: true, usePackAndUnpack: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 将多个的CIP命令打包成一个服务的命令
		/// </summary>
		/// <param name="cip">CIP命令列表</param>
		/// <returns>服务命令</returns>
		protected byte[] PackCommandService(params byte[][] cip)
		{
			if (cip.Length == 1)
			{
				return cip[0];
			}
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.Write(new byte[6] { 10, 2, 32, 2, 36, 1 }, 0, 6);
			memoryStream.WriteByte(BitConverter.GetBytes(cip.Length)[0]);
			memoryStream.WriteByte(BitConverter.GetBytes(cip.Length)[1]);
			int num = 2 + cip.Length * 2;
			for (int i = 0; i < cip.Length; i++)
			{
				memoryStream.WriteByte(BitConverter.GetBytes(num)[0]);
				memoryStream.WriteByte(BitConverter.GetBytes(num)[1]);
				num += cip[i].Length;
			}
			for (int j = 0; j < cip.Length; j++)
			{
				memoryStream.Write(cip[j], 0, cip[j].Length);
			}
			return memoryStream.ToArray();
		}

		/// <summary>
		/// 获取数据通信的前置打开命令，不同的PLC的信息不一样。
		/// </summary>
		/// <param name="connectionID">连接的ID信息</param>
		/// <returns>原始命令数据</returns>
		protected virtual byte[] GetLargeForwardOpen(ushort connectionID)
		{
			return "\r\n00 00 00 00 00 00 02 00 00 00 00 00 b2 00 34 00\r\n5b 02 20 06 24 01 0e 9c 02 00 00 80 01 00 fe 80\r\n02 00 1b 05 30 a7 2b 03 02 00 00 00 80 84 1e 00\r\ncc 07 00 42 80 84 1e 00 cc 07 00 42 a3 03 20 02\r\n24 01 2c 01".ToHexBytes();
		}

		/// <summary>
		/// 获取数据通信的后置关闭命令，不同的PLC的信息不一样。
		/// </summary>
		/// <returns>原始命令数据</returns>
		protected virtual byte[] GetLargeForwardClose()
		{
			return null;
		}

		private byte[] GetOTConnectionIdService()
		{
			byte[] array = new byte[8] { 161, 0, 4, 0, 0, 0, 0, 0 };
			base.ByteTransform.TransByte(OTConnectionId).CopyTo(array, 4);
			return array;
		}

		/// <summary>
		/// 从PLC反馈的数据解析出真实的数据内容，结果内容分别是原始字节数据，数据类型代码，是否有很多的数据<br />
		/// The real data content is parsed from the data fed back by the PLC. The result content is the original byte data, 
		/// the data type code, and whether there is a lot of data.
		/// </summary>
		/// <param name="response">PLC的反馈数据</param>
		/// <param name="isRead">是否是返回的操作</param>
		/// <returns>带有结果标识的最终数据</returns>
		public static OResult<byte[], ushort, bool> ExtractActualData(byte[] response, bool isRead)
		{
			List<byte> list = new List<byte>();
			try
			{
				int num = 42;
				bool value = false;
				ushort value2 = 0;
				ushort num2 = BitConverter.ToUInt16(response, num);
				if (BitConverter.ToInt32(response, 46) == 138)
				{
					num = 50;
					int num3 = BitConverter.ToUInt16(response, num);
					for (int i = 0; i < num3; i++)
					{
						int num4 = BitConverter.ToUInt16(response, num + 2 + i * 2) + num;
						int num5 = ((i == num3 - 1) ? response.Length : (BitConverter.ToUInt16(response, num + 4 + i * 2) + num));
						ushort num6 = BitConverter.ToUInt16(response, num4 + 2);
						switch (num6)
						{
						case 4:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.AllenBradley04
							};
						case 5:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.AllenBradley05
							};
						case 6:
							if (response[num + 2] == 210 || response[num + 2] == 204)
							{
								return new OResult<byte[], ushort, bool>
								{
									ErrorCode = num6,
									Message = StringResources.Language.AllenBradley06
								};
							}
							break;
						case 10:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.AllenBradley0A
							};
						case 12:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.AllenBradley0C
							};
						case 19:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.AllenBradley13
							};
						case 28:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.AllenBradley1C
							};
						case 30:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.AllenBradley1E
							};
						case 38:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.AllenBradley26
							};
						default:
							return new OResult<byte[], ushort, bool>
							{
								ErrorCode = num6,
								Message = StringResources.Language.UnknownError
							};
						case 0:
							break;
						}
						if (isRead)
						{
							for (int j = num4 + 6; j < num5; j++)
							{
								list.Add(response[j]);
							}
						}
					}
				}
				else
				{
					byte b = response[num + 6];
					switch (b)
					{
					case 4:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.AllenBradley04
						};
					case 5:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.AllenBradley05
						};
					case 6:
						value = true;
						break;
					case 10:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.AllenBradley0A
						};
					case 12:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.AllenBradley0C
						};
					case 19:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.AllenBradley13
						};
					case 28:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.AllenBradley1C
						};
					case 30:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.AllenBradley1E
						};
					case 38:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.AllenBradley26
						};
					default:
						return new OResult<byte[], ushort, bool>
						{
							ErrorCode = b,
							Message = StringResources.Language.UnknownError
						};
					case 0:
						break;
					}
					if (response[num + 4] == 205 || response[num + 4] == 211)
					{
						return OResult.CreateSuccessResult(list.ToArray(), value2, value);
					}
					if (response[num + 4] == 204 || response[num + 4] == 210)
					{
						for (int k = num + 10; k < num + 2 + num2; k++)
						{
							list.Add(response[k]);
						}
						value2 = BitConverter.ToUInt16(response, num + 8);
					}
					else if (response[num + 4] == 213)
					{
						for (int l = num + 8; l < num + 2 + num2; l++)
						{
							list.Add(response[l]);
						}
					}
					else if (response[num + 4] == 203)
					{
						if (response[58] != 0)
						{
							return new OResult<byte[], ushort, bool>(response[58], AllenBradleyDF1Serial.GetExtStatusDescription(response[58]) + Environment.NewLine + "Source: " + response.RemoveBegin(57).ToHexString(' '));
						}
						if (!isRead)
						{
							return OResult.CreateSuccessResult(list.ToArray(), value2, value);
						}
						return OResult.CreateSuccessResult(response.RemoveBegin(61), value2, value);
					}
				}
				return OResult.CreateSuccessResult(list.ToArray(), value2, value);
			}
			catch (Exception ex)
			{
				return new OResult<byte[], ushort, bool>("ExtractActualData failed: " + ex.Message + Environment.NewLine + "Source: " + response.ToHexString(' '));
			}
		}
	}
