		/// <summary>
		/// 尝试连接远程的服务器，如果连接成功，就切换短连接模式到长连接模式，后面的每次请求都共享一个通道，使得通讯速度更快速<br />
		/// Try to connect to a remote server. If the connection is successful, switch the short connection mode to the long connection mode. 
		/// Each subsequent request will share a channel, making the communication speed faster.
		/// </summary>
		/// <returns>返回连接结果，如果失败的话（也即IsSuccess为False），包含失败信息</returns>
		/// <example>
		///   简单的连接示例，调用该方法后，连接设备，创建一个长连接的对象，后续的读写操作均公用一个连接对象。
		///   <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="Connect1" title="连接设备" />
		///   如果想知道是否连接成功，请参照下面的代码。
		///   <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="Connect2" title="判断连接结果" />
		/// </example> 
		public OResult ConnectServer()
		{
			isPersistentConn = true;
			pipeSocket.Socket?.Close();
			OResult<Socket> oResult = CreateSocketAndInitialication();
			if (!oResult.IsSuccess)
			{
				pipeSocket.IsSocketError = true;
				oResult.Content = null;
			}
			else
			{
				pipeSocket.Socket = oResult.Content;
				if (SocketKeepAliveTime > 0)
				{
					oResult.Content.SetKeepAlive(SocketKeepAliveTime, SocketKeepAliveTime);
				}
				base.LogNet?.WriteDebug(ToString(), StringResources.Language.NetEngineStart);
			}
			return oResult;
		}

		/// <summary>
		/// 使用指定的套接字创建异形客户端，在异形客户端的模式下，网络通道需要被动创建。<br />
		/// Use the specified socket to create the alien client. In the alien client mode, the network channel needs to be created passively.
		/// </summary>
		/// <param name="session">异形客户端对象，查看<seealso cref="T:Snet.Driver.Core.Net.NetworkAlienClient" />类型创建的客户端</param>
		/// <returns>通常都为成功</returns>
		/// <example>
		///   简单的创建示例。
		///   <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="AlienConnect1" title="连接设备" />
		///   如果想知道是否创建成功。通常都是成功。
		///   <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="AlienConnect2" title="判断连接结果" />
		/// </example> 
		/// <remarks>
		/// 不能和之前的长连接和短连接混用，详细参考 Demo程序 
		/// </remarks>
		public OResult ConnectServer(AlienSession session)
		{
			isPersistentConn = true;
			isUseSpecifiedSocket = true;
			if (session != null)
			{
				AlienSession?.Pipe?.CloseCommunication();
				if (string.IsNullOrEmpty(ConnectionId))
				{
					ConnectionId = session.DTU;
				}
				if (ConnectionId == session.DTU)
				{
					if (session.IsStatusOk)
					{
						OResult oResult = InitializationOnConnect(session.Pipe.Socket);
						if (oResult.IsSuccess)
						{
							pipeSocket.Socket = session.Pipe.Socket;
							pipeSocket.IsSocketError = !session.IsStatusOk;
							AlienSession = session;
							return oResult;
						}
						pipeSocket.IsSocketError = true;
						return oResult;
					}
					return new OResult();
				}
				pipeSocket.IsSocketError = true;
				return new OResult();
			}
			pipeSocket.IsSocketError = true;
			return new OResult();
		}

		/// <summary>
		/// 手动断开与远程服务器的连接，如果当前是长连接模式，那么就会切换到短连接模式<br />
		/// Manually disconnect from the remote server, if it is currently in long connection mode, it will switch to short connection mode
		/// </summary>
		/// <returns>关闭连接，不需要查看IsSuccess属性查看</returns>
		/// <example>
		/// 直接关闭连接即可，基本上是不需要进行成功的判定
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="ConnectCloseExample" title="关闭连接结果" />
		/// </example>
		public OResult ConnectClose()
		{
			OResult oResult = new OResult();
			isPersistentConn = false;
			try
			{
				oResult = ((pipeSocket.Socket != null) ? ExtraOnDisconnect(pipeSocket.Socket) : OResult.CreateSuccessResult());
				if (mqttClient == null)
				{
					pipeSocket.Socket?.Close();
					pipeSocket.Socket = null;
				}
			}
			catch
			{
				throw;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Close);
			return oResult;
		}

		private async void ServerSocketActivePushAsync(IAsyncResult ar)
		{
			object asyncState = ar.AsyncState;
			if (!(asyncState is Socket socket))
			{
				return;
			}
			if (!socket.EndReceiveResult(ar).IsSuccess)
			{
				pipeSocket.IsSocketError = true;
				return;
			}
			OResult<byte[]> oResult = await base.ReceiveByMessageAsync(socket, ReceiveTimeOut, GetNewNetMessage()).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				pipeSocket.IsSocketError = true;
				return;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Receive + " : " + (LogMsgFormatBinary ? oResult.Content.ToHexString(' ') : SoftBasic.GetAsciiStringRender(oResult.Content)));
			if (!socket.BeginReceiveResult(ServerSocketActivePushAsync).IsSuccess)
			{
				pipeSocket.IsSocketError = true;
			}
			if (DecideWhetherQAMessage(socket, oResult))
			{
				bufferQA = oResult.Content;
				autoResetEvent.Set();
			}
		}

		/// <summary>
		/// 决定当前的消息是否是应答机制的消息内容，需要在客户端进行重写实现，如果是应答机制，返回 <c>True</c>, 否则返回 <c>False</c><br />
		/// To determine whether the current message is the message content of the response mechanism, 
		/// it needs to be rewritten on the client side. If it is the response mechanism, return <c>True</c>, otherwise return <c>False</c>
		/// </summary>
		/// <param name="socket">通信使用的网络套接字</param>
		/// <param name="receive">服务器返回的内容</param>
		/// <returns>是否应答机制的数据报文</returns>
		protected virtual bool DecideWhetherQAMessage(Socket socket, OResult<byte[]> receive)
		{
			return true;
		}

		/// <summary>
		/// 根据实际的协议选择是否重写本方法，有些协议在创建连接之后，需要进行一些初始化的信号握手，才能最终建立网络通道。<br />
		/// Whether to rewrite this method is based on the actual protocol. Some protocols require some initial signal handshake to establish a network channel after the connection is created.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <returns>是否初始化成功，依据具体的协议进行重写</returns>
		/// <example>
		/// 有些协议不需要握手信号，比如三菱的MC协议，Modbus协议，西门子和欧姆龙就存在握手信息，此处的例子是继承本类后重写的西门子的协议示例
		/// <code lang="cs" source="Snet.Driver\Profinet\Siemens\SiemensS7Net.cs" region="NetworkDoubleBase Override" title="西门子重连示例" />
		/// </example>
		protected virtual OResult InitializationOnConnect(Socket socket)
		{
			if (useServerActivePush)
			{
				OResult oResult = socket.BeginReceiveResult(ServerSocketActivePushAsync);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 根据实际的协议选择是否重写本方法，有些协议在断开连接之前，需要发送一些报文来关闭当前的网络通道<br />
		/// Select whether to rewrite this method according to the actual protocol. Some protocols need to send some packets to close the current network channel before disconnecting.
		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <example>
		/// 目前暂无相关的示例，组件支持的协议都不用实现这个方法。
		/// </example>
		/// <returns>当断开连接时额外的操作结果</returns>
		protected virtual OResult ExtraOnDisconnect(Socket socket)
		{
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 和服务器交互完成的时候调用的方法，可以根据读写结果进行一些额外的操作，具体的操作需要根据实际的需求来重写实现<br />
		/// The method called when the interaction with the server is completed can perform some additional operations based on the read and write results. 
		/// The specific operations need to be rewritten according to actual needs.
		/// </summary>
		/// <param name="read">读取结果</param>
		protected virtual void ExtraAfterReadFromCoreServer(OResult read)
		{
		}

		/// <summary>
		/// 设置当前的登录的账户名和密码信息，并启用账户验证的功能，账户名为空时设置不生效<br />
		/// Set the current login account name and password information, and enable the account verification function. The account name setting will not take effect when it is empty
		/// </summary>
		/// <remarks>
		/// 当对方的服务器是使用Snet.Driver创建的虚拟服务器时，例如modbus服务器，西门子s7服务器等等，就支持进行账户名验证操作，此时的客户端连接之前，就需要调用本方法设置账户密码信息。<br />
		/// When the other party's server is a virtual server created by Snet.Driver, such as modbus server, Siemens s7 server, etc., 
		/// it supports account name verification operation. At this time, before the client connects, you need to call this method to set account password information.
		/// </remarks>
		/// <param name="userName">账户名</param>
		/// <param name="password">密码</param>
		public void SetLoginAccount(string userName, string password)
		{
			if (!string.IsNullOrEmpty(userName.Trim()))
			{
				isUseAccountCertificate = true;
				this.userName = userName;
				this.password = password;
			}
			else
			{
				isUseAccountCertificate = false;
			}
		}

		/// <summary>
		/// 认证账号，根据已经设置的用户名和密码，进行发送服务器进行账号认证。<br />
		/// Authentication account, according to the user name and password that have been set, sending server for account authentication.
		/// </summary>
		/// <param name="socket">套接字</param>
		/// <returns>认证结果</returns>
		protected OResult AccountCertificate(Socket socket)
		{
			OResult oResult = SendAccountAndCheckReceive(socket, 1, userName, password);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<int, string[]> oResult2 = ReceiveStringArrayContentFromSocket(socket);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (oResult2.Content1 == 0)
			{
				return new OResult(oResult2.Content2[0]);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.AccountCertificate(System.Net.Sockets.Socket)" />
		protected async Task<OResult> AccountCertificateAsync(Socket socket)
		{
			OResult oResult = await SendAccountAndCheckReceiveAsync(socket, 1, userName, password).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			OResult<int, string[]> oResult2 = await ReceiveStringArrayContentFromSocketAsync(socket).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			if (oResult2.Content1 == 0)
			{
				return new OResult(oResult2.Content2[0]);
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.InitializationOnConnect(System.Net.Sockets.Socket)" />
		protected virtual async Task<OResult> InitializationOnConnectAsync(Socket socket)
		{
			if (useServerActivePush)
			{
				OResult oResult = socket.BeginReceiveResult(ServerSocketActivePushAsync);
				if (!oResult.IsSuccess)
				{
					return oResult;
				}
			}
			return await Task.FromResult(OResult.CreateSuccessResult()).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.ExtraOnDisconnect(System.Net.Sockets.Socket)" />
		protected virtual async Task<OResult> ExtraOnDisconnectAsync(Socket socket)
		{
			return await Task.FromResult(OResult.CreateSuccessResult());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.CreateSocketAndInitialication" />
		private async Task<OResult<Socket>> CreateSocketAndInitialicationAsync()
		{
			OResult<Socket> oResult = ((mqttClient == null) ? (await CreateSocketAndConnectAsync(pipeSocket.GetConnectIPEndPoint(), ConnectTimeOut, LocalBinding).ConfigureAwait(continueOnCapturedContext: false)) : OResult.CreateSuccessResult(pipeSocket.Socket));
			OResult<Socket> oResult2 = oResult;
			OResult<Socket> result = oResult2;
			if (result.IsSuccess)
			{
				OResult oResult3 = await InitializationOnConnectAsync(result.Content).ConfigureAwait(continueOnCapturedContext: false);
				if (!oResult3.IsSuccess)
				{
					result.Content?.Close();
					result.IsSuccess = oResult3.IsSuccess;
					result.CopyErrorFromOther(oResult3);
				}
			}
			return result;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.GetAvailableSocket" />
		protected async Task<OResult<Socket>> GetAvailableSocketAsync()
		{
			if (isPersistentConn)
			{
				if (isUseSpecifiedSocket)
				{
					if (pipeSocket.IsSocketError)
					{
						return new OResult<Socket>(StringResources.Language.ConnectionIsNotAvailable);
					}
					return OResult.CreateSuccessResult(pipeSocket.Socket);
				}
				if ((mqttClient == null) ? pipeSocket.IsConnectitonError() : pipeSocket.IsSocketError)
				{
					OResult oResult = await ConnectServerAsync().ConfigureAwait(continueOnCapturedContext: false);
					if (!oResult.IsSuccess)
					{
						pipeSocket.IsSocketError = true;
						return OResult.CreateFailedResult<Socket>(oResult);
					}
					pipeSocket.IsSocketError = false;
					return OResult.CreateSuccessResult(pipeSocket.Socket);
				}
				return OResult.CreateSuccessResult(pipeSocket.Socket);
			}
			return await CreateSocketAndInitialicationAsync().ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.ConnectServer" />
		public async Task<OResult> ConnectServerAsync()
		{
			isPersistentConn = true;
			pipeSocket.Socket?.Close();
			OResult<Socket> oResult = await CreateSocketAndInitialicationAsync().ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				pipeSocket.IsSocketError = true;
				oResult.Content = null;
				return oResult;
			}
			pipeSocket.Socket = oResult.Content;
			if (SocketKeepAliveTime > 0)
			{
				oResult.Content.SetKeepAlive(SocketKeepAliveTime, SocketKeepAliveTime);
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.ConnectedSuccess);
			return oResult;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.ConnectClose" />
		public async Task<OResult> ConnectCloseAsync()
		{
			new OResult();
			isPersistentConn = false;
			OResult result;
			try
			{
				result = await ExtraOnDisconnectAsync(pipeSocket.Socket).ConfigureAwait(continueOnCapturedContext: false);
				if (mqttClient == null)
				{
					pipeSocket.Socket?.Close();
					pipeSocket.Socket = null;
				}
			}
			catch
			{
				throw;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Close);
			return result;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.ReadFromCoreServer(System.Net.Sockets.Socket,System.Byte[],System.Boolean,System.Boolean)" />
		public virtual async Task<OResult<byte[]>> ReadFromCoreServerAsync(Socket socket, byte[] send, bool hasResponseData = true, bool usePackAndUnpack = true)
		{
			byte[] sendValue = (usePackAndUnpack ? PackCommandWithHeader(send) : send);
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Send + " : " + (LogMsgFormatBinary ? sendValue.ToHexString(' ') : SoftBasic.GetAsciiStringRender(sendValue)));
			INetMessage netMessage = GetNewNetMessage();
			if (netMessage != null)
			{
				netMessage.SendBytes = sendValue;
			}
			if (sendbyteBefore != null)
			{
				await SendAsync(socket, sendbyteBefore).ConfigureAwait(continueOnCapturedContext: false);
			}
			OResult oResult = await SendAsync(socket, sendValue).ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (ReceiveTimeOut < 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (!hasResponseData)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (SleepTime > 0)
			{
				SnetHelper.ThreadSleep(SleepTime);
			}
			OResult<byte[]> oResult2;
			if (useServerActivePush)
			{
				if (!(await Task.Run(() => autoResetEvent.WaitOne(ReceiveTimeOut)).ConfigureAwait(continueOnCapturedContext: false)))
				{
					NetSupport.CloseSocket(socket);
					pipeSocket.IsSocketError = true;
					return new OResult<byte[]>(-10000, StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut);
				}
				netMessage.HeadBytes = bufferQA;
				oResult2 = OResult.CreateSuccessResult(bufferQA);
			}
			else if (mqttClient != null)
			{
				MemoryStream ms = new MemoryStream();
				while (true)
				{
					if (await Task.Run(() => autoResetEvent.WaitOne(ReceiveTimeOut)).ConfigureAwait(continueOnCapturedContext: false))
					{
						byte[] array = bufferQA;
						if (array != null && array.Length != 0)
						{
							ms.Write(bufferQA);
						}
						if (netMessage == null)
						{
							break;
						}
						if (ms.Length < netMessage.ProtocolHeadBytesLength)
						{
							continue;
						}
						if (netMessage.HeadBytes == null)
						{
							byte[] array2 = ms.ToArray();
							int num = netMessage.PependedUselesByteLength(array2);
							if (num > 0)
							{
								ms = new MemoryStream();
								ms.Write(array2.RemoveBegin(num));
								if (ms.Length < netMessage.ProtocolHeadBytesLength)
								{
									continue;
								}
							}
							netMessage.HeadBytes = ms.ToArray().SelectBegin(netMessage.ProtocolHeadBytesLength);
						}
						int contentLengthByHeadBytes = netMessage.GetContentLengthByHeadBytes();
						if (ms.Length >= netMessage.ProtocolHeadBytesLength + contentLengthByHeadBytes)
						{
							break;
						}
						continue;
					}
					return new OResult<byte[]>(-10000, StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut);
				}
				oResult2 = OResult.CreateSuccessResult(ms.ToArray());
			}
			else if (netMessage == null)
			{
				DateTime startTime = DateTime.Now;
				MemoryStream ms = new MemoryStream();
				while (true)
				{
					OResult<byte[]> oResult3 = await ReceiveByMessageAsync(socket, ReceiveTimeOut, netMessage).ConfigureAwait(continueOnCapturedContext: false);
					if (!oResult3.IsSuccess)
					{
						return oResult3;
					}
					ms.Write(oResult3.Content);
					if (CheckReceiveDataComplete(sendValue, ms))
					{
						oResult2 = OResult.CreateSuccessResult(ms.ToArray());
						break;
					}
					if (ReceiveTimeOut > 0 && (DateTime.Now - startTime).TotalMilliseconds > (double)ReceiveTimeOut)
					{
						oResult2 = new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut);
						break;
					}
				}
			}
			else
			{
				oResult2 = await ReceiveByMessageAsync(socket, ReceiveTimeOut, netMessage).ConfigureAwait(continueOnCapturedContext: false);
			}
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Receive + " : " + (LogMsgFormatBinary ? oResult2.Content.ToHexString(' ') : SoftBasic.GetAsciiStringRender(oResult2.Content)));
			if (netMessage != null && !netMessage.CheckHeadBytesLegal(base.Token.ToByteArray()))
			{
				if (mqttClient == null)
				{
					NetSupport.CloseSocket(socket);
				}
				return new OResult<byte[]>(StringResources.Language.CommandHeadCodeCheckFailed + Environment.NewLine + StringResources.Language.Send + ": " + SoftBasic.ByteToHexString(sendValue, ' ') + Environment.NewLine + StringResources.Language.Receive + ": " + SoftBasic.ByteToHexString(oResult2.Content, ' '));
			}
			return (OResult<byte[]>)(usePackAndUnpack ? ((OResult)UnpackResponseContent(sendValue, oResult2.Content)) : ((OResult)oResult2));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.ReadFromCoreServer(System.Byte[],System.Boolean,System.Boolean)" />
		public virtual async Task<OResult<byte[]>> ReadFromCoreServerAsync(byte[] send)
		{
			return await ReadFromCoreServerAsync(send, hasResponseData: true).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.ReadFromCoreServer(System.Collections.Generic.IEnumerable{System.Byte[]})" />
		public async Task<OResult<byte[]>> ReadFromCoreServerAsync(IEnumerable<byte[]> send)
		{
			return await NetSupport.ReadFromCoreServerAsync(send, ReadFromCoreServerAsync).ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.ReadFromCoreServer(System.Byte[],System.Boolean,System.Boolean)" />
		public async Task<OResult<byte[]>> ReadFromCoreServerAsync(byte[] send, bool hasResponseData, bool usePackAndUnpack = true)
		{
			if (pipeSocket.LockingTick > SnetHelper.LockLimit)
			{
				return new OResult<byte[]>(StringResources.Language.TooManyLock);
			}
			OResult<byte[]> result = new OResult<byte[]>();
			if (SnetHelper.UseAsyncLock)
			{
				await Task.Run(delegate
				{
					pipeSocket.PipeLockEnter();
				}).ConfigureAwait(continueOnCapturedContext: false);
			}
			else
			{
				pipeSocket.PipeLockEnter();
			}
			OResult<Socket> resultSocket;
			try
			{
				resultSocket = await GetAvailableSocketAsync().ConfigureAwait(continueOnCapturedContext: false);
				if (!resultSocket.IsSuccess)
				{
					pipeSocket.IsSocketError = true;
					AlienSession?.Offline();
					pipeSocket.PipeLockLeave();
					result.CopyErrorFromOther(resultSocket);
					return result;
				}
				OResult<byte[]> oResult = await ReadFromCoreServerAsync(resultSocket.Content, send, hasResponseData, usePackAndUnpack).ConfigureAwait(continueOnCapturedContext: false);
				if (oResult.IsSuccess)
				{
					pipeSocket.IsSocketError = false;
					result.IsSuccess = oResult.IsSuccess;
					result.Content = oResult.Content;
					result.Message = StringResources.Language.SuccessText;
				}
				else
				{
					if (oResult.ErrorCode != int.MinValue)
					{
						pipeSocket.IsSocketError = true;
						AlienSession?.Offline();
					}
					else
					{
						oResult.ErrorCode = 10000;
					}
					result.CopyErrorFromOther(oResult);
				}
				ExtraAfterReadFromCoreServer(oResult);
				pipeSocket.PipeLockLeave();
			}
			catch
			{
				pipeSocket.PipeLockLeave();
				throw;
			}
			if (!isPersistentConn)
			{
				resultSocket?.Content?.Close();
			}
			return result;
		}

		/// <summary>
		/// 检查当前从网口接收的数据是否是完整的，如果是完整的，则需要返回 <c>True</c>，表示数据接收立即完成，默认返回 <c>True</c><br />
		/// Check whether the data currently received from the network port is complete, and if it is complete, 
		/// you need to return <c>True</c>, indicating that the data reception is completed immediately, and the default value is <c>True</c>
		/// </summary>
		/// <remarks>
		/// 在默认情况下，网口在接收数据之后，直接认为本次的数据接收已经完成，如果碰到有结束标记的协议，则可以重写本方法，然后加入额外的验证信息，直到全部数据接收完成。<br />
		/// By default, after receiving data, the network port directly believes that the data reception has been completed, 
		/// if it encounters a protocol with an end tag, you can override this method, and then add additional verification information until all data is received.
		/// </remarks>
		/// <param name="send">当前发送的数据信息</param>
		/// <param name="ms">目前已经接收到数据流</param>
		/// <returns>如果数据接收完成，则返回True, 否则返回False</returns>
		protected virtual bool CheckReceiveDataComplete(byte[] send, MemoryStream ms)
		{
			return true;
		}

		/// <summary>
		/// 对当前的命令进行打包处理，通常是携带命令头内容，标记当前的命令的长度信息，需要进行重写，否则默认不打包<br />
		/// The current command is packaged, usually carrying the content of the command header, marking the length of the current command, 
		/// and it needs to be rewritten, otherwise it is not packaged by default
		/// </summary>
		/// <remarks>
		/// 对发送的命令打包之后，直接发送给真实的对方设备了，例如在AB-PLC里面，就重写了打包方法，将当前的会话ID参数传递给PLC设备<br />
		/// After packaging the sent command, it is directly sent to the real counterpart device. For example, in AB-PLC, 
		/// the packaging method is rewritten and the current session ID parameter is passed to the PLC device.
		/// </remarks>
		/// <param name="command">发送的数据命令内容</param>
		/// <returns>打包之后的数据结果信息</returns>
		public virtual byte[] PackCommandWithHeader(byte[] command)
		{
			return command;
		}

		/// <summary>
		/// 根据对方返回的报文命令，对命令进行基本的拆包，例如各种Modbus协议拆包为统一的核心报文，还支持对报文的验证<br />
		/// According to the message command returned by the other party, the command is basically unpacked, for example, 
		/// various Modbus protocols are unpacked into a unified core message, and the verification of the message is also supported
		/// </summary>
		/// <remarks>
		/// 在实际解包的操作过程中，通常对状态码，错误码等消息进行判断，如果校验不通过，将携带错误消息返回<br />
		/// During the actual unpacking operation, the status code, error code and other messages are usually judged. If the verification fails, the error message will be returned.
		/// </remarks>
		/// <param name="send">发送的原始报文数据</param>
		/// <param name="response">设备方反馈的原始报文内容</param>
		/// <returns>返回拆包之后的报文信息，默认不进行任何的拆包操作</returns>
		public virtual OResult<byte[]> UnpackResponseContent(byte[] send, byte[] response)
		{
			return OResult.CreateSuccessResult(response);
		}

		/// <summary>
		/// 获取本次操作的可用的网络通道，如果是短连接，就重新生成一个新的网络通道，如果是长连接，就复用当前的网络通道。<br />
		/// Obtain the available network channels for this operation. If it is a short connection, a new network channel is regenerated. 
		/// If it is a long connection, the current network channel is reused.
		/// </summary>
		/// <returns>是否成功，如果成功，使用这个套接字</returns>
		protected OResult<Socket> GetAvailableSocket()
		{
			if (isPersistentConn)
			{
				if (isUseSpecifiedSocket)
				{
					if (pipeSocket.IsSocketError)
					{
						return new OResult<Socket>(StringResources.Language.ConnectionIsNotAvailable);
					}
					return OResult.CreateSuccessResult(pipeSocket.Socket);
				}
				if ((mqttClient == null) ? pipeSocket.IsConnectitonError() : pipeSocket.IsSocketError)
				{
					OResult oResult = ConnectServer();
					if (!oResult.IsSuccess)
					{
						pipeSocket.IsSocketError = true;
						return OResult.CreateFailedResult<Socket>(oResult);
					}
					pipeSocket.IsSocketError = false;
					return OResult.CreateSuccessResult(pipeSocket.Socket);
				}
				return OResult.CreateSuccessResult(pipeSocket.Socket);
			}
			return CreateSocketAndInitialication();
		}

		/// <summary>
		/// 尝试连接服务器，如果成功，并执行<see cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.InitializationOnConnect(System.Net.Sockets.Socket)" />的初始化方法，并返回最终的结果。<br />
		/// Attempt to connect to the server, if successful, and execute the initialization method of <see cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.InitializationOnConnect(System.Net.Sockets.Socket)" />, and return the final result.
		/// </summary>
		/// <returns>带有socket的结果对象</returns>
		private OResult<Socket> CreateSocketAndInitialication()
		{
			OResult<Socket> oResult = (OResult<Socket>)((mqttClient == null) ? ((OResult)CreateSocketAndConnect(pipeSocket.GetConnectIPEndPoint(), ConnectTimeOut, LocalBinding)) : ((OResult)OResult.CreateSuccessResult(pipeSocket.Socket)));
			if (oResult.IsSuccess)
			{
				OResult oResult2 = InitializationOnConnect(oResult.Content);
				if (!oResult2.IsSuccess)
				{
					oResult.Content?.Close();
					oResult.IsSuccess = oResult2.IsSuccess;
					oResult.CopyErrorFromOther(oResult2);
				}
			}
			return oResult;
		}

		/// <summary>
		/// 将数据报文发送指定的网络通道上，根据当前指定的<see cref="T:Snet.Driver.Core.IMessage.INetMessage" />类型，返回一条完整的数据指令<br />
		/// Sends a data message to the specified network channel, and returns a complete data command according to the currently specified <see cref="T:Snet.Driver.Core.IMessage.INetMessage" /> type
		/// </summary>
		/// <param name="socket">指定的套接字</param>
		/// <param name="send">发送的完整的报文信息</param>
		/// <param name="hasResponseData">是否有等待的数据返回，默认为 true</param>
		/// <param name="usePackAndUnpack">是否需要对命令重新打包，在重写<see cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.PackCommandWithHeader(System.Byte[])" />方法后才会有影响</param>
		/// <remarks>
		/// 无锁的基于套接字直接进行叠加协议的操作。
		/// </remarks>
		/// <example>
		/// 假设你有一个自己的socket连接了设备，本组件可以直接基于该socket实现modbus读取，三菱读取，西门子读取等等操作，前提是该服务器支持多协议，虽然这个需求听上去比较变态，但本组件支持这样的操作。
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="ReadFromCoreServerExample1" title="ReadFromCoreServer示例" />
		/// </example>
		/// <returns>接收的完整的报文信息</returns>
		public virtual OResult<byte[]> ReadFromCoreServer(Socket socket, byte[] send, bool hasResponseData = true, bool usePackAndUnpack = true)
		{
			byte[] array = (usePackAndUnpack ? PackCommandWithHeader(send) : send);
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Send + " : " + (LogMsgFormatBinary ? array.ToHexString(' ') : SoftBasic.GetAsciiStringRender(array)));
			INetMessage newNetMessage = GetNewNetMessage();
			if (newNetMessage != null)
			{
				newNetMessage.SendBytes = array;
			}
			if (sendbyteBefore != null)
			{
				Send(socket, sendbyteBefore);
			}
			OResult oResult = Send(socket, array);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<byte[]>(oResult);
			}
			if (ReceiveTimeOut < 0)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (!hasResponseData)
			{
				return OResult.CreateSuccessResult(new byte[0]);
			}
			if (SleepTime > 0)
			{
				SnetHelper.ThreadSleep(SleepTime);
			}
			OResult<byte[]> oResult2 = null;
			if (useServerActivePush)
			{
				if (!autoResetEvent.WaitOne(ReceiveTimeOut))
				{
					NetSupport.CloseSocket(socket);
					pipeSocket.IsSocketError = true;
					return new OResult<byte[]>(-10000, StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut);
				}
				newNetMessage.HeadBytes = bufferQA;
				oResult2 = OResult.CreateSuccessResult(bufferQA);
			}
			else if (mqttClient != null)
			{
				MemoryStream memoryStream = new MemoryStream();
				while (true)
				{
					if (autoResetEvent.WaitOne(ReceiveTimeOut))
					{
						byte[] array2 = bufferQA;
						if (array2 != null && array2.Length != 0)
						{
							memoryStream.Write(bufferQA);
						}
						if (newNetMessage == null)
						{
							break;
						}
						if (memoryStream.Length < newNetMessage.ProtocolHeadBytesLength)
						{
							continue;
						}
						if (newNetMessage.HeadBytes == null)
						{
							byte[] array3 = memoryStream.ToArray();
							int num = newNetMessage.PependedUselesByteLength(array3);
							if (num > 0)
							{
								memoryStream = new MemoryStream();
								memoryStream.Write(array3.RemoveBegin(num));
								if (memoryStream.Length < newNetMessage.ProtocolHeadBytesLength)
								{
									continue;
								}
							}
							newNetMessage.HeadBytes = memoryStream.ToArray().SelectBegin(newNetMessage.ProtocolHeadBytesLength);
						}
						int contentLengthByHeadBytes = newNetMessage.GetContentLengthByHeadBytes();
						if (memoryStream.Length >= newNetMessage.ProtocolHeadBytesLength + contentLengthByHeadBytes)
						{
							break;
						}
						continue;
					}
					return new OResult<byte[]>(-10000, StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut);
				}
				oResult2 = OResult.CreateSuccessResult(memoryStream.ToArray());
			}
			else if (newNetMessage == null)
			{
				DateTime now = DateTime.Now;
				MemoryStream memoryStream2 = new MemoryStream();
				while (true)
				{
					OResult<byte[]> oResult3 = ReceiveByMessage(socket, ReceiveTimeOut, newNetMessage);
					if (!oResult3.IsSuccess)
					{
						return oResult3;
					}
					memoryStream2.Write(oResult3.Content);
					if (CheckReceiveDataComplete(array, memoryStream2))
					{
						oResult2 = OResult.CreateSuccessResult(memoryStream2.ToArray());
						break;
					}
					if (ReceiveTimeOut > 0 && (DateTime.Now - now).TotalMilliseconds > (double)ReceiveTimeOut)
					{
						oResult2 = new OResult<byte[]>(StringResources.Language.ReceiveDataTimeout + ReceiveTimeOut);
						break;
					}
				}
			}
			else
			{
				oResult2 = ReceiveByMessage(socket, ReceiveTimeOut, newNetMessage);
			}
			if (!oResult2.IsSuccess)
			{
				return oResult2;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Receive + " : " + (LogMsgFormatBinary ? oResult2.Content.ToHexString(' ') : SoftBasic.GetAsciiStringRender(oResult2.Content)));
			if (newNetMessage != null && !newNetMessage.CheckHeadBytesLegal(base.Token.ToByteArray()))
			{
				if (mqttClient == null)
				{
					NetSupport.CloseSocket(socket);
				}
				return new OResult<byte[]>(StringResources.Language.CommandHeadCodeCheckFailed + Environment.NewLine + StringResources.Language.Send + ": " + SoftBasic.ByteToHexString(array, ' ') + Environment.NewLine + StringResources.Language.Receive + ": " + SoftBasic.ByteToHexString(oResult2.Content, ' '));
			}
			if (!usePackAndUnpack)
			{
				return OResult.CreateSuccessResult(oResult2.Content);
			}
			return UnpackResponseContent(array, oResult2.Content);
		}

