		/// <summary>
		/// 将数据发送到当前的网络通道中，并从网络通道中接收一个<see cref="T:Snet.Driver.Core.IMessage.INetMessage" />指定的完整的报文，网络通道将根据<see cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.GetAvailableSocket" />方法自动获取，本方法是线程安全的。<br />
		/// Send data to the current network channel and receive a complete message specified by <see cref="T:Snet.Driver.Core.IMessage.INetMessage" /> from the network channel. 
		/// The network channel will be automatically obtained according to the <see cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.GetAvailableSocket" /> method This method is thread-safe.
		/// </summary>
		/// <param name="send">发送的完整的报文信息</param>
		/// <param name="hasResponseData">是否有等待的数据返回，默认为 true</param>
		/// <param name="usePackAndUnpack">是否需要对命令重新打包，在重写<see cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.PackCommandWithHeader(System.Byte[])" />方法后才会有影响</param>
		/// <returns>接收的完整的报文信息</returns>
		/// <remarks>
		/// 本方法用于实现本组件还未实现的一些报文功能，例如有些modbus服务器会有一些特殊的功能码支持，需要收发特殊的报文，详细请看示例
		/// </remarks>
		/// <example>
		/// 此处举例有个modbus服务器，有个特殊的功能码0x09，后面携带子数据0x01即可，发送字节为 0x00 0x00 0x00 0x00 0x00 0x03 0x01 0x09 0x01
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="ReadFromCoreServerExample2" title="ReadFromCoreServer示例" />
		/// </example>
		public OResult<byte[]> ReadFromCoreServer(byte[] send, bool hasResponseData, bool usePackAndUnpack = true)
		{
			if (pipeSocket.LockingTick > SnetHelper.LockLimit)
			{
				return new OResult<byte[]>(StringResources.Language.TooManyLock);
			}
			OResult<byte[]> oResult = new OResult<byte[]>();
			OResult<Socket> oResult2 = null;
			pipeSocket.PipeLockEnter();
			try
			{
				oResult2 = GetAvailableSocket();
				if (!oResult2.IsSuccess)
				{
					pipeSocket.IsSocketError = true;
					AlienSession?.Offline();
					pipeSocket.PipeLockLeave();
					oResult.CopyErrorFromOther(oResult2);
					return oResult;
				}
				OResult<byte[]> oResult3 = ReadFromCoreServer(oResult2.Content, send, hasResponseData, usePackAndUnpack);
				if (oResult3.IsSuccess)
				{
					pipeSocket.IsSocketError = false;
					oResult.IsSuccess = oResult3.IsSuccess;
					oResult.Content = oResult3.Content;
					oResult.Message = StringResources.Language.SuccessText;
				}
				else
				{
					if (oResult3.ErrorCode != int.MinValue)
					{
						pipeSocket.IsSocketError = true;
						AlienSession?.Offline();
					}
					else
					{
						oResult3.ErrorCode = 10000;
					}
					oResult.CopyErrorFromOther(oResult3);
				}
				ExtraAfterReadFromCoreServer(oResult3);
				pipeSocket.PipeLockLeave();
			}
			catch
			{
				pipeSocket.PipeLockLeave();
				throw;
			}
			if (!isPersistentConn)
			{
				oResult2?.Content?.Close();
			}
			return oResult;
		}

		/// <summary>
		/// 释放当前的资源，并自动关闭长连接，如果设置了的话
		/// </summary>
		/// <param name="disposing">是否释放托管的资源信息</param>
		protected virtual void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				if (disposing)
				{
					ConnectClose();
				}
				disposedValue = true;
			}
		}

