			: base(ipAddress, port)
		{
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkWebApiBase.#ctor(System.String,System.Int32,System.String,System.String)" />
		public NetworkWebApiRobotBase(string ipAddress, int port, string name, string password)
			: base(ipAddress, port, name, password)
