		}

		/// <summary>
		/// 等待重写的额外的指令信息的支持。除了url的形式之外，还支持基于命令的数据交互<br />
		/// Additional instruction information waiting for rewriting is supported.In addition to the url format, command based data interaction is supported
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <returns>是否读取成功的内容</returns>
		protected virtual OResult<string> ReadByAddress(string address)
		{
			return new OResult<string>(StringResources.Language.NotSupportedFunction);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkWebApiRobotBase.ReadByAddress(System.String)" />
		protected virtual async Task<OResult<string>> ReadByAddressAsync(string address)
