		/// <returns>是否发送成功</returns>
		protected OResult SendFileStreamToSocket(Socket socket, string filename, long filelength, Action<long, long> report = null)
		{
			try
			{
				OResult result = new OResult();
				using (FileStream stream = new FileStream(filename, FileMode.Open, FileAccess.Read))
				{
					result = SendStreamToSocket(socket, stream, filelength, report, reportByPercent: true);
				}
				return result;
			}
			catch (Exception ex)
			{
				socket?.Close();
				base.LogNet?.WriteException(ToString(), ex);
				return new OResult(ex.Message);
			}
		}

