		/// </summary>
		/// <param name="socket">套接字的网络</param>
		/// <returns>包含文件信息的结果对象</returns>
		protected OResult<FileBaseInfo> ReceiveFileHeadFromSocket(Socket socket)
		{
			OResult<int, string> oResult = ReceiveStringContentFromSocket(socket);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<FileBaseInfo>(oResult);
			}
			if (oResult.Content1 == 0)
			{
				socket?.Close();
				base.LogNet?.WriteWarn(ToString(), StringResources.Language.FileRemoteNotExist);
				return new OResult<FileBaseInfo>(StringResources.Language.FileNotExist);
			}
			OResult<FileBaseInfo> oResult2 = new OResult<FileBaseInfo>
			{
				Content = new FileBaseInfo()
			};
			try
			{
				JObject json = JObject.Parse(oResult.Content2);
				oResult2.Content.Name = SoftBasic.GetValueFromJsonObject(json, "FileName", "");
				oResult2.Content.Size = SoftBasic.GetValueFromJsonObject(json, "FileSize", 0L);
				oResult2.Content.Tag = SoftBasic.GetValueFromJsonObject(json, "FileTag", "");
				oResult2.Content.Upload = SoftBasic.GetValueFromJsonObject(json, "FileUpload", "");
				oResult2.IsSuccess = true;
			}
			catch (Exception ex)
