		/// </summary>
		/// <param name="socket">网络套接字</param>
		/// <param name="savename">接收文件后保存的文件名</param>
		/// <param name="receiveReport">接收进度报告</param>
		/// <returns>包含文件信息的结果对象</returns>
		protected OResult<FileBaseInfo> ReceiveFileFromSocket(Socket socket, string savename, Action<long, long> receiveReport)
		{
			OResult<FileBaseInfo> oResult = ReceiveFileHeadFromSocket(socket);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			try
			{
				OResult oResult2 = null;
				using (FileStream stream = new FileStream(savename, FileMode.Create, FileAccess.Write))
				{
					oResult2 = WriteStreamFromSocket(socket, stream, oResult.Content.Size, receiveReport, reportByPercent: true);
				}
				if (!oResult2.IsSuccess)
				{
					if (File.Exists(savename))
					{
						File.Delete(savename);
					}
					return OResult.CreateFailedResult<FileBaseInfo>(oResult2);
				}
				return oResult;
			}
			catch (Exception ex)
			{
				base.LogNet?.WriteException(ToString(), ex);
				socket?.Close();
				return new OResult<FileBaseInfo>
				{
					Message = ex.Message
				};
			}
		}

