	/// <summary>
	/// 管道会话信息，包含了一个管道对象，管道可以是TCP,UDP，也可以是串口，甚至是其他自定义的。<br />
	/// Pipeline session information, which contains a pipeline object, which can be TCP, UDP, serial port, or even other custom interfaces.
	/// </summary>
	public class PipeSession
	{
		/// <summary>
		/// 获取当前的客户端的上线时间<br />
		/// Get the online time of the current client
		/// </summary>
		public DateTime OnlineTime { get; set; } = DateTime.Now;

		/// <summary>
		/// 获取心跳验证的时间点<br />
		/// Get the time point of heartbeat verification
		/// </summary>
		public DateTime HeartTime { get; set; } = DateTime.Now;

		/// <summary>
		/// 当前会话绑定的自定义的对象内容<br />
		/// The content of the custom object bound to the current session
		/// </summary>
		public object Tag { get; set; }

		/// <summary>
		/// 当前的会话的管道信息<br />
		/// Pipeline information for the current session
		/// </summary>
		public CommunicationPipe Communication { get; set; }

		/// <summary>
		/// 获取或设置当前会话的ID信息，某些特殊的会话需要用到该字段<br />
		/// Obtain or set the ID information of the current session, which is required for some special sessions
		/// </summary>
		public string SessionID { get; set; }

		/// <summary>
		/// 关闭当前的会话状态<br />
		/// Close the current session state
		/// </summary>
		public virtual void Close()
		{
			Communication?.CloseCommunication();
		}

		/// <inheritdoc />
		public override string ToString()
		{
			if (Communication == null)
			{
				return "Session<NULL>";
			}
			return $"Session<{Communication}>";
		}
	}
	/// <summary>
	/// 读写网络的辅助类
	/// </summary>
	public class ReadWriteNetHelper
	{
		/// <summary>
		/// 写入位到字寄存器的功能，该功能先读取字寄存器的字数据，然后修改其中的位，再写入回去，可能存在脏数据的风险<br />
		/// The function of writing bit-to-word registers, which first reads the word data of the word register, then modifies the bits in it, and then writes back, which may be the risk of dirty data
		/// </summary>
		/// <remarks>
		/// 关于脏数据风险：从读取数据，修改位，再次写入数据时，大概需要经过3ms~10ms不等的时间，如果此期间内PLC修改了该字寄存器的其他位，再次写入数据时会恢复该点位的数据到读取时的初始值，可能引发设备故障，请谨慎开启此功能。
		/// </remarks>
		/// <param name="readWrite">通信对象信息</param>
		/// <param name="address">写入的地址信息，需要携带'.'号</param>
		/// <param name="values">写入的值信息</param>
		/// <param name="addLength">多少长度的bit位组成一个字地址信息</param>
		/// <param name="reverseWord">对原始数据是否按照字单位进行反转操作</param>
		/// <param name="bitStr">额外指定的位索引，如果为空，则使用<paramref name="address" />中的地址位偏移信息</param>
		/// <returns>是否写入成功</returns>
		public static OResult WriteBoolWithWord(IReadWriteNet readWrite, string address, bool[] values, int addLength = 16, bool reverseWord = false, string bitStr = null)
		{
			string[] array = address.SplitDot();
			int num = 0;
			try
			{
				if (string.IsNullOrEmpty(bitStr))
				{
					if (array.Length > 1)
					{
						num = Convert.ToInt32(array[1]);
					}
				}
				else
				{
					num = Convert.ToInt32(bitStr);
				}
			}
			catch (Exception ex)
			{
				return new OResult(address + " Bit index input wrong: " + ex.Message);
			}
			ushort length = (ushort)((num + values.Length + addLength - 1) / addLength);
			OResult<byte[]> oResult = readWrite.Read(array[0], length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			bool[] array2 = (reverseWord ? oResult.Content.ReverseByWord().ToBoolArray() : oResult.Content.ToBoolArray());
			if (num + values.Length <= array2.Length)
			{
				values.CopyTo(array2, num);
			}
			return readWrite.Write(array[0], reverseWord ? array2.ToByteArray().ReverseByWord() : array2.ToByteArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.ReadWriteNetHelper.WriteBoolWithWord(Snet.Driver.Core.IReadWriteNet,System.String,System.Boolean[],System.Int32,System.Boolean,System.String)" />
		public static async Task<OResult> WriteBoolWithWordAsync(IReadWriteNet readWrite, string address, bool[] values, int addLength = 16, bool reverseWord = false, string bitStr = null)
		{
			string[] adds = address.SplitDot();
			int bit = 0;
			try
			{
				if (string.IsNullOrEmpty(bitStr))
				{
					if (adds.Length > 1)
					{
						bit = Convert.ToInt32(adds[1]);
					}
				}
				else
				{
					bit = Convert.ToInt32(bitStr);
				}
			}
			catch (Exception ex)
			{
				return new OResult(address + " Bit index input wrong: " + ex.Message);
			}
			OResult<byte[]> oResult = await readWrite.ReadAsync(length: (ushort)((bit + values.Length + addLength - 1) / addLength), address: adds[0]);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<bool[]>(oResult);
			}
			bool[] array = (reverseWord ? oResult.Content.ReverseByWord().ToBoolArray() : oResult.Content.ToBoolArray());
			if (bit + values.Length <= array.Length)
			{
				values.CopyTo(array, bit);
			}
			return await readWrite.WriteAsync(adds[0], reverseWord ? array.ToByteArray().ReverseByWord() : array.ToByteArray());
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.Wait(System.String,System.Boolean,System.Int32,System.Int32)" />
		/// <param name="readWriteNet">通信对象</param>
		public static OResult<TimeSpan> Wait(IReadWriteNet readWriteNet, string address, bool waitValue, int readInterval, int waitTimeout)
		{
			DateTime now = DateTime.Now;
			while (true)
			{
				OResult<bool> oResult = readWriteNet.ReadBool(address);
				if (!oResult.IsSuccess)
				{
					return OResult.CreateFailedResult<TimeSpan>(oResult);
				}
				if (oResult.Content == waitValue)
				{
					return OResult.CreateSuccessResult(DateTime.Now - now);
				}
				if (waitTimeout > 0 && (DateTime.Now - now).TotalMilliseconds > (double)waitTimeout)
				{
					break;
				}
				SnetHelper.ThreadSleep(readInterval);
			}
			return new OResult<TimeSpan>(StringResources.Language.CheckDataTimeout + waitTimeout);
		}

