		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadCustomer``1(System.String)" />
		public static OResult<T> ReadCustomer<T>(IReadWriteNet readWriteNet, string address) where T : IDataTransfer, new()
		{
			T obj = new T();
			return ReadCustomer(readWriteNet, address, obj);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadCustomer``1(System.String,``0)" />
		public static OResult<T> ReadCustomer<T>(IReadWriteNet readWriteNet, string address, T obj) where T : IDataTransfer, new()
		{
			OResult<byte[]> oResult = readWriteNet.Read(address, obj.ReadCount);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<T>(oResult);
			}
			obj.ParseSource(oResult.Content);
			return OResult.CreateSuccessResult(obj);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.WriteCustomer``1(System.String,``0)" />
		public static OResult WriteCustomer<T>(IReadWriteNet readWriteNet, string address, T data) where T : IDataTransfer, new()
		{
			return readWriteNet.Write(address, data.ToSource());
		}

