		/// <inheritdoc cref="M:Snet.Driver.Core.IReadWriteNet.ReadStruct``1(System.String,System.UInt16)" />
		public static OResult<T> ReadStruct<T>(IReadWriteNet readWriteNet, string address, ushort length, IByteTransform byteTransform, int startIndex = 0) where T : class, new()
		{
			OResult<byte[]> oResult = readWriteNet.Read(address, length);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<T>(oResult);
			}
			try
			{
				return OResult.CreateSuccessResult(SnetReflectionHelper.PraseStructContent<T>(oResult.Content, startIndex, byteTransform));
			}
			catch (Exception ex)
			{
				return new OResult<T>("Prase struct faild: " + ex.Message + Environment.NewLine + "Source Data: " + oResult.Content.ToHexString(' '));
			}
		}

