	/// <summary>
	/// 基于TCP、IP通信的类
	/// </summary>
	public class TcpNetCommunication : BinaryCommunication
	{
		private PipeTcpNet pipeTcpNet;

		private Lazy<Ping> ping = new Lazy<Ping>(() => new Ping());

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeTcpNet.ConnectTimeOut" />
		public virtual int ConnectTimeOut
		{
			get
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					return pipeTcpNet.ConnectTimeOut;
				}
				return this.pipeTcpNet.ConnectTimeOut;
			}
			set
			{
				if (value >= 0 && CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					pipeTcpNet.ConnectTimeOut = value;
				}
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeTcpNet.IpAddress" />
		public virtual string IpAddress
		{
			get
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					return pipeTcpNet.IpAddress;
				}
				return this.pipeTcpNet.IpAddress;
			}
			set
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					pipeTcpNet.IpAddress = value;
				}
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeTcpNet.Port" />
		public virtual int Port
		{
			get
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					return pipeTcpNet.Port;
				}
				return this.pipeTcpNet.Port;
			}
			set
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					pipeTcpNet.Port = value;
				}
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeTcpNet.LocalBinding" />
		public IPEndPoint LocalBinding
		{
			get
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					return pipeTcpNet.LocalBinding;
				}
				return this.pipeTcpNet.LocalBinding;
			}
			set
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					pipeTcpNet.LocalBinding = value;
				}
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeTcpNet.SocketKeepAliveTime" />
		public int SocketKeepAliveTime
		{
			get
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					return pipeTcpNet.SocketKeepAliveTime;
				}
				return this.pipeTcpNet.SocketKeepAliveTime;
			}
			set
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					pipeTcpNet.SocketKeepAliveTime = value;
				}
			}
		}

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public TcpNetCommunication()
			: this("127.0.0.1", 5000)
		{
		}

		/// <summary>
		/// 指定IP地址以及端口号信息来初始化对象
		/// </summary>
		/// <param name="ipAddress">IP地址信息，可以是IPv4, IPv6, 也可以是域名</param>
		/// <param name="port">设备方的端口号信息</param>
		public TcpNetCommunication(string ipAddress, int port)
		{
			pipeTcpNet = new PipeTcpNet();
			pipeTcpNet.IpAddress = ipAddress;
			pipeTcpNet.Port = port;
			CommunicationPipe = pipeTcpNet;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceTcpNet.IpAddressPing" />
		public IPStatus IpAddressPing()
		{
			return ping.Value.Send(IpAddress).Status;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Device.DeviceTcpNet.ConnectServer" />
		public OResult ConnectServer()
		{
			CommunicationPipe?.CloseCommunication();
			OResult<bool> oResult = CommunicationPipe.OpenCommunication();
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.ConnectedSuccess);
			if (oResult.Content)
			{
				return InitializationOnConnect();
			}
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.TcpNetCommunication.ConnectServer" />
		public async Task<OResult> ConnectServerAsync()
		{
			await CommunicationPipe.CloseCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
			OResult<bool> oResult = await CommunicationPipe.OpenCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.ConnectedSuccess);
			if (oResult.Content)
			{
				return await InitializationOnConnectAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
			return OResult.CreateSuccessResult();
		}

		/// <summary>
		/// 手动断开与远程服务器的连接，如果当前是长连接模式，那么就会切换到短连接模式<br />
		/// Manually disconnect from the remote server, if it is currently in long connection mode, it will switch to short connection mode
		/// </summary>
		/// <returns>关闭连接，不需要查看IsSuccess属性查看</returns>
		/// <example>
		/// 直接关闭连接即可，基本上是不需要进行成功的判定
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="ConnectCloseExample" title="关闭连接结果" />
		/// </example>
		public OResult ConnectClose()
		{
			OResult oResult = ExtraOnDisconnect();
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Close);
			return CommunicationPipe.CloseCommunication();
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.TcpNetCommunication.ConnectClose" />
		public async Task<OResult> ConnectCloseAsync()
		{
			OResult oResult = await ExtraOnDisconnectAsync().ConfigureAwait(continueOnCapturedContext: false);
			if (!oResult.IsSuccess)
			{
				return oResult;
			}
			base.LogNet?.WriteDebug(ToString(), StringResources.Language.Close);
			return await CommunicationPipe.CloseCommunicationAsync().ConfigureAwait(continueOnCapturedContext: false);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"TcpNetCommunication<{CommunicationPipe}>";
		}
	}
}
namespace Snet.Driver.Core.IMessage
