	/// <summary>
	/// 倍福的ADS协议的信息
	/// </summary>
	public class AdsNetMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 6;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			byte[] headBytes = base.HeadBytes;
			if (headBytes != null && headBytes.Length >= 6)
			{
				int num = BitConverter.ToInt32(base.HeadBytes, 2);
				if (num > 100000000)
				{
					num = 100000000;
				}
				if (num < 0)
				{
					num = 0;
				}
				return num;
			}
			return 0;
		}
	}
	/// <summary>
	/// 异形消息对象，用于异形客户端的注册包接收以及验证使用
	/// </summary>
	public class AlienMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 5;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.CheckHeadBytesLegal(System.Byte[])" />
		public override bool CheckHeadBytesLegal(byte[] token)
		{
			if (base.HeadBytes == null)
			{
				return true;
			}
			if (base.HeadBytes[0] == 72)
			{
				return true;
			}
			return false;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			if (base.HeadBytes[3] >= 48 && base.HeadBytes[3] <= 70 && base.HeadBytes[4] >= 48 && base.HeadBytes[4] <= 70)
			{
				return Convert.ToInt32(Encoding.ASCII.GetString(base.HeadBytes, 3, 2), 16);
			}
			return base.HeadBytes[3] * 256 + base.HeadBytes[4];
		}
	}
	/// <summary>
	/// 用于和 AllenBradley PLC 交互的消息协议类
	/// </summary>
	public class AllenBradleyMessage : NetMessageBase, INetMessage
	{
		private bool contextCheck;

		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 24;

		/// <summary>
		/// 实例化一个默认的 <see cref="T:Snet.Driver.Core.IMessage.AllenBradleyMessage" /> 对象
		/// </summary>
		public AllenBradleyMessage()
		{
		}

		/// <summary>
		/// Initializes a new instance of the <see cref="T:Snet.Driver.Core.IMessage.AllenBradleyMessage" /> class.
		/// </summary>
		/// <param name="contextCheck">A value indicating whether the message should perform a context check. If <see langword="true" />, the message will
		/// validate its context before processing.</param>
		public AllenBradleyMessage(bool contextCheck)
		{
			this.contextCheck = contextCheck;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			return BitConverter.ToUInt16(base.HeadBytes, 2);
		}

		/// <inheritdoc />
		public override int CheckMessageMatch(byte[] send, byte[] receive)
		{
			if (receive == null || receive.Length < 24 || send == null || send.Length < 24)
			{
				return 1;
			}
			if (contextCheck)
			{
				for (int i = 12; i < 20; i++)
				{
					if (receive[i] != send[i])
					{
						return -1;
					}
				}
			}
			return base.CheckMessageMatch(send, receive);
		}
	}
