	/// <summary>
	/// 西门子Fetch/Write消息解析协议
	/// </summary>
	public class FetchWriteMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 16;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			if (base.HeadBytes[5] == 5 || base.HeadBytes[5] == 4)
			{
				return 0;
			}
			if (base.HeadBytes[5] == 6)
			{
				if (base.SendBytes == null)
				{
					return 0;
				}
				if (base.HeadBytes[8] != 0)
				{
					return 0;
				}
				if (base.SendBytes[8] == 1 || base.SendBytes[8] == 6 || base.SendBytes[8] == 7)
				{
					return (base.SendBytes[12] * 256 + base.SendBytes[13]) * 2;
				}
				return base.SendBytes[12] * 256 + base.SendBytes[13];
			}
			if (base.HeadBytes[5] == 3)
			{
				if (base.HeadBytes[8] == 1 || base.HeadBytes[8] == 6 || base.HeadBytes[8] == 7)
				{
					return (base.HeadBytes[12] * 256 + base.HeadBytes[13]) * 2;
				}
				return base.HeadBytes[12] * 256 + base.HeadBytes[13];
			}
			return 0;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.CheckHeadBytesLegal(System.Byte[])" />
		public override bool CheckHeadBytesLegal(byte[] token)
		{
			if (base.HeadBytes == null)
			{
				return false;
			}
			if (base.HeadBytes[0] == 83 && base.HeadBytes[1] == 53)
			{
				return true;
			}
			return false;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetHeadBytesIdentity" />
		public override int GetHeadBytesIdentity()
		{
			return base.HeadBytes[3];
		}
	}
	/// <summary>
	/// 用于欧姆龙通信的Fins协议的消息解析规则
	/// </summary>
	public class FinsMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 16;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			int num = BitConverter.ToInt32(new byte[4]
			{
				base.HeadBytes[7],
				base.HeadBytes[6],
				base.HeadBytes[5],
				base.HeadBytes[4]
			}, 0);
			if (num > 10000)
			{
				num = 10000;
			}
			if (num < 8)
			{
				num = 8;
			}
			return num - 8;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.CheckHeadBytesLegal(System.Byte[])" />
		public override bool CheckHeadBytesLegal(byte[] token)
		{
			if (base.HeadBytes == null)
			{
				return true;
			}
			if (base.HeadBytes[0] == 70 && base.HeadBytes[1] == 73 && base.HeadBytes[2] == 78 && base.HeadBytes[3] == 83)
			{
				return true;
			}
			return false;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.PependedUselesByteLength(System.Byte[])" />
		public override int PependedUselesByteLength(byte[] headByte)
		{
			if (headByte == null)
			{
				return 0;
			}
			for (int i = 0; i < headByte.Length - 3; i++)
			{
				if (headByte[i] == 70 && headByte[i + 1] == 73 && headByte[i + 2] == 78 && headByte[i + 3] == 83)
				{
					return i;
				}
			}
			return base.PependedUselesByteLength(headByte);
		}

		/// <inheritdoc />
		public override int CheckMessageMatch(byte[] send, byte[] receive)
		{
			if (send == null || receive == null)
			{
				return 1;
			}
			if (send.Length > 25 && receive.Length > 25)
			{
				if (send[25] == receive[25])
				{
					return 1;
				}
				return -1;
			}
			return base.CheckMessageMatch(send, receive);
		}
	}
