	/// <summary>
	/// 专门用于接收指定字符结尾的网络消息
	/// </summary>
	public class SpecifiedCharacterMessage : NetMessageBase, INetMessage
	{
		private int protocolHeadBytesLength = -1;

		/// <summary>
		/// 获取或设置在结束字符之后剩余的固定字节长度，有些则还包含两个字节的校验码，这时该值就需要设置为2。<br />
		/// Gets or sets the remaining fixed byte length after the end character, and some also contain a two-byte check code. In this case, the value needs to be set to 2.
		/// </summary>
		public byte EndLength
		{
			get
			{
				return BitConverter.GetBytes(protocolHeadBytesLength)[2];
			}
			set
			{
				byte[] bytes = BitConverter.GetBytes(protocolHeadBytesLength);
				bytes[2] = value;
				protocolHeadBytesLength = BitConverter.ToInt32(bytes, 0);
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => protocolHeadBytesLength;

		/// <summary>
		/// 使用固定的一个字符结尾作为当前的报文接收条件，来实例化一个对象<br />
		/// Instantiate an object using a fixed end of one character as the current message reception condition
		/// </summary>
		/// <param name="endCode">结尾的字符</param>
		public SpecifiedCharacterMessage(byte endCode)
		{
			byte[] array = new byte[4];
			array[3] = (byte)(array[3] | 0x80);
			array[3] = (byte)(array[3] | 1);
			array[1] = endCode;
			protocolHeadBytesLength = BitConverter.ToInt32(array, 0);
		}

		/// <summary>
		/// 使用固定的两个个字符结尾作为当前的报文接收条件，来实例化一个对象<br />
		/// Instantiate an object using a fixed two-character end as the current message reception condition
		/// </summary>
		/// <param name="endCode1">第一个结尾的字符</param>
		/// <param name="endCode2">第二个结尾的字符</param>
		public SpecifiedCharacterMessage(byte endCode1, byte endCode2)
		{
			byte[] array = new byte[4];
			array[3] = (byte)(array[3] | 0x80);
			array[3] = (byte)(array[3] | 2);
			array[1] = endCode1;
			array[0] = endCode2;
			protocolHeadBytesLength = BitConverter.ToInt32(array, 0);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			return 0;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.CheckHeadBytesLegal(System.Byte[])" />
		public override bool CheckHeadBytesLegal(byte[] token)
		{
			return true;
		}
	}
	/// <summary>
	/// 丰田工机的PLC的协议消息
	/// </summary>
	public class ToyoPucMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 4;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			try
			{
				byte[] headBytes = base.HeadBytes;
				if (headBytes != null && headBytes.Length >= 4)
				{
					return BitConverter.ToUInt16(base.HeadBytes, 2);
				}
				return 0;
			}
			catch
			{
				return 0;
			}
		}
	}
	/// <summary>
	/// 图尔克Reader协议的消息
	/// </summary>
	public class TurckReaderMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 3;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.CheckHeadBytesLegal(System.Byte[])" />
		public override bool CheckHeadBytesLegal(byte[] token)
		{
			if (base.HeadBytes == null)
			{
				return true;
			}
			return base.HeadBytes[0] == 170;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			if (base.HeadBytes[2] <= 3)
			{
				return 0;
			}
			int num = base.HeadBytes[2] - 3;
			if (num < 0)
			{
				num = 0;
			}
			return num;
		}

		/// <inheritdoc />
		public override int CheckMessageMatch(byte[] send, byte[] receive)
		{
			if (CheckResponseACK(receive))
			{
				return -1;
			}
			return 1;
		}

		private static bool CheckResponseACK(byte[] content)
		{
			try
			{
				if (content[1] == 7 && content[2] == 7 && (content[3] == 104 || (content[3] == 105 && content[4] == 137) || content[3] == 112 || (content[3] == 105 && content[4] == 129)))
				{
					return true;
				}
			}
			catch
			{
				return false;
			}
			return false;
		}
	}
	/// <summary>
	/// VigorSerial协议的消息类
