		public int ProtocolHeadBytesLength => -1;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			return 0;
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.CheckReceiveDataComplete(System.Byte[],System.IO.MemoryStream)" />
		public override bool CheckReceiveDataComplete(byte[] send, MemoryStream ms)
		{
			byte[] array = ms.ToArray();
			return VigorVsHelper.CheckReceiveDataComplete(array, array.Length);
		}
	}
	/// <summary>
	/// 横河PLC的以太网的二进制协议
	/// </summary>
	public class YokogawaLinkBinaryMessage : NetMessageBase, INetMessage
	{
		/// <inheritdoc cref="P:Snet.Driver.Core.IMessage.INetMessage.ProtocolHeadBytesLength" />
		public int ProtocolHeadBytesLength => 4;

		/// <inheritdoc cref="M:Snet.Driver.Core.IMessage.INetMessage.GetContentLengthByHeadBytes" />
		public int GetContentLengthByHeadBytes()
		{
			return base.HeadBytes[2] * 256 + base.HeadBytes[3];
		}
	}
