	/// <summary>
	/// 所有设备的基类信息
	/// </summary>
	public class DeviceCommunication : BinaryCommunication, IReadWriteDevice, IReadWriteNet, IDisposable
	{
		private bool disposedValue;

		private IByteTransform byteTransform = new RegularByteTransform();

		/// <summary>
		/// 一个字单位的数据表示的地址长度，西门子为2，三菱，欧姆龙，modbusTcp就为1，AB PLC无效<br />
		/// The address length represented by one word of data, Siemens is 2, Mitsubishi, Omron, modbusTcp is 1, AB PLC is invalid
		/// </summary>
		/// <remarks>
		/// 对设备来说，一个地址的数据对应的字节数，或是1个字节或是2个字节，4个字节，通常是这四个选择，当设置为0时，则表示4字节的地址长度信息<br />
		/// For the device, the number of bytes corresponding to the data of an address, either 1 byte or 2 bytes, 4 bytes, usually these four choices, when set to 0, it means 4 words Section address length information
		/// </remarks>
		protected ushort WordLength { get; set; } = 1;

		/// <summary>
		/// 当前的数据变换机制，当你需要从字节数据转换类型数据的时候需要。<br />
		/// The current data transformation mechanism is required when you need to convert type data from byte data.
		/// </summary>
		/// <remarks>
		/// 在Snet里提供了三种数据变换机制，分别是 <see cref="T:Snet.Driver.Core.RegularByteTransform" />, <see cref="T:Snet.Driver.Core.ReverseBytesTransform" />,
		/// <see cref="T:Snet.Driver.Core.ReverseWordTransform" />，各自的<see cref="T:Snet.Driver.Core.DataFormat" />属性也可以自定调整，基本满足所有的情况使用。<br />
		/// Three data transformation mechanisms are provided in Snet, namely <see cref="T:Snet.Driver.Core.RegularByteTransform" />, <see cref="T:Snet.Driver.Core.ReverseBytesTransform" />, 
		/// <see cref="T:Snet.Driver.Core.ReverseWordTransform" />, and their respective <see cref="T:Snet.Driver.Core.DataFormat" /> property can also be adjusted by itself, basically satisfying all situations.
		/// </remarks>
		/// <example>
		/// 主要是用来转换数据类型的，下面仅仅演示了2个方法，其他的类型转换，类似处理。
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\Core\NetworkDoubleBase.cs" region="ByteTransform" title="ByteTransform示例" />
		/// </example>
		public IByteTransform ByteTransform
		{
			get
			{
				return byteTransform;
			}
			set
			{
				byteTransform = value;
			}
		}

		/// <summary>
		/// 默认的无参构造函数 <br />
		/// Default no-parameter constructor
		/// </summary>
		public DeviceCommunication()
		{
		}

		/// <summary>
		/// 一个字单位的数据表示的地址长度，西门子为2，三菱，欧姆龙，modbusTcp就为1，AB PLC无效<br />
		/// The address length represented by one word of data, Siemens is 2, Mitsubishi, Omron, modbusTcp is 1, AB PLC is invalid
		/// </summary>
		/// <remarks>
		/// 对设备来说，一个地址的数据对应的字节数，或是1个字节或是2个字节，通常是这两个选择。<br />
		/// 当前也可以重写来根据不同的地址动态控制不同的地址长度，比如有的地址是一个地址一个字节的，有的地址是一个地址两个字节的
		/// </remarks>
		/// <param name="address">读取的设备的地址信息</param>
		/// <param name="length">读取的数据长度信息</param>
		/// <param name="dataTypeLength">数据类型的字节长度信息，比如short, 就是2，int,float就是4</param>
		protected virtual ushort GetWordLength(string address, int length, int dataTypeLength)
		{
			if (WordLength == 0)
			{
				int num = length * dataTypeLength * 2 / 4;
				return (ushort)((num == 0) ? 1 : ((ushort)num));
			}
			return (ushort)(WordLength * length * dataTypeLength);
		}

		/// <summary>
		/// 根据输入的地址，长度信息构建一个读取数据的报文命令
		/// </summary>
		/// <param name="address">输入的地址</param>
		/// <param name="length">读取的长度信息</param>
		/// <param name="isBit">是否位操作</param>
		/// <returns>等待发送的命令报文</returns>
		protected virtual OResult<List<byte[]>> BuildDeviceReadCommand(string address, ushort length, bool isBit)
		{
			return new OResult<List<byte[]>>(StringResources.Language.NotSupportedFunction);
		}

		/// <summary>
		/// 从返回的数据中提取出读取的数据信息，子类需要重写该方法来支持不同设备的解析规则
		/// </summary>
		/// <param name="content">返回的报文信息</param>
		/// <returns>是否正常的结果数据对象</returns>
		protected virtual OResult<byte[]> ParseDeviceReadResult(byte[] content)
		{
			return new OResult<byte[]>(StringResources.Language.NotSupportedFunction);
		}

