		/// <summary>
		/// 将本系统的数据池数据存储到指定的文件<br />
		/// Store the data pool data of this system to the specified file
		/// </summary>
		/// <param name="path">指定文件的路径</param>
		/// <exception cref="T:System.ArgumentException"></exception>
		/// <exception cref="T:System.ArgumentNullException"></exception>
		/// <exception cref="T:System.IO.PathTooLongException"></exception>
		/// <exception cref="T:System.IO.DirectoryNotFoundException"></exception>
		/// <exception cref="T:System.IO.IOException"></exception>
		/// <exception cref="T:System.UnauthorizedAccessException"></exception>
		/// <exception cref="T:System.NotSupportedException"></exception>
		/// <exception cref="T:System.Security.SecurityException"></exception>
		public void SaveDataPool(string path)
		{
			byte[] bytes = SaveToBytes();
			File.WriteAllBytes(path, bytes);
		}

		/// <summary>
		/// 从文件加载数据池信息<br />
		/// Load datapool information from a file
		/// </summary>
		/// <param name="path">文件路径</param>
		/// <exception cref="T:System.ArgumentException"></exception>
		/// <exception cref="T:System.ArgumentNullException"></exception>
		/// <exception cref="T:System.IO.PathTooLongException"></exception>
		/// <exception cref="T:System.IO.DirectoryNotFoundException"></exception>
		/// <exception cref="T:System.IO.IOException"></exception>
		/// <exception cref="T:System.UnauthorizedAccessException"></exception>
		/// <exception cref="T:System.NotSupportedException"></exception>
		/// <exception cref="T:System.Security.SecurityException"></exception>
		public void LoadDataPool(string path)
		{
			if (File.Exists(path))
			{
				byte[] content = File.ReadAllBytes(path);
				LoadFromBytes(content);
			}
		}

		/// <summary>
		/// 从字节数据加载数据信息，需要进行重写方法<br />
		/// Loading data information from byte data requires rewriting method
		/// </summary>
		/// <param name="content">字节数据</param>
		protected virtual void LoadFromBytes(byte[] content)
		{
		}

		/// <summary>
		/// 将数据信息存储到字节数组去，需要进行重写方法<br />
		/// To store data information into a byte array, a rewrite method is required
		/// </summary>
		/// <returns>所有的内容</returns>
		protected virtual byte[] SaveToBytes()
		{
			return new byte[0];
		}

		/// <summary>
		/// 触发一个数据接收的事件信息<br />
		/// Event information that triggers a data reception
		/// </summary>
		/// <param name="session">管道会话</param>
		/// <param name="receive">接收数据信息</param>
		protected void RaiseDataReceived(PipeSession session, byte[] receive)
		{
			OnDataReceived?.Invoke(this, session, receive);
		}

		/// <summary>
		/// 触发一个数据发送的事件信息<br />
		/// Event information that triggers a data transmission
		/// </summary>
		/// <param name="send">数据内容</param>
		protected void RaiseDataSend(byte[] send)
		{
			OnDataSend?.Invoke(this, send);
		}

		private void Server_OnPipeMessageReceived(PipeSession session, byte[] buffer)
		{
			LogRevcMessage(buffer, session);
			OResult<byte[]> oResult = null;
			try
			{
				oResult = ReadFromCoreServer(session, buffer);
			}
			catch (Exception ex)
			{
				base.LogNet?.WriteException("ReadFromCoreServer", "Source Data: " + buffer.ToHexString(' '), ex);
				return;
			}
			if (!oResult.IsSuccess)
			{
				if (oResult.ErrorCode != int.MinValue)
				{
					base.LogNet?.WriteDebug(ToString(), $"<{session.Communication}> {oResult.Message}");
				}
				if (oResult.Content != null && oResult.Content.Length != 0)
				{
					oResult.IsSuccess = true;
				}
			}
			if (oResult.IsSuccess && oResult.Content != null && oResult.Content.Length != 0)
			{
				session.Communication.Send(oResult.Content);
				RaiseDataSend(oResult.Content);
				LogSendMessage(oResult.Content, session);
			}
			RaiseDataReceived(session, buffer);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.NetworkDoubleBase.ReadFromCoreServer(System.Byte[])" />
		protected virtual OResult<byte[]> ReadFromCoreServer(PipeSession session, byte[] receive)
		{
			return new OResult<byte[]>(StringResources.Language.NotSupportedFunction);
		}

		/// <summary>
		/// 当客户端登录后，在Ip信息的过滤后，然后触发本方法，进行后续的数据接收，处理，并返回相关的数据信息<br />
		/// When the client logs in, after filtering the IP information, this method is then triggered to perform subsequent data reception, 
		/// processing, and return related data information
		/// </summary>
		/// <param name="session">管道信息</param>
		/// <param name="endPoint">终端节点</param>
		protected virtual OResult ThreadPoolLoginAfterClientCheck(PipeSession session, IPEndPoint endPoint)
		{
			return OResult.CreateSuccessResult();
		}

		/// <inheritdoc />
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				OnDataSend = null;
				OnDataReceived = null;
				ServerClose();
			}
			base.Dispose(disposing);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.CommunicationServer.StartSerialSlave(System.String)" />
		public OResult StartSerialSlave(string com)
		{
			return server.StartSerialSlave(com);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.CommunicationServer.StartSerialSlave(System.String,System.Int32)" />
		public OResult StartSerialSlave(string com, int baudRate)
		{
			return server.StartSerialSlave(com, baudRate);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.CommunicationServer.StartSerialSlave(System.String,System.Int32,System.Int32,System.IO.Ports.Parity,System.IO.Ports.StopBits)" />
		public OResult StartSerialSlave(string com, int baudRate, int dataBits, Parity parity, StopBits stopBits)
		{
			//IL_0009: Unknown result type (might be due to invalid IL or missing references)
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			return server.StartSerialSlave(com, baudRate, dataBits, parity, stopBits);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.CommunicationServer.StartSerialSlave(System.Action{System.IO.Ports.SerialPort})" />
		public OResult StartSerialSlave(Action<SerialPort> inni)
		{
			return server.StartSerialSlave(inni);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Net.CommunicationServer.CheckSerialReceiveDataComplete(System.Byte[],System.Int32)" />
		protected virtual bool CheckSerialReceiveDataComplete(byte[] buffer, int receivedLength)
		{
			return false;
		}

		private void ThreadTimerHeartCheck(object obj)
		{
			server.RemoveSession(ActiveTimeSpan);
		}
	}
	/// <summary>
	/// 基于TCP管道的设备基类信息
	/// </summary>
	public class DeviceTcpNet : DeviceCommunication
	{
		private PipeTcpNet pipeTcpNet;

		private Lazy<Ping> ping = new Lazy<Ping>(() => new Ping());

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeTcpNet.ConnectTimeOut" />
		public virtual int ConnectTimeOut
		{
			get
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					return pipeTcpNet.ConnectTimeOut;
				}
				return this.pipeTcpNet.ConnectTimeOut;
			}
			set
			{
				if (value >= 0 && CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
					pipeTcpNet.ConnectTimeOut = value;
				}
			}
		}

		/// <inheritdoc cref="P:Snet.Driver.Core.Pipe.PipeTcpNet.IpAddress" />
		public virtual string IpAddress
		{
			get
			{
				if (CommunicationPipe is PipeTcpNet pipeTcpNet)
				{
