namespace Snet.Driver.Core.Address
{
	/// <summary>
	/// 罗克韦尔PLC的地址信息
	/// </summary>
	public class AllenBradleySLCAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置等待读取的数据的代码<br />
		/// Get or set the code of the data waiting to be read
		/// </summary>
		public byte DataCode { get; set; }

		/// <summary>
		/// 获取或设置PLC的DB块数据信息<br />
		/// Get or set PLC DB data information
		/// </summary>
		public ushort DbBlock { get; set; }

		/// <summary>
		/// 从指定的地址信息解析成真正的设备地址信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		public override void Parse(string address, ushort length)
		{
			OResult<AllenBradleySLCAddress> oResult = ParseFrom(address, length);
			if (oResult.IsSuccess)
			{
				base.AddressStart = oResult.Content.AddressStart;
				base.Length = oResult.Content.Length;
				DataCode = oResult.Content.DataCode;
				DbBlock = oResult.Content.DbBlock;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return DataCode switch
			{
				142 => $"A{DbBlock}:{base.AddressStart}", 
				133 => $"B{DbBlock}:{base.AddressStart}", 
				137 => $"N{DbBlock}:{base.AddressStart}", 
				138 => $"F{DbBlock}:{base.AddressStart}", 
				141 => $"ST{DbBlock}:{base.AddressStart}", 
				132 => $"S{DbBlock}:{base.AddressStart}", 
				135 => $"C{DbBlock}:{base.AddressStart}", 
				131 => $"I{DbBlock}:{base.AddressStart}", 
				130 => $"O{DbBlock}:{base.AddressStart}", 
				136 => $"R{DbBlock}:{base.AddressStart}", 
				134 => $"T{DbBlock}:{base.AddressStart}", 
				145 => $"L{DbBlock}:{base.AddressStart}", 
				_ => base.AddressStart.ToString(), 
			};
		}

		/// <summary>
		/// 从实际的罗克韦尔的地址里面解析出地址对象，例如 A9:0<br />
		/// Parse the address object from the actual Rockwell address, such as A9:0
		/// </summary>
		/// <param name="address">实际的地址数据信息，例如 A9:0</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<AllenBradleySLCAddress> ParseFrom(string address)
		{
			return ParseFrom(address, 0);
		}

		/// <summary>
		/// 从实际的罗克韦尔的地址里面解析出地址对象，例如 A9:0<br />
		/// Parse the address object from the actual Rockwell address, such as A9:0
		/// </summary>
		/// <param name="address">实际的地址数据信息，例如 A9:0</param>
		/// <param name="length">读取的数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<AllenBradleySLCAddress> ParseFrom(string address, ushort length)
		{
			if (!address.Contains(":"))
			{
				return new OResult<AllenBradleySLCAddress>("Address can't find ':', example : A9:0");
			}
			string[] array = address.Split(':');
			try
			{
				AllenBradleySLCAddress allenBradleySLCAddress = new AllenBradleySLCAddress();
				switch (array[0][0])
				{
				case 'A':
					allenBradleySLCAddress.DataCode = 142;
					break;
				case 'B':
					allenBradleySLCAddress.DataCode = 133;
					break;
				case 'N':
					allenBradleySLCAddress.DataCode = 137;
					break;
				case 'F':
					allenBradleySLCAddress.DataCode = 138;
					break;
				case 'S':
					if (array[0].Length > 1 && array[0][1] == 'T')
					{
						allenBradleySLCAddress.DataCode = 141;
					}
					else
					{
						allenBradleySLCAddress.DataCode = 132;
					}
					break;
				case 'C':
					allenBradleySLCAddress.DataCode = 135;
					break;
				case 'I':
					allenBradleySLCAddress.DataCode = 131;
					break;
				case 'O':
					allenBradleySLCAddress.DataCode = 130;
					break;
				case 'R':
					allenBradleySLCAddress.DataCode = 136;
					break;
				case 'T':
					allenBradleySLCAddress.DataCode = 134;
					break;
				case 'L':
					allenBradleySLCAddress.DataCode = 145;
					break;
				default:
					throw new Exception("Address code wrong, must be A,B,N,F,S,C,I,O,R,T,ST,L");
				}
				switch (allenBradleySLCAddress.DataCode)
				{
				case 132:
					allenBradleySLCAddress.DbBlock = (ushort)((array[0].Length == 1) ? 2 : ushort.Parse(array[0].Substring(1)));
					break;
				case 130:
					allenBradleySLCAddress.DbBlock = (ushort)((array[0].Length != 1) ? ushort.Parse(array[0].Substring(1)) : 0);
					break;
				case 131:
					allenBradleySLCAddress.DbBlock = (ushort)((array[0].Length == 1) ? 1 : ushort.Parse(array[0].Substring(1)));
					break;
				case 141:
					allenBradleySLCAddress.DbBlock = (ushort)((array[0].Length == 2) ? 1 : ushort.Parse(array[0].Substring(2)));
					break;
				default:
					allenBradleySLCAddress.DbBlock = ushort.Parse(array[0].Substring(1));
					break;
				}
				allenBradleySLCAddress.AddressStart = ushort.Parse(array[1]);
				return OResult.CreateSuccessResult(allenBradleySLCAddress);
			}
			catch (Exception ex)
			{
				return new OResult<AllenBradleySLCAddress>("Wrong Address format: " + ex.Message);
			}
		}
	}
	/// <summary>
	/// Cnet协议的地址数据信息，未完成
	/// </summary>
	public class CnetAddressData : DeviceAddressDataBase
	{
		/// <summary>
		/// 数据的代号，通常是 'P', 'M', 'L', 'K', 'F', 'T', 'C', 'D', 'S', 'Q', 'I', 'N', 'U', 'Z', 'R'
		/// </summary>
		public string DataCode { get; set; }

		/// <summary>
		/// 数据的类型，通常是 X,B,W,D,L
		/// </summary>
		public string DataType { get; set; }

		/// <summary>
		/// 从实际的PLC的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual PLC address
		/// </summary>
		/// <param name="address">西门子的地址数据信息</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<CnetAddressData> ParseFrom(string address)
		{
			return ParseFrom(address, 0);
		}

		/// <summary>
		/// 从实际的PLC的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual PLC address
		/// </summary>
		/// <param name="address">PLC的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<CnetAddressData> ParseFrom(string address, ushort length)
		{
			CnetAddressData cnetAddressData = new CnetAddressData();
			try
			{
				cnetAddressData.Length = length;
				_ = address[1];
				_ = 88;
			}
			catch (Exception ex)
			{
				return new OResult<CnetAddressData>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(cnetAddressData);
		}
	}
	/// <summary>
	/// 设备地址数据的信息，通常包含起始地址，数据类型，长度<br />
	/// Device address data information, usually including the starting address, data type, length
	/// </summary>
	public class DeviceAddressDataBase
	{
		/// <summary>
		/// 数字的起始地址，也就是偏移地址<br />
		/// The starting address of the number, which is the offset address
		/// </summary>
		public int AddressStart { get; set; }

		/// <summary>
		/// 读取的数据长度，单位是字节还是字取决于设备方<br />
		/// The length of the data read, the unit is byte or word depends on the device side
		/// </summary>
		public ushort Length { get; set; }

		/// <summary>
		/// 从指定的地址信息解析成真正的设备地址信息<br />
		/// Parsing from the specified address information into real device address information
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		public virtual void Parse(string address, ushort length)
		{
			AddressStart = int.Parse(address);
			Length = length;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return AddressStart.ToString();
		}

		/// <summary>
		/// 获取地址不支持的描述信息<br />
		/// Get the description that the address is not supported
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="ex">解析地址时候的异常信息</param>
		/// <returns>地址不支持的信息</returns>
		public static string GetUnsupportedAddressInfo(string address, Exception ex = null)
		{
			if (ex == null)
			{
				return "Address[" + address + "]: " + StringResources.Language.NotSupportedDataType;
			}
			return "Parse [" + address + "] failed: " + ex.Message;
		}
	}
	/// <summary>
	/// Fanuc的PMC地址对象信息
	/// </summary>
	public class FanucPMCAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 地址代号信息
		/// </summary>
		public int DataCode { get; set; }

		/// <summary>
		/// 结束的地址值
		/// </summary>
		public int AddressEnd { get; set; }

		/// <summary>
		/// 根据实际的地址信息，解析出PMC地址信息
		/// </summary>
		/// <param name="address">地址信息，例如 R0, G5</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>PMC地址对象</returns>
		public static OResult<FanucPMCAddress> ParseFrom(string address, ushort length)
		{
			FanucPMCAddress fanucPMCAddress = new FanucPMCAddress();
			try
			{
				switch (address[0])
				{
				case 'G':
				case 'g':
					fanucPMCAddress.DataCode = 0;
					break;
				case 'F':
				case 'f':
					fanucPMCAddress.DataCode = 1;
					break;
				case 'Y':
				case 'y':
					fanucPMCAddress.DataCode = 2;
					break;
				case 'X':
				case 'x':
					fanucPMCAddress.DataCode = 3;
					break;
				case 'A':
				case 'a':
					fanucPMCAddress.DataCode = 4;
					break;
				case 'R':
				case 'r':
					fanucPMCAddress.DataCode = 5;
					break;
				case 'T':
				case 't':
					fanucPMCAddress.DataCode = 6;
					break;
				case 'K':
				case 'k':
					fanucPMCAddress.DataCode = 7;
					break;
				case 'C':
				case 'c':
					fanucPMCAddress.DataCode = 8;
					break;
				case 'D':
				case 'd':
					fanucPMCAddress.DataCode = 9;
					break;
				case 'E':
				case 'e':
					fanucPMCAddress.DataCode = 12;
					break;
				default:
					return new OResult<FanucPMCAddress>(StringResources.Language.NotSupportedDataType);
				}
				fanucPMCAddress.AddressStart = Convert.ToInt32(address.Substring(1));
				fanucPMCAddress.AddressEnd = fanucPMCAddress.AddressStart + length - 1;
				fanucPMCAddress.Length = length;
				if (fanucPMCAddress.AddressEnd < fanucPMCAddress.AddressStart)
				{
					fanucPMCAddress.AddressEnd = fanucPMCAddress.AddressStart;
				}
				return OResult.CreateSuccessResult(fanucPMCAddress);
			}
			catch (Exception ex)
			{
				return new OResult<FanucPMCAddress>(StringResources.Language.NotSupportedDataType + " : " + ex.Message);
			}
		}
	}
	/// <summary>
	/// 永宏编程口的地址类对象
	/// </summary>
	public class FatekProgramAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 数据的类型
		/// </summary>
		public string DataCode { get; set; }

		/// <inheritdoc />
		public override void Parse(string address, ushort length)
		{
			OResult<FatekProgramAddress> oResult = ParseFrom(address, length);
			if (oResult.IsSuccess)
			{
				base.AddressStart = oResult.Content.AddressStart;
				base.Length = oResult.Content.Length;
				DataCode = oResult.Content.DataCode;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			if (DataCode == "X" || DataCode == "Y" || DataCode == "M" || DataCode == "S" || DataCode == "T" || DataCode == "C" || DataCode == "RT" || DataCode == "RC")
			{
				return DataCode + base.AddressStart.ToString("D4");
			}
			return DataCode + base.AddressStart.ToString("D5");
		}

		/// <summary>
		/// 从普通的PLC的地址转换为Snet标准的地址信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>是否成功的地址结果</returns>
		public static OResult<FatekProgramAddress> ParseFrom(string address, ushort length)
		{
			try
			{
				FatekProgramAddress fatekProgramAddress = new FatekProgramAddress();
				switch (address[0])
				{
				case 'X':
				case 'x':
					fatekProgramAddress.DataCode = "X";
					fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'Y':
				case 'y':
					fatekProgramAddress.DataCode = "Y";
					fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'M':
				case 'm':
					fatekProgramAddress.DataCode = "M";
					fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'S':
				case 's':
					fatekProgramAddress.DataCode = "S";
					fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'T':
				case 't':
					fatekProgramAddress.DataCode = "T";
					fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'C':
				case 'c':
					fatekProgramAddress.DataCode = "C";
					fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'D':
				case 'd':
					fatekProgramAddress.DataCode = "D";
					fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'R':
				case 'r':
					if (address[1] == 'T' || address[1] == 't')
					{
						fatekProgramAddress.DataCode = "RT";
						fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
					}
					else if (address[1] == 'C' || address[1] == 'c')
					{
						fatekProgramAddress.DataCode = "RC";
						fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
					}
					else
					{
						fatekProgramAddress.DataCode = "R";
						fatekProgramAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					}
					break;
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
				return OResult.CreateSuccessResult(fatekProgramAddress);
			}
			catch (Exception ex)
			{
				return new OResult<FatekProgramAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}
	}
	/// <summary>
	/// 富士CommandSettingsType的协议信息
	/// </summary>
	public class FujiCommandSettingTypeAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 数据的代号信息
		/// </summary>
		public byte DataCode { get; set; }

		/// <summary>
		/// 地址的头信息，缓存的情况
		/// </summary>
		public string AddressHeader { get; set; }

		/// <inheritdoc />
		public override void Parse(string address, ushort length)
		{
			base.Parse(address, length);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return AddressHeader + base.AddressStart;
		}

		/// <summary>
		/// 从字符串地址解析fuji的实际地址信息，如果解析成功，则 <see cref="P:Snet.Driver.OResult.IsSuccess" /> 为 True，取 <see cref="P:Snet.Driver.OResult`1.Content" /> 值即可。
		/// </summary>
		/// <param name="address">字符串地址</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>是否解析成功</returns>
		public static OResult<FujiCommandSettingTypeAddress> ParseFrom(string address, ushort length)
		{
			try
			{
				FujiCommandSettingTypeAddress fujiCommandSettingTypeAddress = new FujiCommandSettingTypeAddress();
				string empty = string.Empty;
				string empty2 = string.Empty;
				if (address.IndexOf('.') < 0)
				{
					Match match = Regex.Match(address, "^[A-Z]+");
					if (!match.Success)
					{
						return new OResult<FujiCommandSettingTypeAddress>(StringResources.Language.NotSupportedDataType);
					}
					empty = match.Value;
					empty2 = address.Substring(empty.Length);
				}
				else
				{
					string[] array = address.SplitDot();
					if (array[0][0] != 'W')
					{
						return new OResult<FujiCommandSettingTypeAddress>(StringResources.Language.NotSupportedDataType);
					}
					empty = array[0];
					empty2 = array[1];
				}
				fujiCommandSettingTypeAddress.AddressHeader = empty;
				fujiCommandSettingTypeAddress.AddressStart = Convert.ToInt32(empty2);
				fujiCommandSettingTypeAddress.Length = length;
				if (empty == null)
				{
					goto IL_025c;
				}
				int length2 = empty.Length;
				if (length2 != 1)
				{
					if (length2 != 2)
					{
						goto IL_025c;
					}
					char c = empty[0];
					if ((uint)c <= 67u)
					{
						if (c != 'B')
						{
							if (c != 'C')
							{
								goto IL_025c;
							}
							if (!(empty == "CS"))
							{
								if (!(empty == "CR"))
								{
									goto IL_025c;
								}
								fujiCommandSettingTypeAddress.DataCode = 13;
							}
							else
							{
								fujiCommandSettingTypeAddress.DataCode = 12;
							}
						}
						else
						{
							if (!(empty == "BD"))
							{
								goto IL_025c;
							}
							fujiCommandSettingTypeAddress.DataCode = 14;
						}
					}
					else if (c != 'T')
					{
						if (c != 'W' || !(empty == "WL"))
						{
							goto IL_025c;
						}
						fujiCommandSettingTypeAddress.DataCode = 20;
					}
					else if (!(empty == "TS"))
					{
						if (!(empty == "TR"))
						{
							goto IL_025c;
						}
						fujiCommandSettingTypeAddress.DataCode = 11;
					}
					else
					{
						fujiCommandSettingTypeAddress.DataCode = 10;
					}
				}
				else
				{
					switch (empty[0])
					{
					case 'B':
						break;
					case 'M':
						goto IL_0214;
					case 'K':
						goto IL_0220;
					case 'F':
						goto IL_022c;
					case 'A':
						goto IL_0238;
					case 'D':
						goto IL_0244;
					case 'S':
						goto IL_0250;
					default:
						goto IL_025c;
					}
					fujiCommandSettingTypeAddress.DataCode = 0;
				}
				goto IL_0300;
				IL_0238:
				fujiCommandSettingTypeAddress.DataCode = 4;
				goto IL_0300;
				IL_0220:
				fujiCommandSettingTypeAddress.DataCode = 2;
				goto IL_0300;
				IL_022c:
				fujiCommandSettingTypeAddress.DataCode = 3;
				goto IL_0300;
				IL_0250:
				fujiCommandSettingTypeAddress.DataCode = 8;
				goto IL_0300;
				IL_0244:
				fujiCommandSettingTypeAddress.DataCode = 5;
				goto IL_0300;
				IL_0214:
				fujiCommandSettingTypeAddress.DataCode = 1;
				goto IL_0300;
				IL_025c:
				if (empty.StartsWith("W"))
				{
					int num = Convert.ToInt32(empty.Substring(1));
					switch (num)
					{
					case 9:
						fujiCommandSettingTypeAddress.DataCode = 9;
						break;
					case 21:
					case 22:
					case 23:
					case 24:
					case 25:
					case 26:
						fujiCommandSettingTypeAddress.DataCode = (byte)num;
						break;
					default:
						if (num >= 30 && num <= 109)
						{
							fujiCommandSettingTypeAddress.DataCode = (byte)num;
							break;
						}
						if (num >= 120 && num <= 123)
						{
							fujiCommandSettingTypeAddress.DataCode = (byte)num;
							break;
						}
						if (num == 125)
						{
							fujiCommandSettingTypeAddress.DataCode = (byte)num;
							break;
						}
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
					goto IL_0300;
				}
				throw new Exception(StringResources.Language.NotSupportedDataType);
				IL_0300:
				return OResult.CreateSuccessResult(fujiCommandSettingTypeAddress);
			}
			catch (Exception ex)
			{
				return new OResult<FujiCommandSettingTypeAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}
	}
	/// <summary>
	/// FujiSPB的地址信息，可以携带数据类型，起始地址操作
	/// </summary>
	public class FujiSPBAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 数据的类型代码
		/// </summary>
		public string TypeCode { get; set; }

		/// <summary>
		/// 当是位地址的时候，用于标记的信息
		/// </summary>
		public int BitIndex { get; set; }

		/// <summary>
		/// 获取读写字数据的时候的地址信息内容
		/// </summary>
		/// <returns>报文信息</returns>
		public string GetWordAddress()
		{
			return TypeCode + FujiSPBHelper.AnalysisIntegerAddress(base.AddressStart);
		}

		/// <summary>
		/// 获取命令，写入字地址的某一位的命令内容
		/// </summary>
		/// <returns>报文信息</returns>
		public string GetWriteBoolAddress()
		{
			int num = base.AddressStart * 2;
			int num2 = BitIndex;
			if (num2 >= 8)
			{
				num++;
				num2 -= 8;
			}
			return $"{TypeCode}{FujiSPBHelper.AnalysisIntegerAddress(num)}{num2:X2}";
		}

		/// <summary>
		/// 按照位为单位获取相关的索引信息
		/// </summary>
		/// <returns>位数据信息</returns>
		public int GetBitIndex()
		{
			return base.AddressStart * 16 + BitIndex;
		}

		/// <summary>
		/// 从实际的Fuji的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Fuji address
		/// </summary>
		/// <param name="address">富士的地址数据信息</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<FujiSPBAddress> ParseFrom(string address)
		{
			return ParseFrom(address, 0);
		}

		/// <summary>
		/// 从实际的Fuji的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Fuji address
		/// </summary>
		/// <param name="address">富士的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<FujiSPBAddress> ParseFrom(string address, ushort length)
		{
			FujiSPBAddress fujiSPBAddress = new FujiSPBAddress();
			fujiSPBAddress.Length = length;
			try
			{
				fujiSPBAddress.BitIndex = SnetHelper.GetBitIndexInformation(ref address);
				switch (address[0])
				{
				case 'X':
				case 'x':
					fujiSPBAddress.TypeCode = "01";
					fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'Y':
				case 'y':
					fujiSPBAddress.TypeCode = "00";
					fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'M':
				case 'm':
					fujiSPBAddress.TypeCode = "02";
					fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'L':
				case 'l':
					fujiSPBAddress.TypeCode = "03";
					fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'T':
				case 't':
					if (address[1] == 'N' || address[1] == 'n')
					{
						fujiSPBAddress.TypeCode = "0A";
						fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						fujiSPBAddress.TypeCode = "04";
						fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'C':
				case 'c':
					if (address[1] == 'N' || address[1] == 'n')
					{
						fujiSPBAddress.TypeCode = "0B";
						fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						fujiSPBAddress.TypeCode = "05";
						fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'D':
				case 'd':
					fujiSPBAddress.TypeCode = "0C";
					fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'R':
				case 'r':
					fujiSPBAddress.TypeCode = "0D";
					fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				case 'W':
				case 'w':
					fujiSPBAddress.TypeCode = "0E";
					fujiSPBAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					break;
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<FujiSPBAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(fujiSPBAddress);
		}
	}
	/// <summary>
	/// 富士SPH地址类对象
	/// </summary>
	public class FujiSPHAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 数据的类型代码
		/// </summary>
		public byte TypeCode { get; set; }

		/// <summary>
		/// 当前地址的位索引信息
		/// </summary>
		public int BitIndex { get; set; }

		/// <summary>
		/// 从实际的Fuji的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Fuji address
		/// </summary>
		/// <param name="address">富士的地址数据信息</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<FujiSPHAddress> ParseFrom(string address)
		{
			return ParseFrom(address, 0);
		}

		/// <summary>
		/// 从实际的Fuji的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Fuji address
		/// </summary>
		/// <param name="address">富士的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<FujiSPHAddress> ParseFrom(string address, ushort length)
		{
			FujiSPHAddress fujiSPHAddress = new FujiSPHAddress();
			try
			{
				switch (address[0])
				{
				case 'M':
				case 'm':
				{
					string[] array2 = address.SplitDot();
					switch (int.Parse(array2[0].Substring(1)))
					{
					case 1:
						fujiSPHAddress.TypeCode = 2;
						break;
					case 3:
						fujiSPHAddress.TypeCode = 4;
						break;
					case 10:
						fujiSPHAddress.TypeCode = 8;
						break;
					default:
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
					fujiSPHAddress.AddressStart = Convert.ToInt32(array2[1]);
					if (array2.Length > 2)
					{
						fujiSPHAddress.BitIndex = SnetHelper.CalculateBitStartIndex(array2[2]);
					}
					break;
				}
				case 'I':
				case 'Q':
				case 'i':
				case 'q':
				{
					string[] array = address.SplitDot();
					fujiSPHAddress.TypeCode = 1;
					fujiSPHAddress.AddressStart = Convert.ToInt32(array[0].Substring(1));
					if (array.Length > 1)
					{
						fujiSPHAddress.BitIndex = SnetHelper.CalculateBitStartIndex(array[1]);
					}
					break;
				}
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<FujiSPHAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(fujiSPHAddress);
		}
	}
	/// <summary>
	/// GE的SRTP协议的地址内容，主要包含一个数据代码信息，还有静态的解析地址的方法<br />
	/// The address content of GE's SRTP protocol mainly includes a data code information, as well as a static method of address resolution
	/// </summary>
	public class GeSRTPAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置等待读取的数据的代码<br />
		/// Get or set the code of the data waiting to be read
		/// </summary>
		public byte DataCode { get; set; }

		/// <inheritdoc />
		public override void Parse(string address, ushort length)
		{
			OResult<GeSRTPAddress> oResult = ParseFrom(address, length, isBit: false);
			if (oResult.IsSuccess)
			{
				base.AddressStart = oResult.Content.AddressStart;
				base.Length = oResult.Content.Length;
				DataCode = oResult.Content.DataCode;
			}
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Address.GeSRTPAddress.ParseFrom(System.String,System.UInt16,System.Boolean)" />
		public static OResult<GeSRTPAddress> ParseFrom(string address, bool isBit)
		{
			return ParseFrom(address, 0, isBit);
		}

		/// <summary>
		/// 从GE的地址里，解析出实际的带数据码的 <see cref="T:Snet.Driver.Core.Address.GeSRTPAddress" /> 地址信息，起始地址会自动减一，和实际的地址相匹配
		/// </summary>
		/// <param name="address">实际的地址数据</param>
		/// <param name="length">读取的长度信息</param>
		/// <param name="isBit">是否位操作</param>
		/// <returns>是否成功的GE地址对象</returns>
		public static OResult<GeSRTPAddress> ParseFrom(string address, ushort length, bool isBit)
		{
			GeSRTPAddress geSRTPAddress = new GeSRTPAddress();
			try
			{
				geSRTPAddress.Length = length;
				if (address.StartsWith("AI") || address.StartsWith("ai"))
				{
					if (isBit)
					{
						return new OResult<GeSRTPAddress>(StringResources.Language.GeSRTPNotSupportBitReadWrite);
					}
					geSRTPAddress.DataCode = 10;
					geSRTPAddress.AddressStart = Convert.ToInt32(address.Substring(2));
				}
				else if (address.StartsWith("AQ") || address.StartsWith("aq"))
				{
					if (isBit)
					{
						return new OResult<GeSRTPAddress>(StringResources.Language.GeSRTPNotSupportBitReadWrite);
					}
					geSRTPAddress.DataCode = 12;
					geSRTPAddress.AddressStart = Convert.ToInt32(address.Substring(2));
				}
				else if (address.StartsWith("R") || address.StartsWith("r"))
				{
					if (isBit)
					{
						return new OResult<GeSRTPAddress>(StringResources.Language.GeSRTPNotSupportBitReadWrite);
					}
					geSRTPAddress.DataCode = 8;
					geSRTPAddress.AddressStart = Convert.ToInt32(address.Substring(1));
				}
				else if (address.StartsWith("SA") || address.StartsWith("sa"))
				{
					geSRTPAddress.DataCode = (byte)(isBit ? 78u : 24u);
					geSRTPAddress.AddressStart = Convert.ToInt32(address.Substring(2));
				}
				else if (address.StartsWith("SB") || address.StartsWith("sb"))
				{
					geSRTPAddress.DataCode = (byte)(isBit ? 80u : 26u);
					geSRTPAddress.AddressStart = Convert.ToInt32(address.Substring(2));
				}
				else if (address.StartsWith("SC") || address.StartsWith("sc"))
				{
					geSRTPAddress.DataCode = (byte)(isBit ? 82u : 28u);
					geSRTPAddress.AddressStart = Convert.ToInt32(address.Substring(2));
				}
				else
				{
					if (address[0] == 'I' || address[0] == 'i')
					{
						geSRTPAddress.DataCode = (byte)(isBit ? 70u : 16u);
					}
					else if (address[0] == 'Q' || address[0] == 'q')
					{
						geSRTPAddress.DataCode = (byte)(isBit ? 72u : 18u);
					}
					else if (address[0] == 'M' || address[0] == 'm')
					{
						geSRTPAddress.DataCode = (byte)(isBit ? 76u : 22u);
					}
					else if (address[0] == 'T' || address[0] == 't')
					{
						geSRTPAddress.DataCode = (byte)(isBit ? 74u : 20u);
					}
					else if (address[0] == 'S' || address[0] == 's')
					{
						geSRTPAddress.DataCode = (byte)(isBit ? 84u : 30u);
					}
					else
					{
						if (address[0] != 'G' && address[0] != 'g')
						{
							throw new Exception(StringResources.Language.NotSupportedDataType);
						}
						geSRTPAddress.DataCode = (byte)(isBit ? 86u : 56u);
					}
					geSRTPAddress.AddressStart = Convert.ToInt32(address.Substring(1));
				}
			}
			catch (Exception ex)
			{
				return new OResult<GeSRTPAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			if (geSRTPAddress.AddressStart == 0)
			{
				return new OResult<GeSRTPAddress>(StringResources.Language.GeSRTPAddressCannotBeZero);
			}
			if (geSRTPAddress.AddressStart > 0)
			{
				geSRTPAddress.AddressStart--;
			}
			return OResult.CreateSuccessResult(geSRTPAddress);
		}
	}
	/// <summary>
	/// 基恩士上位链路协议的地址类对象
	/// </summary>
	public class KeyenceNanoAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置等待读取的数据的代码<br />
		/// Get or set the code of the data waiting to be read
		/// </summary>
		public string DataCode { get; set; }

		/// <summary>
		/// 获取或设置读取的时候切割的数据长度信息<br />
		/// Gets or sets the data length information that is cut when reading
		/// </summary>
		public int SplitLength { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public KeyenceNanoAddress()
		{
		}

		/// <summary>
		/// 通过指定的参数来实例化对象
		/// </summary>
		/// <param name="dataCode">数据类型</param>
		/// <param name="address">偏移地址</param>
		/// <param name="splits">切割但愿长度</param>
		public KeyenceNanoAddress(string dataCode, int address, int splits)
		{
			DataCode = dataCode;
			base.AddressStart = address;
			SplitLength = splits;
		}

		/// <summary>
		/// 获取地址的字符串表示方式<br />
		/// Gets a string representation of the address
		/// </summary>
		/// <returns>字符串信息</returns>
		public string GetAddressStartFormat()
		{
			string dataCode = DataCode;
			if (dataCode != null)
			{
				switch (dataCode.Length)
				{
				case 2:
				{
					char c = dataCode[0];
					if ((uint)c <= 76u)
					{
						if (c != 'C')
						{
							if (c != 'L' || !(dataCode == "LR"))
							{
								break;
							}
						}
						else if (!(dataCode == "CR"))
						{
							break;
						}
					}
					else
					{
						if (c != 'M')
						{
							if (c != 'V' || !(dataCode == "VB"))
							{
								break;
							}
							goto IL_0119;
						}
						if (!(dataCode == "MR"))
						{
							break;
						}
					}
					goto case 0;
				}
				case 1:
				{
					char c = dataCode[0];
					if (c != 'B' && c != 'W')
					{
						break;
					}
					goto IL_0119;
				}
				case 0:
					{
						if (base.AddressStart >= 16)
						{
							return $"{base.AddressStart / 16}{base.AddressStart % 16:D2}";
						}
						return $"{base.AddressStart % 16}";
					}
					IL_0119:
					return base.AddressStart.ToString("X");
				}
			}
			return base.AddressStart.ToString();
		}

		/// <summary>
		/// 该地址的默认数据类型是否是位地址<br />
		/// Whether the default data type for this address is a bit address
		/// </summary>
		/// <returns>是否位地址</returns>
		public bool IsBitAddressDefault()
		{
			string dataCode = DataCode;
			if (dataCode != null)
			{
				switch (dataCode.Length)
				{
				case 1:
				{
					char c = dataCode[0];
					if (c != 'B' && c != 'R')
					{
						break;
					}
					goto case 0;
				}
				case 2:
				{
					char c = dataCode[0];
					if ((uint)c <= 76u)
					{
						if (c != 'C')
						{
							if (c != 'L' || !(dataCode == "LR"))
							{
								break;
							}
						}
						else if (!(dataCode == "CR"))
						{
							break;
						}
					}
					else if (c != 'M')
					{
						if (c != 'V' || !(dataCode == "VB"))
						{
							break;
						}
					}
					else if (!(dataCode == "MR"))
					{
						break;
					}
					goto case 0;
				}
				case 0:
					return true;
				}
			}
			return false;
		}

		/// <summary>
		/// 从指定的地址信息解析成真正的设备地址信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		public override void Parse(string address, ushort length)
		{
			OResult<KeyenceNanoAddress> oResult = ParseFrom(address, length);
			if (oResult.IsSuccess)
			{
				base.AddressStart = oResult.Content.AddressStart;
				DataCode = oResult.Content.DataCode;
				SplitLength = oResult.Content.SplitLength;
			}
		}

		/// <summary>
		/// 位地址转换方法，101等同于10.1等同于10*16+1=161<br />
		/// Bit address conversion method, 101 is equivalent to 10.1 is equivalent to 10 * 16 + 1 = 161
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <returns>实际的位地址信息</returns>
		private static int CalculateAddress(string address)
		{
			if (address.IndexOf(".") < 0)
			{
				if (address.Length <= 2)
				{
					return Convert.ToInt32(address);
				}
				return Convert.ToInt32(address.Substring(0, address.Length - 2)) * 16 + Convert.ToInt32(address.Substring(address.Length - 2));
			}
			int num = Convert.ToInt32(address.Substring(0, address.IndexOf("."))) * 16;
			string bit = address.Substring(address.IndexOf(".") + 1);
			return num + SnetHelper.CalculateBitStartIndex(bit);
		}

		/// <summary>
		/// 解析出一个基恩士上位链路协议的地址信息
		/// </summary>
		/// <param name="address">字符串地址</param>
		/// <param name="length">长度信息</param>
		/// <returns>成功地址</returns>
		public static OResult<KeyenceNanoAddress> ParseFrom(string address, ushort length)
		{
			try
			{
				if (address.StartsWith("CTH") || address.StartsWith("cth"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("CTH", Convert.ToInt32(address.Substring(3)), 2));
				}
				if (address.StartsWith("CTC") || address.StartsWith("ctc"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("CTC", Convert.ToInt32(address.Substring(3)), 4));
				}
				if (address.StartsWith("CR") || address.StartsWith("cr"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("CR", CalculateAddress(address.Substring(2)), 256));
				}
				if (address.StartsWith("MR") || address.StartsWith("mr"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("MR", CalculateAddress(address.Substring(2)), 256));
				}
				if (address.StartsWith("LR") || address.StartsWith("lr"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("LR", CalculateAddress(address.Substring(2)), 256));
				}
				if (address.StartsWith("DM") || address.StartsWith("dm"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("DM", Convert.ToInt32(address.Substring(2)), 256));
				}
				if (address.StartsWith("CM") || address.StartsWith("cm"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("CM", Convert.ToInt32(address.Substring(2)), 256));
				}
				if (address.StartsWith("TM") || address.StartsWith("tm"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("TM", Convert.ToInt32(address.Substring(2)), 256));
				}
				if (address.StartsWith("VM") || address.StartsWith("vm"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("VM", Convert.ToInt32(address.Substring(2)), 256));
				}
				if (address.StartsWith("VB") || address.StartsWith("vb"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("VB", Convert.ToInt32(address.Substring(2), 16), 256));
				}
				if (address.StartsWith("EM") || address.StartsWith("em"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("EM", Convert.ToInt32(address.Substring(2)), 256));
				}
				if (address.StartsWith("FM") || address.StartsWith("fm"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("FM", Convert.ToInt32(address.Substring(2)), 256));
				}
				if (address.StartsWith("ZF") || address.StartsWith("zf"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("ZF", Convert.ToInt32(address.Substring(2)), 256));
				}
				if (address.StartsWith("AT") || address.StartsWith("at"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("AT", Convert.ToInt32(address.Substring(2)), 8));
				}
				if (address.StartsWith("TS") || address.StartsWith("ts"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("TS", Convert.ToInt32(address.Substring(2)), 64));
				}
				if (address.StartsWith("TC") || address.StartsWith("tc"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("TC", Convert.ToInt32(address.Substring(2)), 64));
				}
				if (address.StartsWith("CC") || address.StartsWith("cc"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("CC", Convert.ToInt32(address.Substring(2)), 64));
				}
				if (address.StartsWith("CS") || address.StartsWith("cs"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("CS", Convert.ToInt32(address.Substring(2)), 64));
				}
				if (address.StartsWith("W") || address.StartsWith("w"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("W", Convert.ToInt32(address.Substring(1), 16), 256));
				}
				if (address.StartsWith("Z") || address.StartsWith("z"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("Z", Convert.ToInt32(address.Substring(1)), 12));
				}
				if (address.StartsWith("R") || address.StartsWith("r"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("", CalculateAddress(address.Substring(1)), 256));
				}
				if (address.StartsWith("B") || address.StartsWith("b"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("B", Convert.ToInt32(address.Substring(1), 16), 256));
				}
				if (address.StartsWith("T") || address.StartsWith("t"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("T", Convert.ToInt32(address.Substring(1)), 64));
				}
				if (address.StartsWith("C") || address.StartsWith("c"))
				{
					return OResult.CreateSuccessResult(new KeyenceNanoAddress("C", Convert.ToInt32(address.Substring(1)), 64));
				}
				throw new Exception(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<KeyenceNanoAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}
	}
	/// <summary>
	/// Lsis的Cnet协议的地址信息
	/// </summary>
	public class LsisCnetAddress : DeviceAddressDataBase
	{
		private const string CnetTypes = "PMLKFTCDSQINUZR";

		/// <summary>
		/// 地址类型信息
		/// </summary>
		public string DataType { get; set; }

		/// <summary>
		/// 获取报文里需要的地址格式信息
		/// </summary>
		/// <returns>报文地址</returns>
		public string GetAddressCommand()
		{
			return $"%{DataType}B{base.AddressStart}";
		}

		private static int CalculateByDataType(string address)
		{
			switch (address[1])
			{
			case 'B':
			case 'b':
				return Convert.ToInt32(address.Substring(2));
			case 'W':
			case 'w':
				return Convert.ToInt32(address.Substring(2)) * 2;
			case 'D':
			case 'd':
				return Convert.ToInt32(address.Substring(2)) * 4;
			case 'L':
			case 'l':
				return Convert.ToInt32(address.Substring(2)) * 8;
			case 'X':
			case 'x':
				return Convert.ToInt32(address.Substring(2)) * 2;
			default:
				return Convert.ToInt32(address.Substring(1)) * 2;
			}
		}

		/// <summary>
		/// 从实际三菱的地址里面解析出我们需要的地址类型<br />
		/// Resolve the type of address we need from the actual Mitsubishi address
		/// </summary>
		/// <param name="address">三菱的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="isBit">是否读写bool的操作</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<LsisCnetAddress> ParseFrom(string address, ushort length, bool isBit)
		{
			if (!"PMLKFTCDSQINUZR".Contains(address[0]))
			{
				return new OResult<LsisCnetAddress>(StringResources.Language.NotSupportedDataType);
			}
			LsisCnetAddress lsisCnetAddress = new LsisCnetAddress();
			lsisCnetAddress.Length = length;
			try
			{
				lsisCnetAddress.DataType = address.Substring(0, 1);
				if (lsisCnetAddress.DataType.Equals("U", StringComparison.OrdinalIgnoreCase) && address.Contains("."))
				{
					string[] array = address.SplitDot();
					if (array.Length == 2)
					{
						lsisCnetAddress.AddressStart = Convert.ToInt32(array[0].Substring(1), 16) * 32 + Convert.ToInt32(array[1]);
						lsisCnetAddress.AddressStart *= 2;
					}
					else if (array.Length >= 3)
					{
						lsisCnetAddress.AddressStart = Convert.ToInt32(array[0].Substring(1)) * 32 * 16 + Convert.ToInt32(array[1]) * 32 + Convert.ToInt32(array[2]);
						lsisCnetAddress.AddressStart *= 2;
					}
				}
				else if ((lsisCnetAddress.DataType.Equals("I", StringComparison.OrdinalIgnoreCase) || lsisCnetAddress.DataType.Equals("Q", StringComparison.OrdinalIgnoreCase)) && address.Contains("."))
				{
					string[] array2 = address.SplitDot();
					if (array2.Length >= 3)
					{
						lsisCnetAddress.AddressStart = Convert.ToInt32(array2[0].Substring(1)) * 16 * 4 + Convert.ToInt32(array2[1]) * 4 + Convert.ToInt32(array2[2]);
						lsisCnetAddress.AddressStart *= 2;
					}
				}
				else
				{
					switch (address[1])
					{
					case 'B':
					case 'b':
						lsisCnetAddress.AddressStart = Convert.ToInt32(address.Substring(2));
						break;
					case 'W':
					case 'w':
						lsisCnetAddress.AddressStart = Convert.ToInt32(address.Substring(2)) * 2;
						break;
					case 'D':
					case 'd':
						lsisCnetAddress.AddressStart = Convert.ToInt32(address.Substring(2)) * 4;
						break;
					case 'L':
					case 'l':
						lsisCnetAddress.AddressStart = Convert.ToInt32(address.Substring(2)) * 8;
						break;
					case 'X':
					case 'x':
						lsisCnetAddress.AddressStart = Convert.ToInt32(address.Substring(2)) * 2;
						break;
					default:
						lsisCnetAddress.AddressStart = Convert.ToInt32(address.Substring(1)) * 2;
						break;
					}
				}
			}
			catch (Exception ex)
			{
				return new OResult<LsisCnetAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(lsisCnetAddress);
		}
	}
	/// <summary>
	/// 三菱的数据地址表示形式<br />
	/// Mitsubishi's data address representation
	/// </summary>
	public class McAddressData : DeviceAddressDataBase
	{
		/// <summary>
		/// 三菱的数据类型及地址信息
		/// </summary>
		public MelsecMcDataType McDataType { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public McAddressData()
		{
			McDataType = MelsecMcDataType.D;
		}

		/// <summary>
		/// 从指定的地址信息解析成真正的设备地址信息，默认是三菱的地址
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		public override void Parse(string address, ushort length)
		{
			OResult<McAddressData> oResult = ParseMelsecFrom(address, length, isBit: false);
			if (oResult.IsSuccess)
			{
				base.AddressStart = oResult.Content.AddressStart;
				base.Length = oResult.Content.Length;
				McDataType = oResult.Content.McDataType;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return McDataType.AsciiCode.Replace("*", "") + Convert.ToString(base.AddressStart, McDataType.FromBase);
		}

		/// <summary>
		/// 从实际三菱的地址里面解析出我们需要的地址类型<br />
		/// Resolve the type of address we need from the actual Mitsubishi address
		/// </summary>
		/// <param name="address">三菱的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="isBit">是否读写bool的操作</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<McAddressData> ParseMelsecFrom(string address, ushort length, bool isBit)
		{
			McAddressData mcAddressData = new McAddressData();
			mcAddressData.Length = length;
			try
			{
				switch (address[0])
				{
				case 'M':
				case 'm':
					mcAddressData.McDataType = MelsecMcDataType.M;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.M.FromBase);
					break;
				case 'X':
				case 'x':
					mcAddressData.McDataType = MelsecMcDataType.X;
					address = address.Substring(1);
					if (address.StartsWith("0"))
					{
						mcAddressData.AddressStart = Convert.ToInt32(address, 8);
					}
					else
					{
						mcAddressData.AddressStart = Convert.ToInt32(address, MelsecMcDataType.X.FromBase);
					}
					break;
				case 'Y':
				case 'y':
					mcAddressData.McDataType = MelsecMcDataType.Y;
					address = address.Substring(1);
					if (address.StartsWith("0"))
					{
						mcAddressData.AddressStart = Convert.ToInt32(address, 8);
					}
					else
					{
						mcAddressData.AddressStart = Convert.ToInt32(address, MelsecMcDataType.Y.FromBase);
					}
					break;
				case 'D':
				case 'd':
					if (address[1] == 'X' || address[1] == 'x')
					{
						mcAddressData.McDataType = MelsecMcDataType.DX;
						address = address.Substring(2);
						if (address.StartsWith("0"))
						{
							mcAddressData.AddressStart = Convert.ToInt32(address, 8);
						}
						else
						{
							mcAddressData.AddressStart = Convert.ToInt32(address, MelsecMcDataType.DX.FromBase);
						}
					}
					else if (address[1] == 'Y' || address[1] == 's')
					{
						mcAddressData.McDataType = MelsecMcDataType.DY;
						address = address.Substring(2);
						if (address.StartsWith("0"))
						{
							mcAddressData.AddressStart = Convert.ToInt32(address, 8);
						}
						else
						{
							mcAddressData.AddressStart = Convert.ToInt32(address, MelsecMcDataType.DY.FromBase);
						}
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.D;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.D.FromBase);
					}
					break;
				case 'W':
				case 'w':
					mcAddressData.McDataType = MelsecMcDataType.W;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.W.FromBase);
					break;
				case 'L':
				case 'l':
					mcAddressData.McDataType = MelsecMcDataType.L;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.L.FromBase);
					break;
				case 'F':
				case 'f':
					mcAddressData.McDataType = MelsecMcDataType.F;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.F.FromBase);
					break;
				case 'V':
				case 'v':
					mcAddressData.McDataType = MelsecMcDataType.V;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.V.FromBase);
					break;
				case 'B':
				case 'b':
					mcAddressData.McDataType = MelsecMcDataType.B;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.B.FromBase);
					break;
				case 'R':
				case 'r':
					mcAddressData.McDataType = MelsecMcDataType.R;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.R.FromBase);
					break;
				case 'S':
				case 's':
					if (address[1] == 'N' || address[1] == 'n')
					{
						mcAddressData.McDataType = MelsecMcDataType.SN;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.SN.FromBase);
					}
					else if (address[1] == 'S' || address[1] == 's')
					{
						mcAddressData.McDataType = MelsecMcDataType.SS;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.SS.FromBase);
					}
					else if (address[1] == 'C' || address[1] == 'c')
					{
						mcAddressData.McDataType = MelsecMcDataType.SC;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.SC.FromBase);
					}
					else if (address[1] == 'M' || address[1] == 'm')
					{
						mcAddressData.McDataType = MelsecMcDataType.SM;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.SM.FromBase);
					}
					else if (address[1] == 'D' || address[1] == 'd')
					{
						mcAddressData.McDataType = MelsecMcDataType.SD;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.SD.FromBase);
					}
					else if (address[1] == 'B' || address[1] == 'b')
					{
						mcAddressData.McDataType = MelsecMcDataType.SB;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.SB.FromBase);
					}
					else if (address[1] == 'W' || address[1] == 'w')
					{
						mcAddressData.McDataType = MelsecMcDataType.SW;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.SW.FromBase);
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.S;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.S.FromBase);
					}
					break;
				case 'Z':
				case 'z':
					if (address.StartsWith("ZR") || address.StartsWith("zr"))
					{
						mcAddressData.McDataType = MelsecMcDataType.ZR;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.ZR.FromBase);
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.Z;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Z.FromBase);
					}
					break;
				case 'T':
				case 't':
					if (address[1] == 'N' || address[1] == 'n')
					{
						mcAddressData.McDataType = MelsecMcDataType.TN;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.TN.FromBase);
						break;
					}
					if (address[1] == 'S' || address[1] == 's')
					{
						mcAddressData.McDataType = MelsecMcDataType.TS;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.TS.FromBase);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						mcAddressData.McDataType = MelsecMcDataType.TC;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.TC.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'C':
				case 'c':
					if (address[1] == 'N' || address[1] == 'n')
					{
						mcAddressData.McDataType = MelsecMcDataType.CN;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.CN.FromBase);
						break;
					}
					if (address[1] == 'S' || address[1] == 's')
					{
						mcAddressData.McDataType = MelsecMcDataType.CS;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.CS.FromBase);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
