						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.CC.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<McAddressData>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(mcAddressData);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Address.McAddressData.ParseMelsecFrom(System.String,System.UInt16,System.Boolean)" />
		public static OResult<McAddressData> ParseMelsecRFrom(string address, ushort length, bool isBit)
		{
			OResult<MelsecMcDataType, int> oResult = MelsecMcRNet.AnalysisAddress(address);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<McAddressData>(oResult);
			}
			return OResult.CreateSuccessResult(new McAddressData
			{
				McDataType = oResult.Content1,
				AddressStart = oResult.Content2,
				Length = length
			});
		}

		private static int CalculateComplexAddress(string address)
		{
			if (address.IndexOf(".") < 0)
			{
				if (address.Length <= 2)
				{
					return Convert.ToInt32(address);
				}
				return Convert.ToInt32(address.Substring(0, address.Length - 2)) * 16 + Convert.ToInt32(address.Substring(address.Length - 2), 10);
			}
			int num = Convert.ToInt32(address.Substring(0, address.IndexOf("."))) * 16;
			string bit = address.Substring(address.IndexOf(".") + 1);
			return num + SnetHelper.CalculateBitStartIndex(bit);
		}

		/// <summary>
		/// 从实际基恩士的地址里面解析出我们需要的地址信息<br />
		/// Resolve the address information we need from the actual Keyence address
		/// </summary>
		/// <param name="address">基恩士的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="isBit">是否读写bool操作</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<McAddressData> ParseKeyenceFrom(string address, ushort length, bool isBit)
		{
			McAddressData mcAddressData = new McAddressData();
			mcAddressData.Length = length;
			try
			{
				switch (address[0])
				{
				case 'M':
				case 'm':
					if (address[1] == 'R' || address[1] == 'r')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_M;
						mcAddressData.AddressStart = CalculateComplexAddress(address.Substring(2));
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_M;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Keyence_M.FromBase);
					}
					break;
				case 'X':
				case 'x':
					mcAddressData.McDataType = MelsecMcDataType.Keyence_X;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Keyence_X.FromBase);
					break;
				case 'Y':
				case 'y':
					mcAddressData.McDataType = MelsecMcDataType.Keyence_Y;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Keyence_Y.FromBase);
					break;
				case 'B':
				case 'b':
					mcAddressData.McDataType = MelsecMcDataType.Keyence_B;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Keyence_B.FromBase);
					break;
				case 'L':
				case 'l':
					if (address[1] == 'R' || address[1] == 'r')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_L;
						mcAddressData.AddressStart = CalculateComplexAddress(address.Substring(2));
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_L;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Keyence_L.FromBase);
					}
					break;
				case 'S':
				case 's':
					if (address[1] == 'M' || address[1] == 'm')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_SM;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_SM.FromBase);
						break;
					}
					if (address[1] == 'D' || address[1] == 'd')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_SD;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_SD.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'D':
				case 'd':
					if (address[1] == 'M' || address[1] == 'm')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_D;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_D.FromBase);
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_D;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Keyence_D.FromBase);
					}
					break;
				case 'E':
				case 'e':
					if (address[1] == 'M' || address[1] == 'm')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_D;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_D.FromBase) + 100000;
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'F':
				case 'f':
					if (address[1] == 'M' || address[1] == 'm')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_R;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_R.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'R':
				case 'r':
					if (isBit)
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_Y;
						mcAddressData.AddressStart = CalculateComplexAddress(address.Substring(1));
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_R;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Keyence_R.FromBase);
					}
					break;
				case 'Z':
				case 'z':
					if (address[1] == 'R' || address[1] == 'r')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_ZR;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_ZR.FromBase);
						break;
					}
					if (address[1] == 'F' || address[1] == 'f')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_ZR;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), 10);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'W':
				case 'w':
					mcAddressData.McDataType = MelsecMcDataType.Keyence_W;
					mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1), MelsecMcDataType.Keyence_W.FromBase);
					break;
				case 'T':
				case 't':
					if (address[1] == 'N' || address[1] == 'n')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_TN;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_TN.FromBase);
						break;
					}
					if (address[1] == 'S' || address[1] == 's')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_TS;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_TS.FromBase);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_TC;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_TC.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'C':
				case 'c':
					if (address[1] == 'N' || address[1] == 'n')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_CN;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_CN.FromBase);
						break;
					}
					if (address[1] == 'S' || address[1] == 's')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_CS;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_CS.FromBase);
						break;
					}
					if (address[1] == 'C' || address[1] == 'c')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_CC;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_CC.FromBase);
						break;
					}
					if (address[1] == 'R' || address[1] == 'r')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_SM;
						mcAddressData.AddressStart = CalculateComplexAddress(address.Substring(2));
						break;
					}
					if (address[1] == 'M' || address[1] == 'm')
					{
						mcAddressData.McDataType = MelsecMcDataType.Keyence_SD;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2), MelsecMcDataType.Keyence_SD.FromBase);
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<McAddressData>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(mcAddressData);
		}

		/// <summary>
		/// 从实际松下的地址里面解析出MC协议标准的地址对象
		/// </summary>
		/// <param name="address">松下的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="isBit">是否进行bool类型的读写操作</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<McAddressData> ParsePanasonicFrom(string address, ushort length, bool isBit)
		{
			McAddressData mcAddressData = new McAddressData();
			mcAddressData.Length = length;
			try
			{
				switch (address[0])
				{
				case 'R':
				case 'r':
				{
					int num = PanasonicHelper.CalculateComplexAddress(address.Substring(1));
					if (num < 14400)
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_R;
						mcAddressData.AddressStart = num;
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_SM;
						mcAddressData.AddressStart = num - 14400;
					}
					break;
				}
				case 'X':
				case 'x':
					mcAddressData.McDataType = MelsecMcDataType.Panasonic_X;
					mcAddressData.AddressStart = PanasonicHelper.CalculateComplexAddress(address.Substring(1));
					break;
				case 'Y':
				case 'y':
					mcAddressData.McDataType = MelsecMcDataType.Panasonic_Y;
					mcAddressData.AddressStart = PanasonicHelper.CalculateComplexAddress(address.Substring(1));
					break;
				case 'L':
				case 'l':
					if (address[1] == 'D' || address[1] == 'd')
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_LD;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2));
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_L;
						mcAddressData.AddressStart = PanasonicHelper.CalculateComplexAddress(address.Substring(1));
					}
					break;
				case 'D':
				case 'd':
					if (address[1] == 'T' || address[1] == 't')
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_DT;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2));
					}
					else if (Convert.ToInt32(address.Substring(1)) < 90000)
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_DT;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1));
					}
					else
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_SD;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(1)) - 90000;
					}
					break;
				case 'T':
				case 't':
					if (address[1] == 'N' || address[1] == 'n')
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_TN;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2));
						break;
					}
					if (address[1] == 'S' || address[1] == 's')
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_TS;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2));
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'C':
				case 'c':
					if (address[1] == 'N' || address[1] == 'n')
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_CN;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2));
						break;
					}
					if (address[1] == 'S' || address[1] == 's')
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_CS;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2));
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'S':
				case 's':
					if (address[1] == 'D' || address[1] == 'd')
					{
						mcAddressData.McDataType = MelsecMcDataType.Panasonic_SD;
						mcAddressData.AddressStart = Convert.ToInt32(address.Substring(2));
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
			}
			catch (Exception ex)
			{
				return new OResult<McAddressData>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(mcAddressData);
		}
	}
	/// <summary>
	/// 三菱的FxLinks协议信息
	/// </summary>
	public class MelsecFxLinksAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 当前的地址类型信息
		/// </summary>
		public string TypeCode { get; set; }

		/// <summary>
		/// 实例化一个默认的对象
		/// </summary>
		public MelsecFxLinksAddress()
		{
		}

		/// <inheritdoc />
		public override void Parse(string address, ushort length)
		{
			base.Parse(address, length);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			string typeCode = TypeCode;
			if (typeCode == "X" || typeCode == "Y")
			{
				return TypeCode + Convert.ToString(base.AddressStart, 8).PadLeft((base.AddressStart >= 10000) ? 6 : 4, '0');
			}
			return TypeCode + base.AddressStart.ToString("D" + (((base.AddressStart >= 10000) ? 7 : 5) - TypeCode.Length));
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Address.MelsecFxLinksAddress.Parse(System.String,System.UInt16)" />
		public static OResult<MelsecFxLinksAddress> ParseFrom(string address)
		{
			return ParseFrom(address, 0);
		}

		/// <summary>
		/// 从三菱FxLinks协议里面解析出实际的地址信息
		/// </summary>
		/// <param name="address">三菱的地址信息</param>
		/// <param name="length">读取的长度信息</param>
		/// <returns>解析结果信息</returns>
		public static OResult<MelsecFxLinksAddress> ParseFrom(string address, ushort length)
		{
			MelsecFxLinksAddress melsecFxLinksAddress = new MelsecFxLinksAddress();
			melsecFxLinksAddress.Length = length;
			try
			{
				switch (address[0])
				{
				case 'X':
				case 'x':
					melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 8);
					melsecFxLinksAddress.TypeCode = "X";
					break;
				case 'Y':
				case 'y':
					melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 8);
					melsecFxLinksAddress.TypeCode = "Y";
					break;
				case 'M':
				case 'm':
					melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					melsecFxLinksAddress.TypeCode = "M";
					break;
				case 'S':
				case 's':
					melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					melsecFxLinksAddress.TypeCode = "S";
					break;
				case 'T':
				case 't':
					if (address[1] == 'S' || address[1] == 's')
					{
						melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
						melsecFxLinksAddress.TypeCode = "TS";
						break;
					}
					if (address[1] == 'N' || address[1] == 'n')
					{
						melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
						melsecFxLinksAddress.TypeCode = "TN";
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'C':
				case 'c':
					if (address[1] == 'S' || address[1] == 's')
					{
						melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
						melsecFxLinksAddress.TypeCode = "CS";
						break;
					}
					if (address[1] == 'N' || address[1] == 'n')
					{
						melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(2), 10);
						melsecFxLinksAddress.TypeCode = "CN";
						break;
					}
					throw new Exception(StringResources.Language.NotSupportedDataType);
				case 'D':
				case 'd':
					melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					melsecFxLinksAddress.TypeCode = "D";
					break;
				case 'R':
				case 'r':
					melsecFxLinksAddress.AddressStart = Convert.ToUInt16(address.Substring(1), 10);
					melsecFxLinksAddress.TypeCode = "R";
					break;
				default:
					throw new Exception(StringResources.Language.NotSupportedDataType);
				}
				return OResult.CreateSuccessResult(melsecFxLinksAddress);
			}
			catch (Exception ex)
			{
				return new OResult<MelsecFxLinksAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}
	}
	/// <summary>
	/// 扩展memobus协议的地址信息
	/// </summary>
	public class MemobusAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置当前地址对应的功能码信息
		/// </summary>
		public byte SFC { get; set; }

		/// <summary>
		/// 获取或设置当前的地址对应的主功能码信息
		/// </summary>
		public byte MFC { get; set; }

		/// <inheritdoc />
		public override string ToString()
		{
			return base.AddressStart.ToString();
		}

		/// <summary>
		/// 获取并解析出memobus地址的信息及功能码
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="isBit">是否位</param>
		/// <returns>memobus的地址信息</returns>
		public static OResult<MemobusAddress> ParseFrom(string address, bool isBit)
		{
			try
			{
				MemobusAddress memobusAddress = new MemobusAddress();
				memobusAddress.MFC = (byte)SnetHelper.ExtractParameter(ref address, "mfc", 32);
				memobusAddress.SFC = (byte)SnetHelper.ExtractParameter(ref address, "x", isBit ? 1 : 3);
				if (address.IndexOf('.') > 0)
				{
					int num = address.IndexOf('.');
					memobusAddress.AddressStart = Convert.ToInt32(address.Substring(0, num)) * 16 + SnetHelper.CalculateBitStartIndex(address.Substring(num + 1));
					if (memobusAddress.SFC == 1)
					{
						memobusAddress.SFC = 3;
					}
				}
				else
				{
					memobusAddress.AddressStart = ushort.Parse(address);
				}
				return OResult.CreateSuccessResult(memobusAddress);
			}
			catch (Exception ex)
			{
				return new OResult<MemobusAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}
	}
	/// <summary>
	/// Modbus协议地址格式，可以携带站号，功能码，地址信息<br />
	/// Modbus protocol address format, can carry station number, function code, address information
	/// </summary>
	public class ModbusAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置当前地址的站号信息<br />
		/// Get or set the station number information of the current address
		/// </summary>
		public int Station { get; set; }

		/// <summary>
		/// 获取或设置当前地址携带的功能码<br />
		/// Get or set the function code carried by the current address
		/// </summary>
		public int Function { get; set; }

		/// <summary>
		/// 获取或设置当前地址在写入的情况下使用的功能码，用来扩展一些非常特殊的自定义服务器<br />
		/// </summary>
		public int WriteFunction { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public ModbusAddress()
		{
			Station = -1;
			Function = -1;
			WriteFunction = -1;
			base.AddressStart = 0;
		}

		/// <summary>
		/// 实例化一个对象，使用指定的地址初始化<br />
		/// Instantiate an object, initialize with the specified address
		/// </summary>
		/// <param name="address">传入的地址信息，支持富地址，例如s=2;x=3;100</param>
		public ModbusAddress(string address)
		{
			Station = -1;
			Function = -1;
			WriteFunction = -1;
			base.AddressStart = 0;
			Parse(address, 1);
		}

		/// <summary>
		/// 实例化一个对象，使用指定的地址及功能码初始化<br />
		/// Instantiate an object and initialize it with the specified address and function code
		/// </summary>
		/// <param name="address">传入的地址信息，支持富地址，例如s=2;x=3;100</param>
		/// <param name="function">默认的功能码信息</param>
		public ModbusAddress(string address, byte function)
		{
			Station = -1;
			WriteFunction = -1;
			Function = function;
			base.AddressStart = 0;
			Parse(address, 1);
		}

		/// <summary>
		/// 实例化一个对象，使用指定的地址，站号，功能码来初始化<br />
		/// Instantiate an object, use the specified address, station number, function code to initialize
		/// </summary>
		/// <param name="address">传入的地址信息，支持富地址，例如s=2;x=3;100</param>
		/// <param name="station">站号信息</param>
		/// <param name="function">默认的功能码信息</param>
		public ModbusAddress(string address, byte station, byte function)
		{
			WriteFunction = -1;
			Function = function;
			Station = station;
			base.AddressStart = 0;
			Parse(address, 1);
		}

		private int ParseAddressHelper(string address)
		{
			if (address.EndsWith("H", StringComparison.OrdinalIgnoreCase))
			{
				return Convert.ToInt32(address.Substring(0, address.Length - 1), 16);
			}
			return (int)uint.Parse(address);
		}

		/// <inheritdoc />
		public override void Parse(string address, ushort length)
		{
			base.Length = length;
			if (address.IndexOf(';') < 0)
			{
				base.AddressStart = ParseAddressHelper(address);
				return;
			}
			string[] array = address.Split(new char[1] { ';' }, StringSplitOptions.RemoveEmptyEntries);
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].StartsWith("s=", StringComparison.OrdinalIgnoreCase))
				{
					Station = byte.Parse(array[i].Substring(2));
				}
				else if (array[i].StartsWith("x=", StringComparison.OrdinalIgnoreCase))
				{
					Function = byte.Parse(array[i].Substring(2));
				}
				else if (array[i].StartsWith("w=", StringComparison.OrdinalIgnoreCase))
				{
					WriteFunction = byte.Parse(array[i].Substring(2));
				}
				else
				{
					base.AddressStart = ParseAddressHelper(array[i]);
				}
			}
		}

		/// <summary>
		/// 地址偏移指定的位置，返回一个新的地址对象<br />
		/// The address is offset by the specified position and a new address object is returned
		/// </summary>
		/// <param name="value">数据值信息</param>
		/// <returns>新增后的地址信息</returns>
		public ModbusAddress AddressAdd(int value)
		{
			return new ModbusAddress
			{
				Station = Station,
				Function = Function,
				WriteFunction = WriteFunction,
				AddressStart = base.AddressStart + value
			};
		}

		/// <summary>
		/// 地址偏移1，返回一个新的地址对象<br />
		/// The address is offset by 1 and a new address object is returned
		/// </summary>
		/// <returns>新增后的地址信息</returns>
		public ModbusAddress AddressAdd()
		{
			return AddressAdd(1);
		}

		/// <inheritdoc />
		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (Station >= 0)
			{
				stringBuilder.Append("s=" + Station + ";");
			}
			if (Function == 2 || Function == 4 || Function > 6)
			{
				stringBuilder.Append("x=" + Function + ";");
			}
			if (WriteFunction > 0)
			{
				stringBuilder.Append("w=" + WriteFunction + ";");
			}
			stringBuilder.Append(base.AddressStart.ToString());
			return stringBuilder.ToString();
		}
	}
	/// <summary>
	/// 欧姆龙的Fins协议的地址类对象
	/// </summary>
	public class OmronFinsAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 进行位操作的指令
		/// </summary>
		public byte BitCode { get; set; }

		/// <summary>
		/// 进行字操作的指令
		/// </summary>
		public byte WordCode { get; set; }

		/// <summary>
		/// 从指定的地址信息解析成真正的设备地址信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		public override void Parse(string address, ushort length)
		{
			OResult<OmronFinsAddress> oResult = ParseFrom(address, length, OmronPlcType.CSCJ);
			if (oResult.IsSuccess)
			{
				base.AddressStart = oResult.Content.AddressStart;
				base.Length = oResult.Content.Length;
				BitCode = oResult.Content.BitCode;
				WordCode = oResult.Content.WordCode;
			}
		}

		/// <summary>
		/// 从实际的欧姆龙的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Omron address
		/// </summary>
		/// <param name="address">欧姆龙的地址数据信息</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<OmronFinsAddress> ParseFrom(string address)
		{
			return ParseFrom(address, 0, OmronPlcType.CSCJ);
		}

		private static int CalculateBitIndex(string address)
		{
			string[] array = address.SplitDot();
			int num = ushort.Parse(array[0]) * 16;
			if (array.Length > 1)
			{
				num += SnetHelper.CalculateBitStartIndex(array[1]);
			}
			return num;
		}

		/// <summary>
		/// 从实际的欧姆龙的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Omron address
		/// </summary>
		/// <param name="address">欧姆龙的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="plcType">PLC的类型信息</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<OmronFinsAddress> ParseFrom(string address, ushort length, OmronPlcType plcType)
		{
			OmronFinsAddress omronFinsAddress = new OmronFinsAddress();
			try
			{
				omronFinsAddress.Length = length;
				if (address.StartsWith("DR", StringComparison.OrdinalIgnoreCase))
				{
					if (plcType == OmronPlcType.CV)
					{
						omronFinsAddress.WordCode = 156;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2)) + 48;
					}
					else
					{
						omronFinsAddress.WordCode = 188;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2)) + 8192;
					}
				}
				else if (address.StartsWith("IR", StringComparison.OrdinalIgnoreCase))
				{
					omronFinsAddress.WordCode = 220;
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2)) + 4096;
				}
				else if (address.StartsWith("DM", StringComparison.OrdinalIgnoreCase))
				{
					omronFinsAddress.BitCode = OmronFinsDataType.DM.BitCode;
					omronFinsAddress.WordCode = OmronFinsDataType.DM.WordCode;
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2));
				}
				else if (address.StartsWith("TIM") || address.StartsWith("tim"))
				{
					if (plcType == OmronPlcType.CV)
					{
						omronFinsAddress.BitCode = 1;
						omronFinsAddress.WordCode = 129;
					}
					else
					{
						omronFinsAddress.BitCode = OmronFinsDataType.TIM.BitCode;
						omronFinsAddress.WordCode = OmronFinsDataType.TIM.WordCode;
					}
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(3));
				}
				else if (address.StartsWith("CNT") || address.StartsWith("cnt"))
				{
					if (plcType == OmronPlcType.CV)
					{
						omronFinsAddress.BitCode = 1;
						omronFinsAddress.WordCode = 129;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(3)) + 32768;
					}
					else
					{
						omronFinsAddress.BitCode = OmronFinsDataType.TIM.BitCode;
						omronFinsAddress.WordCode = OmronFinsDataType.TIM.WordCode;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(3)) + 524288;
					}
				}
				else if (address.StartsWith("CIO") || address.StartsWith("cio"))
				{
					if (plcType == OmronPlcType.CV)
					{
						omronFinsAddress.BitCode = 0;
						omronFinsAddress.WordCode = 128;
					}
					else
					{
						omronFinsAddress.BitCode = OmronFinsDataType.CIO.BitCode;
						omronFinsAddress.WordCode = OmronFinsDataType.CIO.WordCode;
					}
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(3));
				}
				else if (address.StartsWith("WR") || address.StartsWith("wr"))
				{
					omronFinsAddress.BitCode = OmronFinsDataType.WR.BitCode;
					omronFinsAddress.WordCode = OmronFinsDataType.WR.WordCode;
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2));
				}
				else if (address.StartsWith("HR") || address.StartsWith("hr"))
				{
					omronFinsAddress.BitCode = OmronFinsDataType.HR.BitCode;
					omronFinsAddress.WordCode = OmronFinsDataType.HR.WordCode;
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2));
				}
				else if (address.StartsWith("AR") || address.StartsWith("ar"))
				{
					if (plcType == OmronPlcType.CV)
					{
						omronFinsAddress.BitCode = 0;
						omronFinsAddress.WordCode = 128;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2)) + 45056;
					}
					else
					{
						omronFinsAddress.BitCode = OmronFinsDataType.AR.BitCode;
						omronFinsAddress.WordCode = OmronFinsDataType.AR.WordCode;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2));
					}
				}
				else if (address.StartsWith("CF") || address.StartsWith("cf"))
				{
					omronFinsAddress.BitCode = 7;
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(2));
				}
				else if (address.StartsWith("EM") || address.StartsWith("em") || address.StartsWith("E") || address.StartsWith("e"))
				{
					if (address.IndexOf('.') > 0)
					{
						int num = Convert.ToInt32(address.SplitDot()[0].Substring((address[1] != 'M' && address[1] != 'm') ? 1 : 2), 16);
						if (num < 16)
						{
							omronFinsAddress.BitCode = (byte)(32 + num);
							if (plcType == OmronPlcType.CV)
							{
								omronFinsAddress.WordCode = (byte)(144 + num);
							}
							else
							{
								omronFinsAddress.WordCode = (byte)(160 + num);
							}
						}
						else
						{
							omronFinsAddress.BitCode = (byte)(224 + num - 16);
							omronFinsAddress.WordCode = (byte)(96 + num - 16);
						}
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(address.IndexOf('.') + 1));
					}
					else
					{
						omronFinsAddress.BitCode = 10;
						omronFinsAddress.WordCode = 152;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring((address[1] != 'M' && address[1] != 'm') ? 1 : 2));
					}
				}
				else if (address.StartsWith("D") || address.StartsWith("d"))
				{
					omronFinsAddress.BitCode = OmronFinsDataType.DM.BitCode;
					omronFinsAddress.WordCode = OmronFinsDataType.DM.WordCode;
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(1));
				}
				else if (address.StartsWith("C") || address.StartsWith("c"))
				{
					if (plcType == OmronPlcType.CV)
					{
						omronFinsAddress.BitCode = 0;
						omronFinsAddress.WordCode = 128;
					}
					else
					{
						omronFinsAddress.BitCode = OmronFinsDataType.CIO.BitCode;
						omronFinsAddress.WordCode = OmronFinsDataType.CIO.WordCode;
					}
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(1));
				}
				else if (address.StartsWith("W") || address.StartsWith("w"))
				{
					omronFinsAddress.BitCode = OmronFinsDataType.WR.BitCode;
					omronFinsAddress.WordCode = OmronFinsDataType.WR.WordCode;
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(1));
				}
				else if (address.StartsWith("H") || address.StartsWith("h"))
				{
					omronFinsAddress.BitCode = OmronFinsDataType.HR.BitCode;
					omronFinsAddress.WordCode = OmronFinsDataType.HR.WordCode;
					omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(1));
				}
				else
				{
					if (!address.StartsWith("A") && !address.StartsWith("a"))
					{
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
					if (plcType == OmronPlcType.CV)
					{
						omronFinsAddress.BitCode = 0;
						omronFinsAddress.WordCode = 128;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(1)) + 45056;
					}
					else
					{
						omronFinsAddress.BitCode = OmronFinsDataType.AR.BitCode;
						omronFinsAddress.WordCode = OmronFinsDataType.AR.WordCode;
						omronFinsAddress.AddressStart = CalculateBitIndex(address.Substring(1));
					}
				}
			}
			catch (Exception ex)
			{
				return new OResult<OmronFinsAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(omronFinsAddress);
		}
	}
	/// <summary>
	/// 西门子的地址数据信息，主要包含数据代码，DB块，偏移地址（偏移地址对于不是CT类型而已，是位为单位的），当处于写入时，Length无效<br />
	/// Address data information of Siemens, mainly including data code, DB block, offset address, when writing, Length is invalid
	/// </summary>
	public class S7AddressData : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置等待读取的数据的代码<br />
		/// Get or set the code of the data waiting to be read
		/// </summary>
		public byte DataCode { get; set; }

		/// <summary>
		/// 获取或设置PLC的DB块数据信息<br />
		/// Get or set PLC DB data information
		/// </summary>
		public ushort DbBlock { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// Instantiate a default object
		/// </summary>
		public S7AddressData()
		{
		}

		/// <summary>
		/// 从另一个 <see cref="T:Snet.Driver.Core.Address.S7AddressData" /> 对象进行实例化<br />
		/// Instantiate from another <see cref="T:Snet.Driver.Core.Address.S7AddressData" /> object
		/// </summary>
		/// <param name="s7Address">S7地址对象</param>
		public S7AddressData(S7AddressData s7Address)
		{
			base.AddressStart = s7Address.AddressStart;
			base.Length = s7Address.Length;
			DbBlock = s7Address.DbBlock;
			DataCode = s7Address.DataCode;
		}

		/// <summary>
		/// 从指定的地址信息解析成真正的设备地址信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		public override void Parse(string address, ushort length)
		{
			OResult<S7AddressData> oResult = ParseFrom(address, length);
			if (oResult.IsSuccess)
			{
				base.AddressStart = oResult.Content.AddressStart;
				base.Length = oResult.Content.Length;
				DataCode = oResult.Content.DataCode;
				DbBlock = oResult.Content.DbBlock;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			if (DataCode == 31)
			{
				return "T" + base.AddressStart;
			}
			if (DataCode == 30)
			{
				return "C" + base.AddressStart;
			}
			if (DataCode == 5)
			{
				return "SM" + GetActualStringAddress(base.AddressStart);
			}
			if (DataCode == 6)
			{
				return "AI" + GetActualStringAddress(base.AddressStart);
			}
			if (DataCode == 7)
			{
				return "AQ" + GetActualStringAddress(base.AddressStart);
			}
			if (DataCode == 128)
			{
				return "P" + GetActualStringAddress(base.AddressStart);
			}
			if (DataCode == 129)
			{
				return "I" + GetActualStringAddress(base.AddressStart);
			}
			if (DataCode == 130)
			{
				return "Q" + GetActualStringAddress(base.AddressStart);
			}
			if (DataCode == 131)
			{
				return "M" + GetActualStringAddress(base.AddressStart);
			}
			if (DataCode == 132)
			{
				return "DB" + DbBlock + "." + GetActualStringAddress(base.AddressStart);
			}
			return base.AddressStart.ToString();
		}

		private static string GetActualStringAddress(int addressStart)
		{
			if (addressStart % 8 == 0)
			{
				return (addressStart / 8).ToString();
			}
			return $"{addressStart / 8}.{addressStart % 8}";
		}

		/// <summary>
		/// 计算特殊的地址信息<br />
		/// Calculate Special Address information
		/// </summary>
		/// <param name="address">字符串地址 -&gt; String address</param>
		/// <param name="isCT">是否是定时器和计数器的地址</param>
		/// <returns>实际值 -&gt; Actual value</returns>
		public static int CalculateAddressStarted(string address, bool isCT = false)
		{
			if (address.IndexOf('.') < 0)
			{
				if (isCT)
				{
					return Convert.ToInt32(address);
				}
				return Convert.ToInt32(address) * 8;
			}
			string[] array = address.Split('.');
			return Convert.ToInt32(array[0]) * 8 + Convert.ToInt32(array[1]);
		}

		/// <summary>
		/// 从实际的西门子的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Siemens address
		/// </summary>
		/// <param name="address">西门子的地址数据信息</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<S7AddressData> ParseFrom(string address)
		{
			return ParseFrom(address, 0);
		}

		/// <summary>
		/// 从实际的西门子的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Siemens address
		/// </summary>
		/// <param name="address">西门子的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<S7AddressData> ParseFrom(string address, ushort length)
		{
			S7AddressData s7AddressData = new S7AddressData();
			try
			{
				address = address.ToUpper();
				s7AddressData.Length = length;
				s7AddressData.DbBlock = 0;
				if (address.StartsWith("SM"))
				{
					s7AddressData.DataCode = 5;
					if (address.StartsWith("SMX") || address.StartsWith("SMB") || address.StartsWith("SMW") || address.StartsWith("SMD"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(3));
					}
					else
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(2));
					}
				}
				else if (address.StartsWith("AI"))
				{
					s7AddressData.DataCode = 6;
					if (address.StartsWith("AIX") || address.StartsWith("AIB") || address.StartsWith("AIW") || address.StartsWith("AID"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(3));
					}
					else
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(2));
					}
				}
				else if (address.StartsWith("AQ"))
				{
					s7AddressData.DataCode = 7;
					if (address.StartsWith("AQX") || address.StartsWith("AQB") || address.StartsWith("AQW") || address.StartsWith("AQD"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(3));
					}
					else
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(2));
					}
				}
				else if (address[0] == 'P')
				{
					s7AddressData.DataCode = 128;
					if (address.StartsWith("PIX") || address.StartsWith("PIB") || address.StartsWith("PIW") || address.StartsWith("PID") || address.StartsWith("PQX") || address.StartsWith("PQB") || address.StartsWith("PQW") || address.StartsWith("PQD"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(3));
					}
					else if (address.StartsWith("PI") || address.StartsWith("PQ"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(2));
					}
					else
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(1));
					}
				}
				else if (address[0] == 'I')
				{
					s7AddressData.DataCode = 129;
					if (address.StartsWith("IX") || address.StartsWith("IB") || address.StartsWith("IW") || address.StartsWith("ID"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(2));
					}
					else
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(1));
					}
				}
				else if (address[0] == 'Q')
				{
					s7AddressData.DataCode = 130;
					if (address.StartsWith("QX") || address.StartsWith("QB") || address.StartsWith("QW") || address.StartsWith("QD"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(2));
					}
					else
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(1));
					}
				}
				else if (address[0] == 'M')
				{
					s7AddressData.DataCode = 131;
					if (address.StartsWith("MX") || address.StartsWith("MB") || address.StartsWith("MW") || address.StartsWith("MD"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(2));
					}
					else
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(1));
					}
				}
				else if (address[0] == 'D' || address.Substring(0, 2) == "DB")
				{
					s7AddressData.DataCode = 132;
					string[] array = address.Split('.');
					if (address[1] == 'B')
					{
						s7AddressData.DbBlock = Convert.ToUInt16(array[0].Substring(2));
					}
					else
					{
						s7AddressData.DbBlock = Convert.ToUInt16(array[0].Substring(1));
					}
					string text = address.Substring(address.IndexOf('.') + 1);
					if (text.StartsWith("DBX") || text.StartsWith("DBB") || text.StartsWith("DBW") || text.StartsWith("DBD"))
					{
						text = text.Substring(3);
					}
					s7AddressData.AddressStart = CalculateAddressStarted(text);
				}
				else if (address[0] == 'T')
				{
					s7AddressData.DataCode = 31;
					s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(1), isCT: true);
				}
				else if (address[0] == 'C')
				{
					s7AddressData.DataCode = 30;
					s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(1), isCT: true);
				}
				else
				{
					if (address[0] != 'V')
					{
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
					s7AddressData.DataCode = 132;
					s7AddressData.DbBlock = 1;
					if (address.StartsWith("VB") || address.StartsWith("VW") || address.StartsWith("VD") || address.StartsWith("VX"))
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(2));
					}
					else
					{
						s7AddressData.AddressStart = CalculateAddressStarted(address.Substring(1));
					}
				}
			}
			catch (Exception ex)
			{
				return new OResult<S7AddressData>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(s7AddressData);
		}
	}
	/// <summary>
	/// 丰田工机PLC的地址类对象
	/// </summary>
	public class ToyoPucAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置等待读取的地址的PRG编号，如果小于0，则表示不使用。<br />
		/// Gets or sets the PRG number of the address waiting to be read, if less than 0, it means that it is not used.
		/// </summary>
		public int PRG { get; set; } = -1;

		/// <summary>
		/// 是否允许位写入操作<br />
		/// Whether to allow bit write operations
		/// </summary>
		public bool WriteBitEnabled { get; set; }

		/// <inheritdoc />
		public override string ToString()
		{
			return base.AddressStart.ToString();
		}

		/// <summary>
		/// 从实际的丰田PLC的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Vigor address
		/// </summary>
		/// <param name="address">丰田的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="isBit">是否是对位进行访问的</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<ToyoPucAddress> ParseFrom(string address, ushort length, bool isBit)
		{
			ToyoPucAddress toyoPucAddress = new ToyoPucAddress();
			toyoPucAddress.Length = length;
			toyoPucAddress.PRG = SnetHelper.ExtractParameter(ref address, "prg", -1);
			try
			{
				if (address[0] == 'K' || address[0] == 'k')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + (isBit ? 512 : 32);
					toyoPucAddress.WriteBitEnabled = true;
				}
				else if (address[0] == 'V' || address[0] == 'v')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + (isBit ? 1280 : 80);
					toyoPucAddress.WriteBitEnabled = true;
				}
				else if (address[0] == 'T' || address[0] == 't')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + (isBit ? 1536 : 96);
					toyoPucAddress.WriteBitEnabled = true;
				}
				else if (address[0] == 'C' || address[0] == 'c')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + (isBit ? 1536 : 96);
					toyoPucAddress.WriteBitEnabled = true;
				}
				else if (address[0] == 'L' || address[0] == 'l')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + (isBit ? 2048 : 128);
					toyoPucAddress.WriteBitEnabled = true;
				}
				else if (address[0] == 'X' || address[0] == 'x')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + (isBit ? 4096 : 256);
					toyoPucAddress.WriteBitEnabled = true;
				}
				else if (address[0] == 'Y' || address[0] == 'y')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + (isBit ? 4096 : 256);
					toyoPucAddress.WriteBitEnabled = true;
				}
				else if (address[0] == 'M' || address[0] == 'm')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + (isBit ? 6144 : 384);
					toyoPucAddress.WriteBitEnabled = true;
				}
				else if (address[0] == 'S' || address[0] == 's')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + 512;
				}
				else if (address[0] == 'N' || address[0] == 'n')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + 1536;
				}
				else if (address[0] == 'R' || address[0] == 'r')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + 2048;
				}
				else if (address[0] == 'D' || address[0] == 'd')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + 4096;
				}
				else if (address[0] == 'B' || address[0] == 'b')
				{
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + 24576;
				}
				else if (address[0] == 'E' || address[0] == 'e')
				{
					if (address[1] == 'K' || address[1] == 'k')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + (isBit ? 4096 : 256);
						toyoPucAddress.WriteBitEnabled = true;
					}
					else if (address[1] == 'V' || address[1] == 'v')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + (isBit ? 8192 : 512);
						toyoPucAddress.WriteBitEnabled = true;
					}
					else if (address[1] == 'T' || address[1] == 't')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + (isBit ? 12288 : 768);
						toyoPucAddress.WriteBitEnabled = true;
					}
					else if (address[1] == 'C' || address[1] == 'c')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + (isBit ? 12288 : 768);
						toyoPucAddress.WriteBitEnabled = true;
					}
					else if (address[1] == 'L' || address[1] == 'l')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + (isBit ? 14336 : 896);
						toyoPucAddress.WriteBitEnabled = true;
					}
					else if (address[1] == 'X' || address[1] == 'x')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + (isBit ? 22528 : 1408);
						toyoPucAddress.WriteBitEnabled = true;
					}
					else if (address[1] == 'Y' || address[1] == 'y')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + (isBit ? 22528 : 1408);
						toyoPucAddress.WriteBitEnabled = true;
					}
					else if (address[1] == 'M' || address[1] == 'm')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + (isBit ? 24576 : 1536);
						toyoPucAddress.WriteBitEnabled = true;
					}
					else if (address[1] == 'S' || address[1] == 's')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + 2048;
					}
					else if (address[1] == 'N' || address[1] == 'n')
					{
						toyoPucAddress.PRG = 0;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + 4096;
					}
					else
					{
						if (address[1] != 'B' && address[1] != 'b')
						{
							throw new Exception(StringResources.Language.NotSupportedDataType);
						}
						int num = Convert.ToInt32(address.Substring(2), 16);
						if (num < 32768)
						{
							toyoPucAddress.PRG = 9;
							toyoPucAddress.AddressStart = num;
						}
						else if (num < 65536)
						{
							toyoPucAddress.PRG = 10;
							toyoPucAddress.AddressStart = num - 32768;
						}
						else
						{
							toyoPucAddress.PRG = 11;
							toyoPucAddress.AddressStart = num - 65536;
						}
					}
				}
				else if (address[0] == 'H' || address[0] == 'h')
				{
					toyoPucAddress.PRG = 0;
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16) + 6144;
				}
				else if (address[0] == 'U' || address[0] == 'u')
				{
					toyoPucAddress.PRG = 8;
					toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(1), 16);
				}
				else
				{
					if (address[0] != 'G' && address[0] != 'g')
					{
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
					if (address[1] == 'X' || address[1] == 'x')
					{
						toyoPucAddress.PRG = 7;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16);
					}
					else if (address[1] == 'Y' || address[1] == 'y')
					{
						toyoPucAddress.PRG = 7;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16);
					}
					else
					{
						if (address[1] != 'M' && address[1] != 'm')
						{
							throw new Exception(StringResources.Language.NotSupportedDataType);
						}
						toyoPucAddress.PRG = 7;
						toyoPucAddress.AddressStart = Convert.ToInt32(address.Substring(2), 16) + 4096;
					}
				}
			}
			catch (Exception ex)
			{
				return new OResult<ToyoPucAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(toyoPucAddress);
		}
	}
	/// <summary>
	/// 丰炜PLC的地址类对象
	/// </summary>
	public class VigorAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置等待读取的数据的代码<br />
		/// Get or set the code of the data waiting to be read
		/// </summary>
		public byte DataCode { get; set; }

		/// <inheritdoc />
		public override string ToString()
		{
			return base.AddressStart.ToString();
		}

		/// <summary>
		/// 从实际的丰炜PLC的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual Vigor address
		/// </summary>
		/// <param name="address">丰炜的地址数据信息</param>
		/// <param name="length">读取的数据长度</param>
		/// <param name="isBit">是否是对位进行访问的</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<VigorAddress> ParseFrom(string address, ushort length, bool isBit)
		{
			VigorAddress vigorAddress = new VigorAddress();
			try
			{
				vigorAddress.Length = length;
				if (isBit)
				{
					if (address.StartsWith("SM") || address.StartsWith("sm"))
					{
						vigorAddress.DataCode = 148;
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(2));
					}
					else if (address.StartsWith("TS") || address.StartsWith("ts"))
					{
						vigorAddress.DataCode = 153;
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(2));
					}
					else if (address.StartsWith("TC") || address.StartsWith("tc"))
					{
						vigorAddress.DataCode = 152;
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(2));
					}
					else if (address.StartsWith("CS") || address.StartsWith("cs"))
					{
						vigorAddress.DataCode = 157;
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(2));
					}
					else if (address.StartsWith("CC") || address.StartsWith("cc"))
					{
						vigorAddress.DataCode = 156;
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(2));
					}
					else if (address.StartsWith("X") || address.StartsWith("x"))
					{
						vigorAddress.DataCode = 144;
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(1));
					}
					else if (address.StartsWith("Y") || address.StartsWith("y"))
					{
						vigorAddress.DataCode = 145;
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(1));
					}
					else if (address.StartsWith("M") || address.StartsWith("m"))
					{
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(1));
						if (vigorAddress.AddressStart >= 9000)
						{
							vigorAddress.AddressStart = 0;
							vigorAddress.DataCode = 148;
						}
						else
						{
							vigorAddress.DataCode = 146;
						}
					}
					else
					{
						if (!address.StartsWith("S") && !address.StartsWith("s"))
						{
							return new OResult<VigorAddress>(StringResources.Language.NotSupportedDataType);
						}
						vigorAddress.DataCode = 147;
						vigorAddress.AddressStart = Convert.ToInt32(address.Substring(1));
					}
				}
				else if (address.StartsWith("SD") || address.StartsWith("sd"))
				{
					vigorAddress.DataCode = 161;
					vigorAddress.AddressStart = Convert.ToInt32(address.Substring(2));
				}
				else if (address.StartsWith("D") || address.StartsWith("d"))
				{
					vigorAddress.AddressStart = Convert.ToInt32(address.Substring(1));
					if (vigorAddress.AddressStart >= 9000)
					{
						vigorAddress.DataCode = 161;
						vigorAddress.AddressStart -= 9000;
					}
					else
					{
						vigorAddress.DataCode = 160;
					}
				}
				else if (address.StartsWith("R") || address.StartsWith("r"))
				{
					vigorAddress.DataCode = 162;
					vigorAddress.AddressStart = Convert.ToInt32(address.Substring(1));
				}
				else if (address.StartsWith("T") || address.StartsWith("t"))
				{
					vigorAddress.DataCode = 168;
					vigorAddress.AddressStart = Convert.ToInt32(address.Substring(1));
				}
				else
				{
					if (!address.StartsWith("C") && !address.StartsWith("c"))
					{
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
					vigorAddress.AddressStart = Convert.ToInt32(address.Substring(1));
					if (vigorAddress.AddressStart >= 200)
					{
						vigorAddress.DataCode = 173;
					}
					else
					{
						vigorAddress.DataCode = 172;
					}
				}
			}
			catch (Exception ex)
			{
				return new OResult<VigorAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
			return OResult.CreateSuccessResult(vigorAddress);
		}
	}
	/// <summary>
	/// 信捷内部协议的地址类对象<br />
	/// The address class object of Xinjie internal protocol
	/// </summary>
	public class XinJEAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置等待读取的数据的代码<br />
		/// Get or set the code of the data waiting to be read
		/// </summary>
		public byte DataCode { get; set; }

		/// <summary>
		/// 获取或设置当前的站号信息<br />
		/// Get or set the current station number information
		/// </summary>
		public byte Station { get; set; }

		/// <summary>
		/// 获取或设置协议升级时候的临界地址信息<br />
		/// Get or set the critical address information when the protocol is upgraded
		/// </summary>
		public int CriticalAddress { get; set; }

		/// <summary>
		/// 实例化一个默认的对象<br />
		/// instantiate a default object
		/// </summary>
		public XinJEAddress()
		{
		}

		/// <summary>
		/// 指定类型，地址偏移，临界地址来实例化一个对象<br />
		/// Specify the type, address offset, and critical address to instantiate an object
		/// </summary>
		/// <param name="dataCode">数据的类型代号</param>
		/// <param name="address">偏移地址信息</param>
		/// <param name="criticalAddress">临界地址信息</param>
		/// <param name="station">站号信息</param>
		public XinJEAddress(byte dataCode, int address, int criticalAddress, byte station)
		{
			DataCode = dataCode;
			base.AddressStart = address;
			CriticalAddress = criticalAddress;
			Station = station;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return base.AddressStart.ToString();
		}

		/// <summary>
		/// 从实际的信捷PLC的地址里面解析出地址对象<br />
		/// Resolve the address object from the actual XinJE address
		/// </summary>
		/// <param name="address">信捷的地址数据信息</param>
		/// <param name="length">读取的长度信息</param>
		/// <param name="defaultStation">默认的站号信息</param>
		/// <returns>是否成功的结果对象</returns>
		public static OResult<XinJEAddress> ParseFrom(string address, ushort length, byte defaultStation)
		{
			OResult<XinJEAddress> oResult = ParseFrom(address, defaultStation);
			if (!oResult.IsSuccess)
			{
				return OResult.CreateFailedResult<XinJEAddress>(oResult);
			}
			oResult.Content.Length = length;
			return OResult.CreateSuccessResult(oResult.Content);
		}

		/// <inheritdoc cref="M:Snet.Driver.Core.Address.XinJEAddress.ParseFrom(System.String,System.UInt16,System.Byte)" />
		public static OResult<XinJEAddress> ParseFrom(string address, byte defaultStation)
		{
			try
			{
				byte station = (byte)SnetHelper.ExtractParameter(ref address, "s", defaultStation);
				if (address.StartsWith("HSCD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(139, int.Parse(address.Substring(4)), int.MaxValue, station));
				}
				if (address.StartsWith("ETD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(133, int.Parse(address.Substring(3)), 0, station));
				}
				if (address.StartsWith("HSD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(140, int.Parse(address.Substring(3)), 1024, station));
				}
				if (address.StartsWith("HTD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(137, int.Parse(address.Substring(3)), 1024, station));
				}
				if (address.StartsWith("HCD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(138, int.Parse(address.Substring(3)), 1024, station));
				}
				if (address.StartsWith("SFD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(142, int.Parse(address.Substring(3)), 4096, station));
				}
				if (address.StartsWith("HSC"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(12, int.Parse(address.Substring(3)), int.MaxValue, station));
				}
				if (address.StartsWith("SD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(131, int.Parse(address.Substring(2)), 4096, station));
				}
				if (address.StartsWith("TD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(129, int.Parse(address.Substring(2)), 4096, station));
				}
				if (address.StartsWith("CD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(130, int.Parse(address.Substring(2)), 4096, station));
				}
				if (address.StartsWith("HD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(136, int.Parse(address.Substring(2)), 6144, station));
				}
				if (address.StartsWith("FD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(141, int.Parse(address.Substring(2)), 8192, station));
				}
				if (address.StartsWith("ID"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(134, int.Parse(address.Substring(2)), 0, station));
				}
				if (address.StartsWith("QD"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(135, int.Parse(address.Substring(2)), 0, station));
				}
				if (address.StartsWith("SM"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(13, int.Parse(address.Substring(2)), 4096, station));
				}
				if (address.StartsWith("ET"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(7, int.Parse(address.Substring(2)), 0, station));
				}
				if (address.StartsWith("HM"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(8, int.Parse(address.Substring(2)), 6144, station));
				}
				if (address.StartsWith("HS"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(9, int.Parse(address.Substring(2)), int.MaxValue, station));
				}
				if (address.StartsWith("HT"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(10, int.Parse(address.Substring(2)), 1024, station));
				}
				if (address.StartsWith("HC"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(11, int.Parse(address.Substring(2)), 1024, station));
				}
				if (address.StartsWith("D"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(128, int.Parse(address.Substring(1)), 20480, station));
				}
				if (address.StartsWith("M"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(3, int.Parse(address.Substring(1)), 20480, station));
				}
				if (address.StartsWith("T"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(5, int.Parse(address.Substring(1)), 4096, station));
				}
				if (address.StartsWith("C"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(6, int.Parse(address.Substring(1)), 4096, station));
				}
				if (address.StartsWith("Y"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(2, Convert.ToInt32(address.Substring(1), 8), int.MaxValue, station));
				}
				if (address.StartsWith("X"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(1, Convert.ToInt32(address.Substring(1), 8), int.MaxValue, station));
				}
				if (address.StartsWith("S"))
				{
					return OResult.CreateSuccessResult(new XinJEAddress(4, int.Parse(address.Substring(1)), 8000, station));
				}
				throw new Exception(StringResources.Language.NotSupportedDataType);
			}
			catch (Exception ex)
			{
				return new OResult<XinJEAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}
	}
	/// <summary>
	/// 横河PLC的地址表示类<br />
	/// Yokogawa PLC address display class
	/// </summary>
	public class YokogawaLinkAddress : DeviceAddressDataBase
	{
		/// <summary>
		/// 获取或设置等待读取的数据的代码<br />
		/// Get or set the code of the data waiting to be read
		/// </summary>
		public int DataCode { get; set; }

		/// <summary>
		/// 获取当前横河PLC的地址的二进制表述方式<br />
		/// Obtain the binary representation of the current Yokogawa PLC address
		/// </summary>
		/// <returns>二进制数据信息</returns>
		public byte[] GetAddressBinaryContent()
		{
			return new byte[6]
			{
				BitConverter.GetBytes(DataCode)[1],
				BitConverter.GetBytes(DataCode)[0],
				BitConverter.GetBytes(base.AddressStart)[3],
				BitConverter.GetBytes(base.AddressStart)[2],
				BitConverter.GetBytes(base.AddressStart)[1],
				BitConverter.GetBytes(base.AddressStart)[0]
			};
		}

		/// <inheritdoc />
		public override void Parse(string address, ushort length)
		{
			OResult<YokogawaLinkAddress> oResult = ParseFrom(address, length);
			if (oResult.IsSuccess)
			{
				base.AddressStart = oResult.Content.AddressStart;
				base.Length = oResult.Content.Length;
				DataCode = oResult.Content.DataCode;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return DataCode switch
			{
				49 => "CN" + base.AddressStart, 
				33 => "TN" + base.AddressStart, 
				24 => "X" + base.AddressStart, 
				25 => "Y" + base.AddressStart, 
				9 => "I" + base.AddressStart, 
				5 => "E" + base.AddressStart, 
				13 => "M" + base.AddressStart, 
				20 => "T" + base.AddressStart, 
				3 => "C" + base.AddressStart, 
				12 => "L" + base.AddressStart, 
				4 => "D" + base.AddressStart, 
				2 => "B" + base.AddressStart, 
				6 => "F" + base.AddressStart, 
				18 => "R" + base.AddressStart, 
				22 => "V" + base.AddressStart, 
				26 => "Z" + base.AddressStart, 
				23 => "W" + base.AddressStart, 
				_ => base.AddressStart.ToString(), 
			};
		}

		/// <summary>
		/// 从普通的PLC的地址转换为Snet标准的地址信息
		/// </summary>
		/// <param name="address">地址信息</param>
		/// <param name="length">数据长度</param>
		/// <returns>是否成功的地址结果</returns>
		public static OResult<YokogawaLinkAddress> ParseFrom(string address, ushort length)
		{
			try
			{
				int num = 0;
				int num2 = 0;
				if (address.StartsWith("CN") || address.StartsWith("cn"))
				{
					num = 49;
					num2 = int.Parse(address.Substring(2));
				}
				else if (address.StartsWith("TN") || address.StartsWith("tn"))
				{
					num = 33;
					num2 = int.Parse(address.Substring(2));
				}
				else if (address.StartsWith("X") || address.StartsWith("x"))
				{
					num = 24;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("Y") || address.StartsWith("y"))
				{
					num = 25;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("I") || address.StartsWith("i"))
				{
					num = 9;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("E") || address.StartsWith("e"))
				{
					num = 5;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("M") || address.StartsWith("m"))
				{
					num = 13;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("T") || address.StartsWith("t"))
				{
					num = 20;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("C") || address.StartsWith("c"))
				{
					num = 3;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("L") || address.StartsWith("l"))
				{
					num = 12;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("D") || address.StartsWith("d"))
				{
					num = 4;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("B") || address.StartsWith("b"))
				{
					num = 2;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("F") || address.StartsWith("f"))
				{
					num = 6;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("R") || address.StartsWith("r"))
				{
					num = 18;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("V") || address.StartsWith("v"))
				{
					num = 22;
					num2 = int.Parse(address.Substring(1));
				}
				else if (address.StartsWith("Z") || address.StartsWith("z"))
				{
					num = 26;
					num2 = int.Parse(address.Substring(1));
				}
				else
				{
					if (!address.StartsWith("W") && !address.StartsWith("w"))
					{
						throw new Exception(StringResources.Language.NotSupportedDataType);
					}
					num = 23;
					num2 = int.Parse(address.Substring(1));
				}
				return OResult.CreateSuccessResult(new YokogawaLinkAddress
				{
					DataCode = num,
					AddressStart = num2,
					Length = length
				});
			}
			catch (Exception ex)
			{
				return new OResult<YokogawaLinkAddress>(DeviceAddressDataBase.GetUnsupportedAddressInfo(address, ex));
			}
		}
	}
