	/// <summary>
	/// 一个高效的数组管理类，用于高效控制固定长度的数组实现<br />
	/// An efficient array management class for efficient control of fixed-length array implementations
	/// </summary>
	/// <typeparam name="T">泛型类型</typeparam>
	public class SharpList<T>
	{
		private T[] array;

		private int capacity = 2048;

		private int count;

		private int lastIndex;

		private object objLock = new object();

		/// <summary>
		/// 获取数组设定时候的固定数量<br />
		/// Gets the fixed number of arrays when they are set
		/// </summary>
		public int Count => count;

		/// <summary>
		/// 获取或设置指定索引的位置的数据<br />
		/// Gets or sets the data at the specified index
		/// </summary>
		/// <param name="index">索引位置</param>
		/// <returns>当前索引的数据值</returns>
		public T this[int index]
		{
			get
			{
				if (index < 0)
				{
					throw new IndexOutOfRangeException("Index must larger than zero");
				}
				if (index >= count)
				{
					throw new IndexOutOfRangeException("Index must smaller than array length");
				}
				lock (objLock)
				{
					if (lastIndex < count)
					{
						return array[index];
					}
					return array[index + lastIndex - count];
				}
			}
			set
			{
				if (index < 0)
				{
					throw new IndexOutOfRangeException("Index must larger than zero");
				}
				if (index >= count)
				{
					throw new IndexOutOfRangeException("Index must smaller than array length");
				}
				lock (objLock)
				{
					if (lastIndex < count)
					{
						array[index] = value;
					}
					else
					{
						array[index + lastIndex - count] = value;
					}
				}
			}
		}

		/// <summary>
		/// 实例化一个对象，需要指定数组的最大长度信息，以及是否从最后一个添加，之前的值为类型默认值<br />
		/// To instantiate an object, you need to specify the maximum length of the array and whether to add it from the last value before the type default
		/// </summary>
		/// <param name="count">数组的固定长度信息</param>
		/// <param name="appendLast">是否从最后一个索引开始添加</param>
		public SharpList(int count, bool appendLast = false)
		{
			if (count > 65535)
			{
				capacity = 8192;
			}
			else if (count > 8192)
			{
				capacity = 4096;
			}
			array = new T[capacity + count];
			this.count = count;
			if (appendLast)
			{
				lastIndex = count;
			}
		}

		private void addItem(T value)
		{
			if (lastIndex >= capacity + count)
			{
				T[] destinationArray = new T[capacity + count];
				Array.Copy(array, capacity, destinationArray, 0, count);
				array = destinationArray;
				lastIndex = count;
			}
			array[lastIndex++] = value;
		}

		/// <summary>
		/// 新增一个数据值<br />
		/// Add a data value
		/// </summary>
		/// <param name="value">数据值</param>
		public void Add(T value)
		{
			lock (objLock)
			{
				addItem(value);
			}
		}

		/// <summary>
		/// 将一个可以遍历的数据集合一次性批量的添加到当前的数据缓存中<br />
		/// Adds a traversable data set to the current data cache in one batch
		/// </summary>
		/// <param name="values">批量数据信息</param>
		public void Add(IEnumerable<T> values)
		{
			lock (objLock)
			{
				foreach (T value in values)
				{
					addItem(value);
				}
			}
		}

		/// <summary>
		/// 获取数据的浅拷贝数组对象<br />
		/// Get array value of data
		/// </summary>
		/// <returns>数组值</returns>
		public T[] ToArray()
		{
			T[] array = null;
			lock (objLock)
			{
				if (lastIndex < count)
				{
					array = new T[lastIndex];
					Array.Copy(this.array, 0, array, 0, lastIndex);
				}
				else
				{
					array = new T[count];
					Array.Copy(this.array, lastIndex - count, array, 0, count);
				}
			}
			return array;
		}

		/// <summary>
		/// 获取最后一个值，如果从来没有添加过，则引发异常<br />
		/// Gets the last value and throws an exception if it has never been added
		/// </summary>
		/// <returns>值信息</returns>
		public T LastValue()
		{
			T result = default(T);
			lock (objLock)
			{
				if (lastIndex - 1 < count + capacity)
				{
					return array[lastIndex - 1];
				}
				return result;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SharpList<{typeof(T)}>[{capacity}]";
		}
	}
	/// <summary>
	/// 一个软件基础类，提供常用的一些静态方法，比如字符串转换，字节转换的方法<br />
	/// A software-based class that provides some common static methods，Such as string conversion, byte conversion method
	/// </summary>
	public class SoftBasic
	{
		/// <summary>
		/// 从一个字节大小返回带单位的描述，主要是用于显示操作<br />
		/// Returns a description with units from a byte size, mainly for display operations
		/// </summary>
		/// <param name="size">实际的大小值</param>
		/// <returns>最终的字符串值</returns>
		/// <example>
		/// 比如说我们获取了文件的长度，这个长度可以来自于本地，也可以来自于数据库查询
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="GetSizeDescriptionExample" title="GetSizeDescription示例" />
		/// </example>
		public static string GetSizeDescription(long size)
		{
			if (size < 1000)
			{
				return size + " B";
			}
			if (size < 1000000)
			{
				return ((float)size / 1024f).ToString("F2") + " Kb";
			}
			if (size < 1000000000)
			{
				return ((float)size / 1024f / 1024f).ToString("F2") + " Mb";
			}
			return ((float)size / 1024f / 1024f / 1024f).ToString("F2") + " Gb";
		}

		/// <summary>
		/// 从一个时间差返回带单位的描述，主要是用于显示操作。<br />
		/// Returns a description with units from a time difference, mainly for display operations.
		/// </summary>
		/// <param name="ts">实际的时间差</param>
		/// <returns>最终的字符串值</returns>
		/// <example>
		/// 比如说我们获取了一个时间差信息
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="GetTimeSpanDescriptionExample" title="GetTimeSpanDescription示例" />
		/// </example>
		public static string GetTimeSpanDescription(TimeSpan ts)
		{
			if (ts.TotalSeconds <= 60.0)
			{
				return (int)ts.TotalSeconds + StringResources.Language.TimeDescriptionSecond;
			}
			if (ts.TotalMinutes <= 60.0)
			{
				return ts.TotalMinutes.ToString("F1") + StringResources.Language.TimeDescriptionMinute;
			}
			if (ts.TotalHours <= 24.0)
			{
				return ts.TotalHours.ToString("F2") + StringResources.Language.TimeDescriptionHour;
			}
			return ts.TotalDays.ToString("F2") + StringResources.Language.TimeDescriptionDay;
		}

		/// <summary>
		/// 将数组格式化为显示的字符串的信息，支持所有的类型对象<br />
		/// Formats the array into the displayed string information, supporting all types of objects
		/// </summary>
		/// <typeparam name="T">数组的类型</typeparam>
		/// <param name="array">数组信息</param>
		/// <returns>最终显示的信息</returns>
		public static string ArrayFormat<T>(T[] array)
		{
			return ArrayFormat(array, string.Empty);
		}

		/// <summary>
		/// 将数组格式化为显示的字符串的信息，支持所有的类型对象<br />
		/// Formats the array into the displayed string information, supporting all types of objects
		/// </summary>
		/// <typeparam name="T">数组的类型</typeparam>
		/// <param name="array">数组信息</param>
		/// <param name="format">格式化的信息</param>
		/// <returns>最终显示的信息</returns>
		public static string ArrayFormat<T>(T[] array, string format)
		{
			if (array == null)
			{
				return "NULL";
			}
			StringBuilder stringBuilder = new StringBuilder("[");
			for (int i = 0; i < array.Length; i++)
			{
				stringBuilder.Append(string.IsNullOrEmpty(format) ? array[i].ToString() : string.Format(format, array[i]));
				if (i != array.Length - 1)
				{
					stringBuilder.Append(",");
				}
			}
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}

		/// <summary>
		/// 将数组格式化为显示的字符串的信息，支持所有的类型对象<br />
		/// Formats the array into the displayed string information, supporting all types of objects
		/// </summary>
		/// <typeparam name="T">数组的类型</typeparam>
		/// <param name="array">数组信息</param>
		/// <returns>最终显示的信息</returns>
		public static string ArrayFormat<T>(T array)
		{
			return ArrayFormat(array, string.Empty);
		}

		/// <summary>
		/// 将数组格式化为显示的字符串的信息，支持所有的类型对象<br />
		/// Formats the array into the displayed string information, supporting all types of objects
		/// </summary>
		/// <typeparam name="T">数组的类型</typeparam>
		/// <param name="array">数组信息</param>
		/// <param name="format">格式化的信息</param>
		/// <returns>最终显示的信息</returns>
		public static string ArrayFormat<T>(T array, string format)
		{
			StringBuilder stringBuilder = new StringBuilder("[");
			if (array is Array array2)
			{
				foreach (object item in array2)
				{
					stringBuilder.Append(string.IsNullOrEmpty(format) ? item.ToString() : string.Format(format, item));
					stringBuilder.Append(",");
				}
				if (array2.Length > 0 && stringBuilder[stringBuilder.Length - 1] == ',')
				{
					stringBuilder.Remove(stringBuilder.Length - 1, 1);
				}
			}
			else
			{
				stringBuilder.Append(string.IsNullOrEmpty(format) ? array.ToString() : string.Format(format, array));
			}
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}

		/// <summary>
		/// 一个通用的数组新增个数方法，会自动判断越界情况，越界的情况下，会自动的截断或是填充<br />
		/// A common array of new methods, will automatically determine the cross-border situation, in the case of cross-border, will be automatically truncated or filled
		/// </summary>
		/// <typeparam name="T">数据类型</typeparam>
		/// <param name="array">原数据</param>
		/// <param name="data">等待新增的数据</param>
		/// <param name="max">原数据的最大值</param>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="AddArrayDataExample" title="AddArrayData示例" />
		/// </example>
		public static void AddArrayData<T>(ref T[] array, T[] data, int max)
		{
			if (data == null || data.Length == 0)
			{
				return;
			}
			if (array.Length == max)
			{
				Array.Copy(array, data.Length, array, 0, array.Length - data.Length);
				Array.Copy(data, 0, array, array.Length - data.Length, data.Length);
			}
			else if (array.Length + data.Length > max)
			{
				T[] array2 = new T[max];
				for (int i = 0; i < max - data.Length; i++)
				{
					array2[i] = array[i + (array.Length - max + data.Length)];
				}
				for (int j = 0; j < data.Length; j++)
				{
					array2[array2.Length - data.Length + j] = data[j];
				}
				array = array2;
			}
			else
			{
				T[] array3 = new T[array.Length + data.Length];
				for (int k = 0; k < array.Length; k++)
				{
					array3[k] = array[k];
				}
				for (int l = 0; l < data.Length; l++)
				{
					array3[array3.Length - data.Length + l] = data[l];
				}
				array = array3;
			}
		}

		/// <summary>
		/// 将一个数组进行扩充到指定长度，或是缩短到指定长度<br />
		/// Extend an array to a specified length, or shorten to a specified length or fill
		/// </summary>
		/// <typeparam name="T">数组的类型</typeparam>
		/// <param name="data">原先数据的数据</param>
		/// <param name="length">新数组的长度</param>
		/// <returns>新数组长度信息</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArrayExpandToLengthExample" title="ArrayExpandToLength示例" />
		/// </example>
		public static T[] ArrayExpandToLength<T>(T[] data, int length)
		{
			if (data == null)
			{
				return new T[length];
			}
			if (data.Length == length)
			{
				return data;
			}
			T[] array = new T[length];
			Array.Copy(data, array, Math.Min(data.Length, array.Length));
			return array;
		}

		/// <summary>
		/// 将一个数组进行扩充到偶数长度<br />
		/// Extend an array to even lengths
		/// </summary>
		/// <typeparam name="T">数组的类型</typeparam>
		/// <param name="data">原先数据的数据</param>
		/// <returns>新数组长度信息</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArrayExpandToLengthEvenExample" title="ArrayExpandToLengthEven示例" />
		/// </example>
		public static T[] ArrayExpandToLengthEven<T>(T[] data)
		{
			if (data == null)
			{
				return new T[0];
			}
			if (data.Length % 2 == 1)
			{
				return ArrayExpandToLength(data, data.Length + 1);
			}
			return data;
		}

		/// <summary>
		/// 将指定的数据按照指定长度进行分割，例如int[10]，指定长度4，就分割成int[4],int[4],int[2]，然后拼接list<br />
		/// Divide the specified data according to the specified length, such as int [10], and specify the length of 4 to divide into int [4], int [4], int [2], and then concatenate the list
		/// </summary>
		/// <typeparam name="T">数组的类型</typeparam>
		/// <param name="array">等待分割的数组</param>
		/// <param name="length">指定的长度信息</param>
		/// <returns>分割后结果内容</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArraySplitByLengthExample" title="ArraySplitByLength示例" />
		/// </example>
		public static List<T[]> ArraySplitByLength<T>(T[] array, int length)
		{
			if (array == null)
			{
				return new List<T[]>();
			}
			List<T[]> list = new List<T[]>();
			int num = 0;
			while (num < array.Length)
			{
				if (num + length < array.Length)
				{
					T[] array2 = new T[length];
					Array.Copy(array, num, array2, 0, length);
					num += length;
					list.Add(array2);
				}
				else
				{
					T[] array3 = new T[array.Length - num];
					Array.Copy(array, num, array3, 0, array3.Length);
					num += length;
					list.Add(array3);
				}
			}
			return list;
		}

		/// <summary>
		/// 将整数进行有效的拆分成数组，指定每个元素的最大值<br />
		/// Effectively split integers into arrays, specifying the maximum value for each element
		/// </summary>
		/// <param name="integer">整数信息</param>
		/// <param name="everyLength">单个的数组长度</param>
		/// <returns>拆分后的数组长度</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="SplitIntegerToArrayExample" title="SplitIntegerToArray示例" />
		/// </example>
		public static int[] SplitIntegerToArray(int integer, int everyLength)
		{
			int[] array = new int[integer / everyLength + ((integer % everyLength != 0) ? 1 : 0)];
			for (int i = 0; i < array.Length; i++)
			{
				if (i == array.Length - 1)
				{
					array[i] = ((integer % everyLength == 0) ? everyLength : (integer % everyLength));
				}
				else
				{
					array[i] = everyLength;
				}
			}
			return array;
		}

		/// <summary>
		/// 判断两个字节的指定部分是否相同<br />
		/// Determines whether the specified portion of a two-byte is the same
		/// </summary>
		/// <param name="b1">第一个字节</param>
		/// <param name="start1">第一个字节的起始位置</param>
		/// <param name="b2">第二个字节</param>
		/// <param name="start2">第二个字节的起始位置</param>
		/// <param name="length">校验的长度</param>
		/// <returns>返回是否相等</returns>
		/// <exception cref="T:System.IndexOutOfRangeException"></exception>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="IsTwoBytesEquelExample1" title="IsTwoBytesEquel示例" />
		/// </example>
		public static bool IsTwoBytesEquel(byte[] b1, int start1, byte[] b2, int start2, int length)
		{
			if (b1 == null || b2 == null)
			{
				return false;
			}
			for (int i = 0; i < length; i++)
			{
				if (b1[i + start1] != b2[i + start2])
				{
					return false;
				}
			}
			return true;
		}

		/// <summary>
		/// 判断两个字节的指定部分是否相同<br />
		/// Determines whether the specified portion of a two-byte is the same
		/// </summary>
		/// <param name="b1">第一个字节</param>
		/// <param name="b2">第二个字节</param>
		/// <returns>返回是否相等</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="IsTwoBytesEquelExample2" title="IsTwoBytesEquel示例" />
		/// </example>
		public static bool IsTwoBytesEquel(byte[] b1, byte[] b2)
		{
			if (b1 == null || b2 == null)
			{
				return false;
			}
			if (b1.Length != b2.Length)
			{
				return false;
			}
			return IsTwoBytesEquel(b1, 0, b2, 0, b1.Length);
		}

		/// <summary>
		/// 判断两个数据的令牌是否相等<br />
		/// Determines whether the tokens of two data are equal
		/// </summary>
		/// <param name="head">字节数据</param>
		/// <param name="token">GUID数据</param>
		/// <returns>返回是否相等</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="IsTwoTokenEquelExample" title="IsByteTokenEquel示例" />
		/// </example>
		public static bool IsByteTokenEquel(byte[] head, Guid token)
		{
			return IsTwoBytesEquel(head, 12, token.ToByteArray(), 0, 16);
		}

		/// <summary>
		/// 判断两个数据的令牌是否相等<br />
		/// Determines whether the tokens of two data are equal
		/// </summary>
		/// <param name="token1">第一个令牌</param>
		/// <param name="token2">第二个令牌</param>
		/// <returns>返回是否相等</returns>
		public static bool IsTwoTokenEquel(Guid token1, Guid token2)
		{
			return IsTwoBytesEquel(token1.ToByteArray(), 0, token2.ToByteArray(), 0, 16);
		}

		/// <summary>
