		/// <summary>
		/// 从字节数组构建一个ASCII格式的数据内容<br />
		/// Byte array to construct an ASCII format data content
		/// </summary>
		/// <param name="value">字节信息</param>
		/// <returns>ASCII格式的地址</returns>
		public static byte[] BuildAsciiBytesFrom(byte[] value)
		{
			byte[] array = new byte[value.Length * 2];
			for (int i = 0; i < value.Length; i++)
			{
				BuildAsciiBytesFrom(value[i]).CopyTo(array, 2 * i);
			}
			return array;
		}

		private static byte GetDataByBitIndex(int offset)
		{
			return offset switch
			{
				0 => 1, 
				1 => 2, 
				2 => 4, 
				3 => 8, 
				4 => 16, 
				5 => 32, 
				6 => 64, 
				7 => 128, 
				_ => 0, 
			};
		}

		/// <summary>
		/// 获取byte数据类型的第offset位，是否为True<br />
		/// Gets the index bit of the byte data type, whether it is True
		/// </summary>
		/// <param name="value">byte数值</param>
		/// <param name="offset">索引位置</param>
		/// <returns>结果</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="BoolOnByteIndex" title="BoolOnByteIndex示例" />
		/// </example>
		public static bool BoolOnByteIndex(byte value, int offset)
		{
			byte dataByBitIndex = GetDataByBitIndex(offset);
			return (value & dataByBitIndex) == dataByBitIndex;
		}

		/// <summary>
		/// 设置取byte数据类型的第offset位，是否为True<br />
		/// Set the offset bit of the byte data type, whether it is True
		/// </summary>
		/// <param name="byt">byte数值</param>
		/// <param name="offset">索引位置</param>
		/// <param name="value">写入的结果值</param>
		/// <returns>结果</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="SetBoolOnByteIndex" title="SetBoolOnByteIndex示例" />
		/// </example>
		public static byte SetBoolOnByteIndex(byte byt, int offset, bool value)
		{
			byte dataByBitIndex = GetDataByBitIndex(offset);
			if (value)
			{
				return (byte)(byt | dataByBitIndex);
			}
			return (byte)(byt & ~dataByBitIndex);
		}

		/// <summary>
		/// 将bool数组转换到byte数组<br />
		/// Converting a bool array to a byte array
		/// </summary>
		/// <param name="array">bool数组</param>
		/// <returns>转换后的字节数组</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="BoolArrayToByte" title="BoolArrayToByte示例" />
		/// </example>
		public static byte[] BoolArrayToByte(bool[] array)
		{
			if (array == null)
			{
				return null;
			}
			byte[] array2 = new byte[(array.Length % 8 == 0) ? (array.Length / 8) : (array.Length / 8 + 1)];
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i])
				{
					array2[i / 8] += GetDataByBitIndex(i % 8);
				}
			}
			return array2;
		}

		/// <summary>
		/// 将bool数组转换为字符串进行显示，true被转为1，false转换为0<br />
		/// Convert the bool array to a string for display, true is converted to 1, false is converted to 0
		/// </summary>
		/// <param name="array">bool数组</param>
		/// <returns>转换后的字符串</returns>
		public static string BoolArrayToString(bool[] array)
		{
			if (array == null)
			{
				return string.Empty;
			}
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < array.Length; i++)
			{
				stringBuilder.Append(array[i] ? "1" : "0");
			}
			return stringBuilder.ToString();
		}

		/// <summary>
		/// 从Byte数组中提取位数组，length代表位数，例如数组 03 A1 长度10转为 [1100 0000 10]<br />
		/// Extracts a bit array from a byte array, length represents the number of digits
		/// </summary>
		/// <param name="inBytes">原先的字节数组</param>
		/// <param name="length">想要转换的长度，如果超出自动会缩小到数组最大长度</param>
		/// <returns>转换后的bool数组</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ByteToBoolArray" title="ByteToBoolArray示例" />
		/// </example> 
		public static bool[] ByteToBoolArray(byte[] inBytes, int length)
		{
			if (inBytes == null)
			{
				return null;
			}
			if (length > inBytes.Length * 8)
			{
				length = inBytes.Length * 8;
			}
			bool[] array = new bool[length];
			for (int i = 0; i < length; i++)
			{
				array[i] = BoolOnByteIndex(inBytes[i / 8], i % 8);
			}
			return array;
		}

		/// <summary>
		/// 从Byte数组中提取位数组，length代表位数，例如数组 01 00 长度10转为 [true,false]<br />
		/// </summary>
		/// <param name="inBytes">原先的字节数组</param>
		/// <param name="length">想要转换的长度，如果超出自动会缩小到数组最大长度</param>
		/// <param name="trueValue">当为true时对应的byte值</param>
		/// <returns>转换后bool数组</returns>
		public static bool[] ByteToBoolArray(byte[] inBytes, int length, byte trueValue)
		{
			if (inBytes == null)
			{
				return null;
			}
			if (length > inBytes.Length)
			{
				length = inBytes.Length;
			}
			bool[] array = new bool[length];
			for (int i = 0; i < length; i++)
			{
				array[i] = inBytes[i] == trueValue;
			}
			return array;
		}

		/// <summary>
		/// 从Byte数组中提取所有的位数组<br />
		/// Extracts a bit array from a byte array, length represents the number of digits
		/// </summary>
		/// <param name="InBytes">原先的字节数组</param>
		/// <returns>转换后的bool数组</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ByteToBoolArray" title="ByteToBoolArray示例" />
		/// </example> 
		public static bool[] ByteToBoolArray(byte[] InBytes)
		{
			if (InBytes != null)
			{
				return ByteToBoolArray(InBytes, InBytes.Length * 8);
			}
			return null;
		}

		/// <summary>
		/// 将一个数组的前后移除指定位数，返回新的一个数组<br />
		/// Removes a array before and after the specified number of bits, returning a new array
		/// </summary>
		/// <param name="value">数组</param>
		/// <param name="leftLength">前面的位数</param>
		/// <param name="rightLength">后面的位数</param>
		/// <returns>新的数组</returns>
		/// <exception cref="T:System.RankException"></exception>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArrayRemoveDouble" title="ArrayRemoveDouble示例" />
		/// </example> 
		public static T[] ArrayRemoveDouble<T>(T[] value, int leftLength, int rightLength)
		{
			if (value == null)
			{
				return null;
			}
			if (value.Length <= leftLength + rightLength)
			{
				return new T[0];
			}
			T[] array = new T[value.Length - leftLength - rightLength];
			Array.Copy(value, leftLength, array, 0, array.Length);
			return array;
		}

		/// <summary>
		/// 将一个数组的前面指定位数移除，返回新的一个数组<br />
		/// Removes the preceding specified number of bits in a array, returning a new array
		/// </summary>
		/// <param name="value">数组</param>
		/// <param name="length">等待移除的长度</param>
		/// <returns>新的数组</returns>
		/// <exception cref="T:System.RankException"></exception>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArrayRemoveBegin" title="ArrayRemoveBegin示例" />
		/// </example> 
		public static T[] ArrayRemoveBegin<T>(T[] value, int length)
		{
			return ArrayRemoveDouble(value, length, 0);
		}

		/// <summary>
		/// 将一个数组的后面指定位数移除，返回新的一个数组<br />
		/// Removes the specified number of digits after a array, returning a new array
		/// </summary>
		/// <param name="value">数组</param>
		/// <param name="length">等待移除的长度</param>
		/// <returns>新的数组</returns>
		/// <exception cref="T:System.RankException"></exception>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArrayRemoveLast" title="ArrayRemoveLast示例" />
		/// </example> 
		public static T[] ArrayRemoveLast<T>(T[] value, int length)
		{
			return ArrayRemoveDouble(value, 0, length);
		}

		/// <summary>
		/// 获取到数组里面的中间指定长度的数组<br />
		/// Get an array of the specified length in the array
		/// </summary>
		/// <param name="value">数组</param>
		/// <param name="index">起始索引</param>
		/// <param name="length">数据的长度</param>
		/// <returns>新的数组值</returns>
		/// <exception cref="T:System.IndexOutOfRangeException"></exception>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArraySelectMiddle" title="ArraySelectMiddle示例" />
		/// </example> 
		public static T[] ArraySelectMiddle<T>(T[] value, int index, int length)
		{
			if (value == null)
			{
				return null;
			}
			if (length == 0)
			{
				return new T[0];
			}
			T[] array = new T[Math.Min(value.Length, length)];
			Array.Copy(value, index, array, 0, array.Length);
			return array;
		}

		/// <summary>
		/// 选择一个数组的前面的几个数据信息<br />
		/// Select the begin few items of data information of a array
		/// </summary>
		/// <param name="value">数组</param>
		/// <param name="length">数据的长度</param>
		/// <returns>新的数组</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArraySelectBegin" title="ArraySelectBegin示例" />
		/// </example> 
		public static T[] ArraySelectBegin<T>(T[] value, int length)
		{
			if (length == 0)
			{
				return new T[0];
			}
			T[] array = new T[Math.Min(value.Length, length)];
			if (array.Length != 0)
			{
				Array.Copy(value, 0, array, 0, array.Length);
			}
			return array;
		}

		/// <summary>
		/// 选择一个数组的后面的几个数据信息<br />
		/// Select the last few items of data information of a array
		/// </summary>
		/// <param name="value">数组</param>
		/// <param name="length">数据的长度</param>
		/// <returns>新的数组信息</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="ArraySelectLast" title="ArraySelectLast示例" />
		/// </example> 
		public static T[] ArraySelectLast<T>(T[] value, int length)
		{
			if (length == 0)
			{
				return new T[0];
			}
			T[] array = new T[Math.Min(value.Length, length)];
			Array.Copy(value, value.Length - length, array, 0, array.Length);
			return array;
		}

		/// <summary>
		/// 拼接任意个泛型数组为一个总的泛型数组对象，采用深度拷贝实现。<br />
		/// Splicing any number of generic arrays into a total generic array object is implemented using deep copy.
		/// </summary>
		/// <typeparam name="T">数组的类型信息</typeparam>
		/// <param name="arrays">任意个长度的数组</param>
		/// <returns>拼接之后的最终的结果对象</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="SpliceByteArray" title="SpliceByteArray示例" />
		/// </example> 
		public static T[] SpliceArray<T>(params T[][] arrays)
		{
			int num = 0;
			for (int i = 0; i < arrays.Length; i++)
			{
				T[] array = arrays[i];
				if (array != null && array.Length != 0)
				{
					num += arrays[i].Length;
				}
			}
			int num2 = 0;
			T[] array2 = new T[num];
			for (int j = 0; j < arrays.Length; j++)
			{
				T[] array3 = arrays[j];
				if (array3 != null && array3.Length != 0)
				{
					arrays[j].CopyTo(array2, num2);
					num2 += arrays[j].Length;
				}
			}
			return array2;
		}

		/// <summary>
		/// 将一个<see cref="T:System.String" />的数组和多个<see cref="T:System.String" /> 类型的对象整合成一个数组<br />
		/// Combine an array of <see cref="T:System.String" /> and multiple objects of type <see cref="T:System.String" /> into an array
		/// </summary>
		/// <param name="first">第一个数组对象</param>
		/// <param name="array">字符串数组信息</param>
		/// <returns>总的数组对象</returns>
		public static string[] SpliceStringArray(string first, string[] array)
		{
			List<string> list = new List<string>();
			list.Add(first);
			list.AddRange(array);
			return list.ToArray();
		}

		/// <summary>
		/// 将两个<see cref="T:System.String" />的数组和多个<see cref="T:System.String" /> 类型的对象整合成一个数组<br />
		/// Combine two arrays of <see cref="T:System.String" /> and multiple objects of type <see cref="T:System.String" /> into one array
		/// </summary>
		/// <param name="first">第一个数据对象</param>
		/// <param name="second">第二个数据对象</param>
		/// <param name="array">字符串数组信息</param>
		/// <returns>总的数组对象</returns>
		public static string[] SpliceStringArray(string first, string second, string[] array)
		{
			List<string> list = new List<string>();
			list.Add(first);
			list.Add(second);
			list.AddRange(array);
			return list.ToArray();
		}

		/// <summary>
		/// 将两个<see cref="T:System.String" />的数组和多个<see cref="T:System.String" /> 类型的对象整合成一个数组<br />
		/// Combine two arrays of <see cref="T:System.String" /> and multiple objects of type <see cref="T:System.String" /> into one array
		/// </summary>
		/// <param name="first">第一个数据对象</param>
		/// <param name="second">第二个数据对象</param>
		/// <param name="third">第三个数据对象</param>
		/// <param name="array">字符串数组信息</param>
		/// <returns>总的数组对象</returns>
		public static string[] SpliceStringArray(string first, string second, string third, string[] array)
		{
			List<string> list = new List<string>();
			list.Add(first);
			list.Add(second);
			list.Add(third);
			list.AddRange(array);
			return list.ToArray();
		}

		private static int HexToInt(char h)
		{
			if (h < '0' || h > '9')
			{
				if (h < 'a' || h > 'f')
				{
					if (h < 'A' || h > 'F')
					{
						return -1;
					}
					return h - 65 + 10;
				}
				return h - 97 + 10;
			}
			return h - 48;
		}

		private static string ValidateString(string input, bool skipUtf16Validation)
		{
			if (skipUtf16Validation || string.IsNullOrEmpty(input))
			{
				return input;
			}
			int num = -1;
			for (int i = 0; i < input.Length; i++)
			{
				if (char.IsSurrogate(input[i]))
				{
					num = i;
					break;
				}
			}
			if (num < 0)
			{
				return input;
			}
			char[] array = input.ToCharArray();
			for (int j = num; j < array.Length; j++)
			{
				char c = array[j];
				if (char.IsLowSurrogate(c))
				{
					array[j] = '\ufffd';
				}
				else if (char.IsHighSurrogate(c))
				{
					if (j + 1 < array.Length && char.IsLowSurrogate(array[j + 1]))
					{
						j++;
					}
					else
					{
						array[j] = '\ufffd';
					}
				}
			}
			return new string(array);
		}

		private static bool ValidateUrlEncodingParameters(byte[] bytes, int offset, int count)
		{
			if (bytes == null && count == 0)
			{
				return false;
			}
			if (bytes == null)
			{
				throw new ArgumentNullException("bytes");
			}
			if (offset < 0 || offset > bytes.Length)
			{
				throw new ArgumentOutOfRangeException("offset");
			}
			if (count < 0 || offset + count > bytes.Length)
			{
				throw new ArgumentOutOfRangeException("count");
			}
			return true;
		}

		private static bool IsUrlSafeChar(char ch)
		{
			if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9'))
			{
				return true;
			}
			switch (ch)
			{
			case '!':
			case '(':
			case ')':
			case '*':
			case '-':
			case '.':
			case '_':
				return true;
			default:
				return false;
			}
		}

		private static string UrlEncodeSpaces(string str)
		{
			if (str != null && str.IndexOf(' ') >= 0)
			{
				str = str.Replace(" ", "%20");
			}
			return str;
		}

		private static char IntToHex(int n)
		{
			Debug.Assert(n < 16);
			if (n <= 9)
			{
				return (char)(n + 48);
			}
			return (char)(n - 10 + 65);
		}

		private static byte[] UrlEncodeToBytes(byte[] bytes)
		{
			int num = 0;
			int num2 = bytes.Length;
			if (!ValidateUrlEncodingParameters(bytes, num, num2))
			{
				return null;
			}
			int num3 = 0;
			int num4 = 0;
			for (int i = 0; i < num2; i++)
			{
				char c = (char)bytes[num + i];
				if (c == ' ')
				{
					num3++;
				}
				else if (!IsUrlSafeChar(c))
				{
					num4++;
				}
			}
			if (num3 == 0 && num4 == 0)
			{
				if (num == 0 && bytes.Length == num2)
				{
					return bytes;
				}
				byte[] array = new byte[num2];
				Buffer.BlockCopy(bytes, num, array, 0, num2);
				return array;
			}
			byte[] array2 = new byte[num2 + num4 * 2];
			int num5 = 0;
			for (int j = 0; j < num2; j++)
			{
				byte b = bytes[num + j];
				char c2 = (char)b;
				if (IsUrlSafeChar(c2))
				{
					array2[num5++] = b;
					continue;
				}
				if (c2 == ' ')
				{
					array2[num5++] = 43;
					continue;
				}
				array2[num5++] = 37;
				array2[num5++] = (byte)IntToHex((b >> 4) & 0xF);
				array2[num5++] = (byte)IntToHex(b & 0xF);
			}
			return array2;
		}

		private static byte[] UrlEncode(byte[] bytes, bool alwaysCreateNewReturnValue)
		{
			byte[] array = UrlEncodeToBytes(bytes);
			if (!alwaysCreateNewReturnValue || array == null || array != bytes)
			{
				return array;
			}
			return (byte[])array.Clone();
		}

		/// <summary>
		/// 将字符串编码为URL可以识别的字符串，中文会被编码为%开头的数据，例如 中文 转义为 %2F%E4%B8%AD%E6%96%87 <br />
		/// Encoding a string as a URL-recognizable string Chinese encoded as data that begins with %, such as 中文 escaped as %2F%E4%B8%AD%E6%96%87
		/// </summary>
		/// <param name="str">等待转换的字符串数据</param>
		/// <param name="e">编码信息，一般为 UTF8 </param>
		/// <returns>编码之后的结果</returns>
		public static string UrlEncode(string str, Encoding e)
		{
			if (str == null)
			{
				return null;
			}
			byte[] bytes = e.GetBytes(str);
			return Encoding.ASCII.GetString(UrlEncode(bytes, alwaysCreateNewReturnValue: true));
		}

		/// <summary>
		/// 将url的编码解码为真实的字符串，例如 %2F%E4%B8%AD%E6%96%87 解码为 中文<br />
		/// Decode the encoding of url as a real string, for example %2F%E4%B8%AD%E6%96%87 to 中文
		/// </summary>
		/// <param name="value">等待转换的值</param>
		/// <param name="encoding">编码信息，一般为 UTF8</param>
		/// <returns>解码之后的结果</returns>
		public static string UrlDecode(string value, Encoding encoding)
		{
			int length = value.Length;
			UrlDecoder urlDecoder = new UrlDecoder(length, encoding);
			for (int i = 0; i < length; i++)
			{
				char c = value[i];
				switch (c)
				{
				case '+':
					c = ' ';
					break;
				case '%':
					if (i >= length - 2)
					{
						break;
					}
					if (value[i + 1] == 'u' && i < length - 5)
					{
						int num = HexToInt(value[i + 2]);
						int num2 = HexToInt(value[i + 3]);
						int num3 = HexToInt(value[i + 4]);
						int num4 = HexToInt(value[i + 5]);
						if (num >= 0 && num2 >= 0 && num3 >= 0 && num4 >= 0)
						{
							c = (char)((num << 12) | (num2 << 8) | (num3 << 4) | num4);
							i += 5;
							urlDecoder.AddChar(c);
							continue;
						}
					}
					else
					{
						int num5 = HexToInt(value[i + 1]);
						int num6 = HexToInt(value[i + 2]);
						if (num5 >= 0 && num6 >= 0)
						{
							byte b = (byte)((num5 << 4) | num6);
							i += 2;
							urlDecoder.AddByte(b);
							continue;
						}
					}
					break;
				}
				if ((c & 0xFF80) == 0)
				{
					urlDecoder.AddByte((byte)c);
				}
				else
				{
					urlDecoder.AddChar(c);
				}
			}
			return ValidateString(urlDecoder.GetString(), skipUtf16Validation: true);
		}

		/// <summary>
		/// 获取一串唯一的随机字符串，长度为20，由Guid码和4位数的随机数组成，保证字符串的唯一性<br />
		/// Gets a string of unique random strings with a length of 20, consisting of a GUID code and a 4-digit random number to guarantee the uniqueness of the string
		/// </summary>
		/// <returns>随机字符串数据</returns>
		/// <example>
		/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBasicExample.cs" region="GetUniqueStringByGuidAndRandom" title="GetUniqueStringByGuidAndRandom示例" />
		/// </example>
		public static string GetUniqueStringByGuidAndRandom()
		{
			return Guid.NewGuid().ToString("N") + SnetHelper.SnetRandom.Next(1000, 10000);
		}
	}
	/// <summary>
	/// 一个线程安全的缓存数据块，支持批量动态修改，添加，并获取快照<br />
	/// A thread-safe cache data block that supports batch dynamic modification, addition, and snapshot acquisition
	/// </summary>
	/// <remarks>
	/// 这个类可以实现什么功能呢，就是你有一个大的数组，作为你的应用程序的中间数据池，允许你往byte[]数组里存放指定长度的子byte[]数组，也允许从里面拿数据，
	/// 这些操作都是线程安全的，当然，本类扩展了一些额外的方法支持，也可以直接赋值或获取基本的数据类型对象。
	/// </remarks>
	/// <example>
	/// 此处举例一些数据的读写说明，可以此处的数据示例。
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftBufferExample.cs" region="SoftBufferExample1" title="SoftBuffer示例" />
	/// </example>
	public class SoftBuffer : IDisposable
	{
		private int capacity = 10;

		private byte[] buffer;

		private SimpleHybirdLock hybirdLock;

		private IByteTransform byteTransform;

		private bool isBoolReverseByWord;

		private bool disposedValue;

		/// <inheritdoc cref="P:Snet.Driver.Core.Net.NetworkDoubleBase.ByteTransform" />
		public IByteTransform ByteTransform
		{
			get
			{
				return byteTransform;
			}
			set
			{
				byteTransform = value;
			}
		}

		/// <summary>
		/// 获取或设置当前的bool操作是否按照字节反转<br />
		/// Gets or sets whether the current bool operation is reversed by bytes
		/// </summary>
		public bool IsBoolReverseByWord
		{
			get
			{
				return isBoolReverseByWord;
			}
			set
			{
				isBoolReverseByWord = value;
			}
		}

		/// <summary>
		/// 获取当前的缓存容量，单位为字节<br />
		/// Get the current cache capacity, in bytes
		/// </summary>
		public int Capacity => capacity;

		/// <summary>
		/// 使用默认的大小(10个字节)初始化缓存空间<br />
		/// Initialize the cache space with the default size (10 bytes).
		/// </summary>
		public SoftBuffer()
		{
			buffer = new byte[capacity];
			hybirdLock = new SimpleHybirdLock();
			byteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 使用指定的容量初始化缓存数据块，长度以字节为单位<br />
		/// Initializes cache chunks with the specified capacity, with a length in bytes
		/// </summary>
		/// <param name="capacity">初始化的容量</param>
		public SoftBuffer(int capacity)
		{
			buffer = new byte[capacity];
			this.capacity = capacity;
			hybirdLock = new SimpleHybirdLock();
			byteTransform = new RegularByteTransform();
		}

		/// <summary>
		/// 设置指定的位置bool值，如果超出，则丢弃数据，该位置是指按照位为单位排序的<br />
		/// Set the bool value at the specified position, if it is exceeded, 
		/// the data is discarded, the position refers to sorting in units of bits
		/// </summary>
		/// <param name="value">bool值</param>
		/// <param name="destIndex">目标存储的索引</param>
		/// <exception cref="T:System.IndexOutOfRangeException"></exception>
		public void SetBool(bool value, int destIndex)
		{
			SetBool(new bool[1] { value }, destIndex);
		}

		/// <summary>
		/// 设置指定的位置的bool数组，如果超出，则丢弃数据，该位置是指按照位为单位排序的<br />
		/// Set the bool array at the specified position, if it is exceeded, 
		/// the data is discarded, the position refers to sorting in units of bits
		/// </summary>
		/// <param name="value">bool数组值</param>
		/// <param name="destIndex">目标存储的索引</param>
		/// <exception cref="T:System.IndexOutOfRangeException"></exception>
		public void SetBool(bool[] value, int destIndex)
		{
			if (value == null)
			{
				return;
			}
			try
			{
				hybirdLock.Enter();
				for (int i = 0; i < value.Length; i++)
				{
					int num = (destIndex + i) / 8;
					int offset = (destIndex + i) % 8;
					if (isBoolReverseByWord)
					{
						num = ((num % 2 != 0) ? (num - 1) : (num + 1));
					}
					if (value[i])
					{
						buffer[num] |= getOrByte(offset);
					}
					else
					{
						buffer[num] &= getAndByte(offset);
					}
				}
				hybirdLock.Leave();
			}
			catch
			{
				hybirdLock.Leave();
				throw;
			}
		}

		/// <summary>
		/// 获取指定的位置的bool值，如果超出，则引发异常<br />
		/// Get the bool value at the specified position, if it exceeds, an exception is thrown
		/// </summary>
		/// <param name="destIndex">目标存储的索引</param>
		/// <returns>获取索引位置的bool数据值</returns>
		/// <exception cref="T:System.IndexOutOfRangeException"></exception>
		public bool GetBool(int destIndex)
		{
			return GetBool(destIndex, 1)[0];
		}

		/// <inheritdoc cref="M:Snet.Driver.BasicFramework.SoftBuffer.GetBool(System.Int32,System.Int32,System.Boolean)" />
		public bool[] GetBool(int destIndex, int length)
		{
			return GetBool(destIndex, length, isBoolReverseByWord);
		}

		/// <inheritdoc cref="M:Snet.Driver.BasicFramework.SoftBuffer.GetBool(System.Int32,System.Int32,System.Boolean)" />
		public bool[] GetBool(int destIndex, int length, DataFormat dataFormat)
		{
			return GetBool(destIndex, length, (dataFormat == DataFormat.ABCD || dataFormat == DataFormat.CDAB) ? true : false);
		}

		/// <summary>
		/// 获取指定位置的bool数组值，如果超过，则引发异常<br />
		/// Get the bool array value at the specified position, if it exceeds, an exception is thrown
		/// </summary>
		/// <param name="destIndex">目标存储的索引</param>
		/// <param name="length">读取的数组长度</param>
		/// <param name="wordReverse">是否按照字反转操作</param>
		/// <exception cref="T:System.IndexOutOfRangeException"></exception>
		/// <returns>bool数组值</returns>
		public bool[] GetBool(int destIndex, int length, bool wordReverse)
		{
			bool[] array = new bool[length];
			try
			{
				hybirdLock.Enter();
				for (int i = 0; i < length; i++)
				{
					int num = (destIndex + i) / 8;
					int offset = (destIndex + i) % 8;
					if (wordReverse)
					{
						num = ((num % 2 != 0) ? (num - 1) : (num + 1));
					}
					array[i] = (buffer[num] & getOrByte(offset)) == getOrByte(offset);
				}
				hybirdLock.Leave();
				return array;
			}
			catch
			{
				hybirdLock.Leave();
				throw;
			}
		}

		private byte getAndByte(int offset)
		{
			return offset switch
			{
				0 => 254, 
				1 => 253, 
				2 => 251, 
				3 => 247, 
				4 => 239, 
				5 => 223, 
				6 => 191, 
				7 => 127, 
				_ => byte.MaxValue, 
			};
		}

		private byte getOrByte(int offset)
		{
			return offset switch
			{
				0 => 1, 
				1 => 2, 
				2 => 4, 
				3 => 8, 
				4 => 16, 
				5 => 32, 
				6 => 64, 
				7 => 128, 
				_ => 0, 
			};
		}

		/// <summary>
		/// 设置指定的位置的数据块，如果超出，则丢弃数据<br />
		/// Set the data block at the specified position, if it is exceeded, the data is discarded
		/// </summary>
		/// <param name="data">数据块信息</param>
		/// <param name="destIndex">目标存储的索引</param>
		public void SetBytes(byte[] data, int destIndex)
		{
			if (destIndex < capacity && destIndex >= 0 && data != null)
			{
				hybirdLock.Enter();
				if (data.Length + destIndex > buffer.Length)
				{
					Array.Copy(data, 0, buffer, destIndex, buffer.Length - destIndex);
				}
				else
				{
					data.CopyTo(buffer, destIndex);
				}
				hybirdLock.Leave();
			}
		}

		/// <summary>
		/// 设置指定的位置的数据块，如果超出，则丢弃数据
		/// Set the data block at the specified position, if it is exceeded, the data is discarded
		/// </summary>
		/// <param name="data">数据块信息</param>
		/// <param name="destIndex">目标存储的索引</param>
		/// <param name="length">准备拷贝的数据长度</param>
		public void SetBytes(byte[] data, int destIndex, int length)
		{
			if (destIndex < capacity && destIndex >= 0 && data != null)
			{
				if (length > data.Length)
				{
					length = data.Length;
				}
				hybirdLock.Enter();
				if (length + destIndex > buffer.Length)
				{
					Array.Copy(data, 0, buffer, destIndex, buffer.Length - destIndex);
				}
				else
				{
					Array.Copy(data, 0, buffer, destIndex, length);
				}
				hybirdLock.Leave();
			}
		}

		/// <summary>
		/// 设置指定的位置的数据块，如果超出，则丢弃数据<br />
		/// Set the data block at the specified position, if it is exceeded, the data is discarded
		/// </summary>
		/// <param name="data">数据块信息</param>
		/// <param name="sourceIndex">Data中的起始位置</param>
		/// <param name="destIndex">目标存储的索引</param>
		/// <param name="length">准备拷贝的数据长度</param>
		/// <exception cref="T:System.IndexOutOfRangeException"></exception>
		public void SetBytes(byte[] data, int sourceIndex, int destIndex, int length)
		{
			if (destIndex < capacity && destIndex >= 0 && data != null)
			{
				if (length > data.Length)
				{
					length = data.Length;
				}
				hybirdLock.Enter();
				Array.Copy(data, sourceIndex, buffer, destIndex, length);
				hybirdLock.Leave();
			}
		}

		/// <summary>
		/// 获取内存指定长度的数据信息<br />
		/// Get data information of specified length in memory
		/// </summary>
		/// <param name="index">起始位置</param>
		/// <param name="length">数组长度</param>
		/// <returns>返回实际的数据信息</returns>
		public byte[] GetBytes(int index, int length)
		{
			byte[] array = new byte[length];
			if (length > 0)
			{
				hybirdLock.Enter();
				if (index >= 0 && index + length <= buffer.Length)
				{
					Array.Copy(buffer, index, array, 0, length);
				}
				hybirdLock.Leave();
			}
			return array;
		}

