		/// <summary>
		/// 释放当前的对象
		/// </summary>
		/// <param name="disposing"></param>
		protected virtual void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				if (disposing)
				{
					hybirdLock?.Dispose();
					buffer = null;
				}
				disposedValue = true;
			}
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			Dispose(disposing: true);
		}

		/// <summary>
		/// 将所有的缓存数据块转换为一个MemoryStream对象<br />
		/// </summary>
		/// <param name="buffers">所有的缓存数据</param>
		/// <returns>MemoryStream对象</returns>
		public static MemoryStream ToMemoryStream(params SoftBuffer[] buffers)
		{
			MemoryStream memoryStream = new MemoryStream();
			if (buffers == null || buffers.Length == 0)
			{
				return memoryStream;
			}
			foreach (SoftBuffer softBuffer in buffers)
			{
				if (softBuffer != null && softBuffer.Capacity > 0)
				{
					memoryStream.Write(softBuffer.GetBytes());
				}
			}
			return memoryStream;
		}

		/// <summary>
		/// 从指定的byte[]数组中加载数据到多个SoftBuffer对象中<br />
		/// </summary>
		/// <param name="source">字节数据</param>
		/// <param name="buffers">所有的缓存数据</param>
		public static void LoadFromBuffer(byte[] source, params SoftBuffer[] buffers)
		{
			if (buffers == null || buffers.Length == 0)
			{
				return;
			}
			int num = 0;
			foreach (SoftBuffer softBuffer in buffers)
			{
				if (num < source.Length && num + softBuffer.capacity <= source.Length)
				{
					if (softBuffer != null && softBuffer.Capacity > 0)
					{
						softBuffer.SetBytes(source.SelectMiddle(num, softBuffer.Capacity), 0);
						num += softBuffer.Capacity;
					}
					continue;
				}
				break;
			}
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SoftBuffer[{capacity}][{ByteTransform}]";
		}
	}
	/// <summary>
	/// 一个简单的不持久化的序号自增类，采用线程安全实现，并允许指定最大数字，将包含该最大值，到达后清空从指定数开始<br />
	/// A simple non-persistent serial number auto-increment class, which is implemented with thread safety, and allows the maximum number to be specified, which will contain the maximum number, and will be cleared from the specified number upon arrival.
	/// </summary>
	/// <example>
	/// 先来看看一个简单的应用的
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftIncrementCountSample.cs" region="Sample1" title="简单示例" />
	/// 再来看看一些复杂的情况
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftIncrementCountSample.cs" region="Sample2" title="复杂示例" />
	/// 其他一些特殊的设定
	/// <code lang="cs" source="Snet.Driver.Test\Documentation\Samples\BasicFramework\SoftIncrementCountSample.cs" region="Sample3" title="其他示例" />
	/// </example>
	public sealed class SoftIncrementCount : IDisposable
	{
		private long start;

		private long current;

		private long max = long.MaxValue;

		private SimpleHybirdLock hybirdLock;

		private bool disposedValue;

		/// <summary>
		/// 增加的单元，如果设置为0，就是不增加。如果为小于0，那就是减少，会变成负数的可能。<br />
		/// Increased units, if set to 0, do not increase. If it is less than 0, it is a decrease and it may become a negative number.
		/// </summary>
		public int IncreaseTick { get; set; } = 1;

		/// <summary>
		/// 获取当前的计数器的最大的设置值。<br />
		/// Get the maximum setting value of the current counter.
		/// </summary>
		public long MaxValue => max;

		/// <summary>
		/// 实例化一个自增信息的对象，包括最大值，初始值，增量值<br />
		/// Instantiate an object with incremental information, including the maximum value and initial value, IncreaseTick
		/// </summary>
		/// <param name="max">数据的最大值，必须指定</param>
		/// <param name="start">数据的起始值，默认为0</param>
		/// <param name="tick">每次的增量值</param>
		public SoftIncrementCount(long max, long start = 0L, int tick = 1)
		{
			this.start = start;
			this.max = max;
			current = start;
			IncreaseTick = tick;
			hybirdLock = new SimpleHybirdLock();
		}

		/// <summary>
		/// 获取自增信息，获得数据之后，下一次获取将会自增，如果自增后大于最大值，则会重置为最小值，如果小于最小值，则会重置为最大值。<br />
		/// Get the auto-increment information. After getting the data, the next acquisition will auto-increase. 
		/// If the auto-increment is greater than the maximum value, it will reset to the minimum value.
		/// If the auto-increment is smaller than the minimum value, it will reset to the maximum value.
		/// </summary>
		/// <returns>计数自增后的值</returns>
		public long GetCurrentValue()
		{
			hybirdLock.Enter();
			long result = current;
			current += IncreaseTick;
			if (current > max)
			{
				current = start;
			}
			else if (current < start)
			{
				current = max;
			}
			hybirdLock.Leave();
			return result;
		}

		/// <summary>
		/// 重置当前序号的最大值，最大值应该大于初始值，如果当前值大于最大值，则当前值被重置为最大值<br />
		/// Reset the maximum value of the current serial number. The maximum value should be greater than the initial value. 
		/// If the current value is greater than the maximum value, the current value is reset to the maximum value.
		/// </summary>
		/// <param name="max">最大值</param>
		public void ResetMaxValue(long max)
		{
			hybirdLock.Enter();
			if (max > start)
			{
				if (max < current)
				{
					current = start;
				}
				this.max = max;
			}
			hybirdLock.Leave();
		}

		/// <summary>
		/// 重置当前序号的初始值，需要小于最大值，如果当前值小于初始值，则当前值被重置为初始值。<br />
		/// To reset the initial value of the current serial number, it must be less than the maximum value. 
		/// If the current value is less than the initial value, the current value is reset to the initial value.
		/// </summary>
		/// <param name="start">初始值</param>
		public void ResetStartValue(long start)
		{
			hybirdLock.Enter();
			if (start < max)
			{
				if (current < start)
				{
					current = start;
				}
				this.start = start;
			}
			hybirdLock.Leave();
		}

		/// <summary>
		/// 将当前的值重置为初始值。<br />
		/// Reset the current value to the initial value.
		/// </summary>
		public void ResetCurrentValue()
		{
			hybirdLock.Enter();
			current = start;
			hybirdLock.Leave();
		}

		/// <summary>
		/// 将当前的值重置为指定值，该值不能大于max，如果大于max值，就会自动设置为max<br />
		/// Reset the current value to the specified value. The value cannot be greater than max. If it is greater than max, it will be automatically set to max.
		/// </summary>
		/// <param name="value">指定的数据值</param>
		public void ResetCurrentValue(long value)
		{
			hybirdLock.Enter();
			if (value > max)
			{
				current = max;
			}
			else if (value < start)
			{
				current = start;
			}
			else
			{
				current = value;
			}
			hybirdLock.Leave();
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return $"SoftIncrementCount[{current}]";
		}

		private void Dispose(bool disposing)
		{
			if (!disposedValue)
			{
				if (disposing)
				{
					hybirdLock.Dispose();
				}
				disposedValue = true;
			}
		}

		/// <inheritdoc cref="M:System.IDisposable.Dispose" />
		public void Dispose()
		{
			Dispose(disposing: true);
		}
	}
	/// <summary>
	/// 一个负责压缩解压数据字节的类
	/// </summary>
	public class SoftZipped
	{
		/// <summary>
		/// 压缩字节数据
		/// </summary>
		/// <param name="bytes">等待被压缩的数据</param>
		/// <exception cref="T:System.ArgumentNullException"></exception>
		/// <returns>压缩之后的字节数据</returns>
		public static byte[] CompressBytes(byte[] bytes)
		{
			if (bytes == null)
			{
				throw new ArgumentNullException("bytes");
			}
			using MemoryStream memoryStream = new MemoryStream();
			using (GZipStream gZipStream = new GZipStream(memoryStream, CompressionMode.Compress))
			{
				gZipStream.Write(bytes, 0, bytes.Length);
			}
			return memoryStream.ToArray();
		}

		/// <summary>
		/// 解压压缩后的数据
		/// </summary>
		/// <param name="bytes">压缩后的数据</param>
		/// <exception cref="T:System.ArgumentNullException"></exception>
		/// <returns>压缩前的原始字节数据</returns>
		public static byte[] Decompress(byte[] bytes)
		{
			if (bytes == null)
			{
				throw new ArgumentNullException("bytes");
			}
			using MemoryStream stream = new MemoryStream(bytes);
			using GZipStream gZipStream = new GZipStream(stream, CompressionMode.Decompress);
			using MemoryStream memoryStream = new MemoryStream();
			int num = 1024;
			byte[] buffer = new byte[num];
			int num2 = 0;
			while ((num2 = gZipStream.Read(buffer, 0, num)) > 0)
			{
				memoryStream.Write(buffer, 0, num2);
			}
			return memoryStream.ToArray();
		}
	}
	internal class UrlDecoder
	{
		private int _bufferSize;

		private int _numChars;

		private char[] _charBuffer;

		private int _numBytes;

		private byte[] _byteBuffer;

		private Encoding _encoding;

		private void FlushBytes()
		{
			if (_numBytes > 0)
			{
				_numChars += _encoding.GetChars(_byteBuffer, 0, _numBytes, _charBuffer, _numChars);
				_numBytes = 0;
			}
		}

		internal UrlDecoder(int bufferSize, Encoding encoding)
		{
			_bufferSize = bufferSize;
			_encoding = encoding;
			_charBuffer = new char[bufferSize];
		}

		internal void AddChar(char ch)
		{
			if (_numBytes > 0)
			{
				FlushBytes();
			}
			_charBuffer[_numChars++] = ch;
		}

		internal void AddByte(byte b)
		{
			if (_byteBuffer == null)
			{
				_byteBuffer = new byte[_bufferSize];
			}
			_byteBuffer[_numBytes++] = b;
		}

		internal string GetString()
		{
			if (_numBytes > 0)
			{
				FlushBytes();
			}
			if (_numChars > 0)
			{
				return new string(_charBuffer, 0, _numChars);
			}
			return string.Empty;
		}
	}
}
